function getSidebarGroupLabel(groupName) {
  if (!groupName) {
    return "";
  }

  return SIDEBAR_GROUP_LABELS[groupName]
    || sidebarGroupPanels
      .find((panel) => panel.dataset.sidebarGroupPanel === groupName)
      ?.querySelector(".sidebar-group-label")
      ?.textContent
      ?.trim()
    || groupName;
}

function getSidebarItemLabel(itemName) {
  if (!itemName) {
    return "";
  }

  return SIDEBAR_ITEM_LABELS[itemName]
    || sidebarNavItems
      .find((button) => button.dataset.sidebarItem === itemName)
      ?.querySelector("strong")
      ?.textContent
      ?.trim()
    || itemName;
}

function getWorkOrderBreadcrumbLabel() {
  const activeId = String(workOrderIdInput?.value || "");
  const persistedItem = state.workOrders.find((item) => String(item.id) === activeId) ?? null;
  return persistedItem?.workOrderNumber || workOrderEditorTitle?.textContent?.trim() || "Novi RN";
}

function navigateToBreadcrumb(target) {
  if (!target) {
    return;
  }

  if (state.workOrderEditorOpen && target.kind !== "work-order") {
    closeWorkOrderEditor();
  }

  if (target.kind === "group") {
    activateSidebarGroup(target.group, { navigate: true, expandSidebar: true });
    return;
  }

  if (target.kind === "item") {
    activateSidebarItem(target.item, { expandSidebar: true });
    return;
  }

  if (target.kind === "people-tab") {
    setPeopleWorkspaceTab(target.tab);
    state.activeView = "management";
    state.activeSidebarGroup = "organisations";
    state.activeSidebarItem = "people";
    renderActiveView();
    renderManagement();
    workspaceViews.management?.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
    return;
  }

  if (target.kind === "work-order-view") {
    setActiveWorkOrderViewMode(target.mode);
  }
}

function buildTopbarBreadcrumbs() {
  if (isClientPortalShellActive()) {
    return [{
      label: getSidebarItemLabel("client-portal") || "Client Portal",
      kind: "item",
      item: "client-portal",
    }];
  }

  const groupName = state.activeSidebarGroup || getSidebarGroupForView();
  const itemName = state.activeSidebarItem || SIDEBAR_GROUP_DEFAULT_ITEM[groupName];
  const crumbs = [];

  if (groupName) {
    crumbs.push({
      label: getSidebarGroupLabel(groupName),
      kind: "group",
      group: groupName,
    });
  }

  if (itemName) {
    crumbs.push({
      label: getSidebarItemLabel(itemName),
      kind: "item",
      item: itemName,
    });
  }

  if (state.activeView === "management" && state.activeSidebarItem === "people") {
    const activePeopleTab = normalizePeopleWorkspaceTab(state.peopleWorkspaceTab);
    crumbs.push({
      label: getPeopleWorkspaceTabLabel(activePeopleTab),
      kind: "people-tab",
      tab: activePeopleTab,
    });
  }

  if (state.activeView === "selfdash" && state.activeSidebarItem === "rn") {
    crumbs.push({
      label: getWorkOrderViewModeLabel(),
      kind: "work-order-view",
      mode: state.activeWorkOrderViewMode,
    });
  }

  if (state.activeView === "selfdash" && state.workOrderEditorOpen) {
    crumbs.push({
      label: getWorkOrderBreadcrumbLabel(),
      kind: "work-order",
    });
  }

  return crumbs.filter((item) => item.label);
}

function renderTopbarBreadcrumbs() {
  if (!organizationContext) {
    return;
  }

  const crumbs = buildTopbarBreadcrumbs();
  organizationContext.className = "organization-context";

  if (crumbs.length === 0) {
    organizationContext.replaceChildren();
    return;
  }

  const nodes = [];

  crumbs.forEach((crumb, index) => {
    const isLast = index === crumbs.length - 1;
    const element = document.createElement(isLast ? "span" : "button");
    element.className = isLast ? "organization-context-current" : "organization-context-link";
    element.textContent = crumb.label;

    if (!isLast) {
      element.type = "button";
      element.addEventListener("click", () => {
        navigateToBreadcrumb(crumb);
      });
    } else {
      element.setAttribute("aria-current", "page");
    }

    nodes.push(element);

    if (!isLast) {
      const separator = document.createElement("span");
      separator.className = "organization-context-separator";
      separator.setAttribute("aria-hidden", "true");
      separator.textContent = "/";
      nodes.push(separator);
    }
  });

  organizationContext.replaceChildren(...nodes);
}

function createAppCapabilityStatusIcon(status = "planned_later") {
  const config = getAppCapabilityStatusConfig(status);
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 24 24");
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("class", "app-capabilities-status-icon");

  const appendPath = (d) => {
    const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
    path.setAttribute("d", d);
    svg.append(path);
  };

  switch (config.value) {
    case "implemented":
      appendPath("M20 6 9 17l-5-5");
      break;
    case "in_progress":
      appendPath("M12 3.75A8.25 8.25 0 1 0 20.25 12");
      appendPath("M12 7.5v4.5l3 2");
      break;
    case "not_planned":
      appendPath("M12 3.75a8.25 8.25 0 1 1 0 16.5 8.25 8.25 0 0 1 0-16.5Z");
      appendPath("m7.75 7.75 8.5 8.5");
      break;
    default:
      appendPath("M12 3.75a8.25 8.25 0 1 1 0 16.5 8.25 8.25 0 0 1 0-16.5Z");
      appendPath("M12 8v4.25");
      appendPath("M12 15.75h.01");
      break;
  }

  return svg;
}

function createAppCapabilityStatusPill(status = "planned_later") {
  const config = getAppCapabilityStatusConfig(status);
  const pill = document.createElement("span");
  pill.className = `app-capabilities-status-pill ${config.className}`;
  pill.append(
    createAppCapabilityStatusIcon(config.value),
    document.createTextNode(config.label),
  );
  return pill;
}

function createAppCapabilityStatusControl(
  status = "planned_later",
  {
    disabled = false,
    onChange = null,
  } = {},
) {
  const control = document.createElement("div");
  control.className = `app-capabilities-choice-control${disabled ? " is-readonly" : ""}`;

  const icon = createAppCapabilityStatusIcon(status);
  control.append(icon);

  const label = document.createElement("span");
  label.className = "app-capabilities-choice-label";
  control.append(label);

  const chevron = document.createElement("span");
  chevron.className = "app-capabilities-choice-chevron";
  chevron.setAttribute("aria-hidden", "true");
  chevron.textContent = "▾";
  control.append(chevron);

  if (!disabled) {
    const select = document.createElement("select");
    select.className = "app-capabilities-choice-native";
    APP_CAPABILITY_STATUS_OPTIONS.forEach((option) => {
      const optionNode = document.createElement("option");
      optionNode.value = option.value;
      optionNode.textContent = option.label;
      select.append(optionNode);
    });
    select.addEventListener("change", () => {
      const nextStatus = normalizeAppCapabilityStatus(select.value);
      syncAppCapabilityStatusControl(control, nextStatus);
      if (typeof onChange === "function") {
        onChange(nextStatus);
      }
    });
    control.append(select);
  }

  syncAppCapabilityStatusControl(control, status);

  return control;
}

function syncAppCapabilityStatusControl(control, status = "planned_later") {
  if (!(control instanceof HTMLElement)) {
    return;
  }

  const config = getAppCapabilityStatusConfig(status);
  const isReadonly = control.classList.contains("is-readonly");
  control.className = `app-capabilities-choice-control ${config.className}${isReadonly ? " is-readonly" : ""}`;

  const currentIcon = control.querySelector(".app-capabilities-status-icon");
  if (currentIcon) {
    currentIcon.replaceWith(createAppCapabilityStatusIcon(config.value));
  }

  const label = control.querySelector(".app-capabilities-choice-label");
  if (label) {
    label.textContent = config.label;
  }

  control.setAttribute("aria-label", config.label);
  control.title = config.label;

  const select = control.querySelector(".app-capabilities-choice-native");
  if (select instanceof HTMLSelectElement) {
    select.value = config.value;
    select.setAttribute("aria-label", config.label);
    select.title = config.label;
  }
}

function getAppCapabilityStatusExportSymbol(status = "planned_later") {
  switch (normalizeAppCapabilityStatus(status)) {
    case "implemented":
      return "✓";
    case "in_progress":
      return "↻";
    case "not_planned":
      return "⊘";
    default:
      return "◷";
  }
}

