const LOGIN_INPUT_LOCK_STYLES = Object.freeze([
  ["color-scheme", "only light"],
  ["background", "#ffffff"],
  ["background-color", "#ffffff"],
  ["color", "#1f2430"],
  ["-webkit-text-fill-color", "#1f2430"],
  ["caret-color", "#1f2430"],
  ["-webkit-box-shadow", "0 0 0 1000px #ffffff inset"],
  ["box-shadow", "0 0 0 1000px #ffffff inset"],
]);

function lockLoginInputAppearance(input) {
  if (!input) {
    return;
  }
  for (const [property, value] of LOGIN_INPUT_LOCK_STYLES) {
    input.style.setProperty(property, value, "important");
  }
}

function bindLoginInputAppearanceLock(input) {
  if (!input || input.dataset.loginAppearanceLocked === "true") {
    return;
  }

  input.dataset.loginAppearanceLocked = "true";
  let animationFrameId = 0;
  let animationFramesRemaining = 0;

  const stop = () => {
    if (animationFrameId) {
      window.cancelAnimationFrame(animationFrameId);
      animationFrameId = 0;
    }
  };

  const tick = () => {
    lockLoginInputAppearance(input);
    if (document.activeElement !== input || animationFramesRemaining <= 0) {
      animationFrameId = 0;
      return;
    }
    animationFramesRemaining -= 1;
    animationFrameId = window.requestAnimationFrame(tick);
  };

  const start = () => {
    stop();
    animationFramesRemaining = 24;
    tick();
  };

  lockLoginInputAppearance(input);

  ["focus", "pointerdown", "mousedown", "keydown", "input", "change"].forEach((eventName) => {
    input.addEventListener(eventName, start);
  });

  input.addEventListener("blur", () => {
    stop();
    lockLoginInputAppearance(input);
  });

  window.setTimeout(() => lockLoginInputAppearance(input), 0);
  window.setTimeout(() => lockLoginInputAppearance(input), 180);
  window.setTimeout(() => lockLoginInputAppearance(input), 1200);
}

function applyLoginRedirectState() {
  const params = new URLSearchParams(window.location.search);
  const loginErrorCode = params.get("loginError");

  if (!loginErrorCode || !loginError) {
    return;
  }

  if (loginErrorCode === "invalid") {
    setInlineMessage(loginError, "Neispravan email ili lozinka.");
  } else if (loginErrorCode === "server") {
    setInlineMessage(loginError, "Prijava trenutno nije uspjela. Pokusaj ponovno.");
  }

  params.delete("loginError");
  const nextQuery = params.toString();
  const nextUrl = `${window.location.pathname}${nextQuery ? `?${nextQuery}` : ""}${window.location.hash}`;
  window.history.replaceState({}, "", nextUrl);
}

function syncPasswordToggleLabel() {
  return;
}

function getIsSuperAdmin() {
  return state.user?.role === "super_admin";
}

function getIsAdmin() {
  return state.user?.role === "admin";
}

function getCanManageMasterData() {
  return ["super_admin", "admin"].includes(state.user?.role);
}

function getCanEditOperationalData() {
  return !isClientPortalUser(state.user);
}

function getCanEditPeopleTrainingData() {
  return getCanManagePeople() || isClientPortalUser(state.user);
}

function syncWorkOrderEditorAccess() {
  const canEdit = getCanEditOperationalData();
  const canCreate = getCanCreateWorkOrders();
  const isEditing = Boolean(workOrderIdInput?.value);
  const currentStatus = workOrderStatusInput?.value || "Otvoreni RN";
  const canChangeStatus = isEditing
    ? getCanChangeAnyWorkOrderStatus(currentStatus)
    : getCanSetWorkOrderStatus("Otvoreni RN", currentStatus);
  const canWriteBilling = getCanWriteWorkOrderBilling();
  if (workOrderForm) {
    workOrderForm.querySelectorAll("input, select, textarea, button").forEach((control) => {
      if (control.matches("[data-work-order-section-toggle]")) {
        control.disabled = false;
        return;
      }
      control.disabled = !canEdit;
    });
  }

  if (workOrderStatusInput) {
    workOrderStatusInput.disabled = !canEdit || !canChangeStatus;
    workOrderStatusInput.title = canChangeStatus ? "" : "Nemas ovlastenje za promjenu statusa RN.";
  }
  [
    workOrderWeightInput,
    workOrderInvoiceDateInput,
    workOrderInvoiceNoteInput,
  ].forEach((control) => {
    if (!control) {
      return;
    }
    control.disabled = !canEdit || !canWriteBilling;
    control.title = canWriteBilling ? "" : "Nemas ovlastenje za upisivanje u fakturiranje.";
  });

  [
    workOrderDocumentDropzone,
    workOrderActivityDropzone,
  ].forEach((control) => {
    if (!control) {
      return;
    }
    control.disabled = !canEdit;
    control.hidden = !canEdit;
  });

  if (workOrderResetButton) {
    workOrderResetButton.hidden = !canEdit;
    workOrderResetButton.disabled = !canEdit;
  }
  if (workOrderOpenFormButton) {
    workOrderOpenFormButton.hidden = !canCreate;
  }
  if (workOrderOpenDocumentsButton) {
    workOrderOpenDocumentsButton.hidden = !canEdit;
  }
  workOrderEditorPanel?.classList.toggle("is-client-read-only", !canEdit);
}

function normalizeCompanyPermissionFlags(value = {}) {
  const source = value && typeof value === "object"
    ? value
    : {};

  return {
    canView: Boolean(source.canView),
    canCreate: Boolean(source.canCreate),
    canEdit: Boolean(source.canEdit),
    canDelete: Boolean(source.canDelete),
  };
}

function normalizeAppPermissionFlags(value = {}) {
  const source = value && typeof value === "object"
    ? value
    : {};

  return Object.fromEntries(APP_ROLE_PERMISSION_KEYS.map((key) => [key, Boolean(source[key])]));
}

function materializeAppRolePermissionDraft(entries = []) {
  return normalizeAppRolePermissions(entries).map((entry) => ({
    ...normalizeAppPermissionFlags(entry),
    profileRole: normalizeUserProfileRoleValue(entry.profileRole),
    isExplicit: entry.isExplicit !== false,
  }));
}

function materializeCompanyRolePermissionDraft(entries = []) {
  const normalizedEntries = (Array.isArray(entries) ? entries : [])
    .map((entry) => normalizeCompanyRolePermissionEntry(entry));

  return USER_PROFILE_ROLE_OPTIONS.map((option) => {
    const profileRole = option.value;
    const explicitGeneralEntry = normalizedEntries.find((entry) => (
      entry.companyId === COMPANY_PERMISSION_SCOPE_GENERAL
      && entry.profileRole === profileRole
      && entry.isExplicit !== false
    ));
    const fallbackEntries = normalizedEntries.filter((entry) => (
      entry.profileRole === profileRole
      && entry.isExplicit !== false
    ));

    if (explicitGeneralEntry) {
      return {
        companyId: COMPANY_PERMISSION_SCOPE_GENERAL,
        profileRole,
        canView: Boolean(explicitGeneralEntry.canView),
        canCreate: Boolean(explicitGeneralEntry.canCreate),
        canEdit: Boolean(explicitGeneralEntry.canEdit),
        canDelete: Boolean(explicitGeneralEntry.canDelete),
      };
    }

    return {
      companyId: COMPANY_PERMISSION_SCOPE_GENERAL,
      profileRole,
      canView: fallbackEntries.some((entry) => Boolean(entry.canView)),
      canCreate: fallbackEntries.some((entry) => Boolean(entry.canCreate)),
      canEdit: fallbackEntries.some((entry) => Boolean(entry.canEdit)),
      canDelete: fallbackEntries.some((entry) => Boolean(entry.canDelete)),
    };
  });
}

function createCompanyRolePermissionDraftKey(profileRole = "new_user") {
  return `${COMPANY_PERMISSION_SCOPE_GENERAL}::${normalizeUserProfileRoleValue(profileRole)}`;
}

function createAppRolePermissionDraftKey(profileRole = "new_user") {
  return normalizeUserProfileRoleValue(profileRole);
}

function getAppRolePermissionsDraft() {
  return materializeAppRolePermissionDraft(state.appRolePermissions ?? []);
}

function setAppRolePermissionDraft(profileRole = "", permissionKey = "", nextValue = false) {
  const normalizedProfileRole = normalizeUserProfileRoleValue(profileRole);
  if (!normalizedProfileRole || !APP_ROLE_PERMISSION_KEYS.includes(permissionKey)) {
    return;
  }

  const draft = getAppRolePermissionsDraft().map((entry) => ({ ...entry }));
  const target = draft.find((entry) => entry.profileRole === normalizedProfileRole);
  if (!target) {
    return;
  }

  target[permissionKey] = Boolean(nextValue);
  state.appRolePermissions = materializeAppRolePermissionDraft(draft);
}

