function syncPeopleTrainingPersonalSummary() {
  if (!peopleTrainingPersonSummary) {
    return;
  }

  const fullName = [
    peopleTrainingFirstNameInput?.value || "",
    peopleTrainingLastNameInput?.value || "",
  ].map((value) => String(value).trim()).filter(Boolean).join(" ");
  const companyLabel = getSelectedOptionLabel(peopleTrainingCompanyInput, "");
  const locationLabel = getSelectedOptionLabel(peopleTrainingLocationInput, "");
  const parts = [
    fullName,
    peopleTrainingOibInput?.value ? `OIB ${peopleTrainingOibInput.value.trim()}` : "",
    peopleTrainingFatherNameInput?.value ? `ime oca ${peopleTrainingFatherNameInput.value.trim()}` : "",
    peopleTrainingLanguageInput?.value?.trim() || "",
    peopleTrainingActivityStatusInput?.value ? `aktivnost ${peopleTrainingActivityStatusInput.value}` : "",
    companyLabel,
    locationLabel && !/nije vezano/i.test(locationLabel) ? locationLabel : "",
  ].filter(Boolean);

  peopleTrainingPersonSummary.textContent = parts.join(" · ");
}

function renderPeopleTrainingStats() {
  const records = state.peopleTrainingRecords ?? [];
  const counts = records.reduce((accumulator, record) => {
    const status = getPeopleTrainingOverallStatus(record);
    accumulator.total += 1;
    if (status === "valid") {
      accumulator.valid += 1;
    } else if (status === "expiring") {
      accumulator.expiring += 1;
    } else if (status === "expired") {
      accumulator.expired += 1;
    }
    return accumulator;
  }, { total: 0, valid: 0, expiring: 0, expired: 0 });

  if (peopleTrainingTotalCount) {
    peopleTrainingTotalCount.textContent = String(counts.total);
  }
  if (peopleTrainingValidCount) {
    peopleTrainingValidCount.textContent = String(counts.valid);
  }
  if (peopleTrainingExpiringCount) {
    peopleTrainingExpiringCount.textContent = String(counts.expiring);
  }
  if (peopleTrainingExpiredCount) {
    peopleTrainingExpiredCount.textContent = String(counts.expired);
  }
}

function buildPeopleTrainingExamOverviewOptions() {
  return [
    { value: "rn", label: "Po radnim nalozima" },
    { value: "people", label: "Komplet po osobama" },
  ];
}

function isPeopleTrainingItemPassed(item = {}) {
  const status = String(item.status || "").trim().toLowerCase();
  if (status === "missing" || status === "not_required") {
    return false;
  }
  return Boolean(
    item.passedOn
      || item.issuedOn
      || item.certificateNumber
      || item.recordNumber
      || item.certificateStatus === "ready"
      || item.certificateStatus === "issued",
  );
}

function getPeopleTrainingItemLearningAssignments(record = {}, item = {}) {
  const linkedIds = new Set(
    [
      item.learningTestId,
      ...(Array.isArray(item.linkedLearningTestIds) ? item.linkedLearningTestIds : []),
    ].map((value) => String(value || "").trim()).filter(Boolean),
  );
  if (linkedIds.size === 0) {
    return [];
  }
  const recordEmail = String(record.email || "").trim().toLowerCase();
  const recordOib = String(record.oib || "").trim();
  const recordName = getPeopleTrainingRecordDisplayName(record).toLowerCase();
  const testsById = getPeopleTrainingLearningTestMap();
  return [...linkedIds].flatMap((testId) => {
    const test = testsById.get(String(testId || "").trim());
    if (!test) {
      return [];
    }
    return (test.assignmentItems ?? [])
      .filter((assignment) => {
        if (item.workOrderId && String(assignment.workOrderId || "") !== String(item.workOrderId)) {
          return false;
        }
        const assignmentOib = String(assignment.externalOib || "").trim();
        const assignmentEmail = String(assignment.externalEmail || assignment.email || "").trim().toLowerCase();
        const assignmentName = String(assignment.externalFullName || assignment.userLabel || "").trim().toLowerCase();
        return Boolean(
          (recordOib && assignmentOib && recordOib === assignmentOib)
          || (recordEmail && assignmentEmail && recordEmail === assignmentEmail)
          || (recordName && assignmentName && recordName === assignmentName),
        );
      })
      .map((assignment) => ({ test, assignment }));
  });
}

function getLearningAssignmentPassPercent(test = {}, assignment = {}) {
  const numeric = Math.round(Number(assignment?.passPercent ?? test?.passPercent ?? 80));
  return Math.max(1, Math.min(100, Number.isFinite(numeric) && numeric > 0 ? numeric : 80));
}

function isLearningAssignmentCompleted(assignment = {}) {
  return String(assignment?.status || "").toLowerCase() === "completed";
}

function isLearningAssignmentPassed(test = {}, assignment = {}) {
  if (!isLearningAssignmentCompleted(assignment)) {
    return false;
  }
  if (assignment?.passed !== undefined) {
    return Boolean(assignment.passed);
  }
  const score = Math.round(Number(assignment?.scorePercent ?? 0));
  return Number.isFinite(score) && score >= getLearningAssignmentPassPercent(test, assignment);
}

function isLearningAssignmentFailed(test = {}, assignment = {}) {
  return isLearningAssignmentCompleted(assignment) && !isLearningAssignmentPassed(test, assignment);
}

function getPeopleTrainingItemExamProgress(record = {}, item = {}) {
  const assignments = getPeopleTrainingItemLearningAssignments(record, item);
  if (assignments.length > 0 && assignments.every(({ test, assignment }) => isLearningAssignmentPassed(test, assignment))) {
    return "completed";
  }
  if (assignments.some(({ test, assignment }) => isLearningAssignmentFailed(test, assignment))) {
    return "failed";
  }
  if (assignments.some(({ assignment }) => String(assignment.status || "").toLowerCase() === "in_progress")) {
    return "in_progress";
  }
  if (assignments.some(({ assignment }) => String(assignment.status || "").toLowerCase() === "pending")) {
    return "pending";
  }
  if (String(item.certificateStatus || "").toLowerCase() === "assigned") {
    return "pending";
  }
  return "";
}

function getPeopleTrainingExamOverviewRows(selection = "all", mode = "passed") {
  const records = sortPersonTrainingRecords(state.peopleTrainingRecords ?? []);
  const normalizedSelection = String(selection || "all").trim();
  const [selectionKind, selectionId = ""] = normalizedSelection.split(":");

  return records.flatMap((record) => normalizePeopleTrainingItemsForUi(record.trainingItems)
    .filter((item) => {
      if (selectionKind === "type") {
        if (item.type !== selectionId) {
          return false;
        }
      }
      if (selectionKind === "test") {
        const linkedIds = Array.isArray(item.linkedLearningTestIds)
          ? item.linkedLearningTestIds.map((value) => String(value))
          : [];
        const matchesSelectedTest = String(item.learningTestId || "") === selectionId || linkedIds.includes(selectionId);
        if (!matchesSelectedTest) {
          return false;
        }
      }
      const isPassed = isPeopleTrainingItemPassed(item);
      if (mode === "pending") {
        return !isPassed && item.status !== "not_required";
      }
      return isPassed;
    })
    .map((item) => ({ record, item })));
}

function createPeopleTrainingExamPassedRow({ record = {}, item = {} } = {}) {
  const row = document.createElement("article");
  row.className = `people-training-exam-row ${getPeopleTrainingStatusClass(item.status)}`;

  const person = document.createElement("div");
  person.className = "people-training-exam-person";
  const name = document.createElement("strong");
  name.textContent = record.fullName || [record.firstName, record.lastName].filter(Boolean).join(" ") || "Osoba bez imena";
  const personMeta = document.createElement("span");
  personMeta.textContent = [
    record.oib ? `OIB ${record.oib}` : "",
    record.jobTitle,
  ].filter(Boolean).join(" · ") || "Bez dodatnih podataka";
  person.append(name, personMeta);

  const company = document.createElement("div");
  company.className = "people-training-exam-company";
  const companyName = document.createElement("strong");
  companyName.textContent = record.companyName || getPeopleTrainingCompany(record.companyId)?.name || "Tvrtka";
  const locationName = document.createElement("span");
  locationName.textContent = record.locationName || getPeopleTrainingLocation(record.locationId)?.name || "Sve lokacije";
  company.append(companyName, locationName);

  const exam = document.createElement("div");
  exam.className = "people-training-exam-meta";
  const examName = document.createElement("strong");
  examName.textContent = item.label || item.type || "Ispit";
  const examSource = document.createElement("span");
  examSource.textContent = getPeopleTrainingItemSourceText(item) || "Ručno evidentirano";
  exam.append(examName, examSource);

  const status = document.createElement("div");
  status.className = "people-training-exam-status";
  const statusPill = createPeopleTrainingStatusPill(item);
  const certificate = document.createElement("span");
  certificate.textContent = item.certificateNumber
    ? `Uvjerenje ${item.certificateNumber}`
    : item.certificateStatus === "ready"
      ? "Uvjerenje spremno"
      : "Bez broja uvjerenja";
  status.append(statusPill, certificate);

  row.append(person, company, exam, status);
  return row;
}

function createPeopleTrainingExamStatusSection(title = "", rows = [], emptyText = "") {
  const section = document.createElement("section");
  section.className = "people-training-exam-status-section";
  const head = document.createElement("div");
  head.className = "people-training-exam-status-head";
  const titleNode = document.createElement("strong");
  titleNode.textContent = title;
  const count = document.createElement("span");
  count.className = "soft-pill";
  count.textContent = String(rows.length);
  head.append(titleNode, count);

  const list = document.createElement("div");
  list.className = "people-training-exam-status-list";
  if (rows.length) {
    list.replaceChildren(...rows.slice(0, 80).map(createPeopleTrainingExamPassedRow));
  } else {
    const empty = document.createElement("p");
    empty.className = "empty-state";
    empty.textContent = emptyText;
    list.append(empty);
  }

  section.append(head, list);
  return section;
}

