function getPeopleTrainingCertificatePrefix(typeOption = {}) {
  return String(typeOption.shortLabel || typeOption.serviceCode || typeOption.label || "OS")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^A-Za-z0-9]+/g, "")
    .toUpperCase()
    .slice(0, 12)
    || "OS";
}

function buildPeopleTrainingRecordNumberForUi(record = {}, typeOption = {}, item = {}) {
  return [
    String(item.workOrderNumber || "").trim(),
    String(typeOption.serviceCode || item.serviceCode || typeOption.shortLabel || item.shortLabel || item.type || "").trim(),
    String(record.oib || peopleTrainingOibInput?.value || "").trim().replace(/\s+/g, ""),
  ].filter(Boolean).join("-");
}

function generatePeopleTrainingCertificateNumber(record = {}, typeOption = {}, dateValue = "", reservedNumbers = new Set()) {
  const normalizedDate = normalizePeopleTrainingDate(dateValue) || getTodayDateKey();
  const year = normalizedDate.slice(0, 4) || String(new Date().getFullYear());
  const prefix = `POTV-${year}-${getPeopleTrainingCertificatePrefix(typeOption)}`;
  const usedNumbers = (state.peopleTrainingRecords ?? [])
    .flatMap((entry) => normalizePeopleTrainingItemsForUi(entry.trainingItems))
    .map((item) => String(item.certificateNumber || "").trim())
    .filter(Boolean);
  reservedNumbers.forEach((number) => {
    if (number) {
      usedNumbers.push(String(number));
    }
  });
  const maxSequence = usedNumbers.reduce((maxValue, number) => {
    const match = number.match(new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}-(\\d+)$`, "i"));
    if (!match) {
      return maxValue;
    }
    const nextValue = Number.parseInt(match[1], 10);
    return Number.isFinite(nextValue) ? Math.max(maxValue, nextValue) : maxValue;
  }, 0);
  const sequence = String(maxSequence + 1).padStart(3, "0");
  return `${prefix}-${sequence}`;
}

function readPeopleTrainingGridItems() {
  if (!peopleTrainingFormTrainingGrid) {
    return [];
  }
  const activeRecordId = String(peopleTrainingIdInput?.value || "").trim();
  const activeRecord = state.peopleTrainingRecords.find((item) => String(item.id) === activeRecordId) ?? null;
  const recordContext = {
    ...(activeRecord || {}),
    oib: peopleTrainingOibInput?.value || activeRecord?.oib || "",
  };
  const existingByType = new Map(
    [
      ...PEOPLE_TRAINING_FORM_SECTION_CONFIGS.flatMap((config) => getPeopleTrainingFallbackItemsForSection(config, activeRecord ?? {})),
      ...normalizePeopleTrainingItemsForUi(activeRecord?.trainingItems ?? []),
    ]
      .map((item) => [item.type, item]),
  );
  return Array.from(peopleTrainingFormTrainingGrid.querySelectorAll("[data-training-type]")).map((card) => {
    const readField = (field) => {
      const input = card.querySelector(`[data-training-field="${field}"]`);
      if (input instanceof HTMLInputElement && input.type === "checkbox") {
        return input.checked;
      }
      return input?.value ?? "";
    };
    const type = card.dataset.trainingType || "";
    const existing = existingByType.get(type) ?? {};
    const typeOption = getPeopleTrainingTypeOption(type, activeRecord?.trainingItems ?? []);
    const details = { ...(existing.details ?? {}) };
    [
      "riskWorkplaceKey",
      "jobTitle",
      "jobDescription",
      "theoryPlace",
      "theoryDate",
      "theoryMethod",
      "employerRepresentativeName",
      "employerRepresentativeOib",
      "additionalPersonName",
      "additionalPersonOib",
      "practicalPlace",
      "safeWorkPeriodFrom",
      "safeWorkPeriodTo",
      "referralNumber",
      "referralValidUntil",
      "examType",
      "examReason",
      "medicalJobTitle",
      "medicalJobDescription",
      "medicalHazards",
      "medicalWorkplace",
      "medicalWorkOrganization",
      "medicalBodyPositions",
      "medicalLoadWeights",
      "medicalWorkConditions",
      "medicalImportantFunctions",
      "medicalEquipment",
      "medicalSubstances",
      "medicalPpe",
      "fitnessResult",
      "fitnessRestrictions",
      "psychologicalCheckUntil",
      "visionJobTitle",
      "visionJobDescription",
      "visionReferralValidUntil",
      "visionReason",
      "visionResult",
      "visionCorrection",
      "computerWork",
    ].forEach((key) => {
      const value = readField(`details.${key}`);
      if (value !== "") {
        details[key] = /Date|From|To|Until/i.test(key) ? normalizePeopleTrainingDate(value) : String(value || "").trim();
      } else if (card.querySelector(`[data-training-field="details.${key}"]`)) {
        details[key] = "";
      }
    });
    const sectionKey = getPeopleTrainingFormSectionKey({ ...existing, ...typeOption, type });
    const passedOn = normalizePeopleTrainingDate(readField("passedOn"));
    const issuedOn = normalizePeopleTrainingDate(readField("issuedOn"))
      || (sectionKey === "safe-work" ? normalizePeopleTrainingDate(details.theoryDate) : passedOn);
    const hasValidUntilField = Boolean(card.querySelector('[data-training-field="validUntil"]'));
    const hasValidForeverField = Boolean(card.querySelector('[data-training-field="validForever"]'));
    const validUntil = hasValidUntilField ? normalizePeopleTrainingDate(readField("validUntil")) : (existing.validUntil || "");
    const hasCertificateNumberField = Boolean(card.querySelector('[data-training-field="certificateNumber"]'));
    const hasProviderField = Boolean(card.querySelector('[data-training-field="provider"]'));
    const hasNoteField = Boolean(card.querySelector('[data-training-field="note"]'));
    const certificateNumber = hasCertificateNumberField
      ? String(readField("certificateNumber") || "").trim()
      : (existing.certificateNumber || "");
    const provider = hasProviderField
      ? String(readField("provider") || "").trim()
      : (sectionKey === "safe-work" ? details.employerRepresentativeName : (existing.provider || ""));
    const note = hasNoteField ? String(readField("note") || "").trim() : (existing.note || "");
    const hasRecordNumberField = Boolean(card.querySelector('[data-training-field="recordNumber"]'));
    const shouldHaveRecordNumber = hasRecordNumberField && Boolean(
      readField("recordNumber")
      || existing.recordNumber
      || certificateNumber
      || existing.workOrderNumber
      || issuedOn
      || passedOn
      || validUntil
      || provider
      || note
      || Object.values(details).some((value) => String(value ?? "").trim()),
    );
    const recordNumber = hasRecordNumberField && shouldHaveRecordNumber ? String(readField("recordNumber") || existing.recordNumber || buildPeopleTrainingRecordNumberForUi(
      recordContext || buildPeopleTrainingPayloadPreview(),
      typeOption,
      existing,
    )).trim() : (existing.recordNumber || "");
    return {
      ...existing,
      type,
      label: typeOption.label || existing.label || "",
      shortLabel: typeOption.shortLabel || existing.shortLabel || "",
      serviceId: typeOption.serviceId || existing.serviceId || "",
      serviceName: typeOption.serviceName || existing.serviceName || "",
      serviceCode: typeOption.serviceCode || existing.serviceCode || "",
      linkedTemplateIds: typeOption.linkedTemplateIds || existing.linkedTemplateIds || [],
      linkedTemplateTitles: typeOption.linkedTemplateTitles || existing.linkedTemplateTitles || [],
      linkedLearningTestIds: typeOption.linkedLearningTestIds || existing.linkedLearningTestIds || [],
      linkedLearningTestTitles: typeOption.linkedLearningTestTitles || existing.linkedLearningTestTitles || [],
      issuedOn,
      passedOn: passedOn || existing.passedOn || issuedOn,
      validUntil,
      validForever: hasValidForeverField ? Boolean(readField("validForever")) : Boolean(existing.validForever),
      certificateNumber,
      recordNumber,
      provider,
      examMode: details.examType || details.theoryMethod || existing.examMode || "",
      details,
      note,
    };
  });
}

function buildPeopleTrainingPayloadPreview() {
  return {
    oib: peopleTrainingOibInput?.value || "",
  };
}

function buildPeopleTrainingPayload() {
  const activeRecordId = String(peopleTrainingIdInput?.value || "").trim();
  const activeRecord = state.peopleTrainingRecords.find((item) => String(item.id) === activeRecordId) ?? {};
  return {
    companyId: peopleTrainingCompanyInput?.value || "",
    locationId: peopleTrainingLocationInput?.value || "",
    firstName: peopleTrainingFirstNameInput?.value || "",
    lastName: peopleTrainingLastNameInput?.value || "",
    fatherName: peopleTrainingFatherNameInput?.value || "",
    oib: peopleTrainingOibInput?.value || "",
    language: peopleTrainingLanguageInput?.value || "",
    birthDate: peopleTrainingBirthDateInput?.value || "",
    birthCountry: peopleTrainingBirthCountryInput?.value || "",
    birthPlace: peopleTrainingBirthPlaceInput?.value || "",
    arrivalDate: peopleTrainingArrivalDateInput?.value || "",
    workPlace: peopleTrainingWorkPlaceInput?.value || "",
    activityStatus: peopleTrainingActivityStatusInput?.value || "DA",
    email: peopleTrainingEmailInput ? (peopleTrainingEmailInput.value || "") : (activeRecord.email || ""),
    phone: peopleTrainingPhoneInput ? (peopleTrainingPhoneInput.value || "") : (activeRecord.phone || ""),
    jobTitle: peopleTrainingJobTitleInput ? (peopleTrainingJobTitleInput.value || "") : (activeRecord.jobTitle || ""),
    note: peopleTrainingNoteInput ? (peopleTrainingNoteInput.value || "") : (activeRecord.note || ""),
    trainingItems: readPeopleTrainingGridItems(),
  };
}

async function handlePeopleTrainingSubmit(event) {
  event.preventDefault();
  const recordId = String(peopleTrainingIdInput?.value || "").trim();
  const method = recordId ? "PATCH" : "POST";
  const path = recordId ? `/people-training-records/${encodeURIComponent(recordId)}` : "/people-training-records";
  const success = await runMutation(() => apiRequest(path, {
    method,
    body: buildPeopleTrainingPayload(),
  }), peopleTrainingFormFeedback);

  if (success) {
    const saved = recordId
      ? state.peopleTrainingRecords.find((item) => String(item.id) === recordId)
      : state.peopleTrainingRecords
        .slice()
        .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))[0];
    if (saved) {
      populatePeopleTrainingForm(saved);
    }
    setPeopleTrainingFeedback(recordId ? "Evidencija je spremljena." : "Osoba je dodana u evidenciju.", "success");
    renderPeopleTrainingModule();
    closePeopleTrainingEditor({ reset: true });
  }
}

async function deletePeopleTrainingRecord() {
  const recordId = String(peopleTrainingIdInput?.value || "").trim();
  if (!recordId) {
    return;
  }
  const record = state.peopleTrainingRecords.find((item) => String(item.id) === recordId);
  const confirmed = window.confirm(`Obrisati evidenciju za ${record?.fullName || "ovu osobu"}?`);
  if (!confirmed) {
    return;
  }
  const success = await runMutation(() => apiRequest(`/people-training-records/${encodeURIComponent(recordId)}`, {
    method: "DELETE",
  }), peopleTrainingFormFeedback);
  if (success) {
    resetPeopleTrainingForm();
    renderPeopleTrainingModule();
    closePeopleTrainingEditor();
    setPeopleTrainingFeedback("Evidencija je obrisana.", "success");
  }
}

function createPeopleTrainingStatusPill(item = {}) {
  const pill = document.createElement("span");
  pill.className = `people-training-status-pill ${getPeopleTrainingStatusClass(item.status)}`;
  const sourceText = getPeopleTrainingItemSourceText(item);
  pill.title = [
    item.label || item.type || "Osposobljavanje",
    getPeopleTrainingStatusLabel(item.status),
    item.validUntil ? `Vrijedi do ${formatCompactDate(item.validUntil)}` : "",
    sourceText,
  ].filter(Boolean).join(" - ");
  const marker = item.status === "valid" || item.status === "not_required"
    ? "✓"
    : item.status === "expiring"
      ? "!"
      : "×";
  pill.textContent = `${marker} ${item.shortLabel || item.label || item.type || "?"}`;
  return pill;
}

function getPeopleTrainingCertificateDocument(record = {}, item = {}) {
  const attachments = Array.isArray(record.attachments) ? record.attachments : [];
  const directIds = [
    item.certificateDocumentId,
    item.type ? `certificate-${item.type}` : "",
    item.serviceId ? `certificate-${item.serviceId}` : "",
  ].map((value) => String(value || "").trim()).filter(Boolean);

  const isGeneratedCertificate = (attachment = {}) => (
    String(attachment.sourceType || "") === "people-training-certificate"
    || String(attachment.documentCategory || "").trim().toLowerCase() === "automatsko uvjerenje"
  );
  const isActiveDocument = (attachment = {}) => (
    attachment.activeDocument !== false
    && attachment.isActive !== false
    && String(attachment.documentStatus || "").trim().toLowerCase() !== "archived"
  );

  const byId = attachments.filter((attachment) => directIds.includes(String(attachment.id || "")));
  const activeById = byId.find(isActiveDocument);
  if (activeById) {
    return activeById;
  }
  if (byId.length && !byId.some(isGeneratedCertificate)) {
    return byId[0];
  }

  const lookupParts = [
    item.type,
    item.serviceId,
    item.label,
    item.serviceName,
    item.serviceCode,
    item.shortLabel,
  ].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean);

  const matches = attachments.filter((attachment) => {
    if (!isGeneratedCertificate(attachment)) {
      return false;
    }
    const key = String(attachment.generatedDocumentKey || "").trim().toLowerCase();
    if (key && lookupParts.includes(key)) {
      return true;
    }
    const haystack = [
      attachment.trainingItemType,
      attachment.trainingServiceId,
      attachment.trainingServiceCode,
      attachment.fileName,
      attachment.description,
    ].map((value) => String(value || "").trim().toLowerCase()).join(" ");
    return lookupParts.some((part) => haystack.includes(part));
  });

  return matches.find(isActiveDocument) ?? matches[0] ?? null;
}

function getPeopleTrainingCertificateMetaText(item = {}, certificateDocument = null) {
  const details = [
    item.certificateNumber ? `Potvrda ${item.certificateNumber}` : "",
    item.passedOn || item.issuedOn ? formatCompactDate(item.passedOn || item.issuedOn) : "",
    item.validForever ? "trajno" : (item.validUntil ? `vrijedi do ${formatCompactDate(item.validUntil)}` : ""),
    certificateDocument ? "PDF" : "",
  ].filter(Boolean);
  return details.join(" · ") || "Nema uvjerenja";
}

async function saveActivePeopleTrainingFormBeforePdf(recordId = "") {
  const activeRecordId = String(peopleTrainingIdInput?.value || "").trim();
  const targetRecordId = String(recordId || "").trim();
  if (!targetRecordId || activeRecordId !== targetRecordId) {
    return true;
  }

  setPeopleTrainingFeedback("Spremam podatke prije izrade PDF-a...", "success");
  const success = await runMutation(() => apiRequest(`/people-training-records/${encodeURIComponent(targetRecordId)}`, {
    method: "PATCH",
    body: {
      ...buildPeopleTrainingPayload(),
      skipCertificateGeneration: true,
    },
  }), peopleTrainingFormFeedback);

  if (success) {
    const updatedRecord = state.peopleTrainingRecords.find((entry) => String(entry.id) === targetRecordId);
    if (updatedRecord) {
      populatePeopleTrainingForm(updatedRecord);
    }
  }

  return success;
}

async function generatePeopleTrainingPdfDocuments(record = {}, item = null, { openLatest = false, force = true, button = null } = {}) {
  const recordId = String(record?.id || "").trim();
  if (!recordId) {
    return false;
  }

  const control = button instanceof HTMLButtonElement ? button : null;
  if (control) {
    control.disabled = true;
    control.classList.add("is-loading");
    control.setAttribute("aria-busy", "true");
  }

  try {
    const saved = await saveActivePeopleTrainingFormBeforePdf(recordId);
    if (!saved) {
      return false;
    }

    const activeRecord = state.peopleTrainingRecords.find((entry) => String(entry.id) === recordId) ?? record;
    const activeItem = item
      ? (normalizePeopleTrainingItemsForUi(activeRecord.trainingItems)
        .find((entry) => String(entry.type) === String(item.type) || String(entry.serviceId) === String(item.serviceId)) ?? item)
      : null;

    setPeopleTrainingFeedback(activeItem ? `Izrađujem PDF za ${activeItem.shortLabel || activeItem.label || "uslugu"}...` : "Izrađujem PDF dokumente za osobu...", "success");
    const success = await runMutation(() => apiRequest(`/people-training-records/${encodeURIComponent(recordId)}/generate-documents`, {
      method: "POST",
      body: activeItem
        ? {
          trainingType: activeItem.type,
          serviceId: activeItem.serviceId,
          force,
        }
        : { force },
    }), peopleTrainingFormFeedback);

    if (!success) {
      return false;
    }

    const updatedRecord = state.peopleTrainingRecords.find((entry) => String(entry.id) === recordId) ?? activeRecord;
    if (String(state.activePeopleTrainingRecordId || "") === recordId) {
      populatePeopleTrainingForm(updatedRecord);
    }
    renderPeopleTrainingModule();

    if (openLatest && activeItem) {
      const updatedItem = normalizePeopleTrainingItemsForUi(updatedRecord.trainingItems)
        .find((entry) => String(entry.type) === String(activeItem.type) || String(entry.serviceId) === String(activeItem.serviceId)) ?? activeItem;
      const generatedDocument = getPeopleTrainingCertificateDocument(updatedRecord, updatedItem);
      if (generatedDocument) {
        triggerModuleAttachmentDownload(generatedDocument);
      }
    }

    setPeopleTrainingFeedback(activeItem ? "PDF dokument je izrađen i označen kao aktivan." : "PDF dokumenti su izrađeni, a stari automatski PDF-ovi su ostali u arhivi.", "success");
    return true;
  } finally {
    if (control) {
      control.disabled = false;
      control.classList.remove("is-loading");
      control.removeAttribute("aria-busy");
    }
  }
}

async function openPeopleTrainingCertificate(record = {}, item = {}) {
  if (!record?.id) {
    return;
  }

  const existingDocument = getPeopleTrainingCertificateDocument(record, item);
  if (existingDocument) {
    triggerModuleAttachmentDownload(existingDocument);
    return;
  }

  if (isPeopleTrainingItemPassed(item)) {
    const generated = await generatePeopleTrainingPdfDocuments(record, item, { openLatest: true, force: false });
    if (generated) {
      return;
    }
  }

  setPeopleTrainingFeedback(`Za ${item.label || item.shortLabel || "ovo osposobljavanje"} još nema PDF uvjerenja. Otvaram dosje osobe.`, "error");
  openPeopleTrainingRecordEditor(record, { focusTarget: "dossier" });
}

function closePeopleTrainingItemMenu() {
  if (typeof closePeopleTrainingItemMenuHandler === "function") {
    closePeopleTrainingItemMenuHandler();
    closePeopleTrainingItemMenuHandler = null;
  }
}

function positionPeopleTrainingItemMenu(menu, anchor) {
  if (!(menu instanceof HTMLElement) || !(anchor instanceof HTMLElement)) {
    return;
  }

  const margin = 10;
  const anchorRect = anchor.getBoundingClientRect();
  const menuRect = menu.getBoundingClientRect();
  const left = Math.min(
    Math.max(anchorRect.left, margin),
    Math.max(margin, window.innerWidth - menuRect.width - margin),
  );
  let top = anchorRect.bottom + 8;
  if (top + menuRect.height > window.innerHeight - margin) {
    top = Math.max(margin, anchorRect.top - menuRect.height - 8);
  }

  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function createPeopleTrainingMenuButton(label, iconName, onClick, { disabled = false } = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.setAttribute("role", "menuitem");
  button.disabled = disabled;
  const icon = document.createElement("span");
  icon.className = "people-training-item-menu-icon";
  icon.innerHTML = getWorkOrderIconMarkup(iconName);
  const text = document.createElement("span");
  text.textContent = label;
  button.append(icon, text);
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    closePeopleTrainingItemMenu();
    if (!disabled) {
      onClick?.();
    }
  });
  return button;
}

function openPeopleTrainingItemMenu(record = {}, item = {}, anchor = null) {
  if (!(anchor instanceof HTMLElement)) {
    return;
  }

  closePeopleTrainingItemMenu();

  const certificateDocument = getPeopleTrainingCertificateDocument(record, item);
  const menu = document.createElement("div");
  menu.className = "people-training-item-menu";
  menu.setAttribute("role", "menu");
  menu.dataset.preventRowOpen = "true";

  const header = document.createElement("div");
  header.className = "people-training-item-menu-head";
  const code = document.createElement("strong");
  code.textContent = item.shortLabel || item.serviceCode || item.label || "Usluga";
  const label = document.createElement("span");
  label.textContent = [
    item.label || item.serviceName || "Osposobljavanje",
    getPeopleTrainingStatusLabel(item.status),
  ].filter(Boolean).join(" · ");
  header.append(code, label);

  menu.append(
    header,
    createPeopleTrainingMenuButton(certificateDocument ? "Otvori aktivni PDF" : "Otvori PDF potvrdu", "download", () => {
      void openPeopleTrainingCertificate(record, item);
    }, {
      disabled: !certificateDocument && !isPeopleTrainingItemPassed(item),
    }),
    createPeopleTrainingMenuButton("Napravi novi PDF", "document", () => {
      void generatePeopleTrainingPdfDocuments(record, item, { openLatest: true, force: true });
    }, {
      disabled: !hasPeopleTrainingCertificateTemplateForItem(item, record),
    }),
    createPeopleTrainingMenuButton("Otvori osposobljavanje za tu uslugu", "service", () => {
      void openPeopleTrainingForService(record, item);
    }),
  );

  document.body.append(menu);
  positionPeopleTrainingItemMenu(menu, anchor);

  const handleOutsidePointer = (event) => {
    if (menu.contains(event.target) || anchor.contains(event.target)) {
      return;
    }
    closePeopleTrainingItemMenu();
  };
  const handleKeydown = (event) => {
    if (event.key === "Escape") {
      closePeopleTrainingItemMenu();
    }
  };
  const handleReposition = () => positionPeopleTrainingItemMenu(menu, anchor);

  document.addEventListener("pointerdown", handleOutsidePointer, true);
  document.addEventListener("keydown", handleKeydown, true);
  window.addEventListener("resize", handleReposition);
  window.addEventListener("scroll", handleReposition, true);

  closePeopleTrainingItemMenuHandler = () => {
    document.removeEventListener("pointerdown", handleOutsidePointer, true);
    document.removeEventListener("keydown", handleKeydown, true);
    window.removeEventListener("resize", handleReposition);
    window.removeEventListener("scroll", handleReposition, true);
    menu.remove();
  };
}

function openPeopleTrainingAttachmentMenu(record = {}, anchor = null) {
  if (!(anchor instanceof HTMLElement)) {
    return;
  }

  closePeopleTrainingItemMenu();

  const attachments = Array.isArray(record.attachments)
    ? record.attachments.filter((attachment) => String(attachment.storageUrl || attachment.dataUrl || "").trim())
    : [];
  const menu = document.createElement("div");
  menu.className = "people-training-item-menu people-training-attachment-menu";
  menu.setAttribute("role", "menu");
  menu.dataset.preventRowOpen = "true";

  const header = document.createElement("div");
  header.className = "people-training-item-menu-head";
  const title = document.createElement("strong");
  title.textContent = "Prilozi osobe";
  const subtitle = document.createElement("span");
  subtitle.textContent = attachments.length > 0
    ? `${attachments.length} priloga u dosjeu`
    : "Nema spremljenih priloga";
  header.append(title, subtitle);
  menu.append(header);

  if (attachments.length === 0) {
    const empty = document.createElement("p");
    empty.className = "people-training-attachment-menu-empty";
    empty.textContent = "Za ovu osobu još nema priloga.";
    menu.append(empty);
  } else {
    attachments.forEach((attachment) => {
      const button = document.createElement("button");
      button.type = "button";
      button.setAttribute("role", "menuitem");

      const icon = document.createElement("span");
      icon.className = "people-training-item-menu-icon";
      icon.innerHTML = getWorkOrderIconMarkup("document");

      const copy = document.createElement("span");
      copy.className = "people-training-attachment-menu-copy";
      const category = document.createElement("strong");
      category.textContent = attachment.documentCategory || "Ostalo";
      const file = document.createElement("small");
      file.textContent = [
        attachment.fileName || "Dokument",
        attachment.updatedAt ? formatCompactDate(attachment.updatedAt) : "",
      ].filter(Boolean).join(" · ");
      copy.append(category, file);

      button.append(icon, copy);
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        closePeopleTrainingItemMenu();
        triggerModuleAttachmentDownload(attachment);
      });
      menu.append(button);
    });
  }

  document.body.append(menu);
  positionPeopleTrainingItemMenu(menu, anchor);

  const handleOutsidePointer = (event) => {
    if (menu.contains(event.target) || anchor.contains(event.target)) {
      return;
    }
    closePeopleTrainingItemMenu();
  };
  const handleKeydown = (event) => {
    if (event.key === "Escape") {
      closePeopleTrainingItemMenu();
    }
  };
  const handleReposition = () => positionPeopleTrainingItemMenu(menu, anchor);

  document.addEventListener("pointerdown", handleOutsidePointer, true);
  document.addEventListener("keydown", handleKeydown, true);
  window.addEventListener("resize", handleReposition);
  window.addEventListener("scroll", handleReposition, true);

  closePeopleTrainingItemMenuHandler = () => {
    document.removeEventListener("pointerdown", handleOutsidePointer, true);
    document.removeEventListener("keydown", handleKeydown, true);
    window.removeEventListener("resize", handleReposition);
    window.removeEventListener("scroll", handleReposition, true);
    menu.remove();
  };
}

function createPeopleTrainingCertificatePill(record = {}, item = {}) {
  const certificateDocument = getPeopleTrainingCertificateDocument(record, item);
  const button = document.createElement("button");
  button.type = "button";
  button.className = `people-training-certificate-pill ${getPeopleTrainingStatusClass(item.status)}${certificateDocument ? " has-pdf" : ""}`;
  button.title = [
    item.label || item.serviceName || "Osposobljavanje",
    getPeopleTrainingStatusLabel(item.status),
    getPeopleTrainingCertificateMetaText(item, certificateDocument),
  ].filter(Boolean).join(" · ");
  const marker = item.status === "valid" || item.status === "not_required"
    ? "✓"
    : item.status === "expiring"
      ? "!"
      : "×";
  const code = document.createElement("strong");
  code.textContent = `${marker} ${item.serviceCode || item.shortLabel || "?"}`;
  button.append(code);
  const examProgress = getPeopleTrainingItemExamProgress(record, item);
  if (examProgress) {
    const progressIcon = document.createElement("span");
    progressIcon.className = `people-training-certificate-progress-icon is-${examProgress}`;
    progressIcon.title = examProgress === "in_progress" ? "Ispit u tijeku" : "Ispit dodijeljen";
    progressIcon.setAttribute("aria-label", progressIcon.title);
    progressIcon.innerHTML = getWorkOrderIconMarkup(examProgress === "in_progress" ? "status" : "reminder");
    button.append(progressIcon);
  }
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openPeopleTrainingItemMenu(record, item, button);
  });
  return button;
}

function getPeopleTrainingItemSourceText(item = {}) {
  const parts = [];
  if (item.examMode) {
    parts.push(getWorkOrderDocumentTrainingModeOption(item.examMode).label);
  }
  if (item.workOrderNumber) {
    parts.push(`RN ${item.workOrderNumber}`);
  }
  if (item.learningTestTitle) {
    parts.push(item.learningTestTitle);
  }
  if (item.serviceCode || item.serviceName) {
    parts.push([item.serviceCode, item.serviceName].filter(Boolean).join(" "));
  }
  if (item.passedOn || item.issuedOn) {
    parts.push(formatCompactDate(item.passedOn || item.issuedOn));
  }
  if (item.certificateStatus === "ready") {
    parts.push("uvjerenje spremno");
  } else if (item.certificateStatus === "issued") {
    parts.push("uvjerenje izdano");
  }
  return parts.join(" · ");
}

function getPeopleTrainingSelectedTypeOption() {
  const selectedType = String(state.peopleTrainingFilters.trainingType || peopleTrainingTypeFilterInput?.value || "all")
    .trim()
    .toLowerCase();
  if (!selectedType || selectedType === "all") {
    return null;
  }

  return getPeopleTrainingTypeOptions()
    .find((option) => String(option.value || "").trim().toLowerCase() === selectedType) ?? null;
}

function buildPeopleTrainingWorkOrderServiceItem(typeOption = {}, sourceItem = {}) {
  const serviceCatalogItem = typeOption.serviceId
    ? state.serviceCatalog.find((entry) => String(entry.id) === String(typeOption.serviceId))
    : null;

  return buildWorkOrderServiceItemSnapshot(serviceCatalogItem ?? {
    id: typeOption.serviceId || sourceItem.serviceId || "",
    name: typeOption.serviceName || typeOption.label || sourceItem.serviceName || sourceItem.label || "Osposobljavanje",
    serviceCode: typeOption.serviceCode || sourceItem.serviceCode || typeOption.shortLabel || sourceItem.shortLabel || "",
    serviceType: "znr",
    linkedTemplateIds: typeOption.linkedTemplateIds || sourceItem.linkedTemplateIds || [],
    linkedTemplateTitles: typeOption.linkedTemplateTitles || sourceItem.linkedTemplateTitles || [],
    linkedLearningTestIds: typeOption.linkedLearningTestIds || sourceItem.linkedLearningTestIds || [],
    linkedLearningTestTitles: typeOption.linkedLearningTestTitles || sourceItem.linkedLearningTestTitles || [],
    isTraining: true,
  });
}

function getPeopleTrainingRecordDisplayName(record = {}) {
  return String(
    record.fullName
    || [record.firstName, record.lastName].filter(Boolean).join(" ")
    || "Osoba bez imena",
  ).trim() || "Osoba bez imena";
}

function getPeopleTrainingLinkedLearningTests(typeOption = {}) {
  const linkedIds = new Set(
    (Array.isArray(typeOption.linkedLearningTestIds) ? typeOption.linkedLearningTestIds : [])
      .map((value) => String(value || "").trim())
      .filter(Boolean),
  );
  if (typeOption.serviceId) {
    const service = (state.serviceCatalog ?? []).find((item) => String(item.id) === String(typeOption.serviceId));
    (service?.linkedLearningTestIds ?? [])
      .map((value) => String(value || "").trim())
      .filter(Boolean)
      .forEach((value) => linkedIds.add(value));
  }
  return sortLearningTests(state.learningTests ?? [])
    .filter((test) => linkedIds.has(String(test.id || "")));
}

function getLearningTestMatchTerms(test = {}) {
  const explicitTerms = String(test.matchKeywords || "")
    .split(/[\n,;|]+/)
    .map((entry) => normalizeLooseName(entry))
    .filter((entry) => entry.length >= 3);
  const descriptiveTerms = [
    test.title,
    test.intendedFor,
    test.recommendationRules,
  ]
    .join(" ")
    .split(/\s+/)
    .map((entry) => normalizeLooseName(entry))
    .filter((entry) => entry.length >= 5);
  return Array.from(new Set([...explicitTerms, ...descriptiveTerms])).slice(0, 80);
}

function buildPeopleTrainingRecordRecommendationText(record = {}) {
  const trainingItems = normalizePeopleTrainingItemsForUi(record.trainingItems);
  return normalizeLooseName([
    record.jobTitle,
    record.workPlace,
    record.note,
    record.companyName,
    record.locationName,
    ...trainingItems.flatMap((item) => [
      item.label,
      item.shortLabel,
      item.serviceName,
      item.serviceCode,
      item.details?.jobDescription,
      item.details?.jobTitle,
    ]),
  ].filter(Boolean).join(" "));
}

function scoreLearningTestForPeopleTrainingRecord(test = {}, record = {}) {
  if (String(test.status || "") !== "active") {
    return 0;
  }
  const haystack = buildPeopleTrainingRecordRecommendationText(record);
  if (!haystack) {
    return 0;
  }
  const terms = getLearningTestMatchTerms(test);
  if (!terms.length) {
    return 0;
  }
  return terms.reduce((score, term) => {
    if (!term) {
      return score;
    }
    if (haystack === term) {
      return score + 6;
    }
    if (haystack.includes(term)) {
      return score + (term.includes(" ") ? 4 : 2);
    }
    return score;
  }, 0);
}

function getRecommendedLearningTestsForPeopleTrainingRecord(record = {}) {
  return sortLearningTests(state.learningTests ?? [])
    .map((test) => ({ test, score: scoreLearningTestForPeopleTrainingRecord(test, record) }))
    .filter((entry) => entry.score > 0)
    .sort((left, right) => right.score - left.score || String(left.test.title || "").localeCompare(String(right.test.title || ""), "hr"))
    .map((entry) => entry.test);
}

function isPeopleTrainingServiceRecommendedForRecord(typeOption = {}, record = {}) {
  const linkedTests = getPeopleTrainingLinkedLearningTests(typeOption);
  return linkedTests.some((test) => scoreLearningTestForPeopleTrainingRecord(test, record) > 0);
}

function buildPeopleTrainingBulkPreviewRows(records = [], typeOption = {}) {
  const tests = getPeopleTrainingLinkedLearningTests(typeOption);
  const groups = groupPeopleTrainingRecordsForWorkOrders(records);
  const groupIndex = new Map(
    groups.map((group, index) => [`${group.companyId}::${group.locationId}`, index + 1]),
  );
  return records.map((record) => {
    const locationId = getPeopleTrainingRecordWorkOrderLocationId(record);
    const groupKey = `${String(record.companyId || "").trim()}::${locationId}`;
    const company = getPeopleTrainingCompany(record.companyId);
    const location = locationId ? getPeopleTrainingLocation(locationId) : null;
    return {
      record,
      groupNumber: groupIndex.get(groupKey) || 0,
      companyName: record.companyName || company?.name || "Tvrtka nije zadana",
      locationName: record.locationName || location?.name || "Sve lokacije",
      serviceLabel: typeOption.serviceCode
        ? `${typeOption.serviceCode} · ${typeOption.label || typeOption.serviceName || ""}`.trim()
        : (typeOption.label || typeOption.serviceName || "Osposobljavanje"),
      tests,
      emailState: record.email
        ? `${record.email} · ${tests.length || 0} pristupa`
        : "Bez emaila",
    };
  });
}

function getPeopleTrainingBulkPreviewServiceLabel(typeOption = null) {
  if (!typeOption?.value) {
    return "Odaberi uslugu za RN";
  }
  return typeOption.serviceCode
    ? `${typeOption.serviceCode} · ${typeOption.label || typeOption.serviceName || ""}`.trim()
    : (typeOption.label || typeOption.serviceName || "Osposobljavanje");
}

function getPeopleTrainingBulkRecordKey(record = {}) {
  return String(record.id || getPeopleTrainingRecordDisplayName(record)).trim();
}

function createPeopleTrainingBulkSelectionMap(records = [], typeOption = null) {
  const selectionMap = new Map();
  if (!typeOption?.value) {
    return selectionMap;
  }

  records.forEach((record) => {
    const recordKey = getPeopleTrainingBulkRecordKey(record);
    if (recordKey) {
      selectionMap.set(recordKey, new Set([String(typeOption.value)]));
    }
  });
  return selectionMap;
}

function getPeopleTrainingBulkSelectionSet(selectionMap = new Map(), record = {}) {
  const recordKey = getPeopleTrainingBulkRecordKey(record);
  if (!recordKey) {
    return new Set();
  }
  if (!selectionMap.has(recordKey)) {
    selectionMap.set(recordKey, new Set());
  }
  return selectionMap.get(recordKey);
}

function getPeopleTrainingItemDaysUntilExpiry(item = {}) {
  const validUntil = normalizePeopleTrainingDate(item.validUntil || item.validTo || item.expiresOn);
  if (!validUntil) {
    return null;
  }
  const today = new Date();
  const todayIso = [
    today.getFullYear(),
    String(today.getMonth() + 1).padStart(2, "0"),
    String(today.getDate()).padStart(2, "0"),
  ].join("-");
  const due = new Date(`${validUntil}T00:00:00`);
  const now = new Date(`${todayIso}T00:00:00`);
  return Math.ceil((due.getTime() - now.getTime()) / 86400000);
}

function doesPeopleTrainingItemMatchBulkPreset(item = {}, preset = {}) {
  const status = String(item.status || "").trim().toLowerCase();
  if (preset.mode === "all") {
    return true;
  }
  if (preset.mode === "clear") {
    return false;
  }
  if (preset.mode === "needs_action") {
    return status === "missing" || status === "expired" || status === "expiring";
  }
  if (preset.mode === "missing_expired") {
    return status === "missing" || status === "expired";
  }
  if (preset.mode === "expiring") {
    const days = getPeopleTrainingItemDaysUntilExpiry(item);
    return days !== null && days >= 0 && days <= Number(preset.days || 0);
  }
  return false;
}

function applyPeopleTrainingBulkSelectionPreset(records = [], serviceOptions = [], selectionMap = new Map(), preset = {}) {
  selectionMap.clear();
  if (preset.mode === "clear") {
    return;
  }

  records.forEach((record) => {
    const selected = getPeopleTrainingBulkSelectionSet(selectionMap, record);
    const items = normalizePeopleTrainingItemsForUi(record.trainingItems);
    serviceOptions.forEach((typeOption) => {
      const item = items.find((entry) => entry.type === typeOption.value) ?? {};
      const matchesPreset = preset.mode === "recommended"
        ? isPeopleTrainingServiceRecommendedForRecord(typeOption, record)
        : doesPeopleTrainingItemMatchBulkPreset(item, preset);
      if (matchesPreset) {
        selected.add(String(typeOption.value));
      }
    });
    if (selected.size === 0) {
      selectionMap.delete(getPeopleTrainingBulkRecordKey(record));
    }
  });
}

function getPeopleTrainingBulkSelectedEntries(records = [], selection = null, serviceOptions = getPeopleTrainingTypeOptions()) {
  const optionsByValue = new Map(
    serviceOptions.map((option) => [String(option.value || ""), option]),
  );
  if (selection?.value && !optionsByValue.has(String(selection.value))) {
    optionsByValue.set(String(selection.value), selection);
  }
  const entries = [];

  records.forEach((record) => {
    const selectedValues = selection instanceof Map
      ? [...(selection.get(getPeopleTrainingBulkRecordKey(record)) ?? [])]
      : selection?.value
        ? [String(selection.value)]
        : [];
    if (!selectedValues.length) {
      return;
    }
    const items = normalizePeopleTrainingItemsForUi(record.trainingItems);
    selectedValues.forEach((value) => {
      const typeOption = optionsByValue.get(String(value));
      if (!typeOption) {
        return;
      }
      const item = items.find((entry) => entry.type === typeOption.value) ?? {};
      entries.push({ record, typeOption, item });
    });
  });

  return entries;
}

function groupPeopleTrainingEntriesForWorkOrders(entries = []) {
  const groups = new Map();

  entries.forEach((entry) => {
    const record = entry.record ?? {};
    const companyId = String(record.companyId || "").trim();
    if (!companyId) {
      return;
    }
    const locationId = getPeopleTrainingRecordWorkOrderLocationId(record);
    const key = `${companyId}::${locationId}`;
    if (!groups.has(key)) {
      groups.set(key, {
        companyId,
        locationId,
        records: [],
        entries: [],
      });
    }
    const group = groups.get(key);
    group.entries.push(entry);
    if (!group.records.some((groupRecord) => String(groupRecord.id) === String(record.id))) {
      group.records.push(record);
    }
  });

  return [...groups.values()];
}

function getPeopleTrainingBulkGroupSelectedEntries(group = {}, serviceOptions = [], selectionMap = new Map()) {
  return getPeopleTrainingBulkSelectedEntries(group.records ?? [], selectionMap, serviceOptions);
}

function buildPeopleTrainingBulkPreviewGroups(records = [], serviceOptions = [], selectionMap = new Map()) {
  const groups = new Map();
  let nextWorkOrderNumber = 0;

  records.forEach((record) => {
    const companyId = String(record.companyId || "").trim();
    const locationId = companyId ? getPeopleTrainingRecordWorkOrderLocationId(record) : "";
    const key = companyId ? `${companyId}::${locationId}` : `missing-company::${record.id || getPeopleTrainingRecordDisplayName(record)}`;
    if (!groups.has(key)) {
      if (companyId) {
        nextWorkOrderNumber += 1;
      }
      const company = companyId ? getPeopleTrainingCompany(companyId) : null;
      const location = locationId ? getPeopleTrainingLocation(locationId) : null;
      groups.set(key, {
        key,
        groupNumber: companyId ? nextWorkOrderNumber : 0,
        companyId,
        locationId,
        company,
        location,
        companyName: record.companyName || company?.name || "Tvrtka nije zadana",
        companyOib: company?.oib || record.companyOib || "",
        headquarters: company?.headquarters || company?.address || "",
        locationName: record.locationName || location?.name || (companyId ? "Sve lokacije" : "Nije vezano"),
        locationMeta: [location?.region, location?.coordinates].filter(Boolean).join(" · "),
        canOpen: Boolean(companyId),
        records: [],
      });
    }
    groups.get(key).records.push(record);
  });

  return [...groups.values()].sort((left, right) => (
    Number(left.groupNumber || 9999) - Number(right.groupNumber || 9999)
    || String(left.companyName || "").localeCompare(String(right.companyName || ""), "hr", { numeric: true })
  ));
}

function createPeopleTrainingBulkServiceCell(record = {}, typeOption = {}, selectionMap = new Map(), onSelectionChange = () => {}) {
  const items = normalizePeopleTrainingItemsForUi(record.trainingItems);
  const item = items.find((entry) => entry.type === typeOption.value) ?? {};
  const selected = getPeopleTrainingBulkSelectionSet(selectionMap, record).has(String(typeOption.value));
  const isRecommended = isPeopleTrainingServiceRecommendedForRecord(typeOption, record);
  const label = document.createElement("label");
  label.className = `people-training-bulk-service-cell ${getPeopleTrainingStatusClass(item.status)}${selected ? " is-selected" : ""}${isRecommended ? " is-recommended" : ""}`;
  label.title = [
    typeOption.label || typeOption.serviceName || "Usluga",
    getPeopleTrainingStatusLabel(item.status),
    item.validUntil ? `Vrijedi do ${formatCompactDate(item.validUntil)}` : "",
    isRecommended ? "Predloženo prema opisu radnog mjesta" : "",
  ].filter(Boolean).join(" · ");

  const input = document.createElement("input");
  input.type = "checkbox";
  input.checked = selected;
  input.setAttribute("aria-label", `${selected ? "Makni" : "Odaberi"} ${typeOption.serviceCode || typeOption.shortLabel || typeOption.label} za ${getPeopleTrainingRecordDisplayName(record)}`);
  input.addEventListener("change", () => {
    const selectedSet = getPeopleTrainingBulkSelectionSet(selectionMap, record);
    if (input.checked) {
      selectedSet.add(String(typeOption.value));
    } else {
      selectedSet.delete(String(typeOption.value));
    }
    if (selectedSet.size === 0) {
      selectionMap.delete(getPeopleTrainingBulkRecordKey(record));
    }
    onSelectionChange();
  });

  const code = document.createElement("strong");
  code.textContent = typeOption.serviceCode || typeOption.shortLabel || buildPeopleTrainingShortLabel(typeOption.label, "?");
  const status = document.createElement("span");
  status.textContent = item.validUntil
    ? formatCompactDate(item.validUntil)
    : isRecommended
      ? "predloženo"
      : getPeopleTrainingStatusLabel(item.status);
  label.append(input, code, status);
  return label;
}

function createPeopleTrainingBulkPreviewPersonRow(record = {}, serviceOptions = [], selectionMap = new Map(), onSelectionChange = () => {}) {
  const row = document.createElement("article");
  row.className = "people-training-bulk-person-row";

  const identity = document.createElement("div");
  identity.className = "people-training-rn-person-identity";
  const name = document.createElement("strong");
  name.textContent = getPeopleTrainingRecordDisplayName(record);
  const meta = document.createElement("span");
  meta.textContent = [
    record.oib ? `OIB ${record.oib}` : "",
    record.jobTitle || "",
    record.email || "",
  ].filter(Boolean).join(" · ") || "Bez dodatnih podataka";
  identity.append(name, meta);

  const services = document.createElement("div");
  services.className = "people-training-bulk-service-cells";
  services.style.setProperty("--bulk-service-count", String(Math.max(serviceOptions.length, 1)));
  if (serviceOptions.length) {
    services.replaceChildren(...serviceOptions.map((option) => (
      createPeopleTrainingBulkServiceCell(record, option, selectionMap, onSelectionChange)
    )));
  } else {
    const empty = document.createElement("p");
    empty.className = "empty-state";
    empty.textContent = "Nema usluga iz List of services za ljude.";
    services.append(empty);
  }

  row.append(identity, services);
  return row;
}

function createPeopleTrainingBulkServiceHeader(serviceOptions = []) {
  const header = document.createElement("div");
  header.className = "people-training-bulk-service-header";
  header.style.setProperty("--bulk-service-count", String(Math.max(serviceOptions.length, 1)));
  serviceOptions.forEach((option) => {
    const cell = document.createElement("span");
    cell.textContent = option.serviceCode || option.shortLabel || buildPeopleTrainingShortLabel(option.label, "?");
    cell.title = option.label || option.serviceName || cell.textContent;
    header.append(cell);
  });
  return header;
}

function createPeopleTrainingBulkPreviewGroupCard(group = {}, serviceOptions = [], selectionMap = new Map(), onSelectionChange = () => {}) {
  const details = document.createElement("details");
  details.className = `people-training-bulk-group-card${group.canOpen ? "" : " is-blocked"}`;
  details.open = true;
  const selectedEntries = getPeopleTrainingBulkGroupSelectedEntries(group, serviceOptions, selectionMap);
  const uniqueServices = new Map(
    selectedEntries.map((entry) => [entry.typeOption.value, entry.typeOption]),
  );
  const linkedTestCount = selectedEntries.reduce((count, entry) => (
    count + getPeopleTrainingLinkedLearningTests(entry.typeOption).length
  ), 0);

  const summary = document.createElement("summary");
  summary.className = "people-training-rn-card-head";
  const title = document.createElement("div");
  title.className = "people-training-rn-card-title";
  const rn = document.createElement("strong");
  rn.textContent = group.canOpen ? `Novi RN ${group.groupNumber}` : "Nedostaje tvrtka";
  const subtitle = document.createElement("span");
  subtitle.textContent = [
    group.companyName,
    group.locationName,
    uniqueServices.size
      ? `${uniqueServices.size} usluga u RN`
      : "Odaberi usluge za RN",
  ].filter(Boolean).join(" · ");
  title.append(rn, subtitle);

  const chips = document.createElement("div");
  chips.className = "people-training-rn-card-chips";
  const ready = document.createElement("span");
  ready.className = `people-training-progress-pill ${group.canOpen ? "is-pending" : "is-missing"}`;
  ready.textContent = group.canOpen && selectedEntries.length ? "Spremno za RN" : group.canOpen ? "Čeka odabir" : "Ne može otvoriti RN";
  const people = document.createElement("span");
  people.className = "soft-pill";
  people.textContent = `${group.records.length} osoba`;
  const exam = document.createElement("span");
  exam.className = "soft-pill";
  exam.textContent = `${selectedEntries.length} polaganja · ${linkedTestCount} online`;
  chips.append(ready, people, exam);
  summary.append(title, chips);

  const meta = document.createElement("div");
  meta.className = "people-training-rn-card-meta";
  meta.append(
    createPeopleTrainingRnMetaItem("Tvrtka", group.companyName),
    createPeopleTrainingRnMetaItem("OIB", group.companyOib || "-"),
    createPeopleTrainingRnMetaItem("Sjedište", group.headquarters || "-"),
    createPeopleTrainingRnMetaItem("Lokacija", group.locationName),
    createPeopleTrainingRnMetaItem("Lokacija info", group.locationMeta || "-"),
    createPeopleTrainingRnMetaItem("Usluge u RN", [...uniqueServices.values()]
      .map((option) => option.serviceCode || option.shortLabel || option.label)
      .filter(Boolean)
      .join(", ") || "Nije odabrano"),
  );

  const matrixHead = document.createElement("div");
  matrixHead.className = "people-training-bulk-matrix-head";
  const personHead = document.createElement("span");
  personHead.textContent = "Osoba";
  matrixHead.append(personHead, createPeopleTrainingBulkServiceHeader(serviceOptions));

  const peopleList = document.createElement("div");
  peopleList.className = "people-training-rn-person-list people-training-bulk-person-list";
  peopleList.replaceChildren(
    ...group.records
      .slice()
      .sort((left, right) => getPeopleTrainingRecordDisplayName(left).localeCompare(getPeopleTrainingRecordDisplayName(right), "hr", { numeric: true }))
      .map((record) => createPeopleTrainingBulkPreviewPersonRow(record, serviceOptions, selectionMap, onSelectionChange)),
  );

  details.append(summary, meta, matrixHead, peopleList);
  return details;
}

function closePeopleTrainingBulkPreviewDialog(dialog = null) {
  const target = dialog || document.querySelector(".people-training-bulk-preview-backdrop");
  if (target instanceof HTMLElement) {
    target.remove();
  }
  document.body.classList.remove("modal-open");
}

function openPeopleTrainingBulkPreviewDialog(records = [], typeOption = {}) {
  const serviceOptions = getPeopleTrainingTypeOptions();
  const selectionMap = createPeopleTrainingBulkSelectionMap(records, typeOption);
  let selectedMode = normalizeWorkOrderDocumentTrainingMode(state.workOrderDocumentWizard.trainingMode || "online_test");

  const backdrop = document.createElement("div");
  backdrop.className = "people-training-bulk-preview-backdrop";
  backdrop.setAttribute("role", "presentation");

  const modal = document.createElement("section");
  modal.className = "people-training-bulk-preview-modal";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-label", "Pregled masovnog osposobljavanja");

  const head = document.createElement("div");
  head.className = "people-training-bulk-preview-head";
  const copy = document.createElement("div");
  const kicker = document.createElement("p");
  kicker.className = "section-kicker";
  kicker.textContent = "Pregled prije otvaranja";
  const title = document.createElement("h3");
  title.textContent = "Masovno osposobljavanje";
  const summary = document.createElement("p");
  summary.className = "helper-copy module-copy";
  copy.append(kicker, title, summary);

  const quickActions = document.createElement("div");
  quickActions.className = "people-training-bulk-quick-actions";
  const quickLabel = document.createElement("span");
  quickLabel.textContent = "Brzi odabir";
  quickActions.append(quickLabel);

  const closeButton = document.createElement("button");
  closeButton.type = "button";
  closeButton.className = "ghost-button";
  closeButton.textContent = "Zatvori";
  closeButton.addEventListener("click", () => closePeopleTrainingBulkPreviewDialog(backdrop));
  head.append(copy, quickActions, closeButton);

  const body = document.createElement("div");
  body.className = "people-training-bulk-preview-body";

  const flow = document.createElement("div");
  flow.className = "people-training-bulk-flow";
  [
    ["1", "Osobe"],
    ["2", "Usluge"],
    ["3", "RN"],
    ["4", "Nastavi izradu"],
  ].forEach(([step, label]) => {
    const item = document.createElement("span");
    item.innerHTML = `<strong>${escapeHtml(step)}</strong><small>${escapeHtml(label)}</small>`;
    flow.append(item);
  });

  const modePanel = document.createElement("div");
  modePanel.className = "people-training-bulk-mode-panel";
  const modeCopy = document.createElement("div");
  modeCopy.className = "people-training-bulk-mode-copy";
  const modeTitle = document.createElement("strong");
  modeTitle.textContent = "Način provedbe";
  const modeHelp = document.createElement("span");
  modeHelp.textContent = "Odaberi kako se polaganje pokreće nakon otvaranja RN-a.";
  modeCopy.append(modeTitle, modeHelp);
  const modeButtons = document.createElement("div");
  modeButtons.className = "people-training-bulk-mode-buttons";
  const renderModeButtons = () => {
    modeButtons.replaceChildren(...WORK_ORDER_DOCUMENT_TRAINING_MODE_OPTIONS.map((option) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "people-training-bulk-mode-button";
      button.classList.toggle("is-active", option.value === selectedMode);
      button.innerHTML = `${getWorkOrderIconMarkup(option.iconName || "service")}<span>${escapeHtml(option.label)}</span>`;
      button.addEventListener("click", () => {
        selectedMode = option.value;
        state.workOrderDocumentWizard.trainingMode = option.value;
        renderModeButtons();
        renderPreviewGroups();
      });
      return button;
    }));
  };
  modePanel.append(modeCopy, modeButtons);

  const groupList = document.createElement("div");
  groupList.className = "people-training-bulk-preview-groups";

  const actions = document.createElement("div");
  actions.className = "people-training-bulk-preview-actions";
  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "ghost-button";
  cancelButton.textContent = "Odustani";
  cancelButton.addEventListener("click", () => closePeopleTrainingBulkPreviewDialog(backdrop));

  const openButton = document.createElement("button");
  openButton.type = "button";
  openButton.className = "primary-button";
  openButton.textContent = "Otvori RN i nastavi";
  openButton.addEventListener("click", () => {
    const selectedEntries = getPeopleTrainingBulkSelectedEntries(records, selectionMap, serviceOptions);
    if (selectedEntries.length === 0) {
      setPeopleTrainingFeedback("Odaberi barem jednu uslugu za masovno osposobljavanje.", "error");
      return;
    }
    closePeopleTrainingBulkPreviewDialog(backdrop);
    void executeBulkPeopleTrainingWorkOrders(records, selectionMap, { examMode: selectedMode });
  });
  actions.append(cancelButton, openButton);

  const renderPreviewGroups = () => {
    const selectedEntries = getPeopleTrainingBulkSelectedEntries(records, selectionMap, serviceOptions);
    const workOrderGroups = groupPeopleTrainingEntriesForWorkOrders(selectedEntries);
    const uniqueServices = new Set(selectedEntries.map((entry) => entry.typeOption.value));
    const groups = buildPeopleTrainingBulkPreviewGroups(records, serviceOptions, selectionMap);
    const modeLabel = getWorkOrderDocumentTrainingModeOption(selectedMode).label;
    summary.textContent = `${records.length} osoba · ${workOrderGroups.length} RN po tvrtki i lokaciji · ${selectedEntries.length} odabranih polaganja · ${uniqueServices.size} usluga u RN · ${modeLabel}.`;
    groupList.replaceChildren(...groups.map((group) => (
      createPeopleTrainingBulkPreviewGroupCard(group, serviceOptions, selectionMap, renderPreviewGroups)
    )));
    openButton.disabled = selectedEntries.length === 0 || workOrderGroups.length === 0;
    openButton.title = selectedEntries.length === 0
      ? "Odaberi usluge po osobama prije otvaranja RN-a."
      : workOrderGroups.length === 0
        ? "Za odabrane osobe nedostaje tvrtka."
        : "Otvori RN po tvrtki i lokaciji pa nastavi izradu dokumentacije.";
  };

  const addQuickButton = (label = "", preset = {}) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "ghost-button people-training-bulk-quick-button";
    button.textContent = label;
    button.addEventListener("click", () => {
      applyPeopleTrainingBulkSelectionPreset(records, serviceOptions, selectionMap, preset);
      renderPreviewGroups();
    });
    quickActions.append(button);
  };
  addQuickButton("Treba riješiti", { mode: "needs_action" });
  addQuickButton("Isteklo / nema", { mode: "missing_expired" });
  addQuickButton("Istječe 30d", { mode: "expiring", days: 30 });
  addQuickButton("Istječe 60d", { mode: "expiring", days: 60 });
  addQuickButton("Istječe 90d", { mode: "expiring", days: 90 });
  addQuickButton("Predloži iz opisa", { mode: "recommended" });
  addQuickButton("Sve", { mode: "all" });
  addQuickButton("Očisti", { mode: "clear" });

  renderModeButtons();
  renderPreviewGroups();
  body.append(flow, modePanel, groupList);
  modal.append(head, body, actions);
  backdrop.append(modal);
  backdrop.addEventListener("click", (event) => {
    if (event.target === backdrop) {
      closePeopleTrainingBulkPreviewDialog(backdrop);
    }
  });
  const handleKeydown = (event) => {
    if (event.key === "Escape" && document.body.contains(backdrop)) {
      closePeopleTrainingBulkPreviewDialog(backdrop);
      document.removeEventListener("keydown", handleKeydown, true);
    }
  };
  document.addEventListener("keydown", handleKeydown, true);
  document.body.append(backdrop);
  document.body.classList.add("modal-open");
  requestAnimationFrame(() => {
    (openButton.disabled ? quickActions.querySelector("button") : openButton)?.focus({ preventScroll: true });
  });
}

function getPeopleTrainingRecordWorkOrderLocationId(record = {}) {
  const locationId = String(record.locationId || "").trim();
  if (!locationId) {
    return "";
  }
  const location = getPeopleTrainingLocation(locationId);
  return location && String(location.companyId) === String(record.companyId) ? String(location.id) : "";
}

function groupPeopleTrainingRecordsForWorkOrders(records = []) {
  const groups = new Map();

  records.forEach((record) => {
    const companyId = String(record.companyId || "").trim();
    if (!companyId) {
      return;
    }
    const locationId = getPeopleTrainingRecordWorkOrderLocationId(record);
    const key = `${companyId}::${locationId}`;
    if (!groups.has(key)) {
      groups.set(key, {
        companyId,
        locationId,
        records: [],
      });
    }
    groups.get(key).records.push(record);
  });

  return [...groups.values()];
}

function getPeopleTrainingUniqueServiceEntries(entries = []) {
  const unique = new Map();
  entries.forEach((entry) => {
    const key = String(entry.typeOption?.value || entry.typeOption?.serviceId || "").trim();
    if (key && !unique.has(key)) {
      unique.set(key, entry);
    }
  });
  return [...unique.values()];
}

function buildPeopleTrainingWorkOrderPayload(group = {}, selection = {}) {
  const records = Array.isArray(group.records) ? group.records : [];
  const entries = Array.isArray(group.entries) && group.entries.length
    ? group.entries
    : getPeopleTrainingBulkSelectedEntries(records, selection);
  const serviceEntries = getPeopleTrainingUniqueServiceEntries(entries);
  const serviceItems = serviceEntries
    .map((entry) => buildPeopleTrainingWorkOrderServiceItem(entry.typeOption, entry.item))
    .filter(Boolean);
  const company = getPeopleTrainingCompany(group.companyId);
  const location = group.locationId ? getPeopleTrainingLocation(group.locationId) : null;
  const openingExecutor = getUserDisplayLabel(state.user || {});
  const locationName = location?.name || company?.headquarters || "Sjedište";
  const peopleLines = records
    .map((record) => {
      const recordEntries = entries.filter((entry) => String(entry.record?.id) === String(record.id));
      const serviceCodes = recordEntries
        .map((entry) => entry.typeOption?.serviceCode || entry.typeOption?.shortLabel || entry.typeOption?.label || "")
        .filter(Boolean)
        .join(", ");
      return `- ${record.fullName || [record.firstName, record.lastName].filter(Boolean).join(" ") || "Osoba"}${record.oib ? `, OIB ${record.oib}` : ""}${serviceCodes ? `: ${serviceCodes}` : ""}`;
    })
    .join("\n");
  const serviceSummary = serviceItems
    .map((item) => item.serviceCode || item.name || "")
    .filter(Boolean)
    .join(", ");

  return {
    organizationId: state.activeOrganizationId,
    status: WORK_ORDER_STATUS_OPTIONS[0]?.value || "Otvoreni RN",
    priority: PRIORITY_OPTIONS[0]?.value || "Normal",
    openedDate: getTodayDateKey(),
    dueDate: resolveDefaultWorkOrderDueDate(getTodayDateKey()),
    executionDate: "",
    teamLabel: "Osposobljavanje ljudi",
    companyId: group.companyId || "",
    locationId: group.locationId || "",
    locationName,
    coordinates: location?.coordinates || "",
    region: location?.region || "",
    contactSlot: "",
    contactName: company?.representative || "",
    contactPhone: company?.contactPhone || "",
    contactEmail: company?.contactEmail || "",
    executors: openingExecutor ? [openingExecutor] : [],
    executor1: openingExecutor || "",
    executor2: "",
    measurementSheet: null,
    serviceItems,
    trainingContext: {
      name: "",
      role: "",
      phone: "",
      email: "",
    },
    serviceLine: serviceSummary || "Osposobljavanje ljudi",
    department: "",
    linkReference: "",
    weight: "",
    completedBy: "",
    invoiceDate: "",
    tagText: "Osposobljavanje",
    description: [
      `Masovno osposobljavanje: ${serviceSummary || "usluge"}`,
      peopleLines,
    ].filter(Boolean).join("\n"),
    invoiceNote: "",
  };
}

function isPeopleTrainingAssignmentForRecord(assignment = {}, record = {}, workOrder = {}) {
  if (String(assignment.workOrderId || "") !== String(workOrder.id || "")) {
    return false;
  }
  const recordOib = String(record.oib || "").trim();
  const assignmentOib = String(assignment.externalOib || "").trim();
  if (recordOib && assignmentOib && recordOib === assignmentOib) {
    return true;
  }
  const recordEmail = String(record.email || "").trim().toLowerCase();
  const assignmentEmail = String(assignment.externalEmail || assignment.email || "").trim().toLowerCase();
  if (recordEmail && assignmentEmail && recordEmail === assignmentEmail) {
    return true;
  }
  return String(assignment.externalFullName || assignment.userLabel || "").trim().toLowerCase()
    === getPeopleTrainingRecordDisplayName(record).toLowerCase();
}

function buildPeopleTrainingLearningAssignment(record = {}, workOrder = {}, typeOption = {}, test = {}, existingAssignment = null) {
  const company = getPeopleTrainingCompany(record.companyId);
  const timestamp = new Date().toISOString();
  const fullName = getPeopleTrainingRecordDisplayName(record);
  return {
    ...(existingAssignment ?? {}),
    id: String(existingAssignment?.id || crypto.randomUUID()),
    assigneeType: "external",
    userId: "",
    userLabel: fullName,
    email: String(record.email || "").trim(),
    externalFullName: fullName,
    externalEmail: String(record.email || "").trim(),
    externalPhone: String(record.phone || "").trim(),
    externalCompany: record.companyName || company?.name || "",
    externalOib: String(record.oib || "").trim(),
    accessToken: String(existingAssignment?.accessToken || crypto.randomUUID()),
    status: String(existingAssignment?.status || "pending"),
    assignedAt: String(existingAssignment?.assignedAt || timestamp),
    workOrderId: String(workOrder.id || "").trim(),
    workOrderNumber: String(workOrder.workOrderNumber || "").trim(),
    serviceId: String(typeOption.serviceId || "").trim(),
    serviceName: String(typeOption.label || typeOption.serviceName || typeOption.serviceCode || "").trim(),
    assignedByUserId: String(state.user?.id || "").trim(),
    assignedByLabel: String(state.user?.fullName || state.user?.email || "").trim(),
    ...buildLearningAssignmentQuestionSnapshot(test, existingAssignment, { workOrder, typeOption }),
  };
}

async function emailPeopleTrainingLearningAssignment(test = {}, assignment = {}, workOrder = {}, typeOption = {}) {
  const to = String(assignment.externalEmail || assignment.email || "").trim();
  if (!to) {
    peopleTrainingLastBulkOpenSummary.skippedEmails += 1;
    return false;
  }
  try {
    await apiRequest(`/learning-tests/${encodeURIComponent(test.id)}/assignments/${encodeURIComponent(assignment.id)}/email`, {
      method: "POST",
      body: {
        to,
        serviceName: typeOption.label || typeOption.serviceName || "",
        serviceCode: typeOption.serviceCode || typeOption.shortLabel || "",
        workOrderNumber: workOrder.workOrderNumber || "",
      },
    });
    peopleTrainingLastBulkOpenSummary.sentEmails += 1;
    return true;
  } catch (error) {
    console.warn("Slanje pristupa online ispitu nije uspjelo.", error);
    peopleTrainingLastBulkOpenSummary.failedEmails += 1;
    return false;
  }
}

async function assignPeopleTrainingLearningTestsForWorkOrder(records = [], typeOption = {}, workOrder = {}, options = {}) {
  const tests = getPeopleTrainingLinkedLearningTests(typeOption);
  if (!tests.length || !workOrder?.id) {
    return true;
  }
  const sendEmails = options.sendEmails !== false;

  for (const test of tests) {
    const assignmentItems = Array.isArray(test.assignmentItems) ? [...test.assignmentItems] : [];
    const nextAssignments = [];
    const assignmentEmails = [];

    records.forEach((record) => {
      const existing = assignmentItems.find((assignment) => isPeopleTrainingAssignmentForRecord(assignment, record, workOrder)) ?? null;
      const nextAssignment = buildPeopleTrainingLearningAssignment(record, workOrder, typeOption, test, existing);
      nextAssignments.push(nextAssignment);
      assignmentEmails.push(nextAssignment);
    });

    const remaining = assignmentItems.filter((assignment) => (
      !records.some((record) => isPeopleTrainingAssignmentForRecord(assignment, record, workOrder))
    ));

    const success = await runMutation(() => apiRequest(`/learning-tests/${encodeURIComponent(test.id)}`, {
      method: "PATCH",
      body: {
        assignmentItems: [...remaining, ...nextAssignments],
      },
    }), peopleTrainingFormFeedback);

    if (!success) {
      return false;
    }

    peopleTrainingLastBulkOpenSummary.assignedTests += nextAssignments.length;
    if (sendEmails) {
      for (const assignment of assignmentEmails) {
        await emailPeopleTrainingLearningAssignment(test, assignment, workOrder, typeOption);
      }
    }
  }

  return true;
}

async function linkPeopleTrainingRecordsToWorkOrder(records = [], typeOption = {}, workOrder = {}, options = {}) {
  const entries = getPeopleTrainingBulkSelectedEntries(records, typeOption);
  return linkPeopleTrainingEntriesToWorkOrder(entries, workOrder, options);
}

async function linkPeopleTrainingEntriesToWorkOrder(entries = [], workOrder = {}, options = {}) {
  if (!workOrder?.id || !entries.length) {
    return false;
  }

  const entriesByRecord = new Map();
  entries.forEach((entry) => {
    const key = getPeopleTrainingBulkRecordKey(entry.record);
    if (!entriesByRecord.has(key)) {
      entriesByRecord.set(key, []);
    }
    entriesByRecord.get(key).push(entry);
  });

  for (const recordEntries of entriesByRecord.values()) {
    const record = recordEntries[0]?.record ?? {};
    const currentRecord = state.peopleTrainingRecords.find((entry) => String(entry.id) === String(record.id)) ?? record;
    const entriesByType = new Map(recordEntries.map((entry) => [String(entry.typeOption?.value || ""), entry]));
    const nextItems = normalizePeopleTrainingItemsForUi(currentRecord.trainingItems).map((item) => {
      const entry = entriesByType.get(String(item.type || ""));
      if (!entry) {
        return item;
      }
      const typeOption = entry.typeOption ?? {};
      const linkedLearningTests = getPeopleTrainingLinkedLearningTests(typeOption);
      const alreadyPassed = isPeopleTrainingItemPassed(item);
      const rawExamMode = String(options.examMode || "").trim();
      const requestedExamMode = rawExamMode ? normalizeWorkOrderDocumentTrainingMode(rawExamMode) : "";
      const useOnlineExam = requestedExamMode
        ? workOrderDocumentTrainingModeUsesLearningTest(requestedExamMode)
        : linkedLearningTests.length > 0 && !alreadyPassed;
      const primaryLearningTest = useOnlineExam ? (linkedLearningTests[0] ?? null) : null;
      const assignOnlineTest = Boolean(primaryLearningTest && !alreadyPassed);
      return {
        ...item,
        label: typeOption.label || item.label || "",
        shortLabel: typeOption.shortLabel || item.shortLabel || "",
        serviceId: typeOption.serviceId || item.serviceId || "",
        serviceName: typeOption.serviceName || item.serviceName || "",
        serviceCode: typeOption.serviceCode || item.serviceCode || "",
        linkedTemplateIds: typeOption.linkedTemplateIds || item.linkedTemplateIds || [],
        linkedTemplateTitles: typeOption.linkedTemplateTitles || item.linkedTemplateTitles || [],
        linkedLearningTestIds: typeOption.linkedLearningTestIds || item.linkedLearningTestIds || [],
        linkedLearningTestTitles: typeOption.linkedLearningTestTitles || item.linkedLearningTestTitles || [],
        examMode: requestedExamMode || (useOnlineExam ? "online_test" : "live_paper"),
        workOrderId: String(workOrder.id || ""),
        workOrderNumber: String(workOrder.workOrderNumber || ""),
        learningTestId: assignOnlineTest ? String(primaryLearningTest.id || "") : item.learningTestId,
        learningTestTitle: assignOnlineTest ? String(primaryLearningTest.title || "") : item.learningTestTitle,
        certificateStatus: assignOnlineTest ? "assigned" : item.certificateStatus,
        status: "",
      };
    });

    const success = await runMutation(() => apiRequest(`/people-training-records/${encodeURIComponent(currentRecord.id)}`, {
      method: "PATCH",
      body: { trainingItems: nextItems },
    }), peopleTrainingFormFeedback);

    if (!success) {
      return false;
    }
  }

  return true;
}

async function assignPeopleTrainingLearningTestsForEntries(entries = [], workOrder = {}) {
  const entriesByType = new Map();
  entries.forEach((entry) => {
    const key = String(entry.typeOption?.value || "");
    if (!key) {
      return;
    }
    if (!entriesByType.has(key)) {
      entriesByType.set(key, {
        typeOption: entry.typeOption,
        records: [],
      });
    }
    const group = entriesByType.get(key);
    if (!group.records.some((record) => String(record.id) === String(entry.record?.id))) {
      group.records.push(entry.record);
    }
  });

  for (const group of entriesByType.values()) {
    const assigned = await assignPeopleTrainingLearningTestsForWorkOrder(group.records, group.typeOption, workOrder);
    if (!assigned) {
      return false;
    }
  }

  return true;
}

async function createPeopleTrainingWorkOrdersForRecords(records = [], selection = {}, options = {}) {
  if (!getCanEditOperationalData() || !getCanCreateWorkOrders()) {
    setPeopleTrainingFeedback("Nemaš pravo otvarati radne naloge.", "error");
    return [];
  }

  const entries = getPeopleTrainingBulkSelectedEntries(records, selection);
  if (entries.length === 0) {
    setPeopleTrainingFeedback("Odaberi barem jednu uslugu za masovno osposobljavanje.", "error");
    return [];
  }

  const groups = groupPeopleTrainingEntriesForWorkOrders(entries);
  if (groups.length === 0) {
    setPeopleTrainingFeedback("Za odabrane osobe nedostaje tvrtka pa ne mogu otvoriti RN.", "error");
    return [];
  }

  const createdWorkOrders = [];
  for (const group of groups) {
    const payload = buildPeopleTrainingWorkOrderPayload(group, selection);
    const previousIds = new Set(state.workOrders.map((item) => String(item.id)));
    let createdFromResponse = null;
    const success = await runMutation(() => apiRequest("/work-orders", {
      method: "POST",
      body: payload,
    }), peopleTrainingFormFeedback, {
      onSuccessPayload: (response) => {
        createdFromResponse = applyCreatedWorkOrderResponse(response, payload, { refresh: false });
      },
    });

    if (!success) {
      return createdWorkOrders;
    }

    const created = createdFromResponse || findCreatedWorkOrderMatch(previousIds, payload);
    if (created) {
      createdWorkOrders.push(created);
      const linked = await linkPeopleTrainingEntriesToWorkOrder(group.entries, created, options);
      if (!linked) {
        return createdWorkOrders;
      }
      const createdExamMode = String(options.examMode || "").trim()
        ? normalizeWorkOrderDocumentTrainingMode(options.examMode)
        : "online_test";
      if (workOrderDocumentTrainingModeUsesLearningTest(createdExamMode)) {
        const assigned = await assignPeopleTrainingLearningTestsForEntries(group.entries, created);
        if (!assigned) {
          return createdWorkOrders;
        }
      }
      queueGeneratedWorkOrderPdfSave(created.id);
    }
  }

  if (createdWorkOrders.length > 0) {
    void refreshSnapshot().catch(() => {});
  }

  return createdWorkOrders;
}

function closePeopleTrainingServiceLaunchDialog(dialog = null) {
  const target = dialog || document.querySelector(".people-training-service-launch-backdrop");
  if (target instanceof HTMLElement) {
    if (target.peopleTrainingLaunchKeydownHandler) {
      document.removeEventListener("keydown", target.peopleTrainingLaunchKeydownHandler, true);
    }
    target.remove();
  }
  document.body.classList.remove("modal-open");
}

async function startPeopleTrainingServiceMode(record = {}, item = {}, mode = "online_test", dialog = null) {
  if (!record?.id) {
    return;
  }

  const existingWorkOrder = item.workOrderId
    ? state.workOrders.find((workOrder) => String(workOrder.id) === String(item.workOrderId))
    : null;

  if (existingWorkOrder) {
    closePeopleTrainingServiceLaunchDialog(dialog);
    hydrateWorkOrderForm(existingWorkOrder);
    setPeopleTrainingFeedback(`Otvoren je RN ${existingWorkOrder.workOrderNumber || ""} za ovu uslugu.`.trim(), "success");
    return;
  }

  const typeOption = getPeopleTrainingTypeOption(item.type, record.trainingItems);
  const created = await createPeopleTrainingWorkOrdersForRecords([record], typeOption, { examMode: mode });
  closePeopleTrainingServiceLaunchDialog(dialog);
  renderPeopleTrainingModule();

  if (created[0]) {
    hydrateWorkOrderForm(created[0]);
    const modeLabel = getWorkOrderDocumentTrainingModeOption(mode).label;
    setPeopleTrainingFeedback(`Otvoren je RN ${created[0].workOrderNumber || ""} za ${modeLabel}: ${typeOption.label || "osposobljavanje"}.`.trim(), "success");
  }
}

function openPeopleTrainingForService(record = {}, item = {}) {
  if (!record?.id) {
    return;
  }

  const typeOption = getPeopleTrainingTypeOption(item.type, record.trainingItems);
  const existingWorkOrder = item.workOrderId
    ? state.workOrders.find((workOrder) => String(workOrder.id) === String(item.workOrderId))
    : null;

  closePeopleTrainingServiceLaunchDialog();
  const backdrop = document.createElement("div");
  backdrop.className = "people-training-service-launch-backdrop";
  backdrop.setAttribute("role", "presentation");

  const modal = document.createElement("section");
  modal.className = "people-training-service-launch-modal";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-label", "Odabir načina osposobljavanja");

  const head = document.createElement("div");
  head.className = "people-training-service-launch-head";
  const copy = document.createElement("div");
  const kicker = document.createElement("p");
  kicker.className = "section-kicker";
  kicker.textContent = "Osposobljavanje";
  const title = document.createElement("h4");
  title.textContent = typeOption.label || item.label || "Odaberi način";
  const subtitle = document.createElement("span");
  subtitle.textContent = [
    getPeopleTrainingRecordDisplayName(record),
    record.companyName || getPeopleTrainingCompany(record.companyId)?.name || "",
    record.locationName || getPeopleTrainingLocation(record.locationId)?.name || "Sjedište / sve lokacije",
  ].filter(Boolean).join(" · ");
  copy.append(kicker, title, subtitle);
  const closeButton = document.createElement("button");
  closeButton.type = "button";
  closeButton.className = "ghost-button";
  closeButton.textContent = "Zatvori";
  closeButton.addEventListener("click", () => closePeopleTrainingServiceLaunchDialog(backdrop));
  head.append(copy, closeButton);

  const choices = document.createElement("div");
  choices.className = "people-training-service-launch-choices";

  const createChoice = ({ mode, title: choiceTitle, text, icon }) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "people-training-service-launch-choice";
    const iconNode = document.createElement("span");
    iconNode.className = "people-training-service-launch-icon";
    iconNode.innerHTML = getWorkOrderIconMarkup(icon);
    const label = document.createElement("strong");
    label.textContent = choiceTitle;
    const helper = document.createElement("small");
    helper.textContent = text;
    button.append(iconNode, label, helper);
    button.addEventListener("click", () => {
      void startPeopleTrainingServiceMode(record, item, mode, backdrop);
    });
    return button;
  };

  choices.append(
    ...WORK_ORDER_DOCUMENT_TRAINING_MODE_OPTIONS.map((option) => createChoice({
      mode: option.value,
      title: option.label,
      text: option.helper,
      icon: option.iconName || "service",
    })),
  );

  if (existingWorkOrder) {
    const existing = document.createElement("button");
    existing.type = "button";
    existing.className = "ghost-button people-training-service-existing-button";
    existing.textContent = `Otvori postojeći RN ${existingWorkOrder.workOrderNumber || ""}`.trim();
    existing.addEventListener("click", () => {
      void startPeopleTrainingServiceMode(record, item, "online_test", backdrop);
    });
    choices.append(existing);
  }

  modal.append(head, choices);
  backdrop.append(modal);
  backdrop.addEventListener("click", (event) => {
    if (event.target === backdrop) {
      closePeopleTrainingServiceLaunchDialog(backdrop);
    }
  });
  const handleKeydown = (event) => {
    if (event.key === "Escape" && document.body.contains(backdrop)) {
      closePeopleTrainingServiceLaunchDialog(backdrop);
    }
  };
  backdrop.peopleTrainingLaunchKeydownHandler = handleKeydown;
  document.addEventListener("keydown", handleKeydown, true);
  document.body.append(backdrop);
  document.body.classList.add("modal-open");
  requestAnimationFrame(() => {
    choices.querySelector("button")?.focus({ preventScroll: true });
  });
}

function buildPeopleTrainingWorkOrderOptions(record = {}) {
  const normalizedCompanyId = String(record.companyId || "").trim();
  const options = (state.workOrders ?? [])
    .filter((workOrder) => !normalizedCompanyId || String(workOrder.companyId || "") === normalizedCompanyId)
    .slice()
    .sort((left, right) => {
      const leftValue = String(left.openedDate || left.createdAt || left.workOrderNumber || "");
      const rightValue = String(right.openedDate || right.createdAt || right.workOrderNumber || "");
      return rightValue.localeCompare(leftValue, "hr", { numeric: true });
    })
    .slice(0, 160)
    .map((workOrder) => ({
      value: String(workOrder.id || ""),
      label: [
        workOrder.workOrderNumber ? `RN ${workOrder.workOrderNumber}` : "RN bez broja",
        workOrder.openedDate ? formatCompactDate(workOrder.openedDate) : "",
        workOrder.locationName || "",
      ].filter(Boolean).join(" · "),
    }));
  return [{ value: "", label: "Odaberi RN" }, ...options];
}

function buildPeopleTrainingLearningTestOptions() {
  const options = sortLearningTests(state.learningTests ?? [])
    .map((test) => ({
      value: String(test.id || ""),
      label: [
        test.title || "Test bez naziva",
        test.status ? getLearningTestStatusLabel(test.status) : "",
      ].filter(Boolean).join(" · "),
    }));
  return [{ value: "", label: "Odaberi online test" }, ...options];
}

function getLearningTestStatusLabel(status = "") {
  return LEARNING_TEST_STATUS_OPTIONS.find((option) => option.value === status)?.label || status || "";
}

async function handlePeopleTrainingQuickExamSubmit(record = {}, form = null) {
  if (!record?.id || !(form instanceof HTMLFormElement)) {
    return;
  }
  const formData = new FormData(form);
  const trainingType = String(formData.get("trainingType") || "").trim();
  const rawExamMode = String(formData.get("examMode") || "live_paper").trim();
  const examMode = rawExamMode === "manual" ? "manual" : normalizeWorkOrderDocumentTrainingMode(rawExamMode);
  const passedOn = normalizePeopleTrainingDate(formData.get("passedOn"));
  const workOrderId = String(formData.get("workOrderId") || "").trim();
  const learningTestId = String(formData.get("learningTestId") || "").trim();
  const typeOption = getPeopleTrainingTypeOption(trainingType, record.trainingItems ?? []);
  const certificateNumber = String(formData.get("certificateNumber") || "").trim()
    || generatePeopleTrainingCertificateNumber(record, typeOption, passedOn);

  if (!trainingType || !passedOn) {
    setPeopleTrainingFeedback("Odaberi vrstu ispita i datum polaganja.", "error");
    return;
  }

  const selectedWorkOrder = (state.workOrders ?? []).find((item) => String(item.id) === workOrderId) ?? null;
  const selectedTest = (state.learningTests ?? []).find((item) => String(item.id) === learningTestId) ?? null;
  const nextItems = normalizePeopleTrainingItemsForUi(record.trainingItems).map((item) => {
    if (item.type !== trainingType) {
      return item;
    }
    return {
      ...item,
      label: typeOption.label || item.label || "",
      shortLabel: typeOption.shortLabel || item.shortLabel || "",
      serviceId: typeOption.serviceId || item.serviceId || "",
      serviceName: typeOption.serviceName || item.serviceName || "",
      serviceCode: typeOption.serviceCode || item.serviceCode || "",
      linkedTemplateIds: typeOption.linkedTemplateIds || item.linkedTemplateIds || [],
      linkedTemplateTitles: typeOption.linkedTemplateTitles || item.linkedTemplateTitles || [],
      linkedLearningTestIds: typeOption.linkedLearningTestIds || item.linkedLearningTestIds || [],
      linkedLearningTestTitles: typeOption.linkedLearningTestTitles || item.linkedLearningTestTitles || [],
      issuedOn: passedOn,
      passedOn,
      certificateNumber,
      provider: item.provider || selectedTest?.title || "SafeNexus",
      examMode,
      workOrderId: ["live_paper", "live_application", "online_teams"].includes(examMode) ? (selectedWorkOrder?.id || workOrderId) : "",
      workOrderNumber: ["live_paper", "live_application", "online_teams"].includes(examMode) ? (selectedWorkOrder?.workOrderNumber || "") : "",
      learningTestId: workOrderDocumentTrainingModeUsesLearningTest(examMode) ? (selectedTest?.id || learningTestId) : "",
      learningTestTitle: workOrderDocumentTrainingModeUsesLearningTest(examMode) ? (selectedTest?.title || "") : "",
      certificateStatus: "ready",
      status: "",
    };
  });

  const success = await runMutation(() => apiRequest(`/people-training-records/${encodeURIComponent(record.id)}`, {
    method: "PATCH",
    body: { trainingItems: nextItems },
  }), peopleTrainingFormFeedback);

  if (success) {
    setPeopleTrainingFeedback("Ispit je upisan i uvjerenje je označeno kao spremno.", "success");
    renderPeopleTrainingModule();
    const updated = state.peopleTrainingRecords.find((item) => String(item.id) === String(record.id));
    if (updated && String(updated.id) === String(state.activePeopleTrainingRecordId)) {
      populatePeopleTrainingForm(updated);
    }
  }
}

function createPeopleTrainingQuickExamForm(record = {}) {
  const form = document.createElement("form");
  form.className = "people-training-inline-exam-form";
  form.addEventListener("click", (event) => event.stopPropagation());
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    event.stopPropagation();
    void handlePeopleTrainingQuickExamSubmit(record, form);
  });

  const typeSelect = document.createElement("select");
  typeSelect.name = "trainingType";
  const trainingTypeOptions = getPeopleTrainingTypeOptions(record.trainingItems);
  replaceSelectOptions(
    typeSelect,
    trainingTypeOptions.map((option) => ({ value: option.value, label: option.serviceCode ? `${option.label} (${option.serviceCode})` : option.label })),
    trainingTypeOptions[0]?.value || "",
  );

  const modeSelect = document.createElement("select");
  modeSelect.name = "examMode";
  replaceSelectOptions(modeSelect, [
    { value: "online_teams", label: "Online - Teams" },
    { value: "online_test", label: "Online - Test" },
    { value: "live_paper", label: "Live - Paper" },
    { value: "live_application", label: "Live - Application" },
    { value: "manual", label: "Manual" },
  ], "live_paper");

  const workOrderSelect = document.createElement("select");
  workOrderSelect.name = "workOrderId";
  replaceSelectOptions(workOrderSelect, buildPeopleTrainingWorkOrderOptions(record), "");

  const testSelect = document.createElement("select");
  testSelect.name = "learningTestId";
  replaceSelectOptions(testSelect, buildPeopleTrainingLearningTestOptions(), "");
  testSelect.hidden = true;

  const passedInput = document.createElement("input");
  passedInput.name = "passedOn";
  passedInput.type = "text";
  passedInput.inputMode = "numeric";
  passedInput.placeholder = "dd.mm.yyyy";
  passedInput.value = formatDateInputDisplayValue(getTodayDateKey());
  passedInput.title = "Datum polaganja";
  passedInput.addEventListener("blur", () => {
    passedInput.value = formatDateInputDisplayValue(normalizePeopleTrainingDate(passedInput.value));
  });

  const certificateInput = document.createElement("input");
  certificateInput.name = "certificateNumber";
  certificateInput.type = "text";
  certificateInput.placeholder = "Auto broj ako prazno";
  certificateInput.title = "Broj uvjerenja";

  const saveButton = document.createElement("button");
  saveButton.type = "submit";
  saveButton.className = "primary-button people-training-inline-save";
  saveButton.textContent = "Upiši";

  const syncSourceControls = () => {
    const mode = modeSelect.value === "manual" ? "manual" : normalizeWorkOrderDocumentTrainingMode(modeSelect.value);
    workOrderSelect.hidden = !["live_paper", "live_application", "online_teams"].includes(mode);
    testSelect.hidden = !workOrderDocumentTrainingModeUsesLearningTest(mode);
  };
  modeSelect.addEventListener("change", syncSourceControls);
  syncSourceControls();

  form.append(typeSelect, modeSelect, workOrderSelect, testSelect, passedInput, certificateInput, saveButton);
  return form;
}

function hasPeopleTrainingDraggedFiles(dataTransfer = null) {
  if (!dataTransfer) {
    return false;
  }

  if ((dataTransfer.files?.length ?? 0) > 0) {
    return true;
  }

  if (Array.from(dataTransfer.items ?? []).some((item) => item.kind === "file")) {
    return true;
  }

  return Array.from(dataTransfer.types ?? []).some((type) => String(type).toLowerCase() === "files");
}

function getPeopleTrainingDroppedFiles(dataTransfer = null) {
  return Array.from(dataTransfer?.files ?? []).filter(Boolean);
}

function getPeopleTrainingDropRowFromEvent(event) {
  if (!(event?.target instanceof Element)) {
    return null;
  }

  const row = event.target.closest("[data-people-training-record-id]");
  if (!row || !peopleTrainingList?.contains(row)) {
    return null;
  }

  return row;
}

function getPeopleTrainingDropRecordFromRow(row = null) {
  const recordId = String(row?.dataset?.peopleTrainingRecordId || "").trim();
  if (!recordId) {
    return null;
  }

  return state.peopleTrainingRecords.find((item) => String(item.id) === recordId) ?? null;
}

function clearPeopleTrainingDropTargets() {
  peopleTrainingList
    ?.querySelectorAll(".people-training-person-row.is-drag-over")
    .forEach((row) => row.classList.remove("is-drag-over"));
}

function bindPeopleTrainingListDocumentDrop() {
  if (!peopleTrainingList) {
    return;
  }

  const activateDropTarget = (event) => {
    if (!hasPeopleTrainingDraggedFiles(event.dataTransfer)) {
      return null;
    }

    const row = getPeopleTrainingDropRowFromEvent(event);
    if (!row) {
      return null;
    }

    event.preventDefault();
    event.stopPropagation();
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = "copy";
    }
    clearPeopleTrainingDropTargets();
    row.classList.add("is-drag-over");
    return row;
  };

  peopleTrainingList.addEventListener("dragenter", activateDropTarget, true);
  peopleTrainingList.addEventListener("dragover", activateDropTarget, true);
  peopleTrainingList.addEventListener("dragleave", (event) => {
    const row = getPeopleTrainingDropRowFromEvent(event);
    if (!row) {
      return;
    }
    if (event.relatedTarget instanceof Node && row.contains(event.relatedTarget)) {
      return;
    }
    row.classList.remove("is-drag-over");
  }, true);
  peopleTrainingList.addEventListener("drop", (event) => {
    const row = activateDropTarget(event);
    const record = getPeopleTrainingDropRecordFromRow(row);
    const files = getPeopleTrainingDroppedFiles(event.dataTransfer);
    clearPeopleTrainingDropTargets();
    if (!record?.id || files.length === 0) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    void openPeopleTrainingAttachmentDialog(record, files);
  }, true);
}

function getPeopleTrainingSelectedRecordIds() {
  if (!(state.peopleTrainingSelectedRecordIds instanceof Set)) {
    state.peopleTrainingSelectedRecordIds = new Set();
  }
  return state.peopleTrainingSelectedRecordIds;
}

function isPeopleTrainingRecordSelected(recordId = "") {
  return getPeopleTrainingSelectedRecordIds().has(String(recordId || ""));
}

function getSelectedPeopleTrainingRecords() {
  const selectedIds = getPeopleTrainingSelectedRecordIds();
  return sortPersonTrainingRecords(
    (state.peopleTrainingRecords ?? []).filter((record) => selectedIds.has(String(record.id))),
  );
}

function setPeopleTrainingRecordSelection(recordId = "", selected = false) {
  const normalizedId = String(recordId || "").trim();
  if (!normalizedId) {
    return;
  }
  const selectedIds = getPeopleTrainingSelectedRecordIds();
  if (selected) {
    selectedIds.add(normalizedId);
  } else {
    selectedIds.delete(normalizedId);
  }
  syncPeopleTrainingBulkActions(getPeopleTrainingFilteredRecords());
}

function clearPeopleTrainingSelection() {
  getPeopleTrainingSelectedRecordIds().clear();
  renderPeopleTrainingList();
}

function selectVisiblePeopleTrainingRecords(records = getPeopleTrainingFilteredRecords()) {
  const selectedIds = getPeopleTrainingSelectedRecordIds();
  records.forEach((record) => {
    if (record?.id) {
      selectedIds.add(String(record.id));
    }
  });
  renderPeopleTrainingList();
}

function syncPeopleTrainingBulkActions(records = getPeopleTrainingFilteredRecords()) {
  const selectedCount = getSelectedPeopleTrainingRecords().length;
  const selectedTypeOption = getPeopleTrainingSelectedTypeOption();
  const canBulk = getCanManagePeople();
  const canOpen = canBulk && selectedCount > 0;

  if (peopleTrainingBulkOpenButton) {
    peopleTrainingBulkOpenButton.hidden = !canBulk;
    peopleTrainingBulkOpenButton.disabled = !canOpen;
    peopleTrainingBulkOpenButton.textContent = selectedCount > 0
      ? `Masovno osposobljavanje (${selectedCount})`
      : "Masovno osposobljavanje";
    peopleTrainingBulkOpenButton.title = selectedCount > 0 && !selectedTypeOption
      ? "Otvori pregled i odaberi uslugu za RN."
      : "Otvori RN po svakoj tvrtki i lokaciji za odabrane osobe.";
  }

  if (peopleTrainingClearSelectionButton) {
    peopleTrainingClearSelectionButton.hidden = !canBulk || selectedCount === 0;
  }

  if (peopleTrainingSelectVisibleButton) {
    peopleTrainingSelectVisibleButton.hidden = !canBulk;
    peopleTrainingSelectVisibleButton.disabled = !canBulk || records.length === 0;
    peopleTrainingSelectVisibleButton.textContent = records.length > 0
      ? `Odaberi prikazane (${records.length})`
      : "Odaberi prikazane";
  }
}

async function executeBulkPeopleTrainingWorkOrders(records = [], selection = {}, options = {}) {
  peopleTrainingLastBulkOpenSummary = {
    assignedTests: 0,
    sentEmails: 0,
    skippedEmails: 0,
    failedEmails: 0,
  };

  if (peopleTrainingBulkOpenButton) {
    peopleTrainingBulkOpenButton.disabled = true;
  }

  const selectedEntries = getPeopleTrainingBulkSelectedEntries(records, selection);
  const created = await createPeopleTrainingWorkOrdersForRecords(records, selection, options);
  if (created.length > 0) {
    clearPeopleTrainingSelection();
    renderPeopleTrainingModule();
    const emailParts = [];
    if (peopleTrainingLastBulkOpenSummary.assignedTests > 0) {
      emailParts.push(`${peopleTrainingLastBulkOpenSummary.assignedTests} dodijeljenih ispita`);
    }
    if (peopleTrainingLastBulkOpenSummary.sentEmails > 0) {
      emailParts.push(`${peopleTrainingLastBulkOpenSummary.sentEmails} poslanih emailova`);
    }
    if (peopleTrainingLastBulkOpenSummary.skippedEmails > 0) {
      emailParts.push(`${peopleTrainingLastBulkOpenSummary.skippedEmails} bez emaila`);
    }
    if (peopleTrainingLastBulkOpenSummary.failedEmails > 0) {
      emailParts.push(`${peopleTrainingLastBulkOpenSummary.failedEmails} emailova nije poslano`);
    }
    setPeopleTrainingFeedback(
      [
        `Otvoreno je ${created.length} RN za ${records.length} osoba i ${selectedEntries.length} odabranih polaganja, po tvrtki i lokaciji.`,
        emailParts.join(" · "),
      ].filter(Boolean).join(" "),
      peopleTrainingLastBulkOpenSummary.failedEmails > 0 ? "error" : "success",
    );
    hydrateWorkOrderForm(created[0]);
  } else {
    syncPeopleTrainingBulkActions(getPeopleTrainingFilteredRecords());
  }
}

async function openBulkPeopleTrainingWorkOrders() {
  const records = getSelectedPeopleTrainingRecords();
  const typeOption = getPeopleTrainingSelectedTypeOption();

  if (records.length === 0) {
    setPeopleTrainingFeedback("Odaberi barem jednu osobu za masovno osposobljavanje.", "error");
    return;
  }

  openPeopleTrainingBulkPreviewDialog(records, typeOption);
}

function getPeopleTrainingAttachmentShortLabel(attachment = {}) {
  const fileName = String(attachment.fileName || "").trim().toLowerCase();
  const fileType = String(attachment.fileType || "").trim().toLowerCase();
  if (fileType.includes("pdf") || fileName.endsWith(".pdf")) {
    return "PDF";
  }
  if (fileType.includes("word") || fileName.endsWith(".doc") || fileName.endsWith(".docx")) {
    return "DOC";
  }
  if (fileType.includes("sheet") || fileName.endsWith(".xls") || fileName.endsWith(".xlsx") || fileName.endsWith(".csv")) {
    return "XLS";
  }
  if (fileType.includes("image") || /\.(png|jpe?g|webp|gif)$/i.test(fileName)) {
    return "IMG";
  }
  return "DOK";
}

function createPeopleTrainingAttachmentQuickActions(record = {}) {
  const attachments = Array.isArray(record.attachments)
    ? record.attachments.filter((attachment) => String(attachment.storageUrl || attachment.dataUrl || "").trim())
    : [];

  const actions = document.createElement("div");
  actions.className = "people-training-attachment-actions";
  actions.dataset.preventRowOpen = "true";

  const button = document.createElement("button");
  button.type = "button";
  button.className = "people-training-attachment-button is-menu";
  button.title = attachments.length > 0
    ? `Otvori izbornik priloga (${attachments.length})`
    : "Nema priloga";
  button.setAttribute("aria-label", button.title);
  button.disabled = attachments.length === 0;
  const icon = document.createElement("span");
  icon.innerHTML = getWorkOrderIconMarkup("folder");
  const count = document.createElement("strong");
  count.textContent = String(attachments.length);
  button.append(icon, count);
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openPeopleTrainingAttachmentMenu(record, button);
  });
  actions.append(button);

  return actions;
}

function createPeopleTrainingRecordCard(record = {}) {
  const trainingItems = normalizePeopleTrainingItemsForUi(record.trainingItems);
  const overallStatus = getPeopleTrainingOverallStatusFromItems(trainingItems);
  const shell = document.createElement("div");
  shell.className = "people-training-row-shell";

  const card = document.createElement("article");
  card.className = `people-training-person-row ${getPeopleTrainingStatusClass(overallStatus)}`;
  card.tabIndex = 0;
  card.dataset.peopleTrainingRecordId = String(record.id || "");

  const top = document.createElement("div");
  top.className = "people-training-person-top";

  const selection = document.createElement("label");
  selection.className = "people-training-row-select";
  selection.dataset.preventRowOpen = "true";
  selection.title = "Odaberi za masovno osposobljavanje";
  const selectionInput = document.createElement("input");
  selectionInput.type = "checkbox";
  selectionInput.checked = isPeopleTrainingRecordSelected(record.id);
  selectionInput.setAttribute("aria-label", `Odaberi ${record.fullName || "osobu"}`);
  selection.hidden = !getCanManagePeople();
  selectionInput.disabled = !getCanManagePeople();
  const selectionVisual = document.createElement("span");
  selectionVisual.setAttribute("aria-hidden", "true");
  selection.append(selectionInput, selectionVisual);
  selection.addEventListener("click", (event) => event.stopPropagation());
  selectionInput.addEventListener("change", (event) => {
    event.stopPropagation();
    setPeopleTrainingRecordSelection(record.id, selectionInput.checked);
    card.classList.toggle("is-selected", selectionInput.checked);
    shell.classList.toggle("is-selected", selectionInput.checked);
  });

  const main = document.createElement("div");
  main.className = "people-training-person-main";
  const name = document.createElement("strong");
  name.textContent = record.fullName || [record.firstName, record.lastName].filter(Boolean).join(" ") || "Osoba bez imena";
  const meta = document.createElement("span");
  meta.textContent = [
    record.oib ? `OIB ${record.oib}` : "",
    record.jobTitle,
  ].filter(Boolean).join(" · ") || "Bez dodatnih podataka";
  main.append(name, meta);

  const location = document.createElement("div");
  location.className = "people-training-person-location";
  const companyName = document.createElement("strong");
  companyName.textContent = record.companyName || getPeopleTrainingCompany(record.companyId)?.name || "Tvrtka";
  const locationName = document.createElement("span");
  locationName.textContent = record.locationName || getPeopleTrainingLocation(record.locationId)?.name || "Sve lokacije / nije vezano";
  location.append(companyName, locationName);

  const identity = document.createElement("div");
  identity.className = "people-training-person-identity";
  identity.append(main, location);

  const overview = document.createElement("div");
  overview.className = "people-training-person-overview";
  const overallPill = document.createElement("span");
  overallPill.className = `people-training-status-chip ${getPeopleTrainingStatusClass(overallStatus)}`;
  overallPill.textContent = getPeopleTrainingStatusLabel(overallStatus);
  overview.append(overallPill);
  const attachmentActions = createPeopleTrainingAttachmentQuickActions(record);
  if (attachmentActions) {
    overview.append(attachmentActions);
  }
  top.append(identity, overview);

  const statuses = document.createElement("div");
  statuses.className = "people-training-person-statuses";
  statuses.replaceChildren(...trainingItems.map((item) => createPeopleTrainingCertificatePill(record, item)));
  card.classList.toggle("is-selected", isPeopleTrainingRecordSelected(record.id));
  shell.classList.toggle("is-selected", isPeopleTrainingRecordSelected(record.id));

  const footer = document.createElement("div");
  footer.className = "people-training-person-footer";
  footer.hidden = trainingItems.length === 0;
  footer.append(statuses);

  const openRecord = (event) => {
    if (event?.target instanceof Element && event.target.closest("button,input,select,textarea,a,form")) {
      return;
    }
    openPeopleTrainingRecordEditor(record);
  };
  card.addEventListener("click", openRecord);
  card.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }
    event.preventDefault();
    openRecord(event);
  });
  card.addEventListener("dragenter", (event) => {
    if (!hasPeopleTrainingDraggedFiles(event.dataTransfer)) {
      return;
    }
    event.preventDefault();
    card.classList.add("is-drag-over");
  });
  card.addEventListener("dragover", (event) => {
    if (!hasPeopleTrainingDraggedFiles(event.dataTransfer)) {
      return;
    }
    event.preventDefault();
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = "copy";
    }
    card.classList.add("is-drag-over");
  });
  card.addEventListener("dragleave", (event) => {
    if (event.relatedTarget instanceof Node && card.contains(event.relatedTarget)) {
      return;
    }
    card.classList.remove("is-drag-over");
  });
  card.addEventListener("drop", (event) => {
    const files = getPeopleTrainingDroppedFiles(event.dataTransfer);
    if (files.length === 0) {
      return;
    }
    event.preventDefault();
    card.classList.remove("is-drag-over");
    void openPeopleTrainingAttachmentDialog(record, files);
  });

  card.append(top, footer);
  shell.append(selection, card);
  return shell;
}

let peopleTrainingListRenderFrame = 0;
let peopleTrainingExamRenderFrame = 0;

function schedulePeopleTrainingListRender() {
  if (peopleTrainingListRenderFrame) {
    cancelAnimationFrame(peopleTrainingListRenderFrame);
  }
  peopleTrainingListRenderFrame = requestAnimationFrame(() => {
    peopleTrainingListRenderFrame = 0;
    renderPeopleTrainingList();
  });
}

function schedulePeopleTrainingExamRender() {
  if (peopleTrainingExamRenderFrame) {
    cancelAnimationFrame(peopleTrainingExamRenderFrame);
  }
  peopleTrainingExamRenderFrame = requestAnimationFrame(() => {
    peopleTrainingExamRenderFrame = 0;
    renderPeopleTrainingExamOverview();
  });
}

function renderPeopleTrainingList() {
  if (!peopleTrainingList) {
    return;
  }

  const records = getPeopleTrainingFilteredRecords();
  if (peopleTrainingListCount) {
    peopleTrainingListCount.textContent = `${records.length} zapisa`;
  }
  if (peopleTrainingEmpty) {
    peopleTrainingEmpty.hidden = records.length > 0;
  }

  peopleTrainingList.replaceChildren(...records.map(createPeopleTrainingRecordCard));
  syncPeopleTrainingBulkActions(records);
}

function syncPeopleTrainingActionAccess() {
  const canEditPeopleTraining = getCanEditPeopleTrainingData();
  const canManageTemplates = getCanManagePeople();
  [
    peopleTrainingDownloadTemplateButton,
    peopleTrainingImportButton,
    peopleTrainingNewButton,
  ].forEach((button) => {
    if (!button) {
      return;
    }
    button.hidden = !canEditPeopleTraining;
    button.disabled = !canEditPeopleTraining;
  });
  if (peopleTrainingOpenTemplateButton) {
    peopleTrainingOpenTemplateButton.hidden = !canManageTemplates;
    peopleTrainingOpenTemplateButton.disabled = !canManageTemplates;
  }
  if (peopleTrainingSaveButton) {
    peopleTrainingSaveButton.hidden = !canEditPeopleTraining;
    peopleTrainingSaveButton.disabled = !canEditPeopleTraining;
  }
  if (peopleTrainingResetButton) {
    peopleTrainingResetButton.hidden = !canEditPeopleTraining;
    peopleTrainingResetButton.disabled = !canEditPeopleTraining;
  }
  if (peopleTrainingDeleteButton) {
    peopleTrainingDeleteButton.hidden = !getCanManagePeople() || !peopleTrainingIdInput?.value;
    peopleTrainingDeleteButton.disabled = !getCanManagePeople();
  }
}

function renderPeopleTrainingModule() {
  if (!peopleTrainingPanel) {
    return;
  }

  closePeopleTrainingItemMenu();
  syncPeopleTrainingActionAccess();
  if (peopleTrainingSearchInput && peopleTrainingSearchInput.value !== state.peopleTrainingFilters.query) {
    peopleTrainingSearchInput.value = state.peopleTrainingFilters.query || "";
  }
  if (peopleTrainingExamSearchInput && peopleTrainingExamSearchInput.value !== (state.peopleTrainingExamQuery || "")) {
    peopleTrainingExamSearchInput.value = state.peopleTrainingExamQuery || "";
  }
  syncPeopleTrainingSelectOptions();
  renderPeopleTrainingStats();
  const active = state.peopleTrainingRecords.find((item) => String(item.id) === String(state.activePeopleTrainingRecordId));
  if (!peopleTrainingFormTrainingGrid?.children.length) {
    renderPeopleTrainingGrid(active || null);
  }
  renderPeopleTrainingDossier(active || null);
  renderPeopleTrainingExamOverview();
  renderPeopleTrainingList();
}

const PEOPLE_TRAINING_IMPORT_MODE_OPTIONS = Object.freeze([
  {
    value: "new",
    title: "Novi zaposlenici",
    eyebrow: "Import za nove",
    description: "Dodaje samo osobe koje još ne postoje u evidenciji.",
  },
  {
    value: "departures",
    title: "Odlasci",
    eyebrow: "Import za odlaske",
    description: "Pronađene osobe označava kao odlazak/neaktivne.",
  },
  {
    value: "changes",
    title: "Promjene",
    eyebrow: "Import za promjene",
    description: "Ažurira postojeće osobe i prije potvrde pokaže svaku razliku.",
  },
]);

const PEOPLE_TRAINING_IMPORT_ACTION_LABELS = Object.freeze({
  create: "Novi zaposlenik",
  update: "Promjena podataka",
  departure: "Odlazak",
  skipped: "Preskočeno",
  unchanged: "Bez promjene",
});

const peopleTrainingImportDraft = {
  open: false,
  mode: "new",
  fileName: "",
  dataUrl: "",
  preview: null,
  rowDecisions: {},
  busy: false,
  applying: false,
  error: "",
};

let peopleTrainingImportKeydownHandler = null;
let peopleTrainingImportModeMenuCloseHandler = null;

function getPeopleTrainingImportModeOption(mode = peopleTrainingImportDraft.mode) {
  return PEOPLE_TRAINING_IMPORT_MODE_OPTIONS.find((option) => option.value === mode)
    ?? PEOPLE_TRAINING_IMPORT_MODE_OPTIONS[0];
}

function resetPeopleTrainingImportDraft({ keepMode = false } = {}) {
  const nextMode = keepMode ? peopleTrainingImportDraft.mode : "new";
  peopleTrainingImportDraft.open = false;
  peopleTrainingImportDraft.mode = nextMode;
  peopleTrainingImportDraft.fileName = "";
  peopleTrainingImportDraft.dataUrl = "";
  peopleTrainingImportDraft.preview = null;
  peopleTrainingImportDraft.rowDecisions = {};
  peopleTrainingImportDraft.busy = false;
  peopleTrainingImportDraft.applying = false;
  peopleTrainingImportDraft.error = "";
}

function getPeopleTrainingImportRequestBody({ previewOnly = false } = {}) {
  const selectedCompanyId = state.peopleTrainingFilters.companyId !== "all" ? state.peopleTrainingFilters.companyId : "";
  const selectedLocationId = state.peopleTrainingFilters.locationId !== "all" ? state.peopleTrainingFilters.locationId : "";
  return {
    fileName: peopleTrainingImportDraft.fileName,
    dataUrl: peopleTrainingImportDraft.dataUrl,
    companyId: selectedCompanyId,
    locationId: selectedLocationId,
    importMode: peopleTrainingImportDraft.mode,
    rowDecisions: peopleTrainingImportDraft.rowDecisions,
    previewOnly,
  };
}

function closePeopleTrainingImportDialog({ reset = true } = {}) {
  document.querySelector(".people-training-import-backdrop")?.remove();
  if (peopleTrainingImportKeydownHandler) {
    document.removeEventListener("keydown", peopleTrainingImportKeydownHandler, true);
    peopleTrainingImportKeydownHandler = null;
  }
  document.body.classList.remove("modal-open");
  if (reset) {
    resetPeopleTrainingImportDraft({ keepMode: true });
  } else {
    peopleTrainingImportDraft.open = false;
  }
}

function openPeopleTrainingImportDialog() {
  resetPeopleTrainingImportDraft({ keepMode: true });
  peopleTrainingImportDraft.open = true;
  renderPeopleTrainingImportDialog();
}

function closePeopleTrainingImportModeMenu() {
  document.querySelector(".people-training-import-mode-menu")?.remove();
  if (peopleTrainingImportModeMenuCloseHandler) {
    document.removeEventListener("pointerdown", peopleTrainingImportModeMenuCloseHandler, true);
    peopleTrainingImportModeMenuCloseHandler = null;
  }
}

function openPeopleTrainingImportModeMenu(anchor) {
  closePeopleTrainingImportModeMenu();
  if (!(anchor instanceof HTMLElement)) {
    return;
  }

  const menu = document.createElement("div");
  menu.className = "people-training-import-mode-menu";
  menu.setAttribute("role", "menu");
  const anchorRect = anchor.getBoundingClientRect();
  menu.style.setProperty("--menu-top", `${Math.round(anchorRect.bottom + 8)}px`);
  menu.style.setProperty("--menu-right", `${Math.max(12, Math.round(window.innerWidth - anchorRect.right))}px`);

  PEOPLE_TRAINING_IMPORT_MODE_OPTIONS.forEach((option) => {
    const item = document.createElement("button");
    item.type = "button";
    item.className = "people-training-import-mode-menu-item";
    item.setAttribute("role", "menuitem");
    const title = document.createElement("strong");
    title.textContent = option.title;
    const description = document.createElement("span");
    description.textContent = option.description;
    item.append(title, description);
    item.addEventListener("click", () => {
      peopleTrainingImportDraft.mode = option.value;
      peopleTrainingImportDraft.fileName = "";
      peopleTrainingImportDraft.dataUrl = "";
      peopleTrainingImportDraft.preview = null;
      peopleTrainingImportDraft.rowDecisions = {};
      peopleTrainingImportDraft.error = "";
      closePeopleTrainingImportModeMenu();
      if (peopleTrainingImportInput) {
        peopleTrainingImportInput.value = "";
        peopleTrainingImportInput.click();
      }
    });
    menu.append(item);
  });

  document.body.append(menu);
  requestAnimationFrame(() => {
    peopleTrainingImportModeMenuCloseHandler = (event) => {
      if (!menu.contains(event.target) && event.target !== anchor) {
        closePeopleTrainingImportModeMenu();
      }
    };
    document.addEventListener("pointerdown", peopleTrainingImportModeMenuCloseHandler, true);
  });
}

function createPeopleTrainingImportModeButton(option = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "people-training-import-mode";
  button.classList.toggle("is-active", option.value === peopleTrainingImportDraft.mode);
  button.dataset.peopleTrainingImportMode = option.value;
  const eyebrow = document.createElement("span");
  eyebrow.textContent = option.eyebrow;
  const title = document.createElement("strong");
  title.textContent = option.title;
  const description = document.createElement("small");
  description.textContent = option.description;
  button.append(eyebrow, title, description);
  button.addEventListener("click", () => {
    peopleTrainingImportDraft.mode = option.value;
    peopleTrainingImportDraft.preview = null;
    peopleTrainingImportDraft.rowDecisions = {};
    peopleTrainingImportDraft.error = "";
    renderPeopleTrainingImportDialog();
  });
  return button;
}

function createPeopleTrainingImportStat(label = "", value = 0, className = "") {
  const stat = document.createElement("article");
  stat.className = `people-training-import-stat ${className}`.trim();
  const valueNode = document.createElement("strong");
  valueNode.textContent = String(value ?? 0);
  const labelNode = document.createElement("span");
  labelNode.textContent = label;
  stat.append(valueNode, labelNode);
  return stat;
}

function createPeopleTrainingImportChangeChip(change = {}) {
  const chip = document.createElement("span");
  chip.className = "people-training-import-change";
  const label = document.createElement("strong");
  label.className = "people-training-import-change-label";
  label.textContent = change.label || "Polje";
  const before = String(change.before || "prazno");
  const after = String(change.after || "prazno");
  const flow = document.createElement("span");
  flow.className = "people-training-import-change-flow";
  const beforeNode = document.createElement("span");
  beforeNode.className = "people-training-import-change-value is-before";
  beforeNode.textContent = before;
  beforeNode.title = before;
  const arrow = document.createElement("span");
  arrow.className = "people-training-import-change-arrow";
  arrow.textContent = "→";
  const afterNode = document.createElement("span");
  afterNode.className = "people-training-import-change-value is-after";
  afterNode.textContent = after;
  afterNode.title = after;
  flow.append(beforeNode, arrow, afterNode);
  chip.append(label, flow);
  return chip;
}

function getPeopleTrainingImportActionLabel(action = "") {
  return PEOPLE_TRAINING_IMPORT_ACTION_LABELS[action] || action || "Status";
}

function recalculatePeopleTrainingImportPreviewTotals(preview = {}) {
  const totals = {
    total: preview.rows?.length ?? 0,
    create: 0,
    update: 0,
    departure: 0,
    skipped: 0,
    unchanged: 0,
    applicable: 0,
  };
  (preview.rows ?? []).forEach((row) => {
    if (row.action === "create") totals.create += 1;
    if (row.action === "update") totals.update += 1;
    if (row.action === "departure") totals.departure += 1;
    if (row.action === "skipped") totals.skipped += 1;
    if (row.action === "unchanged") totals.unchanged += 1;
    if (row.canApply) totals.applicable += 1;
  });
  preview.totals = totals;
}

function setPeopleTrainingImportRowDecision(rowIndex, decision) {
  const preview = peopleTrainingImportDraft.preview;
  const normalizedIndex = String(rowIndex || "");
  const row = (preview?.rows ?? []).find((item) => String(item.index) === normalizedIndex);
  if (!row || row.decisionKind !== "missing-in-changes") {
    return;
  }

  const nextDecision = decision === "create" ? "create" : "skipped";
  peopleTrainingImportDraft.rowDecisions[normalizedIndex] = nextDecision;
  row.decisionValue = nextDecision;
  if (nextDecision === "create") {
    row.action = "create";
    row.actionLabel = getPeopleTrainingImportActionLabel("create");
    row.tone = "success";
    row.canApply = true;
    row.message = "Osoba nije pronađena u evidenciji, ali označena je za unos kao novi zaposlenik.";
  } else {
    row.action = "skipped";
    row.actionLabel = getPeopleTrainingImportActionLabel("skipped");
    row.tone = "warning";
    row.canApply = false;
    row.message = "Osoba nije pronađena u evidenciji. U importu promjena ostaje preskočena dok ne odabereš Unesi.";
  }
  recalculatePeopleTrainingImportPreviewTotals(preview);
  renderPeopleTrainingImportDialog();
}

function createPeopleTrainingImportRowDecisionControl(row = {}) {
  if (row.decisionKind !== "missing-in-changes" || !Array.isArray(row.decisionOptions) || row.decisionOptions.length === 0) {
    return null;
  }

  const control = document.createElement("div");
  control.className = "people-training-import-row-choice";
  const activeDecision = peopleTrainingImportDraft.rowDecisions[String(row.index)]
    || row.decisionValue
    || (row.action === "create" ? "create" : "skipped");
  row.decisionOptions.forEach((option) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "people-training-import-row-choice-button";
    button.classList.toggle("is-active", option.value === activeDecision);
    button.textContent = option.label || option.value;
    button.disabled = peopleTrainingImportDraft.busy || peopleTrainingImportDraft.applying;
    button.addEventListener("click", () => {
      setPeopleTrainingImportRowDecision(row.index, option.value);
    });
    control.append(button);
  });
  return control;
}

function createPeopleTrainingImportPreviewRow(row = {}) {
  const item = document.createElement("article");
  item.className = `people-training-import-row is-${row.action || "skipped"}`;
  item.classList.toggle("is-decision", row.decisionKind === "missing-in-changes");

  const statusCell = document.createElement("div");
  statusCell.className = "people-training-import-status-cell";
  const status = document.createElement("span");
  status.className = "people-training-import-row-status";
  status.textContent = row.actionLabel || "Status";
  statusCell.append(status);
  const decisionControl = createPeopleTrainingImportRowDecisionControl(row);
  if (decisionControl) {
    statusCell.append(decisionControl);
  }

  const person = document.createElement("div");
  person.className = "people-training-import-person";
  const name = document.createElement("strong");
  name.textContent = row.personName || "Bez imena";
  const meta = document.createElement("span");
  meta.textContent = [
    row.oib ? `OIB ${row.oib}` : "",
    row.companyName || "",
    row.locationName || "",
  ].filter(Boolean).join(" · ");
  person.append(name, meta);

  const changes = document.createElement("div");
  changes.className = "people-training-import-changes";
  const changeItems = row.changes ?? [];
  if (changeItems.length) {
    changeItems.slice(0, 6).forEach((change) => {
      changes.append(createPeopleTrainingImportChangeChip(change));
    });
    if (changeItems.length > 6) {
      const more = document.createElement("span");
      more.className = "people-training-import-change is-more";
      more.textContent = `+ ${changeItems.length - 6} promjena`;
      changes.append(more);
    }
  } else {
    const message = document.createElement("span");
    message.className = "people-training-import-row-message";
    message.textContent = row.message || (row.action === "create"
      ? "Dodaje se kao nova osoba, bez usporedbe s postojećom evidencijom."
      : "Nema promjena za ovaj red.");
    changes.append(message);
  }

  item.append(statusCell, person, changes);
  return item;
}

function renderPeopleTrainingImportPreview(container) {
  container.replaceChildren();
  if (peopleTrainingImportDraft.busy) {
    const loading = document.createElement("div");
    loading.className = "people-training-import-empty is-loading";
    const title = document.createElement("strong");
    title.textContent = "Pripremam pregled importa...";
    const copy = document.createElement("span");
    copy.textContent = peopleTrainingImportDraft.fileName
      ? `Čitam ${peopleTrainingImportDraft.fileName} i uspoređujem s evidencijom.`
      : "Čitam Excel i uspoređujem s evidencijom.";
    loading.append(title, copy);
    container.append(loading);
    return;
  }
  const preview = peopleTrainingImportDraft.preview;
  if (!preview) {
    const empty = document.createElement("div");
    empty.className = "people-training-import-empty";
    empty.innerHTML = `
      <strong>Nema pregleda za prikaz.</strong>
      <span>Vrati se na Import Excel, odaberi vrstu importa i učitaj datoteku ponovno.</span>
    `;
    container.append(empty);
    return;
  }

  const totals = preview.totals ?? {};
  const stats = document.createElement("div");
  stats.className = "people-training-import-stats";
  stats.append(
    createPeopleTrainingImportStat("Novi", totals.create, "is-create"),
    createPeopleTrainingImportStat("Promjene", totals.update, "is-update"),
    createPeopleTrainingImportStat("Odlasci", totals.departure, "is-departure"),
    createPeopleTrainingImportStat("Preskočeno", (totals.skipped ?? 0) + (totals.unchanged ?? 0), "is-muted"),
  );

  const table = document.createElement("div");
  table.className = "people-training-import-table";
  const header = document.createElement("div");
  header.className = "people-training-import-row is-head";
  ["Status", "Osoba / tvrtka", "Pregled"].forEach((label) => {
    const cell = document.createElement("strong");
    cell.textContent = label;
    header.append(cell);
  });
  table.append(header);
  (preview.rows ?? []).forEach((row) => {
    table.append(createPeopleTrainingImportPreviewRow(row));
  });

  container.append(stats, table);
}

function renderPeopleTrainingImportDialog() {
  if (!peopleTrainingImportDraft.open) {
    return;
  }

  document.querySelector(".people-training-import-backdrop")?.remove();

  const backdrop = document.createElement("div");
  backdrop.className = "people-training-import-backdrop";
  backdrop.addEventListener("click", (event) => {
    if (event.target === backdrop && !peopleTrainingImportDraft.busy && !peopleTrainingImportDraft.applying) {
      closePeopleTrainingImportDialog();
    }
  });

  const modal = document.createElement("section");
  modal.className = "people-training-import-modal";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-label", "Import Excel osposobljavanja");

  const header = document.createElement("div");
  header.className = "people-training-import-head";
  const copy = document.createElement("div");
  const kicker = document.createElement("p");
  kicker.className = "section-kicker";
  kicker.textContent = "Excel import";
  const title = document.createElement("h3");
  title.textContent = "Pregled prije upisa u evidenciju";
  const summary = document.createElement("span");
  const modeOption = getPeopleTrainingImportModeOption();
  const applicable = peopleTrainingImportDraft.preview?.totals?.applicable ?? 0;
  summary.textContent = peopleTrainingImportDraft.preview
    ? `${modeOption.eyebrow} · ${peopleTrainingImportDraft.preview.rows?.length ?? 0} redaka · ${applicable} za potvrdu.`
    : `${modeOption.eyebrow} · učitaj Excel za pregled promjena.`;
  copy.append(kicker, title, summary);
  const closeButton = document.createElement("button");
  closeButton.type = "button";
  closeButton.className = "ghost-button";
  closeButton.textContent = "Zatvori";
  closeButton.disabled = peopleTrainingImportDraft.busy || peopleTrainingImportDraft.applying;
  closeButton.addEventListener("click", () => closePeopleTrainingImportDialog());
  header.append(copy, closeButton);

  const body = document.createElement("div");
  body.className = "people-training-import-body";

  const previewWrap = document.createElement("div");
  previewWrap.className = "people-training-import-preview";
  renderPeopleTrainingImportPreview(previewWrap);

  const error = document.createElement("p");
  error.className = "inline-message";
  error.hidden = !peopleTrainingImportDraft.error;
  error.textContent = peopleTrainingImportDraft.error;

  body.append(error, previewWrap);

  const actions = document.createElement("div");
  actions.className = "people-training-import-actions";
  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "ghost-button";
  cancelButton.textContent = "Odustani";
  cancelButton.disabled = peopleTrainingImportDraft.busy || peopleTrainingImportDraft.applying;
  cancelButton.addEventListener("click", () => closePeopleTrainingImportDialog());
  const reselectButton = document.createElement("button");
  reselectButton.type = "button";
  reselectButton.className = "ghost-button";
  reselectButton.textContent = "Drugi Excel";
  reselectButton.disabled = peopleTrainingImportDraft.busy || peopleTrainingImportDraft.applying;
  reselectButton.addEventListener("click", () => {
    closePeopleTrainingImportDialog({ reset: false });
    if (peopleTrainingImportInput) {
      peopleTrainingImportInput.value = "";
      peopleTrainingImportInput.click();
    }
  });
  const confirmButton = document.createElement("button");
  confirmButton.type = "button";
  confirmButton.className = "primary-button";
  confirmButton.textContent = peopleTrainingImportDraft.applying ? "Spremam..." : "Potvrdi import";
  confirmButton.disabled = peopleTrainingImportDraft.busy
    || peopleTrainingImportDraft.applying
    || !peopleTrainingImportDraft.preview
    || (peopleTrainingImportDraft.preview?.totals?.applicable ?? 0) <= 0;
  confirmButton.addEventListener("click", () => {
    void applyPeopleTrainingImportPreview();
  });
  actions.append(cancelButton, reselectButton, confirmButton);

  modal.append(header, body, actions);
  backdrop.append(modal);
  document.body.append(backdrop);
  document.body.classList.add("modal-open");

  if (peopleTrainingImportKeydownHandler) {
    document.removeEventListener("keydown", peopleTrainingImportKeydownHandler, true);
  }
  peopleTrainingImportKeydownHandler = (event) => {
    if (event.key === "Escape" && document.body.contains(backdrop) && !peopleTrainingImportDraft.busy && !peopleTrainingImportDraft.applying) {
      closePeopleTrainingImportDialog();
    }
  };
  document.addEventListener("keydown", peopleTrainingImportKeydownHandler, true);
}

async function importPeopleTrainingExcel(file) {
  if (!file) {
    return;
  }
  peopleTrainingImportDraft.open = true;
  peopleTrainingImportDraft.fileName = file.name;
  peopleTrainingImportDraft.preview = null;
  peopleTrainingImportDraft.rowDecisions = {};
  peopleTrainingImportDraft.error = "";
  peopleTrainingImportDraft.busy = true;
  renderPeopleTrainingImportDialog();

  try {
    peopleTrainingImportDraft.dataUrl = await readFileAsDataUrl(file, "Ne mogu učitati Excel tablicu.");
    const payload = await apiRequest("/people-training-records/import", {
      method: "POST",
      body: getPeopleTrainingImportRequestBody({ previewOnly: true }),
    });
    peopleTrainingImportDraft.preview = payload.preview ?? null;
    peopleTrainingImportDraft.error = "";
  } catch (error) {
    peopleTrainingImportDraft.preview = null;
    peopleTrainingImportDraft.error = error?.message || "Ne mogu pripremiti pregled importa.";
  } finally {
    peopleTrainingImportDraft.busy = false;
    renderPeopleTrainingImportDialog();
  }
}

async function downloadPeopleTrainingImportTemplateExcel() {
  if (peopleTrainingDownloadTemplateButton) {
    peopleTrainingDownloadTemplateButton.disabled = true;
  }
  try {
    const { blob, fileName } = await apiBinaryRequest("/people-training-records/import-template");
    triggerBlobDownload(blob, fileName || "osposobljavanja-podaci.xlsx");
    setPeopleTrainingFeedback("Excel s osposobljavanjima je preuzet.", "success");
  } catch (error) {
    setPeopleTrainingFeedback(error?.message || "Ne mogu preuzeti Excel s osposobljavanjima.", "error");
  } finally {
    if (peopleTrainingDownloadTemplateButton) {
      peopleTrainingDownloadTemplateButton.disabled = false;
    }
  }
}

async function applyPeopleTrainingImportPreview() {
  if (!peopleTrainingImportDraft.dataUrl || !peopleTrainingImportDraft.preview) {
    peopleTrainingImportDraft.error = "Prvo učitaj Excel i provjeri pregled promjena.";
    renderPeopleTrainingImportDialog();
    return;
  }

  peopleTrainingImportDraft.applying = true;
  peopleTrainingImportDraft.error = "";
  renderPeopleTrainingImportDialog();

  try {
    const payload = await apiRequest("/people-training-records/import", {
      method: "POST",
      body: getPeopleTrainingImportRequestBody({ previewOnly: false }),
    });
    if (payload && typeof payload === "object" && Object.prototype.hasOwnProperty.call(payload, "storage")) {
      applySnapshot(payload);
    }
    const totals = peopleTrainingImportDraft.preview?.totals ?? {};
    const summary = [
      totals.create ? `${totals.create} novih` : "",
      totals.update ? `${totals.update} promjena` : "",
      totals.departure ? `${totals.departure} odlazaka` : "",
    ].filter(Boolean).join(", ");
    closePeopleTrainingImportDialog();
    setPeopleTrainingFeedback(summary ? `Excel import je potvrđen: ${summary}.` : "Excel import je potvrđen.", "success");
    renderPeopleTrainingModule();
  } catch (error) {
    peopleTrainingImportDraft.error = error?.message || "Ne mogu potvrditi import.";
    peopleTrainingImportDraft.applying = false;
    renderPeopleTrainingImportDialog();
  }
}

function getPeopleTrainingAttachmentCategoryOptions(currentValue = "") {
  const seen = new Set();
  const options = [];
  const addOption = (value) => {
    const label = String(value || "").trim();
    const key = label.toLowerCase();
    if (!label || seen.has(key)) {
      return;
    }
    seen.add(key);
    options.push({ value: label, label });
  };

  PEOPLE_TRAINING_ATTACHMENT_CATEGORY_DEFAULTS.forEach(addOption);
  (state.peopleTrainingRecords ?? []).forEach((record) => {
    (record.attachments ?? []).forEach((attachment) => addOption(attachment.documentCategory));
  });
  addOption(currentValue);
  options.push({ value: "__custom__", label: "+ Nova vrsta priloga" });
  return options;
}

function createPeopleTrainingDocumentRow(documentItem = {}) {
  const row = document.createElement("article");
  row.className = "people-training-document-row";

  const icon = document.createElement("span");
  icon.className = "people-training-document-icon";
  icon.textContent = "PDF";

  const copy = document.createElement("div");
  copy.className = "people-training-document-copy";
  const title = document.createElement("strong");
  title.textContent = documentItem.fileName || "Prilog";
  const titleLine = document.createElement("span");
  titleLine.className = "people-training-document-title-line";
  titleLine.append(title);
  if (String(documentItem.sourceType || "") === "people-training-certificate" || String(documentItem.documentCategory || "").trim().toLowerCase() === "automatsko uvjerenje") {
    const badge = document.createElement("span");
    const isArchived = documentItem.activeDocument === false
      || documentItem.isActive === false
      || String(documentItem.documentStatus || "").trim().toLowerCase() === "archived";
    badge.className = `people-training-document-version ${isArchived ? "is-archived" : "is-active"}`;
    badge.textContent = isArchived ? "Arhiva" : "Aktivno";
    titleLine.append(badge);
  }
  const meta = document.createElement("span");
  meta.textContent = [
    documentItem.documentCategory || "Bez vrste",
    formatFileSize(documentItem.fileSize || 0),
    documentItem.createdAt ? formatCompactDate(documentItem.createdAt) : "",
    documentItem.description || "",
  ].filter(Boolean).join(" · ");
  copy.append(titleLine, meta);

  const actions = document.createElement("div");
  actions.className = "people-training-document-actions";
  const openButton = document.createElement("button");
  openButton.type = "button";
  openButton.className = "ghost-button";
  openButton.textContent = "Otvori";
  openButton.disabled = !(documentItem.storageUrl || documentItem.dataUrl);
  openButton.addEventListener("click", () => triggerModuleAttachmentDownload(documentItem));
  actions.append(openButton);

  row.append(icon, copy, actions);
  return row;
}

function getPeopleTrainingDocumentationBrief(record = {}) {
  const attachments = Array.isArray(record.attachments) ? record.attachments : [];
  if (!attachments.length) {
    return "";
  }

  const names = attachments
    .slice(0, 3)
    .map((attachment) => [
      attachment.documentCategory || "",
      attachment.fileName || "",
    ].filter(Boolean).join(": "))
    .filter(Boolean);
  const more = attachments.length > names.length ? `+${attachments.length - names.length}` : "";
  return [
    `${attachments.length} ${attachments.length === 1 ? "prilog" : "priloga"}`,
    ...names,
    more,
  ].filter(Boolean).join(" · ");
}

function renderPeopleTrainingDossier(record = null) {
  if (!peopleTrainingDossier) {
    return;
  }

  peopleTrainingDossier.replaceChildren();
  peopleTrainingDossier.tabIndex = -1;
  peopleTrainingDossier.classList.toggle("is-empty", !record?.id);
  peopleTrainingDossier.classList.remove("is-drag-over");
  peopleTrainingDossier.ondragover = null;
  peopleTrainingDossier.ondragleave = null;
  peopleTrainingDossier.ondrop = null;
  if (peopleTrainingDossier instanceof HTMLDetailsElement) {
    peopleTrainingDossier.open = Boolean(record?.id);
  }

  if (!record?.id) {
    peopleTrainingDossier.append(createPeopleTrainingSectionSummary({
      number: "10",
      title: "Dokumentacija",
      brief: "",
      statusClass: "is-neutral",
    }));
    return;
  }

  const documents = document.createElement("div");
  documents.className = "people-training-section-body people-training-dossier-documents";
  const documentsHead = document.createElement("div");
  documentsHead.className = "people-training-dossier-subhead";
  const documentsTitle = document.createElement("strong");
  documentsTitle.textContent = "Prilozi i dokumenti";
  const documentsHint = document.createElement("span");
  documentsHint.textContent = "Povuci PDF, sliku ili dokument ovdje ili na red osobe.";
  const documentsCopy = document.createElement("div");
  documentsCopy.append(documentsTitle, documentsHint);
  const generateAllButton = document.createElement("button");
  generateAllButton.type = "button";
  generateAllButton.className = "ghost-button people-training-generate-documents-button";
  generateAllButton.innerHTML = `${getWorkOrderIconMarkup("document")}<span>Napravi sve PDF-ove</span>`;
  generateAllButton.disabled = !normalizePeopleTrainingItemsForUi(record.trainingItems)
    .some((item) => hasPeopleTrainingCertificateTemplateForItem(item, record));
  generateAllButton.title = generateAllButton.disabled
    ? "Nema povezanih Word predložaka za usluge ove osobe."
    : "Izradi aktivne PDF dokumente za sve usluge koje imaju Word predložak.";
  generateAllButton.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    void generatePeopleTrainingPdfDocuments(record, null, { openLatest: false, force: true, button: generateAllButton });
  });
  documentsHead.append(documentsCopy, generateAllButton);
  documents.append(documentsHead);

  const rows = (record.attachments ?? []).map(createPeopleTrainingDocumentRow);
  if (rows.length) {
    documents.append(...rows);
  } else {
    const empty = document.createElement("p");
    empty.className = "empty-state";
    empty.textContent = "Još nema priloga u dosjeu.";
    documents.append(empty);
  }

  const handleFiles = (event) => {
    const files = getPeopleTrainingDroppedFiles(event.dataTransfer);
    if (files.length === 0) {
      return;
    }
    event.preventDefault();
    peopleTrainingDossier.classList.remove("is-drag-over");
    void openPeopleTrainingAttachmentDialog(record, files);
  };
  peopleTrainingDossier.ondragover = (event) => {
    if (hasPeopleTrainingDraggedFiles(event.dataTransfer)) {
      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.dropEffect = "copy";
      }
      peopleTrainingDossier.classList.add("is-drag-over");
    }
  };
  peopleTrainingDossier.ondragleave = (event) => {
    if (event.relatedTarget instanceof Node && peopleTrainingDossier.contains(event.relatedTarget)) {
      return;
    }
    peopleTrainingDossier.classList.remove("is-drag-over");
  };
  peopleTrainingDossier.ondrop = handleFiles;

  peopleTrainingDossier.append(
    createPeopleTrainingSectionSummary({
      number: "10",
      title: "Dokumentacija",
      brief: getPeopleTrainingDocumentationBrief(record),
      statusClass: (record.attachments ?? []).length ? "is-valid" : "is-neutral",
    }),
    documents,
  );
}

async function openPeopleTrainingAttachmentDialog(record = {}, files = [], { defaultCategory = "" } = {}) {
  if (!record?.id || files.length === 0) {
    return;
  }

  const drafts = await Promise.all(files.map(async (file) => ({
    id: crypto.randomUUID(),
    fileName: file.name,
    fileType: file.type || "application/octet-stream",
    fileSize: file.size || 0,
    dataUrl: await readFileAsDataUrl(file, `Ne mogu učitati datoteku ${file.name}.`),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  })));

  const backdrop = document.createElement("div");
  backdrop.className = "people-training-attachment-dialog-backdrop";
  const panel = document.createElement("section");
  panel.className = "people-training-attachment-dialog";
  panel.setAttribute("role", "dialog");
  panel.setAttribute("aria-modal", "true");

  const head = document.createElement("div");
  head.className = "people-training-attachment-dialog-head";
  const titleWrap = document.createElement("div");
  const kicker = document.createElement("p");
  kicker.className = "section-kicker";
  kicker.textContent = "Dosje";
  const title = document.createElement("h3");
  title.textContent = `Dodaj priloge za ${record.fullName || "osobu"}`;
  titleWrap.append(kicker, title);
  const closeButton = document.createElement("button");
  closeButton.type = "button";
  closeButton.className = "ghost-button";
  closeButton.textContent = "Zatvori";
  head.append(titleWrap, closeButton);

  const list = document.createElement("div");
  list.className = "people-training-attachment-file-list";
  drafts.forEach((draft) => {
    const row = document.createElement("label");
    row.className = "people-training-attachment-file-row";
    const fileCopy = document.createElement("span");
    const fileTitle = document.createElement("strong");
    fileTitle.textContent = draft.fileName;
    const fileSize = document.createElement("small");
    fileSize.textContent = formatFileSize(draft.fileSize);
    fileCopy.append(fileTitle, fileSize);
    const select = document.createElement("select");
    select.dataset.attachmentCategory = draft.id;
    replaceSelectOptions(select, getPeopleTrainingAttachmentCategoryOptions(defaultCategory), defaultCategory || PEOPLE_TRAINING_ATTACHMENT_CATEGORY_DEFAULTS[0]);
    const custom = document.createElement("input");
    custom.type = "text";
    custom.placeholder = "Upiši novu vrstu priloga";
    custom.dataset.attachmentCustomCategory = draft.id;
    custom.hidden = true;
    const description = document.createElement("input");
    description.type = "text";
    description.placeholder = "Opis priloga (opcionalno)";
    description.dataset.attachmentDescription = draft.id;
    select.addEventListener("change", () => {
      custom.hidden = select.value !== "__custom__";
      if (!custom.hidden) {
        custom.focus({ preventScroll: true });
      }
    });
    row.append(fileCopy, select, custom, description);
    list.append(row);
  });

  const footer = document.createElement("div");
  footer.className = "people-training-attachment-dialog-actions";
  const saveButton = document.createElement("button");
  saveButton.type = "button";
  saveButton.className = "primary-button";
  saveButton.textContent = "Spremi priloge";
  footer.append(saveButton);

  const closeDialog = () => {
    backdrop.remove();
    panel.remove();
  };
  closeButton.addEventListener("click", closeDialog);
  backdrop.addEventListener("click", closeDialog);
  saveButton.addEventListener("click", async () => {
    const attachments = drafts.map((draft) => {
      const select = list.querySelector(`[data-attachment-category="${draft.id}"]`);
      const custom = list.querySelector(`[data-attachment-custom-category="${draft.id}"]`);
      const description = list.querySelector(`[data-attachment-description="${draft.id}"]`);
      const selectedCategory = String(select?.value || "").trim();
      const customCategory = String(custom?.value || "").trim();
      return {
        ...draft,
        documentCategory: selectedCategory === "__custom__" ? customCategory : selectedCategory,
        description: String(description?.value || "").trim(),
      };
    });
    const success = await addPeopleTrainingAttachments(record, attachments);
    if (success) {
      closeDialog();
    }
  });

  panel.append(head, list, footer);
  document.body.append(backdrop, panel);
  requestAnimationFrame(() => panel.classList.add("is-open"));
}

async function addPeopleTrainingAttachments(record = {}, attachments = []) {
  if (!record?.id || attachments.length === 0) {
    return false;
  }

  const success = await runMutation(() => apiRequest(`/people-training-records/${encodeURIComponent(record.id)}`, {
    method: "PATCH",
    body: {
      attachments: [
        ...(record.attachments ?? []),
        ...attachments,
      ],
    },
  }), peopleTrainingFormFeedback);

  if (success) {
    const updated = state.peopleTrainingRecords.find((item) => String(item.id) === String(record.id));
    if (updated && String(updated.id) === String(state.activePeopleTrainingRecordId)) {
      renderPeopleTrainingDossier(updated);
    }
    renderPeopleTrainingModule();
    setPeopleTrainingFeedback("Prilozi su spremljeni u dosje zaposlenika.", "success");
  }

  return success;
}

function optionListIncludesValue(options = [], value = "") {
  return options.some((option) => String(option.value) === String(value));
}

function buildCategoryOptions(options = [], currentValue = "") {
  const normalizedCurrent = String(currentValue || "").trim();
  if (!normalizedCurrent || optionListIncludesValue(options, normalizedCurrent)) {
    return options;
  }

  const insertIndex = Math.max(0, options.length - 1);
  const nextOptions = options.slice();
  nextOptions.splice(insertIndex, 0, {
    value: normalizedCurrent,
    label: normalizedCurrent,
  });
  return nextOptions;
}

function buildDraftCategoryOptions(baseOptions = [], drafts = [], currentValue = "") {
  const baseWithoutCustom = baseOptions.filter((option) => option.value !== "__custom__");
  const customOption = baseOptions.find((option) => option.value === "__custom__") || null;
  const seen = new Set(baseWithoutCustom.map((option) => String(option.value)));
  const customValues = [];

  (Array.isArray(drafts) ? drafts : []).forEach((draft) => {
    const value = String(draft?.documentCategory || "").trim();
    if (!value || seen.has(value)) {
      return;
    }
    seen.add(value);
    customValues.push({
      value,
      label: value,
    });
  });

  const nextOptions = [...baseWithoutCustom, ...customValues];
  if (customOption) {
    nextOptions.push(customOption);
  }
  return buildCategoryOptions(nextOptions, currentValue);
}

function getUserInitials(userLike = {}) {
  const firstName = String(userLike.firstName ?? "").trim();
  const lastName = String(userLike.lastName ?? "").trim();
  const fullName = String(userLike.fullName ?? "").trim();
  const seed = [firstName, lastName].filter(Boolean).join(" ") || fullName || String(userLike.email ?? "");
  const parts = seed.split(/\s+/).filter(Boolean);
  return parts.slice(0, 2).map((part) => part.charAt(0).toUpperCase()).join("") || "U";
}

function renderAvatar(target, userLike = {}) {
  if (!target) {
    return;
  }

  target.replaceChildren();
  target.classList.toggle("has-image", Boolean(userLike.avatarDataUrl));

  if (userLike.avatarDataUrl) {
    const image = document.createElement("img");
    image.src = userLike.avatarDataUrl;
    image.alt = userLike.fullName || userLike.email || "User";
    target.append(image);
    return;
  }

  target.textContent = getUserInitials(userLike);
}

function renderCompanyLogo(target, companyLike = {}) {
  renderAvatar(target, {
    fullName: companyLike.name || companyLike.companyName || "Tvrtka",
    avatarDataUrl: companyLike.logoDataUrl || companyLike.companyLogoDataUrl || "",
  });
}

function describeCompanyPreview(companyLike = {}) {
  return [
    companyLike.headquarters || "",
    companyLike.oib ? `OIB ${companyLike.oib}` : "",
  ].filter(Boolean).join(" · ") || "Bez dodatnih podataka";
}

function syncCompanySelectionPreview(
  companyId,
  previewWrap,
  previewLogo,
  previewName,
  previewMeta,
) {
  if (!previewWrap || !previewLogo || !previewName || !previewMeta) {
    return;
  }

  const company = getCompany(companyId);
  const keepVisible = previewWrap.dataset.keepVisible === "true";
  previewWrap.hidden = !company && !keepVisible;
  previewWrap.classList.toggle("has-selection", Boolean(company));

  if (!company) {
    previewName.textContent = "Tvrtka";
    previewMeta.textContent = "Odaberi tvrtku za detalje.";
    renderCompanyLogo(previewLogo, { name: "Tvrtka" });
    return;
  }

  previewName.textContent = company.name || "Tvrtka";
  previewMeta.textContent = describeCompanyPreview(company);
  renderCompanyLogo(previewLogo, company);
}

const WORK_ORDER_EDITOR_SECTION_ICON_NAMES = {
  status: "status",
  client: "company",
  route: "location",
  location: "location",
  contact: "contact",
  executors: "assignees",
  services: "service",
  billing: "billing",
  documents: "document",
};

function syncWorkOrderEditorSectionCollapse(section) {
  if (!(section instanceof HTMLElement)) {
    return;
  }

  const sectionKey = String(section.dataset.workOrderSection || "").trim();
  const toggle = section.querySelector("[data-work-order-section-toggle]");
  const toggleIcon = section.querySelector(".work-order-section-toggle-icon");
  const collapsed = Boolean(sectionKey && state.workOrderEditorCollapsedSections[sectionKey]);
  section.classList.toggle("is-collapsed", collapsed);
  toggle?.setAttribute("aria-expanded", collapsed ? "false" : "true");
  toggle?.setAttribute("aria-label", collapsed ? "Prikaži blok" : "Sakrij blok");

  if (toggleIcon) {
    toggleIcon.innerHTML = getWorkOrderIconMarkup(collapsed ? "expand" : "collapse");
  }
}

function toggleWorkOrderEditorSection(section) {
  if (!(section instanceof HTMLElement)) {
    return;
  }

  const sectionKey = String(section.dataset.workOrderSection || "").trim();
  if (!sectionKey) {
    return;
  }

  state.workOrderEditorCollapsedSections[sectionKey] = !state.workOrderEditorCollapsedSections[sectionKey];
  syncWorkOrderEditorSectionCollapse(section);
}

function initializeWorkOrderEditorSectionToggles() {
  workOrderSectionToggleButtons.forEach((button) => {
    const section = button.closest(".work-order-editor-section[data-work-order-section]");
    const sectionKey = String(section?.dataset.workOrderSection || "").trim();

    if (!button.querySelector(".work-order-section-mark")) {
      const icon = document.createElement("span");
      icon.className = "work-order-section-mark";
      icon.setAttribute("aria-hidden", "true");
      icon.innerHTML = getWorkOrderIconMarkup(WORK_ORDER_EDITOR_SECTION_ICON_NAMES[sectionKey] || "service");
      button.prepend(icon);
    }

    syncWorkOrderEditorSectionCollapse(section);
    button.addEventListener("click", () => {
      toggleWorkOrderEditorSection(section);
    });
  });
}

function initializeWorkOrderFieldLabelTooltips() {
  if (!workOrderForm) {
    return;
  }

  workOrderForm.querySelectorAll(".field").forEach((field) => {
    const heading = field.querySelector(":scope > span");
    const label = String(heading?.dataset.originalLabel || heading?.textContent || "").trim();

    if (!label) {
      return;
    }

    field.title = label;
    field.dataset.fieldTooltip = label;

    field.querySelectorAll("input, select, textarea, button").forEach((control) => {
      if (!control.getAttribute("aria-label")) {
        control.setAttribute("aria-label", label);
      }
      if (!control.getAttribute("title")) {
        control.setAttribute("title", label);
      }
    });
  });
}

function applyPresenceToAvatar(target, presence = "online") {
  if (!target) {
    return;
  }

  target.dataset.presence = normalizeUserPresence(presence);
}

function readFileAsDataUrl(file, errorMessage = "Ne mogu učitati datoteku.") {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.addEventListener("load", () => {
      resolve(String(reader.result ?? ""));
    });
    reader.addEventListener("error", () => {
      reject(new Error(errorMessage));
    });
    reader.readAsDataURL(file);
  });
}

function readAvatarFileAsDataUrl(file) {
  return readFileAsDataUrl(file, "Ne mogu učitati sliku.");
}

function normalizeLooseName(value = "") {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeSearchText(value = "") {
  return normalizeLooseName(value);
}

function findUserForExecutor(executorName = "") {
  const normalized = normalizeLooseName(executorName);

  if (!normalized) {
    return null;
  }

  return state.users.find((user) => {
    const candidates = [
      user.displayName,
      user.fullName,
      [user.firstName, user.lastName].filter(Boolean).join(" "),
      user.legacyUsername,
      user.email,
    ].map(normalizeLooseName).filter(Boolean);

    return candidates.includes(normalized);
  }) ?? null;
}

function getUserDisplayLabel(user = {}) {
  return String(user.fullName || user.email || user.username || "User").trim() || "User";
}

function getExecutorTone(name = "") {
  const palette = [
    { bg: "#e7efff", fg: "#3a63b8" },
    { bg: "#f6e7ff", fg: "#8a47b8" },
    { bg: "#e8f8ef", fg: "#2b7a52" },
    { bg: "#fff0de", fg: "#a15a18" },
    { bg: "#ffe4ea", fg: "#b23f6a" },
    { bg: "#ecebff", fg: "#5446c9" },
  ];
  const normalized = String(name ?? "").trim();
  const hash = [...normalized].reduce((sum, char) => sum + char.charCodeAt(0), 0);
  return palette[hash % palette.length];
}

