function createDrawingLayerDraft(index = 0, overrides = {}) {
  const palette = ["#8a9ab8", "#21385f", "#25a37d", "#d64d50", "#7b5fd1", "#da8a1f", "#3a8ec9"];
  drawingDraftLayerCounter += 1;
  return {
    id: String(overrides.id || crypto.randomUUID()),
    name: String(overrides.name || `Layer ${drawingDraftLayerCounter}`).trim() || `Layer ${drawingDraftLayerCounter}`,
    color: String(overrides.color || palette[index % palette.length]).trim() || palette[index % palette.length],
    visible: overrides.visible !== false,
    locked: Boolean(overrides.locked),
    lineWidth: Number.isFinite(Number(overrides.lineWidth)) ? Math.max(1, Math.min(18, Math.round(Number(overrides.lineWidth)))) : 2,
    lineStyle: ["solid", "dashed", "dotted"].includes(String(overrides.lineStyle || "").trim().toLowerCase())
      ? String(overrides.lineStyle).trim().toLowerCase()
      : "solid",
  };
}

function createDrawingDefaultLayers() {
  return [
    createDrawingLayerDraft(0, { name: "Podloga", color: "#8a9ab8", lineWidth: 1 }),
    createDrawingLayerDraft(1, { name: "Zidovi", color: "#21385f", lineWidth: 6 }),
    createDrawingLayerDraft(2, { name: "Vrata i prolazi", color: "#25a37d", lineWidth: 2 }),
    createDrawingLayerDraft(3, { name: "Kote", color: "#da8a1f", lineWidth: 2, lineStyle: "dashed" }),
    createDrawingLayerDraft(4, { name: "Sigurnosni simboli", color: "#d64d50", lineWidth: 2 }),
    createDrawingLayerDraft(5, { name: "Napomene", color: "#7b5fd1", lineWidth: 1, lineStyle: "dashed" }),
  ];
}

function getSortedDrawingCompanies(items = []) {
  return [...(items ?? [])].sort((left, right) => (
    String(left?.name || "").localeCompare(String(right?.name || ""), "hr", { sensitivity: "base" })
  ));
}

function getSortedDrawingLocations(items = []) {
  return [...(items ?? [])].sort((left, right) => (
    String(left?.name || "").localeCompare(String(right?.name || ""), "hr", { sensitivity: "base" })
  ));
}

function getDrawingDefaultElementStyle(type = "rectangle", layer = null) {
  const layerColor = String(layer?.color || "").trim();
  switch (String(type || "").trim().toLowerCase()) {
    case "line":
      return { stroke: layerColor || "#4564d1", fill: "transparent", lineWidth: 2, width: 220, height: 0 };
    case "curve":
      return { stroke: layerColor || "#4564d1", fill: "transparent", lineWidth: 2, width: 220, height: 120 };
    case "wall":
      return { stroke: layerColor || "#21385f", fill: "transparent", lineWidth: 12, width: 280, height: 0 };
    case "dimension":
      return { stroke: layerColor || "#da8a1f", fill: "transparent", lineWidth: 2, width: 220, height: 0 };
    case "ellipse":
      return { stroke: layerColor || "#4564d1", fill: "#e8efff", lineWidth: 2, width: 240, height: 150 };
    case "frame":
      return { stroke: layerColor || "#20416f", fill: "transparent", lineWidth: 2, width: 1380, height: 860 };
    case "door":
      return { stroke: layerColor || "#22a06b", fill: "transparent", lineWidth: 2, width: 120, height: 90 };
    case "exit":
      return { stroke: layerColor || "#1e9e68", fill: "#e8fbf2", lineWidth: 2, width: 140, height: 56 };
    case "extinguisher":
      return { stroke: layerColor || "#cc4f57", fill: "#fff1f2", lineWidth: 2, width: 52, height: 70 };
    case "hydrant":
      return { stroke: layerColor || "#c83d48", fill: "#fff1f2", lineWidth: 2, width: 52, height: 52 };
    case "stairs":
      return { stroke: layerColor || "#3561cf", fill: "#edf3ff", lineWidth: 2, width: 180, height: 120 };
    case "assembly_point":
      return { stroke: layerColor || "#1e9e68", fill: "#e8fbf2", lineWidth: 2, width: 170, height: 72 };
    case "first_aid":
      return { stroke: layerColor || "#239c6d", fill: "#e7faf1", lineWidth: 2, width: 84, height: 84 };
    case "detector":
      return { stroke: layerColor || "#4564d1", fill: "#eef3ff", lineWidth: 2, width: 58, height: 58 };
    case "panel":
      return { stroke: layerColor || "#cc4f57", fill: "#fff1f2", lineWidth: 2, width: 96, height: 72 };
    case "arrow":
      return { stroke: layerColor || "#1e9e68", fill: "#e8fbf2", lineWidth: 2, width: 150, height: 44 };
    case "text":
      return { stroke: layerColor || "#23324f", fill: "transparent", lineWidth: 0, width: 220, height: 40 };
    default:
      return { stroke: layerColor || "#4564d1", fill: "#e8efff", lineWidth: 2, width: 260, height: 140 };
  }
}

function getDrawingActiveLayer() {
  const explicit = drawingLayerDrafts.find((layer) => String(layer.id) === String(drawingActiveLayerId));
  if (explicit) {
    return explicit;
  }

  if (drawingSelectedElementId) {
    const selected = drawingElementDrafts.find((item) => String(item.id) === String(drawingSelectedElementId));
    if (selected) {
      return drawingLayerDrafts.find((layer) => String(layer.id) === String(selected.layerId)) ?? null;
    }
  }

  return drawingLayerDrafts.find((layer) => layer.visible !== false && !layer.locked) ?? drawingLayerDrafts[0] ?? null;
}

function getDrawingPreferredLayerName(tool = "rectangle") {
  const normalizedTool = String(tool || "").trim().toLowerCase();
  if (normalizedTool === "wall") {
    return "Zidovi";
  }
  if (normalizedTool === "door") {
    return "Vrata i prolazi";
  }
  if (normalizedTool === "dimension") {
    return "Kote";
  }
  if (DRAWING_SYMBOL_TYPES.has(normalizedTool)) {
    return "Sigurnosni simboli";
  }
  if (["frame", "text", "curve", "ellipse"].includes(normalizedTool)) {
    return "Napomene";
  }
  return "";
}

function clampDrawingCanvasWidth(value) {
  return Math.max(DRAWING_STAGE_MIN_WIDTH, Math.min(DRAWING_STAGE_MAX_WIDTH, Math.round(Number(value) || DRAWING_STAGE_DEFAULT_WIDTH)));
}

function clampDrawingCanvasHeight(value) {
  return Math.max(DRAWING_STAGE_MIN_HEIGHT, Math.min(DRAWING_STAGE_MAX_HEIGHT, Math.round(Number(value) || DRAWING_STAGE_DEFAULT_HEIGHT)));
}

function getDrawingToolLabel(tool = "select") {
  const mapping = {
    select: "Odabir",
    line: "Linija",
    curve: "Zakrivljena linija",
    wall: "Zid",
    dimension: "Kota",
    rectangle: "Pravokutnik",
    ellipse: "Elipsa",
    frame: "Okvir",
    door: "Vrata",
    text: "Tekst",
    exit: "Exit",
    extinguisher: "Aparat",
    hydrant: "Hidrant",
    stairs: "Stube",
    assembly_point: "Zborno mjesto",
    first_aid: "Prva pomoc",
    detector: "Detektor",
    panel: "Centrala",
    arrow: "Smjer",
  };
  return mapping[String(tool || "").trim().toLowerCase()] || "Alat";
}

function getDrawingActiveReference() {
  return drawingReferenceDrafts.find((item) => String(item.id) === String(drawingActiveReferenceId)) ?? null;
}

function isDrawingDerivedReference(reference = null) {
  return String(reference?.documentCategory || "").trim().toLowerCase() === DRAWING_REFERENCE_PREVIEW_CATEGORY;
}

function getDrawingVisibleReferenceDrafts() {
  return drawingReferenceDrafts.filter((item) => !isDrawingDerivedReference(item));
}

function getDrawingRenderableReference(reference = null) {
  if (!reference) {
    return null;
  }

  if (isDrawingDerivedReference(reference)) {
    return reference;
  }

  if (!isDrawingCadReference(reference)) {
    return reference;
  }

  return drawingReferenceDrafts.find((item) => (
    isDrawingDerivedReference(item)
    && String(item.sourceDocumentId || "").trim() === String(reference.id || "").trim()
  )) ?? reference;
}

function isDrawingCadReference(reference = null) {
  const fileName = String(reference?.fileName || "").trim().toLowerCase();
  return fileName.endsWith(".dwg") || fileName.endsWith(".dxf");
}

function isDrawingDxfReference(reference = null) {
  const fileName = String(reference?.fileName || "").trim().toLowerCase();
  const fileType = String(reference?.fileType || "").trim().toLowerCase();
  return fileName.endsWith(".dxf") || fileType.includes("dxf");
}

function isDrawingPdfReference(reference = null) {
  const fileName = String(reference?.fileName || "").trim().toLowerCase();
  const fileType = String(reference?.fileType || "").trim().toLowerCase();
  return fileType.includes("pdf") || fileName.endsWith(".pdf");
}

function isDrawingImageReference(reference = null) {
  const fileName = String(reference?.fileName || "").trim().toLowerCase();
  const fileType = String(reference?.fileType || "").trim().toLowerCase();
  return fileType.startsWith("image/") || [".png", ".jpg", ".jpeg", ".webp", ".svg"].some((extension) => fileName.endsWith(extension));
}

function showDrawingCadStatus(message = "", tone = "info") {
  if (!drawingStageCadStatus) {
    return;
  }

  const text = String(message || "").trim();
  drawingStageCadStatus.hidden = !text;
  drawingStageCadStatus.textContent = text;
  drawingStageCadStatus.dataset.tone = text ? tone : "";
}

function getDrawingCadWasmUrl() {
  return `/assets/vendor/libredwg.wasm?v=${DRAWING_VENDOR_VERSION}`;
}

function getDrawingCadKindLabel(reference = null) {
  return isDrawingDxfReference(reference) ? "DXF" : "DWG";
}

function getDrawingCadVersionLabel(buffer = null, dwgModule = null) {
  if (!buffer || !dwgModule?.getDwgVersion) {
    return "";
  }

  const version = dwgModule.getDwgVersion(buffer);
  if (!version) {
    return "";
  }

  const releaseName = dwgModule.getDwgReleaseName?.(version) || "";
  return releaseName ? `${version} / ${releaseName}` : version;
}

function getDrawingCadErrorMessage(error = null) {
  const rawMessage = String(error?.message || error || "CAD datoteku nije moguće učitati.").trim();
  if (rawMessage.includes("Failed to fetch")) {
    return "CAD datoteku nije moguće pročitati iz spremljene podloge. Pokušaj ponovno učitati datoteku.";
  }
  if (rawMessage.includes("too old")) {
    return "DWG je prestar za pregled u browseru. Spremi ga kao noviji DWG ili ASCII DXF i pokušaj ponovno.";
  }
  if (rawMessage.includes("Unrecognized DWG version")) {
    return "DWG verzija nije podržana u pregledniku. Iz AutoCAD-a spremi kao noviji DWG ili DXF.";
  }
  if (rawMessage.includes("Binary DXF")) {
    return "Binary DXF nije podržan. Spremi DXF kao ASCII DXF i pokušaj ponovno.";
  }
  if (rawMessage.includes("Cannot convert empty buffer") || rawMessage.includes("Input is empty")) {
    return "CAD datoteka je prazna ili nije ispravno učitana.";
  }
  if (rawMessage.includes("WASM")) {
    return "DWG konverter se nije učitao. Osvježi stranicu i pokušaj ponovno.";
  }

  return rawMessage.replace(/^@cadview\/dwg:\s*/i, "");
}

function getDrawingCadViewerEntityCount(viewer = null) {
  const entities = typeof viewer?.getEntities === "function" ? viewer.getEntities() : [];
  return Array.isArray(entities) ? entities.length : 0;
}

function getDrawingCadLoadedSummary(viewer = null, reference = null, elapsedMs = 0, extra = {}) {
  const entities = typeof viewer?.getEntities === "function" ? viewer.getEntities() : [];
  const layers = typeof viewer?.getLayers === "function" ? viewer.getLayers() : [];
  const entityCount = Array.isArray(entities) ? entities.length : 0;
  const layerCount = Array.isArray(layers) ? layers.length : 0;
  return {
    fileName: String(reference?.fileName || "").trim(),
    kind: getDrawingCadKindLabel(reference),
    entityCount,
    layerCount,
    elapsedMs: Math.max(0, Math.round(Number(elapsedMs) || 0)),
    ...extra,
  };
}

function getDrawingCadLoadedSummaryText(meta = null) {
  if (!meta) {
    return "";
  }

  return [
    `${meta.kind || "CAD"} pregled spreman`,
    `${meta.entityCount || 0} entiteta`,
    `${meta.layerCount || 0} slojeva`,
    meta.note || "",
    meta.elapsedMs ? `${(meta.elapsedMs / 1000).toFixed(meta.elapsedMs >= 10000 ? 0 : 1)} s` : "",
  ].filter(Boolean).join(" · ");
}

function parseDrawingDxfPairs(dxfText = "") {
  const lines = String(dxfText || "").replace(/\r/g, "").split("\n");
  const pairs = [];
  for (let index = 0; index < lines.length - 1; index += 2) {
    pairs.push({
      code: String(lines[index] || "").trim(),
      value: String(lines[index + 1] || "").trim(),
    });
  }
  return pairs;
}

function readDrawingDxfNumber(rawValue = "", fallback = 0) {
  const number = Number.parseFloat(String(rawValue || "").trim().replace(",", "."));
  return Number.isFinite(number) ? number : fallback;
}

function readDrawingDxfFirstValue(pairs = [], code = "") {
  return pairs.find((pair) => pair.code === code)?.value ?? "";
}

function readDrawingDxfFirstNumber(pairs = [], code = "", fallback = 0) {
  return readDrawingDxfNumber(readDrawingDxfFirstValue(pairs, code), fallback);
}

function readDrawingDxfPoints(pairs = []) {
  const points = [];
  let pendingPoint = null;
  pairs.forEach((pair) => {
    if (pair.code === "10") {
      pendingPoint = { x: readDrawingDxfNumber(pair.value), y: 0 };
      points.push(pendingPoint);
    } else if (pair.code === "20" && pendingPoint) {
      pendingPoint.y = readDrawingDxfNumber(pair.value);
      pendingPoint = null;
    }
  });
  return points.filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y));
}

function getDrawingDxfTextValue(pairs = []) {
  const chunks = pairs
    .filter((pair) => pair.code === "1" || pair.code === "3")
    .map((pair) => String(pair.value || "").trim())
    .filter(Boolean);
  return chunks.join(" ").replace(/%%U/gi, "").replace(/\\P/gi, " ").trim();
}

function createDrawingDxfPrimitive(rawEntity = null) {
  if (!rawEntity?.type) {
    return null;
  }

  const pairs = Array.isArray(rawEntity.pairs) ? rawEntity.pairs : [];
  const layer = String(readDrawingDxfFirstValue(pairs, "8") || rawEntity.layer || "0").trim() || "0";
  const base = { type: rawEntity.type, layer };
  if (rawEntity.type === "LINE") {
    return {
      ...base,
      x1: readDrawingDxfFirstNumber(pairs, "10"),
      y1: readDrawingDxfFirstNumber(pairs, "20"),
      x2: readDrawingDxfFirstNumber(pairs, "11"),
      y2: readDrawingDxfFirstNumber(pairs, "21"),
    };
  }
  if (rawEntity.type === "CIRCLE") {
    return {
      ...base,
      x: readDrawingDxfFirstNumber(pairs, "10"),
      y: readDrawingDxfFirstNumber(pairs, "20"),
      radius: Math.max(0.01, readDrawingDxfFirstNumber(pairs, "40", 1)),
    };
  }
  if (rawEntity.type === "ARC") {
    return {
      ...base,
      x: readDrawingDxfFirstNumber(pairs, "10"),
      y: readDrawingDxfFirstNumber(pairs, "20"),
      radius: Math.max(0.01, readDrawingDxfFirstNumber(pairs, "40", 1)),
      startAngle: readDrawingDxfFirstNumber(pairs, "50"),
      endAngle: readDrawingDxfFirstNumber(pairs, "51"),
    };
  }
  if (rawEntity.type === "TEXT" || rawEntity.type === "MTEXT") {
    const text = getDrawingDxfTextValue(pairs);
    if (!text) {
      return null;
    }
    return {
      ...base,
      type: "TEXT",
      x: readDrawingDxfFirstNumber(pairs, "10"),
      y: readDrawingDxfFirstNumber(pairs, "20"),
      height: Math.max(1, readDrawingDxfFirstNumber(pairs, "40", 12)),
      rotation: readDrawingDxfFirstNumber(pairs, "50"),
      text,
    };
  }
  if (rawEntity.type === "LWPOLYLINE") {
    const points = readDrawingDxfPoints(pairs);
    if (points.length < 2) {
      return null;
    }
    return {
      ...base,
      type: "LWPOLYLINE",
      points,
      closed: (Math.trunc(readDrawingDxfFirstNumber(pairs, "70")) & 1) === 1,
    };
  }

  return null;
}

function getDrawingDxfPrimitiveBounds(primitive = null) {
  if (!primitive) {
    return null;
  }
  if (primitive.type === "LINE") {
    return {
      minX: Math.min(primitive.x1, primitive.x2),
      minY: Math.min(primitive.y1, primitive.y2),
      maxX: Math.max(primitive.x1, primitive.x2),
      maxY: Math.max(primitive.y1, primitive.y2),
    };
  }
  if (primitive.type === "CIRCLE" || primitive.type === "ARC") {
    return {
      minX: primitive.x - primitive.radius,
      minY: primitive.y - primitive.radius,
      maxX: primitive.x + primitive.radius,
      maxY: primitive.y + primitive.radius,
    };
  }
  if (primitive.type === "TEXT") {
    const width = Math.max(primitive.height, String(primitive.text || "").length * primitive.height * 0.62);
    return {
      minX: primitive.x,
      minY: primitive.y,
      maxX: primitive.x + width,
      maxY: primitive.y + primitive.height,
    };
  }
  if (primitive.type === "LWPOLYLINE") {
    const xs = primitive.points.map((point) => point.x);
    const ys = primitive.points.map((point) => point.y);
    return {
      minX: Math.min(...xs),
      minY: Math.min(...ys),
      maxX: Math.max(...xs),
      maxY: Math.max(...ys),
    };
  }
  return null;
}

function mergeDrawingDxfBounds(boundsList = []) {
  const visibleBounds = boundsList.filter(Boolean);
  if (!visibleBounds.length) {
    return null;
  }
  return visibleBounds.reduce((result, bounds) => ({
    minX: Math.min(result.minX, bounds.minX),
    minY: Math.min(result.minY, bounds.minY),
    maxX: Math.max(result.maxX, bounds.maxX),
    maxY: Math.max(result.maxY, bounds.maxY),
  }), { ...visibleBounds[0] });
}

function translateDrawingDxfPrimitive(primitive = null, dx = 0, dy = 0) {
  if (!primitive) {
    return null;
  }
  if (primitive.type === "LINE") {
    return { ...primitive, x1: primitive.x1 + dx, y1: primitive.y1 + dy, x2: primitive.x2 + dx, y2: primitive.y2 + dy };
  }
  if (primitive.type === "CIRCLE" || primitive.type === "ARC" || primitive.type === "TEXT") {
    return { ...primitive, x: primitive.x + dx, y: primitive.y + dy };
  }
  if (primitive.type === "LWPOLYLINE") {
    return { ...primitive, points: primitive.points.map((point) => ({ x: point.x + dx, y: point.y + dy })) };
  }
  return primitive;
}

function escapeDrawingDxfText(text = "") {
  return String(text || "").replace(/[\r\n]+/g, " ").replace(/[^\S ]+/g, " ").trim();
}

function renderDrawingDxfPrimitiveMarkup(primitive = null) {
  if (!primitive) {
    return "";
  }
  const layer = escapeDrawingDxfText(primitive.layer || "0") || "0";
  if (primitive.type === "LINE") {
    return `0\nLINE\n8\n${layer}\n10\n${primitive.x1}\n20\n${primitive.y1}\n30\n0\n11\n${primitive.x2}\n21\n${primitive.y2}\n31\n0\n62\n7\n`;
  }
  if (primitive.type === "CIRCLE") {
    return `0\nCIRCLE\n8\n${layer}\n10\n${primitive.x}\n20\n${primitive.y}\n30\n0\n40\n${primitive.radius}\n62\n7\n`;
  }
  if (primitive.type === "ARC") {
    return `0\nARC\n8\n${layer}\n10\n${primitive.x}\n20\n${primitive.y}\n30\n0\n40\n${primitive.radius}\n50\n${primitive.startAngle}\n51\n${primitive.endAngle}\n62\n7\n`;
  }
  if (primitive.type === "TEXT") {
    return `0\nTEXT\n8\n${layer}\n10\n${primitive.x}\n20\n${primitive.y}\n30\n0\n40\n${primitive.height}\n1\n${escapeDrawingDxfText(primitive.text)}\n50\n${primitive.rotation || 0}\n62\n7\n`;
  }
  if (primitive.type === "LWPOLYLINE") {
    const pointsMarkup = primitive.points
      .map((point) => `10\n${point.x}\n20\n${point.y}`)
      .join("\n");
    return `0\nLWPOLYLINE\n8\n${layer}\n90\n${primitive.points.length}\n70\n${primitive.closed ? 1 : 0}\n${pointsMarkup}\n62\n7\n`;
  }
  return "";
}

function createDrawingDxfBlockPreview(dxfText = "") {
  const pairs = parseDrawingDxfPairs(dxfText);
  const supportedEntityTypes = new Set(["LINE", "CIRCLE", "ARC", "TEXT", "MTEXT", "LWPOLYLINE"]);
  const blocks = [];
  let inBlocksSection = false;
  let waitingForSectionName = false;
  let currentBlock = null;
  let currentEntity = null;

  const finishEntity = () => {
    if (currentBlock && currentEntity && supportedEntityTypes.has(currentEntity.type)) {
      const primitive = createDrawingDxfPrimitive(currentEntity);
      if (primitive) {
        currentBlock.primitives.push(primitive);
      }
    }
    currentEntity = null;
  };

  const finishBlock = () => {
    finishEntity();
    if (currentBlock?.name && !currentBlock.name.startsWith("*") && currentBlock.primitives.length) {
      currentBlock.bounds = mergeDrawingDxfBounds(currentBlock.primitives.map(getDrawingDxfPrimitiveBounds));
      if (currentBlock.bounds) {
        blocks.push(currentBlock);
      }
    }
    currentBlock = null;
  };

  pairs.forEach((pair) => {
    const code = pair.code;
    const value = String(pair.value || "").trim();
    const upperValue = value.toUpperCase();

    if (waitingForSectionName && code === "2") {
      inBlocksSection = upperValue === "BLOCKS";
      waitingForSectionName = false;
      return;
    }

    if (code === "0" && upperValue === "SECTION") {
      finishBlock();
      waitingForSectionName = true;
      inBlocksSection = false;
      return;
    }

    if (code === "0" && upperValue === "ENDSEC") {
      finishBlock();
      inBlocksSection = false;
      waitingForSectionName = false;
      return;
    }

    if (!inBlocksSection) {
      return;
    }

    if (code === "0" && upperValue === "BLOCK") {
      finishBlock();
      currentBlock = { name: "", primitives: [] };
      return;
    }

    if (!currentBlock) {
      return;
    }

    if (code === "0" && upperValue === "ENDBLK") {
      finishBlock();
      return;
    }

    if (code === "0" && supportedEntityTypes.has(upperValue)) {
      finishEntity();
      currentEntity = { type: upperValue, pairs: [] };
      return;
    }

    if (code === "0") {
      finishEntity();
      return;
    }

    if (!currentBlock.name && code === "2") {
      currentBlock.name = value;
    }

    if (currentEntity) {
      currentEntity.pairs.push(pair);
    }
  });
  finishBlock();

  if (!blocks.length) {
    return null;
  }

  const maxWidth = Math.max(...blocks.map((block) => Math.max(1, block.bounds.maxX - block.bounds.minX)), 120);
  const maxHeight = Math.max(...blocks.map((block) => Math.max(1, block.bounds.maxY - block.bounds.minY)), 120);
  const gap = Math.max(80, Math.max(maxWidth, maxHeight) * 0.35);
  const columns = Math.max(1, Math.ceil(Math.sqrt(blocks.length)));
  const cellWidth = maxWidth + gap;
  const cellHeight = maxHeight + gap;
  const primitives = [];

  blocks.forEach((block, index) => {
    const column = index % columns;
    const row = Math.floor(index / columns);
    const originX = column * cellWidth;
    const originY = row * cellHeight;
    const dx = originX - block.bounds.minX;
    const dy = originY - block.bounds.minY;
    block.primitives.forEach((primitive) => {
      primitives.push(translateDrawingDxfPrimitive(primitive, dx, dy));
    });
    primitives.push({
      type: "TEXT",
      layer: "BLOCK_PREVIEW",
      x: originX,
      y: originY + maxHeight + Math.max(20, gap * 0.18),
      height: Math.max(12, Math.min(28, maxHeight * 0.08)),
      rotation: 0,
      text: block.name,
    });
  });

  const layerNames = Array.from(new Set([
    "0",
    "BLOCK_PREVIEW",
    ...primitives.map((primitive) => String(primitive?.layer || "0").trim() || "0"),
  ]));
  const layerTable = [
    "0\nSECTION\n2\nTABLES",
    `0\nTABLE\n2\nLAYER\n70\n${layerNames.length}`,
    layerNames.map((layerName) => `0\nLAYER\n2\n${escapeDrawingDxfText(layerName) || "0"}\n70\n0\n62\n7\n6\nContinuous`).join("\n"),
    "0\nENDTAB\n0\nENDSEC",
  ].join("\n");
  const dxf = [
    layerTable,
    "0\nSECTION\n2\nENTITIES",
    primitives.map(renderDrawingDxfPrimitiveMarkup).join(""),
    "0\nENDSEC\n0\nEOF",
  ].join("\n");

  return {
    dxfText: dxf,
    blockCount: blocks.length,
    entityCount: primitives.length,
    blockNames: blocks.map((block) => block.name),
  };
}

function readDrawingDataUrlAsArrayBuffer(dataUrl = "") {
  const source = String(dataUrl || "").trim();
  const commaIndex = source.indexOf(",");
  if (!source.startsWith("data:") || commaIndex < 0) {
    throw new Error("CAD data URL nije ispravan.");
  }

  const header = source.slice(0, commaIndex);
  const payload = source.slice(commaIndex + 1);
  if (/;base64/i.test(header)) {
    const cleanPayload = payload.replace(/\s+/g, "");
    const binary = atob(cleanPayload);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) {
      bytes[index] = binary.charCodeAt(index);
    }
    return bytes.buffer;
  }

  return new TextEncoder().encode(decodeURIComponent(payload)).buffer;
}

async function readDrawingReferenceArrayBuffer(reference = null) {
  if (!reference) {
    throw new Error("Nema aktivne CAD podloge.");
  }

  const drawingId = String(drawingProjectDraft?.id || state.activeDrawingId || "").trim();
  const referenceId = String(reference.id || "").trim();
  const dataUrl = String(reference.dataUrl || "").trim();
  const storageUrl = String(reference.storageUrl || "").trim();
  const organizationHeader = state.activeOrganizationId
    ? { "X-Organization-Id": state.activeOrganizationId }
    : {};

  if (dataUrl.startsWith("data:")) {
    return readDrawingDataUrlAsArrayBuffer(dataUrl);
  }

  if (drawingId && referenceId) {
    const response = await fetch(`${API_BASE}/drawings/${encodeURIComponent(drawingId)}/references/${encodeURIComponent(referenceId)}/content`, {
      headers: organizationHeader,
      credentials: "same-origin",
    });

    if (response.status === 401) {
      const refreshed = await requestTokenRefresh();
      if (refreshed) {
        return readDrawingReferenceArrayBuffer(reference);
      }
    }

    if (response.ok) {
      return response.arrayBuffer();
    }
  }

  if (storageUrl) {
    const response = await fetch(storageUrl, { credentials: "same-origin" });
    if (!response.ok) {
      throw new Error(`Preuzimanje CAD podloge nije uspjelo (${response.status}).`);
    }
    return response.arrayBuffer();
  }

  throw new Error("CAD datoteku nije moguće pročitati.");
}

async function ensureDrawingCadViewer() {
  if (drawingCadViewerState.viewer) {
    return drawingCadViewerState.viewer;
  }

  if (!drawingStageCadCanvas) {
    throw new Error("CAD canvas nije pronađen.");
  }

  if (!drawingCadViewerState.runtimePromise) {
    drawingCadViewerState.runtimePromise = Promise.all([
      import(`/assets/vendor/cadview-core.js?v=${DRAWING_VENDOR_VERSION}`),
      import(`/assets/vendor/cadview-dwg.js?v=${DRAWING_VENDOR_VERSION}`),
    ])
      .then(([coreModule, dwgModule]) => {
        const dwgFormatConverter = dwgModule?.isDwg && dwgModule?.convertDwgToDxf
          ? {
            detect: (buffer) => dwgModule.isDwg(buffer),
            convert: (buffer) => dwgModule.convertDwgToDxf(buffer, {
              wasmUrl: getDrawingCadWasmUrl(),
              timeout: 60000,
            }),
          }
          : null;
        const viewer = new coreModule.CadViewer(drawingStageCadCanvas, {
          theme: "light",
          initialTool: "pan",
          worker: true,
          formatConverters: dwgFormatConverter ? [dwgFormatConverter] : [],
        });
        viewer.setBackgroundColor?.("#f8fbff");
        viewer.setTheme?.("light");
        viewer.setTool?.("pan");
        drawingCadViewerState.viewer = viewer;
        drawingCadViewerState.dwgModule = dwgModule;
        return viewer;
      })
      .catch((error) => {
        drawingCadViewerState.runtimePromise = null;
        drawingCadViewerState.dwgModule = null;
        throw error;
      });
  }

  return drawingCadViewerState.runtimePromise;
}

function resetDrawingCadViewer() {
  drawingCadViewerState.loadGeneration += 1;
  drawingCadViewerState.activeKey = "";
  drawingCadViewerState.rasterDataUrl = "";
  drawingCadViewerState.meta = null;
  drawingCadViewerState.viewer?.clearDocument?.();
  if (drawingStageCadCanvas) {
    drawingStageCadCanvas.hidden = true;
  }
}

async function renderDrawingCadReference(reference = null) {
  if (!reference || !isDrawingCadReference(reference) || !drawingStageCadCanvas) {
    resetDrawingCadViewer();
    return;
  }

  const previewKey = [
    reference.id,
    reference.updatedAt,
    reference.fileName,
    reference.fileSize,
  ].filter(Boolean).join(":");

  const generation = drawingCadViewerState.loadGeneration + 1;
  drawingCadViewerState.loadGeneration = generation;
  const viewer = await ensureDrawingCadViewer();
  if (generation !== drawingCadViewerState.loadGeneration) {
    return;
  }
  drawingStageCadCanvas.hidden = false;
  viewer.resize?.();

  if (drawingCadViewerState.activeKey !== previewKey) {
    const startedAt = performance.now();
    let dxfText = "";
    let fallbackPreview = null;
    showDrawingCadStatus(`Pripremam ${getDrawingCadKindLabel(reference)} podlogu ${String(reference.fileName || "").trim() || "datoteka"}...`, "info");
    const buffer = await readDrawingReferenceArrayBuffer(reference);
    if (generation !== drawingCadViewerState.loadGeneration) {
      return;
    }

    if (isDrawingDxfReference(reference)) {
      showDrawingCadStatus("Učitavam DXF geometriju...", "info");
      dxfText = new TextDecoder().decode(buffer.slice(0));
      await viewer.loadBuffer(buffer.slice(0));
    } else {
      const dwgModule = drawingCadViewerState.dwgModule;
      if (!dwgModule?.isDwg?.(buffer)) {
        throw new Error("Datoteka ima DWG ekstenziju, ali sadržaj nije prepoznat kao DWG.");
      }

      const versionLabel = getDrawingCadVersionLabel(buffer, dwgModule);
      showDrawingCadStatus(
        `Konvertiram DWG${versionLabel ? ` (${versionLabel})` : ""} u browseru...`,
        "info",
      );
      const convertedDxfText = await dwgModule.convertDwgToDxf(buffer.slice(0), {
        wasmUrl: getDrawingCadWasmUrl(),
        timeout: 60000,
      });
      dxfText = convertedDxfText;
      if (generation !== drawingCadViewerState.loadGeneration) {
        return;
      }

      showDrawingCadStatus("Crtam CAD pregled...", "info");
      const dxfBuffer = new TextEncoder().encode(dxfText).buffer;
      await viewer.loadBuffer(dxfBuffer);
    }
    if (!getDrawingCadViewerEntityCount(viewer) && dxfText) {
      fallbackPreview = createDrawingDxfBlockPreview(dxfText);
      if (fallbackPreview?.dxfText) {
        showDrawingCadStatus("Model Space je prazan, prikazujem blokove iz DWG templatea...", "info");
        await viewer.loadBuffer(new TextEncoder().encode(fallbackPreview.dxfText).buffer);
      }
    }
    if (generation !== drawingCadViewerState.loadGeneration) {
      return;
    }
    viewer.resize?.();
    viewer.fitToView();
    drawingCadViewerState.activeKey = previewKey;
    drawingCadViewerState.meta = getDrawingCadLoadedSummary(viewer, reference, performance.now() - startedAt, fallbackPreview
      ? { note: `${fallbackPreview.blockCount} blokova iz templatea` }
      : {});
    reference.previewStatus = "ready";
    reference.previewError = "";
  } else {
    viewer.resize?.();
  }

  renderDrawingReferenceList();
  const successText = getDrawingCadLoadedSummaryText(drawingCadViewerState.meta);
  showDrawingCadStatus(successText, "success");
  window.setTimeout(() => {
    if (drawingCadViewerState.activeKey === previewKey) {
      showDrawingCadStatus("");
    }
  }, 2400);

  requestAnimationFrame(() => {
    try {
      drawingCadViewerState.rasterDataUrl = drawingStageCadCanvas.toDataURL("image/png");
    } catch {
      drawingCadViewerState.rasterDataUrl = "";
    }
  });
}

function setDrawingViewMode(nextMode = "canvas") {
  const activeReference = getDrawingActiveReference();
  if (nextMode === "reference" && !activeReference) {
    drawingViewMode = "canvas";
    return;
  }

  drawingViewMode = nextMode === "reference" ? "reference" : "canvas";
}

function syncDrawingSidebarUi() {
  const shell = drawingSidebar?.closest(".drawing-studio-shell");
  shell?.classList.toggle("is-sidebar-collapsed", drawingSidebarCollapsed === true);

  if (drawingSidebarToggleButton) {
    drawingSidebarToggleButton.setAttribute("aria-expanded", drawingSidebarCollapsed === true ? "false" : "true");
  }
  if (drawingSidebarToggleLabel) {
    drawingSidebarToggleLabel.textContent = drawingSidebarCollapsed === true ? "Alati" : "Sakrij";
  }

  drawingSidebarTabButtons.forEach((button) => {
    const isActive = button.dataset.drawingSidebarTab === drawingSidebarTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });

  drawingSidebarPanels.forEach((panel) => {
    panel.hidden = drawingSidebarCollapsed === true || panel.dataset.drawingSidebarPanel !== drawingSidebarTab;
  });
}

function syncDrawingViewModeUi() {
  const activeReference = getDrawingActiveReference();
  const hasReference = Boolean(activeReference);
  drawingViewModeButtons.forEach((button) => {
    const isActive = button.dataset.drawingView === drawingViewMode;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
    if (button.dataset.drawingView === "reference") {
      button.disabled = !hasReference;
    }
  });
}

function getDrawingCurveControlPoint(element = {}) {
  const startX = Number(element.x || 0);
  const startY = Number(element.y || 0);
  const endX = Number(element.x2 || startX);
  const endY = Number(element.y2 || startY);
  const midX = (startX + endX) / 2;
  const midY = (startY + endY) / 2;
  const deltaX = endX - startX;
  const deltaY = endY - startY;
  const length = Math.max(1, Math.sqrt((deltaX ** 2) + (deltaY ** 2)));
  const normalX = -deltaY / length;
  const normalY = deltaX / length;
  const direction = Number(element.metadata?.curveDirection || 1) >= 0 ? 1 : -1;
  const offset = Math.max(40, Math.min(220, Number(element.metadata?.curveOffset || Math.max(Math.abs(deltaY), 72))));
  return {
    x: Math.round((midX + normalX * offset * direction) * 10) / 10,
    y: Math.round((midY + normalY * offset * direction) * 10) / 10,
  };
}

function applyDrawingOrthoConstraint(startPoint = { x: 0, y: 0 }, point = { x: 0, y: 0 }, tool = "") {
  if (drawingViewportDraft.orthoMode !== true || !DRAWING_LINEAR_TYPES.has(String(tool || "").trim().toLowerCase())) {
    return point;
  }

  const deltaX = Number(point.x || 0) - Number(startPoint.x || 0);
  const deltaY = Number(point.y || 0) - Number(startPoint.y || 0);
  if (Math.abs(deltaX) >= Math.abs(deltaY)) {
    return {
      x: point.x,
      y: startPoint.y,
    };
  }

  return {
    x: startPoint.x,
    y: point.y,
  };
}

function syncDrawingActiveLayerForTool(tool = "rectangle") {
  const preferredLayerName = getDrawingPreferredLayerName(tool);
  if (!preferredLayerName) {
    return;
  }
  const preferredLayer = drawingLayerDrafts.find((layer) => String(layer.name || "").trim().toLowerCase() === preferredLayerName.toLowerCase());
  if (preferredLayer) {
    drawingActiveLayerId = String(preferredLayer.id);
  }
}

function getDrawingStageInsertPoint() {
  const zoom = Math.max(0.5, Math.min(2.5, Number(drawingViewportDraft.zoom || 1)));
  const viewportWidth = Math.max(320, Number(drawingStageScroll?.clientWidth || 760));
  const viewportHeight = Math.max(240, Number(drawingStageScroll?.clientHeight || 640));
  const scrollLeft = Number(drawingStageScroll?.scrollLeft || 0);
  const scrollTop = Number(drawingStageScroll?.scrollTop || 0);
  const x = (scrollLeft + viewportWidth / 2) / zoom;
  const y = (scrollTop + viewportHeight / 2) / zoom;
  return {
    x: Math.max(40, Math.round(x)),
    y: Math.max(40, Math.round(y)),
  };
}

function getDrawingDimensionLabel(element = {}) {
  const deltaX = Number(element.x2 || 0) - Number(element.x || 0);
  const deltaY = Number(element.y2 || 0) - Number(element.y || 0);
  const length = Math.max(0, Math.round(Math.sqrt((deltaX ** 2) + (deltaY ** 2))));
  return `${length} ${DRAWING_DIMENSION_UNIT}`;
}

function syncDrawingElementDerivedFields(element = {}) {
  const next = {
    ...element,
    metadata: { ...(element.metadata ?? {}) },
  };
  const type = String(next.type || "").trim().toLowerCase();

  if (DRAWING_LINEAR_TYPES.has(type)) {
    next.width = Math.abs(Number(next.x2 || 0) - Number(next.x || 0));
    next.height = Math.abs(Number(next.y2 || 0) - Number(next.y || 0));
  } else {
    next.x2 = Number(next.x2 ?? (Number(next.x || 0) + Number(next.width || 0)));
    next.y2 = Number(next.y2 ?? (Number(next.y || 0) + Number(next.height || 0)));
  }

  if (type === "dimension" && next.metadata.autoLabel !== false) {
    next.label = getDrawingDimensionLabel(next);
    next.metadata.autoLabel = true;
    next.metadata.unit = DRAWING_DIMENSION_UNIT;
  }

  if (!DRAWING_ROTATABLE_TYPES.has(type)) {
    next.rotation = 0;
  }

  return next;
}

function createDrawingEmptyDraft(overrides = {}) {
  const companyId = String(overrides.companyId || state.companies[0]?.id || "").trim();
  const locationId = String(
    overrides.locationId
    || (companyId ? (state.locations.find((item) => String(item.companyId) === companyId)?.id ?? "") : "")
    || "",
  ).trim();
  return {
    id: "",
    organizationId: String(state.activeOrganizationId || overrides.organizationId || "").trim(),
    companyId,
    locationId,
    title: "",
    drawingType: "evacuation",
    status: "draft",
    scaleLabel: "",
    note: "",
    createdByUserId: String(state.user?.id || "").trim(),
    createdByLabel: getUserDisplayLabel(state.user ?? {}),
  };
}

function cloneDrawingElementDraft(item = {}) {
  return {
    ...item,
    metadata: { ...(item.metadata ?? {}) },
  };
}

function loadDrawingDraft(project = null) {
  drawingProjectDraft = project
    ? {
      id: String(project.id || "").trim(),
      organizationId: String(project.organizationId || state.activeOrganizationId || "").trim(),
      companyId: String(project.companyId || "").trim(),
      locationId: String(project.locationId || "").trim(),
      title: String(project.title || "").trim(),
      drawingType: String(project.drawingType || "custom").trim() || "custom",
      status: String(project.status || "draft").trim() || "draft",
      scaleLabel: String(project.scaleLabel || "").trim(),
      note: String(project.note || "").trim(),
      createdByUserId: String(project.createdByUserId || "").trim(),
      createdByLabel: String(project.createdByLabel || "").trim(),
    }
    : createDrawingEmptyDraft();
  drawingReferenceDrafts = (project?.referenceDocuments ?? []).map((document) => createModuleAttachmentDraft({
    ...document,
    isPersisted: true,
  }));
  drawingLayerDrafts = (project?.layers ?? []).length > 0
    ? (project.layers ?? []).map((layer, index) => createDrawingLayerDraft(index, layer))
    : createDrawingDefaultLayers();
  drawingElementDrafts = (project?.elements ?? []).map((item) => cloneDrawingElementDraft(item));
  drawingViewportDraft = {
    zoom: Math.max(0.5, Math.min(2.5, Number(project?.viewport?.zoom ?? 1) || 1)),
    gridSize: Math.max(8, Math.min(80, Math.round(Number(project?.viewport?.gridSize ?? 20) || 20))),
    canvasWidth: clampDrawingCanvasWidth(project?.viewport?.canvasWidth ?? DRAWING_STAGE_DEFAULT_WIDTH),
    canvasHeight: clampDrawingCanvasHeight(project?.viewport?.canvasHeight ?? DRAWING_STAGE_DEFAULT_HEIGHT),
    snapToGrid: project?.viewport?.snapToGrid !== false,
    showGrid: project?.viewport?.showGrid !== false,
    orthoMode: project?.viewport?.orthoMode === true,
  };
  const visibleReferences = drawingReferenceDrafts.filter((document) => !isDrawingDerivedReference(document));
  drawingActiveReferenceId = String(
    project?.activeReferenceDocumentId
    || visibleReferences[0]?.id
    || "",
  ).trim();
  drawingSelectedElementId = "";
  drawingActiveLayerId = drawingLayerDrafts[0]?.id || "";
  drawingCurrentTool = "select";
  drawingViewMode = drawingActiveReferenceId ? "reference" : "canvas";
  drawingSidebarCollapsed = true;
  drawingSidebarTab = "symbols";
  drawingPointerSession = null;
  drawingCursorPositionDraft = { x: 0, y: 0 };
  resetDrawingCadViewer();
  showDrawingCadStatus("");
  if (drawingError) {
    drawingError.textContent = "";
  }
}

function resetDrawingForm() {
  state.activeDrawingId = "";
  loadDrawingDraft(null);
  renderDrawingStudioModule();
}

function getDrawingProjectById(projectId = "") {
  return (state.drawings ?? []).find((item) => String(item.id) === String(projectId)) ?? null;
}

function getFilteredDrawingProjects() {
  return sortDrawingProjects(filterDrawingProjects(state.drawings ?? [], {
    query: drawingSearchInput?.value || "",
    status: drawingFilterStatusInput?.value || "all",
    companyId: drawingFilterCompanyInput?.value || "all",
  }));
}

function renderDrawingSelectOptions() {
  if (drawingFilterStatusInput) {
    const currentValue = drawingFilterStatusInput.value || "all";
    drawingFilterStatusInput.replaceChildren(
      new Option("Svi statusi", "all"),
      ...DRAWING_PROJECT_STATUS_OPTIONS.map((option) => new Option(option.label, option.value)),
    );
    drawingFilterStatusInput.value = currentValue;
  }

  if (drawingFilterCompanyInput) {
    const currentValue = drawingFilterCompanyInput.value || "all";
    drawingFilterCompanyInput.replaceChildren(
      new Option("Sve tvrtke", "all"),
      ...getSortedDrawingCompanies(state.companies).map((company) => new Option(company.name || "Tvrtka", String(company.id))),
    );
    drawingFilterCompanyInput.value = Array.from(drawingFilterCompanyInput.options).some((option) => option.value === currentValue)
      ? currentValue
      : "all";
  }

  if (drawingCompanyIdInput) {
    const currentValue = drawingProjectDraft?.companyId || "";
    drawingCompanyIdInput.replaceChildren(
      new Option("Bez tvrtke", ""),
      ...getSortedDrawingCompanies(state.companies).map((company) => new Option(company.name || "Tvrtka", String(company.id))),
    );
    drawingCompanyIdInput.value = Array.from(drawingCompanyIdInput.options).some((option) => option.value === currentValue)
      ? currentValue
      : "";
  }

  if (drawingTypeInput) {
    const currentValue = drawingProjectDraft?.drawingType || "evacuation";
    drawingTypeInput.replaceChildren(...DRAWING_PROJECT_TYPE_OPTIONS.map((option) => new Option(option.label, option.value)));
    drawingTypeInput.value = Array.from(drawingTypeInput.options).some((option) => option.value === currentValue)
      ? currentValue
      : DRAWING_PROJECT_TYPE_OPTIONS[0]?.value || "custom";
  }

  if (drawingStatusInput) {
    const currentValue = drawingProjectDraft?.status || "draft";
    drawingStatusInput.replaceChildren(...DRAWING_PROJECT_STATUS_OPTIONS.map((option) => new Option(option.label, option.value)));
    drawingStatusInput.value = Array.from(drawingStatusInput.options).some((option) => option.value === currentValue)
      ? currentValue
      : DRAWING_PROJECT_STATUS_OPTIONS[0]?.value || "draft";
  }
}

function syncDrawingLocationOptions() {
  if (!drawingLocationIdInput) {
    return;
  }

  const companyId = String(drawingProjectDraft?.companyId || "").trim();
  const locations = companyId
    ? getSortedDrawingLocations(state.locations.filter((item) => String(item.companyId) === companyId))
    : [];
  const currentValue = String(drawingProjectDraft?.locationId || "").trim();
  drawingLocationIdInput.replaceChildren(
    new Option("Bez lokacije", ""),
    ...locations.map((location) => new Option(location.name || "Lokacija", String(location.id))),
  );
  drawingLocationIdInput.value = Array.from(drawingLocationIdInput.options).some((option) => option.value === currentValue)
    ? currentValue
    : "";
  if (drawingProjectDraft) {
    drawingProjectDraft.locationId = drawingLocationIdInput.value;
  }
}

function renderDrawingProjectList() {
  if (!drawingList || !drawingEmpty) {
    return;
  }

  const items = getFilteredDrawingProjects();
  drawingEmpty.hidden = items.length > 0;

  if (items.length === 0) {
    drawingList.replaceChildren();
    return;
  }

  drawingList.replaceChildren(...items.map((item) => {
    const card = document.createElement("article");
    card.className = "drawing-project-card";
    if (String(item.id) === String(state.activeDrawingId || drawingProjectDraft?.id || "")) {
      card.classList.add("is-active");
    }

    const head = document.createElement("div");
    head.className = "drawing-project-card-head";

    const titleWrap = document.createElement("div");
    const kicker = document.createElement("span");
    kicker.className = "drawing-project-card-kicker";
    kicker.textContent = getOptionLabel(DRAWING_PROJECT_TYPE_OPTIONS, item.drawingType) || "Crtez";
    const title = document.createElement("h4");
    title.textContent = item.title || "Novi crtež";
    titleWrap.append(kicker, title);

    const statusBadge = document.createElement("span");
    statusBadge.className = `drawing-project-card-badge is-${item.status || "draft"}`;
    statusBadge.textContent = getOptionLabel(DRAWING_PROJECT_STATUS_OPTIONS, item.status) || "Skica";
    head.append(titleWrap, statusBadge);

    const meta = document.createElement("div");
    meta.className = "drawing-project-card-meta";
    [
      item.companyName || "Bez tvrtke",
      item.locationName || "Bez lokacije",
      item.scaleLabel || "Bez mjerila",
      `${(item.layers ?? []).length} layera`,
      `${(item.elements ?? []).length} elemenata`,
    ].filter(Boolean).forEach((value) => {
      const chip = document.createElement("span");
      chip.className = "drawing-layer-count";
      chip.textContent = value;
      meta.append(chip);
    });

    const note = document.createElement("p");
    note.textContent = item.note || "DWG/PDF podloga, layeri i CAD elementi.";

    card.append(head, meta, note);
    card.addEventListener("click", () => {
      state.activeDrawingId = String(item.id);
      loadDrawingDraft(item);
      renderDrawingStudioModule();
    });
    return card;
  }));
}

function renderDrawingReferenceList() {
  if (!drawingReferenceList || !drawingReferenceEmpty) {
    return;
  }

  const visibleReferences = getDrawingVisibleReferenceDrafts();
  drawingReferenceEmpty.hidden = visibleReferences.length > 0;

  if (visibleReferences.length === 0) {
    drawingReferenceList.replaceChildren();
    return;
  }

  drawingReferenceList.replaceChildren(...visibleReferences.map((entry) => {
    const card = document.createElement("article");
    card.className = "drawing-reference-card";
    if (String(entry.id) === String(drawingActiveReferenceId)) {
      card.classList.add("is-active");
    }

    const head = document.createElement("div");
    head.className = "drawing-reference-card-head";
    const title = document.createElement("strong");
    title.textContent = entry.fileName || "Podloga";
    const type = document.createElement("span");
    type.className = "drawing-reference-type";
    const extension = String(entry.fileName || "").split(".").pop()?.toUpperCase() || "FILE";
    type.textContent = extension;
    head.append(title, type);

    const meta = document.createElement("p");
    const previewReference = getDrawingRenderableReference(entry);
    const previewReady = previewReference && String(previewReference.id || "") !== String(entry.id || "");
    const previewStatusLabel = entry.previewStatus === "error"
      ? "DXF preview greška"
      : entry.previewStatus === "ready"
        ? `${extension === "DWG" || extension === "DXF" ? "CAD" : "DXF"} pregled spreman`
        : entry.previewStatus === "pending"
          ? `${extension === "DWG" ? "DWG preview se priprema" : "Čeka CAD preview"}`
          : "";
    meta.textContent = [
      formatFileSize(entry.fileSize),
      entry.fileType || "",
      previewReady ? "DXF preview spreman" : previewStatusLabel,
      entry.previewError || "",
      entry.updatedAt ? formatCompactDateTime(entry.updatedAt) : "",
    ].filter(Boolean).join(" · ");

    const actions = document.createElement("div");
    actions.className = "drawing-reference-card-actions";

    const activateButton = document.createElement("button");
    activateButton.type = "button";
    activateButton.className = "ghost-button";
    activateButton.textContent = String(entry.id) === String(drawingActiveReferenceId) ? "Aktivno" : "Prikaži";
    activateButton.addEventListener("click", () => {
      drawingActiveReferenceId = String(entry.id);
      setDrawingViewMode("reference");
      drawingSidebarTab = "references";
      renderDrawingStudioModule();
    });

    const downloadButton = document.createElement("button");
    downloadButton.type = "button";
    downloadButton.className = "ghost-button";
    downloadButton.textContent = "Preuzmi";
    downloadButton.addEventListener("click", () => {
      triggerModuleAttachmentDownload(entry);
    });

    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "ghost-button card-danger";
    removeButton.textContent = "Makni";
    removeButton.addEventListener("click", () => {
      drawingReferenceDrafts = drawingReferenceDrafts.filter((item) => (
        String(item.id) !== String(entry.id)
        && String(item.sourceDocumentId || "").trim() !== String(entry.id)
      ));
      if (String(drawingActiveReferenceId) === String(entry.id)) {
        drawingActiveReferenceId = getDrawingVisibleReferenceDrafts()[0]?.id || "";
      }
      if (!drawingActiveReferenceId) {
        setDrawingViewMode("canvas");
      }
      renderDrawingStudioModule();
    });

    actions.append(activateButton, downloadButton, removeButton);
    card.append(head, meta, actions);
    return card;
  }));
}

function renderDrawingLayerList() {
  if (!drawingLayerList) {
    return;
  }

  drawingLayerList.replaceChildren(...drawingLayerDrafts.map((layer) => {
    const row = document.createElement("article");
    row.className = "drawing-layer-row";

    const main = document.createElement("div");
    main.className = "drawing-layer-main";
    const swatch = document.createElement("span");
    swatch.className = "drawing-layer-swatch";
    swatch.style.background = layer.color || "#4564d1";
    const copy = document.createElement("div");
    const title = document.createElement("strong");
    title.textContent = layer.name || "Layer";
    const meta = document.createElement("div");
    meta.className = "drawing-layer-meta";
    [layer.visible === false ? "Sakriven" : "Vidljiv", layer.locked ? "Zaključan" : "Otključan", `${layer.lineWidth || 1}px`].forEach((value) => {
      const chip = document.createElement("span");
      chip.className = "drawing-layer-count";
      chip.textContent = value;
      meta.append(chip);
    });
    copy.append(title, meta);
    main.append(swatch, copy);

    const actions = document.createElement("div");
    actions.className = "drawing-layer-actions";

    const activateButton = document.createElement("button");
    activateButton.type = "button";
    activateButton.className = "drawing-layer-toggle";
    activateButton.title = "Aktivni layer";
    activateButton.textContent = String(layer.id) === String(getDrawingActiveLayer()?.id || "") ? "●" : "○";
    activateButton.addEventListener("click", () => {
      drawingActiveLayerId = String(layer.id);
      renderDrawingStudioModule();
    });

    const visibleButton = document.createElement("button");
    visibleButton.type = "button";
    visibleButton.className = "drawing-layer-toggle";
    visibleButton.title = "Prikaži / sakrij";
    visibleButton.textContent = layer.visible === false ? "S" : "V";
    visibleButton.addEventListener("click", () => {
      layer.visible = layer.visible === false;
      renderDrawingStudioModule();
    });

    const lockButton = document.createElement("button");
    lockButton.type = "button";
    lockButton.className = "drawing-layer-toggle";
    lockButton.title = "Zaključaj";
    lockButton.textContent = layer.locked ? "L" : "O";
    lockButton.addEventListener("click", () => {
      layer.locked = !layer.locked;
      renderDrawingStudioModule();
    });

    const colorInput = document.createElement("input");
    colorInput.type = "color";
    colorInput.value = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(layer.color || "") ? layer.color : "#4564d1";
    colorInput.addEventListener("input", () => {
      layer.color = colorInput.value;
      renderDrawingStudioModule();
    });

    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "drawing-layer-toggle";
    removeButton.title = "Makni layer";
    removeButton.textContent = "×";
    removeButton.disabled = drawingLayerDrafts.length <= 1;
    removeButton.addEventListener("click", () => {
      if (drawingLayerDrafts.length <= 1) {
        return;
      }
      const fallbackLayer = drawingLayerDrafts.find((item) => String(item.id) !== String(layer.id)) ?? null;
      drawingLayerDrafts = drawingLayerDrafts.filter((item) => String(item.id) !== String(layer.id));
      if (fallbackLayer) {
        drawingElementDrafts = drawingElementDrafts.map((item) => (
          String(item.layerId) === String(layer.id)
            ? { ...item, layerId: String(fallbackLayer.id) }
            : item
        ));
        drawingActiveLayerId = String(fallbackLayer.id);
      }
      renderDrawingStudioModule();
    });

    actions.append(activateButton, visibleButton, lockButton, colorInput, removeButton);
    row.append(main, actions);
    return row;
  }));
}

function renderDrawingInspector() {
  const selected = drawingElementDrafts.find((item) => String(item.id) === String(drawingSelectedElementId)) ?? null;
  const layerValue = selected?.layerId || getDrawingActiveLayer()?.id || "";
  const layerOptions = [
    new Option("Odaberi layer", ""),
    ...drawingLayerDrafts.map((layer) => new Option(layer.name || "Layer", String(layer.id))),
  ];
  drawingSelectedLayerInput?.replaceChildren(...layerOptions);
  if (drawingSelectedLayerInput) {
    drawingSelectedLayerInput.value = layerValue;
    drawingSelectedLayerInput.disabled = !selected;
  }

  const hasSelected = Boolean(selected);
  if (drawingSelectedTitle) {
    drawingSelectedTitle.textContent = hasSelected
      ? `${selected.type || "element"} · ${selected.label || "Element"}`
      : "Bez odabira";
  }

  [
    [drawingSelectedLabelInput, selected?.label || ""],
    [drawingSelectedXInput, hasSelected ? String(Math.round(Number(selected?.x ?? 0))) : ""],
    [drawingSelectedYInput, hasSelected ? String(Math.round(Number(selected?.y ?? 0))) : ""],
    [drawingSelectedX2Input, hasSelected ? String(Math.round(Number(selected?.x2 ?? 0))) : ""],
    [drawingSelectedY2Input, hasSelected ? String(Math.round(Number(selected?.y2 ?? 0))) : ""],
    [drawingSelectedWidthInput, hasSelected ? String(Math.round(Number(selected?.width ?? 0))) : ""],
    [drawingSelectedHeightInput, hasSelected ? String(Math.round(Number(selected?.height ?? 0))) : ""],
    [drawingSelectedLineWidthInput, hasSelected ? String(Math.round(Number(selected?.lineWidth ?? 0))) : ""],
    [drawingSelectedSubtitleInput, selected?.metadata?.subtitle || ""],
    [drawingSelectedFooterInput, selected?.metadata?.footer || ""],
  ].forEach(([input, value]) => {
    if (!input) {
      return;
    }
    input.value = value;
    input.disabled = !hasSelected;
  });

  if (drawingSelectedRotationInput) {
    drawingSelectedRotationInput.value = hasSelected ? String(Math.round(Number(selected?.rotation ?? 0))) : "";
    drawingSelectedRotationInput.disabled = !hasSelected || !DRAWING_ROTATABLE_TYPES.has(String(selected?.type || "").trim().toLowerCase());
  }

  if (drawingSelectedStrokeInput) {
    drawingSelectedStrokeInput.value = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(selected?.stroke || "") ? selected.stroke : "#4564d1";
    drawingSelectedStrokeInput.disabled = !hasSelected;
  }

  if (drawingSelectedFillInput) {
    const fillValue = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(selected?.fill || "") ? selected.fill : "#e8efff";
    drawingSelectedFillInput.value = fillValue;
    drawingSelectedFillInput.disabled = !hasSelected || ["line", "curve", "wall", "dimension", "text", "door"].includes(String(selected?.type || ""));
  }

  if (drawingDeleteSelectedButton) {
    drawingDeleteSelectedButton.disabled = !hasSelected;
  }
}

function renderDrawingStudioModule() {
  if (!drawingStudioModule) {
    return;
  }

  if (!drawingProjectDraft) {
    const selectedProject = getDrawingProjectById(state.activeDrawingId);
    loadDrawingDraft(selectedProject);
  }

  if (state.activeDrawingId && !getDrawingProjectById(state.activeDrawingId)) {
    state.activeDrawingId = "";
    if (drawingProjectDraft?.id) {
      loadDrawingDraft(null);
    }
  }

  if (drawingSelectedElementId && !drawingElementDrafts.some((item) => String(item.id) === String(drawingSelectedElementId))) {
    drawingSelectedElementId = "";
  }
  if (drawingActiveReferenceId && !getDrawingVisibleReferenceDrafts().some((item) => String(item.id) === String(drawingActiveReferenceId))) {
    drawingActiveReferenceId = getDrawingVisibleReferenceDrafts()[0]?.id || "";
  }
  if (drawingActiveLayerId && !drawingLayerDrafts.some((item) => String(item.id) === String(drawingActiveLayerId))) {
    drawingActiveLayerId = drawingLayerDrafts[0]?.id || "";
  }

  if (drawingViewMode === "reference" && !drawingActiveReferenceId) {
    drawingViewMode = "canvas";
  }

  renderDrawingSelectOptions();
  syncDrawingLocationOptions();
  renderDrawingProjectList();
  renderDrawingReferenceList();
  renderDrawingLayerList();

  if (drawingEditorTitle) {
    drawingEditorTitle.textContent = drawingProjectDraft?.title?.trim()
      ? drawingProjectDraft.title.trim()
      : (drawingProjectDraft?.id ? "Crtež" : "Novi crtež");
  }

  if (drawingIdInput) {
    drawingIdInput.value = drawingProjectDraft?.id || "";
  }
  if (drawingTitleInput) {
    drawingTitleInput.value = drawingProjectDraft?.title || "";
  }
  if (drawingCompanyIdInput) {
    drawingCompanyIdInput.value = drawingProjectDraft?.companyId || "";
  }
  if (drawingLocationIdInput) {
    drawingLocationIdInput.value = drawingProjectDraft?.locationId || "";
  }
  if (drawingTypeInput) {
    drawingTypeInput.value = drawingProjectDraft?.drawingType || DRAWING_PROJECT_TYPE_OPTIONS[0]?.value || "custom";
  }
  if (drawingStatusInput) {
    drawingStatusInput.value = drawingProjectDraft?.status || DRAWING_PROJECT_STATUS_OPTIONS[0]?.value || "draft";
  }
  if (drawingScaleInput) {
    drawingScaleInput.value = drawingProjectDraft?.scaleLabel || "";
  }
  if (drawingNoteInput) {
    drawingNoteInput.value = drawingProjectDraft?.note || "";
  }
  if (drawingDeleteButton) {
    drawingDeleteButton.hidden = !drawingProjectDraft?.id;
  }

  if (drawingZoomInput) {
    drawingZoomInput.value = String(drawingViewportDraft.zoom || 1);
  }
  if (drawingZoomValue) {
    drawingZoomValue.textContent = `${Math.round(Number(drawingViewportDraft.zoom || 1) * 100)}%`;
  }
  if (drawingGridSizeInput) {
    drawingGridSizeInput.value = String(drawingViewportDraft.gridSize || 20);
  }
  if (drawingCanvasWidthInput) {
    drawingCanvasWidthInput.value = String(drawingViewportDraft.canvasWidth || DRAWING_STAGE_DEFAULT_WIDTH);
  }
  if (drawingCanvasHeightInput) {
    drawingCanvasHeightInput.value = String(drawingViewportDraft.canvasHeight || DRAWING_STAGE_DEFAULT_HEIGHT);
  }
  if (drawingSnapToggle) {
    drawingSnapToggle.checked = drawingViewportDraft.snapToGrid !== false;
  }
  if (drawingGridToggle) {
    drawingGridToggle.checked = drawingViewportDraft.showGrid !== false;
  }
  if (drawingOrthoToggleButton) {
    drawingOrthoToggleButton.classList.toggle("is-active", drawingViewportDraft.orthoMode === true);
    drawingOrthoToggleButton.setAttribute("aria-pressed", drawingViewportDraft.orthoMode === true ? "true" : "false");
  }
  if (drawingActiveToolLabel) {
    drawingActiveToolLabel.textContent = `Alat: ${getDrawingToolLabel(drawingCurrentTool)}`;
  }
  if (drawingCursorPositionLabel) {
    drawingCursorPositionLabel.textContent = `X ${Math.round(Number(drawingCursorPositionDraft.x || 0))} · Y ${Math.round(Number(drawingCursorPositionDraft.y || 0))}`;
  }
  if (drawingReferenceStatusLabel) {
    const activeReference = getDrawingActiveReference();
    const renderableReference = getDrawingRenderableReference(activeReference);
    drawingReferenceStatusLabel.textContent = activeReference
      ? `Podloga: ${activeReference.fileName || "Datoteka"}${renderableReference && String(renderableReference.id || "") !== String(activeReference.id || "") ? " · DXF preview" : ""}`
      : "Podloga: prazno platno";
  }
  if (drawingStageHelper) {
    const activeReference = getDrawingActiveReference();
    const renderableReference = getDrawingRenderableReference(activeReference);
    const hasDxfPreview = Boolean(
      activeReference
      && renderableReference
      && String(renderableReference.id || "") !== String(activeReference.id || "")
      && isDrawingDxfReference(renderableReference)
    );
    drawingStageHelper.textContent = !activeReference
      ? "Radiš na praznom platnu. Gore biraš alat, desno po potrebi otvaraš blokove, layere i inspector, a podlogu možeš dodati naknadno."
      : drawingViewMode === "reference"
        ? `Trenutno gledaš podlogu ${activeReference.fileName || "datoteka"}${hasDxfPreview ? " preko DXF previewa" : ""}. Vrati se na "Crtanje" kad želiš dodavati zidove, kote i blokove.`
        : `Podloga ${activeReference.fileName || "datoteka"}${hasDxfPreview ? " ima DXF preview za rad u editoru" : ""}. Crtaj preko nje ili prebaci na "Podloga" za puni pregled reference.`;
  }

  drawingToolButtons.forEach((button) => {
    button.classList.toggle("is-active", button.dataset.drawingTool === drawingCurrentTool);
  });
  drawingBlockButtons.forEach((button) => {
    button.classList.toggle("is-active", button.dataset.drawingBlock === drawingCurrentTool);
  });
  syncDrawingViewModeUi();
  syncDrawingSidebarUi();

  renderDrawingInspector();
  renderDrawingStage();
}

function getDrawingSelectedElement() {
  return drawingElementDrafts.find((item) => String(item.id) === String(drawingSelectedElementId)) ?? null;
}

function getDrawingStagePoint(clientX, clientY) {
  if (!drawingStageSvg) {
    return { x: 0, y: 0 };
  }

  const rect = drawingStageSvg.getBoundingClientRect();
  if (!rect.width || !rect.height) {
    return { x: 0, y: 0 };
  }

  const width = Number(drawingViewportDraft.canvasWidth || DRAWING_STAGE_DEFAULT_WIDTH);
  const height = Number(drawingViewportDraft.canvasHeight || DRAWING_STAGE_DEFAULT_HEIGHT);
  const rawX = ((clientX - rect.left) / rect.width) * width;
  const rawY = ((clientY - rect.top) / rect.height) * height;
  if (drawingViewportDraft.snapToGrid !== false) {
    const gridSize = Math.max(8, Number(drawingViewportDraft.gridSize || 20));
    return {
      x: Math.round(rawX / gridSize) * gridSize,
      y: Math.round(rawY / gridSize) * gridSize,
    };
  }

  return {
    x: Math.round(rawX * 10) / 10,
    y: Math.round(rawY * 10) / 10,
  };
}

function handleDrawingStagePointerHover(event) {
  if (!drawingStageSvg) {
    return;
  }

  const point = getDrawingStagePoint(event.clientX, event.clientY);
  drawingCursorPositionDraft = point;
  if (drawingCursorPositionLabel) {
    drawingCursorPositionLabel.textContent = `X ${Math.round(Number(point.x || 0))} · Y ${Math.round(Number(point.y || 0))}`;
  }
}

function getDrawingElementBounds(element = {}) {
  const type = String(element.type || "").trim().toLowerCase();
  if (type === "curve") {
    const controlPoint = getDrawingCurveControlPoint(element);
    const minX = Math.min(Number(element.x || 0), Number(element.x2 || 0), controlPoint.x);
    const minY = Math.min(Number(element.y || 0), Number(element.y2 || 0), controlPoint.y);
    const maxX = Math.max(Number(element.x || 0), Number(element.x2 || 0), controlPoint.x);
    const maxY = Math.max(Number(element.y || 0), Number(element.y2 || 0), controlPoint.y);
    return {
      x: minX,
      y: minY,
      width: Math.max(4, maxX - minX),
      height: Math.max(4, maxY - minY),
    };
  }

  if (DRAWING_LINEAR_TYPES.has(type)) {
    const minX = Math.min(Number(element.x || 0), Number(element.x2 || 0));
    const minY = Math.min(Number(element.y || 0), Number(element.y2 || 0));
    const maxX = Math.max(Number(element.x || 0), Number(element.x2 || 0));
    const maxY = Math.max(Number(element.y || 0), Number(element.y2 || 0));
    return {
      x: minX,
      y: minY,
      width: Math.max(4, maxX - minX),
      height: Math.max(4, maxY - minY),
    };
  }

  return {
    x: Number(element.x || 0),
    y: Number(element.y || 0),
    width: Math.max(4, Number(element.width || 0)),
    height: Math.max(4, Number(element.height || 0)),
  };
}

function getDrawingElementTransform(element = {}) {
  const type = String(element.type || "").trim().toLowerCase();
  if (!DRAWING_ROTATABLE_TYPES.has(type)) {
    return "";
  }

  const rotation = Math.max(-360, Math.min(360, Number(element.rotation || 0)));
  if (!rotation) {
    return "";
  }

  const bounds = getDrawingElementBounds(element);
  const centerX = bounds.x + bounds.width / 2;
  const centerY = bounds.y + bounds.height / 2;
  return ` transform="rotate(${rotation} ${centerX} ${centerY})"`;
}

function renderDrawingElementMarkup(element = {}, { selected = false } = {}) {
  const safeId = escapeHtml(String(element.id || ""));
  const stroke = escapeHtml(element.stroke || "#4564d1");
  const fill = String(element.fill || "").trim() === "transparent" ? "transparent" : escapeHtml(element.fill || "#e8efff");
  const strokeWidth = Number(element.lineWidth ?? 2) || 0;
  const label = escapeHtml(element.label || "");
  const subtitle = escapeHtml(element.metadata?.subtitle || "");
  const footer = escapeHtml(element.metadata?.footer || "");
  const type = String(element.type || "").trim().toLowerCase();
  const selectionClass = selected ? " drawing-element-selected" : "";
  const transform = getDrawingElementTransform(element);

  if (type === "line" || type === "wall") {
    const hitStrokeWidth = Math.max(strokeWidth + 18, 18);
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}">
        <line x1="${element.x}" y1="${element.y}" x2="${element.x2}" y2="${element.y2}" stroke="transparent" stroke-width="${hitStrokeWidth}" stroke-linecap="round" data-element-id="${safeId}"></line>
        <line x1="${element.x}" y1="${element.y}" x2="${element.x2}" y2="${element.y2}" stroke="${stroke}" stroke-width="${strokeWidth}" stroke-linecap="round" data-element-id="${safeId}"></line>
      </g>
    `;
  }

  if (type === "curve") {
    const controlPoint = getDrawingCurveControlPoint(element);
    const hitStrokeWidth = Math.max(strokeWidth + 18, 18);
    const path = `M ${element.x} ${element.y} Q ${controlPoint.x} ${controlPoint.y} ${element.x2} ${element.y2}`;
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}">
        <path d="${path}" fill="none" stroke="transparent" stroke-width="${hitStrokeWidth}" stroke-linecap="round" data-element-id="${safeId}"></path>
        <path d="${path}" fill="none" stroke="${stroke}" stroke-width="${strokeWidth}" stroke-linecap="round" data-element-id="${safeId}"></path>
      </g>
    `;
  }

  if (type === "dimension") {
    const midX = (Number(element.x || 0) + Number(element.x2 || 0)) / 2;
    const midY = (Number(element.y || 0) + Number(element.y2 || 0)) / 2;
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}">
        <line x1="${element.x}" y1="${element.y}" x2="${element.x2}" y2="${element.y2}" stroke="transparent" stroke-width="18" stroke-linecap="round" data-element-id="${safeId}"></line>
        <line x1="${element.x}" y1="${element.y}" x2="${element.x2}" y2="${element.y2}" stroke="${stroke}" stroke-width="${Math.max(1, strokeWidth)}" stroke-dasharray="8 6" marker-start="url(#drawing-dimension-arrow)" marker-end="url(#drawing-dimension-arrow)" data-element-id="${safeId}"></line>
        <line x1="${element.x}" y1="${element.y - 14}" x2="${element.x}" y2="${element.y + 14}" stroke="${stroke}" stroke-width="${Math.max(1, strokeWidth - 0.2)}" data-element-id="${safeId}"></line>
        <line x1="${element.x2}" y1="${element.y2 - 14}" x2="${element.x2}" y2="${element.y2 + 14}" stroke="${stroke}" stroke-width="${Math.max(1, strokeWidth - 0.2)}" data-element-id="${safeId}"></line>
        <rect x="${midX - 54}" y="${midY - 18}" width="108" height="28" rx="14" fill="rgba(255,255,255,0.92)" stroke="${stroke}" stroke-width="1" data-element-id="${safeId}"></rect>
        <text x="${midX}" y="${midY + 2}" text-anchor="middle" class="drawing-stage-label">${label || getDrawingDimensionLabel(element)}</text>
      </g>
    `;
  }

  if (type === "door") {
    const openRight = String(element.metadata?.openDirection || "left") === "right";
    const pivotX = Number(element.x || 0);
    const pivotY = Number(element.y || 0);
    const width = Math.max(40, Number(element.width || 120));
    const height = Math.max(30, Number(element.height || 90));
    const doorLeafX = openRight ? pivotX + width : pivotX;
    const sweepEndX = openRight ? pivotX : pivotX + width;
    const sweepFlag = openRight ? 0 : 1;
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <rect x="${pivotX}" y="${pivotY}" width="${width}" height="${height}" fill="transparent" stroke="transparent" stroke-width="18" data-element-id="${safeId}"></rect>
        <line x1="${pivotX}" y1="${pivotY}" x2="${pivotX}" y2="${pivotY + height}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></line>
        <line x1="${pivotX}" y1="${pivotY}" x2="${doorLeafX}" y2="${pivotY}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></line>
        <path d="M ${pivotX} ${pivotY} A ${width} ${height} 0 0 ${sweepFlag} ${sweepEndX} ${pivotY + height}" fill="none" stroke="${stroke}" stroke-width="${Math.max(1, strokeWidth - 0.5)}" stroke-dasharray="7 5" data-element-id="${safeId}"></path>
        ${label ? `<text x="${pivotX + width / 2}" y="${pivotY + height + 24}" text-anchor="middle" class="drawing-stage-label">${label}</text>` : ""}
      </g>
    `;
  }

  if (type === "exit") {
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <rect x="${element.x}" y="${element.y}" width="${element.width}" height="${element.height}" rx="12" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></rect>
        <text x="${Number(element.x || 0) + Number(element.width || 0) / 2}" y="${Number(element.y || 0) + Number(element.height || 0) / 2 + 6}" text-anchor="middle" class="drawing-stage-label">${label || "EXIT"}</text>
      </g>
    `;
  }

  if (type === "extinguisher" || type === "hydrant") {
    const symbol = type === "extinguisher" ? "A" : "H";
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <rect x="${element.x}" y="${element.y}" width="${element.width}" height="${element.height}" rx="16" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></rect>
        <text x="${Number(element.x || 0) + Number(element.width || 0) / 2}" y="${Number(element.y || 0) + Number(element.height || 0) / 2 + 6}" text-anchor="middle" class="drawing-stage-label">${label || symbol}</text>
      </g>
    `;
  }

  if (type === "stairs") {
    const stepCount = 5;
    const width = Math.max(90, Number(element.width || 180));
    const height = Math.max(60, Number(element.height || 120));
    const stepSize = width / stepCount;
    const lines = Array.from({ length: stepCount }, (_, index) => {
      const currentX = Number(element.x || 0) + (index * stepSize);
      return `<path d="M ${currentX} ${Number(element.y || 0) + height} L ${currentX + stepSize} ${Number(element.y || 0) + height} L ${currentX + stepSize} ${Number(element.y || 0)}" fill="none" stroke="${stroke}" stroke-width="${Math.max(1, strokeWidth - 0.3)}" data-element-id="${safeId}"></path>`;
    }).join("");
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <rect x="${element.x}" y="${element.y}" width="${width}" height="${height}" rx="16" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></rect>
        ${lines}
        <text x="${Number(element.x || 0) + width / 2}" y="${Number(element.y || 0) + height + 24}" text-anchor="middle" class="drawing-stage-label">${label || "Stube"}</text>
      </g>
    `;
  }

  if (type === "assembly_point") {
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <rect x="${element.x}" y="${element.y}" width="${element.width}" height="${element.height}" rx="18" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></rect>
        <circle cx="${Number(element.x || 0) + 30}" cy="${Number(element.y || 0) + Number(element.height || 0) / 2}" r="12" fill="${stroke}" data-element-id="${safeId}"></circle>
        <text x="${Number(element.x || 0) + Number(element.width || 0) / 2 + 12}" y="${Number(element.y || 0) + Number(element.height || 0) / 2 + 6}" text-anchor="middle" class="drawing-stage-label">${label || "ZBORNO"}</text>
      </g>
    `;
  }

  if (type === "first_aid") {
    const centerX = Number(element.x || 0) + Number(element.width || 0) / 2;
    const centerY = Number(element.y || 0) + Number(element.height || 0) / 2;
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <rect x="${element.x}" y="${element.y}" width="${element.width}" height="${element.height}" rx="18" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></rect>
        <rect x="${centerX - 10}" y="${centerY - 24}" width="20" height="48" rx="6" fill="${stroke}" data-element-id="${safeId}"></rect>
        <rect x="${centerX - 24}" y="${centerY - 10}" width="48" height="20" rx="6" fill="${stroke}" data-element-id="${safeId}"></rect>
      </g>
    `;
  }

  if (type === "detector") {
    const centerX = Number(element.x || 0) + Number(element.width || 0) / 2;
    const centerY = Number(element.y || 0) + Number(element.height || 0) / 2;
    const radius = Math.max(18, Math.min(Number(element.width || 0), Number(element.height || 0)) / 2);
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <circle cx="${centerX}" cy="${centerY}" r="${radius}" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></circle>
        <circle cx="${centerX}" cy="${centerY}" r="${Math.max(5, radius / 3)}" fill="${stroke}" data-element-id="${safeId}"></circle>
      </g>
    `;
  }

  if (type === "panel") {
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <rect x="${element.x}" y="${element.y}" width="${element.width}" height="${element.height}" rx="16" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></rect>
        <text x="${Number(element.x || 0) + Number(element.width || 0) / 2}" y="${Number(element.y || 0) + Number(element.height || 0) / 2 + 6}" text-anchor="middle" class="drawing-stage-label">${label || "C"}</text>
      </g>
    `;
  }

  if (type === "arrow") {
    const startX = Number(element.x || 0);
    const startY = Number(element.y || 0) + Number(element.height || 0) / 2;
    const endX = startX + Number(element.width || 0);
    const endY = startY;
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <line x1="${startX}" y1="${startY}" x2="${endX}" y2="${endY}" stroke="${stroke}" stroke-width="${Math.max(2, strokeWidth + 1)}" marker-end="url(#drawing-arrow-head)" data-element-id="${safeId}"></line>
        ${label ? `<text x="${startX + Number(element.width || 0) / 2}" y="${Number(element.y || 0) - 8}" text-anchor="middle" class="drawing-stage-label">${label}</text>` : ""}
      </g>
    `;
  }

  if (type === "text") {
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <rect x="${element.x}" y="${element.y}" width="${Math.max(60, element.width || 220)}" height="${Math.max(24, element.height || 40)}" fill="transparent" stroke="transparent" data-element-id="${safeId}"></rect>
        <text x="${Number(element.x || 0) + 6}" y="${Number(element.y || 0) + 24}" class="drawing-stage-label">${label || "Tekst"}</text>
      </g>
    `;
  }

  if (type === "ellipse") {
    const centerX = Number(element.x || 0) + Number(element.width || 0) / 2;
    const centerY = Number(element.y || 0) + Number(element.height || 0) / 2;
    const radiusX = Math.max(6, Number(element.width || 0) / 2);
    const radiusY = Math.max(6, Number(element.height || 0) / 2);
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <ellipse cx="${centerX}" cy="${centerY}" rx="${radiusX}" ry="${radiusY}" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></ellipse>
        ${label ? `<text x="${centerX}" y="${centerY + 6}" text-anchor="middle" class="drawing-stage-label">${label}</text>` : ""}
      </g>
    `;
  }

  if (type === "frame") {
    const innerX = Number(element.x || 0) + 18;
    const innerY = Number(element.y || 0) + 18;
    const innerWidth = Math.max(120, Number(element.width || 0) - 36);
    const innerHeight = Math.max(120, Number(element.height || 0) - 90);
    const footerY = Number(element.y || 0) + Number(element.height || 0) - 72;
    return `
      <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
        <rect x="${element.x}" y="${element.y}" width="${element.width}" height="${element.height}" rx="18" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></rect>
        <rect x="${innerX}" y="${innerY}" width="${innerWidth}" height="${innerHeight}" rx="12" fill="transparent" stroke="${stroke}" stroke-width="${Math.max(1, strokeWidth - 0.5)}" data-element-id="${safeId}"></rect>
        <line x1="${element.x}" y1="${footerY}" x2="${Number(element.x || 0) + Number(element.width || 0)}" y2="${footerY}" stroke="${stroke}" stroke-width="${Math.max(1, strokeWidth - 0.5)}" data-element-id="${safeId}"></line>
        <text x="${Number(element.x || 0) + 24}" y="${footerY + 28}" class="drawing-stage-label">${label || "Plan evakuacije i spasavanja"}</text>
        ${subtitle ? `<text x="${Number(element.x || 0) + 24}" y="${footerY + 50}" class="drawing-stage-label">${subtitle}</text>` : ""}
        ${footer ? `<text x="${Number(element.x || 0) + Number(element.width || 0) - 24}" y="${footerY + 50}" text-anchor="end" class="drawing-stage-label">${footer}</text>` : ""}
      </g>
    `;
  }

  return `
    <g data-element-id="${safeId}" class="drawing-stage-element${selectionClass}"${transform}>
      <rect x="${element.x}" y="${element.y}" width="${element.width}" height="${element.height}" rx="16" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" data-element-id="${safeId}"></rect>
      ${label ? `<text x="${Number(element.x || 0) + 18}" y="${Number(element.y || 0) + 28}" class="drawing-stage-label">${label}</text>` : ""}
    </g>
  `;
}

function renderDrawingStageReference() {
  if (!drawingStageReference) {
    return;
  }

  drawingStageReference.classList.remove("is-cad-reference");
  const activeReference = drawingReferenceDrafts.find((item) => String(item.id) === String(drawingActiveReferenceId)) ?? null;
  const renderableReference = getDrawingRenderableReference(activeReference);
  if (!activeReference) {
    drawingStageReference.innerHTML = '<div class="drawing-stage-reference-empty">Nema aktivne podloge. Crtaj odmah na praznom platnu ili naknadno dodaj DWG, DXF, PDF ili sliku.</div>';
    return;
  }

  const fileName = String(renderableReference?.fileName || activeReference.fileName || "").trim().toLowerCase();
  const fileType = String(renderableReference?.fileType || activeReference.fileType || "").trim().toLowerCase();
  const href = String(renderableReference?.storageUrl || renderableReference?.dataUrl || activeReference.storageUrl || activeReference.dataUrl || "").trim();
  const isPdf = fileType.includes("pdf") || fileName.endsWith(".pdf");
  const isImage = fileType.startsWith("image/") || [".png", ".jpg", ".jpeg", ".webp", ".svg"].some((extension) => fileName.endsWith(extension));
  const isCad = fileName.endsWith(".dwg") || fileName.endsWith(".dxf");

  if (isPdf && href) {
    drawingStageReference.innerHTML = `<object data="${escapeHtml(href)}" type="application/pdf" aria-label="PDF podloga"></object>`;
    return;
  }

  if (isImage && href) {
    drawingStageReference.innerHTML = `<img src="${escapeHtml(href)}" alt="${escapeHtml(activeReference.fileName || "Podloga")}" />`;
    return;
  }

  if (isCad) {
    drawingStageReference.classList.add("is-cad-reference");
    const extensionLabel = fileName.endsWith(".dxf") ? "DXF" : "DWG";
    const displayName = escapeHtml(activeReference.fileName || `${extensionLabel} podloga`);
    const renderableName = escapeHtml(renderableReference?.fileName || "");
    const previewReady = renderableReference && String(renderableReference.id || "") !== String(activeReference.id || "") && isDrawingDxfReference(renderableReference);
    drawingStageReference.innerHTML = `
      <div class="drawing-stage-cad-badge">
        <span>${extensionLabel}</span>
        <strong>${displayName}</strong>
        <small>${previewReady ? `DXF preview: ${renderableName}` : `${extensionLabel} podloga aktivna`}</small>
      </div>
    `;
    return;
  }

  drawingStageReference.innerHTML = `
    <div class="drawing-stage-reference-unsupported">
      <strong>${escapeHtml(activeReference.fileName || "Datoteka")}</strong><br />
      Datoteka je spremljena kao referenca za crtež, ali nema ugrađeni preview u browseru.
    </div>
  `;
}

function renderDrawingStage() {
  if (!drawingStage || !drawingStageSvg) {
    return;
  }

  const zoom = Math.max(0.5, Math.min(2.5, Number(drawingViewportDraft.zoom || 1)));
  const canvasWidth = clampDrawingCanvasWidth(drawingViewportDraft.canvasWidth || DRAWING_STAGE_DEFAULT_WIDTH);
  const canvasHeight = clampDrawingCanvasHeight(drawingViewportDraft.canvasHeight || DRAWING_STAGE_DEFAULT_HEIGHT);
  const activeReference = getDrawingActiveReference();
  const renderableReference = getDrawingRenderableReference(activeReference);
  const isReferenceMode = drawingViewMode === "reference" && Boolean(activeReference);
  drawingStage.style.width = `${Math.round(canvasWidth * zoom)}px`;
  drawingStage.style.height = `${Math.round(canvasHeight * zoom)}px`;
  drawingStage.classList.toggle("is-reference-mode", isReferenceMode);
  drawingStageSvg.setAttribute("viewBox", `0 0 ${canvasWidth} ${canvasHeight}`);
  drawingStageSvg.classList.toggle("is-tool-select", drawingCurrentTool === "select");
  renderDrawingStageReference();
  if (drawingStageReference) {
    drawingStageReference.hidden = false;
  }
  if (renderableReference && isDrawingCadReference(renderableReference)) {
    void renderDrawingCadReference(renderableReference).catch((error) => {
      console.error("Drawing CAD preview failed", error);
      renderableReference.previewStatus = "error";
      renderableReference.previewError = getDrawingCadErrorMessage(error);
      renderDrawingReferenceList();
      resetDrawingCadViewer();
      showDrawingCadStatus(`CAD pregled nije moguće učitati. ${getDrawingCadErrorMessage(error)}`, "error");
    });
  } else {
    resetDrawingCadViewer();
  }
  if (!renderableReference || !isDrawingCadReference(renderableReference)) {
    showDrawingCadStatus("");
  }

  const visibleLayerIds = new Set(
    drawingLayerDrafts
      .filter((layer) => layer.visible !== false)
      .map((layer) => String(layer.id)),
  );
  const gridSize = Math.max(8, Number(drawingViewportDraft.gridSize || 20));
  const majorGrid = gridSize * 5;
  const defsMarkup = `
      <defs>
        <marker id="drawing-arrow-head" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto">
          <path d="M 0 0 L 10 5 L 0 10 z" fill="#1e9e68"></path>
        </marker>
        <marker id="drawing-dimension-arrow" markerWidth="10" markerHeight="10" refX="5" refY="5" orient="auto">
          <path d="M 0 5 L 10 0 L 8 5 L 10 10 z" fill="#da8a1f"></path>
        </marker>
        ${drawingViewportDraft.showGrid === false ? "" : `
        <pattern id="drawing-grid-small" width="${gridSize}" height="${gridSize}" patternUnits="userSpaceOnUse">
          <path d="M ${gridSize} 0 L 0 0 0 ${gridSize}" fill="none" stroke="rgba(90,112,162,0.13)" stroke-width="1"></path>
        </pattern>
        <pattern id="drawing-grid-major" width="${majorGrid}" height="${majorGrid}" patternUnits="userSpaceOnUse">
          <path d="M ${majorGrid} 0 L 0 0 0 ${majorGrid}" fill="none" stroke="rgba(90,112,162,0.22)" stroke-width="1.2"></path>
        </pattern>
        `}
      </defs>
    `;
  const gridMarkup = drawingViewportDraft.showGrid === false
    ? defsMarkup
    : `
      ${defsMarkup}
      <rect x="0" y="0" width="${canvasWidth}" height="${canvasHeight}" fill="url(#drawing-grid-small)"></rect>
      <rect x="0" y="0" width="${canvasWidth}" height="${canvasHeight}" fill="url(#drawing-grid-major)"></rect>
    `;
  const elementMarkup = drawingElementDrafts
    .filter((element) => visibleLayerIds.has(String(element.layerId)))
    .map((element) => renderDrawingElementMarkup(element, {
      selected: String(element.id) === String(drawingSelectedElementId),
    }))
    .join("");

  let selectionMarkup = "";
  const selected = getDrawingSelectedElement();
  if (selected) {
    const bounds = getDrawingElementBounds(selected);
    const handleX = bounds.x + bounds.width;
    const handleY = bounds.y + bounds.height;
    selectionMarkup = `
      <rect class="drawing-stage-selection-box" x="${bounds.x - 8}" y="${bounds.y - 8}" width="${bounds.width + 16}" height="${bounds.height + 16}" rx="12"></rect>
      ${DRAWING_LINEAR_TYPES.has(String(selected.type || "").trim().toLowerCase()) ? "" : `<circle class="drawing-resize-handle" data-drawing-resize-handle="1" cx="${handleX}" cy="${handleY}" r="10" fill="#ffffff" stroke="#496ad6" stroke-width="2"></circle>`}
    `;
  }

  let previewMarkup = "";
  if (drawingPointerSession?.mode === "draw" && drawingPointerSession.previewElement) {
    previewMarkup = renderDrawingElementMarkup(drawingPointerSession.previewElement, { selected: false });
  }

  drawingStageSvg.innerHTML = `${gridMarkup}${elementMarkup}${selectionMarkup}${previewMarkup}`;
}

function getDrawingElementFromTool(tool = "rectangle", point = { x: 120, y: 120 }, endPoint = null) {
  const layer = getDrawingActiveLayer();
  const style = getDrawingDefaultElementStyle(tool, layer);
  const x = Number(point.x || 0);
  const y = Number(point.y || 0);
  const endX = Number(endPoint?.x ?? x + style.width);
  const endY = Number(endPoint?.y ?? y + style.height);
  const minX = Math.min(x, endX);
  const minY = Math.min(y, endY);
  const width = Math.max(4, Math.abs(endX - x) || style.width);
  const height = Math.max(4, Math.abs(endY - y) || style.height);
  const base = {
    id: crypto.randomUUID(),
    type: tool,
    layerId: String(layer?.id || drawingLayerDrafts[0]?.id || ""),
    stroke: style.stroke,
    fill: style.fill,
    lineWidth: style.lineWidth,
    label: "",
    rotation: 0,
    metadata: {},
  };

  if (DRAWING_LINEAR_TYPES.has(tool)) {
    return {
      ...base,
      x,
      y,
      x2: endX,
      y2: endY,
      width: Math.abs(endX - x),
      height: Math.abs(endY - y),
      label: tool === "dimension" ? getDrawingDimensionLabel({ x, y, x2: endX, y2: endY }) : "",
      metadata: {
        ...(tool === "dimension"
          ? {
            autoLabel: true,
            unit: DRAWING_DIMENSION_UNIT,
          }
          : {}),
        ...(tool === "curve"
          ? {
            curveDirection: 1,
            curveOffset: Math.max(48, Math.abs(endY - y) || style.height || 120),
          }
          : {}),
      },
    };
  }

  if (tool === "door") {
    return {
      ...base,
      x,
      y,
      width: style.width,
      height: style.height,
      x2: x + style.width,
      y2: y + style.height,
      label: "Vrata",
      metadata: {
        openDirection: "left",
        subtitle: "",
        footer: "",
      },
    };
  }

  if (tool === "exit") {
    return {
      ...base,
      x,
      y,
      width: style.width,
      height: style.height,
      x2: x + style.width,
      y2: y + style.height,
      label: "EXIT",
      metadata: {
        subtitle: "",
        footer: "",
      },
    };
  }

  if (tool === "extinguisher") {
    return {
      ...base,
      x,
      y,
      width: style.width,
      height: style.height,
      x2: x + style.width,
      y2: y + style.height,
      label: "A",
      metadata: {
        subtitle: "",
        footer: "",
      },
    };
  }

  if (tool === "hydrant") {
    return {
      ...base,
      x,
      y,
      width: style.width,
      height: style.height,
      x2: x + style.width,
      y2: y + style.height,
      label: "H",
      metadata: {
        subtitle: "",
        footer: "",
      },
    };
  }

  if (["stairs", "assembly_point", "first_aid", "detector", "panel", "arrow"].includes(tool)) {
    const defaultLabels = {
      stairs: "Stube",
      assembly_point: "ZBORNO",
      first_aid: "",
      detector: "",
      panel: "C",
      arrow: "Smjer",
    };
    return {
      ...base,
      x,
      y,
      width: style.width,
      height: style.height,
      x2: x + style.width,
      y2: y + style.height,
      label: defaultLabels[tool] || "",
      metadata: {
        subtitle: "",
        footer: "",
      },
    };
  }

  if (tool === "text") {
    return {
      ...base,
      x,
      y,
      width: style.width,
      height: style.height,
      x2: x + style.width,
      y2: y + style.height,
      label: "Tekst",
      metadata: {
        subtitle: "",
        footer: "",
      },
    };
  }

  if (tool === "frame") {
    return {
      ...base,
      x: minX,
      y: minY,
      width,
      height,
      x2: minX + width,
      y2: minY + height,
      label: "Plan evakuacije i spasavanja",
      metadata: {
        subtitle: "",
        footer: "Plan evakuacije i spasavanja",
      },
    };
  }

  return {
    ...base,
    x: minX,
    y: minY,
    width,
    height,
    x2: minX + width,
    y2: minY + height,
    label: tool === "rectangle" ? "Blok" : "",
    metadata: {
      subtitle: "",
      footer: "",
    },
  };
}

function appendDrawingElement(element, { selectToolAfterInsert = false } = {}) {
  const normalizedElement = syncDrawingElementDerivedFields(cloneDrawingElementDraft(element));
  drawingElementDrafts = [...drawingElementDrafts, normalizedElement];
  drawingSelectedElementId = String(normalizedElement.id);
  drawingActiveLayerId = String(normalizedElement.layerId || drawingActiveLayerId);
  if (selectToolAfterInsert) {
    drawingCurrentTool = "select";
  }
  renderDrawingStudioModule();
}

function updateDrawingElementDraft(elementId, patch = {}) {
  drawingElementDrafts = drawingElementDrafts.map((item) => (
    String(item.id) === String(elementId)
      ? syncDrawingElementDerivedFields({
        ...item,
        ...patch,
        metadata: {
          ...(item.metadata ?? {}),
          ...(patch.metadata ?? {}),
        },
      })
      : item
  ));
}

function deleteSelectedDrawingElement() {
  if (!drawingSelectedElementId) {
    return;
  }

  drawingElementDrafts = drawingElementDrafts.filter((item) => String(item.id) !== String(drawingSelectedElementId));
  drawingSelectedElementId = "";
  renderDrawingStudioModule();
}

function applyDrawingInspectorPatch(patch = {}) {
  if (!drawingSelectedElementId) {
    return;
  }

  updateDrawingElementDraft(drawingSelectedElementId, patch);
  renderDrawingStudioModule();
}

function handleDrawingStagePointerDown(event) {
  if (!drawingStageSvg) {
    return;
  }

  const resizeHandle = event.target.closest("[data-drawing-resize-handle]");
  const elementTarget = event.target.closest("[data-element-id]");
  const point = getDrawingStagePoint(event.clientX, event.clientY);
  drawingCursorPositionDraft = point;

  if (drawingCurrentTool === "select") {
    if (resizeHandle && drawingSelectedElementId) {
      const current = getDrawingSelectedElement();
      if (!current || DRAWING_LINEAR_TYPES.has(String(current.type || "").trim().toLowerCase())) {
        return;
      }

      drawingPointerSession = {
        mode: "resize",
        elementId: String(current.id),
        startPoint: point,
        originalElement: cloneDrawingElementDraft(current),
      };
      event.preventDefault();
      return;
    }

    if (elementTarget) {
      const elementId = String(elementTarget.dataset.elementId || "").trim();
      const current = drawingElementDrafts.find((item) => String(item.id) === elementId);
      if (!current) {
        return;
      }

      drawingSelectedElementId = elementId;
      drawingActiveLayerId = String(current.layerId || drawingActiveLayerId);
      drawingPointerSession = {
        mode: "move",
        elementId,
        startPoint: point,
        originalElement: cloneDrawingElementDraft(current),
      };
      renderDrawingStudioModule();
      event.preventDefault();
      return;
    }

    drawingSelectedElementId = "";
    renderDrawingStudioModule();
    return;
  }

  if (DRAWING_SINGLE_CLICK_TYPES.has(drawingCurrentTool)) {
    appendDrawingElement(getDrawingElementFromTool(drawingCurrentTool, point));
    event.preventDefault();
    return;
  }

  drawingPointerSession = {
    mode: "draw",
    tool: drawingCurrentTool,
    startPoint: point,
    previewElement: getDrawingElementFromTool(drawingCurrentTool, point, point),
  };
  event.preventDefault();
}

function handleDrawingStagePointerMove(event) {
  const point = getDrawingStagePoint(event.clientX, event.clientY);
  drawingCursorPositionDraft = point;

  if (!drawingPointerSession) {
    if (drawingCursorPositionLabel) {
      drawingCursorPositionLabel.textContent = `X ${Math.round(Number(point.x || 0))} · Y ${Math.round(Number(point.y || 0))}`;
    }
    return;
  }

  if (drawingPointerSession.mode === "draw") {
    const constrainedPoint = applyDrawingOrthoConstraint(
      drawingPointerSession.startPoint,
      point,
      drawingPointerSession.tool,
    );
    drawingPointerSession.previewElement = getDrawingElementFromTool(
      drawingPointerSession.tool,
      drawingPointerSession.startPoint,
      constrainedPoint,
    );
    renderDrawingStage();
    return;
  }

  if (drawingPointerSession.mode === "move") {
    const original = drawingPointerSession.originalElement;
    const deltaX = point.x - drawingPointerSession.startPoint.x;
    const deltaY = point.y - drawingPointerSession.startPoint.y;
    if (!original) {
      return;
    }

    const type = String(original.type || "").trim().toLowerCase();
    if (DRAWING_LINEAR_TYPES.has(type)) {
      updateDrawingElementDraft(drawingPointerSession.elementId, {
        x: Number(original.x || 0) + deltaX,
        y: Number(original.y || 0) + deltaY,
        x2: Number(original.x2 || 0) + deltaX,
        y2: Number(original.y2 || 0) + deltaY,
      });
    } else {
      updateDrawingElementDraft(drawingPointerSession.elementId, {
        x: Number(original.x || 0) + deltaX,
        y: Number(original.y || 0) + deltaY,
        x2: Number(original.x2 || (Number(original.x || 0) + Number(original.width || 0))) + deltaX,
        y2: Number(original.y2 || (Number(original.y || 0) + Number(original.height || 0))) + deltaY,
      });
    }
    renderDrawingInspector();
    renderDrawingStage();
    return;
  }

  if (drawingPointerSession.mode === "resize") {
    const original = drawingPointerSession.originalElement;
    if (!original) {
      return;
    }
    const minX = Math.min(Number(original.x || 0), point.x);
    const minY = Math.min(Number(original.y || 0), point.y);
    const width = Math.max(20, Math.abs(point.x - Number(original.x || 0)));
    const height = Math.max(20, Math.abs(point.y - Number(original.y || 0)));
    updateDrawingElementDraft(drawingPointerSession.elementId, {
      x: minX,
      y: minY,
      width,
      height,
      x2: minX + width,
      y2: minY + height,
    });
    renderDrawingInspector();
    renderDrawingStage();
  }
}

function handleDrawingStagePointerUp(event) {
  if (!drawingPointerSession) {
    return;
  }

  const point = getDrawingStagePoint(event.clientX, event.clientY);
  drawingCursorPositionDraft = point;

  if (drawingPointerSession.mode === "draw") {
    const constrainedPoint = applyDrawingOrthoConstraint(
      drawingPointerSession.startPoint,
      point,
      drawingPointerSession.tool,
    );
    const element = getDrawingElementFromTool(
      drawingPointerSession.tool,
      drawingPointerSession.startPoint,
      constrainedPoint,
    );
    drawingPointerSession = null;
    appendDrawingElement(element);
    return;
  }

  drawingPointerSession = null;
}

function buildDrawingPayload() {
  return {
    organizationId: drawingProjectDraft?.organizationId || state.activeOrganizationId,
    companyId: drawingProjectDraft?.companyId || "",
    locationId: drawingProjectDraft?.locationId || "",
    title: drawingProjectDraft?.title || "",
    drawingType: drawingProjectDraft?.drawingType || "custom",
    status: drawingProjectDraft?.status || "draft",
    scaleLabel: drawingProjectDraft?.scaleLabel || "",
    note: drawingProjectDraft?.note || "",
    referenceDocuments: drawingReferenceDrafts.map((document) => serializeModuleAttachmentDraft(document)),
    activeReferenceDocumentId: drawingActiveReferenceId || "",
    layers: drawingLayerDrafts.map((layer) => ({
      ...layer,
    })),
    elements: drawingElementDrafts.map((element) => {
      const normalizedElement = syncDrawingElementDerivedFields(element);
      return {
        ...normalizedElement,
        metadata: { ...(normalizedElement.metadata ?? {}) },
      };
    }),
    viewport: {
      ...drawingViewportDraft,
    },
  };
}

function buildDrawingExportSvg(includeReference = true) {
  const canvasWidth = clampDrawingCanvasWidth(drawingViewportDraft.canvasWidth || DRAWING_STAGE_DEFAULT_WIDTH);
  const canvasHeight = clampDrawingCanvasHeight(drawingViewportDraft.canvasHeight || DRAWING_STAGE_DEFAULT_HEIGHT);
  const visibleLayerIds = new Set(
    drawingLayerDrafts
      .filter((layer) => layer.visible !== false)
      .map((layer) => String(layer.id)),
  );
  const gridSize = Math.max(8, Number(drawingViewportDraft.gridSize || 20));
  const majorGrid = gridSize * 5;
  const activeReference = drawingReferenceDrafts.find((item) => String(item.id) === String(drawingActiveReferenceId)) ?? null;
  const renderableReference = getDrawingRenderableReference(activeReference);
  const activeReferenceHref = String(renderableReference?.dataUrl || renderableReference?.storageUrl || activeReference?.dataUrl || activeReference?.storageUrl || "").trim();
  const fileName = String(renderableReference?.fileName || activeReference?.fileName || "").trim().toLowerCase();
  const fileType = String(renderableReference?.fileType || activeReference?.fileType || "").trim().toLowerCase();
  const referenceIsImage = includeReference
    && Boolean(activeReferenceHref)
    && (fileType.startsWith("image/") || [".png", ".jpg", ".jpeg", ".webp", ".svg"].some((extension) => fileName.endsWith(extension)));
  const referenceIsCadRaster = includeReference
    && Boolean(drawingCadViewerState.rasterDataUrl || (drawingStageCadCanvas && !drawingStageCadCanvas.hidden))
    && Boolean(renderableReference)
    && isDrawingCadReference(renderableReference);
  const cadRasterHref = drawingCadViewerState.rasterDataUrl
    || (() => {
      try {
        return drawingStageCadCanvas && !drawingStageCadCanvas.hidden
          ? drawingStageCadCanvas.toDataURL("image/png")
          : "";
      } catch {
        return "";
      }
    })();
  const referenceMarkup = referenceIsImage
    ? `<image href="${escapeHtml(activeReferenceHref)}" x="0" y="0" width="${canvasWidth}" height="${canvasHeight}" preserveAspectRatio="xMidYMid meet"></image>`
    : referenceIsCadRaster
      ? `<image href="${escapeHtml(cadRasterHref)}" x="0" y="0" width="${canvasWidth}" height="${canvasHeight}" preserveAspectRatio="xMidYMid meet"></image>`
      : "";
  const defsMarkup = `
      <defs>
        <marker id="drawing-export-arrow-head" markerWidth="10" markerHeight="10" refX="8" refY="5" orient="auto">
          <path d="M 0 0 L 10 5 L 0 10 z" fill="#1e9e68"></path>
        </marker>
        <marker id="drawing-export-dimension-arrow" markerWidth="10" markerHeight="10" refX="5" refY="5" orient="auto">
          <path d="M 0 5 L 10 0 L 8 5 L 10 10 z" fill="#da8a1f"></path>
        </marker>
        ${drawingViewportDraft.showGrid === false ? "" : `
        <pattern id="drawing-export-grid-small" width="${gridSize}" height="${gridSize}" patternUnits="userSpaceOnUse">
          <path d="M ${gridSize} 0 L 0 0 0 ${gridSize}" fill="none" stroke="rgba(90,112,162,0.13)" stroke-width="1"></path>
        </pattern>
        <pattern id="drawing-export-grid-major" width="${majorGrid}" height="${majorGrid}" patternUnits="userSpaceOnUse">
          <path d="M ${majorGrid} 0 L 0 0 0 ${majorGrid}" fill="none" stroke="rgba(90,112,162,0.22)" stroke-width="1.2"></path>
        </pattern>
        `}
      </defs>
    `;
  const gridMarkup = drawingViewportDraft.showGrid === false
    ? defsMarkup
    : `
      ${defsMarkup}
      <rect x="0" y="0" width="${canvasWidth}" height="${canvasHeight}" fill="url(#drawing-export-grid-small)"></rect>
      <rect x="0" y="0" width="${canvasWidth}" height="${canvasHeight}" fill="url(#drawing-export-grid-major)"></rect>
    `;
  const elementMarkup = drawingElementDrafts
    .filter((element) => visibleLayerIds.has(String(element.layerId)))
    .map((element) => renderDrawingElementMarkup(element, { selected: false })
      .replaceAll("url(#drawing-arrow-head)", "url(#drawing-export-arrow-head)")
      .replaceAll("url(#drawing-dimension-arrow)", "url(#drawing-export-dimension-arrow)"))
    .join("");
  return `
    <svg xmlns="http://www.w3.org/2000/svg" width="${canvasWidth}" height="${canvasHeight}" viewBox="0 0 ${canvasWidth} ${canvasHeight}">
      <rect x="0" y="0" width="${canvasWidth}" height="${canvasHeight}" fill="#f9fbff"></rect>
      ${gridMarkup}
      ${referenceMarkup}
      ${elementMarkup}
    </svg>
  `.trim();
}

function downloadDrawingSvgFile() {
  const fileName = `${sanitizeDocumentTemplateFileName(drawingProjectDraft?.title || "drawing-studio", "drawing-studio")}.svg`;
  triggerBlobDownload(new Blob([buildDrawingExportSvg(true)], { type: "image/svg+xml;charset=utf-8" }), fileName);
}

function printDrawingAsPdf() {
  const title = escapeHtml(drawingProjectDraft?.title || "Drawing Studio");
  const company = escapeHtml(
    getSortedDrawingCompanies(state.companies).find((item) => String(item.id) === String(drawingProjectDraft?.companyId || ""))?.name
    || "Bez tvrtke",
  );
  const location = escapeHtml(
    getSortedDrawingLocations(state.locations).find((item) => String(item.id) === String(drawingProjectDraft?.locationId || ""))?.name
    || "Bez lokacije",
  );
  const scaleLabel = escapeHtml(drawingProjectDraft?.scaleLabel || "Bez mjerila");
  const svgMarkup = buildDrawingExportSvg(true);
  const html = `<!doctype html>
<html lang="hr">
  <head>
    <meta charset="utf-8" />
    <title>${title}</title>
    <style>
      @page { size: landscape; margin: 16mm; }
      body { margin: 0; font-family: Arial, sans-serif; color: #22314f; }
      .sheet { display: grid; gap: 12px; }
      .meta { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
      .meta-card { border: 1px solid #c9d7f2; border-radius: 14px; padding: 10px 12px; background: #f8fbff; }
      .meta-card strong { display: block; font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #6280bf; margin-bottom: 4px; }
      .stage { border: 1px solid #c9d7f2; border-radius: 18px; overflow: hidden; background: #ffffff; }
      svg { width: 100%; height: auto; display: block; }
    </style>
  </head>
  <body>
    <div class="sheet">
      <div class="meta">
        <div class="meta-card"><strong>Crtež</strong>${title}</div>
        <div class="meta-card"><strong>Tvrtka</strong>${company}</div>
        <div class="meta-card"><strong>Lokacija</strong>${location}</div>
        <div class="meta-card"><strong>Mjerilo</strong>${scaleLabel}</div>
      </div>
      <div class="stage">${svgMarkup}</div>
    </div>
  </body>
</html>`;
  triggerBlobPrint(new Blob(["\ufeff", html], { type: "text/html;charset=utf-8" }), `${sanitizeDocumentTemplateFileName(drawingProjectDraft?.title || "drawing-studio", "drawing-studio")}.pdf`);
}

async function queueDrawingReferenceFiles(files = []) {
  const uploadFiles = Array.from(files ?? []).filter((file) => file instanceof File);
  if (!uploadFiles.length) {
    return;
  }

  const prepared = [];
  for (const file of uploadFiles) {
    const extension = String(file.name || "").split(".").pop()?.toLowerCase() || "";
    if (!DRAWING_REFERENCE_ALLOWED_EXTENSIONS.has(extension)) {
      throw new Error(`Datoteka ${file.name} nije podržana. Dozvoljeno: .dwg, .dxf, .pdf i slike.`);
    }
    if (file.size > DRAWING_REFERENCE_MAX_SIZE_BYTES) {
      throw new Error(`Datoteka ${file.name} mora biti manja od 25 MB.`);
    }
    prepared.push(createModuleAttachmentDraft({
      id: crypto.randomUUID(),
      fileName: file.name,
      fileType: file.type,
      fileSize: file.size,
      previewStatus: ["dwg", "dxf"].includes(extension) ? "pending" : "",
      dataUrl: await readFileAsDataUrl(file, `Ne mogu učitati datoteku ${file.name}.`),
      updatedAt: new Date().toISOString(),
    }));
  }

  drawingReferenceDrafts = [...drawingReferenceDrafts, ...prepared];
  drawingActiveReferenceId = prepared[prepared.length - 1]?.id || drawingActiveReferenceId || "";
  drawingSidebarTab = "references";
  drawingSidebarCollapsed = false;
  setDrawingViewMode(drawingActiveReferenceId ? "reference" : "canvas");
  renderDrawingStudioModule();
}

function applySelectedDrawingInspectorField(fieldName, rawValue) {
  const selected = getDrawingSelectedElement();
  if (!selected) {
    if (fieldName === "layerId") {
      drawingActiveLayerId = String(rawValue || "").trim();
      renderDrawingLayerList();
      renderDrawingInspector();
    }
    return;
  }

  const numericValue = Number(rawValue);
  const isNumeric = Number.isFinite(numericValue);
  const type = String(selected.type || "").trim().toLowerCase();
  const patch = {};

  if (fieldName === "label") {
    patch.label = String(rawValue || "").trim();
    if (type === "dimension") {
      patch.metadata = {
        ...(selected.metadata ?? {}),
        autoLabel: false,
      };
    }
  } else if (fieldName === "stroke") {
    patch.stroke = String(rawValue || "").trim();
  } else if (fieldName === "fill") {
    patch.fill = String(rawValue || "").trim();
  } else if (fieldName === "lineWidth" && isNumeric) {
    patch.lineWidth = Math.max(0, Math.min(24, Math.round(numericValue)));
  } else if (fieldName === "rotation" && isNumeric) {
    patch.rotation = Math.max(-360, Math.min(360, Math.round(numericValue)));
  } else if (fieldName === "layerId") {
    patch.layerId = String(rawValue || "").trim();
    drawingActiveLayerId = patch.layerId;
  } else if (fieldName === "subtitle") {
    patch.metadata = {
      ...(selected.metadata ?? {}),
      subtitle: String(rawValue || "").trim(),
    };
  } else if (fieldName === "footer") {
    patch.metadata = {
      ...(selected.metadata ?? {}),
      footer: String(rawValue || "").trim(),
    };
  } else if (fieldName === "x" && isNumeric) {
    if (DRAWING_LINEAR_TYPES.has(type)) {
      const delta = numericValue - Number(selected.x || 0);
      patch.x = numericValue;
      patch.x2 = Number(selected.x2 || 0) + delta;
    } else {
      patch.x = numericValue;
      patch.x2 = numericValue + Number(selected.width || 0);
    }
  } else if (fieldName === "y" && isNumeric) {
    if (DRAWING_LINEAR_TYPES.has(type)) {
      const delta = numericValue - Number(selected.y || 0);
      patch.y = numericValue;
      patch.y2 = Number(selected.y2 || 0) + delta;
    } else {
      patch.y = numericValue;
      patch.y2 = numericValue + Number(selected.height || 0);
    }
  } else if (fieldName === "x2" && isNumeric) {
    patch.x2 = numericValue;
    if (!DRAWING_LINEAR_TYPES.has(type)) {
      patch.width = Math.max(4, numericValue - Number(selected.x || 0));
    }
  } else if (fieldName === "y2" && isNumeric) {
    patch.y2 = numericValue;
    if (!DRAWING_LINEAR_TYPES.has(type)) {
      patch.height = Math.max(4, numericValue - Number(selected.y || 0));
    }
  } else if (fieldName === "width" && isNumeric) {
    patch.width = Math.max(4, numericValue);
    patch.x2 = Number(selected.x || 0) + patch.width;
  } else if (fieldName === "height" && isNumeric) {
    patch.height = Math.max(4, numericValue);
    patch.y2 = Number(selected.y || 0) + patch.height;
  }

  if (Object.keys(patch).length === 0) {
    return;
  }

  applyDrawingInspectorPatch(patch);
}

function isSidebarGroupAccessible(groupName) {
  if (isClientPortalShellActive()) {
    return groupName === "company";
  }

  if (groupName === "organisations") {
    return !managementTab?.hidden;
  }

  if (groupName === "company") {
    return getCanViewCompanies();
  }

  if (groupName === "locations") {
    return false;
  }

  return ALL_SIDEBAR_GROUPS.includes(groupName);
}

function renderSidebarState() {
  const clientPortalShell = isClientPortalShellActive();
  if (clientPortalShell) {
    ensureClientPortalShellState();
  }

  let activeGroup = state.activeSidebarGroup || getSidebarGroupForView();

  if (!isSidebarGroupAccessible(activeGroup)) {
    activeGroup = getSidebarGroupForView();

    if (!isSidebarGroupAccessible(activeGroup)) {
      activeGroup = "home";
    }

    state.activeSidebarGroup = activeGroup;
  }

  appFrame?.classList.toggle("is-sidebar-collapsed", state.sidebarCollapsed);
  appFrame?.classList.toggle("is-rail-hidden", state.railHidden);
  appFrame?.classList.toggle("is-client-portal-shell", clientPortalShell);
  appSidebar?.classList.toggle("is-collapsed", state.sidebarCollapsed);

  if (sidebarCollapseToggle) {
    sidebarCollapseToggle.setAttribute("aria-expanded", state.sidebarCollapsed ? "false" : "true");
    sidebarCollapseToggle.setAttribute("aria-label", state.sidebarCollapsed ? "Open sidebar" : "Minimize sidebar");
    sidebarCollapseToggle.innerHTML = `<span aria-hidden="true">${state.sidebarCollapsed ? "&rarr;" : "&larr;"}</span>`;
  }

  railButtons.forEach((button) => {
    if (clientPortalShell) {
      button.hidden = true;
      button.classList.remove("is-active");
      return;
    }

    const groupName = button.dataset.sidebarGroup;
    const isAccessible = isSidebarGroupAccessible(groupName);
    button.hidden = !isAccessible;
    button.classList.toggle("is-active", isAccessible && groupName === activeGroup);
  });

  sidebarNavItems.forEach((button) => {
    if (clientPortalShell) {
      button.hidden = button.dataset.sidebarItem !== "client-portal";
    }
    button.classList.toggle("is-active", button.dataset.sidebarItem === state.activeSidebarItem);
  });

  if (appRailToggle) {
    appRailToggle.hidden = clientPortalShell || state.railHidden;
    appRailToggle.setAttribute("aria-label", "Sakrij lijevu traku");
    appRailToggle.innerHTML = `<span aria-hidden="true">&larr;</span>`;
  }

  if (appRailRestore) {
    appRailRestore.hidden = clientPortalShell || !state.railHidden;
    appRailRestore.setAttribute("aria-label", "Prikazi lijevu traku");
    appRailRestore.innerHTML = `<span aria-hidden="true">&rarr;</span>`;
  }

  sidebarGroupPanels.forEach((panel) => {
    const groupName = panel.dataset.sidebarGroupPanel;
    const isAccessible = isSidebarGroupAccessible(groupName);
    const isActive = isAccessible && groupName === activeGroup;
    panel.hidden = !isActive;
    panel.classList.toggle("is-open", isActive);
    panel.querySelector(".sidebar-group-items")?.toggleAttribute("hidden", state.sidebarCollapsed || !isActive);
    const groupToggle = panel.querySelector(".sidebar-group-toggle");
    if (groupToggle) {
      groupToggle.hidden = clientPortalShell && groupName === "company";
      groupToggle.setAttribute("aria-expanded", isActive && !state.sidebarCollapsed ? "true" : "false");
    }
  });
}

function ensureSidebarExpanded(expandSidebar = false) {
  if (expandSidebar && state.sidebarCollapsed) {
    state.sidebarCollapsed = false;
    persistSidebarCollapsed();
  }
}

function setSidebarCollapsed(nextValue) {
  state.sidebarCollapsed = Boolean(nextValue);
  persistSidebarCollapsed();
  renderSidebarState();
}

function setRailHidden(nextValue) {
  state.railHidden = Boolean(nextValue);
  persistRailHidden();
  renderSidebarState();
}

function focusCompanyArea(target = "list") {
  if (!getCanViewCompanies()) {
    return;
  }

  state.activeView = "companies";
  renderActiveView();
  renderCompanies();

  window.requestAnimationFrame(() => {
    if (target === "form") {
      if (getCanCreateCompany()) {
        resetCompanyForm();
        openCompanyEditor();
      }

      companyNameInput?.focus({ preventScroll: true });
    }

    if (target === "location-form") {
      if (state.companies.length === 1) {
        openLocationEditorForCompany(state.companies[0].id);
      } else {
        state.companyEditorActiveTab = "locations";
        syncCompanyEditorTabs();
        companiesSearchInput?.focus({ preventScroll: true });
      }
    }

    workspaceViews.companies?.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
  });
}

function focusLocationArea(target = "list") {
  if (!getCanViewLocations()) {
    return;
  }

  const wasLocationsView = state.activeView === "locations";
  state.activeView = "locations";
  if (target !== "form" && !wasLocationsView) {
    resetLocationListWindow({ scroll: false });
  }
  renderActiveView();
  renderLocations();

  window.requestAnimationFrame(() => {
    if (target === "form") {
      if (getCanCreateLocations() && state.companies.length > 0) {
        resetLocationForm();
        openLocationEditor();
        locationNameInput?.focus({ preventScroll: true });
      }
    } else {
      locationsSearchInput?.focus({ preventScroll: true });
    }

    workspaceViews.locations?.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
  });
}

function activateSidebarItem(itemName, options = {}) {
  const {
    expandSidebar = false,
    preserveGroup = false,
  } = options;
  const itemConfig = SIDEBAR_ITEM_CONFIG[itemName];

  if (!itemConfig) {
    return;
  }

  if (isClientPortalShellActive() && itemName !== "client-portal") {
    ensureClientPortalShellState();
    renderActiveView();
    return;
  }

  closeTransientNavigationOverlays();
  ensureSidebarExpanded(expandSidebar);
  state.activeSidebarItem = itemConfig.sidebarItem || itemName;

  if (!preserveGroup && itemConfig.group) {
    state.activeSidebarGroup = itemConfig.group;
  }

  if (itemConfig.view === "module") {
    if (itemConfig.module === "contract" && !getCanViewContracts()) {
      return;
    }
    if (itemConfig.module === "client-portal" && !getCanUseClientPortalRecords()) {
      return;
    }
    if (itemConfig.module === "jobs" && !getCanViewJobs()) {
      return;
    }
    state.activeModuleItem = itemConfig.module;
    state.activeView = "module";
    renderModuleView();
    renderActiveView();
    return;
  }

  if (itemConfig.view === "reminders") {
    state.activeView = "reminders";
    renderActiveView();
    workspaceViews.reminders?.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
    return;
  }

  if (itemConfig.view === "todo") {
    state.activeView = "todo";
    renderActiveView();
    workspaceViews.todo?.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
    return;
  }

  if (itemConfig.view === "notifications") {
    state.activeView = "notifications";
    renderActiveView();
    workspaceViews.notifications?.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
    return;
  }

  if (itemConfig.view === "management") {
    setPeopleWorkspaceTab(itemConfig.managementTab || "users");
    state.activeView = "management";
    renderActiveView();
    renderManagement();
    workspaceViews.management?.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
    return;
  }

  if (itemConfig.view === "companies") {
    if (!getCanViewCompanies()) {
      return;
    }
    focusCompanyArea(itemConfig.focus);
    return;
  }

  if (itemConfig.view === "locations") {
    focusLocationArea(itemConfig.focus);
    return;
  }

  if (itemConfig.view === "selfdash") {
    state.activeView = "selfdash";
    renderActiveView();

    if (itemConfig.focus === "control-panel") {
      dashboardControlPanel?.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
      return;
    }

    if (itemConfig.focus === "list") {
      workOrdersTableWrap?.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
      return;
    }

    workspaceViews.selfdash?.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
  }
}

function activateSidebarGroup(groupName, options = {}) {
  const {
    navigate = false,
    expandSidebar = false,
  } = options;

  if (isClientPortalShellActive()) {
    ensureClientPortalShellState();
    ensureSidebarExpanded(expandSidebar);
    if (navigate) {
      renderActiveView();
    }
    return;
  }

  if (!isSidebarGroupAccessible(groupName)) {
    return;
  }

  closeTransientNavigationOverlays();
  state.activeSidebarGroup = groupName;
  ensureSidebarExpanded(expandSidebar);

  if (navigate) {
    const targetItem = SIDEBAR_GROUP_DEFAULT_ITEM[groupName];

    if (targetItem) {
      activateSidebarItem(targetItem, { preserveGroup: true });
      return;
    }

    const targetView = SIDEBAR_GROUP_DEFAULT_VIEW[groupName];

    if (targetView) {
      state.activeView = targetView;
    }
  }

  renderActiveView();
}

function focusSelfDashArea(target = "top") {
  state.activeView = "selfdash";

  if (!["home", "operations"].includes(state.activeSidebarGroup)) {
    state.activeSidebarGroup = target === "top" ? "home" : "operations";
  }

  if (target === "top") {
    state.activeSidebarItem = "dashboard";
  } else if (target === "list") {
    state.activeSidebarItem = "rn";
  }

  renderActiveView();

  if (target === "composer") {
    focusWorkOrderComposer();
    return;
  }

  if (target === "list") {
    workOrdersTableWrap?.scrollIntoView({
      behavior: "smooth",
      block: "start",
    });
    return;
  }

  workspaceViews.selfdash?.scrollIntoView({
    behavior: "smooth",
    block: "start",
  });
}

function parseDateValue(value) {
  if (!value) {
    return null;
  }

  const rawValue = String(value).trim();
  const compactRawValue = normalizeCompactTypedDateValue(rawValue);
  if (compactRawValue && compactRawValue !== rawValue) {
    return parseDateValue(compactRawValue);
  }
  const createLocalDate = (year, month, day) => {
    if (
      !Number.isFinite(day)
      || !Number.isFinite(month)
      || !Number.isFinite(year)
      || day < 1
      || day > 31
      || month < 1
      || month > 12
    ) {
      return null;
    }
    const parsed = new Date(year, month - 1, day, 12, 0, 0, 0);
    if (
      Number.isNaN(parsed.getTime())
      || parsed.getFullYear() !== year
      || parsed.getMonth() !== month - 1
      || parsed.getDate() !== day
    ) {
      return null;
    }
    return parsed;
  };

  const isoDateOnlyMatch = rawValue.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (isoDateOnlyMatch) {
    const year = Number(isoDateOnlyMatch[1]);
    const month = Number(isoDateOnlyMatch[2]);
    const day = Number(isoDateOnlyMatch[3]);
    return createLocalDate(year, month, day);
  }

  const croatianDateMatch = rawValue.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})\.?$/);
  if (croatianDateMatch) {
    const day = Number(croatianDateMatch[1]);
    const month = Number(croatianDateMatch[2]);
    const year = Number(croatianDateMatch[3]);
    return createLocalDate(year, month, day);
  }

  const directDate = new Date(rawValue);

  if (!Number.isNaN(directDate.getTime())) {
    return directDate;
  }

  const normalizedDateOnly = new Date(`${rawValue.slice(0, 10)}T12:00:00`);

  if (!Number.isNaN(normalizedDateOnly.getTime())) {
    return normalizedDateOnly;
  }

  return null;
}

function normalizeCompactTypedDateValue(value = "") {
  const rawValue = String(value ?? "").trim();
  if (!rawValue) {
    return "";
  }

  const digitValue = rawValue.replace(/\s+/g, "");
  if (!/^\d+$/.test(digitValue)) {
    return rawValue;
  }

  if (digitValue.length === 8) {
    return `${digitValue.slice(0, 2)}.${digitValue.slice(2, 4)}.${digitValue.slice(4)}`;
  }

  if (digitValue.length === 6) {
    const yearPrefix = Number(digitValue.slice(4)) >= 70 ? "19" : "20";
    return `${digitValue.slice(0, 2)}.${digitValue.slice(2, 4)}.${yearPrefix}${digitValue.slice(4)}`;
  }

  return rawValue;
}

function normalizeLiveDateTypingValue(value = "") {
  const rawValue = String(value ?? "").trim();
  if (!rawValue) {
    return "";
  }

  const digitValue = rawValue.replace(/\s+/g, "");
  if (/^\d{8}$/.test(digitValue)) {
    return `${digitValue.slice(0, 2)}.${digitValue.slice(2, 4)}.${digitValue.slice(4)}`;
  }

  return rawValue;
}

function formatDate(value) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return "Bez datuma";
  }

  return formatCompactDate(parsedDate);
}

function formatCompactDate(value) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return "Bez datuma";
  }

  const day = String(parsedDate.getDate()).padStart(2, "0");
  const month = String(parsedDate.getMonth() + 1).padStart(2, "0");
  const year = parsedDate.getFullYear();
  return `${day}.${month}.${year}`;
}

function formatCompactTime(value) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return "";
  }

  const hours = String(parsedDate.getHours()).padStart(2, "0");
  const minutes = String(parsedDate.getMinutes()).padStart(2, "0");
  return `${hours}:${minutes}`;
}

function formatCompactDateTime(value) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return "";
  }

  return [formatCompactDate(parsedDate), formatCompactTime(parsedDate)].filter(Boolean).join(" | ");
}

function formatCompactDueDate(value) {
  if (!value) {
    return "Bez roka";
  }

  return formatCompactDate(value);
}

function formatCompactOpenedDate(value) {
  if (!value) {
    return "Bez datuma";
  }

  return formatCompactDate(value);
}

function formatDateTime(value) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return "Bez datuma";
  }

  return [formatCompactDate(parsedDate), formatCompactTime(parsedDate)].filter(Boolean).join(" | ");
}

function toDateKey(value) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return "";
  }

  const year = parsedDate.getFullYear();
  const month = String(parsedDate.getMonth() + 1).padStart(2, "0");
  const day = String(parsedDate.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function formatDateInputDisplayValue(value) {
  const rawValue = String(value ?? "").trim();
  if (!rawValue) {
    return "";
  }

  const normalizedRawValue = normalizeCompactTypedDateValue(rawValue)
    .replace(/^(\d{1,2})\s*\/\s*(\d{1,2})\s*\/\s*(\d{4})$/, "$1.$2.$3");
  const looksLikeCompleteDate = /^\d{4}-\d{2}-\d{2}$/.test(normalizedRawValue)
    || /^\d{1,2}\.\d{1,2}\.\d{4}\.?$/.test(normalizedRawValue);
  if (!looksLikeCompleteDate) {
    return rawValue;
  }

  const parsedDate = parseDateValue(normalizedRawValue);
  return parsedDate ? formatCompactDate(parsedDate) : rawValue;
}

function normalizeDateInputValue(value) {
  const rawValue = String(value ?? "").trim();
  if (!rawValue) {
    return "";
  }

  const normalizedRawValue = normalizeCompactTypedDateValue(rawValue)
    .replace(/^(\d{1,2})\s*\/\s*(\d{1,2})\s*\/\s*(\d{4})$/, "$1.$2.$3");
  const looksLikeCompleteDate = /^\d{4}-\d{2}-\d{2}$/.test(normalizedRawValue)
    || /^\d{1,2}\.\d{1,2}\.\d{4}\.?$/.test(normalizedRawValue);
  if (!looksLikeCompleteDate) {
    return rawValue;
  }

  const parsedDate = parseDateValue(normalizedRawValue);
  return parsedDate ? toDateKey(parsedDate) : rawValue;
}

function addMonthsToDateKey(value, monthsValue) {
  const normalizedDate = toDateKey(value);
  const months = Number.parseInt(String(monthsValue ?? "").trim(), 10);
  if (!normalizedDate || !Number.isFinite(months) || months <= 0) {
    return "";
  }

  const [year, month, day] = normalizedDate.split("-").map((part) => Number.parseInt(part, 10));
  const date = new Date(year, month - 1, day);
  const originalDay = date.getDate();
  date.setMonth(date.getMonth() + months);
  if (date.getDate() !== originalDay) {
    date.setDate(0);
  }
  return toDateKey(date);
}

function getNormalizedWorkOrderDateInputValue(input) {
  return normalizeDateInputValue(input?.value ?? "");
}

function setWorkOrderDateInputValue(input, value) {
  if (!input) {
    return;
  }
  input.value = formatDateInputDisplayValue(value);
}

function normalizeWorkOrderDateInputDisplay(input) {
  if (!input) {
    return "";
  }
  const normalizedValue = normalizeDateInputValue(input.value);
  input.value = formatDateInputDisplayValue(normalizedValue);
  return normalizedValue;
}

function ensureWorkOrderDateInputDisplay(input) {
  if (!input) {
    return "";
  }

  const rawValue = String(input.value || "").trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(rawValue)) {
    input.value = formatDateInputDisplayValue(rawValue);
  }

  return input.value;
}

function ensureWorkOrderDateInputsDisplay() {
  [
    workOrderOpenedDateInput,
    workOrderDueDateInput,
    workOrderExecutionDateInput,
    workOrderInvoiceDateInput,
  ].forEach((input) => {
    ensureWorkOrderDateInputDisplay(input);
  });
}

function getStartOfWeekDateKey(value) {
  const parsedDate = parseDateValue(value) ?? new Date();
  const start = new Date(parsedDate);
  const offset = (start.getDay() + 6) % 7;
  start.setHours(12, 0, 0, 0);
  start.setDate(start.getDate() - offset);
  return toDateKey(start);
}

function shiftDateKey(value, days) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return toDateKey(new Date());
  }

  const shifted = new Date(parsedDate);
  shifted.setDate(shifted.getDate() + days);
  return toDateKey(shifted);
}

function getWorkOrderDefaultDueDays() {
  const value = getPeriodicsVisualSettings().workOrderDefaultDueDays;
  if (String(value ?? "").trim() === "") {
    return null;
  }
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.max(0, Math.min(365, Math.round(numeric))) : null;
}

function resolveDefaultWorkOrderDueDate(openedDate = getTodayDateKey()) {
  const days = getWorkOrderDefaultDueDays();
  if (days === null) {
    return "";
  }
  return shiftDateKey(openedDate || getTodayDateKey(), days);
}

function applyDefaultWorkOrderDueDate({ force = false } = {}) {
  if (!workOrderDueDateInput || !workOrderOpenedDateInput) {
    return "";
  }

  const currentDueDate = getNormalizedWorkOrderDateInputValue(workOrderDueDateInput);
  const shouldApply = force || !currentDueDate || workOrderDueDateInput.dataset.autoDefaultDue === "true";
  if (!shouldApply) {
    return currentDueDate;
  }

  const nextDueDate = resolveDefaultWorkOrderDueDate(getNormalizedWorkOrderDateInputValue(workOrderOpenedDateInput) || getTodayDateKey());
  setWorkOrderDateInputValue(workOrderDueDateInput, nextDueDate);
  workOrderDueDateInput.dataset.autoDefaultDue = nextDueDate ? "true" : "false";
  return nextDueDate;
}

function shiftMonthDateKey(value, months) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return toDateKey(new Date());
  }

  const shifted = new Date(parsedDate);
  shifted.setDate(1);
  shifted.setMonth(shifted.getMonth() + months);
  return toDateKey(shifted);
}

function getCalendarIsoWeekNumber(value) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return 0;
  }

  const workingDate = new Date(parsedDate);
  const day = (workingDate.getDay() + 6) % 7;
  workingDate.setDate(workingDate.getDate() - day + 3);
  const firstThursday = new Date(workingDate.getFullYear(), 0, 4);
  const firstThursdayDay = (firstThursday.getDay() + 6) % 7;
  firstThursday.setDate(firstThursday.getDate() - firstThursdayDay + 3);
  return 1 + Math.round((workingDate - firstThursday) / 604800000);
}

function formatCalendarMonthLabel(value = state.workOrderCalendar.weekStart) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return "Kalendar";
  }

  return new Intl.DateTimeFormat("hr-HR", {
    month: "long",
    year: "numeric",
  }).format(parsedDate);
}

function formatCalendarWeekRangeLabel(startValue, endValue) {
  if (!startValue) {
    return "Kalendar";
  }

  const endDate = endValue || startValue;
  const weekNumber = getCalendarIsoWeekNumber(startValue);
  return `Tjedan ${weekNumber} · ${formatCompactDate(startValue)} - ${formatCompactDate(endDate)}`;
}

function buildWorkOrderCalendarWeekDays(
  weekStart = state.workOrderCalendar.weekStart,
  showWeekends = state.workOrderCalendar.showWeekends,
) {
  const todayKey = toDateKey(new Date());
  const days = Array.from({ length: 7 }, (_, index) => {
    const dateKey = shiftDateKey(weekStart, index);
    const parsedDate = parseDateValue(dateKey);
    return {
      key: dateKey,
      dayIndex: parsedDate.getDay(),
      label: new Intl.DateTimeFormat("hr-HR", {
        weekday: "short",
      }).format(parsedDate),
      dateLabel: formatCompactDate(dateKey),
      compactLabel: new Intl.DateTimeFormat("hr-HR", {
        day: "2-digit",
        month: "2-digit",
      }).format(parsedDate),
      fullLabel: formatCompactDate(dateKey),
      isToday: dateKey === todayKey,
    };
  });

  return showWeekends ? days : days.filter((day) => day.dayIndex !== 0 && day.dayIndex !== 6);
}

function formatCalendarRangeLabel(
  weekStart = state.workOrderCalendar.weekStart,
  showWeekends = state.workOrderCalendar.showWeekends,
) {
  const days = buildWorkOrderCalendarWeekDays(weekStart, showWeekends);
  return formatCalendarWeekRangeLabel(days[0]?.key || weekStart, days[days.length - 1]?.key || weekStart);
}

function getWorkOrderViewModeLabel(mode = state.activeWorkOrderViewMode) {
  return WORK_ORDER_VIEW_MODES.find((item) => item.value === mode)?.label ?? "List";
}

