function createWorkOrderEditorMetaIcon(iconName) {
  const icon = document.createElement("span");
  icon.className = `work-order-editor-meta-icon is-${iconName}`;
  icon.innerHTML = getWorkOrderIconMarkup(iconName);
  return icon;
}

function createWorkOrderEditorMetaItem(iconName, label, value, contentNode = null) {
  const item = document.createElement("div");
  item.className = "work-order-editor-meta-item";

  const body = document.createElement("div");
  body.className = "work-order-editor-meta-body";

  const labelNode = document.createElement("span");
  labelNode.className = "work-order-editor-meta-label";
  labelNode.textContent = label;

  body.append(labelNode);

  if (contentNode) {
    body.append(contentNode);
  } else {
    const valueNode = document.createElement("strong");
    valueNode.className = "work-order-editor-meta-value";
    valueNode.textContent = value || "-";
    body.append(valueNode);
  }

  item.append(createWorkOrderEditorMetaIcon(iconName), body);
  return item;
}

function expandWorkOrderEditorSections(sectionKeys = []) {
  (Array.isArray(sectionKeys) ? sectionKeys : [sectionKeys])
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .forEach((sectionKey) => {
      state.workOrderEditorCollapsedSections[sectionKey] = false;
      syncWorkOrderEditorSectionCollapse(
        workOrderForm?.querySelector(`.work-order-editor-section[data-work-order-section="${sectionKey}"]`),
      );
    });
}

function focusWorkOrderEditorSection(sectionKeys = []) {
  const keys = (Array.isArray(sectionKeys) ? sectionKeys : [sectionKeys])
    .map((value) => String(value || "").trim())
    .filter(Boolean);
  if (keys.length === 0) {
    return;
  }

  expandWorkOrderEditorSections(keys);
  const target = workOrderForm?.querySelector(`.work-order-editor-section[data-work-order-section="${keys[0]}"]`);
  if (!(target instanceof HTMLElement)) {
    return;
  }

  requestAnimationFrame(() => {
    target.scrollIntoView({ block: "start", behavior: "smooth" });
    target.classList.add("is-editor-focus-pulse");
    window.setTimeout(() => {
      target.classList.remove("is-editor-focus-pulse");
    }, 1200);
  });
}

function createWorkOrderEditorStageCard({
  iconName = "service",
  label = "",
  value = "",
  targetSections = [],
  tone = "",
} = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `work-order-editor-stage-card${tone ? ` is-${tone}` : ""}`.trim();
  button.dataset.preventRowOpen = "true";
  button.setAttribute("aria-label", `${label}: ${value || ""}`.trim());

  const icon = document.createElement("span");
  icon.className = "work-order-editor-stage-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.innerHTML = getWorkOrderIconMarkup(iconName);

  const copy = document.createElement("span");
  copy.className = "work-order-editor-stage-copy";

  const labelNode = document.createElement("strong");
  labelNode.textContent = label;
  const valueNode = document.createElement("span");
  valueNode.textContent = value || "-";
  copy.append(labelNode, valueNode);

  button.append(icon, copy);
  button.addEventListener("click", () => {
    focusWorkOrderEditorSection(targetSections);
  });
  return button;
}

function createWorkOrderEditorPlainValue(value = "", { muted = false } = {}) {
  const node = document.createElement("span");
  node.className = `work-order-editor-detail-value${muted ? " is-muted" : ""}`;
  node.textContent = value || "-";
  return node;
}

function createWorkOrderEditorStatusPill(statusLabel = "Otvoreni RN", statusValue = statusLabel) {
  const pill = document.createElement("span");
  pill.className = "work-order-editor-detail-status-pill";
  pill.dataset.status = slugifyValue(statusValue || statusLabel || "Otvoreni RN");
  pill.textContent = statusLabel || "Otvoreni RN";
  return pill;
}

function createWorkOrderEditorPriorityPill(priorityLabel = "Normal", priorityValue = priorityLabel) {
  const pill = document.createElement("span");
  pill.className = "work-order-editor-detail-priority-pill";
  pill.dataset.priority = slugifyValue(priorityValue || priorityLabel || "Normal");
  pill.textContent = priorityLabel || "Normal";
  return pill;
}

function splitWorkOrderTags(value = "") {
  const rawValue = Array.isArray(value) ? value.join(",") : String(value ?? "");
  const seen = new Set();
  return rawValue
    .split(/[|,;/\n]+/u)
    .map((entry) => entry.trim())
    .filter((entry) => {
      const key = normalizeLooseName(entry);
      if (!entry || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .slice(0, 32);
}

const WORK_ORDER_TAG_TONES = Object.freeze([
  { bg: "#e9415e", border: "#d62f4b", color: "#ffffff", softBg: "#ffe4ea", softBorder: "#ffc2cd", softColor: "#9f1239" },
  { bg: "#2563eb", border: "#1d4ed8", color: "#ffffff", softBg: "#dbeafe", softBorder: "#bfdbfe", softColor: "#1d4ed8" },
  { bg: "#0f9f7a", border: "#0d8b69", color: "#ffffff", softBg: "#d1fae5", softBorder: "#a7f3d0", softColor: "#047857" },
  { bg: "#7c3aed", border: "#6d28d9", color: "#ffffff", softBg: "#ede9fe", softBorder: "#ddd6fe", softColor: "#6d28d9" },
  { bg: "#ea580c", border: "#c2410c", color: "#ffffff", softBg: "#ffedd5", softBorder: "#fed7aa", softColor: "#c2410c" },
  { bg: "#be185d", border: "#9d174d", color: "#ffffff", softBg: "#fce7f3", softBorder: "#fbcfe8", softColor: "#be185d" },
  { bg: "#4f46e5", border: "#4338ca", color: "#ffffff", softBg: "#e0e7ff", softBorder: "#c7d2fe", softColor: "#4338ca" },
  { bg: "#0e7490", border: "#155e75", color: "#ffffff", softBg: "#cffafe", softBorder: "#a5f3fc", softColor: "#0e7490" },
]);

function getWorkOrderTagTone(value = "") {
  const normalized = normalizeLooseName(value);
  let hash = 0;
  for (let index = 0; index < normalized.length; index += 1) {
    hash = ((hash * 31) + normalized.charCodeAt(index)) >>> 0;
  }
  return WORK_ORDER_TAG_TONES[hash % WORK_ORDER_TAG_TONES.length];
}

function applyWorkOrderTagTone(node, value = "", { soft = false } = {}) {
  if (!(node instanceof HTMLElement)) {
    return node;
  }

  const tone = getWorkOrderTagTone(value);
  node.style.setProperty("--work-order-tag-bg", soft ? tone.softBg : tone.bg);
  node.style.setProperty("--work-order-tag-border", soft ? tone.softBorder : tone.border);
  node.style.setProperty("--work-order-tag-color", soft ? tone.softColor : tone.color);
  node.style.setProperty("--work-order-tag-soft-bg", tone.softBg);
  node.style.setProperty("--work-order-tag-soft-border", tone.softBorder);
  node.style.setProperty("--work-order-tag-soft-color", tone.softColor);
  return node;
}

function getKnownWorkOrderTags(additionalTags = []) {
  const tags = [
    ...splitWorkOrderTags(additionalTags),
    ...(state.workOrders ?? []).flatMap((item) => splitWorkOrderTags(item?.tagText ?? "")),
  ];
  const seen = new Set();
  return tags
    .filter((tag) => {
      const key = normalizeLooseName(tag);
      if (!tag || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .sort((left, right) => left.localeCompare(right, "hr", { sensitivity: "base" }));
}

function formatWorkOrderTagText(tags = []) {
  return splitWorkOrderTags(tags).join(", ");
}

function createWorkOrderTagPickerControl({
  value = "",
  placeholder = "Tagovi",
  className = "",
  ariaLabel = "Odaberi tagove",
  onChange = () => {},
  onCommit = null,
} = {}) {
  const wrapper = document.createElement("span");
  wrapper.className = ["work-order-tag-picker", "work-order-quick-picker", className].filter(Boolean).join(" ");
  wrapper.dataset.preventRowOpen = "true";

  const field = document.createElement("span");
  field.className = "work-order-tag-picker-field work-order-quick-picker-trigger";
  field.dataset.preventRowOpen = "true";
  field.tabIndex = 0;
  field.setAttribute("role", "combobox");
  field.setAttribute("aria-haspopup", "dialog");
  field.setAttribute("aria-expanded", "false");
  field.setAttribute("aria-label", ariaLabel);

  const chipsWrap = document.createElement("span");
  chipsWrap.className = "work-order-tag-picker-trigger-copy work-order-tag-picker-chip-wrap";

  const searchInput = document.createElement("input");
  searchInput.type = "text";
  searchInput.className = "work-order-tag-picker-inline-input";
  searchInput.autocomplete = "off";
  searchInput.spellcheck = false;
  searchInput.dataset.preventRowOpen = "true";
  searchInput.setAttribute("aria-label", `${ariaLabel} - pretraga ili novi tag`);

  const caret = document.createElement("span");
  caret.className = "work-order-editor-field-caret";
  caret.setAttribute("aria-hidden", "true");
  caret.textContent = "⌄";

  field.append(chipsWrap, searchInput, caret);

  let selectedTags = splitWorkOrderTags(value);
  let searchQuery = "";
  let optionsList = null;
  let clearButton = null;
  let hasPendingCommit = false;

  const commitTags = () => {
    hasPendingCommit = true;
    onChange([...selectedTags]);
  };

  const setSelectedTags = (nextTags, { commit = true } = {}) => {
    selectedTags = splitWorkOrderTags(nextTags);
    renderField();
    if (commit) {
      commitTags();
    }
  };

  const renderField = () => {
    chipsWrap.replaceChildren();
    field.title = selectedTags.length ? selectedTags.join(", ") : placeholder;
    searchInput.placeholder = selectedTags.length ? "" : placeholder;
    if (selectedTags.length === 0) {
      const empty = document.createElement("span");
      empty.className = "work-order-tag-picker-empty-hint";
      empty.textContent = "";
      chipsWrap.append(empty);
      return;
    }

    selectedTags.forEach((tag) => {
      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = "work-order-tag-picker-field-chip work-order-editor-detail-tag";
      chip.dataset.preventRowOpen = "true";
      chip.setAttribute("aria-label", `Ukloni tag ${tag}`);
      applyWorkOrderTagTone(chip, tag);
      const label = document.createElement("span");
      label.textContent = tag;
      const remove = document.createElement("span");
      remove.className = "work-order-tag-picker-field-chip-remove";
      remove.setAttribute("aria-hidden", "true");
      remove.textContent = "×";
      chip.append(label, remove);
      chip.addEventListener("click", (event) => {
        event.stopPropagation();
        setSelectedTags(selectedTags.filter((entry) => normalizeLooseName(entry) !== normalizeLooseName(tag)));
        renderMenu();
        openMenu({ focusInput: true });
      });
      chipsWrap.append(chip);
    });
  };

  const positionMenu = (menu) => {
    const triggerRect = field.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    let left = triggerRect.left;
    let top = triggerRect.bottom + 8;

    if (left + menuRect.width > window.innerWidth - 12) {
      left = Math.max(12, window.innerWidth - menuRect.width - 12);
    }
    if (top + menuRect.height > window.innerHeight - 12) {
      top = Math.max(12, triggerRect.top - menuRect.height - 8);
    }

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.minWidth = `${Math.max(300, Math.round(triggerRect.width + 48))}px`;
  };

  const closeMenu = () => {
    wrapper.classList.remove("is-open");
    field.setAttribute("aria-expanded", "false");
    if (wrapper._menuPortal) {
      wrapper._menuPortal.remove();
      wrapper._menuPortal = null;
    }
    if (hasPendingCommit) {
      hasPendingCommit = false;
      if (typeof onCommit === "function") {
        onCommit([...selectedTags]);
      }
    }
  };

  const renderOptions = () => {
    if (!(optionsList instanceof HTMLElement)) {
      return;
    }

    optionsList.replaceChildren();
    const normalizedQuery = normalizeLooseName(searchQuery);
    const selectedKeys = new Set(selectedTags.map((tag) => normalizeLooseName(tag)));
    const knownTags = getKnownWorkOrderTags(selectedTags);
    const visibleTags = knownTags.filter((tag) => (
      !normalizedQuery || normalizeLooseName(tag).includes(normalizedQuery)
    ));

    const typedTag = searchQuery.trim();
    const typedKey = normalizeLooseName(typedTag);
    if (typedTag && !knownTags.some((tag) => normalizeLooseName(tag) === typedKey)) {
      const createButton = document.createElement("button");
      createButton.type = "button";
      createButton.className = "work-item-status-option work-order-tag-picker-option is-create";
      createButton.innerHTML = `<span><strong>Dodaj "${escapeHtml(typedTag)}"</strong><small>Novi tag</small></span><span class="work-order-quick-picker-marker">+</span>`;
      createButton.addEventListener("click", (event) => {
        event.stopPropagation();
        setSelectedTags([...selectedTags, typedTag]);
        searchInput.value = "";
        searchQuery = "";
        renderMenu();
        searchInput.focus({ preventScroll: true });
      });
      optionsList.append(createButton);
    }

    if (visibleTags.length === 0 && !typedTag) {
      const empty = document.createElement("p");
      empty.className = "work-order-quick-picker-empty";
      empty.textContent = "Nema spremljenih tagova.";
      optionsList.append(empty);
      return;
    }

    visibleTags.forEach((tag) => {
      const isSelected = selectedKeys.has(normalizeLooseName(tag));
      const option = document.createElement("button");
      option.type = "button";
      option.className = `work-item-status-option work-order-tag-picker-option${isSelected ? " is-selected" : ""}`;
      option.setAttribute("role", "menuitemcheckbox");
      option.setAttribute("aria-checked", String(isSelected));

      const chip = document.createElement("span");
      chip.className = "work-order-editor-detail-tag";
      chip.textContent = tag;
      applyWorkOrderTagTone(chip, tag);

      const marker = document.createElement("span");
      marker.className = "work-order-quick-picker-marker";
      marker.textContent = isSelected ? "✓" : "+";

      option.append(chip, marker);
      option.addEventListener("click", (event) => {
        event.stopPropagation();
        setSelectedTags(isSelected
          ? selectedTags.filter((entry) => normalizeLooseName(entry) !== normalizeLooseName(tag))
          : [...selectedTags, tag]);
        searchInput.value = "";
        searchQuery = "";
        renderMenu();
        searchInput.focus({ preventScroll: true });
      });
      optionsList.append(option);
    });
  };

  const renderMenu = () => {
    renderOptions();
    if (clearButton instanceof HTMLButtonElement) {
      clearButton.disabled = selectedTags.length === 0;
    }
    if (wrapper._menuPortal) {
      requestAnimationFrame(() => positionMenu(wrapper._menuPortal));
    }
  };

  const addTypedTag = () => {
    const typedTag = searchInput.value.trim();
    if (!typedTag) {
      return false;
    }
    setSelectedTags([...selectedTags, typedTag]);
    searchInput.value = "";
    searchQuery = "";
    renderMenu();
    return true;
  };

  const openMenu = ({ focusInput = false } = {}) => {
    closeOpenWorkOrderStatusMenus(wrapper);
    if (wrapper._menuPortal) {
      renderMenu();
      if (focusInput) {
        searchInput.focus({ preventScroll: true });
      }
      return;
    }

    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal work-order-tag-picker-menu-portal work-order-quick-picker-menu-portal";
    menu.dataset.preventRowOpen = "true";
    menu.setAttribute("role", "dialog");
    menu.setAttribute("aria-label", ariaLabel);

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => event.stopPropagation());
    });
    menu.addEventListener("wheel", (event) => event.stopPropagation(), { passive: true });

    optionsList = document.createElement("div");
    optionsList.className = "work-order-tag-picker-options work-order-quick-picker-options";

    const actions = document.createElement("div");
    actions.className = "work-order-inline-field-actions work-order-tag-picker-actions";
    clearButton = document.createElement("button");
    clearButton.type = "button";
    clearButton.className = "ghost-button";
    clearButton.textContent = "Očisti";
    const doneButton = document.createElement("button");
    doneButton.type = "button";
    doneButton.className = "primary-button";
    doneButton.textContent = "Gotovo";
    actions.append(clearButton, doneButton);

    clearButton.addEventListener("click", (event) => {
      event.stopPropagation();
      setSelectedTags([]);
      searchInput.value = "";
      searchQuery = "";
      renderMenu();
      searchInput.focus({ preventScroll: true });
    });
    doneButton.addEventListener("click", (event) => {
      event.stopPropagation();
      closeMenu();
      searchInput.blur();
      field.blur();
    });

    menu.append(optionsList, actions);
    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    field.setAttribute("aria-expanded", "true");
    renderMenu();
    requestAnimationFrame(() => {
      positionMenu(menu);
      if (focusInput) {
        searchInput.focus({ preventScroll: true });
      }
    });
  };

  wrapper._closeMenu = closeMenu;
  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    wrapper.addEventListener(eventName, (event) => event.stopPropagation());
  });

  field.addEventListener("click", (event) => {
    event.stopPropagation();
    openMenu({ focusInput: true });
  });
  field.addEventListener("focus", () => {
    openMenu();
  });
  searchInput.addEventListener("focus", () => {
    openMenu();
  });
  searchInput.addEventListener("input", () => {
    searchQuery = searchInput.value || "";
    openMenu();
    renderMenu();
  });
  searchInput.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      addTypedTag();
      return;
    }
    if (event.key === "Backspace" && !searchInput.value && selectedTags.length > 0) {
      setSelectedTags(selectedTags.slice(0, -1));
      renderMenu();
      return;
    }
    if (event.key === "Escape") {
      event.preventDefault();
      closeMenu();
      searchInput.blur();
    }
  });

  renderField();
  wrapper.append(field);
  return wrapper;
}

function createWorkOrderEditorTagsContent(tagText = "") {
  return createWorkOrderTagPickerControl({
    value: tagText,
    placeholder: "Tagovi",
    className: "work-order-editor-tag-picker",
    ariaLabel: "Odaberi tagove radnog naloga",
    onChange: (tags) => {
      if (!(workOrderTagTextInput instanceof HTMLInputElement)) {
        return;
      }
      const nextValue = formatWorkOrderTagText(tags);
      if (workOrderTagTextInput.value === nextValue) {
        return;
      }
      workOrderTagTextInput.value = nextValue;
      queueWorkOrderAutoSave();
    },
    onCommit: () => {
      void persistWorkOrderAutoSave({ immediate: true });
    },
  });
}

function createWorkOrderEditorDatesContent(openedDateLabel = "", dueDateLabel = "") {
  const wrap = document.createElement("span");
  wrap.className = "work-order-editor-detail-dates";

  const start = document.createElement("span");
  start.className = openedDateLabel === "Bez datuma" ? "is-muted" : "";
  start.textContent = openedDateLabel || "Bez datuma";

  const arrow = document.createElement("span");
  arrow.className = "work-order-editor-detail-date-arrow";
  arrow.textContent = "->";

  const due = document.createElement("strong");
  due.className = dueDateLabel === "Bez roka" ? "is-muted" : "";
  due.textContent = dueDateLabel || "Bez roka";

  wrap.append(start, arrow, due);
  return wrap;
}

function createWorkOrderEditorAssigneesContent(executorValues = []) {
  const wrap = document.createElement("span");
  wrap.className = "work-order-editor-detail-assignees";
  const values = (Array.isArray(executorValues) ? executorValues : [])
    .map((value) => String(value || "").trim())
    .filter(Boolean);

  if (values.length === 0) {
    wrap.append(createWorkOrderEditorPlainValue("Empty", { muted: true }));
    return wrap;
  }

  const stack = document.createElement("span");
  stack.className = "work-order-editor-detail-avatar-stack";
  values.slice(0, 3).forEach((value) => {
    stack.append(createWorkOrderMiniExecutor(value, {
      className: "work-order-mini-executor work-order-editor-detail-avatar",
    }));
  });
  if (values.length > 3) {
    stack.append(createExecutorOverflowBadge(values.length - 3, "work-order-mini-executor work-order-editor-detail-avatar"));
  }

  const label = document.createElement("span");
  label.className = "work-order-editor-detail-assignee-label";
  label.textContent = values.length === 1 ? values[0] : `${values[0]} +${values.length - 1}`;

  wrap.append(stack, label);
  return wrap;
}

function dispatchWorkOrderEditorFieldEvent(input, eventName = "change") {
  if (!(input instanceof HTMLElement)) {
    return;
  }

  input.dispatchEvent(new Event(eventName, { bubbles: true }));
}

function setWorkOrderEditorFieldValue(input, value = "", eventName = "change") {
  if (!(input instanceof HTMLElement)) {
    return;
  }

  input.value = String(value ?? "");
  dispatchWorkOrderEditorFieldEvent(input, eventName);
}

function getWorkOrderEditorMenuSearchText(option = {}, getOptionLabel = () => "", getOptionMeta = () => "") {
  return normalizeLooseName([
    getOptionLabel(option),
    getOptionMeta(option),
    option.searchText,
  ].filter(Boolean).join(" "));
}

function createWorkOrderEditorDefaultTriggerContent(option = null, placeholder = "Empty", getOptionLabel = () => "", getOptionMeta = () => "") {
  const wrap = document.createElement("span");
  wrap.className = "work-order-editor-field-trigger-copy";

  const label = document.createElement("span");
  label.className = option ? "work-order-editor-field-trigger-label" : "work-order-editor-field-trigger-label is-empty";
  label.textContent = option ? getOptionLabel(option) : placeholder;
  wrap.append(label);

  const metaText = option ? String(getOptionMeta(option) || "").trim() : "";
  if (metaText) {
    const meta = document.createElement("span");
    meta.className = "work-order-editor-field-trigger-meta";
    meta.textContent = metaText;
    wrap.append(meta);
  }

  return wrap;
}

function createWorkOrderEditorMenuControl({
  className = "",
  value = "",
  options = [],
  placeholder = "Empty",
  emptyLabel = "Nema opcija.",
  ariaLabel = "Odabir",
  searchPlaceholder = "",
  maxInitialOptions = 90,
  maxSearchOptions = 160,
  disabled = false,
  getOptionValue = (option) => option?.value ?? "",
  getOptionLabel = (option) => option?.label ?? "",
  getOptionMeta = (option) => option?.meta ?? "",
  renderTriggerContent = null,
  onSelect = () => {},
} = {}) {
  const normalizedValue = String(value ?? "").trim();
  const normalizedOptions = Array.isArray(options) ? options : [];
  const selectedOption = normalizedOptions.find((option) => String(getOptionValue(option) ?? "").trim() === normalizedValue) ?? null;
  const wrapper = document.createElement("span");
  wrapper.className = ["work-order-quick-picker", "work-order-editor-field-picker", className].filter(Boolean).join(" ");
  wrapper.dataset.preventRowOpen = "true";

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "work-order-quick-picker-trigger work-order-editor-field-trigger";
  trigger.dataset.preventRowOpen = "true";
  trigger.setAttribute("aria-haspopup", "dialog");
  trigger.setAttribute("aria-expanded", "false");
  trigger.setAttribute("aria-label", ariaLabel);
  trigger.disabled = Boolean(disabled);

  const caret = document.createElement("span");
  caret.className = "work-order-editor-field-caret";
  caret.setAttribute("aria-hidden", "true");
  caret.textContent = "⌄";

  const renderTrigger = () => {
    const contentNode = typeof renderTriggerContent === "function"
      ? renderTriggerContent(selectedOption, {
        value: normalizedValue,
        placeholder,
        getOptionLabel,
        getOptionMeta,
      })
      : createWorkOrderEditorDefaultTriggerContent(selectedOption, placeholder, getOptionLabel, getOptionMeta);
    trigger.replaceChildren(contentNode, caret);
    trigger.title = selectedOption
      ? [getOptionLabel(selectedOption), getOptionMeta(selectedOption)].filter(Boolean).join(" · ")
      : placeholder;
  };

  const positionMenuPortal = (menu) => {
    const triggerRect = trigger.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let left = triggerRect.left;
    let top = triggerRect.bottom + 8;

    if (left + menuRect.width > viewportWidth - 12) {
      left = Math.max(12, viewportWidth - menuRect.width - 12);
    }

    if (top + menuRect.height > viewportHeight - 12) {
      top = Math.max(12, triggerRect.top - menuRect.height - 8);
    }

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.minWidth = `${Math.max(260, Math.round(triggerRect.width + 36))}px`;
  };

  const closeMenu = () => {
    wrapper.classList.remove("is-open");
    trigger.setAttribute("aria-expanded", "false");
    if (wrapper._menuPortal) {
      wrapper._menuPortal.remove();
      wrapper._menuPortal = null;
    }
  };

  wrapper._closeMenu = closeMenu;

  const openMenu = () => {
    if (trigger.disabled) {
      return;
    }

    closeOpenWorkOrderStatusMenus(wrapper);
    if (wrapper._menuPortal) {
      return;
    }

    let searchQuery = "";
    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal work-order-quick-picker-menu-portal work-order-editor-field-menu-portal";
    menu.dataset.preventRowOpen = "true";
    menu.setAttribute("role", "dialog");
    menu.setAttribute("aria-label", ariaLabel);

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => {
        event.stopPropagation();
      });
    });
    menu.addEventListener("wheel", (event) => event.stopPropagation(), { passive: true });

    let searchInput = null;
    if (searchPlaceholder) {
      const searchWrap = document.createElement("div");
      searchWrap.className = "work-order-editor-field-search";

      searchInput = document.createElement("input");
      searchInput.type = "search";
      searchInput.className = "work-order-editor-field-search-input";
      searchInput.placeholder = searchPlaceholder;
      searchInput.autocomplete = "off";
      searchInput.spellcheck = false;
      searchWrap.append(searchInput);
      menu.append(searchWrap);
    }

    const optionList = document.createElement("div");
    optionList.className = "work-order-editor-field-options";

    const renderOptions = () => {
      optionList.replaceChildren();
      const normalizedQuery = normalizeLooseName(searchQuery);
      const visibleOptions = normalizedOptions.filter((option) => {
        if (!normalizedQuery) {
          return true;
        }
        return getWorkOrderEditorMenuSearchText(option, getOptionLabel, getOptionMeta).includes(normalizedQuery);
      });

      if (visibleOptions.length === 0) {
        const empty = document.createElement("p");
        empty.className = "work-order-editor-field-empty";
        empty.textContent = emptyLabel;
        optionList.append(empty);
        return;
      }

      const safeInitialLimit = Math.max(1, Number(maxInitialOptions) || 90);
      const safeSearchLimit = Math.max(1, Number(maxSearchOptions) || 160);
      const visibleLimit = normalizedQuery ? safeSearchLimit : safeInitialLimit;
      const renderedOptions = visibleOptions.slice(0, visibleLimit);

      renderedOptions.forEach((option) => {
        const optionValue = String(getOptionValue(option) ?? "").trim();
        const isSelected = optionValue === normalizedValue;
        const optionButton = document.createElement("button");
        optionButton.type = "button";
        optionButton.className = `work-item-status-option work-order-editor-field-option${isSelected ? " is-selected" : ""}`;
        optionButton.setAttribute("role", "menuitemradio");
        optionButton.setAttribute("aria-checked", String(isSelected));

        const copy = document.createElement("span");
        copy.className = "work-order-editor-field-option-copy";

        const optionLabel = document.createElement("strong");
        optionLabel.textContent = getOptionLabel(option) || placeholder;
        copy.append(optionLabel);

        const metaText = String(getOptionMeta(option) || "").trim();
        if (metaText) {
          const meta = document.createElement("span");
          meta.textContent = metaText;
          copy.append(meta);
        }

        const marker = document.createElement("span");
        marker.className = "work-order-editor-field-option-marker";
        marker.setAttribute("aria-hidden", "true");
        marker.textContent = isSelected ? "✓" : "";

        optionButton.append(copy, marker);
        optionButton.addEventListener("click", (event) => {
          event.stopPropagation();
          onSelect(optionValue, option);
          closeMenu();
        });

        optionList.append(optionButton);
      });

      if (visibleOptions.length > renderedOptions.length) {
        const more = document.createElement("p");
        more.className = "work-order-editor-field-empty work-order-editor-field-limit-hint";
        more.textContent = `Prikazano ${renderedOptions.length} od ${visibleOptions.length}. Nastavi tipkati za uzi odabir.`;
        optionList.append(more);
      }
    };

    if (searchInput) {
      searchInput.addEventListener("input", () => {
        searchQuery = searchInput.value || "";
        renderOptions();
        requestAnimationFrame(() => positionMenuPortal(menu));
      });
      searchInput.addEventListener("keydown", (event) => {
        if (event.key === "Escape") {
          event.preventDefault();
          closeMenu();
          trigger.focus({ preventScroll: true });
        }
      });
    }

    renderOptions();
    menu.append(optionList);
    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    positionMenuPortal(menu);
    requestAnimationFrame(() => {
      positionMenuPortal(menu);
      searchInput?.focus({ preventScroll: true });
      searchInput?.select();
    });
  };

  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (wrapper._menuPortal) {
      closeOpenWorkOrderStatusMenus();
      return;
    }
    openMenu();
  });

  renderTrigger();
  wrapper.append(trigger);
  return wrapper;
}

function createWorkOrderEditorStatusControl(statusValue = "", statusLabel = "") {
  return createWorkOrderEditorMenuControl({
    className: "is-status",
    value: statusValue || "Otvoreni RN",
    options: WORK_ORDER_STATUS_OPTIONS,
    placeholder: "Otvoreni RN",
    ariaLabel: "Promijeni status radnog naloga",
    getOptionValue: (option) => option.value,
    getOptionLabel: (option) => option.label || option.value,
    renderTriggerContent: (option, context) => createWorkOrderEditorStatusPill(
      option?.label || statusLabel || context.placeholder,
      option?.value || context.value || statusLabel,
    ),
    onSelect: (nextValue) => {
      setWorkOrderEditorFieldValue(workOrderStatusInput, nextValue, "change");
    },
  });
}

function createWorkOrderEditorPriorityControl(priorityValue = "", priorityLabel = "") {
  return createWorkOrderEditorMenuControl({
    className: "is-priority",
    value: priorityValue || "Normal",
    options: PRIORITY_OPTIONS,
    placeholder: "Normal",
    ariaLabel: "Promijeni prioritet",
    getOptionValue: (option) => option.value,
    getOptionLabel: (option) => option.label || option.value,
    renderTriggerContent: (option, context) => createWorkOrderEditorPriorityPill(
      option?.label || priorityLabel || context.placeholder,
      option?.value || context.value || priorityLabel,
    ),
    onSelect: (nextValue) => {
      setWorkOrderEditorFieldValue(workOrderPriorityInput, nextValue, "change");
    },
  });
}

function createWorkOrderEditorDateControl(input, placeholder = "Odaberi datum") {
  const normalizedValue = getNormalizedWorkOrderDateInputValue(input);
  const wrap = document.createElement("span");
  wrap.className = "work-order-editor-date-wrap";
  wrap.dataset.preventRowOpen = "true";

  const dateInput = document.createElement("input");
  dateInput.type = "text";
  dateInput.inputMode = "numeric";
  dateInput.className = "work-order-editor-date-control";
  dateInput.dataset.preventRowOpen = "true";
  dateInput.value = normalizedValue ? formatDateInputDisplayValue(normalizedValue) : "";
  dateInput.placeholder = "dd.mm.yyyy";
  dateInput.maxLength = 10;
  dateInput.setAttribute("aria-label", placeholder);

  const nativeInput = document.createElement("input");
  nativeInput.type = "date";
  nativeInput.className = "work-order-editor-native-date";
  nativeInput.value = normalizedValue || "";
  nativeInput.tabIndex = -1;
  nativeInput.dataset.preventRowOpen = "true";
  nativeInput.setAttribute("aria-hidden", "true");

  const pickerButton = document.createElement("button");
  pickerButton.type = "button";
  pickerButton.className = "work-order-editor-date-picker-button";
  pickerButton.dataset.preventRowOpen = "true";
  pickerButton.setAttribute("aria-label", `${placeholder} - kalendar`);
  pickerButton.innerHTML = getWorkOrderIconMarkup("dates");

  const openPicker = () => {
    if (typeof nativeInput.showPicker === "function") {
      try {
        nativeInput.showPicker();
        return;
      } catch {
        // Browser can reject showPicker without a direct user gesture; focus is the safe fallback.
      }
    }
    nativeInput.focus({ preventScroll: true });
  };

  const commitDate = () => {
    const normalized = normalizeDateInputValue(dateInput.value);
    dateInput.value = normalized ? formatDateInputDisplayValue(normalized) : "";
    nativeInput.value = normalized || "";
    if (input && getNormalizedWorkOrderDateInputValue(input) !== normalized) {
      setWorkOrderDateInputValue(input, normalized);
      dispatchWorkOrderEditorFieldEvent(input, "change");
    }
  };

  dateInput.addEventListener("click", (event) => {
    event.stopPropagation();
  });

  dateInput.addEventListener("input", () => {
    dateInput.value = normalizeLiveDateTypingValue(dateInput.value);
  });
  dateInput.addEventListener("change", commitDate);
  dateInput.addEventListener("blur", commitDate);
  dateInput.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      dateInput.blur();
    }
  });

  pickerButton.addEventListener("click", (event) => {
    event.stopPropagation();
    openPicker();
  });
  nativeInput.addEventListener("click", (event) => event.stopPropagation());
  nativeInput.addEventListener("change", () => {
    const normalized = normalizeDateInputValue(nativeInput.value);
    dateInput.value = normalized ? formatDateInputDisplayValue(normalized) : "";
    if (input && getNormalizedWorkOrderDateInputValue(input) !== normalized) {
      setWorkOrderDateInputValue(input, normalized);
      dispatchWorkOrderEditorFieldEvent(input, "change");
    }
  });

  wrap.append(dateInput, pickerButton, nativeInput);
  return wrap;
}

function createWorkOrderEditorTextControl(input, {
  placeholder = "",
  className = "",
  inputMode = "",
  type = "text",
  formatValue = null,
} = {}) {
  const wrap = document.createElement("span");
  wrap.className = ["work-order-editor-text-control", className].filter(Boolean).join(" ");
  wrap.dataset.preventRowOpen = "true";

  const control = document.createElement("input");
  control.type = type;
  control.className = "work-order-editor-text-input";
  control.placeholder = placeholder;
  control.value = typeof formatValue === "function" ? formatValue(input?.value || "") : (input?.value || "");
  control.dataset.preventRowOpen = "true";
  if (inputMode) {
    control.inputMode = inputMode;
  }

  const getCommittedValue = (shouldFormat = false) => {
    if (shouldFormat && typeof formatValue === "function") {
      const formatted = formatValue(control.value);
      control.value = formatted;
      return formatted;
    }
    return control.value;
  };

  const commit = (shouldFormat = false) => {
    if (!input) {
      return;
    }
    input.value = getCommittedValue(shouldFormat);
    dispatchWorkOrderEditorFieldEvent(input, "change");
  };

  control.addEventListener("click", (event) => event.stopPropagation());
  control.addEventListener("input", () => {
    if (!input) {
      return;
    }
    input.value = control.value;
  });
  control.addEventListener("change", () => commit(true));
  control.addEventListener("blur", () => commit(true));
  control.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      control.blur();
    }
  });

  wrap.append(control);
  return wrap;
}

function formatWorkOrderInvoiceAmountDisplayValue(value = "") {
  const rawValue = String(value ?? "").trim();
  if (!rawValue) {
    return "";
  }

  const numericValue = roundMoneyAmount(parseOfferMoneyInput(rawValue, 0));
  return formatCurrencyAmount(numericValue, "EUR");
}

function createWorkOrderEditorStaticValue(value = "", placeholder = "-") {
  const node = document.createElement("span");
  node.className = value ? "work-order-editor-static-value" : "work-order-editor-static-value is-empty";
  node.textContent = value || placeholder;
  return node;
}

function getWorkOrderEditorCompanyMenuOptions() {
  return [
    {
      value: "",
      label: "Odaberi tvrtku",
      meta: "Obavezno polje",
      searchText: "",
    },
    ...state.companies
      .slice()
      .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "hr"))
      .map((company) => ({
        value: String(company.id || ""),
        label: company.name || "Tvrtka",
        meta: [
          company.headquarters ? `Sjedište ${company.headquarters}` : "",
          company.oib ? `OIB ${company.oib}` : "",
        ].filter(Boolean).join(" · "),
        searchText: [
          company.name,
          company.headquarters,
          company.oib,
        ].filter(Boolean).join(" "),
      })),
  ];
}

function getWorkOrderEditorLocationMenuOptions() {
  const companyId = String(workOrderCompanyIdInput.value || "").trim();
  const locations = companyId ? getLocationsForCompany(companyId) : [];
  return [
    {
      value: "",
      label: companyId ? "Odaberi lokaciju" : "Prvo odaberi tvrtku",
      meta: companyId ? "Obavezno polje" : "",
      searchText: "",
    },
    ...locations.map((location) => ({
      value: String(location.id || ""),
      label: location.name || "Lokacija",
      meta: [
        location.region || "",
        location.coordinates || "",
      ].filter(Boolean).join(" · "),
      searchText: [
        location.name,
        location.region,
        location.coordinates,
      ].filter(Boolean).join(" "),
    })),
  ];
}

function getWorkOrderEditorContactMenuOptions() {
  const location = getLocation(workOrderLocationIdInput.value);
  const contacts = buildLocationContacts(location);
  const options = [
    {
      value: "",
      label: contacts.length === 0 ? "Nema kontakata" : "Odaberi kontakt",
      meta: location ? "" : "Prvo odaberi lokaciju",
      searchText: "",
    },
  ];

  contacts.forEach((contact) => {
    options.push({
      value: String(contact.slot ?? ""),
      label: contact.name || `Kontakt ${contact.slot}`,
      meta: [
        contact.phone || "",
        contact.email || "",
      ].filter(Boolean).join(" · "),
      searchText: [
        contact.name,
        contact.phone,
        contact.email,
      ].filter(Boolean).join(" "),
    });
  });

  return options;
}

function createWorkOrderEditorCompanyControl() {
  return createWorkOrderEditorMenuControl({
    className: "is-company",
    value: workOrderCompanyIdInput.value,
    options: getWorkOrderEditorCompanyMenuOptions(),
    placeholder: "Odaberi tvrtku",
    emptyLabel: "Nema tvrtki za ovaj pojam.",
    ariaLabel: "Odaberi tvrtku",
    searchPlaceholder: "Traži tvrtku, sjedište ili OIB",
    maxInitialOptions: 45,
    maxSearchOptions: 140,
    getOptionValue: (option) => option.value,
    getOptionLabel: (option) => option.label,
    getOptionMeta: (option) => option.meta,
    onSelect: (nextValue) => {
      setWorkOrderEditorFieldValue(workOrderCompanyIdInput, nextValue, "change");
    },
  });
}

function createWorkOrderEditorLocationControl() {
  const wrap = document.createElement("span");
  wrap.className = "work-order-editor-location-control";
  wrap.dataset.preventRowOpen = "true";

  wrap.append(createWorkOrderEditorMenuControl({
    className: "is-location",
    value: workOrderLocationIdInput.value,
    options: getWorkOrderEditorLocationMenuOptions(),
    placeholder: "Odaberi lokaciju",
    emptyLabel: "Nema lokacija za ovaj pojam.",
    ariaLabel: "Odaberi lokaciju",
    searchPlaceholder: "Traži lokaciju, regiju ili adresu",
    disabled: !String(workOrderCompanyIdInput.value || "").trim(),
    getOptionValue: (option) => option.value,
    getOptionLabel: (option) => option.label,
    getOptionMeta: (option) => option.meta,
    onSelect: (nextValue) => {
      setWorkOrderEditorFieldValue(workOrderLocationIdInput, nextValue, "change");
    },
  }));

  const location = getLocation(workOrderLocationIdInput.value);
  const missingCoordinates = Boolean(location && !String(workOrderCoordinatesInput.value || location.coordinates || "").trim());
  const missingRegion = Boolean(location && !String(workOrderRegionInput.value || location.region || "").trim());

  if (!missingCoordinates && !missingRegion) {
    return wrap;
  }

  const prompt = document.createElement("span");
  prompt.className = "work-order-editor-location-missing";

  const copy = document.createElement("span");
  copy.className = "work-order-editor-location-missing-copy";
  copy.textContent = `Nedostaje: ${[
    missingRegion ? "regija" : "",
    missingCoordinates ? "koordinate" : "",
  ].filter(Boolean).join(", ")}`;

  const regionSelect = document.createElement("select");
  regionSelect.className = "work-order-editor-location-region";
  regionSelect.dataset.preventRowOpen = "true";
  regionSelect.setAttribute("aria-label", "Regija lokacije");
  regionSelect.append(createOption("", "Regija", workOrderRegionInput.value));
  WORK_ORDER_REGION_OPTIONS.forEach((region) => {
    regionSelect.append(createOption(region, region, workOrderRegionInput.value));
  });
  regionSelect.value = workOrderRegionInput.value || location?.region || "";

  const coordinatesInput = document.createElement("input");
  coordinatesInput.type = "text";
  coordinatesInput.className = "work-order-editor-location-coordinates";
  coordinatesInput.dataset.preventRowOpen = "true";
  coordinatesInput.placeholder = "45.8150, 15.9819";
  coordinatesInput.value = workOrderCoordinatesInput.value || location?.coordinates || "";
  coordinatesInput.setAttribute("aria-label", "Koordinate lokacije");

  const saveButton = document.createElement("button");
  saveButton.type = "button";
  saveButton.className = "work-order-editor-location-save";
  saveButton.dataset.preventRowOpen = "true";
  saveButton.style.gridColumn = "1 / -1";
  saveButton.style.justifySelf = "start";
  saveButton.style.width = "auto";
  saveButton.textContent = "Ažuriraj";

  saveButton.addEventListener("click", async (event) => {
    event.stopPropagation();
    const activeLocation = getLocation(workOrderLocationIdInput.value);
    if (!activeLocation) {
      return;
    }

    const nextRegion = String(regionSelect.value || "").trim();
    const nextCoordinates = String(coordinatesInput.value || "").trim();
    workOrderCoordinatesInput.value = nextCoordinates;
    syncWorkOrderRegionOption(nextRegion);
    dispatchWorkOrderEditorFieldEvent(workOrderCoordinatesInput, "input");
    dispatchWorkOrderEditorFieldEvent(workOrderRegionInput, "change");

    saveButton.disabled = true;
    saveButton.textContent = "Spremam";
    const contacts = buildLocationContacts(activeLocation)
      .map((contact) => ({
        name: contact.name,
        phone: contact.phone,
        email: contact.email,
      }))
      .filter((contact) => contact.name || contact.phone || contact.email);
    const success = await runMutation(() => apiRequest(`/locations/${encodeURIComponent(String(activeLocation.id))}`, {
      method: "PATCH",
      body: {
        companyId: activeLocation.companyId,
        name: activeLocation.name,
        region: nextRegion,
        coordinates: nextCoordinates,
        period: activeLocation.period || "",
        representative: activeLocation.representative || "",
        isActive: activeLocation.isActive === false ? "false" : "true",
        contacts,
        note: activeLocation.note || "",
      },
    }), workOrderError);
    if (success) {
      renderWorkOrderEditorSummary();
      queueWorkOrderAutoSave();
    } else {
      saveButton.disabled = false;
      saveButton.textContent = "Ažuriraj";
    }
  });

  prompt.append(copy, regionSelect, coordinatesInput, saveButton);
  wrap.append(prompt);
  return wrap;
}

function createWorkOrderEditorContactControl() {
  const hasLocation = Boolean(String(workOrderLocationIdInput.value || "").trim());

  if (!hasLocation) {
    return createWorkOrderEditorMenuControl({
      className: "is-contact",
      value: "",
      options: getWorkOrderEditorContactMenuOptions(),
      placeholder: "Prvo lokacija",
      ariaLabel: "Odaberi kontakt",
      disabled: true,
      getOptionValue: (option) => option.value,
      getOptionLabel: (option) => option.label,
      getOptionMeta: (option) => option.meta,
    });
  }

  let searchQuery = "";
  let isAdding = false;
  let draftContact = { name: "", phone: "", email: "" };

  const getSelectedOption = () => getWorkOrderEditorContactMenuOptions()
    .find((option) => String(option.value || "").trim() === String(workOrderContactSlotInput.value || "").trim()) ?? null;

  const renderTriggerContent = () => createWorkOrderEditorDefaultTriggerContent(
    getSelectedOption(),
    "Odaberi kontakt",
    (option) => option?.label || "",
    (option) => option?.meta || "",
  );

  return createWorkOrderEditorMenuShell({
    className: "is-contact",
    ariaLabel: "Odaberi ili dodaj kontakt",
    renderTriggerContent,
    renderMenuContent: (menu, reposition, closeMenu) => {
      menu.classList.add("work-order-contact-menu-portal");

      const searchWrap = document.createElement("div");
      searchWrap.className = "work-order-editor-field-search work-order-contact-menu-search";

      const searchInput = document.createElement("input");
      searchInput.type = "search";
      searchInput.className = "work-order-editor-field-search-input";
      searchInput.placeholder = "Traži kontakt, telefon ili email";
      searchInput.autocomplete = "off";
      searchInput.spellcheck = false;
      searchWrap.append(searchInput);

      const header = document.createElement("div");
      header.className = "work-order-contact-menu-head";

      const headerCopy = document.createElement("span");
      headerCopy.className = "work-order-contact-menu-title";
      headerCopy.textContent = "Odaberi kontakt";

      const addButton = document.createElement("button");
      addButton.type = "button";
      addButton.className = "work-order-contact-add-button";
      addButton.textContent = "+";
      addButton.title = "Dodaj novi kontakt na ovu lokaciju";
      addButton.setAttribute("aria-label", "Dodaj novi kontakt");
      header.append(headerCopy, addButton);

      const list = document.createElement("div");
      list.className = "work-order-editor-field-options work-order-contact-options";

      const form = document.createElement("div");
      form.className = "work-order-contact-add-form";
      form.hidden = true;

      const nameInput = document.createElement("input");
      nameInput.type = "text";
      nameInput.placeholder = "Ime i prezime";
      nameInput.autocomplete = "name";

      const phoneInput = document.createElement("input");
      phoneInput.type = "tel";
      phoneInput.placeholder = "Telefon";
      phoneInput.autocomplete = "tel";

      const emailInput = document.createElement("input");
      emailInput.type = "email";
      emailInput.placeholder = "Email";
      emailInput.autocomplete = "email";

      const formActions = document.createElement("div");
      formActions.className = "work-order-contact-add-actions";

      const cancelButton = document.createElement("button");
      cancelButton.type = "button";
      cancelButton.className = "ghost-button";
      cancelButton.textContent = "Odustani";

      const saveButton = document.createElement("button");
      saveButton.type = "button";
      saveButton.className = "primary-button";
      saveButton.textContent = "Spremi kontakt";

      const formError = document.createElement("p");
      formError.className = "form-error work-order-contact-add-error";
      formError.hidden = true;

      formActions.append(cancelButton, saveButton);
      form.append(nameInput, phoneInput, emailInput, formActions, formError);

      const syncDraftFromInputs = () => {
        draftContact = {
          name: String(nameInput.value || "").trim(),
          phone: String(phoneInput.value || "").trim(),
          email: String(emailInput.value || "").trim(),
        };
      };

      const setFormError = (message = "") => {
        formError.textContent = message;
        formError.hidden = !message;
      };

      const renderList = () => {
        const location = getLocation(workOrderLocationIdInput.value);
        const contacts = buildLocationContacts(location);
        const normalizedQuery = normalizeLooseName(searchQuery);
        const visibleContacts = contacts.filter((contact) => (
          !normalizedQuery
          || normalizeLooseName([contact.name, contact.phone, contact.email].filter(Boolean).join(" ")).includes(normalizedQuery)
        ));

        list.replaceChildren();
        if (visibleContacts.length === 0) {
          const empty = document.createElement("p");
          empty.className = "work-order-editor-field-empty";
          empty.textContent = contacts.length === 0 ? "Na ovoj lokaciji još nema kontakata." : "Nema kontakata za upisani pojam.";
          list.append(empty);
        } else {
          visibleContacts.forEach((contact) => {
            const optionButton = document.createElement("button");
            optionButton.type = "button";
            optionButton.className = `work-item-status-option work-order-editor-field-option${String(contact.slot) === String(workOrderContactSlotInput.value) ? " is-selected" : ""}`;
            optionButton.setAttribute("role", "menuitemradio");
            optionButton.setAttribute("aria-checked", String(String(contact.slot) === String(workOrderContactSlotInput.value)));

            const copy = document.createElement("span");
            copy.className = "work-order-editor-field-option-copy";
            const label = document.createElement("strong");
            label.textContent = contact.name || `Kontakt ${contact.slot}`;
            const meta = document.createElement("span");
            meta.textContent = [contact.phone, contact.email].filter(Boolean).join(" · ");
            copy.append(label);
            if (meta.textContent) {
              copy.append(meta);
            }

            const marker = document.createElement("span");
            marker.className = "work-order-editor-field-option-marker";
            marker.setAttribute("aria-hidden", "true");
            marker.textContent = String(contact.slot) === String(workOrderContactSlotInput.value) ? "✓" : "";

            optionButton.append(copy, marker);
            optionButton.addEventListener("click", (event) => {
              event.stopPropagation();
              setWorkOrderEditorFieldValue(workOrderContactSlotInput, contact.slot, "change");
              closeMenu();
            });
            list.append(optionButton);
          });
        }

        reposition();
      };

      const showAddForm = () => {
        isAdding = true;
        form.hidden = false;
        headerCopy.textContent = "Novi kontakt";
        addButton.hidden = true;
        setFormError("");
        requestAnimationFrame(() => {
          reposition();
          nameInput.focus({ preventScroll: true });
        });
      };

      const hideAddForm = () => {
        isAdding = false;
        form.hidden = true;
        headerCopy.textContent = "Odaberi kontakt";
        addButton.hidden = false;
        draftContact = { name: "", phone: "", email: "" };
        nameInput.value = "";
        phoneInput.value = "";
        emailInput.value = "";
        setFormError("");
        renderList();
      };

      const saveContact = async () => {
        syncDraftFromInputs();
        if (!draftContact.name && !draftContact.phone && !draftContact.email) {
          setFormError("Upiši barem ime, telefon ili email.");
          return;
        }

        const location = getLocation(workOrderLocationIdInput.value);
        if (!location?.id) {
          setFormError("Prvo odaberi lokaciju.");
          return;
        }

        const contacts = buildLocationContacts(location)
          .map((contact) => ({
            name: contact.name,
            phone: contact.phone,
            email: contact.email,
          }))
          .filter((contact) => contact.name || contact.phone || contact.email);
        const nextContacts = [...contacts, draftContact];

        saveButton.disabled = true;
        cancelButton.disabled = true;
        saveButton.textContent = "Spremam...";
        setFormError("");

        const success = await runMutation(() => apiRequest(`/locations/${encodeURIComponent(String(location.id))}`, {
          method: "PATCH",
          body: {
            companyId: location.companyId,
            name: location.name,
            region: location.region || "",
            coordinates: location.coordinates || "",
            period: location.period || "",
            representative: location.representative || "",
            isActive: location.isActive === false ? "false" : "true",
            contacts: nextContacts,
            note: location.note || "",
          },
        }), workOrderError);

        if (success) {
          const refreshedLocation = getLocation(location.id);
          const refreshedContacts = buildLocationContacts(refreshedLocation);
          const selectedContact = refreshedContacts.find((contact) => (
            contact.name === draftContact.name
            && contact.phone === draftContact.phone
            && contact.email === draftContact.email
          )) ?? refreshedContacts[refreshedContacts.length - 1] ?? null;

          rebuildWorkOrderContactOptions(selectedContact?.slot ?? "", selectedContact?.name ?? "");
          if (selectedContact) {
            setWorkOrderEditorFieldValue(workOrderContactSlotInput, selectedContact.slot, "change");
          }
          renderWorkOrderEditorSummary();
          queueWorkOrderAutoSave();
          closeMenu();
          return;
        }

        saveButton.disabled = false;
        cancelButton.disabled = false;
        saveButton.textContent = "Spremi kontakt";
      };

      addButton.addEventListener("click", (event) => {
        event.stopPropagation();
        showAddForm();
      });
      cancelButton.addEventListener("click", (event) => {
        event.stopPropagation();
        hideAddForm();
      });
      saveButton.addEventListener("click", (event) => {
        event.stopPropagation();
        void saveContact();
      });
      [nameInput, phoneInput, emailInput].forEach((input) => {
        input.addEventListener("input", syncDraftFromInputs);
        input.addEventListener("keydown", (event) => {
          if (event.key === "Enter") {
            event.preventDefault();
            void saveContact();
          } else if (event.key === "Escape" && isAdding) {
            event.preventDefault();
            hideAddForm();
          }
        });
      });
      searchInput.addEventListener("input", () => {
        searchQuery = searchInput.value || "";
        renderList();
      });
      searchInput.addEventListener("keydown", (event) => {
        if (event.key === "Escape") {
          event.preventDefault();
          closeMenu();
        }
      });

      menu.append(searchWrap, header, list, form);
      renderList();
      requestAnimationFrame(() => {
        reposition();
        searchInput.focus({ preventScroll: true });
      });
    },
  });
}

function createWorkOrderEditorMenuShell({
  className = "",
  ariaLabel = "Odabir",
  renderTriggerContent = () => document.createTextNode("Odaberi"),
  renderMenuContent = () => {},
  commit = () => {},
} = {}) {
  const wrapper = document.createElement("span");
  wrapper.className = ["work-order-quick-picker", "work-order-editor-field-picker", "work-order-editor-multi-picker", className].filter(Boolean).join(" ");
  wrapper.dataset.preventRowOpen = "true";

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "work-order-quick-picker-trigger work-order-editor-field-trigger";
  trigger.dataset.preventRowOpen = "true";
  trigger.setAttribute("aria-haspopup", "dialog");
  trigger.setAttribute("aria-expanded", "false");
  trigger.setAttribute("aria-label", ariaLabel);

  const caret = document.createElement("span");
  caret.className = "work-order-editor-field-caret";
  caret.setAttribute("aria-hidden", "true");
  caret.textContent = "⌄";

  const syncTrigger = () => {
    const content = renderTriggerContent();
    trigger.replaceChildren(content, caret);
  };

  const positionMenuPortal = (menu) => {
    const triggerRect = trigger.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;
    let left = triggerRect.left;
    let top = triggerRect.bottom + 8;

    if (left + menuRect.width > viewportWidth - 12) {
      left = Math.max(12, viewportWidth - menuRect.width - 12);
    }
    if (top + menuRect.height > viewportHeight - 12) {
      top = Math.max(12, triggerRect.top - menuRect.height - 8);
    }

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.minWidth = `${Math.max(340, Math.round(triggerRect.width + 80))}px`;
  };

  const closeMenu = () => {
    commit();
    wrapper.classList.remove("is-open");
    trigger.setAttribute("aria-expanded", "false");
    if (wrapper._menuPortal) {
      wrapper._menuPortal.remove();
      wrapper._menuPortal = null;
    }
    syncTrigger();
  };

  wrapper._closeMenu = closeMenu;

  const openMenu = () => {
    closeOpenWorkOrderStatusMenus(wrapper);
    if (wrapper._menuPortal) {
      return;
    }

    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal work-order-quick-picker-menu-portal work-order-editor-field-menu-portal work-order-editor-multi-menu-portal";
    menu.dataset.preventRowOpen = "true";
    menu.setAttribute("role", "dialog");
    menu.setAttribute("aria-label", ariaLabel);

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => {
        event.stopPropagation();
      });
    });
    menu.addEventListener("wheel", (event) => event.stopPropagation(), { passive: true });

    renderMenuContent(menu, () => {
      requestAnimationFrame(() => positionMenuPortal(menu));
    }, closeMenu);

    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    positionMenuPortal(menu);
    requestAnimationFrame(() => positionMenuPortal(menu));
  };

  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (wrapper._menuPortal) {
      closeOpenWorkOrderStatusMenus();
      return;
    }
    openMenu();
  });

  syncTrigger();
  wrapper.append(trigger);
  return wrapper;
}

function createWorkOrderEditorExecutorTriggerContent(values = []) {
  const wrap = document.createElement("span");
  wrap.className = "work-order-editor-trigger-people";
  const normalizedValues = normalizeWorkOrderExecutorValues(values);

  if (normalizedValues.length === 0) {
    wrap.append(createWorkOrderEditorPlainValue("Odaberi izvršitelje", { muted: true }));
    return wrap;
  }

  const stack = document.createElement("span");
  stack.className = "work-order-editor-detail-avatar-stack";
  normalizedValues.slice(0, 4).forEach((value) => {
    stack.append(createWorkOrderMiniExecutor(value, {
      className: "work-order-mini-executor work-order-editor-detail-avatar",
    }));
  });
  if (normalizedValues.length > 4) {
    stack.append(createExecutorOverflowBadge(normalizedValues.length - 4, "work-order-mini-executor work-order-editor-detail-avatar"));
  }

  const label = document.createElement("span");
  label.className = "work-order-editor-trigger-people-label";
  label.textContent = normalizedValues.join(", ");
  wrap.append(stack, label);
  return wrap;
}

function createWorkOrderEditorExecutorsContent(executorValues = []) {
  let draftValues = normalizeWorkOrderExecutorValues(executorValues);
  let dirty = false;

  const commit = () => {
    if (!dirty) {
      return;
    }
    writeWorkOrderExecutorSelection(draftValues, {
      dispatchEventName: "change",
    });
    dirty = false;
  };

  return createWorkOrderEditorMenuShell({
    className: "is-executors",
    ariaLabel: "Odaberi izvršitelje",
    renderTriggerContent: () => createWorkOrderEditorExecutorTriggerContent(draftValues),
    commit,
    renderMenuContent: (menu, reposition, closeMenu) => {
      const selection = document.createElement("div");
      selection.className = "work-order-editor-menu-selection";

      const list = document.createElement("div");
      list.className = "work-order-editor-field-options work-order-editor-people-options";

      const footer = document.createElement("div");
      footer.className = "work-order-editor-menu-footer";

      const clearButton = document.createElement("button");
      clearButton.type = "button";
      clearButton.className = "ghost-button work-order-editor-menu-clear";
      clearButton.textContent = "Očisti";

      const doneButton = document.createElement("button");
      doneButton.type = "button";
      doneButton.className = "primary-button work-order-editor-menu-done";
      doneButton.textContent = "Gotovo";

      const render = () => {
        selection.replaceChildren();
        if (draftValues.length === 0) {
          const empty = document.createElement("span");
          empty.className = "work-order-calendar-executor-selection-empty";
          empty.textContent = "Bez izvršitelja";
          selection.append(empty);
        } else {
          draftValues.forEach((value) => {
            const chip = document.createElement("button");
            chip.type = "button";
            chip.className = "work-order-calendar-executor-chip";
            chip.title = `Makni ${value}`;
            const avatar = createWorkOrderMiniExecutor(value);
            avatar.removeAttribute("title");
            const label = document.createElement("span");
            label.className = "work-order-calendar-executor-chip-label";
            label.textContent = value;
            const remove = document.createElement("span");
            remove.className = "work-order-calendar-executor-chip-remove";
            remove.setAttribute("aria-hidden", "true");
            remove.textContent = "x";
            chip.append(avatar, label, remove);
            chip.addEventListener("click", (event) => {
              event.stopPropagation();
              draftValues = draftValues.filter((entry) => entry !== value);
              dirty = true;
              render();
            });
            selection.append(chip);
          });
        }

        list.replaceChildren();
        getWorkOrderExecutorOptions(draftValues).forEach((option) => {
          const isSelected = draftValues.includes(option.value);
          const optionButton = document.createElement("button");
          optionButton.type = "button";
          optionButton.className = `work-item-status-option work-order-calendar-executor-option${isSelected ? " is-selected" : ""}`;
          optionButton.setAttribute("role", "menuitemcheckbox");
          optionButton.setAttribute("aria-checked", String(isSelected));
          const avatar = createWorkOrderMiniExecutor(option, {
            className: "work-order-calendar-executor-option-avatar",
          });
          const label = document.createElement("span");
          label.className = "work-order-calendar-executor-option-label";
          label.textContent = option.label;
          const marker = document.createElement("span");
          marker.className = "work-order-calendar-executor-option-marker";
          marker.setAttribute("aria-hidden", "true");
          marker.textContent = isSelected ? "✓" : "+";
          optionButton.append(avatar, label, marker);
          optionButton.addEventListener("click", (event) => {
            event.stopPropagation();
            draftValues = isSelected
              ? draftValues.filter((entry) => entry !== option.value)
              : [...draftValues, option.value];
            dirty = true;
            render();
          });
          list.append(optionButton);
        });

        clearButton.disabled = draftValues.length === 0;
        reposition();
      };

      clearButton.addEventListener("click", (event) => {
        event.stopPropagation();
        draftValues = [];
        dirty = true;
        render();
      });
      doneButton.addEventListener("click", (event) => {
        event.stopPropagation();
        closeMenu();
      });

      footer.append(clearButton, doneButton);
      menu.append(selection, list, footer);
      render();
    },
  });
}

function getWorkOrderCompletedByOptions(currentValues = []) {
  const labels = normalizeWorkOrderExecutorValues(currentValues);
  const target = {
    ...buildWorkOrderPayload(),
    completedBy: labels.join(", "),
  };
  return getWorkOrderFinishedInspectorOptions([target], labels)
    .map((option) => ({
      value: option.label,
      label: option.label,
      user: option.user,
      summary: option.summary,
      isSnapshot: option.isSnapshot,
    }));
}

