function createWorkOrderEditorServicesContent(selectedServiceItems = []) {
  let draftItems = Array.isArray(selectedServiceItems) ? [...selectedServiceItems] : [];
  let dirty = false;
  let selectedTypeFilter = getWorkOrderSelectionServiceType(draftItems) || "inspection";

  const commit = () => {
    if (!dirty) {
      return;
    }
    writeWorkOrderServiceSelection(draftItems, {
      dispatchEventName: "change",
    });
    dirty = false;
  };

  const getServiceTriggerContent = () => {
    const wrap = document.createElement("span");
    wrap.className = "work-order-editor-trigger-services";
    if (draftItems.length === 0) {
      wrap.append(createWorkOrderEditorPlainValue("Odaberi usluge", { muted: true }));
      return wrap;
    }
    const label = document.createElement("span");
    label.className = "work-order-editor-trigger-service-label";
    label.textContent = `${draftItems.length} odabrano`;
    const summary = document.createElement("span");
    summary.className = "work-order-editor-trigger-service-summary";
    summary.textContent = draftItems.map((item) => item.name || item.serviceCode).filter(Boolean).join(", ");
    wrap.append(label, summary);
    return wrap;
  };

  return createWorkOrderEditorMenuShell({
    className: "is-services",
    ariaLabel: "Odaberi usluge",
    renderTriggerContent: getServiceTriggerContent,
    commit,
    renderMenuContent: (menu, reposition, closeMenu) => {
      const typeTabs = document.createElement("div");
      typeTabs.className = "work-order-service-type-tabs";

      const selection = document.createElement("div");
      selection.className = "work-order-service-picker-selection";
      const list = document.createElement("div");
      list.className = "work-order-service-picker-options work-order-editor-field-options";
      const footer = document.createElement("div");
      footer.className = "work-order-editor-menu-footer";
      const clearButton = document.createElement("button");
      clearButton.type = "button";
      clearButton.className = "ghost-button work-order-editor-menu-clear";
      clearButton.textContent = "Očisti";
      const doneButton = document.createElement("button");
      doneButton.type = "button";
      doneButton.className = "primary-button work-order-editor-menu-done";
      doneButton.textContent = "Gotovo";

      const render = () => {
        selection.replaceChildren();
        if (draftItems.length === 0) {
          const empty = document.createElement("span");
          empty.className = "work-order-service-picker-selection-empty";
          empty.textContent = "Bez odabranih usluga";
          selection.append(empty);
        } else {
          draftItems.forEach((item) => {
            const chip = document.createElement("div");
            chip.className = `work-order-service-picker-selection-chip${item.isCompleted ? " is-completed" : ""}`;
            const name = document.createElement("button");
            name.type = "button";
            name.className = "work-order-service-picker-selection-name";
            name.textContent = item.name || item.serviceCode || "Usluga";
            name.addEventListener("click", (event) => {
              event.stopPropagation();
              draftItems = draftItems.filter((entry) => String(entry.serviceId) !== String(item.serviceId));
              dirty = true;
              render();
            });
            const quantity = document.createElement("input");
            quantity.type = "number";
            quantity.min = "0.01";
            quantity.step = "0.25";
            quantity.inputMode = "decimal";
            quantity.className = "work-order-service-picker-quantity";
            quantity.value = formatWorkOrderServiceQuantity(item.quantity);
            quantity.title = "Količina za bodove i primopredaju";
            quantity.addEventListener("click", (event) => event.stopPropagation());
            quantity.addEventListener("input", () => {
              draftItems = draftItems.map((entry) => (
                String(entry.serviceId) === String(item.serviceId)
                  ? { ...entry, quantity: String(quantity.value || "1").trim() || "1" }
                  : entry
              ));
              dirty = true;
            });
            chip.append(name, quantity);
            selection.append(chip);
          });
        }

        list.replaceChildren();
        const lockedType = getWorkOrderSelectionServiceType(draftItems);
        if (lockedType) {
          selectedTypeFilter = lockedType;
        }
        if (!SERVICE_CATALOG_TYPE_OPTIONS.some((option) => option.value === selectedTypeFilter)) {
          selectedTypeFilter = lockedType || "inspection";
        }

        typeTabs.replaceChildren(...SERVICE_CATALOG_TYPE_OPTIONS.map((option) => {
          const tab = document.createElement("button");
          tab.type = "button";
          tab.className = `work-order-service-type-tab${selectedTypeFilter === option.value ? " is-active" : ""}`;
          tab.textContent = option.label;
          tab.disabled = Boolean(lockedType && lockedType !== option.value);
          tab.title = tab.disabled
            ? `RN je zaključan na vrstu: ${getServiceCatalogTypeLabel(lockedType)}`
            : `Prikaži: ${option.label}`;
          tab.addEventListener("click", (event) => {
            event.stopPropagation();
            selectedTypeFilter = option.value;
            render();
          });
          return tab;
        }));

        const visibleOptions = getWorkOrderServiceCatalogOptions(draftItems)
          .filter((option) => getWorkOrderServiceType(option) === selectedTypeFilter);

        if (visibleOptions.length === 0) {
          const empty = document.createElement("p");
          empty.className = "work-order-service-picker-empty";
          empty.textContent = `Nema usluga za vrstu ${getServiceCatalogTypeLabel(selectedTypeFilter)}.`;
          list.append(empty);
        }

        visibleOptions.forEach((option) => {
          const optionType = getWorkOrderServiceType(option);
          const isSelected = draftItems.some((item) => String(item.serviceId) === String(option.id));
          const isLockedOut = Boolean(lockedType && optionType && lockedType !== optionType && !isSelected);
          const optionButton = document.createElement("button");
          optionButton.type = "button";
          optionButton.className = `work-item-status-option work-order-service-picker-option${isSelected ? " is-selected" : ""}${isLockedOut ? " is-disabled" : ""}`;
          optionButton.disabled = isLockedOut;

          const copy = document.createElement("div");
          copy.className = "work-order-service-picker-option-copy";
          const title = document.createElement("strong");
          title.textContent = option.name || "Usluga";
          const meta = document.createElement("span");
          meta.textContent = [
            option.serviceCode || "",
            getServiceCatalogTypeLabel(optionType),
            option.status === "inactive" ? "Neaktivna" : "Aktivna",
          ].filter(Boolean).join(" · ");
          copy.append(title, meta);

          const marker = document.createElement("span");
          marker.className = "work-order-service-picker-option-marker";
          marker.textContent = isSelected ? "✓" : "+";

          optionButton.append(copy, marker);
          optionButton.addEventListener("click", (event) => {
            event.stopPropagation();
            if (isLockedOut) {
              return;
            }
            draftItems = isSelected
              ? draftItems.filter((item) => String(item.serviceId) !== String(option.id))
              : [...draftItems, buildWorkOrderServiceItemSnapshot(option)];
            dirty = true;
            render();
          });
          list.append(optionButton);
        });

        clearButton.disabled = draftItems.length === 0;
        reposition();
      };

      clearButton.addEventListener("click", (event) => {
        event.stopPropagation();
        draftItems = [];
        dirty = true;
        render();
      });
      doneButton.addEventListener("click", (event) => {
        event.stopPropagation();
        closeMenu();
      });

      footer.append(clearButton, doneButton);
      menu.append(typeTabs, selection, list, footer);
      render();
    },
  });
}

function createWorkOrderEditorDetailRow({
  iconName = "service",
  label = "",
  content = null,
  value = "",
  targetSections = [],
  tone = "",
  attention = false,
} = {}) {
  const row = document.createElement("div");
  row.className = `work-order-editor-detail-row${tone ? ` is-${tone}` : ""}${attention ? " has-required-attention" : ""}`.trim();
  if ((Array.isArray(targetSections) ? targetSections : [targetSections]).filter(Boolean).length > 0) {
    row.tabIndex = 0;
    row.setAttribute("role", "button");
  }

  const icon = document.createElement("span");
  icon.className = "work-order-editor-detail-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.innerHTML = getWorkOrderIconMarkup(iconName);

  const labelNode = document.createElement("span");
  labelNode.className = "work-order-editor-detail-label";
  labelNode.textContent = label;

  const valueNode = document.createElement("span");
  valueNode.className = "work-order-editor-detail-content";
  if (content instanceof Node) {
    valueNode.append(content);
  } else {
    valueNode.append(createWorkOrderEditorPlainValue(value || "-"));
  }

  row.append(icon, labelNode, valueNode);
  row.addEventListener("click", (event) => {
    if (event.target instanceof Element && event.target.closest("[data-prevent-row-open='true']")) {
      return;
    }
    focusWorkOrderEditorSection(targetSections);
  });
  row.addEventListener("keydown", (event) => {
    if (event.target instanceof Element && event.target.closest("[data-prevent-row-open='true']")) {
      return;
    }
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }
    event.preventDefault();
    focusWorkOrderEditorSection(targetSections);
  });

  return row;
}

function createWorkOrderSideSummaryItem(label = "", value = "", iconName = "service") {
  const item = document.createElement("div");
  item.className = "work-order-side-summary-item";

  const icon = document.createElement("span");
  icon.className = "work-order-side-summary-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.innerHTML = getWorkOrderIconMarkup(iconName);

  const copy = document.createElement("span");
  copy.className = "work-order-side-summary-copy";

  const labelNode = document.createElement("span");
  labelNode.className = "work-order-side-summary-label";
  labelNode.textContent = label;

  const valueNode = document.createElement("strong");
  valueNode.className = "work-order-side-summary-value";
  valueNode.textContent = value || "-";

  copy.append(labelNode, valueNode);
  item.append(icon, copy);
  return item;
}

function renderWorkOrderEditorSideSummary({
  workOrderNumber = "",
  statusLabel = "",
  priorityLabel = "",
  companyName = "",
  locationName = "",
  dateSummary = "",
  serviceSummary = "",
  contactSummary = "",
  executorValues = [],
  documentCount = 0,
} = {}) {
  if (!workOrderEditorSideSummary) {
    return;
  }

  const head = document.createElement("div");
  head.className = "work-order-side-summary-head";

  const mark = document.createElement("span");
  mark.className = "work-order-side-summary-mark";
  mark.textContent = "RN";

  const titleWrap = document.createElement("span");
  titleWrap.className = "work-order-side-summary-title";
  const title = document.createElement("strong");
  title.textContent = workOrderNumber ? `RN ${workOrderNumber}` : "Novi RN";
  const subtitle = document.createElement("span");
  subtitle.textContent = statusLabel || "Otvoreni RN";
  titleWrap.append(title, subtitle);
  head.append(mark, titleWrap);

  const chips = document.createElement("div");
  chips.className = "work-order-side-summary-chips";
  chips.append(
    createWorkOrderEditorInfoChip(statusLabel || "Otvoreni RN", "accent"),
    createWorkOrderEditorInfoChip(priorityLabel || "Normal", "soft"),
  );

  const list = document.createElement("div");
  list.className = "work-order-side-summary-list";
  list.append(
    createWorkOrderSideSummaryItem("Tvrtka", companyName || "Nije odabrana", "company"),
    createWorkOrderSideSummaryItem("Lokacija", locationName || "Nije odabrana", "location"),
    createWorkOrderSideSummaryItem("Rokovi", dateSummary || "Bez roka", "dates"),
    createWorkOrderSideSummaryItem("Usluge", serviceSummary || "Bez usluge", "service"),
    createWorkOrderSideSummaryItem("Izvršitelji", executorValues.length ? `${executorValues.length} odabrano` : "Bez izvršitelja", "assignees"),
    createWorkOrderSideSummaryItem("Kontakt", contactSummary || "Bez kontakta", "contact"),
    createWorkOrderSideSummaryItem("Upload", `${Number(documentCount || 0)} dokumenata`, "document"),
  );

  workOrderEditorSideSummary.replaceChildren(head, chips, list);
}

function createWorkOrderFieldIcon(iconName) {
  const icon = document.createElement("span");
  icon.className = `work-order-field-icon is-${iconName}`;
  icon.setAttribute("aria-hidden", "true");
  icon.innerHTML = getWorkOrderIconMarkup(iconName);
  return icon;
}

function createWorkOrderActionIcon(iconName) {
  const icon = document.createElement("span");
  icon.className = `work-order-action-icon is-${iconName}`;
  icon.setAttribute("aria-hidden", "true");
  icon.innerHTML = getWorkOrderIconMarkup(iconName);
  return icon;
}

function decorateWorkOrderFieldLabel(input, {
  iconName = "service",
  emphasize = false,
} = {}) {
  if (!(input instanceof HTMLElement)) {
    return;
  }

  const field = input.closest(".field");
  const heading = field?.querySelector(":scope > span");

  if (!field || !heading) {
    return;
  }

  const originalLabel = heading.dataset.originalLabel || heading.textContent.trim();
  heading.dataset.originalLabel = originalLabel;
  heading.className = "work-order-field-heading";

  if (!heading.dataset.decorated) {
    const label = document.createElement("span");
    label.className = "work-order-field-label";
    label.textContent = originalLabel;
    heading.replaceChildren(createWorkOrderFieldIcon(iconName), label);
    heading.dataset.decorated = "true";
  }

  field.classList.toggle("is-primary-field", emphasize);
}

function decorateWorkOrderActionButton(button, iconName) {
  if (!(button instanceof HTMLButtonElement) || button.dataset.decorated === "true") {
    return;
  }

  const label = document.createElement("span");
  label.className = "work-order-action-label";
  label.textContent = button.textContent.trim();
  button.replaceChildren(createWorkOrderActionIcon(iconName), label);
  button.dataset.decorated = "true";
}

function mountWorkOrderEditorTopActions() {
  if (!(workOrderEditorTopActions instanceof HTMLElement)) {
    return;
  }

  [
    workOrderOpenTodoButton,
    workOrderOpenReminderButton,
    workOrderResetButton,
  ].forEach((button) => {
    if (!(button instanceof HTMLButtonElement)) {
      return;
    }

    button.classList.add("work-order-editor-top-action");
    workOrderEditorTopActions.append(button);
  });
}

function createWorkOrderEditorInfoChip(label, modifier = "neutral") {
  const chip = document.createElement("span");
  chip.className = `work-order-editor-tag-chip is-${modifier}`;
  chip.textContent = label;
  return chip;
}

function setWorkOrderFieldRequiredAttention(target, missing = false) {
  const field = target instanceof HTMLElement ? target.closest(".field") : null;
  if (!field) {
    return;
  }
  field.classList.toggle("has-required-attention", Boolean(missing));
}

function getWorkOrderRequiredFieldStates(payload = buildWorkOrderPayload()) {
  const serviceItems = Array.isArray(payload?.serviceItems) ? payload.serviceItems : [];
  const executors = Array.isArray(payload?.executors) ? payload.executors : [];

  return [
    {
      key: "company",
      label: "Tvrtka",
      target: workOrderCompanyIdInput,
      complete: Boolean(String(payload?.companyId || "").trim()),
    },
    {
      key: "location",
      label: "Lokacija",
      target: workOrderLocationIdInput,
      complete: Boolean(String(payload?.locationId || "").trim()),
    },
    {
      key: "openedDate",
      label: "Datum otvaranja",
      target: workOrderOpenedDateInput,
      complete: Boolean(String(payload?.openedDate || "").trim()),
    },
    {
      key: "dueDate",
      label: "Rok završetka",
      target: workOrderDueDateInput,
      complete: Boolean(String(payload?.dueDate || "").trim()),
    },
    {
      key: "executors",
      label: "Izvršitelji",
      target: workOrderExecutorsPicker,
      complete: executors.length > 0,
    },
    {
      key: "services",
      label: "Usluge",
      target: workOrderServicePicker,
      complete: serviceItems.length > 0,
    },
  ];
}

function getWorkOrderRequiredBlockMessage(payload = buildWorkOrderPayload()) {
  const missing = getWorkOrderRequiredFieldStates(payload).filter((entry) => !entry.complete);
  return missing.length > 0
    ? `Popuni obavezno: ${missing.map((entry) => entry.label).join(", ")}.`
    : "";
}

function getWorkOrderPdfReadiness(payload = buildWorkOrderPayload()) {
  const requiredFields = getWorkOrderRequiredFieldStates(payload);
  const missing = requiredFields.filter((entry) => !entry.complete);
  return {
    requiredFields,
    missing,
    ready: missing.length === 0,
  };
}

function syncWorkOrderPdfAndRequiredFields(payload = buildWorkOrderPayload()) {
  const readiness = getWorkOrderPdfReadiness(payload);
  const shouldHighlight = state.workOrderEditorOpen && getCanEditOperationalData();

  readiness.requiredFields.forEach((entry) => {
    setWorkOrderFieldRequiredAttention(entry.target, shouldHighlight && !entry.complete);
    if (entry.target instanceof HTMLElement) {
      entry.target.setAttribute("aria-required", "true");
      if ("required" in entry.target) {
        entry.target.required = true;
      }
    }
  });

  if (workOrderDownloadPdfButton) {
    const hasWorkOrderId = Boolean(String(workOrderIdInput?.value || "").trim());
    workOrderDownloadPdfButton.hidden = !(readiness.ready || hasWorkOrderId);
    workOrderDownloadPdfButton.disabled = !readiness.ready || !hasWorkOrderId;
    workOrderDownloadPdfButton.innerHTML = getWorkOrderIconMarkup("download");
    workOrderDownloadPdfButton.setAttribute(
      "aria-label",
      hasWorkOrderId ? "Preuzmi PDF" : "PDF nakon spremanja",
    );
    workOrderDownloadPdfButton.title = readiness.ready
      ? (hasWorkOrderId ? "Preuzmi PDF i spremi ga u Documents." : "RN se automatski sprema, nakon toga PDF je dostupan.")
      : `Popuni: ${readiness.missing.map((entry) => entry.label).join(", ")}`;
  }

  const hasWorkOrderIdForDocumentation = Boolean(String(workOrderIdInput?.value || "").trim());
  const documentationTitle = readiness.ready
    ? (hasWorkOrderIdForDocumentation ? "Otvori izradu dokumentacije za ovaj RN." : "Spremi RN i otvori izradu dokumentacije.")
    : `Popuni: ${readiness.missing.map((entry) => entry.label).join(", ")}`;

  if (workOrderOpenDocumentationButton) {
    workOrderOpenDocumentationButton.hidden = !(readiness.ready || hasWorkOrderIdForDocumentation);
    workOrderOpenDocumentationButton.disabled = !readiness.ready;
    workOrderOpenDocumentationButton.innerHTML = `${getWorkOrderIconMarkup("document")}<span>Izradi dokumentaciju</span>`;
    workOrderOpenDocumentationButton.setAttribute("aria-label", "Izrada dokumentacije");
    workOrderOpenDocumentationButton.title = documentationTitle;
  }

  if (workOrderCreateDocumentationButton) {
    workOrderCreateDocumentationButton.disabled = !readiness.ready;
    workOrderCreateDocumentationButton.title = documentationTitle;
  }

  return readiness;
}

