function renderWorkOrderEditorExecutorPicker() {
  if (!workOrderExecutorsPicker) {
    return;
  }

  const wrapper = document.createElement("div");
  wrapper.className = "work-order-calendar-executor-picker work-order-editor-executor-picker";

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "work-order-calendar-executor-trigger work-order-editor-executor-trigger";
  trigger.setAttribute("aria-haspopup", "dialog");
  trigger.setAttribute("aria-expanded", "false");

  const getCurrentValues = () => readWorkOrderExecutorSelection();
  const setCurrentValues = (values) => {
    setWorkOrderCalendarExecutorTriggerContent(trigger, values);
  };

  const positionMenuPortal = (menu) => {
    const triggerRect = trigger.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let left = triggerRect.left;
    let top = triggerRect.bottom + 8;

    if (left + menuRect.width > viewportWidth - 12) {
      left = Math.max(12, viewportWidth - menuRect.width - 12);
    }

    if (top + menuRect.height > viewportHeight - 12) {
      top = Math.max(12, triggerRect.top - menuRect.height - 8);
    }

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.minWidth = `${Math.max(280, Math.round(triggerRect.width))}px`;
  };

  const closeMenu = () => {
    wrapper.classList.remove("is-open");
    trigger.setAttribute("aria-expanded", "false");
    if (wrapper._menuPortal) {
      wrapper._menuPortal.remove();
      wrapper._menuPortal = null;
    }
  };

  wrapper._closeMenu = closeMenu;

  const openMenu = () => {
    closeOpenWorkOrderStatusMenus(wrapper);

    if (wrapper._menuPortal) {
      return;
    }

    let draftValues = getCurrentValues();
    let searchQuery = "";

    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal work-order-calendar-executor-menu-portal";
    menu.setAttribute("role", "dialog");
    menu.setAttribute("aria-label", "Izbor izvršitelja");

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => {
        event.stopPropagation();
      });
    });
    menu.addEventListener("wheel", (event) => event.stopPropagation(), { passive: true });

    const searchWrap = document.createElement("div");
    searchWrap.className = "work-order-calendar-executor-search";

    const searchInput = document.createElement("input");
    searchInput.type = "search";
    searchInput.className = "work-order-calendar-executor-search-input";
    searchInput.placeholder = "Traži po imenu ili prezimenu";
    searchInput.autocomplete = "off";
    searchInput.spellcheck = false;
    searchWrap.append(searchInput);

    const selection = document.createElement("div");
    selection.className = "work-order-calendar-executor-selection";

    const helper = document.createElement("p");
    helper.className = "work-order-calendar-executor-helper";

    const optionsList = document.createElement("div");
    optionsList.className = "work-order-calendar-executor-options";

    const clearButton = document.createElement("button");
    clearButton.type = "button";
    clearButton.className = "ghost-button work-order-calendar-executor-clear";
    clearButton.textContent = "Očisti";

    const selectionsEqual = (leftValues, rightValues) => {
      if (leftValues.length !== rightValues.length) {
        return false;
      }

      return leftValues.every((value, index) => value === rightValues[index]);
    };

    const toggleDraftValue = (value) => {
      const normalizedValue = String(value ?? "").trim();
      if (!normalizedValue) {
        return;
      }

      if (draftValues.includes(normalizedValue)) {
        draftValues = draftValues.filter((entry) => entry !== normalizedValue);
        return;
      }

      draftValues = [...draftValues, normalizedValue];
    };

    const applyDraftValues = (nextValues, { focusSearch = true } = {}) => {
      const normalized = normalizeWorkOrderExecutorValues(nextValues);
      draftValues = normalized;

      if (!selectionsEqual(normalized, getCurrentValues())) {
        writeWorkOrderExecutorSelection(normalized, {
          dispatchEventName: "change",
          renderPicker: false,
        });
      }

      setCurrentValues(normalized);
      syncMenuState();

      if (focusSearch) {
        searchInput.focus({ preventScroll: true });
      }
    };

    const renderSelection = () => {
      selection.replaceChildren();

      if (draftValues.length === 0) {
        const empty = document.createElement("span");
        empty.className = "work-order-calendar-executor-selection-empty";
        empty.textContent = "Bez izvršitelja";
        selection.append(empty);
        return;
      }

      draftValues.forEach((value) => {
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "work-order-calendar-executor-chip";
        chip.title = `Makni ${value}`;

        const avatar = createWorkOrderMiniExecutor(value);
        avatar.removeAttribute("title");

        const label = document.createElement("span");
        label.className = "work-order-calendar-executor-chip-label";
        label.textContent = value;

        const remove = document.createElement("span");
        remove.className = "work-order-calendar-executor-chip-remove";
        remove.setAttribute("aria-hidden", "true");
        remove.textContent = "x";

        chip.append(avatar, label, remove);
        chip.addEventListener("click", (event) => {
          event.stopPropagation();
          applyDraftValues(draftValues.filter((entry) => entry !== value));
        });

        selection.append(chip);
      });
    };

    const renderOptions = () => {
      optionsList.replaceChildren();

      const visibleOptions = getWorkOrderExecutorOptions(getCurrentValues())
        .filter((option) => matchesWorkOrderExecutorSearch(option, searchQuery));

      if (visibleOptions.length === 0) {
        const empty = document.createElement("p");
        empty.className = "work-order-calendar-executor-empty";
        empty.textContent = "Nema izvršitelja za ovaj pojam.";
        optionsList.append(empty);
        return;
      }

      visibleOptions.forEach((option) => {
        const isSelected = draftValues.includes(option.value);
        const optionButton = document.createElement("button");
        optionButton.type = "button";
        optionButton.className = "work-item-status-option work-order-calendar-executor-option";
        optionButton.classList.toggle("is-selected", isSelected);
        optionButton.setAttribute("role", "menuitemcheckbox");
        optionButton.setAttribute("aria-checked", String(isSelected));

        const avatar = createWorkOrderMiniExecutor(option, {
          className: "work-order-calendar-executor-option-avatar",
        });

        const label = document.createElement("span");
        label.className = "work-order-calendar-executor-option-label";
        label.textContent = option.label;

        const marker = document.createElement("span");
        marker.className = "work-order-calendar-executor-option-marker";
        marker.setAttribute("aria-hidden", "true");
        marker.textContent = isSelected ? "✓" : "+";

        optionButton.append(avatar, label, marker);
        optionButton.addEventListener("click", (event) => {
          event.stopPropagation();
          toggleDraftValue(option.value);
          applyDraftValues(draftValues);
        });

        optionsList.append(optionButton);
      });
    };

    const syncMenuState = () => {
      renderSelection();
      renderOptions();
      helper.textContent = draftValues.length > 0
        ? `${draftValues.length} odabranih izvršitelja.`
        : "Odaberi jednog ili više izvršitelja.";
      clearButton.disabled = draftValues.length === 0;
      requestAnimationFrame(() => positionMenuPortal(menu));
    };

    clearButton.addEventListener("click", (event) => {
      event.stopPropagation();
      applyDraftValues([]);
    });

    searchInput.addEventListener("input", () => {
      searchQuery = searchInput.value || "";
      renderOptions();
      requestAnimationFrame(() => positionMenuPortal(menu));
    });

    searchInput.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        closeMenu();
        trigger.focus({ preventScroll: true });
        return;
      }

      if (event.key !== "Enter") {
        return;
      }

      const visibleOptions = getWorkOrderExecutorOptions(getCurrentValues())
        .filter((option) => matchesWorkOrderExecutorSearch(option, searchQuery));

      if (visibleOptions.length !== 1) {
        return;
      }

      event.preventDefault();
      toggleDraftValue(visibleOptions[0].value);
      applyDraftValues(draftValues);
    });

    menu.append(searchWrap, selection, helper, optionsList, clearButton);

    syncMenuState();

    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    positionMenuPortal(menu);
    requestAnimationFrame(() => {
      positionMenuPortal(menu);
      searchInput.focus({ preventScroll: true });
      searchInput.select();
    });
  };

  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    wrapper.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });

  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (wrapper.classList.contains("is-open")) {
      closeOpenWorkOrderStatusMenus();
      return;
    }
    openMenu();
  });

  setCurrentValues(getCurrentValues());
  wrapper.append(trigger);
  workOrderExecutorsPicker.replaceChildren(wrapper);
}

function getWorkOrderServiceCatalogOptions(currentItems = []) {
  const options = [];
  const seen = new Set();

  currentItems.forEach((item) => {
    const key = String(item.serviceId || `${item.serviceCode}::${item.name}`).trim();
    if (!key || seen.has(key)) {
      return;
    }

    options.push({
      id: item.serviceId || key,
      name: item.name,
      serviceCode: item.serviceCode,
      serviceType: getWorkOrderServiceType(item),
      linkedTemplateIds: [...(item.linkedTemplateIds ?? [])],
      linkedTemplateTitles: [...(item.linkedTemplateTitles ?? [])],
      linkedLearningTestIds: [...(item.linkedLearningTestIds ?? [])],
      linkedLearningTestTitles: [...(item.linkedLearningTestTitles ?? [])],
      isTraining: Boolean(item.isTraining),
      status: "inactive",
      isSnapshot: true,
    });
    seen.add(key);
  });

  sortServiceCatalogItems(state.serviceCatalog ?? []).forEach((item) => {
    const key = String(item.id || `${item.serviceCode}::${item.name}`).trim();
    if (!key || seen.has(key)) {
      return;
    }

    options.push(item);
    seen.add(key);
  });

  return options;
}

function matchesWorkOrderServiceSearch(option, query = "") {
  const normalizedQuery = normalizeLooseName(query);

  if (!normalizedQuery) {
    return true;
  }

  const haystack = [
    option.name,
    option.serviceCode,
    getServiceCatalogTypeLabel(option.serviceType),
    ...(option.linkedTemplateTitles ?? []),
    ...(option.linkedLearningTestTitles ?? []),
  ]
    .join(" ")
    .toLowerCase();

  return haystack.includes(normalizedQuery);
}

function setWorkOrderServicePickerTriggerContent(trigger, items = []) {
  const selectedItems = getWorkOrderServiceItems({ serviceItems: items });
  trigger.replaceChildren();
  trigger.title = selectedItems.length > 0
    ? selectedItems.map((item) => item.name || item.serviceCode).join(", ")
    : "Dodaj usluge";

  const label = document.createElement("span");
  label.className = "work-order-service-picker-label";
  label.textContent = selectedItems.length > 0
    ? `Uredi usluge (${selectedItems.length})`
    : "+ Dodaj usluge";

  trigger.append(label);

  if (selectedItems.length > 0) {
    const meta = document.createElement("span");
    meta.className = "work-order-service-picker-empty";
    const progressCounts = summarizeWorkOrderServiceProgress(selectedItems);
    meta.textContent = [
      progressCounts.pending ? `${progressCounts.pending} nije završeno` : "",
      progressCounts.in_progress ? `${progressCounts.in_progress} u tijeku` : "",
      progressCounts.completed ? `${progressCounts.completed} završeno` : "",
    ].filter(Boolean).join(" · ");
    trigger.append(meta);
  }
}

function normalizeWeatherCityName(value = "") {
  return String(value ?? "")
    .trim()
    .replace(/\s+/g, " ")
    .slice(0, 80);
}

function getWeatherCityKey(value = "") {
  return normalizeWeatherCityName(value).toLowerCase();
}

function formatWeatherCityLabel(value = "") {
  const normalized = normalizeWeatherCityName(value);
  if (!normalized) {
    return "";
  }
  const geoLabel = normalized.match(/^geo:[^:]+:(.+)$/i)?.[1];
  if (geoLabel) {
    return geoLabel
      .split(",")
      .map((part) => part.trim())
      .filter(Boolean)
      .join(", ");
  }
  return normalized
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean)
    .join(", ");
}

function getWeatherPreferenceScope() {
  const userId = state.user?.id || state.user?.email || "guest";
  const organizationId = state.activeOrganizationId || "global";
  return `${userId}:${organizationId}`;
}

function getWeatherCitiesStorageKey() {
  return `${WEATHER_CITIES_STORAGE_PREFIX}${getWeatherPreferenceScope()}`;
}

function getWeatherActiveCityStorageKey() {
  return `${WEATHER_ACTIVE_CITY_STORAGE_PREFIX}${getWeatherPreferenceScope()}`;
}

function normalizeWeatherCityList(value = []) {
  const seen = new Set();
  return (Array.isArray(value) ? value : [])
    .map(normalizeWeatherCityName)
    .filter((city) => {
      const key = getWeatherCityKey(city);
      if (!city || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .slice(0, WEATHER_MAX_CITIES);
}

function loadWeatherPreferences() {
  const scope = getWeatherPreferenceScope();
  if (weatherPreferenceScope === scope && weatherCities.length > 0) {
    return;
  }

  weatherPreferenceScope = scope;
  weatherCities = normalizeWeatherCityList(readJsonFromLocalStorage(getWeatherCitiesStorageKey(), WEATHER_DEFAULT_CITIES));
  if (weatherCities.length === 0) {
    weatherCities = [...WEATHER_DEFAULT_CITIES];
  }
  const storedActiveCity = normalizeWeatherCityName(window.localStorage?.getItem(getWeatherActiveCityStorageKey()) || "");
  weatherActiveCity = weatherCities.find((city) => getWeatherCityKey(city) === getWeatherCityKey(storedActiveCity))
    || weatherCities[0]
    || "";
  weatherItems = [];
  weatherStatus = "idle";
  weatherErrorMessage = "";
  weatherLoadedAt = 0;
  weatherAutoRefreshQueued = false;
  clearWeatherCitySuggestions();
}

function persistWeatherPreferences() {
  if (!state.user) {
    return;
  }
  writeJsonToLocalStorage(getWeatherCitiesStorageKey(), weatherCities);
  try {
    window.localStorage.setItem(getWeatherActiveCityStorageKey(), weatherActiveCity || "");
  } catch {
    // Ignore persistence failures.
  }
}

function getWeatherConditionClass(condition = "") {
  const normalized = String(condition || "").trim().toLowerCase();
  if (["thunderstorm", "storm"].includes(normalized)) return "is-thunderstorm";
  if (normalized === "rain" || normalized === "drizzle") return "is-rain";
  if (normalized === "snow") return "is-snow";
  if (["mist", "fog", "haze", "smoke", "dust", "sand", "ash", "squall", "tornado"].includes(normalized)) return "is-fog";
  if (normalized === "clouds") return "is-clouds";
  return "is-clear";
}

function isWeatherNight(weatherLike = null) {
  if (!weatherLike || typeof weatherLike !== "object") {
    return false;
  }
  if (typeof weatherLike.isNight === "boolean") {
    return weatherLike.isNight;
  }
  return String(weatherLike.icon || "").trim().toLowerCase().endsWith("n");
}

function getWeatherVisualCondition(weatherLike = "clear") {
  if (weatherLike && typeof weatherLike === "object") {
    return weatherLike.condition || "clear";
  }
  return weatherLike || "clear";
}

function getWeatherVisualClass(weatherLike = "clear") {
  return [
    getWeatherConditionClass(getWeatherVisualCondition(weatherLike)),
    isWeatherNight(weatherLike) ? "is-night" : "",
  ].filter(Boolean).join(" ");
}

function getWeatherConditionLabel(condition = "") {
  const map = {
    clear: "Vedro",
    clouds: "Oblačno",
    rain: "Kiša",
    drizzle: "Rosulja",
    thunderstorm: "Oluja",
    snow: "Snijeg",
    mist: "Magla",
    fog: "Magla",
    haze: "Sumaglica",
    smoke: "Dim",
    dust: "Prašina",
    sand: "Pijesak",
    ash: "Pepeo",
    squall: "Neverin",
    tornado: "Tornado",
  };
  const key = String(condition || "").trim().toLowerCase();
  return map[key] || "Vrijeme";
}

function getWeatherDisplayDescription(weatherLike = {}) {
  const condition = getWeatherVisualCondition(weatherLike);
  const description = String(weatherLike?.description || "").trim();
  if (isWeatherNight(weatherLike)) {
    if (condition === "clear") {
      return "Vedra noć";
    }
    if (condition === "clouds" && (!description || description.toLowerCase().includes("obla"))) {
      return "Oblačna noć";
    }
  }
  return description || getWeatherConditionLabel(condition);
}

function formatWeatherTemperature(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) {
    return "--°";
  }
  return `${Math.round(number)}°`;
}

function formatWeatherPrecipitation(value) {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) {
    return "";
  }
  if (number < 1) {
    return "<1 mm";
  }
  return `${Math.round(number)} mm`;
}

function formatWeatherCardTemperature(value) {
  const formatted = formatWeatherTemperature(value);
  return formatted === "--°" ? "-" : formatted;
}

function formatWeatherSpeed(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) {
    return "-- km/h";
  }
  return `${Math.round(number * 3.6)} km/h`;
}

function formatWeatherTime(isoValue = "") {
  if (!isoValue) {
    return "";
  }
  const date = new Date(isoValue);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  return new Intl.DateTimeFormat("hr-HR", {
    weekday: "short",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

function formatWeatherForecastDay(isoValue = "") {
  if (!isoValue) {
    return "";
  }
  const date = new Date(isoValue);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  return new Intl.DateTimeFormat("hr-HR", {
    weekday: "short",
    day: "2-digit",
    month: "2-digit",
  }).format(date);
}

function formatWeatherForecastHour(isoValue = "") {
  if (!isoValue) {
    return "";
  }
  const date = new Date(isoValue);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  return new Intl.DateTimeFormat("hr-HR", {
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

function buildWeatherTemperatureText(label, values = []) {
  const numbers = values.map(Number).filter(Number.isFinite);
  if (!numbers.length) {
    return "";
  }
  const min = Math.round(Math.min(...numbers));
  const max = Math.round(Math.max(...numbers));
  return min === max
    ? `${label} oko ${max} °C`
    : `${label} između ${min} i ${max} °C`;
}

function buildWeatherDominantConditionText(entries = []) {
  const counts = entries.reduce((map, entry) => {
    const condition = getWeatherVisualCondition(entry);
    map.set(condition, (map.get(condition) || 0) + 1);
    return map;
  }, new Map());
  const dominant = [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] || "clear";
  if (dominant === "thunderstorm") {
    return "mogući su lokalni pljuskovi s grmljavinom";
  }
  if (dominant === "rain" || dominant === "drizzle") {
    return "prevladavat će promjenjivo vrijeme s kišom";
  }
  if (dominant === "snow") {
    return "očekuje se hladnije vrijeme sa snijegom";
  }
  if (dominant === "fog") {
    return "moguća je magla i smanjena vidljivost";
  }
  if (dominant === "clouds") {
    return "prevladavat će oblačnije vrijeme uz povremena sunčana razdoblja";
  }
  return "prevladavat će stabilno i pretežno sunčano vrijeme";
}

function buildWeatherWindText(maxWindMs) {
  const windKmh = Math.round(Number(maxWindMs || 0) * 3.6);
  if (!windKmh) {
    return "";
  }
  if (windKmh >= 50) {
    return `Vjetar može biti jak, s udarima do oko ${windKmh} km/h.`;
  }
  if (windKmh >= 25) {
    return `Vjetar slab do umjeren, povremeno pojačan do oko ${windKmh} km/h.`;
  }
  return `Vjetar uglavnom slab, do oko ${windKmh} km/h.`;
}

function buildWeatherNarrative(activeItem = {}) {
  const entries = Array.isArray(activeItem?.dailyForecast) ? activeItem.dailyForecast.slice(0, 5) : [];
  if (!entries.length) {
    return activeItem.summary || "Trenutni uvjeti i kratka prognoza za odabrani grad.";
  }

  const totalPrecipitation = entries.reduce((sum, entry) => {
    const value = entry.precipitationMm ?? (Number(entry.rainMm || 0) + Number(entry.snowMm || 0));
    return sum + Number(value || 0);
  }, 0);
  const precipitationDays = entries.filter((entry) => {
    const value = entry.precipitationMm ?? (Number(entry.rainMm || 0) + Number(entry.snowMm || 0));
    return Number(value || 0) > 0.5;
  }).length;
  const hasStorm = entries.some((entry) => getWeatherVisualCondition(entry) === "thunderstorm");
  const morningText = buildWeatherTemperatureText("Jutarnje temperature", entries.map((entry) => entry.morningTemp ?? entry.tempMin ?? entry.temp));
  const afternoonText = buildWeatherTemperatureText("popodnevne većinom", entries.map((entry) => entry.afternoonTemp ?? entry.tempMax ?? entry.temp));
  const maxWind = Math.max(...entries.map((entry) => Number(entry.windGust || entry.windSpeed || 0)), Number(activeItem.current?.windGust || activeItem.current?.windSpeed || 0));
  const temperatureSentence = [morningText, afternoonText].filter(Boolean).join(", ");
  const conditionText = buildWeatherDominantConditionText(entries);
  const windText = buildWeatherWindText(maxWind);

  const sentences = [
    `U idućim danima ${conditionText}.`,
  ];
  if (totalPrecipitation > 0.5) {
    const precipitationText = precipitationDays > 1
      ? `Oborine se očekuju kroz ${precipitationDays} dana, ukupno oko ${Math.round(totalPrecipitation)} mm.`
      : `Oborine su moguće lokalno, ukupno oko ${Math.round(totalPrecipitation)} mm.`;
    sentences.push(precipitationText);
  } else {
    sentences.push("Oborine se ne ističu kao glavni rizik u prikazanoj prognozi.");
  }
  if (hasStorm) {
    sentences.push("Uz nestabilnosti su mogući pljuskovi s grmljavinom i kratkotrajno jači udari vjetra.");
  } else if (windText) {
    sentences.push(windText);
  }
  if (temperatureSentence) {
    sentences.push(`${temperatureSentence}.`);
  }

  return sentences.join(" ");
}

const WEATHER_VISUAL_PART_CLASSES = Object.freeze([
  "weather-halo",
  "weather-rays",
  "weather-moon",
  "weather-sun",
  "weather-cloud",
  "weather-rain",
  "weather-snow",
  "weather-bolt",
  "weather-fog",
  "weather-wind",
  "weather-sparkle",
]);

function populateWeatherVisualParts(container) {
  if (!(container instanceof HTMLElement)) {
    return;
  }

  container.replaceChildren(...WEATHER_VISUAL_PART_CLASSES.map((partClass) => {
    const part = document.createElement("span");
    part.className = partClass;
    return part;
  }));
}

function createWeatherVisual(weatherLike = "clear", className = "weather-mini-icon") {
  const wrap = document.createElement("span");
  wrap.className = `${className} ${getWeatherVisualClass(weatherLike)}`;
  wrap.setAttribute("aria-hidden", "true");
  populateWeatherVisualParts(wrap);
  return wrap;
}

function getActiveWeatherItem() {
  if (!weatherItems.length) {
    return null;
  }
  return weatherItems.find((item) => getWeatherCityKey(item.query || item.name || "") === getWeatherCityKey(weatherActiveCity))
    || weatherItems[0]
    || null;
}

function getWeatherAlertCount() {
  return weatherItems.reduce((sum, item) => sum + (Array.isArray(item.alerts) ? item.alerts.length : 0), 0);
}

function renderWeatherTrigger() {
  const activeItem = getActiveWeatherItem();
  const currentWeather = activeItem?.current || { condition: "clear" };
  if (weatherTrigger) {
    weatherTrigger.hidden = !state.user;
    weatherTrigger.setAttribute("aria-expanded", weatherMenuOpen ? "true" : "false");
    weatherTrigger.classList.toggle("is-open", weatherMenuOpen);
    weatherTrigger.classList.toggle("has-alert", getWeatherAlertCount() > 0);
    weatherTrigger.classList.toggle("is-loading", weatherStatus === "loading");
    weatherTrigger.title = activeItem
      ? `${activeItem.name || weatherActiveCity}: ${formatWeatherTemperature(activeItem.current?.temp)}`
      : "Vrijeme";
  }
  if (weatherTriggerIcon) {
    weatherTriggerIcon.className = `weather-mini-icon ${getWeatherVisualClass(currentWeather)}`;
    populateWeatherVisualParts(weatherTriggerIcon);
  }
  if (weatherTriggerTemp) {
    weatherTriggerTemp.hidden = !activeItem;
    weatherTriggerTemp.textContent = formatWeatherTemperature(activeItem?.current?.temp);
  }
}

function renderWeatherHero() {
  if (!weatherHero) {
    return;
  }
  const activeItem = getActiveWeatherItem();
  weatherHero.replaceChildren();
  if (!activeItem) {
    const empty = document.createElement("div");
    empty.className = "weather-loading";
    empty.textContent = weatherStatus === "loading"
      ? "Učitavam prognozu..."
      : "Dodaj grad ili osvježi vrijeme.";
    weatherHero.append(empty);
    weatherHero.className = "weather-hero";
    return;
  }

  const currentWeather = activeItem.current || { condition: "clear" };
  const condition = currentWeather.condition || "clear";
  weatherHero.className = `weather-hero ${getWeatherVisualClass(currentWeather)}`;

  const copy = document.createElement("div");
  copy.className = "weather-hero-copy";

  const location = document.createElement("span");
  location.className = "weather-location";
  location.textContent = [activeItem.name, activeItem.country].filter(Boolean).join(", ");

  const description = document.createElement("div");
  description.className = "weather-description";
  const eyebrow = document.createElement("span");
  eyebrow.textContent = "Prognoza vremena";
  const title = document.createElement("strong");
  title.textContent = getWeatherDisplayDescription(currentWeather);
  const summary = document.createElement("p");
  summary.textContent = buildWeatherNarrative(activeItem);
  description.append(eyebrow, title, summary);

  const metrics = document.createElement("div");
  metrics.className = "weather-current-metrics";
  [
    `Vjetar ${formatWeatherSpeed(activeItem.current?.windSpeed)}`,
    `Vlaga ${Math.round(Number(activeItem.current?.humidity) || 0)}%`,
    `Tlak ${Math.round(Number(activeItem.current?.pressure) || 0)} hPa`,
  ].forEach((text) => {
    const metric = document.createElement("span");
    metric.textContent = text;
    metrics.append(metric);
  });

  copy.append(location, description, metrics);

  const tempBlock = document.createElement("div");
  tempBlock.className = "weather-temp-block";
  tempBlock.append(
    createWeatherVisual(currentWeather, "weather-visual-icon"),
    Object.assign(document.createElement("span"), {
      className: "weather-temp-value",
      textContent: formatWeatherTemperature(activeItem.current?.temp),
    }),
    Object.assign(document.createElement("span"), {
      className: "weather-feels",
      textContent: `Osjećaj ${formatWeatherTemperature(activeItem.current?.feelsLike)}`,
    }),
  );

  weatherHero.append(copy, tempBlock);
}

function renderWeatherCities() {
  if (weatherCityLimit) {
    weatherCityLimit.textContent = `${weatherCities.length}/${WEATHER_MAX_CITIES} gradova`;
  }
  if (!weatherCityList) {
    return;
  }
  weatherCityList.replaceChildren(...weatherCities.map((city) => {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = `weather-city-chip${getWeatherCityKey(city) === getWeatherCityKey(weatherActiveCity) ? " is-active" : ""}`;
    chip.dataset.weatherCity = city;

    const label = document.createElement("span");
    label.textContent = formatWeatherCityLabel(city);
    chip.append(label);

    const remove = document.createElement("span");
    remove.className = "weather-remove-city";
    remove.dataset.weatherRemoveCity = city;
    remove.textContent = "x";
    chip.append(remove);
    return chip;
  }));
}

function clearWeatherCitySuggestions({ render = true } = {}) {
  if (weatherCitySearchTimerId) {
    window.clearTimeout(weatherCitySearchTimerId);
    weatherCitySearchTimerId = 0;
  }
  weatherCitySuggestions = [];
  weatherCitySuggestionsOpen = false;
  weatherCitySearchStatus = "idle";
  weatherCitySearchMessage = "";
  if (render) {
    renderWeatherCitySuggestions();
  }
}

function renderWeatherCitySuggestions() {
  if (weatherCityInput) {
    weatherCityInput.setAttribute("aria-expanded", weatherCitySuggestionsOpen ? "true" : "false");
  }
  if (!weatherCitySuggestionsPanel) {
    return;
  }

  const query = normalizeWeatherCityName(weatherCityInput?.value || "");
  const shouldShow = weatherMenuOpen
    && weatherCitySuggestionsOpen
    && (query.length >= 2 || weatherCitySearchStatus === "loading" || weatherCitySearchMessage);
  weatherCitySuggestionsPanel.hidden = !shouldShow;
  weatherCitySuggestionsPanel.replaceChildren();
  if (!shouldShow) {
    return;
  }

  if (weatherCitySearchStatus === "loading") {
    const loading = document.createElement("div");
    loading.className = "weather-city-suggestion-empty";
    loading.textContent = "Tražim gradove...";
    weatherCitySuggestionsPanel.append(loading);
    return;
  }

  if (weatherCitySearchMessage) {
    const message = document.createElement("div");
    message.className = "weather-city-suggestion-empty";
    message.textContent = weatherCitySearchMessage;
    weatherCitySuggestionsPanel.append(message);
    return;
  }

  if (weatherCitySuggestions.length === 0) {
    const empty = document.createElement("div");
    empty.className = "weather-city-suggestion-empty";
    empty.textContent = "Nema prijedloga za upisani grad.";
    weatherCitySuggestionsPanel.append(empty);
    return;
  }

  weatherCitySuggestionsPanel.replaceChildren(...weatherCitySuggestions.map((city) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "weather-city-suggestion";
    button.dataset.weatherSuggestion = city.query || city.label || city.name || "";

    const main = document.createElement("strong");
    main.textContent = city.name || city.label || "Grad";
    const meta = document.createElement("span");
    meta.textContent = [city.state, city.country].filter(Boolean).join(" | ") || "OpenWeather";
    const badge = document.createElement("small");
    badge.textContent = "Dodaj";

    button.append(main, meta, badge);
    return button;
  }));
}

function scheduleWeatherCitySuggestions(query = weatherCityInput?.value || "") {
  const normalizedQuery = normalizeWeatherCityName(query);
  if (weatherCitySearchTimerId) {
    window.clearTimeout(weatherCitySearchTimerId);
    weatherCitySearchTimerId = 0;
  }
  weatherCitySuggestionsOpen = true;
  weatherCitySearchMessage = "";
  if (normalizedQuery.length < 2) {
    weatherCitySuggestions = [];
    weatherCitySearchStatus = "idle";
    renderWeatherCitySuggestions();
    return;
  }
  weatherCitySearchStatus = "loading";
  renderWeatherCitySuggestions();
  weatherCitySearchTimerId = window.setTimeout(() => {
    weatherCitySearchTimerId = 0;
    void loadWeatherCitySuggestions(normalizedQuery);
  }, 220);
}

async function loadWeatherCitySuggestions(query = "") {
  const normalizedQuery = normalizeWeatherCityName(query);
  if (!state.user || normalizedQuery.length < 2) {
    clearWeatherCitySuggestions();
    return;
  }
  const requestId = ++weatherCitySearchRequestId;
  weatherCitySearchStatus = "loading";
  weatherCitySearchMessage = "";
  renderWeatherCitySuggestions();
  try {
    const params = new URLSearchParams({ q: normalizedQuery });
    const payload = await apiRequest(`/weather/cities?${params.toString()}`);
    if (requestId !== weatherCitySearchRequestId) {
      return;
    }
    weatherCitySuggestions = Array.isArray(payload.cities) ? payload.cities : [];
    weatherCitySearchStatus = "ready";
    weatherCitySearchMessage = "";
  } catch (error) {
    if (requestId !== weatherCitySearchRequestId) {
      return;
    }
    weatherCitySuggestions = [];
    weatherCitySearchStatus = "error";
    weatherCitySearchMessage = error?.message || "Pretraga gradova trenutno nije dostupna.";
  }
  renderWeatherCitySuggestions();
}

function renderWeatherAlerts() {
  if (!weatherAlerts) {
    return;
  }
  weatherAlerts.replaceChildren();
  const activeItem = getActiveWeatherItem();
  const alerts = Array.isArray(activeItem?.alerts) ? activeItem.alerts : [];
  alerts.slice(0, 4).forEach((alert) => {
    const row = document.createElement("div");
    row.className = `weather-alert${alert.level === "danger" ? " is-danger" : ""}`;
    const icon = document.createElement("span");
    icon.className = "weather-alert-icon";
    icon.textContent = alert.type === "storm" ? "!" : "W";
    const copy = document.createElement("span");
    copy.className = "weather-alert-copy";
    const title = document.createElement("strong");
    title.textContent = alert.title || "Upozorenje";
    const message = document.createElement("span");
    message.textContent = alert.message || "";
    copy.append(title, message);
    row.append(icon, copy);
    weatherAlerts.append(row);
  });
}

function renderWeatherForecast() {
  if (!weatherForecast) {
    return;
  }
  weatherForecast.replaceChildren();
  const activeItem = getActiveWeatherItem();
  const entries = Array.isArray(activeItem?.dailyForecast) && activeItem.dailyForecast.length
    ? activeItem.dailyForecast.slice(0, 5)
    : (Array.isArray(activeItem?.forecast) ? activeItem.forecast.slice(0, 5) : []);
  if (!entries.length) {
    return;
  }
  const head = document.createElement("div");
  head.className = "weather-forecast-head";
  const title = document.createElement("div");
  title.className = "weather-forecast-title";
  title.textContent = "Dnevna prognoza";
  const meta = document.createElement("span");
  meta.textContent = "5 dana unaprijed.";
  head.append(title, meta);

  const strip = document.createElement("div");
  strip.className = "weather-forecast-strip";
  entries.forEach((entry) => {
    const card = document.createElement("article");
    card.className = "weather-forecast-card";

    const day = document.createElement("span");
    day.className = "weather-forecast-day";
    day.textContent = formatWeatherForecastDay(entry.time || entry.date) || "Prognoza";

    const temps = document.createElement("div");
    temps.className = "weather-daily-temps";
    [
      ["Jutro", entry.morningTemp ?? entry.tempMin ?? entry.temp],
      ["Popodne", entry.afternoonTemp ?? entry.tempMax ?? entry.temp],
    ].forEach(([labelText, value]) => {
      const pill = document.createElement("span");
      pill.className = "weather-daily-temp-pill";
      const label = document.createElement("span");
      label.className = "weather-daily-temp-label";
      label.textContent = labelText;
      const tempValue = document.createElement("strong");
      tempValue.className = "weather-daily-temp-value";
      tempValue.textContent = formatWeatherCardTemperature(value);
      pill.append(label, tempValue);
      temps.append(pill);
    });

    const description = document.createElement("span");
    description.className = "weather-forecast-description";
    description.textContent = getWeatherDisplayDescription(entry);

    const wind = document.createElement("span");
    wind.className = "weather-forecast-wind";
    const precipitation = formatWeatherPrecipitation(entry.precipitationMm ?? (Number(entry.rainMm || 0) + Number(entry.snowMm || 0)));
    wind.textContent = precipitation
      ? `Oborine ${precipitation}`
      : `Vjetar do ${formatWeatherSpeed(entry.windSpeed)}`;

    card.append(day, createWeatherVisual(entry, "weather-mini-icon"), temps, description, wind);
    strip.append(card);
  });
  weatherForecast.append(head, strip);
}

function renderWeatherWidget() {
  if (!weatherTrigger) {
    return;
  }
  if (!state.user) {
    weatherMenuOpen = false;
    if (weatherPanel) {
      weatherPanel.hidden = true;
    }
    weatherTrigger.hidden = true;
    clearWeatherCitySuggestions();
    return;
  }

  loadWeatherPreferences();
  const shouldAutoRefresh = weatherStatus === "idle" && weatherCities.length > 0 && !weatherAutoRefreshQueued;
  if (weatherPanel) {
    weatherPanel.hidden = !weatherMenuOpen;
  }
  if (weatherPanelMeta) {
    if (weatherStatus === "loading") {
      weatherPanelMeta.textContent = "Učitavam OpenWeather podatke...";
    } else if (weatherLoadedAt) {
      weatherPanelMeta.textContent = `Ažurirano ${formatDateTime(new Date(weatherLoadedAt).toISOString())}`;
    } else {
      weatherPanelMeta.textContent = "Do 8 gradova, s upozorenjima za vjetar i oluje.";
    }
  }
  if (weatherRefreshButton) {
    weatherRefreshButton.disabled = weatherStatus === "loading";
  }
  if (weatherError) {
    weatherError.hidden = !weatherErrorMessage;
    weatherError.textContent = weatherErrorMessage;
  }
  renderWeatherTrigger();
  renderWeatherHero();
  renderWeatherCities();
  renderWeatherCitySuggestions();
  renderWeatherAlerts();
  renderWeatherForecast();

  if (shouldAutoRefresh) {
    weatherAutoRefreshQueued = true;
    window.setTimeout(() => {
      weatherAutoRefreshQueued = false;
      void refreshWeather();
    }, 0);
  }
}

async function refreshWeather({ force = false } = {}) {
  if (!state.user || weatherStatus === "loading") {
    return;
  }
  loadWeatherPreferences();
  if (!force && weatherItems.length > 0 && Date.now() - weatherLoadedAt < WEATHER_REFRESH_INTERVAL_MS) {
    renderWeatherWidget();
    return;
  }
  weatherStatus = "loading";
  weatherErrorMessage = "";
  renderWeatherWidget();
  try {
    const params = new URLSearchParams({ cities: weatherCities.join("|") });
    const payload = await apiRequest(`/weather?${params.toString()}`);
    weatherItems = Array.isArray(payload.cities) ? payload.cities : [];
    weatherLoadedAt = Date.now();
    const cityErrors = Array.isArray(payload.errors) ? payload.errors : [];
    weatherErrorMessage = cityErrors.length > 0
      ? cityErrors.map((item) => `${item.city}: ${item.message || "nije dostupno"}`).join(" | ")
      : "";
    const activeStillAvailable = weatherItems.some((item) => getWeatherCityKey(item.query || item.name || "") === getWeatherCityKey(weatherActiveCity));
    if (!activeStillAvailable && weatherItems[0]) {
      weatherActiveCity = weatherItems[0].query || weatherItems[0].name || weatherActiveCity;
      persistWeatherPreferences();
    }
    weatherStatus = "ready";
  } catch (error) {
    weatherStatus = "error";
    weatherErrorMessage = error?.message || "Vrijeme trenutno nije dostupno.";
  }
  renderWeatherWidget();
}

function scheduleWeatherRefresh() {
  if (weatherRefreshTimerId) {
    window.clearInterval(weatherRefreshTimerId);
  }
  weatherRefreshTimerId = window.setInterval(() => {
    if (state.user) {
      void refreshWeather();
    }
  }, WEATHER_REFRESH_INTERVAL_MS);
}

function setWeatherMenuOpen(isOpen, { closeOthers = true } = {}) {
  weatherMenuOpen = Boolean(isOpen && state.user);
  if (!weatherMenuOpen) {
    clearWeatherCitySuggestions({ render: false });
  }
  renderWeatherWidget();

  if (weatherMenuOpen) {
    void refreshWeather();
  }

  if (weatherMenuOpen && closeOthers) {
    setRemindersShortcutMenuOpen(false, { closeOthers: false });
    setTodoShortcutMenuOpen(false, { closeOthers: false });
    setNotificationsMenuOpen(false, { closeOthers: false });
    setTopbarHelpMenuOpen(false, { closeOthers: false });
    setUserMenuOpen(false);
  }
}

function addWeatherCity(cityName = "") {
  const city = normalizeWeatherCityName(cityName);
  if (!city) {
    weatherErrorMessage = "Upiši naziv grada.";
    renderWeatherWidget();
    return;
  }
  const exists = weatherCities.some((entry) => getWeatherCityKey(entry) === getWeatherCityKey(city));
  if (exists) {
    weatherActiveCity = weatherCities.find((entry) => getWeatherCityKey(entry) === getWeatherCityKey(city)) || city;
    persistWeatherPreferences();
    renderWeatherWidget();
    return;
  }
  if (weatherCities.length >= WEATHER_MAX_CITIES) {
    weatherErrorMessage = `Možeš pratiti najviše ${WEATHER_MAX_CITIES} gradova.`;
    renderWeatherWidget();
    return;
  }
  weatherCities = [...weatherCities, city];
  weatherActiveCity = city;
  weatherItems = weatherItems.filter((item) => weatherCities.some((entry) => getWeatherCityKey(entry) === getWeatherCityKey(item.query || item.name || "")));
  weatherErrorMessage = "";
  clearWeatherCitySuggestions({ render: false });
  persistWeatherPreferences();
  renderWeatherWidget();
  void refreshWeather({ force: true });
}

function removeWeatherCity(cityName = "") {
  const city = normalizeWeatherCityName(cityName);
  weatherCities = weatherCities.filter((entry) => getWeatherCityKey(entry) !== getWeatherCityKey(city));
  if (weatherCities.length === 0) {
    weatherCities = [...WEATHER_DEFAULT_CITIES];
  }
  if (!weatherCities.some((entry) => getWeatherCityKey(entry) === getWeatherCityKey(weatherActiveCity))) {
    weatherActiveCity = weatherCities[0] || "";
  }
  weatherItems = weatherItems.filter((item) => weatherCities.some((entry) => getWeatherCityKey(entry) === getWeatherCityKey(item.query || item.name || "")));
  persistWeatherPreferences();
  renderWeatherWidget();
  void refreshWeather({ force: true });
}

