function getDocumentsExplorerWorkOrderDocuments({ documentCategory = "" } = {}) {
  const categoryValues = (Array.isArray(documentCategory) ? documentCategory : [documentCategory])
    .map((value) => String(value || "").trim())
    .filter(Boolean);
  const categorySet = new Set(categoryValues);
  return (Array.isArray(state.documentsExplorer.workOrderDocuments)
    ? state.documentsExplorer.workOrderDocuments
    : [])
    .filter((documentItem) => (
      String(documentItem?.id || "").trim()
      && String(documentItem?.workOrderId || "").trim()
      && (!categorySet.size || categorySet.has(String(documentItem?.documentCategory || "").trim()))
    ));
}

function normalizeGeneratedSignatureFieldName(value = "") {
  return String(value || "").trim();
}

function parseGeneratedSignedFieldsJson(value = "") {
  if (!value || typeof value !== "string") {
    return [];
  }
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function getGeneratedDocumentSignatureFieldNames(documentItem = {}) {
  const metadata = parseSignatureFieldsJson(documentItem?.signatureFieldsJson || "");
  const fieldNames = metadata
    .map((entry) => normalizeGeneratedSignatureFieldName(entry?.fieldName || entry?.preferredField))
    .filter(Boolean);
  if (fieldNames.length > 0) {
    return Array.from(new Set(fieldNames));
  }
  const preferredField = normalizeGeneratedSignatureFieldName(documentItem?.preferredField);
  return preferredField ? [preferredField] : [];
}

function getGeneratedDocumentSignedFieldNames(documentItem = {}) {
  return new Set(parseGeneratedSignedFieldsJson(documentItem?.signedFieldsJson || "")
    .map((entry) => normalizeGeneratedSignatureFieldName(typeof entry === "string" ? entry : (entry?.fieldName || entry?.preferredField)))
    .filter(Boolean));
}

function hasGeneratedDocumentAnySignature(documentItem = {}) {
  return getGeneratedDocumentSignedFieldNames(documentItem).size > 0
    || /\bpotpisano\b/i.test(String(documentItem?.description || ""));
}

function isGeneratedDocumentSignatureFieldSigned(documentItem = {}, fieldName = "") {
  const normalizedFieldName = normalizeGeneratedSignatureFieldName(fieldName);
  const fieldNames = getGeneratedDocumentSignatureFieldNames(documentItem);
  const signedFields = getGeneratedDocumentSignedFieldNames(documentItem);
  if (normalizedFieldName && signedFields.has(normalizedFieldName)) {
    return true;
  }
  return fieldNames.length <= 1
    && normalizedFieldName
    && fieldNames.includes(normalizedFieldName)
    && signedFields.size === 0
    && /\bpotpisano\b/i.test(String(documentItem?.description || ""));
}

function isGeneratedDocumentSigned(documentItem = {}) {
  const fieldNames = getGeneratedDocumentSignatureFieldNames(documentItem);
  if (fieldNames.length > 0) {
    const signedFields = getGeneratedDocumentSignedFieldNames(documentItem);
    if (signedFields.size === 0) {
      return fieldNames.length === 1 && /\bpotpisano\b/i.test(String(documentItem?.description || ""));
    }
    return fieldNames.every((fieldName) => signedFields.has(fieldName));
  }
  return /\bpotpisano\b/i.test(String(documentItem?.description || ""));
}

function isGeneratedDocumentRejected(documentItem = {}) {
  return String(documentItem?.signatureReviewStatus || "").trim() === "rejected_with_comment";
}

function resolveGeneratedDocumentSignatureSummaryRole(entry = {}, documentItem = {}) {
  const rawRole = String(
    entry?.roleLabel
    || entry?.role
    || getSignatureRoleFallbackLabel(entry?.signatureFieldRole || ""),
  ).replace(/\s+/g, " ").trim();
  const normalizedRole = normalizeSignatureIdentityKey(rawRole);
  const baseRole = normalizedRole.includes("odgovorna") || normalizedRole.includes("nositelj")
    ? "Odgovorna osoba"
    : normalizedRole.includes("ispitiv")
      ? "Ispitivač"
      : rawRole;
  const serviceCode = normalizeDocumentTemplateSignatureServiceCode([
    documentItem?.fileName,
    documentItem?.documentType,
    documentItem?.templateTitle,
    documentItem?.description,
    entry?.roleLabel,
    entry?.role,
  ].filter(Boolean).join(" "));
  const alreadyHasServiceCode = serviceCode && new RegExp(`\\b${serviceCode}\\b`, "i").test(rawRole);
  return [baseRole, serviceCode && !alreadyHasServiceCode ? serviceCode : ""].filter(Boolean).join(" ");
}

function buildGeneratedDocumentSignatureSummary(documentItem = {}) {
  return parseSignatureFieldsJson(documentItem?.signatureFieldsJson || "")
    .map((entry) => {
      const role = resolveGeneratedDocumentSignatureSummaryRole(entry, documentItem);
      const name = String(
        entry?.name
        || entry?.signerName
        || (normalizeSignatureIdentityKey(entry?.label) !== normalizeSignatureIdentityKey(role) ? entry?.label : "")
        || entry?.signerEmail
        || entry?.oib
        || "",
      ).replace(/\s+/g, " ").trim();
      return [name, role].filter(Boolean).join(" - ");
    })
    .filter(Boolean)
    .join("; ");
}

function getWorkOrderDocumentLibraryContext(documentItem = {}, documentIndex = 0) {
  const linkedWorkOrder = findWorkOrderById(documentItem?.workOrderId || "");
  const company = getCompany(linkedWorkOrder?.companyId || "");
  const location = getLocation(linkedWorkOrder?.locationId || "");
  const serviceLabel = String(
    getWorkOrderServiceSummary(linkedWorkOrder)
    || linkedWorkOrder?.serviceLine
    || "",
  ).trim();
  const workOrderNumber = String(
    linkedWorkOrder?.workOrderNumber
    || documentItem?.workOrderNumber
    || `Zapisnik ${documentIndex + 1}`,
  ).trim();

  return {
    documentIndex,
    linkedWorkOrder,
    company,
    location,
    serviceLabel,
    workOrderNumber,
    sourceTarget: linkedWorkOrder
      ? { kind: "work-order", record: linkedWorkOrder }
      : null,
  };
}

function createSavedWorkOrderDocumentLibraryEntry(documentItem = {}, context = {}, idPrefix = "saved-work-order-document") {
  const fileName = getDocumentLibraryAttachmentFileName(documentItem)
    || `${slugifyValue(context.workOrderNumber || "dokument") || "dokument"}.pdf`;
  const categoryLabel = String(documentItem?.documentCategory || GENERATED_DOCUMENT_TEMPLATE_PDF_CATEGORY).trim()
    || GENERATED_DOCUMENT_TEMPLATE_PDF_CATEGORY;
  const description = String(documentItem?.description || `${categoryLabel} za RN ${context.workOrderNumber || ""}`).trim();
  const documentWithDescription = { ...documentItem, description };
  const hasSignature = hasGeneratedDocumentAnySignature(documentWithDescription);
  const isFullySigned = isGeneratedDocumentSigned(documentWithDescription);
  const signatureSummary = buildGeneratedDocumentSignatureSummary(documentItem);
  const fileKind = resolveDocumentLibraryAttachmentFileKind(documentItem);

  return createDocumentLibraryEntry({
    id: `${idPrefix}:${String(documentItem?.workOrderId || "")}:${String(documentItem?.id || "")}`,
    label: fileName,
    description,
    fileName,
    fileType: documentItem?.fileType || documentItem?.mimeType || (fileKind === "pdf" ? "application/pdf" : ""),
    fileSize: documentItem?.fileSize || 0,
    fileKind,
    updatedAt: documentItem?.updatedAt || documentItem?.createdAt || "",
    previewType: "work-order-document",
    workOrderId: documentItem?.workOrderId || "",
    documentId: documentItem?.id || "",
    documentCategory: categoryLabel,
    signed: hasSignature,
    metaParts: [
      categoryLabel,
      hasSignature ? (isFullySigned ? "Potpisano" : "Digitalni potpis u tijeku") : "",
      signatureSummary,
      documentItem?.actorLabel || "",
      formatFileSize(documentItem?.fileSize || 0),
    ].filter(Boolean),
    sourceTarget: context.sourceTarget ?? null,
    searchTerms: [
      context.workOrderNumber || "",
      context.serviceLabel || "",
      context.company?.name || "",
      context.location?.name || context.linkedWorkOrder?.locationName || "",
      categoryLabel,
    ],
  });
}

function dedupeDocumentLibraryAttachments(documents = []) {
  const seenKeys = new Set();
  const unique = [];

  (Array.isArray(documents) ? documents : []).forEach((document) => {
    const fileName = getDocumentLibraryAttachmentFileName(document);
    const href = getDocumentLibraryAttachmentHref(document);
    const key = [fileName, href].join("|");
    if (!fileName || !href || seenKeys.has(key)) {
      return;
    }
    seenKeys.add(key);
    unique.push(document);
  });

  return unique;
}

function finalizeDocumentLibraryFolder(folder = {}) {
  const documents = (Array.isArray(folder.documents) ? folder.documents : [])
    .filter(Boolean)
    .slice()
    .sort((left, right) => (
      right.updatedAtMs - left.updatedAtMs
      || String(left.label || "").localeCompare(String(right.label || ""), "hr", {
        sensitivity: "base",
        numeric: true,
      })
    ));

  if (documents.length === 0) {
    return null;
  }

  const pdfCount = documents.filter((entry) => entry.fileKind === "pdf").length;
  const searchTerms = [
    String(folder.label || "").trim(),
    String(folder.subtitle || "").trim(),
    ...(Array.isArray(folder.metaParts) ? folder.metaParts : []),
    ...(Array.isArray(folder.searchTerms) ? folder.searchTerms : []),
    ...documents.map((entry) => entry.searchBlob),
  ];
  const latestEntry = documents[0] ?? null;

  return {
    id: String(folder.id || crypto.randomUUID()).trim(),
    categoryId: normalizeDocumentLibraryCategory(folder.categoryId || "all"),
    categoryDefinition: getDocumentLibraryCategoryDefinition(folder.categoryId || "all"),
    label: String(folder.label || "Folder").trim() || "Folder",
    subtitle: String(folder.subtitle || "").trim(),
    metaParts: Array.from(new Set(
      (Array.isArray(folder.metaParts) ? folder.metaParts : [])
        .map((value) => String(value || "").trim())
        .filter(Boolean),
    )),
    sourceTarget: folder.sourceTarget ?? null,
    documents,
    documentCount: documents.length,
    pdfCount,
    latestTimestamp: latestEntry?.updatedAtMs || 0,
    latestLabel: latestEntry?.updatedLabel || "Bez datuma",
    searchBlob: normalizeLooseName(searchTerms.join(" ")),
  };
}

function buildDocumentLibraryAttachmentFolders(items = [], {
  categoryId = "all",
  getFolderLabel = () => "Folder",
  getFolderSubtitle = () => "",
  getFolderMetaParts = () => [],
  getFolderSearchTerms = () => [],
  getDocuments = (item) => item?.documents ?? [],
  getSourceTarget = () => null,
  mapDocument = () => ({}),
  buildExtraEntries = () => [],
} = {}) {
  return (Array.isArray(items) ? items : [])
    .map((item, itemIndex) => {
      const sourceTarget = getSourceTarget(item);
      const documents = dedupeDocumentLibraryAttachments(getDocuments(item))
        .map((document, documentIndex) => {
          const fileName = getDocumentLibraryAttachmentFileName(document);
          const href = getDocumentLibraryAttachmentHref(document);
          if (!fileName || !href) {
            return null;
          }

          const mapped = mapDocument(document, item, sourceTarget) ?? {};
          return createDocumentLibraryEntry({
            id: mapped.id || `${categoryId}:${String(item?.id || itemIndex)}:${String(document?.id || documentIndex)}:${fileName}`,
            label: mapped.label || fileName,
            description: mapped.description || "",
            fileName,
            fileType: mapped.fileType || document?.fileType || document?.mimeType || "",
            fileSize: mapped.fileSize ?? document?.fileSize ?? 0,
            href,
            fileKind: mapped.fileKind || resolveDocumentLibraryAttachmentFileKind(document),
            updatedAt: mapped.updatedAt || document?.updatedAt || item?.updatedAt || item?.createdAt || "",
            metaParts: mapped.metaParts || [],
            sourceTarget: mapped.sourceTarget || sourceTarget,
            previewType: mapped.previewType || "href",
            searchTerms: mapped.searchTerms || [],
          });
        })
        .filter(Boolean);

      const extraEntries = (Array.isArray(buildExtraEntries(item, sourceTarget)) ? buildExtraEntries(item, sourceTarget) : [])
        .filter(Boolean);

      return finalizeDocumentLibraryFolder({
        id: `${categoryId}:folder:${String(item?.id || itemIndex)}`,
        categoryId,
        label: getFolderLabel(item),
        subtitle: getFolderSubtitle(item),
        metaParts: getFolderMetaParts(item),
        searchTerms: getFolderSearchTerms(item),
        sourceTarget,
        documents: [...documents, ...extraEntries],
      });
    })
    .filter(Boolean);
}

function buildDocumentLibraryEntriesForItem(item, itemIndex = 0, {
  categoryId = "all",
  getDocuments = (entry) => entry?.documents ?? [],
  getSourceTarget = () => null,
  mapDocument = () => ({}),
  buildExtraEntries = () => [],
} = {}) {
  const sourceTarget = getSourceTarget(item);
  const documents = dedupeDocumentLibraryAttachments(getDocuments(item))
    .map((document, documentIndex) => {
      const fileName = getDocumentLibraryAttachmentFileName(document);
      const href = getDocumentLibraryAttachmentHref(document);
      if (!fileName || !href) {
        return null;
      }

      const mapped = mapDocument(document, item, sourceTarget) ?? {};
      return createDocumentLibraryEntry({
        id: mapped.id || `${categoryId}:${String(item?.id || itemIndex)}:${String(document?.id || documentIndex)}:${fileName}`,
        label: mapped.label || fileName,
        description: mapped.description || "",
        fileName,
        fileType: mapped.fileType || document?.fileType || document?.mimeType || "",
        fileSize: mapped.fileSize ?? document?.fileSize ?? 0,
        href,
        fileKind: mapped.fileKind || resolveDocumentLibraryAttachmentFileKind(document),
        updatedAt: mapped.updatedAt || document?.updatedAt || item?.updatedAt || item?.createdAt || "",
        metaParts: mapped.metaParts || [],
        sourceTarget: mapped.sourceTarget || sourceTarget,
        previewType: mapped.previewType || "href",
        searchTerms: mapped.searchTerms || [],
      });
    })
    .filter(Boolean);
  const extraEntries = (Array.isArray(buildExtraEntries(item, sourceTarget)) ? buildExtraEntries(item, sourceTarget) : [])
    .filter(Boolean);
  return [...documents, ...extraEntries];
}

function getDocumentRecordLibraryContext(record = {}, recordIndex = 0) {
  const extractedWorkOrderNumber = extractDocumentsExplorerWorkOrderNumber(record);
  const linkedWorkOrder = resolveDocumentsExplorerWorkOrder(record, extractedWorkOrderNumber);
  const company = getCompany(linkedWorkOrder?.companyId || record?.companyId || "");
  const location = getLocation(linkedWorkOrder?.locationId || record?.locationId || "");
  const object = getLocationObject(record?.objectId || "");
  const serviceLabel = String(
    getWorkOrderServiceSummary(linkedWorkOrder)
    || linkedWorkOrder?.serviceLine
    || extractDocumentsExplorerFieldValueByHints(record, DOCUMENTS_EXPLORER_SERVICE_KEY_HINTS)
    || "",
  ).trim();
  const workOrderNumber = String(
    linkedWorkOrder?.workOrderNumber
    || extractedWorkOrderNumber
    || `Zapisnik ${recordIndex + 1}`,
  ).trim();

  return {
    recordIndex,
    extractedWorkOrderNumber,
    linkedWorkOrder,
    company,
    location,
    object,
    serviceLabel,
    workOrderNumber,
    sourceTarget: linkedWorkOrder
      ? { kind: "work-order", record: linkedWorkOrder }
      : null,
  };
}

function createDocumentRecordLibraryEntryFromContext(record = {}, context = {}, idPrefix = "document-record") {
  return createDocumentLibraryRecordEntry({
    id: `${idPrefix}:${String(record?.id || context.recordIndex || 0)}`,
    label: String(record?.templateTitle || record?.documentType || "Zapisnik").trim() || "Zapisnik",
    description: [
      record?.inspectionDate ? `Ispitivanje ${formatCompactDate(record.inspectionDate)}` : "",
      record?.issuedDate ? `Izdano ${formatCompactDate(record.issuedDate)}` : "",
      context.object?.name || record?.objectName || "",
      record?.createdByLabel || "",
    ].filter(Boolean).join(" · "),
    updatedAt: record?.updatedAt || record?.issuedDate || record?.inspectionDate || record?.createdAt || "",
    sourceTarget: context.sourceTarget ?? null,
    searchTerms: [
      record?.templateTitle || "",
      record?.documentType || "",
      context.workOrderNumber || "",
      context.serviceLabel || "",
      context.company?.name || "",
      context.object?.name || record?.objectName || "",
    ],
  });
}

function buildDocumentRecordLibraryFolders(records = state.documentsExplorer.records) {
  const buckets = new Map();

  (Array.isArray(records) ? records : []).forEach((record, recordIndex) => {
    const context = getDocumentRecordLibraryContext(record, recordIndex);
    const folderKey = context.linkedWorkOrder?.id
      ? `document-records:work-order:${context.linkedWorkOrder.id}`
      : `document-records:record:${String(record?.id || recordIndex)}`;

    if (!buckets.has(folderKey)) {
      buckets.set(folderKey, {
        id: folderKey,
        categoryId: "document-records",
        label: context.workOrderNumber || "Zapisnik",
        subtitle: [
          context.company?.name || context.linkedWorkOrder?.companyName || "",
          createCompactLocationLabel(context.location?.name || context.linkedWorkOrder?.locationName || ""),
          context.object?.name || record?.objectName || "",
          context.serviceLabel,
        ].filter(Boolean).join(" · "),
        metaParts: [
          context.company?.name || "",
          context.object?.name || record?.objectName || "",
          context.serviceLabel || "",
        ].filter(Boolean),
        searchTerms: [
          context.company?.name || "",
          context.location?.name || context.linkedWorkOrder?.locationName || "",
          context.object?.name || record?.objectName || "",
          context.serviceLabel,
        ],
        sourceTarget: context.sourceTarget,
        documents: [],
      });
    }

    // Zapisnički record ostaje interan za periodiku i lookup; Documents prikazuje samo stvarno spremljene datoteke.
  });

  getDocumentsExplorerWorkOrderDocuments({ documentCategory: SIGNATURE_PDF_DOCUMENT_CATEGORIES })
    .forEach((documentItem, documentIndex) => {
      const context = getWorkOrderDocumentLibraryContext(documentItem, documentIndex);
      const folderKey = context.linkedWorkOrder?.id
        ? `document-records:work-order:${context.linkedWorkOrder.id}`
        : `document-records:document:${String(documentItem?.id || documentIndex)}`;

      if (!buckets.has(folderKey)) {
        buckets.set(folderKey, {
          id: folderKey,
          categoryId: "document-records",
          label: context.workOrderNumber || "Zapisnik",
          subtitle: [
            context.company?.name || context.linkedWorkOrder?.companyName || "",
            createCompactLocationLabel(context.location?.name || context.linkedWorkOrder?.locationName || ""),
            context.serviceLabel,
          ].filter(Boolean).join(" · "),
          metaParts: [
            context.company?.name || "",
            context.serviceLabel || "",
          ].filter(Boolean),
          searchTerms: [
            context.company?.name || "",
            context.location?.name || context.linkedWorkOrder?.locationName || "",
            context.serviceLabel,
          ],
          sourceTarget: context.sourceTarget,
          documents: [],
        });
      }

      const bucket = buckets.get(folderKey);
      if (context.sourceTarget && !bucket.sourceTarget) {
        bucket.sourceTarget = context.sourceTarget;
      }
      bucket.documents.push(
        createSavedWorkOrderDocumentLibraryEntry(documentItem, context, "document-record-pdf"),
      );
    });

  return [...buckets.values()]
    .map((folder) => finalizeDocumentLibraryFolder(folder))
    .filter(Boolean);
}

function buildWorkOrderDocumentLibraryFolders(records = state.documentsExplorer.records) {
  const buckets = new Map();

  const ensureWorkOrderFolder = (workOrder = {}, fallbackRecord = {}, recordIndex = 0) => {
    const company = getCompany(workOrder?.companyId || fallbackRecord?.companyId || "");
    const location = getLocation(workOrder?.locationId || fallbackRecord?.locationId || "");
    const serviceLabel = String(
      getWorkOrderServiceSummary(workOrder)
      || workOrder?.serviceLine
      || "",
    ).trim();
    const workOrderNumber = String(workOrder?.workOrderNumber || fallbackRecord?.workOrderNumber || "").trim();
    const folderKey = workOrder?.id
      ? `work-orders:work-order:${workOrder.id}`
      : `work-orders:record:${String(fallbackRecord?.id || recordIndex)}`;

    if (!buckets.has(folderKey)) {
      buckets.set(folderKey, {
        id: folderKey,
        categoryId: "work-orders",
        label: workOrderNumber || "Radni nalog",
        subtitle: [
          company?.name || workOrder?.companyName || "",
          createCompactLocationLabel(location?.name || workOrder?.locationName || ""),
          serviceLabel,
        ].filter(Boolean).join(" · "),
        metaParts: [
          company?.name || "",
          serviceLabel || "",
        ].filter(Boolean),
        searchTerms: [
          workOrderNumber || "",
          company?.name || "",
          location?.name || workOrder?.locationName || "",
          serviceLabel,
        ],
        sourceTarget: workOrder?.id ? { kind: "work-order", record: workOrder } : null,
        documents: [],
      });
    }

    return buckets.get(folderKey);
  };

  (Array.isArray(records) ? records : []).forEach((record, recordIndex) => {
    const context = getDocumentRecordLibraryContext(record, recordIndex);
    const folder = ensureWorkOrderFolder(context.linkedWorkOrder, record, recordIndex);
    if (context.sourceTarget && !folder.sourceTarget) {
      folder.sourceTarget = context.sourceTarget;
    }
    folder.documents.push(
      createDocumentRecordLibraryEntryFromContext(record, context, "work-order-record"),
    );
  });

  getDocumentsExplorerWorkOrderDocuments({ documentCategory: SIGNATURE_PDF_DOCUMENT_CATEGORIES })
    .forEach((documentItem, documentIndex) => {
      const context = getWorkOrderDocumentLibraryContext(documentItem, documentIndex);
      const folder = ensureWorkOrderFolder(context.linkedWorkOrder, {
        id: documentItem?.id || documentIndex,
        workOrderNumber: context.workOrderNumber,
      }, documentIndex);
      if (context.sourceTarget && !folder.sourceTarget) {
        folder.sourceTarget = context.sourceTarget;
      }
      folder.documents.push(
        createSavedWorkOrderDocumentLibraryEntry(documentItem, context, "work-order-saved-report"),
      );
    });

  sortWorkOrders(state.workOrders ?? []).forEach((workOrder, index) => {
    if (!workOrder?.id) {
      return;
    }
    const folder = ensureWorkOrderFolder(workOrder, {}, index);
    const workOrderNumber = workOrder.workOrderNumber || `RN ${index + 1}`;
    const company = getCompany(workOrder.companyId);
    const location = getLocation(workOrder.locationId);
    folder.documents.push(createDocumentLibraryGeneratedPdfEntry({
      id: `work-orders:pdf:${workOrder.id}`,
      label: `${workOrderNumber} PDF`,
      description: "Automatski PDF radnog naloga. Kod preuzimanja se ponovno spremi u Documents.",
      exportPath: `/work-orders/${encodeURIComponent(String(workOrder.id))}/pdf`,
      fileName: `${slugifyValue(workOrderNumber || "radni-nalog") || "radni-nalog"}.pdf`,
      updatedAt: workOrder.updatedAt || workOrder.createdAt || workOrder.openedDate || "",
      sourceTarget: { kind: "work-order", record: workOrder },
      searchTerms: [
        workOrderNumber,
        company?.name || "",
        location?.name || workOrder.locationName || "",
        getWorkOrderServiceSummary(workOrder),
      ],
    }));
  });

  return [...buckets.values()]
    .map((folder) => finalizeDocumentLibraryFolder(folder))
    .filter(Boolean);
}

function getCompanyDocumentFolder(map, {
  company = null,
  companyId = "",
  companyName = "",
  folderKey = "documents",
  folderLabel = "Dokumenti",
  subtitle = "",
  metaParts = [],
  searchTerms = [],
} = {}) {
  const resolvedCompanyId = String(company?.id || companyId || "").trim();
  const resolvedCompanyName = String(company?.name || companyName || "Bez tvrtke").trim() || "Bez tvrtke";
  const key = `companies:${resolvedCompanyId || slugifyValue(resolvedCompanyName) || "bez-tvrtke"}:${folderKey}`;

  if (!map.has(key)) {
    map.set(key, {
      id: key,
      categoryId: "companies",
      label: `${resolvedCompanyName} / ${folderLabel}`,
      subtitle: subtitle || "Tvrtke",
      metaParts: [
        resolvedCompanyName,
        ...metaParts,
      ].filter(Boolean),
      searchTerms: [
        resolvedCompanyName,
        company?.oib || "",
        company?.headquarters || "",
        ...searchTerms,
      ],
      sourceTarget: company ? { kind: "company", record: company } : null,
      documents: [],
    });
  }

  return map.get(key);
}

function buildCompanyDocumentLibraryFolders(records = state.documentsExplorer.records) {
  const folders = new Map();
  const sortedCompanies = [...(state.companies ?? [])].sort((left, right) => String(left?.name || "")
    .localeCompare(String(right?.name || ""), "hr", { sensitivity: "base", numeric: true }));
  const companyById = new Map(sortedCompanies.map((company) => [String(company?.id || ""), company]));

  const ensureCompanyFolder = ({
    company = null,
    companyId = "",
    companyName = "",
    searchTerms = [],
  } = {}) => {
    const resolvedCompanyId = String(company?.id || companyId || "").trim();
    const resolvedCompanyName = String(company?.name || companyName || "Bez tvrtke").trim() || "Bez tvrtke";
    const key = `companies:${resolvedCompanyId || slugifyValue(resolvedCompanyName) || "bez-tvrtke"}:overview`;
    if (!folders.has(key)) {
      folders.set(key, {
        id: key,
        categoryId: "companies",
        label: resolvedCompanyName,
        subtitle: "Temeljna dokumentacija, lokacije i RN dokumenti",
        metaParts: [resolvedCompanyName],
        searchTerms: [
          resolvedCompanyName,
          company?.oib || "",
          company?.headquarters || "",
          ...searchTerms,
        ],
        sourceTarget: company ? { kind: "company", record: company } : null,
        documents: [],
      });
    }
    return folders.get(key);
  };

  const addCompanyEntry = (companyInfo = {}, entry = null) => {
    if (!entry) {
      return;
    }
    const company = companyInfo.company
      || companyById.get(String(companyInfo.companyId || ""))
      || null;
    const folder = ensureCompanyFolder({
      company,
      companyId: companyInfo.companyId,
      companyName: companyInfo.companyName,
      searchTerms: companyInfo.searchTerms,
    });
    folder.documents.push(entry);
  };

  const createFoundationEntry = ({
    company = null,
    companyId = "",
    companyName = "",
    sourceTarget = null,
    document = {},
    item = {},
    label = "Temeljni dokument",
    typeLabel = "Temeljna dokumentacija",
    idPrefix = "foundation",
    index = 0,
  } = {}) => {
    const fileName = getDocumentLibraryAttachmentFileName(document);
    const href = getDocumentLibraryAttachmentHref(document);
    if (!fileName || !href) {
      return null;
    }
    const itemTitle = String(item?.title || item?.assessmentNumber || item?.referenceCode || item?.rulebookType || label).trim();
    return createDocumentLibraryEntry({
      id: `companies:${idPrefix}:${String(item?.id || index)}:${String(document?.id || index)}:${fileName}`,
      label: `Temeljna dokumentacija / ${typeLabel} / ${fileName}`,
      description: itemTitle,
      fileName,
      fileType: document?.fileType || document?.mimeType || "",
      fileSize: document?.fileSize || 0,
      href,
      fileKind: resolveDocumentLibraryAttachmentFileKind(document),
      updatedAt: document?.updatedAt || item?.updatedAt || item?.createdAt || item?.assessmentDate || item?.effectiveFrom || "",
      previewType: "href",
      companyPath: {
        type: "foundation",
        sectionKey: "foundation",
        sectionLabel: "Temeljna dokumentacija",
        typeLabel,
        fileLabel: fileName,
      },
      metaParts: [
        "Temeljna dokumentacija",
        typeLabel,
        formatFileSize(document?.fileSize || 0),
      ].filter(Boolean),
      sourceTarget,
      searchTerms: [
        company?.name || companyName || "",
        itemTitle,
        typeLabel,
        item?.status || "",
      ],
    });
  };

  (Array.isArray(records) ? records : []).forEach((record, recordIndex) => {
    const context = getDocumentRecordLibraryContext(record, recordIndex);
    const companyId = context.linkedWorkOrder?.companyId || record?.companyId || "";
    const company = context.company || companyById.get(String(companyId || "")) || null;
    const locationLabel = createCompactLocationLabel(context.location?.name || context.linkedWorkOrder?.locationName || record?.locationName || "");
    const locationKey = normalizeDocumentsExplorerKey(context.location?.id || context.linkedWorkOrder?.locationId || record?.locationId || locationLabel)
      || "bez-lokacije";
    const workOrderLabel = context.workOrderNumber ? `RN ${context.workOrderNumber}` : "Bez RN";
    const workOrderKey = normalizeDocumentsExplorerKey(context.linkedWorkOrder?.id || record?.workOrderId || context.workOrderNumber || record?.id)
      || normalizeDocumentsExplorerKey(workOrderLabel)
      || "bez-rn";
    const recordEntry = createDocumentRecordLibraryEntryFromContext(record, context, "company-record");
    addCompanyEntry({
      company,
      companyId,
      companyName: context.linkedWorkOrder?.companyName || record?.companyName || "",
      searchTerms: [context.workOrderNumber || "", context.serviceLabel || ""],
    }, {
      ...recordEntry,
      label: [
        locationLabel || "Bez lokacije",
        context.workOrderNumber ? `RN ${context.workOrderNumber}` : "Bez RN",
        recordEntry.label,
      ].filter(Boolean).join(" / "),
      description: [
        context.serviceLabel || "",
        recordEntry.description || "",
      ].filter(Boolean).join(" · "),
      metaParts: [
        "Zapisnik",
        locationLabel || "",
        context.workOrderNumber ? `RN ${context.workOrderNumber}` : "",
        ...recordEntry.metaParts,
      ].filter(Boolean),
      companyPath: {
        type: "work-order",
        locationKey,
        locationLabel: locationLabel || "Bez lokacije",
        workOrderKey,
        workOrderLabel,
        fileLabel: recordEntry.label,
      },
      searchBlob: normalizeLooseName([
        recordEntry.searchBlob,
        locationLabel,
        context.workOrderNumber,
        context.serviceLabel,
      ].join(" ")),
    });
  });

  getDocumentsExplorerWorkOrderDocuments()
    .forEach((documentItem, documentIndex) => {
      const context = getWorkOrderDocumentLibraryContext(documentItem, documentIndex);
      const workOrder = context.linkedWorkOrder || {};
      const companyId = workOrder.companyId || documentItem.companyId || "";
      const company = context.company || companyById.get(String(companyId || "")) || null;
      const locationLabel = createCompactLocationLabel(context.location?.name || workOrder.locationName || documentItem.locationName || "");
      const locationKey = normalizeDocumentsExplorerKey(context.location?.id || workOrder.locationId || documentItem.locationId || locationLabel)
        || "bez-lokacije";
      const workOrderLabel = context.workOrderNumber ? `RN ${context.workOrderNumber}` : "Bez RN";
      const workOrderKey = normalizeDocumentsExplorerKey(workOrder.id || documentItem.workOrderId || context.workOrderNumber || documentItem.id)
        || normalizeDocumentsExplorerKey(workOrderLabel)
        || "bez-rn";
      const baseEntry = createSavedWorkOrderDocumentLibraryEntry(documentItem, context, "company-work-order-document");
      addCompanyEntry({
        company,
        companyId,
        companyName: workOrder.companyName || documentItem.companyName || "",
        searchTerms: [context.workOrderNumber || "", context.serviceLabel || ""],
      }, {
        ...baseEntry,
        label: [
          locationLabel || "Bez lokacije",
          context.workOrderNumber ? `RN ${context.workOrderNumber}` : "Bez RN",
          baseEntry.label,
        ].filter(Boolean).join(" / "),
        description: [
          documentItem?.documentCategory || "",
          context.serviceLabel || "",
          baseEntry.description || "",
        ].filter(Boolean).join(" · "),
        metaParts: [
          "RN dokument",
          locationLabel || "",
          context.workOrderNumber ? `RN ${context.workOrderNumber}` : "",
          ...baseEntry.metaParts,
        ].filter(Boolean),
        companyPath: {
          type: "work-order",
          locationKey,
          locationLabel: locationLabel || "Bez lokacije",
          workOrderKey,
          workOrderLabel,
          fileLabel: baseEntry.label,
        },
        searchBlob: normalizeLooseName([
          baseEntry.searchBlob,
          locationLabel,
          context.workOrderNumber,
          context.serviceLabel,
          documentItem?.documentCategory || "",
        ].join(" ")),
      });
    });

  sortRiskAssessments(state.riskAssessments ?? []).forEach((item, itemIndex) => {
    const companyId = String(item?.companyId || "").trim();
    const company = companyById.get(companyId) || null;
    const documents = [
      ...(Array.isArray(item?.attachments) ? item.attachments : []),
      item?.employerData?.znrAuthorizationDocument,
      item?.reportTemplate?.referenceDocument,
    ].filter(Boolean);
    documents.forEach((document, documentIndex) => {
      addCompanyEntry({ company, companyId, companyName: item?.employerData?.fullName || "" }, createFoundationEntry({
        company,
        companyId,
        companyName: item?.employerData?.fullName || "",
        sourceTarget: { kind: "risk-assessment", record: item },
        document,
        item,
        typeLabel: "Procjena rizika",
        idPrefix: "risk-assessment",
        index: `${itemIndex}-${documentIndex}`,
      }));
    });
  });

  sortRulebooks(state.rulebooks ?? []).forEach((item, itemIndex) => {
    const companyId = String(item?.companyId || "").trim();
    const company = companyById.get(companyId) || null;
    (Array.isArray(item?.documents) ? item.documents : []).forEach((document, documentIndex) => {
      addCompanyEntry({ company, companyId, companyName: item?.owner || "" }, createFoundationEntry({
        company,
        companyId,
        companyName: item?.owner || "",
        sourceTarget: { kind: "rulebook", record: item },
        document,
        item,
        typeLabel: "Pravilnik",
        idPrefix: "rulebook",
        index: `${itemIndex}-${documentIndex}`,
      }));
    });
  });

  sortSafetyAuthorizations(state.safetyAuthorizations ?? []).forEach((item, itemIndex) => {
    const companyId = String(item?.companyId || "").trim();
    const company = companyById.get(companyId) || null;
    (Array.isArray(item?.documents) ? item.documents : []).forEach((document, documentIndex) => {
      addCompanyEntry({ company, companyId, companyName: item?.companyName || "" }, createFoundationEntry({
        company,
        companyId,
        companyName: item?.companyName || "",
        sourceTarget: { kind: "safety-authorization", record: item },
        document,
        item,
        typeLabel: "Ovlaštenje",
        idPrefix: "safety-authorization",
        index: `${itemIndex}-${documentIndex}`,
      }));
    });
  });

  return [...folders.values()]
    .map((folder) => finalizeDocumentLibraryFolder({
      ...folder,
      metaParts: [
        `${folder.documents.filter((entry) => String(entry?.label || "").startsWith("Temeljna dokumentacija")).length} temeljnih`,
        `${folder.documents.filter((entry) => String(entry?.label || "").includes(" / RN ")).length} RN dok.`,
      ],
    }))
    .filter(Boolean);
}

