      categoryId: "service-catalog",
      getFolderLabel: (item) => item?.name || item?.serviceCode || "Usluga",
      getFolderSubtitle: (item) => [
        item?.serviceCode || "",
        getServiceCatalogTypeLabel(item?.serviceType || (item?.isTraining ? "znr" : "inspection")),
      ].filter(Boolean).join(" · "),
