async function savePeriodicsVisualSettings(options = {}) {
  const successMessage = typeof options.successMessage === "string" && options.successMessage.trim()
    ? options.successMessage.trim()
    : "Postavke su spremljene.";

  if (!getCanManageSettings()) {
    if (settingsPeriodicsVisualFeedback) {
      settingsPeriodicsVisualFeedback.textContent = "Nemate pravo spremati postavke.";
    }
    return false;
  }

  const criticalDays = normalizeNotificationDayValue(
    settingsPeriodicsCriticalDaysInput?.value,
    DEFAULT_PERIODICS_VISUAL_SETTINGS.criticalDays,
    { min: 1, max: 120 },
  );
  const warningDaysRaw = normalizeNotificationDayValue(
    settingsPeriodicsWarningDaysInput?.value,
    DEFAULT_PERIODICS_VISUAL_SETTINGS.warningDays,
    { min: 1, max: 365 },
  );
  const warningDays = Math.max(criticalDays, warningDaysRaw);
  const workOrderDefaultDueDays = normalizeOptionalDayValue(
    settingsWorkOrderDefaultDueDaysInput?.value,
    { min: 0, max: 365 },
  );
  const workOrderFieldSharePercent = normalizePercentValue(
    settingsWorkOrderFieldShareInput?.value,
    DEFAULT_PERIODICS_VISUAL_SETTINGS.workOrderFieldSharePercent,
  );
  const workOrderCompletionSharePercent = 100 - workOrderFieldSharePercent;
  const workOrderServicePointFactors = normalizeWorkOrderServicePointFactors(
    collectSettingsWorkOrderServicePointFactors(),
  );

  if (settingsPeriodicsCriticalDaysInput) {
    settingsPeriodicsCriticalDaysInput.value = String(criticalDays);
  }
  if (settingsPeriodicsWarningDaysInput) {
    settingsPeriodicsWarningDaysInput.value = String(warningDays);
  }
  if (settingsWorkOrderDefaultDueDaysInput) {
    settingsWorkOrderDefaultDueDaysInput.value = workOrderDefaultDueDays;
  }
  if (settingsWorkOrderFieldShareInput) {
    settingsWorkOrderFieldShareInput.value = String(workOrderFieldSharePercent);
  }
  if (settingsWorkOrderCompletionShareInput) {
    settingsWorkOrderCompletionShareInput.value = String(workOrderCompletionSharePercent);
  }
  renderSettingsWorkOrderPointsPreview({
    workOrderFieldSharePercent,
    workOrderCompletionSharePercent,
    workOrderServicePointFactors,
  });

  const success = await runMutation(() => apiRequest("/periodics/visual-settings", {
    method: "POST",
    body: {
      criticalDays,
      warningDays,
      workOrderDefaultDueDays,
      workOrderFieldSharePercent,
      workOrderCompletionSharePercent,
      workOrderServicePointFactors,
    },
  }), settingsPeriodicsVisualFeedback);

  if (success) {
    if (settingsPeriodicsVisualFeedback) {
      settingsPeriodicsVisualFeedback.textContent = successMessage;
    }
    if (settingsWorkOrderPointsFeedback) {
      settingsWorkOrderPointsFeedback.textContent = successMessage;
    }
  }

  return success;
}

async function saveProfilePushNotificationPreferences(options = {}) {
  const successMessage = typeof options.successMessage === "string" && options.successMessage.trim()
    ? options.successMessage.trim()
    : "Push postavke su spremljene.";

  if (!state.user) {
    setInlineMessage(settingsPushPreferencesFeedback, "Prijavite se prije spremanja push postavki.");
    return false;
  }

  const preferences = collectSettingsPushPreferences();
  if (settingsPushPreferencesSaveButton) {
    settingsPushPreferencesSaveButton.disabled = true;
  }

  const success = await runMutation(() => apiRequest("/auth/profile/push-notifications", {
    method: "PATCH",
    body: {
      preferences,
    },
  }), settingsPushPreferencesFeedback);

  if (settingsPushPreferencesSaveButton) {
    settingsPushPreferencesSaveButton.disabled = false;
  }

  if (success) {
    state.user = {
      ...(state.user ?? {}),
      pushNotificationPreferences: preferences,
    };
    const currentUserIndex = state.users.findIndex((item) => String(item.id) === String(state.user?.id));
    if (currentUserIndex >= 0) {
      state.users[currentUserIndex] = {
        ...state.users[currentUserIndex],
        pushNotificationPreferences: preferences,
      };
    }
    renderSettingsPushPreferences();
    setInlineMessage(settingsPushPreferencesFeedback, successMessage, "success");
  }

  return success;
}

async function saveSettingsIsznrApiSettings(options = {}) {
  const successMessage = typeof options.successMessage === "string" && options.successMessage.trim()
    ? options.successMessage.trim()
    : "ISZNR API postavke su spremljene.";

  if (!getCanManageSettings()) {
    setInlineMessage(settingsIsznrApiFeedback, "Nemate pravo spremati ISZNR API postavke.");
    return false;
  }

  if (!state.activeOrganizationId) {
    setInlineMessage(settingsIsznrApiFeedback, "Odaberi organizaciju prije spremanja ISZNR postavki.");
    return false;
  }

  if (settingsIsznrApiSaveButton) {
    settingsIsznrApiSaveButton.disabled = true;
  }

  const success = await runMutation(() => apiRequest("/isznr/api-settings", {
    method: "POST",
    body: collectSettingsIsznrApiPayload(),
  }), settingsIsznrApiFeedback, {
    onSuccessPayload: (payload) => {
      if (payload?.isznrApiSettings) {
        state.isznrApiSettings = normalizeIsznrApiSettings(payload.isznrApiSettings);
      }
    },
  });

  if (settingsIsznrApiSaveButton) {
    settingsIsznrApiSaveButton.disabled = !getCanManageSettings();
  }

  if (success) {
    if (settingsIsznrApiPasswordInput) {
      settingsIsznrApiPasswordInput.value = "";
      settingsIsznrApiPasswordInput.type = "password";
      settingsIsznrApiPasswordInput.dataset.revealedStoredPassword = "false";
    }
    if (settingsIsznrApiClearPasswordInput) {
      settingsIsznrApiClearPasswordInput.checked = false;
    }
    renderSettingsIsznrApiSettings();
    setInlineMessage(settingsIsznrApiFeedback, successMessage, "success");
  }

  return success;
}

async function testSettingsIsznrApiConnection() {
  if (!getCanManageSettings()) {
    setInlineMessage(settingsIsznrApiFeedback, "Nemate pravo testirati ISZNR API postavke.");
    return false;
  }

  if (!state.activeOrganizationId) {
    setInlineMessage(settingsIsznrApiFeedback, "Odaberi organizaciju prije testiranja ISZNR veze.");
    return false;
  }

  if (settingsIsznrApiTestButton) {
    settingsIsznrApiTestButton.disabled = true;
  }
  if (settingsIsznrApiSaveButton) {
    settingsIsznrApiSaveButton.disabled = true;
  }
  renderSettingsIsznrApiResourceStatus(null);
  setInlineMessage(settingsIsznrApiFeedback, "Testiram ISZNR vezu...", "success");

  try {
    const result = await apiRequestWithTransientRetry("/isznr/test-connection", {
      method: "POST",
      body: collectSettingsIsznrApiPayload(),
    }, {
      maxAttempts: 3,
      delays: [1200, 2500],
      onRetry: () => {
        setInlineMessage(settingsIsznrApiFeedback, "ISZNR test veze se ponavlja nakon kratkog prekida...", "success");
      },
    });
    const message = result?.message || "ISZNR API veza je dostupna.";
    setInlineMessage(settingsIsznrApiFeedback, message, result?.ok === false ? "error" : "success");
    renderSettingsIsznrApiResourceStatus(result);
    return Boolean(result?.ok);
  } catch (error) {
    setInlineMessage(settingsIsznrApiFeedback, error.message || "ISZNR test veze nije uspio.");
    renderSettingsIsznrApiResourceStatus(null);
    return false;
  } finally {
    if (settingsIsznrApiTestButton) {
      settingsIsznrApiTestButton.disabled = !getCanManageSettings();
    }
    if (settingsIsznrApiSaveButton) {
      settingsIsznrApiSaveButton.disabled = !getCanManageSettings();
    }
  }
}

