const SIGNATURE_BRIDGE_KEY_STORAGE_KEY = "safeNexus.signatureBridge.key";
const LOCAL_SIGNATURE_BRIDGE_BASE_URLS = ["http://127.0.0.1:9137", "http://localhost:9137"];

function createSignatureBridgeKey() {
  const bytes = new Uint8Array(18);
  if (window.crypto?.getRandomValues) {
    window.crypto.getRandomValues(bytes);
  } else {
    for (let index = 0; index < bytes.length; index += 1) {
      bytes[index] = Math.floor(Math.random() * 256);
    }
  }
  return `sn-${Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("")}`;
}

function getSignatureBridgeKey() {
  try {
    const existing = localStorage.getItem(SIGNATURE_BRIDGE_KEY_STORAGE_KEY);
    if (existing && existing.trim()) {
      return existing.trim().toLowerCase();
    }
    const created = createSignatureBridgeKey();
    localStorage.setItem(SIGNATURE_BRIDGE_KEY_STORAGE_KEY, created);
    return created;
  } catch {
    return createSignatureBridgeKey();
  }
}

async function postLocalSignatureBridgeJob(payload = {}) {
  let lastError = null;
  for (const baseUrl of LOCAL_SIGNATURE_BRIDGE_BASE_URLS) {
    try {
      const response = await fetch(`${baseUrl}/sign`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          token: payload.token || "",
          apiBase: payload.apiBase || window.location.origin,
          origin: window.location.origin,
        }),
      });

      const result = await response.json().catch(() => ({}));
      if (!response.ok || result.ok === false) {
        throw new Error(result.error || result.message || "Lokalni signer nije uspio obraditi paket.");
      }
      return result;
    } catch (error) {
      lastError = error;
    }
  }

  throw lastError || new Error("Lokalni signer nije dostupan na 127.0.0.1:9137.");
}

async function pingLocalSignatureBridge() {
  for (const baseUrl of LOCAL_SIGNATURE_BRIDGE_BASE_URLS) {
    try {
      const response = await fetch(`${baseUrl}/health`, {
        method: "GET",
        cache: "no-store",
      });
      if (response.ok) {
        return true;
      }
    } catch {
      // Try the next localhost alias.
    }
  }
  return false;
}

async function pairLocalSignatureBridgeDirect(bridgeKey = getSignatureBridgeKey()) {
  let lastError = null;
  for (const baseUrl of LOCAL_SIGNATURE_BRIDGE_BASE_URLS) {
    try {
      const response = await fetch(`${baseUrl}/pair`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          bridgeKey,
          apiBase: window.location.origin,
        }),
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok || result.ok === false) {
        throw new Error(result.error || result.message || "Lokalno povezivanje nije uspjelo.");
      }
      return result;
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError || new Error("Lokalni signer nije dostupan za automatsko povezivanje.");
}

function openExternalProtocolWithoutNavigation(url = "") {
  if (!url || !document.body) {
    return false;
  }

  const frame = document.createElement("iframe");
  frame.setAttribute("aria-hidden", "true");
  frame.tabIndex = -1;
  frame.style.position = "fixed";
  frame.style.left = "-10px";
  frame.style.top = "-10px";
  frame.style.width = "1px";
  frame.style.height = "1px";
  frame.style.opacity = "0";
  frame.style.pointerEvents = "none";
  frame.style.border = "0";
  frame.src = url;
  document.body.append(frame);

  window.setTimeout(() => {
    frame.remove();
  }, 5000);

  return true;
}

function openSignatureBridgePairProtocol(bridgeKey = getSignatureBridgeKey()) {
  const protocolUrl = `safenexus-signer://pair?bridgeKey=${encodeURIComponent(bridgeKey)}&api=${encodeURIComponent(window.location.origin)}`;
  if (!openExternalProtocolWithoutNavigation(protocolUrl)) {
    window.open(protocolUrl, "_blank", "noopener,noreferrer,width=1,height=1");
  }
}

async function pairLocalSignatureBridge() {
  const bridgeKey = getSignatureBridgeKey();
  signaturesCopyBridgeUrlButton.disabled = true;
  signaturesCopyBridgeUrlButton.classList.add("is-loading");
  setSignaturesBridgeStatus("Povezujem lokalni signer s DigitalOcean redom za potpis...", "loading");
  try {
    const result = await pairLocalSignatureBridgeDirect(bridgeKey);
    setSignaturesBridgeStatus(result.message || "Lokalni signer je povezan i spreman za potpis.", "ready");
  } catch {
    openSignatureBridgePairProtocol(bridgeKey);
    setSignaturesBridgeStatus("Otvaram lokalni signer za automatsko povezivanje bez napuštanja stranice. Ako Windows pita, potvrdi otvaranje aplikacije.", "warning");
  } finally {
    signaturesCopyBridgeUrlButton.disabled = false;
    signaturesCopyBridgeUrlButton.classList.remove("is-loading");
  }
}

function waitForLocalSignatureBridge(ms = 2500) {
  return new Promise((resolve) => {
    window.setTimeout(resolve, ms);
  });
}

async function openLocalSignatureBridge(entriesOverride = null, options = {}) {
  const pendingEntries = Array.isArray(entriesOverride) && entriesOverride.length > 0
    ? entriesOverride
    : getPendingSignatureBridgeEntries();
  if (pendingEntries.length === 0) {
    setSignaturesBridgeStatus("Nema nepotpisanih PDF dokumenata za potpis.", "warning");
    return;
  }

  signaturesOpenLocalSignerButton.disabled = true;
  signaturesOpenLocalSignerButton.classList.add("is-loading");
  if (signaturesInstallSignerButton) {
    signaturesInstallSignerButton.hidden = true;
  }
  setSignaturesBridgeStatus("Provjeravam PDF Signer...", "loading");

  try {
    await runSignatureDebugPing({ showStatus: false });
    setSignaturesBridgeStatus("Pripremam dokumente za potpis...", "loading");

    const { payload, documents } = await createSignatureBridgeJobForPendingEntries(pendingEntries, options);

    setSignaturesBridgeStatus("Otvaram lokalni PDF Signer...", "loading");
    let keepPollingSignatureProgress = true;
    const progressPolling = pollSignatureBridgeJobProgress(payload.token || "", {
      total: documents.length || pendingEntries.length || 1,
      isActive: () => keepPollingSignatureProgress,
    });
    let signResult;
    try {
      const signerSettings = getActivePdfSignerWebSettings();
      signResult = await signDocumentsWithPdfSignerExtension({
        jobId: payload.token || "",
        token: payload.token || "",
        apiBaseUrl: payload.apiBase || window.location.origin,
        documents,
        settings: signerSettings,
        debugAppearance: getPdfSignerAppearanceDebug(signerSettings),
        allowErrorResponse: true,
      });
    } finally {
      keepPollingSignatureProgress = false;
      await progressPolling.catch(() => {});
    }

    setSignatureDebugFromPingResponse(signResult);
    applySignatureReviewSigningResult(signResult);
    if (signResult.ok === false || signResult.success === false) {
      const errors = normalizeSignatureBridgeErrors(signResult);
      if (isSignatureBridgeResultEffectivelySuccessful(signResult)) {
        setSignaturesBridgeStatus(signResult.message || "Potpisano. Osvježavam dokumente u pozadini...", "ready");
        scheduleDocumentsExplorerSilentRefresh();
      } else {
        const firstError = errors[0];
        setSignaturesBridgeStatus(
          firstError
            ? `${firstError.code}: ${firstError.nativeSignerMessage || firstError.message}`
            : (signResult.message || "Potpisivanje je završilo s greškama."),
          "error",
        );
        if (Number(signResult.signed || 0) > 0) {
          scheduleDocumentsExplorerSilentRefresh();
        }
      }
      return;
    }

    if (signResult.dryRun) {
      setSignaturesBridgeStatus(`Dry-run zavrsen. Bilo bi potpisano: ${Number(signResult.wouldSign || 0)}.`, "ready");
    } else {
      const signedRaw = Number(signResult.signed ?? signResult.downloaded);
      const signedCount = Number.isFinite(signedRaw) && signedRaw > 0 ? signedRaw : documents.length;
      setSignaturesBridgeStatus(
        signedCount === 1
          ? "Potpisano. Osvježavam dokumente..."
          : `Potpisano ${signedCount} dokumenata. Osvježavam dokumente...`,
        "ready",
      );
    }
    scheduleDocumentsExplorerSilentRefresh();
  } catch (error) {
    if (isPdfSignerExtensionUnavailable(error)) {
      setSignatureReviewState({
        status: "error",
        error: error.message || "PDF Signer nije dostupan.",
        errorDetails: normalizeSignatureBridgeErrors(error),
        signingProgress: {
          ...(state.signatures.review.signingProgress || {}),
          active: false,
          state: "error",
          message: "PDF Signer nije dostupan.",
        },
      });
      if (signaturesInstallSignerButton) {
        signaturesInstallSignerButton.hidden = false;
      }
      setSignaturesBridgeStatus(
        "Za digitalno potpisivanje instaliraj PDF Signer ekstenziju i lokalni Signer program.",
        "warning",
      );
    } else {
      const errors = normalizeSignatureBridgeErrors(error);
      setSignatureReviewState({
        status: "error",
        error: error.message || "Nije moguće pokrenuti potpisivanje.",
        errorDetails: errors,
        signingProgress: {
          ...(state.signatures.review.signingProgress || {}),
          active: false,
          state: "error",
          message: error.message || "Nije moguće pokrenuti potpisivanje.",
        },
      });
      const firstError = errors[0];
      setSignaturesBridgeStatus(
        firstError
          ? `${firstError.code}: ${firstError.nativeSignerMessage || firstError.message}`
          : (error.message || "Nije moguće pokrenuti potpisivanje."),
        "error",
      );
    }
  } finally {
    signaturesOpenLocalSignerButton.disabled = false;
    signaturesOpenLocalSignerButton.classList.remove("is-loading");
  }
}

function upsertDocumentsExplorerWorkOrderDocuments(documents = []) {
  const nextDocuments = (Array.isArray(documents) ? documents : [])
    .filter((item) => item && typeof item === "object" && String(item.id || "").trim());
  if (nextDocuments.length === 0) {
    return;
  }

  const currentItems = Array.isArray(state.documentsExplorer.workOrderDocuments)
    ? state.documentsExplorer.workOrderDocuments
    : [];
  const nextKeys = new Set(nextDocuments.map((item) => String(item.id || "").trim()));

  state.documentsExplorer.workOrderDocuments = [
    ...nextDocuments,
    ...currentItems.filter((item) => !nextKeys.has(String(item?.id || "").trim())),
  ];
  state.documentsExplorer.organizationId = String(state.activeOrganizationId || "").trim();
}

function upsertDocumentsExplorerRecord(record = null) {
  if (!record || typeof record !== "object") {
    return;
  }

  const normalizedId = String(record.id || "").trim();
  if (!normalizedId) {
    return;
  }

  const currentItems = Array.isArray(state.documentsExplorer.records)
    ? state.documentsExplorer.records
    : [];

  state.documentsExplorer.records = [
    record,
    ...currentItems.filter((item) => String(item?.id || "").trim() !== normalizedId),
  ];
  state.documentsExplorer.loaded = true;
  const activeOrganizationId = String(state.activeOrganizationId || "").trim();
  state.documentsExplorer.organizationId = activeOrganizationId;

  const feedScopeId = String(state.measurementEquipmentActivityFeed.organizationId || "").trim();
  if (feedScopeId && feedScopeId === activeOrganizationId) {
    const feedRecords = Array.isArray(state.measurementEquipmentActivityFeed.records)
      ? state.measurementEquipmentActivityFeed.records
      : [];
    state.measurementEquipmentActivityFeed = {
      ...state.measurementEquipmentActivityFeed,
      loaded: true,
      error: "",
      records: [
        record,
        ...feedRecords.filter((item) => String(item?.id || "").trim() !== normalizedId),
      ],
    };
  }

  const periodicsScopeId = String(state.periodicsFeed.organizationId || "").trim();
  if (periodicsScopeId && periodicsScopeId === activeOrganizationId) {
    const periodicsRecords = Array.isArray(state.periodicsFeed.records)
      ? state.periodicsFeed.records
      : [];
    state.periodicsFeed = {
      ...state.periodicsFeed,
      loaded: true,
      error: "",
      records: [
        record,
        ...periodicsRecords.filter((item) => String(item?.id || "").trim() !== normalizedId),
      ],
    };
  }

  if (state.activeView === "module" && state.activeModuleItem === "documents") {
    renderDocumentsModule();
  }
  if (state.activeView === "module" && state.activeModuleItem === "periodics") {
    renderPeriodicsModule();
  }
  if (state.measurementEquipmentEditorOpen) {
    renderMeasurementEquipmentSideActivityPanel();
  }
}

function hasExplicitPeriodicsDatePattern(value = "") {
  const token = String(value || "").trim();
  return /\b\d{4}-\d{1,2}-\d{1,2}\b/.test(token)
    || /\b\d{1,2}[./]\d{1,2}[./]\d{4}\b/.test(token);
}

function normalizePeriodicsDateToken(value = "") {
  const token = String(value || "").trim();
  if (!token) {
    return "";
  }

  const isoMatch = token.match(/\b\d{4}-\d{2}-\d{2}\b/);
  if (isoMatch?.[0]) {
    return isoMatch[0];
  }

  const localMatch = token.match(/\b\d{2}[./]\d{2}[./]\d{4}\b/);
  if (localMatch?.[0]) {
    const normalized = localMatch[0].replace(/\./g, "/");
    const [dayValue, monthValue, yearValue] = normalized.split("/");
    const day = Number.parseInt(dayValue, 10);
    const month = Number.parseInt(monthValue, 10);
    const year = Number.parseInt(yearValue, 10);
    if (Number.isFinite(day) && Number.isFinite(month) && Number.isFinite(year)) {
      const candidate = `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      const parsedCandidate = parseDateValue(candidate);
      if (parsedCandidate) {
        return toDateKey(parsedCandidate);
      }
    }
  }

  if (!hasExplicitPeriodicsDatePattern(token)) {
    return "";
  }

  const parsedDate = parseDateValue(token);
  return parsedDate ? toDateKey(parsedDate) : "";
}

function isPeriodicsDueDateKey(key = "") {
  const normalizedKey = normalizeDocumentsExplorerKey(key);
  if (!normalizedKey) {
    return false;
  }
  if (
    PERIODICS_DUE_DATE_REJECT_KEY_HINTS.some((hint) => normalizedKey.includes(hint))
    || PERIODICS_VALIDITY_MONTHS_KEY_HINTS.some((hint) => normalizedKey.includes(hint))
  ) {
    return false;
  }
  return PERIODICS_DUE_DATE_KEY_HINTS.some((hint) => normalizedKey.includes(hint));
}

function isPeriodicsValidityMonthsKey(key = "") {
  const normalizedKey = normalizeDocumentsExplorerKey(key);
  if (!normalizedKey) {
    return false;
  }
  return PERIODICS_VALIDITY_MONTHS_KEY_HINTS.some((hint) => normalizedKey.includes(hint));
}

function getPeriodicsRecordFieldValues(record = {}) {
  return record?.fieldValues && typeof record.fieldValues === "object" && !Array.isArray(record.fieldValues)
    ? record.fieldValues
    : {};
}

function getPeriodicsPreferredDueDateSources(record = {}) {
  const fieldValues = getPeriodicsRecordFieldValues(record);
  const trackedDates = Array.isArray(fieldValues[PERIODICS_TRACKED_DATES_FIELD_KEY])
    ? fieldValues[PERIODICS_TRACKED_DATES_FIELD_KEY]
    : [];
  const trackedSources = trackedDates
    .map((entry) => {
      const fieldKey = String(entry?.fieldKey || entry?.key || entry?.label || "").trim();
      if (!fieldKey || !isPeriodicsDueDateKey(fieldKey)) {
        return null;
      }
      const dateKey = normalizePeriodicsDateToken(entry?.value ?? entry?.date ?? entry?.validUntil);
      return dateKey ? {
        sourceKey: `${PERIODICS_TRACKED_DATES_FIELD_KEY}.${fieldKey}`,
        fieldKey,
        dateKey,
      } : null;
    })
    .filter(Boolean);

  return trackedSources;
}

function normalizePeriodicsDueDateSet(values = []) {
  return Array.from(new Set((Array.isArray(values) ? values : [])
    .map((value) => normalizePeriodicsDateToken(value))
    .filter(Boolean)))
    .sort((left, right) => left.localeCompare(right));
}

function extractPeriodicsDocumentDueDates(record = {}) {
  const expirationDate = normalizePeriodicsDateToken(record?.expirationDate ?? record?.expiration_date);
  if (expirationDate) {
    return [expirationDate];
  }
  const preferredDueDates = getPeriodicsPreferredDueDateSources(record).map((entry) => entry.dateKey);
  return normalizePeriodicsDueDateSet(preferredDueDates);
}

function getPeriodicsDueState(dueDate = "", todayDate = null, visualSettings = getPeriodicsVisualSettings()) {
  const parsedDate = parseDateValue(dueDate);
  if (!parsedDate) {
    return {
      daysUntil: Number.NaN,
      toneClass: "is-unknown",
      badgeLabel: "Bez roka",
    };
  }

  const targetDate = new Date(parsedDate);
  targetDate.setHours(0, 0, 0, 0);
  const baselineDate = todayDate instanceof Date
    ? new Date(todayDate)
    : new Date();
  baselineDate.setHours(0, 0, 0, 0);

  const daysUntil = Math.round((targetDate.getTime() - baselineDate.getTime()) / (1000 * 60 * 60 * 24));
  const normalizedVisualSettings = normalizePeriodicsVisualSettings(visualSettings);
  const criticalDays = normalizedVisualSettings.criticalDays;
  const warningDays = normalizedVisualSettings.warningDays;
  if (daysUntil < 0) {
    return {
      daysUntil,
      toneClass: "is-overdue",
      badgeLabel: `Isteklo ${Math.abs(daysUntil)} d`,
    };
  }
  if (daysUntil === 0) {
    return {
      daysUntil,
      toneClass: "is-today",
      badgeLabel: "Danas",
    };
  }
  if (daysUntil <= criticalDays) {
    return {
      daysUntil,
      toneClass: "is-critical",
      badgeLabel: `${daysUntil} d`,
    };
  }
  if (daysUntil <= warningDays) {
    return {
      daysUntil,
      toneClass: "is-warning",
      badgeLabel: `${daysUntil} d`,
    };
  }
  return {
    daysUntil,
    toneClass: "is-future",
    badgeLabel: `${daysUntil} d`,
  };
}

function getPeriodicsDocumentRecords() {
  const activeOrganizationId = String(state.activeOrganizationId || "").trim();
  if (!activeOrganizationId) {
    return [];
  }

  const recordsById = new Map();
  const pushScopedRecords = (records = []) => {
    (Array.isArray(records) ? records : []).forEach((record) => {
      const recordId = String(record?.id || "").trim();
      if (!recordId) {
        return;
      }
      if (!recordsById.has(recordId)) {
        recordsById.set(recordId, record);
      }
    });
  };

  const periodicsFeedScope = String(state.periodicsFeed.organizationId || "").trim();
  if (
    state.periodicsFeed.loaded
    && periodicsFeedScope === activeOrganizationId
    && Array.isArray(state.periodicsFeed.records)
  ) {
    pushScopedRecords(state.periodicsFeed.records);
  }

  const documentsScope = String(state.documentsExplorer.organizationId || "").trim();
  if (
    state.documentsExplorer.loaded
    && documentsScope === activeOrganizationId
    && Array.isArray(state.documentsExplorer.records)
  ) {
    pushScopedRecords(state.documentsExplorer.records);
  }

  return Array.from(recordsById.values());
}

function getPeriodicsRecordFreshnessKey(record = {}, dueDate = "") {
  const dateCandidates = [
    record?.inspectionDate,
    record?.issuedDate,
    record?.updatedAt,
    record?.createdAt,
    dueDate,
  ]
    .map((value) => String(value || "").trim())
    .filter(Boolean);
  const normalizedDates = dateCandidates.map((value) => {
    const dateKey = normalizeDateInputValue(value.slice(0, 10));
    if (dateKey) {
      return dateKey;
    }
    const timestamp = Date.parse(value);
    return Number.isFinite(timestamp) ? new Date(timestamp).toISOString() : "";
  });

  return [
    ...normalizedDates,
    String(record?.id || ""),
  ].join("|");
}

function createPeriodicsInspectionRenewalKey({
  record = {},
  companyId = "",
  companyName = "",
  locationId = "",
  locationName = "",
  objectId = "",
  objectName = "",
  serviceLabel = "",
  templateLabel = "",
  workOrderNumber = "",
  inspectionDate = "",
  issuedDate = "",
  dueIndex = 0,
} = {}) {
  const recordId = String(record?.id || "").trim();
  const documentNumber = normalizeDocumentsExplorerKey(workOrderNumber) || recordId;
  const identityParts = [
    String(record?.organizationId || state.activeOrganizationId || "").trim(),
    companyId || normalizeDocumentsExplorerKey(companyName),
    locationId || normalizeDocumentsExplorerKey(locationName),
    objectId || normalizeDocumentsExplorerKey(objectName),
    normalizeDocumentsExplorerKey(serviceLabel),
    normalizeDocumentsExplorerKey(templateLabel),
    documentNumber,
    inspectionDate || issuedDate,
    String(dueIndex || 0),
  ];

  return identityParts.map((part) => String(part || "").trim()).join("|");
}

function buildPeriodicsInspectionEntries(records = getPeriodicsDocumentRecords()) {
  const latestRows = new Map();
  const todayDate = new Date();
  const visualSettings = getPeriodicsVisualSettings();
  todayDate.setHours(0, 0, 0, 0);

  (Array.isArray(records) ? records : []).forEach((record) => {
    const dueDates = extractPeriodicsDocumentDueDates(record);

    const extractedWorkOrderNumber = extractDocumentsExplorerWorkOrderNumber(record);
    const linkedWorkOrder = resolveDocumentsExplorerWorkOrder(record, extractedWorkOrderNumber);
    if (dueDates.length === 0) {
      return;
    }
    const inspectionDueDates = dueDates;
    const companyId = String(linkedWorkOrder?.companyId || record?.companyId || "").trim();
    const locationId = String(linkedWorkOrder?.locationId || record?.locationId || "").trim();
    const company = getCompany(companyId);
    const location = getLocation(locationId);
    const locationObject = getLocationObject(record?.objectId || "");
    const serviceFromRecord = extractDocumentsExplorerFieldValueByHints(
      record,
      DOCUMENTS_EXPLORER_SERVICE_KEY_HINTS,
    );
    const companyFromRecord = extractDocumentsExplorerFieldValueByHints(
      record,
      PERIODICS_COMPANY_KEY_HINTS,
    );
    const locationFromRecord = extractDocumentsExplorerFieldValueByHints(
      record,
      PERIODICS_LOCATION_KEY_HINTS,
    );
    const objectFromRecord = extractDocumentsExplorerFieldValueByHints(
      record,
      ["OBJECT_NAME", "OBJEKT", "NAZIV_OBJEKTA", "OBJECT"],
    );
    const headquartersFromRecord = extractDocumentsExplorerFieldValueByHints(
      record,
      PERIODICS_HEADQUARTERS_KEY_HINTS,
    );
    const oibFromRecord = extractDocumentsExplorerFieldValueByHints(
      record,
      PERIODICS_OIB_KEY_HINTS,
    );
    const serviceLabel = String(
      getWorkOrderServiceSummary(linkedWorkOrder)
      || linkedWorkOrder?.serviceLine
      || serviceFromRecord
      || record?.templateTitle
      || record?.documentType
      || "Ispitivanje",
    ).trim() || "Ispitivanje";

    const companyName = String(
      company?.name
      || linkedWorkOrder?.companyName
      || linkedWorkOrder?.company
      || companyFromRecord
      || "Bez tvrtke",
    ).trim() || "Bez tvrtke";
    const headquarters = String(
      company?.headquarters
      || linkedWorkOrder?.headquarters
      || headquartersFromRecord
      || "",
    ).trim();
    const companyOib = String(
      company?.oib
      || linkedWorkOrder?.companyOib
      || oibFromRecord
      || "",
    ).trim();
    const locationName = String(
      location?.name
      || linkedWorkOrder?.locationName
      || locationFromRecord
      || "",
    ).trim();
    const compactLocationName = createCompactLocationLabel(locationName);
    const objectName = String(locationObject?.name || record?.objectName || objectFromRecord || "").trim();
    const objectId = String(locationObject?.id || record?.objectId || "").trim();
    const templateLabel = String(record?.templateTitle || record?.documentType || "Zapisnik").trim() || "Zapisnik";
    const workOrderNumber = String(linkedWorkOrder?.workOrderNumber || extractedWorkOrderNumber || "").trim();
    const workOrderId = String(linkedWorkOrder?.id || "").trim();
    const workOrderStatus = String(linkedWorkOrder?.status || "").trim();
    const workOrderVerified = Boolean(
      Number(linkedWorkOrder?.documentSummary?.verifiedWorkOrderCount || 0) > 0
      || normalizeLooseName(workOrderStatus).includes("ovjeren"),
    );

    inspectionDueDates.forEach((dueDate, index) => {
      const renewalKey = createPeriodicsInspectionRenewalKey({
        record,
        companyId,
        companyName,
        locationId,
        locationName: compactLocationName,
        objectId,
        objectName,
        serviceLabel,
        templateLabel,
        workOrderNumber,
        inspectionDate: normalizeDateInputValue(record?.inspectionDate || ""),
        issuedDate: normalizeDateInputValue(record?.issuedDate || ""),
        dueIndex: index,
      });
      const freshnessKey = getPeriodicsRecordFreshnessKey(record, dueDate);

      const dueState = getPeriodicsDueState(dueDate, todayDate, visualSettings);
      const searchText = [
        companyName,
        headquarters,
        companyOib,
        compactLocationName,
        objectName,
        serviceLabel,
        templateLabel,
        workOrderNumber,
        workOrderStatus,
      ].filter(Boolean).join(" ");

      const row = {
        id: `periodics-inspection-${renewalKey || String(record?.id || "")}-${dueDate}-${index}`,
        dueDate,
        dueState,
        companyId,
        companyName,
        headquarters,
        companyOib,
        locationId,
        locationName: compactLocationName,
        objectId,
        objectName,
        serviceLabel,
        templateLabel,
        workOrderId,
        workOrderNumber,
        workOrderStatus,
        workOrderVerified,
        workOrder: linkedWorkOrder || null,
        searchText,
        freshnessKey,
      };
      const current = latestRows.get(renewalKey);
      if (!current || String(row.freshnessKey).localeCompare(String(current.freshnessKey)) >= 0) {
        latestRows.set(renewalKey, row);
      }
    });
  });

  return Array.from(latestRows.values()).sort((left, right) => (
    String(left.dueDate || "9999-12-31").localeCompare(String(right.dueDate || "9999-12-31"))
    || String(left.companyName || "").localeCompare(String(right.companyName || ""), "hr")
    || String(left.locationName || "").localeCompare(String(right.locationName || ""), "hr")
  ));
}

function buildPeriodicsVehicleEntries() {
  const rows = [];
  const todayDate = new Date();
  const visualSettings = getPeriodicsVisualSettings();
  todayDate.setHours(0, 0, 0, 0);
  const activeOrganizationId = String(state.activeOrganizationId || "").trim();

  (state.vehicles ?? [])
    .filter((vehicle) => {
      if (!activeOrganizationId) {
        return true;
      }
      const vehicleOrganizationId = String(vehicle?.organizationId || vehicle?.orgId || "").trim();
      return !vehicleOrganizationId || vehicleOrganizationId === activeOrganizationId;
    })
    .forEach((vehicle) => {
      const vehicleId = String(vehicle?.id || "").trim();
      const vehicleName = String(vehicle?.name || "Vozilo").trim() || "Vozilo";
      const plateNumber = String(vehicle?.plateNumber || "").trim();
      const vinNumber = String(vehicle?.vinNumber || "").trim();

      const registrationDueDate = String(vehicle?.registrationExpiresOn || "").trim();
      if (registrationDueDate) {
        const dueState = getPeriodicsDueState(registrationDueDate, todayDate, visualSettings);
        rows.push({
          id: `periodics-vehicle-registration-${vehicleId}-${registrationDueDate}`,
          vehicleId,
          periodicsGroupType: "registration",
          dueDate: registrationDueDate,
          dueState,
          vehicleName,
          plateNumber,
          vinNumber,
          periodicLabel: "Registracija",
          detail: "Istek prometne dozvole",
          searchText: [vehicleName, plateNumber, vinNumber, "registracija"].filter(Boolean).join(" "),
        });
      }

      const serviceDueDate = String(vehicle?.serviceDueDate || "").trim();
      if (serviceDueDate) {
        const dueState = getPeriodicsDueState(serviceDueDate, todayDate, visualSettings);
        rows.push({
          id: `periodics-vehicle-service-${vehicleId}-${serviceDueDate}`,
          vehicleId,
          periodicsGroupType: "service",
          dueDate: serviceDueDate,
          dueState,
          vehicleName,
          plateNumber,
          vinNumber,
          periodicLabel: "Servis",
          detail: "Planirani servisni rok",
          searchText: [vehicleName, plateNumber, vinNumber, "servis"].filter(Boolean).join(" "),
        });
      }

      (Array.isArray(vehicle?.activityItems) ? vehicle.activityItems : []).forEach((activityItem) => {
        const dueDate = String(activityItem?.validUntil || "").trim();
        if (!dueDate) {
          return;
        }
        const activityType = normalizeVehicleActivityTypeValue(activityItem?.activityType || activityItem?.type || "");
        const activityLabel = getVehicleActivityTypeLabel(activityType);
        const detail = [
          String(activityItem?.performedBy || "").trim(),
          String(activityItem?.workSummary || "").trim(),
        ].filter(Boolean).join(" · ");
        const dueState = getPeriodicsDueState(dueDate, todayDate, visualSettings);
        rows.push({
          id: `periodics-vehicle-activity-${vehicleId}-${String(activityItem?.id || "")}-${dueDate}`,
          vehicleId,
          periodicsGroupType: `activity:${activityType || activityLabel}`,
          dueDate,
          dueState,
          vehicleName,
          plateNumber,
          vinNumber,
          periodicLabel: activityLabel,
          detail: detail || "Evidencija vozila",
          searchText: [vehicleName, plateNumber, vinNumber, activityLabel, detail].filter(Boolean).join(" "),
        });
      });
    });

  return rows.sort((left, right) => (
    String(left.dueDate || "").localeCompare(String(right.dueDate || ""))
    || String(left.vehicleName || "").localeCompare(String(right.vehicleName || ""), "hr")
  ));
}

function buildPeriodicsPeopleEntries() {
  const rows = [];
  const todayDate = new Date();
  const visualSettings = getPeriodicsVisualSettings();
  todayDate.setHours(0, 0, 0, 0);
  const areaDefinitions = getQualificationExamDefinitions();

  getActiveOrganizationUsers().forEach((user) => {
    const userId = String(user?.id || "").trim();
    const userName = getUserDocumentDisplayName(user);
    const userEmail = String(user?.email || "").trim();

    areaDefinitions.forEach((areaDefinition) => {
      const qualification = getUserElectricalQualification(user, areaDefinition.key);
      if (!hasQualificationCapability(qualification) || qualification.validForever) {
        return;
      }

      const dueDate = String(qualification.validUntil || "").trim();
      if (!dueDate) {
        return;
      }

      const dueState = getPeriodicsDueState(dueDate, todayDate, visualSettings);
      const capabilityLabel = [
        qualification.canInspect ? "Ispitivač" : "",
        qualification.canAuthorize ? "Ovlaštena osoba" : "",
        qualification.canResponsible ? "Odgovorna osoba" : "",
      ].filter(Boolean).join(" + ") || "Ispit";
      const qualificationLabel = [
        capabilityLabel,
        qualification.data1 ? `Podatak 1 ${qualification.data1}` : "",
      ].filter(Boolean).join(" · ");

      rows.push({
        id: `periodics-people-${userId}-${areaDefinition.key}-${dueDate}`,
        userId,
        periodicsGroupType: areaDefinition.key,
        dueDate,
        dueState,
        userName,
        userEmail,
        areaLabel: areaDefinition.label,
        qualificationLabel: qualificationLabel || capabilityLabel,
        searchText: [
          userName,
          userEmail,
          areaDefinition.label,
          capabilityLabel,
          qualification.data1,
          qualification.data2,
          qualification.data3,
          qualification.type,
        ].filter(Boolean).join(" "),
      });
    });
  });

  return rows.sort((left, right) => (
    String(left.dueDate || "").localeCompare(String(right.dueDate || ""))
    || String(left.userName || "").localeCompare(String(right.userName || ""), "hr")
  ));
}

function buildPeriodicsMeasurementEquipmentEntries() {
  const rows = [];
  const todayDate = new Date();
  const visualSettings = getPeriodicsVisualSettings();
  todayDate.setHours(0, 0, 0, 0);
  const activeOrganizationId = String(state.activeOrganizationId || "").trim();

  (state.measurementEquipment ?? [])
    .filter((item) => {
      if (!activeOrganizationId) {
        return true;
      }
      const itemOrganizationId = String(item?.organizationId || item?.orgId || "").trim();
      return !itemOrganizationId || itemOrganizationId === activeOrganizationId;
    })
    .forEach((item) => {
      const equipmentId = String(item?.id || "").trim();
      const equipmentName = String(item?.name || "Oprema").trim() || "Oprema";
      const manufacturerModel = [
        String(item?.manufacturer || "").trim(),
        String(item?.deviceType || "").trim(),
      ].filter(Boolean).join(" · ");
      const kindLabel = getOptionLabel(
        MEASUREMENT_EQUIPMENT_KIND_OPTIONS,
        String(item?.equipmentKind || "combined").trim() || "combined",
      );
      const codeSummary = [
        String(item?.deviceCode || "").trim() ? `Ozn. ${String(item.deviceCode || "").trim()}` : "",
        String(item?.serialNumber || "").trim() ? `Ser. ${String(item.serialNumber || "").trim()}` : "",
        String(item?.inventoryNumber || "").trim() ? `Inv. ${String(item.inventoryNumber || "").trim()}` : "",
      ].filter(Boolean).join(" · ");
      const templateSummary = (Array.isArray(item?.linkedTemplateTitles) ? item.linkedTemplateTitles : [])
        .map((value) => String(value || "").trim())
        .filter(Boolean)
        .slice(0, 3)
        .join(", ");

      const dueCandidates = [];

      const calibrationDueDate = String(item?.validUntil || "").trim();
      if (calibrationDueDate) {
        dueCandidates.push({
          dueDate: calibrationDueDate,
          periodicLabel: "Umjernica",
          detail: item?.requiresCalibration ? "Glavni rok umjeravanja" : "Rok evidencije opreme",
        });
      }

      (Array.isArray(item?.activityItems) ? item.activityItems : []).forEach((entry) => {
        const dueDate = String(entry?.validUntil || "").trim();
        if (!dueDate) {
          return;
        }
        const activityType = normalizeMeasurementEquipmentActivityTypeValue(entry?.activityType || entry?.type || "");
        const activityLabel = getMeasurementEquipmentActivityTypeLabel(activityType);
        const detail = [
          String(entry?.performedBy || "").trim(),
          String(entry?.note || "").trim(),
        ].filter(Boolean).join(" · ");
        dueCandidates.push({
          dueDate,
          periodicLabel: activityLabel,
          detail: detail || "Aktivnost opreme",
        });
      });

      dueCandidates.forEach((entry, index) => {
        const dueDate = String(entry?.dueDate || "").trim();
        if (!dueDate) {
          return;
        }
        const dueState = getPeriodicsDueState(dueDate, todayDate, visualSettings);
        const periodicLabel = String(entry?.periodicLabel || "Rok opreme").trim() || "Rok opreme";
        const detail = String(entry?.detail || "").trim();
        const searchText = [
          equipmentName,
          manufacturerModel,
          kindLabel,
          periodicLabel,
          detail,
          codeSummary,
          templateSummary,
        ].filter(Boolean).join(" ");

        rows.push({
          id: `periodics-equipment-${equipmentId}-${dueDate}-${index}`,
          equipmentId,
          periodicsGroupType: normalizeLooseName(periodicLabel) || `rok-${index}`,
          dueDate,
          dueState,
          equipmentName,
          manufacturerModel,
          kindLabel,
          periodicLabel,
          detail,
          codeSummary,
          templateSummary,
          searchText,
        });
      });
    });

  return rows.sort((left, right) => (
    String(left.dueDate || "").localeCompare(String(right.dueDate || ""))
    || String(left.equipmentName || "").localeCompare(String(right.equipmentName || ""), "hr")
  ));
}

function applyPeriodicsFilters(entries = [], filters = state.periodicsFilters) {
  const queryNeedle = normalizeLooseName(filters?.query || "");
  const horizon = String(filters?.horizon || "all").trim().toLowerCase();
  const horizonDays = Number.parseInt(horizon, 10);

  return (Array.isArray(entries) ? entries : []).filter((entry) => {
    const daysUntil = Number(entry?.dueState?.daysUntil);

    if (horizon === "overdue") {
      if (!Number.isFinite(daysUntil) || daysUntil >= 0) {
        return false;
      }
    } else if (Number.isFinite(horizonDays)) {
      if (!Number.isFinite(daysUntil) || daysUntil > horizonDays) {
        return false;
      }
    }

    return matchesPeriodicsSearchFilter(entry, queryNeedle);
  });
}

function normalizePeriodicsInspectionGroupMode(value = "location-object") {
  const normalized = String(value || "location-object").trim().toLowerCase();
  if (["item", "inspection", "by-inspection", "po-ispitivanju"].includes(normalized)) {
    return "item";
  }
  if (
    [
      "location-object",
      "locationobject",
      "location_object",
      "company-location-object",
      "company",
      "location",
      "object",
    ].includes(normalized)
  ) {
    return "location-object";
  }
  return "location-object";
}

function getPeriodicsInspectionGroupMeta(entry = {}, groupMode = "location-object") {
  const mode = normalizePeriodicsInspectionGroupMode(groupMode);
  if (mode === "location-object") {
    const companyName = entry.companyName || "Bez tvrtke";
    const companyOib = entry.companyOib || "";
    const headquarters = entry.headquarters || "";
    return {
      key: [
        "company",
        normalizeDocumentsExplorerKey(companyName) || "unknown-company",
        normalizeDocumentsExplorerKey(companyOib || headquarters) || "unknown-company-meta",
      ].join(":"),
      title: companyName,
      companyName,
      headquarters,
      companyOib,
    };
  }
  return { key: "item", title: "", subtitle: "" };
}

function buildPeriodicsInspectionGroupOptions(entries = [], groupMode = "location-object") {
  const mode = normalizePeriodicsInspectionGroupMode(groupMode);
  if (mode === "item") {
    return [];
  }

  const groupMap = new Map();
  (Array.isArray(entries) ? entries : []).forEach((entry) => {
    const meta = getPeriodicsInspectionGroupMeta(entry, mode);
    const current = groupMap.get(meta.key) || {
      ...meta,
      count: 0,
      nextDueDate: "",
      nextDueState: null,
    };
    current.count += 1;
    if (entry.dueDate && (!current.nextDueDate || entry.dueDate < current.nextDueDate)) {
      current.nextDueDate = entry.dueDate;
      current.nextDueState = entry.dueState || null;
    }
    groupMap.set(meta.key, current);
  });

  return Array.from(groupMap.values())
    .sort((left, right) => (
      String(left.title || "").localeCompare(String(right.title || ""), "hr")
      || String(left.nextDueDate || "9999-12-31").localeCompare(String(right.nextDueDate || "9999-12-31"))
    ));
}

function applyPeriodicsInspectionGroupFilter(entries = [], filters = state.periodicsFilters) {
  const mode = normalizePeriodicsInspectionGroupMode(filters?.inspectionGroup || "location-object");
  const selectedKey = String(filters?.inspectionGroupKey || "").trim();
  if (mode === "item" || !selectedKey) {
    return Array.isArray(entries) ? entries : [];
  }

  return (Array.isArray(entries) ? entries : []).filter((entry) => (
    getPeriodicsInspectionGroupMeta(entry, mode).key === selectedKey
  ));
}

function syncPeriodicsInspectionGroupFilterControl(entries = [], filters = state.periodicsFilters) {
  if (!periodicsInspectionGroupValueInput || !periodicsInspectionGroupValueField) {
    return "";
  }

  const mode = normalizePeriodicsInspectionGroupMode(filters?.inspectionGroup || "location-object");
  const options = buildPeriodicsInspectionGroupOptions(entries, mode);
  const selectedKey = options.some((option) => option.key === filters?.inspectionGroupKey)
    ? String(filters.inspectionGroupKey)
    : "";

  periodicsInspectionGroupValueField.hidden = mode === "item";
  replaceSelectOptions(
    periodicsInspectionGroupValueInput,
    [
      { value: "", label: "Sve lokacije i objekti" },
      ...options.map((option) => ({
        value: option.key,
        label: [
          option.companyName,
          option.count ? `${option.count} stavki` : "",
          option.nextDueDate ? formatCompactDate(option.nextDueDate) : "",
        ].filter(Boolean).join(" · "),
      })),
    ],
    selectedKey,
  );
  return selectedKey;
}

function getPeriodicsInspectionExpandedGroups() {
  if (!state.periodicsInspectionExpandedGroups || typeof state.periodicsInspectionExpandedGroups !== "object") {
    state.periodicsInspectionExpandedGroups = {};
  }
  return state.periodicsInspectionExpandedGroups;
}

function isPeriodicsInspectionGroupExpanded(groupKey = "") {
  return Boolean(getPeriodicsInspectionExpandedGroups()[String(groupKey || "")]);
}

function togglePeriodicsInspectionGroupExpansion(groupKey = "") {
  const key = String(groupKey || "").trim();
  if (!key) {
    return;
  }
  const expandedGroups = getPeriodicsInspectionExpandedGroups();
  expandedGroups[key] = !expandedGroups[key];
  persistPeriodicsPreferences();
  renderPeriodicsModule();
}

function createPeriodicsInspectionGroupCell(group = {}, expanded = false) {
  const cell = document.createElement("div");
  cell.className = "periodics-group-cell";

  const titleLine = document.createElement("div");
  titleLine.className = "periodics-group-title-line";
  const alertDot = createPeriodicsGroupAlertDot(group);
  if (alertDot) {
    titleLine.append(alertDot);
  }

  const title = document.createElement("strong");
  title.textContent = `${expanded ? "v" : ">"} ${group.companyName || "Bez tvrtke"}`;
  titleLine.append(title);

  const meta = document.createElement("span");
  meta.textContent = [
    group.headquarters || "",
    group.companyOib ? `OIB ${group.companyOib}` : "",
    `${Number(group.count || 0)} ${Number(group.count || 0) === 1 ? "ispitivanje" : "ispitivanja"}`,
  ].filter(Boolean).join(" · ");

  const due = createPeriodicsDueCell(group.nextDueDate || "", group.nextDueState || {});
  due.classList.add("periodics-group-due");

  const copy = document.createElement("div");
  copy.className = "periodics-group-copy";
  copy.append(titleLine, meta);

  cell.append(copy, due);
  return cell;
}

function createPeriodicsInspectionGroupRow(group = {}) {
  const expanded = isPeriodicsInspectionGroupExpanded(group.key);
  const row = document.createElement("article");
  row.className = `periodics-grid-row periodics-group-row periodics-group-summary ${getPeriodicsInspectionGroupToneClass(group)}`.trim();
  row.tabIndex = 0;
  row.setAttribute("role", "button");
  row.setAttribute("aria-expanded", String(expanded));
  row.setAttribute("title", expanded ? "Klikni za sazimanje ispitivanja." : "Klikni za prikaz svih ispitivanja.");

  row.append(createPeriodicsInspectionGroupCell(group, expanded));

  const toggleGroup = () => {
    togglePeriodicsInspectionGroupExpansion(group.key);
  };
  row.addEventListener("click", toggleGroup);
  row.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      toggleGroup();
    }
  });
  return bindPeriodicsInspectionWorkOrderContext(row, group.items);
}

function getPeriodicsEntryCounts(entries = [], visualSettings = getPeriodicsVisualSettings()) {
  const normalizedVisualSettings = normalizePeriodicsVisualSettings(visualSettings);
  const warningDays = normalizedVisualSettings.warningDays;
  let overdueCount = 0;
  let warningCount = 0;
  let validCount = 0;
  (Array.isArray(entries) ? entries : []).forEach((entry) => {
    const daysUntil = Number(entry?.dueState?.daysUntil);
    if (!Number.isFinite(daysUntil)) {
      return;
    }
    if (daysUntil < 0) {
      overdueCount += 1;
      return;
    }
    validCount += 1;
    if (daysUntil <= warningDays) {
      warningCount += 1;
    }
  });
  return { overdueCount, warningCount, validCount };
}

function getPeriodicsInspectionGroupToneClass(group = {}) {
  if (Number(group.overdueCount || 0) > 0) {
    return "is-overdue";
  }
  if (Number(group.warningCount || 0) > 0) {
    return "is-warning";
  }
  return group.nextDueState?.toneClass || "";
}

function summarizePeriodicsInspectionEntries(entries = []) {
  const normalizedEntries = Array.isArray(entries) ? entries : [];
  const summary = {
    count: normalizedEntries.length,
    nextDueDate: "",
    nextDueState: null,
    ...getPeriodicsEntryCounts(normalizedEntries),
  };

  normalizedEntries.forEach((entry) => {
    if (entry?.dueDate && (!summary.nextDueDate || entry.dueDate < summary.nextDueDate)) {
      summary.nextDueDate = entry.dueDate;
      summary.nextDueState = entry.dueState || null;
    }
  });

  return summary;
}

function createPeriodicsGroupAlertDot(group = {}) {
  const overdueCount = Number(group.overdueCount || 0);
  const warningCount = Number(group.warningCount || 0);
  if (overdueCount <= 0 && warningCount <= 0) {
    return null;
  }

  const dot = document.createElement("span");
  dot.className = `periodics-group-alert-dot ${overdueCount > 0 ? "is-overdue has-pulse-alert" : "is-warning has-pulse-warning"}`;
  dot.setAttribute("aria-hidden", "true");
  dot.title = overdueCount > 0
    ? `${overdueCount} isteklo`
    : `${warningCount} uskoro ističe`;
  return dot;
}

function syncPeriodicsSectionMetrics(
  {
    overdueNode = null,
    warningNode = null,
    validNode = null,
    alertOverdueNode = null,
    alertWarningNode = null,
    bodyNode = null,
  } = {},
  entries = [],
  visualSettings = getPeriodicsVisualSettings(),
) {
  const { overdueCount, warningCount, validCount } = getPeriodicsEntryCounts(entries, visualSettings);
  const hasOverdue = overdueCount > 0;
  const hasWarning = warningCount > 0;
  if (overdueNode) {
    overdueNode.textContent = String(overdueCount);
  }
  if (warningNode) {
    warningNode.textContent = String(warningCount);
    warningNode.classList.toggle("has-pulse-warning", warningCount > 0);
  }
  if (validNode) {
    validNode.textContent = String(validCount);
  }
  if (alertOverdueNode) {
    alertOverdueNode.hidden = !hasOverdue;
  }
  if (alertWarningNode) {
    alertWarningNode.hidden = !hasWarning;
  }
  if (bodyNode) {
    bodyNode.classList.toggle("has-overdue", hasOverdue);
    bodyNode.classList.toggle("has-warning", hasWarning);
    const hostCard = bodyNode.closest(".periodics-section-card");
    hostCard?.classList.toggle("has-overdue", hasOverdue);
    hostCard?.classList.toggle("has-warning", hasWarning);
  }
}

function getPeriodicsInspectionWorkOrder(entry = {}) {
  if (entry?.workOrder && typeof entry.workOrder === "object" && entry.workOrder.id) {
    return entry.workOrder;
  }

  const workOrderId = String(entry?.workOrderId || "").trim();
  if (workOrderId) {
    const matchById = state.workOrders.find((item) => String(item?.id || "") === workOrderId);
    if (matchById) {
      return matchById;
    }
  }

  const workOrderNumber = String(entry?.workOrderNumber || "").trim().toUpperCase();
  if (!workOrderNumber) {
    return null;
  }

  return state.workOrders.find((item) => (
    String(item?.workOrderNumber || "").trim().toUpperCase() === workOrderNumber
  )) || null;
}

function isPeriodicsInspectionExpired(entry = {}) {
  const daysUntil = Number(entry?.dueState?.daysUntil);
  return Number.isFinite(daysUntil) && daysUntil < 0;
}

function isPeriodicsInspectionSourceWorkOrder(workOrder = null, entry = {}) {
  if (!workOrder?.id) {
    return false;
  }

  const entryWorkOrderId = String(entry?.workOrderId || "").trim();
  const entryWorkOrderNumber = String(entry?.workOrderNumber || "").trim().toUpperCase();
  const workOrderNumber = String(workOrder?.workOrderNumber || "").trim().toUpperCase();

  return Boolean(
    (entryWorkOrderId && entryWorkOrderId === String(workOrder.id))
    || (entryWorkOrderNumber && workOrderNumber && entryWorkOrderNumber === workOrderNumber),
  );
}

function getPeriodicsInspectionActiveWorkOrderState(workOrder = null, entry = {}) {
  if (!workOrder?.id) {
    return null;
  }

  const status = String(workOrder?.status || entry?.workOrderStatus || "").trim();
  const normalizedStatus = normalizeLooseName(status);
  const entryMatchesWorkOrder = Boolean(
    workOrder?.id
    && (
      String(entry?.workOrderId || "").trim() === String(workOrder.id)
      || (
        String(entry?.workOrderNumber || "").trim()
        && String(entry.workOrderNumber || "").trim().toUpperCase() === String(workOrder.workOrderNumber || "").trim().toUpperCase()
      )
    ),
  );
  const verified = Boolean(
    (entryMatchesWorkOrder && entry?.workOrderVerified)
    || Number(workOrder?.documentSummary?.verifiedWorkOrderCount || 0) > 0
    || normalizedStatus.includes("ovjeren"),
  );

  if (verified) {
    return {
      state: "verified",
      label: "Ovjeren RN",
      toneClass: "is-verified",
      title: status ? `Postoji ovjeren RN (${status}).` : "Postoji ovjeren RN.",
    };
  }

  if (
    workOrder?.id
    && (
      !normalizedStatus
      || normalizedStatus.includes("otvoren")
      || normalizedStatus.includes("open")
      || normalizedStatus.includes("u radu")
      || normalizedStatus.includes("novo")
    )
  ) {
    return {
      state: "open",
      label: "Otvoren RN",
      toneClass: "is-open",
      title: status ? `Postoji otvoren RN (${status}).` : "Postoji otvoren RN.",
    };
  }

  return null;
}

function getPeriodicsInspectionActiveWorkOrder(entry = {}) {
  const linkedWorkOrder = getPeriodicsInspectionWorkOrder(entry);
  if (
    linkedWorkOrder?.id
    && !isPeriodicsInspectionExpired(entry)
    && getPeriodicsInspectionActiveWorkOrderState(linkedWorkOrder, entry)
  ) {
    return linkedWorkOrder;
  }

  const companyId = String(entry?.companyId || "").trim();
  const locationId = String(entry?.locationId || "").trim();
  const serviceNeedle = normalizeLooseName(entry?.serviceLabel || "");
  const candidates = (state.workOrders ?? [])
    .filter((workOrder) => {
      if (companyId && String(workOrder?.companyId || "") !== companyId) {
        return false;
      }
      if (locationId && String(workOrder?.locationId || "") !== locationId) {
        return false;
      }
      if (isPeriodicsInspectionExpired(entry) && isPeriodicsInspectionSourceWorkOrder(workOrder, entry)) {
        return false;
      }
      if (!getPeriodicsInspectionActiveWorkOrderState(workOrder, entry)) {
        return false;
      }
      if (!serviceNeedle) {
        return true;
      }
      const serviceText = normalizeLooseName([
        getWorkOrderServiceSummary(workOrder),
        workOrder?.serviceLine,
        ...(getWorkOrderServiceItems(workOrder) ?? []).flatMap((item) => [
          item?.name,
          item?.serviceCode,
        ]),
      ].filter(Boolean).join(" "));
      return Boolean(serviceText) && (serviceText.includes(serviceNeedle) || serviceNeedle.includes(serviceText));
    })
    .sort((left, right) => (
      String(right?.openedDate || right?.createdAt || "").localeCompare(String(left?.openedDate || left?.createdAt || ""))
      || String(right?.id || "").localeCompare(String(left?.id || ""))
    ));

  return candidates[0] ?? null;
}

function getPeriodicsInspectionWorkOrderStatusInfo(entry = {}) {
  const workOrder = getPeriodicsInspectionActiveWorkOrder(entry);
  const activeState = getPeriodicsInspectionActiveWorkOrderState(workOrder, entry);

  if (activeState) {
    return {
      ...activeState,
      workOrder,
    };
  }

  if (entry?.workOrderNumber) {
    return {
      state: "historic",
      label: "Stari RN",
      toneClass: "is-unlinked",
      title: "Zapisnik ima raniji RN, ali nema otvorenog ili ovjerenog RN-a za novu periodiku.",
    };
  }

  return {
    state: "missing",
    label: "Novi RN",
    toneClass: "is-missing",
    title: "Nema otvorenog ili ovjerenog RN-a za ovu periodiku.",
  };
}

function createPeriodicsInspectionWorkOrderBadge(entry = {}) {
  const info = getPeriodicsInspectionWorkOrderStatusInfo(entry);
  const badge = document.createElement("span");
  badge.className = `periodics-work-order-badge ${info.toneClass}`;
  badge.title = info.workOrder?.workOrderNumber
    ? `${info.title} ${info.workOrder.workOrderNumber}`
    : info.title;
  badge.setAttribute("aria-label", info.label);

  const icon = document.createElement("span");
  icon.className = "periodics-work-order-badge-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.innerHTML = getWorkOrderIconMarkup(info.state === "verified" ? "status" : "todo");

  badge.append(icon);
  return badge;
}

function getPeriodicsInspectionLinkedWorkOrderTargets(entries = []) {
  const sourceEntries = Array.isArray(entries) ? entries : [entries];
  const targetsByKey = new Map();

  sourceEntries.forEach((entry) => {
    const workOrder = getPeriodicsInspectionActiveWorkOrder(entry);
    if (!workOrder?.id) {
      return;
    }

    const key = String(workOrder.id);
    const current = targetsByKey.get(key) || {
      key,
      workOrder,
      entry: { ...entry, workOrder },
      count: 0,
      services: new Set(),
      dueDate: "",
    };
    current.count += 1;
    if (entry?.serviceLabel) {
      current.services.add(String(entry.serviceLabel));
    }
    if (entry?.dueDate && (!current.dueDate || entry.dueDate < current.dueDate)) {
      current.dueDate = entry.dueDate;
    }
    targetsByKey.set(key, current);
  });

  return Array.from(targetsByKey.values())
    .sort((left, right) => (
      String(left.dueDate || "9999-12-31").localeCompare(String(right.dueDate || "9999-12-31"))
      || String(left.workOrder?.workOrderNumber || "").localeCompare(String(right.workOrder?.workOrderNumber || ""), "hr", { numeric: true })
    ));
}

function isPeriodicsInspectionRenewalCandidate(entry = {}) {
  return !getPeriodicsInspectionActiveWorkOrder(entry)
    && isPeriodicsInspectionExpired(entry);
}

function buildPeriodicsInspectionWorkOrderServiceItems(entries = []) {
  const serviceMap = new Map();
  (Array.isArray(entries) ? entries : [entries]).forEach((entry) => {
    const serviceLabel = String(entry?.serviceLabel || "Ispitivanje").trim() || "Ispitivanje";
    const serviceKey = normalizeLooseName(serviceLabel) || serviceLabel.toLowerCase();
    if (serviceMap.has(serviceKey)) {
      return;
    }
    const catalogItem = getServiceCatalogItemForWorkOrderService({
      name: serviceLabel,
      serviceCode: serviceLabel,
    });
    serviceMap.set(serviceKey, buildWorkOrderServiceItemSnapshot(catalogItem ?? {
      name: serviceLabel,
      serviceCode: "",
      serviceType: "inspection",
      status: "active",
    }, {
      name: serviceLabel,
      serviceType: "inspection",
    }));
  });
  return Array.from(serviceMap.values());
}

function getPeriodicsInspectionRenewalTargets(entries = []) {
  const sourceEntries = (Array.isArray(entries) ? entries : [entries])
    .filter(isPeriodicsInspectionRenewalCandidate);
  const targetsByKey = new Map();

  sourceEntries.forEach((entry) => {
    const key = [
      String(entry?.companyId || normalizeLooseName(entry?.companyName || "bez-tvrtke")).trim(),
      String(entry?.locationId || normalizeLooseName(entry?.locationName || "bez-lokacije")).trim(),
    ].join(":");
    const current = targetsByKey.get(key) || {
      key,
      companyId: String(entry?.companyId || "").trim(),
      companyName: String(entry?.companyName || "Bez tvrtke").trim() || "Bez tvrtke",
      locationId: String(entry?.locationId || "").trim(),
      locationName: String(entry?.locationName || "Bez lokacije").trim() || "Bez lokacije",
      entries: [],
      services: new Set(),
      dueDate: "",
    };
    current.entries.push(entry);
    if (entry?.serviceLabel) {
      current.services.add(String(entry.serviceLabel));
    }
    if (entry?.dueDate && (!current.dueDate || entry.dueDate < current.dueDate)) {
      current.dueDate = entry.dueDate;
    }
    targetsByKey.set(key, current);
  });

  return Array.from(targetsByKey.values())
    .map((target) => ({
      ...target,
      serviceItems: buildPeriodicsInspectionWorkOrderServiceItems(target.entries),
    }))
    .sort((left, right) => (
      String(left.dueDate || "9999-12-31").localeCompare(String(right.dueDate || "9999-12-31"))
      || String(left.companyName || "").localeCompare(String(right.companyName || ""), "hr", { numeric: true })
      || String(left.locationName || "").localeCompare(String(right.locationName || ""), "hr", { numeric: true })
    ));
}

function getPeriodicsInspectionWorkOrderSummary(entries = []) {
  const targets = getPeriodicsInspectionLinkedWorkOrderTargets(entries);
  if (targets.length === 0) {
    const renewalTargets = getPeriodicsInspectionRenewalTargets(entries);
    return renewalTargets.length > 0 ? "Treba otvoriti RN" : "Bez otvorenog RN-a";
  }

  const verifiedCount = targets.filter((target) => (
    getPeriodicsInspectionWorkOrderStatusInfo(target.entry).toneClass === "is-verified"
  )).length;
  const openCount = targets.filter((target) => (
    getPeriodicsInspectionWorkOrderStatusInfo(target.entry).toneClass === "is-open"
  )).length;

  return [
    `${targets.length} RN`,
    verifiedCount > 0 ? `${verifiedCount} ovjereno` : "",
    openCount > 0 ? `${openCount} otvoreno` : "",
  ].filter(Boolean).join(" · ");
}

function closePeriodicsInspectionContextMenu() {
  const menu = state.periodicsInspectionContextMenu;
  if (menu instanceof HTMLElement) {
    menu.remove();
  }
  state.periodicsInspectionContextMenu = null;
}

function openPeriodicsInspectionWorkOrderTarget(target = {}) {
  const workOrder = target?.workOrder || getPeriodicsInspectionWorkOrder(target?.entry || target);
  if (!workOrder?.id) {
    return false;
  }

  closePeriodicsInspectionContextMenu();
  activateSidebarItem("rn", { expandSidebar: state.sidebarCollapsed });
  requestAnimationFrame(() => {
    hydrateWorkOrderForm(workOrder, { loadActivity: true });
  });
  return true;
}

function openPeriodicsInspectionRenewalTarget(target = {}) {
  const entries = Array.isArray(target?.entries) ? target.entries : [];
  const firstEntry = entries[0] || {};
  if (!firstEntry?.companyId && !firstEntry?.companyName) {
    return false;
  }

  closePeriodicsInspectionContextMenu();
  activateSidebarItem("rn", { expandSidebar: state.sidebarCollapsed });
  requestAnimationFrame(() => {
    focusWorkOrderComposer({
      status: "Otvoreni RN",
      companyId: target.companyId || firstEntry.companyId || "",
      companyName: target.companyName || firstEntry.companyName || "",
      headquarters: firstEntry.headquarters || "",
      companyOib: firstEntry.companyOib || "",
      locationId: target.locationId || firstEntry.locationId || "",
      dueDate: new Date().toISOString().slice(0, 10),
      serviceItems: target.serviceItems || buildPeriodicsInspectionWorkOrderServiceItems(entries),
      tagText: "periodika",
      linkReference: target.dueDate ? `Periodika ${formatCompactDate(target.dueDate)}` : "Periodika",
    });
  });
  return true;
}

function openPeriodicsInspectionContextMenu(entries = [], pointerX = 0, pointerY = 0) {
  const targets = getPeriodicsInspectionLinkedWorkOrderTargets(entries);
  const renewalTargets = getPeriodicsInspectionRenewalTargets(entries);
  if (targets.length === 0 && renewalTargets.length === 0) {
    return;
  }

  closePeriodicsInspectionContextMenu();

  const menu = document.createElement("div");
  menu.className = "periodics-inspection-context-menu";
  menu.dataset.preventRowOpen = "true";
  menu.setAttribute("role", "menu");

  const head = document.createElement("div");
  head.className = "periodics-inspection-context-head";
  const title = document.createElement("strong");
  title.textContent = targets.length > 0 ? (targets.length === 1 ? "Radni nalog" : "Radni nalozi") : "Novi RN";
  const subtitle = document.createElement("span");
  subtitle.textContent = targets.length > 0
    ? (targets.length === 1
      ? "Otvori otvoreni ili ovjereni RN za ovu stavku."
      : `${targets.length} otvorena/ovjerena RN-a za ove stavke.`)
    : "Otvori novi RN za istekle stavke.";
  head.append(title, subtitle);
  menu.append(head);

  targets.slice(0, 8).forEach((target) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "periodics-inspection-context-action";
    button.setAttribute("role", "menuitem");

    const copy = document.createElement("span");
    copy.className = "periodics-inspection-context-copy";
    const label = document.createElement("strong");
    label.textContent = `Otvori RN ${target.workOrder.workOrderNumber || "bez broja"}`;
    const meta = document.createElement("span");
    meta.textContent = [
      Array.from(target.services).slice(0, 2).join(", "),
      target.count > 1 ? `${target.count} stavki` : "",
      target.dueDate ? `rok ${formatCompactDate(target.dueDate)}` : "",
    ].filter(Boolean).join(" · ");
    copy.append(label, meta);

    button.append(copy, createPeriodicsInspectionWorkOrderBadge(target.entry));
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openPeriodicsInspectionWorkOrderTarget(target);
    });
    menu.append(button);
  });

  renewalTargets.slice(0, 6).forEach((target) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "periodics-inspection-context-action is-new-rn";
    button.setAttribute("role", "menuitem");

    const copy = document.createElement("span");
    copy.className = "periodics-inspection-context-copy";
    const label = document.createElement("strong");
    label.textContent = `Otvori novi RN · ${target.locationName || target.companyName}`;
    const meta = document.createElement("span");
    meta.textContent = [
      Array.from(target.services).slice(0, 3).join(", "),
      `${target.entries.length} ${target.entries.length === 1 ? "stavka" : "stavki"}`,
      target.dueDate ? `rok ${formatCompactDate(target.dueDate)}` : "",
    ].filter(Boolean).join(" · ");
    copy.append(label, meta);

    const plus = document.createElement("span");
    plus.className = "periodics-new-work-order-menu-icon";
    plus.setAttribute("aria-hidden", "true");
    plus.textContent = "+";

    button.append(copy, plus);
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openPeriodicsInspectionRenewalTarget(target);
    });
    menu.append(button);
  });

  if (targets.length > 8) {
    const more = document.createElement("p");
    more.className = "periodics-inspection-context-more";
    more.textContent = `Još ${targets.length - 8} RN-a je skriveno u ovom prikazu.`;
    menu.append(more);
  }

  if (renewalTargets.length > 6) {
    const more = document.createElement("p");
    more.className = "periodics-inspection-context-more";
    more.textContent = `Još ${renewalTargets.length - 6} prijedloga za novi RN je skriveno u ovom prikazu.`;
    menu.append(more);
  }

  document.body.append(menu);
  const rect = menu.getBoundingClientRect();
  const left = Math.min(Math.max(pointerX + 8, 12), Math.max(12, window.innerWidth - rect.width - 12));
  const top = Math.min(Math.max(pointerY + 8, 12), Math.max(12, window.innerHeight - rect.height - 12));
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
  state.periodicsInspectionContextMenu = menu;
}

function bindPeriodicsInspectionWorkOrderContext(row, entries = []) {
  const targets = getPeriodicsInspectionLinkedWorkOrderTargets(entries);
  const renewalTargets = getPeriodicsInspectionRenewalTargets(entries);
  if (!(row instanceof HTMLElement) || (targets.length === 0 && renewalTargets.length === 0)) {
    return row;
  }

  row.classList.add("has-periodics-work-order-context");
  const currentTitle = row.getAttribute("title") || "";
  row.setAttribute("title", [currentTitle, "Desni klik: RN akcije."].filter(Boolean).join(" "));
  row.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openPeriodicsInspectionContextMenu(entries, event.clientX, event.clientY);
  });
  return row;
}

function createPeriodicsInspectionRenewalButton(entry = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "periodics-new-work-order-button";
  button.dataset.preventRowOpen = "true";
  button.setAttribute("aria-label", "Otvori novi RN za isteklo ispitivanje");
  button.title = "Otvori novi RN za isteklo ispitivanje";
  button.textContent = "+";
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    const [target] = getPeriodicsInspectionRenewalTargets([entry]);
    if (target) {
      openPeriodicsInspectionRenewalTarget(target);
    }
  });
  return button;
}

function createPeriodicsCell(primary = "", secondary = "", { dimmed = false } = {}) {
  const cell = document.createElement("div");
  cell.className = `periodics-cell${dimmed ? " is-dimmed" : ""}`;

  const primaryLine = document.createElement("strong");
  primaryLine.className = "periodics-cell-primary";
  primaryLine.textContent = primary || "—";
  cell.append(primaryLine);

  if (secondary) {
    const secondaryLine = document.createElement("span");
    secondaryLine.className = "periodics-cell-secondary";
    secondaryLine.textContent = secondary;
    cell.append(secondaryLine);
  }

  return cell;
}

function createPeriodicsInspectionServiceCell(entry = {}) {
  const cell = createPeriodicsCell(entry.serviceLabel || "Ispitivanje");
  cell.classList.add("periodics-service-cell");
  if (getPeriodicsInspectionActiveWorkOrder(entry)) {
    cell.append(createPeriodicsInspectionWorkOrderBadge(entry));
  } else if (isPeriodicsInspectionRenewalCandidate(entry)) {
    cell.append(createPeriodicsInspectionRenewalButton(entry));
  }
  return cell;
}

function createPeriodicsBlankCell() {
  const cell = document.createElement("div");
  cell.className = "periodics-cell periodics-cell-blank";
  cell.setAttribute("aria-hidden", "true");
  return cell;
}

function createPeriodicsDueCell(dueDate = "", dueState = {}) {
  const cell = document.createElement("div");
  cell.className = "periodics-cell periodics-cell-due";

  const primaryLine = document.createElement("strong");
  primaryLine.className = "periodics-cell-primary";
  primaryLine.textContent = dueDate ? formatCompactDate(dueDate) : "Bez roka";
  cell.append(primaryLine);

  const badge = document.createElement("span");
  badge.className = `periodics-due-pill ${dueState?.toneClass || "is-unknown"}`;
  if (String(dueState?.toneClass || "") === "is-overdue") {
    badge.classList.add("has-pulse-alert");
  } else if (String(dueState?.toneClass || "") === "is-warning") {
    badge.classList.add("has-pulse-warning");
  }
  badge.textContent = dueState?.badgeLabel || "Bez roka";
  cell.append(badge);

  return cell;
}

function createPeriodicsRow(cells = [], toneClass = "") {
  const row = document.createElement("article");
  row.className = `periodics-grid-row ${toneClass || ""}`.trim();
  row.append(...cells);
  return row;
}

function getPeriodicsDateExpandedGroups() {
  if (!state.periodicsDateExpandedGroups || typeof state.periodicsDateExpandedGroups !== "object") {
    state.periodicsDateExpandedGroups = {};
  }
  return state.periodicsDateExpandedGroups;
}

function isPeriodicsDateGroupExpanded(groupKey = "") {
  return Boolean(getPeriodicsDateExpandedGroups()[String(groupKey || "")]);
}

function togglePeriodicsDateGroupExpansion(groupKey = "") {
  const key = String(groupKey || "").trim();
  if (!key) {
    return;
  }
  const expandedGroups = getPeriodicsDateExpandedGroups();
  expandedGroups[key] = !expandedGroups[key];
  persistPeriodicsPreferences();
  renderPeriodicsModule();
}

function getPeriodicsDateGroupKeyPart(value = "", fallback = "bez-vrijednosti") {
  return normalizeDocumentsExplorerKey(value) || fallback;
}

function createPeriodicsDateGroupKey(entry = {}, category = "periodika") {
  const normalizedCategory = String(category || "periodika").trim().toLowerCase() || "periodika";
  const categoryKey = getPeriodicsDateGroupKeyPart(normalizedCategory, "periodika");

  if (normalizedCategory === "inspection") {
    return [
      "date",
      categoryKey,
      getPeriodicsDateGroupKeyPart(entry.companyId || entry.companyOib || entry.companyName, "bez-tvrtke"),
      getPeriodicsDateGroupKeyPart(entry.locationId || entry.locationName, "bez-lokacije"),
      getPeriodicsDateGroupKeyPart(entry.objectId || entry.objectName, "bez-objekta"),
      getPeriodicsDateGroupKeyPart(entry.serviceLabel || entry.templateLabel, "ispitivanje"),
      getPeriodicsDateGroupKeyPart(entry.templateLabel, "zapisnik"),
    ].join(":");
  }

  if (normalizedCategory === "vehicle") {
    return [
      "date",
      categoryKey,
      getPeriodicsDateGroupKeyPart(entry.vehicleId || entry.vinNumber || entry.plateNumber || entry.vehicleName, "vozilo"),
      getPeriodicsDateGroupKeyPart(entry.periodicsGroupType || entry.periodicLabel, "rok"),
    ].join(":");
  }

  if (normalizedCategory === "people") {
    return [
      "date",
      categoryKey,
      getPeriodicsDateGroupKeyPart(entry.userId || entry.userEmail || entry.userName, "osoba"),
      getPeriodicsDateGroupKeyPart(entry.periodicsGroupType || entry.areaLabel, "ovlast"),
    ].join(":");
  }

  if (normalizedCategory === "equipment") {
    return [
      "date",
      categoryKey,
      getPeriodicsDateGroupKeyPart(entry.equipmentId || entry.codeSummary || entry.equipmentName, "oprema"),
      getPeriodicsDateGroupKeyPart(entry.periodicsGroupType || entry.periodicLabel, "rok"),
    ].join(":");
  }

  return [
    "date",
    categoryKey,
    getPeriodicsDateGroupKeyPart(entry.id || entry.searchText || entry.dueDate, "stavka"),
  ].join(":");
}

function getPeriodicsEntryDateValue(entry = {}) {
  const normalizedDate = normalizeDateInputValue(entry?.dueDate || "");
  if (!normalizedDate) {
    return Number.NEGATIVE_INFINITY;
  }
  const timestamp = Date.parse(normalizedDate);
  return Number.isFinite(timestamp) ? timestamp : Number.NEGATIVE_INFINITY;
}

function comparePeriodicsEntriesNewestDate(left = {}, right = {}) {
  const dateDifference = getPeriodicsEntryDateValue(right) - getPeriodicsEntryDateValue(left);
  if (dateDifference !== 0) {
    return dateDifference;
  }

  return String(right?.freshnessKey || right?.id || "").localeCompare(
    String(left?.freshnessKey || left?.id || ""),
    "hr",
    { numeric: true },
  );
}

function comparePeriodicsEntriesByDueDate(left = {}, right = {}) {
  return (
    String(left?.dueDate || "9999-12-31").localeCompare(String(right?.dueDate || "9999-12-31"))
    || String(left?.searchText || left?.id || "").localeCompare(String(right?.searchText || right?.id || ""), "hr", {
      numeric: true,
      sensitivity: "base",
    })
  );
}

function buildPeriodicsCurrentDateEntries(entries = [], category = "periodika") {
  const groups = new Map();
  (Array.isArray(entries) ? entries : []).forEach((entry, index) => {
    const key = createPeriodicsDateGroupKey(entry, category);
    const current = groups.get(key) || {
      key,
      items: [],
    };
    current.items.push({
      ...entry,
      periodicsOriginalIndex: index,
    });
    groups.set(key, current);
  });

  return Array.from(groups.values())
    .map((group) => {
      const sortedItems = group.items.slice().sort(comparePeriodicsEntriesNewestDate);
      const [primaryEntry, ...otherEntries] = sortedItems;
      return {
        ...primaryEntry,
        periodicsDateGroupKey: group.key,
        periodicsDateGroupCount: sortedItems.length,
        periodicsOtherDateEntries: otherEntries
          .slice()
          .sort(comparePeriodicsEntriesNewestDate)
          .map((entry) => ({
            ...entry,
            periodicsDateGroupKey: group.key,
            periodicsDateGroupCount: sortedItems.length,
            periodicsOtherDateEntries: [],
            periodicsIsOtherDate: true,
          })),
      };
    })
    .filter(Boolean)
    .sort(comparePeriodicsEntriesByDueDate);
}

function formatPeriodicsOtherDateCount(count = 0) {
  const normalizedCount = Number(count || 0);
  return normalizedCount === 1 ? "još 1 datum" : `još ${normalizedCount} datuma`;
}

function createPeriodicsDateExpandRow(entry = {}) {
  const otherEntries = Array.isArray(entry?.periodicsOtherDateEntries)
    ? entry.periodicsOtherDateEntries
    : [];
  const groupKey = String(entry?.periodicsDateGroupKey || "").trim();
  if (!groupKey || otherEntries.length === 0) {
    return null;
  }

  const expanded = isPeriodicsDateGroupExpanded(groupKey);
  const row = document.createElement("article");
  row.className = "periodics-grid-row periodics-date-expand-row";
  row.dataset.preventRowOpen = "true";

  const cell = document.createElement("div");
  cell.className = "periodics-date-expand-cell";

  const button = document.createElement("button");
  button.type = "button";
  button.className = "periodics-date-expand-button";
  button.setAttribute("aria-expanded", String(expanded));
  button.textContent = expanded
    ? "Sakrij ostale datume"
    : `Prikaži ${formatPeriodicsOtherDateCount(otherEntries.length)}`;
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    togglePeriodicsDateGroupExpansion(groupKey);
  });

  const meta = document.createElement("span");
  meta.className = "periodics-date-expand-meta";
  meta.textContent = entry?.dueDate
    ? `Aktualno prikazano ${formatCompactDate(entry.dueDate)}`
    : "Aktualni rok je prikazan iznad";

  cell.append(button, meta);
  row.append(cell);
  return row;
}

function createPeriodicsDateRows(entry = {}, renderRow) {
  const primaryRow = renderRow(entry);
  primaryRow.classList.add("periodics-current-date-row");

  const rows = [primaryRow];
  const expandRow = createPeriodicsDateExpandRow(entry);
  if (!expandRow) {
    return rows;
  }

  rows.push(expandRow);
  if (isPeriodicsDateGroupExpanded(entry.periodicsDateGroupKey)) {
    const otherRows = (entry.periodicsOtherDateEntries ?? []).map((otherEntry) => {
      const row = renderRow(otherEntry);
      row.classList.add("periodics-other-date-row");
      return row;
    });
    rows.push(...otherRows);
  }

  return rows;
}

function getPeriodicsInspectionNestedGroupKey(parentKey = "", type = "location", id = "", title = "") {
  return [
    String(parentKey || "").trim(),
    type,
    String(id || "").trim() || normalizeDocumentsExplorerKey(title) || "bez-naziva",
  ].join(":");
}

function sortPeriodicsInspectionHierarchyEntries(left = {}, right = {}) {
  return (
    String(left.locationName || "").localeCompare(String(right.locationName || ""), "hr", { numeric: true })
    || String(left.objectName || "").localeCompare(String(right.objectName || ""), "hr", { numeric: true })
    || String(left.dueDate || "9999-12-31").localeCompare(String(right.dueDate || "9999-12-31"))
    || String(left.serviceLabel || "").localeCompare(String(right.serviceLabel || ""), "hr", { numeric: true })
    || String(left.workOrderNumber || "").localeCompare(String(right.workOrderNumber || ""), "hr", { numeric: true })
  );
}

function buildPeriodicsInspectionNestedGroups(entries = [], parentKey = "", type = "location") {
  const groups = new Map();
  (Array.isArray(entries) ? entries : []).forEach((entry) => {
    const isLocation = type === "location";
    const id = isLocation ? entry.locationId : entry.objectId;
    const title = String(isLocation ? (entry.locationName || "Bez lokacije") : (entry.objectName || "Bez objekta")).trim()
      || (isLocation ? "Bez lokacije" : "Bez objekta");
    const key = getPeriodicsInspectionNestedGroupKey(parentKey, type, id, title);
    const current = groups.get(key) || {
      key,
      type,
      title,
      items: [],
    };
    current.items.push(entry);
    groups.set(key, current);
  });

  return Array.from(groups.values())
    .map((group) => ({
      ...group,
      ...summarizePeriodicsInspectionEntries(group.items),
      items: group.items.slice().sort(sortPeriodicsInspectionHierarchyEntries),
    }))
    .sort((left, right) => (
      String(left.title || "").localeCompare(String(right.title || ""), "hr", { numeric: true })
      || String(left.nextDueDate || "9999-12-31").localeCompare(String(right.nextDueDate || "9999-12-31"))
    ));
}

function createPeriodicsInspectionSubgroupCell(group = {}, expanded = false, type = "location") {
  const cell = document.createElement("div");
  cell.className = `periodics-cell periodics-subgroup-cell is-${type}`;

  const titleLine = document.createElement("div");
  titleLine.className = "periodics-subgroup-title-line";
  const alertDot = createPeriodicsGroupAlertDot(group);
  if (alertDot) {
    titleLine.append(alertDot);
  }

  const title = document.createElement("strong");
  title.className = "periodics-subgroup-title";
  title.textContent = `${expanded ? "v" : ">"} ${group.title || (type === "location" ? "Bez lokacije" : "Bez objekta")}`;
  titleLine.append(title);

  const meta = document.createElement("span");
  meta.className = "periodics-cell-secondary";
  meta.textContent = [
    `${Number(group.count || 0)} ${Number(group.count || 0) === 1 ? "ispitivanje" : "ispitivanja"}`,
    Number(group.overdueCount || 0) > 0 ? `${group.overdueCount} isteklo` : "",
  ].filter(Boolean).join(" · ");

  cell.append(titleLine, meta);
  return cell;
}

function createPeriodicsInspectionSubgroupRow(group = {}, type = "location") {
  const expanded = isPeriodicsInspectionGroupExpanded(group.key);
  const countLabel = `${Number(group.count || 0)} ${Number(group.count || 0) === 1 ? "stavka" : "stavki"}`;
  const summaryCell = createPeriodicsCell(countLabel);
  summaryCell.classList.add("periodics-subgroup-summary-cell");
  const dueCell = createPeriodicsDueCell(group.nextDueDate || "", group.nextDueState || {});

  const cells = type === "location"
    ? [
      createPeriodicsBlankCell(),
      createPeriodicsBlankCell(),
      createPeriodicsBlankCell(),
      createPeriodicsInspectionSubgroupCell(group, expanded, type),
      createPeriodicsBlankCell(),
      summaryCell,
      dueCell,
    ]
    : [
      createPeriodicsBlankCell(),
      createPeriodicsBlankCell(),
      createPeriodicsBlankCell(),
      createPeriodicsBlankCell(),
      createPeriodicsInspectionSubgroupCell(group, expanded, type),
      summaryCell,
      dueCell,
    ];

  const row = createPeriodicsRow(cells, getPeriodicsInspectionGroupToneClass(group));
  row.classList.add("periodics-subgroup-row", `is-${type}`);
  row.tabIndex = 0;
  row.setAttribute("role", "button");
  row.setAttribute("aria-expanded", String(expanded));
  row.setAttribute("title", expanded ? "Klikni za sazimanje grupe." : "Klikni za prikaz stavki u grupi.");

  const toggleGroup = () => {
    togglePeriodicsInspectionGroupExpansion(group.key);
  };
  row.addEventListener("click", toggleGroup);
  row.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      toggleGroup();
    }
  });

  return bindPeriodicsInspectionWorkOrderContext(row, group.items);
}

function createPeriodicsInspectionRow(entry = {}, { detail = false, hideLocation = false, hideObject = false } = {}) {
  const row = detail
    ? createPeriodicsRow([
      createPeriodicsBlankCell(),
      createPeriodicsBlankCell(),
      createPeriodicsBlankCell(),
      hideLocation ? createPeriodicsBlankCell() : createPeriodicsCell(entry.locationName || "Bez lokacije"),
      hideObject ? createPeriodicsBlankCell() : createPeriodicsCell(entry.objectName || "Bez objekta", "", { dimmed: !entry.objectName }),
      createPeriodicsInspectionServiceCell(entry),
      createPeriodicsDueCell(entry.dueDate, entry.dueState),
    ], entry.dueState?.toneClass)
    : createPeriodicsRow([
      createPeriodicsCell(entry.companyName),
      createPeriodicsCell(entry.headquarters || "—", "", { dimmed: !entry.headquarters }),
      createPeriodicsCell(entry.companyOib || "—", "", { dimmed: !entry.companyOib }),
      createPeriodicsCell(entry.locationName || "Bez lokacije"),
      createPeriodicsCell(entry.objectName || "Bez objekta", "", { dimmed: !entry.objectName }),
      createPeriodicsInspectionServiceCell(entry),
      createPeriodicsDueCell(entry.dueDate, entry.dueState),
    ], entry.dueState?.toneClass);
  if (detail) {
    row.classList.add("periodics-detail-row");
  }
  return bindPeriodicsInspectionWorkOrderContext(row, [entry]);
}

function createPeriodicsInspectionDateRows(entry = {}, options = {}) {
  return createPeriodicsDateRows(entry, (rowEntry) => createPeriodicsInspectionRow(rowEntry, options));
}

function createPeriodicsInspectionObjectRows(objectGroup = {}, { hideLocation = true } = {}) {
  if (Number(objectGroup.count || 0) > 1) {
    const expanded = isPeriodicsInspectionGroupExpanded(objectGroup.key);
    return [
      createPeriodicsInspectionSubgroupRow(objectGroup, "object"),
      ...(expanded
        ? objectGroup.items.flatMap((entry) => createPeriodicsInspectionDateRows(entry, {
          detail: true,
          hideLocation,
          hideObject: true,
        }))
        : []),
    ];
  }

  return objectGroup.items.flatMap((entry) => createPeriodicsInspectionDateRows(entry, {
    detail: true,
    hideLocation,
  }));
}

function createPeriodicsInspectionLocationRows(locationGroup = {}) {
  if (Number(locationGroup.count || 0) > 1) {
    const expanded = isPeriodicsInspectionGroupExpanded(locationGroup.key);
    const rows = [createPeriodicsInspectionSubgroupRow(locationGroup, "location")];
    if (!expanded) {
      return rows;
    }

    const objectGroups = buildPeriodicsInspectionNestedGroups(locationGroup.items, locationGroup.key, "object");
    return [
      ...rows,
      ...objectGroups.flatMap((objectGroup) => createPeriodicsInspectionObjectRows(objectGroup, { hideLocation: true })),
    ];
  }

  return locationGroup.items.flatMap((entry) => createPeriodicsInspectionDateRows(entry, { detail: true }));
}

function createPeriodicsInspectionCompanyRows(group = {}) {
  const expanded = isPeriodicsInspectionGroupExpanded(group.key);
  const rows = [createPeriodicsInspectionGroupRow(group)];
  if (!expanded) {
    return rows;
  }

  const locationGroups = buildPeriodicsInspectionNestedGroups(group.items, group.key, "location");
  rows.push(...locationGroups.flatMap((locationGroup) => createPeriodicsInspectionLocationRows(locationGroup)));
  return rows;
}

function createPeriodicsInspectionRows(entries = [], groupMode = "location-object") {
  const mode = normalizePeriodicsInspectionGroupMode(groupMode);
  if (mode === "item") {
    return entries.flatMap((entry) => createPeriodicsInspectionDateRows(entry));
  }

  const groups = new Map();
  (Array.isArray(entries) ? entries : []).forEach((entry) => {
    const meta = getPeriodicsInspectionGroupMeta(entry, mode);
    const current = groups.get(meta.key) || { ...meta, items: [], count: 0, nextDueDate: "", nextDueState: null };
    current.items.push(entry);
    current.count += 1;
    if (entry.dueDate && (!current.nextDueDate || entry.dueDate < current.nextDueDate)) {
      current.nextDueDate = entry.dueDate;
      current.nextDueState = entry.dueState || null;
    }
    groups.set(meta.key, current);
  });

  return Array.from(groups.values())
    .map((group) => ({
      ...group,
      ...summarizePeriodicsInspectionEntries(group.items),
      items: group.items.slice().sort(sortPeriodicsInspectionHierarchyEntries),
    }))
    .sort((left, right) => (
      String(left.companyName || left.title || "").localeCompare(String(right.companyName || right.title || ""), "hr")
      || String(left.nextDueDate || "9999-12-31").localeCompare(String(right.nextDueDate || "9999-12-31"))
    ))
    .flatMap((group) => createPeriodicsInspectionCompanyRows(group));
}

function renderPeriodicsRows(target, rows = []) {
  if (!target) {
    return;
  }
  target.replaceChildren(...rows);
}

function syncPeriodicsSectionToggle(button, body, heading, collapsed = false, title = "sekciju") {
  if (body) {
    body.hidden = collapsed;
    const hostCard = body.closest(".periodics-section-card");
    hostCard?.classList.toggle("is-collapsed", collapsed);
  }
  const expanded = !collapsed;
  if (heading) {
    heading.classList.toggle("is-collapsed", collapsed);
    heading.setAttribute("aria-expanded", String(expanded));
  }
  if (!button) {
    return;
  }
  button.textContent = expanded ? "−" : "+";
  button.setAttribute("aria-expanded", String(expanded));
  button.setAttribute("aria-label", expanded ? `Sakrij ${title}` : `Prikaži ${title}`);
}

function togglePeriodicsSection(sectionKey = "") {
  if (!Object.prototype.hasOwnProperty.call(state.periodicsSections, sectionKey)) {
    return;
  }
  state.periodicsSections[sectionKey] = !state.periodicsSections[sectionKey];
  syncPeriodicsSections();
}

function bindPeriodicsSectionHeaderToggle(headingNode, toggleButton, sectionKey = "") {
  if (!headingNode) {
    return;
  }
  const shouldSkipHeaderToggle = (target) => {
    if (!(target instanceof Element)) {
      return false;
    }
    const interactiveAncestor = target.closest("button, a, input, select, textarea, [role='button']");
    return Boolean(interactiveAncestor && interactiveAncestor !== headingNode);
  };
  headingNode.addEventListener("click", (event) => {
    if (shouldSkipHeaderToggle(event.target)) {
      return;
    }
    togglePeriodicsSection(sectionKey);
  });
  headingNode.addEventListener("keydown", (event) => {
    if (shouldSkipHeaderToggle(event.target)) {
      return;
    }
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }
    event.preventDefault();
    togglePeriodicsSection(sectionKey);
  });
  toggleButton?.addEventListener("click", (event) => {
    event.stopPropagation();
    togglePeriodicsSection(sectionKey);
  });
}

function syncPeriodicsSections() {
  syncPeriodicsSectionToggle(
    periodicsInspectionPeriodicsToggleButton,
    periodicsInspectionPeriodicsBody,
    periodicsInspectionPeriodicsHeading,
    Boolean(state.periodicsSections.inspectionPeriodicsCollapsed),
    "periodiku ispitivanja",
  );
  syncPeriodicsSectionToggle(
    periodicsVehiclesToggleButton,
    periodicsVehiclesBody,
    periodicsVehiclesHeading,
    Boolean(state.periodicsSections.vehiclesCollapsed),
    "blok vozila",
  );
  syncPeriodicsSectionToggle(
    periodicsPeopleToggleButton,
    periodicsPeopleBody,
    periodicsPeopleHeading,
    Boolean(state.periodicsSections.peopleCollapsed),
    "blok ljudi",
  );
  syncPeriodicsSectionToggle(
    periodicsEquipmentToggleButton,
    periodicsEquipmentBody,
    periodicsEquipmentHeading,
    Boolean(state.periodicsSections.equipmentCollapsed),
    "blok mjerne opreme",
  );
}

function normalizePeriodicsViewMode(mode = state.periodicsViewMode) {
  return String(mode || "").trim().toLowerCase() === "calendar" ? "calendar" : "list";
}

function normalizePeriodicsCalendarDisplayMode(mode = state.periodicsCalendar?.displayMode) {
  return String(mode || "").trim().toLowerCase() === "week" ? "week" : "month";
}

function normalizePeriodicsCalendarSelectedDate(
  value = state.periodicsCalendar?.selectedDate,
  {
    allowEmpty = true,
    fallback = "",
  } = {},
) {
  const normalizedValue = String(value || "").trim();
  if (!normalizedValue) {
    return allowEmpty ? "" : getPeriodicsCalendarAnchorDate(fallback || state.periodicsCalendar?.anchorDate);
  }

  const parsedDate = parseDateValue(normalizedValue);
  if (!parsedDate) {
    return allowEmpty ? "" : getPeriodicsCalendarAnchorDate(fallback || state.periodicsCalendar?.anchorDate);
  }

  parsedDate.setHours(0, 0, 0, 0);
  return toDateKey(parsedDate);
}

function normalizePeriodicsCalendarVisibility(value = state.periodicsCalendar?.visibility) {
  const source = value && typeof value === "object" ? value : {};
  return {
    inspections: source.inspections !== false,
    vehicles: source.vehicles !== false,
    people: source.people !== false,
    equipment: source.equipment !== false,
    absences: source.absences !== false,
  };
}

function areAllPeriodicsCalendarServiceFiltersEnabled(
  visibility = normalizePeriodicsCalendarVisibility(state.periodicsCalendar?.visibility),
) {
  return PERIODICS_CALENDAR_SERVICE_CATEGORY_KEYS.every((key) => visibility[key] !== false);
}

function getPeriodicsCalendarAnchorDate(value = state.periodicsCalendar?.anchorDate) {
  const parsedDate = parseDateValue(value);
  if (!parsedDate) {
    return toDateKey(new Date());
  }

  parsedDate.setHours(0, 0, 0, 0);
  return toDateKey(parsedDate);
}

function getPeriodicsCalendarWeekStart(value = state.periodicsCalendar?.anchorDate) {
  const parsedDate = parseDateValue(getPeriodicsCalendarAnchorDate(value));
  if (!parsedDate) {
    return toDateKey(new Date());
  }

  const mondayOffset = (parsedDate.getDay() + 6) % 7;
  parsedDate.setDate(parsedDate.getDate() - mondayOffset);
  parsedDate.setHours(0, 0, 0, 0);
  return toDateKey(parsedDate);
}

function matchesPeriodicsSearchFilter(entry = {}, queryNeedle = "") {
  if (!queryNeedle) {
    return true;
  }

  const haystack = normalizeLooseName(entry?.searchText || "");
  return haystack.includes(queryNeedle);
}

function createPeriodicsCalendarBaseDay(key = "", { inMonth = true, isToday = false } = {}) {
  const parsedDate = parseDateValue(key);
  const dayIndex = parsedDate ? parsedDate.getDay() : -1;
  return {
    key,
    inMonth,
    isToday,
    dayIndex,
    isWeekend: dayIndex === 0 || dayIndex === 6,
    dueItems: [],
    absenceItems: [],
  };
}

function buildPeriodicsCalendarWeekStructure(anchorDate = state.periodicsCalendar?.anchorDate) {
  const weekStart = getPeriodicsCalendarWeekStart(anchorDate);
  const todayKey = toDateKey(new Date());
  const days = Array.from({ length: 7 }, (_, index) => {
    const key = shiftDateKey(weekStart, index);
    return createPeriodicsCalendarBaseDay(key, {
      inMonth: true,
      isToday: key === todayKey,
    });
  });

  return {
    anchorDate: getPeriodicsCalendarAnchorDate(anchorDate),
    weekStart,
    weekEnd: shiftDateKey(weekStart, 6),
    days,
  };
}

function buildPeriodicsCalendarMonthStructure(anchorDate = state.periodicsCalendar?.anchorDate) {
  const safeAnchorDate = getPeriodicsCalendarAnchorDate(anchorDate);
  const monthStart = `${safeAnchorDate.slice(0, 7)}-01`;
  const monthStartDate = parseDateValue(monthStart) || new Date();
  const monthEndDate = new Date(monthStartDate.getFullYear(), monthStartDate.getMonth() + 1, 0);
  const monthEnd = toDateKey(monthEndDate);
  const displayStart = getPeriodicsCalendarWeekStart(monthStart);
  const displayEnd = shiftDateKey(getPeriodicsCalendarWeekStart(monthEnd), 6);
  const todayKey = toDateKey(new Date());
  const weeks = [];

  for (let cursor = displayStart; cursor <= displayEnd; cursor = shiftDateKey(cursor, 7)) {
    const days = Array.from({ length: 7 }, (_, index) => {
      const key = shiftDateKey(cursor, index);
      return createPeriodicsCalendarBaseDay(key, {
        inMonth: key >= monthStart && key <= monthEnd,
        isToday: key === todayKey,
      });
    });

    weeks.push({
      key: cursor,
      weekStart: cursor,
      days,
    });
  }

  return {
    anchorDate: safeAnchorDate,
    monthStart,
    monthEnd,
    displayStart,
    displayEnd,
    weeks,
  };
}

function createPeriodicsCalendarDueItem(entry = {}, category = "inspections") {
  const categoryConfig = PERIODICS_CALENDAR_CATEGORY_CONFIG[category] || PERIODICS_CALENDAR_CATEGORY_CONFIG.inspections;
  let title = categoryConfig.label;
  let subtitle = "";
  let detail = "";

  if (category === "inspections") {
    title = entry.companyName || "Ispitivanje";
    subtitle = [entry.locationName, entry.serviceLabel].filter(Boolean).join(" · ");
    detail = [entry.templateLabel, entry.workOrderNumber ? `RN ${entry.workOrderNumber}` : ""].filter(Boolean).join(" · ");
  } else if (category === "vehicles") {
    title = entry.vehicleName || "Vozilo";
    subtitle = [entry.periodicLabel, entry.plateNumber || "Bez registracije"].filter(Boolean).join(" · ");
    detail = [entry.detail, entry.vinNumber ? `Sasija ${entry.vinNumber}` : ""].filter(Boolean).join(" · ");
  } else if (category === "people") {
    title = entry.userName || "Korisnik";
    subtitle = [entry.areaLabel, entry.qualificationLabel].filter(Boolean).join(" · ");
    detail = entry.userEmail || "";
  } else if (category === "equipment") {
    title = entry.equipmentName || "Oprema";
    subtitle = [entry.kindLabel, entry.periodicLabel].filter(Boolean).join(" · ");
    detail = [entry.detail, entry.codeSummary].filter(Boolean).join(" · ");
  }

  return {
    id: String(entry.id || createClientSideId("periodics-calendar-due")),
    kind: "due",
    category,
    categoryLabel: categoryConfig.label,
    categoryClassName: categoryConfig.className,
    startDate: String(entry.dueDate || "").trim(),
    endDate: String(entry.dueDate || "").trim(),
    dueDate: String(entry.dueDate || "").trim(),
    dueState: entry.dueState || {},
    title: String(title || categoryConfig.label).trim() || categoryConfig.label,
    subtitle: String(subtitle || "").trim(),
    detail: String(detail || "").trim(),
    searchText: String(entry.searchText || "").trim(),
  };
}

function buildPeriodicsCalendarAbsenceItems(query = state.periodicsFilters.query || "") {
  const queryNeedle = normalizeLooseName(query || "");
  const activeOrganizationId = String(state.activeOrganizationId || "").trim();
  const activeUsers = activeOrganizationId ? getActiveOrganizationUsers() : (state.users ?? []);
  const allowedUserIds = new Set(
    activeUsers
      .map((user) => String(user?.id || "").trim())
      .filter(Boolean),
  );

  return getApprovedAbsenceEntries()
    .filter((entry) => {
      if (!activeOrganizationId) {
        return true;
      }

      const userId = String(entry?.userId || "").trim();
      return !userId || allowedUserIds.has(userId);
    })
    .map((entry) => {
      const linkedUser = activeUsers.find((user) => String(user?.id || "") === String(entry?.userId || ""))
        || state.users.find((user) => String(user?.id || "") === String(entry?.userId || ""))
        || null;
      const userLabel = String(
        entry?.userLabel
        || getUserDocumentDisplayName(linkedUser)
        || linkedUser?.email
        || "Odsutnost",
      ).trim() || "Odsutnost";
      const typeKey = String(entry?.type || "").trim().toLowerCase();
      const startDate = String(entry?.startDate || "").trim();
      const endDate = String(entry?.endDate || startDate).trim();
      const normalizedEntry = {
        ...entry,
        userLabel,
      };
      return {
        id: `periodics-calendar-absence-${String(entry?.id || createClientSideId("absence"))}`,
        kind: "absence",
        category: "absence",
        toneClass: ABSENCE_CALENDAR_BADGE_TONES[typeKey] || "is-other",
        startDate,
        endDate,
        title: userLabel,
        subtitle: getAbsenceTypeLabelClient(typeKey),
        searchText: [
          userLabel,
          linkedUser?.email || "",
          getAbsenceTypeLabelClient(typeKey),
          String(entry?.note || "").trim(),
        ].filter(Boolean).join(" "),
        rawEntry: normalizedEntry,
      };
    })
    .filter((entry) => entry.startDate && matchesPeriodicsSearchFilter(entry, queryNeedle))
    .sort((left, right) => (
      String(left.startDate || "").localeCompare(String(right.startDate || ""))
      || String(left.title || "").localeCompare(String(right.title || ""), "hr")
    ));
}

function buildPeriodicsCalendarData({
  inspectionEntries = [],
  vehicleEntries = [],
  peopleEntries = [],
  equipmentEntries = [],
  query = state.periodicsFilters.query || "",
  visibility = state.periodicsCalendar?.visibility,
} = {}) {
  const queryNeedle = normalizeLooseName(query || "");
  const safeVisibility = normalizePeriodicsCalendarVisibility(visibility);
  const dueItems = [
    ...(Array.isArray(inspectionEntries) ? inspectionEntries : []).map((entry) => createPeriodicsCalendarDueItem(entry, "inspections")),
    ...(Array.isArray(vehicleEntries) ? vehicleEntries : []).map((entry) => createPeriodicsCalendarDueItem(entry, "vehicles")),
    ...(Array.isArray(peopleEntries) ? peopleEntries : []).map((entry) => createPeriodicsCalendarDueItem(entry, "people")),
    ...(Array.isArray(equipmentEntries) ? equipmentEntries : []).map((entry) => createPeriodicsCalendarDueItem(entry, "equipment")),
  ]
    .filter((entry) => (
      entry.startDate
      && safeVisibility[String(entry.category || "").trim()] !== false
      && matchesPeriodicsSearchFilter(entry, queryNeedle)
    ))
    .sort((left, right) => (
      String(left.startDate || "").localeCompare(String(right.startDate || ""))
      || String(left.title || "").localeCompare(String(right.title || ""), "hr")
      || String(left.categoryLabel || "").localeCompare(String(right.categoryLabel || ""), "hr")
    ));

  return {
    dueItems,
    absenceItems: safeVisibility.absences ? buildPeriodicsCalendarAbsenceItems(query) : [],
  };
}

function appendPeriodicsCalendarItemsToDayMap(dayMap = new Map(), {
  dueItems = [],
  absenceItems = [],
  rangeStart = "",
  rangeEnd = "",
} = {}) {
  const safeRangeStart = String(rangeStart || "").trim();
  const safeRangeEnd = String(rangeEnd || safeRangeStart).trim();
  if (!safeRangeStart || !safeRangeEnd) {
    return;
  }

  (Array.isArray(dueItems) ? dueItems : []).forEach((item) => {
    const targetDay = dayMap.get(String(item?.startDate || "").trim());
    if (!targetDay) {
      return;
    }
    targetDay.dueItems.push(item);
  });

  (Array.isArray(absenceItems) ? absenceItems : []).forEach((item) => {
    const startDate = String(item?.startDate || "").trim();
    const endDate = String(item?.endDate || startDate).trim() || startDate;
    if (!startDate) {
      return;
    }

    let cursor = startDate < safeRangeStart ? safeRangeStart : startDate;
    const lastDate = endDate > safeRangeEnd ? safeRangeEnd : endDate;
    while (cursor && cursor <= lastDate) {
      const targetDay = dayMap.get(cursor);
      if (targetDay) {
        targetDay.absenceItems.push(item);
      }
      cursor = shiftDateKey(cursor, 1);
    }
  });

  dayMap.forEach((day) => {
    day.dueItems.sort((left, right) => (
      String(left.categoryLabel || "").localeCompare(String(right.categoryLabel || ""), "hr")
      || String(left.title || "").localeCompare(String(right.title || ""), "hr")
    ));
    day.absenceItems.sort((left, right) => (
      String(left.title || "").localeCompare(String(right.title || ""), "hr")
      || String(left.subtitle || "").localeCompare(String(right.subtitle || ""), "hr")
    ));
  });
}

function getPeriodicsCalendarMetrics(days = []) {
  const dueCount = (Array.isArray(days) ? days : []).reduce((sum, day) => sum + (day?.dueItems?.length || 0), 0);
  const visibleAbsenceIds = new Set();

  (Array.isArray(days) ? days : []).forEach((day) => {
    (day?.absenceItems ?? []).forEach((item) => {
      visibleAbsenceIds.add(String(item?.id || ""));
    });
  });

  return {
    dueCount,
    absenceCount: visibleAbsenceIds.size,
  };
}

function setPeriodicsCalendarServiceVisibility(checked = true) {
  const nextChecked = checked !== false;
  const visibility = normalizePeriodicsCalendarVisibility(state.periodicsCalendar?.visibility);
  PERIODICS_CALENDAR_SERVICE_CATEGORY_KEYS.forEach((key) => {
    visibility[key] = nextChecked;
  });
  state.periodicsCalendar.visibility = visibility;
}

function syncPeriodicsCalendarVisibilityControls() {
  const visibility = normalizePeriodicsCalendarVisibility(state.periodicsCalendar?.visibility);
  const allServicesEnabled = areAllPeriodicsCalendarServiceFiltersEnabled(visibility);
  const someServicesEnabled = PERIODICS_CALENDAR_SERVICE_CATEGORY_KEYS.some((key) => visibility[key] !== false);

  if (periodicsCalendarFilterServices instanceof HTMLInputElement) {
    periodicsCalendarFilterServices.checked = allServicesEnabled;
    periodicsCalendarFilterServices.indeterminate = !allServicesEnabled && someServicesEnabled;
  }
  if (periodicsCalendarFilterInspections instanceof HTMLInputElement) {
    periodicsCalendarFilterInspections.checked = visibility.inspections !== false;
  }
  if (periodicsCalendarFilterVehicles instanceof HTMLInputElement) {
    periodicsCalendarFilterVehicles.checked = visibility.vehicles !== false;
  }
  if (periodicsCalendarFilterPeople instanceof HTMLInputElement) {
    periodicsCalendarFilterPeople.checked = visibility.people !== false;
  }
  if (periodicsCalendarFilterEquipment instanceof HTMLInputElement) {
    periodicsCalendarFilterEquipment.checked = visibility.equipment !== false;
  }
  if (periodicsCalendarFilterAbsences instanceof HTMLInputElement) {
    periodicsCalendarFilterAbsences.checked = visibility.absences !== false;
  }
}

function syncPeriodicsCalendarGridShellHeight() {
  if (!periodicsCalendarGridShell || state.periodicsViewMode !== "calendar") {
    return;
  }

  const viewportHeight = window.visualViewport?.height || window.innerHeight || document.documentElement.clientHeight || 0;
  if (!Number.isFinite(viewportHeight) || viewportHeight <= 0) {
    periodicsCalendarGridShell.style.removeProperty("--periodics-calendar-shell-height");
    return;
  }

  const shellRect = periodicsCalendarGridShell.getBoundingClientRect();
  const visibleTop = Math.max(shellRect.top, window.innerWidth <= 980 ? 10 : 16);
  const bottomGap = window.innerWidth <= 980 ? 16 : 24;
  const availableHeight = Math.floor(viewportHeight - visibleTop - bottomGap);

  if (!Number.isFinite(availableHeight) || availableHeight <= 180) {
    periodicsCalendarGridShell.style.removeProperty("--periodics-calendar-shell-height");
    return;
  }

  periodicsCalendarGridShell.style.setProperty("--periodics-calendar-shell-height", `${availableHeight}px`);
}

function queuePeriodicsCalendarGridShellHeightSync() {
  if (!periodicsCalendarGridShell) {
    return;
  }

  if (periodicsCalendarShellHeightFrame) {
    window.cancelAnimationFrame(periodicsCalendarShellHeightFrame);
  }

  periodicsCalendarShellHeightFrame = window.requestAnimationFrame(() => {
    periodicsCalendarShellHeightFrame = 0;
    syncPeriodicsCalendarGridShellHeight();
  });
}

function bindPeriodicsCalendarGrabScroll() {
  if (!periodicsCalendarGridShell || periodicsCalendarGridShell.dataset.grabBound === "true") {
    return;
  }

  periodicsCalendarGridShell.dataset.grabBound = "true";
  periodicsCalendarGridShell.addEventListener("wheel", (event) => {
    const absDeltaX = Math.abs(event.deltaX);
    const absDeltaY = Math.abs(event.deltaY);
    const horizontalDelta = (event.deltaX || event.deltaY) * 1.1;
    const verticalDelta = event.deltaY * 1.18;
    const hasHorizontalOverflow = periodicsCalendarGridShell.scrollWidth > periodicsCalendarGridShell.clientWidth + 4;
    const hasVerticalOverflow = periodicsCalendarGridShell.scrollHeight > periodicsCalendarGridShell.clientHeight + 4;
    const shouldPanHorizontally = event.shiftKey || absDeltaX > absDeltaY;

    if (shouldPanHorizontally && hasHorizontalOverflow) {
      const nextScrollLeft = periodicsCalendarGridShell.scrollLeft + horizontalDelta;
      const maxScrollLeft = Math.max(0, periodicsCalendarGridShell.scrollWidth - periodicsCalendarGridShell.clientWidth);
      const canConsumeHorizontal = horizontalDelta < 0
        ? periodicsCalendarGridShell.scrollLeft > 0
        : periodicsCalendarGridShell.scrollLeft < maxScrollLeft;

      if (canConsumeHorizontal) {
        event.preventDefault();
        periodicsCalendarGridShell.scrollLeft = Math.max(0, Math.min(nextScrollLeft, maxScrollLeft));
      }
      return;
    }

    if (!hasVerticalOverflow || absDeltaY <= 0) {
      return;
    }

    const nextScrollTop = periodicsCalendarGridShell.scrollTop + verticalDelta;
    const maxScrollTop = Math.max(0, periodicsCalendarGridShell.scrollHeight - periodicsCalendarGridShell.clientHeight);
    const canConsumeVertical = verticalDelta < 0
      ? periodicsCalendarGridShell.scrollTop > 0
      : periodicsCalendarGridShell.scrollTop < maxScrollTop;

    if (!canConsumeVertical) {
      return;
    }

    event.preventDefault();
    periodicsCalendarGridShell.scrollTop = Math.max(0, Math.min(nextScrollTop, maxScrollTop));
  }, { passive: false, capture: true });
}

function createPeriodicsCalendarWeekRail(weekStart = "", visibleDays = []) {
  const rail = document.createElement("div");
  rail.className = "periodics-calendar-week-rail";

  const label = document.createElement("span");
  label.className = "periodics-calendar-week-rail-label";
  label.textContent = "Tjedan";

  const value = document.createElement("strong");
  value.className = "periodics-calendar-week-rail-value";
  value.textContent = String(getCalendarIsoWeekNumber(visibleDays[0]?.key || weekStart || new Date().toISOString().slice(0, 10)));

  rail.append(label, value);
  return rail;
}

function selectPeriodicsCalendarDate(dateKey = "", { toggle = false } = {}) {
  const normalizedDateKey = normalizePeriodicsCalendarSelectedDate(dateKey, {
    allowEmpty: true,
  });

  if (toggle && normalizedDateKey && normalizedDateKey === normalizePeriodicsCalendarSelectedDate(state.periodicsCalendar?.selectedDate)) {
    state.periodicsCalendar.selectedDate = "";
  } else {
    state.periodicsCalendar.selectedDate = normalizedDateKey;
  }

  renderPeriodicsModule();
}

function getPeriodicsCalendarDayEntries(day = {}) {
  return [
    ...(Array.isArray(day?.dueItems) ? day.dueItems : []),
    ...(Array.isArray(day?.absenceItems) ? day.absenceItems : []),
  ];
}

function getPeriodicsCalendarCompactEntryMeta(item = {}) {
  if (item.kind === "absence") {
    return item.subtitle || "Odsutnost";
  }

  return item.dueState?.badgeLabel || "Rok";
}

function createPeriodicsCalendarCompactEntryBlock(item = {}) {
  const block = document.createElement("div");
  block.className = [
    "periodics-calendar-block",
    item.kind === "absence" ? item.toneClass || "is-other" : item.categoryClassName || "",
    item.kind === "due" ? item.dueState?.toneClass || "" : "",
  ].filter(Boolean).join(" ");
  block.title = [
    item.kind === "absence" ? item.subtitle : item.categoryLabel,
    item.title,
    getPeriodicsCalendarCompactEntryMeta(item),
  ].filter(Boolean).join(" · ");

  const label = document.createElement("span");
  label.className = "periodics-calendar-block-label";
  label.textContent = item.title || item.categoryLabel || "Stavka";

  const meta = document.createElement("span");
  meta.className = "periodics-calendar-block-meta";
  meta.textContent = getPeriodicsCalendarCompactEntryMeta(item);

  block.append(label, meta);
  return block;
}

function createPeriodicsCalendarCompactList(day = {}, { maxVisible = PERIODICS_CALENDAR_COMPACT_BLOCK_LIMIT } = {}) {
  const entries = getPeriodicsCalendarDayEntries(day).filter(Boolean);
  if (entries.length === 0) {
    return null;
  }

  const wrap = document.createElement("div");
  wrap.className = "periodics-calendar-block-list";

  entries.slice(0, maxVisible).forEach((item) => {
    wrap.append(createPeriodicsCalendarCompactEntryBlock(item));
  });

  if (entries.length > maxVisible) {
    const more = document.createElement("span");
    more.className = "periodics-calendar-block-more";
    more.textContent = `+ jos ${entries.length - maxVisible}`;
    wrap.append(more);
  }

  return wrap;
}

function createPeriodicsCalendarCategoryTag(label = "", className = "") {
  const tag = document.createElement("span");
  tag.className = ["periodics-calendar-card-tag", className].filter(Boolean).join(" ");
  tag.textContent = label || "Stavka";
  return tag;
}

function createPeriodicsCalendarDueBadge(dueState = {}) {
  const badge = document.createElement("span");
  badge.className = `periodics-due-pill ${String(dueState?.toneClass || "is-unknown")}`;
  if (String(dueState?.toneClass || "") === "is-overdue") {
    badge.classList.add("has-pulse-alert");
  } else if (String(dueState?.toneClass || "") === "is-warning") {
    badge.classList.add("has-pulse-warning");
  }
  badge.textContent = dueState?.badgeLabel || "Rok";
  return badge;
}

function createPeriodicsCalendarDueCard(item = {}) {
  const card = document.createElement("article");
  card.className = [
    "work-order-calendar-card",
    "periodics-calendar-card",
    "is-static",
    item.categoryClassName,
    item.dueState?.toneClass || "",
  ].filter(Boolean).join(" ");
  card.title = [
    item.categoryLabel,
    item.title,
    item.subtitle,
    item.detail,
    item.dueDate ? `Rok ${formatCompactDate(item.dueDate)}` : "",
  ].filter(Boolean).join(" · ");

  const top = document.createElement("div");
  top.className = "work-order-calendar-card-top";
  top.append(
    createPeriodicsCalendarCategoryTag(item.categoryLabel, item.categoryClassName),
    createPeriodicsCalendarDueBadge(item.dueState),
  );

  const title = document.createElement("strong");
  title.className = "work-order-calendar-card-title";
  title.textContent = item.title || item.categoryLabel || "Stavka";

  const subtitle = document.createElement("span");
  subtitle.className = "work-order-calendar-card-meta";
  subtitle.textContent = item.subtitle || item.categoryLabel || "";

  const detail = document.createElement("span");
  detail.className = "periodics-calendar-card-detail";
  detail.textContent = item.detail || "";
  detail.hidden = !detail.textContent;

  const footer = document.createElement("div");
  footer.className = "work-order-calendar-card-footer";

  const dueDate = document.createElement("span");
  dueDate.className = "periodics-calendar-card-date";
  dueDate.textContent = item.dueDate ? `Rok ${formatCompactDate(item.dueDate)}` : "Bez roka";

  footer.append(dueDate);
  card.append(top, title, subtitle);
  if (!detail.hidden) {
    card.append(detail);
  }
  card.append(footer);
  return card;
}

function createPeriodicsCalendarAbsenceCard(item = {}) {
  const card = document.createElement("article");
  card.className = [
    "work-order-calendar-card",
    "periodics-calendar-card",
    "is-static",
    "is-absence",
    item.toneClass || "is-other",
  ].filter(Boolean).join(" ");

  const top = document.createElement("div");
  top.className = "work-order-calendar-card-top";
  top.append(
    createPeriodicsCalendarCategoryTag(item.subtitle || "Odsutnost", item.toneClass || "is-other"),
  );

  const title = document.createElement("strong");
  title.className = "work-order-calendar-card-title";
  title.textContent = item.title || "Odsutnost";

  const subtitle = document.createElement("span");
  subtitle.className = "work-order-calendar-card-meta";
  subtitle.textContent = item.subtitle || "Odsutnost";

  const detail = document.createElement("span");
  detail.className = "periodics-calendar-card-detail";
  detail.textContent = item.startDate
    ? (
      item.endDate && item.endDate !== item.startDate
        ? `${formatCompactDate(item.startDate)} - ${formatCompactDate(item.endDate)}`
        : formatCompactDate(item.startDate)
    )
    : "Bez datuma";

  card.append(top, title, subtitle, detail);
  return card;
}

function createPeriodicsCalendarDetailSection(titleText = "", items = [], renderItem) {
  const safeItems = (Array.isArray(items) ? items : []).filter(Boolean);
  if (safeItems.length === 0 || typeof renderItem !== "function") {
    return null;
  }

  const section = document.createElement("section");
  section.className = "periodics-calendar-detail-section";

  const head = document.createElement("div");
  head.className = "periodics-calendar-detail-section-head";

  const title = document.createElement("strong");
  title.textContent = titleText || "Stavke";
  head.append(title);

  const list = document.createElement("div");
  list.className = "periodics-calendar-detail-card-list";
  safeItems.forEach((item) => {
    list.append(renderItem(item));
  });

  section.append(head, list);
  return section;
}

function renderPeriodicsCalendarDetailPanel(dayMap = new Map(), {
  visibleRangeStart = "",
  visibleRangeEnd = "",
} = {}) {
  if (!periodicsCalendarDetailPanel || !periodicsCalendarDetailList) {
    return;
  }

  const selectedDate = normalizePeriodicsCalendarSelectedDate(state.periodicsCalendar?.selectedDate, {
    allowEmpty: true,
  });

  if (!selectedDate || !dayMap.has(selectedDate)) {
    periodicsCalendarDetailPanel.hidden = true;
    periodicsCalendarDetailList.replaceChildren();
    if (periodicsCalendarDetailEmpty) {
      periodicsCalendarDetailEmpty.hidden = true;
    }
    return;
  }

  const day = dayMap.get(selectedDate);
  const visibleStart = String(visibleRangeStart || "").trim();
  const visibleEnd = String(visibleRangeEnd || visibleStart).trim();
  if ((visibleStart && selectedDate < visibleStart) || (visibleEnd && selectedDate > visibleEnd)) {
    periodicsCalendarDetailPanel.hidden = true;
    periodicsCalendarDetailList.replaceChildren();
    if (periodicsCalendarDetailEmpty) {
      periodicsCalendarDetailEmpty.hidden = true;
    }
    return;
  }

  const fullDateLabel = new Intl.DateTimeFormat("hr-HR", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  }).format(parseDateValue(selectedDate));

  if (periodicsCalendarDetailTitle) {
    periodicsCalendarDetailTitle.textContent = fullDateLabel;
  }
  if (periodicsCalendarDetailMeta) {
    const summary = [
      day.dueItems.length > 0 ? "Usluge i rokovi" : "",
      day.absenceItems.length > 0 ? "Odsutnosti" : "",
    ].filter(Boolean).join(" · ");
    periodicsCalendarDetailMeta.textContent = summary || "Nema evidentiranih događaja za odabrani datum.";
  }

  const sections = [
    createPeriodicsCalendarDetailSection("Periodika", day.dueItems, (item) => createPeriodicsCalendarDueCard(item)),
    createPeriodicsCalendarDetailSection("Odsutnosti", day.absenceItems, (item) => createPeriodicsCalendarAbsenceCard(item)),
  ].filter(Boolean);

  periodicsCalendarDetailList.replaceChildren(...sections);
  if (periodicsCalendarDetailEmpty) {
    periodicsCalendarDetailEmpty.hidden = sections.length > 0;
  }
  periodicsCalendarDetailPanel.hidden = false;
}

function createPeriodicsCalendarDayCell(day = {}) {
  const cell = document.createElement("article");
  cell.className = "work-order-calendar-month-day periodics-calendar-day";
  cell.classList.toggle("is-today", Boolean(day.isToday));
  cell.classList.toggle("is-outside-month", day.inMonth === false);
  cell.classList.toggle("is-weekend", Boolean(day.isWeekend));
  cell.classList.toggle(
    "is-selected",
    normalizePeriodicsCalendarSelectedDate(state.periodicsCalendar?.selectedDate, { allowEmpty: true }) === day.key,
  );
  cell.dataset.date = day.key;
  cell.tabIndex = 0;
  cell.setAttribute("role", "button");
  cell.setAttribute("aria-label", `Prikaži detalje za ${formatCompactDate(day.key)}`);
  cell.addEventListener("click", () => {
    selectPeriodicsCalendarDate(day.key, { toggle: false });
  });
  cell.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }
    event.preventDefault();
    selectPeriodicsCalendarDate(day.key, { toggle: false });
  });

  const top = document.createElement("div");
  top.className = "work-order-calendar-month-day-top";

  const copy = document.createElement("div");
  copy.className = "work-order-calendar-month-day-copy";

  const label = document.createElement("span");
  label.className = "work-order-calendar-day-label";
  label.textContent = new Intl.DateTimeFormat("hr-HR", { weekday: "short" }).format(parseDateValue(day.key));

  const dateStamp = document.createElement("div");
  dateStamp.className = "periodics-calendar-day-stamp";

  const date = document.createElement("strong");
  date.className = "work-order-calendar-day-date";
  date.textContent = String(parseDateValue(day.key)?.getDate?.() ?? day.key.slice(-2));

  const month = document.createElement("span");
  month.className = "periodics-calendar-day-month";
  month.textContent = new Intl.DateTimeFormat("hr-HR", { month: "short" }).format(parseDateValue(day.key));

  const meta = document.createElement("span");
  meta.className = "work-order-calendar-day-meta";
  meta.textContent = [
    day.dueItems.length > 0 ? "Usluge" : "",
    day.absenceItems.length > 0 ? "Odsutnosti" : "",
  ].filter(Boolean).join(" · ");
  meta.hidden = !meta.textContent;

  dateStamp.append(date, month);
  copy.append(label, meta);
  top.append(copy, dateStamp);

  const body = document.createElement("div");
  body.className = "work-order-calendar-month-day-body periodics-calendar-day-body";

  const compactList = createPeriodicsCalendarCompactList(day, {
    maxVisible: PERIODICS_CALENDAR_COMPACT_BLOCK_LIMIT,
  });
  if (compactList) {
    body.append(compactList);
  }

  cell.append(top, body);
  return cell;
}

function syncPeriodicsViewState() {
  const viewMode = normalizePeriodicsViewMode(state.periodicsViewMode);
  const isCalendarMode = viewMode === "calendar";

  periodicsModule?.classList.toggle("is-calendar-mode", isCalendarMode);

  if (periodicsViewListButton) {
    periodicsViewListButton.classList.toggle("is-active", !isCalendarMode);
    periodicsViewListButton.setAttribute("aria-pressed", !isCalendarMode ? "true" : "false");
  }
  if (periodicsViewCalendarButton) {
    periodicsViewCalendarButton.classList.toggle("is-active", isCalendarMode);
    periodicsViewCalendarButton.setAttribute("aria-pressed", isCalendarMode ? "true" : "false");
  }
  if (periodicsCalendarPanel) {
    periodicsCalendarPanel.hidden = !isCalendarMode;
  }
  if (periodicsListView) {
    periodicsListView.hidden = isCalendarMode;
  }
  if (periodicsHorizonField) {
    periodicsHorizonField.hidden = isCalendarMode;
  }
  if (periodicsHelper) {
    periodicsHelper.hidden = isCalendarMode;
  }
}

function syncPeriodicsCalendarToolbar() {
  const displayMode = normalizePeriodicsCalendarDisplayMode(state.periodicsCalendar?.displayMode);
  const showWeekends = Boolean(state.periodicsCalendar?.showWeekends);
  syncPeriodicsCalendarVisibilityControls();

  if (periodicsCalendarPrevButton) {
    periodicsCalendarPrevButton.setAttribute(
      "aria-label",
      displayMode === "month" ? "Prethodni mjesec" : "Prethodni tjedan",
    );
  }
  if (periodicsCalendarNextButton) {
    periodicsCalendarNextButton.setAttribute(
      "aria-label",
      displayMode === "month" ? "Sljedeci mjesec" : "Sljedeci tjedan",
    );
  }
  if (periodicsCalendarDisplayWeekButton) {
    const isActive = displayMode === "week";
    periodicsCalendarDisplayWeekButton.classList.toggle("is-active", isActive);
    periodicsCalendarDisplayWeekButton.setAttribute("aria-pressed", isActive ? "true" : "false");
  }
  if (periodicsCalendarDisplayMonthButton) {
    const isActive = displayMode === "month";
    periodicsCalendarDisplayMonthButton.classList.toggle("is-active", isActive);
    periodicsCalendarDisplayMonthButton.setAttribute("aria-pressed", isActive ? "true" : "false");
  }
  if (periodicsCalendarWeekendsButton) {
    periodicsCalendarWeekendsButton.classList.toggle("is-active", showWeekends);
    periodicsCalendarWeekendsButton.setAttribute("aria-pressed", showWeekends ? "true" : "false");
    periodicsCalendarWeekendsButton.setAttribute(
      "title",
      showWeekends ? "Sakrij vikende" : "Prikazi vikende",
    );
  }
}

function renderPeriodicsCalendarWeekMode(calendarData = {}) {
  const week = buildPeriodicsCalendarWeekStructure(state.periodicsCalendar?.anchorDate);
  const dayMap = new Map(week.days.map((day) => [day.key, day]));
  appendPeriodicsCalendarItemsToDayMap(dayMap, {
    dueItems: calendarData.dueItems,
    absenceItems: calendarData.absenceItems,
    rangeStart: week.weekStart,
    rangeEnd: week.weekEnd,
  });

  const visibleDays = getVisibleCalendarWeekDays(week.days, Boolean(state.periodicsCalendar?.showWeekends));
  const firstVisibleDay = visibleDays[0]?.key || week.weekStart;
  const lastVisibleDay = visibleDays[visibleDays.length - 1]?.key || week.weekEnd;

  if (periodicsCalendarRange) {
    periodicsCalendarRange.textContent = formatCalendarWeekRangeLabel(firstVisibleDay, lastVisibleDay);
  }
  if (periodicsCalendarMeta) {
    periodicsCalendarMeta.textContent = "Klikni dan za detaljni pregled.";
  }

  const fragment = document.createDocumentFragment();
  const section = document.createElement("section");
  section.className = "periodics-calendar-week-row";

  const rail = createPeriodicsCalendarWeekRail(firstVisibleDay, visibleDays);

  const grid = document.createElement("div");
  grid.className = "work-order-calendar-month-grid periodics-calendar-week-grid";
  grid.style.gridTemplateColumns = `repeat(${visibleDays.length}, minmax(0, 1fr))`;
  grid.style.minWidth = `${visibleDays.length * 160}px`;
  grid.style.width = "100%";

  visibleDays.forEach((day) => {
    grid.append(createPeriodicsCalendarDayCell(day));
  });

  section.append(rail, grid);
  fragment.append(section);
  periodicsCalendarGrid?.replaceChildren(fragment);
  renderPeriodicsCalendarDetailPanel(dayMap, {
    visibleRangeStart: week.weekStart,
    visibleRangeEnd: week.weekEnd,
  });

  return getPeriodicsCalendarMetrics(visibleDays);
}

function renderPeriodicsCalendarMonthMode(calendarData = {}) {
  const calendar = buildPeriodicsCalendarMonthStructure(state.periodicsCalendar?.anchorDate);
  const dayMap = new Map(
    calendar.weeks.flatMap((week) => week.days.map((day) => [day.key, day])),
  );

  appendPeriodicsCalendarItemsToDayMap(dayMap, {
    dueItems: calendarData.dueItems,
    absenceItems: calendarData.absenceItems,
    rangeStart: calendar.displayStart,
    rangeEnd: calendar.displayEnd,
  });

  const allVisibleDays = calendar.weeks.flatMap((week) => getVisibleCalendarWeekDays(week.days, Boolean(state.periodicsCalendar?.showWeekends)));

  if (periodicsCalendarRange) {
    periodicsCalendarRange.textContent = formatCalendarMonthLabel(calendar.anchorDate);
  }
  if (periodicsCalendarMeta) {
    periodicsCalendarMeta.textContent = "Klikni dan za detaljni pregled.";
  }

  const fragment = document.createDocumentFragment();

  calendar.weeks.forEach((week) => {
    const visibleDays = getVisibleCalendarWeekDays(week.days, Boolean(state.periodicsCalendar?.showWeekends));
    const section = document.createElement("section");
    section.className = "periodics-calendar-week-row";

    const rail = createPeriodicsCalendarWeekRail(week.weekStart, visibleDays);

    const grid = document.createElement("div");
    grid.className = "work-order-calendar-month-grid periodics-calendar-week-grid";
    grid.style.gridTemplateColumns = `repeat(${visibleDays.length}, minmax(0, 1fr))`;
    grid.style.minWidth = `${visibleDays.length * 160}px`;
    grid.style.width = "100%";

    visibleDays.forEach((day) => {
      grid.append(createPeriodicsCalendarDayCell(day));
    });

    section.append(rail, grid);
    fragment.append(section);
  });

  periodicsCalendarGrid?.replaceChildren(fragment);
  renderPeriodicsCalendarDetailPanel(dayMap, {
    visibleRangeStart: calendar.displayStart,
    visibleRangeEnd: calendar.displayEnd,
  });
  return getPeriodicsCalendarMetrics(allVisibleDays);
}

function renderPeriodicsCalendarView(calendarData = {}) {
  if (!periodicsCalendarGrid) {
    return { dueCount: 0, absenceCount: 0 };
  }

  bindPeriodicsCalendarGrabScroll();
  syncPeriodicsCalendarToolbar();
  queuePeriodicsCalendarGridShellHeightSync();

  const dueItems = Array.isArray(calendarData?.dueItems) ? calendarData.dueItems : [];
  const absenceItems = Array.isArray(calendarData?.absenceItems) ? calendarData.absenceItems : [];
  const hasEntries = dueItems.length > 0 || absenceItems.length > 0;

  if (periodicsCalendarEmpty) {
    periodicsCalendarEmpty.hidden = hasEntries;
  }

  if (!hasEntries) {
    periodicsCalendarGrid.replaceChildren();
    periodicsCalendarDetailPanel && (periodicsCalendarDetailPanel.hidden = true);
    periodicsCalendarDetailList?.replaceChildren();
    if (periodicsCalendarRange) {
      periodicsCalendarRange.textContent = normalizePeriodicsCalendarDisplayMode(state.periodicsCalendar?.displayMode) === "month"
        ? formatCalendarMonthLabel(getPeriodicsCalendarAnchorDate(state.periodicsCalendar?.anchorDate))
        : formatCalendarWeekRangeLabel(
          getPeriodicsCalendarWeekStart(state.periodicsCalendar?.anchorDate),
          shiftDateKey(getPeriodicsCalendarWeekStart(state.periodicsCalendar?.anchorDate), 6),
        );
    }
    if (periodicsCalendarMeta) {
      periodicsCalendarMeta.textContent = "";
    }
    return { dueCount: 0, absenceCount: 0 };
  }

  if (normalizePeriodicsCalendarDisplayMode(state.periodicsCalendar?.displayMode) === "week") {
    return renderPeriodicsCalendarWeekMode(calendarData);
  }

  return renderPeriodicsCalendarMonthMode(calendarData);
}

function renderPeriodicsModule() {
  if (!periodicsModule) {
    return;
  }
  loadPeriodicsPreferences();
  state.periodicsFilters = {
    query: String(state.periodicsFilters?.query || "").trim(),
    horizon: String(state.periodicsFilters?.horizon || "all").trim() || "all",
    inspectionGroup: normalizePeriodicsInspectionGroupMode(state.periodicsFilters?.inspectionGroup || "item"),
    inspectionGroupKey: String(state.periodicsFilters?.inspectionGroupKey || "").trim(),
  };
  state.periodicsViewMode = normalizePeriodicsViewMode(state.periodicsViewMode);
  state.periodicsCalendar = {
    anchorDate: getPeriodicsCalendarAnchorDate(state.periodicsCalendar?.anchorDate),
    displayMode: normalizePeriodicsCalendarDisplayMode(state.periodicsCalendar?.displayMode),
    showWeekends: state.periodicsCalendar?.showWeekends !== false,
    selectedDate: normalizePeriodicsCalendarSelectedDate(state.periodicsCalendar?.selectedDate, {
      allowEmpty: true,
    }),
    visibility: normalizePeriodicsCalendarVisibility(state.periodicsCalendar?.visibility),
  };
  const visualSettings = getPeriodicsVisualSettings();
  const warningDays = visualSettings.warningDays;
  const criticalDays = visualSettings.criticalDays;

  syncPeriodicsViewState();

  const activeOrganizationId = String(state.activeOrganizationId || "").trim();
  const periodicsOrganizationId = String(state.periodicsFeed.organizationId || "").trim();
  if (
    periodicsOrganizationId
    && activeOrganizationId
    && periodicsOrganizationId !== activeOrganizationId
  ) {
    state.periodicsFeed.loaded = false;
    state.periodicsFeed.records = [];
    state.periodicsFeed.error = "";
  }

  if (
    !state.periodicsFeed.loading
    && (
      !state.periodicsFeed.loaded
      || !periodicsOrganizationId
      || periodicsOrganizationId !== activeOrganizationId
    )
  ) {
    void loadPeriodicsFeed();
  }

  const rawDocumentRecords = getPeriodicsDocumentRecords();
  const rawInspectionEntries = buildPeriodicsInspectionEntries(rawDocumentRecords);
  const rawVehicleEntries = buildPeriodicsVehicleEntries();
  const rawPeopleEntries = buildPeriodicsPeopleEntries();
  const rawEquipmentEntries = buildPeriodicsMeasurementEquipmentEntries();
  const currentInspectionEntries = buildPeriodicsCurrentDateEntries(rawInspectionEntries, "inspection");
  const currentVehicleEntries = buildPeriodicsCurrentDateEntries(rawVehicleEntries, "vehicle");
  const currentPeopleEntries = buildPeriodicsCurrentDateEntries(rawPeopleEntries, "people");
  const currentEquipmentEntries = buildPeriodicsCurrentDateEntries(rawEquipmentEntries, "equipment");

  const inspectionSearchEntries = applyPeriodicsFilters(currentInspectionEntries, {
    ...state.periodicsFilters,
    horizon: "all",
  });
  const selectedInspectionGroupKey = syncPeriodicsInspectionGroupFilterControl(
    inspectionSearchEntries,
    state.periodicsFilters,
  );
  if (String(state.periodicsFilters.inspectionGroupKey || "") !== selectedInspectionGroupKey) {
    state.periodicsFilters.inspectionGroupKey = selectedInspectionGroupKey;
  }
  const inspectionEntries = applyPeriodicsInspectionGroupFilter(inspectionSearchEntries, state.periodicsFilters);
  const vehicleEntries = currentVehicleEntries;
  const peopleEntries = currentPeopleEntries;
  const equipmentEntries = currentEquipmentEntries;
  const calendarData = buildPeriodicsCalendarData({
    inspectionEntries: currentInspectionEntries,
    vehicleEntries: currentVehicleEntries,
    peopleEntries: currentPeopleEntries,
    equipmentEntries: currentEquipmentEntries,
    query: "",
    visibility: state.periodicsCalendar.visibility,
  });
  renderPeriodicsCalendarView(calendarData);

  if (periodicsSearchInput && periodicsSearchInput.value !== state.periodicsFilters.query) {
    periodicsSearchInput.value = state.periodicsFilters.query;
  }
  if (periodicsInspectionGroupInput) {
    const inspectionGroupMode = normalizePeriodicsInspectionGroupMode(state.periodicsFilters.inspectionGroup);
    if (periodicsInspectionGroupInput.value !== inspectionGroupMode) {
      periodicsInspectionGroupInput.value = inspectionGroupMode;
    }
  }

  const inspectionPeriodicsRows = createPeriodicsInspectionRows(
    inspectionEntries,
    state.periodicsFilters.inspectionGroup,
  );

  const vehicleRows = vehicleEntries.flatMap((entry) => createPeriodicsDateRows(entry, (rowEntry) => createPeriodicsRow([
    createPeriodicsCell(rowEntry.vehicleName, rowEntry.plateNumber || "Bez registracije"),
    createPeriodicsCell(rowEntry.vinNumber || "—", "", { dimmed: !rowEntry.vinNumber }),
    createPeriodicsCell(rowEntry.periodicLabel),
    createPeriodicsCell(rowEntry.detail),
    createPeriodicsDueCell(rowEntry.dueDate, rowEntry.dueState),
  ], rowEntry.dueState?.toneClass)));

  const peopleRows = peopleEntries.flatMap((entry) => createPeriodicsDateRows(entry, (rowEntry) => createPeriodicsRow([
    createPeriodicsCell(rowEntry.userName, rowEntry.userEmail || "Bez e-maila"),
    createPeriodicsCell(rowEntry.areaLabel),
    createPeriodicsCell(rowEntry.qualificationLabel),
    createPeriodicsDueCell(rowEntry.dueDate, rowEntry.dueState),
  ], rowEntry.dueState?.toneClass)));

  const equipmentRows = equipmentEntries.flatMap((entry) => createPeriodicsDateRows(entry, (rowEntry) => createPeriodicsRow([
    createPeriodicsCell(rowEntry.equipmentName, rowEntry.manufacturerModel || "Bez modela"),
    createPeriodicsCell(rowEntry.kindLabel, rowEntry.periodicLabel),
    createPeriodicsCell(rowEntry.detail || "Bez detalja", rowEntry.templateSummary || ""),
    createPeriodicsCell(rowEntry.codeSummary || "—", "", { dimmed: !rowEntry.codeSummary }),
    createPeriodicsDueCell(rowEntry.dueDate, rowEntry.dueState),
  ], rowEntry.dueState?.toneClass)));

  renderPeriodicsRows(periodicsInspectionPeriodicsList, inspectionPeriodicsRows);
  renderPeriodicsRows(periodicsVehiclesList, vehicleRows);
  renderPeriodicsRows(periodicsPeopleList, peopleRows);
  renderPeriodicsRows(periodicsEquipmentList, equipmentRows);

  if (periodicsVehiclesCount) {
    periodicsVehiclesCount.textContent = String(vehicleEntries.length);
  }
  if (periodicsPeopleCount) {
    periodicsPeopleCount.textContent = String(peopleEntries.length);
  }
  if (periodicsEquipmentCount) {
    periodicsEquipmentCount.textContent = String(equipmentEntries.length);
  }
  syncPeriodicsSectionMetrics(
    {
      overdueNode: periodicsInspectionPeriodicsOverdue,
      warningNode: periodicsInspectionPeriodicsWarning,
      validNode: periodicsInspectionPeriodicsValid,
      alertOverdueNode: periodicsInspectionPeriodicsOverdueDot,
      alertWarningNode: periodicsInspectionPeriodicsWarningDot,
      bodyNode: periodicsInspectionPeriodicsBody,
    },
    inspectionEntries,
    visualSettings,
  );
  syncPeriodicsSectionMetrics(
    {
      overdueNode: periodicsVehiclesOverdue,
      warningNode: periodicsVehiclesWarning,
      validNode: periodicsVehiclesValid,
      alertOverdueNode: periodicsVehiclesOverdueDot,
      alertWarningNode: periodicsVehiclesWarningDot,
      bodyNode: periodicsVehiclesBody,
    },
    vehicleEntries,
    visualSettings,
  );
  syncPeriodicsSectionMetrics(
    {
      overdueNode: periodicsPeopleOverdue,
      warningNode: periodicsPeopleWarning,
      validNode: periodicsPeopleValid,
      alertOverdueNode: periodicsPeopleOverdueDot,
      alertWarningNode: periodicsPeopleWarningDot,
      bodyNode: periodicsPeopleBody,
    },
    peopleEntries,
    visualSettings,
  );
  syncPeriodicsSectionMetrics(
    {
      overdueNode: periodicsEquipmentOverdue,
      warningNode: periodicsEquipmentWarning,
      validNode: periodicsEquipmentValid,
      alertOverdueNode: periodicsEquipmentOverdueDot,
      alertWarningNode: periodicsEquipmentWarningDot,
      bodyNode: periodicsEquipmentBody,
    },
    equipmentEntries,
    visualSettings,
  );

  const allEntries = [
    ...inspectionEntries,
    ...vehicleEntries,
    ...peopleEntries,
    ...equipmentEntries,
  ];
  const totalPeriodicEntryCount = inspectionEntries.length + vehicleEntries.length + peopleEntries.length + equipmentEntries.length;
  const overdueEntries = allEntries.filter((entry) => Number(entry?.dueState?.daysUntil) < 0);
  const nextSixtyDaysEntries = allEntries.filter((entry) => {
    const daysUntil = Number(entry?.dueState?.daysUntil);
    return Number.isFinite(daysUntil) && daysUntil >= 0 && daysUntil <= warningDays;
  });
  const criticalEntries = allEntries.filter((entry) => {
    const daysUntil = Number(entry?.dueState?.daysUntil);
    return Number.isFinite(daysUntil) && daysUntil >= 0 && daysUntil <= criticalDays;
  });

  if (periodicsTotalCount) {
    periodicsTotalCount.textContent = String(totalPeriodicEntryCount);
  }
  if (periodicsOverdueCount) {
    periodicsOverdueCount.textContent = String(overdueEntries.length);
  }
  if (periodicsNext30Count) {
    periodicsNext30Count.textContent = String(nextSixtyDaysEntries.length);
  }
  if (periodicsNext30Label) {
    periodicsNext30Label.textContent = `Rok do ${warningDays} dana`;
  }
  if (periodicsCriticalCount) {
    periodicsCriticalCount.textContent = String(criticalEntries.length);
  }
  if (periodicsCriticalLabel) {
    periodicsCriticalLabel.textContent = `Kritično (${criticalDays} dana)`;
  }
  periodicsOverdueCount?.closest(".periodics-stat-card")?.classList.toggle("has-overdue-pulse", overdueEntries.length > 0);

  if (periodicsInspectionPeriodicsEmpty) {
    periodicsInspectionPeriodicsEmpty.hidden = state.periodicsFeed.loading || inspectionEntries.length > 0;
    periodicsInspectionPeriodicsEmpty.textContent = state.periodicsFeed.error
      ? "Periodika ispitivanja trenutno nije učitana."
      : (rawInspectionEntries.length > 0
        ? "Nema ispitivanja za odabranu pretragu ili prikaz."
        : "Nema ispitivanja s expiration_date iz trackanog polja Vrijedi do.");
  }
  if (periodicsVehiclesEmpty) {
    periodicsVehiclesEmpty.hidden = vehicleEntries.length > 0;
  }
  if (periodicsPeopleEmpty) {
    periodicsPeopleEmpty.hidden = peopleEntries.length > 0;
  }
  if (periodicsEquipmentEmpty) {
    periodicsEquipmentEmpty.hidden = equipmentEntries.length > 0;
  }

  if (periodicsHelper) {
    if (!activeOrganizationId) {
      periodicsHelper.textContent = "Odaberi organizaciju za pregled periodike.";
    } else if (state.periodicsFeed.loading) {
      periodicsHelper.textContent = "Učitavanje periodike...";
    } else if (state.periodicsFeed.error && allEntries.length === 0) {
      periodicsHelper.textContent = state.periodicsFeed.error;
    } else if (allEntries.length === 0) {
      periodicsHelper.textContent = "Nema periodičkih obveza za aktivnu organizaciju.";
    } else if (state.periodicsFeed.error) {
      periodicsHelper.textContent = `Aktualni rokovi: Ispitivanja ${inspectionEntries.length} · Vozila ${vehicleEntries.length} · Ljudi ${peopleEntries.length} · Oprema ${equipmentEntries.length}.`;
    } else {
      periodicsHelper.textContent = `Aktualni rokovi: Ispitivanja ${inspectionEntries.length} · Vozila ${vehicleEntries.length} · Ljudi ${peopleEntries.length} · Oprema ${equipmentEntries.length}.`;
    }
  }

  syncPeriodicsSections();
}

async function loadPeriodicsFeed({ force = false } = {}) {
  const activeOrganizationId = String(state.activeOrganizationId || "").trim();
  if (!activeOrganizationId || state.periodicsFeed.loading) {
    return;
  }

  const isSameOrganization = String(state.periodicsFeed.organizationId || "").trim() === activeOrganizationId;
  if (!force && state.periodicsFeed.loaded && isSameOrganization) {
    return;
  }

  state.periodicsFeed.loading = true;
  state.periodicsFeed.error = "";
  if (state.activeView === "module" && state.activeModuleItem === "periodics") {
    renderPeriodicsModule();
  }

  try {
    const response = await apiRequest(`/document-records?limit=${PERIODICS_MAX_RECORDS}&periodics=1`);
    state.periodicsFeed = {
      organizationId: activeOrganizationId,
      loaded: true,
      loading: false,
      error: "",
      records: Array.isArray(response?.items) ? response.items : [],
    };
  } catch (error) {
    state.periodicsFeed = {
      ...state.periodicsFeed,
      organizationId: activeOrganizationId,
      loaded: false,
      loading: false,
      error: error?.message || "Ne mogu učitati periodičke zapise.",
    };
  }

  if (state.activeView === "module" && state.activeModuleItem === "periodics") {
    renderPeriodicsModule();
  }
  if (state.companyEditorOpen && state.activeView === "companies") {
    renderCompanyWorkspaceDashboard(companyIdInput?.value || "");
  }
}

function getWorkOrderTeamOptions() {
  return Array.from(new Set(
    state.workOrders
      .map((item) => String(item.teamLabel ?? "").trim())
      .filter(Boolean),
  )).sort((left, right) => left.localeCompare(right, "hr"));
}

function refreshWorkOrderTeamSuggestions() {
  if (!workOrderTeamSuggestions) {
    return;
  }

  workOrderTeamSuggestions.replaceChildren(
    ...getWorkOrderTeamOptions().map((label) => {
      const option = document.createElement("option");
      option.value = label;
      return option;
    }),
  );
}

function buildDefaultMeasurementColumns() {
  return DEFAULT_MEASUREMENT_COLUMNS.map((column) => ({ ...column }));
}

function normalizeMeasurementSheetValidationOptionsLocal(values = []) {
  return Array.from(new Set((Array.isArray(values) ? values : String(values ?? "")
    .split(/[\n,;|]/))
    .map((value) => String(value ?? "").trim())
    .filter(Boolean)))
    .slice(0, 160);
}

function normalizeMeasurementSheetColumnValidationSnapshotLocal(input = {}, availableColumnIds = new Set(), columnId = "") {
  const source = input && typeof input === "object" ? input : {};
  const type = String(source?.type || "").trim().toLowerCase() === "list" ? "list" : "none";
  const sourceMode = String(source?.sourceMode || "").trim().toLowerCase() === "custom" ? "custom" : "column";
  const sourceColumnId = String(source?.sourceColumnId || "").trim();
  const normalizedSourceColumnId = sourceMode === "column"
    && sourceColumnId
    && (!availableColumnIds.size || availableColumnIds.has(sourceColumnId))
    ? sourceColumnId
    : (sourceMode === "column" && columnId && (!availableColumnIds.size || availableColumnIds.has(columnId))
      ? columnId
      : "");

  if (type !== "list") {
    return {
      type: "none",
      sourceMode: "column",
      sourceColumnId: "",
      options: [],
      allowCustom: true,
    };
  }

  return {
    type: "list",
    sourceMode,
    sourceColumnId: sourceMode === "column" ? normalizedSourceColumnId : "",
    options: sourceMode === "custom"
      ? normalizeMeasurementSheetValidationOptionsLocal(source?.options)
      : [],
    allowCustom: Boolean(source?.allowCustom ?? true),
  };
}

const MEASUREMENT_AI_COLUMN_FORMATS = new Set([
  "text",
  "number",
  "date",
  "boolean",
  "enum",
  "measurement",
  "list",
]);

const AI_CONFIDENCE_LEVELS = new Set(["high", "medium", "low"]);

const AI_CONFIDENCE_LABELS = {
  high: "NexAI visoka sigurnost",
  medium: "NexAI srednja sigurnost",
  low: "NexAI niska sigurnost",
};

function normalizeAiConfigListLocal(value, maxItems = 120) {
  return normalizeMeasurementSheetValidationOptionsLocal(value).slice(0, maxItems);
}

function normalizeAiConfidenceLevelLocal(value = "", fallback = "medium") {
  const normalized = String(value || "").trim().toLowerCase();
  return AI_CONFIDENCE_LEVELS.has(normalized) ? normalized : fallback;
}

function normalizeAiDisplayOrderLocal(value = "") {
  const parsed = Number.parseInt(String(value ?? "").trim(), 10);
  return Number.isFinite(parsed) ? Math.max(0, Math.min(9999, parsed)) : 0;
}

function normalizeAiFieldTypeLocal(value = "", fallback = "text") {
  const normalized = String(value || "").trim().toLowerCase();
  if (MEASUREMENT_AI_COLUMN_FORMATS.has(normalized)) {
    return normalized;
  }
  return fallback;
}

function normalizeMeasurementSheetColumnAiMappingSnapshotLocal(input = {}) {
  const source = input && typeof input === "object" ? input : {};
  const format = normalizeAiFieldTypeLocal(source?.format || source?.type || "", "text");
  const description = String(source?.description ?? source?.aiDescription ?? source?.ai_description ?? "").trim().slice(0, 2000);
  const aiDescription = String(source?.aiDescription ?? source?.ai_description ?? source?.description ?? "").trim().slice(0, 4000);
  const aiLookFor = normalizeAiConfigListLocal(
    source?.aiLookFor ?? source?.ai_look_for ?? source?.synonyms,
    160,
  );
  const aiAvoid = String(source?.aiAvoid ?? source?.ai_avoid ?? source?.avoid ?? "").trim().slice(0, 1000);

  return {
    key: String(source?.key || "").trim().slice(0, 120),
    label: String(source?.label || "").trim().slice(0, 160),
    description,
    type: normalizeAiFieldTypeLocal(source?.type || format, format),
    required: Boolean(source?.required),
    placeholder: String(source?.placeholder || "").trim().slice(0, 400),
    helpText: String(source?.helpText ?? source?.help_text ?? "").trim().slice(0, 1000),
    enabled: Boolean(source?.enabled ?? source?.aiEnabled ?? source?.ai_enabled),
    aiDescription,
    aiLookFor,
    aiAvoid,
    synonyms: normalizeAiConfigListLocal(source?.synonyms ?? aiLookFor, 80),
    allowedValues: normalizeAiConfigListLocal(source?.allowedValues ?? source?.allowed_values, 160),
    commonValues: normalizeAiConfigListLocal(source?.commonValues ?? source?.common_values, 80),
    examples: normalizeAiConfigListLocal(source?.examples, 80),
    avoid: aiAvoid,
    format,
    unit: String(source?.unit || "").trim().slice(0, 40),
    defaultValue: String(source?.defaultValue ?? source?.default_value ?? "").trim().slice(0, 500),
    fallbackValue: String(source?.fallbackValue ?? source?.fallback_value ?? "").trim().slice(0, 500),
    confidenceRequired: normalizeAiConfidenceLevelLocal(
      source?.confidenceRequired ?? source?.confidence_required,
      "medium",
    ),
    sourceTracking: Boolean(source?.sourceTracking ?? source?.source_tracking ?? true),
    validationRules: String(source?.validationRules ?? source?.validation_rules ?? "").trim().slice(0, 1600),
    displayOrder: normalizeAiDisplayOrderLocal(source?.displayOrder ?? source?.display_order),
    group: String(source?.group || "").trim().slice(0, 120),
  };
}

function hasMeasurementColumnAiMapping(aiMapping = {}) {
  const normalized = normalizeMeasurementSheetColumnAiMappingSnapshotLocal(aiMapping);
  return Boolean(
    normalized.description
    || normalized.key
    || normalized.label
    || normalized.synonyms.length
    || normalized.aiDescription
    || normalized.aiLookFor.length
    || normalized.allowedValues.length
    || normalized.commonValues.length
    || normalized.examples.length
    || normalized.avoid
    || normalized.aiAvoid
    || normalized.format !== "text"
    || normalized.type !== "text"
    || normalized.required
    || normalized.enabled
    || normalized.placeholder
    || normalized.helpText
    || normalized.unit
    || normalized.defaultValue
    || normalized.fallbackValue
    || normalized.validationRules
    || normalized.displayOrder
    || normalized.group
  );
}

function normalizeMeasurementColumnCellPlaceholder(value = "", label = "") {
  const placeholder = String(value ?? "").trim();
  const normalizedLabel = String(label ?? "").trim();
  const defaultCellHints = new Set([
    "pozicija",
    "opis",
    "vrijednost",
    "granica",
    "napomena",
    "unos",
    "mjerno mjesto",
    "oznaka",
    "jedinica",
    "min",
    "max",
    "0,00",
  ]);

  if (!placeholder) {
    return "";
  }
  if (placeholder.toLowerCase() === normalizedLabel.toLowerCase() || defaultCellHints.has(placeholder.toLowerCase())) {
    return "";
  }
  return placeholder;
}

function createMeasurementColumn(partial = {}) {
  measurementColumnCounter += 1;
  const fallbackId = partial.id || `measurement-custom-${measurementColumnCounter}`;
  const label = partial.label || `Kolona ${measurementColumnCounter}`;

  return {
    id: fallbackId,
    label,
    placeholder: normalizeMeasurementColumnCellPlaceholder(partial.placeholder, label),
    width: partial.width || 160,
    computed: partial.computed || null,
    readonly: Boolean(partial.readonly),
    validation: normalizeMeasurementSheetColumnValidationSnapshotLocal(
      partial.validation,
      new Set([fallbackId]),
      fallbackId,
    ),
    aiMapping: normalizeMeasurementSheetColumnAiMappingSnapshotLocal(partial.aiMapping ?? partial.ai),
  };
}

function createMeasurementRow(partialCells = {}, partialFormats = {}) {
  measurementRowCounter += 1;

  const cells = {};
  const formats = {};

  state.measurementSheet.columns
    .filter((column) => !column.computed)
    .forEach((column) => {
      cells[column.id] = partialCells[column.id] ?? "";
      formats[column.id] = normalizeMeasurementCellFormat(partialFormats[column.id]);
    });

  return {
    id: `measurement-row-${measurementRowCounter}`,
    cells,
    formats,
  };
}

function buildDefaultMeasurementRows(count = DEFAULT_MEASUREMENT_ROW_COUNT) {
  return Array.from({ length: count }, () => createMeasurementRow());
}

