function createStackCell({
  eyebrow = "",
  title = "",
  subtitle = "",
  tertiary = "",
  meta = [],
  className = "",
} = {}) {
  const cell = document.createElement("td");
  if (className) {
    cell.className = className;
  }

  const stack = document.createElement("div");
  stack.className = "list-cell";

  if (eyebrow) {
    stack.append(createListLine(eyebrow, "list-eyebrow"));
  }

  if (title) {
    stack.append(createListLine(title, "list-primary"));
  }

  if (subtitle) {
    stack.append(createListLine(subtitle, "list-secondary"));
  }

  if (tertiary) {
    stack.append(createListLine(tertiary, "list-tertiary"));
  }

  const metaItems = meta.filter(Boolean);

  if (metaItems.length > 0) {
    const metaRow = document.createElement("div");
    metaRow.className = "list-meta-row";

    for (const item of metaItems) {
      if (typeof Node !== "undefined" && item instanceof Node) {
        metaRow.append(item);
      } else if (typeof item === "string") {
        metaRow.append(createMetaPill(item));
      } else {
        metaRow.append(createMetaPill(item.label, item.className));
      }
    }

    stack.append(metaRow);
  }

  cell.append(stack);
  return cell;
}

function toggleCompanyListExpansion(companyId = "") {
  const normalizedCompanyId = String(companyId || "").trim();
  if (!normalizedCompanyId) {
    return;
  }

  if (state.companyExpandedIds.has(normalizedCompanyId)) {
    state.companyExpandedIds.delete(normalizedCompanyId);
  } else {
    state.companyExpandedIds.add(normalizedCompanyId);
  }
  companiesListRenderSignature = "";
  renderCompanies();
}

function getCompanyListExpandIconMarkup() {
  return '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4.25 6.25 3.75 3.75 3.75-3.75" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.65"/></svg>';
}

function createCompanyIdentityCell(company, rowSnapshot = null) {
  const cell = document.createElement("td");
  cell.className = "company-list-company-cell";
  const stack = document.createElement("div");
  stack.className = "company-list-cell";

  if (rowSnapshot) {
    const expandButton = document.createElement("button");
    expandButton.type = "button";
    expandButton.className = "company-list-expand-toggle";
    expandButton.dataset.companyExpandToggle = String(company.id || "");
    expandButton.setAttribute("aria-label", rowSnapshot.isExpanded ? "Sakrij lokacije" : "Prikaži lokacije");
    expandButton.setAttribute("aria-expanded", String(rowSnapshot.isExpanded));
    expandButton.classList.toggle("is-expanded", Boolean(rowSnapshot.isExpanded));
    expandButton.innerHTML = getCompanyListExpandIconMarkup();
    expandButton.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      toggleCompanyListExpansion(company.id || "");
    });
    stack.append(expandButton);
  }

  const logo = document.createElement("span");
  logo.className = "company-list-logo";
  renderCompanyLogo(logo, company);

  const copy = document.createElement("div");
  copy.className = "company-list-copy";

  const titleRow = document.createElement("div");
  titleRow.className = "company-list-title-row";
  titleRow.append(createListLine(company.name || "Tvrtka", "list-primary company-list-title"));
  if (company.isActive !== undefined) {
    titleRow.append(createMetaPill(company.isActive ? "Aktivna" : "Neaktivna", company.isActive ? "is-success" : "is-danger"));
  }

  copy.append(
    titleRow,
    createListLine(company.headquarters || "Bez sjedišta", "list-secondary company-list-address"),
    createListLine(company.oib ? `OIB ${company.oib}` : "Bez OIB-a", "list-tertiary company-list-oib"),
  );

  stack.append(logo, copy);
  cell.append(stack);
  return cell;
}

