function escapeHtml(value = "") {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function serializeJsonForHtml(value) {
  return JSON.stringify(value)
    .replace(/</g, "\\u003c")
    .replace(/>/g, "\\u003e")
    .replace(/&/g, "\\u0026")
    .replace(/\u2028/g, "\\u2028")
    .replace(/\u2029/g, "\\u2029");
}

function sanitizeDocumentTemplateFileName(value = "", fallback = "zapisnik-template") {
  const slug = slugifyValue(value).replace(/-+/g, "-").replace(/^-+|-+$/g, "");
  return slug || fallback;
}

function triggerBlobDownload(blob, fileName) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  document.body.append(link);
  link.click();
  link.remove();
  window.setTimeout(() => {
    URL.revokeObjectURL(url);
  }, 1_000);
}

function triggerBlobPrint(blob, fileName = "zapisnici.pdf") {
  const url = URL.createObjectURL(blob);
  const iframe = document.createElement("iframe");
  iframe.style.position = "fixed";
  iframe.style.width = "0";
  iframe.style.height = "0";
  iframe.style.opacity = "0";
  iframe.style.pointerEvents = "none";
  iframe.setAttribute("aria-hidden", "true");
  iframe.src = url;

  let settled = false;
  const cleanup = () => {
    if (settled) {
      return;
    }
    settled = true;
    window.setTimeout(() => {
      iframe.remove();
      URL.revokeObjectURL(url);
    }, 1_500);
  };

  iframe.addEventListener("load", () => {
    window.setTimeout(() => {
      try {
        iframe.contentWindow?.focus();
        iframe.contentWindow?.print();
      } catch (error) {
        console.error("Ne mogu otvoriti print dijalog za PDF batch.", error);
        triggerBlobDownload(blob, fileName);
      } finally {
        cleanup();
      }
    }, 250);
  }, { once: true });

  iframe.addEventListener("error", () => {
    triggerBlobDownload(blob, fileName);
    cleanup();
  }, { once: true });

  document.body.append(iframe);
}

function triggerDataUrlDownload(dataUrl, fileName) {
  const link = document.createElement("a");
  link.href = dataUrl;
  link.download = fileName;
  document.body.append(link);
  link.click();
  link.remove();
}

function createWordHtmlBlob(title, bodyHtml) {
  const html = `<!DOCTYPE html>
<html lang="hr">
<head>
  <meta charset="utf-8" />
  <title>${escapeHtml(title)}</title>
  <style>
    body { font-family: Arial, sans-serif; color: #24362e; line-height: 1.5; margin: 28px; }
    h1, h2, h3 { color: #1f4e42; margin-bottom: 12px; }
    h1 { font-size: 26px; }
    h2 { font-size: 20px; margin-top: 30px; }
    h3 { font-size: 16px; margin-top: 20px; }
    p { margin: 10px 0; }
    table { width: 100%; border-collapse: collapse; margin: 12px 0 18px; }
    th, td { border: 1px solid #cad8d1; padding: 8px 10px; text-align: left; vertical-align: top; }
    th { background: #eef5f2; }
    .cover { border: 1px solid #cad8d1; border-radius: 18px; padding: 24px; background: #f7faf8; }
    .signature-grid { display: table; width: 100%; table-layout: fixed; margin-top: 18px; }
    .signature-cell { display: table-cell; width: 50%; padding-right: 18px; }
    .signature-line { margin-top: 46px; border-top: 1px solid #95aea3; padding-top: 8px; }
    .placeholder-table td:first-child { width: 32%; font-family: Consolas, monospace; }
    .placeholder-page p { margin: 0 0 12px; font-family: Consolas, "Courier New", monospace; color: #24362e; }
  </style>
</head>
<body>${bodyHtml}</body>
</html>`;

  return new Blob(["\ufeff", html], {
    type: "application/msword;charset=utf-8",
  });
}

function createStandaloneHtmlBlob(title, bodyHtml) {
  const html = `<!DOCTYPE html>
<html lang="hr">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>${escapeHtml(title)}</title>
  <style>
    body { font-family: Arial, sans-serif; color: #24362e; line-height: 1.5; margin: 28px; }
    h1, h2, h3 { color: #1f4e42; margin-bottom: 12px; }
    h1 { font-size: 26px; }
    h2 { font-size: 20px; margin-top: 30px; }
    h3 { font-size: 16px; margin-top: 20px; }
    p { margin: 10px 0; }
    table { width: 100%; border-collapse: collapse; margin: 12px 0 18px; }
    th, td { border: 1px solid #cad8d1; padding: 8px 10px; text-align: left; vertical-align: top; }
    th { background: #eef5f2; }
    .cover { border: 1px solid #cad8d1; border-radius: 18px; padding: 24px; background: #f7faf8; }
    .signature-grid { display: table; width: 100%; table-layout: fixed; margin-top: 18px; }
    .signature-cell { display: table-cell; width: 50%; padding-right: 18px; }
    .signature-line { margin-top: 46px; border-top: 1px solid #95aea3; padding-top: 8px; }
    .placeholder-table td:first-child { width: 32%; font-family: Consolas, monospace; }
    .placeholder-page p { margin: 0 0 12px; font-family: Consolas, "Courier New", monospace; color: #24362e; }
  </style>
</head>
<body>${bodyHtml}</body>
</html>`;

  return new Blob(["\ufeff", html], {
    type: "text/html;charset=utf-8",
  });
}

function textToDataUrl(text = "", mimeType = "text/html;charset=utf-8") {
  const bytes = new TextEncoder().encode(String(text ?? ""));
  const chunks = [];
  const chunkSize = 0x8000;
  for (let index = 0; index < bytes.length; index += chunkSize) {
    chunks.push(String.fromCharCode(...bytes.slice(index, index + chunkSize)));
  }
  return `data:${mimeType};base64,${btoa(chunks.join(""))}`;
}

const HTML_TEXT_ENCODING_REPLACEMENTS = Object.freeze([
  ["\u00c4\u0152", "\u010c"],
  ["\u00c4\u008c", "\u010c"],
  ["\u00c4\u0160", "\u010c"],
  ["\u00c4\u2020", "\u0106"],
  ["\u00c4\u0086", "\u0106"],
  ["\u00c4\u2021", "\u0107"],
  ["\u00c4\u0087", "\u0107"],
  ["\u00c4\u0164", "\u010d"],
  ["\u00c4\u008d", "\u010d"],
  ["\u00c4\u02c7", "\u010d"],
  ["\u00c4\u2018", "\u0111"],
  ["\u00c4\u0091", "\u0111"],
  ["\u00c4\u0090", "\u0110"],
  ["\u00c5\u00a0", "\u0160"],
  ["\u00c5\u00a1", "\u0161"],
  ["\u00c5\u00bd", "\u017d"],
  ["\u00c5\u00be", "\u017e"],
  ["\u0139\u02c7", "\u0161"],
  ["\u0139\u013e", "\u017e"],
  ["\u0139\u02dd", "\u017d"],
  ["\u00c2\u00a0", " "],
]);

function repairHtmlTextEncoding(value = "") {
  let text = String(value ?? "");
  HTML_TEXT_ENCODING_REPLACEMENTS.forEach(([broken, fixed]) => {
    text = text.split(broken).join(fixed);
  });
  return text;
}

function getHtmlTextEncodingSuspicionScore(value = "") {
  return (String(value ?? "").match(/[\uFFFD\u00c2\u00c3\u00c4\u00c5\u0102\u0139]/g) || []).length;
}

function ensureHtmlUtf8Meta(value = "") {
  let source = repairHtmlTextEncoding(String(value ?? "").replace(/^\uFEFF/, ""));

  if (/<meta\b[^>]*charset\s*=/i.test(source)) {
    return source.replace(/<meta\b[^>]*charset\s*=\s*["']?[^"'>\s;]+[^>]*>/i, '<meta charset="utf-8">');
  }

  if (/<head\b[^>]*>/i.test(source)) {
    return source.replace(/<head\b([^>]*)>/i, '<head$1>\n<meta charset="utf-8">');
  }

  if (/<html\b[^>]*>/i.test(source)) {
    return source.replace(/<html\b([^>]*)>/i, '<html$1>\n<head>\n<meta charset="utf-8">\n</head>');
  }

  return source;
}

function detectHtmlFileCharset(bytes = new Uint8Array()) {
  if (bytes.length >= 3 && bytes[0] === 0xEF && bytes[1] === 0xBB && bytes[2] === 0xBF) {
    return "utf-8";
  }

  const headBytes = bytes.slice(0, Math.min(bytes.length, 4096));
  const head = Array.from(headBytes, (byte) => String.fromCharCode(byte)).join("");
  const charset = String(
    head.match(/<meta\b[^>]*charset\s*=\s*["']?\s*([A-Za-z0-9._-]+)/i)?.[1]
    || head.match(/charset\s*=\s*([A-Za-z0-9._-]+)/i)?.[1]
    || "utf-8",
  ).trim().toLowerCase();
  return charset === "utf8" ? "utf-8" : charset;
}

function countReplacementCharacters(value = "") {
  return (String(value ?? "").match(/\uFFFD/g) || []).length;
}

function decodeHtmlTemplateBytes(buffer = new ArrayBuffer(0)) {
  const bytes = new Uint8Array(buffer);
  const charset = detectHtmlFileCharset(bytes);
  let decoded = "";
  try {
    decoded = new TextDecoder(charset).decode(bytes);
    if (charset !== "utf-8") {
      const utf8Decoded = new TextDecoder("utf-8").decode(bytes);
      if (getHtmlTextEncodingSuspicionScore(utf8Decoded) < getHtmlTextEncodingSuspicionScore(decoded)) {
        decoded = utf8Decoded;
      }
    }
  } catch {
    decoded = new TextDecoder("utf-8").decode(bytes);
  }

  if (charset === "utf-8" && countReplacementCharacters(decoded) > 0) {
    try {
      const centralEuropeanDecoded = new TextDecoder("windows-1250").decode(bytes);
      if (countReplacementCharacters(centralEuropeanDecoded) < countReplacementCharacters(decoded)) {
        decoded = centralEuropeanDecoded;
      }
    } catch {
      // Keep the UTF-8 decode when the browser does not support this legacy charset.
    }
  }

  return ensureHtmlUtf8Meta(decoded);
}

async function readHtmlTemplateFileAsText(file) {
  if (!(file instanceof File)) {
    return "";
  }
  return decodeHtmlTemplateBytes(await file.arrayBuffer());
}

async function readDataUrlAsText(dataUrl = "") {
  const source = String(dataUrl || "").trim();
  if (!source) {
    return "";
  }

  if (!source.startsWith("data:")) {
    const response = await fetch(source, { credentials: "same-origin" });
    if (!response.ok) {
      throw new Error("HTML predložak nije moguće učitati.");
    }
    return ensureHtmlUtf8Meta(await response.text());
  }

  const commaIndex = source.indexOf(",");
  if (commaIndex < 0) {
    return "";
  }

  const meta = source.slice(5, commaIndex).toLowerCase();
  const payload = source.slice(commaIndex + 1);
  if (!meta.includes(";base64")) {
    return ensureHtmlUtf8Meta(decodeURIComponent(payload));
  }

  const binary = atob(payload);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return decodeHtmlTemplateBytes(bytes.buffer);
}

function buildOfferLocationSummaryFromSelection(locationIds = [], companyId = "") {
  const normalizedIds = Array.from(new Set(
    (Array.isArray(locationIds) ? locationIds : [])
      .map((value) => String(value ?? "").trim())
      .filter(Boolean),
  ));
  const companyLocations = state.locations
    .filter((location) => String(location.companyId) === String(companyId))
    .slice()
    .sort((left, right) => left.name.localeCompare(right.name, "hr"));

  if (!companyId || companyLocations.length === 0 || normalizedIds.length === 0) {
    return {
      scope: "none",
      ids: [],
      names: [],
      summary: "Bez lokacije",
    };
  }

  const names = normalizedIds
    .map((locationId) => companyLocations.find((location) => String(location.id) === String(locationId))?.name ?? "")
    .filter(Boolean);

  if (normalizedIds.length >= companyLocations.length) {
    return {
      scope: "all",
      ids: companyLocations.map((location) => String(location.id)),
      names: companyLocations.map((location) => location.name),
      summary: `Sve lokacije (${companyLocations.length})`,
    };
  }

  if (normalizedIds.length === 1) {
    return {
      scope: "single",
      ids: normalizedIds,
      names,
      summary: names[0] || "1 lokacija",
    };
  }

  return {
    scope: "selection",
    ids: normalizedIds,
    names,
    summary: `${normalizedIds.length} od ${companyLocations.length} lokacija`,
  };
}

function isOfferExtraTextEnabled() {
  return Boolean(offerExtraTextEnabledInput?.checked && !isCommercialQuickUploadMode());
}

function getOfferPreparedByLabelForDraft() {
  const currentOfferId = String(offerIdInput?.value || "").trim();
  const currentOffer = currentOfferId ? getCurrentCommercialDocumentById(currentOfferId) : null;
  return String(
    currentOffer?.createdByLabel
      || currentOffer?.preparedByLabel
      || getUserDisplayLabel(state.user ?? {})
      || state.user?.email
      || "",
  ).trim();
}

function hasSerializedCommercialBreakdowns(items = []) {
  return Array.isArray(items) && items.some((item) => hasCommercialItemBreakdownRows(item));
}

function shouldShowOfferTotalAmountOnDocument({
  quickMode = false,
  isPurchaseOrder = false,
  serviceLine = "",
  items = [],
} = {}) {
  if (quickMode) {
    return false;
  }
  if (isPurchaseOrder) {
    return isOfferTotalVisible();
  }

  const planType = getCommercialItemsTablePlanType(serviceLine);
  if (planType === "Fixed Plan") {
    return true;
  }
  if (planType === "Hybrid Plan" || hasSerializedCommercialBreakdowns(items)) {
    return false;
  }
  return isOfferTotalVisible();
}

function buildOfferDraftPreviewData() {
  const isPurchaseOrder = isPurchaseOrdersContextActive();
  const activeDirection = getActiveCommercialDocumentDirection();
  const includeUploadedDocuments = shouldShowCommercialDocumentUploadSection();
  const companyId = String(offerCompanyIdInput?.value || "").trim();
  const company = state.companies.find((item) => String(item.id) === companyId) ?? null;
  const locationSelection = buildOfferLocationSummaryFromSelection(offerFormSelectedLocationIds, companyId);
  const contactSnapshot = getSelectedOfferContactSnapshot();
  const quickMode = isCommercialQuickUploadMode();
  const outgoingStandaloneOffer = isOutgoingStandaloneOfferMode();
  const documentItems = buildOfferDocumentItemsForPayload();
  const totals = quickMode
    ? calculateOfferTotalsForSerializedItems(documentItems, 0, 0)
    : getOfferDraftTotals();
  const currentNumber = String(offerNumberPreview?.textContent || "").trim();
  const documentDrafts = purchaseOrderDocumentDrafts.map((entry) => serializeModuleAttachmentDraft(entry));
  const currentDate = getOfferDateFieldValue();
  const rawServiceLine = String((quickMode && !outgoingStandaloneOffer ? offerTitleInput?.value : offerServiceLineInput?.value) || "").trim();
  const serviceLine = !isPurchaseOrder && activeDirection === "outgoing"
    ? normalizeOfferPlanTypeValue(rawServiceLine)
    : rawServiceLine;
  const payloadItems = quickMode ? documentItems : serializeOfferItemsForPayload();
  const preparedByLabel = getOfferPreparedByLabelForDraft();

  return {
    id: String(offerIdInput?.value || "").trim(),
    offerNumber: isPurchaseOrder ? "" : currentNumber,
    purchaseOrderNumber: isPurchaseOrder ? currentNumber : "",
    offerDirection: isPurchaseOrder ? "" : activeDirection,
    title: String(offerTitleInput?.value || "").trim(),
    status: String(offerStatusInput?.value || getActiveCommercialDocumentConfig().defaultStatus).trim(),
    offerDate: isPurchaseOrder ? "" : currentDate,
    purchaseOrderDate: isPurchaseOrder ? currentDate : "",
    validUntil: "",
    companyId,
    companyName: company?.name || "",
    companyOib: company?.oib || "",
    headquarters: company?.headquarters || "",
    selectedLocationIds: [...locationSelection.ids],
    selectedLocationNames: [...locationSelection.names],
    locationScope: locationSelection.scope,
    locationName: locationSelection.summary,
    contactName: contactSnapshot.contactName || "",
    contactPhone: contactSnapshot.contactPhone || "",
    contactEmail: contactSnapshot.contactEmail || "",
    serviceLine,
    note: String(offerNoteInput?.value || "").trim(),
    textBlock1: isOfferExtraTextEnabled() ? String(offerTextBlock1Input?.value || "").trim() : "",
    textBlock2: isOfferExtraTextEnabled() ? String(offerTextBlock2Input?.value || "").trim() : "",
    createdByLabel: preparedByLabel,
    preparedByLabel,
    orderDirection: isPurchaseOrder ? activeDirection : "",
    documentMode: quickMode ? "upload" : "app",
    internalDocumentNumber: outgoingStandaloneOffer ? "" : String(commercialInternalNumberInput?.value || "").trim(),
    externalDocumentNumber: outgoingStandaloneOffer
      ? ""
      : (isPurchaseOrder
        ? String(commercialExternalNumberInput?.value || purchaseOrderExternalNumberInput?.value || "").trim()
        : String(commercialExternalNumberInput?.value || "").trim()),
    documents: includeUploadedDocuments ? documentDrafts : [],
    currency: "EUR",
    taxRate: totals.taxRate,
    discountRate: totals.discountRate,
    subtotal: totals.subtotal,
    discountTotal: totals.discountTotal,
    taxableSubtotal: totals.taxableSubtotal,
    taxTotal: totals.taxTotal,
    total: totals.total,
    showTotalAmount: shouldShowOfferTotalAmountOnDocument({
      quickMode,
      isPurchaseOrder,
      serviceLine,
      items: payloadItems,
    }),
    items: payloadItems.map((item) => ({
      description: String(item?.description || "").trim(),
      unit: String(item?.unit || "").trim(),
      quantity: parseOfferMoneyInput(item?.quantity, 0),
      unitPrice: parseOfferMoneyInput(item?.unitPrice, 0),
      isIncludedService: Boolean(item?.isIncludedService),
      breakdowns: Array.isArray(item?.breakdowns)
        ? item.breakdowns.map((entry) => ({
          priceKind: String(entry?.priceKind || "").trim(),
          unitLabel: String(entry?.unitLabel || "").trim(),
          recordLabel: String(entry?.recordLabel || entry?.label || "").trim(),
          measurementFrom: String(entry?.measurementFrom || "").trim(),
          measurementTo: String(entry?.measurementTo || "").trim(),
          label: String(entry?.label || entry?.unitLabel || entry?.recordLabel || "").trim(),
          amount: parseOfferMoneyInput(entry?.amount, 0),
        })).filter((entry) => entry.recordLabel || entry.unitLabel || entry.measurementFrom || entry.measurementTo || entry.amount)
        : [],
      discountRate: parseOfferMoneyInput(item?.discountRate, 0),
      totalPrice: calculateOfferTotalsForSerializedItems([item], 0, 0).subtotal,
    })),
  };
}

function getCommercialItemsTablePlanType(value = "") {
  const normalizedValue = normalizeOfferPlanTypeValue(value);
  return OFFER_PLAN_TYPE_DEFINITIONS.some((entry) => entry.value === normalizedValue)
    ? normalizedValue
    : "";
}

function hasCommercialItemBreakdownRows(item = {}) {
  return Array.isArray(item?.breakdowns) && item.breakdowns.some((entry) => (
    String(entry?.recordLabel || entry?.label || entry?.unitLabel || "").trim()
      || String(entry?.measurementFrom || "").trim()
      || String(entry?.measurementTo || "").trim()
      || parseOfferMoneyInput(entry?.amount, 0) > 0
  ));
}

function buildCommercialTableCellPreview(text = "", format = {}) {
  return {
    text: String(text ?? ""),
    format: {
      fontFamily: "arial",
      fontSize: 9,
      bold: false,
      border: { top: true, right: true, bottom: true, left: true },
      ...format,
    },
  };
}

function getCommercialTableQuantityText(item = {}) {
  const rawQuantity = String(item?.quantity ?? "").trim();
  const unit = String(item?.unit || "").trim();
  if (!rawQuantity && !unit) {
    return "";
  }
  return [rawQuantity || "1", unit].filter(Boolean).join(" ");
}

function getCommercialTableMoneyText(value, currency = "EUR", { showZero = false } = {}) {
  const numeric = parseOfferMoneyInput(value, 0);
  if (!showZero && numeric === 0) {
    return "";
  }
  return formatCurrencyAmount(numeric, currency);
}

function getCommercialFinancialRowsPreview(source = {}, currency = "EUR") {
  const hasDiscount = Number(source?.discountRate || 0) > 0 || Number(source?.discountTotal || 0) > 0;
  const taxRate = String(source?.taxRate ?? "").trim();
  const rows = [
    {
      id: "subtotal",
      label: "Međuzbroj",
      amount: formatCurrencyAmount(source?.subtotal || 0, currency),
    },
  ];

  if (hasDiscount) {
    rows.push(
      {
        id: "discount",
        label: Number(source?.discountRate || 0) > 0 ? `Rabat (${source.discountRate}%)` : "Rabat",
        amount: formatCurrencyAmount(source?.discountTotal || 0, currency),
      },
      {
        id: "taxable-subtotal",
        label: "Osnovica za PDV",
        amount: formatCurrencyAmount(source?.taxableSubtotal || 0, currency),
      },
    );
  }

  rows.push(
    {
      id: "tax",
      label: taxRate ? `PDV (${taxRate}%)` : "PDV",
      amount: formatCurrencyAmount(source?.taxTotal || 0, currency),
    },
    {
      id: "total",
      label: "Ukupno s PDV-om",
      amount: formatCurrencyAmount(source?.total || 0, currency),
      isGrand: true,
    },
  );

  return rows;
}

function getCommercialBreakdownRangeText(entry = {}) {
  const priceKind = String(entry?.priceKind || "").trim();
  const measurementFrom = String(entry?.measurementFrom || "").trim();
  const measurementTo = String(entry?.measurementTo || "").trim();
  if (priceKind === "measurement") {
    return measurementTo ? `do ${measurementTo}` : "";
  }
  if (priceKind === "measurement_range") {
    return [measurementFrom, measurementTo].filter(Boolean).join(" - ");
  }
  return "";
}

function getCommercialBreakdownDocumentLabel(entry = {}) {
  const priceKind = String(entry?.priceKind || "").trim();
  const label = getOfferBreakdownDisplayLabel(entry);
  const measurementFrom = String(entry?.measurementFrom || "").trim();
  const measurementTo = String(entry?.measurementTo || "").trim();

  if (priceKind === "measurement" && measurementTo) {
    return `Do ${measurementTo} mjernih mjesta`;
  }
  if (priceKind === "measurement_range") {
    if (measurementFrom && measurementTo) {
      return `Od ${measurementFrom} do ${measurementTo} mjernog mjesta`;
    }
    const range = [measurementFrom, measurementTo].filter(Boolean).join(" - ");
    return range ? `Od-Do ${range} mjernog mjesta` : label;
  }
  if (priceKind === "next_measurement") {
    return "Svako iduće mjerno mjesto";
  }
  return label;
}

function buildCommercialItemAmountText(item = {}, currency = "EUR") {
  if (isCommercialIncludedServiceItem(item)) {
    return "Uključeno";
  }
  const total = parseOfferMoneyInput(item?.totalPrice, 0);
  if (total > 0) {
    return getCommercialTableMoneyText(total, currency);
  }
  const breakdownTotal = Array.isArray(item?.breakdowns)
    ? item.breakdowns.reduce((sum, entry) => sum + Math.max(0, parseOfferMoneyInput(entry?.amount, 0)), 0)
    : 0;
  if (breakdownTotal > 0) {
    return getCommercialTableMoneyText(breakdownTotal, currency);
  }
  const quantity = Math.max(0, parseOfferMoneyInput(item?.quantity, 0));
  const unitPrice = Math.max(0, parseOfferMoneyInput(item?.unitPrice, 0));
  if (quantity > 0 && unitPrice > 0) {
    return getCommercialTableMoneyText(quantity * unitPrice, currency);
  }
  return getCommercialTableMoneyText(unitPrice, currency);
}

function isCommercialIncludedServiceItem(item = {}) {
  return Boolean(item?.isIncludedService || item?.includedService || item?.includedInPlan || item?.included);
}

function getCommercialOfferMonthlyItems(items = [], offerType = "") {
  const planType = getCommercialItemsTablePlanType(offerType);
  const safeItems = Array.isArray(items) ? items : [];
  if (planType === "Hybrid Plan") {
    return safeItems.filter((item) => isOfferMainFeeItemDraft(item));
  }
  if (planType === "Fixed Plan") {
    return safeItems.filter((item) => !isCommercialIncludedServiceItem(item));
  }
  return [];
}

function getCommercialOfferServicePricingItems(items = [], offerType = "") {
  const planType = getCommercialItemsTablePlanType(offerType);
  const safeItems = Array.isArray(items) ? items : [];
  if (planType === "Fixed Plan") {
    return [];
  }
  if (planType === "Hybrid Plan") {
    return safeItems.filter((item) => !isOfferMainFeeItemDraft(item));
  }
  return safeItems;
}

function buildCommercialItemsTablePlaceholderPreview(items = [], currency = "EUR", {
  fallbackTitle = "Opis stavke",
  offerType = "",
  showTotalAmount = true,
  totals = null,
  section = "all",
  includeHeader = true,
  emptyMessage = "Nema dodanih stavki.",
} = {}) {
  const allItems = Array.isArray(items) ? items : [];
  const planType = getCommercialItemsTablePlanType(offerType);
  const isFixedPlan = planType === "Fixed Plan";
  const isHybridPlan = planType === "Hybrid Plan";
  const isFinancialPlan = section === "all" && ["Fixed Plan", "One-Time Service", "Per Employee Plan"].includes(planType);
  const safeItems = section === "monthly"
    ? getCommercialOfferMonthlyItems(allItems, offerType)
    : section === "services"
      ? getCommercialOfferServicePricingItems(allItems, offerType)
      : allItems;
  const columns = isFinancialPlan
    ? [
      { id: "index", label: "#", width: 42 },
      { id: "description", label: fallbackTitle, width: 330 },
      { id: "unit", label: "Jed.", width: 54 },
      { id: "quantity", label: "Kol.", width: 54 },
      { id: "unitPrice", label: "Cijena", width: 86 },
      { id: "amount", label: "Iznos", width: 98 },
    ]
    : [
      { id: "description", label: fallbackTitle, width: 520 },
      { id: "amount", label: "Iznos", width: 120 },
    ];
  const merges = [];
  const rows = [];
  if (includeHeader) {
    rows.push({
      id: "header",
      header: true,
      cells: columns.map((column) => buildCommercialTableCellPreview(column.label, {
        bold: true,
        fillColor: "#F3F4F6",
        align: column.id === "amount" ? "right" : "left",
      })),
    });
  }

  const pushRow = (id, description = "", amount = "", format = {}) => {
    rows.push({
      id,
      cells: [
        buildCommercialTableCellPreview(description, { align: "left", ...format }),
        buildCommercialTableCellPreview(amount, { align: "right", ...format }),
      ],
    });
  };

  const pushMergedRow = (id, description = "", format = {}) => {
    rows.push({
      id,
      cells: [
        buildCommercialTableCellPreview(description, { align: "left", ...format }),
        buildCommercialTableCellPreview("", { align: "right", ...format }),
      ],
    });
    merges.push({ rowId: id, columnId: "description", colSpan: 2 });
  };

  const pushBreakdownRows = (item, itemIndex) => {
    const breakdowns = Array.isArray(item?.breakdowns) ? item.breakdowns : [];
    breakdowns
      .filter((entry) => (
        String(entry?.recordLabel || entry?.label || entry?.unitLabel || "").trim()
          || String(entry?.measurementFrom || "").trim()
          || String(entry?.measurementTo || "").trim()
          || parseOfferMoneyInput(entry?.amount, 0) > 0
      ))
      .forEach((entry, breakdownIndex) => {
        pushRow(
          `item-${itemIndex + 1}-breakdown-${breakdownIndex + 1}`,
          `    - ${getCommercialBreakdownDocumentLabel(entry)}`,
          getCommercialTableMoneyText(entry?.amount, currency),
          { fillColor: "#FFFFFF", color: "#334155" },
        );
      });
  };

  const pushFinancialItemRow = (item, index) => {
    const breakdowns = Array.isArray(item?.breakdowns) ? item.breakdowns.filter((entry) => (
      String(entry?.recordLabel || entry?.label || entry?.unitLabel || "").trim()
        || String(entry?.measurementFrom || "").trim()
        || String(entry?.measurementTo || "").trim()
        || parseOfferMoneyInput(entry?.amount, 0) > 0
    )) : [];
    const included = Boolean(item?.isIncludedService || item?.includedService || item?.includedInPlan || item?.included);
    const description = [
      item?.description || item?.serviceCode || "Stavka",
      parseOfferMoneyInput(item?.discountRate, 0) > 0 ? `Rabat stavke: ${item.discountRate}%` : "",
      included ? "Uključeno u plan" : "",
    ].filter(Boolean).join("\n");
    rows.push({
      id: `financial-item-${index + 1}`,
      cells: [
        buildCommercialTableCellPreview(String(index + 1), { align: "center" }),
        buildCommercialTableCellPreview(description, { align: "left", bold: true }),
        buildCommercialTableCellPreview(included ? "" : String(item?.unit || ""), { align: "center" }),
        buildCommercialTableCellPreview(included ? "" : String(item?.quantity ?? ""), { align: "center" }),
        buildCommercialTableCellPreview(included ? "" : getCommercialTableMoneyText(item?.unitPrice, currency), { align: "right" }),
        buildCommercialTableCellPreview(included ? "Uključeno" : buildCommercialItemAmountText(item, currency), {
          align: "right",
          bold: true,
          color: included ? "#047857" : "#0F172A",
        }),
      ],
    });
    breakdowns.forEach((entry, breakdownIndex) => {
      const rowId = `financial-item-${index + 1}-breakdown-${breakdownIndex + 1}`;
      rows.push({
        id: rowId,
        cells: [
          buildCommercialTableCellPreview(`- ${getCommercialBreakdownDocumentLabel(entry)}`, {
            align: "left",
            fillColor: "#F8FAFC",
            color: "#334155",
          }),
          buildCommercialTableCellPreview("", { fillColor: "#F8FAFC" }),
          buildCommercialTableCellPreview("", { fillColor: "#F8FAFC" }),
          buildCommercialTableCellPreview("", { fillColor: "#F8FAFC" }),
          buildCommercialTableCellPreview("", { fillColor: "#F8FAFC" }),
          buildCommercialTableCellPreview(getCommercialTableMoneyText(entry?.amount, currency), {
            align: "right",
            bold: true,
            fillColor: "#F8FAFC",
            color: "#0F172A",
          }),
        ],
      });
      merges.push({ rowId, columnId: "index", colSpan: 5 });
    });
  };

  const pushFinancialTotals = () => {
    if (!totals || typeof totals !== "object") {
      return;
    }
    getCommercialFinancialRowsPreview(totals, currency).forEach((row) => {
      const rowId = `financial-total-${row.id}`;
      rows.push({
        id: rowId,
        cells: [
          buildCommercialTableCellPreview(row.label, {
            align: "right",
            bold: true,
            fillColor: row.isGrand ? "#ECFDF5" : "#F8FAFC",
            color: row.isGrand ? "#047857" : "#0F172A",
          }),
          buildCommercialTableCellPreview("", { fillColor: row.isGrand ? "#ECFDF5" : "#F8FAFC" }),
          buildCommercialTableCellPreview("", { fillColor: row.isGrand ? "#ECFDF5" : "#F8FAFC" }),
          buildCommercialTableCellPreview("", { fillColor: row.isGrand ? "#ECFDF5" : "#F8FAFC" }),
          buildCommercialTableCellPreview("", { fillColor: row.isGrand ? "#ECFDF5" : "#F8FAFC" }),
          buildCommercialTableCellPreview(row.amount, {
            align: "right",
            bold: true,
            fillColor: row.isGrand ? "#ECFDF5" : "#F8FAFC",
            color: row.isGrand ? "#047857" : "#0F172A",
          }),
        ],
      });
      merges.push({ rowId, columnId: "index", colSpan: 5 });
    });
  };

  const buildTableBlock = (tableColumns = columns, tableRows = rows, tableMerges = merges, tableHeaderRows = includeHeader ? ["header"] : []) => ({
    __docxBlockType: "table",
    columns: tableColumns,
    rows: tableRows,
    headerRows: tableHeaderRows,
    merges: tableMerges,
  });

  const buildFixedIncludedServicesTableBlock = (includedItems = []) => {
    const serviceColumns = [
      { id: "index", label: "#", width: 42 },
      { id: "code", label: "Šifra", width: 92 },
      { id: "description", label: "Usluga uključena u paušal", width: 520 },
    ];
    const serviceRows = [
      {
        id: "included-header",
        header: true,
        cells: serviceColumns.map((column) => buildCommercialTableCellPreview(column.label, {
          bold: true,
          fillColor: "#F3F4F6",
          align: column.id === "index" ? "center" : "left",
        })),
      },
      ...(includedItems.length > 0
        ? includedItems.map((item, index) => ({
          id: `included-service-${index + 1}`,
          cells: [
            buildCommercialTableCellPreview(String(index + 1), { align: "center" }),
            buildCommercialTableCellPreview(item?.serviceCode || "", { align: "left", color: "#475569" }),
            buildCommercialTableCellPreview(item?.description || item?.serviceCode || "Usluga", { align: "left", bold: true }),
          ],
        }))
        : [{
          id: "included-empty",
          cells: [
            buildCommercialTableCellPreview("Nema dodanih uključenih usluga.", { align: "left", color: "#64748B" }),
            buildCommercialTableCellPreview("", {}),
            buildCommercialTableCellPreview("", {}),
          ],
        }]),
    ];
    const serviceMerges = includedItems.length > 0
      ? []
      : [{ rowId: "included-empty", columnId: "index", colSpan: serviceColumns.length }];

    return buildTableBlock(serviceColumns, serviceRows, serviceMerges, ["included-header"]);
  };

  const buildHybridMonthlyFeesTableBlock = (monthlyItems = []) => {
    const monthlyColumns = [
      { id: "index", label: "#", width: 42 },
      { id: "description", label: "Mjesečna naknada", width: 300 },
      { id: "unit", label: "Jed.", width: 54 },
      { id: "quantity", label: "Kol.", width: 54 },
      { id: "unitPrice", label: "Cijena", width: 90 },
      { id: "amount", label: "Iznos", width: 98 },
    ];
    const monthlyRows = [{
      id: "monthly-header",
      header: true,
      cells: monthlyColumns.map((column) => buildCommercialTableCellPreview(column.label, {
        bold: true,
        fillColor: "#DBEAFE",
        color: "#1D4ED8",
        align: ["index", "unit", "quantity"].includes(column.id) ? "center" : (column.id === "amount" || column.id === "unitPrice" ? "right" : "left"),
      })),
    }];
    const monthlyMerges = [];
    if (monthlyItems.length === 0) {
      monthlyRows.push({
        id: "monthly-empty",
        cells: monthlyColumns.map((column, index) => buildCommercialTableCellPreview(index === 0 ? "Nema mjesečnih naknada." : "", {
          color: "#64748B",
        })),
      });
      monthlyMerges.push({ rowId: "monthly-empty", columnId: "index", colSpan: monthlyColumns.length });
    } else {
      monthlyItems.forEach((item, index) => {
        monthlyRows.push({
          id: `monthly-fee-${index + 1}`,
          cells: [
            buildCommercialTableCellPreview(String(index + 1), { align: "center", fillColor: "#EFF6FF" }),
            buildCommercialTableCellPreview(item?.description || "Mjesečna naknada", { align: "left", bold: true, fillColor: "#EFF6FF", color: "#0F172A" }),
            buildCommercialTableCellPreview(String(item?.unit || ""), { align: "center", fillColor: "#EFF6FF" }),
            buildCommercialTableCellPreview(String(item?.quantity ?? ""), { align: "center", fillColor: "#EFF6FF" }),
            buildCommercialTableCellPreview(getCommercialTableMoneyText(item?.unitPrice, currency), { align: "right", fillColor: "#EFF6FF" }),
            buildCommercialTableCellPreview(buildCommercialItemAmountText(item, currency), { align: "right", bold: true, fillColor: "#EFF6FF", color: "#1D4ED8" }),
          ],
        });
      });
    }
    return buildTableBlock(monthlyColumns, monthlyRows, monthlyMerges, ["monthly-header"]);
  };

  const buildHybridServicePricingTableBlock = (serviceItems = []) => {
    const serviceColumns = [
      { id: "index", label: "#", width: 42 },
      { id: "description", label: "Usluga / razrada", width: 382 },
      { id: "unit", label: "Jedinica", width: 90 },
      { id: "amount", label: "Cijena", width: 120 },
    ];
    const serviceRows = [{
      id: "service-header",
      header: true,
      cells: serviceColumns.map((column) => buildCommercialTableCellPreview(column.label, {
        bold: true,
        fillColor: "#E0E7FF",
        color: "#3730A3",
        align: column.id === "index" || column.id === "unit" ? "center" : (column.id === "amount" ? "right" : "left"),
      })),
    }];
    const serviceMerges = [];
    if (serviceItems.length === 0) {
      serviceRows.push({
        id: "service-empty",
        cells: serviceColumns.map((column, index) => buildCommercialTableCellPreview(index === 0 ? "Nema usluga u cjeniku." : "", {
          color: "#64748B",
        })),
      });
      serviceMerges.push({ rowId: "service-empty", columnId: "index", colSpan: serviceColumns.length });
    } else {
      serviceItems.forEach((item, index) => {
        const breakdowns = Array.isArray(item?.breakdowns) ? item.breakdowns.filter((entry) => (
          String(entry?.recordLabel || entry?.label || entry?.unitLabel || "").trim()
            || String(entry?.measurementFrom || "").trim()
            || String(entry?.measurementTo || "").trim()
            || parseOfferMoneyInput(entry?.amount, 0) > 0
        )) : [];
        if (breakdowns.length === 0) {
          serviceRows.push({
            id: `service-item-${index + 1}`,
            cells: [
              buildCommercialTableCellPreview(String(index + 1), { align: "center", fillColor: "#F8FAFC" }),
              buildCommercialTableCellPreview(item?.description || item?.serviceCode || "Usluga", { align: "left", bold: true, fillColor: "#F8FAFC" }),
              buildCommercialTableCellPreview(getCommercialTableQuantityText(item) || item?.unit || "po usluzi", { align: "center", fillColor: "#F8FAFC" }),
              buildCommercialTableCellPreview(buildCommercialItemAmountText(item, currency), { align: "right", bold: true, fillColor: "#F8FAFC" }),
            ],
          });
          return;
        }

        const groupRowId = `service-group-${index + 1}`;
        serviceRows.push({
          id: groupRowId,
          cells: [
            buildCommercialTableCellPreview(String(index + 1), { align: "center", bold: true, fillColor: "#E0F2FE", color: "#0369A1" }),
            buildCommercialTableCellPreview(item?.description || item?.serviceCode || "Usluga", { align: "left", bold: true, fillColor: "#E0F2FE", color: "#0F172A" }),
            buildCommercialTableCellPreview("", { fillColor: "#E0F2FE" }),
            buildCommercialTableCellPreview("", { fillColor: "#E0F2FE" }),
          ],
        });
        serviceMerges.push({ rowId: groupRowId, columnId: "description", colSpan: 3 });
        breakdowns.forEach((entry, breakdownIndex) => {
          serviceRows.push({
            id: `service-item-${index + 1}-breakdown-${breakdownIndex + 1}`,
            cells: [
              buildCommercialTableCellPreview("", { align: "center", fillColor: "#FFFFFF" }),
              buildCommercialTableCellPreview(`    - ${getCommercialBreakdownDocumentLabel(entry)}`, { align: "left", color: "#334155", fillColor: "#FFFFFF" }),
              buildCommercialTableCellPreview(entry?.unitLabel || "", { align: "center", color: "#475569", fillColor: "#FFFFFF" }),
              buildCommercialTableCellPreview(getCommercialTableMoneyText(entry?.amount, currency), { align: "right", bold: true, fillColor: "#FFFFFF" }),
            ],
          });
        });
      });
    }
    return buildTableBlock(serviceColumns, serviceRows, serviceMerges, ["service-header"]);
  };

  const buildHybridTotalsTableBlock = () => {
    const totalColumns = [
      { id: "label", label: "Ukupni iznosi", width: 500 },
      { id: "amount", label: "Iznos", width: 130 },
    ];
    const totalRows = [{
      id: "totals-header",
      header: true,
      cells: totalColumns.map((column) => buildCommercialTableCellPreview(column.label, {
        bold: true,
        fillColor: "#F3F4F6",
        align: column.id === "amount" ? "right" : "left",
      })),
    }];
    getCommercialFinancialRowsPreview(totals || {}, currency).forEach((row) => {
      totalRows.push({
        id: `hybrid-total-${row.id}`,
        cells: [
          buildCommercialTableCellPreview(row.label, {
            align: "right",
            bold: true,
            fillColor: row.isGrand ? "#ECFDF5" : "#F8FAFC",
            color: row.isGrand ? "#047857" : "#0F172A",
          }),
          buildCommercialTableCellPreview(row.amount, {
            align: "right",
            bold: true,
            fillColor: row.isGrand ? "#ECFDF5" : "#F8FAFC",
            color: row.isGrand ? "#047857" : "#0F172A",
          }),
        ],
      });
    });
    return buildTableBlock(totalColumns, totalRows, [], ["totals-header"]);
  };

  if (isHybridPlan) {
    const monthlyItems = getCommercialOfferMonthlyItems(allItems, offerType);
    const serviceItems = getCommercialOfferServicePricingItems(allItems, offerType);
    if (section === "monthly") {
      return buildHybridMonthlyFeesTableBlock(monthlyItems);
    }
    if (section === "services") {
      return buildHybridServicePricingTableBlock(serviceItems);
    }
    if (section === "all") {
      const blocks = [
        { type: "heading", text: "Mjesečne naknade", level: 4 },
        buildHybridMonthlyFeesTableBlock(monthlyItems),
        { type: "heading", text: "Cjenik usluga po izvršenju", level: 4 },
        buildHybridServicePricingTableBlock(serviceItems),
      ];
      if (showTotalAmount && totals && typeof totals === "object") {
        blocks.push(
          { type: "heading", text: "Ukupni iznosi", level: 4 },
          buildHybridTotalsTableBlock(),
        );
      }
      return { __docxBlockType: "blocks", blocks };
    }
  }

  if (isFinancialPlan) {
    if (isFixedPlan && section === "all") {
      const billableItems = safeItems.filter((item) => !isCommercialIncludedServiceItem(item));
      const includedItems = safeItems.filter((item) => isCommercialIncludedServiceItem(item));
      if (billableItems.length === 0) {
        const rowId = "empty";
        rows.push({
          id: rowId,
          cells: columns.map((column, index) => buildCommercialTableCellPreview(index === 0 ? "Nema dodanih fiksnih stavki." : "", {
            align: index === columns.length - 1 ? "right" : "left",
            color: "#64748B",
          })),
        });
        merges.push({ rowId, columnId: "index", colSpan: columns.length });
      } else {
        billableItems.forEach((item, index) => {
          pushFinancialItemRow(item, index);
        });
        if (showTotalAmount) {
          pushFinancialTotals();
        }
      }

      if (includedItems.length > 0) {
        return {
          __docxBlockType: "blocks",
          blocks: [
            { type: "heading", text: "Fiksne stavke ponude", level: 4 },
            buildTableBlock(),
            { type: "heading", text: "Uključene usluge", level: 4 },
            buildFixedIncludedServicesTableBlock(includedItems),
          ],
        };
      }
      return buildTableBlock();
    }

    if (safeItems.length === 0) {
      const rowId = "empty";
      rows.push({
        id: rowId,
        cells: columns.map((column, index) => buildCommercialTableCellPreview(index === 0 ? emptyMessage : "", {
          align: index === columns.length - 1 ? "right" : "left",
          color: "#64748B",
        })),
      });
      merges.push({ rowId, columnId: "index", colSpan: columns.length });
    } else {
      safeItems.forEach((item, index) => {
        pushFinancialItemRow(item, index);
      });
      if (showTotalAmount) {
        pushFinancialTotals();
      }
    }
  } else if (safeItems.length === 0) {
    pushRow("empty", emptyMessage, "");
  } else if (section === "monthly") {
    safeItems.forEach((item, index) => {
      pushRow(
        `monthly-fee-${index + 1}`,
        item?.description || "Mjesečna naknada",
        buildCommercialItemAmountText(item, currency),
      );
    });
  } else if (section === "services") {
    safeItems.forEach((item, index) => {
      const hasBreakdowns = hasCommercialItemBreakdownRows(item);
      if (hasBreakdowns) {
        pushMergedRow(`service-item-${index + 1}`, item?.description || "Usluga", { fillColor: "#FFFFFF" });
        pushBreakdownRows(item, index);
      } else {
        pushRow(
          `service-item-${index + 1}`,
          item?.description || "Usluga",
          !showTotalAmount ? "" : buildCommercialItemAmountText(item, currency),
        );
      }
    });
  } else if (isFixedPlan) {
    const fixedItems = safeItems;
    fixedItems.forEach((item, index) => {
      pushRow(
        `fixed-item-${index + 1}`,
        item?.description || "Stavka",
        buildCommercialItemAmountText(item, currency),
      );
    });

    if (showTotalAmount && fixedItems.length > 0) {
      const fixedTotal = fixedItems.reduce((sum, item) => sum + parseOfferMoneyInput(item?.totalPrice || getOfferLineTotal(item), 0), 0);
      pushRow("fixed-total", "Ukupno", getCommercialTableMoneyText(fixedTotal, currency, { showZero: true }), { fillColor: "#F8FAFC" });
    }
  } else if (isHybridPlan) {
    const feeItems = getCommercialOfferMonthlyItems(safeItems, offerType);
    const serviceItems = getCommercialOfferServicePricingItems(safeItems, offerType);

    if (feeItems.length > 0) {
      pushMergedRow("monthly-fees-section", "Mjesečne naknade", { fillColor: "#DBEAFE", color: "#1D4ED8", bold: true });
      feeItems.forEach((item, index) => {
        pushRow(
          `monthly-fee-${index + 1}`,
          item?.description || "Mjesečna naknada",
          buildCommercialItemAmountText(item, currency),
          { fillColor: "#EFF6FF", bold: true },
        );
      });
    }

    if (serviceItems.length > 0) {
      pushMergedRow("service-pricing-section", "Cjenik usluga", { fillColor: "#E0E7FF", color: "#3730A3", bold: true });
      serviceItems.forEach((item, index) => {
        pushMergedRow(`service-item-${index + 1}`, item?.description || "Usluga", { fillColor: "#E0F2FE", color: "#0F172A", bold: true });
        pushBreakdownRows(item, index);
      });
    }

    if (section === "all" && showTotalAmount && totals && typeof totals === "object") {
      getCommercialFinancialRowsPreview(totals, currency).forEach((row) => {
        pushRow(
          `hybrid-total-${row.id}`,
          row.label,
          row.amount,
          {
            align: "right",
            bold: true,
            fillColor: row.isGrand ? "#ECFDF5" : "#F8FAFC",
            color: row.isGrand ? "#047857" : "#0F172A",
          },
        );
      });
    }
  } else {
    safeItems.forEach((item, index) => {
      const hasBreakdowns = hasCommercialItemBreakdownRows(item);
      if (hasBreakdowns) {
        pushMergedRow(`item-${index + 1}`, item?.description || "Usluga", { fillColor: "#F8FAFC" });
      } else {
        pushRow(
          `item-${index + 1}`,
          item?.description || "Stavka",
          !showTotalAmount ? "" : buildCommercialItemAmountText(item, currency),
        );
      }
      if (hasBreakdowns) {
        pushBreakdownRows(item, index);
      }
    });
  }

  return {
    ...buildTableBlock(),
  };
}

function formatCommercialTemplatePlaceholderPreviewValue(value) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    if (String(value.__docxBlockType || value.type || "").trim().toLowerCase() === "table") {
      const rows = Array.isArray(value.rows) ? value.rows : [];
      const bodyRows = rows.filter((row) => !row?.header);
      return `${bodyRows.length} redaka Word tablice`;
    }
    if (String(value.__docxBlockType || value.type || "").trim().toLowerCase() === "blocks") {
      const blocks = Array.isArray(value.blocks) ? value.blocks : [];
      const tableCount = blocks.filter((block) => String(block?.__docxBlockType || block?.type || "").trim().toLowerCase() === "table").length;
      return tableCount ? `${tableCount} Word tablice u placeholderu` : `${blocks.length} Word blokova`;
    }
    return "";
  }

  return String(value ?? "");
}

function buildOfferTemplatePlaceholderPayload(offer = buildOfferDraftPreviewData()) {
  const normalizedOffer = offer || {};
  const isPurchaseOrder = isPurchaseOrdersContextActive()
    || Boolean(normalizedOffer.purchaseOrderNumber)
    || Boolean(normalizedOffer.orderDirection);
  const currency = normalizedOffer.currency || "EUR";
  const planType = getCommercialItemsTablePlanType(normalizedOffer.serviceLine || "");
  const itemsFallbackTitle = !isPurchaseOrder && planType === "Per Employee Plan"
    ? "Cijena po zaposleniku"
    : isPurchaseOrder
      ? "Opis narudžbe"
      : "Opis stavke";
  const suppressItemTotals = !isPurchaseOrder
    && (planType === "Hybrid Plan" || hasSerializedCommercialBreakdowns(normalizedOffer.items ?? []));
  const itemsSummary = (normalizedOffer.items ?? [])
    .map((item, index) => `${index + 1}. ${item.description || "Stavka"}${item.unit ? ` · ${item.quantity} ${item.unit}` : ""}${item?.isIncludedService ? " · Uključeno" : (!suppressItemTotals && Number(item.totalPrice || 0) > 0 ? ` · ${formatCurrencyAmount(item.totalPrice || 0, currency)}` : "")}`)
    .join("\n");
  const itemsTableText = (normalizedOffer.items ?? [])
    .map((item, index) => {
      const breakdownText = Array.isArray(item.breakdowns) && item.breakdowns.length > 0
        ? `\n${item.breakdowns.map((entry) => `   - ${getOfferBreakdownDisplayLabel(entry)}: ${formatCurrencyAmount(entry.amount || 0, currency)}`).join("\n")}`
        : "";
      const amountText = item?.isIncludedService
        ? "Uključeno"
        : suppressItemTotals
        ? formatCurrencyAmount(item.unitPrice || 0, currency)
        : formatCurrencyAmount(item.totalPrice || 0, currency);
      return `${index + 1}. ${item.description || "Stavka"} | ${item.quantity || 0} ${item.unit || ""} | ${amountText}${breakdownText}`;
    })
    .join("\n");
  const itemsTable = buildCommercialItemsTablePlaceholderPreview(
    normalizedOffer.items ?? [],
    currency,
    {
      fallbackTitle: itemsFallbackTitle,
      offerType: isPurchaseOrder ? "" : normalizedOffer.serviceLine,
      showTotalAmount: normalizedOffer.showTotalAmount !== false,
      totals: normalizedOffer,
    },
  );
  const monthlyItems = getCommercialOfferMonthlyItems(normalizedOffer.items ?? [], isPurchaseOrder ? "" : normalizedOffer.serviceLine);
  const servicePricingItems = getCommercialOfferServicePricingItems(normalizedOffer.items ?? [], isPurchaseOrder ? "" : normalizedOffer.serviceLine);
  const monthlyFeesTable = monthlyItems.length > 0
    ? buildCommercialItemsTablePlaceholderPreview(
      normalizedOffer.items ?? [],
      currency,
      {
        fallbackTitle: "Mjesečne naknade",
        offerType: isPurchaseOrder ? "" : normalizedOffer.serviceLine,
        showTotalAmount: normalizedOffer.showTotalAmount !== false,
        section: "monthly",
        includeHeader: false,
        emptyMessage: "",
      },
    )
    : "";
  const servicePricingTable = servicePricingItems.length > 0
    ? buildCommercialItemsTablePlaceholderPreview(
      normalizedOffer.items ?? [],
      currency,
      {
        fallbackTitle: "Cjenik usluga",
        offerType: isPurchaseOrder ? "" : normalizedOffer.serviceLine,
        showTotalAmount: normalizedOffer.showTotalAmount !== false,
        section: "services",
        includeHeader: false,
        emptyMessage: "",
      },
    )
    : "";
  const preparedBy = String(normalizedOffer.preparedByLabel || normalizedOffer.preparedBy || normalizedOffer.createdByLabel || "").trim();

  const sharedPayload = {
    VALID_UNTIL: normalizedOffer.validUntil ? formatDate(normalizedOffer.validUntil) : "",
    COMPANY_NAME: normalizedOffer.companyName || "",
    COMPANY_OIB: normalizedOffer.companyOib || "",
    COMPANY_HEADQUARTERS: normalizedOffer.headquarters || "",
    LOCATION_SUMMARY: normalizedOffer.locationName || "Bez lokacije",
    LOCATION_LIST: (normalizedOffer.selectedLocationNames ?? []).join("\n") || "Bez lokacije",
    CONTACT_NAME: normalizedOffer.contactName || "",
    CONTACT_PHONE: normalizedOffer.contactPhone || "",
    CONTACT_EMAIL: normalizedOffer.contactEmail || "",
    OFFER_PREPARED_BY: preparedBy,
    PREPARED_BY: preparedBy,
    CREATED_BY: preparedBy,
    SERVICE_LINE: normalizedOffer.serviceLine || "",
    OFFER_TYPE: normalizedOffer.serviceLine || "",
    OFFER_TEXT_1: normalizedOffer.textBlock1 || "",
    OFFER_TEXT_2: normalizedOffer.textBlock2 || "",
    ITEMS_TABLE: itemsTable,
    MONTHLY_FEES_TABLE: monthlyFeesTable,
    SERVICE_PRICING_TABLE: servicePricingTable,
    ITEMS_TABLE_TEXT: itemsTableText,
    ITEMS_SUMMARY: itemsSummary,
    NOTE: normalizedOffer.note || "",
    SUBTOTAL: formatCurrencyAmount(normalizedOffer.subtotal || 0, currency),
    DISCOUNT_RATE: Number(normalizedOffer.discountRate || 0) > 0 ? `${normalizedOffer.discountRate}%` : "",
    DISCOUNT_TOTAL: formatCurrencyAmount(normalizedOffer.discountTotal || 0, currency),
    TAX_RATE: `${normalizedOffer.taxRate || 0}%`,
    TAX_TOTAL: formatCurrencyAmount(normalizedOffer.taxTotal || 0, currency),
    TOTAL: formatCurrencyAmount(normalizedOffer.total || 0, currency),
  };

  if (isPurchaseOrder) {
    return {
      PURCHASE_ORDER_NUMBER: normalizedOffer.id
        ? (normalizedOffer.purchaseOrderNumber || "Dodijeljen nakon spremanja")
        : "Dodijeljen nakon spremanja",
      PURCHASE_ORDER_TITLE: normalizedOffer.title || "",
      PURCHASE_ORDER_STATUS: getOptionLabel(PURCHASE_ORDER_STATUS_OPTIONS, normalizedOffer.status || "draft"),
      PURCHASE_ORDER_DATE: normalizedOffer.purchaseOrderDate ? formatDate(normalizedOffer.purchaseOrderDate) : "",
      ORDER_DIRECTION: getCommercialDocumentDirectionLabel(normalizedOffer.orderDirection),
      EXTERNAL_DOCUMENT_NUMBER: normalizedOffer.externalDocumentNumber || "",
      ...sharedPayload,
    };
  }

  return {
    OFFER_NUMBER: normalizedOffer.id ? (normalizedOffer.offerNumber || "Dodijeljen nakon spremanja") : "Dodijeljen nakon spremanja",
    OFFER_TITLE: normalizedOffer.title || "",
    OFFER_STATUS: getOptionLabel(OFFER_STATUS_OPTIONS, normalizedOffer.status || "draft"),
    OFFER_DATE: normalizedOffer.offerDate ? formatDate(normalizedOffer.offerDate) : "",
    ...sharedPayload,
  };
}

function buildOfferTemplatePlaceholderWordMarkup(offer = buildOfferDraftPreviewData()) {
  const config = getActiveCommercialDocumentConfig();
  const payload = buildOfferTemplatePlaceholderPayload(offer);
  const rows = getActiveCommercialTemplateDefinitions().map((entry) => `
    <tr>
      <td>{{${escapeHtml(entry.key)}}}</td>
      <td>${escapeHtml(entry.label)}</td>
      <td>${escapeHtml(entry.description)}</td>
      <td>${escapeHtml(formatCommercialTemplatePlaceholderPreviewValue(payload[entry.key]))}</td>
    </tr>
  `).join("");

  return `
    <div class="cover">
      <h1>${escapeHtml(config.templatePlaceholderDocTitle)}</h1>
      <p>${escapeHtml(config.templateCopy)} Vrijednosti desno su primjer iz trenutne forme.</p>
      <table class="placeholder-table">
        <thead>
          <tr>
            <th>Placeholder</th>
            <th>Polje</th>
            <th>Opis</th>
            <th>Primjer</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
  `;
}

function parseTemplateLooseNumber(value, fallback = 0) {
  const raw = String(value ?? "").trim().replace(/\s+/g, "").replace(",", ".");
  const parsed = Number.parseFloat(raw);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function normalizeDocumentTemplateSystemDescriptionLineCount(value = 1) {
  return Math.max(1, Math.min(8, Math.round(parseTemplateLooseNumber(value, 1))));
}

function createEmptyDocumentTemplateSystemDescriptionRowDraft(initial = {}, index = 0) {
  return {
    id: initial.id || crypto.randomUUID(),
    subtitle: String(initial.subtitle ?? initial.label ?? "").trim(),
    description: String(initial.description ?? initial.value ?? "").replace(/\r\n/g, "\n").trim(),
    lineCount: normalizeDocumentTemplateSystemDescriptionLineCount(initial.lineCount ?? initial.rows),
    placeholder: String(initial.placeholder ?? "").trim(),
  };
}

function createDefaultDocumentTemplateSystemDescriptionRows() {
  return [
    { id: "system-description-default-1", subtitle: "Proizvođač", description: "", lineCount: 1, placeholder: "npr. COOPER" },
    { id: "system-description-default-2", subtitle: "Tip", description: "", lineCount: 1, placeholder: "npr. FULL CXM/CO/GP/R/BB" },
    { id: "system-description-default-3", subtitle: "Teh. podaci", description: "", lineCount: 1, placeholder: "npr. 1 kom" },
    { id: "system-description-default-4", subtitle: "", description: "", lineCount: 2, placeholder: "Kratki opis sustava, položaja i bitnih napomena..." },
  ].map((row, index) => createEmptyDocumentTemplateSystemDescriptionRowDraft(row, index));
}

function normalizeDocumentTemplateSystemDescriptionRows(rows = [], { ensureOne = true, fallbackRows = [] } = {}) {
  const sourceRows = Array.isArray(rows) && rows.length > 0
    ? rows
    : (Array.isArray(fallbackRows) && fallbackRows.length > 0 ? fallbackRows : []);
  const normalizedRows = sourceRows
    .slice(0, 16)
    .map((row, index) => createEmptyDocumentTemplateSystemDescriptionRowDraft(row, index));

  if (normalizedRows.length > 0) {
    return normalizedRows;
  }

  return ensureOne
    ? [createEmptyDocumentTemplateSystemDescriptionRowDraft({}, 0)]
    : [];
}

function createDocumentTemplateSystemDescriptionBlockDraft(initial = {}, field = {}, index = 0) {
  const defaultTitle = String(field?.label || field?.wordLabel || "Opis sustava").trim() || "Opis sustava";
  const fallbackRows = normalizeDocumentTemplateSystemDescriptionRows(
    field?.systemRows,
    {
      ensureOne: true,
      fallbackRows: createDefaultDocumentTemplateSystemDescriptionRows(),
    },
  );

  return {
    id: initial.id || crypto.randomUUID(),
    title: String(initial.title ?? initial.label ?? defaultTitle).trim() || defaultTitle,
    sectionSubtitle: String(initial.sectionSubtitle ?? initial.subtitle ?? field?.sectionSubtitle ?? "").trim(),
    rows: normalizeDocumentTemplateSystemDescriptionRows(
      initial.rows,
      {
        ensureOne: true,
        fallbackRows,
      },
    ),
  };
}

function normalizeDocumentTemplateSystemDescriptionBlocks(value = null, field = {}, { ensureOne = true } = {}) {
  const legacyRows = Array.isArray(value?.rows) ? value.rows : [];
  const sourceBlocks = Array.isArray(value?.blocks)
    ? value.blocks
    : (legacyRows.length > 0 || value?.title || value?.sectionSubtitle
      ? [{
        id: value?.id,
        title: value?.title,
        sectionSubtitle: value?.sectionSubtitle,
        rows: legacyRows,
      }]
      : []);

  const normalizedBlocks = sourceBlocks
    .slice(0, 24)
    .map((block, index) => createDocumentTemplateSystemDescriptionBlockDraft(block, field, index));

  if (normalizedBlocks.length > 0) {
    return normalizedBlocks;
  }

  return ensureOne
    ? [createDocumentTemplateSystemDescriptionBlockDraft({}, field, 0)]
    : [];
}

function isDocumentTemplateSystemDescriptionValue(value = null) {
  return Boolean(
    value
    && typeof value === "object"
    && !Array.isArray(value)
    && (Array.isArray(value.rows) || Array.isArray(value.blocks)),
  );
}

function getDocumentTemplateSystemDescriptionValueByKeys(source = {}, keys = []) {
  if (!source || typeof source !== "object" || Array.isArray(source)) {
    return "";
  }

  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(source, key) && hasMeaningfulDocumentRecordValue(source[key])) {
      return source[key];
    }
  }

  const sourceEntries = Object.entries(source);
  for (const key of keys) {
    const normalizedKey = normalizeLooseName(key);
    const matchedEntry = sourceEntries.find(([entryKey]) => normalizeLooseName(entryKey) === normalizedKey);
    if (matchedEntry && hasMeaningfulDocumentRecordValue(matchedEntry[1])) {
      return matchedEntry[1];
    }
  }

  return "";
}

function getDocumentTemplateSystemDescriptionRowValueKeys(row = {}) {
  const subtitle = String(row?.subtitle || "").trim();
  const looseSubtitle = normalizeLooseName(subtitle);
  const keys = [
    subtitle,
    looseSubtitle,
    subtitle.replace(/\s+/g, ""),
  ].filter(Boolean);

  if (looseSubtitle.includes("proizvodac") || looseSubtitle.includes("manufacturer")) {
    keys.push("proizvodac", "proizvođač", "manufacturer", "producer", "make");
  }
  if (looseSubtitle === "tip" || looseSubtitle.includes("model")) {
    keys.push("tip", "type", "model", "tipModel", "tip_model");
  }
  if (looseSubtitle.includes("teh") || looseSubtitle.includes("podat")) {
    keys.push("tehPodaci", "teh_podaci", "tehnickiPodaci", "tehnički podaci", "technicalData", "technical_data");
  }
  if (!looseSubtitle || looseSubtitle.includes("opis")) {
    keys.push("opis", "description", "systemDescription", "system_description", "napomena", "note");
  }

  return Array.from(new Set(keys.map((key) => String(key || "").trim()).filter(Boolean)));
}

function normalizeDocumentTemplateSystemDescriptionRowsFromAiValue(field = {}, value = null) {
  if (!value || typeof value !== "object") {
    return null;
  }

  if (Array.isArray(value)) {
    const rowObjects = value
      .filter((entry) => entry && typeof entry === "object" && !Array.isArray(entry))
      .map((entry, index) => createEmptyDocumentTemplateSystemDescriptionRowDraft({
        subtitle: entry.subtitle ?? entry.label ?? entry.title ?? "",
        description: entry.description ?? entry.value ?? entry.text ?? entry.content ?? "",
        lineCount: entry.lineCount ?? entry.line_count ?? 1,
        placeholder: entry.placeholder ?? "",
      }, index))
      .filter((row) => String(row.subtitle || row.description || "").trim());
    if (rowObjects.length > 0) {
      return rowObjects;
    }

    const textRows = value
      .map((entry) => String(entry ?? "").trim())
      .filter(Boolean);
    return textRows.length > 0
      ? [createEmptyDocumentTemplateSystemDescriptionRowDraft({ description: textRows.join("\n"), lineCount: 2 }, 0)]
      : null;
  }

  const explicitRows = Array.isArray(value.rows)
    ? value.rows
    : Array.isArray(value.items)
      ? value.items
      : null;
  if (explicitRows) {
    return normalizeDocumentTemplateSystemDescriptionRowsFromAiValue(field, explicitRows);
  }

  const templateRows = normalizeDocumentTemplateSystemDescriptionRows(
    field?.systemRows,
    {
      ensureOne: true,
      fallbackRows: createDefaultDocumentTemplateSystemDescriptionRows(),
    },
  );
  let hasMappedValue = false;
  const rows = templateRows.map((row, index) => {
    const rawValue = getDocumentTemplateSystemDescriptionValueByKeys(value, getDocumentTemplateSystemDescriptionRowValueKeys(row));
    const description = Array.isArray(rawValue)
      ? rawValue.map((entry) => String(entry ?? "").trim()).filter(Boolean).join("\n")
      : rawValue && typeof rawValue === "object"
        ? String(rawValue.value ?? rawValue.text ?? rawValue.description ?? rawValue.content ?? "").trim()
        : String(rawValue ?? "").trim();
    if (description) {
      hasMappedValue = true;
    }
    return createEmptyDocumentTemplateSystemDescriptionRowDraft({
      ...row,
      description,
    }, index);
  });

  return hasMappedValue ? rows : null;
}

function normalizeDocumentTemplateSystemDescriptionRuntimeValue(field = {}, value = null) {
  if (!isDocumentTemplateSystemDescriptionValue(value) && value && typeof value === "object") {
    const aiRows = normalizeDocumentTemplateSystemDescriptionRowsFromAiValue(field, value);
    if (aiRows?.length) {
      return {
        blocks: [
          createDocumentTemplateSystemDescriptionBlockDraft({
            title: value.title ?? value.label ?? field?.label ?? field?.wordLabel ?? "Opis sustava",
            sectionSubtitle: value.sectionSubtitle ?? value.section_subtitle ?? value.subtitle ?? "",
            rows: aiRows,
          }, field, 0),
        ],
      };
    }
  }

  if (!isDocumentTemplateSystemDescriptionValue(value) && hasMeaningfulDocumentRecordValue(value)) {
    const textValue = Array.isArray(value)
      ? value.map((entry) => String(entry ?? "").trim()).filter(Boolean).join("\n")
      : String(value ?? "").trim();
    const nextValue = normalizeDocumentTemplateSystemDescriptionRuntimeValue(field);
    const firstBlock = nextValue.blocks[0] ?? createDocumentTemplateSystemDescriptionBlockDraft({}, field, 0);
    const firstRow = firstBlock.rows[0] ?? createEmptyDocumentTemplateSystemDescriptionRowDraft({}, 0);
    return {
      blocks: [
        {
          ...firstBlock,
          rows: [
            {
              ...firstRow,
              description: textValue,
            },
            ...(Array.isArray(firstBlock.rows) ? firstBlock.rows.slice(1) : []),
          ],
        },
        ...(Array.isArray(nextValue.blocks) ? nextValue.blocks.slice(1) : []),
      ],
    };
  }

  const source = isDocumentTemplateSystemDescriptionValue(value) ? value : {};
  return {
    blocks: normalizeDocumentTemplateSystemDescriptionBlocks(source, field, { ensureOne: true }),
  };
}

function createDocumentTemplateSystemDescriptionBlankValue(field = {}) {
  const value = normalizeDocumentTemplateSystemDescriptionRuntimeValue(field);
  return {
    ...value,
    blocks: value.blocks.map((block, blockIndex) => ({
      ...block,
      id: block.id || `system-description-block-${blockIndex + 1}`,
      rows: (Array.isArray(block.rows) ? block.rows : []).map((row) => ({
        ...row,
        description: "",
      })),
    })),
  };
}

function buildDocumentTemplateSystemDescriptionSummaryLines(value = null) {
  const model = isDocumentTemplateSystemDescriptionValue(value)
    ? normalizeDocumentTemplateSystemDescriptionRuntimeValue({}, value)
    : null;

  if (!model) {
    return [];
  }

  const lines = [];
  model.blocks.forEach((block) => {
    const title = String(block.title || "").trim();
    const subtitle = String(block.sectionSubtitle || "").trim();
    if (title) {
      lines.push(title);
    }
    if (subtitle) {
      lines.push(subtitle);
    }
    (Array.isArray(block.rows) ? block.rows : []).forEach((row) => {
      const rowSubtitle = String(row.subtitle || "").trim();
      const description = String(row.description || "").trim();
      if (!rowSubtitle && !description) {
        return;
      }
      lines.push(rowSubtitle ? `${rowSubtitle}: ${description}`.trim() : description);
    });
  });

  return lines.filter(Boolean);
}

function buildDocumentTemplateSystemDescriptionSummaryText(value = null) {
  return buildDocumentTemplateSystemDescriptionSummaryLines(value).join("\n");
}

function buildDocumentTemplateSystemDescriptionNarrativeText(value = null, {
  includeBlockTitle = true,
  includeRowHeadings = true,
} = {}) {
  const model = isDocumentTemplateSystemDescriptionValue(value)
    ? normalizeDocumentTemplateSystemDescriptionRuntimeValue({}, value)
    : null;

  if (!model) {
    return "";
  }

  const paragraphs = [];
  model.blocks.forEach((block) => {
    const title = String(block.title || "").trim();
    const subtitle = String(block.sectionSubtitle || "").trim();
    if (includeBlockTitle && title) {
      paragraphs.push(title);
    }
    if (subtitle) {
      paragraphs.push(subtitle);
    }
    (Array.isArray(block.rows) ? block.rows : []).forEach((row) => {
      const rowSubtitle = String(row?.subtitle || "").trim();
      const description = String(row?.description || "").trim();
      if (!rowSubtitle && !description) {
        return;
      }
      if (includeRowHeadings && rowSubtitle && description) {
        paragraphs.push(`${rowSubtitle}\n${description}`);
        return;
      }
      paragraphs.push(description || rowSubtitle);
    });
  });

  return paragraphs.filter(Boolean).join("\n\n");
}

function hasDocumentTemplateSystemDescriptionContent(value = null) {
  if (!isDocumentTemplateSystemDescriptionValue(value)) {
    return false;
  }

  const model = normalizeDocumentTemplateSystemDescriptionRuntimeValue({}, value);
  return model.blocks.some((block) => (
    String(block.sectionSubtitle || "").trim()
    || (Array.isArray(block.rows) ? block.rows : []).some((row) => (
      String(row?.description || "").trim()
    ))
  ));
}

