function getDocumentTemplateFieldTypeLabel(value) {
  return getOptionLabel(DOCUMENT_TEMPLATE_FIELD_TYPE_OPTIONS, value || "text");
}

function isDocumentTemplateSpecialFieldType(value) {
  return DOCUMENT_TEMPLATE_SPECIAL_FIELD_TYPES.has(String(value || "").trim().toLowerCase());
}

function isDocumentTemplatePersonSignatureFieldType(value) {
  return DOCUMENT_TEMPLATE_PERSON_SIGNATURE_FIELD_TYPES.has(String(value || "").trim().toLowerCase());
}

function isDocumentTemplateRequiredToggleFieldType(value) {
  return DOCUMENT_TEMPLATE_REQUIRED_TOGGLE_FIELD_TYPES.has(String(value || "").trim().toLowerCase());
}

function getDocumentTemplateRequiredToggleLabel(type = "text") {
  const normalizedType = String(type || "text").trim().toLowerCase();
  if (normalizedType === "legal_list" || normalizedType === "equipment_list") {
    return "Potrebno odabrati barem jedan";
  }
  return "Obavezno polje";
}

function normalizeDocumentTemplateTextListStyleLocal(value = "") {
  const normalizedValue = String(value || "").trim().toLowerCase();
  return DOCUMENT_TEMPLATE_TEXT_LIST_STYLE_OPTIONS.some((option) => option.value === normalizedValue)
    ? normalizedValue
    : "none";
}

function normalizeDocumentTemplateHtmlStyleDraft(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  const align = String(source.align || "").trim().toLowerCase();
  const tone = String(source.tone || "").trim().toLowerCase();
  const textSize = String(source.textSize || "").trim().toLowerCase();

  return {
    align: DOCUMENT_TEMPLATE_HTML_STYLE_ALIGN_OPTIONS.some((option) => option.value === align) ? align : "left",
    tone: DOCUMENT_TEMPLATE_HTML_STYLE_TONE_OPTIONS.some((option) => option.value === tone) ? tone : "default",
    textSize: DOCUMENT_TEMPLATE_HTML_STYLE_TEXT_SIZE_OPTIONS.some((option) => option.value === textSize) ? textSize : "normal",
  };
}

function isDocumentTemplateTextListStyleField(type = "text") {
  const normalizedType = String(type || "text").trim().toLowerCase();
  return normalizedType === "text" || normalizedType === "longtext";
}

function normalizeDocumentTemplateSignatureMetaFieldsLocal(values = undefined) {
  if (!Array.isArray(values)) {
    return [...DOCUMENT_TEMPLATE_DEFAULT_SIGNATURE_META_FIELDS];
  }
  const allowedValues = new Set(DOCUMENT_TEMPLATE_DEFAULT_SIGNATURE_META_FIELDS);
  return Array.from(
    new Set(
      values
        .map((value) => {
          const raw = String(value || "").trim();
          if (allowedValues.has(raw)) {
            return raw;
          }
          return DOCUMENT_TEMPLATE_SIGNATURE_META_FIELD_ALIASES.get(raw.toLowerCase()) || "";
        })
        .filter(Boolean),
    ),
  );
}

function isDocumentTemplateFieldWidthEditable(type = "text") {
  const normalizedType = String(type || "text").trim().toLowerCase();
  return !DOCUMENT_TEMPLATE_RUNTIME_FORCE_FULL_WIDTH_TYPES.has(normalizedType);
}

function getDocumentTemplateRuntimeFieldLayoutWidth(field = {}) {
  const type = String(field?.type || "text").trim().toLowerCase();
  if (DOCUMENT_TEMPLATE_RUNTIME_FORCE_FULL_WIDTH_TYPES.has(type)) {
    return "full";
  }
  return normalizeDocumentTemplateFieldLayoutWidth(field?.layoutWidth, type);
}

function getDocumentTemplateRuntimeFieldLayoutSpan(field = {}) {
  const width = getDocumentTemplateRuntimeFieldLayoutWidth(field);
  return DOCUMENT_TEMPLATE_FIELD_WIDTH_SPANS[width] || DOCUMENT_TEMPLATE_FIELD_WIDTH_SPANS[3];
}

function isDocumentTemplateMediaFieldType(value) {
  return DOCUMENT_TEMPLATE_MEDIA_FIELD_TYPES.has(String(value || "").trim().toLowerCase());
}

function getDocumentTemplateMediaFieldKindLabel(type = "image_upload") {
  return String(type || "").trim().toLowerCase() === "sketch_upload"
    ? "Dokumenti"
    : "Slika";
}

function getDocumentTemplateMediaFieldAccept(type = "image_upload") {
  return String(type || "").trim().toLowerCase() === "sketch_upload"
    ? "image/*,.pdf,.doc,.docx,.xls,.xlsx,.csv,.txt"
    : "image/*";
}

function isDocumentTemplateMediaFieldMultiple(type = "image_upload") {
  return String(type || "").trim().toLowerCase() === "sketch_upload";
}

function getDocumentTemplateMediaFieldUploadLabel(type = "image_upload") {
  return isDocumentTemplateMediaFieldMultiple(type) ? "dokumente" : "sliku";
}

function getDocumentTemplateMediaFieldAllowedLabel(type = "image_upload") {
  return isDocumentTemplateMediaFieldMultiple(type)
    ? "slike, PDF, Word, Excel, CSV ili tekstualne dokumente"
    : "podržane slike";
}

function isDocumentTemplateMediaFileAllowed(type = "image_upload", file = null) {
  if (!(file instanceof File)) {
    return false;
  }

  const safeType = String(type || "").trim().toLowerCase();
  if (safeType === "sketch_upload") {
    const fileType = String(file.type || "").trim().toLowerCase();
    const fileName = String(file.name || "").trim();
    return String(file.type || "").startsWith("image/")
      || /^(application\/pdf|text\/plain|text\/csv)$/i.test(fileType)
      || /spreadsheet|wordprocessingml|msword|excel/i.test(fileType)
      || /\.(pdf|docx?|xlsx?|csv|txt)$/i.test(fileName);
  }

  return String(file.type || "").startsWith("image/");
}

function getDocumentTemplateFieldSourceLabel(value) {
  const normalizedValue = String(value || "").trim().toUpperCase() || "CUSTOM_VALUE";
  const parsedSource = parseDocumentTemplateServiceValiditySource(normalizedValue);
  if (parsedSource) {
    const service = getServiceCatalogItemByValidityKey(parsedSource.key);
    const serviceLabel = service ? getWorkOrderServiceValidityLabel(service) : "odabrana usluga";
    return parsedSource.kind === "SERVICE_VALID_UNTIL"
      ? `Dokument Vrijedi do - ${serviceLabel}`
      : `Dokument ${serviceLabel} (mjeseci)`;
  }
  return getOptionLabel(getDocumentTemplateSourceOptions(normalizedValue), normalizedValue);
}

function getDocumentTemplateDatabaseTableLabel(value) {
  return getOptionLabel(
    Object.entries(DOCUMENT_TEMPLATE_DATABASE_TABLE_DEFINITIONS).map(([entryValue, definition]) => ({
      value: entryValue,
      label: definition.label,
    })),
    String(value || "").trim().toLowerCase(),
  );
}

function getDocumentTemplatePreviousDocumentLabel(value) {
  return getOptionLabel(DOCUMENT_TEMPLATE_PREVIOUS_DOCUMENT_OPTIONS, String(value || "").trim().toUpperCase() || "NONE");
}

function getDocumentTemplateLookupMode(field = {}) {
  if (String(field?.previousDocumentMode || "").trim().toUpperCase() === "SAME_TEMPLATE_LOCATION") {
    return "PREVIOUS_DOCUMENT_LOCATION";
  }
  if (String(field?.lookupValueSource || "").trim().toUpperCase() === "CUSTOM_VALUE") {
    return "CUSTOM_VALUE";
  }
  return "WORK_ORDER_NUMBER";
}

function setDocumentTemplateLookupMode(field = {}, mode = "WORK_ORDER_NUMBER") {
  const safeMode = String(mode || "WORK_ORDER_NUMBER").trim().toUpperCase();
  if (safeMode === "PREVIOUS_DOCUMENT_LOCATION") {
    field.previousDocumentMode = "SAME_TEMPLATE_LOCATION";
    field.lookupValueSource = "WORK_ORDER_NUMBER";
    return field;
  }
  if (safeMode === "CUSTOM_VALUE") {
    field.previousDocumentMode = "NONE";
    field.lookupValueSource = "CUSTOM_VALUE";
    return field;
  }
  field.previousDocumentMode = "NONE";
  field.lookupValueSource = "WORK_ORDER_NUMBER";
  return field;
}

function getDocumentTemplateDatabaseTableDefinition(table = "") {
  const normalizedTable = String(table || "").trim().toLowerCase();
  return DOCUMENT_TEMPLATE_DATABASE_TABLE_DEFINITIONS[normalizedTable] ?? null;
}

function getDocumentTemplateDatabaseTableOptions() {
  return Object.entries(DOCUMENT_TEMPLATE_DATABASE_TABLE_DEFINITIONS).map(([value, definition]) => ({
    value,
    label: `${definition.label} - ${definition.copy}`,
  }));
}

function getDocumentTemplateDatabaseColumnOptions(table = "") {
  const definition = getDocumentTemplateDatabaseTableDefinition(table);
  if (!definition) {
    return [];
  }
  return definition.columns.map((column) => ({
    value: column.value,
    label: `${column.value} - ${column.label}`,
  }));
}

function getDocumentTemplateDatabaseColumnDefinition(table = "", column = "") {
  const definition = getDocumentTemplateDatabaseTableDefinition(table);
  if (!definition) {
    return null;
  }
  const normalizedColumn = String(column || "").trim().toLowerCase();
  return definition.columns.find((entry) => String(entry.value || "").trim().toLowerCase() === normalizedColumn) ?? null;
}

function getDocumentTemplateDefaultDatabaseLookupConfig(table = "radni_nalozi") {
  const options = getDocumentTemplateDatabaseColumnOptions(table);
  return {
    sourceTable: table,
    lookupColumn: options[1]?.value || options[0]?.value || "",
    valueColumn: options[2]?.value || options[1]?.value || options[0]?.value || "",
    lookupValueSource: "WORK_ORDER_NUMBER",
    lookupValue: "",
    previousDocumentMode: "NONE",
  };
}

function ensureDocumentTemplateDatabaseLookupDraft(field = {}) {
  if (String(field?.source || "").trim().toUpperCase() !== "DATABASE_LOOKUP") {
    if (!field.previousDocumentMode) {
      field.previousDocumentMode = "NONE";
    }
    return field;
  }

  const defaults = getDocumentTemplateDefaultDatabaseLookupConfig(field.sourceTable || "radni_nalozi");
  const definition = getDocumentTemplateDatabaseTableDefinition(field.sourceTable || defaults.sourceTable)
    ?? getDocumentTemplateDatabaseTableDefinition(defaults.sourceTable);
  const columns = definition?.columns ?? [];
  const hasLookupColumn = columns.some((column) => String(column.value) === String(field.lookupColumn || ""));
  const hasValueColumn = columns.some((column) => String(column.value) === String(field.valueColumn || ""));

  field.sourceTable = definition ? Object.entries(DOCUMENT_TEMPLATE_DATABASE_TABLE_DEFINITIONS)
    .find(([, entry]) => entry === definition)?.[0] || defaults.sourceTable : defaults.sourceTable;
  field.lookupColumn = hasLookupColumn ? field.lookupColumn : defaults.lookupColumn;
  field.valueColumn = hasValueColumn ? field.valueColumn : defaults.valueColumn;
  field.lookupValueSource = String(field.lookupValueSource || defaults.lookupValueSource).trim().toUpperCase();
  field.lookupValue = String(field.lookupValue || "").trim();
  field.previousDocumentMode = String(field.previousDocumentMode || "NONE").trim().toUpperCase();
  return field;
}

function normalizeDocumentTemplateLookupComparable(value) {
  return String(value ?? "").trim().toLowerCase();
}

function formatDocumentTemplateLookupResolvedValue(value) {
  if (Array.isArray(value)) {
    return value.map((entry) => formatDocumentTemplateLookupResolvedValue(entry)).filter(Boolean).join(", ");
  }
  if (value === true) {
    return "Da";
  }
  if (value === false) {
    return "Ne";
  }
  if (value && typeof value === "object") {
    if (isDocumentTemplateSystemDescriptionValue(value)) {
      if (!hasDocumentTemplateSystemDescriptionContent(value)) {
        return "";
      }
      return buildDocumentTemplateSystemDescriptionSummaryLines(value).slice(0, 3).join(" | ");
    }
    const mediaValue = normalizeDocumentTemplateMediaFieldValue(value);
    if (mediaValue) {
      return mediaValue.fileName || getDocumentTemplateMediaFieldKindLabel(mediaValue.documentCategory || "");
    }
  }
  const text = String(value ?? "").trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    return formatCompactDate(text);
  }
  return text;
}

function hasMeaningfulDocumentRecordValue(value) {
  if (value === false || value === 0) {
    return true;
  }

  if (Array.isArray(value)) {
    return value.length > 0;
  }

  if (value && typeof value === "object") {
    if (isDocumentTemplateSystemDescriptionValue(value)) {
      return hasDocumentTemplateSystemDescriptionContent(value);
    }
    return Object.keys(value).length > 0;
  }

  return String(value ?? "").trim() !== "";
}

function isDocumentTemplatePreviousDocumentLookupField(field = {}) {
  return String(field?.source || "").trim().toUpperCase() === "DATABASE_LOOKUP"
    && getDocumentTemplateLookupMode(field) === "PREVIOUS_DOCUMENT_LOCATION";
}

function getDocumentTemplateRuntimeTemplateId(template = buildDocumentTemplateDraft()) {
  return String(template?.id || documentTemplateIdInput?.value || state.activeDocumentTemplateId || "").trim();
}

function getDocumentTemplatePreviousRecordOptionsCacheKey(templateId = "", workOrder = {}) {
  const normalizedTemplateId = String(templateId || "").trim();
  const companyId = String(workOrder?.companyId || "").trim();
  const locationId = String(workOrder?.locationId || "").trim();
  const objectId = String(workOrder?.objectId || getDocumentTemplateRuntimeSelectedObjectId(workOrder) || "").trim();

  if (!normalizedTemplateId || !companyId || !locationId) {
    return "";
  }

  return `${normalizedTemplateId}::${companyId}::${locationId}::${objectId || "bez-objekta"}`;
}

function getDocumentTemplatePreviousRecordOptionsCacheEntry(templateId = "", workOrder = {}) {
  const key = getDocumentTemplatePreviousRecordOptionsCacheKey(templateId, workOrder);
  if (!key) {
    return null;
  }

  return state.documentTemplateRuntime.previousRecordOptions?.[key] ?? null;
}

function getDocumentTemplatePreviousRecordDateValue(record = {}) {
  const anchorDate = String(record.inspectionDate || record.issuedDate || record.createdAt || "").trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(anchorDate)) {
    return anchorDate;
  }
  if (!anchorDate) {
    return "";
  }
  const parsedDate = new Date(anchorDate);
  return Number.isNaN(parsedDate.getTime()) ? "" : parsedDate.toISOString().slice(0, 10);
}

function getDocumentTemplatePreviousRecordWorkOrderNumber(record = {}) {
  const directValue = String(
    record.workOrderNumber
    || record.workOrderNo
    || record.workOrder
    || record.documentNumber
    || record.reportNumber
    || record.number
    || extractDocumentsExplorerWorkOrderNumber(record)
    || "",
  ).trim();
  const normalizedDirectValue = directValue.replace(/^RN\s+/i, "").trim();
  if (normalizedDirectValue) {
    return normalizedDirectValue;
  }

  const linkedWorkOrder = resolveDocumentsExplorerWorkOrder(record);
  return String(linkedWorkOrder?.workOrderNumber || "").replace(/^RN\s+/i, "").trim();
}

function buildDocumentTemplatePreviousRecordCandidateLabel(record = {}, index = 0) {
  const dateValue = getDocumentTemplatePreviousRecordDateValue(record);
  const dateLabel = dateValue ? formatCompactDate(dateValue) : "bez datuma";
  const workOrderNumber = getDocumentTemplatePreviousRecordWorkOrderNumber(record);
  return [
    dateLabel,
    workOrderNumber ? `RN ${workOrderNumber}` : "",
  ].filter(Boolean).join(" · ") || `Prethodno ispitivanje ${index + 1}`;
}

function buildDocumentTemplatePreviousRecordSelectLabel(candidate = {}) {
  if (candidate.id === "template") {
    return "Template vrijednosti";
  }

  return [
    "Prethodno ispitivanje",
    candidate.label,
  ].filter(Boolean).join(" · ");
}

async function ensureDocumentTemplatePreviousRecordOptions(template = buildDocumentTemplateDraft(), workOrder = {}) {
  const templateId = getDocumentTemplateRuntimeTemplateId(template);
  const cacheKey = getDocumentTemplatePreviousRecordOptionsCacheKey(templateId, workOrder);

  if (!cacheKey) {
    return;
  }

  const current = state.documentTemplateRuntime.previousRecordOptions?.[cacheKey];
  if (current?.status === "loading" || current?.status === "loaded") {
    return;
  }

  state.documentTemplateRuntime.previousRecordOptions = {
    ...(state.documentTemplateRuntime.previousRecordOptions ?? {}),
    [cacheKey]: {
      status: "loading",
      items: [],
      error: "",
    },
  };

  renderDocumentTemplateFieldRows();

  try {
    const objectId = getDocumentTemplateRuntimeSelectedObjectId(workOrder);
    const objectQuery = objectId ? `&objectId=${encodeURIComponent(objectId)}` : "";
    const payload = await apiRequest(
      `/document-records?templateId=${encodeURIComponent(templateId)}&companyId=${encodeURIComponent(String(workOrder.companyId || "").trim())}&locationId=${encodeURIComponent(String(workOrder.locationId || "").trim())}${objectQuery}&limit=12`,
    );
    state.documentTemplateRuntime.previousRecordOptions = {
      ...(state.documentTemplateRuntime.previousRecordOptions ?? {}),
      [cacheKey]: {
        status: "loaded",
        items: Array.isArray(payload?.items) ? payload.items : [],
        error: "",
      },
    };
  } catch (error) {
    state.documentTemplateRuntime.previousRecordOptions = {
      ...(state.documentTemplateRuntime.previousRecordOptions ?? {}),
      [cacheKey]: {
        status: "error",
        items: [],
        error: error.message || "Ne mogu ucitati prethodna ispitivanja.",
      },
    };
  }

  if (isDocumentTemplateRuntimeFillMode()) {
    renderDocumentTemplateRuntimeContext();
    renderDocumentTemplateFieldRows();
    renderDocumentTemplatePreviewContent();
  }
}

function getDocumentTemplatePreviousRecordRuntimeCandidates(workOrder = {}, template = buildDocumentTemplateDraft()) {
  const templateId = getDocumentTemplateRuntimeTemplateId(template);
  const cacheEntry = getDocumentTemplatePreviousRecordOptionsCacheEntry(templateId, workOrder);
  const candidates = [];

  if (Array.isArray(cacheEntry?.items)) {
    cacheEntry.items.forEach((record, index) => {
      candidates.push({
        id: `record:${record.id}`,
        label: buildDocumentTemplatePreviousRecordCandidateLabel(record, index),
        meta: record.createdByLabel || "",
        value: record,
      });
    });
  }

  candidates.push({
    id: "template",
    label: "Template",
    meta: "Vrijednosti iz predloška",
    value: null,
  });

  return {
    status: cacheEntry?.status || "idle",
    error: cacheEntry?.error || "",
    candidates,
  };
}

function restoreDocumentTemplateEditorNode(node, homeParent, homeNextSibling) {
  if (!(node instanceof HTMLElement) || !(homeParent instanceof Node)) {
    return;
  }

  if (node.parentNode === homeParent) {
    return;
  }

  if (homeNextSibling instanceof Node && homeNextSibling.parentNode === homeParent) {
    homeParent.insertBefore(node, homeNextSibling);
    return;
  }

  homeParent.append(node);
}

function syncDocumentTemplateEditorMountTarget(useBodyMount = false) {
  if (!(documentTemplateEditorPanel instanceof HTMLElement) || !(documentTemplateEditorBackdrop instanceof HTMLElement)) {
    return;
  }

  if (useBodyMount) {
    if (documentTemplateEditorBackdrop.parentNode !== document.body) {
      document.body.append(documentTemplateEditorBackdrop);
    }
    if (documentTemplateEditorPanel.parentNode !== document.body) {
      document.body.append(documentTemplateEditorPanel);
    }
    return;
  }

  restoreDocumentTemplateEditorNode(
    documentTemplateEditorBackdrop,
    documentTemplateEditorBackdropHomeParent,
    documentTemplateEditorBackdropHomeNextSibling,
  );
  restoreDocumentTemplateEditorNode(
    documentTemplateEditorPanel,
    documentTemplateEditorPanelHomeParent,
    documentTemplateEditorPanelHomeNextSibling,
  );
}

function getDocumentTemplatePreviousRecordCandidates(field = {}, workOrder = {}, template = buildDocumentTemplateDraft()) {
  const templateId = getDocumentTemplateRuntimeTemplateId(template);
  const cacheEntry = getDocumentTemplatePreviousRecordOptionsCacheEntry(templateId, workOrder);
  const fieldKey = String(field?.key || "").trim();
  const candidates = [];

  if (fieldKey && Array.isArray(cacheEntry?.items)) {
    cacheEntry.items.forEach((record, index) => {
      const nextValue = record?.fieldValues?.[fieldKey];

      if (!hasMeaningfulDocumentRecordValue(nextValue)) {
        return;
      }

      candidates.push({
        id: `record:${record.id}`,
        label: buildDocumentTemplatePreviousRecordCandidateLabel(record, index),
        meta: record.createdByLabel || "",
        value: nextValue,
      });
    });
  }

  candidates.push({
    id: "template",
    label: "Template",
    meta: hasMeaningfulDocumentRecordValue(field?.defaultValue)
      ? "Zadana vrijednost iz predloska"
      : "Ako nema prethodnog ispitivanja, ostaje vrijednost iz templatea",
    value: field?.defaultValue ?? "",
  });

  return {
    status: cacheEntry?.status || "idle",
    error: cacheEntry?.error || "",
    candidates,
  };
}

function getDocumentTemplatePreviousRecordFieldKey(field = {}) {
  return String(field?.key || field?.id || "").trim();
}

function getDocumentTemplatePreviousRecordFieldCandidates(
  field = {},
  workOrder = {},
  template = buildDocumentTemplateDraft(),
  { kind = "value" } = {},
) {
  const templateId = getDocumentTemplateRuntimeTemplateId(template);
  const cacheEntry = getDocumentTemplatePreviousRecordOptionsCacheEntry(templateId, workOrder);
  const fieldKey = getDocumentTemplatePreviousRecordFieldKey(field);
  const normalizedKind = String(kind || "value").trim().toLowerCase() === "sheet" ? "sheet" : "value";
  const candidates = [];

  if (fieldKey && Array.isArray(cacheEntry?.items)) {
    cacheEntry.items.forEach((record, index) => {
      const nextValue = normalizedKind === "sheet"
        ? normalizeWorkOrderMeasurementSheet(record?.fieldSheets?.[fieldKey])
        : record?.fieldValues?.[fieldKey];

      if (!hasMeaningfulDocumentRecordValue(nextValue)) {
        return;
      }

      candidates.push({
        id: `record:${record.id}`,
        label: buildDocumentTemplatePreviousRecordCandidateLabel(record, index),
        meta: normalizedKind === "sheet"
          ? getMeasurementSheetTemplateSummary(nextValue)
          : (record.createdByLabel || formatDocumentTemplateLookupResolvedValue(nextValue)),
        value: nextValue,
      });
    });
  }

  candidates.push({
    id: "template",
    label: "Template",
    meta: normalizedKind === "sheet"
      ? "Početna Excel tablica iz predloška"
      : (hasMeaningfulDocumentRecordValue(field?.defaultValue)
        ? "Zadana vrijednost iz predloška"
        : "Ako nema prethodnog ispitivanja, ostaje vrijednost iz templatea"),
    value: normalizedKind === "sheet"
      ? normalizeWorkOrderMeasurementSheet(field?.sheet ?? field?.measurementSheet) ?? null
      : (field?.defaultValue ?? ""),
  });

  return {
    status: cacheEntry?.status || "idle",
    error: cacheEntry?.error || "",
    candidates,
  };
}

function getDocumentTemplatePreviousRecordFieldCandidateById(
  field = {},
  workOrder = {},
  template = buildDocumentTemplateDraft(),
  candidateId = "",
  options = {},
) {
  const normalizedCandidateId = String(candidateId || "").trim();
  if (!normalizedCandidateId) {
    return null;
  }

  return getDocumentTemplatePreviousRecordFieldCandidates(field, workOrder, template, options)
    .candidates
    .find((candidate) => String(candidate.id || "").trim() === normalizedCandidateId) || null;
}

function applyDocumentTemplateRuntimeRecordCandidate(
  workOrderId,
  candidateId = "",
  template = buildDocumentTemplateDraft(),
  { render = true } = {},
) {
  const normalizedWorkOrderId = String(workOrderId || "").trim();
  const normalizedCandidateId = String(candidateId || "").trim() || "template";
  const workOrder = (state.workOrders ?? []).find((item) => String(item.id) === normalizedWorkOrderId) ?? null;
  if (!workOrder) {
    return;
  }

  (Array.isArray(template?.customFields) ? template.customFields : []).forEach((field) => {
    if (!isDocumentTemplateRuntimePersistedField(field)) {
      return;
    }
    const kind = String(field?.type || "").trim().toLowerCase() === "measurement_table" ? "sheet" : "value";
    if (normalizedCandidateId === "template") {
      applyDocumentTemplateRuntimePersistedFieldCandidate(normalizedWorkOrderId, field, "template", template, {
        kind,
        render: false,
      });
      return;
    }

    const matchingCandidate = getDocumentTemplatePreviousRecordFieldCandidateById(
      field,
      workOrder,
      template,
      normalizedCandidateId,
      { kind },
    );

    applyDocumentTemplateRuntimePersistedFieldCandidate(
      normalizedWorkOrderId,
      field,
      matchingCandidate?.id || "template",
      template,
      { kind, render: false },
    );
  });

  setDocumentTemplateRuntimeRecordSource(normalizedWorkOrderId, normalizedCandidateId, { render: false });

  if (render) {
    syncDocumentTemplateEditorChrome();
    renderDocumentTemplateRuntimeContext();
    renderDocumentTemplateFieldRows();
    renderDocumentTemplatePreviewContent();
  }
}

function getDocumentTemplatePreviousDocumentFallbackValue(field = {}, workOrderId = "", template = buildDocumentTemplateDraft()) {
  const normalizedWorkOrderId = String(workOrderId || state.documentTemplateRuntime.activeWorkOrderId || "").trim();
  const workOrder = (state.workOrders ?? []).find((item) => String(item.id) === normalizedWorkOrderId) ?? null;

  if (!workOrder) {
    return field.defaultValue ?? "";
  }

  const { candidates } = getDocumentTemplatePreviousRecordCandidates(field, workOrder, template);
  if (candidates.length > 0) {
    return candidates[0].value;
  }

  return field.defaultValue ?? "";
}

function getDocumentTemplateDefaultFieldSource(type = "text") {
  return isDocumentTemplateSpecialFieldType(type) ? "" : "CUSTOM_VALUE";
}

function normalizeDocumentTemplateDropdownOptionsLocal(value = []) {
  const source = Array.isArray(value)
    ? value
    : String(value ?? "").split(/[\n,;]/);
  const seen = new Set();

  return source
    .map((entry) => {
      if (entry && typeof entry === "object") {
        return String(entry.label ?? entry.value ?? "").trim();
      }
      return String(entry ?? "").trim();
    })
    .filter(Boolean)
    .filter((entry) => {
      const key = entry.toLowerCase();
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .slice(0, 80);
}

function buildDocumentTemplateDropdownSelectOptions(field = {}, { includePlaceholder = false } = {}) {
  const options = normalizeDocumentTemplateDropdownOptionsLocal(field.dropdownOptions ?? field.options ?? field.choices);
  const selectOptions = options.map((option) => ({
    value: option,
    label: option,
  }));

  if (!includePlaceholder) {
    return selectOptions;
  }

  return [
    { value: "", label: options.length > 0 ? "Odaberi..." : "Nema definiranih izbora" },
    ...selectOptions,
  ];
}

function buildDocumentTemplateToolFieldDraft(tool = "text") {
  const safeTool = String(tool || "text").trim().toLowerCase();
  const baseIndex = documentTemplateFieldDrafts.length;

  if (safeTool === "chapter") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Novi blok",
        wordLabel: "Novi blok",
        type: "chapter",
        defaultValue: "Naziv bloka",
      },
      baseIndex,
    );
  }

  if (safeTool === "page_break") {
    const pageNumber = buildDocumentTemplateSheetGroups().length + 1;
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: `A4 stranica ${pageNumber}`,
        wordLabel: `A4 stranica ${pageNumber}`,
        type: "page_break",
        defaultValue: "",
      },
      baseIndex,
    );
  }

  if (safeTool === "system_description") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Opis sustava",
        wordLabel: "Opis sustava",
        type: "system_description",
        sectionSubtitle: "",
        systemRows: createDefaultDocumentTemplateSystemDescriptionRows(),
        helpText: "Dodaj naslov bloka i retke koje će korisnik kasnije ispunjavati u zapisniku.",
      },
      baseIndex,
    );
  }

  if (safeTool === "measurement_table") {
    const sheet = buildTemplateMeasurementSheetFromLegacyConfig({
      columns: ["Pozicija", "Opis", "Vrijednost", "Granica", "Napomena"],
      rowCount: 12,
    });

    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Excel tablica",
        wordLabel: "Excel tablica",
        type: "measurement_table",
        columns: sheet.columns.map((column) => column.label),
        rowCount: sheet.rows.length,
        sheet,
      },
      baseIndex,
    );
  }

  if (safeTool === "legal_list") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Propisi",
        wordLabel: "Propisi",
        type: "legal_list",
        helpText: "Odaberi koje pravilnike prikazuje ovaj blok i koje označava unaprijed.",
      },
      baseIndex,
    );
  }

  if (safeTool === "equipment_list") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Mjerna oprema",
        wordLabel: "Mjerna oprema",
        type: "equipment_list",
        helpText: "Povezana mjerna i ispitna oprema iz Measurement Equipment modula.",
      },
      baseIndex,
    );
  }

  if (safeTool === "sketch_upload") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Dodaj dokumente",
        wordLabel: "Dokumenti",
        type: "sketch_upload",
        helpText: "Kod izrade zapisnika korisnik dodaje dokumente, skice ili priloge klikom ili drag and dropom.",
      },
      baseIndex,
    );
  }

  if (safeTool === "image_upload") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Slika",
        wordLabel: "Slika",
        type: "image_upload",
        helpText: "Kod izrade zapisnika korisnik dodaje sliku klikom ili drag and dropom.",
      },
      baseIndex,
    );
  }

  if (safeTool === "inspector_signature") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Potpis ispitivača",
        wordLabel: "Potpis ispitivača panik rasvjete",
        type: "inspector_signature",
        signatureArea: "elektro",
        helpText: "Potpis ispitivača panik rasvjete iz People modula.",
      },
      baseIndex,
    );
  }

  if (safeTool === "authorization_holder_signature") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Potpis nositelja",
        wordLabel: "Potpis nositelja panik rasvjete",
        type: "authorization_holder_signature",
        signatureArea: "elektro",
        helpText: "Potpis nositelja ovlaštenja za panik rasvjetu iz People modula.",
      },
      baseIndex,
    );
  }

  if (safeTool === "signature") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Osobe koje sudjeluju u ispitivanju",
        wordLabel: "Osobe koje sudjeluju u ispitivanju",
        type: "qualified_inspectors",
        signatureArea: "elektro",
        helpText: "Povlači odabrane osobe za traženu uslugu i odmah rezervira njihova mjesta potpisa.",
      },
      baseIndex,
    );
  }

  if (safeTool === "digital_signature") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Potpis",
        wordLabel: "Potpis panik rasvjete",
        type: "digital_signature",
        signatureArea: "elektro",
        signatureRole: "inspect",
        signatureMultiple: true,
        signatureIncludeScan: false,
        helpText: "Jedinstveni potpisni slot. U izradi zapisnika biraš koristi li spremljeni potpis ili digitalni potpis.",
      },
      baseIndex,
    );
  }

  if (safeTool === "qualified_inspector") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Osobe koje sudjeluju u ispitivanju",
        wordLabel: "Osobe koje sudjeluju u ispitivanju",
        type: "qualified_inspectors",
        signatureArea: "elektro",
        helpText: "Povlači odabrane osobe za traženu uslugu i odmah slaže njihove potpise u isti blok.",
      },
      baseIndex,
    );
  }

  if (safeTool === "qualified_authorization_holder") {
    return createEmptyDocumentTemplateFieldDraft(
      {
        label: "Nositelj",
        wordLabel: "Nositelj ovlaštenja panik rasvjete",
        type: "text",
        source: "QUALIFIED_AUTHORIZATION_HOLDER_SUMMARY",
        helpText: "Povlači podatke o odabranom nositelju ovlaštenja iz People modula.",
      },
      baseIndex,
    );
  }

  const presets = {
    text: {
      label: "Tekst polje",
      wordLabel: "Tekst polje",
      type: "text",
    },
    longtext: {
      label: "Dugacak tekst",
      wordLabel: "Dugacak tekst",
      type: "longtext",
    },
    dropdown: {
      label: "Padajuci izbor",
      wordLabel: "Padajuci izbor",
      type: "dropdown",
      dropdownOptions: ["Da", "Ne", "Nije primjenjivo"],
      helpText: "Opcije definiras u postavkama polja, a korisnik u zapisniku bira jednu vrijednost.",
    },
    date: {
      label: "Datum",
      wordLabel: "Datum",
      type: "date",
      source: "TODAY",
    },
    checkbox: {
      label: "Kvacica",
      wordLabel: "Kvacica",
      type: "checkbox",
    },
    toggle: {
      label: "Toggle",
      wordLabel: "Toggle",
      type: "toggle",
    },
    number: {
      label: "Broj",
      wordLabel: "Broj",
      type: "number",
    },
  };

  return createEmptyDocumentTemplateFieldDraft(
    presets[safeTool] ?? presets.text,
    baseIndex,
  );
}

function addDocumentTemplateBuilderBlock(tool = "text", { pageIndex = activeDocumentTemplateSheetIndex, focus = true } = {}) {
  if (isDocumentTemplateRuntimeFillMode()) {
    return;
  }
  const safeTool = String(tool || "text").trim().toLowerCase();

  const fieldDraft = buildDocumentTemplateToolFieldDraft(safeTool);
  insertDocumentTemplateFieldDraft(fieldDraft, { pageIndex });
  if (safeTool === "page_break") {
    activeDocumentTemplateSheetIndex = Math.min(pageIndex + 1, buildDocumentTemplateSheetGroups().length - 1);
    activeDocumentTemplateInspectorFieldId = "";
    documentTemplateInspectorModalOpen = false;
    renderDocumentTemplateFieldRows({ supportImmediate: true });
    requestAnimationFrame(() => {
      documentTemplateCustomFields
        ?.querySelector(`[data-template-sheet-page="${activeDocumentTemplateSheetIndex}"]`)
        ?.scrollIntoView({ block: "nearest", behavior: "smooth" });
    });
    return;
  }
  if (safeTool !== "chapter") {
    const insertedIndex = documentTemplateFieldDrafts.findIndex((field) => String(field.id) === String(fieldDraft.id));
    for (let index = insertedIndex - 1; index >= 0; index -= 1) {
      if (documentTemplateFieldDrafts[index]?.type === "chapter") {
        collapsedDocumentTemplateChapterIds.delete(String(documentTemplateFieldDrafts[index].id || ""));
        break;
      }
    }
  }
  renderDocumentTemplateFieldRows();

  if (safeTool === "measurement_table") {
    requestAnimationFrame(() => {
      ensureTemplateMeasurementSheetForField(fieldDraft.id);
      if (focus) {
        focusDocumentTemplateFieldLabel(fieldDraft.id);
      }
    });
    return;
  }

  if (focus) {
    focusDocumentTemplateFieldLabel(fieldDraft.id);
  }
}

function normalizeDocumentTemplateFieldKeyDraft(value = "", fallback = "FIELD_1") {
  const normalized = String(value ?? "")
    .trim()
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");

  return normalized || fallback;
}

function normalizeDocumentTemplateFieldAiConfig(input = {}, field = {}) {
  const source = input && typeof input === "object" ? input : {};
  const fieldType = String(field?.type || "text").trim().toLowerCase();
  const fallbackType = fieldType === "dropdown"
    ? "enum"
    : fieldType === "measurement_table"
      ? "list"
      : fieldType === "date"
        ? "date"
        : "text";
  const label = String(source?.label ?? field?.label ?? field?.wordLabel ?? "").trim().slice(0, 160);
  const key = String(source?.key ?? field?.key ?? "").trim().slice(0, 120);
  const aiDescription = String(source?.aiDescription ?? source?.ai_description ?? source?.description ?? "").trim().slice(0, 2000);
  const aiLookFor = normalizeAiConfigListLocal(source?.aiLookFor ?? source?.ai_look_for, 160);
  const aiAvoid = String(source?.aiAvoid ?? source?.ai_avoid ?? "").trim().slice(0, 1000);

  return {
    key,
    label,
    description: String(source?.description ?? field?.helpText ?? "").trim().slice(0, 2000),
    type: normalizeAiFieldTypeLocal(source?.type || fallbackType, fallbackType),
    required: Boolean(source?.required),
    placeholder: String(source?.placeholder || "").trim().slice(0, 400),
    helpText: String(source?.helpText ?? source?.help_text ?? field?.helpText ?? "").trim().slice(0, 1000),
    enabled: Boolean(source?.enabled ?? source?.aiEnabled ?? source?.ai_enabled),
    aiDescription,
    aiLookFor,
    aiAvoid,
    allowedValues: normalizeAiConfigListLocal(source?.allowedValues ?? source?.allowed_values, 160),
    commonValues: normalizeAiConfigListLocal(source?.commonValues ?? source?.common_values, 80),
    examples: normalizeAiConfigListLocal(source?.examples, 80),
    format: String(source?.format || "").trim().slice(0, 1200),
    unit: String(source?.unit || "").trim().slice(0, 40),
    defaultValue: String(source?.defaultValue ?? source?.default_value ?? field?.defaultValue ?? "").trim().slice(0, 500),
    fallbackValue: String(source?.fallbackValue ?? source?.fallback_value ?? "").trim().slice(0, 500),
    confidenceRequired: normalizeAiConfidenceLevelLocal(
      source?.confidenceRequired ?? source?.confidence_required,
      "medium",
    ),
    sourceTracking: Boolean(source?.sourceTracking ?? source?.source_tracking ?? true),
    validationRules: String(source?.validationRules ?? source?.validation_rules ?? "").trim().slice(0, 1600),
    displayOrder: normalizeAiDisplayOrderLocal(source?.displayOrder ?? source?.display_order),
    group: String(source?.group || "").trim().slice(0, 120),
  };
}

function hasDocumentTemplateFieldAiConfig(input = {}, field = {}) {
  const config = normalizeDocumentTemplateFieldAiConfig(input, field);
  return Boolean(
    config.enabled
    || config.aiDescription
    || config.aiLookFor.length
    || config.aiAvoid
    || config.allowedValues.length
    || config.commonValues.length
    || config.examples.length
    || config.fallbackValue
    || config.validationRules
    || config.group
  );
}

function getDocumentTemplateFieldAiConfidence(field = {}, runtimeConfidence = "") {
  const normalizedRuntime = normalizeAiConfidenceLevelLocal(runtimeConfidence, "");
  if (normalizedRuntime) {
    return normalizedRuntime;
  }
  const config = normalizeDocumentTemplateFieldAiConfig(field.ai ?? field.aiConfig, field);
  return normalizeAiConfidenceLevelLocal(config.confidenceRequired, "medium");
}

function createDocumentTemplateAiStatusPill(field = {}, options = {}) {
  const config = normalizeDocumentTemplateFieldAiConfig(field.ai ?? field.aiConfig, field);
  const runtimeMeta = normalizeDocumentTemplateRuntimeFieldAiMeta(options.runtimeMeta);
  if (!hasDocumentTemplateFieldAiConfig(config, field) && !runtimeMeta) {
    return null;
  }
  const confidence = getDocumentTemplateFieldAiConfidence(field, runtimeMeta?.confidence || options.confidence);
  const pill = document.createElement("span");
  pill.className = `document-template-ai-pill is-${confidence}`;
  if (runtimeMeta) {
    pill.classList.add("is-filled");
  }
  pill.textContent = "NexAI";
  const titleParts = runtimeMeta
    ? [
      `${AI_CONFIDENCE_LABELS[confidence] || "NexAI"} - NexAI je popunio ovo polje.`,
      runtimeMeta.reason ? `Razlog: ${runtimeMeta.reason}` : "",
      runtimeMeta.sourceFile ? `Izvor: ${runtimeMeta.sourceFile}` : "",
    ]
    : [
      `${AI_CONFIDENCE_LABELS[confidence] || "NexAI postavke"} - ${config.aiDescription || "Polje ima NexAI upute."}`,
    ];
  pill.title = titleParts.filter(Boolean).join(" ");
  pill.setAttribute("aria-label", pill.title);
  return pill;
}

function appendDocumentTemplateRuntimeTitleAiPill(titleNode, field = {}, workOrderId = "") {
  if (!(titleNode instanceof HTMLElement)) {
    return;
  }
  const runtimeAiMeta = workOrderId
    ? getDocumentTemplateRuntimeFieldAiMeta(workOrderId, field?.id)
    : null;
  const pill = createDocumentTemplateAiStatusPill(field, {
    confidence: runtimeAiMeta?.confidence,
    runtimeMeta: runtimeAiMeta,
  });
  if (!pill) {
    return;
  }
  pill.classList.add("is-inline-runtime");
  titleNode.classList.add("document-template-runtime-field-title-ai");
  titleNode.append(pill);
}

function isDocumentTemplateNexAiEnabled(template = {}) {
  return Boolean(
    template?.useAi
    ?? template?.useAI
    ?? template?.useNexAi
    ?? template?.nexAiEnabled
    ?? template?.aiEnabled
    ?? template?.ai_enabled,
  );
}

function appendDocumentTemplateRuntimeNexAiPanel(shell, template = {}, workOrder = {}) {
  if (!(shell instanceof HTMLElement) || !isDocumentTemplateNexAiEnabled(template)) {
    return;
  }
  shell.append(createDocumentTemplateRuntimeAiAssistantPanel(template, workOrder));
}

function getDocumentTemplateRuntimeAiFieldsFromBlock(block = {}) {
  return (Array.isArray(block?.items) ? block.items : [])
    .map((entry) => entry?.field)
    .filter((field) => field && hasDocumentTemplateFieldAiConfig(field.ai ?? field.aiConfig, field));
}

function createDocumentTemplateRuntimeBlockAiPill(block = {}) {
  const aiFields = getDocumentTemplateRuntimeAiFieldsFromBlock(block);
  if (aiFields.length === 0) {
    return null;
  }
  const pill = createDocumentTemplateAiStatusPill(aiFields[0]);
  if (!pill) {
    return null;
  }
  pill.classList.add("is-block-runtime");
  pill.textContent = aiFields.length > 1 ? `NexAI ${aiFields.length}` : "NexAI";
  pill.title = aiFields.length > 1
    ? `${aiFields.length} polja u ovom bloku imaju NexAI postavke.`
    : pill.title;
  pill.setAttribute("aria-label", pill.title);
  return pill;
}

const DOCUMENT_TEMPLATE_RUNTIME_AI_MODEL_TIERS = Object.freeze([
  {
    value: "fast",
    label: "Brzi",
    strength: "Slabiji / jeftiniji",
    description: "Za probu, kratke zapisnike i brzu provjeru mapiranja.",
  },
  {
    value: "standard",
    label: "Standard",
    strength: "Uravnotežen",
    description: "Default za većinu starih zapisnika i normalno popunjavanje.",
  },
  {
    value: "strong",
    label: "Jaki",
    strength: "Precizniji",
    description: "Za loš PDF, skenove, slike i složenije Excel tablice.",
  },
  {
    value: "max",
    label: "Najjači",
    strength: "Najsporiji / najskuplji",
    description: "Kad treba maksimalna pažnja i više provjera prije prijedloga.",
  },
]);
const DOCUMENT_TEMPLATE_RUNTIME_AI_MAX_INLINE_FILE_BYTES = 8 * 1024 * 1024;
const DOCUMENT_TEMPLATE_RUNTIME_AI_MAX_INLINE_FILES = 5;
const DOCUMENT_TEMPLATE_RUNTIME_AI_INLINE_TEXT_EXTENSIONS = Object.freeze([".txt", ".csv", ".json", ".xml", ".md"]);

function normalizeDocumentTemplateRuntimeAiModelTier(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  return DOCUMENT_TEMPLATE_RUNTIME_AI_MODEL_TIERS.some((option) => option.value === normalized)
    ? normalized
    : "standard";
}

function getDocumentTemplateRuntimeAiModelTierOption(value = "") {
  const normalized = normalizeDocumentTemplateRuntimeAiModelTier(value);
  return DOCUMENT_TEMPLATE_RUNTIME_AI_MODEL_TIERS.find((option) => option.value === normalized)
    || DOCUMENT_TEMPLATE_RUNTIME_AI_MODEL_TIERS[1];
}

function getDocumentTemplateRuntimeAiAssistantScopeKey(template = {}, workOrder = {}) {
  return [
    String(template?.id || state.activeDocumentTemplateId || "template").trim() || "template",
    String(workOrder?.id || state.documentTemplateRuntime.activeWorkOrderId || "work-order").trim() || "work-order",
  ].join("::");
}

function getDocumentTemplateRuntimeAiAssistantState(template = {}, workOrder = {}) {
  const scopeKey = getDocumentTemplateRuntimeAiAssistantScopeKey(template, workOrder);
  const current = state.documentTemplateRuntime.aiAssistant;
  if (!current || current.scopeKey !== scopeKey) {
    state.documentTemplateRuntime.aiAssistant = {
      scopeKey,
      files: [],
      status: "idle",
      message: "",
      lastPlan: null,
      modelTier: "standard",
    };
  } else {
    current.modelTier = normalizeDocumentTemplateRuntimeAiModelTier(current.modelTier);
  }
  return state.documentTemplateRuntime.aiAssistant;
}

function setDocumentTemplateRuntimeAiModelTier(modelTier, template = {}, workOrder = {}) {
  const assistant = getDocumentTemplateRuntimeAiAssistantState(template, workOrder);
  assistant.modelTier = normalizeDocumentTemplateRuntimeAiModelTier(modelTier);
  assistant.lastPlan = null;
  assistant.message = assistant.files?.length
    ? `Model postavljen na ${getDocumentTemplateRuntimeAiModelTierOption(assistant.modelTier).label}. Spremno za NexAI pripremu.`
    : "Odaberi snagu modela, zatim dodaj stari zapisnik.";
  assistant.status = assistant.files?.length ? "ready" : "idle";
  renderDocumentTemplateFieldRows({ renderSupport: false });
}

function canInlineDocumentTemplateRuntimeAiFile(file = {}) {
  const name = String(file?.name || "").trim();
  const size = Number(file?.size || 0);
  const type = String(file?.type || "").trim();
  const lowerName = name.toLowerCase();
  if (!name || size <= 0 || size > DOCUMENT_TEMPLATE_RUNTIME_AI_MAX_INLINE_FILE_BYTES) {
    return false;
  }
  return type === "application/pdf"
    || type.startsWith("image/")
    || type.startsWith("text/")
    || type.includes("json")
    || type.includes("xml")
    || DOCUMENT_TEMPLATE_RUNTIME_AI_INLINE_TEXT_EXTENSIONS.some((extension) => lowerName.endsWith(extension));
}

function readDocumentTemplateRuntimeAiFileAsDataUrl(file = {}) {
  return new Promise((resolveRead) => {
    if (!canInlineDocumentTemplateRuntimeAiFile(file)) {
      resolveRead("");
      return;
    }
    const reader = new FileReader();
    reader.addEventListener("load", () => {
      resolveRead(typeof reader.result === "string" ? reader.result : "");
    }, { once: true });
    reader.addEventListener("error", () => {
      resolveRead("");
    }, { once: true });
    reader.readAsDataURL(file);
  });
}

async function createDocumentTemplateRuntimeAiFileMeta(file = {}) {
  const name = String(file?.name || "").trim();
  const size = Number(file?.size || 0);
  const type = String(file?.type || "").trim();
  const lastModified = Number(file?.lastModified || 0);
  const safeName = name || "stari-zapisnik";
  const contentDataUrl = await readDocumentTemplateRuntimeAiFileAsDataUrl(file);
  return {
    id: [safeName, Number.isFinite(size) ? size : 0, Number.isFinite(lastModified) ? lastModified : 0].join("::"),
    name: safeName,
    size: Number.isFinite(size) ? size : 0,
    type,
    lastModified: Number.isFinite(lastModified) ? lastModified : 0,
    contentDataUrl,
    inlineReady: Boolean(contentDataUrl),
  };
}

async function addDocumentTemplateRuntimeAiFiles(files, template = {}, workOrder = {}) {
  const assistant = getDocumentTemplateRuntimeAiAssistantState(template, workOrder);
  const fileList = Array.from(files ?? []);
  if (fileList.length > 0) {
    assistant.status = "loading";
    assistant.message = "Učitavam datoteke za NexAI obradu...";
    renderDocumentTemplateFieldRows({ renderSupport: false });
  }
  const incoming = (await Promise.all(fileList.map(createDocumentTemplateRuntimeAiFileMeta)))
    .filter((file) => file.name);
  if (incoming.length === 0) {
    assistant.status = "error";
    assistant.message = "Nisam dobio datoteku za NexAI pripremu.";
    renderDocumentTemplateFieldRows({ renderSupport: false });
    return;
  }

  const fileMap = new Map((assistant.files ?? []).map((file) => [String(file.id || file.name), file]));
  incoming.forEach((file) => {
    fileMap.set(String(file.id || file.name), file);
  });
  assistant.files = Array.from(fileMap.values()).slice(0, 12);
  assistant.status = "ready";
  assistant.lastPlan = null;
  const inlineCount = assistant.files.filter((file) => file.inlineReady || file.contentDataUrl).length;
  const fileLabel = assistant.files.length === 1 ? "1 datoteka" : `${assistant.files.length} datoteka`;
  assistant.message = inlineCount > 0
    ? `${fileLabel} spremno. ${inlineCount} ide direktno u NexAI analizu.`
    : `${fileLabel} spremno, ali bez čitljivog PDF/slika/tekst sadržaja za direktnu NexAI analizu.`;
  renderDocumentTemplateFieldRows({ renderSupport: false });
}

function removeDocumentTemplateRuntimeAiFile(fileId, template = {}, workOrder = {}) {
  const assistant = getDocumentTemplateRuntimeAiAssistantState(template, workOrder);
  assistant.files = (assistant.files ?? []).filter((file) => String(file.id || file.name) !== String(fileId));
  assistant.lastPlan = null;
  assistant.status = assistant.files.length > 0 ? "ready" : "idle";
  assistant.message = assistant.files.length > 0
    ? (assistant.files.length === 1
      ? "1 datoteka ostaje za NexAI pripremu."
      : `${assistant.files.length} datoteka ostaje za NexAI pripremu.`)
    : "";
  renderDocumentTemplateFieldRows({ renderSupport: false });
}

function getDocumentTemplateRuntimeAiFields(template = {}) {
  const fields = Array.isArray(template?.customFields) && template.customFields.length > 0
    ? template.customFields
    : documentTemplateFieldDrafts;
  return fields
    .map((field, index) => {
      const fieldType = String(field?.type || "text").trim().toLowerCase();
      const config = normalizeDocumentTemplateFieldAiConfig(field?.ai ?? field?.aiConfig, field);
      const isSystemDescription = fieldType === "system_description";
      if (!hasDocumentTemplateFieldAiConfig(config, field) && !isSystemDescription) {
        return null;
      }
      const runtimeField = {
        id: String(field?.id || `field-${index + 1}`),
        key: config.key || String(field?.key || field?.wordLabel || field?.label || `field_${index + 1}`),
        label: config.label || String(field?.label || field?.wordLabel || `Polje ${index + 1}`),
        type: isSystemDescription ? "system_description" : (config.type || fieldType || "text"),
        fieldType,
        required: Boolean(config.required || field?.required),
        ai: config,
      };
      if (isSystemDescription) {
        runtimeField.valueShape = "system_description_blocks";
        runtimeField.sectionSubtitle = String(field?.sectionSubtitle || "");
        runtimeField.systemRows = normalizeDocumentTemplateSystemDescriptionRows(
          field?.systemRows,
          {
            ensureOne: true,
            fallbackRows: createDefaultDocumentTemplateSystemDescriptionRows(),
          },
        ).map((row, rowIndex) => ({
          id: String(row?.id || `system-description-row-${rowIndex + 1}`),
          subtitle: String(row?.subtitle || ""),
          lineCount: normalizeDocumentTemplateSystemDescriptionLineCount(row?.lineCount),
          placeholder: String(row?.placeholder || ""),
        }));
      }
      return runtimeField;
    })
    .filter(Boolean);
}

function getDocumentTemplateRuntimeAiMeasurementColumns(template = {}) {
  const fields = Array.isArray(template?.customFields) && template.customFields.length > 0
    ? template.customFields
    : documentTemplateFieldDrafts;
  const columns = [];
  fields.forEach((field) => {
    if (String(field?.type || "").trim() !== "measurement_table") {
      return;
    }
    const sheet = ensureDocumentTemplateMeasurementFieldSheet(field);
    const fieldAi = normalizeDocumentTemplateFieldAiConfig(field?.ai ?? field?.aiConfig, field);
    (Array.isArray(sheet?.columns) ? sheet.columns : [])
      .filter((column) => !column?.computed)
      .forEach((column, columnIndex) => {
        const aiMapping = normalizeMeasurementSheetColumnAiMappingSnapshotLocal(column?.aiMapping ?? column?.ai);
        if (!hasMeasurementColumnAiMapping(aiMapping)) {
          return;
        }
        columns.push({
          fieldId: String(field?.id || ""),
          fieldKey: String(field?.key || ""),
          fieldLabel: String(field?.label || field?.wordLabel || "Mjerenje"),
          fieldDescription: fieldAi.aiDescription || fieldAi.description || String(field?.helpText || ""),
          columnId: String(column?.id || ""),
          columnIndex,
          columnLetter: getSpreadsheetColumnLabel(columnIndex),
          key: aiMapping.key || String(column?.id || ""),
          label: aiMapping.label || String(column?.label || column?.placeholder || column?.id || "Kolona"),
          type: aiMapping.type || aiMapping.format || "text",
          required: Boolean(aiMapping.required),
          placeholder: String(column?.placeholder || aiMapping.placeholder || ""),
          helpText: aiMapping.helpText || aiMapping.description || aiMapping.aiDescription || "",
          aiMapping,
        });
      });
  });
  return columns;
}

function getDocumentTemplateRuntimeAiPayloadFiles(files = [], options = {}) {
  const maxInlineFiles = Math.max(
    0,
    Number.isFinite(Number(options.maxInlineFiles))
      ? Math.floor(Number(options.maxInlineFiles))
      : DOCUMENT_TEMPLATE_RUNTIME_AI_MAX_INLINE_FILES,
  );
  let inlineCount = 0;
  return (Array.isArray(files) ? files : []).map((file) => {
    const base = {
      id: String(file?.id || file?.name || ""),
      name: String(file?.name || ""),
      size: Number(file?.size || 0),
      type: String(file?.type || ""),
      lastModified: Number(file?.lastModified || 0),
      inlineReady: Boolean(file?.inlineReady || file?.contentDataUrl),
    };
    if (file?.contentDataUrl && inlineCount < maxInlineFiles) {
      inlineCount += 1;
      return {
        ...base,
        contentDataUrl: String(file.contentDataUrl),
      };
    }
    return base;
  });
}

function getDocumentTemplateRuntimeAiResultObject(payload = {}) {
  if (payload?.result && typeof payload.result === "object") {
    return payload.result;
  }
  const text = String(payload?.outputText || "").trim();
  if (!text) {
    return null;
  }
  try {
    return JSON.parse(text);
  } catch {
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) {
      return null;
    }
    try {
      return JSON.parse(match[0]);
    } catch {
      return null;
    }
  }
}

function getDocumentTemplateRuntimeAiSuggestionArray(result = {}, camelKey = "", snakeKey = "") {
  if (Array.isArray(result?.[camelKey])) {
    return result[camelKey];
  }
  if (snakeKey && Array.isArray(result?.[snakeKey])) {
    return result[snakeKey];
  }
  return [];
}

function normalizeDocumentTemplateRuntimeAiLookupKey(value = "") {
  return String(value ?? "").trim().toLowerCase();
}

function getDocumentTemplateRuntimeAiLookupKeyVariants(value = "") {
  const normalizedValue = normalizeDocumentTemplateRuntimeAiLookupKey(value);
  const looseValue = normalizeLooseName(value);
  return [normalizedValue, looseValue].filter(Boolean);
}

function getDocumentTemplateRuntimeAiSuggestionLookupValues(suggestion = {}) {
  return Array.from(new Set([
    suggestion?.fieldId,
    suggestion?.field_id,
    suggestion?.fieldKey,
    suggestion?.field_key,
    suggestion?.key,
    suggestion?.label,
    suggestion?.fieldLabel,
    suggestion?.field_label,
  ]
    .flatMap(getDocumentTemplateRuntimeAiLookupKeyVariants)
    .filter(Boolean)));
}

function getDocumentTemplateRuntimeAiFieldLookupValues(candidate = {}) {
  const aiConfig = normalizeDocumentTemplateFieldAiConfig(candidate?.ai ?? candidate?.aiConfig, candidate);
  return Array.from(new Set([
    candidate?.id,
    candidate?.key,
    candidate?.wordLabel,
    candidate?.label,
    aiConfig.key,
    aiConfig.label,
  ]
    .flatMap(getDocumentTemplateRuntimeAiLookupKeyVariants)
    .filter(Boolean)));
}

function getDocumentTemplateRuntimeAiMatchedFields(fields = [], suggestion = {}) {
  const lookupValues = new Set(getDocumentTemplateRuntimeAiSuggestionLookupValues(suggestion));
  if (!lookupValues.size) {
    return [];
  }

  return (Array.isArray(fields) ? fields : []).filter((candidate) => (
    getDocumentTemplateRuntimeAiFieldLookupValues(candidate).some((value) => lookupValues.has(value))
  ));
}

function findDocumentTemplateRuntimeAiField(fields = [], suggestion = {}) {
  return getDocumentTemplateRuntimeAiMatchedFields(fields, suggestion)[0] ?? null;
}

function findDocumentTemplateRuntimeAiMeasurementField(fields = [], suggestion = {}) {
  const allFields = Array.isArray(fields) ? fields : [];
  const matchedFields = getDocumentTemplateRuntimeAiMatchedFields(allFields, suggestion);
  const directMeasurementField = matchedFields.find((field) => (
    String(field?.type || "").trim().toLowerCase() === "measurement_table"
  ));
  if (directMeasurementField) {
    return directMeasurementField;
  }

  for (const matchedField of matchedFields) {
    if (String(matchedField?.type || "").trim().toLowerCase() !== "chapter") {
      continue;
    }
    const childMeasurementFields = getDocumentTemplateRuntimeChapterChildFields(allFields, matchedField)
      .filter((field) => String(field?.type || "").trim().toLowerCase() === "measurement_table");
    if (childMeasurementFields.length === 1) {
      return childMeasurementFields[0];
    }
  }

  const measurementFields = allFields.filter((field) => (
    String(field?.type || "").trim().toLowerCase() === "measurement_table"
  ));
  return measurementFields.length === 1 ? measurementFields[0] : null;
}

function isDocumentTemplateRuntimeAiWritableField(field = {}) {
  const type = String(field?.type || "text").trim().toLowerCase();
  if (!field || !DOCUMENT_TEMPLATE_RUNTIME_AI_WRITABLE_FIELD_TYPES.has(type)) {
    return false;
  }
  return isDocumentTemplateRuntimePersistedField(field)
    || hasDocumentTemplateFieldAiConfig(field.ai ?? field.aiConfig, field);
}

function getDocumentTemplateRuntimeChapterChildFields(fields = [], chapterField = {}) {
  const allFields = Array.isArray(fields) ? fields : [];
  const chapterId = String(chapterField?.id || "").trim();
  const chapterIndex = allFields.findIndex((field) => String(field?.id || "").trim() === chapterId);
  if (chapterIndex < 0) {
    return [];
  }

  const childFields = [];
  for (let index = chapterIndex + 1; index < allFields.length; index += 1) {
    const field = allFields[index];
    const type = String(field?.type || "").trim().toLowerCase();
    if (type === "chapter" || type === "page_break") {
      break;
    }
    childFields.push(field);
  }
  return childFields;
}

function findDocumentTemplateRuntimeAiWritableField(fields = [], suggestion = {}) {
  const matchedFields = getDocumentTemplateRuntimeAiMatchedFields(fields, suggestion);
  const directWritableField = matchedFields.find(isDocumentTemplateRuntimeAiWritableField);
  if (directWritableField) {
    return directWritableField;
  }

  const lookupValues = new Set(getDocumentTemplateRuntimeAiSuggestionLookupValues(suggestion));
  for (const matchedField of matchedFields) {
    if (String(matchedField?.type || "").trim().toLowerCase() !== "chapter") {
      continue;
    }
    const childFields = getDocumentTemplateRuntimeChapterChildFields(fields, matchedField)
      .filter(isDocumentTemplateRuntimeAiWritableField);
    const exactChild = childFields.find((childField) => (
      getDocumentTemplateRuntimeAiFieldLookupValues(childField).some((value) => lookupValues.has(value))
    ));
    if (exactChild) {
      return exactChild;
    }
    const aiChildren = childFields.filter((childField) => (
      hasDocumentTemplateFieldAiConfig(childField.ai ?? childField.aiConfig, childField)
    ));
    if (aiChildren.length === 1) {
      return aiChildren[0];
    }
    if (childFields.length === 1) {
      return childFields[0];
    }
    if (aiChildren.length > 0) {
      return aiChildren[0];
    }
  }

  return null;
}

function getDocumentTemplateRuntimeAiSuggestionValue(suggestion = {}) {
  return suggestion?.value
    ?? suggestion?.suggestedValue
    ?? suggestion?.suggested_value
    ?? suggestion?.text
    ?? "";
}

function applyDocumentTemplateRuntimeAiFieldSuggestion(payload = {}, workOrder = {}, suggestion = {}, field = null) {
  const rawValue = getDocumentTemplateRuntimeAiSuggestionValue(suggestion);
  if (!workOrder?.id || !field || !isDocumentTemplateRuntimeAiWritableField(field) || !hasMeaningfulDocumentRecordValue(rawValue)) {
    return false;
  }

  const confidence = normalizeAiConfidenceLevelLocal(suggestion?.confidence, "low");
  const normalizedValue = normalizeDocumentTemplateRuntimeFieldValueByType(field, rawValue);
  if (!hasMeaningfulDocumentRecordValue(normalizedValue)) {
    return false;
  }

  setDocumentTemplateRuntimeFieldValue(workOrder.id, field.id, normalizedValue, {
    render: false,
    source: "ai",
    aiMeta: {
      confidence,
      reason: suggestion?.reason ?? suggestion?.explanation ?? "",
      sourceFile: suggestion?.sourceFile ?? suggestion?.source_file ?? "",
      sourcePage: suggestion?.sourcePage ?? suggestion?.source_page ?? "",
      model: payload?.model || payload?.modelLabel || "",
    },
  });
  return true;
}

function getDocumentTemplateRuntimeAiSuggestionRows(suggestion = {}) {
  const sources = [
    suggestion?.rows,
    suggestion?.tableRows,
    suggestion?.table_rows,
    suggestion?.dataRows,
    suggestion?.data_rows,
    suggestion?.items,
    suggestion?.records,
    suggestion?.values,
    suggestion?.value,
  ];
  const rows = sources.find((source) => Array.isArray(source));
  if (Array.isArray(rows)) {
    return rows;
  }
  const singleRow = sources.find((source) => (
    source && typeof source === "object" && !Array.isArray(source)
  ));
  return singleRow ? [singleRow] : [];
}

function getDocumentTemplateRuntimeAiSuggestionRowValues(row = {}, editableColumns = []) {
  if (Array.isArray(row)) {
    return row;
  }
  if (row?.data && (typeof row.data === "object" || Array.isArray(row.data))) {
    return row.data;
  }
  if (row?.values && (typeof row.values === "object" || Array.isArray(row.values))) {
    return row.values;
  }
  if (Array.isArray(row?.orderedValues) || Array.isArray(row?.ordered_values)) {
    return row.orderedValues ?? row.ordered_values;
  }
  if (row?.cells && (typeof row.cells === "object" || Array.isArray(row.cells))) {
    return row.cells;
  }
  if (row?.columns && (typeof row.columns === "object" || Array.isArray(row.columns))) {
    return row.columns;
  }
  if (row && typeof row === "object") {
    return row;
  }
  const firstColumn = editableColumns[0];
  return firstColumn ? { [firstColumn.id]: row } : {};
}

const DOCUMENT_TEMPLATE_RUNTIME_AI_MEASUREMENT_META_KEYS = new Set([
  "confidence",
  "sourcefile",
  "source_file",
  "sourcepage",
  "source_page",
  "reason",
  "explanation",
  "note",
  "notes",
  "warning",
  "warnings",
  "fieldid",
  "field_id",
  "fieldkey",
  "field_key",
  "fieldlabel",
  "field_label",
  "row",
  "rowindex",
  "row_index",
  "id",
]);

function isDocumentTemplateRuntimeAiMeasurementMetaKey(key = "") {
  return getDocumentTemplateRuntimeAiLookupKeyVariants(key)
    .some((variant) => DOCUMENT_TEMPLATE_RUNTIME_AI_MEASUREMENT_META_KEYS.has(variant.replace(/\s+/g, "")));
}

function extractDocumentTemplateRuntimeAiCellValue(value) {
  if (value == null) {
    return "";
  }
  if (typeof value !== "object") {
    return value;
  }
  const preferredKeys = [
    "value",
    "text",
    "content",
    "cellValue",
    "cell_value",
    "suggestedValue",
    "suggested_value",
    "result",
  ];
  for (const key of preferredKeys) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      return value[key] ?? "";
    }
  }
  return "";
}

function getDocumentTemplateRuntimeAiMeasurementColumnLookupValues(column = {}, columnIndex = -1) {
  const aiMapping = normalizeMeasurementSheetColumnAiMappingSnapshotLocal(column?.aiMapping ?? column?.ai);
  const sheetColumnIndex = Number(column?.aiSheetColumnIndex);
  const targetColumnIndex = Number(column?.aiTargetColumnIndex);
  return new Set([
    column?.id,
    column?.key,
    column?.label,
    column?.placeholder,
    Number.isInteger(columnIndex) && columnIndex >= 0 ? getSpreadsheetColumnLabel(columnIndex) : "",
    Number.isInteger(sheetColumnIndex) && sheetColumnIndex >= 0 ? getSpreadsheetColumnLabel(sheetColumnIndex) : "",
    Number.isInteger(targetColumnIndex) && targetColumnIndex >= 0 ? getSpreadsheetColumnLabel(targetColumnIndex) : "",
    aiMapping.key,
    aiMapping.label,
    aiMapping.placeholder,
    ...(Array.isArray(aiMapping.synonyms) ? aiMapping.synonyms : []),
    ...(Array.isArray(aiMapping.aiLookFor) ? aiMapping.aiLookFor : []),
  ]
    .flatMap(getDocumentTemplateRuntimeAiLookupKeyVariants)
    .filter(Boolean));
}

function getDocumentTemplateRuntimeAiCellReferenceValues(value = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return [];
  }
  return [
    value.columnId,
    value.column_id,
    value.columnKey,
    value.column_key,
    value.columnLabel,
    value.column_label,
    value.column,
    value.key,
    value.id,
    value.label,
    value.name,
    value.header,
  ].flatMap(getDocumentTemplateRuntimeAiLookupKeyVariants).filter(Boolean);
}

function doesDocumentTemplateRuntimeAiCellReferenceColumn(value = {}, column = {}, columnIndex = -1) {
  const columnKeys = getDocumentTemplateRuntimeAiMeasurementColumnLookupValues(column, columnIndex);
  return getDocumentTemplateRuntimeAiCellReferenceValues(value).some((variant) => columnKeys.has(variant));
}

function getDocumentTemplateRuntimeAiSuggestionArrayCellValue(values = [], column = {}, columnIndex = 0) {
  const objectMatch = values.find((entry) => (
    entry && typeof entry === "object" && !Array.isArray(entry)
    && doesDocumentTemplateRuntimeAiCellReferenceColumn(entry, column, columnIndex)
  ));
  if (objectMatch) {
    return extractDocumentTemplateRuntimeAiCellValue(objectMatch);
  }
  return extractDocumentTemplateRuntimeAiCellValue(values[columnIndex]);
}

function getDocumentTemplateRuntimeAiSuggestionCellValue(values = {}, column = {}, columnIndex = 0) {
  if (Array.isArray(values)) {
    return getDocumentTemplateRuntimeAiSuggestionArrayCellValue(values, column, columnIndex);
  }
  if (!values || typeof values !== "object") {
    return "";
  }
  if (doesDocumentTemplateRuntimeAiCellReferenceColumn(values, column, columnIndex)) {
    return extractDocumentTemplateRuntimeAiCellValue(values);
  }
  const keys = getDocumentTemplateRuntimeAiMeasurementColumnLookupValues(column, columnIndex);
  const entries = Object.entries(values);
  const matchedEntry = entries.find(([key]) => (
    !isDocumentTemplateRuntimeAiMeasurementMetaKey(key)
    && getDocumentTemplateRuntimeAiLookupKeyVariants(key).some((variant) => keys.has(variant))
  ));
  if (matchedEntry) {
    return extractDocumentTemplateRuntimeAiCellValue(matchedEntry[1]);
  }

  return "";
}

function getDocumentTemplateRuntimeAiMeasurementTargetColumns(sheet = {}) {
  return (Array.isArray(sheet?.columns) ? sheet.columns : [])
    .map((column, sheetColumnIndex) => ({ column, sheetColumnIndex }))
    .filter(({ column }) => (
      !column?.computed
      && hasMeasurementColumnAiMapping(column?.aiMapping ?? column?.ai)
    ))
    .map(({ column, sheetColumnIndex }, targetColumnIndex) => ({
      column: {
        ...column,
        aiSheetColumnIndex: sheetColumnIndex,
        aiTargetColumnIndex: targetColumnIndex,
      },
      sheetColumnIndex,
      targetColumnIndex,
    }));
}

function buildDocumentTemplateRuntimeAiMeasurementRows(workOrder = {}, field = {}, suggestion = {}, suggestionIndex = 0) {
  if (!workOrder?.id || !field || String(field.type || "").trim().toLowerCase() !== "measurement_table") {
    return null;
  }

  const rows = getDocumentTemplateRuntimeAiSuggestionRows(suggestion);
  if (!rows.length) {
    return null;
  }

  const sheet = getDocumentTemplateRuntimeMeasurementSheet(workOrder.id, field)
    ?? ensureDocumentTemplateMeasurementFieldSheet(field);
  const normalizedSheet = normalizeWorkOrderMeasurementSheet(sheet);
  if (!normalizedSheet?.columns?.length) {
    return null;
  }

  const targetColumns = getDocumentTemplateRuntimeAiMeasurementTargetColumns(normalizedSheet);
  if (!targetColumns.length) {
    return null;
  }
  const incomingRows = rows.map((row, rowIndex) => {
    const values = getDocumentTemplateRuntimeAiSuggestionRowValues(row, targetColumns.map(({ column }) => column));
    const cells = {};
    const formats = {};
    targetColumns.forEach(({ column, sheetColumnIndex }, targetColumnIndex) => {
      const cellValue = getDocumentTemplateRuntimeAiSuggestionCellValue(values, column, targetColumnIndex);
      cells[column.id] = cellValue == null ? "" : String(cellValue);
      formats[column.id] = normalizeMeasurementCellFormat(row?.formats?.[column.id] ?? row?.formats?.[sheetColumnIndex]);
    });
    return normalizeMeasurementSheetRowSnapshotLocal({
      id: `measurement-ai-${Date.now()}-${suggestionIndex + 1}-${rowIndex + 1}`,
      cells,
      formats,
    }, normalizedSheet.columns, normalizedSheet.rows.length + rowIndex);
  }).filter((row) => isMeasurementSheetRowMeaningful(row, targetColumns.map(({ column }) => column)));

  if (!incomingRows.length) {
    return null;
  }

  return {
    sheet: normalizedSheet,
    rows: incomingRows,
    targetColumns,
  };
}

const DOCUMENT_TEMPLATE_RUNTIME_AI_EMPTY_MEASUREMENT_CELL_HINTS = new Set([
  "pozicija",
  "opis",
  "vrijednost",
  "granica",
  "napomena",
  "unos",
  "mjerno mjesto",
  "oznaka",
  "jedinica",
  "min",
  "max",
  "0,00",
]);

function isDocumentTemplateRuntimeAiBlankMeasurementCell(value = "", column = {}) {
  const normalizedValue = String(value ?? "").trim().toLowerCase();
  if (!normalizedValue) {
    return true;
  }
  const normalizedLabel = String(column?.label || "").trim().toLowerCase();
  const normalizedPlaceholder = String(column?.placeholder || "").trim().toLowerCase();
  return normalizedValue === normalizedLabel
    || normalizedValue === normalizedPlaceholder
    || DOCUMENT_TEMPLATE_RUNTIME_AI_EMPTY_MEASUREMENT_CELL_HINTS.has(normalizedValue);
}

function isDocumentTemplateRuntimeAiWritableBlankMeasurementRow(row = {}, columns = []) {
  return (Array.isArray(columns) ? columns : [])
    .filter((column) => !column?.computed)
    .every((column) => isDocumentTemplateRuntimeAiBlankMeasurementCell(row?.cells?.[column.id], column));
}

function applyDocumentTemplateRuntimeAiMeasurementSuggestion(payload = {}, workOrder = {}, suggestion = {}, field = null, suggestionIndex = 0) {
  const measurementPatch = buildDocumentTemplateRuntimeAiMeasurementRows(workOrder, field, suggestion, suggestionIndex);
  if (!measurementPatch) {
    return { applied: false, rowCount: 0 };
  }

  const existingRows = [...(measurementPatch.sheet.rows ?? [])];
  const headerRowIds = new Set((measurementPatch.sheet.headerRows ?? []).map((rowId) => String(rowId || "")));
  const aiColumns = measurementPatch.targetColumns.map(({ column }) => column);
  const aiColumnIds = new Set(aiColumns.map((column) => String(column.id || "")));
  measurementPatch.rows.forEach((incomingRow) => {
    const blankIndex = existingRows.findIndex((row) => (
      !headerRowIds.has(String(row?.id || ""))
      &&
      isDocumentTemplateRuntimeAiWritableBlankMeasurementRow(row, aiColumns)
    ));
    if (blankIndex >= 0) {
      const existingRow = existingRows[blankIndex];
      const nextCells = { ...(existingRow?.cells ?? {}) };
      const nextFormats = { ...(existingRow?.formats ?? {}) };
      aiColumnIds.forEach((columnId) => {
        nextCells[columnId] = incomingRow?.cells?.[columnId] ?? "";
        nextFormats[columnId] = normalizeMeasurementCellFormat(incomingRow?.formats?.[columnId]);
      });
      existingRows[blankIndex] = {
        ...existingRow,
        id: existingRow.id,
        cells: nextCells,
        formats: nextFormats,
      };
    } else {
      const blankRow = normalizeMeasurementSheetRowSnapshotLocal({
        id: incomingRow.id,
        cells: {},
        formats: {},
      }, measurementPatch.sheet.columns, existingRows.length);
      const nextCells = { ...(blankRow.cells ?? {}) };
      const nextFormats = { ...(blankRow.formats ?? {}) };
      aiColumnIds.forEach((columnId) => {
        nextCells[columnId] = incomingRow?.cells?.[columnId] ?? "";
        nextFormats[columnId] = normalizeMeasurementCellFormat(incomingRow?.formats?.[columnId]);
      });
      existingRows.push({
        ...blankRow,
        cells: nextCells,
        formats: nextFormats,
      });
    }
  });

  const nextSheet = {
    ...measurementPatch.sheet,
    rows: existingRows,
  };
  setDocumentTemplateRuntimeMeasurementSheet(workOrder.id, field.id, nextSheet, { render: false });

  const isOpenSameRuntimeSheet = state.measurementSheet.isOpen
    && state.measurementSheet.ownerKind === "document_template_runtime_field"
    && String(state.measurementSheet.ownerFieldId || "") === String(field.id || "")
    && String(state.measurementSheet.ownerRuntimeWorkOrderId || "") === String(workOrder.id || "");
  if (isOpenSameRuntimeSheet) {
    applyMeasurementSheetSnapshot(nextSheet);
    syncMeasurementSheetHeaderFromWorkOrder();
    renderMeasurementSheet();
    syncMeasurementToolbar();
  }

  return {
    applied: true,
    rowCount: measurementPatch.rows.length,
  };
}

function applyDocumentTemplateRuntimeAiSuggestions(payload = {}, template = {}, workOrder = {}) {
  const result = getDocumentTemplateRuntimeAiResultObject(payload);
  const fieldSuggestions = getDocumentTemplateRuntimeAiSuggestionArray(result, "fieldSuggestions", "field_suggestions");
  const measurementSuggestions = getDocumentTemplateRuntimeAiSuggestionArray(result, "measurementSuggestions", "measurement_suggestions");
  if (!workOrder?.id || (!fieldSuggestions.length && !measurementSuggestions.length)) {
    return { fieldCount: 0, measurementCount: 0 };
  }

  const fields = Array.isArray(template?.customFields) && template.customFields.length > 0
    ? template.customFields
    : documentTemplateFieldDrafts;
  let fieldCount = 0;
  let measurementCount = 0;

  fieldSuggestions.forEach((suggestion) => {
    const field = findDocumentTemplateRuntimeAiWritableField(fields, suggestion);
    if (applyDocumentTemplateRuntimeAiFieldSuggestion(payload, workOrder, suggestion, field)) {
      fieldCount += 1;
    }
  });

  measurementSuggestions.forEach((suggestion, suggestionIndex) => {
    const field = findDocumentTemplateRuntimeAiMeasurementField(fields, suggestion);
    const applied = applyDocumentTemplateRuntimeAiMeasurementSuggestion(payload, workOrder, suggestion, field, suggestionIndex);
    if (applied.applied) {
      measurementCount += 1;
    }
  });

  if (fieldCount > 0 || measurementCount > 0) {
    scheduleDocumentTemplateRuntimeAutosave();
  }
  return { fieldCount, measurementCount };
}

function formatDocumentTemplateRuntimeAiSuggestionValue(value = "", field = null) {
  if (value == null) {
    return "";
  }
  if (isDocumentTemplateSystemDescriptionValue(value)) {
    return String(field?.type || "").trim().toLowerCase() === "system_description"
      ? buildDocumentTemplateSystemDescriptionSummaryText(value)
      : buildDocumentTemplateSystemDescriptionNarrativeText(value, {
        includeBlockTitle: false,
        includeRowHeadings: true,
      });
  }
  if (String(field?.type || "").trim().toLowerCase() === "system_description") {
    const normalizedValue = normalizeDocumentTemplateSystemDescriptionRuntimeValue(field, value);
    return buildDocumentTemplateSystemDescriptionSummaryText(normalizedValue);
  }
  if (typeof value === "object") {
    try {
      return JSON.stringify(value);
    } catch {
      return String(value);
    }
  }
  return String(value);
}

function getDocumentTemplateRuntimeAiSuggestionConfidenceLabel(suggestion = {}) {
  const confidence = normalizeAiConfidenceLevelLocal(suggestion?.confidence, "");
  if (confidence === "high") {
    return "Visoka sigurnost";
  }
  if (confidence === "medium") {
    return "Srednja sigurnost";
  }
  if (confidence === "low") {
    return "Niska sigurnost";
  }
  return "Bez ocjene sigurnosti";
}

function createDocumentTemplateRuntimeAiSuggestionsPanel(payload = {}, template = {}, workOrder = {}) {
  const result = getDocumentTemplateRuntimeAiResultObject(payload);
  const fieldSuggestions = getDocumentTemplateRuntimeAiSuggestionArray(result, "fieldSuggestions", "field_suggestions");
  const measurementSuggestions = getDocumentTemplateRuntimeAiSuggestionArray(result, "measurementSuggestions", "measurement_suggestions");
  if (!fieldSuggestions.length && !measurementSuggestions.length) {
    return null;
  }

  const fields = Array.isArray(template?.customFields) && template.customFields.length > 0
    ? template.customFields
    : documentTemplateFieldDrafts;
  const panel = document.createElement("section");
  panel.className = "document-template-runtime-ai-suggestions";

  const head = document.createElement("div");
  head.className = "document-template-runtime-ai-suggestions-head";
  const title = document.createElement("strong");
  title.textContent = "NexAI prijedlozi";
  const meta = document.createElement("span");
  meta.textContent = `${fieldSuggestions.length} polja · ${measurementSuggestions.length} Excel tablica`;
  head.append(title, meta);

  const list = document.createElement("div");
  list.className = "document-template-runtime-ai-suggestions-list";

  fieldSuggestions.forEach((suggestion, index) => {
    const matchedField = findDocumentTemplateRuntimeAiField(fields, suggestion);
    const field = findDocumentTemplateRuntimeAiWritableField(fields, suggestion);
    const rawValue = getDocumentTemplateRuntimeAiSuggestionValue(suggestion);
    const suggestionField = field || matchedField;
    const value = formatDocumentTemplateRuntimeAiSuggestionValue(rawValue, suggestionField);
    const shouldRenderRichValue = String(suggestionField?.type || "").trim().toLowerCase() === "longtext"
      && isRichTextHtml(value);
    const copyValue = shouldRenderRichValue ? richTextHtmlToPlainText(value) : value;
    const canApply = Boolean(field && isDocumentTemplateRuntimeAiWritableField(field));
    const card = document.createElement("article");
    card.className = "document-template-runtime-ai-suggestion";
    card.classList.toggle("is-unmatched", !canApply);

    const cardHead = document.createElement("div");
    cardHead.className = "document-template-runtime-ai-suggestion-head";
    const cardTitle = document.createElement("strong");
    cardTitle.textContent = String(
      suggestion?.fieldLabel
      || suggestion?.field_label
      || suggestion?.label
      || field?.label
      || field?.wordLabel
      || `Prijedlog ${index + 1}`,
    ).trim();
    const status = document.createElement("span");
    const resolvedFieldLabel = String(field?.label || field?.wordLabel || "").trim();
    status.textContent = canApply
      ? (resolvedFieldLabel ? `Povezano: ${resolvedFieldLabel}` : "Povezano s poljem")
      : (matchedField ? "Polje nije za automatski upis" : "Nije povezano s template poljem");
    cardHead.append(cardTitle, status);

    const valueNode = document.createElement(shouldRenderRichValue ? "div" : "p");
    valueNode.className = "document-template-runtime-ai-suggestion-value";
    if (shouldRenderRichValue) {
      valueNode.classList.add("is-rich-text");
      valueNode.innerHTML = sanitizeRichTextHtml(value);
    } else {
      valueNode.textContent = value || "Prazna vrijednost";
    }

    const footer = document.createElement("div");
    footer.className = "document-template-runtime-ai-suggestion-footer";
    const confidence = document.createElement("small");
    confidence.textContent = getDocumentTemplateRuntimeAiSuggestionConfidenceLabel(suggestion);
    const reasonText = String(suggestion?.reason ?? suggestion?.explanation ?? "").trim();
    const reason = document.createElement("small");
    reason.textContent = reasonText ? `Razlog: ${reasonText}` : "";
    const copyButton = document.createElement("button");
    copyButton.type = "button";
    copyButton.className = "ghost-button compact-button document-template-runtime-ai-suggestion-copy";
    copyButton.textContent = "Kopiraj";
    copyButton.disabled = !copyValue;
    copyButton.addEventListener("click", async () => {
      try {
        await navigator.clipboard?.writeText(copyValue);
        copyButton.textContent = "Kopirano";
        window.setTimeout(() => {
          copyButton.textContent = "Kopiraj";
        }, 1300);
      } catch {
        copyButton.textContent = "Označi tekst";
      }
    });
    footer.append(confidence);
    if (reasonText) {
      footer.append(reason);
    }
    if (canApply) {
      const applyButton = document.createElement("button");
      applyButton.type = "button";
      applyButton.className = "primary-button compact-button document-template-runtime-ai-suggestion-apply";
      applyButton.textContent = "Upiši";
      applyButton.disabled = !hasMeaningfulDocumentRecordValue(rawValue);
      applyButton.addEventListener("click", () => {
        const applied = applyDocumentTemplateRuntimeAiFieldSuggestion(payload, workOrder, suggestion, field);
        if (!applied) {
          status.textContent = "Nije upisano";
          return;
        }
        status.textContent = "Upisano u polje";
        scheduleDocumentTemplateRuntimeAutosave();
        renderDocumentTemplateFieldRows();
        renderDocumentTemplatePreviewContent();
      });
      footer.append(applyButton);
    }
    footer.append(copyButton);

    card.append(cardHead, valueNode, footer);
    list.append(card);
  });

  measurementSuggestions.forEach((suggestion, index) => {
    const field = findDocumentTemplateRuntimeAiMeasurementField(fields, suggestion);
    const rows = getDocumentTemplateRuntimeAiSuggestionRows(suggestion);
    const preparedRows = field
      ? buildDocumentTemplateRuntimeAiMeasurementRows(workOrder, field, suggestion, index)
      : null;
    const canApply = Boolean(field && preparedRows?.rows?.length);
    const card = document.createElement("article");
    card.className = "document-template-runtime-ai-suggestion";
    card.classList.toggle("is-unmatched", !canApply);

    const cardHead = document.createElement("div");
    cardHead.className = "document-template-runtime-ai-suggestion-head";
    const cardTitle = document.createElement("strong");
    cardTitle.textContent = String(
      suggestion?.fieldLabel
      || suggestion?.field_label
      || suggestion?.label
      || field?.label
      || field?.wordLabel
      || `Excel prijedlog ${index + 1}`,
    ).trim();
    const status = document.createElement("span");
    status.textContent = canApply
      ? `Spremno za upis: ${preparedRows.rows.length} redaka`
      : (field ? "Excel povezan, ali nema redaka za upis" : "Nije povezan s Excel poljem");
    cardHead.append(cardTitle, status);

    const valueNode = document.createElement("p");
    valueNode.className = "document-template-runtime-ai-suggestion-value";
    valueNode.textContent = preparedRows?.rows?.length
      ? `${preparedRows.rows.length} redaka spremno za upis u dokument.`
      : rows.length
        ? `${rows.length} redaka je stiglo od NexAI-ja, ali kolone nisu prepoznate za upis.`
      : "Nema redaka u ovom prijedlogu.";

    const footer = document.createElement("div");
    footer.className = "document-template-runtime-ai-suggestion-footer";
    const confidence = document.createElement("small");
    confidence.textContent = getDocumentTemplateRuntimeAiSuggestionConfidenceLabel(suggestion);
    footer.append(confidence);
    if (canApply) {
      const applyButton = document.createElement("button");
      applyButton.type = "button";
      applyButton.className = "primary-button compact-button document-template-runtime-ai-suggestion-apply";
      applyButton.textContent = "Upiši u Excel";
      applyButton.addEventListener("click", () => {
        const applied = applyDocumentTemplateRuntimeAiMeasurementSuggestion(payload, workOrder, suggestion, field, index);
        if (!applied.applied) {
          status.textContent = "Nije upisano";
          return;
        }
        status.textContent = `Upisano ${applied.rowCount} redaka`;
        scheduleDocumentTemplateRuntimeAutosave();
        renderDocumentTemplateFieldRows();
        renderDocumentTemplatePreviewContent();
      });
      footer.append(applyButton);
    }

    card.append(cardHead, valueNode, footer);
    list.append(card);
  });

  panel.append(head, list);
  return panel;
}

function formatDocumentTemplateRuntimeAiDuration(ms = 0) {
  const numericMs = Number(ms);
  if (!Number.isFinite(numericMs) || numericMs <= 0) {
    return "";
  }
  if (numericMs < 1000) {
    return `${Math.round(numericMs)} ms`;
  }
  return `${(numericMs / 1000).toFixed(numericMs < 10000 ? 1 : 0)} s`;
}

async function runDocumentTemplateRuntimeAiAssistant(template = {}, workOrder = {}) {
  const assistant = getDocumentTemplateRuntimeAiAssistantState(template, workOrder);
  const modelOption = getDocumentTemplateRuntimeAiModelTierOption(assistant.modelTier);
  if (!assistant.files?.length) {
    assistant.status = "error";
    assistant.message = "Prvo dodaj stari zapisnik ili sliku pa pokreni NexAI.";
    renderDocumentTemplateFieldRows({ renderSupport: false });
    return;
  }

  const fields = getDocumentTemplateRuntimeAiFields(template);
  const columns = getDocumentTemplateRuntimeAiMeasurementColumns(template);
  assistant.status = "loading";
  assistant.message = `Šaljem zapisnik NexAI-ju (${modelOption.label}) i čekam prijedloge...`;
  assistant.lastPlan = null;
  renderDocumentTemplateFieldRows({ renderSupport: false });

  try {
    await loadOpenAiIntegrationStatus({ force: true });
    const payload = await apiRequest("/ai/openai/prepare", {
      method: "POST",
      body: {
        purpose: "document-template-runtime-ai-prefill",
        organizationId: state.activeOrganizationId || "",
        templateId: template?.id || state.activeDocumentTemplateId || "",
        workOrderId: workOrder?.id || state.documentTemplateRuntime.activeWorkOrderId || "",
        workOrderNumber: workOrder?.workOrderNumber || workOrder?.number || "",
        files: getDocumentTemplateRuntimeAiPayloadFiles(assistant.files),
        fields,
        columns,
        modelTier: modelOption.value,
        modelPreference: {
          label: modelOption.label,
          strength: modelOption.strength,
          description: modelOption.description,
        },
        dryRun: false,
      },
    });
    assistant.status = "success";
    assistant.lastPlan = payload;
    const applied = payload?.dryRun
      ? { fieldCount: 0, measurementCount: 0 }
      : applyDocumentTemplateRuntimeAiSuggestions(payload, template, workOrder);
    const appliedCount = Number(applied?.fieldCount || 0);
    const appliedMeasurementCount = Number(applied?.measurementCount || 0);
    const result = getDocumentTemplateRuntimeAiResultObject(payload);
    const fieldSuggestionCount = getDocumentTemplateRuntimeAiSuggestionArray(result, "fieldSuggestions", "field_suggestions").length;
    const measurementSuggestionCount = getDocumentTemplateRuntimeAiSuggestionArray(result, "measurementSuggestions", "measurement_suggestions").length;
    const fieldSuggestionLabel = fieldSuggestionCount === 1 ? "1 polje" : `${fieldSuggestionCount} polja`;
    const measurementSuggestionLabel = measurementSuggestionCount === 1 ? "1 Excel tablica" : `${measurementSuggestionCount} Excel tablica`;
    if (payload?.dryRun) {
      assistant.message = `Dry-run je prošao za model ${payload?.modelLabel || modelOption.label}. Live poziv još nije uključen na serveru.`;
    } else {
      const elapsed = formatDocumentTemplateRuntimeAiDuration(payload?.timings?.totalMs);
      assistant.message = [
        `NexAI live test prošao${elapsed ? ` za ${elapsed}` : ""} (${payload?.model || payload?.modelLabel || modelOption.label}).`,
        appliedCount || appliedMeasurementCount
          ? `NexAI je popunio ${appliedCount} polja i ${appliedMeasurementCount} Excel tablica. Boja NexAI oznake pokazuje sigurnost.`
          : "NexAI je vratio prijedloge, ali nema polja koja se mogu automatski upisati.",
        fieldSuggestionCount || measurementSuggestionCount
          ? `Prijedlozi su prikazani ispod NexAI kontrole: ${fieldSuggestionLabel}, ${measurementSuggestionLabel}.`
          : "",
      ].filter(Boolean).join(" ");
    }
    if (!payload?.dryRun && (appliedCount > 0 || appliedMeasurementCount > 0)) {
      renderDocumentTemplateFieldRows();
      renderDocumentTemplatePreviewContent();
    }
  } catch (error) {
    assistant.status = "error";
    assistant.message = error?.message || "NexAI priprema trenutno nije dostupna.";
  }

  renderDocumentTemplateFieldRows({ renderSupport: false });
}

function setDocumentTemplateRuntimeAiAssistantHidden(hidden = false, { render = true } = {}) {
  state.documentTemplateRuntime.aiAssistantHidden = Boolean(hidden);
  if (render) {
    renderDocumentTemplateFieldRows({ renderSupport: false });
  }
}

function createDocumentTemplateRuntimeAiAssistantPanel(template = {}, workOrder = {}) {
  if (state.documentTemplateRuntime.aiAssistantHidden) {
    const collapsedPanel = document.createElement("section");
    collapsedPanel.className = "document-template-runtime-ai-assistant-togglebar";
    collapsedPanel.tabIndex = 0;
    collapsedPanel.setAttribute("role", "button");
    collapsedPanel.setAttribute("aria-label", "Prikaži NexAI");
    const copy = document.createElement("span");
    copy.textContent = "NexAI je sakriven za ovaj unos.";
    const showButton = document.createElement("button");
    showButton.type = "button";
    showButton.className = "ghost-button compact-button";
    showButton.textContent = "Prikaži NexAI";
    showButton.addEventListener("click", () => {
      setDocumentTemplateRuntimeAiAssistantHidden(false);
    });
    collapsedPanel.addEventListener("click", (event) => {
      if (event.target instanceof HTMLElement && event.target.closest("button")) {
        return;
      }
      setDocumentTemplateRuntimeAiAssistantHidden(false);
    });
    collapsedPanel.addEventListener("keydown", (event) => {
      if (!["Enter", " "].includes(event.key)) {
        return;
      }
      event.preventDefault();
      setDocumentTemplateRuntimeAiAssistantHidden(false);
    });
    collapsedPanel.append(copy, showButton);
    return collapsedPanel;
  }

  const assistant = getDocumentTemplateRuntimeAiAssistantState(template, workOrder);
  const modelOption = getDocumentTemplateRuntimeAiModelTierOption(assistant.modelTier);

  const panel = document.createElement("section");
  panel.className = "document-template-runtime-ai-assistant document-template-runtime-nexai-assistant";
  panel.classList.toggle("is-loading", assistant.status === "loading");
  panel.classList.toggle("is-success", assistant.status === "success");
  panel.classList.toggle("is-error", assistant.status === "error");

  const fileInput = document.createElement("input");
  fileInput.type = "file";
  fileInput.multiple = true;
  fileInput.accept = ".pdf,.doc,.docx,.txt,.csv,.json,.xml,.jpg,.jpeg,.png,.webp,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/*,image/*";
  fileInput.hidden = true;

  const intro = document.createElement("div");
  intro.className = "document-template-runtime-ai-intro";
  const introHead = document.createElement("div");
  introHead.className = "document-template-runtime-ai-head document-template-runtime-ai-collapsible-head";
  introHead.tabIndex = 0;
  introHead.setAttribute("role", "button");
  introHead.setAttribute("aria-label", "Sakrij NexAI");
  const mark = document.createElement("span");
  mark.className = "document-template-runtime-ai-mark";
  mark.innerHTML = getWorkOrderIconMarkup("document");
  const copy = document.createElement("div");
  copy.className = "document-template-runtime-ai-copy";
  const eyebrow = document.createElement("span");
  eyebrow.className = "document-template-runtime-ai-eyebrow";
  eyebrow.textContent = "NexAI";
  const title = document.createElement("strong");
  title.textContent = "Uvezi stari zapisnik i pripremi popunjavanje";
  const description = document.createElement("p");
  description.textContent = "Dodaj PDF, sliku ili tekst starog zapisnika. NexAI čita datoteku, vraća prijedloge i automatski popunjava samo sigurnija polja.";
  const connectionStatus = document.createElement("span");
  connectionStatus.className = "document-template-ai-connection-status document-template-runtime-ai-connection";
  syncOpenAiIntegrationStatusTargets(connectionStatus);
  void loadOpenAiIntegrationStatus().then(() => {
    syncOpenAiIntegrationStatusTargets(connectionStatus);
  });
  copy.append(eyebrow, title, description, connectionStatus);
  introHead.append(mark, copy);
  const hideButton = document.createElement("button");
  hideButton.type = "button";
  hideButton.className = "ghost-button compact-button document-template-runtime-ai-hide";
  hideButton.textContent = "Sakrij NexAI";
  hideButton.addEventListener("click", () => {
    setDocumentTemplateRuntimeAiAssistantHidden(true);
  });
  introHead.append(hideButton);
  introHead.addEventListener("click", (event) => {
    if (event.target instanceof HTMLElement && event.target.closest("button, input, select, textarea, a")) {
      return;
    }
    setDocumentTemplateRuntimeAiAssistantHidden(true);
  });
  introHead.addEventListener("keydown", (event) => {
    if (!["Enter", " "].includes(event.key)) {
      return;
    }
    event.preventDefault();
    setDocumentTemplateRuntimeAiAssistantHidden(true);
  });
  intro.append(introHead);

  const uploadWrap = document.createElement("div");
  uploadWrap.className = "document-template-runtime-ai-upload";
  const dropzone = document.createElement("button");
  dropzone.type = "button";
  dropzone.className = "document-template-runtime-ai-dropzone";
  const dropIcon = document.createElement("span");
  dropIcon.className = "document-template-runtime-ai-drop-icon";
  dropIcon.innerHTML = getWorkOrderIconMarkup("download");
  const dropCopy = document.createElement("span");
  dropCopy.className = "document-template-runtime-ai-drop-copy";
  const dropTitle = document.createElement("strong");
  dropTitle.textContent = "Dodaj stari zapisnik";
  const dropMeta = document.createElement("span");
  dropMeta.textContent = "Klikni ili povuci datoteke ovdje.";
  dropCopy.append(dropTitle, dropMeta);
  dropzone.append(dropIcon, dropCopy);

  let dragDepth = 0;
  dropzone.addEventListener("click", () => {
    fileInput.click();
  });
  fileInput.addEventListener("change", () => {
    void addDocumentTemplateRuntimeAiFiles(fileInput.files, template, workOrder);
    fileInput.value = "";
  });
  dropzone.addEventListener("dragenter", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }
    event.preventDefault();
    dragDepth += 1;
    dropzone.classList.add("is-drag-over");
  });
  dropzone.addEventListener("dragover", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }
    event.preventDefault();
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = "copy";
    }
  });
  dropzone.addEventListener("dragleave", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }
    dragDepth = Math.max(0, dragDepth - 1);
    if (dragDepth === 0) {
      dropzone.classList.remove("is-drag-over");
    }
  });
  dropzone.addEventListener("drop", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }
    event.preventDefault();
    dragDepth = 0;
    dropzone.classList.remove("is-drag-over");
    void addDocumentTemplateRuntimeAiFiles(event.dataTransfer?.files, template, workOrder);
  });

  const filesWrap = document.createElement("div");
  filesWrap.className = "document-template-runtime-ai-files";
  if (!assistant.files?.length) {
    const empty = document.createElement("span");
    empty.className = "document-template-runtime-ai-empty";
    empty.textContent = "Nema dodanih datoteka. Za prvi korak dovoljan je stari PDF zapisnik.";
    filesWrap.append(empty);
  } else {
    assistant.files.forEach((file) => {
      const chip = document.createElement("article");
      chip.className = "document-template-runtime-ai-file";
      const fileCopy = document.createElement("span");
      const fileName = document.createElement("strong");
      fileName.textContent = file.name || "Datoteka";
      const fileMeta = document.createElement("small");
      fileMeta.textContent = [
        formatFileSize(file.size),
        file.type || "datoteka",
        file.inlineReady || file.contentDataUrl ? "NexAI sadržaj spreman" : "samo metapodaci",
      ].filter(Boolean).join(" · ");
      fileCopy.append(fileName, fileMeta);
      const removeButton = document.createElement("button");
      removeButton.type = "button";
      removeButton.className = "document-template-runtime-ai-file-remove";
      removeButton.title = "Makni datoteku";
      removeButton.setAttribute("aria-label", `Makni ${file.name || "datoteku"}`);
      removeButton.innerHTML = getWorkOrderIconMarkup("trash");
      removeButton.addEventListener("click", (event) => {
        event.stopPropagation();
        removeDocumentTemplateRuntimeAiFile(file.id || file.name, template, workOrder);
      });
      chip.append(fileCopy, removeButton);
      filesWrap.append(chip);
    });
  }
  uploadWrap.append(fileInput, dropzone, filesWrap);

  const action = document.createElement("div");
  action.className = "document-template-runtime-ai-action";
  const actionTitle = document.createElement("strong");
  actionTitle.textContent = assistant.status === "loading" ? "NexAI priprema..." : "Spremno za provjeru";
  const actionMeta = document.createElement("span");
  actionMeta.textContent = assistant.status === "success"
    ? "Rezultat je vraćen iz NexAI-ja. Provjeri prijedloge prije završnog exporta."
    : "Odaberi snagu modela i pokreni live analizu.";
  const modelPicker = document.createElement("label");
  modelPicker.className = "document-template-runtime-ai-model";
  const modelHeader = document.createElement("span");
  modelHeader.className = "document-template-runtime-ai-model-head";
  const modelTitle = document.createElement("strong");
  modelTitle.textContent = "Snaga NexAI modela";
  const modelStrength = document.createElement("small");
  modelStrength.textContent = modelOption.strength;
  modelHeader.append(modelTitle, modelStrength);
  const modelSelect = document.createElement("select");
  modelSelect.value = modelOption.value;
  DOCUMENT_TEMPLATE_RUNTIME_AI_MODEL_TIERS.forEach((option) => {
    const optionNode = document.createElement("option");
    optionNode.value = option.value;
    optionNode.textContent = `${option.label} - ${option.strength}`;
    modelSelect.append(optionNode);
  });
  const modelDescription = document.createElement("span");
  modelDescription.className = "document-template-runtime-ai-model-copy";
  modelDescription.textContent = modelOption.description;
  modelSelect.addEventListener("change", () => {
    setDocumentTemplateRuntimeAiModelTier(modelSelect.value, template, workOrder);
  });
  modelPicker.append(modelHeader, modelSelect, modelDescription);
  const runButton = document.createElement("button");
  runButton.type = "button";
  runButton.className = "primary-button document-template-runtime-ai-run";
  runButton.disabled = assistant.status === "loading" || !assistant.files?.length;
  const runIcon = document.createElement("span");
  runIcon.className = "document-template-runtime-ai-run-icon";
  runIcon.innerHTML = getWorkOrderIconMarkup("measurement");
  const runLabel = document.createElement("span");
  runLabel.textContent = assistant.status === "loading" ? "Pripremam..." : "Pokreni NexAI";
  runButton.append(runIcon, runLabel);
  runButton.addEventListener("click", () => {
    void runDocumentTemplateRuntimeAiAssistant(template, workOrder);
  });
  const status = document.createElement("p");
  status.className = "document-template-runtime-ai-message";
  status.textContent = assistant.message || "Upload starog zapisnika pa pokreni NexAI pripremu.";
  action.append(actionTitle, actionMeta, modelPicker, runButton, status);

  const suggestionsPanel = createDocumentTemplateRuntimeAiSuggestionsPanel(assistant.lastPlan, template, workOrder);
  panel.append(intro, uploadWrap, action);
  if (suggestionsPanel) {
    panel.append(suggestionsPanel);
  }
  return panel;
}

function closeDocumentTemplateFieldAiWizard({ render = false } = {}) {
  document.querySelector(".document-template-ai-wizard-backdrop")?.remove();
  activeDocumentTemplateAiFieldId = "";
  documentTemplateAiWizardOpen = false;
  if (render) {
    renderDocumentTemplateFieldRows({ renderSupport: false });
  }
}

function createDocumentTemplateAiWizardField(config, definition) {
  const label = document.createElement("label");
  label.className = `document-template-ai-wizard-field ${definition.full ? "is-full" : ""}`;
  const span = document.createElement("span");
  span.textContent = definition.label;

  let control;
  if (definition.kind === "textarea") {
    control = document.createElement("textarea");
    control.rows = definition.rows || 3;
  } else if (definition.kind === "select") {
    control = document.createElement("select");
    replaceSelectOptions(control, definition.options, config[definition.name] ?? definition.defaultValue ?? "");
  } else {
    control = document.createElement("input");
    control.type = definition.kind === "number" ? "number" : "text";
    if (definition.kind === "number") {
      control.min = "0";
      control.max = "9999";
      control.step = "1";
    }
  }

  control.name = definition.name;
  if (definition.placeholder) {
    control.placeholder = definition.placeholder;
  }
  if (definition.kind !== "select") {
    const rawValue = config[definition.name];
    control.value = Array.isArray(rawValue)
      ? rawValue.join(", ")
      : String(rawValue ?? definition.defaultValue ?? "");
  }

  label.append(span, control);
  return label;
}

function collectDocumentTemplateAiWizardConfig(form, field) {
  const read = (name) => String(form.elements[name]?.value || "").trim();
  const readList = (name) => normalizeAiConfigListLocal(read(name), 160);
  return normalizeDocumentTemplateFieldAiConfig({
    key: read("key"),
    label: read("label"),
    description: read("description"),
    type: read("type"),
    required: Boolean(form.elements.required?.checked),
    placeholder: read("placeholder"),
    helpText: read("helpText"),
    enabled: Boolean(form.elements.enabled?.checked),
    aiDescription: read("aiDescription"),
    aiLookFor: readList("aiLookFor"),
    aiAvoid: read("aiAvoid"),
    allowedValues: readList("allowedValues"),
    commonValues: readList("commonValues"),
    examples: readList("examples"),
    format: read("format"),
    unit: read("unit"),
    defaultValue: read("defaultValue"),
    fallbackValue: read("fallbackValue"),
    confidenceRequired: read("confidenceRequired"),
    sourceTracking: Boolean(form.elements.sourceTracking?.checked),
    validationRules: read("validationRules"),
    displayOrder: read("displayOrder"),
    group: read("group"),
  }, field);
}

function openDocumentTemplateFieldAiWizard(fieldId) {
  const normalizedFieldId = String(fieldId || "").trim();
  const fieldIndex = documentTemplateFieldDrafts.findIndex((field) => String(field.id || "") === normalizedFieldId);
  if (fieldIndex < 0) {
    return;
  }

  activeDocumentTemplateAiFieldId = normalizedFieldId;
  documentTemplateAiWizardOpen = true;
  document.querySelector(".document-template-ai-wizard-backdrop")?.remove();

  const field = documentTemplateFieldDrafts[fieldIndex];
  const config = normalizeDocumentTemplateFieldAiConfig(field.ai ?? field.aiConfig, field);
  const backdrop = document.createElement("div");
  backdrop.className = "document-template-ai-wizard-backdrop";
  backdrop.addEventListener("pointerdown", (event) => {
    if (event.target === backdrop) {
      closeDocumentTemplateFieldAiWizard({ render: true });
    }
  });

  const panel = document.createElement("section");
  panel.className = "document-template-ai-wizard";
  panel.setAttribute("role", "dialog");
  panel.setAttribute("aria-modal", "true");
  panel.setAttribute("aria-labelledby", "document-template-ai-wizard-title");
  panel.addEventListener("pointerdown", (event) => event.stopPropagation());

  const head = document.createElement("div");
  head.className = "document-template-ai-wizard-head";
  const copy = document.createElement("div");
  const eyebrow = document.createElement("span");
  eyebrow.className = "document-template-ai-wizard-eyebrow";
  eyebrow.textContent = "NexAI polje";
  const title = document.createElement("strong");
  title.id = "document-template-ai-wizard-title";
  title.textContent = field.label || field.wordLabel || "Postavke NexAI polja";
  const subtitle = document.createElement("p");
  subtitle.textContent = "Ovdje opisuješ što NexAI smije prepoznati iz uploadanih zapisnika, slika ili PDF-ova.";
  const connectionStatus = document.createElement("span");
  connectionStatus.className = "document-template-ai-connection-status";
  connectionStatus.textContent = "NexAI veza: provjeravam...";
  copy.append(eyebrow, title, subtitle, connectionStatus);
  syncOpenAiIntegrationStatusTargets(connectionStatus);
  void loadOpenAiIntegrationStatus().then(() => {
    syncOpenAiIntegrationStatusTargets(connectionStatus);
  });
  const closeButton = createActionButton("Zatvori", "ghost-button", () => closeDocumentTemplateFieldAiWizard({ render: true }));
  head.append(copy, closeButton);

  const form = document.createElement("form");
  form.className = "document-template-ai-wizard-form";
  const enabledLabel = document.createElement("label");
  enabledLabel.className = "document-template-ai-wizard-toggle";
  const enabledInput = document.createElement("input");
  enabledInput.type = "checkbox";
  enabledInput.name = "enabled";
  enabledInput.checked = Boolean(config.enabled);
  const enabledText = document.createElement("span");
  enabledText.textContent = "NexAI smije popuniti ovo polje";
  enabledLabel.append(enabledInput, enabledText);
  form.append(enabledLabel);

  const grid = document.createElement("div");
  grid.className = "document-template-ai-wizard-grid";
  [
    { name: "key", label: "Key", placeholder: "machine_placement" },
    { name: "label", label: "Label", placeholder: "Smještaj stroja" },
    {
      name: "type",
      label: "Tip podatka",
      kind: "select",
      options: [
        { value: "text", label: "Text" },
        { value: "number", label: "Number" },
        { value: "enum", label: "Enum" },
        { value: "date", label: "Date" },
        { value: "list", label: "List" },
        { value: "boolean", label: "Boolean" },
        { value: "measurement", label: "Measurement" },
      ],
    },
    { name: "unit", label: "Jedinica", placeholder: "mm2, A, ohm, lux" },
    { name: "description", label: "Opis polja", kind: "textarea", rows: 3, full: true, placeholder: "Što ovo polje znači u zapisniku." },
    { name: "aiDescription", label: "NexAI opis", kind: "textarea", rows: 3, full: true, placeholder: "Što NexAI treba tražiti u dokumentu ili slici." },
    { name: "aiLookFor", label: "NexAI neka gleda", full: true, placeholder: "prepreke, pristup, stabilnost, prostor oko stroja" },
    { name: "aiAvoid", label: "NexAI ne smije", full: true, placeholder: "Ne zaključuj ako nije vidljivo." },
    { name: "allowedValues", label: "Dopuštene vrijednosti", placeholder: "uredno, neuredno, nije vidljivo" },
    { name: "commonValues", label: "Česte vrijednosti", placeholder: "uredno" },
    { name: "examples", label: "Primjeri", full: true, placeholder: "Smještaj stroja je uredan..." },
    { name: "format", label: "Format", placeholder: "kratka stručna rečenica" },
    { name: "placeholder", label: "Placeholder", placeholder: "Unesite smještaj stroja..." },
    { name: "helpText", label: "Help text", full: true, placeholder: "Opišite pristup, stabilnost i prepreke." },
    { name: "defaultValue", label: "Default value" },
    { name: "fallbackValue", label: "Fallback value", placeholder: "Nije moguće procijeniti." },
    {
      name: "confidenceRequired",
      label: "Minimalna sigurnost",
      kind: "select",
      options: [
        { value: "high", label: "High" },
        { value: "medium", label: "Medium" },
        { value: "low", label: "Low" },
      ],
    },
    { name: "displayOrder", label: "Redoslijed", kind: "number" },
    { name: "group", label: "Grupa", placeholder: "Opći pregled" },
    { name: "validationRules", label: "Validation rules", kind: "textarea", rows: 3, full: true, placeholder: "Ako nije vidljivo, ne smije biti ispravno." },
  ].forEach((definition) => {
    grid.append(createDocumentTemplateAiWizardField(config, definition));
  });
  form.append(grid);

  const checks = document.createElement("div");
  checks.className = "document-template-ai-wizard-checks";
  [
    { name: "required", label: "Polje je obavezno", checked: config.required },
    { name: "sourceTracking", label: "Spremi izvor podatka", checked: config.sourceTracking },
  ].forEach((definition) => {
    const label = document.createElement("label");
    const input = document.createElement("input");
    input.type = "checkbox";
    input.name = definition.name;
    input.checked = Boolean(definition.checked);
    const span = document.createElement("span");
    span.textContent = definition.label;
    label.append(input, span);
    checks.append(label);
  });
  form.append(checks);

  const actions = document.createElement("div");
  actions.className = "document-template-ai-wizard-actions";
  const saveButton = document.createElement("button");
  saveButton.type = "submit";
  saveButton.className = "primary-button";
  saveButton.textContent = "Spremi NexAI postavke";
  const clearButton = createActionButton("Makni NexAI", "ghost-button", () => {
    documentTemplateFieldDrafts[fieldIndex].ai = normalizeDocumentTemplateFieldAiConfig({}, field);
    invalidateDocumentTemplateDraftCache();
    closeDocumentTemplateFieldAiWizard({ render: true });
    setDocumentTemplateMessage("Spremam uklanjanje NexAI postavki...");
    void persistDocumentTemplateAiFieldConfig(normalizedFieldId, documentTemplateFieldDrafts[fieldIndex].ai, {
      successMessage: "NexAI postavke su uklonjene i template je spremljen.",
      scrollToTop: false,
    });
  });
  actions.append(clearButton, saveButton);
  form.append(actions);

  form.addEventListener("submit", (event) => {
    event.preventDefault();
    const nextAiConfig = collectDocumentTemplateAiWizardConfig(form, field);
    documentTemplateFieldDrafts[fieldIndex].ai = nextAiConfig;
    invalidateDocumentTemplateDraftCache();
    closeDocumentTemplateFieldAiWizard({ render: true });
    setDocumentTemplateMessage("Spremam NexAI postavke u template...");
    void persistDocumentTemplateAiFieldConfig(normalizedFieldId, nextAiConfig, {
      successMessage: "NexAI postavke su spremljene i odmah aktivne u izradi zapisnika.",
      scrollToTop: false,
    });
  });

  panel.append(head, form);
  backdrop.append(panel);
  document.body.append(backdrop);
}

function createEmptyDocumentTemplateFieldDraft(initial = {}, index = 0) {
  const fallbackKey = `FIELD_${index + 1}`;
  const type = initial.type || "text";
  const legacyDocumentUploadLabel = /^(tlocrt(\s*\(skica\))?|grafi[cč]ki\s+(prikaz|prilog))$/i;
  const rawLabel = String(initial.label ?? "").trim();
  const rawWordLabel = String(initial.wordLabel ?? "").trim();
  const rawHelpText = String(initial.helpText ?? "").trim();
  const shouldRenameLegacyDocumentUpload = (type === "sketch_upload" || type === "chapter")
    && (legacyDocumentUploadLabel.test(rawLabel) || legacyDocumentUploadLabel.test(rawWordLabel));
  const label = shouldRenameLegacyDocumentUpload
    ? "Dodaj dokumente"
    : (rawLabel || (type === "chapter" ? "Novi blok" : ""));
  const wordLabel = type === "sketch_upload" && legacyDocumentUploadLabel.test(rawWordLabel)
    ? "Dokumenti"
    : (shouldRenameLegacyDocumentUpload ? label : (rawWordLabel || label));
  const defaultColumns = type === "measurement_table"
    ? ["Pozicija", "Opis", "Vrijednost", "Granica", "Napomena"]
    : [];
  const sheet = type === "measurement_table"
    ? ensureDocumentTemplateMeasurementFieldSheet(initial)
    : null;
  const key = normalizeDocumentTemplateFieldKeyDraft(initial.key || wordLabel || label || fallbackKey, fallbackKey);
  const source = String(initial.source ?? initial.bindingSource ?? getDocumentTemplateDefaultFieldSource(type)).trim().toUpperCase();
  const isPeriodicsTrackable = isDocumentTemplatePeriodicsTrackableField({
    ...initial,
    key,
    label,
    wordLabel,
    type,
    source,
  });
  const draft = {
    id: initial.id || crypto.randomUUID(),
    label,
    wordLabel,
    key,
    type,
    required: Boolean(initial.required),
    trackPeriodics: isPeriodicsTrackable ? Boolean(initial.trackPeriodics ?? initial.periodicsTracked) : false,
    layoutWidth: normalizeDocumentTemplateFieldLayoutWidth(initial.layoutWidth, type),
    fieldHeight: normalizeDocumentTemplateFieldHeight(initial.fieldHeight, type),
    htmlStyle: normalizeDocumentTemplateHtmlStyleDraft(initial.htmlStyle),
    source,
    sourceTable: String(initial.sourceTable ?? "").trim().toLowerCase(),
    lookupColumn: String(initial.lookupColumn ?? "").trim().toLowerCase(),
    lookupValueSource: String(initial.lookupValueSource ?? "").trim().toUpperCase() || "WORK_ORDER_NUMBER",
    lookupValue: String(initial.lookupValue ?? "").trim(),
    valueColumn: String(initial.valueColumn ?? "").trim().toLowerCase(),
    previousDocumentMode: String(initial.previousDocumentMode ?? "").trim().toUpperCase() || "NONE",
    defaultValue: String(initial.defaultValue ?? "").trim(),
    helpText: type === "sketch_upload" && (!rawHelpText || /tlocrt|skic/i.test(rawHelpText))
      ? "Kod izrade zapisnika korisnik dodaje dokumente, skice ili priloge klikom ili drag and dropom."
      : rawHelpText,
    textListStyle: isDocumentTemplateTextListStyleField(type)
      ? normalizeDocumentTemplateTextListStyleLocal(initial.textListStyle ?? initial.listStyle)
      : "none",
    ai: normalizeDocumentTemplateFieldAiConfig(initial.ai ?? initial.aiConfig, {
      key: initial.key || wordLabel || label || fallbackKey,
      label,
      type,
      helpText: initial.helpText,
      defaultValue: initial.defaultValue,
    }),
    toggleTrueLabel: String(initial.toggleTrueLabel ?? "").trim(),
    toggleFalseLabel: String(initial.toggleFalseLabel ?? "").trim(),
    toggleTrueText: String(initial.toggleTrueText ?? initial.toggleTrueDetailText ?? "").trim(),
    toggleFalseText: String(initial.toggleFalseText ?? initial.toggleFalseDetailText ?? "").trim(),
    dropdownOptions: type === "dropdown"
      ? normalizeDocumentTemplateDropdownOptionsLocal(initial.dropdownOptions ?? initial.options ?? initial.choices)
      : [],
    sectionSubtitle: String(initial.sectionSubtitle ?? "").trim(),
    systemRows: type === "system_description"
      ? normalizeDocumentTemplateSystemDescriptionRows(
        initial.systemRows ?? initial.rows,
        {
          ensureOne: true,
          fallbackRows: createDefaultDocumentTemplateSystemDescriptionRows(),
        },
      )
      : [],
    signatureArea: String(initial.signatureArea ?? "elektro").trim().toLowerCase() || "elektro",
    signatureRole: normalizeDocumentTemplateSignatureRole(initial.signatureRole ?? (type === "authorization_holder_signature" ? "authorize" : "inspect")),
    signatureMultiple: type === "authorization_holder_signature" || type === "inspector_signature"
      ? false
      : (initial.signatureMultiple !== undefined ? Boolean(initial.signatureMultiple) : true),
    signatureIncludeScan: Boolean(initial.signatureIncludeScan),
    signatureMetaFields: normalizeDocumentTemplateSignatureMetaFieldsLocal(initial.signatureMetaFields),
    legalFrameworkIds: Array.isArray(initial.legalFrameworkIds ?? initial.availableLegalFrameworkIds)
      ? [...new Set((initial.legalFrameworkIds ?? initial.availableLegalFrameworkIds).map((entry) => String(entry || "").trim()).filter(Boolean))]
      : [],
    defaultLegalFrameworkIds: Array.isArray(initial.defaultLegalFrameworkIds ?? initial.preselectedLegalFrameworkIds)
      ? [...new Set((initial.defaultLegalFrameworkIds ?? initial.preselectedLegalFrameworkIds).map((entry) => String(entry || "").trim()).filter(Boolean))]
      : [],
    columns: Array.isArray(initial.columns)
      ? initial.columns.join(", ")
      : String(initial.columns ?? (defaultColumns.length ? defaultColumns.join(", ") : "")).trim(),
    rowCount: String(initial.rowCount ?? (type === "measurement_table" ? 12 : 0)).trim(),
    sheet,
  };
  ensureDocumentTemplateDatabaseLookupDraft(draft);
  return draft;
}

function createEmptyDocumentTemplateEquipmentDraft(initial = {}, index = 0) {
  return {
    id: initial.id || crypto.randomUUID(),
    name: String(initial.name ?? "").trim() || `Oprema ${index + 1}`,
    code: String(initial.code ?? "").trim(),
    quantity: String(initial.quantity ?? 1).trim(),
    note: String(initial.note ?? "").trim(),
  };
}

function createEmptyDocumentTemplateSectionDraft(initial = {}, index = 0) {
  const type = initial.type || "rich_text";
  const defaultColumns = type === "measurement_table"
    ? ["Pozicija", "Opis", "Vrijednost", "Granica", "Napomena"]
    : [];
  const sheet = type === "measurement_table"
    ? ensureDocumentTemplateMeasurementFieldSheet(initial)
    : null;

  return {
    id: initial.id || crypto.randomUUID(),
    type,
    title: String(initial.title ?? "").trim() || getDocumentTemplateSectionTypeLabel(type) || `Sekcija ${index + 1}`,
    body: String(initial.body ?? "").trim(),
    columns: Array.isArray(initial.columns)
      ? initial.columns.join(", ")
      : String(initial.columns ?? (defaultColumns.length ? defaultColumns.join(", ") : "")).trim(),
    rowCount: String(initial.rowCount ?? (type === "measurement_table" ? 12 : 0)).trim(),
    sheet,
  };
}

