function createModuleAttachmentDraft(document = {}) {
  const documentCategory = String(document.documentCategory || document.category || "").trim();
  return {
    id: String(document.id || crypto.randomUUID()),
    fileName: String(document.fileName || "").trim(),
    fileType: String(document.fileType || "").trim(),
    fileSize: Number(document.fileSize || 0) || 0,
    documentCategory,
    sourceDocumentId: String(document.sourceDocumentId || document.parentDocumentId || "").trim(),
    previewStatus: String(document.previewStatus || "").trim(),
    previewError: String(document.previewError || "").trim(),
    documentCategoryLocked: Boolean(document.documentCategoryLocked) || (Boolean(document.isPersisted || document.persisted) && Boolean(documentCategory)),
    description: String(document.description || "").trim(),
    dataUrl: String(document.dataUrl || document.storageUrl || "").trim(),
    storageProvider: String(document.storageProvider || "").trim(),
    storageBucket: String(document.storageBucket || "").trim(),
    storageKey: String(document.storageKey || "").trim(),
    storageUrl: String(document.storageUrl || document.dataUrl || "").trim(),
    createdAt: String(document.createdAt || new Date().toISOString()),
    updatedAt: String(document.updatedAt || document.createdAt || new Date().toISOString()),
  };
}

function normalizeDocumentTemplateMediaFieldValue(value = null) {
  return normalizeDocumentTemplateMediaFieldValues(value)[0] ?? null;
}

function normalizeDocumentTemplateMediaFieldValues(value = null) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    const values = Array.isArray(value) ? value : [];
    return values
      .map((entry) => (entry && typeof entry === "object" ? createModuleAttachmentDraft(entry) : null))
      .filter((draft) => draft?.fileName && (draft.dataUrl || draft.storageUrl));
  }

  const draft = createModuleAttachmentDraft(value);
  return draft.fileName && (draft.dataUrl || draft.storageUrl) ? [draft] : [];
}

function isDocumentTemplateMediaFieldImageValue(value = null) {
  const mediaValue = normalizeDocumentTemplateMediaFieldValue(value);
  if (!mediaValue) {
    return false;
  }

  const fileType = String(mediaValue.fileType || "").trim();
  const fileName = String(mediaValue.fileName || "").trim();
  const url = String(mediaValue.storageUrl || mediaValue.dataUrl || "").trim();
  if (/^image\//i.test(fileType)) {
    return true;
  }
  if (/\.pdf($|\?)/i.test(url) || /application\/pdf/i.test(fileType)) {
    return false;
  }
  return /\.(png|jpe?g|webp|gif|bmp)$/i.test(fileName) || /^data:image\//i.test(url);
}

function getDocumentTemplateMediaFieldSummary(value = null, field = {}) {
  const mediaValue = normalizeDocumentTemplateMediaFieldValue(value);
  if (!mediaValue) {
    return `Nema dodane datoteke za ${getDocumentTemplateMediaFieldKindLabel(field?.type)}.`;
  }

  return [
    mediaValue.fileName,
    mediaValue.fileType || "",
    formatFileSize(mediaValue.fileSize),
  ].filter(Boolean).join(" · ");
}

function getDocumentTemplateMediaFieldPreviewUrl(value = null) {
  const mediaValue = normalizeDocumentTemplateMediaFieldValue(value);
  if (!mediaValue) {
    return "";
  }

  return String(mediaValue.storageUrl || mediaValue.dataUrl || "").trim();
}

async function createDocumentTemplateMediaDraftFromFile(file, field = {}) {
  if (!isDocumentTemplateMediaFileAllowed(field?.type, file)) {
    throw new Error(`${getDocumentTemplateMediaFieldKindLabel(field?.type)} prihvaća samo ${getDocumentTemplateMediaFieldAllowedLabel(field?.type)}.`);
  }

  const dataUrl = await readFileAsDataUrl(file, "Ne mogu učitati datoteku.");
  return createModuleAttachmentDraft({
    fileName: file.name,
    fileType: file.type || "application/octet-stream",
    fileSize: file.size || 0,
    documentCategory: getDocumentTemplateMediaFieldKindLabel(field?.type),
    dataUrl,
    updatedAt: new Date().toISOString(),
  });
}

function getUserElectricalQualification(user = {}, signatureArea = "elektro") {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const rootQualification = user?.electricalQualification ?? {};
  const qualification = normalizedArea === "elektro"
    ? rootQualification
    : rootQualification?.additionalAreas?.[normalizedArea] ?? {};
  const inheritedSignatureDataUrl = String(
    rootQualification.signatureDataUrl
    || rootQualification.signatureStorageUrl
    || rootQualification.storageUrl
    || "",
  ).trim();
  const serviceIds = getQualificationServiceIdsForArea(normalizedArea, qualification, {
    organizationId: user?.organizationId || state.activeOrganizationId || "",
  });
  return {
    discipline: String(qualification.discipline || normalizedArea || "elektro").trim().toLowerCase() || "elektro",
    examTitle: String(qualification.examTitle || qualification.title || "").trim(),
    type: String(qualification.examType || qualification.type || qualification.equipmentType || qualification.kind || "").trim(),
    examType: String(qualification.examType || qualification.type || qualification.equipmentType || qualification.kind || "").trim(),
    canInspect: Boolean(qualification.canInspect),
    canAuthorize: Boolean(qualification.canAuthorize),
    canResponsible: Boolean(qualification.canResponsible || qualification.canBeResponsible),
    data1: String(qualification.data1 || qualification.classCode || "").trim(),
    data2: String(qualification.data2 || qualification.urbroj || "").trim(),
    data3: String(qualification.data3 || qualification.eBroj || "").trim(),
    classCode: String(qualification.data1 || qualification.classCode || "").trim(),
    urbroj: String(qualification.data2 || qualification.urbroj || "").trim(),
    eBroj: String(qualification.data3 || qualification.eBroj || "").trim(),
    passedOn: String(qualification.passedOn || qualification.examDate || "").trim(),
    validUntil: String(qualification.validUntil || "").trim(),
    validForever: Boolean(qualification.validForever),
    specialRoles: normalizeQualificationSpecialRoles(qualification.specialRoles),
    serviceIds,
    linkedServiceCatalogIds: serviceIds,
    linkedServiceCatalogTitles: getServiceCatalogTitlesByIds(serviceIds, {
      organizationId: user?.organizationId || state.activeOrganizationId || "",
    }),
    signatureDataUrl: String(
      qualification.signatureDataUrl
      || qualification.signatureStorageUrl
      || inheritedSignatureDataUrl
      || qualification.storageUrl
      || "",
    ).trim(),
    signatureStorageProvider: String(qualification.signatureStorageProvider || "").trim(),
    signatureStorageBucket: String(qualification.signatureStorageBucket || "").trim(),
    signatureStorageKey: String(qualification.signatureStorageKey || "").trim(),
    signatureStorageUrl: String(qualification.signatureStorageUrl || "").trim(),
    documents: Array.isArray(qualification.documents) ? qualification.documents : [],
  };
}

function getUserQualificationAreaDefinitions(user = null) {
  const definitions = new Map(getQualificationExamDefinitions().map((definition) => [definition.key, definition]));
  Object.keys(user?.electricalQualification?.additionalAreas || {}).forEach((area) => {
    const key = normalizeQualificationAreaKey(area);
    if (!key || definitions.has(key)) {
      return;
    }
    definitions.set(key, {
      key,
      title: getSignatureAreaLabel(key),
      label: getSignatureAreaLabel(key),
      specialRoleOptions: [],
    });
  });
  return Array.from(definitions.values());
}

function getUserQualificationInput(area = "", field = "") {
  if (!userQualificationAreasContainer) {
    return null;
  }
  const areaKey = normalizeQualificationAreaKey(area);
  return userQualificationAreasContainer.querySelector(
    `[data-user-qualification-area="${CSS.escape(areaKey)}"] [data-user-qualification-field="${CSS.escape(field)}"]`,
  );
}

function getUserQualificationSpecialRoleInputs(area = "") {
  if (!userQualificationAreasContainer) {
    return [];
  }
  const areaKey = normalizeQualificationAreaKey(area);
  return Array.from(userQualificationAreasContainer.querySelectorAll(
    `[data-user-qualification-area="${CSS.escape(areaKey)}"] [data-user-qualification-special-role]`,
  ));
}

function getUserQualificationServiceInputs(area = "") {
  if (!userQualificationAreasContainer) {
    return [];
  }
  const areaKey = normalizeQualificationAreaKey(area);
  return Array.from(userQualificationAreasContainer.querySelectorAll(
    `[data-user-qualification-area="${CSS.escape(areaKey)}"] [data-user-qualification-service-id]`,
  ));
}

function readUserQualificationAreaPayload(definition = {}) {
  const area = normalizeQualificationAreaKey(definition.key || "elektro");
  const validForever = Boolean(getUserQualificationInput(area, "validForever")?.checked);
  const currentRecord = getCurrentUserEditorRecord() || {};
  const currentRootQualification = currentRecord?.electricalQualification ?? {};
  const currentQualification = area === "elektro"
    ? currentRootQualification
    : currentRootQualification?.additionalAreas?.[area] ?? {};
  const existingServiceIds = getQualificationLinkedServiceIds(currentQualification);
  const specialRoles = Object.fromEntries(
    getUserQualificationSpecialRoleInputs(area).map((input) => [
      String(input.dataset.userQualificationSpecialRole || "").trim(),
      Boolean(input.checked),
    ]).filter(([key]) => key),
  );
  const specialRoleOptions = Array.isArray(definition.specialRoleOptions) ? definition.specialRoleOptions : [];
  const hasSpecialCapability = (capability) => specialRoleOptions.some((option) => (
    option.capability === capability && specialRoles[option.key]
  ));
  const examType = String(getUserQualificationInput(area, "type")?.value || "").trim();
  const data1 = String(getUserQualificationInput(area, "data1")?.value || "").trim();
  const data2 = String(getUserQualificationInput(area, "data2")?.value || "").trim();
  const data3 = String(getUserQualificationInput(area, "data3")?.value || "").trim();
  return {
    discipline: area,
    examTitle: String(definition.title || definition.label || area).trim(),
    type: examType,
    examType,
    canInspect: Boolean(getUserQualificationInput(area, "canInspect")?.checked || hasSpecialCapability("inspect")),
    canAuthorize: Boolean(getUserQualificationInput(area, "canAuthorize")?.checked || hasSpecialCapability("authorize")),
    canResponsible: Boolean(getUserQualificationInput(area, "canResponsible")?.checked || hasSpecialCapability("responsible")),
    data1,
    data2,
    data3,
    classCode: data1,
    urbroj: data2,
    eBroj: data3,
    passedOn: normalizePeopleTrainingDate(getUserQualificationInput(area, "passedOn")?.value || ""),
    validUntil: validForever ? "" : normalizePeopleTrainingDate(getUserQualificationInput(area, "validUntil")?.value || ""),
    validForever,
    specialRoles,
    serviceIds: existingServiceIds,
    linkedServiceCatalogIds: existingServiceIds,
  };
}

function createUserQualificationField(labelText = "", control, fieldName = "") {
  const field = document.createElement("label");
  field.className = "field";
  if (fieldName) {
    field.classList.add(`user-qualification-field-${fieldName}`);
  }
  const label = document.createElement("span");
  label.textContent = labelText;
  if (fieldName) {
    control.dataset.userQualificationField = fieldName;
  }
  field.append(label, control);
  return field;
}

function createUserQualificationCheckbox(labelText = "", checked = false, fieldName = "") {
  const label = document.createElement("label");
  label.className = "checkbox-field user-qualification-checkbox";
  const input = document.createElement("input");
  input.type = "checkbox";
  input.checked = Boolean(checked);
  if (fieldName) {
    input.dataset.userQualificationField = fieldName;
  }
  const copy = document.createElement("span");
  copy.textContent = labelText;
  label.append(input, copy);
  return label;
}

function createUserQualificationDateInput(value = "") {
  const input = document.createElement("input");
  input.type = "text";
  input.inputMode = "numeric";
  input.maxLength = 10;
  input.placeholder = "dd.mm.yyyy";
  input.value = formatDateInputDisplayValue(normalizePeopleTrainingDate(value));
  input.addEventListener("input", () => {
    input.value = normalizeLiveDateTypingValue(input.value);
  });
  input.addEventListener("blur", () => {
    const normalizedValue = normalizePeopleTrainingDate(input.value);
    input.value = normalizedValue ? formatDateInputDisplayValue(normalizedValue) : String(input.value || "").trim();
  });
  return input;
}

function renderUserQualificationAreas(user = getCurrentUserEditorRecord() || {}) {
  if (!userQualificationAreasContainer) {
    return;
  }

  const definitions = getUserQualificationAreaDefinitions(user);
  if (definitions.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Nema definiranih ispita. Dodaj novi ispit u People pa će se nuditi i na drugim osobama.";
    userQualificationAreasContainer.replaceChildren(empty);
    return;
  }

  userQualificationAreasContainer.replaceChildren(...definitions.map((definition) => {
    const area = normalizeQualificationAreaKey(definition.key);
    const qualification = getUserElectricalQualification(user, area);
    const block = document.createElement("section");
    block.className = "service-catalog-template-block user-editor-module user-electrical-qualification-block";
    block.dataset.userManagementScope = "people";
    block.dataset.userQualificationArea = area;

    const heading = document.createElement("div");
    heading.className = "section-heading offers-section-heading";
    const headingCopy = document.createElement("div");
    const kicker = document.createElement("p");
    kicker.className = "section-kicker";
    kicker.textContent = definition.defaultExam ? "Default ispit" : "Ispit";
    const title = document.createElement("h3");
    title.textContent = definition.title || definition.label || area;
    headingCopy.append(kicker, title);
    heading.append(headingCopy);

    const grid = document.createElement("div");
    grid.className = "form-grid user-electrical-grid";

    const typeInput = document.createElement("input");
    typeInput.type = "text";
    typeInput.maxLength = 160;
    typeInput.value = qualification.type || "";
    typeInput.placeholder = "npr. Opći ispit iz zaštite na radu";
    const data1Input = document.createElement("input");
    data1Input.type = "text";
    data1Input.maxLength = 160;
    data1Input.value = qualification.data1 || "";
    const data2Input = document.createElement("input");
    data2Input.type = "text";
    data2Input.maxLength = 160;
    data2Input.value = qualification.data2 || "";
    const data3Input = document.createElement("input");
    data3Input.type = "text";
    data3Input.maxLength = 160;
    data3Input.value = qualification.data3 || "";
    const passedOnInput = createUserQualificationDateInput(qualification.passedOn);
    const validUntilInput = createUserQualificationDateInput(qualification.validUntil);
    const validForeverInput = document.createElement("input");
    validForeverInput.type = "checkbox";
    validForeverInput.checked = Boolean(qualification.validForever);

    const validForeverField = document.createElement("div");
    validForeverField.className = "field qualification-validity-field";
    const validForeverLabel = document.createElement("span");
    validForeverLabel.textContent = "Vrijedi trajno";
    const checkboxLabel = document.createElement("label");
    checkboxLabel.className = "checkbox-field";
    const checkboxCopy = document.createElement("span");
    checkboxCopy.textContent = "Bez isteka";
    validForeverInput.dataset.userQualificationField = "validForever";
    checkboxLabel.append(validForeverInput, checkboxCopy);
    validForeverField.append(validForeverLabel, checkboxLabel);

    validForeverInput.addEventListener("change", () => {
      syncQualificationValidityInput(validUntilInput, validForeverInput);
    });

    const genericRoles = document.createElement("div");
    genericRoles.className = "field field-span-full user-qualification-role-group";
    const genericRoleLabel = document.createElement("span");
    genericRoleLabel.textContent = "Razina osobe";
    const genericRoleOptions = document.createElement("div");
    genericRoleOptions.className = "user-qualification-role-options";
    genericRoleOptions.append(
      createUserQualificationCheckbox("Ispitivač", qualification.canInspect, "canInspect"),
      createUserQualificationCheckbox("Ovlaštena osoba", qualification.canAuthorize, "canAuthorize"),
      createUserQualificationCheckbox("Odgovorna osoba", qualification.canResponsible, "canResponsible"),
    );
    genericRoles.append(genericRoleLabel, genericRoleOptions);

    const specialRoleOptions = Array.isArray(definition.specialRoleOptions) ? definition.specialRoleOptions : [];
    if (specialRoleOptions.length > 0) {
      block.classList.add("has-special-roles");
    }
    const specialRoles = normalizeQualificationSpecialRoles(qualification.specialRoles);
    const specialRoleField = document.createElement("div");
    specialRoleField.className = "field field-span-full user-qualification-role-group is-special";
    const specialRoleLabel = document.createElement("span");
    specialRoleLabel.textContent = "Dodatne razine";
    const specialRoleOptionWrap = document.createElement("div");
    specialRoleOptionWrap.className = "user-qualification-role-options";
    specialRoleOptions.forEach((option) => {
      const optionLabel = createUserQualificationCheckbox(option.label, specialRoles[option.key], "");
      const input = optionLabel.querySelector("input");
      if (input) {
        input.dataset.userQualificationSpecialRole = option.key;
      }
      specialRoleOptionWrap.append(optionLabel);
    });
    specialRoleField.append(specialRoleLabel, specialRoleOptionWrap);

    grid.append(
      genericRoles,
      ...(specialRoleOptions.length > 0 ? [specialRoleField] : []),
      createUserQualificationField("Vrsta ispita", typeInput, "type"),
      createUserQualificationField("Podatak 1", data1Input, "data1"),
      createUserQualificationField("Podatak 2", data2Input, "data2"),
      createUserQualificationField("Podatak 3", data3Input, "data3"),
      createUserQualificationField("Datum polaganja", passedOnInput, "passedOn"),
      createUserQualificationField("Vrijedi do", validUntilInput, "validUntil"),
      validForeverField,
    );

    block.append(heading, grid);
    syncQualificationValidityInput(validUntilInput, validForeverInput);
    return block;
  }));
}

function buildUserElectricalQualificationPayload() {
  const currentRecord = getCurrentUserEditorRecord();
  const definitions = getUserQualificationAreaDefinitions(currentRecord || {});
  const renderedAreas = new Set(definitions.map((definition) => normalizeQualificationAreaKey(definition.key)));
  const rootDefinition = definitions.find((definition) => normalizeQualificationAreaKey(definition.key) === "elektro");
  const currentRoot = getUserElectricalQualification(currentRecord || {}, "elektro");
  const root = {
    ...(rootDefinition ? readUserQualificationAreaPayload(rootDefinition) : currentRoot),
    discipline: "elektro",
    signatureDataUrl: userElectricalSignatureDataUrlInput?.value || "",
    documents: [],
    additionalAreas: {},
  };

  definitions
    .filter((definition) => normalizeQualificationAreaKey(definition.key) !== "elektro")
    .forEach((definition) => {
      const area = normalizeQualificationAreaKey(definition.key);
      root.additionalAreas[area] = readUserQualificationAreaPayload(definition);
    });

  Object.entries(currentRecord?.electricalQualification?.additionalAreas || {}).forEach(([area, value]) => {
    const normalizedArea = normalizeQualificationAreaKey(area);
    if (!normalizedArea || renderedAreas.has(normalizedArea)) {
      return;
    }
    root.additionalAreas[normalizedArea] = value;
  });

  return root;
}

function getQualifiedUsersForSignatureArea(capability = "inspect", signatureArea = "elektro") {
  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  return (state.users ?? [])
    .filter((user) => Boolean(user?.isActive))
    .filter((user) => {
      const qualification = getUserElectricalQualification(user, normalizedArea);
      if (qualification.discipline !== normalizedArea) {
        return false;
      }

      return normalizedCapability === "authorize"
        ? qualification.canAuthorize
        : qualification.canInspect;
    })
    .sort((left, right) => String(left.fullName || left.email || "").localeCompare(
      String(right.fullName || right.email || ""),
      "hr",
    ));
}

function getQualifiedUserSelectLabel(user = {}, capability = "inspect", signatureArea = "elektro") {
  const qualification = getUserElectricalQualification(user, signatureArea);
  const summaryParts = [
    qualification.type ? `Vrsta ispita ${qualification.type}` : "",
    qualification.data1 ? `Podatak 1 ${qualification.data1}` : "",
    qualification.data2 ? `Podatak 2 ${qualification.data2}` : "",
    qualification.data3 ? `Podatak 3 ${qualification.data3}` : "",
    qualification.passedOn ? `Položeno ${formatCompactDate(qualification.passedOn)}` : "",
  ].filter(Boolean);
  const roleLabel = capability === "authorize" ? "nositelj" : "ispitivač";
  const areaLabel = getSignatureAreaLabel(signatureArea);
  const fallback = `${roleLabel} · ${areaLabel}`;
  return [
    String(user.fullName || user.email || fallback).trim(),
    summaryParts.join(" · "),
  ].filter(Boolean).join(" | ");
}

function getQualifiedUserSelectOptions(capability = "inspect", signatureArea = "elektro") {
  const emptyLabel = capability === "authorize"
    ? "Odaberi nositelja"
    : "Odaberi ispitivača";
  return [
    { value: "", label: emptyLabel },
    ...getQualifiedUsersForSignatureArea(capability, signatureArea).map((user) => ({
      value: String(user.id),
      label: getQualifiedUserSelectLabel(user, capability, signatureArea),
    })),
  ];
}

function getQualifiedUserOptionsForSignatureAreas(
  capability = "inspect",
  signatureAreas = [],
  { includeEmpty = false, emptyLabel = "" } = {},
) {
  const normalizedAreas = Array.from(new Set(
    (Array.isArray(signatureAreas) ? signatureAreas : [signatureAreas])
      .map((area) => normalizeQualificationAreaKey(area))
      .filter(Boolean),
  ));
  const areas = normalizedAreas.length > 0 ? normalizedAreas : ["elektro"];
  const merged = new Map();

  areas.forEach((area) => {
    getQualifiedUsersForSignatureArea(capability, area).forEach((user) => {
      const key = String(user.id);
      const existing = merged.get(key) ?? {
        user,
        areas: new Set(),
      };
      existing.areas.add(area);
      merged.set(key, existing);
    });
  });

  const options = [...merged.values()]
    .sort((left, right) => String(left.user.fullName || left.user.email || "").localeCompare(
      String(right.user.fullName || right.user.email || ""),
      "hr",
    ))
    .map(({ user, areas: userAreas }) => {
      const labels = [...userAreas].map((area) => getSignatureAreaLabel(area));
      return {
        value: String(user.id),
        label: [
          String(user.fullName || user.email || "").trim(),
          labels.join(", "),
        ].filter(Boolean).join(" | "),
      };
    });

  if (!includeEmpty) {
    return options;
  }

  return [
    { value: "", label: emptyLabel || (capability === "authorize" ? "Odaberi nositelja" : "Odaberi ispitivača") },
    ...options,
  ];
}

function findQualifiedUserById(userId = "", capability = "inspect", signatureArea = "elektro") {
  const normalizedId = String(userId || "").trim();
  if (!normalizedId) {
    return null;
  }

  return getQualifiedUsersForSignatureArea(capability, signatureArea)
    .find((user) => String(user.id) === normalizedId) || null;
}

function getQualifiedUserSummaryValue(user = null, capability = "inspect", signatureArea = "elektro") {
  if (!user) {
    const roleLabel = capability === "authorize" ? "Nositelj ovlaštenja" : "Ispitivač";
    return `${roleLabel} (${getSignatureAreaLabel(signatureArea)})`;
  }

  const qualification = getUserElectricalQualification(user, signatureArea);
  return [
    getUserDocumentDisplayName(user),
    qualification.type ? `Vrsta ispita ${qualification.type}` : "",
    qualification.data1 ? `Podatak 1 ${qualification.data1}` : "",
    qualification.data2 ? `Podatak 2 ${qualification.data2}` : "",
    qualification.data3 ? `Podatak 3 ${qualification.data3}` : "",
    qualification.passedOn ? `Položeno ${formatCompactDate(qualification.passedOn)}` : "",
  ].filter(Boolean).join(" | ");
}

function getQualifiedUserDocumentMetaLines(
  user = null,
  capability = "inspect",
  signatureArea = "elektro",
  metaFields = undefined,
) {
  if (!user) {
    return [];
  }

  const qualification = getUserElectricalQualification(user, signatureArea);
  const visibleFields = new Set(normalizeDocumentTemplateSignatureMetaFieldsLocal(metaFields));
  return [
    visibleFields.has("title") && user.title ? String(user.title).trim() : "",
    visibleFields.has("oib") && user.oib ? `OIB ${String(user.oib).trim()}` : "",
    visibleFields.has("type") && qualification.type ? String(qualification.type).trim() : "",
    (visibleFields.has("data1") || visibleFields.has("classCode")) && qualification.data1 ? String(qualification.data1).trim() : "",
    (visibleFields.has("data2") || visibleFields.has("urbroj")) && qualification.data2 ? String(qualification.data2).trim() : "",
    (visibleFields.has("data3") || visibleFields.has("eBroj")) && qualification.data3 ? String(qualification.data3).trim() : "",
    visibleFields.has("passedOn") && qualification.passedOn ? formatCompactDate(qualification.passedOn) : "",
  ].filter(Boolean);
}

function normalizeQualifiedUserIdList(values = []) {
  const source = Array.isArray(values)
    ? values
    : String(values || "")
      .split(",")
      .map((value) => value.trim())
      .filter(Boolean);

  return Array.from(new Set(source.map((value) => String(value || "").trim()).filter(Boolean)));
}

function getQualifiedUsersByIds(userIds = [], capability = "inspect", signatureArea = "elektro") {
  const normalizedIds = normalizeQualifiedUserIdList(userIds);
  if (normalizedIds.length === 0) {
    return [];
  }

  const eligibleUsers = new Map(
    getQualifiedUsersForSignatureArea(capability, signatureArea)
      .map((user) => [String(user.id), user]),
  );

  return normalizedIds
    .map((id) => eligibleUsers.get(String(id)) || null)
    .filter(Boolean);
}

function resolveQualifiedWorkOrderUsers(workOrder = {}, capability = "inspect", signatureArea = "elektro") {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const executorNames = getWorkOrderExecutors(workOrder).map((entry) => normalizePersonLookupValue(entry)).filter(Boolean);
  const eligibleUsers = getQualifiedUsersForSignatureArea(capability, normalizedArea);

  return eligibleUsers.filter((user) => (
    [
      getUserDocumentDisplayName(user),
      user.fullName,
      [user.firstName, user.lastName].filter(Boolean).join(" "),
      user.email,
      user.legacyUsername,
    ].map((value) => normalizePersonLookupValue(value)).filter(Boolean)
      .some((candidate) => executorNames.includes(candidate))
  ));
}

function getWorkOrderDocumentQualifiedUsers(workOrder = {}, capability = "inspect", signatureArea = "elektro") {
  const areaSpecificListFieldName = getWorkOrderDocumentSignaturePersonListFieldName(capability, signatureArea);
  const areaSpecificUsers = getQualifiedUsersByIds(
    workOrder?.id && areaSpecificListFieldName
      ? getDocumentTemplateRuntimeArrayValue(workOrder.id, areaSpecificListFieldName)
      : [],
    capability,
    signatureArea,
  );

  if (areaSpecificUsers.length > 0) {
    return areaSpecificUsers;
  }

  const listFieldName = capability === "authorize" ? "authorizationHolderUserIds" : "inspectorUserIds";
  const explicitUsers = getQualifiedUsersByIds(
    workOrder?.id ? getDocumentTemplateRuntimeArrayValue(workOrder.id, listFieldName) : [],
    capability,
    signatureArea,
  );

  if (explicitUsers.length > 0) {
    return explicitUsers;
  }

  const areaSpecificFieldName = getWorkOrderDocumentSignaturePersonFieldName(capability, signatureArea);
  const areaSpecificUserId = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, areaSpecificFieldName) : "";
  const areaSpecificUser = findQualifiedUserById(areaSpecificUserId, capability, signatureArea);
  if (areaSpecificUser) {
    return [areaSpecificUser];
  }

  const singleFieldName = capability === "authorize" ? "authorizationHolderUserId" : "inspectorUserId";
  const explicitSingleUserId = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, singleFieldName) : "";
  const explicitSingleUser = findQualifiedUserById(explicitSingleUserId, capability, signatureArea);
  if (explicitSingleUser) {
    return [explicitSingleUser];
  }

  return resolveQualifiedWorkOrderUsers(workOrder, capability, signatureArea);
}

function getWorkOrderDocumentQualifiedUser(workOrder = {}, capability = "inspect", signatureArea = "elektro") {
  return getWorkOrderDocumentQualifiedUsers(workOrder, capability, signatureArea)[0]
    || resolveQualifiedWorkOrderUser(workOrder, capability, signatureArea);
}

function getWorkOrderDocumentWizardRelevantAreasForWorkOrder(workOrder = {}) {
  const resolvedServiceItems = getWorkOrderDocumentWizardResolvedServiceItems(workOrder);
  return getWorkOrderRelevantSignatureAreas({
    ...workOrder,
    serviceItems: resolvedServiceItems,
  });
}

function getWorkOrderDocumentWizardRelevantAreasForBatch(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  const areas = new Set();
  (Array.isArray(workOrders) ? workOrders : []).forEach((workOrder) => {
    getWorkOrderDocumentWizardRelevantAreasForWorkOrder(workOrder).forEach((area) => areas.add(area));
  });
  return areas.size > 0 ? [...areas] : ["elektro"];
}

function getWorkOrderDocumentSignatureAreaGroupsForAreas(areas = []) {
  const normalizedAreas = Array.from(new Set(
    (Array.isArray(areas) ? areas : [areas])
      .map((area) => normalizeQualificationAreaKey(area))
      .filter(Boolean),
  ));
  const areaList = normalizedAreas.length > 0 ? normalizedAreas : ["elektro"];
  const areaGroups = getWorkOrderDocumentSignatureAreaGroups();
  return areaList.map((area) => (
    areaGroups.find((group) => group.key === area) || {
      key: area,
      title: getSignatureAreaLabel(area),
    }
  ));
}

function findPreferredWorkOrderDocumentWizardPerson(
  workOrder = {},
  capability = "inspect",
  signatureArea = "elektro",
  fallbackIds = [],
  { allowFirstQualifiedFallback = true } = {},
) {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const executorMatch = resolveQualifiedWorkOrderUsers(workOrder, capability, normalizedArea)[0] || null;
  if (executorMatch) {
    return executorMatch;
  }

  const fallbackMatch = normalizeQualifiedUserIdList(fallbackIds)
    .map((userId) => findQualifiedUserById(userId, capability, normalizedArea))
    .find(Boolean);
  if (fallbackMatch) {
    return fallbackMatch;
  }

  return allowFirstQualifiedFallback
    ? getQualifiedUsersForSignatureArea(capability, normalizedArea)[0] || null
    : null;
}

function buildWorkOrderDocumentWizardPersonDefaults(workOrder = {}, signatureArea = "elektro") {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const inspectorFieldName = getWorkOrderDocumentSignaturePersonFieldName("inspect", normalizedArea);
  const inspectorListFieldName = getWorkOrderDocumentSignaturePersonListFieldName("inspect", normalizedArea);
  const authorizationFieldName = getWorkOrderDocumentSignaturePersonFieldName("authorize", normalizedArea);
  const inspectorUsers = resolveQualifiedWorkOrderUsers(workOrder, "inspect", normalizedArea);
  const inspectorIds = normalizeQualifiedUserIdList(inspectorUsers.map((user) => user.id));
  const authorizationUser = findPreferredWorkOrderDocumentWizardPerson(
    workOrder,
    "authorize",
    normalizedArea,
    inspectorIds,
    { allowFirstQualifiedFallback: false },
  );
  const patch = {};

  if (inspectorIds.length > 0) {
    if (inspectorListFieldName) {
      patch[inspectorListFieldName] = inspectorIds;
    }
    patch[inspectorFieldName] = inspectorIds[0];
  }

  if (authorizationUser?.id) {
    patch[authorizationFieldName] = String(authorizationUser.id);
  }

  return patch;
}

function ensureWorkOrderDocumentWizardPersonDefaults(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  const selectedWorkOrders = Array.isArray(workOrders) ? workOrders : [];
  if (selectedWorkOrders.length === 0 || state.workOrderDocumentWizard.mode === "znr") {
    return;
  }

  const commonPatch = {};
  getWorkOrderDocumentWizardRelevantAreasForBatch(selectedWorkOrders).forEach((area) => {
    const normalizedArea = normalizeQualificationAreaKey(area);
    const inspectorFieldName = getWorkOrderDocumentSignaturePersonFieldName("inspect", normalizedArea);
    const inspectorListFieldName = getWorkOrderDocumentSignaturePersonListFieldName("inspect", normalizedArea);
    const authorizationFieldName = getWorkOrderDocumentSignaturePersonFieldName("authorize", normalizedArea);
    const commonInspectorIds = inspectorListFieldName
      ? normalizeQualifiedUserIdList(state.workOrderDocumentWizard.common?.[inspectorListFieldName] ?? [])
      : normalizeQualifiedUserIdList([state.workOrderDocumentWizard.common?.[inspectorFieldName] ?? ""]);
    const executorInspectorIds = normalizeQualifiedUserIdList(
      selectedWorkOrders.flatMap((workOrder) => (
        resolveQualifiedWorkOrderUsers(workOrder, "inspect", normalizedArea).map((user) => user.id)
      )),
    );

    if (commonInspectorIds.length === 0 && executorInspectorIds.length > 0) {
      if (inspectorListFieldName) {
        commonPatch[inspectorListFieldName] = executorInspectorIds;
      }
      commonPatch[inspectorFieldName] = executorInspectorIds[0];
    }

    if (!String(state.workOrderDocumentWizard.common?.[authorizationFieldName] ?? "").trim()) {
      const authorizationUser = selectedWorkOrders
        .map((workOrder) => findPreferredWorkOrderDocumentWizardPerson(
          workOrder,
          "authorize",
          normalizedArea,
          executorInspectorIds,
          { allowFirstQualifiedFallback: false },
        ))
        .find(Boolean);
      if (authorizationUser?.id) {
        commonPatch[authorizationFieldName] = String(authorizationUser.id);
      }
    }
  });

  if (Object.keys(commonPatch).length > 0) {
    state.workOrderDocumentWizard.common = {
      ...state.workOrderDocumentWizard.common,
      ...commonPatch,
    };
  }

  selectedWorkOrders.forEach((workOrder) => {
    const override = getWorkOrderDocumentWizardOverride(workOrder.id);
    const patch = {};
    getWorkOrderDocumentWizardRelevantAreasForWorkOrder(workOrder).forEach((area) => {
      const defaults = buildWorkOrderDocumentWizardPersonDefaults(workOrder, area);
      Object.entries(defaults).forEach(([fieldName, value]) => {
        if (Object.prototype.hasOwnProperty.call(override, fieldName)) {
          return;
        }
        if (Array.isArray(value)) {
          if (value.length > 0) {
            patch[fieldName] = value;
          }
          return;
        }
        if (String(value || "").trim()) {
          patch[fieldName] = String(value || "").trim();
        }
      });
    });

    if (Object.keys(patch).length > 0) {
      setWorkOrderDocumentWizardOverride(workOrder.id, patch);
    }
  });
}

function getDocumentTemplateRuntimeResolvedServiceItems(workOrder = {}) {
  const normalizedId = String(workOrder?.id || "").trim();
  const record = normalizedId ? getDocumentTemplateRuntimeOverrideRecord(normalizedId) : null;
  if (record && Object.prototype.hasOwnProperty.call(record, "serviceItems")) {
    return getWorkOrderServiceItems({ serviceItems: record.serviceItems });
  }
  return getWorkOrderServiceItems(workOrder);
}

function getDocumentTemplateRuntimeResolvedServiceEntries(workOrder = {}) {
  const workOrderId = String(workOrder?.id || "").trim();
  return getDocumentTemplateRuntimeResolvedServiceItems(workOrder)
    .map((service, index) => ({
      service,
      index,
      key: getDocumentTemplateRuntimeServiceItemKey(service, index),
      included: isDocumentTemplateRuntimeServiceItemIncluded(workOrderId, service, index),
    }));
}

function getDocumentTemplateRuntimeIncludedServiceEntries(workOrder = {}) {
  return getDocumentTemplateRuntimeResolvedServiceEntries(workOrder)
    .filter((entry) => entry.included);
}

function getDocumentTemplateRuntimeIncludedServiceItems(workOrder = {}) {
  return getDocumentTemplateRuntimeIncludedServiceEntries(workOrder)
    .map((entry) => entry.service);
}

function setDocumentTemplateRuntimeServiceItemCompleted(workOrderId = "", serviceIndex = -1, isCompleted = false, { render = true } = {}) {
  setDocumentTemplateRuntimeServiceItemStatus(workOrderId, serviceIndex, isCompleted ? "completed" : "pending", { render });
}

function setDocumentTemplateRuntimeServiceItemStatus(workOrderId = "", serviceIndex = -1, status = "pending", { render = true } = {}) {
  const normalizedId = String(workOrderId || "").trim();
  const workOrder = getDocumentTemplateRuntimeWorkOrderById(normalizedId);
  if (!normalizedId || !workOrder) {
    return;
  }

  const currentItems = getDocumentTemplateRuntimeResolvedServiceItems(workOrder);
  if (serviceIndex < 0 || serviceIndex >= currentItems.length) {
    return;
  }

  const nextItems = currentItems.map((item, index) => (
    index === serviceIndex
      ? withWorkOrderServiceProgressStatus(item, status)
      : item
  ));

  updateDocumentTemplateRuntimeOverride(normalizedId, { serviceItems: nextItems }, { render: false });
  clearDocumentTemplateRuntimeExportStatusesForWorkOrder(normalizedId);

  if (render) {
    syncDocumentTemplateEditorChrome();
    renderDocumentTemplateRuntimeContext();
    renderDocumentTemplateFieldRows();
    renderDocumentTemplatePreviewContent();
  }
}

function buildDocumentTemplateRuntimeServiceProgressPatch(workOrder = {}, template = null, status = "in_progress") {
  const workOrderId = String(workOrder?.id || "").trim();
  const currentItems = getDocumentTemplateRuntimeResolvedServiceItems(workOrder);
  if (!workOrderId || currentItems.length === 0) {
    return null;
  }

  const normalizedTemplateId = getDocumentTemplateRuntimeTemplateId(template);
  const normalizedTemplateTitle = String(template?.title || "").trim().toLowerCase();
  let matchedCount = 0;
  const nextItems = currentItems.map((service, index) => {
    const templateIds = getWorkOrderServiceTemplateIds(service).map((value) => String(value || "").trim());
    const templateTitles = getResolvedWorkOrderServiceTemplateTitles(service)
      .map((value) => String(value || "").trim().toLowerCase());
    const matchesTemplate = (
      (normalizedTemplateId && templateIds.includes(normalizedTemplateId))
      || (normalizedTemplateTitle && templateTitles.includes(normalizedTemplateTitle))
      || currentItems.length === 1
    );

    if (!isDocumentTemplateRuntimeServiceItemIncluded(workOrderId, service, index)) {
      return service;
    }

    if (!matchesTemplate) {
      return service;
    }

    matchedCount += 1;
    return withWorkOrderServiceProgressStatus(service, status);
  });

  return matchedCount > 0 ? nextItems : null;
}

async function persistDocumentTemplateRuntimeServiceProgress(workOrder = {}, template = null, status = "in_progress") {
  const workOrderId = String(workOrder?.id || "").trim();
  const nextItems = buildDocumentTemplateRuntimeServiceProgressPatch(workOrder, template, status);
  if (!workOrderId || !nextItems) {
    return false;
  }

  updateDocumentTemplateRuntimeOverride(workOrderId, { serviceItems: nextItems }, { render: false });
  const stateItem = state.workOrders.find((item) => String(item.id) === workOrderId);
  if (stateItem) {
    stateItem.serviceItems = nextItems;
    stateItem.serviceLine = getWorkOrderServiceSummary({ serviceItems: nextItems });
  }

  try {
    await apiRequest(`/work-orders/${encodeURIComponent(workOrderId)}`, {
      method: "PATCH",
      body: { serviceItems: nextItems },
    });
    return true;
  } catch (error) {
    console.warn("Ne mogu automatski ažurirati status usluge na RN-u.", error);
    return false;
  }
}

function getDocumentTemplateRuntimeMatchedServiceItems(workOrder = {}, template = buildDocumentTemplateDraft()) {
  const runtimeTemplateId = getDocumentTemplateRuntimeTemplateId(template);
  const normalizedTemplateTitle = String(template?.title || "").trim().toLowerCase();

  return getDocumentTemplateRuntimeIncludedServiceItems(workOrder).filter((service) => {
    const templateIds = getWorkOrderServiceTemplateIds(service).map((value) => String(value || "").trim());
    if (runtimeTemplateId && templateIds.includes(runtimeTemplateId)) {
      return true;
    }

    if (!normalizedTemplateTitle) {
      return false;
    }

    return getResolvedWorkOrderServiceTemplateTitles(service)
      .map((value) => String(value || "").trim().toLowerCase())
      .includes(normalizedTemplateTitle);
  });
}

function getDocumentTemplateRuntimePrimaryServiceItem(workOrder = {}, template = buildDocumentTemplateDraft()) {
  return getDocumentTemplateRuntimeMatchedServiceItems(workOrder, template)[0] ?? null;
}

function getDocumentTemplateRuntimeDocumentNumber(workOrder = {}, template = buildDocumentTemplateDraft()) {
  const workOrderNumber = String(workOrder?.workOrderNumber || "").trim();
  const primaryService = getDocumentTemplateRuntimePrimaryServiceItem(workOrder, template);
  const serviceCode = String(
    primaryService?.serviceCode
    || primaryService?.name
    || template?.title
    || ""
  ).trim();

  const baseNumber = [workOrderNumber, serviceCode].filter(Boolean).join("-");
  const objectSequence = getDocumentTemplateRuntimeSequenceObjectNumber(workOrder, template);
  return objectSequence > 0 && baseNumber ? `${baseNumber}-${objectSequence}` : baseNumber;
}

function formatQualifiedInspectorNameWithTitle(user = {}) {
  const name = String(user?.fullName || user?.email || "").trim();
  const title = String(user?.title || "").trim();
  return [name, title].filter(Boolean).join(", ");
}

function getWorkOrderDocumentOrderedQualifiedInspectors(workOrder = {}) {
  const orderedInspectors = [];
  const seenUserIds = new Set();

  getWorkOrderDocumentSignaturePersonFields()
    .filter((definition) => definition.capability === "inspect")
    .forEach((definition) => {
      getWorkOrderDocumentQualifiedUsers(workOrder, "inspect", definition.signatureArea).forEach((user) => {
        const key = String(user?.id || user?.email || user?.fullName || "").trim();
        if (!key || seenUserIds.has(key)) {
          return;
        }
        seenUserIds.add(key);
        orderedInspectors.push(user);
      });
    });

  return orderedInspectors;
}

function getWorkOrderDocumentQualifiedInspectorNames(workOrder = {}) {
  return getWorkOrderDocumentOrderedQualifiedInspectors(workOrder)
    .map((user) => getUserDocumentDisplayName(user))
    .filter(Boolean)
    .join(", ");
}

function getWorkOrderDocumentQualifiedInspectorsWithTitles(workOrder = {}) {
  return getWorkOrderDocumentOrderedQualifiedInspectors(workOrder)
    .map((user) => formatQualifiedInspectorNameWithTitle(user))
    .filter(Boolean)
    .join(", ");
}

function getQualifiedUserSourcePreviewValue(source, context = {}) {
  const workOrder = context.sampleWorkOrder;
  const normalizedSource = String(source || "").trim().toUpperCase();
  if (!workOrder) {
    return "";
  }

  if (normalizedSource === "QUALIFIED_INSPECTOR_LIST_WITH_TITLES") {
    return getWorkOrderDocumentQualifiedInspectorsWithTitles(workOrder);
  }
  if (normalizedSource === "QUALIFIED_INSPECTOR_LIST_NAMES") {
    return getWorkOrderDocumentQualifiedInspectorNames(workOrder);
  }

  const sourceMap = {
    QUALIFIED_INSPECTOR_NAME: { capability: "inspect", field: "name" },
    QUALIFIED_INSPECTOR_TYPE: { capability: "inspect", field: "type" },
    QUALIFIED_INSPECTOR_DATA_1: { capability: "inspect", field: "data1" },
    QUALIFIED_INSPECTOR_DATA_2: { capability: "inspect", field: "data2" },
    QUALIFIED_INSPECTOR_DATA_3: { capability: "inspect", field: "data3" },
    QUALIFIED_INSPECTOR_PASSED_ON: { capability: "inspect", field: "passedOn" },
    QUALIFIED_INSPECTOR_CLASS_CODE: { capability: "inspect", field: "classCode" },
    QUALIFIED_INSPECTOR_URBROJ: { capability: "inspect", field: "urbroj" },
    QUALIFIED_INSPECTOR_E_BROJ: { capability: "inspect", field: "eBroj" },
    QUALIFIED_INSPECTOR_SUMMARY: { capability: "inspect", field: "summary" },
    QUALIFIED_AUTHORIZATION_HOLDER_NAME: { capability: "authorize", field: "name" },
    QUALIFIED_AUTHORIZATION_HOLDER_TYPE: { capability: "authorize", field: "type" },
    QUALIFIED_AUTHORIZATION_HOLDER_DATA_1: { capability: "authorize", field: "data1" },
    QUALIFIED_AUTHORIZATION_HOLDER_DATA_2: { capability: "authorize", field: "data2" },
    QUALIFIED_AUTHORIZATION_HOLDER_DATA_3: { capability: "authorize", field: "data3" },
    QUALIFIED_AUTHORIZATION_HOLDER_PASSED_ON: { capability: "authorize", field: "passedOn" },
    QUALIFIED_AUTHORIZATION_HOLDER_CLASS_CODE: { capability: "authorize", field: "classCode" },
    QUALIFIED_AUTHORIZATION_HOLDER_URBROJ: { capability: "authorize", field: "urbroj" },
    QUALIFIED_AUTHORIZATION_HOLDER_E_BROJ: { capability: "authorize", field: "eBroj" },
    QUALIFIED_AUTHORIZATION_HOLDER_SUMMARY: { capability: "authorize", field: "summary" },
  };
  const mapping = sourceMap[normalizedSource];
  if (!mapping) {
    return "";
  }

  const user = getWorkOrderDocumentQualifiedUser(workOrder, mapping.capability, "elektro");
  if (!user) {
    return "";
  }

  const qualification = getUserElectricalQualification(user);
  if (mapping.field === "summary") {
    return getQualifiedUserSummaryValue(user, mapping.capability, "elektro");
  }
  if (mapping.field === "name") {
    return getUserDocumentDisplayName(user);
  }

  return String(qualification[mapping.field] || "").trim();
}

function getUserDocuments(user = {}) {
  return Array.isArray(user?.documents) ? user.documents : [];
}

function getUserSignatureScanDataUrl(user = {}) {
  const rootQualification = user?.electricalQualification ?? {};
  return String(
    user?.signatureDataUrl
    || user?.signatureStorageUrl
    || rootQualification.signatureDataUrl
    || rootQualification.signatureStorageUrl
    || rootQualification.storageUrl
    || "",
  ).trim();
}

function clearUserElectricalSignaturePad({ preserveValue = false } = {}) {
  if (!preserveValue && userElectricalSignatureDataUrlInput) {
    userElectricalSignatureDataUrlInput.value = "";
  }

  if (userElectricalSignatureFileInput) {
    userElectricalSignatureFileInput.value = "";
  }

  if (userElectricalSignaturePreview) {
    userElectricalSignaturePreview.replaceChildren();
    userElectricalSignaturePreview.classList.add("is-empty");
  }
}

function renderUserElectricalSignaturePad(signatureValue = "") {
  const safeValue = String(signatureValue || "").trim();

  if (userElectricalSignatureDataUrlInput) {
    userElectricalSignatureDataUrlInput.value = safeValue;
  }

  if (userElectricalSignatureFileInput) {
    userElectricalSignatureFileInput.value = "";
  }

  if (!userElectricalSignaturePreview) {
    return;
  }

  userElectricalSignaturePreview.replaceChildren();
  userElectricalSignaturePreview.classList.toggle("is-empty", !safeValue);

  if (!safeValue) {
    return;
  }

  const previewImage = document.createElement("img");
  previewImage.src = safeValue;
  previewImage.alt = "Potpis korisnika";
  previewImage.loading = "lazy";

  userElectricalSignaturePreview.append(previewImage);
}

async function queueUserElectricalSignatureFile(file) {
  if (!file) {
    return;
  }

  const dataUrl = await readFileAsDataUrl(file, `Ne mogu učitati datoteku ${file.name}.`);
  renderUserElectricalSignaturePad(dataUrl);
}

function setUserDocumentDrafts(items = []) {
  userDocumentDrafts = (Array.isArray(items) ? items : [])
    .map((item) => createModuleAttachmentDraft(item))
    .filter((item) => item.fileName && item.dataUrl);
}

function updateUserDocumentDraft(documentId, patch = {}) {
  userDocumentDrafts = userDocumentDrafts.map((item) => (
    item.id === documentId
      ? {
        ...item,
        ...patch,
      }
      : item
  ));
}

function focusUserDocumentCategory(documentId = "") {
  if (!documentId || !userDocumentsList) {
    return;
  }

  requestAnimationFrame(() => {
    const target = Array.from(
      userDocumentsList.querySelectorAll(".module-attachment-category-select"),
    ).find((input) => input.dataset.documentId === String(documentId));

    target?.focus({ preventScroll: false });
  });
}

function focusUserDocumentCustomCategory(documentId = "") {
  if (!documentId || !userDocumentsList) {
    return;
  }

  requestAnimationFrame(() => {
    const target = Array.from(
      userDocumentsList.querySelectorAll(".module-attachment-custom-category-input"),
    ).find((input) => input.dataset.documentId === String(documentId));

    target?.focus({ preventScroll: false });
  });
}

function finalizeUserDocumentCustomCategory(documentId = "", rawValue = "") {
  const nextValue = String(rawValue || "").trim();
  if (!documentId || !nextValue) {
    return false;
  }

  updateUserDocumentDraft(documentId, {
    documentCategory: nextValue,
    documentCategoryMode: "",
  });
  renderUserDocuments();
  focusUserDocumentCategory(documentId);
  return true;
}

function renderUserDocuments() {
  if (!userDocumentsList) {
    return;
  }

  if (userDocumentDrafts.length === 0) {
    const empty = document.createElement("div");
    empty.className = "module-attachment-empty";
    empty.setAttribute("aria-label", "Nema dokumenata za korisnika");
    userDocumentsList.replaceChildren(empty);
    return;
  }

  userDocumentsList.replaceChildren(...userDocumentDrafts.map((entry) => {
    const row = document.createElement("article");
    row.className = "module-attachment-row";
    row.classList.toggle("is-unclassified", !entry.documentCategory);

    const copy = document.createElement("div");
    copy.className = "module-attachment-copy";

    const meta = document.createElement("span");
    meta.className = "module-attachment-meta";
    meta.textContent = [
      entry.fileType || "",
      formatFileSize(entry.fileSize),
      entry.updatedAt ? formatCompactDate(entry.updatedAt) : "",
    ].filter(Boolean).join(" | ");

    const fieldWrap = document.createElement("div");
    fieldWrap.className = "module-attachment-fields";

    const nameField = document.createElement("label");
    nameField.className = "module-attachment-field";

    const nameLabel = document.createElement("span");
    nameLabel.className = "module-attachment-field-label";
    nameLabel.textContent = "Naziv";

    const nameInput = document.createElement("input");
    nameInput.type = "text";
    nameInput.value = entry.fileName;
    nameInput.maxLength = 220;
    nameInput.placeholder = "Naziv dokumenta";
    nameInput.addEventListener("input", () => {
      updateUserDocumentDraft(entry.id, { fileName: nameInput.value });
    });

    nameField.append(nameLabel, nameInput);

    const categoryField = document.createElement("label");
    categoryField.className = "module-attachment-field";

    const categoryLabel = document.createElement("span");
    categoryLabel.className = "module-attachment-field-label";
    categoryLabel.textContent = "Vrsta";

    const categorySelect = document.createElement("select");
    categorySelect.className = "module-attachment-category-select";
    categorySelect.dataset.documentId = entry.id;
    const categoryOptions = buildDraftCategoryOptions(
      USER_DOCUMENT_CATEGORY_OPTIONS,
      userDocumentDrafts,
      entry.documentCategory || "",
    );
    const usesCustomCategory = entry.documentCategoryMode === "custom";
    replaceSelectOptions(
      categorySelect,
      categoryOptions,
      entry.documentCategory || "",
    );
    categorySelect.addEventListener("change", () => {
      const nextValue = categorySelect.value || "";
      if (nextValue === "__custom__") {
        updateUserDocumentDraft(entry.id, {
          documentCategory: "",
          documentCategoryMode: "custom",
        });
        renderUserDocuments();
        focusUserDocumentCustomCategory(entry.id);
        return;
      }
      updateUserDocumentDraft(entry.id, {
        documentCategory: nextValue,
        documentCategoryMode: "",
      });
      row.classList.toggle("is-unclassified", !nextValue);
      if (usesCustomCategory) {
        renderUserDocuments();
      }
    });

    categoryField.append(categoryLabel, categorySelect);
    fieldWrap.append(nameField, categoryField);
    if (usesCustomCategory) {
      const customCategoryField = document.createElement("label");
      customCategoryField.className = "module-attachment-field is-custom-category";

      const customCategoryLabel = document.createElement("span");
      customCategoryLabel.className = "module-attachment-field-label";
      customCategoryLabel.textContent = "Nova vrsta";

      const customCategoryInput = document.createElement("input");
      customCategoryInput.type = "text";
      customCategoryInput.value = entry.documentCategory || "";
      customCategoryInput.maxLength = 64;
      customCategoryInput.placeholder = "Upiši vrstu dokumenta";
      customCategoryInput.className = "module-attachment-custom-category-input";
      customCategoryInput.dataset.documentId = entry.id;
      customCategoryInput.addEventListener("input", () => {
        const customValue = customCategoryInput.value;
        updateUserDocumentDraft(entry.id, {
          documentCategory: customValue,
          documentCategoryMode: "custom",
        });
        row.classList.toggle("is-unclassified", !String(customValue || "").trim());
      });
      customCategoryInput.addEventListener("blur", () => {
        finalizeUserDocumentCustomCategory(entry.id, customCategoryInput.value);
      });
      customCategoryInput.addEventListener("keydown", (event) => {
        if (event.key === "Enter") {
          event.preventDefault();
          finalizeUserDocumentCustomCategory(entry.id, customCategoryInput.value);
          return;
        }

        if (event.key === "Escape") {
          event.preventDefault();
          updateUserDocumentDraft(entry.id, {
            documentCategory: "",
            documentCategoryMode: "",
          });
          renderUserDocuments();
          focusUserDocumentCategory(entry.id);
        }
      });

      customCategoryField.append(customCategoryLabel, customCategoryInput);
      fieldWrap.append(customCategoryField);
    }

    copy.append(meta, fieldWrap);

    const actions = document.createElement("div");
    actions.className = "module-attachment-actions";

    const openButton = createActionButton("Preuzmi", "card-button", () => {
      triggerModuleAttachmentDownload({
        ...entry,
        fileName: nameInput.value || entry.fileName,
      });
    });
    const removeButton = createActionButton("Makni", "card-button card-danger", () => {
      userDocumentDrafts = userDocumentDrafts.filter((item) => item.id !== entry.id);
      renderUserDocuments();
    });

    actions.append(openButton, removeButton);
    row.append(copy, actions);
    return row;
  }));
}

