function getClientPortalFoundationalDocumentItems() {
  const presetTypes = new Set(RULEBOOK_PRESETS.map((preset) => preset.type));
  const visibleRulebooks = sortRulebooks(state.rulebooks ?? [])
    .filter((item) => String(item.status || "draft") === "active");
  const rulebooksByType = new Map();
  visibleRulebooks.forEach((item) => {
    const type = String(item.rulebookType || "custom");
    if (!rulebooksByType.has(type)) {
      rulebooksByType.set(type, item);
    }
  });

  const presetItems = RULEBOOK_PRESETS.map((preset) => ({
    key: `preset:${preset.type}`,
    type: preset.type,
    preset,
    rulebook: rulebooksByType.get(preset.type) ?? null,
  }));
  const customItems = visibleRulebooks
    .filter((item) => !presetTypes.has(String(item.rulebookType || "")))
    .map((item) => ({
      key: `rulebook:${item.id || item.title || item.rulebookType}`,
      type: item.rulebookType || "custom",
      preset: getRulebookPreset(item.rulebookType) ?? null,
      rulebook: item,
    }));

  return [...presetItems, ...customItems];
}

function getClientPortalFoundationDocumentCount(items = getClientPortalFoundationalDocumentItems()) {
  return items.reduce((total, item) => total + ((item.rulebook?.documents ?? []).length > 0 ? 1 : 0), 0);
}

function createClientPortalFoundationDocumentCard(item = {}) {
  const rulebook = item.rulebook ?? null;
  const preset = item.preset ?? getRulebookPreset(item.type) ?? {};
  const type = String(rulebook?.rulebookType || preset.type || item.type || "custom");
  const documents = (rulebook?.documents ?? [])
    .map((document) => createModuleAttachmentDraft(document))
    .filter((document) => document.fileName && (document.dataUrl || document.storageUrl));
  const article = document.createElement("article");
  article.className = `client-portal-foundation-card is-${slugifyValue(type || "custom")}${rulebook ? " has-rulebook" : " is-placeholder"}`;

  const icon = document.createElement("span");
  icon.className = "client-portal-foundation-icon";
  icon.innerHTML = renderRulebookIcon(getRulebookIconName(type));

  const copy = document.createElement("div");
  copy.className = "client-portal-foundation-copy";
  const title = document.createElement("strong");
  title.textContent = rulebook?.title || preset.title || getRulebookTypeLabel(type);
  const summary = document.createElement("span");
  summary.textContent = rulebook?.summary || preset.summary || "Temeljni interni dokument za klijentski portal.";
  copy.append(title, summary);

  const status = document.createElement("span");
  status.className = `client-portal-foundation-status is-${slugifyValue(rulebook?.status || "pending")}`;
  status.textContent = rulebook ? getRulebookStatusLabel(rulebook.status) : "U pripremi";

  const meta = document.createElement("div");
  meta.className = "client-portal-foundation-meta";
  [
    getRulebookTypeLabel(type),
    documents.length ? `${documents.length} dok.` : "Bez dokumenta",
    rulebook?.reviewDate ? `Revizija ${formatCompactDate(rulebook.reviewDate)}` : "",
    rulebook?.owner || "",
  ].filter(Boolean).forEach((label) => {
    const chip = document.createElement("span");
    chip.textContent = label;
    meta.append(chip);
  });

  const actions = document.createElement("div");
  actions.className = "client-portal-foundation-actions";
  if (documents.length > 0) {
    documents.slice(0, 3).forEach((document) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "client-portal-foundation-document-button";
      button.textContent = document.fileName || "Preuzmi dokument";
      button.title = document.fileName || "Preuzmi dokument";
      button.addEventListener("click", () => {
        triggerModuleAttachmentDownload(document);
      });
      actions.append(button);
    });
    if (documents.length > 3) {
      const more = document.createElement("span");
      more.className = "client-portal-foundation-more";
      more.textContent = `+${documents.length - 3}`;
      actions.append(more);
    }
  } else {
    const empty = document.createElement("span");
    empty.className = "client-portal-foundation-empty";
    empty.textContent = "Dokument još nije dodan.";
    actions.append(empty);
  }

  article.append(icon, copy, status, meta, actions);
  return article;
}

function createClientPortalFoundationPreviewRow(item = {}) {
  const rulebook = item.rulebook ?? null;
  const preset = item.preset ?? getRulebookPreset(item.type) ?? {};
  const type = String(rulebook?.rulebookType || preset.type || item.type || "custom");
  const documents = (rulebook?.documents ?? []).filter((document) => String(document?.storageUrl || document?.dataUrl || "").trim());
  const row = document.createElement("article");
  row.className = "client-portal-preview-row is-foundation-document";

  const main = document.createElement("div");
  main.className = "client-portal-preview-row-main";
  const title = document.createElement("strong");
  title.textContent = rulebook?.title || preset.title || getRulebookTypeLabel(type);
  const status = document.createElement("span");
  status.textContent = rulebook ? getRulebookStatusLabel(rulebook.status) : "U pripremi";
  main.append(title, status);

  const copy = document.createElement("div");
  copy.className = "client-portal-preview-row-copy";
  const typeLabel = document.createElement("strong");
  typeLabel.textContent = getRulebookTypeLabel(type);
  const summary = document.createElement("span");
  summary.textContent = rulebook?.summary || preset.summary || "Temeljni dokument.";
  copy.append(typeLabel, summary);

  const meta = document.createElement("div");
  meta.className = "client-portal-preview-row-meta";
  const documentCount = document.createElement("span");
  documentCount.textContent = documents.length ? `${documents.length} dokumenata` : "Bez dokumenta";
  const review = document.createElement("span");
  review.textContent = rulebook?.reviewDate ? `Revizija ${formatCompactDate(rulebook.reviewDate)}` : "Bez revizije";
  meta.append(documentCount, review);

  const badge = document.createElement("span");
  badge.className = "client-portal-preview-row-badge is-foundation-document";
  badge.textContent = rulebook ? "Vidljivo klijentu" : "Nije objavljeno";

  row.append(main, copy, meta, badge);
  return row;
}

function renderClientPortalPreview() {
  const companyId = getClientPortalSelectedCompanyId();
  const company = getCompany(companyId);
  const selectedLocationIds = getClientPortalSelectedLocationIdsForPreview();
  const allLocations = Boolean(clientPortalAllLocationsInput?.checked);
  const companyLocations = companyId ? getCompanyLocations(companyId) : [];
  ensureClientPortalDocumentRecordsLoaded(companyId);
  const selectedLocationNames = selectedLocationIds
    .map((locationId) => getLocation(locationId)?.name || "")
    .filter(Boolean);
  const scopeLabel = allLocations
    ? "Sve lokacije"
    : (selectedLocationNames.length > 0 ? `${selectedLocationNames.length} odabrane lokacije` : "Odaberi lokacije");

  if (clientPortalPreviewScope) {
    clientPortalPreviewScope.textContent = scopeLabel;
  }
  if (clientPortalPreviewCompany) {
    clientPortalPreviewCompany.textContent = company?.name || "Odaberi tvrtku";
  }
  if (clientPortalPreviewLocation) {
    clientPortalPreviewLocation.textContent = allLocations
      ? (companyLocations.length > 0 ? `Sve lokacije tvrtke (${companyLocations.length})` : "Sve sadašnje i buduće lokacije")
      : (selectedLocationNames.join(", ") || "Odaberi jednu ili više lokacija");
  }

  if (!clientPortalPreviewList) {
    return;
  }

  const scopedDocumentRecords = getClientPortalDocumentRecordPreviews(companyId, selectedLocationIds);
  const scopedTrainingRecords = sortPersonTrainingRecords(filterClientPortalRecordsByScope(
    state.peopleTrainingRecords,
    companyId,
    selectedLocationIds,
  ));
  const scopedRiskAssessments = sortRiskAssessments(filterClientPortalRecordsByScope(
    state.riskAssessments,
    companyId,
    selectedLocationIds,
  ));
  const scopedClientPortalRecords = sortClientPortalRecords(filterClientPortalRecordsByScope(
    state.clientPortalRecords ?? [],
    companyId,
    selectedLocationIds,
  ));

  const foundationRows = getClientPortalFoundationalDocumentItems().map(createClientPortalFoundationPreviewRow);
  const documentRows = scopedDocumentRecords.map(createClientPortalDocumentPreviewRow);
  const trainingRows = scopedTrainingRecords.map(createClientPortalTrainingPreviewRow);
  const riskAssessmentRows = scopedRiskAssessments.map(createClientPortalRiskAssessmentPreviewRow);
  const clientRecordRows = companyId ? createClientPortalRecordTypePreviewRows(scopedClientPortalRecords) : [];
  const documentsLoading = Boolean(companyId && state.documentsExplorer.loading);
  const recordsCopy = documentsLoading
    ? "Ucitavam spremljene zapisnike za odabrani opseg."
    : "Spremljeni zapisnici koje klijent vidi u Documents.";

  const foundationSection = createClientPortalPreviewSection({
    key: "foundationDocuments",
    title: "Temeljna dokumentacija",
    subtitle: "Osnovni pravilnici i akti koji se prikazuju klijentu u portalu.",
    rows: foundationRows,
    emptyMessage: "Nema temeljne dokumentacije za prikaz.",
  });
  const documentsSection = createClientPortalPreviewSection({
    key: "documents",
    title: "Zapisnici",
    subtitle: recordsCopy,
    rows: documentRows,
    emptyMessage: documentsLoading ? "Ucitavanje zapisnika..." : "Nema spremljenih zapisnika za odabrani opseg.",
  });
  const trainingsSection = createClientPortalPreviewSection({
    key: "trainings",
    title: "Osposobljavanja i pregledi",
    subtitle: "Klijent vidi važenja za svoje ljude: ZNR, požar, ADR, liječnički i stručna osposobljavanja.",
    rows: trainingRows,
    emptyMessage: companyId ? "Nema evidentiranih osposobljavanja za odabrani opseg." : "Odaberi tvrtku za preview osposobljavanja.",
  });
  const riskAssessmentSection = createClientPortalPreviewSection({
    key: "riskAssessments",
    title: "Procjene rizika",
    subtitle: "Klijent vidi procjene rizika i dopunjava podatke po svakom radnom mjestu.",
    rows: riskAssessmentRows,
    emptyMessage: companyId ? "Nema procjena rizika za odabrani opseg." : "Odaberi tvrtku za preview procjena rizika.",
  });
  const clientRecordsSection = createClientPortalPreviewSection({
    key: "clientPortalRecords",
    title: "Evidencije klijenta",
    subtitle: "Radnici, OZO, vatrogasni aparati, vozila, nadzori, nedostaci i ostali rokovi.",
    rows: clientRecordRows,
    emptyMessage: companyId ? "Nema evidencija za odabrani opseg." : "Odaberi tvrtku za preview evidencija.",
  });

  clientPortalPreviewList.replaceChildren(
    foundationSection,
    clientRecordsSection,
    documentsSection,
    trainingsSection,
    riskAssessmentSection,
  );
}

function createClientPortalRecordTypePreviewRows(records = []) {
  return CLIENT_PORTAL_RECORD_TYPE_OPTIONS.map((option) => {
    const typeMeta = getClientPortalRecordTypeMeta(option.value);
    const typeRecords = records.filter((record) => String(record.type || "") === option.value);
    const openCount = typeRecords.filter(isClientPortalRecordOpen).length;
    const attentionCount = typeRecords.filter((record) => isClientPortalRecordOpen(record) && isClientPortalRecordAttention(record)).length;
    const latestRecord = typeRecords[0] ?? null;
    const row = document.createElement("article");
    row.className = `client-portal-preview-row is-client-record is-${typeMeta.accent}`;

    const main = document.createElement("div");
    main.className = "client-portal-preview-row-main";
    const title = document.createElement("strong");
    title.textContent = option.label;
    const count = document.createElement("span");
    count.textContent = `${typeRecords.length} zapisa`;
    main.append(title, count);

    const copy = document.createElement("div");
    copy.className = "client-portal-preview-row-copy";
    const eyebrow = document.createElement("strong");
    eyebrow.textContent = typeMeta.eyebrow;
    const latest = document.createElement("span");
    latest.textContent = latestRecord
      ? [latestRecord.title || typeMeta.title, latestRecord.dueDate ? `rok ${formatCompactDate(latestRecord.dueDate)}` : ""].filter(Boolean).join(" · ")
      : "Još nema zapisa za ovaj blok.";
    copy.append(eyebrow, latest);

    const meta = document.createElement("div");
    meta.className = "client-portal-preview-row-meta";
    const open = document.createElement("span");
    open.textContent = `${openCount} otvoreno`;
    const attention = document.createElement("span");
    attention.textContent = attentionCount ? `${attentionCount} za pažnju` : "bez upozorenja";
    meta.append(open, attention);

    const badge = document.createElement("span");
    badge.className = `client-portal-preview-row-badge is-client-record is-${typeMeta.accent}`;
    badge.textContent = typeMeta.title;

    row.append(main, copy, meta, badge);
    return row;
  });
}

