function buildClientPortalRecordPayloadFromForm(form, type = "worker", companyId = "") {
  const data = new FormData(form);
  const getValue = (name) => String(data.get(name) || "").trim();
  const details = {};

  if (type === "worker") {
    const riskWorkplaceKey = getValue("riskWorkplaceKey");
    const riskWorkplace = getRiskAssessmentWorkplaceOptionByValue(riskWorkplaceKey, companyId);
    Object.assign(details, {
      fullName: getValue("fullName"),
      riskWorkplaceKey,
      jobTitle: getValue("jobTitle") || riskWorkplace?.data?.jobTitle || "",
      jobDescription: riskWorkplace?.data?.jobDescription || "",
      email: getValue("email"),
      phone: getValue("phone"),
      oib: getValue("oib"),
      medicalReferralNumber: getValue("medicalReferralNumber"),
      medicalReferralValidUntil: getValue("medicalReferralValidUntil"),
      medicalCertificateNumber: getValue("medicalCertificateNumber"),
      medicalCertificateValidUntil: getValue("medicalCertificateValidUntil"),
      visionReferralNumber: getValue("visionReferralNumber"),
      visionReferralValidUntil: getValue("visionReferralValidUntil"),
      visionCertificateNumber: getValue("visionCertificateNumber"),
      visionCertificateValidUntil: getValue("visionCertificateValidUntil"),
      psychologicalCheckUntil: getValue("psychologicalCheckUntil"),
      medicalWorkplace: getValue("medicalWorkplace") || riskWorkplace?.data?.medicalWorkplace || "",
      medicalLoadWeights: getValue("medicalLoadWeights") || riskWorkplace?.data?.medicalLoadWeights || "",
      medicalWorkOrganization: getValue("medicalWorkOrganization") || riskWorkplace?.data?.medicalWorkOrganization || "",
      medicalBodyPositions: getValue("medicalBodyPositions") || riskWorkplace?.data?.medicalBodyPositions || "",
      medicalWorkConditions: getValue("medicalWorkConditions") || riskWorkplace?.data?.medicalWorkConditions || "",
      medicalEquipment: getValue("medicalEquipment") || riskWorkplace?.data?.medicalEquipment || "",
      medicalSubstances: getValue("medicalSubstances") || riskWorkplace?.data?.medicalSubstances || "",
      note: getValue("note"),
    });
  } else if (type === "vehicle") {
    const workerRecordId = getValue("responsibleWorkerRecordId");
    const worker = getClientPortalWorkerRecords(companyId).find((item) => String(item.id) === workerRecordId) ?? null;
    Object.assign(details, {
      vehicleName: getValue("vehicleName"),
      plateNumber: getValue("plateNumber"),
      vehicleType: getValue("vehicleType"),
      responsibleWorkerRecordId: workerRecordId,
      responsibleWorkerName: worker?.title || worker?.details?.fullName || "",
      registrationDate: getValue("registrationDate"),
      insuranceDate: getValue("insuranceDate"),
      serviceDate: getValue("serviceDate"),
      note: getValue("note"),
    });
  } else if (type === "fire_extinguisher") {
    Object.assign(details, {
      code: getValue("code"),
      locationText: getValue("locationText"),
      extinguisherType: getValue("extinguisherType"),
      lastInspectionDate: getValue("lastInspectionDate"),
      nextInspectionDate: getValue("nextInspectionDate"),
      lastInternalInspectionDate: getValue("lastInternalInspectionDate"),
      nextInternalInspectionDate: getValue("nextInternalInspectionDate"),
      lastServiceDate: getValue("lastServiceDate"),
      nextServiceDate: getValue("nextServiceDate"),
      note: getValue("note"),
    });
  } else if (type === "ppe_assignment") {
    const workerRecordId = getValue("workerRecordId");
    const worker = getClientPortalWorkerRecords(companyId).find((item) => String(item.id) === workerRecordId) ?? null;
    Object.assign(details, {
      workerRecordId,
      workerName: worker?.title || worker?.details?.fullName || "",
      ppeName: getValue("ppeName"),
      quantity: getValue("quantity"),
      assignedDate: getValue("assignedDate"),
      dueDate: getValue("dueDate"),
      returnedDate: getValue("returnedDate"),
      note: getValue("note"),
    });
  } else if (type === "defect_report") {
    Object.assign(details, {
      defectTitle: getValue("defectTitle"),
      priority: getValue("priority"),
      category: getValue("category"),
      reportedDate: getValue("reportedDate"),
      dueDate: getValue("dueDate"),
      reportedBy: getValue("reportedBy"),
      locationText: getValue("locationText"),
      description: getValue("description"),
      action: getValue("action"),
    });
  } else if (type === "internal_inspection") {
    Object.assign(details, {
      inspectionTitle: getValue("inspectionTitle"),
      area: getValue("area"),
      inspectionDate: getValue("inspectionDate"),
      dueDate: getValue("dueDate"),
      inspectorName: getValue("inspectorName"),
      result: getValue("result"),
      finding: getValue("finding"),
      correctiveAction: getValue("correctiveAction"),
      documentName: getValue("documentName"),
    });
  } else if (type === "alcohol_test") {
    const workerRecordId = getValue("workerRecordId");
    const worker = getClientPortalWorkerRecords(companyId).find((item) => String(item.id) === workerRecordId) ?? null;
    Object.assign(details, {
      workerRecordId,
      workerName: worker?.title || worker?.details?.fullName || "",
      testDate: getValue("testDate"),
      result: getValue("result"),
      measuredValue: getValue("measuredValue"),
      testerName: getValue("testerName"),
      nextTestDate: getValue("nextTestDate"),
      documentName: getValue("documentName"),
      note: getValue("note"),
    });
  } else if (type === "document") {
    Object.assign(details, {
      documentName: getValue("documentName"),
      documentType: getValue("documentType"),
      fileName: getValue("fileName"),
      fileUrl: getValue("fileUrl"),
      documentDate: getValue("documentDate"),
      validUntil: getValue("validUntil"),
      ownerName: getValue("ownerName"),
      note: getValue("note"),
    });
  } else {
    Object.assign(details, {
      deadlineName: getValue("deadlineName"),
      deadlineType: getValue("deadlineType"),
      dueDate: getValue("dueDate"),
      ownerName: getValue("ownerName"),
      description: getValue("description"),
    });
  }

  return {
    companyId,
    locationId: getValue("locationId"),
    type,
    status: getValue("status") || "active",
    details,
  };
}

async function resolveClientPortalRecordAttachmentsFromForm(form, currentAttachments = []) {
  const data = new FormData(form);
  const getValue = (name) => String(data.get(name) || "").trim();
  const removeKeys = new Set(data.getAll("removeAttachmentKeys").map((value) => String(value || "")));
  const retainedAttachments = (Array.isArray(currentAttachments) ? currentAttachments : [])
    .filter((attachment, index) => !removeKeys.has(getClientPortalRecordAttachmentKey(attachment, index)))
    .map((attachment) => ({ ...attachment }));
  const description = getValue("attachmentDescription");
  const addedAttachments = [];
  const fileInput = form.querySelector('input[name="attachmentFiles"]');
  const files = fileInput instanceof HTMLInputElement && fileInput.files
    ? Array.from(fileInput.files)
    : [];

  for (const file of files) {
    if (file.size > CLIENT_PORTAL_RECORD_ATTACHMENT_MAX_BYTES) {
      throw new Error(`Prilog ${file.name || "datoteka"} je veći od ${formatFileSize(CLIENT_PORTAL_RECORD_ATTACHMENT_MAX_BYTES)}.`);
    }
    addedAttachments.push({
      id: createClientPortalRecordAttachmentId(),
      fileName: file.name || "prilog",
      fileSize: file.size || null,
      mimeType: file.type || "",
      dataUrl: await readFileAsDataUrl(file, "Ne mogu učitati prilog."),
      fileUrl: "",
      description,
      uploadedAt: new Date().toISOString(),
    });
  }

  const linkUrl = getValue("attachmentLinkUrl");
  const linkName = getValue("attachmentLinkName");
  if (linkUrl || linkName) {
    if (!linkUrl) {
      throw new Error("Za link priloga upiši i URL.");
    }
    addedAttachments.push({
      id: createClientPortalRecordAttachmentId(),
      fileName: linkName || linkUrl,
      fileUrl: linkUrl,
      dataUrl: "",
      fileSize: null,
      mimeType: "",
      description,
      uploadedAt: new Date().toISOString(),
    });
  }

  return [...retainedAttachments, ...addedAttachments].slice(0, 20);
}

function getClientPortalRecordAttachments(record = {}) {
  const attachments = record.details?.attachments;
  return Array.isArray(attachments) ? attachments.filter(Boolean) : [];
}

function createClientPortalRecordAttachmentChips(record = {}) {
  const attachments = getClientPortalRecordAttachments(record);
  if (attachments.length === 0) {
    return null;
  }
  const wrap = document.createElement("div");
  wrap.className = "client-portal-record-attachment-chips";
  attachments.slice(0, 6).forEach((attachment, index) => {
    const name = getClientPortalRecordAttachmentName(attachment, index);
    const href = getClientPortalRecordAttachmentHref(attachment);
    const chip = href ? document.createElement("a") : document.createElement("span");
    chip.className = "client-portal-record-attachment-chip";
    chip.textContent = name;
    if (href) {
      chip.href = href;
      chip.target = "_blank";
      chip.rel = "noopener noreferrer";
      if (attachment.dataUrl) {
        chip.download = name;
      }
    }
    wrap.append(chip);
  });
  if (attachments.length > 6) {
    const more = document.createElement("span");
    more.className = "client-portal-record-attachment-chip";
    more.textContent = `+${attachments.length - 6}`;
    wrap.append(more);
  }
  return wrap;
}

function getClientPortalPersonEmail(value = "") {
  return String(value || "").trim().toLowerCase();
}

function getClientPortalPersonOib(value = "") {
  return String(value || "").replace(/\D+/g, "").trim();
}

function getClientPortalWorkerDisplayName(record = {}) {
  const details = record.details ?? {};
  return String(details.fullName || record.title || "").trim();
}

function getClientPortalWorkerTrainingRecords(workerRecord = {}) {
  const details = workerRecord.details ?? {};
  const companyId = String(workerRecord.companyId || "").trim();
  const locationId = String(workerRecord.locationId || "").trim();
  const workerName = normalizeLooseName(getClientPortalWorkerDisplayName(workerRecord));
  const workerOib = getClientPortalPersonOib(details.oib);
  const workerEmail = getClientPortalPersonEmail(details.email);

  if (!companyId || (!workerName && !workerOib && !workerEmail)) {
    return [];
  }

  return sortPersonTrainingRecords((state.peopleTrainingRecords ?? []).filter((trainingRecord) => {
    if (String(trainingRecord.companyId || "").trim() !== companyId) {
      return false;
    }

    const trainingLocationId = String(trainingRecord.locationId || "").trim();
    if (locationId && trainingLocationId && trainingLocationId !== locationId) {
      return false;
    }

    const trainingName = normalizeLooseName(getPeopleTrainingRecordDisplayName(trainingRecord));
    const trainingOib = getClientPortalPersonOib(trainingRecord.oib);
    const trainingEmail = getClientPortalPersonEmail(trainingRecord.email);
    return Boolean(
      (workerOib && trainingOib && workerOib === trainingOib)
      || (workerEmail && trainingEmail && workerEmail === trainingEmail)
      || (workerName && trainingName && workerName === trainingName),
    );
  }));
}

function getClientPortalTrainingStatusCounts(trainingRecords = []) {
  const counts = {
    records: trainingRecords.length,
    valid: 0,
    expiring: 0,
    expired: 0,
    missing: 0,
    attentionRecords: 0,
  };

  trainingRecords.forEach((record) => {
    const overall = getPeopleTrainingOverallStatus(record);
    if (overall === "expired" || overall === "expiring" || overall === "missing") {
      counts.attentionRecords += 1;
    }
    normalizePeopleTrainingItemsForUi(record.trainingItems).forEach((item) => {
      const status = String(item.status || "missing").trim().toLowerCase();
      if (status === "valid" || status === "not_required") {
        counts.valid += 1;
      } else if (status === "expiring") {
        counts.expiring += 1;
      } else if (status === "expired") {
        counts.expired += 1;
      } else {
        counts.missing += 1;
      }
    });
  });

  return counts;
}

function getClientPortalWorkerTrainingSummary(workerRecord = {}) {
  const records = getClientPortalWorkerTrainingRecords(workerRecord);
  return {
    records,
    counts: getClientPortalTrainingStatusCounts(records),
  };
}

function getClientPortalTrainingSummaryLine(counts = {}) {
  if (!counts.records) {
    return "Osposobljavanja: nema povezane evidencije";
  }

  const parts = [
    `${counts.records} zapis(a)`,
    counts.valid ? `${counts.valid} važećih` : "",
    counts.expiring ? `${counts.expiring} istječe` : "",
    counts.expired ? `${counts.expired} isteklo` : "",
    counts.missing ? `${counts.missing} bez podatka` : "",
  ].filter(Boolean);
  return `Osposobljavanja: ${parts.join(" · ")}`;
}

function getClientPortalCompanyTrainingSummary(companyId = "") {
  const records = sortPersonTrainingRecords(filterClientPortalRecordsByScope(
    state.peopleTrainingRecords ?? [],
    companyId,
    [],
  ));
  return getClientPortalTrainingStatusCounts(records);
}

function createClientPortalWorkerTrainingBlock(workerRecord = {}) {
  const { records, counts } = getClientPortalWorkerTrainingSummary(workerRecord);
  const block = document.createElement("div");
  block.className = "client-portal-worker-training-block";
  block.classList.toggle("has-attention", Boolean(counts.expiring || counts.expired || counts.missing));

  const head = document.createElement("div");
  head.className = "client-portal-worker-training-head";
  const title = document.createElement("strong");
  title.textContent = "Osposobljavanja radnika";
  const meta = document.createElement("span");
  meta.textContent = getClientPortalTrainingSummaryLine(counts).replace(/^Osposobljavanja:\s*/i, "");
  head.append(title, meta);
  block.append(head);

  if (!records.length) {
    const empty = document.createElement("p");
    empty.className = "client-portal-worker-training-empty";
    empty.textContent = "Nema povezane evidencije osposobljavanja za ovog radnika.";
    block.append(empty);
    return block;
  }

  const list = document.createElement("div");
  list.className = "client-portal-worker-training-list";
  records.slice(0, 3).forEach((record) => {
    const row = document.createElement("div");
    row.className = "client-portal-worker-training-row";

    const copy = document.createElement("span");
    copy.className = "client-portal-worker-training-copy";
    const name = document.createElement("strong");
    name.textContent = getPeopleTrainingRecordDisplayName(record);
    const company = document.createElement("small");
    company.textContent = [
      record.jobTitle || "",
      record.locationName || getPeopleTrainingLocation(record.locationId)?.name || "",
    ].filter(Boolean).join(" · ") || "Osoba u evidenciji osposobljavanja";
    copy.append(name, company);

    const statusWrap = document.createElement("span");
    statusWrap.className = "client-portal-worker-training-statuses";
    const highlightedItems = normalizePeopleTrainingItemsForUi(record.trainingItems)
      .filter((item) => item.status !== "missing")
      .slice(0, 4);
    if (highlightedItems.length > 0) {
      highlightedItems.forEach((item) => {
        const pill = document.createElement("span");
        pill.className = `client-portal-training-mini-pill ${getPeopleTrainingStatusClass(item.status)}`;
        pill.textContent = item.shortLabel || item.label || getPeopleTrainingStatusLabel(item.status);
        statusWrap.append(pill);
      });
    } else {
      const pill = document.createElement("span");
      pill.className = "client-portal-training-mini-pill is-missing";
      pill.textContent = getPeopleTrainingStatusLabel("missing");
      statusWrap.append(pill);
    }

    row.append(copy, statusWrap);
    list.append(row);
  });

  if (records.length > 3) {
    const more = document.createElement("small");
    more.className = "client-portal-worker-training-more";
    more.textContent = `+${records.length - 3} dodatnih zapisa`;
    list.append(more);
  }

  block.append(list);
  return block;
}

function createClientPortalWorkerTrainingDashboard(records = []) {
  if (records.length === 0) {
    return createClientPortalEmptyLine("Još nema dodanih radnika.");
  }

  const list = document.createElement("div");
  list.className = "client-portal-worker-training-dashboard";
  records.slice(0, 5).forEach((record) => {
    const { counts } = getClientPortalWorkerTrainingSummary(record);
    const row = document.createElement("button");
    row.type = "button";
    row.className = "client-portal-worker-training-dashboard-row";
    row.addEventListener("click", () => {
      openClientPortalRecordModal("worker", record.id);
    });

    const copy = document.createElement("span");
    copy.className = "client-portal-worker-training-dashboard-copy";
    const name = document.createElement("strong");
    name.textContent = getClientPortalWorkerDisplayName(record) || record.title || "Radnik";
    const meta = document.createElement("small");
    meta.textContent = [
      record.details?.jobTitle || "",
      record.locationName || "",
    ].filter(Boolean).join(" · ") || "Radnik u evidenciji";
    copy.append(name, meta);

    const summary = document.createElement("span");
    summary.className = "client-portal-worker-training-dashboard-summary";
    summary.textContent = getClientPortalTrainingSummaryLine(counts).replace(/^Osposobljavanja:\s*/i, "");

    row.append(copy, summary);
    list.append(row);
  });
  return list;
}

function getClientPortalRecordDetailLines(record = {}) {
  const details = record.details ?? {};
  if (record.type === "worker") {
    const trainingSummary = getClientPortalWorkerTrainingSummary(record);
    const healthLine = (label, number = "", validUntil = "") => {
      const parts = [
        number,
        validUntil ? `do ${formatCompactDate(validUntil)}` : "",
      ].filter(Boolean).join(" · ");
      return parts ? `${label}: ${parts}` : "";
    };
    return [
      details.jobTitle,
      details.email,
      details.phone,
      details.oib ? `OIB ${details.oib}` : "",
      healthLine("RA-1 uputnica", details.medicalReferralNumber, details.medicalReferralValidUntil),
      healthLine("Uvjerenje", details.medicalCertificateNumber, details.medicalCertificateValidUntil),
      healthLine("Vid uputnica", details.visionReferralNumber, details.visionReferralValidUntil),
      healthLine("Vid uvjerenje", details.visionCertificateNumber, details.visionCertificateValidUntil),
      details.psychologicalCheckUntil ? `Psihološka provjera: do ${formatCompactDate(details.psychologicalCheckUntil)}` : "",
      details.medicalWorkplace ? `Mjesto rada: ${details.medicalWorkplace}` : "",
      details.medicalLoadWeights ? `Teret: ${details.medicalLoadWeights}` : "",
      getClientPortalTrainingSummaryLine(trainingSummary.counts),
    ].filter(Boolean);
  }
  if (record.type === "vehicle") {
    return [
      details.vehicleType,
      details.responsibleWorkerName ? `Zadužen: ${details.responsibleWorkerName}` : "",
      details.registrationDate ? `Registracija: ${formatCompactDate(details.registrationDate)}` : "",
      details.insuranceDate ? `Osiguranje: ${formatCompactDate(details.insuranceDate)}` : "",
      details.serviceDate ? `Servis: ${formatCompactDate(details.serviceDate)}` : "",
      details.note,
    ].filter(Boolean);
  }
  if (record.type === "fire_extinguisher") {
    return [
      details.locationText,
      details.extinguisherType,
      details.lastInspectionDate ? `Zadnji pregled: ${formatCompactDate(details.lastInspectionDate)}` : "",
      details.nextInspectionDate ? `Sljedeći pregled: ${formatCompactDate(details.nextInspectionDate)}` : "",
      details.lastInternalInspectionDate ? `Zadnji unutarnji: ${formatCompactDate(details.lastInternalInspectionDate)}` : "",
      details.nextInternalInspectionDate ? `Unutarnji pregled: ${formatCompactDate(details.nextInternalInspectionDate)}` : "",
      details.lastServiceDate ? `Zadnji servis: ${formatCompactDate(details.lastServiceDate)}` : "",
      details.nextServiceDate ? `Godišnji servis: ${formatCompactDate(details.nextServiceDate)}` : "",
      details.note,
    ].filter(Boolean);
  }
  if (record.type === "ppe_assignment") {
    return [
      details.workerName ? `Radnik: ${details.workerName}` : "",
      details.quantity ? `Količina: ${details.quantity}` : "",
      details.assignedDate ? `Zaduženo: ${formatCompactDate(details.assignedDate)}` : "",
      details.dueDate ? `Rok: ${formatCompactDate(details.dueDate)}` : "",
      details.returnedDate ? `Razduženo: ${formatCompactDate(details.returnedDate)}` : "",
      details.note,
    ].filter(Boolean);
  }
  if (record.type === "defect_report") {
    return [
      details.priority ? `Prioritet: ${details.priority}` : "",
      details.category,
      details.locationText,
      details.reportedDate ? `Prijava: ${formatCompactDate(details.reportedDate)}` : "",
      details.dueDate ? `Rok: ${formatCompactDate(details.dueDate)}` : "",
      details.reportedBy ? `Prijavio: ${details.reportedBy}` : "",
      details.description,
    ].filter(Boolean);
  }
  if (record.type === "internal_inspection") {
    return [
      details.area,
      details.inspectionDate ? `Nadzor: ${formatCompactDate(details.inspectionDate)}` : "",
      details.dueDate ? `Rok: ${formatCompactDate(details.dueDate)}` : "",
      details.inspectorName ? `Kontrolor: ${details.inspectorName}` : "",
      details.result ? `Rezultat: ${details.result}` : "",
      details.documentName,
      details.finding,
      details.correctiveAction ? `Mjera: ${details.correctiveAction}` : "",
    ].filter(Boolean);
  }
  if (record.type === "alcohol_test") {
    return [
      details.workerName ? `Radnik: ${details.workerName}` : "",
      details.testDate ? `Datum: ${formatCompactDate(details.testDate)}` : "",
      details.result ? `Rezultat: ${details.result}` : "",
      details.measuredValue,
      details.testerName ? `Testirao: ${details.testerName}` : "",
      details.nextTestDate ? `Kontrola: ${formatCompactDate(details.nextTestDate)}` : "",
      details.documentName,
      details.note,
    ].filter(Boolean);
  }
  if (record.type === "document") {
    return [
      details.documentType,
      details.fileName,
      details.documentDate ? `Datum: ${formatCompactDate(details.documentDate)}` : "",
      details.validUntil ? `Vrijedi do: ${formatCompactDate(details.validUntil)}` : "",
      details.ownerName ? `Osoba: ${details.ownerName}` : "",
      details.fileUrl,
      details.note,
    ].filter(Boolean);
  }
  if (record.type === "training_import") {
    const totals = details.preview?.totals || {};
    const result = details.result || {};
    return [
      details.fileName ? `Datoteka: ${details.fileName}` : "",
      details.importMode ? `Import: ${details.importMode}` : "",
      Number.isFinite(Number(totals.total)) ? `Redaka: ${totals.total}` : "",
      Number.isFinite(Number(totals.create)) ? `Novi: ${totals.create}` : "",
      Number.isFinite(Number(totals.update)) ? `Promjene: ${totals.update}` : "",
      Number.isFinite(Number(totals.departure)) ? `Odlasci: ${totals.departure}` : "",
      Number.isFinite(Number(totals.applicable)) ? `Za potvrdu: ${totals.applicable}` : "",
      result.created || result.updated || result.departures ? `Potvrđeno: +${result.created || 0}, až. ${result.updated || 0}, odlasci ${result.departures || 0}` : "",
      details.uploadedAt ? `Zaprimljeno: ${formatCompactDate(details.uploadedAt)}` : "",
      details.appliedAt ? `Potvrđeno: ${formatCompactDate(details.appliedAt)}` : "",
    ].filter(Boolean);
  }
  return [
    details.deadlineType,
    details.dueDate ? `Datum: ${formatCompactDate(details.dueDate)}` : "",
    details.ownerName ? `Odgovoran: ${details.ownerName}` : "",
    details.description,
  ].filter(Boolean);
}

function createClientPortalTrainingImportPreview(record = {}) {
  if (record.type !== "training_import") {
    return null;
  }
  const details = record.details || {};
  const previewRows = Array.isArray(details.preview?.rows) ? details.preview.rows.slice(0, 6) : [];
  const block = document.createElement("div");
  block.className = "client-portal-training-import-preview";
  if (previewRows.length) {
    const list = document.createElement("div");
    list.className = "client-portal-training-import-preview-list";
    previewRows.forEach((row) => {
      const item = document.createElement("span");
      item.textContent = [
        row.personName,
        row.oib ? `OIB ${row.oib}` : "",
        row.actionLabel,
      ].filter(Boolean).join(" · ");
      list.append(item);
    });
    block.append(list);
  }
  if (record.status !== "done" && getCanManagePeople()) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "primary-button client-portal-training-import-confirm";
    button.textContent = "Potvrdi import";
    button.addEventListener("click", () => {
      void confirmClientPortalTrainingImport(record.id);
    });
    block.append(button);
  }
  return block.childNodes.length ? block : null;
}

function createClientPortalRecordCard(record = {}) {
  const typeMeta = getClientPortalRecordTypeMeta(record.type);
  const dueState = getClientPortalRecordDueState(record);
  const card = document.createElement("article");
  card.className = `client-portal-record-card is-${record.type || "deadline"} is-${typeMeta.accent}`;

  const head = document.createElement("div");
  head.className = "client-portal-record-card-head";
  const icon = document.createElement("span");
  icon.className = "client-portal-record-card-icon";
  icon.innerHTML = getClientPortalRecordIconMarkup(record.type);

  const copy = document.createElement("div");
  copy.className = "client-portal-record-card-copy";
  const title = document.createElement("strong");
  title.textContent = record.title || getClientPortalRecordTypeLabel(record.type);
  const meta = document.createElement("span");
  meta.textContent = [
    getClientPortalRecordTypeLabel(record.type),
    record.locationName || "",
    record.dueDate ? `Rok ${formatCompactDate(record.dueDate)}` : "",
    `Status: ${getClientPortalRecordStatusLabel(record.status)}`,
  ].filter(Boolean).join(" · ");
  copy.append(title, meta);

  const statusWrap = document.createElement("div");
  statusWrap.className = "client-portal-record-card-status";
  const duePill = document.createElement("span");
  duePill.className = `client-portal-record-due-pill ${dueState.className}`;
  duePill.textContent = dueState.label;
  const statusPill = document.createElement("span");
  statusPill.className = "client-portal-record-status-pill";
  statusPill.textContent = getClientPortalRecordStatusLabel(record.status);
  statusWrap.append(duePill, statusPill);

  const actions = document.createElement("div");
  actions.className = "client-portal-record-card-actions";
  if (record.type !== "training_import") {
    actions.append(createIconActionButton("Uredi", "edit", "", () => {
      openClientPortalRecordModal(record.type, record.id);
    }));
  }
  actions.append(createIconActionButton("Obriši", "trash", "card-danger", () => {
    void deleteClientPortalRecord(record.id);
  }));
  head.append(icon, copy, statusWrap, actions);

  const lines = document.createElement("div");
  lines.className = "client-portal-record-lines";
  const detailLines = getClientPortalRecordDetailLines(record);
  if (detailLines.length > 0) {
    lines.replaceChildren(...detailLines.map((line) => {
      const element = document.createElement("span");
      element.textContent = line;
      return element;
    }));
  }

  const attachments = createClientPortalRecordAttachmentChips(record);
  const workerTrainingBlock = record.type === "worker" ? createClientPortalWorkerTrainingBlock(record) : null;
  const trainingImportBlock = createClientPortalTrainingImportPreview(record);
  card.append(head, lines);
  if (workerTrainingBlock) {
    card.append(workerTrainingBlock);
  }
  if (trainingImportBlock) {
    card.append(trainingImportBlock);
  }
  if (attachments) {
    card.append(attachments);
  }
  return card;
}

function createClientPortalRecordSummaryCard(label = "", value = "0", detail = "", iconType = "worker", tone = "neutral") {
  const card = document.createElement("article");
  card.className = `client-portal-record-summary-card is-${tone}`;
  const icon = document.createElement("span");
  icon.className = "client-portal-record-summary-icon";
  icon.innerHTML = getClientPortalRecordIconMarkup(iconType);

  const copy = document.createElement("div");
  copy.className = "client-portal-record-summary-copy";
  const labelNode = document.createElement("span");
  labelNode.textContent = label;
  const valueNode = document.createElement("strong");
  valueNode.textContent = value;
  const detailNode = document.createElement("small");
  detailNode.textContent = detail;
  copy.append(labelNode, valueNode, detailNode);

  card.append(icon, copy);
  return card;
}

function createClientPortalRecordOverview(records = [], company = null) {
  const openRecords = records.filter(isClientPortalRecordOpen);
  const overdueCount = openRecords.filter((record) => {
    const days = getClientPortalRecordDaysUntilDue(record);
    return Number.isFinite(days) && days < 0;
  }).length;
  const soonCount = openRecords.filter((record) => {
    const days = getClientPortalRecordDaysUntilDue(record);
    return Number.isFinite(days) && days >= 0 && days <= 30;
  }).length;
  const workerCount = records.filter((record) => record.type === "worker").length;
  const extinguisherCount = records.filter((record) => record.type === "fire_extinguisher").length;
  const openDefectCount = records.filter((record) => record.type === "defect_report" && isClientPortalRecordOpen(record)).length;
  const internalInspectionCount = records.filter((record) => record.type === "internal_inspection").length;
  const trainingCounts = getClientPortalCompanyTrainingSummary(company?.id || getClientPortalRecordsCompanyId());
  const trainingAttentionCount = trainingCounts.expiring + trainingCounts.expired + trainingCounts.missing;
  const overview = document.createElement("div");
  overview.className = "client-portal-record-overview";
  overview.append(
    createClientPortalRecordSummaryCard("Istekli rokovi", String(overdueCount), overdueCount ? "potrebna hitna akcija" : "nema kašnjenja", "deadline", overdueCount ? "danger" : "ok"),
    createClientPortalRecordSummaryCard("Uskoro ističe", String(soonCount), "u narednih 30 dana", "deadline", soonCount ? "attention" : "ok"),
    createClientPortalRecordSummaryCard("Zaposlenici", String(workerCount), company?.name || "aktivni radnici", "worker", "worker"),
    createClientPortalRecordSummaryCard("Osposobljavanja", String(trainingCounts.records), trainingAttentionCount ? `${trainingAttentionCount} za pažnju` : "povezano s radnicima", "worker", trainingAttentionCount ? "training" : "ok"),
    createClientPortalRecordSummaryCard("Vatrogasni aparati", String(extinguisherCount), "u evidenciji", "fire_extinguisher", "fire"),
    createClientPortalRecordSummaryCard("Otvoreni nedostaci", String(openDefectCount), "za rješavanje", "defect_report", openDefectCount ? "defect" : "ok"),
    createClientPortalRecordSummaryCard("Unutarnji nadzori", String(internalInspectionCount), "nalazi i mjere", "internal_inspection", "inspection"),
  );
  return overview;
}

function createClientPortalRecordTabs(activeType = "worker", records = []) {
  const tabs = document.createElement("div");
  tabs.className = "client-portal-record-tabs";
  tabs.replaceChildren(...CLIENT_PORTAL_RECORD_TYPE_OPTIONS.map((option) => {
    const typeMeta = getClientPortalRecordTypeMeta(option.value);
    const typeRecords = records.filter((record) => String(record.type) === option.value);
    const attentionCount = typeRecords.filter((record) => isClientPortalRecordOpen(record) && isClientPortalRecordAttention(record)).length;
    const latestRecord = typeRecords[0] ?? null;
    const button = document.createElement("button");
    button.type = "button";
    button.className = `client-portal-record-tab is-${typeMeta.accent}`;
    button.dataset.clientPortalRecordTab = option.value;
    button.classList.toggle("is-active", option.value === activeType);

    const icon = document.createElement("span");
    icon.className = "client-portal-record-tab-icon";
    icon.innerHTML = getClientPortalRecordIconMarkup(option.value);
    const copy = document.createElement("span");
    copy.className = "client-portal-record-tab-copy";
    const label = document.createElement("strong");
    label.textContent = option.label;
    const meta = document.createElement("small");
    meta.textContent = [
      `${typeRecords.length} zapisa`,
      attentionCount ? `${attentionCount} za pažnju` : "",
      latestRecord?.updatedAt ? `až. ${formatCompactDate(latestRecord.updatedAt)}` : "",
    ].filter(Boolean).join(" · ");
    copy.append(label, meta);
    button.append(icon, copy);
    return button;
  }));
  return tabs;
}

function closeClientPortalRecordModal({ keepEdit = false } = {}) {
  if (!state.clientPortalRecordsUi) {
    return;
  }
  state.clientPortalRecordsUi.modalOpen = false;
  if (!keepEdit) {
    state.clientPortalRecordsUi.editId = "";
  }
  setInlineMessage(clientPortalRecordsFeedback, "");
  renderClientPortalRecordsPanel();
}

function openClientPortalRecordModal(type = "worker", editId = "") {
  state.clientPortalRecordsUi.activeType = normalizeClientPortalRecordUiType(type);
  state.clientPortalRecordsUi.editId = String(editId || "");
  state.clientPortalRecordsUi.modalOpen = true;
  setInlineMessage(clientPortalRecordsFeedback, "");
  renderClientPortalRecordsPanel();
  requestAnimationFrame(() => {
    const firstInput = clientPortalRecordsRoot?.querySelector(".client-portal-record-modal input, .client-portal-record-modal select, .client-portal-record-modal textarea");
    if (firstInput instanceof HTMLElement) {
      firstInput.focus({ preventScroll: true });
    }
  });
}

function focusClientPortalRecordType(type = "worker", { scroll = false } = {}) {
  state.clientPortalRecordsUi.activeType = normalizeClientPortalRecordUiType(type);
  state.clientPortalRecordsUi.editId = "";
  state.clientPortalRecordsUi.modalOpen = false;
  setInlineMessage(clientPortalRecordsFeedback, "");
  renderClientPortalRecordsPanel();
  if (scroll) {
    requestAnimationFrame(() => {
      clientPortalRecordsRoot
        ?.querySelector(".client-portal-record-list-section")
        ?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    });
  }
}

function createClientPortalRecordForm(activeType = "worker", editingRecord = null, companyId = "", company = null) {
  const form = document.createElement("form");
  form.className = "client-portal-record-form";
  form.dataset.clientPortalRecordForm = activeType;
  const formHead = document.createElement("div");
  formHead.className = "client-portal-record-form-head";
  const formIcon = document.createElement("span");
  formIcon.className = "client-portal-record-form-icon";
  formIcon.innerHTML = getClientPortalRecordIconMarkup(activeType);
  const formCopy = document.createElement("div");
  formCopy.className = "client-portal-record-form-copy";
  const formTitle = document.createElement("strong");
  formTitle.textContent = editingRecord
    ? `Uredi: ${editingRecord.title || getClientPortalRecordTypeLabel(activeType)}`
    : `Novi zapis: ${getClientPortalRecordTypeLabel(activeType)}`;
  const formMeta = document.createElement("span");
  formMeta.textContent = [company?.name || "Klijentska tvrtka", getClientPortalRecordTypeMeta(activeType).eyebrow].filter(Boolean).join(" · ");
  formCopy.append(formTitle, formMeta);
  formHead.append(formIcon, formCopy);

  const grid = document.createElement("div");
  grid.className = "client-portal-record-form-grid";
  grid.replaceChildren(...getClientPortalRecordFormFields(activeType, editingRecord, companyId));

  const feedback = document.createElement("p");
  feedback.className = "form-error client-portal-record-modal-feedback";
  feedback.dataset.clientPortalRecordFormFeedback = "true";
  feedback.setAttribute("aria-live", "polite");

  const actions = document.createElement("div");
  actions.className = "client-portal-record-form-actions";
  const saveButton = document.createElement("button");
  saveButton.type = "submit";
  saveButton.className = "primary-button";
  saveButton.textContent = editingRecord ? "Spremi promjene" : "Dodaj zapis";
  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "ghost-button";
  cancelButton.dataset.clientPortalRecordCancel = "true";
  cancelButton.textContent = "Zatvori";
  actions.append(saveButton, cancelButton);
  form.append(formHead, grid, feedback, actions);
  return form;
}

function createClientPortalRecordModal(activeType = "worker", editingRecord = null, companyId = "", company = null) {
  const fragment = document.createDocumentFragment();

  const backdrop = document.createElement("div");
  backdrop.className = "client-portal-record-modal-backdrop";
  backdrop.dataset.clientPortalRecordModalBackdrop = "true";

  const modal = document.createElement("section");
  modal.className = "client-portal-record-modal";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-labelledby", "client-portal-record-modal-title");

  const dialog = document.createElement("div");
  dialog.className = "panel client-portal-record-dialog";

  const head = document.createElement("div");
  head.className = "section-heading offers-section-heading client-portal-record-modal-head";
  const copy = document.createElement("div");
  const kicker = document.createElement("p");
  kicker.className = "section-kicker";
  kicker.textContent = editingRecord ? "Uređivanje evidencije" : "Novi unos";
  const title = document.createElement("h3");
  title.id = "client-portal-record-modal-title";
  title.textContent = editingRecord
    ? (editingRecord.title || getClientPortalRecordTypeLabel(activeType))
    : `Dodaj: ${getClientPortalRecordTypeLabel(activeType)}`;
  const summary = document.createElement("p");
  summary.className = "helper-copy";
  summary.textContent = [company?.name || "Odabrana tvrtka", getClientPortalRecordTypeMeta(activeType).eyebrow].filter(Boolean).join(" · ");
  copy.append(kicker, title, summary);
  const closeButton = document.createElement("button");
  closeButton.type = "button";
  closeButton.className = "ghost-button";
  closeButton.dataset.clientPortalRecordCancel = "true";
  closeButton.textContent = "Zatvori";
  head.append(copy, closeButton);

  dialog.append(head, createClientPortalRecordForm(activeType, editingRecord, companyId, company));
  modal.append(dialog);
  fragment.append(backdrop, modal);
  return fragment;
}

function createClientPortalActionCard(type = "worker", label = "", description = "") {
  const typeMeta = getClientPortalRecordTypeMeta(type);
  const button = document.createElement("button");
  button.type = "button";
  button.className = `client-portal-action-card is-${typeMeta.accent}`;
  button.addEventListener("click", () => openClientPortalRecordModal(type));
  const icon = document.createElement("span");
  icon.className = "client-portal-action-icon";
  icon.innerHTML = getClientPortalRecordIconMarkup(type);
  const title = document.createElement("strong");
  title.textContent = label || getClientPortalRecordTypeLabel(type);
  const meta = document.createElement("small");
  meta.textContent = description || typeMeta.eyebrow;
  button.append(icon, title, meta);
  return button;
}

function createClientPortalDashboardPanel(title = "", actionType = "", contentNode = null, options = {}) {
  const panel = document.createElement("section");
  panel.className = "client-portal-dashboard-panel";
  if (options.wide) {
    panel.classList.add("is-wide");
  }
  const head = document.createElement("div");
  head.className = "client-portal-dashboard-panel-head";
  const heading = document.createElement("strong");
  heading.textContent = title;
  head.append(heading);
  if (actionType) {
    const action = document.createElement("button");
    action.type = "button";
    action.className = "client-portal-dashboard-link";
    action.textContent = "Prikaži sve";
    action.addEventListener("click", () => focusClientPortalRecordType(actionType));
    head.append(action);
  }
  panel.append(head);
  if (contentNode) {
    panel.append(contentNode);
  }
  return panel;
}

function createClientPortalDashboardRow(record = {}) {
  const row = document.createElement("button");
  row.type = "button";
  row.className = `client-portal-dashboard-row is-${getClientPortalRecordTypeMeta(record.type).accent}`;
  row.addEventListener("click", () => {
    openClientPortalRecordModal(record.type, record.id);
  });
  const icon = document.createElement("span");
  icon.className = "client-portal-dashboard-row-icon";
  icon.innerHTML = getClientPortalRecordIconMarkup(record.type);
  const copy = document.createElement("span");
  copy.className = "client-portal-dashboard-row-copy";
  const title = document.createElement("strong");
  title.textContent = record.title || getClientPortalRecordTypeLabel(record.type);
  const meta = document.createElement("small");
  meta.textContent = [record.locationName, getClientPortalRecordStatusLabel(record.status)].filter(Boolean).join(" · ");
  copy.append(title, meta);
  const date = document.createElement("span");
  date.className = "client-portal-dashboard-row-date";
  date.textContent = record.dueDate ? formatCompactDate(record.dueDate) : "Bez roka";
  const dueState = getClientPortalRecordDueState(record);
  const pill = document.createElement("span");
  pill.className = `client-portal-record-due-pill ${dueState.className}`;
  pill.textContent = dueState.label;
  row.append(icon, copy, date, pill);
  return row;
}

