function renderCompanyEditorRelatedData(companyId = companyIdInput?.value || "") {
  renderCompanyWorkspaceDashboard(companyId);
  renderCompanyLinkedContractsSafe(companyId);
  renderCompanyLinkedLocationsSafe(companyId);
  renderCompanyLinkedWorkOrdersSafe(companyId);
  renderCompanyActivityPanelSafe(companyId);
}

function cancelScheduledCompanyEditorRelatedData() {
  if (companyEditorRelatedDataRafId) {
    cancelAnimationFrame(companyEditorRelatedDataRafId);
    companyEditorRelatedDataRafId = 0;
  }
  if (companyEditorRelatedDataTimeoutId) {
    window.clearTimeout(companyEditorRelatedDataTimeoutId);
    companyEditorRelatedDataTimeoutId = 0;
  }
  if (companyEditorRelatedDataIdleId) {
    if (typeof window.cancelIdleCallback === "function") {
      window.cancelIdleCallback(companyEditorRelatedDataIdleId);
    } else {
      window.clearTimeout(companyEditorRelatedDataIdleId);
    }
    companyEditorRelatedDataIdleId = 0;
  }
}

function isCompanyEditorRenderTargetActive(companyId = "") {
  return state.companyEditorOpen
    && state.activeView === "companies"
    && String(companyIdInput?.value || "").trim() === String(companyId || "").trim();
}

function scheduleCompanyEditorRelatedData(companyId = companyIdInput?.value || "", { defer = true } = {}) {
  const normalizedCompanyId = String(companyId || "").trim();
  cancelScheduledCompanyEditorRelatedData();

  const renderCompanyActivityDeferred = () => {
    if (!isCompanyEditorRenderTargetActive(normalizedCompanyId)) {
      return;
    }

    if (typeof window.requestIdleCallback === "function") {
      companyEditorRelatedDataIdleId = window.requestIdleCallback(() => {
        companyEditorRelatedDataIdleId = 0;
        if (!isCompanyEditorRenderTargetActive(normalizedCompanyId)) {
          return;
        }
        renderCompanyActivityPanelSafe(normalizedCompanyId);
      }, { timeout: COMPANY_EDITOR_ACTIVITY_IDLE_TIMEOUT_MS });
      return;
    }

    companyEditorRelatedDataIdleId = window.setTimeout(() => {
      companyEditorRelatedDataIdleId = 0;
      if (!isCompanyEditorRenderTargetActive(normalizedCompanyId)) {
        return;
      }
      renderCompanyActivityPanelSafe(normalizedCompanyId);
    }, COMPANY_EDITOR_RELATED_RENDER_DELAY_MS);
  };

  const runRender = () => {
    if (normalizedCompanyId && !isCompanyEditorRenderTargetActive(normalizedCompanyId)) {
      return;
    }
    renderCompanyWorkspaceDashboard(normalizedCompanyId);
    renderCompanyLinkedContractsSafe(normalizedCompanyId);
    renderCompanyLinkedWorkOrdersSafe(normalizedCompanyId);
    companyEditorRelatedDataTimeoutId = window.setTimeout(() => {
      companyEditorRelatedDataTimeoutId = 0;
      if (normalizedCompanyId && !isCompanyEditorRenderTargetActive(normalizedCompanyId)) {
        return;
      }
      renderCompanyLinkedLocationsSafe(normalizedCompanyId);
      renderCompanyActivityDeferred();
    }, 0);
  };

  if (!defer) {
    runRender();
    return;
  }

  companyEditorRelatedDataRafId = requestAnimationFrame(() => {
    companyEditorRelatedDataRafId = 0;
    companyEditorRelatedDataTimeoutId = window.setTimeout(() => {
      companyEditorRelatedDataTimeoutId = 0;
      runRender();
    }, COMPANY_EDITOR_RELATED_RENDER_DELAY_MS);
  });
}

function renderLocationEditorRelatedData(locationId = locationIdInput?.value || "") {
  try {
    renderLocationClientUsers(locationId);
    renderLocationLinkedWorkOrders(locationId);
  } catch (error) {
    console.error("Location related data render failed", error);
    if (locationClientUsersList) {
      locationClientUsersList.replaceChildren();
    }
    if (locationClientUsersCount) {
      locationClientUsersCount.textContent = "0";
    }
    if (locationClientUsersEmpty) {
      locationClientUsersEmpty.textContent = "Klijentske pristupe trenutno nije moguće prikazati.";
      locationClientUsersEmpty.hidden = false;
    }
    if (locationLinkedWorkOrdersList) {
      locationLinkedWorkOrdersList.replaceChildren();
    }
    if (locationLinkedWorkOrdersCount) {
      locationLinkedWorkOrdersCount.textContent = "0";
    }
    if (locationLinkedWorkOrdersEmpty) {
      locationLinkedWorkOrdersEmpty.textContent = "Povezane RN-ove trenutno nije moguće prikazati.";
      locationLinkedWorkOrdersEmpty.hidden = false;
    }
  }
}

function createEmptyLocationContactDraft() {
  return {
    name: "",
    phone: "",
    email: "",
  };
}

function sanitizeLocationContactDrafts(contacts = [], { ensureOne = false } = {}) {
  const drafts = Array.isArray(contacts)
    ? contacts.map((contact) => ({
      name: String(contact?.name ?? "").trim(),
      phone: String(contact?.phone ?? "").trim(),
      email: String(contact?.email ?? "").trim(),
    }))
    : [];

  if (ensureOne && drafts.length === 0) {
    return [createEmptyLocationContactDraft()];
  }

  return drafts;
}

function setLocationFormContacts(contacts = [], { ensureOne = false } = {}) {
  locationFormContacts = sanitizeLocationContactDrafts(contacts, { ensureOne });
  renderLocationContactCards();
}

function updateLocationFormContact(index, key, value) {
  if (!locationFormContacts[index]) {
    return;
  }

  locationFormContacts[index][key] = value;
}

function addLocationFormContact(contact = createEmptyLocationContactDraft()) {
  locationFormContacts = [
    ...locationFormContacts,
    {
      name: String(contact?.name ?? "").trim(),
      phone: String(contact?.phone ?? "").trim(),
      email: String(contact?.email ?? "").trim(),
    },
  ];
  renderLocationContactCards();
}

function removeLocationFormContact(index) {
  locationFormContacts = locationFormContacts.filter((_, contactIndex) => contactIndex !== index);

  if (locationFormContacts.length === 0) {
    locationFormContacts = [createEmptyLocationContactDraft()];
  }

  renderLocationContactCards();
}

function renderLocationContactCards() {
  if (!locationContactsList) {
    return;
  }

  if (locationFormContacts.length === 0) {
    locationContactsList.replaceChildren();
    return;
  }

  locationContactsList.replaceChildren(...locationFormContacts.map((contact, index) => {
    const card = document.createElement("fieldset");
    card.className = "contact-card";

    const header = document.createElement("div");
    header.className = "contact-card-header";

    const heading = document.createElement("div");
    heading.className = "contact-card-heading";

    const title = document.createElement("span");
    title.className = "contact-card-title";
    title.textContent = `Kontakt ${index + 1}`;

    const subtitle = document.createElement("span");
    subtitle.className = "contact-card-index";
    subtitle.textContent = "Ime, broj i email";

    heading.append(title, subtitle);

    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "contact-card-remove";
    removeButton.textContent = "Ukloni";
    removeButton.disabled = locationFormContacts.length === 1;
    removeButton.addEventListener("click", () => removeLocationFormContact(index));

    header.append(heading, removeButton);

    const createInputField = (labelText, key, type = "text", maxLength = "160") => {
      const label = document.createElement("label");
      label.className = "field";

      const span = document.createElement("span");
      span.textContent = labelText;

      const input = document.createElement("input");
      input.type = type;
      input.maxLength = Number(maxLength);
      input.value = contact[key] ?? "";
      input.addEventListener("input", (event) => {
        updateLocationFormContact(index, key, event.currentTarget.value);
      });

      label.append(span, input);
      return label;
    };

    card.append(
      header,
      createInputField("Ime", "name"),
      createInputField("Broj", "phone", "text", "80"),
      createInputField("Email", "email", "email"),
    );

    return card;
  }));
}

