function hydrateCompanyForm(company) {
  if (!getCanEditCompany(company?.id || "")) {
    return;
  }

  const shouldSwitchToCompaniesView = state.activeView !== "companies";
  if (shouldSwitchToCompaniesView) {
    state.activeView = "companies";
    renderActiveView();
  }
  companyIdInput.value = company.id;
  if (companyLogoDataUrlInput) {
    companyLogoDataUrlInput.value = company.logoDataUrl || "";
  }
  if (companyLogoFileInput) {
    companyLogoFileInput.value = "";
  }
  companyNameInput.value = company.name;
  companyHeadquartersInput.value = company.headquarters;
  companyOibInput.value = company.oib;
  if (companyMbsInput) {
    companyMbsInput.value = company.mbs || "";
  }
  if (companyNkdActivityInput) {
    companyNkdActivityInput.value = company.nkdActivity || "";
  }
  if (companyContractNameInput) {
    companyContractNameInput.value = company.contractName || "";
  }
  companyContractTypeInput.value = normalizeCompanyContractType(company.contractType || "");
  companyContractNumberInput.value = company.contractNumber;
  if (companyContractValidFromInput) {
    companyContractValidFromInput.value = normalizeCompanyDateValue(company.contractValidFrom || "");
  }
  if (companyContractValidForeverInput) {
    companyContractValidForeverInput.checked = Boolean(company.contractValidForever);
  }
  if (companyContractValidToInput) {
    companyContractValidToInput.value = normalizeCompanyDateValue(company.contractValidTo || "");
  }
  if (companyContractMonthlyPriceInput) {
    companyContractMonthlyPriceInput.value = company.contractMonthlyPrice || "";
  }
  setCompanyContractPriceListDraft(company.contractPriceList || []);
  syncCompanyContractValidityControls();
  syncCompanyEmployeeSizeInput(company.employeeSize || "");
  if (companyClientRiskJobInputEnabledInput) {
    companyClientRiskJobInputEnabledInput.checked = Boolean(company.riskAssessmentClientJobInputEnabled);
  }
  rebuildCompanyManagerUserOptions(Array.isArray(company.managerUserIds) ? company.managerUserIds : []);
  renderCompanyTemplateAssignments(company.templateAssignments ?? []);
  hydrateCompanyTrainingImportProfile(company.isznrTraining?.importProfile);
  writeCompanyIsznrTrainingDraft(company.isznrTraining ?? { source: "internal" });
  companyPeriodInput.value = company.period;
  companyIsActiveInput.value = String(company.isActive);
  companyRepresentativeInput.value = company.representative;
  if (companyRepresentativeRoleInput) {
    companyRepresentativeRoleInput.value = company.representativeRole || "";
  }
  if (companyRepresentativeOibInput) {
    companyRepresentativeOibInput.value = company.representativeOib || "";
  }
  companyContactPhoneInput.value = company.contactPhone;
  companyContactEmailInput.value = company.contactEmail;
  companyNoteInput.value = company.note;
  companyError.textContent = "";
  if (companyEditorTitle) {
    companyEditorTitle.textContent = "Company workspace";
  }
  state.companyEditorActiveTab = "overview";
  state.companyOverviewEditMode = false;
  state.companyWorkOrderFilters = {
    query: "",
    status: "all",
    sort: "newest",
  };
  resetCompanyClientUserForm();
  renderCompanyClientPortalPanel();
  renderCompanyWorkspaceDashboard(company.id);
  syncCompanyEditorChrome();
  openCompanyEditor();
  scheduleCompanyEditorRelatedData(company.id, { defer: true });
}

