function buildAbsenceNotifications() {
  const notificationSettings = getAbsenceNotificationSettings();
  const leadDaysBeforeStart = notificationSettings.leadDaysBeforeStart;
  const repeatEveryDays = notificationSettings.repeatEveryDays;
  const todayDate = new Date();
  todayDate.setHours(0, 0, 0, 0);

  const getDaysUntil = (value) => {
    const targetDate = parseDateValue(value);
    if (!targetDate) {
      return null;
    }

    targetDate.setHours(0, 0, 0, 0);
    const deltaMs = targetDate.getTime() - todayDate.getTime();
    return Math.round(deltaMs / (1000 * 60 * 60 * 24));
  };

  const shouldSend = (daysUntilStart) => {
    if (!Number.isFinite(daysUntilStart) || daysUntilStart < 0 || daysUntilStart > leadDaysBeforeStart) {
      return false;
    }

    if (daysUntilStart === 0 || daysUntilStart === leadDaysBeforeStart) {
      return true;
    }

    return ((leadDaysBeforeStart - daysUntilStart) % repeatEveryDays) === 0;
  };

  const pendingApprovalNotifications = getCanManageMasterData()
    ? (state.absenceEntries ?? [])
      .filter((entry) => (
        String(entry?.status || "").trim().toLowerCase() === "pending"
        && doesAbsenceTypeRequireApproval(entry?.type)
      ))
      .map((entry) => ({
        id: `absence-pending-${entry.id}`,
        kind: "absence",
        level: "warning",
        title: "Zahtjev za odsutnost čeka odobrenje",
        message: entry.userLabel || "Korisnik",
        context: [
          getAbsenceTypeLabelClient(entry.type),
          entry.startDate
            ? (entry.endDate && entry.endDate !== entry.startDate
              ? `${formatCompactDate(entry.startDate)} - ${formatCompactDate(entry.endDate)}`
              : formatCompactDate(entry.startDate))
            : "",
        ].filter(Boolean).join(" · "),
        dueDate: entry.startDate || "",
        referenceId: String(entry.id || ""),
      }))
    : [];

  const upcomingApprovedNotifications = getApprovedAbsenceEntries()
    .map((entry) => {
      const startDate = String(entry.startDate || "").trim();
      if (!startDate) {
        return null;
      }

      const daysUntilStart = getDaysUntil(startDate);
      if (!shouldSend(daysUntilStart)) {
        return null;
      }

      return {
        id: `absence-start-${entry.id}-${startDate}`,
        kind: "absence",
        level: daysUntilStart === 0 ? "warning" : "info",
        title: daysUntilStart === 0 ? "Odsutnost počinje danas" : "Odsutnost uskoro počinje",
        message: entry.userLabel || "Korisnik",
        context: [
          getAbsenceTypeLabelClient(entry.type),
          entry.endDate && entry.endDate !== startDate
            ? `${formatCompactDate(startDate)} - ${formatCompactDate(entry.endDate)}`
            : formatCompactDate(startDate),
        ].filter(Boolean).join(" · "),
        dueDate: startDate,
        referenceId: String(entry.id || ""),
      };
    })
    .filter(Boolean);

  return [
    ...pendingApprovalNotifications,
    ...upcomingApprovedNotifications,
  ];
}

function buildVehicleNotifications() {
  const notificationSettings = getVehicleNotificationSettings();
  const todayDate = new Date();
  todayDate.setHours(0, 0, 0, 0);

  const getDaysUntil = (value) => {
    const targetDate = parseDateValue(value);
    if (!targetDate) {
      return null;
    }

    targetDate.setHours(0, 0, 0, 0);
    const deltaMs = targetDate.getTime() - todayDate.getTime();
    return Math.round(deltaMs / (1000 * 60 * 60 * 24));
  };

  const shouldSend = (daysUntilDue, leadDaysBeforeExpiry, repeatEveryDays) => {
    if (!Number.isFinite(daysUntilDue)) {
      return false;
    }

    if (daysUntilDue >= 0) {
      if (daysUntilDue > leadDaysBeforeExpiry) {
        return false;
      }
      if (daysUntilDue === 0 || daysUntilDue === leadDaysBeforeExpiry) {
        return true;
      }
      return ((leadDaysBeforeExpiry - daysUntilDue) % repeatEveryDays) === 0;
    }

    const overdueDays = Math.abs(daysUntilDue);
    if (overdueDays === 1) {
      return true;
    }
    return (overdueDays % repeatEveryDays) === 0;
  };

  const registrationNotifications = (state.vehicles ?? [])
    .map((vehicle) => {
      const dueDate = String(vehicle?.registrationExpiresOn || "");
      if (!dueDate) {
        return null;
      }

      const daysUntilDue = getDaysUntil(dueDate);
      if (!shouldSend(
        daysUntilDue,
        notificationSettings.registrationLeadDaysBeforeExpiry,
        notificationSettings.registrationRepeatEveryDays,
      )) {
        return null;
      }

      let level = "warning";
      let title = "Registracija uskoro istice";
      if (Number.isFinite(daysUntilDue) && daysUntilDue < 0) {
        level = "critical";
        title = "Registracija je istekla";
      } else if (daysUntilDue === 0) {
        title = "Registracija istice danas";
      }

      return {
        id: `vehicle-registration-${vehicle.id}-${dueDate}`,
        kind: "vehicle",
        level,
        title,
        message: vehicle.name || vehicle.plateNumber || "Vozilo",
        context: [
          vehicle.plateNumber || "",
          vehicle.vinNumber ? `Sasija ${vehicle.vinNumber}` : "",
        ].filter(Boolean).join(" · ") || "Vozilo",
        dueDate,
        referenceId: String(vehicle.id || ""),
      };
    })
    .filter(Boolean);

  const tireNotifications = (state.vehicles ?? [])
    .map((vehicle) => {
      const tireActivity = [...(vehicle.activityItems ?? [])]
        .filter((entry) => (
          String(entry?.activityType || "").trim().toLowerCase() === "tires"
          && String(entry?.validUntil || "").trim()
        ))
        .sort(compareVehicleActivityDraftRecency)[0];
      const dueDate = String(tireActivity?.validUntil || "");
      if (!dueDate) {
        return null;
      }

      const daysUntilDue = getDaysUntil(dueDate);
      if (!shouldSend(
        daysUntilDue,
        notificationSettings.tireLeadDaysBeforeDue,
        notificationSettings.tireRepeatEveryDays,
      )) {
        return null;
      }

      let level = "warning";
      let title = "Promjena guma uskoro";
      if (Number.isFinite(daysUntilDue) && daysUntilDue < 0) {
        level = "critical";
        title = "Promjena guma kasni";
      } else if (daysUntilDue === 0) {
        title = "Promjena guma je danas";
      }

      return {
        id: `vehicle-tires-${vehicle.id}-${dueDate}`,
        kind: "vehicle",
        level,
        title,
        message: vehicle.name || vehicle.plateNumber || "Vozilo",
        context: [
          vehicle.plateNumber || "",
          tireActivity?.performedBy ? `Zadnje: ${tireActivity.performedBy}` : "",
        ].filter(Boolean).join(" · ") || "Vozilo",
        dueDate,
        referenceId: String(vehicle.id || ""),
      };
    })
    .filter(Boolean);

  return [
    ...registrationNotifications,
    ...tireNotifications,
  ];
}

function isTodoCommentFromCurrentUser(comment = {}) {
  const currentUserId = String(state.user?.id ?? "").trim();
  const normalizeLabel = (value) => String(value ?? "")
    .trim()
    .replace(/\s+/g, " ")
    .toLowerCase();
  const currentAuthorLabel = normalizeLabel(
    state.user?.fullName || state.user?.username || state.user?.email || "",
  );
  const commentUserId = String(comment.userId ?? "").trim();
  const commentAuthorLabel = normalizeLabel(comment.authorLabel || "");

  if (currentUserId && commentUserId) {
    return currentUserId === commentUserId;
  }

  if (currentAuthorLabel && commentAuthorLabel) {
    return currentAuthorLabel === commentAuthorLabel;
  }

  return false;
}

function buildTodoCommentNotifications() {
  if (!state.user) {
    return [];
  }

  return (state.todoTasks ?? [])
    .map((task) => {
      const comments = Array.isArray(task?.comments) ? task.comments : [];
      const externalComments = comments.filter((comment) => !isTodoCommentFromCurrentUser(comment));
      if (externalComments.length === 0) {
        return null;
      }

      const latestComment = externalComments
        .slice()
        .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))[0];

      if (!latestComment) {
        return null;
      }

      const createdAt = String(latestComment.createdAt || "");
      const createdAtDate = createdAt.slice(0, 10);
      const commentText = String(latestComment.message || "").replace(/\s+/g, " ").trim();

      return {
        id: `todo-comment-${task.id}-${latestComment.id || createdAt || externalComments.length}`,
        kind: "todo_comment",
        level: "info",
        title: task.title || "ToDo tema",
        message: `${latestComment.authorLabel || "Kolega"}: ${commentText || "Dodan je komentar."}`,
        context: [
          task.workOrderNumber ? `RN ${task.workOrderNumber}` : "",
          task.companyName || "",
          createdAt ? `Komentar ${formatDateTime(createdAt)}` : "",
        ].filter(Boolean).join(" · "),
        dueDate: createdAtDate,
        referenceId: String(task.id || ""),
      };
    })
    .filter(Boolean);
}

function buildDocumentSignatureNotifications() {
  if (!state.user) {
    return [];
  }

  const currentUser = state.users.find((item) => String(item?.id || "") === String(state.user?.id || ""))
    ?? state.user
    ?? {};
  const identityTerms = [
    currentUser.oib,
    currentUser.email,
    currentUser.fullName,
    [currentUser.firstName, currentUser.lastName].filter(Boolean).join(" "),
  ]
    .map((value) => normalizeLooseName(value || ""))
    .filter((value) => value.length >= 4);
  if (identityTerms.length === 0) {
    return [];
  }

  return (Array.isArray(state.documentsExplorer.workOrderDocuments) ? state.documentsExplorer.workOrderDocuments : [])
    .map((documentItem) => {
      const description = String(documentItem?.description || "");
      if (!isGeneratedDocumentSigned(documentItem)) {
        return null;
      }

      const normalizedDescription = normalizeLooseName(description);
      if (!identityTerms.some((term) => normalizedDescription.includes(term))) {
        return null;
      }

      const workOrder = findWorkOrderById(documentItem.workOrderId || "");
      const workOrderNumber = workOrder?.workOrderNumber || documentItem.workOrderNumber || "";
      return {
        id: `document-signature-${documentItem.id || documentItem.workOrderId || documentItem.fileName}`,
        kind: "document_signature",
        level: "info",
        title: "Potpisano",
        message: `${documentItem.fileName || "Zapisnik"} je potpisan.`,
        context: [
          workOrderNumber ? `RN ${workOrderNumber}` : "",
          workOrder?.companyName || "",
          documentItem.updatedAt ? `Spremljeno ${formatDateTime(documentItem.updatedAt)}` : "",
        ].filter(Boolean).join(" · "),
        dueDate: String(documentItem.updatedAt || documentItem.createdAt || "").slice(0, 10),
        referenceId: String(documentItem.workOrderId || ""),
      };
    })
    .filter(Boolean);
}

function buildSignupRequestNotifications() {
  if (!getCanManageMasterData()) {
    return [];
  }

  return (state.signupRequests ?? [])
    .filter((request) => String(request?.status || "").trim().toLowerCase() === "pending")
    .map((request) => ({
      id: `signup-request-${request.id}`,
      kind: "signup_request",
      level: "warning",
      title: "Novi zahtjev za pristup",
      message: request.fullName || [request.firstName, request.lastName].filter(Boolean).join(" ") || request.email || "Novi korisnik",
      context: [
        getSignupRequestOrganizationLabel(request),
        request.organizationOib ? `OIB ${request.organizationOib}` : "",
        request.email || "",
      ].filter(Boolean).join(" · "),
      dueDate: String(request.requestedAt || "").slice(0, 10) || new Date().toISOString().slice(0, 10),
      referenceId: String(request.id || ""),
    }));
}

function getPendingReminderNotificationCount() {
  return getPersonalReminders().filter((item) => getReminderStatusValue(item) !== "done").length;
}

function getPendingTodoNotificationCount() {
  return (state.todoTasks ?? []).filter((item) => getTodoTaskStatusValue(item) !== "done").length;
}

function createTopbarShortcutPreviewRow({
  title = "",
  subtitle = "",
  meta = "",
  onOpen = null,
} = {}) {
  const row = document.createElement("button");
  row.type = "button";
  row.className = "topbar-shortcut-preview-row";
  row.title = subtitle || title;

  const copy = document.createElement("div");
  copy.className = "topbar-shortcut-preview-copy";

  const titleEl = document.createElement("strong");
  titleEl.textContent = title || "Stavka";

  const subtitleEl = document.createElement("span");
  subtitleEl.textContent = subtitle || "";

  copy.append(titleEl, subtitleEl);

  const metaEl = document.createElement("span");
  metaEl.className = "topbar-shortcut-preview-meta";
  metaEl.textContent = meta || "";

  row.append(copy, metaEl);

  if (typeof onOpen === "function") {
    row.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      onOpen();
    });
  }

  return row;
}

function getTopbarActiveReminderItems() {
  return sortReminders(getPersonalReminders().filter((item) => getReminderStatusValue(item) !== "done"))
    .slice(0, 6);
}

function getTopbarActiveTodoItems() {
  return sortTodoTasks((state.todoTasks ?? []).filter((item) => getTodoTaskStatusValue(item) !== "done"))
    .slice(0, 6);
}

function renderTopbarRemindersPanel() {
  if (!topbarRemindersPanelList || !topbarRemindersPanelEmpty) {
    return;
  }

  const reminders = getTopbarActiveReminderItems();

  if (topbarRemindersPanelMeta) {
    topbarRemindersPanelMeta.textContent = reminders.length > 0
      ? `${reminders.length} aktivnih remindersa`
      : "Nema aktivnih remindersa.";
  }

  if (topbarRemindersOpenAllButton) {
    topbarRemindersOpenAllButton.disabled = getPersonalReminders().length === 0;
  }

  topbarRemindersPanelList.replaceChildren(...reminders.map((reminder) => createTopbarShortcutPreviewRow({
    title: reminder.title || "Reminder",
    subtitle: [
      reminder.workOrderNumber ? `RN ${reminder.workOrderNumber}` : "",
      reminder.companyName || "",
    ].filter(Boolean).join(" · ") || "Opći reminder",
    meta: reminder.dueDate ? `Rok ${formatCompactDate(reminder.dueDate)}` : "Bez datuma",
    onOpen: () => {
      setRemindersShortcutMenuOpen(false);
      hydrateReminderForm(reminder);
    },
  })));

  topbarRemindersPanelEmpty.hidden = reminders.length !== 0;
}

function renderTopbarTodoPanel() {
  if (!topbarTodoPanelList || !topbarTodoPanelEmpty) {
    return;
  }

  const tasks = getTopbarActiveTodoItems();

  if (topbarTodoPanelMeta) {
    topbarTodoPanelMeta.textContent = tasks.length > 0
      ? `${tasks.length} otvorenih tema`
      : "Nema aktivnih ToDo zadataka.";
  }

  if (topbarTodoOpenAllButton) {
    topbarTodoOpenAllButton.disabled = (state.todoTasks ?? []).length === 0;
  }

  topbarTodoPanelList.replaceChildren(...tasks.map((task) => createTopbarShortcutPreviewRow({
    title: task.title || "ToDo tema",
    subtitle: task.companyName || task.workOrderNumber
      ? [task.workOrderNumber ? `RN ${task.workOrderNumber}` : "", task.companyName || ""].filter(Boolean).join(" · ")
      : "Bez vezanog RN-a",
    meta: task.dueDate ? `Rok ${formatCompactDate(task.dueDate)}` : getOptionLabel(PRIORITY_OPTIONS, task.priority || "Normal"),
    onOpen: () => {
      setTodoShortcutMenuOpen(false);
      hydrateTodoTaskForm(task);
    },
  })));

  topbarTodoPanelEmpty.hidden = tasks.length !== 0;
}

function renderTopbarShortcutCounts() {
  const reminderCount = getPendingReminderNotificationCount();
  const todoCount = getPendingTodoNotificationCount();

  if (topbarShortcutRemindersCount) {
    topbarShortcutRemindersCount.hidden = reminderCount === 0;
    topbarShortcutRemindersCount.textContent = reminderCount > 99 ? "99+" : String(reminderCount);
  }

  if (topbarShortcutTodoCount) {
    topbarShortcutTodoCount.hidden = todoCount === 0;
    topbarShortcutTodoCount.textContent = todoCount > 99 ? "99+" : String(todoCount);
    topbarShortcutTodoButton?.classList.toggle("has-unread", todoCount > 0);
  }

  topbarShortcutRemindersButton?.classList.toggle("has-unread", reminderCount > 0);
  renderTopbarRemindersPanel();
  renderTopbarTodoPanel();
}

function getAllNotifications() {
  return [
    ...buildReminderNotifications(),
    ...buildPublicProcurementNotifications(),
    ...buildMeasurementEquipmentNotifications(),
    ...buildSafetyAuthorizationNotifications(),
    ...buildAbsenceNotifications(),
    ...buildVehicleNotifications(),
    ...buildTodoCommentNotifications(),
    ...buildDocumentSignatureNotifications(),
    ...buildSignupRequestNotifications(),
  ].map((entry) => ({
    ...entry,
    resolved: isNotificationResolved(entry.id),
  })).sort((left, right) => {
    const levelDelta = getNotificationLevelPriority(left.level) - getNotificationLevelPriority(right.level);
    if (levelDelta !== 0) {
      return levelDelta;
    }

    const leftDate = parseDateValue(left.dueDate)?.getTime() ?? Number.MAX_SAFE_INTEGER;
    const rightDate = parseDateValue(right.dueDate)?.getTime() ?? Number.MAX_SAFE_INTEGER;
    if (leftDate !== rightDate) {
      return leftDate - rightDate;
    }

    return String(left.message || left.title || "").localeCompare(String(right.message || right.title || ""), "hr");
  });
}

function getFilteredNotifications(source = getAllNotifications()) {
  const query = String(notificationsSearchInput?.value || "").trim().toLowerCase();
  const kind = String(notificationsFilterKindInput?.value || "all").trim().toLowerCase();
  const level = String(notificationsFilterLevelInput?.value || "all").trim().toLowerCase();
  const viewState = String(notificationsFilterStateInput?.value || "active").trim().toLowerCase();

  return source.filter((entry) => {
    if (kind !== "all" && String(entry.kind || "").toLowerCase() !== kind) {
      return false;
    }
    if (level !== "all" && String(entry.level || "").toLowerCase() !== level) {
      return false;
    }
    if (viewState === "active" && entry.resolved) {
      return false;
    }
    if (viewState === "resolved" && !entry.resolved) {
      return false;
    }
    if (!query) {
      return true;
    }

    const haystack = [
      entry.title,
      entry.message,
      entry.context,
      entry.dueDate ? formatCompactDate(entry.dueDate) : "",
    ].join(" ").toLowerCase();
    return haystack.includes(query);
  });
}

function getTopbarNotificationItems(items = getAllNotifications()) {
  return items.filter((item) => item.kind === "reminder");
}

function openNotificationEntry(entry) {
  if (!entry) {
    return;
  }

  if (entry.kind === "reminder") {
    const reminder = getReminderById(entry.referenceId);
    if (reminder) {
      hydrateReminderForm(reminder);
      return;
    }
    activateSidebarItem("reminders", { expandSidebar: state.sidebarCollapsed });
    return;
  }

  if (entry.kind === "public_procurement") {
    activateSidebarItem("public-procurement", { expandSidebar: state.sidebarCollapsed });
    const procurement = (state.publicProcurements ?? []).find((item) => String(item.id) === String(entry.referenceId)) ?? null;
    if (procurement && getCanEditPublicProcurements()) {
      window.requestAnimationFrame(() => {
        hydratePublicProcurementForm(procurement);
        openPublicProcurementEditor();
      });
    }
    return;
  }

  if (entry.kind === "equipment") {
    activateSidebarItem("measurement-equipment", { expandSidebar: state.sidebarCollapsed });
    const equipment = state.measurementEquipment.find((item) => String(item.id) === String(entry.referenceId)) ?? null;
    if (equipment && getCanManageMasterData()) {
      window.requestAnimationFrame(() => {
        hydrateMeasurementEquipmentForm(equipment);
      });
    }
    return;
  }

  if (entry.kind === "authorization") {
    activateSidebarItem("safety-authorization", { expandSidebar: state.sidebarCollapsed });
    const authorization = state.safetyAuthorizations.find((item) => String(item.id) === String(entry.referenceId)) ?? null;
    if (authorization && getCanManageMasterData()) {
      window.requestAnimationFrame(() => {
        hydrateSafetyAuthorizationForm(authorization);
      });
    }
    return;
  }

  if (entry.kind === "absence") {
    const absenceEntry = (state.absenceEntries ?? []).find((item) => String(item.id) === String(entry.referenceId)) ?? null;
    const targetModule = ABSENCE_MEDICAL_TYPE_OPTIONS.some((option) => option.value === absenceEntry?.type)
      ? "sick-leave"
      : "annual-leave";
    activateSidebarItem(targetModule, { expandSidebar: state.sidebarCollapsed });
    if (absenceEntry) {
      window.requestAnimationFrame(() => {
        hydrateAbsenceForm(absenceEntry);
      });
    }
    return;
  }

  if (entry.kind === "vehicle") {
    activateSidebarItem("vehicles", { expandSidebar: state.sidebarCollapsed });
    const vehicle = state.vehicles.find((item) => String(item.id) === String(entry.referenceId)) ?? null;
    if (vehicle && getCanManageMasterData()) {
      window.requestAnimationFrame(() => {
        hydrateVehicleForm(vehicle);
      });
    }
    return;
  }

  if (entry.kind === "todo_comment") {
    activateSidebarItem("todo", { expandSidebar: state.sidebarCollapsed });
    const task = getTodoTaskById(entry.referenceId);
    if (task) {
      window.requestAnimationFrame(() => {
        setTodoTaskExpanded(task.id, true);
        selectTodoTask(task.id);
      });
    }
    return;
  }

  if (entry.kind === "signup_request") {
    activateSidebarItem("control-panel", { expandSidebar: state.sidebarCollapsed });
    window.requestAnimationFrame(() => {
      renderDashboardSignupRequestsPanel();
      dashboardSignupRequestsPanel?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
    return;
  }

  if (entry.kind === "document_signature") {
    activateSidebarItem("documents", { expandSidebar: state.sidebarCollapsed });
    state.documentsExplorer.category = "document-records";
    state.documentsExplorer.expandedFolderIds = new Set();
    state.documentsExplorer.suppressDefaultExpansion = false;
    void loadDocumentsExplorerRecords({ force: false }).then(() => renderDocumentsModule());
  }
}

function createNotificationRow(entry, { compact = false } = {}) {
  const row = document.createElement("article");
  row.className = `notification-row is-${entry.level || "info"}${compact ? " is-compact" : ""}${entry.resolved ? " is-resolved" : ""}`;
  row.tabIndex = 0;
  row.setAttribute("role", "button");
  row.addEventListener("click", () => {
    openNotificationEntry(entry);
    if (compact) {
      setNotificationsMenuOpen(false);
    }
  });
  row.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }
    event.preventDefault();
    openNotificationEntry(entry);
    if (compact) {
      setNotificationsMenuOpen(false);
    }
  });

  const marker = document.createElement("span");
  marker.className = `notification-row-marker is-${entry.level || "info"}${entry.resolved ? " is-resolved" : ""}`;
  marker.setAttribute("aria-hidden", "true");

  const copy = document.createElement("div");
  copy.className = "notification-row-copy";

  const top = document.createElement("div");
  top.className = "notification-row-top";
  const title = document.createElement("strong");
  title.textContent = entry.title || "Notifikacija";

  const badges = document.createElement("div");
  badges.className = "notification-row-badges";
  badges.append(
    createBadge(getNotificationKindLabel(entry.kind), "service-catalog-template-badge"),
    createBadge(getNotificationLevelLabel(entry.level), `notification-level-badge is-${entry.level || "info"}`),
    createBadge(entry.resolved ? "Riješeno" : "Aktivno", `notification-row-status-badge${entry.resolved ? " is-resolved" : " is-active"}`),
  );
  top.append(title, badges);

  const message = document.createElement("p");
  message.className = "notification-row-message";
  message.textContent = entry.message || "Bez naslova";

  const meta = document.createElement("p");
  meta.className = "notification-row-meta";
  meta.textContent = [
    entry.context || "",
    entry.dueDate ? `Rok: ${formatCompactDate(entry.dueDate)}` : "",
  ].filter(Boolean).join(" · ");

  copy.append(top, message, meta);

  const actions = document.createElement("div");
  actions.className = "notification-row-actions";
  const toggleResolvedButton = document.createElement("button");
  toggleResolvedButton.type = "button";
  toggleResolvedButton.className = "ghost-button notification-inline-action";
  toggleResolvedButton.textContent = entry.resolved ? "Vrati aktivno" : "Riješeno";
  toggleResolvedButton.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    setNotificationResolvedState(entry.id, !entry.resolved);
    renderNotifications();
  });
  actions.append(toggleResolvedButton);

  row.append(marker, copy, actions);
  return row;
}

function renderNotificationsPanel(items = getAllNotifications()) {
  const activeItems = getTopbarNotificationItems(items).filter((item) => !item.resolved);
  const count = activeItems.length;

  if (notificationsTriggerCount) {
    notificationsTriggerCount.hidden = count === 0;
    notificationsTriggerCount.textContent = count > 99 ? "99+" : String(count);
  }
  if (notificationsTrigger) {
    notificationsTrigger.classList.toggle("has-unread", count > 0);
  }
  if (notificationsPanelMeta) {
    notificationsPanelMeta.textContent = count > 0
      ? `${count} aktivnih remindera`
      : "Nema novih remindera.";
  }
  if (notificationsPanelOpenAllButton) {
    notificationsPanelOpenAllButton.disabled = count === 0;
  }
  if (!notificationsPanelList || !notificationsPanelEmpty) {
    return;
  }

  const previewItems = activeItems.slice(0, 6);
  notificationsPanelList.replaceChildren(...previewItems.map((entry) => createNotificationRow(entry, { compact: true })));
  notificationsPanelEmpty.hidden = previewItems.length !== 0;
}

function renderNotificationsView(items = getAllNotifications()) {
  if (!notificationsBody || !notificationsEmpty) {
    return;
  }

  const filtered = getFilteredNotifications(items);
  notificationsBody.replaceChildren(...filtered.map((entry) => createNotificationRow(entry)));
  notificationsEmpty.hidden = filtered.length !== 0;
}

function renderNotifications() {
  if (!state.user) {
    if (topbarShortcutRemindersCount) {
      topbarShortcutRemindersCount.hidden = true;
      topbarShortcutRemindersCount.textContent = "0";
    }
    if (topbarShortcutTodoCount) {
      topbarShortcutTodoCount.hidden = true;
      topbarShortcutTodoCount.textContent = "0";
    }
    if (notificationsTriggerCount) {
      notificationsTriggerCount.hidden = true;
      notificationsTriggerCount.textContent = "0";
    }
    notificationsTrigger?.classList.remove("has-unread");
    topbarShortcutRemindersButton?.classList.remove("has-unread", "is-open");
    topbarShortcutTodoButton?.classList.remove("has-unread", "is-open");
    notificationsPanelList?.replaceChildren();
    topbarRemindersPanelList?.replaceChildren();
    topbarTodoPanelList?.replaceChildren();
    if (notificationsPanelMeta) {
      notificationsPanelMeta.textContent = "Nema novih stavki.";
    }
    if (topbarRemindersPanelMeta) {
      topbarRemindersPanelMeta.textContent = "Nema aktivnih remindersa.";
    }
    if (topbarTodoPanelMeta) {
      topbarTodoPanelMeta.textContent = "Nema aktivnih ToDo zadataka.";
    }
    if (topbarRemindersPanelEmpty) {
      topbarRemindersPanelEmpty.hidden = false;
    }
    if (topbarTodoPanelEmpty) {
      topbarTodoPanelEmpty.hidden = false;
    }
    if (topbarRemindersOpenAllButton) {
      topbarRemindersOpenAllButton.disabled = true;
    }
    if (topbarTodoOpenAllButton) {
      topbarTodoOpenAllButton.disabled = true;
    }
    setRemindersShortcutMenuOpen(false);
    setTodoShortcutMenuOpen(false);
    notificationsBody?.replaceChildren();
    return;
  }

  renderTopbarShortcutCounts();
  const items = getAllNotifications();
  renderNotificationsPanel(items);
  renderNotificationsView(items);
}

function getFilteredReminders() {
  return sortReminders(filterReminders(getPersonalReminders(), {
    query: remindersSearchInput?.value ?? "",
    status: remindersFilterStatusInput?.value ?? "all",
  }));
}

function rebuildReminderWorkOrderOptions(selectedValue = "") {
  if (!reminderWorkOrderIdInput) {
    return;
  }

  const options = [
    { value: "", label: "Bez vezanog RN" },
    ...sortWorkOrders(state.workOrders).map((item) => ({
      value: item.id,
      label: `${item.workOrderNumber} · ${item.companyName || item.locationName || "RN"}`,
    })),
  ];

  replaceSelectOptions(reminderWorkOrderIdInput, options, selectedValue || "");
}

function rebuildReminderCompanyOptions(selectedValue = "") {
  if (!reminderCompanyIdInput) {
    return;
  }

  const options = [
    { value: "", label: "Opci reminder" },
    ...state.companies
      .slice()
      .sort((left, right) => left.name.localeCompare(right.name, "hr"))
      .map((company) => ({
        value: company.id,
        label: company.name,
      })),
  ];

  replaceSelectOptions(reminderCompanyIdInput, options, selectedValue || "");
}

function syncReminderContextFromWorkOrder() {
  const linkedWorkOrder = state.workOrders.find((item) => item.id === reminderWorkOrderIdInput?.value);

  if (linkedWorkOrder && reminderCompanyIdInput) {
    reminderCompanyIdInput.value = linkedWorkOrder.companyId || "";
    reminderCompanyIdInput.disabled = true;
  } else if (reminderCompanyIdInput) {
    reminderCompanyIdInput.disabled = false;
  }

  renderReminderLinkPreview();
}

function renderReminderLinkPreview() {
  if (!reminderLinkPreview) {
    return;
  }

  const linkedWorkOrder = state.workOrders.find((item) => item.id === reminderWorkOrderIdInput?.value);
  const company = getCompany(reminderCompanyIdInput?.value || linkedWorkOrder?.companyId || "");
  const parts = [];

  if (linkedWorkOrder?.workOrderNumber) {
    parts.push(`RN ${linkedWorkOrder.workOrderNumber}`);
  }

  if (company?.name) {
    parts.push(company.name);
  }

  if (linkedWorkOrder?.locationName) {
    parts.push(linkedWorkOrder.locationName);
  }

  reminderLinkPreview.hidden = parts.length === 0;
  reminderLinkPreview.textContent = parts.join(" · ");
}

function buildReminderPayload() {
  const linkedWorkOrder = state.workOrders.find((item) => item.id === reminderWorkOrderIdInput.value);

  return {
    title: reminderTitleInput.value,
    dueDate: normalizeDateInputValue(reminderDueDateInput.value),
    status: reminderStatusInput.value,
    workOrderId: reminderWorkOrderIdInput.value,
    companyId: linkedWorkOrder?.companyId || reminderCompanyIdInput.value,
    locationId: linkedWorkOrder?.locationId || "",
    note: reminderNoteInput.value,
    repeatEveryDays: reminderRepeatDaysInput?.value ?? "",
  };
}

function resetReminderForm() {
  reminderForm?.reset();

  if (reminderIdInput) {
    reminderIdInput.value = "";
  }

  if (reminderStatusInput) {
    reminderStatusInput.value = "active";
  }

  if (reminderRepeatDaysInput) {
    reminderRepeatDaysInput.value = "";
  }

  if (reminderCompanyIdInput) {
    reminderCompanyIdInput.disabled = false;
  }

  if (reminderError) {
    reminderError.textContent = "";
  }

  renderReminderLinkPreview();
  syncReminderEditorChrome();
}

function syncReminderEditorChrome() {
  if (reminderEditorTitle) {
    reminderEditorTitle.textContent = reminderIdInput?.value
      ? `Uredi reminder | ${reminderTitleInput?.value?.trim() || "Bez naslova"}`
      : "Novi reminder";
  }
}

function syncReminderEditorModal() {
  if (state.reminderEditorOpen && (
    state.activeView !== "reminders"
    || !state.user
  )) {
    state.reminderEditorOpen = false;
  }

  const isOpen = state.reminderEditorOpen;
  reminderEditorPanel?.classList.toggle("is-modal-open", isOpen);
  document.body.classList.toggle("is-reminder-editor-open", isOpen);

  if (reminderEditorPanel) {
    reminderEditorPanel.hidden = !isOpen;
    reminderEditorPanel.setAttribute("aria-hidden", String(!isOpen));
  }

  if (reminderEditorBackdrop) {
    reminderEditorBackdrop.hidden = !isOpen;
  }

  if (reminderEditorCloseButton) {
    reminderEditorCloseButton.hidden = !isOpen;
  }

  if (isOpen) {
    requestAnimationFrame(() => {
      reminderEditorBody?.scrollTo({ top: 0, behavior: "auto" });
      reminderTitleInput?.focus({ preventScroll: true });
    });
  }
}

function openReminderEditor() {
  state.reminderEditorOpen = true;
  syncReminderEditorChrome();
  syncReminderEditorModal();
}

function closeReminderEditor({ reset = false } = {}) {
  state.reminderEditorOpen = false;
  syncReminderEditorModal();
  if (reset) {
    resetReminderForm();
  }
}

function dismissReminderEditor() {
  closeReminderEditor({ reset: true });
}

function hydrateReminderForm(reminder) {
  state.activeView = "reminders";
  state.activeSidebarGroup = "home";
  state.activeSidebarItem = "reminders";
  renderActiveView();

  reminderIdInput.value = reminder.id;
  reminderTitleInput.value = reminder.title || "";
  reminderDueDateInput.value = formatDateInputDisplayValue(reminder.dueDate || "");
  reminderStatusInput.value = getReminderStatusValue(reminder);
  if (reminderRepeatDaysInput) {
    reminderRepeatDaysInput.value = Number.isInteger(Number(reminder.repeatEveryDays))
      ? String(reminder.repeatEveryDays)
      : "";
  }
  rebuildReminderWorkOrderOptions(reminder.workOrderId || "");
  rebuildReminderCompanyOptions(reminder.companyId || "");
  reminderCompanyIdInput.value = reminder.companyId || "";
  reminderNoteInput.value = reminder.note || "";
  syncReminderContextFromWorkOrder();
  syncReminderEditorChrome();
  openReminderEditor();
}

function openReminderComposerForWorkOrder(workOrder = null) {
  state.activeView = "reminders";
  state.activeSidebarGroup = "home";
  state.activeSidebarItem = "reminders";
  renderActiveView();
  resetReminderForm();

  if (workOrder) {
    reminderTitleInput.value = `Podsjetnik za ${workOrder.workOrderNumber}`;
    reminderDueDateInput.value = formatDateInputDisplayValue(workOrder.dueDate || workOrder.openedDate || "");
    rebuildReminderWorkOrderOptions(workOrder.id);
    reminderWorkOrderIdInput.value = workOrder.id;
    rebuildReminderCompanyOptions(workOrder.companyId || "");
    reminderCompanyIdInput.value = workOrder.companyId || "";
  }

  syncReminderContextFromWorkOrder();
  syncReminderEditorChrome();
  openReminderEditor();
}

function createReminderStatusBadge(status) {
  const normalizedStatus = getReminderStatusValue(status);
  const option = REMINDER_STATUS_OPTIONS.find((item) => item.value === normalizedStatus);
  const label = option?.label ?? normalizedStatus ?? "Aktivan";
  const badge = document.createElement("span");
  badge.className = `reminder-status-badge is-${normalizedStatus || "active"}`;
  badge.textContent = label;
  return badge;
}

function formatReminderRepeatLabel(value) {
  const parsed = Number.parseInt(String(value ?? ""), 10);

  if (!Number.isFinite(parsed) || parsed <= 0) {
    return "";
  }

  if (parsed === 1) {
    return "Svakodnevno";
  }

  if (parsed === 7) {
    return "Tjedno";
  }

  return `Svaka ${parsed} dana`;
}

function createReminderStatusSelect(reminder) {
  const select = document.createElement("select");
  const currentStatus = getReminderStatusValue(reminder);
  select.className = `reminder-status-select is-${currentStatus}`;
  select.setAttribute("aria-label", "Status remindera");
  replaceSelectOptions(select, REMINDER_STATUS_OPTIONS, currentStatus);

  const stopPropagation = (event) => {
    event.stopPropagation();
  };

  select.addEventListener("pointerdown", stopPropagation);
  select.addEventListener("click", stopPropagation);
  select.addEventListener("keydown", stopPropagation);
  select.addEventListener("change", () => {
    const nextStatus = select.value;

    if (nextStatus === currentStatus) {
      return;
    }

    void runMutation(() => apiRequest(`/reminders/${reminder.id}`, {
      method: "PATCH",
      body: {
        status: nextStatus,
      },
    }), reminderError).then((success) => {
      if (!success) {
        select.value = currentStatus;
        select.className = `reminder-status-select is-${currentStatus}`;
      }
    });
  });

  return select;
}

function renderReminderSummary() {
  const reminders = getPersonalReminders();
  const today = new Date().toISOString().slice(0, 10);

  if (remindersTotalCount) {
    remindersTotalCount.textContent = String(reminders.length);
  }

  if (remindersTodayCount) {
    remindersTodayCount.textContent = String(reminders.filter((item) => item.dueDate === today).length);
  }

  if (remindersOverdueCount) {
    remindersOverdueCount.textContent = String(reminders.filter((item) => isReminderOverdue(item)).length);
  }

  if (remindersDoneCount) {
    remindersDoneCount.textContent = String(reminders.filter((item) => getReminderStatusValue(item) === "done").length);
  }
}

function renderReminders() {
  renderReminderSummary();
  renderTopbarShortcutCounts();
  syncReminderEditorModal();

  if (!remindersBody) {
    return;
  }

  const reminders = getFilteredReminders();
  remindersBody.replaceChildren(...reminders.map((reminder) => {
    const linkedWorkOrder = getReminderLinkedWorkOrder(reminder);
    const repeatLabel = formatReminderRepeatLabel(reminder.repeatEveryDays);
    const openEditor = () => {
      hydrateReminderForm(reminder);
    };
    const card = document.createElement("article");
    card.className = `reminder-card is-${getReminderStatusValue(reminder)}`;
    card.tabIndex = 0;
    card.setAttribute("role", "button");
    card.setAttribute("aria-label", `Uredi reminder ${reminder.title}`);
    card.addEventListener("click", openEditor);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openEditor();
      }
    });

    const top = document.createElement("div");
    top.className = "reminder-card-top";
    const copy = document.createElement("div");
    copy.className = "reminder-card-copy";
    const title = document.createElement("strong");
    title.className = "reminder-card-title";
    title.textContent = reminder.title;
    const subtitle = document.createElement("span");
    subtitle.className = "reminder-card-subtitle";
    subtitle.textContent = [
      reminder.workOrderNumber ? `RN ${reminder.workOrderNumber}` : "",
      reminder.companyName || "",
      reminder.locationName || "",
    ].filter(Boolean).join(" · ") || "Opci reminder";
    copy.append(title, subtitle);

    const meta = document.createElement("div");
    meta.className = "reminder-card-meta";
    meta.append(createReminderStatusSelect(reminder));

    const due = document.createElement("span");
    due.className = `reminder-due-pill${isReminderOverdue(reminder) ? " is-overdue" : ""}`;
    due.textContent = reminder.dueDate ? formatCompactDate(reminder.dueDate) : "Bez datuma";
    meta.append(due);

    if (repeatLabel) {
      const repeat = document.createElement("span");
      repeat.className = "reminder-repeat-pill";
      repeat.textContent = repeatLabel;
      meta.append(repeat);
    }

    top.append(copy, meta);

    const note = document.createElement("p");
    note.className = "reminder-card-note";
    note.textContent = reminder.note || "Bez bilješke.";

    const footer = document.createElement("div");
    footer.className = "reminder-card-footer";

    const footerMeta = document.createElement("div");
    footerMeta.className = "reminder-card-footer-meta";
    footerMeta.textContent = reminder.createdByLabel
      ? `Kreirao ${reminder.createdByLabel}${reminder.createdAt ? ` · ${formatDateTime(reminder.createdAt)}` : ""}`
      : (reminder.createdAt ? formatDateTime(reminder.createdAt) : "");

    const actions = document.createElement("div");
    actions.className = "reminder-card-actions";
    actions.addEventListener("pointerdown", (event) => {
      event.stopPropagation();
    });
    actions.addEventListener("click", (event) => {
      event.stopPropagation();
    });

    if (linkedWorkOrder) {
      actions.append(createActionButton("Otvori RN", "ghost-button reminder-inline-action", () => {
        hydrateWorkOrderForm(linkedWorkOrder);
      }));
    }

    actions.append(
      createActionButton("Obriši", "ghost-button reminder-inline-action is-danger", () => {
        if (!window.confirm(`Obrisati reminder "${reminder.title}"?`)) {
          return;
        }

        void runMutation(() => apiRequest(`/reminders/${reminder.id}`, {
          method: "DELETE",
        }), reminderError).then((success) => {
          if (success && reminderIdInput.value === reminder.id) {
            resetReminderForm();
          }
        });
      }),
    );

    footer.append(footerMeta, actions);
    card.append(top, note, footer);
    return card;
  }));

  remindersEmpty.hidden = reminders.length !== 0;
}

function getTodoTaskById(taskId = state.activeTodoTaskId) {
  return state.todoTasks.find((item) => String(item.id) === String(taskId)) ?? null;
}

function getLinkedTodoWorkOrder(task) {
  if (!task?.workOrderId) {
    return null;
  }

  return state.workOrders.find((item) => item.id === task.workOrderId) ?? null;
}

function isTodoTaskOverdue(task) {
  if (!task?.dueDate || getTodoTaskStatusValue(task) === "done") {
    return false;
  }

  return task.dueDate < new Date().toISOString().slice(0, 10);
}

function getTodoAssigneeOptions() {
  return [
    { value: "", label: "Bez nositelja" },
    ...[...state.users]
      .filter((user) => user?.isActive !== false)
      .sort((left, right) => String(left.fullName || left.email).localeCompare(String(right.fullName || right.email)))
      .map((user) => ({
        value: user.id,
        label: user.fullName || user.email || user.username || "User",
      })),
  ];
}

function getFilteredTodoTasks() {
  return sortTodoTasks(filterTodoTasks(state.todoTasks, {
    query: todoSearchInput?.value ?? "",
    status: todoFilterStatusInput?.value ?? "all",
    scope: todoFilterScopeInput?.value ?? "all",
    userId: state.user?.id ?? "",
  }));
}

function getTodoInvitedPeopleOptions() {
  return [...state.users]
    .filter((user) => user?.isActive !== false)
    .sort((left, right) => String(left.fullName || left.email).localeCompare(String(right.fullName || right.email)))
    .map((user) => ({
      value: user.id,
      label: user.fullName || user.email || user.username || "User",
    }));
}

const TODO_INVITED_ALL_TOKEN = "__all__";

function getTodoInvitedSelectedUserIds(select) {
  const selectedValues = getSelectedMultiSelectValues(select);
  const availableUserIds = getTodoInvitedPeopleOptions().map((option) => String(option.value));
  if (selectedValues.includes(TODO_INVITED_ALL_TOKEN)) {
    return availableUserIds;
  }
  return selectedValues.filter((value) => value !== TODO_INVITED_ALL_TOKEN);
}

function getTodoInvitedSelectedUsers(select = todoInvitedUsersInput) {
  return getTodoInvitedSelectedUserIds(select)
    .map((userId) => state.users.find((user) => String(user?.id) === String(userId)) ?? null)
    .filter(Boolean);
}

function createTodoInvitedAvatar(userLike = {}) {
  const label = userLike.fullName || userLike.email || userLike.username || "User";
  return createWorkOrderMiniExecutor(
    { label, user: userLike },
    { className: "work-order-mini-executor todo-invited-avatar" },
  );
}

function syncTodoInvitedPicker() {
  if (state.todoInvitedPickerOpen && (!state.todoEditorOpen || !todoInvitedDropdown)) {
    state.todoInvitedPickerOpen = false;
  }

  const isOpen = Boolean(state.todoInvitedPickerOpen && state.todoEditorOpen && todoInvitedDropdown);
  todoInvitedDropdown?.classList.toggle("is-open", isOpen);
  if (todoInvitedTrigger) {
    todoInvitedTrigger.setAttribute("aria-expanded", isOpen ? "true" : "false");
  }
  if (todoInvitedPanel) {
    todoInvitedPanel.hidden = !isOpen;
  }
}

function setTodoInvitedPickerOpen(isOpen) {
  state.todoInvitedPickerOpen = Boolean(isOpen);
  syncTodoInvitedPicker();
}

function renderTodoInvitedPreview() {
  if (!todoInvitedPreview) {
    return;
  }

  const selectedUsers = getTodoInvitedSelectedUsers(todoInvitedUsersInput);
  const previewWrap = document.createElement("div");
  previewWrap.className = "todo-invited-preview-wrap";

  const stack = document.createElement("div");
  stack.className = "todo-invited-preview-stack";

  if (selectedUsers.length === 0) {
    stack.append(createWorkOrderMiniExecutor("Bez pozvanih", {
      className: "work-order-mini-executor todo-invited-avatar",
    }));
  } else {
    selectedUsers.slice(0, 3).forEach((user) => stack.append(createTodoInvitedAvatar(user)));
    if (selectedUsers.length > 3) {
      stack.append(createExecutorOverflowBadge(selectedUsers.length - 3, "work-order-mini-executor todo-invited-avatar"));
    }
  }

  const summary = document.createElement("span");
  summary.className = "todo-invited-preview-text";
  summary.textContent = selectedUsers.length === 0
    ? "Odaberi ljude"
    : selectedUsers.length === 1
      ? (selectedUsers[0].fullName || selectedUsers[0].email || selectedUsers[0].username || "1 osoba")
      : `${selectedUsers.length} pozvanih`;

  previewWrap.append(stack, summary);
  todoInvitedPreview.replaceChildren(previewWrap);
}

function syncTodoInvitedPanelOptionState() {
  if (!todoInvitedPanel || !todoInvitedUsersInput) {
    return;
  }

  const selectedSet = new Set(getTodoInvitedSelectedUserIds(todoInvitedUsersInput));
  todoInvitedPanel.querySelectorAll(".todo-invited-option").forEach((option) => {
    const checkbox = option.querySelector('input[name="todo-invited-user-id"]');
    if (!(checkbox instanceof HTMLInputElement)) {
      return;
    }
    const checked = selectedSet.has(String(checkbox.value || ""));
    checkbox.checked = checked;
    option.classList.toggle("is-selected", checked);
  });
}

function syncTodoInvitedSelectionFromPanel() {
  if (!todoInvitedPanel || !todoInvitedUsersInput) {
    return;
  }

  const selectedIds = Array.from(
    todoInvitedPanel.querySelectorAll('input[name="todo-invited-user-id"]:checked'),
  ).map((input) => String(input.value || "")).filter(Boolean);

  const peopleOptions = getTodoInvitedPeopleOptions();
  const allSelected = peopleOptions.length > 0
    && peopleOptions.every((option) => selectedIds.includes(String(option.value)));

  setMultiSelectSelectedValues(
    todoInvitedUsersInput,
    allSelected ? [TODO_INVITED_ALL_TOKEN, ...selectedIds] : selectedIds,
  );
  syncTodoInvitedPanelOptionState();
  renderTodoInvitedPreview();
}

function rebuildTodoInvitedPanel() {
  if (!todoInvitedPanel) {
    return;
  }

  const selectedSet = new Set(getTodoInvitedSelectedUserIds(todoInvitedUsersInput));
  const users = [...state.users]
    .filter((user) => user?.isActive !== false)
    .sort((left, right) => String(left.fullName || left.email).localeCompare(String(right.fullName || right.email), "hr"));

  if (users.length === 0) {
    const empty = document.createElement("p");
    empty.className = "todo-invited-empty";
    empty.textContent = "Nema aktivnih kolega za odabir.";
    todoInvitedPanel.replaceChildren(empty);
    return;
  }

  todoInvitedPanel.replaceChildren(...users.map((user) => {
    const option = document.createElement("label");
    option.className = "todo-invited-option";
    option.classList.toggle("is-selected", selectedSet.has(String(user.id)));

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.name = "todo-invited-user-id";
    checkbox.value = String(user.id);
    checkbox.checked = selectedSet.has(String(user.id));

    const avatar = createTodoInvitedAvatar(user);

    const copy = document.createElement("span");
    copy.className = "todo-invited-option-copy";
    const name = document.createElement("strong");
    name.textContent = user.fullName || user.email || user.username || "User";
    const meta = document.createElement("span");
    meta.textContent = user.email || user.username || "SafeNexus";
    copy.append(name, meta);

    option.append(checkbox, avatar, copy);
    return option;
  }));
}

function rebuildTodoAssigneeOptions(selectedValue = "") {
  if (!todoAssigneeInput) {
    return;
  }

  replaceSelectOptions(todoAssigneeInput, getTodoAssigneeOptions(), selectedValue || "");
}

function rebuildTodoInvitedUserOptions(selectedValues = []) {
  if (!todoInvitedUsersInput) {
    return;
  }
  const values = Array.isArray(selectedValues) ? Array.from(new Set(selectedValues.map((value) => String(value)))) : [];
  const peopleOptions = getTodoInvitedPeopleOptions();
  const allSelected = peopleOptions.length > 0 && peopleOptions.every((option) => values.includes(String(option.value)));
  const options = [
    createOption(TODO_INVITED_ALL_TOKEN, "Svi aktivni kolege"),
    ...peopleOptions.map((option) => createOption(option.value, option.label)),
  ];
  todoInvitedUsersInput.replaceChildren(...options);
  setMultiSelectSelectedValues(
    todoInvitedUsersInput,
    allSelected ? [TODO_INVITED_ALL_TOKEN, ...values] : values,
  );
  rebuildTodoInvitedPanel();
  renderTodoInvitedPreview();
  syncTodoInvitedPicker();
}

function rebuildTodoDetailAssigneeOptions(selectedValue = "") {
  if (!todoDetailAssignee) {
    return;
  }

  replaceSelectOptions(todoDetailAssignee, getTodoAssigneeOptions(), selectedValue || "");
}

function rebuildTodoDetailInvitedUserOptions(selectedValues = []) {
  if (!todoDetailInvitedUsersInput) {
    return;
  }
  const values = Array.isArray(selectedValues) ? Array.from(new Set(selectedValues.map((value) => String(value)))) : [];
  const peopleOptions = getTodoInvitedPeopleOptions();
  const allSelected = peopleOptions.length > 0 && peopleOptions.every((option) => values.includes(String(option.value)));
  const options = [
    createOption(TODO_INVITED_ALL_TOKEN, "Svi aktivni kolege"),
    ...peopleOptions.map((option) => createOption(option.value, option.label)),
  ];
  todoDetailInvitedUsersInput.replaceChildren(...options);
  setMultiSelectSelectedValues(
    todoDetailInvitedUsersInput,
    allSelected ? [TODO_INVITED_ALL_TOKEN, ...values] : values,
  );
}

function rebuildTodoWorkOrderOptions(selectedValue = "") {
  if (!todoWorkOrderIdInput) {
    return;
  }

  const options = [
    { value: "", label: "Bez vezanog RN" },
    ...sortWorkOrders(state.workOrders).map((item) => ({
      value: item.id,
      label: `${item.workOrderNumber} · ${item.companyName || item.locationName || "RN"}`,
    })),
  ];

  replaceSelectOptions(todoWorkOrderIdInput, options, selectedValue || "");
}

function rebuildTodoCompanyOptions(selectedValue = "") {
  if (!todoCompanyIdInput) {
    return;
  }

  const options = [
    { value: "", label: "Bez tvrtke" },
    ...(state.companies ?? [])
      .slice()
      .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "hr"))
      .map((company) => ({
        value: company.id,
        label: company.name || "Tvrtka",
      })),
  ];

  replaceSelectOptions(todoCompanyIdInput, options, selectedValue || "");
}

function rebuildTodoLocationOptions(selectedValue = "") {
  if (!todoLocationIdInput) {
    return;
  }

  const selectedCompanyId = String(todoCompanyIdInput?.value || "").trim();
  const options = (state.locations ?? [])
    .filter((location) => !selectedCompanyId || String(location.companyId || "") === selectedCompanyId)
    .slice()
    .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "hr"))
    .map((location) => ({
      value: location.id,
      label: [location.name, location.companyName].filter(Boolean).join(" · ") || "Lokacija",
    }));

  replaceSelectOptions(todoLocationIdInput, [
    { value: "", label: selectedCompanyId ? "Bez lokacije" : "Bez lokacije / slobodni plan" },
    ...options,
  ], selectedValue || "");
}

function syncTodoContextFromWorkOrder() {
  const linkedWorkOrder = state.workOrders.find((item) => item.id === todoWorkOrderIdInput?.value) ?? null;

  if (linkedWorkOrder) {
    rebuildTodoCompanyOptions(linkedWorkOrder.companyId || "");
    if (todoCompanyIdInput) {
      todoCompanyIdInput.value = linkedWorkOrder.companyId || "";
      todoCompanyIdInput.disabled = true;
    }
    rebuildTodoLocationOptions(linkedWorkOrder.locationId || "");
    if (todoLocationIdInput) {
      todoLocationIdInput.value = linkedWorkOrder.locationId || "";
      todoLocationIdInput.disabled = true;
    }
  } else {
    if (todoCompanyIdInput) {
      todoCompanyIdInput.disabled = false;
    }
    if (todoLocationIdInput) {
      todoLocationIdInput.disabled = false;
    }
    rebuildTodoLocationOptions(todoLocationIdInput?.value || "");
  }

  renderTodoLinkPreview();
}

function renderTodoLinkPreview() {
  if (!todoLinkPreview) {
    return;
  }

  const linkedWorkOrder = state.workOrders.find((item) => item.id === todoWorkOrderIdInput?.value);
  const company = getCompany(todoCompanyIdInput?.value || linkedWorkOrder?.companyId || "");
  const location = state.locations.find((item) => item.id === (todoLocationIdInput?.value || linkedWorkOrder?.locationId || ""));
  const parts = [];

  if (linkedWorkOrder?.workOrderNumber) {
    parts.push(`RN ${linkedWorkOrder.workOrderNumber}`);
  }
  if (company?.name) {
    parts.push(company.name);
  }
  if (location?.name || linkedWorkOrder?.locationName) {
    parts.push(location?.name || linkedWorkOrder.locationName);
  }

  if (parts.length === 0) {
    todoLinkPreview.hidden = true;
    todoLinkPreview.textContent = "";
    return;
  }

  todoLinkPreview.hidden = false;
  todoLinkPreview.textContent = parts.join(" · ");
}

function buildTodoTaskPayload() {
  const linkedWorkOrder = state.workOrders.find((item) => item.id === todoWorkOrderIdInput.value) ?? null;

  return {
    title: todoTitleInput.value,
    assignedToUserId: todoAssigneeInput.value,
    invitedUserIds: getTodoInvitedSelectedUserIds(todoInvitedUsersInput),
    dueDate: normalizeDateInputValue(todoDueDateInput.value),
    status: todoStatusInput.value,
    priority: todoPriorityInput.value,
    workOrderId: todoWorkOrderIdInput.value,
    companyId: linkedWorkOrder?.companyId ?? todoCompanyIdInput?.value ?? "",
    locationId: linkedWorkOrder?.locationId ?? todoLocationIdInput?.value ?? "",
    message: todoMessageInput.value,
  };
}

function syncTodoStatusInputLock(task = null) {
  if (!todoStatusInput) {
    return;
  }

  const canChangeStatus = !task || canCurrentUserChangeTodoStatus(task);
  todoStatusInput.disabled = !canChangeStatus;
  todoStatusInput.title = canChangeStatus
    ? ""
    : "Status može mijenjati samo osoba koja je otvorila temu.";
}

function resetTodoForm() {
  if (!todoForm) {
    return;
  }

  state.todoInvitedPickerOpen = false;
  todoIdInput.value = "";
  todoTitleInput.value = "";
  todoDueDateInput.value = "";
  todoStatusInput.value = "open";
  syncTodoStatusInputLock(null);
  todoPriorityInput.value = "Normal";
  rebuildTodoAssigneeOptions("");
  rebuildTodoInvitedUserOptions([]);
  rebuildTodoWorkOrderOptions("");
  rebuildTodoCompanyOptions("");
  rebuildTodoLocationOptions("");
  todoWorkOrderIdInput.value = "";
  if (todoCompanyIdInput) {
    todoCompanyIdInput.value = "";
    todoCompanyIdInput.disabled = false;
  }
  if (todoLocationIdInput) {
    todoLocationIdInput.value = "";
    todoLocationIdInput.disabled = false;
  }
  todoMessageInput.value = "";

  if (todoError) {
    todoError.textContent = "";
  }

  renderTodoLinkPreview();
  syncTodoInvitedPicker();
  syncTodoEditorChrome();
}

function syncTodoEditorChrome() {
  if (todoEditorTitle) {
    todoEditorTitle.textContent = todoIdInput?.value
      ? `Uredi temu | ${todoTitleInput?.value?.trim() || "Bez naslova"}`
      : "Nova tema";
  }
}

function syncTodoEditorModal() {
  if (state.todoEditorOpen && (
    state.activeView !== "todo"
    || !state.user
  )) {
    state.todoEditorOpen = false;
  }

  const isOpen = state.todoEditorOpen;

  if (!isOpen) {
    state.todoInvitedPickerOpen = false;
  }

  if (isOpen) {
    if (todoEditorBackdrop && todoEditorBackdrop.parentNode !== document.body) {
      document.body.append(todoEditorBackdrop);
    }
    if (todoEditorPanel && todoEditorPanel.parentNode !== document.body) {
      document.body.append(todoEditorPanel);
    }
  } else {
    if (todoEditorBackdrop && todoEditorBackdropHomeParent) {
      if (todoEditorBackdropHomeNextSibling && todoEditorBackdropHomeNextSibling.parentNode === todoEditorBackdropHomeParent) {
        todoEditorBackdropHomeParent.insertBefore(todoEditorBackdrop, todoEditorBackdropHomeNextSibling);
      } else {
        todoEditorBackdropHomeParent.append(todoEditorBackdrop);
      }
    }
    if (todoEditorPanel && todoEditorPanelHomeParent) {
      if (todoEditorPanelHomeNextSibling && todoEditorPanelHomeNextSibling.parentNode === todoEditorPanelHomeParent) {
        todoEditorPanelHomeParent.insertBefore(todoEditorPanel, todoEditorPanelHomeNextSibling);
      } else {
        todoEditorPanelHomeParent.append(todoEditorPanel);
      }
    }
  }

  todoEditorPanel?.classList.toggle("is-modal-open", isOpen);
  document.body.classList.toggle("is-todo-editor-open", isOpen);

  if (todoEditorPanel) {
    todoEditorPanel.hidden = !isOpen;
    todoEditorPanel.setAttribute("aria-hidden", String(!isOpen));
  }

  if (todoEditorBackdrop) {
    todoEditorBackdrop.hidden = !isOpen;
  }

  if (todoEditorCloseButton) {
    todoEditorCloseButton.hidden = !isOpen;
  }

  syncTodoInvitedPicker();

  if (isOpen) {
    requestAnimationFrame(() => {
      todoEditorBody?.scrollTo({ top: 0, behavior: "auto" });
      todoTitleInput?.focus({ preventScroll: true });
    });
  }
}

function openTodoEditor() {
  state.todoEditorOpen = true;
  syncTodoEditorChrome();
  syncTodoEditorModal();
}

function closeTodoEditor({ reset = false } = {}) {
  state.todoEditorOpen = false;
  syncTodoEditorModal();
  if (reset) {
    resetTodoForm();
  }
}

function dismissTodoEditor() {
  closeTodoEditor({ reset: true });
}

function hydrateTodoTaskForm(task) {
  state.activeView = "todo";
  state.activeSidebarGroup = "home";
  state.activeSidebarItem = "todo";
  state.activeTodoTaskId = task.id;
  renderActiveView();

  todoIdInput.value = task.id;
  todoTitleInput.value = task.title || "";
  todoDueDateInput.value = formatDateInputDisplayValue(task.dueDate || "");
  todoStatusInput.value = getTodoTaskStatusValue(task);
  syncTodoStatusInputLock(task);
  todoPriorityInput.value = task.priority || "Normal";
  rebuildTodoAssigneeOptions(task.assignedToUserId || "");
  todoAssigneeInput.value = task.assignedToUserId || "";
  rebuildTodoInvitedUserOptions(task.invitedUserIds ?? []);
  rebuildTodoWorkOrderOptions(task.workOrderId || "");
  todoWorkOrderIdInput.value = task.workOrderId || "";
  rebuildTodoCompanyOptions(task.companyId || "");
  if (todoCompanyIdInput) {
    todoCompanyIdInput.value = task.companyId || "";
  }
  rebuildTodoLocationOptions(task.locationId || "");
  if (todoLocationIdInput) {
    todoLocationIdInput.value = task.locationId || "";
  }
  syncTodoContextFromWorkOrder();
  todoMessageInput.value = task.message || "";
  state.todoInvitedPickerOpen = false;
  renderTodoLinkPreview();
  syncTodoInvitedPicker();
  syncTodoEditorChrome();
  openTodoEditor();
}

function openTodoComposerForWorkOrder(workOrder = null) {
  state.activeView = "todo";
  state.activeSidebarGroup = "home";
  state.activeSidebarItem = "todo";
  renderActiveView();
  resetTodoForm();

  if (workOrder) {
    todoTitleInput.value = `Tema za ${workOrder.workOrderNumber}`;
    todoDueDateInput.value = formatDateInputDisplayValue(workOrder.dueDate || workOrder.openedDate || "");
    rebuildTodoWorkOrderOptions(workOrder.id);
    todoWorkOrderIdInput.value = workOrder.id;
    rebuildTodoCompanyOptions(workOrder.companyId || "");
    if (todoCompanyIdInput) {
      todoCompanyIdInput.value = workOrder.companyId || "";
    }
    rebuildTodoLocationOptions(workOrder.locationId || "");
    if (todoLocationIdInput) {
      todoLocationIdInput.value = workOrder.locationId || "";
    }
    syncTodoContextFromWorkOrder();
    todoMessageInput.value = `${workOrder.companyName || "Klijent"} · ${workOrder.locationName || "Lokacija"}`;
  }

  renderTodoLinkPreview();
  syncTodoEditorChrome();
  openTodoEditor();
}

function createTodoTaskStatusBadge(task) {
  const status = getTodoTaskStatusValue(task);
  const label = getOptionLabel(TODO_TASK_STATUS_OPTIONS, status);
  const badge = document.createElement("span");
  badge.className = `todo-task-status-badge is-${status}`;
  badge.textContent = label;
  return badge;
}

function createTodoTaskPriorityBadge(priority = "Normal") {
  const badge = document.createElement("span");
  badge.className = `todo-task-priority-badge ${priorityBadgeClass(priority)}`;
  badge.textContent = getOptionLabel(PRIORITY_OPTIONS, priority);
  return badge;
}

function canCurrentUserChangeTodoStatus(task = {}) {
  const createdByUserId = String(task.createdByUserId ?? "").trim();
  const currentUserId = String(state.user?.id ?? "").trim();
  return Boolean(createdByUserId && currentUserId && createdByUserId === currentUserId);
}

function createTodoOpenTopicButton(task = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "ghost-button todo-open-topic-button";
  const expanded = isTodoTaskExpanded(task.id);
  button.textContent = expanded ? "Sakrij temu" : "Otvori temu";
  button.setAttribute("aria-expanded", expanded ? "true" : "false");
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    state.activeTodoTaskId = String(task.id ?? "");
    setTodoTaskExpanded(task.id, !expanded);
    renderTodo();
  });
  return button;
}

function getTodoExpandedTaskIdsSet() {
  if (state.todoExpandedTaskIds instanceof Set) {
    return state.todoExpandedTaskIds;
  }

  if (Array.isArray(state.todoExpandedTaskIds)) {
    state.todoExpandedTaskIds = new Set(state.todoExpandedTaskIds.map((item) => String(item || "")));
    return state.todoExpandedTaskIds;
  }

  state.todoExpandedTaskIds = new Set();
  return state.todoExpandedTaskIds;
}

function isTodoTaskExpanded(taskId) {
  return getTodoExpandedTaskIdsSet().has(String(taskId || ""));
}

function setTodoTaskExpanded(taskId, isExpanded = false) {
  const normalizedTaskId = String(taskId || "").trim();
  if (!normalizedTaskId) {
    return;
  }

  const expandedIds = getTodoExpandedTaskIdsSet();
  if (isExpanded) {
    expandedIds.add(normalizedTaskId);
  } else {
    expandedIds.delete(normalizedTaskId);
  }
}

function createTodoTaskStatusControl(task = {}) {
  const wrapper = document.createElement("label");
  wrapper.className = "todo-task-status-control";

  const label = document.createElement("span");
  label.className = "todo-task-status-control-label";
  label.textContent = "Status";

  const select = document.createElement("select");
  select.className = "todo-task-status-select";
  const currentStatus = getTodoTaskStatusValue(task);
  replaceSelectOptions(select, TODO_TASK_STATUS_OPTIONS, currentStatus);
  select.dataset.status = slugifyValue(currentStatus);
  const canChangeStatus = canCurrentUserChangeTodoStatus(task);
  select.disabled = !canChangeStatus;
  select.title = canChangeStatus
    ? "Promijeni status teme"
    : "Status može mijenjati samo osoba koja je otvorila temu.";
  ["click", "keydown"].forEach((eventName) => {
    select.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });
  select.addEventListener("change", () => {
    const previousStatus = currentStatus;
    const nextStatus = select.value || previousStatus;
    select.dataset.status = slugifyValue(nextStatus);

    if (nextStatus === previousStatus) {
      return;
    }

    select.disabled = true;
    void runMutation(() => apiRequest(`/todo-tasks/${task.id}`, {
      method: "PATCH",
      body: {
        status: nextStatus,
      },
    }), todoInlineError).then((success) => {
      if (!success) {
        select.value = previousStatus;
        select.dataset.status = slugifyValue(previousStatus);
      }
    }).finally(() => {
      const latestTask = getTodoTaskById(task.id) ?? task;
      select.disabled = !canCurrentUserChangeTodoStatus(latestTask);
    });
  });

  wrapper.append(label, select);
  return wrapper;
}

function getTodoTaskParticipantLabels(task = {}) {
  const labels = [];
  [task.assignedToLabel, ...(task.invitedUserLabels ?? []), task.createdByLabel]
    .filter(Boolean)
    .forEach((label) => {
      if (!labels.includes(label)) {
        labels.push(label);
      }
    });
  return labels;
}

function createTodoTaskDetailRow(label, value = "") {
  const row = document.createElement("div");
  row.className = "todo-task-detail-row";

  const title = document.createElement("span");
  title.className = "todo-task-detail-row-label";
  title.textContent = label;

  const content = document.createElement("strong");
  content.className = "todo-task-detail-row-value";
  content.textContent = value || "Bez podatka";

  row.append(title, content);
  return row;
}

function getTodoCommentMentionCandidates(task = {}, query = "") {
  const normalizedQuery = String(query ?? "").trim().toLowerCase();
  const priorityUserIds = new Set([
    task.createdByUserId,
    task.assignedToUserId,
    ...(task.invitedUserIds ?? []),
  ].map((value) => String(value ?? "").trim()).filter(Boolean));

  return [...state.users]
    .filter((user) => user?.isActive !== false)
    .map((user) => ({
      ...user,
      mentionLabel: user.fullName || user.username || user.email || "Kolega",
    }))
    .filter((user) => {
      if (!normalizedQuery) {
        return true;
      }
      const haystack = [
        user.mentionLabel,
        user.fullName,
        user.username,
        user.email,
      ].filter(Boolean).join(" ").toLowerCase();
      return haystack.includes(normalizedQuery);
    })
    .sort((left, right) => {
      const leftPriority = priorityUserIds.has(String(left.id ?? "").trim()) ? 0 : 1;
      const rightPriority = priorityUserIds.has(String(right.id ?? "").trim()) ? 0 : 1;
      if (leftPriority !== rightPriority) {
        return leftPriority - rightPriority;
      }
      return String(left.mentionLabel || "").localeCompare(String(right.mentionLabel || ""), "hr");
    })
    .slice(0, 6);
}

function getTodoCommentMentionState(value = "", caretIndex = String(value ?? "").length) {
  const safeValue = String(value ?? "");
  const safeCaretIndex = Math.max(0, Math.min(Number(caretIndex) || 0, safeValue.length));
  const beforeCaret = safeValue.slice(0, safeCaretIndex);
  const match = beforeCaret.match(/(^|[\s(])@([^\s@]*)$/u);

  if (!match) {
    return null;
  }

  const query = match[2] ?? "";
  return {
    query,
    start: safeCaretIndex - query.length - 1,
    end: safeCaretIndex,
  };
}

function applyTodoCommentMention(textarea, mentionState, candidate = {}) {
  if (!(textarea instanceof HTMLTextAreaElement) || !mentionState) {
    return;
  }

  const label = String(candidate.mentionLabel || candidate.fullName || candidate.username || candidate.email || "").trim();
  if (!label) {
    return;
  }

  const value = textarea.value || "";
  const nextValue = `${value.slice(0, mentionState.start)}@${label} ${value.slice(mentionState.end)}`;
  const nextCaret = mentionState.start + label.length + 2;
  textarea.value = nextValue;
  textarea.focus();
  textarea.setSelectionRange(nextCaret, nextCaret);
}

function createTodoCommentArticle(comment = {}) {
  const article = document.createElement("article");
  article.className = "todo-comment";
  const isOwnComment = isTodoCommentFromCurrentUser(comment);
  article.classList.toggle("is-own", isOwnComment);

  const avatar = document.createElement("span");
  avatar.className = "todo-comment-avatar";
  avatar.textContent = getUserInitials({ fullName: comment.authorLabel || "Kolega" });

  const content = document.createElement("div");
  content.className = "todo-comment-content";

  const top = document.createElement("div");
  top.className = "todo-comment-top";

  const author = document.createElement("strong");
  author.textContent = isOwnComment ? "Ti" : (comment.authorLabel || "SafeNexus");

  const time = document.createElement("span");
  time.textContent = comment.createdAt ? formatDateTime(comment.createdAt) : "";
  top.append(author, time);

  const body = document.createElement("p");
  body.className = "todo-comment-body";
  body.textContent = String(comment.message || "").trim() || "Bez teksta komentara.";

  content.append(top, body);
  article.append(avatar, content);
  return article;
}

function createTodoTaskCommentSection(task = {}) {
  const section = document.createElement("section");
  section.className = "todo-task-comments";
  ["click", "keydown"].forEach((eventName) => {
    section.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });

  const head = document.createElement("div");
  head.className = "todo-task-comments-head";

  const titleWrap = document.createElement("div");
  titleWrap.className = "todo-task-comments-title";
  const title = document.createElement("strong");
  title.textContent = "Komentari";
  const subtitle = document.createElement("span");
  subtitle.textContent = "Kao ispod objave: napiši komentar, Enter šalje, @ tagira kolegu.";
  titleWrap.append(title, subtitle);

  const count = createMetaPill(`${task.commentCount ?? task.comments?.length ?? 0} komentara`, "is-soft");
  head.append(titleWrap, count);

  const list = document.createElement("div");
  list.className = "todo-comments-list";
  const comments = Array.isArray(task.comments) ? task.comments : [];
  if (comments.length === 0) {
    const empty = document.createElement("p");
    empty.className = "empty-inline";
    empty.textContent = "Još nema komentara na ovoj temi.";
    list.append(empty);
  } else {
    list.append(...comments.map((comment) => createTodoCommentArticle(comment)));
  }

  const composer = document.createElement("form");
  composer.className = "todo-comment-form todo-task-comment-form";

  const field = document.createElement("label");
  field.className = "field field-span-full todo-task-comment-field";

  const fieldLabel = document.createElement("span");
  fieldLabel.textContent = "Dodaj komentar";

  const textareaWrap = document.createElement("div");
  textareaWrap.className = "todo-task-comment-textarea-wrap";

  const textarea = document.createElement("textarea");
  textarea.className = "todo-task-comment-textarea";
  textarea.rows = 3;
  textarea.placeholder = "Napiši komentar... Enter šalje, Shift+Enter novi red, @ tagira kolegu.";
  textarea.required = true;

  const mentionMenu = document.createElement("div");
  mentionMenu.className = "todo-comment-mention-menu";
  mentionMenu.hidden = true;

  textareaWrap.append(textarea, mentionMenu);
  field.append(fieldLabel, textareaWrap);

  const error = document.createElement("p");
  error.className = "form-error";
  error.setAttribute("aria-live", "polite");

  const footer = document.createElement("div");
  footer.className = "todo-task-comment-footer";

  const hint = document.createElement("p");
  hint.className = "todo-task-comment-hint";
  hint.textContent = "Tip: `@Ime Prezime` ubaciš iz prijedloga ispod polja.";

  const submitButton = document.createElement("button");
  submitButton.type = "submit";
  submitButton.className = "primary-button";
  submitButton.textContent = "Komentiraj";

  footer.append(hint, submitButton);
  composer.append(field, error, footer);

  let mentionState = null;
  let mentionCandidates = [];
  let mentionIndex = 0;

  const closeMentionMenu = () => {
    mentionState = null;
    mentionCandidates = [];
    mentionIndex = 0;
    mentionMenu.hidden = true;
    mentionMenu.replaceChildren();
  };

  const renderMentionMenu = () => {
    if (!mentionState || mentionCandidates.length === 0) {
      closeMentionMenu();
      return;
    }

    mentionMenu.replaceChildren(...mentionCandidates.map((candidate, index) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "todo-comment-mention-option";
      if (index === mentionIndex) {
        button.classList.add("is-active");
      }

      const avatar = document.createElement("span");
      avatar.className = "todo-comment-mention-avatar";
      avatar.textContent = getUserInitials({ fullName: candidate.mentionLabel || "Kolega" });

      const copy = document.createElement("span");
      copy.className = "todo-comment-mention-copy";
      const strong = document.createElement("strong");
      strong.textContent = candidate.mentionLabel;
      const meta = document.createElement("span");
      meta.textContent = candidate.email || candidate.username || "Korisnik";
      copy.append(strong, meta);

      button.append(avatar, copy);
      button.addEventListener("mousedown", (event) => {
        event.preventDefault();
        event.stopPropagation();
      });
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        applyTodoCommentMention(textarea, mentionState, candidate);
        closeMentionMenu();
      });
      return button;
    }));

    mentionMenu.hidden = false;
  };

  const updateMentionMenu = () => {
    mentionState = getTodoCommentMentionState(textarea.value, textarea.selectionStart ?? textarea.value.length);
    mentionCandidates = mentionState
      ? getTodoCommentMentionCandidates(task, mentionState.query)
      : [];
    mentionIndex = 0;
    renderMentionMenu();
  };

  const submitComment = async () => {
    const message = textarea.value.trim();
    if (!message) {
      error.textContent = "Upiši komentar prije slanja.";
      textarea.focus();
      return;
    }

    textarea.disabled = true;
    submitButton.disabled = true;
    const success = await runMutation(() => apiRequest(`/todo-tasks/${task.id}/comments`, {
      method: "POST",
      body: {
        message,
      },
    }), error);

    if (!success) {
      textarea.disabled = false;
      submitButton.disabled = false;
      textarea.focus();
      return;
    }

    textarea.value = "";
    closeMentionMenu();
  };

  textarea.addEventListener("input", updateMentionMenu);
  textarea.addEventListener("click", updateMentionMenu);
  textarea.addEventListener("keyup", (event) => {
    if (["ArrowUp", "ArrowDown", "Enter", "Tab", "Escape"].includes(event.key)) {
      return;
    }
    updateMentionMenu();
  });
  textarea.addEventListener("blur", () => {
    window.setTimeout(() => {
      if (!mentionMenu.matches(":hover")) {
        closeMentionMenu();
      }
    }, 120);
  });
  textarea.addEventListener("keydown", (event) => {
    event.stopPropagation();

    if (!mentionMenu.hidden && mentionCandidates.length > 0) {
      if (event.key === "ArrowDown") {
        event.preventDefault();
        mentionIndex = (mentionIndex + 1) % mentionCandidates.length;
        renderMentionMenu();
        return;
      }
      if (event.key === "ArrowUp") {
        event.preventDefault();
        mentionIndex = (mentionIndex - 1 + mentionCandidates.length) % mentionCandidates.length;
        renderMentionMenu();
        return;
      }
      if (event.key === "Enter" || event.key === "Tab") {
        event.preventDefault();
        applyTodoCommentMention(textarea, mentionState, mentionCandidates[mentionIndex]);
        closeMentionMenu();
        return;
      }
      if (event.key === "Escape") {
        event.preventDefault();
        closeMentionMenu();
        return;
      }
    }

    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      void submitComment();
    }
  });

  composer.addEventListener("submit", (event) => {
    event.preventDefault();
    void submitComment();
  });

  section.append(head, list, composer);
  return section;
}

function createTodoTaskExpandedPanel(task = {}) {
  if (!isTodoTaskExpanded(task.id)) {
    return null;
  }

  const wrap = document.createElement("section");
  wrap.className = "todo-task-card-expand todo-task-card-expand-details";
  wrap.addEventListener("click", (event) => {
    event.stopPropagation();
  });

  const message = document.createElement("p");
  message.className = "todo-task-detail-message";
  message.textContent = task.message || "Bez dodatnog opisa teme.";

  const facts = document.createElement("div");
  facts.className = "todo-task-detail-facts";
  facts.append(
    createTodoTaskPriorityBadge(task.priority || "Normal"),
    createMetaPill(
      task.dueDate ? `Rok ${formatCompactDate(task.dueDate)}` : "Bez roka",
      isTodoTaskOverdue(task) ? "is-danger" : "is-soft",
    ),
  );
  if (task.updatedAt) {
    facts.append(createMetaPill(`Ažurirano ${formatCompactDate(String(task.updatedAt).slice(0, 10))}`, "is-soft"));
  }

  const detailList = document.createElement("div");
  detailList.className = "todo-task-detail-list";
  detailList.append(
    createTodoTaskDetailRow("Otvorio", task.createdByLabel || "SafeNexus"),
    createTodoTaskDetailRow("Nositelj", task.assignedToLabel || "Bez nositelja"),
    createTodoTaskDetailRow(
      "Sudionici",
      (() => {
        const participantLabels = getTodoTaskParticipantLabels(task);
        return participantLabels.length > 0 ? participantLabels.join(", ") : "Bez sudionika";
      })(),
    ),
  );

  if (task.workOrderNumber || task.companyName || task.locationName) {
    detailList.append(createTodoTaskDetailRow(
      "Povezano",
      [
        task.workOrderNumber ? `RN ${task.workOrderNumber}` : "",
        task.companyName || "",
        task.locationName || "",
      ].filter(Boolean).join(" · "),
    ));
  }

  const actions = document.createElement("div");
  actions.className = "todo-task-detail-actions";

  const linkedWorkOrder = getLinkedTodoWorkOrder(task);
  if (linkedWorkOrder) {
    actions.append(createActionButton("Otvori RN", "ghost-button", (event) => {
      event.stopPropagation();
      hydrateWorkOrderForm(linkedWorkOrder);
    }));
  }

  actions.append(
    createActionButton("Uredi", "ghost-button", (event) => {
      event.stopPropagation();
      hydrateTodoTaskForm(task);
    }),
    createActionButton("Obriši", "ghost-button", (event) => {
      event.stopPropagation();
      if (!window.confirm(`Obrisati temu "${task.title}"?`)) {
        return;
      }

      void runMutation(() => apiRequest(`/todo-tasks/${task.id}`, {
        method: "DELETE",
      }), todoInlineError).then((success) => {
        if (success) {
          setTodoTaskExpanded(task.id, false);
          state.activeTodoTaskId = getFilteredTodoTasks()[0]?.id ?? "";
        }
      });
    }),
  );

  wrap.append(message, facts, detailList);

  if (!canCurrentUserChangeTodoStatus(task)) {
    const note = document.createElement("p");
    note.className = "todo-task-detail-note";
    note.textContent = "Status može mijenjati samo osoba koja je otvorila temu.";
    wrap.append(note);
  }

  wrap.append(createTodoTaskCommentSection(task), actions);
  return wrap;
}

function selectTodoTask(taskId) {
  state.activeTodoTaskId = String(taskId ?? "");
  renderTodo();
}

function renderTodoSummary() {
  if (!todoTotalCount || !todoAssignedCount || !todoCreatedCount || !todoOverdueCount) {
    return;
  }

  const userId = String(state.user?.id ?? "");
  todoTotalCount.textContent = String(state.todoTasks.length);
  todoAssignedCount.textContent = String(state.todoTasks.filter((item) => String(item.assignedToUserId) === userId && getTodoTaskStatusValue(item) !== "done").length);
  todoCreatedCount.textContent = String(state.todoTasks.filter((item) => String(item.createdByUserId) === userId).length);
  todoOverdueCount.textContent = String(state.todoTasks.filter((item) => isTodoTaskOverdue(item)).length);
}

function ensureTodoWorkspaceVisible() {
  const todoView = workspaceViews.todo;

  if (!todoView) {
    return;
  }

  const composerCard = todoView.querySelector(".todo-composer-card");
  const listCard = todoView.querySelector(".todo-list-card");
  const detailCard = todoView.querySelector(".todo-detail-card");
  const formNode = todoForm instanceof HTMLElement ? todoForm : null;
  const filterRowNode = todoView.querySelector(".todo-filter-row");
  const listBodyNode = todoBody instanceof HTMLElement ? todoBody : null;

  [
    composerCard,
    listCard,
    detailCard,
    composerCard?.querySelector(".section-heading"),
    listCard?.querySelector(".workspace-list-head"),
    formNode,
    filterRowNode,
    listBodyNode,
  ].forEach((node) => {
    if (!(node instanceof HTMLElement)) {
      return;
    }
    node.hidden = false;
    node.removeAttribute("hidden");
    node.style.visibility = "visible";
    node.style.opacity = "1";
  });

  if (formNode) {
    formNode.style.display = "grid";
    formNode.style.maxHeight = "none";
    formNode.style.overflow = "visible";
  }

  if (filterRowNode instanceof HTMLElement) {
    filterRowNode.style.display = "grid";
    filterRowNode.style.maxHeight = "none";
    filterRowNode.style.overflow = "visible";
  }

  if (listBodyNode) {
    listBodyNode.style.display = "grid";
    listBodyNode.style.minHeight = "120px";
  }
}

function renderTodoList() {
  if (!todoBody) {
    return;
  }

  const tasks = getFilteredTodoTasks();

  if (tasks.length > 0 && !tasks.some((item) => String(item.id) === String(state.activeTodoTaskId))) {
    state.activeTodoTaskId = tasks[0].id;
  }

  if (tasks.length === 0) {
    state.activeTodoTaskId = "";
  }

  todoBody.replaceChildren(...tasks.map((task) => {
    const card = document.createElement("article");
    card.className = `todo-task-card is-status-${slugifyValue(getTodoTaskStatusValue(task))}`;
    const isExpanded = isTodoTaskExpanded(task.id);
    card.classList.toggle("is-active", isExpanded || String(task.id) === String(state.activeTodoTaskId));
    card.tabIndex = 0;
    card.addEventListener("click", () => {
      state.activeTodoTaskId = String(task.id);
      setTodoTaskExpanded(task.id, true);
      renderTodo();
    });
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        state.activeTodoTaskId = String(task.id);
        setTodoTaskExpanded(task.id, true);
        renderTodo();
      }
    });

    const leadLabel = task.assignedToLabel || task.createdByLabel || "Tema";
    const participantLabels = getTodoTaskParticipantLabels(task);

    const head = document.createElement("div");
    head.className = "todo-task-card-head";

    const threadLead = document.createElement("div");
    threadLead.className = "todo-task-card-shell";

    const avatar = document.createElement("span");
    avatar.className = "todo-task-card-avatar";
    avatar.textContent = getUserInitials({ fullName: leadLabel || "Tema" });

    const copy = document.createElement("div");
    copy.className = "todo-task-card-copy";
    const title = document.createElement("strong");
    title.className = "todo-task-card-title";
    title.textContent = task.title;
    const subtitle = document.createElement("span");
    subtitle.className = "todo-task-card-subtitle";
    subtitle.textContent = [
      task.workOrderNumber ? `RN ${task.workOrderNumber}` : "",
      task.companyName || "",
    ].filter(Boolean).join(" · ");
    const preview = document.createElement("span");
    preview.className = "todo-task-card-preview";
    preview.textContent = (task.message || "Bez opisa teme.").replace(/\s+/g, " ").trim();
    copy.append(title, subtitle, preview);
    threadLead.append(avatar, copy);

    head.append(threadLead, createTodoTaskStatusControl(task));

    const meta = document.createElement("div");
    meta.className = "todo-task-card-meta";

    meta.append(createMetaPill(
      task.dueDate ? formatCompactDate(task.dueDate) : "Bez roka",
      isTodoTaskOverdue(task) ? "is-danger" : "is-soft",
    ));
    meta.append(createTodoTaskPriorityBadge(task.priority || "Normal"));
    meta.append(createMetaPill(`${task.commentCount ?? task.comments?.length ?? 0} komentara`, "is-soft"));
    if (task.updatedAt) {
      meta.append(createMetaPill(`Ažurirano ${formatCompactDate(String(task.updatedAt).slice(0, 10))}`, "is-soft"));
    }

    const participants = document.createElement("div");
    participants.className = "todo-task-card-participants";
    if (participantLabels.length === 0) {
      participants.append(createMetaPill("Bez sudionika", "is-soft"));
    } else {
      participantLabels.slice(0, 3).forEach((label) => {
        const badge = document.createElement("span");
        badge.className = "todo-task-card-participant";
        badge.textContent = label;
        participants.append(badge);
      });
      if (participantLabels.length > 3) {
        participants.append(createMetaPill(`+${participantLabels.length - 3}`, "is-soft"));
      }
    }

    const footer = document.createElement("div");
    footer.className = "todo-task-card-footer";
    const footerMain = document.createElement("div");
    footerMain.className = "todo-task-card-footer-main";
    footerMain.append(meta, participants);
    const footerActions = document.createElement("div");
    footerActions.className = "todo-task-card-footer-actions";
    footerActions.append(createTodoOpenTopicButton(task));
    footer.append(footerMain, footerActions);

    card.append(head, footer);
    const expandedPanel = createTodoTaskExpandedPanel(task);
    if (expandedPanel) {
      card.append(expandedPanel);
    }
    return card;
  }));

  if (todoEmpty) {
    todoEmpty.hidden = tasks.length !== 0;
  }
}

function renderTodoDetail() {
  if (!todoDetailPanel || !todoDetailEmpty || !todoDetailContent) {
    return;
  }

  const task = getTodoTaskById();

  todoDetailEmpty.hidden = Boolean(task);
  todoDetailContent.hidden = !task;

  if (!task) {
    if (todoCommentsBody) {
      todoCommentsBody.replaceChildren();
    }

    if (todoCommentsEmpty) {
      todoCommentsEmpty.hidden = false;
    }

    return;
  }

  if (todoDetailTitle) {
    todoDetailTitle.textContent = task.title;
  }

  if (todoDetailMeta) {
    todoDetailMeta.textContent = "";
    todoDetailMeta.hidden = true;
  }

  if (todoDetailMessage) {
    todoDetailMessage.textContent = task.message || "Bez opisa teme.";
  }

  if (todoDetailFacts) {
    const createFact = (label, classNames = []) => {
      const fact = document.createElement("span");
      fact.className = "todo-detail-fact-chip";
      classNames.forEach((className) => fact.classList.add(className));
      fact.textContent = label;
      return fact;
    };

    const status = getTodoTaskStatusValue(task);
    const facts = [];
    facts.push(
      createFact(
        getOptionLabel(TODO_TASK_STATUS_OPTIONS, status),
        [`is-status-${slugifyValue(status)}`],
      ),
    );
    facts.push(
      createFact(
        getOptionLabel(PRIORITY_OPTIONS, task.priority || "Normal"),
        [`is-priority-${slugifyValue(task.priority || "Normal")}`],
      ),
    );
    facts.push(
      createFact(
        task.dueDate ? `Rok ${formatCompactDate(task.dueDate)}` : "Bez roka",
        [isTodoTaskOverdue(task) ? "is-overdue" : "is-date"],
      ),
    );
    facts.push(createFact(`${task.commentCount ?? task.comments?.length ?? 0} komentara`, ["is-soft"]));

    if (task.updatedAt) {
      facts.push(createFact(`Ažurirano ${formatCompactDate(String(task.updatedAt).slice(0, 10))}`, ["is-soft"]));
    }

    todoDetailFacts.replaceChildren(...facts);
  }

  if (todoDetailStatus) {
    const status = getTodoTaskStatusValue(task);
    replaceSelectOptions(todoDetailStatus, TODO_TASK_STATUS_OPTIONS, status);
    todoDetailStatus.value = status;
    todoDetailStatus.dataset.taskId = task.id;
  }

  if (todoDetailPriority) {
    replaceSelectOptions(todoDetailPriority, PRIORITY_OPTIONS, task.priority || "Normal");
    todoDetailPriority.value = task.priority || "Normal";
    todoDetailPriority.dataset.taskId = task.id;
  }

  if (todoDetailAssignee) {
    rebuildTodoDetailAssigneeOptions(task.assignedToUserId || "");
    todoDetailAssignee.value = task.assignedToUserId || "";
    todoDetailAssignee.dataset.taskId = task.id;
  }

  if (todoDetailDueDate) {
    todoDetailDueDate.value = task.dueDate || "";
    todoDetailDueDate.dataset.taskId = task.id;
  }

  if (todoDetailInvitedUsersInput) {
    rebuildTodoDetailInvitedUserOptions(task.invitedUserIds ?? []);
    todoDetailInvitedUsersInput.dataset.taskId = task.id;
  }

  const participantEntries = [];
  const seenParticipants = new Set();
  const appendParticipant = (userId, fallbackLabel = "") => {
    const normalizedId = String(userId || "").trim();
    const user = normalizedId
      ? (state.users.find((item) => String(item?.id) === normalizedId) ?? null)
      : null;
    const label = user?.fullName || user?.email || fallbackLabel || "Osoba";
    const key = normalizedId ? `id:${normalizedId}` : `label:${label.toLowerCase()}`;
    if (!label || seenParticipants.has(key)) {
      return;
    }
    seenParticipants.add(key);
    participantEntries.push({ user, label });
  };

  appendParticipant(task.assignedToUserId, task.assignedToLabel || "");
  (Array.isArray(task.invitedUserIds) ? task.invitedUserIds : []).forEach((userId) => appendParticipant(userId, ""));
  (Array.isArray(task.invitedUserLabels) ? task.invitedUserLabels : []).forEach((label) => appendParticipant("", label));
  appendParticipant(task.createdByUserId, task.createdByLabel || "");

  if (todoDetailPeopleStack) {
    todoDetailPeopleStack.replaceChildren();
    if (participantEntries.length === 0) {
      todoDetailPeopleStack.append(createMetaPill("Bez sudionika", "is-soft"));
    } else {
      participantEntries.slice(0, 4).forEach((entry) => {
        const avatar = createWorkOrderMiniExecutor(
          { label: entry.label, user: entry.user },
          { className: "work-order-mini-executor todo-detail-person-avatar" },
        );
        avatar.title = entry.label;
        todoDetailPeopleStack.append(avatar);
      });
      if (participantEntries.length > 4) {
        todoDetailPeopleStack.append(createExecutorOverflowBadge(participantEntries.length - 4, "work-order-mini-executor todo-detail-person-avatar"));
      }
    }
  }

  if (todoDetailPeopleChips) {
    todoDetailPeopleChips.replaceChildren();
    if (participantEntries.length === 0) {
      const chip = document.createElement("span");
      chip.className = "todo-detail-person-chip is-soft";
      chip.textContent = "Bez pozvanih kolega";
      todoDetailPeopleChips.append(chip);
    } else {
      participantEntries.slice(0, 3).forEach((entry) => {
        const chip = document.createElement("span");
        chip.className = "todo-detail-person-chip";
        chip.textContent = entry.label;
        todoDetailPeopleChips.append(chip);
      });
      if (participantEntries.length > 3) {
        const extra = document.createElement("span");
        extra.className = "todo-detail-person-chip is-soft";
        extra.textContent = `+${participantEntries.length - 3}`;
        todoDetailPeopleChips.append(extra);
      }
    }
  }

  if (todoDetailOpenWorkOrder) {
    const linkedWorkOrder = getLinkedTodoWorkOrder(task);
    todoDetailOpenWorkOrder.hidden = !linkedWorkOrder;
    todoDetailOpenWorkOrder.onclick = linkedWorkOrder
      ? (() => {
        hydrateWorkOrderForm(linkedWorkOrder);
      })
      : null;
  }

  if (todoDetailEdit) {
    todoDetailEdit.onclick = () => {
      hydrateTodoTaskForm(task);
    };
  }

  if (todoDetailDelete) {
    todoDetailDelete.onclick = () => {
      if (!window.confirm(`Obrisati temu "${task.title}"?`)) {
        return;
      }

      void runMutation(() => apiRequest(`/todo-tasks/${task.id}`, {
        method: "DELETE",
      }), todoCommentError).then((success) => {
        if (success) {
          state.activeTodoTaskId = getFilteredTodoTasks()[0]?.id ?? "";
        }
      });
    };
  }

  if (todoCommentsBody) {
    todoCommentsBody.replaceChildren(...(task.comments ?? []).map((comment) => {
      const article = document.createElement("article");
      article.className = "todo-comment";
      const isOwnComment = String(comment.userId ?? "") === String(state.user?.id ?? "");
      article.classList.toggle("is-own", isOwnComment);

      const avatar = document.createElement("span");
      avatar.className = "todo-comment-avatar";
      avatar.textContent = getUserInitials({ fullName: comment.authorLabel });

      const content = document.createElement("div");
      content.className = "todo-comment-content";

      const top = document.createElement("div");
      top.className = "todo-comment-top";
      const author = document.createElement("strong");
      author.textContent = isOwnComment ? "Ti" : (comment.authorLabel || "SafeNexus");
      const time = document.createElement("span");
      time.textContent = formatDateTime(comment.createdAt);
      top.append(author, time);

      const body = document.createElement("p");
      body.className = "todo-comment-body";
      body.textContent = comment.message;

      content.append(top, body);
      article.append(avatar, content);
      return article;
    }));
  }

  if (todoCommentsEmpty) {
    todoCommentsEmpty.hidden = (task.comments?.length ?? 0) !== 0;
  }
}

function renderTodo() {
  syncTodoEditorModal();
  renderTodoSummary();
  renderTopbarShortcutCounts();
  renderTodoList();
  renderTodoDetail();
}

function isPurchaseOrdersContextActive() {
  return state.activeSidebarItem === "purchase-orders";
}

function getActiveCommercialDocumentKey() {
  return isPurchaseOrdersContextActive() ? "purchase-orders" : "offers";
}

function normalizeCommercialDocumentDirection(value = "", fallback = "outgoing") {
  const normalized = String(value || "").trim().toLowerCase();
  return ["incoming", "outgoing"].includes(normalized) ? normalized : fallback;
}

function ensureCommercialDocumentDirectionState() {
  if (!state.commercialDocumentDirections || typeof state.commercialDocumentDirections !== "object") {
    state.commercialDocumentDirections = {};
  }
  state.commercialDocumentDirections.offers = normalizeCommercialDocumentDirection(
    state.commercialDocumentDirections.offers,
    "outgoing",
  );
  state.commercialDocumentDirections["purchase-orders"] = normalizeCommercialDocumentDirection(
    state.commercialDocumentDirections["purchase-orders"],
    "outgoing",
  );
}

function getActiveCommercialDocumentDirection() {
  ensureCommercialDocumentDirectionState();
  return normalizeCommercialDocumentDirection(
    state.commercialDocumentDirections[getActiveCommercialDocumentKey()],
    "outgoing",
  );
}

function setActiveCommercialDocumentDirection(value = "outgoing") {
  ensureCommercialDocumentDirectionState();
  state.commercialDocumentDirections[getActiveCommercialDocumentKey()] = normalizeCommercialDocumentDirection(value, "outgoing");
}

function getActiveCommercialDocumentConfig() {
  return COMMERCIAL_DOCUMENT_MODULE_CONFIG[getActiveCommercialDocumentKey()] ?? COMMERCIAL_DOCUMENT_MODULE_CONFIG.offers;
}

function getActiveCommercialDocumentCollection() {
  return isPurchaseOrdersContextActive() ? (state.purchaseOrders ?? []) : (state.offers ?? []);
}

function getActiveCommercialStatusOptions() {
  return getActiveCommercialDocumentConfig().statusOptions ?? OFFER_STATUS_OPTIONS;
}

function getActiveCommercialApiBasePath() {
  return getActiveCommercialDocumentConfig().apiBasePath || "/offers";
}

function getActiveCommercialTemplateDefinitions() {
  return isPurchaseOrdersContextActive()
    ? PURCHASE_ORDER_TEMPLATE_PLACEHOLDER_DEFINITIONS
    : OFFER_TEMPLATE_PLACEHOLDER_DEFINITIONS;
}

function getActiveCommercialTemplateReferenceDraft() {
  return isPurchaseOrdersContextActive() ? purchaseOrderTemplateReferenceDraft : offerTemplateReferenceDraft;
}

function setActiveCommercialTemplateReferenceDraft(value) {
  if (isPurchaseOrdersContextActive()) {
    purchaseOrderTemplateReferenceDraft = value;
    return;
  }

  offerTemplateReferenceDraft = value;
}

function getCurrentCommercialDocumentById(id = "") {
  return getActiveCommercialDocumentCollection().find((item) => String(item.id) === String(id)) ?? null;
}

function getCommercialDocumentStatusLabel(status = "draft") {
  return getOptionLabel(getActiveCommercialStatusOptions(), status || getActiveCommercialDocumentConfig().defaultStatus) || status;
}

function getCommercialDocumentNumber(item = {}) {
  return isPurchaseOrdersContextActive()
    ? String(item.purchaseOrderNumber || "").trim()
    : String(item.offerNumber || "").trim();
}

function getCommercialDocumentDateValue(item = {}) {
  return isPurchaseOrdersContextActive()
    ? String(item.purchaseOrderDate || "").trim()
    : String(item.offerDate || "").trim();
}

function getOfferDateFieldValue() {
  return normalizeDateInputValue(offerDateInput?.value || "");
}

function setOfferDateFieldValue(value = "") {
  const normalizedValue = normalizeDateInputValue(value) || toDateKey(value) || "";
  if (offerDateInput) {
    offerDateInput.value = normalizedValue ? formatDateInputDisplayValue(normalizedValue) : "";
  }
  if (offerDatePickerInput) {
    offerDatePickerInput.value = normalizedValue || "";
  }
}

function normalizeOfferDateFieldDisplay() {
  const normalizedValue = getOfferDateFieldValue();
  if (offerDateInput) {
    offerDateInput.value = normalizedValue ? formatDateInputDisplayValue(normalizedValue) : String(offerDateInput.value || "").trim();
  }
  if (offerDatePickerInput) {
    offerDatePickerInput.value = normalizedValue || "";
  }
  return normalizedValue;
}

function openOfferDatePicker() {
  if (!offerDatePickerInput) {
    offerDateInput?.focus({ preventScroll: true });
    return;
  }

  offerDatePickerInput.value = getOfferDateFieldValue() || toDateKey(new Date());

  if (typeof offerDatePickerInput.showPicker === "function") {
    try {
      offerDatePickerInput.showPicker();
      return;
    } catch {
      // Browser can block showPicker on visually hidden inputs; the click fallback still keeps the date field usable.
    }
  }

  offerDatePickerInput.focus({ preventScroll: true });
  offerDatePickerInput.click();
}

function getCommercialDocumentDisplayName(item = {}) {
  const config = getActiveCommercialDocumentConfig();
  return String(item.title || "").trim() || config.untitledLabel;
}

function getCommercialDocumentIdentifierText(item = {}) {
  const config = getActiveCommercialDocumentConfig();
  return getCommercialDocumentNumber(item) || config.numberFallback;
}

function getCommercialDocumentDirectionLabel(value = "") {
  return String(value || "").trim().toLowerCase() === "outgoing" ? "Izlazna" : "Ulazna";
}

function getCommercialDocumentDirectionForItem(item = {}, contextKey = getActiveCommercialDocumentKey()) {
  return contextKey === "purchase-orders"
    ? normalizeCommercialDocumentDirection(item?.orderDirection, "incoming")
    : normalizeCommercialDocumentDirection(item?.offerDirection, "outgoing");
}

function isCommercialIncomingMode() {
  return getActiveCommercialDocumentDirection() === "incoming";
}

function isOutgoingStandaloneOfferMode() {
  return !isPurchaseOrdersContextActive()
    && getActiveCommercialDocumentDirection() === "outgoing"
    && Boolean(commercialStandaloneUploadInput?.checked);
}

function isCommercialQuickUploadMode() {
  return isCommercialIncomingMode() || Boolean(commercialStandaloneUploadInput?.checked);
}

function shouldShowCommercialDocumentUploadSection() {
  return isCommercialQuickUploadMode() || isPurchaseOrdersContextActive() || getActiveCommercialDocumentDirection() === "incoming";
}

function normalizeOfferPlanTypeValue(value = "") {
  const rawValue = String(value || "").trim();
  const normalizedValue = normalizeLooseName(rawValue);
  const legacyMap = new Map([
    ["fixed fee", "Fixed Plan"],
    ["flat plan", "Fixed Plan"],
    ["fixed plan", "Fixed Plan"],
    ["base fee variable fee", "Hybrid Plan"],
    ["base fee plus variable fee", "Hybrid Plan"],
    ["monthly per services", "Hybrid Plan"],
    ["hybrid plan", "Hybrid Plan"],
    ["one time", "One-Time Service"],
    ["one time service", "One-Time Service"],
    ["one-time", "One-Time Service"],
    ["one-time service", "One-Time Service"],
    ["per employee", "Per Employee Plan"],
    ["per employee plan", "Per Employee Plan"],
  ]);

  const directMatch = OFFER_PLAN_TYPE_DEFINITIONS.find((entry) => normalizeLooseName(entry.value) === normalizedValue);
  return directMatch?.value || legacyMap.get(normalizedValue) || rawValue;
}

function getOfferPlanTypeDefinition(value = "") {
  const normalizedValue = normalizeOfferPlanTypeValue(value);
  return OFFER_PLAN_TYPE_DEFINITIONS.find((entry) => entry.value === normalizedValue)
    || OFFER_PLAN_TYPE_DEFINITIONS[0];
}

function isOfferPlanEditorActive() {
  return !isPurchaseOrdersContextActive()
    && getActiveCommercialDocumentDirection() === "outgoing"
    && !isCommercialQuickUploadMode();
}

function getActiveOfferPlanTypeDefinition() {
  return getOfferPlanTypeDefinition(offerServiceLineInput?.value || "");
}

function shouldOfferPlanAllowBreakdowns() {
  return !isOfferPlanEditorActive() || getActiveOfferPlanTypeDefinition().allowBreakdowns !== false;
}

function shouldOfferPlanAllowMultipleItems() {
  return !isOfferPlanEditorActive() || getActiveOfferPlanTypeDefinition().allowMultipleItems !== false;
}

function hasMeaningfulOfferItemDraft(item = {}) {
  return Boolean(
    String(item.description || "").trim()
      || String(item.unit || "").trim()
      || String(item.quantity || "").trim()
      || String(item.unitPrice || "").trim()
      || String(item.discountRate || "").trim()
      || (Array.isArray(item.breakdowns) && item.breakdowns.some((entry) => (
        String(entry.recordLabel || entry.label || entry.unitLabel || "").trim()
        || String(entry.measurementFrom || "").trim()
        || String(entry.measurementTo || "").trim()
        || String(entry.amount || "").trim()
      ))),
  );
}

function isOfferFormUsingPlanDefaults() {
  if (!Array.isArray(offerFormItems) || offerFormItems.length === 0) {
    return true;
  }

  const defaultLabels = new Set(OFFER_PLAN_DEFAULT_ITEM_LABELS.map((label) => normalizeLooseName(label)));
  return offerFormItems.every((item) => {
    const description = normalizeLooseName(item.description || "");
    const hasMoney = parseOfferMoneyInput(item.unitPrice, 0) > 0
      || parseOfferMoneyInput(item.discountRate, 0) > 0
      || (Array.isArray(item.breakdowns) && item.breakdowns.some((entry) => parseOfferMoneyInput(entry.amount, 0) > 0));
    return !hasMoney && (!description || defaultLabels.has(description));
  });
}

function buildOfferPlanDefaultItems(planDefinition = getActiveOfferPlanTypeDefinition()) {
  switch (planDefinition.value) {
    case "Hybrid Plan":
      return [
        createEmptyOfferItemDraft({
          description: "Mjesečni iznos",
          unit: "mj",
          quantity: "1",
          unitPrice: "",
          breakdowns: [],
        }),
        createEmptyOfferItemDraft({
          description: "Usluge po izvršenju",
          unit: "usluga",
          quantity: "1",
          unitPrice: "",
          breakdowns: createDefaultOfferBreakdownDrafts(),
        }),
      ];
    case "One-Time Service":
      return [
        createEmptyOfferItemDraft({
          description: "One-Time Service",
          unit: "kom",
          quantity: "1",
          unitPrice: "",
        }),
      ];
    case "Per Employee Plan":
      return [
        createEmptyOfferItemDraft({
          description: "Per Employee Plan",
          unit: "zaposlenik",
          quantity: "",
          unitPrice: "",
        }),
      ];
    case "Fixed Plan":
    default:
      return [
        createOfferFixedItemDraft(),
      ];
  }
}

function createOfferFixedItemDraft() {
  return createEmptyOfferItemDraft({
    description: "",
    unit: "",
    quantity: "1",
    unitPrice: "",
  });
}

function createOfferIncludedServiceDraft(service = {}) {
  return createEmptyOfferItemDraft({
    description: service.name || service.serviceCode || "",
    serviceCatalogId: service.id ? String(service.id) : "",
    serviceCode: service.serviceCode || "",
    isIncludedService: true,
    unit: "",
    quantity: "",
    unitPrice: "",
    discountRate: "",
    breakdowns: [],
  });
}

function createOfferMainFeeDraft() {
  return createEmptyOfferItemDraft({
    description: "Mjesečni paušal",
    unit: "mj",
    quantity: "1",
    unitPrice: "",
  });
}

function isOfferMainFeeItemDraft(item = {}) {
  const unit = String(item?.unit || "").trim().toLowerCase();
  const description = String(item?.description || "").trim().toLowerCase();
  return unit === "mj"
    || unit === "mjesec"
    || unit === "mjesečno"
    || description.includes("mjese")
    || description.includes("paušal")
    || description.includes("pausal");
}

function createOfferAdditionalItemDraftForCurrentPlan() {
  const planDefinition = getActiveOfferPlanTypeDefinition();

  if (isOfferPlanEditorActive() && planDefinition.value === "Fixed Plan") {
    return createOfferFixedItemDraft();
  }

  if (isOfferPlanEditorActive() && planDefinition.value === "Hybrid Plan") {
    return createEmptyOfferItemDraft({
      description: "",
      unit: "usluga",
      quantity: "1",
      unitPrice: "",
      breakdowns: createDefaultOfferBreakdownDrafts(),
    });
  }

  return createEmptyOfferItemDraft();
}

function sanitizeOfferItemsForCurrentPlan(items = offerFormItems) {
  if (shouldOfferPlanAllowBreakdowns()) {
    return items.map((item) => (
      isOfferMainFeeItemDraft(item)
        ? { ...item, isIncludedService: false, breakdowns: [], showBreakdowns: false }
        : { ...item, isIncludedService: false }
    ));
  }

  const isFixedPlan = isOfferPlanEditorActive() && getActiveOfferPlanTypeDefinition().value === "Fixed Plan";

  return items.map((item) => ({
    ...item,
    isIncludedService: isFixedPlan && Boolean(item.isIncludedService),
    unit: isFixedPlan && item.isIncludedService ? "" : item.unit,
    quantity: isFixedPlan && item.isIncludedService ? "" : item.quantity,
    unitPrice: isFixedPlan && item.isIncludedService ? "" : item.unitPrice,
    discountRate: isFixedPlan && item.isIncludedService ? "" : item.discountRate,
    showDiscount: isFixedPlan && item.isIncludedService ? false : item.showDiscount,
    breakdowns: [],
    showBreakdowns: false,
  }));
}

function applyOfferPlanTypeToForm({ forceDefaults = false } = {}) {
  if (!isOfferPlanEditorActive()) {
    return;
  }

  const planDefinition = getActiveOfferPlanTypeDefinition();
  if (offerServiceLineInput) {
    offerServiceLineInput.value = planDefinition.value;
  }

  const shouldUseDefaults = forceDefaults
    || offerFormItems.length === 0
    || offerFormItems.every((item) => !hasMeaningfulOfferItemDraft(item))
    || isOfferFormUsingPlanDefaults();

  if (shouldUseDefaults) {
    offerFormItems = buildOfferPlanDefaultItems(planDefinition);
    renderOfferItemRows();
    return;
  }

  const sanitizedItems = sanitizeOfferItemsForCurrentPlan(offerFormItems);
  const changed = sanitizedItems.some((item, index) => item !== offerFormItems[index]);
  if (changed) {
    offerFormItems = sanitizedItems;
    renderOfferItemRows();
  } else {
    syncCommercialQuickUploadMode();
    syncOfferTotals();
  }
}

function getCommercialDocumentUploadCategoryLabel() {
  if (isPurchaseOrdersContextActive()) {
    return getActiveCommercialDocumentDirection() === "outgoing"
      ? "Narudžbenica koju šaljemo"
      : "Zaprimljena narudžbenica";
  }

  return isOutgoingStandaloneOfferMode() ? "Samostalna ponuda" : "Zaprimljena ponuda";
}

function readOfferExtraTextTemplates() {
  const stored = readJsonFromLocalStorage(OFFER_TEXT_TEMPLATE_STORAGE_KEY, []);
  return (Array.isArray(stored) ? stored : [])
    .map((template) => ({
      id: String(template?.id || crypto.randomUUID()),
      label: String(template?.label || "").trim(),
      textBlock1: String(template?.textBlock1 || "").trim(),
      textBlock2: String(template?.textBlock2 || "").trim(),
    }))
    .filter((template) => template.label && (template.textBlock1 || template.textBlock2));
}

function writeOfferExtraTextTemplates(templates = []) {
  writeJsonToLocalStorage(
    OFFER_TEXT_TEMPLATE_STORAGE_KEY,
    (Array.isArray(templates) ? templates : [])
      .map((template) => ({
        id: String(template.id || crypto.randomUUID()),
        label: String(template.label || "").trim(),
        textBlock1: String(template.textBlock1 || "").trim(),
        textBlock2: String(template.textBlock2 || "").trim(),
      }))
      .filter((template) => template.label && (template.textBlock1 || template.textBlock2)),
  );
}

function renderOfferExtraTextTemplateControls() {
  if (offerTextTemplateSelect) {
    const templates = readOfferExtraTextTemplates();
    replaceSelectOptions(
      offerTextTemplateSelect,
      [
        { value: "", label: templates.length ? "Odaberi spremljeni tekst" : "Nema spremljenih tekstova" },
        ...templates.map((template) => ({
          value: template.id,
          label: template.label,
        })),
      ],
      "",
    );
  }

  if (offerTextPlaceholderButtons) {
    offerTextPlaceholderButtons.replaceChildren(...OFFER_TEXT_PLACEHOLDER_KEYS.map((key) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "ghost-button offer-text-placeholder-button";
      button.dataset.offerTextPlaceholder = key;
      button.textContent = `{{${key}}}`;
      return button;
    }));
  }
}

function getActiveOfferTextBlockInput() {
  const active = document.activeElement;
  if (active === offerTextBlock1Input || active === offerTextBlock2Input) {
    return active;
  }
  return offerTextBlock1Input || offerTextBlock2Input || null;
}

function insertOfferTextPlaceholder(key = "") {
  const textarea = getActiveOfferTextBlockInput();
  const placeholder = `{{${String(key || "").trim()}}}`;
  if (!textarea || !placeholder.match(/^\{\{[A-Z0-9_]+\}\}$/)) {
    return;
  }
  const start = Number(textarea.selectionStart ?? textarea.value.length);
  const end = Number(textarea.selectionEnd ?? start);
  textarea.value = `${textarea.value.slice(0, start)}${placeholder}${textarea.value.slice(end)}`;
  const nextCaret = start + placeholder.length;
  textarea.focus();
  textarea.setSelectionRange(nextCaret, nextCaret);
  textarea.dispatchEvent(new Event("input", { bubbles: true }));
}

function applyOfferExtraTextTemplate(templateId = "") {
  const template = readOfferExtraTextTemplates().find((entry) => String(entry.id) === String(templateId));
  if (!template) {
    return;
  }
  if (offerTextBlock1Input) {
    offerTextBlock1Input.value = template.textBlock1 || "";
  }
  if (offerTextBlock2Input) {
    offerTextBlock2Input.value = template.textBlock2 || "";
  }
  if (state.offerTemplateModalOpen) {
    renderOfferTemplatePlaceholderList();
  }
}

function saveOfferExtraTextTemplate() {
  const textBlock1 = String(offerTextBlock1Input?.value || "").trim();
  const textBlock2 = String(offerTextBlock2Input?.value || "").trim();
  if (!textBlock1 && !textBlock2) {
    setInlineMessage(offerError, "Upiši dodatni tekst koji želiš spremiti kao template.");
    return;
  }

  const fallbackName = (textBlock1 || textBlock2).split(/\s+/).slice(0, 6).join(" ").slice(0, 70) || "Template teksta";
  const label = String(window.prompt("Naziv templatea", fallbackName) || "").trim();
  if (!label) {
    return;
  }

  const templates = readOfferExtraTextTemplates();
  writeOfferExtraTextTemplates([
    ...templates.filter((template) => template.label.toLowerCase() !== label.toLowerCase()),
    {
      id: crypto.randomUUID(),
      label,
      textBlock1,
      textBlock2,
    },
  ]);
  renderOfferExtraTextTemplateControls();
  setInlineMessage(offerError, `Spremljen template dodatnog teksta: ${label}.`, "success");
}

function syncOfferExtraTextControls() {
  const isPurchaseOrder = isPurchaseOrdersContextActive();
  const quickUploadMode = isCommercialQuickUploadMode();
  const toggleWrapper = offerExtraTextEnabledInput?.closest(".offer-extra-text-toggle");
  const shouldHideExtraTexts = isPurchaseOrder || quickUploadMode;
  if (shouldHideExtraTexts && offerExtraTextEnabledInput) {
    offerExtraTextEnabledInput.checked = false;
  }
  if (shouldHideExtraTexts) {
    if (offerTextBlock1Input) {
      offerTextBlock1Input.value = "";
    }
    if (offerTextBlock2Input) {
      offerTextBlock2Input.value = "";
    }
  }
  if (toggleWrapper) {
    toggleWrapper.hidden = shouldHideExtraTexts;
  }
  if (offerTextBlocks) {
    offerTextBlocks.hidden = shouldHideExtraTexts || !isOfferExtraTextEnabled();
  }
  if (!shouldHideExtraTexts && isOfferExtraTextEnabled()) {
    renderOfferExtraTextTemplateControls();
  }
}

function serializeModuleAttachmentDraft(document = {}) {
  return {
    id: String(document.id || crypto.randomUUID()),
    fileName: String(document.fileName || "").trim(),
    fileType: String(document.fileType || "").trim(),
    fileSize: Number(document.fileSize || 0) || 0,
    documentCategory: String(document.documentCategory || "").trim(),
    sourceDocumentId: String(document.sourceDocumentId || "").trim(),
    previewStatus: String(document.previewStatus || "").trim(),
    previewError: String(document.previewError || "").trim(),
    description: String(document.description || "").trim(),
    dataUrl: String(document.dataUrl || document.storageUrl || "").trim(),
    storageProvider: String(document.storageProvider || "").trim(),
    storageBucket: String(document.storageBucket || "").trim(),
    storageKey: String(document.storageKey || "").trim(),
    storageUrl: String(document.storageUrl || document.dataUrl || "").trim(),
    createdAt: String(document.createdAt || "").trim(),
    updatedAt: String(document.updatedAt || document.createdAt || "").trim(),
  };
}

function buildCommercialStatusSelectOptions(options = getActiveCommercialStatusOptions()) {
  return options.map((option) => ({
    value: option.value,
    label: option.label,
  }));
}

function buildCommercialFilterStatusOptions(options = getActiveCommercialStatusOptions()) {
  return [
    { value: "all", label: "Svi statusi" },
    ...buildCommercialStatusSelectOptions(options),
  ];
}

function syncCommercialQuickUploadMode() {
  const isPurchaseOrder = isPurchaseOrdersContextActive();
  const activeDirection = getActiveCommercialDocumentDirection();
  const incomingMode = activeDirection === "incoming";
  const outgoingStandaloneOffer = isOutgoingStandaloneOfferMode();
  const quickMode = isCommercialQuickUploadMode();
  const offerPlanEditorActive = isOfferPlanEditorActive();
  const offerPlanDefinition = getActiveOfferPlanTypeDefinition();
  const forceOfferTotalForFixed = offerPlanEditorActive && offerPlanDefinition.value === "Fixed Plan";
  const suppressOfferTotalForPlan = offerPlanEditorActive
    && offerPlanDefinition.value === "Hybrid Plan";
  const shouldShowUploads = shouldShowCommercialDocumentUploadSection();
  const quickTitleLabel = isPurchaseOrder ? "Što je naručeno" : (incomingMode ? "Što je ponuđeno" : "Naziv ponude");
  const standaloneToggleField = commercialStandaloneUploadInput?.closest(".commercial-standalone-upload-field");
  offerForm?.classList.toggle("is-commercial-quick-upload", quickMode);
  offerForm?.classList.toggle("is-commercial-standalone-offer", outgoingStandaloneOffer);
  offerForm?.classList.toggle("is-offer-plan-no-breakdowns", offerPlanEditorActive && offerPlanDefinition.allowBreakdowns === false);
  offerForm?.classList.toggle("is-offer-plan-hybrid", offerPlanEditorActive && offerPlanDefinition.value === "Hybrid Plan");
  if (standaloneToggleField) {
    standaloneToggleField.hidden = incomingMode;
  }
  if (incomingMode && commercialStandaloneUploadInput) {
    commercialStandaloneUploadInput.checked = true;
  }
  if (quickMode) {
    if (offerTitleLabel) {
      offerTitleLabel.textContent = quickTitleLabel;
    }
    if (offerTitleInput) {
      offerTitleInput.placeholder = isPurchaseOrdersContextActive()
        ? "Npr. narudžbenica za servis, opremu ili ispitivanje..."
        : (incomingMode
          ? "Npr. ponuda dobavljača za umjernicu, opremu ili uslugu..."
          : "Npr. godišnje održavanje, ispitivanje, servis...");
    }
  } else {
    const config = getActiveCommercialDocumentConfig();
    if (offerTitleLabel) {
      offerTitleLabel.textContent = config.titleLabel;
    }
    if (offerTitleInput) {
      offerTitleInput.placeholder = config.titlePlaceholder;
    }
  }
  offerServiceLineInput?.closest(".field")?.toggleAttribute("hidden", quickMode && !outgoingStandaloneOffer);
  if (offerServiceLineInput) {
    offerServiceLineInput.required = !quickMode || outgoingStandaloneOffer;
    offerServiceLineInput.disabled = quickMode && !outgoingStandaloneOffer;
  }
  if (offerServiceLineLabel) {
    offerServiceLineLabel.textContent = (outgoingStandaloneOffer || offerPlanEditorActive)
      ? "Vrsta ponude"
      : getActiveCommercialDocumentConfig().serviceLineLabel;
  }
  if (offerPlanEditorActive && offerServiceLineInput) {
    if ("placeholder" in offerServiceLineInput) {
      offerServiceLineInput.placeholder = "Fixed Plan, Hybrid Plan, One-Time Service, Per Employee Plan...";
    }
  }
  if (offerUploadAmountField) {
    offerUploadAmountField.hidden = !outgoingStandaloneOffer;
  }
  syncOfferExtraTextControls();
  offerTaxRateInput?.closest(".offer-tax-field")?.toggleAttribute("hidden", quickMode);
  offerAddItemButton?.closest(".offers-items-head")?.toggleAttribute("hidden", quickMode);
  if (offerPlanEditorActive) {
    if (offerItemsTitle) {
      offerItemsTitle.textContent = offerPlanDefinition.itemsTitle;
    }
    if (offerItemsHelp) {
      offerItemsHelp.textContent = offerPlanDefinition.help;
    }
    if (offerAddItemButton) {
      offerAddItemButton.hidden = offerPlanDefinition.allowMultipleItems === false;
      offerAddItemButton.textContent = offerPlanDefinition.addButtonLabel;
    }
    if (offerCopyPricingButton) {
      offerCopyPricingButton.hidden = false;
    }
  } else if (offerAddItemButton) {
    offerAddItemButton.hidden = false;
    offerAddItemButton.textContent = isPurchaseOrder ? "+ Dodaj stavku" : "+ Dodaj uslugu";
    if (offerCopyPricingButton) {
      offerCopyPricingButton.hidden = isPurchaseOrder || quickMode;
    }
  }
  offerItems?.toggleAttribute("hidden", quickMode);
  offerTotalsCard?.toggleAttribute("hidden", quickMode || suppressOfferTotalForPlan);
  if (forceOfferTotalForFixed && !isOfferTotalVisible()) {
    setOfferTotalVisibility(true);
  }
  offerPreviewButton?.closest(".offers-editor-meta-actions")?.toggleAttribute("hidden", false);
  if (offerTotalPreviewBlock) {
    offerTotalPreviewBlock.hidden = quickMode || suppressOfferTotalForPlan || (!forceOfferTotalForFixed && !isOfferTotalVisible());
  }
  const showCommercialNumberFields = quickMode && !outgoingStandaloneOffer;
  if (commercialInternalNumberField) {
    commercialInternalNumberField.hidden = !showCommercialNumberFields;
  }
  if (commercialExternalNumberField) {
    commercialExternalNumberField.hidden = !showCommercialNumberFields;
  }
  if (commercialInternalNumberLabel) {
    commercialInternalNumberLabel.textContent = isPurchaseOrder
      ? "Interni broj narudžbenice"
      : "Broj ponude";
  }
  if (commercialExternalNumberLabel) {
    commercialExternalNumberLabel.textContent = isPurchaseOrder
      ? "Broj narudžbenice"
      : "Broj ponude klijenta";
  }
  if (commercialInternalNumberInput) {
    commercialInternalNumberInput.placeholder = isPurchaseOrder
      ? "Naš interni broj..."
      : "Broj ponude...";
  }
  if (commercialExternalNumberInput) {
    commercialExternalNumberInput.placeholder = isPurchaseOrder
      ? "Broj s dokumenta..."
      : "Broj ponude klijenta...";
  }

  if (purchaseOrderDocumentsSection) {
    purchaseOrderDocumentsSection.hidden = !shouldShowUploads;
  }
  if (purchaseOrderDocumentsTitle) {
    purchaseOrderDocumentsTitle.textContent = isPurchaseOrder
      ? "Dokumenti narudžbenice"
      : (outgoingStandaloneOffer ? "Dokumenti samostalne ponude" : "Dokumenti primljene ponude");
  }
  if (purchaseOrderDocumentsHelp) {
    purchaseOrderDocumentsHelp.textContent = isPurchaseOrder
      ? "Odaberi tvrtku, upiši što je naručeno i učitaj PDF, sken ili zaprimljenu narudžbenicu."
      : (outgoingStandaloneOffer
        ? "Ponuda je izrađena izvan aplikacije. Učitaj gotov PDF ili Word i upiši iznos za evidenciju."
        : "Odaberi tvrtku, upiši što je ponuđeno i učitaj PDF ili sken ponude koja je došla prema nama.");
  }
}

