function openVehicleDocumentPreview(documentItem = null) {
  const href = String(documentItem?.storageUrl || documentItem?.dataUrl || "").trim();

  if (!href) {
    return;
  }

  window.open(href, "_blank", "noopener");
}

function renderVehicleDocuments() {
  if (!vehicleDocumentsList) {
    return;
  }

  if (vehicleDocumentDrafts.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Još nema dodanih dokumenata za ovo vozilo.";
    vehicleDocumentsList.replaceChildren(empty);
    return;
  }

  vehicleDocumentsList.replaceChildren(...vehicleDocumentDrafts.map((entry) => {
    const row = document.createElement("article");
    row.className = "module-attachment-row";
    row.classList.toggle("is-unclassified", !entry.documentCategory);

    const copy = document.createElement("div");
    copy.className = "module-attachment-copy";

    const title = document.createElement("strong");
    title.textContent = entry.fileName || "Dokument";

    const meta = document.createElement("span");
    meta.textContent = [
      getVehicleDocumentCategoryLabel(entry.documentCategory),
      formatFileSize(entry.fileSize),
      entry.updatedAt ? formatCompactDateTime(entry.updatedAt) : "",
    ].filter(Boolean).join(" | ");
    copy.append(title, meta);

    if (entry.description) {
      const description = document.createElement("p");
      description.className = "module-attachment-description";
      description.textContent = entry.description;
      copy.append(description);
    }

    const middle = document.createElement("div");
    middle.className = "module-attachment-middle";

    const categorySelect = document.createElement("select");
    categorySelect.className = "module-attachment-category-select";
    replaceSelectOptions(categorySelect, VEHICLE_DOCUMENT_CATEGORY_OPTIONS, entry.documentCategory || "");
    categorySelect.addEventListener("change", () => {
      entry.documentCategory = categorySelect.value || "";
      entry.updatedAt = new Date().toISOString();
      row.classList.toggle("is-unclassified", !entry.documentCategory);
      renderVehicleDocuments();
    });
    middle.append(categorySelect);

    const actions = document.createElement("div");
    actions.className = "module-attachment-actions";
    actions.append(
      createIconActionButton("Pregled", "preview", "", () => {
        openVehicleDocumentPreview(entry);
      }),
      createIconActionButton("Preuzmi", "download", "", () => {
        triggerModuleAttachmentDownload(entry);
      }),
      createIconActionButton("Makni", "trash", "card-danger", () => {
        vehicleDocumentDrafts = vehicleDocumentDrafts.filter((item) => String(item.id) !== String(entry.id));
        renderVehicleDocuments();
      }),
    );

    row.append(copy, middle, actions);
    return row;
  }));
}

async function queueVehicleDocuments(
  files,
  {
    defaultCategory = "",
    defaultDescription = "",
  } = {},
) {
  const uploads = await buildWorkOrderDocumentUploadPayload(files);
  const normalizedCategory = String(defaultCategory || "").trim().toLowerCase();
  const normalizedDescription = String(defaultDescription || "").trim();
  vehicleDocumentDrafts = [
    ...vehicleDocumentDrafts,
    ...uploads.map((file) => createModuleAttachmentDraft({
      ...file,
      documentCategory: normalizedCategory,
      description: normalizedDescription,
    })),
  ];
  renderVehicleDocuments();
}

function isVehicleTripDraft(entry = {}) {
  return normalizeVehicleActivityTypeValue(entry.activityType) === "vehicle_trip"
    || Boolean(
      String(entry.departureAt || "").trim()
      || String(entry.returnAt || "").trim()
      || String(entry.startKm || "").trim()
      || String(entry.endKm || "").trim()
      || String(entry.tripStatus || "").trim()
    );
}

function formatVehicleTripDatePart(value = "") {
  const normalized = String(value || "").trim();
  if (!normalized) return "";
  const dateValue = normalized.includes("T") ? normalized : normalized.slice(0, 10);
  return formatCompactDate(dateValue) || normalized.slice(0, 10);
}

function formatVehicleTripTimePart(value = "") {
  const normalized = String(value || "").trim();
  if (!normalized || !normalized.includes("T")) return "";
  const parsed = new Date(normalized);
  if (Number.isNaN(parsed.getTime())) {
    return normalized.slice(11, 16);
  }
  return parsed.toLocaleTimeString("hr-HR", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
}

function getVehicleTripDrivers(entry = {}) {
  const labels = Array.isArray(entry.driverLabels) ? entry.driverLabels : [];
  return labels.map((value) => String(value || "").trim()).filter(Boolean).join(", ")
    || String(entry.performedBy || "").trim();
}

function getVehicleTripCondition(entry = {}) {
  return [
    entry.returnCondition,
    entry.vehicleCondition,
    entry.departureCondition,
    entry.note,
  ].map((value) => String(value || "").trim()).filter(Boolean)[0] || "";
}

function getVehicleTripDocumentCategoryLabel(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  return VEHICLE_TRIP_DOCUMENT_CATEGORY_LABELS.get(normalized)
    || VEHICLE_DOCUMENT_CATEGORY_LABELS.get(normalized)
    || String(value || "").trim()
    || "Prilog";
}

function getVehicleTripWorkOrderLabel(workOrder = null) {
  if (!workOrder) {
    return "";
  }
  return [
    workOrder.workOrderNumber || workOrder.displayNumber || workOrder.number || "RN",
    workOrder.companyName || "",
    workOrder.locationName || "",
  ].filter(Boolean).join(" | ");
}

function getVehicleTripLinkedWorkOrder(trip = {}) {
  const linkedId = String(trip.linkedWorkOrderId || trip.workOrderId || "").trim();
  if (!linkedId) {
    return null;
  }
  return (state.workOrders ?? []).find((item) => String(item.id) === linkedId) ?? null;
}

function buildVehicleTripWorkOrderOptions(selectedValue = "", filters = "") {
  const selectedId = String(selectedValue || "").trim();
  const normalizedFilters = filters && typeof filters === "object"
    ? filters
    : { startDate: String(filters || "").trim().slice(0, 10), endDate: String(filters || "").trim().slice(0, 10) };
  const startDateKey = String(normalizedFilters.startDate || "").trim().slice(0, 10);
  const endDateKey = String(normalizedFilters.endDate || startDateKey || "").trim().slice(0, 10);
  const strict = Boolean(normalizedFilters.strict);
  const filterUsers = (Array.isArray(normalizedFilters.users) ? normalizedFilters.users : [])
    .filter(Boolean);
  const filterUserIds = new Set([
    ...(Array.isArray(normalizedFilters.userIds) ? normalizedFilters.userIds : []),
    ...filterUsers.map((user) => user.id),
  ].map((value) => String(value || "").trim()).filter(Boolean));
  const filterUserLabels = [
    ...(Array.isArray(normalizedFilters.userLabels) ? normalizedFilters.userLabels : []),
    ...filterUsers.flatMap((user) => [
      user.fullName,
      user.displayName,
      user.username,
      user.email,
    ]),
    ...(!filterUsers.length && !filterUserIds.size ? [
      state.user?.fullName,
      state.user?.displayName,
      state.user?.username,
      state.user?.email,
    ] : []),
  ].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean);
  const isAssignedToSelectedUsers = (workOrder = {}) => {
    const ids = [
      ...(Array.isArray(workOrder.executorUserIds) ? workOrder.executorUserIds : []),
      ...(Array.isArray(workOrder.executorIds) ? workOrder.executorIds : []),
      ...(Array.isArray(workOrder.assignedUserIds) ? workOrder.assignedUserIds : []),
      workOrder.assignedToUserId,
      workOrder.executorUserId,
    ].map((value) => String(value || "").trim()).filter(Boolean);
    if (ids.some((id) => filterUserIds.has(id))) {
      return true;
    }
    const labels = [
      ...getWorkOrderExecutors(workOrder),
      ...(Array.isArray(workOrder.executors) ? workOrder.executors : []),
      workOrder.executor,
      workOrder.executor1,
      workOrder.executor2,
      workOrder.assignedTo,
    ].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean);
    return labels.some((label) => filterUserLabels.some((userLabel) => label === userLabel || label.includes(userLabel) || userLabel.includes(label)));
  };
  const getWorkOrderExecutionDay = (workOrder = {}) => String(
    workOrder.executionDate
      || workOrder.execution_date
      || workOrder.executionAt
      || workOrder.plannedExecutionDate
      || "",
  ).slice(0, 10);
  const isInDateRange = (workOrder = {}) => {
    const executionDay = getWorkOrderExecutionDay(workOrder);
    if (!startDateKey || !executionDay) {
      return !strict || selectedId === String(workOrder.id || "");
    }
    if (endDateKey) {
      return executionDay >= startDateKey && executionDay <= endDateKey;
    }
    return executionDay === startDateKey;
  };
  const ranked = sortWorkOrders(state.workOrders ?? [])
    .filter((workOrder) => {
      const id = String(workOrder.id || "");
      if (id && id === selectedId) {
        return true;
      }
      if (strict && !isInDateRange(workOrder)) {
        return false;
      }
      if (strict && (filterUserLabels.length || filterUserIds.size) && !isAssignedToSelectedUsers(workOrder)) {
        return false;
      }
      return true;
    })
    .map((workOrder) => {
      const executionDay = getWorkOrderExecutionDay(workOrder);
      const rank = [
        isInDateRange(workOrder) ? 0 : 1,
        isAssignedToSelectedUsers(workOrder) ? 0 : 1,
      ];
      return { workOrder, rank };
    })
    .sort((left, right) => (
      left.rank[0] - right.rank[0]
      || left.rank[1] - right.rank[1]
      || String(left.workOrder.workOrderNumber || left.workOrder.displayNumber || "").localeCompare(String(right.workOrder.workOrderNumber || right.workOrder.displayNumber || ""))
    ));
  return [
    { value: "", label: "Bez povezanog RN-a" },
    ...ranked.slice(0, 250).map(({ workOrder }) => ({
      value: String(workOrder.id || ""),
      label: getVehicleTripWorkOrderLabel(workOrder),
    })),
  ].filter((option, index, list) => (
    option.value === "" || option.value === selectedId || list.findIndex((item) => item.value === option.value) === index
  ));
}

function updateVehicleTripDraft(tripId, patch = {}) {
  updateVehicleActivityDraft(tripId, patch);
  renderVehicleTrips();
}

async function queueVehicleTripDocuments(tripId, files, documentCategory = "putni_nalog") {
  const uploadFiles = Array.from(files ?? []);
  if (!uploadFiles.length) {
    return;
  }
  const category = String(documentCategory || "putni_nalog").trim().toLowerCase();
  const uploads = await buildWorkOrderDocumentUploadPayload(
    uploadFiles,
    uploadFiles.map((file) => ({
      file,
      documentCategory: getVehicleTripDocumentCategoryLabel(category),
      description: "Prilog putovanja vozila",
    })),
  );
  vehicleActivityDrafts = vehicleActivityDrafts.map((entry) => {
    if (String(entry.id) !== String(tripId)) {
      return entry;
    }
    return {
      ...entry,
      documents: [
        ...(Array.isArray(entry.documents) ? entry.documents : []),
        ...uploads.map((file) => createModuleAttachmentDraft({
          ...file,
          documentCategory: category,
          description: getVehicleTripDocumentCategoryLabel(category),
          updatedAt: new Date().toISOString(),
        })),
      ],
      updatedAt: new Date().toISOString(),
    };
  }).sort(compareVehicleActivityDraftRecency);
  renderVehicleTrips();
}

function removeVehicleTripDocument(tripId, documentId) {
  vehicleActivityDrafts = vehicleActivityDrafts.map((entry) => {
    if (String(entry.id) !== String(tripId)) {
      return entry;
    }
    return {
      ...entry,
      documents: (Array.isArray(entry.documents) ? entry.documents : []).filter((documentItem) => String(documentItem.id) !== String(documentId)),
      updatedAt: new Date().toISOString(),
    };
  }).sort(compareVehicleActivityDraftRecency);
  renderVehicleTrips();
}

function updateVehicleTripDocument(tripId, documentId, patch = {}) {
  vehicleActivityDrafts = vehicleActivityDrafts.map((entry) => {
    if (String(entry.id) !== String(tripId)) {
      return entry;
    }
    return {
      ...entry,
      documents: (Array.isArray(entry.documents) ? entry.documents : []).map((documentItem) => (
        String(documentItem.id) === String(documentId)
          ? { ...documentItem, ...patch, updatedAt: new Date().toISOString() }
          : documentItem
      )),
      updatedAt: new Date().toISOString(),
    };
  }).sort(compareVehicleActivityDraftRecency);
  renderVehicleTrips();
}

function renderVehicleTrips() {
  if (!vehicleTripList) {
    return;
  }

  const trips = vehicleActivityDrafts
    .filter(isVehicleTripDraft)
    .sort((left, right) => String(right.departureAt || right.createdAt || "").localeCompare(String(left.departureAt || left.createdAt || "")));

  if (trips.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Još nema evidentiranih putovanja za ovo vozilo.";
    vehicleTripList.replaceChildren(empty);
    return;
  }

  vehicleTripList.replaceChildren(...trips.map((trip) => {
    const card = document.createElement("article");
    card.className = "vehicle-trip-card";
    card.classList.toggle("is-open", !trip.returnAt);

    const head = document.createElement("div");
    head.className = "vehicle-trip-card-head";
    const titleWrap = document.createElement("div");
    const title = document.createElement("strong");
    title.textContent = trip.destination || "Putovanje vozila";
    const meta = document.createElement("span");
    meta.textContent = [
      trip.returnAt ? "Zaključeno" : "Otvoreno putovanje",
      getVehicleTripDrivers(trip),
      trip.linkedWorkOrderNumber ? `RN ${trip.linkedWorkOrderNumber}` : "",
    ].filter(Boolean).join(" | ");
    titleWrap.append(title, meta);
    head.append(titleWrap);

    const facts = document.createElement("div");
    facts.className = "vehicle-trip-facts";
    [
      ["Polazak", [formatVehicleTripDatePart(trip.departureAt || trip.performedOn), formatVehicleTripTimePart(trip.departureAt)].filter(Boolean).join(" ")],
      ["Povratak", trip.returnAt ? [formatVehicleTripDatePart(trip.returnAt), formatVehicleTripTimePart(trip.returnAt)].filter(Boolean).join(" ") : "Otvoreno"],
      ["Početna km", trip.startKm ? `${trip.startKm} km` : "-"],
      ["Krajnja KM", trip.endKm ? `${trip.endKm} km` : "-"],
      ["Stanje", getVehicleTripCondition(trip) || "-"],
    ].forEach(([label, value]) => {
      const fact = document.createElement("div");
      fact.className = "vehicle-trip-fact";
      const factLabel = document.createElement("span");
      factLabel.textContent = label;
      const factValue = document.createElement("strong");
      factValue.textContent = value || "-";
      fact.append(factLabel, factValue);
      facts.append(fact);
    });

    const tools = document.createElement("div");
    tools.className = "vehicle-trip-tools";

    const workOrderField = document.createElement("label");
    workOrderField.className = "vehicle-trip-field";
    const workOrderLabel = document.createElement("span");
    workOrderLabel.textContent = "Povezani RN";
    const workOrderSelect = document.createElement("select");
    replaceSelectOptions(workOrderSelect, buildVehicleTripWorkOrderOptions(trip.linkedWorkOrderId), trip.linkedWorkOrderId || "");
    workOrderSelect.addEventListener("change", () => {
      const linkedWorkOrder = (state.workOrders ?? []).find((item) => String(item.id) === String(workOrderSelect.value)) ?? null;
      updateVehicleTripDraft(trip.id, {
        linkedWorkOrderId: workOrderSelect.value || "",
        linkedWorkOrderNumber: linkedWorkOrder
          ? String(linkedWorkOrder.workOrderNumber || linkedWorkOrder.displayNumber || linkedWorkOrder.number || "").trim()
          : "",
      });
    });
    workOrderField.append(workOrderLabel, workOrderSelect);
    tools.append(workOrderField);

    const documents = Array.isArray(trip.documents) ? trip.documents : [];
    const documentTools = document.createElement("div");
    documentTools.className = "vehicle-trip-document-tools";
    const categorySelect = document.createElement("select");
    replaceSelectOptions(categorySelect, VEHICLE_TRIP_DOCUMENT_CATEGORY_OPTIONS, "putni_nalog");
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.multiple = true;
    fileInput.hidden = true;
    const addButton = document.createElement("button");
    addButton.type = "button";
    addButton.className = "ghost-button";
    addButton.textContent = "Dodaj prilog";
    addButton.addEventListener("click", () => fileInput.click());
    fileInput.addEventListener("change", () => {
      const files = Array.from(fileInput.files ?? []);
      if (!files.length) return;
      void runMutation(() => queueVehicleTripDocuments(trip.id, files, categorySelect.value || "putni_nalog"), vehicleError).then(() => {
        fileInput.value = "";
      });
    });
    documentTools.append(categorySelect, addButton, fileInput);
    tools.append(documentTools);

    const documentList = document.createElement("div");
    documentList.className = "vehicle-trip-documents";
    if (documents.length === 0) {
      const empty = document.createElement("p");
      empty.className = "helper-copy module-copy";
      empty.textContent = "Nema putnog naloga, ENC-a ni računa za ovo putovanje.";
      documentList.append(empty);
    } else {
      documents.forEach((documentItem) => {
        const row = document.createElement("article");
        row.className = "module-attachment-row vehicle-trip-document-row";
        const copy = document.createElement("div");
        copy.className = "module-attachment-copy";
        const name = document.createElement("strong");
        name.textContent = documentItem.fileName || "Prilog";
        const docMeta = document.createElement("span");
        docMeta.textContent = [
          getVehicleTripDocumentCategoryLabel(documentItem.documentCategory),
          formatFileSize(documentItem.fileSize),
          documentItem.updatedAt ? formatCompactDateTime(documentItem.updatedAt) : "",
        ].filter(Boolean).join(" | ");
        copy.append(name, docMeta);

        const middle = document.createElement("div");
        middle.className = "module-attachment-middle";
        const documentCategorySelect = document.createElement("select");
        documentCategorySelect.className = "module-attachment-category-select";
        replaceSelectOptions(documentCategorySelect, VEHICLE_TRIP_DOCUMENT_CATEGORY_OPTIONS, documentItem.documentCategory || "ostalo");
        documentCategorySelect.addEventListener("change", () => {
          updateVehicleTripDocument(trip.id, documentItem.id, { documentCategory: documentCategorySelect.value || "ostalo" });
        });
        middle.append(documentCategorySelect);

        const actions = document.createElement("div");
        actions.className = "module-attachment-actions";
        actions.append(
          createIconActionButton("Pregled", "preview", "", () => openVehicleDocumentPreview(documentItem)),
          createIconActionButton("Preuzmi", "download", "", () => triggerModuleAttachmentDownload(documentItem)),
          createIconActionButton("Makni", "trash", "card-danger", () => removeVehicleTripDocument(trip.id, documentItem.id)),
        );
        row.append(copy, middle, actions);
        documentList.append(row);
      });
    }

    card.append(head, facts, tools, documentList);
    return card;
  }));
}

function renderVehicleActivities() {
  if (!vehicleActivityList) {
    return;
  }

  const editableActivities = vehicleActivityDrafts.filter((entry) => !isVehicleTripDraft(entry));

  if (editableActivities.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Dodaj servis, promjenu guma, tehnički pregled, registraciju ili drugi važan događaj za vozilo.";
    vehicleActivityList.replaceChildren(empty);
    return;
  }

  const createField = (labelText, control, className = "") => {
    const field = document.createElement("label");
    field.className = ["vehicle-activity-field", className].filter(Boolean).join(" ");
    const label = document.createElement("span");
    label.className = "vehicle-activity-label";
    label.textContent = labelText;
    field.append(label, control);
    return field;
  };

  vehicleActivityList.replaceChildren(...editableActivities.map((entry) => {
    const row = document.createElement("article");
    row.className = "vehicle-activity-row";

    const fieldsGrid = document.createElement("div");
    fieldsGrid.className = "vehicle-activity-grid";

    const typeInput = document.createElement("select");
    replaceSelectOptions(typeInput, VEHICLE_ACTIVITY_TYPE_OPTIONS, entry.activityType || "service");
    typeInput.addEventListener("change", () => {
      updateVehicleActivityDraft(entry.id, {
        activityType: typeInput.value || "service",
      });
      renderVehicleActivities();
    });

    const dateInput = document.createElement("input");
    dateInput.type = "date";
    dateInput.value = entry.performedOn || "";
    dateInput.addEventListener("change", () => {
      updateVehicleActivityDraft(entry.id, {
        performedOn: dateInput.value || "",
      });
      renderVehicleActivities();
    });

    const byInput = document.createElement("input");
    byInput.type = "text";
    byInput.maxLength = 180;
    byInput.placeholder = "Tko je radio";
    byInput.value = entry.performedBy || "";
    byInput.addEventListener("input", () => {
      updateVehicleActivityDraft(entry.id, {
        performedBy: byInput.value || "",
      });
    });

    const odometerInput = document.createElement("input");
    odometerInput.type = "number";
    odometerInput.min = "0";
    odometerInput.step = "1";
    odometerInput.placeholder = "Kilometraža";
    odometerInput.value = entry.odometerKm || "";
    odometerInput.addEventListener("input", () => {
      updateVehicleActivityDraft(entry.id, {
        odometerKm: odometerInput.value || "",
      });
    });

    const validUntilInput = document.createElement("input");
    validUntilInput.type = "date";
    validUntilInput.value = entry.validUntil || "";
    validUntilInput.addEventListener("change", () => {
      updateVehicleActivityDraft(entry.id, {
        validUntil: validUntilInput.value || "",
      });
      renderVehicleActivities();
    });

    const workSummaryInput = document.createElement("input");
    workSummaryInput.type = "text";
    workSummaryInput.maxLength = 240;
    workSummaryInput.placeholder = "Radovi / što je napravljeno";
    workSummaryInput.value = entry.workSummary || "";
    workSummaryInput.addEventListener("input", () => {
      updateVehicleActivityDraft(entry.id, {
        workSummary: workSummaryInput.value || "",
      });
    });

    const noteInput = document.createElement("input");
    noteInput.type = "text";
    noteInput.maxLength = 240;
    noteInput.placeholder = "Napomena";
    noteInput.value = entry.note || "";
    noteInput.addEventListener("input", () => {
      updateVehicleActivityDraft(entry.id, {
        note: noteInput.value || "",
      });
    });

    fieldsGrid.append(
      createField("Aktivnost", typeInput),
      createField("Datum", dateInput, "is-date"),
      createField("Izvršio", byInput),
      createField("Km", odometerInput),
      createField("Vrijedi do", validUntilInput, "is-date"),
      createField("Radovi", workSummaryInput, "is-wide"),
      createField("Napomena", noteInput, "is-wide"),
    );

    const actions = document.createElement("div");
    actions.className = "vehicle-activity-actions";
    const removeButton = createIconActionButton("Makni aktivnost", "trash", "card-danger", () => {
      vehicleActivityDrafts = vehicleActivityDrafts.filter((item) => String(item.id) !== String(entry.id));
      renderVehicleActivities();
    });
    actions.append(removeButton);

    const meta = document.createElement("div");
    meta.className = "vehicle-activity-row-meta";
    meta.textContent = [
      getVehicleActivityTypeLabel(entry.activityType),
      entry.performedOn ? formatCompactDate(entry.performedOn) : "bez datuma",
      entry.performedBy ? `izvršio: ${entry.performedBy}` : "",
      entry.validUntil ? `vrijedi do ${formatCompactDate(entry.validUntil)}` : "",
    ].filter(Boolean).join(" · ");

    row.append(fieldsGrid, actions, meta);
    return row;
  }));
}

function buildVehiclePayload() {
  return {
    name: vehicleNameInput?.value || "",
    plateNumber: vehiclePlateNumberInput?.value || "",
    vinNumber: vehicleVinNumberInput?.value || "",
    status: vehicleStatusInput?.value || "available",
    category: vehicleCategoryInput?.value || "",
    make: vehicleMakeInput?.value || "",
    model: vehicleModelInput?.value || "",
    year: vehicleYearInput?.value || "",
    color: vehicleColorInput?.value || "",
    fuelType: vehicleFuelTypeInput?.value || "",
    transmission: vehicleTransmissionInput?.value || "",
    seatCount: vehicleSeatCountInput?.value || "",
    odometerKm: vehicleOdometerKmInput?.value || "",
    serviceDueDate: vehicleServiceDueDateInput?.value || "",
    registrationExpiresOn: vehicleRegistrationExpiresOnInput?.value || "",
    documents: vehicleDocumentDrafts.map((item) => {
      const { documentCategoryLocked, ...payload } = item;
      return { ...payload };
    }),
    activityItems: buildVehicleActivityPayload(),
    notes: vehicleNotesInput?.value || "",
  };
}

function buildVehicleReservationPayload() {
  const selectedUsers = getVehicleReservationSelectedUsers();
  const reservedForUserIds = selectedUsers.map((user) => String(user.id));
  const reservedForLabels = selectedUsers.map((user) => user.fullName || user.email || user.username || "User");

  return {
    status: vehicleReservationStatusInput?.value || "reserved",
    reservedForUserIds,
    reservedForLabels,
    reservedForUserId: reservedForUserIds[0] || "",
    reservedForLabel: reservedForLabels.join(", "),
    purpose: vehicleReservationPurposeInput?.value || "",
    startAt: vehicleReservationStartAtInput?.value || "",
    endAt: vehicleReservationEndAtInput?.value || "",
    destination: vehicleReservationDestinationInput?.value || "",
    note: vehicleReservationNoteInput?.value || "",
  };
}

const VEHICLE_MY_TRIP_WINDOW_TOLERANCE_MS = 60 * 60 * 1000;

function getCurrentVehicleUsageUserId() {
  return String(state.user?.id || state.user?.userId || state.user?.sub || "").trim();
}

function getCurrentVehicleUsageUserLabels() {
  return [
    state.user?.fullName,
    state.user?.displayName,
    state.user?.username,
    state.user?.email,
    state.user?.name,
  ].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean);
}

function vehicleReservationBelongsToCurrentUser(reservation = null) {
  if (!reservation) {
    return false;
  }

  const currentUserId = getCurrentVehicleUsageUserId();
  const reservationUserIds = [
    ...(Array.isArray(reservation.reservedForUserIds) ? reservation.reservedForUserIds : []),
    reservation.reservedForUserId,
    reservation.userId,
  ].map((value) => String(value || "").trim()).filter(Boolean);

  if (reservationUserIds.length > 0) {
    return Boolean(currentUserId && reservationUserIds.includes(currentUserId));
  }

  const userLabels = getCurrentVehicleUsageUserLabels();
  const reservationLabels = [
    ...(Array.isArray(reservation.reservedForLabels) ? reservation.reservedForLabels : []),
    reservation.reservedForLabel,
  ].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean);

  return reservationLabels.some((label) => userLabels.some((userLabel) => (
    label === userLabel || label.includes(userLabel) || userLabel.includes(label)
  )));
}

function vehicleReservationStatusAllowsMyTrip(reservation = {}) {
  const status = String(reservation?.status || "").trim().toLowerCase();
  return status === "reserved" || status === "checked_out";
}

function vehicleUsageTimestampInReservationWindow(reservation = null, timestampValue = "") {
  if (!reservation) {
    return false;
  }

  const startTimestamp = Date.parse(reservation.startAt || "");
  const endTimestamp = Date.parse(reservation.endAt || "");
  const actionTimestamp = Date.parse(timestampValue || new Date().toISOString());

  if (![startTimestamp, endTimestamp, actionTimestamp].every(Number.isFinite)) {
    return false;
  }

  return actionTimestamp >= startTimestamp - VEHICLE_MY_TRIP_WINDOW_TOLERANCE_MS
    && actionTimestamp <= endTimestamp + VEHICLE_MY_TRIP_WINDOW_TOLERANCE_MS;
}

function vehicleReservationAllowsCurrentUserMyTrip(reservation = null, timestampValue = new Date().toISOString()) {
  return Boolean(
    reservation
      && vehicleReservationStatusAllowsMyTrip(reservation)
      && vehicleReservationBelongsToCurrentUser(reservation)
      && vehicleUsageTimestampInReservationWindow(reservation, timestampValue),
  );
}

function getVehicleUsageModeLabel(mode = "") {
  return "My Trip";
}

function findVehicleUsageDefaultReservation(vehicle = {}, mode = "checkout", options = {}) {
  const requestedReservationId = String(options.reservationId || "").trim();
  const timestampValue = options.timestamp || new Date().toISOString();
  const reservations = sortVehicleReservations(vehicle?.reservations ?? [], timestampValue);
  const openTrip = findVehicleOpenTripDraft(vehicle, requestedReservationId);
  const openTripReservationId = String(openTrip?.reservationId || "").trim();

  if (openTrip && vehicleTripDraftBelongsToCurrentUser(openTrip)) {
    const openTripReservation = reservations.find((reservation) => String(reservation.id) === openTripReservationId) ?? null;
    if (openTripReservation && vehicleReservationAllowsCurrentUserMyTrip(openTripReservation, timestampValue)) {
      return openTripReservation;
    }
  }

  if (requestedReservationId) {
    const requestedReservation = reservations.find((reservation) => String(reservation.id) === requestedReservationId) ?? null;
    return vehicleReservationAllowsCurrentUserMyTrip(requestedReservation, timestampValue) ? requestedReservation : null;
  }

  const preferredStatus = mode === "return" ? "checked_out" : "reserved";
  return reservations.find((reservation) => (
    String(reservation.status || "").toLowerCase() === preferredStatus
    && vehicleReservationAllowsCurrentUserMyTrip(reservation, timestampValue)
  ))
    || reservations.find((reservation) => vehicleReservationAllowsCurrentUserMyTrip(reservation, timestampValue))
    || null;
}

function findVehicleOpenTripDraft(vehicle = {}, reservationId = "") {
  const requestedReservationId = String(reservationId || "").trim();
  const trips = (vehicle?.activityItems ?? [])
    .filter(isVehicleTripDraft)
    .filter((trip) => (
      String(trip.tripStatus || "").trim().toLowerCase() !== "completed"
      && !String(trip.returnAt || "").trim()
    ))
    .sort(compareVehicleActivityDraftRecency);

  if (requestedReservationId) {
    const byReservation = trips.find((trip) => String(trip.reservationId || "").trim() === requestedReservationId);
    if (byReservation) {
      return byReservation;
    }
  }

  return trips[0] || null;
}

function vehicleTripDraftBelongsToCurrentUser(trip = {}) {
  const labels = [
    ...(Array.isArray(trip.driverLabels) ? trip.driverLabels : []),
    trip.performedBy,
    trip.checkedOutByLabel,
  ].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean);
  const currentLabels = [
    state.user?.fullName,
    state.user?.displayName,
    state.user?.username,
    state.user?.email,
  ].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean);
  if (!labels.length || !currentLabels.length) {
    return false;
  }
  return labels.some((label) => currentLabels.some((current) => label === current || label.includes(current) || current.includes(label)));
}

function getVehicleUsageRecentDestinations(vehicle = {}, defaultReservation = null, openTrip = null) {
  return [
    defaultReservation?.destination,
    openTrip?.destination,
    ...(vehicle?.reservations ?? []).map((reservation) => reservation.destination),
    ...(vehicle?.activityItems ?? []).filter(isVehicleTripDraft).map((trip) => trip.destination),
  ]
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .filter((value, index, list) => list.findIndex((item) => item.toLowerCase() === value.toLowerCase()) === index)
    .slice(0, 5);
}

function getVehicleUsageRecentDrivers(vehicle = {}, defaultReservation = null, openTrip = null) {
  return [
    defaultReservation?.reservedForLabel,
    getVehicleTripDrivers(openTrip || {}),
    state.user?.fullName,
    state.user?.email,
    ...(vehicle?.activityItems ?? []).filter(isVehicleTripDraft).map((trip) => getVehicleTripDrivers(trip)),
  ]
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .filter((value, index, list) => list.findIndex((item) => item.toLowerCase() === value.toLowerCase()) === index)
    .slice(0, 5);
}

function getVehicleUsageDateRange(defaultReservation = null, openTrip = null) {
  const startDate = String(
    vehicleUsageDepartureAtInput?.value
      || openTrip?.departureAt
      || defaultReservation?.startAt
      || "",
  ).slice(0, 10);
  const endDate = String(
    vehicleUsageReturnAtInput?.value
      || openTrip?.returnAt
      || defaultReservation?.endAt
      || startDate
      || "",
  ).slice(0, 10);
  return {
    startDate,
    endDate: endDate || startDate,
  };
}

function buildVehicleUsageWorkOrderOptions(selectedValue = "", defaultReservation = null, openTrip = null) {
  const selectedUsers = getVehicleUsageSelectedUsers();
  const selectedLabels = getVehicleUsageSelectedUserLabels();
  const range = getVehicleUsageDateRange(defaultReservation, openTrip);
  return buildVehicleTripWorkOrderOptions(selectedValue, {
    ...range,
    users: selectedUsers,
    userIds: selectedUsers.map((user) => user.id),
    userLabels: selectedLabels,
    strict: Boolean(range.startDate && selectedUsers.length),
  });
}

function rebuildVehicleUsageWorkOrderOptions(selectedValue = "", defaultReservation = null, openTrip = null) {
  if (!vehicleUsageWorkOrderIdInput) {
    return;
  }
  replaceSelectOptions(vehicleUsageWorkOrderIdInput, buildVehicleUsageWorkOrderOptions(selectedValue, defaultReservation, openTrip), selectedValue);
}

function renderVehicleUsageQuickActions(vehicle = {}, safeMode = "checkout", defaultReservation = null, openTrip = null) {
  if (!vehicleUsageQuickActions) {
    return;
  }
  vehicleUsageQuickActions.replaceChildren();
}

function rebuildVehicleUsageReservationOptions(vehicle = {}, selectedValue = "") {
  if (!vehicleUsageReservationIdInput) {
    return;
  }

  const reservations = sortVehicleReservations(vehicle?.reservations ?? [], new Date().toISOString());
  const options = [
    { value: "", label: "Bez vezane rezervacije" },
    ...reservations.slice(0, 20).map((reservation) => ({
      value: reservation.id,
      label: [
        reservation.purpose || "Rezervacija",
        formatDateTime(reservation.startAt),
        reservation.reservedForLabel || "",
        getVehicleReservationStatusLabel(reservation.status),
      ].filter(Boolean).join(" | "),
    })),
  ];
  replaceSelectOptions(vehicleUsageReservationIdInput, options, selectedValue);
}

function getVehicleUsageFormContext() {
  const vehicleId = vehicleUsageVehicleIdInput?.value || state.activeVehicleId || "";
  const vehicle = state.vehicles.find((item) => String(item.id) === String(vehicleId)) ?? null;
  const reservationId = vehicleUsageReservationIdInput?.value || "";
  const defaultReservation = vehicle
    ? (
      findVehicleUsageDefaultReservation(vehicle, "checkout", { reservationId })
      || (vehicle.reservations ?? []).find((reservation) => String(reservation.id) === String(reservationId))
      || null
    )
    : null;
  const openTrip = vehicle ? findVehicleOpenTripDraft(vehicle, reservationId || defaultReservation?.id || "") : null;
  return {
    vehicle,
    reservationId,
    defaultReservation,
    openTrip,
  };
}

function renderVehicleUsageReturnFiles() {
  if (!vehicleUsageFilesList) {
    return;
  }
  if (!vehicleUsageReturnFiles.length) {
    vehicleUsageFilesList.innerHTML = '<p class="helper-copy">Nema dodanih dokumenata za povrat.</p>';
    return;
  }
  vehicleUsageFilesList.replaceChildren(...vehicleUsageReturnFiles.map((file, index) => {
    const row = document.createElement("div");
    row.className = "vehicle-usage-file-row";
    row.innerHTML = `
      <span class="vehicle-usage-file-icon">${file.fileType?.startsWith("image/") ? "IMG" : "DOC"}</span>
      <span class="vehicle-usage-file-name">${escapeHtml(file.fileName || "Dokument")}</span>
      <span class="vehicle-usage-file-size">${formatFileSize(file.fileSize || 0)}</span>
    `;
    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "ghost-button";
    removeButton.textContent = "Makni";
    removeButton.addEventListener("click", () => {
      vehicleUsageReturnFiles = vehicleUsageReturnFiles.filter((_, fileIndex) => fileIndex !== index);
      renderVehicleUsageReturnFiles();
    });
    row.append(removeButton);
    return row;
  }));
}

async function queueVehicleUsageReturnFiles(files) {
  const selectedFiles = Array.from(files ?? []).filter((file) => file instanceof File);
  if (!selectedFiles.length) {
    return;
  }
  for (const file of selectedFiles) {
    if (!isWorkOrderDocumentFileAllowed(file)) {
      throw new Error(`Format ${file.name} nije podrzan. Dozvoljeno: ${WORK_ORDER_DOCUMENT_ACCEPT_LABEL}`);
    }
    if (file.size > WORK_ORDER_DOCUMENT_MAX_SIZE_BYTES) {
      throw new Error(`Datoteka ${file.name} mora biti manja od 12 MB.`);
    }
  }
  const uploads = await Promise.all(selectedFiles.map(async (file) => ({
    fileName: file.name,
    fileType: file.type || "application/octet-stream",
    fileSize: file.size,
    documentCategory: "Ostalo",
    description: "Prilog putovanja vozila",
    dataUrl: await readFileAsDataUrl(file, `Ne mogu učitati datoteku ${file.name}.`),
  })));
  vehicleUsageReturnFiles = [...vehicleUsageReturnFiles, ...uploads];
  renderVehicleUsageReturnFiles();
}

function clearVehicleUsageSignatureCanvas() {
  if (!vehicleUsageSignatureCanvas) {
    return;
  }
  const context = vehicleUsageSignatureCanvas.getContext("2d");
  context?.clearRect(0, 0, vehicleUsageSignatureCanvas.width, vehicleUsageSignatureCanvas.height);
  vehicleUsageSignatureDirty = false;
}

function getVehicleUsageSignaturePointer(event) {
  const rect = vehicleUsageSignatureCanvas?.getBoundingClientRect();
  if (!rect || !vehicleUsageSignatureCanvas) {
    return null;
  }
  const scaleX = vehicleUsageSignatureCanvas.width / Math.max(1, rect.width);
  const scaleY = vehicleUsageSignatureCanvas.height / Math.max(1, rect.height);
  return {
    x: (event.clientX - rect.left) * scaleX,
    y: (event.clientY - rect.top) * scaleY,
  };
}

function getVehicleUsageSignatureDataUrl() {
  if (!vehicleUsageSignatureCanvas || !vehicleUsageSignatureDirty) {
    return "";
  }
  return vehicleUsageSignatureCanvas.toDataURL("image/png");
}

function resetVehicleUsageForm() {
  vehicleUsageForm?.reset();
  setVehicleUsageUserPickerOpen(false);
  if (vehicleUsageVehicleIdInput) vehicleUsageVehicleIdInput.value = "";
  if (vehicleUsageModeInput) vehicleUsageModeInput.value = "trip";
  if (vehicleUsageVehicleLabelInput) vehicleUsageVehicleLabelInput.value = "";
  if (vehicleUsageOdometerKmInput) vehicleUsageOdometerKmInput.value = "";
  if (vehicleUsageDepartureAtInput) vehicleUsageDepartureAtInput.value = "";
  if (vehicleUsageStartKmInput) vehicleUsageStartKmInput.value = "";
  if (vehicleUsageReturnAtInput) vehicleUsageReturnAtInput.value = "";
  if (vehicleUsageEndKmInput) vehicleUsageEndKmInput.value = "";
  if (vehicleUsageOdometerLabel) vehicleUsageOdometerLabel.textContent = "Početna KM";
  if (vehicleUsageDestinationLabel) vehicleUsageDestinationLabel.textContent = "Lokacija gdje se ide";
  if (vehicleUsageConditionLabel) vehicleUsageConditionLabel.textContent = "Stanje vozila / napomena";
  if (vehicleUsageConditionInput) vehicleUsageConditionInput.value = "";
  rebuildVehicleUsageUserOptions(getCurrentVehicleUsageUserId() ? [getCurrentVehicleUsageUserId()] : []);
  if (vehicleUsageCleanInput) vehicleUsageCleanInput.checked = true;
  if (vehicleUsageDocumentsInput) vehicleUsageDocumentsInput.checked = true;
  if (vehicleUsageFuelInput) vehicleUsageFuelInput.checked = true;
  if (vehicleUsageDamageInput) vehicleUsageDamageInput.checked = false;
  if (vehicleUsageError) vehicleUsageError.textContent = "";
  vehicleUsageReturnFiles = [];
  renderVehicleUsageReturnFiles();
  clearVehicleUsageSignatureCanvas();
  if (vehicleUsageReturnDocumentsPanel) vehicleUsageReturnDocumentsPanel.hidden = false;
  if (vehicleUsageSignaturePanel) vehicleUsageSignaturePanel.hidden = false;
  rebuildVehicleUsageReservationOptions({}, "");
  rebuildVehicleUsageWorkOrderOptions("");
  vehicleUsageQuickActions?.replaceChildren();
}

function hydrateVehicleUsageForm(vehicle = {}, { mode = "checkout", reservationId = "" } = {}) {
  const safeMode = "trip";
  const requestedReservationId = String(reservationId || "").trim();
  const defaultReservation = findVehicleUsageDefaultReservation(vehicle, "checkout", {
    reservationId: requestedReservationId,
  });
  const openTrip = findVehicleOpenTripDraft(vehicle, defaultReservation?.id || requestedReservationId || "");
  const selectedWorkOrderId = openTrip?.linkedWorkOrderId || "";
  const nowLocal = toDateTimeLocalInputValue(new Date().toISOString());
  const departureAt = toDateTimeLocalInputValue(openTrip?.departureAt || new Date().toISOString());
  const returnAt = toDateTimeLocalInputValue(openTrip?.returnAt || (openTrip ? new Date().toISOString() : ""));
  const selectedUserIds = Array.from(new Set([
    ...(Array.isArray(openTrip?.driverUserIds) ? openTrip.driverUserIds : []),
    openTrip?.checkedOutByUserId,
    ...(Array.isArray(defaultReservation?.reservedForUserIds) ? defaultReservation.reservedForUserIds : []),
    defaultReservation?.reservedForUserId,
    vehicleReservationBelongsToCurrentUser(defaultReservation) ? getCurrentVehicleUsageUserId() : "",
  ].map((value) => String(value || "").trim()).filter(Boolean)));

  if (vehicleUsageVehicleIdInput) vehicleUsageVehicleIdInput.value = vehicle.id || "";
  if (vehicleUsageModeInput) vehicleUsageModeInput.value = safeMode;
  if (vehicleUsageTitle) vehicleUsageTitle.textContent = getVehicleUsageModeLabel(safeMode);
  if (vehicleUsageSubmitButton) vehicleUsageSubmitButton.textContent = openTrip ? "Zaključi My Trip" : "Pokreni My Trip";
  if (vehicleUsageOdometerLabel) vehicleUsageOdometerLabel.textContent = "Kilometraža";
  if (vehicleUsageDestinationLabel) vehicleUsageDestinationLabel.textContent = "Lokacija gdje se ide";
  if (vehicleUsageConditionLabel) {
    vehicleUsageConditionLabel.textContent = "Stanje vozila / napomena";
  }
  if (vehicleUsageVehicleLabelInput) {
    vehicleUsageVehicleLabelInput.value = [vehicle.plateNumber, vehicle.name].filter(Boolean).join(" | ") || "Vozilo";
  }
  if (vehicleUsageDepartureAtInput) vehicleUsageDepartureAtInput.value = departureAt;
  if (vehicleUsageReturnAtInput) vehicleUsageReturnAtInput.value = returnAt;
  if (vehicleUsageStartKmInput) vehicleUsageStartKmInput.value = String(openTrip?.startKm || openTrip?.odometerKm || vehicle.odometerKm || "");
  if (vehicleUsageEndKmInput) vehicleUsageEndKmInput.value = String(openTrip?.endKm || "");
  if (vehicleUsageOdometerKmInput) vehicleUsageOdometerKmInput.value = String(openTrip?.endKm || openTrip?.startKm || vehicle.odometerKm || "");
  if (vehicleUsageDestinationInput) {
    vehicleUsageDestinationInput.value = openTrip?.destination || defaultReservation?.destination || "";
  }
  rebuildVehicleUsageUserOptions(selectedUserIds);
  if (vehicleUsageCleanInput) vehicleUsageCleanInput.checked = true;
  if (vehicleUsageDocumentsInput) vehicleUsageDocumentsInput.checked = true;
  if (vehicleUsageFuelInput) vehicleUsageFuelInput.checked = true;
  if (vehicleUsageDamageInput) vehicleUsageDamageInput.checked = false;
  if (vehicleUsageConditionInput) {
    vehicleUsageConditionInput.value = getVehicleTripCondition(openTrip || {}) || "Uredno";
    vehicleUsageConditionInput.placeholder = "Stanje vozila, oprema, oštećenje ili napomena...";
  }
  if (vehicleUsageNoteInput) vehicleUsageNoteInput.value = "";
  if (vehicleUsageError) vehicleUsageError.textContent = "";
  vehicleUsageReturnFiles = [];
  renderVehicleUsageReturnFiles();
  clearVehicleUsageSignatureCanvas();
  if (vehicleUsageReturnDocumentsPanel) vehicleUsageReturnDocumentsPanel.hidden = false;
  if (vehicleUsageSignaturePanel) vehicleUsageSignaturePanel.hidden = false;
  rebuildVehicleUsageReservationOptions(vehicle, openTrip?.reservationId || defaultReservation?.id || "");
  rebuildVehicleUsageWorkOrderOptions(selectedWorkOrderId, defaultReservation, openTrip);
  renderVehicleUsageQuickActions(vehicle, safeMode, defaultReservation, openTrip);
}

function buildVehicleUsagePayload() {
  const mode = "trip";
  const reservationId = vehicleUsageReservationIdInput?.value || "";
  const activeVehicle = getActiveVehicle();
  const openTrip = activeVehicle ? findVehicleOpenTripDraft(activeVehicle, reservationId) : null;
  const linkedWorkOrderId = vehicleUsageWorkOrderIdInput?.value || "";
  const linkedWorkOrder = (state.workOrders ?? []).find((item) => String(item.id) === String(linkedWorkOrderId)) ?? null;
  const finalLinkedWorkOrderId = linkedWorkOrderId || openTrip?.linkedWorkOrderId || "";
  const driverUsers = getVehicleUsageSelectedUsers();
  const driverUserIds = driverUsers.map((user) => String(user.id || "")).filter(Boolean);
  const driverLabels = driverUsers.map(getVehicleUserLabel).filter(Boolean);
  const endKm = String(vehicleUsageEndKmInput?.value || "").trim();
  const startKm = String(vehicleUsageStartKmInput?.value || "").trim();
  const odometerKm = endKm || startKm || vehicleUsageOdometerKmInput?.value || "";
  return {
    mode,
    tripId: openTrip?.id || "",
    activityItemId: openTrip?.id || "",
    departureAt: vehicleUsageDepartureAtInput?.value || openTrip?.departureAt || "",
    returnAt: vehicleUsageReturnAtInput?.value || "",
    startKm,
    endKm,
    odometerKm,
    reservationId: reservationId || openTrip?.reservationId || "",
    linkedWorkOrderId: finalLinkedWorkOrderId,
    linkedWorkOrderNumber: linkedWorkOrder
      ? String(linkedWorkOrder.workOrderNumber || linkedWorkOrder.displayNumber || linkedWorkOrder.number || "").trim()
      : openTrip?.linkedWorkOrderNumber || "",
    performedBy: driverLabels.join(", ") || vehicleUsagePerformedByInput?.value || "",
    driverUserIds,
    driverLabels,
    drivers: driverLabels,
    destination: vehicleUsageDestinationInput?.value || openTrip?.destination || "",
    vehicleCondition: vehicleUsageConditionInput?.value || "",
    vehicleClean: Boolean(vehicleUsageCleanInput?.checked),
    documentsPresent: Boolean(vehicleUsageDocumentsInput?.checked),
    fuelOk: Boolean(vehicleUsageFuelInput?.checked),
    damageNoted: Boolean(vehicleUsageDamageInput?.checked),
    note: vehicleUsageNoteInput?.value || "",
    files: vehicleUsageReturnFiles,
    signatureDataUrl: getVehicleUsageSignatureDataUrl(),
  };
}

function openVehicleUsageComposer(vehicle, options = {}) {
  if (!vehicle || isVehicleServiceOnlyStatus(vehicle)) {
    return;
  }
  const defaultReservation = findVehicleUsageDefaultReservation(vehicle, "checkout", {
    reservationId: options.reservationId || "",
  });
  const openTrip = findVehicleOpenTripDraft(vehicle, defaultReservation?.id || options.reservationId || "");
  const hasAllowedOpenTrip = Boolean(openTrip && vehicleTripDraftBelongsToCurrentUser(openTrip));
  if (!defaultReservation && !hasAllowedOpenTrip) {
    if (vehicleError) {
      vehicleError.textContent = "My Trip možeš pokrenuti samo kad u tom terminu imaš rezerviran automobil.";
    }
    return;
  }
  state.activeVehicleId = vehicle.id;
  hydrateVehicleUsageForm(vehicle, {
    ...options,
    reservationId: defaultReservation?.id || options.reservationId || openTrip?.reservationId || "",
  });
  openVehicleUsageEditor();
  requestAnimationFrame(() => {
    (openTrip ? vehicleUsageEndKmInput : vehicleUsageStartKmInput)?.focus({ preventScroll: true });
  });
}

function resetVehicleReservationForm({ clearSelection = true, vehicleId = state.activeVehicleId || "" } = {}) {
  if (!vehicleReservationForm) {
    return;
  }

  setVehicleReservationAssigneePickerOpen(false);
  vehicleReservationForm.reset();
  if (vehicleReservationIdInput) {
    vehicleReservationIdInput.value = "";
  }
  if (vehicleReservationError) {
    vehicleReservationError.textContent = "";
  }
  if (vehicleReservationStatusInput) {
    vehicleReservationStatusInput.value = "reserved";
  }
  rebuildVehicleReservationVehicleOptions(vehicleId);

  const windowRange = buildDefaultVehicleReservationWindow();
  if (vehicleReservationStartAtInput) {
    vehicleReservationStartAtInput.value = windowRange.startAt;
  }
  if (vehicleReservationEndAtInput) {
    vehicleReservationEndAtInput.value = windowRange.endAt;
  }

  rebuildVehicleReservationUserOptions([]);

  if (clearSelection) {
    state.activeVehicleReservationId = "";
  }

  if (vehicleId) {
    state.activeVehicleId = String(vehicleId);
  } else if (!vehicleReservationIdInput?.value) {
    state.activeVehicleId = "";
  }

  syncVehicleEditorSummary();
}

