function renderWorkOrderMapView() {
  if (!workOrderMapView || !workOrderMapStage || !workOrderMapCanvas) {
    return;
  }

  const filtered = getFilteredWorkOrders();
  const map = buildWorkOrderMapMarkers(filtered);
  const markers = map.markers;
  const missingCoordinatesCount = filtered.length - markers.length;

  if (workOrderMapSummary) {
    workOrderMapSummary.textContent = `${markers.length} s koordinatama · ${missingCoordinatesCount} bez koordinata`;
  }

  if (workOrderMapSummary) {
    workOrderMapSummary.textContent = `${markers.length} s koordinatama · ${missingCoordinatesCount} bez`;
  }

  if (workOrderMapSummary) {
    workOrderMapSummary.textContent = `${markers.length} s koordinatama · ${missingCoordinatesCount} bez koordinata`;
  }

  if (workOrderMapSummary) {
    workOrderMapSummary.textContent = `${markers.length} s koordinatama · ${missingCoordinatesCount} bez koordinata`;
  }

  if (workOrderMapSummary) {
    workOrderMapSummary.textContent = `${markers.length} s koordinatama · ${missingCoordinatesCount} bez koordinata`;
  }

  workOrderMapList?.replaceChildren();

  if (markers.length === 0) {
    state.workOrderMap.selectedWorkOrderId = "";
    state.workOrderMap.popupWorkOrderId = "";
    renderWorkOrderMapSelectionCard(null);
    setWorkOrderMapEmptyOverlay(true);
    syncWorkOrderLeafletMarkers([]);

    if (workOrderMapList) {
      const empty = document.createElement("p");
      empty.className = "work-order-map-selection-empty";
      empty.textContent = "Nema dostupnih lokacija za prikaz na karti.";
      workOrderMapList.append(empty);
    }
    return;
  }

  setWorkOrderMapEmptyOverlay(false);

  if (!markers.some((item) => String(item.workOrderId) === String(state.workOrderMap.selectedWorkOrderId))) {
    state.workOrderMap.selectedWorkOrderId = markers[0].workOrderId;
  }

  syncWorkOrderLeafletMarkers(markers);

  markers.forEach((marker) => {
    if (workOrderMapList) {
      const item = document.createElement("button");
      item.type = "button";
      item.className = "work-order-map-list-item";
      item.classList.toggle("is-selected", String(marker.workOrderId) === String(state.workOrderMap.selectedWorkOrderId));

      const title = document.createElement("strong");
      title.textContent = marker.workOrderNumber || "Bez broja";

      const subtitle = document.createElement("span");
      subtitle.textContent = [marker.companyName, marker.locationName].filter(Boolean).join(" · ") || "Bez detalja";

      const meta = document.createElement("span");
      meta.className = "work-order-map-list-meta";
      meta.textContent = marker.coordinates || "";

      item.append(title, subtitle, meta);
      item.addEventListener("click", () => {
        state.workOrderMap.selectedWorkOrderId = marker.workOrderId;
        renderWorkOrderMapView();
      });
      workOrderMapList.append(item);
    }
  });

  renderWorkOrderMapSelectionCard(
    markers.find((item) => String(item.workOrderId) === String(state.workOrderMap.selectedWorkOrderId)) ?? null,
  );
}

function createWorkOrderCalendarSchedulerCard(workOrder) {
  const card = document.createElement("article");
  card.className = "work-order-calendar-card";
  card.draggable = true;
  card.dataset.workOrderId = workOrder.id;
  card.tabIndex = 0;
  card.setAttribute("role", "button");
  const tone = getWorkOrderCalendarTone(workOrder.status || "Otvoreni RN");
  card.style.setProperty("--calendar-card-accent", tone.accent);
  card.style.setProperty("--calendar-card-soft", tone.soft);
  card.style.setProperty("--calendar-card-border", tone.border);

  const top = document.createElement("div");
  top.className = "work-order-calendar-card-top";

  const number = document.createElement("strong");
  number.className = "work-order-calendar-card-number";
  number.textContent = workOrder.workOrderNumber || "Bez broja";

  const status = createWorkOrderStatusDropdown(workOrder, {
    className: "work-order-calendar-card-status-dropdown",
  });
  top.append(number, status);

  const title = document.createElement("span");
  title.className = "work-order-calendar-card-title";
  title.textContent = workOrder.companyName || workOrder.locationName || "Radni nalog";

  const meta = document.createElement("span");
  meta.className = "work-order-calendar-card-meta";
  meta.textContent = [workOrder.locationName, workOrder.region].filter(Boolean).join(" · ") || "Bez lokacije";

  const due = document.createElement("span");
  due.className = "work-order-calendar-card-due";
  due.textContent = workOrder.dueDate ? `Rok ${formatCompactDate(workOrder.dueDate)}` : "Bez roka";

  const footer = document.createElement("div");
  footer.className = "work-order-calendar-card-footer";
  footer.append(due);

  const executorWrap = document.createElement("div");
  executorWrap.className = "work-order-calendar-card-executors";
  executorWrap.dataset.preventRowOpen = "true";
  executorWrap.append(createWorkOrderCalendarExecutorPicker(workOrder));
  footer.append(executorWrap);

  card.append(top, title, meta, footer);

  if (workOrder.priority) {
    const priority = createBadge(
      getOptionLabel(PRIORITY_OPTIONS, workOrder.priority),
      priorityBadgeClass(workOrder.priority),
    );
    priority.classList.add("work-order-calendar-card-priority");
    card.append(priority);
  }

  card.addEventListener("click", (event) => {
    if (isInteractiveWorkOrderTarget(event.target)) {
      return;
    }
    hydrateWorkOrderForm(workOrder);
  });

  card.addEventListener("keydown", (event) => {
    if (isInteractiveWorkOrderTarget(event.target)) {
      return;
    }

    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      hydrateWorkOrderForm(workOrder);
    }
  });

  card.addEventListener("dragstart", (event) => {
    state.workOrderCalendar.draggingWorkOrderId = workOrder.id;
    state.workOrderCalendar.draggingGroupIds = [];
    event.dataTransfer?.setData("text/plain", String(workOrder.id));
    event.dataTransfer?.setData("application/x-work-order-id", String(workOrder.id));
    event.dataTransfer?.setDragImage?.(card, 18, 18);
    window.requestAnimationFrame(() => {
      card.classList.add("is-dragging");
    });
  });

  card.addEventListener("dragend", () => {
    state.workOrderCalendar.draggingWorkOrderId = "";
    state.workOrderCalendar.draggingGroupIds = [];
    card.classList.remove("is-dragging");
    workOrderCalendarGrid?.querySelectorAll(".is-drop-target").forEach((node) => node.classList.remove("is-drop-target"));
  });

  return card;
}

function getVisibleCalendarWeekDays(days = [], showWeekends = state.workOrderCalendar.showWeekends) {
  if (showWeekends) {
    return days;
  }

  return days.filter((day) => {
    const parsedDate = parseDateValue(day.key);

    if (!parsedDate) {
      return true;
    }

    const dayIndex = parsedDate.getDay();
    return dayIndex !== 0 && dayIndex !== 6;
  });
}

function createWorkOrderCalendarGroupLead(group) {
  const lead = document.createElement("div");
  lead.className = "work-order-calendar-team-lead";

  const titleWrap = document.createElement("div");
  titleWrap.className = "work-order-calendar-team-copy";

  const title = document.createElement("strong");
  title.className = "work-order-calendar-team-name";
  title.textContent = group.label;

  const subtitle = document.createElement("span");
  subtitle.className = "work-order-calendar-team-meta";
  subtitle.textContent = group.totalCount === 1 ? "1 RN" : `${group.totalCount} RN`;

  titleWrap.append(title, subtitle);

  const metaWrap = document.createElement("div");
  metaWrap.className = "work-order-calendar-team-side";

  if (group.executors.length > 0) {
    const avatars = document.createElement("div");
    avatars.className = "work-order-calendar-team-executors";
    group.executors.slice(0, 4).forEach((executor) => avatars.append(createWorkOrderMiniExecutor(executor)));
    metaWrap.append(avatars);
  }

  lead.append(titleWrap, metaWrap);
  return lead;
}

function getWorkOrderCalendarRowMetrics(visibleDayCount = 7) {
  const teamMinWidth = visibleDayCount <= 5 ? 136 : visibleDayCount === 6 ? 124 : 112;
  const teamFraction = visibleDayCount <= 5 ? 1.35 : visibleDayCount === 6 ? 1.2 : 1.05;

  return {
    teamMinWidth,
    teamFraction,
  };
}

function applyWorkOrderCalendarRowLayout(row, visibleDayCount = 7) {
  const metrics = getWorkOrderCalendarRowMetrics(visibleDayCount);
  row.style.gridTemplateColumns = `minmax(${metrics.teamMinWidth}px, ${metrics.teamFraction}fr) repeat(${visibleDayCount}, minmax(0, 1fr))`;
  row.style.minWidth = "0";
  row.style.width = "100%";
}

function bindWorkOrderCalendarGroupDrag(handle, workOrderIds = [], groupCard = null) {
  if (!handle || !Array.isArray(workOrderIds) || workOrderIds.length === 0) {
    return;
  }

  const normalizedIds = Array.from(new Set(
    workOrderIds.map((value) => String(value ?? "").trim()).filter(Boolean),
  ));

  if (normalizedIds.length === 0) {
    return;
  }

  handle.draggable = true;
  handle.classList.add("is-draggable");

  handle.addEventListener("dragstart", (event) => {
    state.workOrderCalendar.draggingWorkOrderId = "";
    state.workOrderCalendar.draggingGroupIds = [...normalizedIds];
    event.dataTransfer?.setData("application/x-work-order-group-ids", normalizedIds.join(","));
    event.dataTransfer?.setData("text/plain", normalizedIds[0]);
    event.dataTransfer?.setDragImage?.((groupCard || handle), 18, 18);
    window.requestAnimationFrame(() => {
      groupCard?.classList.add("is-dragging-group");
    });
  });

  handle.addEventListener("dragend", () => {
    state.workOrderCalendar.draggingWorkOrderId = "";
    state.workOrderCalendar.draggingGroupIds = [];
    groupCard?.classList.remove("is-dragging-group");
    workOrderCalendarGrid?.querySelectorAll(".is-drop-target").forEach((node) => node.classList.remove("is-drop-target"));
  });
}

function createWorkOrderCalendarExecutorGroup(items = [], options = {}) {
  const { targetDate = "" } = options;
  const groups = groupWorkOrdersByExecutorSet(items);

  const wrap = document.createDocumentFragment();

  groups.forEach((executorGroup) => {
    const groupCard = document.createElement("details");
    groupCard.className = "work-order-calendar-cell-group";
    groupCard.dataset.executorGroupKey = executorGroup.key;
    const persistenceKey = targetDate ? `${targetDate}:${executorGroup.key}` : executorGroup.key;
    groupCard.open = state.workOrderCalendar.expandedGroupKeys.has(persistenceKey);
    groupCard.addEventListener("toggle", () => {
      if (groupCard.open) {
        state.workOrderCalendar.expandedGroupKeys.add(persistenceKey);
      } else {
        state.workOrderCalendar.expandedGroupKeys.delete(persistenceKey);
      }
    });

    if (targetDate && executorGroup.executors.length > 0) {
      bindWorkOrderCalendarDropTarget(groupCard, (dragPayload) => {
        void applyWorkOrderCalendarDropPayload(dragPayload, targetDate, {
          executors: executorGroup.executors,
        });
      }, { stopPropagation: true });
    }

    const header = document.createElement("summary");
    header.className = "work-order-calendar-cell-group-summary";
    bindWorkOrderCalendarGroupDrag(
      header,
      executorGroup.items.map((item) => item.id),
      groupCard,
    );

    const lead = document.createElement("div");
    lead.className = "work-order-calendar-cell-group-lead";

    const avatars = document.createElement("div");
    avatars.className = "work-order-calendar-cell-group-avatars";
    if (executorGroup.executors.length > 0) {
      executorGroup.executors.slice(0, 3).forEach((executor) => avatars.append(createWorkOrderMiniExecutor(executor)));
    } else {
      avatars.append(createWorkOrderMiniExecutor("Bez izvršitelja"));
    }

    const copy = document.createElement("div");
    copy.className = "work-order-calendar-cell-group-copy";

    const title = document.createElement("strong");
    title.className = "work-order-calendar-cell-group-title";
    title.textContent = executorGroup.label;

    copy.append(title);

    const uniqueRegions = Array.from(new Set(
      executorGroup.items
        .map((item) => String(item?.region ?? "").trim())
        .filter(Boolean),
    )).sort((left, right) => left.localeCompare(right, "hr"));

    if (uniqueRegions.length > 0) {
      const regions = document.createElement("div");
      regions.className = "work-order-calendar-cell-group-regions";
      uniqueRegions.forEach((region) => {
        const pill = document.createElement("span");
        pill.className = "work-order-calendar-cell-group-region";
        pill.textContent = region;
        pill.title = region;
        regions.append(pill);
      });
      copy.append(regions);
    }

    lead.append(avatars, copy);

    const count = document.createElement("span");
    count.className = "work-order-calendar-cell-group-count";
    count.textContent = String(executorGroup.items.length);

    header.append(lead, count);

    const body = document.createElement("div");
    body.className = "work-order-calendar-cell-group-body";

    const list = document.createElement("div");
    list.className = "work-order-calendar-cell-group-list";
    executorGroup.items.forEach((workOrder) => {
      list.append(createWorkOrderCalendarSchedulerCard(workOrder));
    });

    body.append(list);
    groupCard.append(header, body);
    wrap.append(groupCard);
  });

  return wrap;
}

function createWorkOrderCalendarWeekCell(day, group, items) {
  const cell = document.createElement("div");
  cell.className = "work-order-calendar-week-cell";
  cell.dataset.dateKey = day.key;
  cell.dataset.teamKey = group.key;

  bindWorkOrderCalendarDropTarget(cell, (dragPayload) => {
    void applyWorkOrderCalendarDropPayload(dragPayload, day.key);
  });

  const absenceStrip = createWorkOrderCalendarAbsenceStrip(getAbsenceEntriesForDate(day.key), {
    compact: true,
    maxVisible: 2,
    className: "work-order-calendar-week-absence-strip",
  });
  if (absenceStrip) {
    cell.append(absenceStrip);
  }

  if (items.length === 0) {
    const placeholder = document.createElement("span");
    placeholder.className = "work-order-calendar-cell-placeholder";
    placeholder.textContent = day.inMonth ? "Povuci ovdje" : "";
    cell.append(placeholder);
    return cell;
  }

  cell.append(createWorkOrderCalendarExecutorGroup(items, { targetDate: day.key }));

  return cell;
}

function syncWorkOrderCalendarGridShellHeight() {
  if (!workOrderCalendarGridShell) {
    return;
  }

  if (state.activeWorkOrderViewMode !== "calendar" || workOrderCalendarView?.hidden) {
    workOrderCalendarGridShell.style.removeProperty("--work-order-calendar-shell-height");
    return;
  }

  const viewportHeight = window.visualViewport?.height || window.innerHeight;
  if (!Number.isFinite(viewportHeight) || viewportHeight <= 0) {
    return;
  }

  const shellRect = workOrderCalendarGridShell.getBoundingClientRect();
  const visibleTop = Math.max(shellRect.top, window.innerWidth <= 980 ? 10 : 16);
  const bottomGap = window.innerWidth <= 980 ? 16 : 24;
  const availableHeight = Math.floor(viewportHeight - visibleTop - bottomGap);

  if (!Number.isFinite(availableHeight) || availableHeight <= 120) {
    workOrderCalendarGridShell.style.removeProperty("--work-order-calendar-shell-height");
    return;
  }

  workOrderCalendarGridShell.style.setProperty("--work-order-calendar-shell-height", `${availableHeight}px`);
}

function queueWorkOrderCalendarGridShellHeightSync() {
  if (!workOrderCalendarGridShell) {
    return;
  }

  if (workOrderCalendarShellHeightFrame) {
    window.cancelAnimationFrame(workOrderCalendarShellHeightFrame);
  }

  workOrderCalendarShellHeightFrame = window.requestAnimationFrame(() => {
    workOrderCalendarShellHeightFrame = 0;
    syncWorkOrderCalendarGridShellHeight();
  });
}

function bindWorkOrderCalendarGrabScroll() {
  if (!workOrderCalendarGridShell || workOrderCalendarGridShell.dataset.grabBound === "true") {
    return;
  }

  workOrderCalendarGridShell.dataset.grabBound = "true";
  workOrderCalendarGridShell.addEventListener("wheel", (event) => {
    const absDeltaX = Math.abs(event.deltaX);
    const absDeltaY = Math.abs(event.deltaY);
    const horizontalDelta = (event.deltaX || event.deltaY) * 1.1;
    const verticalDelta = event.deltaY * 1.18;
    const hasHorizontalOverflow = workOrderCalendarGridShell.scrollWidth > workOrderCalendarGridShell.clientWidth + 4;
    const hasVerticalOverflow = workOrderCalendarGridShell.scrollHeight > workOrderCalendarGridShell.clientHeight + 4;
    const shouldPanHorizontally = event.shiftKey || absDeltaX > absDeltaY;

    if (shouldPanHorizontally && hasHorizontalOverflow) {
      const nextScrollLeft = workOrderCalendarGridShell.scrollLeft + horizontalDelta;
      const maxScrollLeft = Math.max(0, workOrderCalendarGridShell.scrollWidth - workOrderCalendarGridShell.clientWidth);
      const canConsumeHorizontal = horizontalDelta < 0
        ? workOrderCalendarGridShell.scrollLeft > 0
        : workOrderCalendarGridShell.scrollLeft < maxScrollLeft;

      if (canConsumeHorizontal) {
        event.preventDefault();
        workOrderCalendarGridShell.scrollLeft = Math.max(0, Math.min(nextScrollLeft, maxScrollLeft));
      }
      return;
    }

    if (!hasVerticalOverflow || absDeltaY <= 0) {
      return;
    }

    const nextScrollTop = workOrderCalendarGridShell.scrollTop + verticalDelta;
    const maxScrollTop = Math.max(0, workOrderCalendarGridShell.scrollHeight - workOrderCalendarGridShell.clientHeight);
    const canConsumeVertical = verticalDelta < 0
      ? workOrderCalendarGridShell.scrollTop > 0
      : workOrderCalendarGridShell.scrollTop < maxScrollTop;

    if (!canConsumeVertical) {
      return;
    }

    event.preventDefault();
    workOrderCalendarGridShell.scrollTop = Math.max(0, Math.min(nextScrollTop, maxScrollTop));
  }, { passive: false, capture: true });
}

function syncWorkOrderCalendarToolbar(unscheduledCount = 0, sidePanelCount = unscheduledCount) {
  if (workOrderCalendarPrevButton) {
    workOrderCalendarPrevButton.setAttribute(
      "aria-label",
      state.workOrderCalendar.displayMode === "month" ? "Prethodni mjesec" : "Prethodni tjedan",
    );
  }

  if (workOrderCalendarNextButton) {
    workOrderCalendarNextButton.setAttribute(
      "aria-label",
      state.workOrderCalendar.displayMode === "month" ? "Sljedeći mjesec" : "Sljedeći tjedan",
    );
  }

  if (workOrderCalendarDisplayWeekButton) {
    const isActive = state.workOrderCalendar.displayMode === "week";
    workOrderCalendarDisplayWeekButton.classList.toggle("is-active", isActive);
    workOrderCalendarDisplayWeekButton.setAttribute("aria-pressed", isActive ? "true" : "false");
  }

  if (workOrderCalendarDisplayMonthButton) {
    const isActive = state.workOrderCalendar.displayMode === "month";
    workOrderCalendarDisplayMonthButton.classList.toggle("is-active", isActive);
    workOrderCalendarDisplayMonthButton.setAttribute("aria-pressed", isActive ? "true" : "false");
  }

  if (workOrderCalendarWeekendsInput) {
    workOrderCalendarWeekendsInput.classList.toggle("is-active", state.workOrderCalendar.showWeekends);
    workOrderCalendarWeekendsInput.setAttribute("aria-pressed", state.workOrderCalendar.showWeekends ? "true" : "false");
  }

  if (workOrderCalendarUnscheduledToggle) {
    const hasSidePanelItems = sidePanelCount > 0;
    const visible = state.workOrderCalendar.showUnscheduled && hasSidePanelItems;
    workOrderCalendarUnscheduledToggle.classList.toggle("is-active", visible);
    workOrderCalendarUnscheduledToggle.setAttribute("aria-pressed", visible ? "true" : "false");
    workOrderCalendarUnscheduledToggle.disabled = !hasSidePanelItems;
    workOrderCalendarUnscheduledToggle.textContent = unscheduledCount > 0
      ? `Bez datuma (${unscheduledCount})`
      : "Bez datuma";
  }

  if (workOrderCalendarContent) {
    workOrderCalendarContent.classList.toggle(
      "is-unscheduled-hidden",
      !state.workOrderCalendar.showUnscheduled || sidePanelCount === 0,
    );
  }
}

function createWorkOrderCalendarUnscheduledGroup(group) {
  const section = document.createElement("section");
  section.className = "work-order-calendar-unscheduled-group";

  const header = document.createElement("div");
  header.className = "work-order-calendar-unscheduled-group-head";
  bindWorkOrderCalendarGroupDrag(
    header,
    group.items.map((item) => item.id),
    section,
  );
  header.append(createWorkOrderCalendarGroupLead({
    ...group,
    totalCount: group.items.length,
  }));

  const list = document.createElement("div");
  list.className = "work-order-calendar-unscheduled-list";
  group.items.forEach((workOrder) => {
    list.append(createWorkOrderCalendarSchedulerCard(workOrder));
  });

  section.append(header, list);
  return section;
}

function renderWorkOrderCalendarSchedulerView() {
  if (!workOrderCalendarView || !workOrderCalendarGrid) {
    return;
  }

  bindWorkOrderCalendarGrabScroll();

  const filtered = getFilteredWorkOrders();
  const calendar = buildWorkOrderCalendarTeamWeeks(filtered, state.workOrderCalendar.weekStart);

  if (workOrderCalendarRange) {
    workOrderCalendarRange.textContent = formatCalendarRangeLabel(calendar.anchorDate);
  }

  const unscheduledCount = calendar.unscheduledGroups.reduce((sum, group) => sum + group.items.length, 0);
  syncWorkOrderCalendarToolbar(unscheduledCount);

  if (workOrderCalendarMeta) {
    const scheduledCount = calendar.weeks.reduce((sum, week) => sum + week.totalCount, 0);
    workOrderCalendarMeta.textContent = `${scheduledCount} raspoređenih · ${unscheduledCount} bez datuma`;
  }

  if (workOrderCalendarUnscheduled) {
    workOrderCalendarUnscheduled.hidden = unscheduledCount === 0 || !state.workOrderCalendar.showUnscheduled;
    workOrderCalendarUnscheduled.replaceChildren();

    if (unscheduledCount > 0) {
      const head = document.createElement("div");
      head.className = "work-order-calendar-unscheduled-head";

      const label = document.createElement("strong");
      label.textContent = "Bez datuma";

      const meta = document.createElement("span");
      meta.textContent = "Dodijeli datum pa ce se RN pojaviti u kalendaru.";
      head.append(label, meta);

      const list = document.createElement("div");
      list.className = "work-order-calendar-unscheduled-groups";
      calendar.unscheduledGroups.forEach((group) => {
        list.append(createWorkOrderCalendarUnscheduledGroup(group));
      });

      workOrderCalendarUnscheduled.append(head, list);
    }
  }

  const fragment = document.createDocumentFragment();
  const scheduledCount = calendar.weeks.reduce((sum, week) => sum + week.totalCount, 0);

  if (scheduledCount === 0) {
    const emptyState = document.createElement("div");
    emptyState.className = "work-order-calendar-empty";

    const title = document.createElement("strong");
    title.textContent = "Nema raspoređenih RN-a";

    const text = document.createElement("span");
    text.textContent = "Dodijeli datum i tim da bi se radni nalozi pojavili u kalendaru.";

    emptyState.append(title, text);
    fragment.append(emptyState);
    workOrderCalendarGrid.replaceChildren(fragment);
    return;
  }

  calendar.weeks.forEach((week) => {
    const visibleDays = getVisibleCalendarWeekDays(week.days, state.workOrderCalendar.showWeekends);
    const weekBlock = document.createElement("section");
    weekBlock.className = "work-order-calendar-week-block";

    const weekHead = document.createElement("div");
    weekHead.className = "work-order-calendar-week-head";

    const weekCopy = document.createElement("div");
    weekCopy.className = "work-order-calendar-week-copy";

    const weekTitle = document.createElement("strong");
    weekTitle.textContent = `${formatCompactDate(visibleDays[0]?.key ?? week.weekStart)} - ${formatCompactDate(
      visibleDays[visibleDays.length - 1]?.key ?? visibleDays[0]?.key ?? week.weekStart,
    )}`;

    const weekMeta = document.createElement("span");
    weekMeta.textContent = week.totalCount === 1 ? "1 RN" : `${week.totalCount} RN`;

    weekCopy.append(weekTitle, weekMeta);
    weekHead.append(weekCopy);
    weekBlock.append(weekHead);

    const headerRow = document.createElement("div");
    headerRow.className = "work-order-calendar-week-row is-head";
    applyWorkOrderCalendarRowLayout(headerRow, visibleDays.length);

    const teamHead = document.createElement("div");
    teamHead.className = "work-order-calendar-week-team-head";
    teamHead.textContent = "Raspored";
    headerRow.append(teamHead);

    visibleDays.forEach((day) => {
      const dayHead = document.createElement("div");
      dayHead.className = "work-order-calendar-week-day-head";
      dayHead.classList.toggle("is-today", day.isToday);
      dayHead.classList.toggle("is-outside-month", !day.inMonth);

      const label = document.createElement("span");
      label.className = "work-order-calendar-day-label";
      label.textContent = new Intl.DateTimeFormat("hr-HR", { weekday: "short" }).format(parseDateValue(day.key));

      const date = document.createElement("strong");
      date.className = "work-order-calendar-day-date";
      date.textContent = formatCompactDate(day.key);

      dayHead.append(label, date);
      const absenceStrip = createWorkOrderCalendarAbsenceStrip(getAbsenceEntriesForDate(day.key), {
        compact: true,
        maxVisible: 2,
        className: "work-order-calendar-head-absence-strip",
      });
      if (absenceStrip) {
        dayHead.append(absenceStrip);
      }
      headerRow.append(dayHead);
    });

    weekBlock.append(headerRow);

    if (week.groups.length === 0) {
      const emptyRow = document.createElement("div");
      emptyRow.className = "work-order-calendar-week-row";
      applyWorkOrderCalendarRowLayout(emptyRow, visibleDays.length);

      const emptyLead = document.createElement("div");
      emptyLead.className = "work-order-calendar-team-lead";

      const emptyTitleWrap = document.createElement("div");
      emptyTitleWrap.className = "work-order-calendar-team-copy";

      const emptyTitle = document.createElement("strong");
      emptyTitle.className = "work-order-calendar-team-name";
      emptyTitle.textContent = "Bez rasporeda";

      const emptyMeta = document.createElement("span");
      emptyMeta.className = "work-order-calendar-team-meta";
      emptyMeta.textContent = "Nema RN za ovaj tjedan";

      emptyTitleWrap.append(emptyTitle, emptyMeta);
      emptyLead.append(emptyTitleWrap);
      emptyRow.append(emptyLead);

      visibleDays.forEach((day) => {
        emptyRow.append(createWorkOrderCalendarWeekCell(day, {
          key: "team:unassigned",
          label: "Bez tima",
          isUnassigned: true,
        }, []));
      });

      weekBlock.append(emptyRow);
      fragment.append(weekBlock);
      return;
    }

    week.groups.forEach((group) => {
      const row = document.createElement("div");
      row.className = "work-order-calendar-week-row";
      applyWorkOrderCalendarRowLayout(row, visibleDays.length);

      row.append(createWorkOrderCalendarGroupLead(group));

      visibleDays.forEach((day) => {
        row.append(createWorkOrderCalendarWeekCell(day, group, group.itemsByDate[day.key] ?? []));
      });

      weekBlock.append(row);
    });

    fragment.append(weekBlock);
  });

  workOrderCalendarGrid.replaceChildren(fragment);
}

function renderWorkOrderCroatiaMapView() {
  if (!workOrderMapView || !workOrderMapStage || !workOrderMapCanvas) {
    return;
  }

  const filtered = getMapFilteredWorkOrders();
  const mapData = buildWorkOrderMapMarkers(filtered);
  const markers = mapData.markers;
  const missingCoordinatesCount = filtered.length - markers.length;

  if (workOrderMapSummary) {
    workOrderMapSummary.textContent = `${markers.length} s koordinatama · ${missingCoordinatesCount} bez koordinata`;
  }

  if (markers.length === 0) {
    state.workOrderMap.selectedWorkOrderId = "";
    state.workOrderMap.popupWorkOrderId = "";
    setWorkOrderMapEmptyOverlay(true);
    syncWorkOrderLeafletMarkers([]);
    return;
  }

  setWorkOrderMapEmptyOverlay(false);

  if (!markers.some((item) => String(item.workOrderId) === String(state.workOrderMap.selectedWorkOrderId))) {
    state.workOrderMap.selectedWorkOrderId = markers[0].workOrderId;
  }

  if (!markers.some((item) => String(item.workOrderId) === String(state.workOrderMap.popupWorkOrderId))) {
    state.workOrderMap.popupWorkOrderId = "";
  }

  syncWorkOrderLeafletMarkers(markers);
}

const WORK_ORDER_METRIC_FILTERS = new Set([
  "open",
  "overdue",
  "completed-month",
  "invoiced-month",
  "pending-invoice",
  "due-soon",
  "executors",
]);

function getWorkOrderDateKey(value = "") {
  const normalized = String(value ?? "").trim();
  return /^\d{4}-\d{2}-\d{2}/.test(normalized) ? normalized.slice(0, 10) : "";
}

function getWorkOrderCompletionDateKey(item = {}) {
  if (!isClosedWorkOrder(item.status)) {
    return "";
  }
  return getWorkOrderDateKey(item.executionDate)
    || getWorkOrderDateKey(item.completedAt)
    || getWorkOrderDateKey(item.updatedAt)
    || getWorkOrderDateKey(item.openedDate);
}

function getWorkOrderInvoiceDateKey(item = {}) {
  return getWorkOrderDateKey(item.invoiceDate)
    || (String(item.status || "") === "Fakturiran RN" ? getWorkOrderCompletionDateKey(item) : "");
}

function getWorkOrderInvoiceAmount(item = {}) {
  return Math.max(0, parseOfferMoneyInput(item.weight, 0));
}

function hasWorkOrderInvoiceData(item = {}) {
  const status = String(item.status || "");
  return Boolean(
    getWorkOrderDateKey(item.invoiceDate)
    || String(item.invoiceNote || "").trim()
    || status === "Fakturiran RN",
  );
}

function getWorkOrderReadyForInvoiceDateKey(item = {}) {
  return getWorkOrderCompletionDateKey(item)
    || getWorkOrderDateKey(item.executionDate)
    || getWorkOrderDateKey(item.completedAt)
    || getWorkOrderDateKey(item.updatedAt)
    || getWorkOrderDateKey(item.openedDate);
}

function isWorkOrderReadyForInvoice(item = {}) {
  const status = String(item.status || "");
  if (status === "Storno RN") {
    return false;
  }

  return Boolean(
    ["Gotov RN", "Ovjeren RN", "Fakturiran RN"].includes(status)
    || String(item.completedBy || "").trim()
    || getWorkOrderDateKey(item.executionDate),
  );
}

function isWorkOrderWaitingForInvoice(item = {}) {
  return isWorkOrderReadyForInvoice(item) && !hasWorkOrderInvoiceData(item);
}

function getWorkOrderFinanceStatus(item = {}) {
  const status = String(item.status || "");
  const rawPaymentStatus = normalizeLooseName([
    item.paymentStatus,
    item.invoiceStatus,
    item.paymentNote,
  ].filter(Boolean).join(" "));

  if (status === "Storno RN") {
    return { state: "cancelled", label: "STORNO" };
  }

  if (
    rawPaymentStatus.includes("naplac")
    || rawPaymentStatus.includes("placen")
    || rawPaymentStatus.includes("paid")
  ) {
    return { state: "paid", label: "NAPLAĆENO" };
  }

  if (hasWorkOrderInvoiceData(item)) {
    return { state: "invoiced", label: "FAKTURIRANO" };
  }

  if (isWorkOrderWaitingForInvoice(item)) {
    return { state: "pending-invoice", label: "ČEKA FAKTURU" };
  }

  return { state: "draft", label: "U PRIPREMI" };
}

function getDateDistanceInDays(targetDateKey = "", baseDateKey = getTodayDateKey()) {
  const target = Date.parse(`${targetDateKey}T12:00:00`);
  const base = Date.parse(`${baseDateKey}T12:00:00`);
  if (!Number.isFinite(target) || !Number.isFinite(base)) {
    return Number.NaN;
  }
  return Math.round((target - base) / 86400000);
}

function isWorkOrderDueWithin(item = {}, fromDays = 0, toDays = 7, todayKey = getTodayDateKey()) {
  if (!item?.dueDate || isClosedWorkOrder(item.status)) {
    return false;
  }
  const days = getDateDistanceInDays(item.dueDate, todayKey);
  return Number.isFinite(days) && days >= fromDays && days <= toDays;
}

function isWorkOrderMetricMatch(item = {}, metricKey = "", todayKey = getTodayDateKey()) {
  const monthKey = todayKey.slice(0, 7);
  if (metricKey === "open") {
    return String(item.status || "") === "Otvoreni RN";
  }
  if (metricKey === "overdue") {
    return isOverdueWorkOrder(item);
  }
  if (metricKey === "completed-month") {
    return getWorkOrderCompletionDateKey(item).startsWith(monthKey);
  }
  if (metricKey === "invoiced-month") {
    return getWorkOrderInvoiceDateKey(item).startsWith(monthKey);
  }
  if (metricKey === "pending-invoice") {
    return isWorkOrderWaitingForInvoice(item);
  }
  if (metricKey === "due-soon") {
    return isWorkOrderDueWithin(item, 0, 7, todayKey);
  }
  if (metricKey === "executors") {
    return !isClosedWorkOrder(item.status) && getWorkOrderExecutors(item).length > 0;
  }
  return true;
}

function applyWorkOrderMetricFilter(items = []) {
  const metricKey = String(state.workOrderMetricFilter || "");
  if (!WORK_ORDER_METRIC_FILTERS.has(metricKey)) {
    return items;
  }
  const todayKey = getTodayDateKey();
  return items.filter((item) => isWorkOrderMetricMatch(item, metricKey, todayKey));
}

function getMetricDelta(currentValue = 0, previousValue = 0) {
  const current = Number(currentValue) || 0;
  const previous = Number(previousValue) || 0;
  if (previous <= 0) {
    return current > 0 ? 100 : 0;
  }
  return Math.round(((current - previous) / previous) * 100);
}

function formatMetricDelta(value = 0) {
  const numeric = Number(value) || 0;
  if (numeric === 0) {
    return "0%";
  }
  return `${numeric > 0 ? "+" : ""}${numeric}%`;
}

function formatCompactMetricCurrency(value = 0) {
  const numeric = Number(value) || 0;
  return new Intl.NumberFormat("hr-HR", {
    style: "currency",
    currency: "EUR",
    maximumFractionDigits: numeric >= 10000 ? 0 : 2,
  }).format(numeric);
}

function getMetricDeltaClass(metric = {}) {
  const numericDelta = Number(metric.delta) || 0;
  if (numericDelta === 0) {
    return "is-neutral";
  }
  if (metric.badWhenUp) {
    return numericDelta > 0 ? "is-down" : "is-up";
  }
  return numericDelta > 0 ? "is-up" : "is-down";
}

function buildRollingMetricValues(items = [], dateGetter, { bucketCount = 6, bucketDays = 7, valueGetter = () => 1 } = {}) {
  const todayKey = getTodayDateKey();
  return Array.from({ length: bucketCount }, (_, index) => {
    const bucketStart = shiftDateKey(todayKey, -((bucketCount - index) * bucketDays) + 1);
    const bucketEnd = shiftDateKey(bucketStart, bucketDays - 1);
    return items.reduce((sum, item) => {
      const dateKey = getWorkOrderDateKey(dateGetter(item));
      if (!dateKey || dateKey < bucketStart || dateKey > bucketEnd) {
        return sum;
      }
      return sum + (Number(valueGetter(item)) || 0);
    }, 0);
  });
}

function shiftMonthKey(monthKey = getTodayDateKey().slice(0, 7), offset = 0) {
  const [year, month] = monthKey.split("-").map((value) => Number(value));
  const date = new Date(year || new Date().getFullYear(), (month || 1) - 1 + offset, 1, 12, 0, 0, 0);
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}

function buildMonthlyMetricValues(items = [], dateGetter, { monthCount = 6, valueGetter = () => 1 } = {}) {
  const currentMonth = getTodayDateKey().slice(0, 7);
  return Array.from({ length: monthCount }, (_, index) => {
    const monthKey = shiftMonthKey(currentMonth, index - monthCount + 1);
    return items.reduce((sum, item) => {
      const dateKey = getWorkOrderDateKey(dateGetter(item));
      return dateKey.startsWith(monthKey) ? sum + (Number(valueGetter(item)) || 0) : sum;
    }, 0);
  });
}

function buildMetricSparkline(values = [], tone = "blue") {
  const safeValues = values.length > 0 ? values.map((value) => Math.max(0, Number(value) || 0)) : [0, 0];
  const maxValue = Math.max(1, ...safeValues);
  const points = safeValues.map((value, index) => {
    const x = safeValues.length === 1 ? 48 : (index / (safeValues.length - 1)) * 96;
    const y = 23 - ((value / maxValue) * 18);
    return `${x.toFixed(2)},${y.toFixed(2)}`;
  }).join(" ");
  const areaPoints = `0,24 ${points} 96,24`;
  return `
    <svg class="work-order-metric-sparkline is-${escapeHtml(tone)}" viewBox="0 0 96 24" aria-hidden="true" focusable="false">
      <polygon class="metric-sparkline-area" points="${areaPoints}"></polygon>
      <polyline class="metric-sparkline-line" points="${points}"></polyline>
    </svg>
  `;
}

function buildMetricBars(values = [], tone = "blue") {
  const safeValues = values.length > 0 ? values.map((value) => Math.max(0, Number(value) || 0)) : [0];
  const maxValue = Math.max(1, ...safeValues);
  return `
    <span class="work-order-metric-bars is-${escapeHtml(tone)}" aria-hidden="true">
      ${safeValues.map((value) => `<span style="--bar:${Math.max(7, Math.round((value / maxValue) * 100))}%"></span>`).join("")}
    </span>
  `;
}

function buildMetricDonut({ today = 0, soon = 0, week = 0 } = {}) {
  const total = Math.max(0, today + soon + week);
  const todayPart = total > 0 ? (today / total) * 100 : 0;
  const soonPart = total > 0 ? ((today + soon) / total) * 100 : 0;
  return `
    <span class="work-order-metric-donut" style="--today:${todayPart.toFixed(2)}%;--soon:${soonPart.toFixed(2)}%" aria-hidden="true">
      <span>${total}</span>
    </span>
  `;
}

function buildWorkOrderMetricData(items = state.workOrders ?? []) {
  const workOrders = Array.isArray(items) ? items : [];
  const todayKey = getTodayDateKey();
  const monthKey = todayKey.slice(0, 7);
  const previousMonthKey = shiftMonthKey(monthKey, -1);
  const activeItems = workOrders.filter((item) => !isClosedWorkOrder(item.status));
  const openItems = workOrders.filter((item) => String(item.status || "") === "Otvoreni RN");
  const overdueItems = activeItems.filter((item) => isOverdueWorkOrder(item));
  const completedThisMonth = workOrders.filter((item) => getWorkOrderCompletionDateKey(item).startsWith(monthKey));
  const completedPreviousMonth = workOrders.filter((item) => getWorkOrderCompletionDateKey(item).startsWith(previousMonthKey));
  const invoicedThisMonth = workOrders.filter((item) => getWorkOrderInvoiceDateKey(item).startsWith(monthKey));
  const invoicedPreviousMonth = workOrders.filter((item) => getWorkOrderInvoiceDateKey(item).startsWith(previousMonthKey));
  const invoiceTotal = invoicedThisMonth.reduce((sum, item) => sum + getWorkOrderInvoiceAmount(item), 0);
  const previousInvoiceTotal = invoicedPreviousMonth.reduce((sum, item) => sum + getWorkOrderInvoiceAmount(item), 0);
  const dueToday = activeItems.filter((item) => isWorkOrderDueWithin(item, 0, 0, todayKey)).length;
  const dueOneToThree = activeItems.filter((item) => isWorkOrderDueWithin(item, 1, 3, todayKey)).length;
  const dueFourToSeven = activeItems.filter((item) => isWorkOrderDueWithin(item, 4, 7, todayKey)).length;
  const dueSoonTotal = dueToday + dueOneToThree + dueFourToSeven;
  const executorLoads = new Map();
  activeItems.forEach((item) => {
    getWorkOrderExecutors(item).forEach((executor) => {
      executorLoads.set(executor, (executorLoads.get(executor) || 0) + 1);
    });
  });
  const sortedExecutorLoads = [...executorLoads.entries()].sort((left, right) => right[1] - left[1]);
  const activeExecutorCount = sortedExecutorLoads.length;
  const workloadCapacity = Math.max(1, activeExecutorCount * 8);
  const workloadPercent = Math.min(100, Math.round((activeItems.length / workloadCapacity) * 100));
  const openTrend = buildRollingMetricValues(openItems, (item) => item.openedDate);
  const overdueTrend = buildRollingMetricValues(overdueItems, (item) => item.dueDate);
  const completedTrend = buildRollingMetricValues(completedThisMonth, (item) => getWorkOrderCompletionDateKey(item), { bucketCount: 5, bucketDays: 6 });
  const invoiceTrend = buildMonthlyMetricValues(workOrders, (item) => getWorkOrderInvoiceDateKey(item), { valueGetter: getWorkOrderInvoiceAmount });
  const executorTrend = sortedExecutorLoads.slice(0, 8).map(([, load]) => load);
  const openedLastSeven = workOrders.filter((item) => {
    const openedDate = getWorkOrderDateKey(item.openedDate);
    return openedDate >= shiftDateKey(todayKey, -6) && openedDate <= todayKey;
  }).length;
  const openedPreviousSeven = workOrders.filter((item) => {
    const openedDate = getWorkOrderDateKey(item.openedDate);
    return openedDate >= shiftDateKey(todayKey, -13) && openedDate <= shiftDateKey(todayKey, -7);
  }).length;
  const overdueMoreThanSeven = overdueItems.filter((item) => getDateDistanceInDays(item.dueDate, todayKey) <= -7).length;
  const overdueMoreThanThirty = overdueItems.filter((item) => getDateDistanceInDays(item.dueDate, todayKey) <= -30).length;
  const urgentOpen = openItems.filter((item) => String(item.priority || "") === "Urgent").length;
  const activeAssignments = [...executorLoads.values()].reduce((sum, value) => sum + value, 0);

  return [
    {
      id: "open",
      tone: "violet",
      title: "Otvoreni RN",
      value: openItems.length,
      delta: getMetricDelta(openedLastSeven, openedPreviousSeven),
      chart: buildMetricSparkline(openTrend, "violet"),
      metaLeft: `${overdueItems.length} kasni`,
      metaRight: `${urgentOpen} hitno`,
    },
    {
      id: "overdue",
      tone: "red",
      title: "RN u kašnjenju",
      value: overdueItems.length,
      delta: getMetricDelta(overdueItems.length, Math.max(0, overdueItems.length - overdueTrend.at(-2) || 0)),
      badWhenUp: true,
      chart: buildMetricSparkline(overdueTrend, "red"),
      metaLeft: `${overdueMoreThanSeven} više od 7 dana`,
      metaRight: `${overdueMoreThanThirty} više od 30 dana`,
    },
    {
      id: "completed-month",
      tone: "green",
      title: "Završeni ovaj mjesec",
      value: completedThisMonth.length,
      delta: getMetricDelta(completedThisMonth.length, completedPreviousMonth.length),
      chart: buildMetricSparkline(completedTrend, "green"),
      metaLeft: `Cilj ${Math.max(completedThisMonth.length, completedPreviousMonth.length, 1)}`,
      metaRight: `${completedPreviousMonth.length} prošli mj.`,
    },
    {
      id: "invoiced-month",
      tone: "blue",
      title: "Fakturirano ovaj mjesec",
      value: formatCompactMetricCurrency(invoiceTotal),
      delta: getMetricDelta(invoiceTotal, previousInvoiceTotal),
      chart: buildMetricSparkline(invoiceTrend, "blue"),
      metaLeft: `${invoicedThisMonth.length} RN`,
      metaRight: `Prosj. ${formatCompactMetricCurrency(invoicedThisMonth.length ? invoiceTotal / invoicedThisMonth.length : 0)}`,
    },
    {
      id: "due-soon",
      tone: "amber",
      title: "Rokovi uskoro",
      value: dueSoonTotal,
      delta: getMetricDelta(dueSoonTotal, overdueItems.length),
      badWhenUp: true,
      chart: buildMetricSparkline([dueToday, dueOneToThree, dueFourToSeven, dueSoonTotal], "orange"),
      metaLeft: `${dueToday} danas`,
      metaRight: `${dueOneToThree} 1-3d · ${dueFourToSeven} 4-7d`,
    },
    {
      id: "executors",
      tone: "indigo",
      title: "Aktivni izvršitelji",
      value: activeExecutorCount,
      delta: activeExecutorCount > 0 ? getMetricDelta(activeExecutorCount, Math.max(1, activeExecutorCount - 1)) : 0,
      chart: buildMetricSparkline(executorTrend, "violet"),
      metaLeft: `${workloadPercent}% workload`,
      metaRight: `${activeAssignments} dodjela`,
    },
  ];
}

function renderWorkOrderPremiumSummary(items = state.workOrders ?? []) {
  if (!workOrderMetricsBar) {
    return;
  }

  const metrics = buildWorkOrderMetricData(items);
  workOrderMetricsBar.replaceChildren(...metrics.map((metric) => {
    const card = document.createElement("button");
    card.type = "button";
    card.className = `work-order-metric-card is-${metric.tone}`;
    card.dataset.workOrderMetric = metric.id;
    const isActive = state.workOrderMetricFilter === metric.id;
    card.classList.toggle("is-active", isActive);
    card.setAttribute("aria-pressed", isActive ? "true" : "false");
    card.setAttribute("aria-label", `${metric.title}: ${metric.value}`);

    const deltaClass = getMetricDeltaClass(metric);
    card.innerHTML = `
      <span class="work-order-metric-head">
        <span class="work-order-metric-title">${escapeHtml(metric.title)}</span>
        <span class="work-order-metric-delta ${deltaClass}">${escapeHtml(formatMetricDelta(metric.delta))}</span>
      </span>
      <span class="work-order-metric-main">
        <strong>${escapeHtml(metric.value)}</strong>
      </span>
      <span class="work-order-metric-chart">${metric.chart}</span>
      <span class="work-order-metric-meta">
        <span>${escapeHtml(metric.metaLeft)}</span>
        <span>${escapeHtml(metric.metaRight)}</span>
      </span>
    `;
    card.addEventListener("click", () => {
      state.workOrderMetricFilter = state.workOrderMetricFilter === metric.id ? "" : metric.id;
      resetWorkOrderListWindow();
      renderWorkOrderWorkspace();
    });
    return card;
  }));
}

function getFieldInquiryStatusOption(status = "") {
  const normalizedStatus = String(status || "").trim() || "inquiry";
  return FIELD_INQUIRY_STATUS_OPTIONS.find((option) => option.value === normalizedStatus)
    || FIELD_INQUIRY_STATUS_OPTIONS[0]
    || { value: "inquiry", label: "Upit" };
}

function getFieldInquiryStatusLabel(status = "") {
  return getFieldInquiryStatusOption(status).label;
}

function getFieldInquiryById(id = "") {
  const normalizedId = String(id || "").trim();
  if (!normalizedId) {
    return null;
  }
  return (state.fieldInquiries ?? []).find((item) => String(item.id) === normalizedId) ?? null;
}

function getFieldInquiryCompany(item = {}) {
  return (state.companies ?? []).find((company) => String(company.id) === String(item.companyId || "")) ?? null;
}

function getFieldInquiryLocation(item = {}) {
  return (state.locations ?? []).find((location) => String(location.id) === String(item.locationId || "")) ?? null;
}

function getFieldInquiryWorkOrder(item = {}) {
  return (state.workOrders ?? []).find((workOrder) => String(workOrder.id) === String(item.workOrderId || "")) ?? null;
}

function getFieldInquiryVehicle(item = {}) {
  return (state.vehicles ?? []).find((vehicle) => String(vehicle.id) === String(item.vehicleId || "")) ?? null;
}

function getFieldInquiryCompanyLabel(item = {}) {
  return item.companyName || getFieldInquiryCompany(item)?.name || "";
}

function getFieldInquiryLocationLabel(item = {}) {
  return item.locationName || getFieldInquiryLocation(item)?.name || "";
}

function getFieldInquiryWorkOrderLabel(item = {}) {
  return item.workOrderNumber || getFieldInquiryWorkOrder(item)?.workOrderNumber || "";
}

function getFieldInquiryVehicleLabel(item = {}) {
  const vehicle = getFieldInquiryVehicle(item);
  return item.vehicleLabel || vehicle?.registration || vehicle?.name || "";
}

function getFieldInquiryAssigneeLabels(item = {}) {
  const explicitLabels = Array.isArray(item.assignedUserLabels)
    ? item.assignedUserLabels.map((value) => String(value || "").trim()).filter(Boolean)
    : [];
  if (explicitLabels.length > 0) {
    return explicitLabels;
  }
  const selectedIds = new Set(
    (Array.isArray(item.assignedUserIds) ? item.assignedUserIds : [])
      .map((value) => String(value || "").trim())
      .filter(Boolean),
  );
  if (selectedIds.size === 0) {
    return [];
  }
  return (state.users ?? [])
    .filter((user) => selectedIds.has(String(user.id)))
    .map((user) => user.fullName || user.username || user.email || "")
    .filter(Boolean);
}

function compareFieldInquiries(left = {}, right = {}) {
  const leftDate = normalizeDateInputValue(left.plannedDate || "") || "9999-12-31";
  const rightDate = normalizeDateInputValue(right.plannedDate || "") || "9999-12-31";
  if (leftDate !== rightDate) {
    return leftDate.localeCompare(rightDate);
  }
  const leftTime = String(left.timeFrom || "").padEnd(5, "9") || "99:99";
  const rightTime = String(right.timeFrom || "").padEnd(5, "9") || "99:99";
  if (leftTime !== rightTime) {
    return leftTime.localeCompare(rightTime);
  }
  return String(right.updatedAt || right.createdAt || "").localeCompare(String(left.updatedAt || left.createdAt || ""));
}

function getSortedFieldInquiries() {
  return [...(state.fieldInquiries ?? [])].sort(compareFieldInquiries);
}

function rebuildFieldInquiryOptions({
  selectedCompanyId = fieldInquiryCompanyInput?.value || "",
  selectedLocationId = fieldInquiryLocationInput?.value || "",
  selectedWorkOrderId = fieldInquiryWorkOrderInput?.value || "",
  selectedVehicleId = fieldInquiryVehicleInput?.value || "",
  selectedAssigneeIds = getSelectedMultiSelectValues(fieldInquiryAssigneesInput),
} = {}) {
  if (fieldInquiryStatusInput) {
    replaceSelectOptions(fieldInquiryStatusInput, FIELD_INQUIRY_STATUS_OPTIONS, fieldInquiryStatusInput.value || "inquiry");
  }

  if (fieldInquiryCompanyInput) {
    const companyOptions = [
      { value: "", label: "Bez tvrtke" },
      ...(state.companies ?? [])
        .slice()
        .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "hr"))
        .map((company) => ({ value: company.id, label: company.name || "Tvrtka" })),
    ];
    replaceSelectOptions(fieldInquiryCompanyInput, companyOptions, selectedCompanyId);
  }

  if (fieldInquiryLocationInput) {
    const locationOptions = (state.locations ?? [])
      .filter((location) => !selectedCompanyId || String(location.companyId || "") === String(selectedCompanyId))
      .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "hr"))
      .map((location) => ({
        value: location.id,
        label: [location.name, location.companyName].filter(Boolean).join(" · ") || "Lokacija",
      }));
    replaceSelectOptions(fieldInquiryLocationInput, [
      { value: "", label: selectedCompanyId ? "Bez lokacije" : "Bez lokacije / slobodni upit" },
      ...locationOptions,
    ], selectedLocationId);
  }

  if (fieldInquiryWorkOrderInput) {
    const workOrderOptions = sortWorkOrders(state.workOrders ?? [])
      .filter((workOrder) => !selectedCompanyId || String(workOrder.companyId || "") === String(selectedCompanyId))
      .slice(0, 500)
      .map((workOrder) => ({
        value: workOrder.id,
        label: [
          workOrder.workOrderNumber || "RN",
          workOrder.companyName || "",
          workOrder.locationName || "",
        ].filter(Boolean).join(" · "),
      }));
    replaceSelectOptions(fieldInquiryWorkOrderInput, [
      { value: "", label: "Bez RN-a" },
      ...workOrderOptions,
    ], selectedWorkOrderId);
  }

  if (fieldInquiryVehicleInput) {
    const vehicleOptions = (state.vehicles ?? [])
      .slice()
      .sort((left, right) => String(left.registration || left.name || "").localeCompare(String(right.registration || right.name || ""), "hr"))
      .map((vehicle) => ({
        value: vehicle.id,
        label: [vehicle.registration || vehicle.name || "Vozilo", vehicle.model || vehicle.name || ""].filter(Boolean).join(" · "),
      }));
    replaceSelectOptions(fieldInquiryVehicleInput, [
      { value: "", label: "Bez vozila" },
      ...vehicleOptions,
    ], selectedVehicleId);
  }

  if (fieldInquiryAssigneesInput) {
    const userOptions = (state.users ?? [])
      .slice()
      .sort((left, right) => String(left.fullName || left.username || left.email || "").localeCompare(String(right.fullName || right.username || right.email || ""), "hr"))
      .map((user) => ({
        value: user.id,
        label: user.fullName || user.username || user.email || "Korisnik",
      }));
    replaceSelectOptions(fieldInquiryAssigneesInput, userOptions, "");
    setMultiSelectSelectedValues(fieldInquiryAssigneesInput, selectedAssigneeIds);
  }
}

function normalizeFieldInquiryDocuments(documents = []) {
  return (Array.isArray(documents) ? documents : [])
    .map((document) => ({
      id: String(document?.id || crypto.randomUUID()),
      fileName: String(document?.fileName || document?.name || "").trim(),
      fileType: String(document?.fileType || document?.type || document?.mimeType || "").trim(),
      fileSize: Number(document?.fileSize || document?.size || 0) || 0,
      documentCategory: String(document?.documentCategory || "field_inquiry").trim(),
      dataUrl: String(document?.dataUrl || document?.storageUrl || document?.url || "").trim(),
      storageUrl: String(document?.storageUrl || document?.url || document?.dataUrl || "").trim(),
      createdAt: document?.createdAt || new Date().toISOString(),
      updatedAt: document?.updatedAt || document?.createdAt || new Date().toISOString(),
    }))
    .filter((document) => document.fileName && (document.dataUrl || document.storageUrl));
}

function renderFieldInquiryDocumentDraft() {
  if (!fieldInquiryDocumentList) {
    return;
  }
  if (fieldInquiryDocumentDraft.length === 0) {
    const empty = document.createElement("p");
    empty.className = "field-inquiry-document-empty";
    empty.textContent = "Nema dodanih dokumenata za ovaj dogovor.";
    fieldInquiryDocumentList.replaceChildren(empty);
    return;
  }

  fieldInquiryDocumentList.replaceChildren(...fieldInquiryDocumentDraft.map((documentItem) => {
    const row = document.createElement("div");
    row.className = "field-inquiry-document-item";

    const copy = document.createElement("div");
    copy.className = "field-inquiry-document-copy";
    const name = document.createElement("strong");
    name.textContent = documentItem.fileName;
    const meta = document.createElement("span");
    meta.textContent = [documentItem.fileType, documentItem.fileSize ? formatFileSize(documentItem.fileSize) : ""].filter(Boolean).join(" · ");
    copy.append(name, meta);

    const actions = document.createElement("div");
    actions.className = "field-inquiry-document-actions";
    const href = documentItem.storageUrl || documentItem.dataUrl;
    if (href) {
      const openLink = document.createElement("a");
      openLink.className = "ghost-button";
      openLink.href = href;
      openLink.target = "_blank";
      openLink.rel = "noopener";
      openLink.textContent = "Otvori";
      actions.append(openLink);
    }
    actions.append(createActionButton("Makni", "ghost-button card-danger", (event) => {
      event.stopPropagation();
      fieldInquiryDocumentDraft = fieldInquiryDocumentDraft.filter((entry) => entry.id !== documentItem.id);
      renderFieldInquiryDocumentDraft();
    }));

    row.append(copy, actions);
    return row;
  }));
}

async function addFieldInquiryDocuments(files = []) {
  const selectedFiles = Array.from(files || []).filter(Boolean);
  if (selectedFiles.length === 0) {
    return;
  }
  try {
    const nextDocuments = await Promise.all(selectedFiles.map(async (file) => ({
      id: crypto.randomUUID(),
      fileName: file.name || "dokument",
      fileType: file.type || "application/octet-stream",
      fileSize: file.size || 0,
      documentCategory: "field_inquiry",
      dataUrl: await readFileAsDataUrl(file, `Ne mogu učitati datoteku ${file.name}.`),
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    })));
    fieldInquiryDocumentDraft = normalizeFieldInquiryDocuments([...fieldInquiryDocumentDraft, ...nextDocuments]);
    renderFieldInquiryDocumentDraft();
  } catch (error) {
    setInlineMessage(fieldInquiryFeedback, error.message || "Dokument nije učitan.");
  } finally {
    if (fieldInquiryDocumentFileInput) {
      fieldInquiryDocumentFileInput.value = "";
    }
  }
}

function appendFieldInquiryNote(text = "") {
  const value = String(text || "").trim();
  if (!fieldInquiryNoteInput || !value) {
    return;
  }
  const current = String(fieldInquiryNoteInput.value || "");
  const separator = !current || current.endsWith(" ") || current.endsWith("\n") ? "" : " ";
  fieldInquiryNoteInput.value = `${current}${separator}${value}`;
  fieldInquiryNoteInput.dispatchEvent(new Event("input", { bubbles: true }));
}

function getFieldInquiryPolishContext() {
  const selectedCompany = getFieldInquiryCompany({
    companyId: fieldInquiryCompanyInput?.value || "",
  });
  const selectedLocation = getFieldInquiryLocation({
    locationId: fieldInquiryLocationInput?.value || "",
  });
  return {
    title: fieldInquiryTitleInput?.value || "",
    currentNote: fieldInquiryNoteInput?.value || "",
    companyName: selectedCompany?.name || "",
    locationName: selectedLocation?.name || "",
    serviceLine: fieldInquiryServiceLineInput?.value || "",
  };
}

async function polishFieldInquiryNoteTranscript(transcript = "") {
  const text = String(transcript || "").trim();
  if (!text) {
    return "";
  }
  try {
    const payload = await apiRequest("/field-inquiries/polish-note", {
      method: "POST",
      body: {
        ...getFieldInquiryPolishContext(),
        transcript: text,
      },
    });
    return String(payload?.note || "").trim() || text;
  } catch (error) {
    setInlineMessage(fieldInquiryFeedback, error.message || "NexAI nije sredio opis, koristim diktirani tekst.");
    return text;
  }
}

function startFieldInquiryNoteDictation() {
  const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!Recognition) {
    setInlineMessage(fieldInquiryFeedback, "Govorni unos nije dostupan u ovom pregledniku.");
    return;
  }
  const recognition = new Recognition();
  recognition.lang = "hr-HR";
  recognition.interimResults = false;
  recognition.maxAlternatives = 1;
  fieldInquiryNoteMicButton?.setAttribute("aria-busy", "true");
  recognition.addEventListener("result", (event) => {
    const transcript = Array.from(event.results || [])
      .map((result) => result?.[0]?.transcript || "")
      .join(" ")
      .trim();
    void polishFieldInquiryNoteTranscript(transcript).then((note) => {
      if (!note) {
        return;
      }
      if (fieldInquiryNoteInput) {
        fieldInquiryNoteInput.value = note;
        fieldInquiryNoteInput.dispatchEvent(new Event("input", { bubbles: true }));
      }
    });
  });
  recognition.addEventListener("error", () => {
    setInlineMessage(fieldInquiryFeedback, "Ne mogu pokrenuti mikrofon za opis.");
  });
  recognition.addEventListener("end", () => {
    fieldInquiryNoteMicButton?.removeAttribute("aria-busy");
  });
  recognition.start();
}

function resetFieldInquiryForm() {
  state.activeFieldInquiryId = "";
  if (fieldInquiryFormTitle) {
    fieldInquiryFormTitle.textContent = "Novi upit za teren";
  }
  if (fieldInquiryIdInput) fieldInquiryIdInput.value = "";
  if (fieldInquiryTitleInput) fieldInquiryTitleInput.value = "";
  if (fieldInquiryStatusInput) fieldInquiryStatusInput.value = "inquiry";
  if (fieldInquiryPlannedDateInput) fieldInquiryPlannedDateInput.value = formatDateInputDisplayValue(getTodayDateKey());
  if (fieldInquiryTimeFromInput) fieldInquiryTimeFromInput.value = "";
  if (fieldInquiryTimeToInput) fieldInquiryTimeToInput.value = "";
  if (fieldInquiryContactNameInput) fieldInquiryContactNameInput.value = "";
  if (fieldInquiryContactPhoneInput) fieldInquiryContactPhoneInput.value = "";
  if (fieldInquiryServiceLineInput) fieldInquiryServiceLineInput.value = "";
  if (fieldInquiryNoteInput) fieldInquiryNoteInput.value = "";
  fieldInquiryDocumentDraft = [];
  renderFieldInquiryDocumentDraft();
  if (fieldInquirySyncWorkOrderDateInput) fieldInquirySyncWorkOrderDateInput.checked = true;
  const currentUserId = state.user?.id ? [String(state.user.id)] : [];
  rebuildFieldInquiryOptions({
    selectedCompanyId: "",
    selectedLocationId: "",
    selectedWorkOrderId: "",
    selectedVehicleId: "",
    selectedAssigneeIds: currentUserId,
  });
  if (fieldInquiryConvertButton) {
    fieldInquiryConvertButton.hidden = true;
  }
  setInlineMessage(fieldInquiryFeedback, "");
}

function hydrateFieldInquiryForm(item = {}) {
  state.activeFieldInquiryId = String(item.id || "");
  if (fieldInquiryFormTitle) {
    fieldInquiryFormTitle.textContent = item.title ? "Uredi terenski upit" : "Terenski upit";
  }
  if (fieldInquiryIdInput) fieldInquiryIdInput.value = String(item.id || "");
  if (fieldInquiryTitleInput) fieldInquiryTitleInput.value = item.title || "";
  if (fieldInquiryStatusInput) fieldInquiryStatusInput.value = getFieldInquiryStatusOption(item.status).value;
  if (fieldInquiryPlannedDateInput) fieldInquiryPlannedDateInput.value = item.plannedDate ? formatDateInputDisplayValue(item.plannedDate) : "";
  if (fieldInquiryTimeFromInput) fieldInquiryTimeFromInput.value = item.timeFrom || "";
  if (fieldInquiryTimeToInput) fieldInquiryTimeToInput.value = item.timeTo || "";
  if (fieldInquiryContactNameInput) fieldInquiryContactNameInput.value = item.contactName || "";
  if (fieldInquiryContactPhoneInput) fieldInquiryContactPhoneInput.value = item.contactPhone || "";
  if (fieldInquiryServiceLineInput) fieldInquiryServiceLineInput.value = item.serviceLine || "";
  if (fieldInquiryNoteInput) fieldInquiryNoteInput.value = item.note || "";
  fieldInquiryDocumentDraft = normalizeFieldInquiryDocuments(item.documents ?? []);
  renderFieldInquiryDocumentDraft();
  if (fieldInquirySyncWorkOrderDateInput) fieldInquirySyncWorkOrderDateInput.checked = true;
  rebuildFieldInquiryOptions({
    selectedCompanyId: item.companyId || "",
    selectedLocationId: item.locationId || "",
    selectedWorkOrderId: item.workOrderId || "",
    selectedVehicleId: item.vehicleId || "",
    selectedAssigneeIds: Array.isArray(item.assignedUserIds) ? item.assignedUserIds.map(String) : [],
  });
  if (fieldInquiryConvertButton) {
    fieldInquiryConvertButton.hidden = !item.id || String(item.status || "") === "converted";
    fieldInquiryConvertButton.disabled = !item.companyId;
    fieldInquiryConvertButton.title = item.companyId ? "" : "Za pretvaranje u RN prvo odaberi tvrtku.";
  }
  setInlineMessage(fieldInquiryFeedback, "");
  fieldInquiryTitleInput?.focus({ preventScroll: true });
}

function syncFieldInquiryContextFromWorkOrder() {
  const workOrder = (state.workOrders ?? []).find((item) => String(item.id) === String(fieldInquiryWorkOrderInput?.value || "")) ?? null;
  if (!workOrder) {
    return;
  }
  const companyId = workOrder.companyId || "";
  const locationId = workOrder.locationId || "";
  rebuildFieldInquiryOptions({
    selectedCompanyId: companyId,
    selectedLocationId: locationId,
    selectedWorkOrderId: workOrder.id,
    selectedVehicleId: fieldInquiryVehicleInput?.value || "",
    selectedAssigneeIds: getSelectedMultiSelectValues(fieldInquiryAssigneesInput),
  });
  if (fieldInquiryServiceLineInput && !fieldInquiryServiceLineInput.value) {
    fieldInquiryServiceLineInput.value = getWorkOrderServiceSummary(workOrder) || workOrder.serviceLine || "";
  }
  if (fieldInquiryTitleInput && !fieldInquiryTitleInput.value) {
    fieldInquiryTitleInput.value = [
      workOrder.workOrderNumber || "",
      workOrder.companyName || "",
      workOrder.locationName || "",
    ].filter(Boolean).join(" · ");
  }
  if (fieldInquiryContactNameInput && !fieldInquiryContactNameInput.value) {
    fieldInquiryContactNameInput.value = workOrder.contactName || "";
  }
  if (fieldInquiryContactPhoneInput && !fieldInquiryContactPhoneInput.value) {
    fieldInquiryContactPhoneInput.value = workOrder.contactPhone || "";
  }
}

function normalizeFieldInquiryDateInput() {
  if (!fieldInquiryPlannedDateInput) {
    return "";
  }
  const normalizedValue = normalizeDateInputValue(fieldInquiryPlannedDateInput.value);
  const isValid = !normalizedValue || /^\d{4}-\d{2}-\d{2}$/.test(normalizedValue);
  fieldInquiryPlannedDateInput.value = isValid ? formatDateInputDisplayValue(normalizedValue) : fieldInquiryPlannedDateInput.value.trim();
  return isValid ? normalizedValue : "";
}

function buildFieldInquiryPayload() {
  const normalizedDate = normalizeFieldInquiryDateInput();
  const rawDate = String(fieldInquiryPlannedDateInput?.value || "").trim();
  if (rawDate && !normalizedDate) {
    throw new Error("Datum upita mora biti u formatu dd.mm.yyyy.");
  }

  const title = String(fieldInquiryTitleInput?.value || "").trim();
  if (!title) {
    throw new Error("Upiši naziv ili kratki opis upita.");
  }

  const selectedAssigneeIds = getSelectedMultiSelectValues(fieldInquiryAssigneesInput);
  const selectedAssigneeLabels = Array.from(fieldInquiryAssigneesInput?.selectedOptions ?? [])
    .map((option) => String(option.textContent || "").trim())
    .filter(Boolean);

  return {
    title,
    status: fieldInquiryStatusInput?.value || "inquiry",
    plannedDate: normalizedDate,
    timeFrom: fieldInquiryTimeFromInput?.value || "",
    timeTo: fieldInquiryTimeToInput?.value || "",
    companyId: fieldInquiryCompanyInput?.value || "",
    locationId: fieldInquiryLocationInput?.value || "",
    workOrderId: fieldInquiryWorkOrderInput?.value || "",
    vehicleId: fieldInquiryVehicleInput?.value || "",
    contactName: fieldInquiryContactNameInput?.value || "",
    contactPhone: fieldInquiryContactPhoneInput?.value || "",
    serviceLine: fieldInquiryServiceLineInput?.value || "",
    note: fieldInquiryNoteInput?.value || "",
    documents: fieldInquiryDocumentDraft,
    assignedUserIds: selectedAssigneeIds,
    assignedUserLabels: selectedAssigneeLabels,
    syncWorkOrderExecutionDate: Boolean(fieldInquirySyncWorkOrderDateInput?.checked),
  };
}

function buildFieldInquiryMatchedServiceItems(item = {}) {
  const source = String([item.serviceLine, item.title].filter(Boolean).join(" ")).toLowerCase();
  if (!source) {
    return [];
  }
  return (state.serviceCatalog ?? [])
    .filter((service) => {
      const name = String(service.name || "").toLowerCase();
      const code = String(service.serviceCode || service.code || service.shortCode || "").toLowerCase();
      return (name && source.includes(name)) || (code && source.includes(code));
    })
    .slice(0, 6)
    .map((service) => ({
      serviceId: service.id,
      name: service.name || "",
      serviceCode: service.serviceCode || service.code || service.shortCode || "",
      quantity: "1",
    }));
}

function openFieldInquiryDetail(item = {}) {
  document.querySelectorAll(".field-inquiry-detail-backdrop").forEach((node) => node.remove());

  const backdrop = document.createElement("div");
  backdrop.className = "field-inquiry-detail-backdrop";
  backdrop.setAttribute("role", "dialog");
  backdrop.setAttribute("aria-modal", "true");

  const dialog = document.createElement("article");
  dialog.className = "field-inquiry-detail-dialog";

  const closeDetail = () => {
    backdrop.remove();
  };

  const head = document.createElement("header");
  head.className = "field-inquiry-detail-head";
  const headCopy = document.createElement("div");
  const kicker = document.createElement("span");
  kicker.textContent = "Plan terena";
  const title = document.createElement("h3");
  title.textContent = item.title || "Terenski upit";
  const meta = document.createElement("p");
  meta.textContent = [
    item.plannedDate ? formatCompactDate(item.plannedDate) : "Bez datuma",
    [item.timeFrom, item.timeTo].filter(Boolean).join("-"),
    getFieldInquiryStatusLabel(item.status),
  ].filter(Boolean).join(" · ");
  headCopy.append(kicker, title, meta);
  const closeButton = createActionButton("Zatvori", "ghost-button", closeDetail);
  head.append(headCopy, closeButton);

  const facts = document.createElement("div");
  facts.className = "field-inquiry-detail-facts";
  [
    ["Tvrtka", getFieldInquiryCompanyLabel(item) || "Bez tvrtke"],
    ["Lokacija", getFieldInquiryLocationLabel(item) || "Bez lokacije"],
    ["Usluga", item.serviceLine || ""],
    ["Ekipa", getFieldInquiryAssigneeLabels(item).join(", ")],
    ["Vozilo", getFieldInquiryVehicleLabel(item)],
    ["Kontakt", joinParts([item.contactName, item.contactPhone])],
    ["RN", getFieldInquiryWorkOrderLabel(item)],
  ].filter(([, value]) => String(value || "").trim()).forEach(([label, value]) => {
    const row = document.createElement("div");
    row.className = "field-inquiry-detail-fact";
    row.innerHTML = `<span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong>`;
    facts.append(row);
  });

  const body = document.createElement("div");
  body.className = "field-inquiry-detail-body";
  if (item.note) {
    const note = document.createElement("section");
    note.className = "field-inquiry-detail-section";
    note.innerHTML = `<h4>Opis dogovora</h4><p>${escapeHtml(item.note)}</p>`;
    body.append(note);
  }

  const documents = normalizeFieldInquiryDocuments(item.documents ?? []);
  const docs = document.createElement("section");
  docs.className = "field-inquiry-detail-section";
  const docsTitle = document.createElement("h4");
  docsTitle.textContent = "Dokumenti";
  const docsList = document.createElement("div");
  docsList.className = "field-inquiry-detail-documents";
  if (documents.length === 0) {
    const empty = document.createElement("p");
    empty.className = "field-inquiry-detail-empty";
    empty.textContent = "Nema dodanih dokumenata.";
    docsList.append(empty);
  } else {
    documents.forEach((documentItem) => {
      const row = document.createElement("div");
      row.className = "field-inquiry-detail-document";
      const copy = document.createElement("div");
      copy.innerHTML = `<strong>${escapeHtml(documentItem.fileName)}</strong><span>${escapeHtml([documentItem.fileType, documentItem.fileSize ? formatFileSize(documentItem.fileSize) : ""].filter(Boolean).join(" · "))}</span>`;
      const actions = document.createElement("div");
      const href = documentItem.storageUrl || documentItem.dataUrl;
      if (href) {
        const open = document.createElement("a");
        open.className = "ghost-button";
        open.href = href;
        open.target = "_blank";
        open.rel = "noopener";
        open.textContent = "Otvori";
        const download = document.createElement("a");
        download.className = "ghost-button";
        download.href = href;
        download.download = documentItem.fileName;
        download.textContent = "Preuzmi";
        actions.append(open, download);
      }
      row.append(copy, actions);
      docsList.append(row);
    });
  }
  docs.append(docsTitle, docsList);
  body.append(docs);

  const actions = document.createElement("footer");
  actions.className = "field-inquiry-detail-actions";
  actions.append(
    createActionButton("Uredi", "ghost-button", () => {
      closeDetail();
      hydrateFieldInquiryForm(item);
    }),
  );
  const convertButton = createActionButton("Otvori RN", "primary-button", () => {
    closeDetail();
    void convertFieldInquiryToWorkOrder(item.id);
  });
  convertButton.disabled = !item.companyId || String(item.status || "") === "converted";
  convertButton.title = item.companyId ? "" : "Za RN prvo odaberi tvrtku.";
  actions.append(convertButton);

  dialog.append(head, facts, body, actions);
  backdrop.append(dialog);
  backdrop.addEventListener("click", (event) => {
    if (event.target === backdrop) {
      closeDetail();
    }
  });
  document.body.append(backdrop);
}

function renderFieldInquiryCard(item = {}) {
  const card = document.createElement("article");
  card.className = "field-inquiry-card";
  card.classList.add(`is-${getFieldInquiryStatusOption(item.status).value}`);
  card.classList.toggle("is-active", String(item.id) === String(state.activeFieldInquiryId));

  const head = document.createElement("div");
  head.className = "field-inquiry-card-head";
  const copy = document.createElement("div");
  copy.className = "field-inquiry-card-copy";
  const title = document.createElement("strong");
  title.textContent = item.title || "Terenski upit";
  const meta = document.createElement("span");
  meta.textContent = [
    item.plannedDate ? formatCompactDate(item.plannedDate) : "Bez datuma",
    [item.timeFrom, item.timeTo].filter(Boolean).join("-"),
    getFieldInquiryCompanyLabel(item) || "Bez tvrtke",
  ].filter(Boolean).join(" · ");
  copy.append(title, meta);
  const status = document.createElement("span");
  status.className = "field-inquiry-status-pill";
  status.textContent = getFieldInquiryStatusLabel(item.status);
  head.append(copy, status);

  const details = document.createElement("div");
  details.className = "field-inquiry-card-details";
  [
    ["Lokacija", getFieldInquiryLocationLabel(item)],
    ["RN", getFieldInquiryWorkOrderLabel(item)],
    ["Ekipa", getFieldInquiryAssigneeLabels(item).join(", ")],
    ["Vozilo", getFieldInquiryVehicleLabel(item)],
    ["Kontakt", joinParts([item.contactName, item.contactPhone])],
    ["Usluga", item.serviceLine || ""],
    ["Dokumenti", normalizeFieldInquiryDocuments(item.documents ?? []).length > 0
      ? normalizeFieldInquiryDocuments(item.documents ?? []).map((document) => document.fileName).join(", ")
      : ""],
  ].filter(([, value]) => String(value || "").trim()).forEach(([label, value]) => {
    const row = document.createElement("span");
    row.innerHTML = `<small>${escapeHtml(label)}</small>${escapeHtml(value)}`;
    details.append(row);
  });

  if (item.note) {
    const note = document.createElement("p");
    note.className = "field-inquiry-card-note";
    note.textContent = item.note;
    details.append(note);
  }

  const actions = document.createElement("div");
  actions.className = "field-inquiry-card-actions";
  actions.append(createActionButton("Detalji", "ghost-button", () => openFieldInquiryDetail(item)));
  actions.append(createActionButton("Uredi", "ghost-button", () => hydrateFieldInquiryForm(item)));
  const convertButton = createActionButton("Otvori RN", "ghost-button", () => {
    void convertFieldInquiryToWorkOrder(item.id);
  });
  convertButton.disabled = !item.companyId || String(item.status || "") === "converted";
  convertButton.hidden = String(item.status || "") === "converted";
  convertButton.title = item.companyId ? "" : "Za RN treba odabrati tvrtku.";
  actions.append(convertButton);
  const deleteButton = createActionButton("Obriši", "ghost-button card-danger", () => {
    if (!window.confirm("Obrisati ovaj terenski upit?")) {
      return;
    }
    void deleteFieldInquiry(item.id);
  });
  actions.append(deleteButton);

  card.append(head, details, actions);
  card.addEventListener("click", (event) => {
    if (isInteractiveWorkOrderTarget(event.target)) {
      return;
    }
    openFieldInquiryDetail(item);
  });
  return card;
}

function getFieldInquiryPlanGroups(items = []) {
  const today = getTodayDateKey();
  const nextSeven = shiftDateKey(today, 7);
  const groups = [
    { key: "undated", title: "Bez datuma", description: "Upiti koje treba rasporediti.", items: [] },
    { key: "next_week", title: "Iduci tjedan", description: "Dogovori za planiranje terena.", items: [] },
    { key: "scheduled", title: "Zakazano", description: "Imaju datum ili termin.", items: [] },
    { key: "linked", title: "Povezano s RN", description: "Upiti koji vec imaju radni nalog.", items: [] },
    { key: "closed", title: "Zatvoreno", description: "Pretvoreno u RN ili odbijeno.", items: [] },
  ];
  const byKey = new Map(groups.map((group) => [group.key, group]));

  items.forEach((item) => {
    const status = getFieldInquiryStatusOption(item.status).value;
    if (status === "converted" || status === "rejected") {
      byKey.get("closed").items.push(item);
      return;
    }
    if (item.workOrderId || item.workOrderNumber) {
      byKey.get("linked").items.push(item);
      return;
    }
    const dateKey = normalizeDateInputValue(item.plannedDate || "");
    if (!dateKey) {
      byKey.get("undated").items.push(item);
      return;
    }
    if (status === "next_week" || (dateKey >= today && dateKey <= nextSeven)) {
      byKey.get("next_week").items.push(item);
      return;
    }
    byKey.get("scheduled").items.push(item);
  });

  return groups.filter((group) => group.items.length > 0);
}

function renderFieldInquiryPlanGroup(group = {}) {
  const section = document.createElement("section");
  section.className = `field-inquiry-group is-${group.key || "default"}`;

  const head = document.createElement("div");
  head.className = "field-inquiry-group-head";
  const copy = document.createElement("div");
  copy.className = "field-inquiry-group-copy";
  const title = document.createElement("strong");
  title.textContent = group.title || "Plan";
  const description = document.createElement("span");
  description.textContent = group.description || "";
  copy.append(title, description);
  const count = document.createElement("span");
  count.className = "field-inquiry-group-count";
  count.textContent = String(group.items?.length ?? 0);
  head.append(copy, count);

  const body = document.createElement("div");
  body.className = "field-inquiry-group-body";
  body.append(...(group.items ?? []).map(renderFieldInquiryCard));

  section.append(head, body);
  return section;
}

function renderFieldInquiriesView() {
  if (!fieldInquiriesView) {
    return;
  }

  rebuildFieldInquiryOptions({
    selectedCompanyId: fieldInquiryCompanyInput?.value || "",
    selectedLocationId: fieldInquiryLocationInput?.value || "",
    selectedWorkOrderId: fieldInquiryWorkOrderInput?.value || "",
    selectedVehicleId: fieldInquiryVehicleInput?.value || "",
    selectedAssigneeIds: getSelectedMultiSelectValues(fieldInquiryAssigneesInput),
  });

  if (!fieldInquiryIdInput?.value && !state.activeFieldInquiryId && fieldInquiryPlannedDateInput && !fieldInquiryPlannedDateInput.value) {
    fieldInquiryPlannedDateInput.value = formatDateInputDisplayValue(getTodayDateKey());
  }

  const items = getSortedFieldInquiries();
  if (fieldInquiryCount) {
    const nextSeven = shiftDateKey(getTodayDateKey(), 7);
    const weekCount = items.filter((item) => {
      const dateKey = normalizeDateInputValue(item.plannedDate || "");
      return dateKey && dateKey >= getTodayDateKey() && dateKey <= nextSeven;
    }).length;
    fieldInquiryCount.textContent = `${items.length} ukupno · ${weekCount} u idućih 7 dana`;
  }
  if (fieldInquiryList) {
    fieldInquiryList.replaceChildren(...getFieldInquiryPlanGroups(items).map(renderFieldInquiryPlanGroup));
  }
  if (fieldInquiryEmpty) {
    fieldInquiryEmpty.hidden = items.length > 0;
  }
}

async function saveFieldInquiry() {
  let payload;
  try {
    payload = buildFieldInquiryPayload();
  } catch (error) {
    setInlineMessage(fieldInquiryFeedback, error.message || "Upit nije ispravno popunjen.");
    return;
  }
  const inquiryId = String(fieldInquiryIdInput?.value || "").trim();
  const success = await runMutation(() => apiRequest(inquiryId
    ? `/field-inquiries/${encodeURIComponent(inquiryId)}`
    : "/field-inquiries", {
      method: inquiryId ? "PATCH" : "POST",
      body: payload,
    }), fieldInquiryFeedback);
  if (success) {
    resetFieldInquiryForm();
    renderWorkOrderWorkspace();
  }
}

async function convertFieldInquiryToWorkOrder(id = fieldInquiryIdInput?.value || "") {
  const inquiry = getFieldInquiryById(id);
  if (!inquiry) {
    setInlineMessage(fieldInquiryFeedback, "Odaberi upit koji želiš pretvoriti u RN.");
    return;
  }
  if (!inquiry.companyId) {
    setInlineMessage(fieldInquiryFeedback, "Za otvaranje RN-a prvo odaberi tvrtku u planu terena.");
    return;
  }

  const assigneeLabels = getFieldInquiryAssigneeLabels(inquiry);
  focusWorkOrderComposer({
    sourceFieldInquiryId: String(inquiry.id || ""),
    status: "Otvoreni RN",
    priority: "Normal",
    openedDate: getTodayDateKey(),
    dueDate: inquiry.plannedDate || "",
    executionDate: inquiry.plannedDate || "",
    companyId: inquiry.companyId || "",
    locationId: inquiry.locationId || "",
    serviceLine: inquiry.serviceLine || inquiry.title || "",
    serviceItems: buildFieldInquiryMatchedServiceItems(inquiry),
    executors: assigneeLabels,
    contactName: inquiry.contactName || "",
    contactPhone: inquiry.contactPhone || "",
    contactEmail: "",
    description: [inquiry.title, inquiry.note].filter(Boolean).join("\n\n"),
    linkReference: "Plan terena",
    tagText: "Plan terena",
  });
  setInlineMessage(workOrderError, "RN je popunjen iz plana terena. Provjeri podatke i stisni spremanje/otvaranje kada je sve u redu.");
}

async function deleteFieldInquiry(id = "") {
  const normalizedId = String(id || "").trim();
  if (!normalizedId) {
    return;
  }
  const success = await runMutation(() => apiRequest(`/field-inquiries/${encodeURIComponent(normalizedId)}`, {
    method: "DELETE",
  }), fieldInquiryFeedback);
  if (success) {
    resetFieldInquiryForm();
    renderWorkOrderWorkspace();
  }
}

function renderWorkOrderWorkspace() {
  ensureActiveWorkOrderViewMode();
  ensureWorkOrderColumnPanelSettingsLoaded();
  updateWorkOrderModeButtons();
  updateWorkOrderListDensityButtons();
  refreshWorkOrderTeamSuggestions();
  renderWorkOrderTemplateStrip();
  renderWorkOrderQuickFilters();
  renderWorkOrderQuickCreateSlot();
  renderWorkOrderFilterSummary();
  renderWorkOrderColumnPanel();
  renderWorkOrderPremiumSummary(state.workOrders ?? []);

  const filtered = getFilteredWorkOrders();
  const emptyTextByMode = {
    list: "Nema radnih naloga za trenutni filter.",
    calendar: "Nema radnih naloga za prikaz u kalendaru.",
    maps: "Nema radnih naloga za prikaz na karti.",
  };

  if (workOrderListView) {
    workOrderListView.hidden = state.activeWorkOrderViewMode !== "list";
  }

  if (workOrderCalendarView) {
    workOrderCalendarView.hidden = state.activeWorkOrderViewMode !== "calendar";
  }

  if (workOrderMapView) {
    workOrderMapView.hidden = state.activeWorkOrderViewMode !== "maps";
  }

  if (fieldInquiriesView) {
    fieldInquiriesView.hidden = true;
  }

  if (workOrdersEmpty) {
    const shouldShowEmpty = filtered.length === 0
      && state.activeWorkOrderViewMode !== "calendar";
    workOrdersEmpty.hidden = !shouldShowEmpty;
    workOrdersEmpty.textContent = emptyTextByMode[state.activeWorkOrderViewMode] || emptyTextByMode.list;
  }

  if (workOrdersLoadState) {
    workOrdersLoadState.hidden = state.activeWorkOrderViewMode !== "list";
  }

  updateWorkOrderDocumentSelectionChrome();

  if (state.activeWorkOrderViewMode === "list") {
    renderCompactWorkOrdersList();
  } else if (state.activeWorkOrderViewMode === "calendar") {
    renderWorkOrderCalendarView();
  } else {
    renderWorkOrderCroatiaMapView();
  }

  queueWorkOrderCalendarGridShellHeightSync();
}

function renderWorkOrders() {
  const filtered = getFilteredWorkOrders();
  const visibleItems = filtered.slice(0, state.workOrderRenderLimit);
  const fullGroups = buildWorkOrderGroups(filtered);
  const visibleGroups = buildWorkOrderGroups(visibleItems);

  if (workOrdersHelper) {
    workOrdersHelper.textContent = `${filtered.length} RN u list view prikazu.`;
  }

  workOrdersBody.replaceChildren(...visibleGroups.map((group) => {
    const section = document.createElement("section");
    section.className = "work-group";

    const groupHeader = document.createElement("div");
    groupHeader.className = "work-group-header";

    const headerLead = document.createElement("div");
    headerLead.className = "work-group-lead";

    const foldIcon = document.createElement("span");
    foldIcon.className = "work-group-fold";
    foldIcon.textContent = "▾";

    const statusBadge = createBadge(group.label, statusBadgeClass(group.status));
    statusBadge.classList.add("work-group-status-badge");

    const totalCount = fullGroups.find((entry) => entry.status === group.status)?.items.length ?? group.items.length;
    const count = document.createElement("span");
    count.className = "work-group-count";
    count.textContent = String(totalCount);

    headerLead.append(foldIcon, statusBadge, count);

    const groupActions = document.createElement("button");
    groupActions.type = "button";
    groupActions.className = "work-group-add-inline";
    groupActions.textContent = "+ Add task";
    groupActions.hidden = !getCanCreateWorkOrders();
    groupActions.addEventListener("click", () => {
      focusWorkOrderComposer({ status: group.status });
    });

    groupHeader.append(headerLead, groupActions);

    const columns = document.createElement("div");
    columns.className = "work-group-columns";
    ["Name", "Regija", "Lokacija", "Due date", "Priority", "Kontakt", "Actions"].forEach((label) => {
      const cell = document.createElement("div");
      cell.className = "work-group-column";
      cell.textContent = label;
      columns.append(cell);
    });

    const body = document.createElement("div");
    body.className = "work-group-body";

    group.items.forEach((item) => {
      const overdue = isOverdueWorkOrder(item);
      const row = document.createElement("article");
      row.className = "work-item-row";

      const title = document.createElement("div");
      title.className = "work-item-cell work-item-cell-name";
      const titleCheck = document.createElement("span");
      titleCheck.className = "work-item-check";
      titleCheck.textContent = "✓";
      const titleCopy = document.createElement("div");
      titleCopy.className = "work-item-copy";
      const titlePrimary = document.createElement("strong");
      titlePrimary.textContent = `${item.workOrderNumber} ${item.description || item.locationName || item.companyName || "Radni nalog"}`;
      const titleSecondary = document.createElement("span");
      titleSecondary.textContent = joinParts([
        item.department,
        item.serviceLine,
        item.tagText ? `#${item.tagText}` : "",
      ]) || "Bez dodatnog opisa";
      titleCopy.append(titlePrimary, titleSecondary);
      title.append(titleCheck, titleCopy);

      const region = document.createElement("div");
      region.className = "work-item-cell";
      const regionPill = document.createElement("span");
      regionPill.className = "work-field-pill";
      regionPill.textContent = item.region || "Bez regije";
      region.append(regionPill);

      const location = document.createElement("div");
      location.className = "work-item-cell";
      const locationPrimary = document.createElement("strong");
      locationPrimary.textContent = item.locationName || "Bez lokacije";
      const locationSecondary = document.createElement("span");
      locationSecondary.textContent = item.companyName || "Bez tvrtke";
      location.append(locationPrimary, locationSecondary);

      const due = document.createElement("div");
      due.className = "work-item-cell";
      const duePrimary = document.createElement("strong");
      duePrimary.textContent = item.dueDate ? formatDate(item.dueDate) : "Bez roka";
      const dueSecondary = document.createElement("span");
      dueSecondary.textContent = overdue
        ? "Kasni"
        : (item.openedDate ? `Otvoren ${formatDate(item.openedDate)}` : "Bez datuma");
      if (overdue) {
        due.classList.add("is-overdue");
      }
      due.append(duePrimary, dueSecondary);

      const priority = document.createElement("div");
      priority.className = "work-item-cell";
      const priorityBadge = createBadge(getOptionLabel(PRIORITY_OPTIONS, item.priority), priorityBadgeClass(item.priority));
      priorityBadge.classList.add("work-priority-badge");
      priority.append(priorityBadge);

      const contact = document.createElement("div");
      contact.className = "work-item-cell";
      const contactPrimary = document.createElement("strong");
      contactPrimary.textContent = item.contactName || item.contactPhone || "Bez kontakta";
      const contactSecondary = document.createElement("span");
      contactSecondary.textContent = joinParts([item.contactPhone, item.contactEmail]) || "Nema broja ni emaila";
      contact.append(contactPrimary, contactSecondary);

      const actions = document.createElement("div");
      actions.className = "work-item-cell work-item-actions";
      actions.append(
        createActionButton("Uredi", "card-button card-button-light", () => hydrateWorkOrderForm(item)),
      );

      if (state.user?.role !== "user") {
        actions.append(
          createActionButton("Obriši", "card-button card-button-light card-danger", () => {
            if (!window.confirm(`Obrisati ${item.workOrderNumber}?`)) {
              return;
            }

            void runMutation(() => apiRequest(`/work-orders/${item.id}`, { method: "DELETE" }));
          }),
        );
      }

      row.append(title, region, location, due, priority, contact, actions);
      body.append(row);
    });

    const addRow = document.createElement("button");
    addRow.type = "button";
    addRow.className = "work-group-add-row";
    addRow.textContent = "+ Add task";
    addRow.hidden = !getCanCreateWorkOrders();
    addRow.addEventListener("click", () => {
      focusWorkOrderComposer({ status: group.status });
    });

    section.append(groupHeader, columns, body, addRow);
    return section;
  }));

  workOrdersEmpty.hidden = filtered.length !== 0;

  if (filtered.length === 0) {
    workOrdersLoadState.hidden = true;
    workOrdersLoadState.textContent = "";
    return;
  }

  workOrdersLoadState.hidden = false;
  workOrdersLoadState.textContent = visibleItems.length < filtered.length
    ? `Prikazano ${visibleItems.length} od ${filtered.length} RN. Skrolaj dalje za još.`
    : `Prikazano svih ${filtered.length} RN.`;
}

function looksLikeWorkOrderLog(text) {
  const normalized = String(text ?? "").trim();
  return /^\[\d{2}\.\d{2}\.\d{4}\s+\d{2}:\d{2}:\d{2}\]\s*-\s*.+?:/u.test(normalized);
}

function getWorkOrderDetailLines(item) {
  const lines = [];
  const normalizedDescription = String(item.description ?? "").trim();

  if (normalizedDescription) {
    lines.push({
      label: looksLikeWorkOrderLog(normalizedDescription) ? "Dnevnik" : "Opis",
      value: normalizedDescription,
      isLog: looksLikeWorkOrderLog(normalizedDescription),
    });
  }

  if (item.linkReference) {
    lines.push({ label: "Poveznica", value: item.linkReference });
  }

  if (item.completedBy) {
    lines.push({ label: "Zavrsio", value: item.completedBy });
  }

  return lines;
}

function updateWorkOrderStatusSelectTheme(select, value) {
  select.dataset.status = slugifyValue(value);
}

function createWorkOrderStatusSelect(item, options = {}) {
  const { className = "" } = options;
  const select = document.createElement("select");
  select.className = ["work-item-status-select", className].filter(Boolean).join(" ");
  select.dataset.preventRowOpen = "true";

  WORK_ORDER_STATUS_OPTIONS.forEach((option) => {
    const node = document.createElement("option");
    node.value = option.value;
    node.textContent = option.label;
    select.append(node);
  });

  select.value = item.status || "Otvoreni RN";
  updateWorkOrderStatusSelectTheme(select, select.value);

  bindWorkOrderInlineSelect(select, () => {
    const previousValue = item.status || "Otvoreni RN";
    const nextValue = select.value;

    updateWorkOrderStatusSelectTheme(select, nextValue);
    select.disabled = true;

    void runMutation(() => apiRequest(`/work-orders/${item.id}`, {
      method: "PATCH",
      body: { status: nextValue },
    })).then((success) => {
      const updatedItem = state.workOrders.find((entry) => String(entry.id) === String(item.id));

      if (!success) {
        select.value = previousValue;
        updateWorkOrderStatusSelectTheme(select, previousValue);
      } else {
        select.value = updatedItem?.status || nextValue;
        updateWorkOrderStatusSelectTheme(select, select.value);
      }

      if (select.isConnected) {
        select.disabled = false;
      }
    });
  });

  return select;
}

function normalizeWorkOrderClientReference(value) {
  const normalized = String(value ?? "").trim();

  if (!normalized) {
    return "";
  }

  return normalized
    .replace(/^\s*veza(?:\s*rn)?\s*[:\-]?\s*/iu, "")
    .trim();
}

function getWorkOrderClientPills(item) {
  const rawValue = normalizeWorkOrderClientReference(item.linkReference);

  if (!rawValue) {
    return [];
  }

  return Array.from(new Set(
    rawValue
      .split(/[|,;/]+/u)
      .map((entry) => entry.trim())
      .filter(Boolean),
  ));
}

function isInteractiveWorkOrderTarget(target) {
  if (!(target instanceof Element)) {
    return false;
  }

  return Boolean(target.closest(
    "select, button, input, textarea, a, [data-prevent-row-open='true'], [role='menuitem']",
  ));
}

function normalizeWorkOrderDocumentWizardStep(step = "") {
  return step === "templates" ? "templates" : "details";
}

function pruneWorkOrderDocumentWizardState() {
  const existingIds = new Set((state.workOrders ?? []).map((item) => String(item.id)));
  state.workOrderDocumentWizard.selectedIds = new Set(
    [...(state.workOrderDocumentWizard.selectedIds ?? [])].filter((id) => existingIds.has(String(id))),
  );
  state.workOrderDocumentWizard.overrides = Object.fromEntries(
    Object.entries(state.workOrderDocumentWizard.overrides ?? {}).filter(([id]) => existingIds.has(String(id))),
  );

  if (state.workOrderDocumentWizard.selectedIds.size === 0) {
    state.workOrderDocumentWizard.step = "details";
    state.workOrderDocumentWizard.open = false;
  }
}

function getSelectedWorkOrdersForDocumentWizard() {
  const selectedIds = state.workOrderDocumentWizard.selectedIds ?? new Set();
  const selectedIdSet = new Set([...selectedIds].map((value) => String(value)));
  return getFilteredWorkOrders().filter((item) => selectedIdSet.has(String(item.id)));
}

function buildActiveWorkOrderDocumentWizardFallback(workOrderId = "") {
  const normalizedId = String(workOrderId || workOrderIdInput?.value || "").trim();
  if (!normalizedId || String(workOrderIdInput?.value || "").trim() !== normalizedId) {
    return null;
  }

  const payload = buildWorkOrderPayload();
  const company = getCompany(payload.companyId) ?? {};
  const location = getLocation(payload.locationId) ?? {};
  const previewNumber = String(workOrderNumberPreview?.textContent || "").replace(/^RN\s+/i, "").trim();
  return {
    ...payload,
    id: normalizedId,
    workOrderNumber: previewNumber && !/^broj rn/i.test(previewNumber) ? previewNumber : "",
    companyName: company.name || payload.companyName || "",
    companyOib: company.oib || payload.companyOib || "",
    locationName: location.name || payload.locationName || "",
    locationAddress: location.address || payload.locationAddress || "",
  };
}

function getAllSelectedWorkOrdersForDocumentWizard() {
  const selectedIds = state.workOrderDocumentWizard.selectedIds ?? new Set();
  const selectedIdSet = new Set([...selectedIds].map((value) => String(value)));
  const selectedWorkOrders = (state.workOrders ?? []).filter((item) => selectedIdSet.has(String(item.id)));
  if (state.workOrderDocumentWizard.launchSource === "editor") {
    [...selectedIdSet].forEach((selectedId) => {
      if (!selectedWorkOrders.some((item) => String(item.id) === selectedId)) {
        const fallback = buildActiveWorkOrderDocumentWizardFallback(selectedId);
        if (fallback) {
          selectedWorkOrders.push(fallback);
        }
      }
    });
  }
  return sortWorkOrders(selectedWorkOrders);
}

function formatWorkOrderSelectionCountLabel(count = 0) {
  if (count === 1) {
    return "1 RN odabran";
  }

  return `${count} RN odabrana`;
}

function getSharedWorkOrderBatchValue(items = [], resolver = (value) => value) {
  if (!Array.isArray(items) || items.length === 0) {
    return {
      value: "",
      mixed: false,
    };
  }

  const values = items.map((item) => String(resolver(item) ?? "").trim());
  const firstValue = values[0];
  const mixed = values.some((value) => value !== firstValue);

  return {
    value: mixed ? "" : firstValue,
    mixed,
  };
}

function getSharedWorkOrderBatchExecutors(items = []) {
  if (!Array.isArray(items) || items.length === 0) {
    return {
      values: [],
      mixed: false,
    };
  }

  const executorSets = items.map((item) => normalizeWorkOrderExecutorValues(getWorkOrderExecutors(item)));
  const firstKey = executorSets[0].join("||");
  const mixed = executorSets.some((values) => values.join("||") !== firstKey);

  return {
    values: mixed ? [] : executorSets[0],
    mixed,
  };
}

async function applyWorkOrderBatchUpdate(bodyOrBuilder, { successMessage = "" } = {}) {
  const selectedWorkOrders = getAllSelectedWorkOrdersForDocumentWizard();

  if (selectedWorkOrders.length === 0) {
    return false;
  }

  state.workOrderBatch.pending = true;
  state.workOrderBatch.message = "Spremam promjene...";
  state.workOrderBatch.tone = "pending";
  renderWorkOrderBatchBar();

  try {
    let hasChanges = false;

    for (const workOrder of selectedWorkOrders) {
      const body = typeof bodyOrBuilder === "function"
        ? bodyOrBuilder(workOrder)
        : bodyOrBuilder;

      if (!body || Object.keys(body).length === 0) {
        continue;
      }

      hasChanges = true;
      await apiRequest(`/work-orders/${workOrder.id}`, {
        method: "PATCH",
        body,
      });
    }

    if (hasChanges) {
      await refreshSnapshot();
    }

    state.workOrderBatch.message = successMessage || `Ažurirano ${formatWorkOrderSelectionCountLabel(selectedWorkOrders.length).toLowerCase()}.`;
    state.workOrderBatch.tone = "success";
    if (state.workOrderDocumentWizard.open) {
      renderWorkOrderDocumentWizard();
      syncWorkOrderDocumentWizardModal();
    }
    return true;
  } catch (error) {
    if (error.statusCode === 401) {
      state.user = null;
      renderAuthState();
      setSyncError("");
      return false;
    }

    state.workOrderBatch.message = error.message || "Batch promjena nije uspjela.";
    state.workOrderBatch.tone = "error";
    setSyncError(error.message || "Batch promjena nije uspjela.");
    if (state.workOrderDocumentWizard.open) {
      renderWorkOrderDocumentWizard();
      syncWorkOrderDocumentWizardModal();
    }
    return false;
  } finally {
    state.workOrderBatch.pending = false;
    renderWorkOrderBatchBar();
    if (state.workOrderDocumentWizard.open) {
      renderWorkOrderDocumentWizard();
      syncWorkOrderDocumentWizardModal();
    }
  }
}

function closeWorkOrderRowMenu() {
  const menuElement = state.workOrderRowMenu?.element;
  if (menuElement instanceof HTMLElement) {
    menuElement.remove();
  }
  state.workOrderRowMenu = null;
}

function getWorkOrderRowMenuTargets(workOrder = {}) {
  const selectedWorkOrders = getAllSelectedWorkOrdersForDocumentWizard();
  if (selectedWorkOrders.length > 0) {
    return selectedWorkOrders;
  }
  return workOrder?.id ? [workOrder] : [];
}

function getWorkOrderSharedValue(items = [], resolver = (item) => item) {
  const shared = getSharedWorkOrderBatchValue(items, resolver);
  return {
    value: shared.value,
    mixed: shared.mixed,
  };
}

function splitWorkOrderCompletedByValue(value = "") {
  return String(value || "")
    .split(/[,;\n]+/)
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function getWorkOrderFinishedInspectorAreas(targets = []) {
  const areas = new Set();
  (Array.isArray(targets) ? targets : []).forEach((workOrder) => {
    getWorkOrderRelevantSignatureAreas(workOrder).forEach((area) => {
      areas.add(normalizeQualificationAreaKey(area));
    });
  });
  return areas.size > 0 ? [...areas] : ["elektro"];
}

function getWorkOrderFinishedInspectorState(targets = []) {
  const shared = getWorkOrderSharedValue(targets, (item) => item.completedBy);
  return {
    mixed: shared.mixed,
    labels: shared.mixed ? [] : splitWorkOrderCompletedByValue(shared.value),
  };
}

function getWorkOrderFinishedInspectorOptions(targets = [], currentLabels = []) {
  const byLabel = new Map();

  (Array.isArray(targets) ? targets : []).forEach((workOrder) => {
    getWorkOrderExecutors(workOrder).forEach((executor) => {
      const label = String(executor || "").trim();
      const key = normalizePersonLookupValue(label);
      if (!key || byLabel.has(key)) {
        return;
      }
      const user = findUserForExecutor(label);
      byLabel.set(key, {
        value: `executor:${key}`,
        label,
        user,
        summary: workOrder.workOrderNumber
          ? `Izvršitelj na RN ${workOrder.workOrderNumber}`
          : "Izvršitelj RN-a",
      });
    });
  });

  const options = [...byLabel.values()]
    .sort((left, right) => left.label.localeCompare(right.label, "hr"));

  currentLabels.forEach((label) => {
    const normalizedLabel = normalizePersonLookupValue(label);
    const hasMatch = options.some((option) => (
      normalizePersonLookupValue(option.label) === normalizedLabel
      || normalizePersonLookupValue(option.user?.email || "") === normalizedLabel
    ));
    if (hasMatch) {
      return;
    }
    options.push({
      value: `label:${label}`,
      label,
      user: null,
      summary: "Već upisano u RN",
      isSnapshot: true,
    });
  });

  return options;
}

function getWorkOrderFinishedInspectorValuesFromLabels(labels = [], options = []) {
  const values = [];
  splitWorkOrderCompletedByValue(labels.join(",")).forEach((label) => {
    const normalizedLabel = normalizePersonLookupValue(label);
    const match = options.find((option) => (
      normalizePersonLookupValue(option.label) === normalizedLabel
      || normalizePersonLookupValue(option.user?.email || "") === normalizedLabel
    ));
    if (match?.value) {
      values.push(match.value);
    }
  });
  return Array.from(new Set(values));
}

function getWorkOrderFinishedInspectorNames(values = [], options = []) {
  const byValue = new Map(options.map((option) => [String(option.value), option]));
  return Array.from(new Set(
    (Array.isArray(values) ? values : [])
      .map((value) => byValue.get(String(value))?.label || "")
      .map((label) => String(label || "").trim())
      .filter(Boolean),
  ));
}

function getDefaultWorkOrderFinishedInspectorValues(options = []) {
  const currentUserId = String(state.user?.id || "").trim();
  if (currentUserId) {
    const currentUserOption = options.find((option) => option.value === `user:${currentUserId}`);
    if (currentUserOption) {
      return [currentUserOption.value];
    }
  }

  return options[0]?.value ? [options[0].value] : [];
}

function matchesWorkOrderFinishedInspectorOption(option = {}, query = "") {
  const normalizedQuery = normalizeLooseName(query);
  if (!normalizedQuery) {
    return true;
  }

  return normalizeLooseName([
    option.label,
    option.summary,
    option.user?.email,
    option.user?.legacyUsername,
  ].filter(Boolean).join(" ")).includes(normalizedQuery);
}

function createWorkOrderFinishedInspectorPicker({
  options = [],
  selectedValues = [],
  mixed = false,
  onChange = null,
} = {}) {
  const wrapper = document.createElement("div");
  wrapper.className = "work-order-calendar-executor-picker work-order-row-inspector-picker";
  wrapper.dataset.preventRowOpen = "true";

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "work-order-calendar-executor-trigger work-order-row-inspector-trigger";
  trigger.dataset.preventRowOpen = "true";
  trigger.setAttribute("aria-haspopup", "dialog");
  trigger.setAttribute("aria-expanded", "false");

  let draftValues = Array.from(new Set((Array.isArray(selectedValues) ? selectedValues : []).map((value) => String(value || "").trim()).filter(Boolean)));
  let mixedSelection = Boolean(mixed);

  const renderTrigger = () => {
    const names = getWorkOrderFinishedInspectorNames(draftValues, options);
    trigger.replaceChildren();
    trigger.title = mixedSelection && names.length === 0
      ? "Različiti izvršitelji"
      : names.length > 0
        ? names.join(", ")
        : "Odaberi izvršitelje";
    trigger.setAttribute("aria-label", trigger.title);

    const icon = createWorkOrderActionIcon("assignees");
    icon.classList.add("work-order-bulk-action-icon");
    trigger.append(icon);

    if (names.length > 0) {
      const stack = document.createElement("span");
      stack.className = "work-order-bulk-executor-stack work-order-row-inspector-stack";
      draftValues.slice(0, 3).forEach((value) => {
        const option = options.find((entry) => entry.value === value);
        const avatar = createWorkOrderMiniExecutor({
          label: option?.label || value,
          user: option?.user || null,
        }, {
          className: "work-order-mini-executor work-order-bulk-executor-avatar work-order-row-inspector-avatar",
        });
        avatar.removeAttribute("title");
        stack.append(avatar);
      });
      if (draftValues.length > 3) {
        stack.append(createExecutorOverflowBadge(
          draftValues.length - 3,
          "work-order-mini-executor work-order-bulk-executor-avatar work-order-row-inspector-avatar",
        ));
      }
      trigger.append(stack);
    }

    const label = document.createElement("span");
    label.className = "work-order-bulk-action-label work-order-row-inspector-trigger-label";
    label.textContent = mixedSelection && names.length === 0
      ? "Različiti izvršitelji"
      : names.length === 0
        ? "Odaberi izvršitelje"
        : names.length === 1
          ? names[0]
          : `${names.length} izvršitelja`;
    trigger.append(label);
  };

  const positionMenuPortal = (menu) => {
    const triggerRect = trigger.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let left = triggerRect.left;
    let top = triggerRect.bottom + 10;
    if (left + menuRect.width > viewportWidth - 12) {
      left = Math.max(12, viewportWidth - menuRect.width - 12);
    }
    if (top + menuRect.height > viewportHeight - 12) {
      top = Math.max(12, triggerRect.top - menuRect.height - 10);
    }

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.minWidth = `${Math.max(340, Math.round(triggerRect.width + 80))}px`;
  };

  const closeMenu = () => {
    wrapper.classList.remove("is-open");
    trigger.setAttribute("aria-expanded", "false");
    if (wrapper._menuPortal) {
      wrapper._menuPortal.remove();
      wrapper._menuPortal = null;
    }
  };

  wrapper._closeMenu = closeMenu;
  wrapper._setSelectedValues = (nextValues = [], { mixed: nextMixed = false } = {}) => {
    draftValues = Array.from(new Set((Array.isArray(nextValues) ? nextValues : []).map((value) => String(value || "").trim()).filter(Boolean)));
    mixedSelection = Boolean(nextMixed);
    renderTrigger();
  };

  const openMenu = () => {
    closeOpenWorkOrderStatusMenus(wrapper);
    if (wrapper._menuPortal) {
      return;
    }

    let searchQuery = "";
    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal work-order-calendar-executor-menu-portal work-order-row-inspector-menu-portal";
    menu.setAttribute("role", "dialog");
    menu.setAttribute("aria-label", "Odabir izvršitelja za RN završio");

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => {
        event.stopPropagation();
      });
    });

    const searchWrap = document.createElement("div");
    searchWrap.className = "work-order-calendar-executor-search";
    const searchInput = document.createElement("input");
    searchInput.type = "search";
    searchInput.className = "work-order-calendar-executor-search-input";
    searchInput.placeholder = "Traži izvršitelja";
    searchInput.autocomplete = "off";
    searchInput.spellcheck = false;
    searchWrap.append(searchInput);

    const selection = document.createElement("div");
    selection.className = "work-order-calendar-executor-selection work-order-row-inspector-selection";
    const helper = document.createElement("p");
    helper.className = "work-order-calendar-executor-helper";
    const optionsList = document.createElement("div");
    optionsList.className = "work-order-calendar-executor-options";
    const clearButton = document.createElement("button");
    clearButton.type = "button";
    clearButton.className = "ghost-button work-order-calendar-executor-clear";
    clearButton.textContent = "Očisti";

    const emitChange = () => {
      mixedSelection = false;
      renderTrigger();
      onChange?.([...draftValues]);
    };

    const toggleValue = (value) => {
      const normalizedValue = String(value || "").trim();
      if (!normalizedValue) {
        return;
      }
      draftValues = draftValues.includes(normalizedValue)
        ? draftValues.filter((entry) => entry !== normalizedValue)
        : [...draftValues, normalizedValue];
      emitChange();
      syncMenuState();
    };

    const renderSelection = () => {
      selection.replaceChildren();
      const names = getWorkOrderFinishedInspectorNames(draftValues, options);
      if (mixedSelection && names.length === 0) {
        const empty = document.createElement("span");
        empty.className = "work-order-calendar-executor-selection-empty";
        empty.textContent = "Odaberi novi set izvršitelja za sve odabrane RN-ove.";
        selection.append(empty);
        return;
      }
      if (names.length === 0) {
        const empty = document.createElement("span");
        empty.className = "work-order-calendar-executor-selection-empty";
        empty.textContent = "Nema odabranih izvršitelja.";
        selection.append(empty);
        return;
      }
      draftValues.forEach((value) => {
        const option = options.find((entry) => entry.value === value);
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "work-order-calendar-executor-chip";
        chip.title = `Makni ${option?.label || value}`;
        const avatar = createWorkOrderMiniExecutor({ label: option?.label || value, user: option?.user || null });
        avatar.removeAttribute("title");
        const text = document.createElement("span");
        text.className = "work-order-calendar-executor-chip-label";
        text.textContent = option?.label || value;
        const remove = document.createElement("span");
        remove.className = "work-order-calendar-executor-chip-remove";
        remove.setAttribute("aria-hidden", "true");
        remove.textContent = "x";
        chip.append(avatar, text, remove);
        chip.addEventListener("click", (event) => {
          event.stopPropagation();
          toggleValue(value);
        });
        selection.append(chip);
      });
    };

    const renderOptions = () => {
      optionsList.replaceChildren();
      const visibleOptions = options.filter((option) => matchesWorkOrderFinishedInspectorOption(option, searchQuery));
      if (!visibleOptions.length) {
        const empty = document.createElement("p");
        empty.className = "work-order-calendar-executor-empty";
        empty.textContent = "Nema izvršitelja za ovaj pojam.";
        optionsList.append(empty);
        return;
      }
      visibleOptions.forEach((option) => {
        const isSelected = draftValues.includes(option.value);
        const optionButton = document.createElement("button");
        optionButton.type = "button";
        optionButton.className = "work-item-status-option work-order-calendar-executor-option work-order-row-inspector-option";
        optionButton.classList.toggle("is-selected", isSelected);
        optionButton.setAttribute("role", "menuitemcheckbox");
        optionButton.setAttribute("aria-checked", String(isSelected));
        const avatar = createWorkOrderMiniExecutor({ label: option.label, user: option.user }, {
          className: "work-order-calendar-executor-option-avatar work-order-row-inspector-option-avatar",
        });
        const copy = document.createElement("div");
        copy.className = "work-order-document-person-option-copy";
        const label = document.createElement("span");
        label.className = "work-order-calendar-executor-option-label";
        label.textContent = option.label;
        const meta = document.createElement("small");
        meta.className = "work-order-document-person-option-meta";
        meta.textContent = option.summary;
        copy.append(label, meta);
        const marker = document.createElement("span");
        marker.className = "work-order-calendar-executor-option-marker";
        marker.setAttribute("aria-hidden", "true");
        marker.textContent = isSelected ? "✓" : "+";
        optionButton.append(avatar, copy, marker);
        optionButton.addEventListener("click", (event) => {
          event.stopPropagation();
          toggleValue(option.value);
        });
        optionsList.append(optionButton);
      });
    };

    const syncMenuState = () => {
      renderSelection();
      renderOptions();
      helper.textContent = draftValues.length > 0
        ? `${draftValues.length} odabranih izvršitelja.`
        : "Odaberi jednog ili više izvršitelja za završetak RN-a.";
      clearButton.hidden = draftValues.length === 0 && !mixedSelection;
      requestAnimationFrame(() => positionMenuPortal(menu));
    };

    searchInput.addEventListener("input", () => {
      searchQuery = searchInput.value.trim();
      renderOptions();
      requestAnimationFrame(() => positionMenuPortal(menu));
    });
    searchInput.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        closeMenu();
        trigger.focus({ preventScroll: true });
        return;
      }
      if (event.key !== "Enter") {
        return;
      }
      const visibleOptions = options.filter((option) => matchesWorkOrderFinishedInspectorOption(option, searchQuery));
      if (visibleOptions.length === 1) {
        event.preventDefault();
        toggleValue(visibleOptions[0].value);
      }
    });
    clearButton.addEventListener("click", (event) => {
      event.stopPropagation();
      draftValues = [];
      emitChange();
      syncMenuState();
    });

    menu.append(searchWrap, selection, helper, optionsList, clearButton);
    syncMenuState();
    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    positionMenuPortal(menu);
    requestAnimationFrame(() => {
      positionMenuPortal(menu);
      searchInput.focus({ preventScroll: true });
      searchInput.select();
    });
  };

  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    wrapper.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });
  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (wrapper.classList.contains("is-open")) {
      closeOpenWorkOrderStatusMenus();
      return;
    }
    openMenu();
  });

  renderTrigger();
  wrapper.append(trigger);
  return wrapper;
}

function getWorkOrderFinishedPatch(workOrder = {}, finished = false, completedByNames = []) {
  if (finished) {
    const names = Array.isArray(completedByNames)
      ? completedByNames.map((name) => String(name || "").trim()).filter(Boolean)
      : splitWorkOrderCompletedByValue(completedByNames);
    return {
      completedBy: names.length > 0 ? names.join(", ") : getUserDocumentDisplayName(state.user),
      status: isClosedWorkOrder(workOrder.status) ? workOrder.status : "Gotov RN",
    };
  }

  return {
    completedBy: "",
    status: String(workOrder.status || "") === "Gotov RN" ? "Otvoreni RN" : workOrder.status,
  };
}

async function applyWorkOrderRowMenuUpdate(targets = [], bodyBuilder = () => ({})) {
  const workOrders = targets.filter((item) => item?.id);
  if (!workOrders.length) {
    return false;
  }

  state.workOrderBatch.pending = true;
  state.workOrderBatch.message = `Ažuriram ${formatWorkOrderSelectionCountLabel(workOrders.length).toLowerCase()}...`;
  state.workOrderBatch.tone = "pending";
  renderWorkOrderBatchBar();

  try {
    const updates = [];
    for (const workOrder of workOrders) {
      const body = bodyBuilder(workOrder);
      if (!body || Object.keys(body).length === 0) {
        continue;
      }
      updates.push({
        id: String(workOrder.id),
        patch: body,
      });
    }

    const hasChanges = updates.length > 0;
    if (hasChanges) {
      const payload = await apiRequest("/work-orders/batch-update", {
        method: "POST",
        body: { updates },
      });
      if (payload && typeof payload === "object" && Object.prototype.hasOwnProperty.call(payload, "storage")) {
        applySnapshot(payload);
      } else {
        await refreshSnapshot();
      }
    }

    state.workOrderBatch.message = hasChanges
      ? `Ažurirano ${formatWorkOrderSelectionCountLabel(workOrders.length).toLowerCase()}.`
      : "Nema promjena za spremanje.";
    state.workOrderBatch.tone = hasChanges ? "success" : "";
    closeWorkOrderRowMenu();
    return true;
  } catch (error) {
    if (error.statusCode === 401) {
      state.user = null;
      renderAuthState();
      setSyncError("");
      return false;
    }

    state.workOrderBatch.message = error.message || "Brza promjena RN-a nije uspjela.";
    state.workOrderBatch.tone = "error";
    setSyncError(error.message || "Brza promjena RN-a nije uspjela.");
    return false;
  } finally {
    state.workOrderBatch.pending = false;
    renderWorkOrderBatchBar();
  }
}

function openWorkOrderRowMenu(workOrder = {}, pointerX = 0, pointerY = 0) {
  const targets = getWorkOrderRowMenuTargets(workOrder);
  if (!targets.length) {
    return;
  }

  closeOpenWorkOrderStatusMenus();
  closeWorkOrderRowMenu();

  const invoiceDate = getWorkOrderSharedValue(targets, (item) => item.invoiceDate);
  const invoiceNote = getWorkOrderSharedValue(targets, (item) => item.invoiceNote);
  const amount = getWorkOrderSharedValue(targets, (item) => item.weight);
  const finishedValues = targets.map((item) => Boolean(item.completedBy || String(item.status || "") === "Gotov RN"));
  const finishedMixed = finishedValues.some((value) => value !== finishedValues[0]);
  const inspectorState = getWorkOrderFinishedInspectorState(targets);
  const inspectorOptions = getWorkOrderFinishedInspectorOptions(targets, inspectorState.labels);
  let inspectorValues = getWorkOrderFinishedInspectorValuesFromLabels(inspectorState.labels, inspectorOptions);
  let inspectorsDirty = false;

  const menu = document.createElement("form");
  menu.className = "work-order-row-context-menu";
  menu.setAttribute("role", "menu");
  menu.dataset.preventRowOpen = "true";

  const header = document.createElement("div");
  header.className = "work-order-row-context-head";
  const title = document.createElement("strong");
  title.textContent = "Akcije RN-a";
  const subtitle = document.createElement("span");
  subtitle.textContent = targets.length > 1
    ? `Primjenjuje se na ${targets.length} odabrana RN-a`
    : `RN ${workOrder.workOrderNumber || ""}`.trim();
  header.append(title, subtitle);

  const shortcuts = document.createElement("div");
  shortcuts.className = "work-order-row-context-shortcuts";
  const createShortcutButton = (label, onClick, options = {}) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "work-order-row-context-shortcut";
    button.textContent = label;
    button.disabled = Boolean(options.disabled);
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (button.disabled) {
        return;
      }
      onClick?.();
    });
    return button;
  };
  shortcuts.append(
    createShortcutButton("Otvori RN", () => {
      closeWorkOrderRowMenu();
      hydrateWorkOrderForm(workOrder);
    }),
    createShortcutButton("Uredi", () => {
      closeWorkOrderRowMenu();
      hydrateWorkOrderForm(workOrder);
    }),
    createShortcutButton("Promijeni status", () => {
      closeWorkOrderRowMenu();
      hydrateWorkOrderForm(workOrder);
      workOrderStatusInput?.focus?.({ preventScroll: true });
    }),
    createShortcutButton("Dodijeli izvršitelja", () => {
      closeWorkOrderRowMenu();
      hydrateWorkOrderForm(workOrder);
      workOrderExecutorsPicker?.scrollIntoView?.({ block: "center", behavior: "smooth" });
    }),
    createShortcutButton("Prilozi", () => {
      closeWorkOrderRowMenu();
      hydrateWorkOrderForm(workOrder);
      document.querySelector("[data-work-order-section='documents']")?.scrollIntoView?.({ block: "start", behavior: "smooth" });
    }),
    createShortcutButton("Otvori PDF", () => {
      void downloadVerifiedWorkOrderDocument(workOrder);
    }),
    createShortcutButton("Izradi dokumentaciju", () => {
      closeWorkOrderRowMenu();
      clearWorkOrderDocumentSelection({ closeWizard: false });
      state.workOrderDocumentWizard.launchSource = "editor";
      state.workOrderDocumentWizard.selectedIds = new Set([String(workOrder.id || "")].filter(Boolean));
      openWorkOrderDocumentWizard(getWorkOrderSelectionModeFromWorkOrders([workOrder]), { launchSource: "editor" });
    }),
    createShortcutButton("Export PDF", () => {
      void downloadWorkOrderPdf(workOrder);
    }),
    createShortcutButton("Povijest", () => {
      closeWorkOrderRowMenu();
      hydrateWorkOrderForm(workOrder);
      workOrderActivityPanel?.scrollIntoView?.({ block: "center", behavior: "smooth" });
    }),
  );

  const createTextField = (labelText, value = "", placeholder = "", options = {}) => {
    const label = document.createElement("label");
    label.className = "work-order-row-context-field";
    if (options.datePicker) {
      label.classList.add("has-date-picker");
    }
    const labelNode = document.createElement("span");
    labelNode.textContent = labelText;
    const input = document.createElement("input");
    input.type = "text";
    if (options.datePicker) {
      input.inputMode = "numeric";
      input.pattern = "[0-9.\\-/\\s]*";
      input.title = "Upiši datum, npr. 12112025 za 12.11.2025.";
    }
    input.value = value;
    input.placeholder = placeholder;
    input.dataset.dirty = "false";
    input.addEventListener("input", () => {
      input.dataset.dirty = "true";
    });
    label.append(labelNode, input);
    if (options.datePicker) {
      const picker = document.createElement("input");
      picker.type = "date";
      picker.className = "work-order-row-context-native-date";
      picker.tabIndex = -1;
      picker.setAttribute("aria-hidden", "true");

      const button = document.createElement("button");
      button.type = "button";
      button.className = "work-order-row-context-date-button";
      button.innerHTML = getWorkOrderIconMarkup("dates");
      button.setAttribute("aria-label", "Odaberi datum fakture");
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        picker.value = normalizeDateInputValue(input.value);
        if (typeof picker.showPicker === "function") {
          picker.showPicker();
          return;
        }
        picker.focus({ preventScroll: true });
      });

      picker.addEventListener("change", () => {
        input.value = formatDateInputDisplayValue(picker.value);
        input.dataset.dirty = "true";
      });

      input.addEventListener("blur", () => {
        const normalizedValue = normalizeDateInputValue(input.value);
        input.value = formatDateInputDisplayValue(normalizedValue || input.value);
        picker.value = normalizedValue;
      });

      label.append(button, picker);
    }
    return { label, input };
  };

  const dateField = createTextField(
    "Datum fakture",
    invoiceDate.mixed ? "" : formatDateInputDisplayValue(invoiceDate.value),
    invoiceDate.mixed ? "Različiti datumi" : "dd.mm.yyyy",
    { datePicker: true },
  );
  const noteField = createTextField(
    "Broj fakture",
    invoiceNote.mixed ? "" : invoiceNote.value,
    invoiceNote.mixed ? "Različiti brojevi" : "npr. 2026-001",
  );
  const amountField = createTextField(
    "Iznos",
    amount.mixed ? "" : amount.value,
    amount.mixed ? "Različiti iznosi" : "npr. 250,00",
  );

  const finishedLabel = document.createElement("label");
  finishedLabel.className = "work-order-row-context-check";
  const finishedInput = document.createElement("input");
  finishedInput.type = "checkbox";
  finishedInput.checked = finishedValues[0] && !finishedMixed;
  finishedInput.indeterminate = finishedMixed;
  finishedInput.dataset.dirty = "false";
  finishedInput.addEventListener("change", () => {
    finishedInput.dataset.dirty = "true";
    finishedInput.indeterminate = false;
    if (finishedInput.checked && inspectorValues.length === 0) {
      inspectorValues = getDefaultWorkOrderFinishedInspectorValues(inspectorOptions);
      inspectorPicker?._setSelectedValues?.(inspectorValues, { mixed: false });
      inspectorsDirty = true;
    }
  });
  const finishedText = document.createElement("span");
  finishedText.textContent = "RN završio";
  finishedLabel.append(finishedInput, finishedText);

  const inspectorField = document.createElement("div");
  inspectorField.className = "work-order-row-context-field work-order-row-context-inspectors";
  const inspectorFieldLabel = document.createElement("span");
  inspectorFieldLabel.textContent = "Ispitivači";
  const inspectorPicker = createWorkOrderFinishedInspectorPicker({
    options: inspectorOptions,
    selectedValues: inspectorValues,
    mixed: inspectorState.mixed,
    onChange: (nextValues) => {
      inspectorValues = Array.from(new Set((Array.isArray(nextValues) ? nextValues : []).map((value) => String(value || "").trim()).filter(Boolean)));
      inspectorsDirty = true;
      finishedInput.checked = inspectorValues.length > 0;
      finishedInput.indeterminate = false;
      finishedInput.dataset.dirty = "true";
    },
  });
  inspectorField.append(inspectorFieldLabel, inspectorPicker);

  const fields = document.createElement("div");
  fields.className = "work-order-row-context-grid";
  fields.append(dateField.label, noteField.label, amountField.label, finishedLabel, inspectorField);

  const actions = document.createElement("div");
  actions.className = "work-order-row-context-actions";
  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "ghost-button";
  cancelButton.textContent = "Zatvori";
  cancelButton.addEventListener("click", () => {
    closeWorkOrderRowMenu();
  });
  const saveButton = document.createElement("button");
  saveButton.type = "submit";
  saveButton.className = "primary-button";
  saveButton.textContent = "Primijeni";
  actions.append(cancelButton, saveButton);

  menu.append(header, shortcuts, fields, actions);
  menu.addEventListener("click", (event) => {
    event.stopPropagation();
  });
  menu.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
  });
  menu.addEventListener("submit", (event) => {
    event.preventDefault();
    const dateDirty = dateField.input.dataset.dirty === "true";
    const noteDirty = noteField.input.dataset.dirty === "true";
    const amountDirty = amountField.input.dataset.dirty === "true";
    const finishedDirty = finishedInput.dataset.dirty === "true";
    const completedByNames = getWorkOrderFinishedInspectorNames(inspectorValues, inspectorOptions);

    void applyWorkOrderRowMenuUpdate(targets, (targetWorkOrder) => {
      const body = {};
      if (dateDirty) {
        body.invoiceDate = normalizeDateInputValue(dateField.input.value);
      }
      if (noteDirty) {
        body.invoiceNote = noteField.input.value;
      }
      if (amountDirty) {
        body.weight = amountField.input.value;
      }
      if (finishedDirty || inspectorsDirty) {
        Object.assign(body, getWorkOrderFinishedPatch(targetWorkOrder, finishedInput.checked, completedByNames));
      }
      return body;
    });
  });

  document.body.append(menu);
  const rect = menu.getBoundingClientRect();
  const left = Math.min(Math.max(pointerX + 8, 12), Math.max(12, window.innerWidth - rect.width - 12));
  const top = Math.min(Math.max(pointerY + 8, 12), Math.max(12, window.innerHeight - rect.height - 12));
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
  state.workOrderRowMenu = { element: menu, workOrderId: String(workOrder.id || "") };
  dateField.input.focus({ preventScroll: true });
}

function setWorkOrderBulkExecutorTriggerContent(trigger, values = [], { mixed = false } = {}) {
  if (!(trigger instanceof HTMLButtonElement)) {
    return;
  }

  const normalizedValues = normalizeWorkOrderExecutorValues(values);
  trigger.replaceChildren();
  trigger.title = mixed
    ? "Izvršitelji imaju različite vrijednosti"
    : normalizedValues.length > 0
      ? normalizedValues.join(", ")
      : "Postavi izvršitelje";
  trigger.setAttribute("aria-label", trigger.title);

  const icon = createWorkOrderActionIcon("assignees");
  icon.classList.add("work-order-bulk-action-icon");
  trigger.append(icon);

  if (normalizedValues.length > 0) {
    const stack = document.createElement("span");
    stack.className = "work-order-bulk-executor-stack";
    normalizedValues.slice(0, 3).forEach((value) => {
      const avatar = createWorkOrderMiniExecutor(value, {
        className: "work-order-mini-executor work-order-bulk-executor-avatar",
      });
      avatar.removeAttribute("title");
      stack.append(avatar);
    });
    if (normalizedValues.length > 3) {
      stack.append(createExecutorOverflowBadge(
        normalizedValues.length - 3,
        "work-order-mini-executor work-order-bulk-executor-avatar",
      ));
    }

    trigger.append(stack);
  }

  const label = document.createElement("span");
  label.className = "work-order-bulk-action-label";
  if (mixed) {
    label.textContent = "Izvršitelji";
  } else if (normalizedValues.length === 1) {
    label.textContent = normalizedValues[0];
  } else if (normalizedValues.length > 1) {
    label.textContent = `${normalizedValues.length} izvršitelja`;
  } else {
    label.textContent = "Izvršitelji";
  }
  trigger.append(label);
}

function getWorkOrderBulkOptionLabel(options = [], value = "", fallbackLabel = "") {
  const match = options.find((option) => String(option.value) === String(value));
  return match?.label || value || fallbackLabel;
}

function createWorkOrderBulkChoicePicker({
  type = "choice",
  iconName = "document",
  emptyLabel = "",
  value = "",
  mixed = false,
  options = [],
  pending = false,
  onSelect,
} = {}) {
  const wrapper = document.createElement("div");
  wrapper.className = "work-item-status-dropdown work-order-bulk-choice-dropdown";
  wrapper.dataset.preventRowOpen = "true";

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "work-item-status-trigger work-order-bulk-choice-trigger";
  trigger.dataset.preventRowOpen = "true";
  trigger.dataset.bulkType = type;
  trigger.setAttribute("aria-haspopup", "menu");
  trigger.setAttribute("aria-expanded", "false");

  let currentValue = String(value || "").trim();
  let isMixed = Boolean(mixed);

  const setPendingState = (isPending) => {
    wrapper.classList.toggle("is-pending", isPending);
    trigger.disabled = isPending || state.workOrderBatch.pending;
  };

  const renderTrigger = () => {
    trigger.replaceChildren();
    trigger.dataset.optionValue = isMixed
      ? "mixed"
      : currentValue
        ? slugifyValue(currentValue)
        : "empty";
    trigger.classList.toggle("is-mixed", isMixed);

    const icon = createWorkOrderActionIcon(iconName);
    icon.classList.add("work-order-bulk-action-icon");
    trigger.append(icon);

    const label = document.createElement("span");
    label.className = "work-order-bulk-action-label";
    label.textContent = isMixed
      ? emptyLabel
      : getWorkOrderBulkOptionLabel(options, currentValue, emptyLabel);
    trigger.append(label);

    trigger.title = label.textContent || emptyLabel;
    trigger.setAttribute("aria-label", trigger.title);
  };

  const positionMenuPortal = (menu) => {
    const triggerRect = trigger.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let left = triggerRect.left;
    let top = triggerRect.bottom + 10;

    if (left + menuRect.width > viewportWidth - 12) {
      left = Math.max(12, viewportWidth - menuRect.width - 12);
    }

    if (top + menuRect.height > viewportHeight - 12) {
      top = Math.max(12, triggerRect.top - menuRect.height - 10);
    }

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.minWidth = `${Math.round(Math.max(triggerRect.width, 196))}px`;
  };

  const openMenu = () => {
    closeOpenWorkOrderStatusMenus(wrapper);

    if (wrapper._menuPortal) {
      return;
    }

    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal work-order-bulk-choice-menu-portal";
    menu.dataset.bulkType = type;
    menu.setAttribute("role", "menu");

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => {
        event.stopPropagation();
      });
    });

    options.forEach((option) => {
      const optionButton = document.createElement("button");
      optionButton.type = "button";
      optionButton.className = "work-item-status-option work-order-bulk-choice-option";
      optionButton.dataset.bulkType = type;
      optionButton.dataset.optionValue = slugifyValue(option.value);
      optionButton.textContent = option.label;
      optionButton.setAttribute("role", "menuitem");
      optionButton.classList.toggle("is-selected", !isMixed && option.value === currentValue);
      optionButton.disabled = Boolean(option.disabled);
      optionButton.title = option.disabled ? (option.disabledTitle || "Nemas ovlastenje za ovu promjenu.") : "";

      optionButton.addEventListener("click", (event) => {
        event.stopPropagation();
        closeOpenWorkOrderStatusMenus();

        if (state.workOrderBatch.pending || option.disabled) {
          return;
        }

        if (!isMixed && option.value === currentValue) {
          return;
        }

        currentValue = option.value;
        isMixed = false;
        renderTrigger();
        setPendingState(true);

        Promise.resolve(onSelect?.(option.value)).finally(() => {
          setPendingState(false);
        });
      });

      menu.append(optionButton);
    });

    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    positionMenuPortal(menu);
    requestAnimationFrame(() => positionMenuPortal(menu));
  };

  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    wrapper.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });

  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (wrapper.classList.contains("is-open")) {
      closeOpenWorkOrderStatusMenus();
      return;
    }
    openMenu();
  });

  setPendingState(pending);
  renderTrigger();
  wrapper.append(trigger);
  return wrapper;
}

function createWorkOrderBatchExecutorPicker(selectedWorkOrders = []) {
  const wrapper = document.createElement("div");
  wrapper.className = "work-order-calendar-executor-picker work-order-bulk-executor-picker";
  wrapper.dataset.preventRowOpen = "true";

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "work-order-calendar-executor-trigger work-order-bulk-executor-trigger";
  trigger.dataset.preventRowOpen = "true";
  trigger.setAttribute("aria-haspopup", "dialog");
  trigger.setAttribute("aria-expanded", "false");

  const getCurrentState = () => getSharedWorkOrderBatchExecutors(getAllSelectedWorkOrdersForDocumentWizard());
  const setPendingState = (isPending) => {
    wrapper.classList.toggle("is-pending", isPending);
    trigger.disabled = isPending || state.workOrderBatch.pending;
  };
  const setCurrentValues = (values, { mixed = false } = {}) => {
    setWorkOrderBulkExecutorTriggerContent(trigger, values, { mixed });
  };

  const positionMenuPortal = (menu) => {
    const triggerRect = trigger.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let left = triggerRect.left;
    let top = triggerRect.top - menuRect.height - 10;

    if (top < 12) {
      top = triggerRect.bottom + 10;
    }

    if (left + menuRect.width > viewportWidth - 12) {
      left = Math.max(12, viewportWidth - menuRect.width - 12);
    }

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.minWidth = `${Math.max(280, Math.round(triggerRect.width + 60))}px`;
  };

  const closeMenu = () => {
    wrapper.classList.remove("is-open");
    trigger.setAttribute("aria-expanded", "false");
    if (wrapper._menuPortal) {
      wrapper._menuPortal.remove();
      wrapper._menuPortal = null;
    }
  };

  wrapper._closeMenu = closeMenu;

  const openMenu = () => {
    closeOpenWorkOrderStatusMenus(wrapper);

    if (wrapper._menuPortal) {
      return;
    }

    const sharedState = getCurrentState();
    let draftValues = [...sharedState.values];
    let mixedSelection = sharedState.mixed;
    let searchQuery = "";
    let menuPending = false;

    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal work-order-calendar-executor-menu-portal work-order-bulk-executor-menu-portal";
    menu.setAttribute("role", "dialog");
    menu.setAttribute("aria-label", "Batch izbor izvršitelja");

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => {
        event.stopPropagation();
      });
    });

    const searchWrap = document.createElement("div");
    searchWrap.className = "work-order-calendar-executor-search";

    const searchInput = document.createElement("input");
    searchInput.type = "search";
    searchInput.className = "work-order-calendar-executor-search-input";
    searchInput.placeholder = "Traži po imenu ili prezimenu";
    searchInput.autocomplete = "off";
    searchInput.spellcheck = false;
    searchWrap.append(searchInput);

    const selection = document.createElement("div");
    selection.className = "work-order-calendar-executor-selection";

    const helper = document.createElement("p");
    helper.className = "work-order-calendar-executor-helper";

    const optionsList = document.createElement("div");
    optionsList.className = "work-order-calendar-executor-options";

    const clearButton = document.createElement("button");
    clearButton.type = "button";
    clearButton.className = "ghost-button work-order-calendar-executor-clear";
    clearButton.textContent = "Očisti";

    const toggleDraftValue = (value) => {
      const normalizedValue = String(value ?? "").trim();
      if (!normalizedValue) {
        return;
      }

      if (draftValues.includes(normalizedValue)) {
        draftValues = draftValues.filter((entry) => entry !== normalizedValue);
        return;
      }

      draftValues = [...draftValues, normalizedValue];
    };

    const setMenuPending = (isPending) => {
      menuPending = Boolean(isPending);
      setPendingState(menuPending);
      searchInput.disabled = menuPending;
      syncMenuState();
    };

    const applyDraftValues = async (nextValues, { focusSearch = true } = {}) => {
      const normalized = normalizeWorkOrderExecutorValues(nextValues);
      draftValues = normalized;
      mixedSelection = false;
      setMenuPending(true);

      const success = await applyWorkOrderBatchUpdate({
        executors: normalized,
        executor1: normalized[0] || "",
        executor2: normalized[1] || "",
      }, {
        successMessage: `Izvršitelji ažurirani na ${formatWorkOrderSelectionCountLabel(getAllSelectedWorkOrdersForDocumentWizard().length).toLowerCase()}.`,
      });

      setMenuPending(false);

      if (!success) {
        const currentState = getCurrentState();
        draftValues = [...currentState.values];
        mixedSelection = currentState.mixed;
        syncMenuState();
        if (focusSearch) {
          searchInput.focus({ preventScroll: true });
        }
        return;
      }

      setCurrentValues(normalized, { mixed: false });
      syncMenuState();

      if (focusSearch) {
        searchInput.focus({ preventScroll: true });
      }
    };

    const renderSelection = () => {
      selection.replaceChildren();

      if (mixedSelection && draftValues.length === 0) {
        const mixed = document.createElement("span");
        mixed.className = "work-order-calendar-executor-selection-empty";
        mixed.textContent = "Odaberi novi set izvršitelja za sve odabrane RN-ove";
        selection.append(mixed);
        return;
      }

      if (draftValues.length === 0) {
        const empty = document.createElement("span");
        empty.className = "work-order-calendar-executor-selection-empty";
        empty.textContent = "Bez izvršitelja";
        selection.append(empty);
        return;
      }

      draftValues.forEach((value) => {
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "work-order-calendar-executor-chip";
        chip.title = `Makni ${value}`;

        const avatar = createWorkOrderMiniExecutor(value);
        avatar.removeAttribute("title");

        const label = document.createElement("span");
        label.className = "work-order-calendar-executor-chip-label";
        label.textContent = value;

        const remove = document.createElement("span");
        remove.className = "work-order-calendar-executor-chip-remove";
        remove.setAttribute("aria-hidden", "true");
        remove.textContent = "x";

        chip.append(avatar, label, remove);
        chip.addEventListener("click", (event) => {
          event.stopPropagation();
          if (menuPending) {
            return;
          }
          void applyDraftValues(draftValues.filter((entry) => entry !== value));
        });

        selection.append(chip);
      });
    };

    const renderOptions = () => {
      optionsList.replaceChildren();

      const visibleOptions = getWorkOrderExecutorOptions(draftValues)
        .filter((option) => matchesWorkOrderExecutorSearch(option, searchQuery));

      if (visibleOptions.length === 0) {
        const empty = document.createElement("p");
        empty.className = "work-order-calendar-executor-empty";
        empty.textContent = "Nema izvršitelja za ovaj pojam.";
        optionsList.append(empty);
        return;
      }

      visibleOptions.forEach((option) => {
        const isSelected = draftValues.includes(option.value);
        const optionButton = document.createElement("button");
        optionButton.type = "button";
        optionButton.className = "work-item-status-option work-order-calendar-executor-option";
        optionButton.classList.toggle("is-selected", isSelected);
        optionButton.setAttribute("role", "menuitemcheckbox");
        optionButton.setAttribute("aria-checked", String(isSelected));

        const avatar = createWorkOrderMiniExecutor(option, {
          className: "work-order-calendar-executor-option-avatar",
        });

        const label = document.createElement("span");
        label.className = "work-order-calendar-executor-option-label";
        label.textContent = option.label;

        const marker = document.createElement("span");
        marker.className = "work-order-calendar-executor-option-marker";
        marker.setAttribute("aria-hidden", "true");
        marker.textContent = isSelected ? "✓" : "+";

        optionButton.append(avatar, label, marker);
        optionButton.addEventListener("click", (event) => {
          event.stopPropagation();
          if (menuPending) {
            return;
          }
          toggleDraftValue(option.value);
          void applyDraftValues(draftValues);
        });

        optionsList.append(optionButton);
      });
    };

    const syncMenuState = () => {
      renderSelection();
      renderOptions();
      helper.textContent = mixedSelection && draftValues.length === 0
        ? "Odaberi nove izvršitelje i primijeni ih na sve odabrane RN-ove."
        : draftValues.length > 0
          ? `${draftValues.length} odabranih izvršitelja za batch promjenu.`
          : "Odaberi jednog ili više izvršitelja.";
      clearButton.disabled = menuPending || draftValues.length === 0;
      requestAnimationFrame(() => positionMenuPortal(menu));
    };

    clearButton.addEventListener("click", (event) => {
      event.stopPropagation();
      if (menuPending) {
        return;
      }
      void applyDraftValues([]);
    });

    searchInput.addEventListener("input", () => {
      searchQuery = searchInput.value || "";
      renderOptions();
      requestAnimationFrame(() => positionMenuPortal(menu));
    });

    searchInput.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        closeMenu();
        trigger.focus({ preventScroll: true });
        return;
      }

      if (event.key !== "Enter") {
        return;
      }

      const visibleOptions = getWorkOrderExecutorOptions(draftValues)
        .filter((option) => matchesWorkOrderExecutorSearch(option, searchQuery));

      if (visibleOptions.length !== 1) {
        return;
      }

      event.preventDefault();
      toggleDraftValue(visibleOptions[0].value);
      void applyDraftValues(draftValues);
    });

    menu.append(searchWrap, selection, helper, optionsList, clearButton);
    syncMenuState();

    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    positionMenuPortal(menu);
    requestAnimationFrame(() => {
      positionMenuPortal(menu);
      searchInput.focus({ preventScroll: true });
      searchInput.select();
    });
  };

  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    wrapper.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });

  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (wrapper.classList.contains("is-open")) {
      closeOpenWorkOrderStatusMenus();
      return;
    }
    openMenu();
  });

  const sharedState = getSharedWorkOrderBatchExecutors(selectedWorkOrders);
  setCurrentValues(sharedState.values, { mixed: sharedState.mixed });
  setPendingState(state.workOrderBatch.pending);
  wrapper.append(trigger);
  return wrapper;
}

function renderWorkOrderBatchBar() {
  const selectedWorkOrders = getAllSelectedWorkOrdersForDocumentWizard();
  const selectedCount = selectedWorkOrders.length;
  const isVisible = state.activeWorkOrderViewMode === "list" && selectedCount >= 1;

  if (workOrderBulkBar) {
    workOrderBulkBar.hidden = !isVisible;
    workOrderBulkBar.style.display = isVisible ? "block" : "none";
  }

  if (!isVisible) {
    return;
  }

  const sharedStatus = getSharedWorkOrderBatchValue(selectedWorkOrders, (item) => item.status || "Otvoreni RN");
  const sharedPriority = getSharedWorkOrderBatchValue(selectedWorkOrders, (item) => item.priority || "Normal");
  const sharedDueDate = getSharedWorkOrderBatchValue(selectedWorkOrders, (item) => item.dueDate || "");
  const allowedStatusOptions = WORK_ORDER_STATUS_OPTIONS.map((option) => ({
    ...option,
    disabled: selectedWorkOrders.some((item) => !getCanSetWorkOrderStatus(item.status || "Otvoreni RN", option.value)),
    disabledTitle: "Nemas ovlastenje za ovaj status na svim odabranim RN-ovima.",
  }));

  if (workOrderBulkCountLabel) {
    workOrderBulkCountLabel.textContent = formatWorkOrderSelectionCountLabel(selectedCount);
  }

  if (workOrderBulkStatusSlot) {
    workOrderBulkStatusSlot.replaceChildren(createWorkOrderBulkChoicePicker({
      type: "status",
      iconName: "status",
      emptyLabel: "Status",
      value: sharedStatus.value,
      mixed: sharedStatus.mixed,
      options: allowedStatusOptions,
      pending: state.workOrderBatch.pending,
      onSelect: (nextValue) => applyWorkOrderBatchUpdate({ status: nextValue }, {
        successMessage: `Status je ažuriran za ${formatWorkOrderSelectionCountLabel(getAllSelectedWorkOrdersForDocumentWizard().length).toLowerCase()}.`,
      }),
    }));
  }

  if (workOrderBulkPrioritySlot) {
    workOrderBulkPrioritySlot.replaceChildren(createWorkOrderBulkChoicePicker({
      type: "priority",
      iconName: "priority",
      emptyLabel: "Prioritet",
      value: sharedPriority.value,
      mixed: sharedPriority.mixed,
      options: PRIORITY_OPTIONS,
      pending: state.workOrderBatch.pending,
      onSelect: (nextValue) => applyWorkOrderBatchUpdate({ priority: nextValue }, {
        successMessage: `Prioritet je ažuriran za ${formatWorkOrderSelectionCountLabel(getAllSelectedWorkOrdersForDocumentWizard().length).toLowerCase()}.`,
      }),
    }));
  }

  if (workOrderBulkDueDateInput) {
    workOrderBulkDueDateInput.value = sharedDueDate.mixed
      ? ""
      : (sharedDueDate.value ? formatCompactDate(sharedDueDate.value) : "");
    workOrderBulkDueDateInput.placeholder = sharedDueDate.mixed ? "Različiti rokovi" : "dd.mm.yyyy";
    workOrderBulkDueDateInput.dataset.isoValue = sharedDueDate.mixed ? "" : sharedDueDate.value;
    workOrderBulkDueDateInput.disabled = state.workOrderBatch.pending;
    workOrderBulkDueDateInput.title = sharedDueDate.mixed
      ? "Odabrani RN-ovi imaju različite rokove. Upiši novi rok kao dd.mm.yyyy."
      : "Postavi rok kao dd.mm.yyyy";
  }

  if (workOrderBulkExecutorsPicker) {
    workOrderBulkExecutorsPicker.replaceChildren(createWorkOrderBatchExecutorPicker(selectedWorkOrders));
  }

  if (workOrderBulkOpenDocumentsButton) {
    const selectionState = getWorkOrderDocumentSelectionState(selectedWorkOrders);
    const hasUnsupportedMode = selectionState.mode === "other";
    const hasNoTypedServices = selectedCount > 0 && !selectionState.hasServices;
    workOrderBulkOpenDocumentsButton.disabled = state.workOrderBatch.pending
      || selectedCount === 0
      || selectionState.hasMixedTypes
      || hasUnsupportedMode
      || hasNoTypedServices;
    decorateWorkOrderActionButton(workOrderBulkOpenDocumentsButton, "document");
  }

  if (workOrderBulkClearButton) {
    workOrderBulkClearButton.disabled = state.workOrderBatch.pending;
    if (workOrderBulkClearButton.dataset.decorated !== "true") {
      workOrderBulkClearButton.textContent = "Očisti";
    }
    decorateWorkOrderActionButton(workOrderBulkClearButton, "reset");
  }

  if (workOrderBulkFeedback) {
    const message = String(state.workOrderBatch.message || "").trim();
    workOrderBulkFeedback.hidden = !message;
    workOrderBulkFeedback.textContent = message;
    workOrderBulkFeedback.dataset.tone = state.workOrderBatch.tone || "";
  }
}

function updateWorkOrderDocumentSelectionChrome({ visibleItems = null } = {}) {
  const selectedCount = state.workOrderDocumentWizard.selectedIds.size;
  const isListMode = state.activeWorkOrderViewMode === "list";
  const showBatchBar = isListMode && selectedCount >= 1;
  const selectedWorkOrders = getAllSelectedWorkOrdersForDocumentWizard();
  const selectionState = getWorkOrderDocumentSelectionState(selectedWorkOrders);
  const mode = selectionState.mode;
  const copy = getWorkOrderDocumentActionCopy(mode || "inspection");
  const hasUnsupportedMode = mode === "other";
  const hasMixedTypes = selectionState.hasMixedTypes;
  const hasNoTypedServices = selectedCount > 0 && !selectionState.hasServices;
  const canOpen = selectedCount > 0 && !hasMixedTypes && !hasUnsupportedMode && !hasNoTypedServices;

  if (workOrderOpenDocumentsButton) {
    workOrderOpenDocumentsButton.disabled = !canOpen;
    workOrderOpenDocumentsButton.hidden = !isListMode || showBatchBar;
  }

  if (workOrderOpenDocumentsLabel) {
    workOrderOpenDocumentsLabel.textContent = copy.single;
  }

  if (workOrderBatchClearButton) {
    workOrderBatchClearButton.hidden = !isListMode || selectedCount === 0 || showBatchBar;
  }

  if (workOrderOpenDocumentsCount) {
    workOrderOpenDocumentsCount.textContent = String(selectedCount);
    workOrderOpenDocumentsCount.hidden = selectedCount === 0;
  }

  if (workOrdersHelper && isListMode) {
    const currentText = workOrdersHelper.dataset.baseText || workOrdersHelper.textContent || "";
    const selectionText = selectedCount === 0
      ? ""
      : hasMixedTypes
        ? `${selectedCount} odabrano, ali RN-ovi imaju različite vrste usluga.`
        : hasUnsupportedMode
          ? `${selectedCount} odabrano, ali vrsta "Ostalo" nema poseban tok.`
          : hasNoTypedServices
            ? `${selectedCount} odabrano, ali RN-ovi nemaju uslugu s vrstom.`
            : `${selectedCount} ${copy.helper}`;
    workOrdersHelper.textContent = [currentText, selectionText].filter(Boolean).join(" ");
    workOrdersHelper.hidden = false;
  }

  if (workOrdersTableWrap) {
    workOrdersTableWrap.classList.toggle("is-selection-active", selectedCount > 0);
    workOrdersTableWrap.classList.toggle("has-bulk-bar", showBatchBar);
  }

  if (visibleItems && workOrdersBody) {
    const visibleIdSet = new Set(visibleItems.map((item) => String(item.id)));
    const selectedVisibleCount = visibleItems.filter((item) => state.workOrderDocumentWizard.selectedIds.has(String(item.id))).length;
    const masterCheckbox = workOrdersBody.querySelector("[data-work-order-select-all]");
    if (masterCheckbox instanceof HTMLInputElement) {
      masterCheckbox.checked = visibleItems.length > 0 && selectedVisibleCount === visibleItems.length;
      masterCheckbox.indeterminate = selectedVisibleCount > 0 && selectedVisibleCount < visibleItems.length;
      masterCheckbox.dataset.visibleCount = String(visibleIdSet.size);
    }
  }

  if (workOrderBulkOpenDocumentsButton) {
    workOrderBulkOpenDocumentsButton.disabled = state.workOrderBatch.pending || !canOpen;
  }
  if (workOrderBulkOpenDocumentsLabel) {
    workOrderBulkOpenDocumentsLabel.textContent = copy.bulk;
  }
  if (workOrderDocumentWizardTitle) {
    workOrderDocumentWizardTitle.textContent = copy.title;
  }
  if (workOrderDocumentWizardHelper) {
    workOrderDocumentWizardHelper.textContent = hasMixedTypes
      ? "Odabrani RN-ovi imaju različite vrste usluga. Otvori Ispitivanje i ZNR zasebno."
      : hasUnsupportedMode
        ? "Za usluge vrste Ostalo još nema poseban tok kroz zapisnike ili ispite."
        : hasNoTypedServices
          ? "Odabrani RN-ovi nemaju vrstu usluge koja pokreće zapisnike ili ispite."
          : copy.wizardHelper;
    workOrderDocumentWizardHelper.hidden = false;
  }

  renderWorkOrderBatchBar();
}

function getWorkOrderTemplateKindConfig(kind = "rn") {
  return WORK_ORDER_TEMPLATE_KIND_CONFIGS[String(kind || "").trim()] ?? WORK_ORDER_TEMPLATE_KIND_CONFIGS.rn;
}

function normalizeWorkOrderTemplateKind(kind = "rn") {
  return getWorkOrderTemplateKindConfig(kind).key;
}

function getWorkOrderTemplateEntries(kind = "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  return sortDocumentTemplates(state.documentTemplates ?? []).filter((template) => {
    const title = normalizeLooseName(template.title || "");
    const documentType = normalizeLooseName(template.documentType || "");
    const referenceDocument = template.referenceDocument ?? {};
    const hasSupportedReference = isDocumentTemplateWordReferenceDocument(referenceDocument);
    if (!hasSupportedReference) {
      return false;
    }

    if (config.key === "handover") {
      return documentType.includes("primopredaj")
        || title.includes("primopredaj")
        || title.includes("handover");
    }

    return documentType.includes("radni nalog")
      || title.includes("rn template")
      || title.includes("radni nalog");
  });
}

function getSelectedWorkOrderTemplateId(templatesOrKind = getWorkOrderTemplateEntries("rn"), maybeKind = "rn") {
  const templates = Array.isArray(templatesOrKind) ? templatesOrKind : getWorkOrderTemplateEntries(templatesOrKind || "rn");
  const kind = Array.isArray(templatesOrKind) ? maybeKind : templatesOrKind;
  const config = getWorkOrderTemplateKindConfig(kind);
  const selectedTemplateId = String(state.workOrderTemplateSettings[config.selectedKey] || "").trim();
  if (selectedTemplateId && templates.some((template) => String(template.id) === selectedTemplateId)) {
    return selectedTemplateId;
  }

  return templates[0]?.id ? String(templates[0].id) : "";
}

function getSelectedWorkOrderTemplate(templatesOrKind = getWorkOrderTemplateEntries("rn"), maybeKind = "rn") {
  const templates = Array.isArray(templatesOrKind) ? templatesOrKind : getWorkOrderTemplateEntries(templatesOrKind || "rn");
  const kind = Array.isArray(templatesOrKind) ? maybeKind : templatesOrKind;
  const selectedTemplateId = getSelectedWorkOrderTemplateId(templates, kind);
  return templates.find((template) => String(template.id) === selectedTemplateId) ?? null;
}

function getWorkOrderTemplateDisplayName(template = null, kind = "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  return template?.title
    || template?.referenceDocument?.fileName
    || state.workOrderTemplateSettings[config.fileNameKey]
    || "";
}

function getWorkOrderTemplateDisplayTimestamp(template = null, kind = "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  return template?.updatedAt || state.workOrderTemplateSettings[config.updatedAtKey] || "";
}

function setSelectedWorkOrderTemplate(template = null, kind = "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  state.workOrderTemplateSettings[config.selectedKey] = template?.id ? String(template.id) : "";
  state.workOrderTemplateSettings[config.fileNameKey] = getWorkOrderTemplateDisplayName(template, kind);
  state.workOrderTemplateSettings[config.updatedAtKey] = template?.updatedAt || new Date().toISOString();
  persistWorkOrderTemplateSettings();
}

function renderWorkOrderTemplateSelect(kind = "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  const select = config.key === "handover" ? workOrderHandoverTemplateSelect : workOrderTemplateSelect;
  if (!select) {
    return;
  }

  const templates = getWorkOrderTemplateEntries(config.key);
  const selectedTemplateId = getSelectedWorkOrderTemplateId(templates, config.key);
  const options = templates.length > 0
    ? templates.map((template) => ({
      value: template.id,
      label: template.title || template.referenceDocument?.fileName || config.title,
    }))
    : [{ value: "", label: config.emptyLabel }];
  replaceSelectOptions(select, options, selectedTemplateId);
  select.disabled = templates.length === 0;
}

function renderWorkOrderTemplateKindMeta(kind = "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  const meta = config.key === "handover" ? workOrderTemplateHandoverMeta : workOrderTemplateRnMeta;
  if (!meta) {
    return;
  }

  const templates = getWorkOrderTemplateEntries(config.key);
  const selectedTemplate = getSelectedWorkOrderTemplate(templates, config.key);
  const label = getWorkOrderTemplateDisplayName(selectedTemplate, config.key);
  const timestamp = getWorkOrderTemplateDisplayTimestamp(selectedTemplate, config.key);
  const countLabel = templates.length === 1 ? "1 spremljen template" : `${templates.length} spremljena templatea`;
  meta.textContent = label
    ? `${label}${timestamp ? ` · ${formatCompactDateTime(timestamp)}` : ""} · ${countLabel}`
    : `${config.emptyLabel}. Uploadaj .docx ili .dotx predložak.`;

  workOrderTemplateDownloadButtons
    .filter((button) => normalizeWorkOrderTemplateKind(button.dataset.workOrderTemplateDownload) === config.key)
    .forEach((button) => {
      button.disabled = !selectedTemplate;
      button.title = selectedTemplate ? `Preuzmi ${label}` : config.emptyLabel;
    });

  workOrderTemplateDeleteButtons
    .filter((button) => normalizeWorkOrderTemplateKind(button.dataset.workOrderTemplateDelete) === config.key)
    .forEach((button) => {
      button.disabled = !selectedTemplate || !getCanManageMasterData();
      button.title = selectedTemplate ? `Obriši ${label}` : config.emptyLabel;
    });

  workOrderTemplateUploadButtons
    .filter((button) => normalizeWorkOrderTemplateKind(button.dataset.workOrderTemplateUpload) === config.key)
    .forEach((button) => {
      button.disabled = !getCanManageMasterData();
      button.title = getCanManageMasterData()
        ? `Uploadaj ${config.title.toLowerCase()}`
        : "Nemaš ovlaštenje za dodavanje templatea.";
    });
}

function renderWorkOrderTemplatePlaceholderList() {
  if (!workOrderTemplatePlaceholderList) {
    return;
  }

  const config = getWorkOrderTemplateKindConfig(state.workOrderTemplateSettings.placeholderKind || "rn");
  workOrderTemplatePlaceholderTabs.forEach((tab) => {
    const tabKind = normalizeWorkOrderTemplateKind(tab.dataset.workOrderTemplatePlaceholderTab);
    tab.classList.toggle("is-active", tabKind === config.key);
    tab.setAttribute("aria-selected", tabKind === config.key ? "true" : "false");
  });

  if (workOrderTemplatePlaceholderCopy) {
    workOrderTemplatePlaceholderCopy.textContent = config.key === "handover"
      ? "Za gotovu tablicu stavi {{SPECIFIKACIJA}}. Loop {{#USLUGE_REDOVI}} koristi samo ako želiš ručno složiti tablicu."
      : "Klikni placeholder da ga kopiraš u Word RN predložak. Za usluge u tablici koristi {{#USLUGE_REDOVI}} loop.";
  }

  workOrderTemplatePlaceholderList.replaceChildren(...config.placeholders.map(([token, description]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "offer-template-placeholder-chip";
    button.innerHTML = `
      <strong>${escapeHtml(token)}</strong>
      <span>${escapeHtml(description)}</span>
    `;
    button.title = `Kopiraj ${token}`;
    button.addEventListener("click", () => {
      navigator.clipboard?.writeText(token)
        .then(() => {
          if (workOrderTemplateError) {
            workOrderTemplateError.textContent = `Kopirano ${token}`;
          }
        })
        .catch(() => {
          if (workOrderTemplateError) {
            workOrderTemplateError.textContent = `Ne mogu kopirati ${token}`;
          }
        });
    });
    return button;
  }));
}

function syncWorkOrderTemplateModal() {
  const isOpen = Boolean(state.workOrderTemplateSettings.modalOpen);
  if (workOrderTemplateBackdrop) {
    workOrderTemplateBackdrop.hidden = !isOpen;
    workOrderTemplateBackdrop.classList.toggle("is-modal-open", isOpen);
  }
  if (workOrderTemplatePanel) {
    workOrderTemplatePanel.hidden = !isOpen;
    workOrderTemplatePanel.classList.toggle("is-modal-open", isOpen);
  }
  document.body.classList.toggle("is-work-order-template-open", isOpen);

  if (!isOpen) {
    return;
  }

  renderWorkOrderTemplateSelect("rn");
  renderWorkOrderTemplateSelect("handover");
  renderWorkOrderTemplateKindMeta("rn");
  renderWorkOrderTemplateKindMeta("handover");
  renderWorkOrderTemplatePlaceholderList();

  if (workOrderTemplateModalMeta) {
    const rnLabel = getWorkOrderTemplateDisplayName(getSelectedWorkOrderTemplate("rn"), "rn") || "bez RN templatea";
    const handoverLabel = getWorkOrderTemplateDisplayName(getSelectedWorkOrderTemplate("handover"), "handover") || "bez primopredajnog templatea";
    workOrderTemplateModalMeta.textContent = `Aktivno: RN ${rnLabel} · Primopredaja ${handoverLabel}`;
  }
}

function setWorkOrderTemplateModalOpen(isOpen = false, { placeholderKind = "" } = {}) {
  state.workOrderTemplateSettings.modalOpen = Boolean(isOpen);
  if (placeholderKind) {
    state.workOrderTemplateSettings.placeholderKind = normalizeWorkOrderTemplateKind(placeholderKind);
  }
  if (workOrderTemplateError) {
    workOrderTemplateError.textContent = "";
  }
  syncWorkOrderTemplateModal();
  if (isOpen) {
    requestAnimationFrame(() => {
      workOrderTemplatePanel?.querySelector(".offer-template-body")?.focus({ preventScroll: true });
    });
  }
}

function renderWorkOrderTemplateStrip() {
  if (!workOrderTemplateMeta || !workOrderTemplateOpenButton || !workOrderTemplatePlaceholdersButton) {
    return;
  }

  const rnTemplate = getSelectedWorkOrderTemplate("rn");
  const handoverTemplate = getSelectedWorkOrderTemplate("handover");
  const rnLabel = getWorkOrderTemplateDisplayName(rnTemplate, "rn");
  const handoverLabel = getWorkOrderTemplateDisplayName(handoverTemplate, "handover");
  const bits = [
    rnLabel ? `RN: ${rnLabel}` : "RN: nema predloška",
    handoverLabel ? `Primopredaja: ${handoverLabel}` : "Primopredaja: nema predloška",
  ];

  workOrderTemplateMeta.textContent = bits.join(" · ");
  workOrderTemplateOpenButton.disabled = false;
  workOrderTemplateOpenButton.title = getCanManageMasterData()
    ? "Uredi Word predloške za RN i primopredaju"
    : "Pregled predložaka i placeholdera";
  workOrderTemplatePlaceholdersButton.disabled = false;

  syncWorkOrderTemplateModal();
}

function buildWorkOrderTemplatePlaceholderText(kind = "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  const lines = [
    `SafeNexus ${config.title} placeholderi`,
    "",
    config.key === "handover"
      ? "U Word predlosku za gotovu specifikaciju stavi {{SPECIFIKACIJA}}. Loop {{#USLUGE_REDOVI}} koristi samo za rucno slaganje tablice."
      : "U Word predlosku koristi ove oznake. Za tablicne redove koristi Docxtemplater loop: {{#USLUGE_REDOVI}} ... {{/USLUGE_REDOVI}}.",
    "",
    ...config.placeholders.map(([key, description]) => `${key} - ${description}`),
  ];

  return lines.join("\r\n");
}

function downloadWorkOrderTemplatePlaceholders(kind = state.workOrderTemplateSettings.placeholderKind || "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  triggerBlobDownload(
    new Blob(["\ufeff", buildWorkOrderTemplatePlaceholderText(config.key)], { type: "text/plain;charset=utf-8" }),
    `${config.key === "handover" ? "primopredaja" : "rn"}-template-placeholderi.txt`,
  );
}

async function uploadWorkOrderTemplateFile(file, kind = "rn") {
  if (!(file instanceof File) || !getCanManageMasterData()) {
    return;
  }

  const config = getWorkOrderTemplateKindConfig(kind);
  const extension = String(file.name || "").split(".").pop()?.toLowerCase() || "";
  const isWordTemplate = ["docx", "dotx"].includes(extension);
  if (!isWordTemplate) {
    const message = `${config.title} mora biti .docx ili .dotx Word dokument.`;
    setSyncError(message);
    if (workOrderTemplateError) {
      workOrderTemplateError.textContent = message;
    }
    return;
  }

  const targetButtons = workOrderTemplateUploadButtons.filter((button) => (
    normalizeWorkOrderTemplateKind(button.dataset.workOrderTemplateUpload) === config.key
  ));
  targetButtons.forEach((button) => {
    button.disabled = true;
    button.classList.add("is-loading");
  });

  const success = await runMutation(async () => {
    const dataUrl = await readFileAsDataUrl(file, `Ne mogu učitati template ${file.name}.`);
    const titleBaseName = file.name.replace(/\.(docx|dotx)$/i, "");
    return apiRequest("/document-templates", {
      method: "POST",
      body: {
        title: `${config.titlePrefix} - ${titleBaseName}`,
        documentType: config.documentType,
        status: "active",
        description: config.description,
        outputFileName: config.outputFileName,
        referenceDocument: {
          fileName: file.name,
          fileType: file.type || "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
          fileSize: file.size || 0,
          dataUrl,
          updatedAt: new Date().toISOString(),
        },
        customFields: [],
        equipmentItems: [],
        sections: [],
      },
    });
  });

  if (success) {
    const uploadedTitle = `${config.titlePrefix} - ${file.name.replace(/\.(docx|dotx)$/i, "")}`;
    const uploadedTemplate = getWorkOrderTemplateEntries(config.key).find((template) => (
      String(template.title || "") === uploadedTitle
      || String(template.referenceDocument?.fileName || "") === String(file.name || "")
    ));
    state.workOrderTemplateSettings[config.selectedKey] = uploadedTemplate?.id ? String(uploadedTemplate.id) : "";
    state.workOrderTemplateSettings[config.fileNameKey] = file.name;
    state.workOrderTemplateSettings[config.updatedAtKey] = new Date().toISOString();
    persistWorkOrderTemplateSettings();
  }
  renderWorkOrderTemplateStrip();
  targetButtons.forEach((button) => {
    button.classList.remove("is-loading");
  });

  if (success) {
    setSyncError("");
    if (workOrderTemplateError) {
      workOrderTemplateError.textContent = "";
    }
  }
}

async function deleteSelectedWorkOrderTemplate(kind = "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  const selectedTemplate = getSelectedWorkOrderTemplate(config.key);
  const templateId = String(selectedTemplate?.id || "").trim();

  if (!templateId || !getCanManageMasterData()) {
    return;
  }

  const title = selectedTemplate.title || selectedTemplate.referenceDocument?.fileName || "RN template";
  if (!window.confirm(`Obrisati ${config.title.toLowerCase()} "${title}"?`)) {
    return;
  }

  const targetButtons = workOrderTemplateDeleteButtons.filter((button) => (
    normalizeWorkOrderTemplateKind(button.dataset.workOrderTemplateDelete) === config.key
  ));
  targetButtons.forEach((button) => {
    button.disabled = true;
    button.classList.add("is-loading");
  });

  const success = await runMutation(() => apiRequest(`/document-templates/${encodeURIComponent(templateId)}`, {
    method: "DELETE",
  }), null);

  if (success) {
    state.workOrderTemplateSettings[config.selectedKey] = "";
    state.workOrderTemplateSettings[config.fileNameKey] = "";
    state.workOrderTemplateSettings[config.updatedAtKey] = new Date().toISOString();
    persistWorkOrderTemplateSettings();
    renderDocumentTemplateModule();
    renderWorkOrderTemplateStrip();
    setSyncError("");
  }

  targetButtons.forEach((button) => {
    button.classList.remove("is-loading");
  });
}

function downloadSelectedWorkOrderTemplate(kind = "rn") {
  const config = getWorkOrderTemplateKindConfig(kind);
  const selectedTemplate = getSelectedWorkOrderTemplate(config.key);
  if (selectedTemplate?.referenceDocument) {
    triggerModuleAttachmentDownload(selectedTemplate.referenceDocument);
  }
}

async function saveGeneratedWorkOrderPdf(workOrderId = "", { refreshDocuments = true } = {}) {
  const normalizedId = String(workOrderId || "").trim();
  if (!normalizedId || workOrderPdfSaveInFlight.has(normalizedId)) {
    return false;
  }

  workOrderPdfSaveInFlight.add(normalizedId);

  try {
    const templateId = getSelectedWorkOrderTemplateId("rn");
    const payload = await apiRequest(`/work-orders/${encodeURIComponent(normalizedId)}/save-pdf`, {
      method: "POST",
      body: {
        ...(templateId ? { templateId } : {}),
        signatureSettings: getPdfSignatureExportSettings(),
      },
    });

    if (payload?.item) {
      upsertDocumentsExplorerWorkOrderDocuments([payload.item]);
      state.documentsExplorer.loaded = true;
    }

    if (refreshDocuments && String(state.workOrderDocuments.workOrderId || workOrderIdInput?.value || "") === normalizedId) {
      await loadWorkOrderDocuments(normalizedId);
    }

    renderNotifications();

    return true;
  } catch (error) {
    console.warn("Automatsko spremanje RN PDF-a nije uspjelo.", error);
    return false;
  } finally {
    workOrderPdfSaveInFlight.delete(normalizedId);
  }
}

function queueGeneratedWorkOrderPdfSave(workOrderId = "") {
  const normalizedId = String(workOrderId || "").trim();
  if (!normalizedId || !getCanEditOperationalData()) {
    return;
  }

  window.clearTimeout(workOrderPdfSaveTimers.get(normalizedId));
  workOrderPdfSaveTimers.set(normalizedId, window.setTimeout(() => {
    workOrderPdfSaveTimers.delete(normalizedId);
    void saveGeneratedWorkOrderPdf(normalizedId, { refreshDocuments: false });
  }, WORK_ORDER_PDF_AUTOSAVE_DELAY_MS));
}

async function downloadWorkOrderPdf(workOrder = {}, { saveFirst = false, useTemplate = true } = {}) {
  const workOrderId = String(workOrder?.id || "").trim();
  if (!workOrderId) {
    return false;
  }

  try {
    if (saveFirst) {
      await saveGeneratedWorkOrderPdf(workOrderId, { refreshDocuments: false });
    }
    const templateId = useTemplate ? getSelectedWorkOrderTemplateId() : "";
    const response = await apiBinaryRequest(`/work-orders/${workOrderId}/pdf`, {
      method: "POST",
      body: {
        ...(templateId ? { templateId } : {}),
        signatureSettings: getPdfSignatureExportSettings(),
      },
    });
    triggerBlobDownload(response.blob, response.fileName || `${sanitizeDocumentTemplateFileName(workOrder.workOrderNumber || "radni-nalog", "radni-nalog")}.pdf`);
    return true;
  } catch (error) {
    setSyncError(error?.message || "Ne mogu preuzeti RN PDF.");
    return false;
  }
}

async function openActiveWorkOrderDocumentationFromEditor() {
  const readiness = syncWorkOrderPdfAndRequiredFields();
  if (!readiness.ready) {
    workOrderError.textContent = `Popuni obavezna polja za dokumentaciju: ${readiness.missing.map((entry) => entry.label).join(", ")}.`;
    return;
  }

  try {
    let workOrderId = String(workOrderIdInput?.value || "").trim();
    if (!workOrderId) {
      await persistWorkOrderAutoSave({ immediate: true });
      workOrderId = String(workOrderIdInput?.value || "").trim();
    }

    if (!workOrderId) {
      throw new Error("RN se još sprema. Pokušaj ponovno za trenutak.");
    }

    clearWorkOrderDocumentSelection({ closeWizard: false });
    state.workOrderDocumentWizard.launchSource = "editor";
    state.workOrderDocumentWizard.selectedIds = new Set([workOrderId]);
    const workOrder = state.workOrders.find((item) => String(item.id) === workOrderId);
    const mode = getWorkOrderSelectionModeFromWorkOrders(workOrder ? [workOrder] : [{
      ...buildWorkOrderPayload(),
      id: workOrderId,
    }]);
    openWorkOrderDocumentWizard(mode, { launchSource: "editor" });
    workOrderError.textContent = "";
  } catch (error) {
    workOrderError.textContent = error?.message || "Ne mogu otvoriti izradu dokumentacije.";
  }
}

function findVerifiedWorkOrderDocument(documents = []) {
  return (Array.isArray(documents) ? documents : []).find((document) => (
    String(document.documentCategory || "").trim() === VERIFIED_WORK_ORDER_DOCUMENT_CATEGORY
  )) ?? null;
}

async function downloadVerifiedWorkOrderDocument(workOrder = {}, button = null) {
  const workOrderId = String(workOrder?.id || "").trim();
  if (!workOrderId) {
    return;
  }

  if (button instanceof HTMLButtonElement) {
    button.disabled = true;
    button.classList.add("is-loading");
    button.setAttribute("aria-busy", "true");
  }

  try {
    const payload = await apiRequest(`/work-orders/${workOrderId}/documents`);
    const document = findVerifiedWorkOrderDocument(payload.items ?? []);

    if (!document) {
      setSyncError(`Za RN ${workOrder.workOrderNumber || "bez broja"} još nema ovjerenog naloga.`);
      return;
    }

    triggerModuleAttachmentDownload(document);
    setSyncError("");
  } catch (error) {
    setSyncError(error?.message || "Ne mogu preuzeti ovjereni nalog.");
  } finally {
    if (button instanceof HTMLButtonElement) {
      button.disabled = false;
      button.classList.remove("is-loading");
      button.removeAttribute("aria-busy");
    }
  }
}

async function downloadActiveWorkOrderPdfFromEditor() {
  const readiness = syncWorkOrderPdfAndRequiredFields();
  if (!readiness.ready) {
    workOrderError.textContent = `Popuni obavezna polja za RN PDF: ${readiness.missing.map((entry) => entry.label).join(", ")}.`;
    return;
  }

  const mainScrollTop = workOrderEditorMain?.scrollTop ?? null;
  const activityScrollTop = workOrderActivityPanel?.scrollTop ?? null;

  if (workOrderDownloadPdfButton) {
    workOrderDownloadPdfButton.disabled = true;
    workOrderDownloadPdfButton.classList.add("is-loading");
    workOrderDownloadPdfButton.innerHTML = getWorkOrderIconMarkup("download");
    workOrderDownloadPdfButton.setAttribute("aria-label", "Pripremam PDF");
    workOrderDownloadPdfButton.setAttribute("aria-busy", "true");
    workOrderDownloadPdfButton.title = "Pripremam PDF...";
  }

  try {
    let workOrderId = String(workOrderIdInput?.value || "").trim();
    if (!workOrderId) {
      await persistWorkOrderAutoSave({ immediate: true });
      workOrderId = String(workOrderIdInput?.value || "").trim();
    }

    if (!workOrderId) {
      throw new Error("RN se još sprema. Pokušaj ponovno za trenutak.");
    }

    const workOrder = state.workOrders.find((item) => String(item.id) === workOrderId) ?? {
      ...buildWorkOrderPayload(),
      id: workOrderId,
      workOrderNumber: workOrderNumberPreview?.textContent?.replace(/^RN\s+/i, "") || "",
    };

    await saveGeneratedWorkOrderPdf(workOrderId, { refreshDocuments: false });
    await downloadWorkOrderPdf(workOrder, { saveFirst: false });
    workOrderError.textContent = "";
  } catch (error) {
    workOrderError.textContent = error?.message || "Ne mogu pripremiti RN PDF.";
  } finally {
    if (workOrderDownloadPdfButton) {
      workOrderDownloadPdfButton.classList.remove("is-loading");
      workOrderDownloadPdfButton.removeAttribute("aria-busy");
    }
    syncWorkOrderPdfAndRequiredFields();
    requestAnimationFrame(() => {
      if (workOrderEditorMain && mainScrollTop !== null) {
        workOrderEditorMain.scrollTop = mainScrollTop;
      }
      if (workOrderActivityPanel && activityScrollTop !== null) {
        workOrderActivityPanel.scrollTop = activityScrollTop;
      }
    });
  }
}

