function toggleWorkOrderDocumentSelection(workOrderId, forceValue = null) {
  const normalizedId = String(workOrderId || "");
  if (!normalizedId) {
    return;
  }

  const nextSelected = new Set(state.workOrderDocumentWizard.selectedIds ?? []);
  const shouldSelect = forceValue === null ? !nextSelected.has(normalizedId) : Boolean(forceValue);

  if (shouldSelect) {
    nextSelected.add(normalizedId);
  } else {
    nextSelected.delete(normalizedId);
  }

  state.workOrderDocumentWizard.selectedIds = nextSelected;
  state.workOrderBatch.message = "";
  state.workOrderBatch.tone = "";

  if (!shouldSelect) {
    delete state.workOrderDocumentWizard.overrides?.[normalizedId];
    delete state.workOrderDocumentWizard.isznrWorkEquipment?.[normalizedId];
    delete state.workOrderDocumentWizard.isznrWorkEnvironment?.[normalizedId];
  }

  if (state.workOrderDocumentWizard.selectedIds.size === 0) {
    state.workOrderDocumentWizard.step = "details";
    state.workOrderDocumentWizard.open = false;
  }

  updateWorkOrderDocumentSelectionChrome({
    visibleItems: getFilteredWorkOrders().slice(0, state.workOrderRenderLimit),
  });
  renderWorkOrderWorkspace();
  renderWorkOrderBatchBar();
  if (state.workOrderDocumentWizard.open) {
    renderWorkOrderDocumentWizard();
  }
  syncWorkOrderDocumentWizardModal();
}

function setVisibleWorkOrderDocumentSelection(selectAll = false) {
  const visibleItems = getFilteredWorkOrders().slice(0, state.workOrderRenderLimit);
  const nextSelected = new Set(state.workOrderDocumentWizard.selectedIds ?? []);

  visibleItems.forEach((item) => {
    const normalizedId = String(item.id);
    if (selectAll) {
      nextSelected.add(normalizedId);
    } else {
      nextSelected.delete(normalizedId);
      delete state.workOrderDocumentWizard.overrides?.[normalizedId];
      delete state.workOrderDocumentWizard.isznrWorkEquipment?.[normalizedId];
      delete state.workOrderDocumentWizard.isznrWorkEnvironment?.[normalizedId];
    }
  });

  state.workOrderDocumentWizard.selectedIds = nextSelected;
  state.workOrderBatch.message = "";
  state.workOrderBatch.tone = "";

  if (state.workOrderDocumentWizard.selectedIds.size === 0) {
    state.workOrderDocumentWizard.step = "details";
    state.workOrderDocumentWizard.open = false;
  }

  updateWorkOrderDocumentSelectionChrome({ visibleItems });
  renderWorkOrderWorkspace();
  renderWorkOrderBatchBar();
  if (state.workOrderDocumentWizard.open) {
    renderWorkOrderDocumentWizard();
  }
  syncWorkOrderDocumentWizardModal();
}

function renderWorkOrderDocumentWizardCompanyStrip(workOrders = []) {
  void workOrders;
}

function normalizeWorkOrderDocumentWorkEquipmentText(value = "") {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function isWorkOrderDocumentWorkEquipmentText(value = "") {
  const normalized = normalizeWorkOrderDocumentWorkEquipmentText(value);
  return normalized.includes("radna oprema")
    || normalized.includes("radne opreme")
    || normalized === "ro"
    || normalized.startsWith("ro ");
}

function isWorkOrderDocumentWorkEquipmentService(service = {}) {
  return [
    service?.name,
    service?.serviceName,
    service?.title,
    service?.serviceCode,
    service?.code,
    service?.shortCode,
    service?.serviceGroup,
  ].some((value) => isWorkOrderDocumentWorkEquipmentText(value));
}

function isWorkOrderDocumentPhysicalFactorsText(value = "") {
  const normalized = normalizeWorkOrderDocumentWorkEquipmentText(value);
  if (!normalized || isWorkOrderDocumentWorkEquipmentText(value)) {
    return false;
  }
  return normalized === "fc"
    || normalized.startsWith("fc ")
    || normalized.includes("fizikalni cimbenici")
    || normalized.includes("fizikalnih cimbenika")
    || normalized.includes("radni okolis fizikal")
    || normalized.includes("radnog okolisa fizikal");
}

function isWorkOrderDocumentPhysicalFactorsService(service = {}) {
  return [
    service?.name,
    service?.serviceName,
    service?.title,
    service?.serviceCode,
    service?.code,
    service?.shortCode,
    service?.serviceGroup,
  ].some((value) => isWorkOrderDocumentPhysicalFactorsText(value));
}

function shouldShowWorkOrderDocumentIsznrWorkEquipmentSection(workOrder = {}, serviceItems = []) {
  return Boolean(
    isWorkOrderDocumentWorkEquipmentText(workOrder?.serviceLine)
    || isWorkOrderDocumentWorkEquipmentText(workOrder?.displayService)
    || (Array.isArray(serviceItems) && serviceItems.some((service) => isWorkOrderDocumentWorkEquipmentService(service)))
  );
}

function getWorkOrderDocumentIsznrWorkEquipmentState(workOrderId = "") {
  const normalizedId = String(workOrderId || "").trim();
  if (!state.workOrderDocumentWizard.isznrWorkEquipment || typeof state.workOrderDocumentWizard.isznrWorkEquipment !== "object") {
    state.workOrderDocumentWizard.isznrWorkEquipment = {};
  }
  if (!state.workOrderDocumentWizard.isznrWorkEquipment[normalizedId]) {
    state.workOrderDocumentWizard.isznrWorkEquipment[normalizedId] = {
      loading: false,
      loaded: false,
      queued: false,
      error: "",
      message: "",
      items: [],
      options: [],
      registers: [],
      companyOib: "",
      fetchedAt: "",
      totalItems: null,
      recordsLimited: false,
      scope: "locations",
      locationKey: "",
      filter: "all",
      postDraft: null,
      selectedItemIds: [],
      manualEquipments: [],
      aiFiles: [],
      aiLoading: false,
      aiMessage: "",
      aiError: "",
      aiResult: null,
      aiModelTier: "standard",
      aiBatchMode: "batch",
      submitting: false,
      postResult: null,
    };
  }
  return state.workOrderDocumentWizard.isznrWorkEquipment[normalizedId];
}

const WORK_ORDER_DOCUMENT_RO_AI_MAX_FILES = 32;
const WORK_ORDER_DOCUMENT_RO_AI_MAX_BATCH_INLINE_FILES = 10;
const WORK_ORDER_DOCUMENT_RO_AI_BATCH_MODES = [
  {
    key: "batch",
    label: "Auto više opreme",
    description: "Web upload: slike idu kronološki, NexAI razdvaja više strojeva u više stavki.",
  },
  {
    key: "single",
    label: "Jedna oprema",
    description: "Sve dodane slike/PDF čitaj kao jedan stroj.",
  },
];

function normalizeWorkOrderDocumentRoAiBatchMode(value = "") {
  return String(value || "").trim() === "single" ? "single" : "batch";
}

function normalizeWorkOrderDocumentRoManualAssessmentItems(items = []) {
  return (Array.isArray(items) ? items : [])
    .map((item) => {
      const source = item && typeof item === "object" ? item : { label: item };
      const registerIri = String(source.registerIri || source.iri || source["@id"] || source.register || "").trim();
      const label = String(source.label || source.name || source.title || source.customContent || "").trim();
      const customContent = String(source.customContent || (!registerIri ? label : "") || "").trim();
      return {
        registerIri,
        label,
        customContent,
        meetsConditions: Number(source.meetsConditions) === 0 || String(source.meetsConditions).toLowerCase() === "false" ? 0 : 1,
        measuredValue: String(source.measuredValue || source.value || "").trim(),
      };
    })
    .filter((item) => item.registerIri || item.label || item.customContent || item.measuredValue)
    .slice(0, 80);
}

function normalizeWorkOrderDocumentRoIriList(values = []) {
  return normalizeAiConfigListLocal(values, 120)
    .map((value) => String(value || "").trim())
    .filter(Boolean);
}

function normalizeWorkOrderDocumentRoManualEquipment(equipment = {}, index = 0) {
  const source = equipment && typeof equipment === "object" ? equipment : {};
  const finalGradeValue = String(source.finalGrade || source.grade || "1").toLowerCase();
  const serialNumber = String(source.serialNumber || source.serial || "").trim();
  const inventoryNumber = String(source.inventoryNumber || source.inventory || "").trim();
  const name = String(source.name || source.equipmentName || source.type || "").trim();
  const manufacturer = String(source.manufacturer || source.producer || "").trim();
  const model = String(source.model || source.typeModel || source.type || "").trim();
  const attachments = (Array.isArray(source.attachments) ? source.attachments : [])
    .map((file) => ({
      fileName: String(file?.fileName || file?.name || "").trim(),
      fileType: String(file?.fileType || file?.type || file?.mimeType || "").trim(),
      fileSize: Number(file?.fileSize || file?.size || 0) || 0,
      dataUrl: String(file?.dataUrl || file?.contentDataUrl || "").trim(),
      description: String(file?.description || "").trim(),
    }))
    .filter((file) => file.fileName && file.dataUrl)
    .slice(0, 12);
  return {
    id: String(source.id || "").trim() || createClientSideId(`ro-manual-${index + 1}`),
    source: String(source.source || "ai").trim(),
    profileId: String(source.profileId || "").trim(),
    profileName: String(source.profileName || "").trim(),
    profileVariantName: String(source.profileVariantName || source.variantName || source.subcategory || "").trim(),
    profileMatchReason: String(source.profileMatchReason || "").trim(),
    confidence: normalizeAiConfidenceLevelLocal(source.confidence || "medium"),
    name,
    manufacturer,
    model,
    serialNumber,
    inventoryNumber,
    technicalData: String(source.technicalData || "").trim(),
    purposeDescription: String(source.purposeDescription || "").trim(),
    workspacePosition: String(source.workspacePosition || "").trim(),
    workingSubstancesAndRawMaterials: String(source.workingSubstancesAndRawMaterials || "").trim(),
    useAndMaintenance: String(source.useAndMaintenance || "").trim(),
    methodsProceduresAndNorms: String(source.methodsProceduresAndNorms || "").trim(),
    deficiencies: String(source.deficiencies || "").trim(),
    measuresToEliminateDeficiencies: String(source.measuresToEliminateDeficiencies || "").trim(),
    finalGrade: finalGradeValue === "0" || finalGradeValue.includes("ne zadovoljava") ? 0 : 1,
    mechanicalItems: normalizeWorkOrderDocumentRoManualAssessmentItems(source.mechanicalItems),
    electricalItems: normalizeWorkOrderDocumentRoManualAssessmentItems(source.electricalItems),
    hazardRegisterIris: normalizeWorkOrderDocumentRoIriList(source.hazardRegisterIris || source.hazards),
    harmfulnessRegisterIris: normalizeWorkOrderDocumentRoIriList(source.harmfulnessRegisterIris || source.harmfulnesses),
    strainRegisterIris: normalizeWorkOrderDocumentRoIriList(source.strainRegisterIris || source.strains),
    attachments,
    aiReason: String(source.reason || source.aiReason || "").trim(),
    sourceFile: String(source.sourceFile || "").trim(),
  };
}

function getReadyWorkOrderDocumentRoManualEquipments(entry = {}) {
  return (Array.isArray(entry.manualEquipments) ? entry.manualEquipments : [])
    .map((equipment, index) => normalizeWorkOrderDocumentRoManualEquipment(equipment, index))
    .filter((equipment) => equipment.name || equipment.manufacturer || equipment.model || equipment.serialNumber || equipment.inventoryNumber);
}

function getWorkOrderDocumentRoAiImageFiles(entry = {}) {
  return (Array.isArray(entry.aiFiles) ? entry.aiFiles : [])
    .filter((file) => file?.contentDataUrl && String(file.type || "").startsWith("image/"))
    .map((file, index) => ({ ...file, aiFileIndex: index + 1 }));
}

function normalizeWorkOrderDocumentRoAiIndexList(values = [], maxLength = 0) {
  const raw = Array.isArray(values) ? values : [values];
  const numbers = raw
    .flatMap((value) => String(value ?? "").split(/[,\s;]+/))
    .map((value) => Number.parseInt(String(value || "").trim(), 10))
    .filter((value) => Number.isFinite(value));
  const hasZero = numbers.some((value) => value === 0);
  return [...new Set(numbers
    .map((value) => (hasZero ? value + 1 : value))
    .filter((value) => value >= 1 && (!maxLength || value <= maxLength)))];
}

function getWorkOrderDocumentRoAiSuggestionImageIndexes(suggestion = {}, maxLength = 0) {
  const directIndexes = normalizeWorkOrderDocumentRoAiIndexList([
    ...(Array.isArray(suggestion.imageIndexes) ? suggestion.imageIndexes : []),
    ...(Array.isArray(suggestion.sourceImageIndexes) ? suggestion.sourceImageIndexes : []),
    ...(Array.isArray(suggestion.sourceFileIndexes) ? suggestion.sourceFileIndexes : []),
    ...(Array.isArray(suggestion.fileIndexes) ? suggestion.fileIndexes : []),
  ], maxLength);
  if (directIndexes.length) {
    return directIndexes;
  }
  const start = Number.parseInt(String(suggestion.groupStartIndex ?? suggestion.imageGroupStartIndex ?? ""), 10);
  const end = Number.parseInt(String(suggestion.groupEndIndex ?? suggestion.imageGroupEndIndex ?? ""), 10);
  if (Number.isFinite(start) && Number.isFinite(end)) {
    const from = Math.max(1, Math.min(start, end));
    const to = maxLength ? Math.min(Math.max(start, end), maxLength) : Math.max(start, end);
    return Array.from({ length: Math.max(0, to - from + 1) }, (_, index) => from + index);
  }
  return [];
}

function getWorkOrderDocumentRoAiSuggestionFileNames(suggestion = {}) {
  return normalizeAiConfigListLocal([
    ...(Array.isArray(suggestion.sourceFileNames) ? suggestion.sourceFileNames : []),
    ...(Array.isArray(suggestion.sourceFiles) ? suggestion.sourceFiles : []),
    ...(Array.isArray(suggestion.fileNames) ? suggestion.fileNames : []),
    ...(Array.isArray(suggestion.imageFileNames) ? suggestion.imageFileNames : []),
    suggestion.sourceFile,
  ], 24).map((value) => String(value || "").toLowerCase());
}

function getWorkOrderDocumentRoAiFilesForAttachments(entry = {}, equipmentIndex = 0, suggestion = {}) {
  const imageFiles = getWorkOrderDocumentRoAiImageFiles(entry);
  const selectedByIndex = new Set(getWorkOrderDocumentRoAiSuggestionImageIndexes(suggestion, imageFiles.length));
  const selectedByName = new Set(getWorkOrderDocumentRoAiSuggestionFileNames(suggestion));
  let selectedFiles = [];

  if (selectedByIndex.size || selectedByName.size) {
    selectedFiles = imageFiles.filter((file) => (
      selectedByIndex.has(file.aiFileIndex)
      || selectedByName.has(String(file.name || "").toLowerCase())
    ));
  }

  if (!selectedFiles.length) {
    selectedFiles = imageFiles.slice(equipmentIndex * 4, equipmentIndex * 4 + 4);
  }

  return selectedFiles
    .map((file) => ({
      fileName: String(file.name || "slika-radne-opreme").trim(),
      fileType: String(file.type || "image/jpeg").trim(),
      fileSize: Number(file.size || 0) || 0,
      dataUrl: String(file.contentDataUrl || "").trim(),
      description: file.aiFileIndex ? `NexAI upload za radnu opremu · slika ${file.aiFileIndex}` : "NexAI upload za radnu opremu",
    }));
}

function normalizeWorkEquipmentAiLearningKey(value = "") {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0111\u0110]/g, "d")
    .replace(/[\u0300-\u036f]/g, "")
    .toLocaleLowerCase("hr")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function findWorkEquipmentAiProfileForVariantLearning(profiles = [], suggestion = {}) {
  const normalizedProfiles = (Array.isArray(profiles) ? profiles : []).map((profile, index) => normalizeWorkEquipmentAiProfile(profile, index));
  const profileId = String(suggestion.profileId || "").trim();
  if (profileId) {
    const byId = normalizedProfiles.find((profile) => String(profile.id || "") === profileId);
    if (byId) return byId;
  }

  const profileName = normalizeWorkEquipmentAiLearningKey(suggestion.profileName || "");
  if (profileName) {
    const byName = normalizedProfiles.find((profile) => {
      const terms = [profile.name, ...profile.aliases].map(normalizeWorkEquipmentAiLearningKey).filter(Boolean);
      return terms.some((term) => term === profileName || profileName.includes(term) || term.includes(profileName));
    });
    if (byName) return byName;
  }

  const searchable = normalizeWorkEquipmentAiLearningKey([
    suggestion.name,
    suggestion.manufacturer,
    suggestion.model,
    suggestion.profileMatchReason,
    suggestion.reason,
  ].join(" "));
  if (searchable) {
    const scored = normalizedProfiles
      .map((profile) => {
        const terms = [profile.name, ...profile.aliases].map(normalizeWorkEquipmentAiLearningKey).filter((term) => term && term !== "osnovno");
        const score = terms.reduce((sum, term) => sum + (searchable.includes(term) ? 1 : 0), 0);
        return { profile, score };
      })
      .sort((a, b) => b.score - a.score);
    if (scored[0]?.score > 0) {
      return scored[0].profile;
    }
  }

  return normalizedProfiles.find((profile) => normalizeWorkEquipmentAiLearningKey(profile.name) === "osnovno")
    || normalizedProfiles[0]
    || normalizeWorkEquipmentAiProfile({ name: "Osnovno" });
}

function workEquipmentAiProfileHasVariant(profile = {}, variantName = "") {
  const key = normalizeWorkEquipmentAiLearningKey(variantName);
  if (!key) {
    return true;
  }
  return normalizeWorkEquipmentAiProfile(profile).variants.some((variant) => {
    const terms = [variant.name, ...variant.aliases].map(normalizeWorkEquipmentAiLearningKey).filter(Boolean);
    return terms.some((term) => term === key || term.includes(key) || key.includes(term));
  });
}

async function learnWorkEquipmentAiProfileVariantsFromResult(result = {}) {
  const suggestions = Array.isArray(result?.workEquipments)
    ? result.workEquipments
    : (Array.isArray(result?.equipments) ? result.equipments : []);
  if (!suggestions.length || !state.activeOrganizationId) {
    return 0;
  }
  const settings = getWorkEquipmentAiSettings();
  const profiles = (settings.profiles.length ? settings.profiles : createDefaultWorkEquipmentAiProfiles())
    .map((profile, index) => normalizeWorkEquipmentAiProfile(profile, index));
  let addedCount = 0;

  suggestions.forEach((suggestion) => {
    const variantName = String(suggestion?.profileVariantName || suggestion?.variantName || suggestion?.subcategory || "").trim();
    if (!variantName) {
      return;
    }
    const target = findWorkEquipmentAiProfileForVariantLearning(profiles, suggestion);
    const profileIndex = profiles.findIndex((profile) => String(profile.id || "") === String(target.id || ""));
    if (profileIndex < 0 || workEquipmentAiProfileHasVariant(profiles[profileIndex], variantName)) {
      return;
    }
    profiles[profileIndex] = normalizeWorkEquipmentAiProfile({
      ...profiles[profileIndex],
      variants: [
        ...profiles[profileIndex].variants,
        normalizeWorkEquipmentAiProfileVariant({
          name: variantName,
          aliases: suggestion.profileVariantAliases || "",
          appliesWhen: suggestion.profileMatchReason || suggestion.reason || "",
          extraInstruction: suggestion.profileVariantInstruction || "",
          source: "nexai",
          firstSeenAt: new Date().toISOString(),
        }, profiles[profileIndex].variants.length),
      ],
    }, profileIndex);
    addedCount += 1;
  });

  if (!addedCount) {
    return 0;
  }

  const nextSettings = normalizeWorkEquipmentAiSettings({
    ...settings,
    organizationId: state.activeOrganizationId,
    profiles,
  });
  state.workEquipmentAiSettings = nextSettings;
  settingsWorkEquipmentAiProfileDrafts = nextSettings.profiles;
  settingsWorkEquipmentAiDraftInitialized = true;
  try {
    await apiRequest("/work-equipment/ai-settings", {
      method: "POST",
      body: { settings: nextSettings },
    });
  } catch (error) {
    console.warn("RO NexAI variant learning was not persisted", error);
  }
  return addedCount;
}

function getWorkEquipmentAiRegisterPromptGroups(entry = {}) {
  const groups = [];
  const sourceGroups = Array.isArray(settingsWorkEquipmentAiRegisterGroups) && settingsWorkEquipmentAiRegisterGroups.length
    ? settingsWorkEquipmentAiRegisterGroups
    : (Array.isArray(entry?.registers) ? entry.registers : []);
  (Array.isArray(sourceGroups) ? sourceGroups : []).forEach((group) => {
    const items = (Array.isArray(group.items) ? group.items : [])
      .slice(0, 120)
      .map((item) => ({
        key: getWorkEquipmentAiRegisterKey(item, group),
        id: String(item.id || item["@id"] || item.iri || "").trim(),
        iri: String(item.iri || item["@id"] || "").trim(),
        label: String(item.label || item.name || item.title || "").trim(),
        code: String(item.code || "").trim(),
      }))
      .filter((item) => item.key || item.iri || item.label);
    if (items.length) {
      groups.push({
        group: String(group.group || "").trim(),
        label: String(group.label || "").trim(),
        path: String(group.path || "").trim(),
        items,
      });
    }
  });
  return groups;
}

