function getWorkOrderLearningTestRecommendations(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  const recommendationMap = new Map();
  const unmatchedTrainingWorkOrders = [];

  workOrders.forEach((workOrder) => {
    const serviceItems = getWorkOrderDocumentWizardResolvedServiceItems(workOrder);
    let hasTrainingTests = false;

    serviceItems.forEach((service) => {
      if (!service?.isTraining) {
        return;
      }
      const resolvedTestIds = getWorkOrderServiceLearningTestIds(service);
      if (resolvedTestIds.length === 0) {
        return;
      }

      hasTrainingTests = true;

      resolvedTestIds.forEach((testId) => {
        const test = (state.learningTests ?? []).find((item) => String(item.id) === String(testId));
        if (!test) {
          return;
        }

        const existing = recommendationMap.get(String(test.id)) ?? {
          test,
          workOrders: [],
          serviceLabels: new Set(),
        };

        if (!existing.workOrders.some((item) => String(item.id) === String(workOrder.id))) {
          existing.workOrders.push(workOrder);
        }

        const serviceLabel = service.name || service.serviceCode || "";
        if (serviceLabel) {
          existing.serviceLabels.add(serviceLabel);
        }

        recommendationMap.set(String(test.id), existing);
      });
    });

    if (!hasTrainingTests && serviceItems.some((service) => Boolean(service?.isTraining))) {
      unmatchedTrainingWorkOrders.push(workOrder);
    }
  });

  const recommendations = [...recommendationMap.values()]
    .map((item) => ({
      test: item.test,
      workOrders: sortWorkOrders(item.workOrders),
      serviceLabels: [...item.serviceLabels].sort((left, right) => left.localeCompare(right, "hr")),
    }))
    .sort((left, right) => String(left.test.title || "").localeCompare(String(right.test.title || ""), "hr"));

  return {
    recommendations,
    unmatchedTrainingWorkOrders,
  };
}

function getWorkOrderDocumentTemplateRecommendations(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  const recommendationMap = new Map();
  const unmatchedWorkOrders = [];

  workOrders.forEach((workOrder) => {
    const serviceItems = getWorkOrderDocumentWizardResolvedServiceItems(workOrder);
    let hasTemplate = false;

    serviceItems.forEach((service) => {
      const resolvedTemplateIds = getWorkOrderServiceTemplateIds(service);
      if (resolvedTemplateIds.length === 0) {
        return;
      }

      hasTemplate = true;

      resolvedTemplateIds.forEach((templateId) => {
        const template = getDocumentTemplateById(templateId);
        if (!template) {
          return;
        }

        const existing = recommendationMap.get(String(template.id)) ?? {
          template,
          workOrders: [],
          serviceLabels: new Set(),
        };

        if (!existing.workOrders.some((item) => String(item.id) === String(workOrder.id))) {
          existing.workOrders.push(workOrder);
        }

        const serviceLabel = service.name || service.serviceCode || "";
        if (serviceLabel) {
          existing.serviceLabels.add(serviceLabel);
        }

        recommendationMap.set(String(template.id), existing);
      });
    });

    if (!hasTemplate) {
      unmatchedWorkOrders.push(workOrder);
    }
  });

  const recommendations = [...recommendationMap.values()]
    .map((item) => ({
      template: item.template,
      workOrders: sortWorkOrders(item.workOrders),
      serviceLabels: [...item.serviceLabels].sort((left, right) => left.localeCompare(right, "hr")),
    }))
    .sort((left, right) => String(left.template.title || "").localeCompare(String(right.template.title || ""), "hr"));

  return {
    recommendations,
    unmatchedWorkOrders,
  };
}

function normalizeDocumentTemplateRuntimeSequenceEntries(entries = []) {
  return (Array.isArray(entries) ? entries : [])
    .map((entry) => ({
      templateId: String(entry?.templateId ?? "").trim(),
      workOrderId: String(entry?.workOrderId ?? "").trim(),
      templateTitle: String(entry?.templateTitle ?? "").trim(),
      workOrderNumber: String(entry?.workOrderNumber ?? "").trim(),
      companyName: String(entry?.companyName ?? "").trim(),
      locationName: String(entry?.locationName ?? "").trim(),
      objectId: String(entry?.objectId ?? "").trim(),
      objectName: String(entry?.objectName ?? "").trim(),
      objectSequence: Math.max(0, Number.parseInt(entry?.objectSequence, 10) || 0),
    }))
    .filter((entry) => (
      entry.templateId
      && entry.workOrderId
      && Boolean(getDocumentTemplateById(entry.templateId))
      && (state.workOrders ?? []).some((item) => String(item.id) === entry.workOrderId)
    ));
}

function getDocumentTemplateRuntimeSequenceEntries() {
  return normalizeDocumentTemplateRuntimeSequenceEntries(state.documentTemplateRuntime.sequenceEntries ?? []);
}

function getDocumentTemplateRuntimeSequenceState() {
  const entries = getDocumentTemplateRuntimeSequenceEntries();
  if (entries.length === 0) {
    return null;
  }

  const safeIndex = clampDocumentTemplateRuntimeSequenceIndex(state.documentTemplateRuntime.sequenceIndex, entries);
  const summaryIndex = entries.length;
  const isSummary = safeIndex === summaryIndex;

  return {
    entries,
    entry: isSummary ? entries[entries.length - 1] : entries[safeIndex],
    index: safeIndex,
    total: entries.length + 1,
    itemTotal: entries.length,
    summaryIndex,
    isSummary,
  };
}

function buildWorkOrderDocumentWizardSequence(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  const sequence = [];
  const seenPairs = new Set();

  sortWorkOrders(Array.isArray(workOrders) ? workOrders : []).forEach((workOrder) => {
    getWorkOrderDocumentWizardResolvedServiceItems(workOrder).forEach((service) => {
      getWorkOrderServiceTemplateIds(service).forEach((templateId) => {
        const template = getDocumentTemplateById(templateId);
        if (!template) {
          return;
        }

        const pairKey = `${String(workOrder.id)}::${String(template.id)}`;
        if (seenPairs.has(pairKey)) {
          return;
        }
        seenPairs.add(pairKey);

        sequence.push({
          templateId: String(template.id),
          workOrderId: String(workOrder.id),
          templateTitle: String(template.title || getDocumentTemplateTypeLabel(template.documentType) || "Zapisnik").trim(),
          workOrderNumber: String(workOrder.workOrderNumber || "Bez broja").trim(),
          companyName: String(workOrder.companyName || "").trim(),
          locationName: String(workOrder.locationName || "").trim(),
        });
      });
    });
  });

  return sequence;
}

function renderWorkOrderDocumentWizardSelectionSummary(workOrders = []) {
  if (!workOrderDocumentWizardSelectionSummary) {
    return;
  }

  const companyCount = new Set(workOrders.map((item) => String(item.companyName || "").trim()).filter(Boolean)).size;
  const templateCount = getWorkOrderDocumentTemplateRecommendations(workOrders).recommendations.length;
  const learningTestCount = getWorkOrderLearningTestRecommendations(workOrders).recommendations.length;
  const mode = state.workOrderDocumentWizard.mode || getSelectedWorkOrderDocumentMode() || "inspection";
  const isSingleWorkOrderFlow = state.workOrderDocumentWizard.launchSource === "editor" && workOrders.length === 1;
  const workOrder = isSingleWorkOrderFlow ? workOrders[0] : null;
  const summaryPills = isSingleWorkOrderFlow
    ? [
      workOrder?.workOrderNumber ? `RN ${workOrder.workOrderNumber}` : "Jedan RN",
      workOrder?.companyName || "Tvrtka nije odabrana",
      mode === "znr" ? `${learningTestCount} ispita` : `${templateCount} zapisnika`,
    ]
    : [
      `${workOrders.length} RN`,
      `${companyCount} tvrtki`,
      mode === "znr" ? `${learningTestCount} ispita` : `${templateCount} zapisnika`,
    ];

  workOrderDocumentWizardSelectionSummary.replaceChildren(...summaryPills.map((text) => {
    const pill = document.createElement("span");
    pill.className = "work-order-document-summary-pill";
    pill.textContent = text;
    return pill;
  }));
}

const WORK_ORDER_DOCUMENT_TRAINING_MODE_OPTIONS = Object.freeze([
  Object.freeze({
    value: "online_teams",
    label: "Online - Teams",
    helper: "Remote classroom session. No automatic test link is sent.",
    actionLabel: "Prepare Online - Teams",
    examMode: "online_teams",
    iconName: "team",
  }),
  Object.freeze({
    value: "online_test",
    label: "Online - Test",
    helper: "Sends test links by email and tracks remote completion.",
    actionLabel: "Send Online - Test",
    examMode: "online_test",
    iconName: "mail",
  }),
  Object.freeze({
    value: "live_paper",
    label: "Live - Paper",
    helper: "In-person training with paper exam evidence.",
    actionLabel: "Prepare Live - Paper",
    examMode: "live_paper",
    iconName: "document",
  }),
  Object.freeze({
    value: "live_application",
    label: "Live - Application",
    helper: "In-person training with the test completed in the app or by link.",
    actionLabel: "Prepare Live - Application",
    examMode: "live_application",
    iconName: "todo",
  }),
]);

function normalizeWorkOrderDocumentTrainingMode(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  const aliases = {
    online: "online_test",
    "online-test": "online_test",
    onlinetest: "online_test",
    test: "online_test",
    teams: "online_teams",
    "online-teams": "online_teams",
    onlineteams: "online_teams",
    live: "live_paper",
    paper: "live_paper",
    livepaper: "live_paper",
    "live-paper": "live_paper",
    live_app: "live_application",
    liveapp: "live_application",
    "live-app": "live_application",
    application: "live_application",
    liveapplication: "live_application",
    "live-application": "live_application",
  };
  const canonical = aliases[normalized] ?? normalized;
  return WORK_ORDER_DOCUMENT_TRAINING_MODE_OPTIONS.some((option) => option.value === canonical)
    ? canonical
    : "online_test";
}

function getWorkOrderDocumentTrainingModeOption(value = state.workOrderDocumentWizard.trainingMode) {
  const normalized = normalizeWorkOrderDocumentTrainingMode(value);
  return WORK_ORDER_DOCUMENT_TRAINING_MODE_OPTIONS.find((option) => option.value === normalized)
    ?? WORK_ORDER_DOCUMENT_TRAINING_MODE_OPTIONS[0];
}

function workOrderDocumentTrainingModeUsesLearningTest(mode = "") {
  const normalized = normalizeWorkOrderDocumentTrainingMode(mode);
  return normalized === "online_test" || normalized === "live_application";
}

function workOrderDocumentTrainingModeSendsEmail(mode = "") {
  return normalizeWorkOrderDocumentTrainingMode(mode) === "online_test";
}

function getLearningTestQuestionItems(test = {}) {
  return Array.isArray(test?.questionItems)
    ? test.questionItems.filter((question) => String(question?.id || "").trim())
    : [];
}

function normalizeLearningTestSecondsForUi(value, fallback = 60) {
  const numeric = Math.round(Number(value));
  const fallbackNumeric = Math.round(Number(fallback));
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return Math.max(5, Math.min(3600, Number.isFinite(fallbackNumeric) && fallbackNumeric > 0 ? fallbackNumeric : 60));
  }
  return Math.max(5, Math.min(3600, numeric));
}

function normalizeLearningTestPassPercentForUi(value, fallback = 80) {
  const numeric = Math.round(Number(value));
  const fallbackNumeric = Math.round(Number(fallback));
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return Math.max(1, Math.min(100, Number.isFinite(fallbackNumeric) && fallbackNumeric > 0 ? fallbackNumeric : 80));
  }
  return Math.max(1, Math.min(100, numeric));
}

function normalizeLearningTestQuestionLimitForUi(value, totalQuestions = 0) {
  const total = Math.max(0, Math.min(500, Math.round(Number(totalQuestions)) || 0));
  const numeric = Math.round(Number(value));
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return total;
  }
  return Math.max(1, Math.min(total || 1, numeric));
}

function formatDurationLabel(totalSeconds = 0) {
  const seconds = Math.max(0, Math.round(Number(totalSeconds) || 0));
  const minutes = Math.floor(seconds / 60);
  const remainder = seconds % 60;
  if (minutes <= 0) {
    return `${remainder} s`;
  }
  if (remainder === 0) {
    return `${minutes} min`;
  }
  return `${minutes} min ${remainder} s`;
}

function getWorkOrderDocumentTrainingQuestionConfigKey(test = {}, context = {}) {
  const testId = String(test?.id || "").trim();
  if (!testId) {
    return "";
  }
  const workOrderId = String(context?.workOrder?.id || context?.workOrderId || context?.assignment?.workOrderId || "").trim();
  const workOrderNumber = String(context?.workOrder?.workOrderNumber || context?.workOrderNumber || context?.assignment?.workOrderNumber || "").trim();
  const serviceId = String(
    context?.typeOption?.serviceId
      || context?.typeOption?.value
      || context?.typeOption?.serviceCode
      || context?.service?.serviceId
      || context?.service?.id
      || context?.service?.serviceCode
      || context?.serviceId
      || context?.assignment?.serviceId
      || context?.assignment?.serviceName
      || "",
  ).trim();
  return [workOrderId || workOrderNumber || "rn", serviceId || "service", testId].join("::");
}

function getWorkOrderDocumentTrainingQuestionConfig(test = {}, context = {}) {
  const testId = String(test?.id || "").trim();
  const configKey = getWorkOrderDocumentTrainingQuestionConfigKey(test, context);
  const questionItems = getLearningTestQuestionItems(test);
  const totalQuestions = questionItems.length;
  const stored = configKey
    ? (state.workOrderDocumentWizard.trainingQuestionConfig?.[configKey]
      ?? state.workOrderDocumentWizard.trainingQuestionConfig?.[testId]
      ?? {})
    : {};
  return {
    questionLimit: normalizeLearningTestQuestionLimitForUi(stored.questionLimit, totalQuestions),
    timePerQuestionSeconds: normalizeLearningTestSecondsForUi(
      stored.timePerQuestionSeconds,
      test.secondsPerQuestion ?? 60,
    ),
    passPercent: normalizeLearningTestPassPercentForUi(
      stored.passPercent,
      test.passPercent ?? 80,
    ),
  };
}

function setWorkOrderDocumentTrainingQuestionConfig(test = {}, patch = {}, context = {}) {
  const configKey = getWorkOrderDocumentTrainingQuestionConfigKey(test, context);
  if (!configKey) {
    return;
  }
  const current = getWorkOrderDocumentTrainingQuestionConfig(test, context);
  const questionItems = getLearningTestQuestionItems(test);
  const next = {
    questionLimit: normalizeLearningTestQuestionLimitForUi(
      patch.questionLimit ?? current.questionLimit,
      questionItems.length,
    ),
    timePerQuestionSeconds: normalizeLearningTestSecondsForUi(
      patch.timePerQuestionSeconds ?? current.timePerQuestionSeconds,
      test.secondsPerQuestion ?? 60,
    ),
    passPercent: normalizeLearningTestPassPercentForUi(
      patch.passPercent ?? current.passPercent,
      test.passPercent ?? 80,
    ),
  };
  state.workOrderDocumentWizard.trainingQuestionConfig = {
    ...(state.workOrderDocumentWizard.trainingQuestionConfig ?? {}),
    [configKey]: next,
  };
}

function getRandomLearningIndex(maxExclusive = 0) {
  const max = Math.max(0, Math.floor(Number(maxExclusive) || 0));
  if (max <= 1) {
    return 0;
  }
  const cryptoApi = globalThis.crypto;
  if (cryptoApi?.getRandomValues) {
    const values = new Uint32Array(1);
    cryptoApi.getRandomValues(values);
    return values[0] % max;
  }
  return Math.floor(Math.random() * max);
}

function pickRandomLearningQuestionIds(questionItems = [], questionLimit = 0) {
  const ids = getLearningTestQuestionItems({ questionItems })
    .map((question) => String(question.id || "").trim())
    .filter(Boolean);
  const shuffled = [...ids];
  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const swapIndex = getRandomLearningIndex(index + 1);
    [shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
  }
  const limit = normalizeLearningTestQuestionLimitForUi(questionLimit, shuffled.length);
  return shuffled.slice(0, limit || shuffled.length);
}

function buildLearningAssignmentQuestionSnapshot(test = {}, existingAssignment = null, context = {}) {
  const config = getWorkOrderDocumentTrainingQuestionConfig(test, {
    ...context,
    assignment: existingAssignment,
  });
  const questionItems = getLearningTestQuestionItems(test);
  const questionIds = questionItems.map((question) => String(question.id || "").trim()).filter(Boolean);
  const questionIdSet = new Set(questionIds);
  const existingIds = Array.isArray(existingAssignment?.selectedQuestionIds)
    ? existingAssignment.selectedQuestionIds.map((entry) => String(entry || "").trim()).filter((entry) => questionIdSet.has(entry))
    : [];
  if (String(existingAssignment?.status || "").toLowerCase() === "completed" && existingIds.length > 0) {
    const timePerQuestionSeconds = normalizeLearningTestSecondsForUi(
      existingAssignment?.timePerQuestionSeconds,
      config.timePerQuestionSeconds,
    );
    return {
      questionLimit: existingIds.length,
      selectedQuestionIds: existingIds,
      timePerQuestionSeconds,
      timeLimitSeconds: Math.max(
        existingIds.length * timePerQuestionSeconds,
        Math.round(Number(existingAssignment?.timeLimitSeconds) || 0),
      ),
      passPercent: normalizeLearningTestPassPercentForUi(existingAssignment?.passPercent, config.passPercent),
      passed: existingAssignment?.passed,
    };
  }
  const existingLimit = normalizeLearningTestQuestionLimitForUi(existingAssignment?.questionLimit, questionIds.length);
  const existingSeconds = normalizeLearningTestSecondsForUi(existingAssignment?.timePerQuestionSeconds, config.timePerQuestionSeconds);
  const shouldKeepExisting = existingIds.length > 0
    && (
      String(existingAssignment?.status || "").toLowerCase() === "completed"
      || (existingLimit === config.questionLimit && existingSeconds === config.timePerQuestionSeconds)
    );
  const selectedQuestionIds = shouldKeepExisting
    ? existingIds
    : pickRandomLearningQuestionIds(questionItems, config.questionLimit);
  const timePerQuestionSeconds = config.timePerQuestionSeconds;
  return {
    questionLimit: selectedQuestionIds.length,
    selectedQuestionIds,
    timePerQuestionSeconds,
    timeLimitSeconds: selectedQuestionIds.length * timePerQuestionSeconds,
    passPercent: config.passPercent,
  };
}

function getPeopleTrainingTypeOptionForWorkOrderService(service = {}) {
  const catalogItem = getServiceCatalogItemForWorkOrderService(service) ?? service;
  const serviceId = String(catalogItem?.id ?? service?.serviceId ?? service?.id ?? "").trim();
  const serviceCode = String(catalogItem?.serviceCode ?? service?.serviceCode ?? "").trim();
  const serviceName = String(catalogItem?.name ?? service?.name ?? service?.serviceName ?? serviceCode ?? "").trim();
  const options = getPeopleTrainingTypeOptions();
  const byServiceId = serviceId
    ? options.find((option) => String(option.serviceId || "").trim() === serviceId)
    : null;
  const byCode = serviceCode
    ? options.find((option) => String(option.serviceCode || option.shortLabel || "").trim().toLowerCase() === serviceCode.toLowerCase())
    : null;
  const byName = serviceName
    ? options.find((option) => normalizeLooseName(option.serviceName || option.label) === normalizeLooseName(serviceName))
    : null;
  if (byServiceId || byCode || byName) {
    return { ...(byServiceId ?? byCode ?? byName) };
  }

  const isSafeWork = isPeopleTrainingSafeWorkTypeCandidate({
    label: serviceName,
    serviceName,
    serviceCode,
    shortLabel: serviceCode,
  });
  return {
    value: isSafeWork ? "safe_work" : (serviceId ? `service:${serviceId}`.toLowerCase() : `service:${normalizeLooseName(serviceName || serviceCode || "training")}`),
    label: serviceName || serviceCode || "Osposobljavanje",
    shortLabel: serviceCode || buildPeopleTrainingShortLabel(serviceName || serviceCode, isSafeWork ? "ZNR" : "OS"),
    serviceId,
    serviceName: serviceName || serviceCode || "Osposobljavanje",
    serviceCode,
    linkedTemplateIds: Array.isArray(catalogItem?.linkedTemplateIds) ? catalogItem.linkedTemplateIds.map(String) : [],
    linkedTemplateTitles: Array.isArray(catalogItem?.linkedTemplateTitles) ? catalogItem.linkedTemplateTitles.map(String) : [],
    linkedLearningTestIds: Array.isArray(catalogItem?.linkedLearningTestIds) ? catalogItem.linkedLearningTestIds.map(String) : [],
    linkedLearningTestTitles: Array.isArray(catalogItem?.linkedLearningTestTitles) ? catalogItem.linkedLearningTestTitles.map(String) : [],
  };
}

function getWorkOrderDocumentTrainingServiceOptions(workOrder = {}) {
  const seen = new Set();
  return getWorkOrderDocumentWizardResolvedServiceItems(workOrder)
    .filter((service) => Boolean(service?.isTraining) || getWorkOrderServiceType(service) === "znr")
    .map(getPeopleTrainingTypeOptionForWorkOrderService)
    .filter((option) => {
      const key = String(option.value || option.serviceId || option.serviceCode || option.label || "").trim();
      if (!key || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

function isPeopleTrainingRecordAvailableForWorkOrder(record = {}) {
  const activity = String(record.activityStatus || record.status || "").trim().toLowerCase();
  if (record.archivedAt || record.deletedAt) {
    return false;
  }
  return !["inactive", "former", "left", "departure", "departed", "odlazak", "neaktivan"].includes(activity);
}

function getWorkOrderDocumentTrainingRecordsForWorkOrder(workOrder = {}) {
  const companyId = String(workOrder.companyId || "").trim();
  const companyName = normalizeLooseName(workOrder.companyName || "");
  const records = (state.peopleTrainingRecords ?? []).filter((record) => {
    if (!isPeopleTrainingRecordAvailableForWorkOrder(record)) {
      return false;
    }
    if (companyId && String(record.companyId || "").trim() === companyId) {
      return true;
    }
    return Boolean(companyName && normalizeLooseName(record.companyName || getPeopleTrainingCompany(record.companyId)?.name || "") === companyName);
  });
  return sortPersonTrainingRecords(records);
}

function getPeopleTrainingItemForTypeOption(record = {}, typeOption = {}) {
  const items = normalizePeopleTrainingItemsForUi(record.trainingItems);
  const serviceId = String(typeOption.serviceId || "").trim();
  const serviceCode = String(typeOption.serviceCode || typeOption.shortLabel || "").trim().toLowerCase();
  return items.find((item) => String(item.type || "") === String(typeOption.value || ""))
    ?? (serviceId ? items.find((item) => String(item.serviceId || "") === serviceId) : null)
    ?? (serviceCode ? items.find((item) => String(item.serviceCode || item.shortLabel || "").trim().toLowerCase() === serviceCode) : null)
    ?? {};
}

function getWorkOrderDocumentTrainingSelectionKey(row = {}) {
  return [
    row.workOrder?.id || row.workOrder?.workOrderNumber || "",
    row.record?.id || row.record?.oib || getPeopleTrainingRecordDisplayName(row.record),
    row.typeOption?.value || row.typeOption?.serviceId || row.typeOption?.serviceCode || "",
  ].map((value) => String(value || "").trim()).join("::");
}

function getWorkOrderDocumentTrainingRowProgress(row = {}) {
  const item = row.item ?? {};
  if (isPeopleTrainingItemPassed(item)) {
    return "completed";
  }
  const progress = getPeopleTrainingItemExamProgress(row.record, item);
  if (progress) {
    return progress;
  }
  if (item.status === "expired" || item.status === "expiring" || item.status === "missing") {
    return "missing";
  }
  return item.status || "missing";
}

function getWorkOrderDocumentTrainingProgressLabel(progress = "", item = {}) {
  const normalized = String(progress || "").trim().toLowerCase();
  if (normalized === "completed") {
    return "Položeno";
  }
  if (normalized === "failed") {
    return "Nije položio";
  }
  if (normalized === "in_progress") {
    return "U tijeku";
  }
  if (normalized === "pending") {
    return "Dodijeljeno";
  }
  if (item.status === "expired") {
    return "Isteklo";
  }
  if (item.status === "expiring") {
    return "Istječe";
  }
  if (item.status === "valid") {
    return "Važeće";
  }
  return "Nedostaje";
}

function isWorkOrderDocumentTrainingRowActionRequired(row = {}) {
  const progress = getWorkOrderDocumentTrainingRowProgress(row);
  const status = String(row.item?.status || "").trim().toLowerCase();
  return progress !== "completed" && status !== "valid" && status !== "not_required";
}

function getWorkOrderDocumentTrainingRows(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  return (Array.isArray(workOrders) ? workOrders : []).flatMap((workOrder) => {
    const serviceOptions = getWorkOrderDocumentTrainingServiceOptions(workOrder);
    const records = getWorkOrderDocumentTrainingRecordsForWorkOrder(workOrder);
    return records.flatMap((record) => serviceOptions.map((typeOption) => {
      const item = getPeopleTrainingItemForTypeOption(record, typeOption);
      const row = { workOrder, record, typeOption, item };
      return {
        ...row,
        key: getWorkOrderDocumentTrainingSelectionKey(row),
        progress: getWorkOrderDocumentTrainingRowProgress(row),
        recommended: isPeopleTrainingServiceRecommendedForRecord(typeOption, record),
      };
    }));
  });
}

function ensureWorkOrderDocumentTrainingSelection(rows = getWorkOrderDocumentTrainingRows()) {
  const selection = state.workOrderDocumentWizard.trainingSelection && typeof state.workOrderDocumentWizard.trainingSelection === "object"
    ? state.workOrderDocumentWizard.trainingSelection
    : {};
  const validKeys = new Set(rows.map((row) => row.key).filter(Boolean));
  Object.keys(selection).forEach((key) => {
    if (!validKeys.has(key)) {
      delete selection[key];
    }
  });
  rows.forEach((row) => {
    if (!row.key || Object.prototype.hasOwnProperty.call(selection, row.key)) {
      return;
    }
    selection[row.key] = isWorkOrderDocumentTrainingRowActionRequired(row) || row.recommended;
  });
  state.workOrderDocumentWizard.trainingSelection = selection;
  return selection;
}

function isWorkOrderDocumentTrainingRowSelected(row = {}) {
  const selection = ensureWorkOrderDocumentTrainingSelection();
  return Boolean(selection[row.key]);
}

function setWorkOrderDocumentTrainingRowSelected(row = {}, selected = false) {
  const selection = ensureWorkOrderDocumentTrainingSelection();
  if (row.key) {
    selection[row.key] = Boolean(selected);
  }
}

function applyWorkOrderDocumentTrainingSelectionPreset(mode = "needs_action") {
  const rows = getWorkOrderDocumentTrainingRows();
  const selection = ensureWorkOrderDocumentTrainingSelection(rows);
  rows.forEach((row) => {
    if (mode === "all") {
      selection[row.key] = true;
    } else if (mode === "clear") {
      selection[row.key] = false;
    } else if (mode === "recommended") {
      selection[row.key] = Boolean(row.recommended);
    } else {
      selection[row.key] = isWorkOrderDocumentTrainingRowActionRequired(row);
    }
  });
}

function getSelectedWorkOrderDocumentTrainingRows(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  const rows = getWorkOrderDocumentTrainingRows(workOrders);
  ensureWorkOrderDocumentTrainingSelection(rows);
  return rows.filter(isWorkOrderDocumentTrainingRowSelected);
}

function createWorkOrderDocumentTrainingModeButton(option = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "ghost-button work-order-document-training-mode-button";
  const activeMode = normalizeWorkOrderDocumentTrainingMode(state.workOrderDocumentWizard.trainingMode);
  button.classList.toggle("is-active", option.value === activeMode);
  button.innerHTML = `
    <span class="work-order-document-training-mode-icon">${getWorkOrderIconMarkup(option.iconName || "service")}</span>
    <span class="work-order-document-training-mode-copy">
      <strong>${escapeHtml(option.label)}</strong>
      <small>${escapeHtml(option.helper)}</small>
    </span>
  `;
  button.addEventListener("click", () => {
    state.workOrderDocumentWizard.trainingMode = option.value;
    renderWorkOrderDocumentWizard();
  });
  return button;
}

function getWorkOrderDocumentTrainingQuestionSettingGroups(rows = []) {
  const byKey = new Map();
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    getPeopleTrainingLinkedLearningTests(row?.typeOption).forEach((test) => {
      const key = getWorkOrderDocumentTrainingQuestionConfigKey(test, row);
      if (!key) {
        return;
      }
      if (!byKey.has(key)) {
        byKey.set(key, {
          key,
          test,
          workOrder: row.workOrder,
          typeOption: row.typeOption,
          rows: [],
        });
      }
      byKey.get(key).rows.push(row);
    });
  });
  return [...byKey.values()].sort((left, right) => (
    String(left.workOrder?.workOrderNumber || "").localeCompare(String(right.workOrder?.workOrderNumber || ""), "hr", { numeric: true })
    || String(left.typeOption?.label || left.typeOption?.serviceName || "").localeCompare(String(right.typeOption?.label || right.typeOption?.serviceName || ""), "hr")
    || String(left.test?.title || "").localeCompare(String(right.test?.title || ""), "hr")
  ));
}

function createWorkOrderDocumentTrainingQuestionSettingsPanel(rows = []) {
  const groups = getWorkOrderDocumentTrainingQuestionSettingGroups(rows);
  const panel = document.createElement("div");
  panel.className = "work-order-document-training-question-settings";

  const head = document.createElement("div");
  head.className = "work-order-document-training-question-settings-head";
  const title = document.createElement("strong");
  title.textContent = "Postavke ispita";
  const helper = document.createElement("span");
  helper.textContent = "Postavke ovise o RN-u, usluzi i testu. Pitanja se izvlače random za svakog polaznika.";
  head.append(title, helper);
  panel.append(head);

  if (groups.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Nema povezanih testova za odabrane RN/usluge.";
    panel.append(empty);
    return panel;
  }

  const list = document.createElement("div");
  list.className = "work-order-document-training-question-settings-list";
  groups.forEach((group) => {
    const test = group.test;
    const questionItems = getLearningTestQuestionItems(test);
    const config = getWorkOrderDocumentTrainingQuestionConfig(test, group);
    const totalSeconds = config.questionLimit * config.timePerQuestionSeconds;
    const row = document.createElement("article");
    row.className = "work-order-document-training-question-setting";

    const copy = document.createElement("div");
    copy.className = "work-order-document-training-question-setting-copy";
    const eyebrow = document.createElement("small");
    eyebrow.className = "work-order-document-training-question-setting-eyebrow";
    eyebrow.textContent = [
      group.workOrder?.workOrderNumber ? `RN ${group.workOrder.workOrderNumber}` : "RN",
      group.typeOption?.serviceCode || group.typeOption?.shortLabel || group.typeOption?.label || group.typeOption?.serviceName || "Usluga",
      `${group.rows.length} polaznika`,
    ].filter(Boolean).join(" · ");
    const name = document.createElement("strong");
    name.textContent = test.title || "Ispit";
    const meta = document.createElement("span");
    meta.textContent = `${questionItems.length} pitanja u bazi · ukupno ${formatDurationLabel(totalSeconds)} · prolaz ${config.passPercent}%`;
    copy.append(eyebrow, name, meta);

    const controls = document.createElement("div");
    controls.className = "work-order-document-training-question-setting-controls";
    const questionField = document.createElement("label");
    questionField.className = "field compact-field";
    const questionLabel = document.createElement("span");
    questionLabel.textContent = "Pitanja";
    const questionInput = document.createElement("input");
    questionInput.type = "number";
    questionInput.min = questionItems.length > 0 ? "1" : "0";
    questionInput.max = String(Math.max(questionItems.length, 1));
    questionInput.value = String(config.questionLimit);
    questionInput.addEventListener("change", () => {
      setWorkOrderDocumentTrainingQuestionConfig(test, { questionLimit: questionInput.value }, group);
      renderWorkOrderDocumentWizard();
    });
    questionField.append(questionLabel, questionInput);

    const secondsField = document.createElement("label");
    secondsField.className = "field compact-field";
    const secondsLabel = document.createElement("span");
    secondsLabel.textContent = "Sek. / pitanje";
    const secondsInput = document.createElement("input");
    secondsInput.type = "number";
    secondsInput.min = "5";
    secondsInput.max = "3600";
    secondsInput.step = "5";
    secondsInput.value = String(config.timePerQuestionSeconds);
    secondsInput.addEventListener("change", () => {
      setWorkOrderDocumentTrainingQuestionConfig(test, { timePerQuestionSeconds: secondsInput.value }, group);
      renderWorkOrderDocumentWizard();
    });
    secondsField.append(secondsLabel, secondsInput);

    const passField = document.createElement("label");
    passField.className = "field compact-field";
    const passLabel = document.createElement("span");
    passLabel.textContent = "Prolaz %";
    const passInput = document.createElement("input");
    passInput.type = "number";
    passInput.min = "1";
    passInput.max = "100";
    passInput.step = "1";
    passInput.value = String(config.passPercent);
    passInput.addEventListener("change", () => {
      setWorkOrderDocumentTrainingQuestionConfig(test, { passPercent: passInput.value }, group);
      renderWorkOrderDocumentWizard();
    });
    passField.append(passLabel, passInput);
    controls.append(questionField, secondsField, passField);

    row.append(copy, controls);
    list.append(row);
  });
  panel.append(list);
  return panel;
}

function renderWorkOrderDocumentWizardTrainingControlSection(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  if (!workOrderDocumentWizardCommonZnrSection) {
    return;
  }
  const rows = getWorkOrderDocumentTrainingRows(workOrders);
  const selection = ensureWorkOrderDocumentTrainingSelection(rows);
  const selectedRows = rows.filter((row) => Boolean(selection[row.key]));
  const uniquePeople = new Set(rows.map((row) => String(row.record?.id || row.record?.oib || getPeopleTrainingRecordDisplayName(row.record))).filter(Boolean));
  const uniqueServices = new Set(rows.map((row) => String(row.typeOption?.value || row.typeOption?.serviceId || row.typeOption?.label || "")).filter(Boolean));
  const linkedTestCount = selectedRows.reduce((count, row) => count + getPeopleTrainingLinkedLearningTests(row.typeOption).length, 0);

  const shell = document.createElement("div");
  shell.className = "work-order-document-training-cockpit";

  const head = document.createElement("div");
  head.className = "work-order-document-training-cockpit-head";
  const copy = document.createElement("div");
  const title = document.createElement("strong");
  title.textContent = "Osposobljavanje po RN-u";
  const helper = document.createElement("span");
  helper.textContent = "Odaberi ljude iz People modula, način provedbe i ispite koji idu na odabrane radne naloge.";
  copy.append(title, helper);
  const stats = document.createElement("div");
  stats.className = "work-order-document-training-stats";
  [
    [`${workOrders.length}`, "RN"],
    [`${uniquePeople.size}`, "osoba"],
    [`${selectedRows.length}`, "odabrano"],
    [`${linkedTestCount}`, "testova"],
  ].forEach(([value, label]) => {
    const item = document.createElement("span");
    item.innerHTML = `<strong>${escapeHtml(value)}</strong><small>${escapeHtml(label)}</small>`;
    stats.append(item);
  });
  head.append(copy, stats);

  const modes = document.createElement("div");
  modes.className = "work-order-document-training-mode-grid";
  modes.replaceChildren(...WORK_ORDER_DOCUMENT_TRAINING_MODE_OPTIONS.map(createWorkOrderDocumentTrainingModeButton));

  const questionSettings = createWorkOrderDocumentTrainingQuestionSettingsPanel(selectedRows);

  const quick = document.createElement("div");
  quick.className = "work-order-document-training-quick-actions";
  [
    ["Treba riješiti", "needs_action"],
    ["Predloženo", "recommended"],
    ["Sve", "all"],
    ["Očisti", "clear"],
  ].forEach(([label, preset]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "ghost-button";
    button.textContent = label;
    button.addEventListener("click", () => {
      applyWorkOrderDocumentTrainingSelectionPreset(preset);
      renderWorkOrderDocumentWizard();
    });
    quick.append(button);
  });
  const importButton = document.createElement("button");
  importButton.type = "button";
  importButton.className = "primary-button subtle";
  importButton.textContent = "Masovni import ljudi";
  importButton.addEventListener("click", () => {
    closeWorkOrderDocumentWizard();
    activateSidebarItem("people-training", { preserveGroup: false });
    window.requestAnimationFrame(() => {
      openPeopleTrainingImportDialog();
    });
  });
  quick.append(importButton);

  const notice = document.createElement("p");
  notice.className = `work-order-document-training-notice${rows.length ? "" : " is-warning"}`;
  notice.textContent = rows.length
    ? `Pronađeno je ${uniqueServices.size} usluga osposobljavanja. Status se preuzima iz People zapisa i online test assignmenta.`
    : "Za odabrane RN-ove nema ljudi iz te tvrtke ili nema ZNR usluga povezanih u List Of Services.";

  if (state.workOrderDocumentWizard.trainingLastMessage) {
    const message = document.createElement("p");
    message.className = "work-order-document-training-message";
    message.textContent = state.workOrderDocumentWizard.trainingLastMessage;
    shell.append(head, modes, questionSettings, quick, notice, message);
  } else {
    shell.append(head, modes, questionSettings, quick, notice);
  }

  workOrderDocumentWizardCommonZnrSection.replaceChildren(shell);
}

function buildWorkOrderDocumentWizardTrainingCard(workOrder = {}) {
  const card = document.createElement("article");
  card.className = "work-order-document-selection-card work-order-document-training-card";

  const serviceOptions = getWorkOrderDocumentTrainingServiceOptions(workOrder);
  const records = getWorkOrderDocumentTrainingRecordsForWorkOrder(workOrder);
  const rows = getWorkOrderDocumentTrainingRows([workOrder]);
  ensureWorkOrderDocumentTrainingSelection(rows);
  const selectedRows = rows.filter(isWorkOrderDocumentTrainingRowSelected);
  const completedRows = rows.filter((row) => getWorkOrderDocumentTrainingRowProgress(row) === "completed");
  const activeRows = rows.filter((row) => ["pending", "in_progress"].includes(getWorkOrderDocumentTrainingRowProgress(row)));

  const head = document.createElement("div");
  head.className = "work-order-document-selection-head";
  const copy = document.createElement("div");
  copy.className = "work-order-document-selection-copy";
  const title = document.createElement("strong");
  title.textContent = workOrder.workOrderNumber ? `RN ${workOrder.workOrderNumber}` : "RN bez broja";
  const meta = document.createElement("span");
  meta.className = "work-order-document-selection-subline";
  meta.textContent = [workOrder.companyName || "Bez tvrtke", workOrder.locationName || "Bez lokacije"]
    .filter(Boolean)
    .join(" · ");
  copy.append(title, meta);
  const chips = document.createElement("div");
  chips.className = "work-order-document-training-card-chips";
  [
    [`${records.length} osoba`, ""],
    [`${serviceOptions.length} usluga`, ""],
    [`${selectedRows.length} odabrano`, "is-selected"],
    [`${completedRows.length} položeno`, "is-completed"],
    [`${activeRows.length} aktivno`, "is-pending"],
  ].forEach(([label, className]) => {
    const chip = document.createElement("span");
    chip.className = ["soft-pill", className].filter(Boolean).join(" ");
    chip.textContent = label;
    chips.append(chip);
  });
  chips.append(createPeopleTrainingRnRecordButton({
    workOrder,
    rows: rows.map((row) => ({
      ...row,
      progress: getWorkOrderDocumentTrainingRowProgress(row),
    })),
  }));
  head.append(copy, chips);

  const serviceHeader = document.createElement("div");
  serviceHeader.className = "work-order-document-training-service-header";
  serviceHeader.style.setProperty("--training-service-count", String(Math.max(serviceOptions.length, 1)));
  const personHead = document.createElement("span");
  personHead.textContent = "Osoba";
  serviceHeader.append(personHead);
  serviceOptions.forEach((option) => {
    const service = document.createElement("span");
    service.textContent = option.serviceCode || option.shortLabel || buildPeopleTrainingShortLabel(option.label, "?");
    service.title = option.label || option.serviceName || service.textContent;
    serviceHeader.append(service);
  });

  const list = document.createElement("div");
  list.className = "work-order-document-training-person-list";

  if (serviceOptions.length === 0) {
    const empty = document.createElement("p");
    empty.className = "empty-state";
    empty.textContent = "Ovaj RN nema ZNR uslugu povezanu s List Of Services.";
    list.append(empty);
  } else if (records.length === 0) {
    const empty = document.createElement("p");
    empty.className = "empty-state";
    empty.textContent = "Nema People zapisa za ovu tvrtku. Dodaj ljude ili napravi masovni import prije dodjele ispita.";
    list.append(empty);
  } else {
    records.forEach((record) => {
      const row = document.createElement("article");
      row.className = "work-order-document-training-person-row";
      const identity = document.createElement("div");
      identity.className = "people-training-rn-person-identity";
      const name = document.createElement("strong");
      name.textContent = getPeopleTrainingRecordDisplayName(record);
      const metaLine = document.createElement("span");
      metaLine.textContent = [
        record.oib ? `OIB ${record.oib}` : "",
        record.jobTitle || record.workPlace || "",
        record.email || "",
      ].filter(Boolean).join(" · ") || "Bez dodatnih podataka";
      identity.append(name, metaLine);

      const cells = document.createElement("div");
      cells.className = "work-order-document-training-service-cells";
      cells.style.setProperty("--training-service-count", String(Math.max(serviceOptions.length, 1)));
      serviceOptions.forEach((typeOption) => {
        const item = getPeopleTrainingItemForTypeOption(record, typeOption);
        const rowModel = { workOrder, record, typeOption, item };
        rowModel.key = getWorkOrderDocumentTrainingSelectionKey(rowModel);
        rowModel.progress = getWorkOrderDocumentTrainingRowProgress(rowModel);
        rowModel.recommended = isPeopleTrainingServiceRecommendedForRecord(typeOption, record);
        const selected = isWorkOrderDocumentTrainingRowSelected(rowModel);
        const progressLabel = getWorkOrderDocumentTrainingProgressLabel(rowModel.progress, item);
        const cell = document.createElement("label");
        cell.className = `work-order-document-training-service-cell is-${rowModel.progress || "missing"}${selected ? " is-selected" : ""}${rowModel.recommended ? " is-recommended" : ""}`;
        cell.title = [
          typeOption.label || typeOption.serviceName || "Osposobljavanje",
          progressLabel,
          rowModel.recommended ? "AI/preporuka prema opisu radnog mjesta" : "",
        ].filter(Boolean).join(" · ");
        const input = document.createElement("input");
        input.type = "checkbox";
        input.checked = selected;
        input.addEventListener("change", () => {
          setWorkOrderDocumentTrainingRowSelected(rowModel, input.checked);
          renderWorkOrderDocumentWizard();
        });
        const code = document.createElement("strong");
        code.textContent = typeOption.serviceCode || typeOption.shortLabel || buildPeopleTrainingShortLabel(typeOption.label, "?");
        const status = document.createElement("span");
        status.textContent = progressLabel;
        cell.append(input, code, status);
        cells.append(cell);
      });

      row.append(identity, cells);
      list.append(row);
    });
  }

  const rail = document.createElement("div");
  rail.className = "work-order-document-selection-rail";
  const railLabel = document.createElement("span");
  railLabel.textContent = "Provedba";
  const railValue = document.createElement("strong");
  railValue.textContent = getWorkOrderDocumentTrainingModeOption().label;
  rail.append(railLabel, railValue);

  card.append(head, serviceHeader, list, rail);
  return card;
}

function summarizeWorkOrderDocumentTrainingAssignmentResult(selectedRows = []) {
  const uniquePeople = new Set(selectedRows.map((row) => String(row.record?.id || row.record?.oib || getPeopleTrainingRecordDisplayName(row.record))).filter(Boolean));
  const uniqueWorkOrders = new Set(selectedRows.map((row) => String(row.workOrder?.id || row.workOrder?.workOrderNumber || "")).filter(Boolean));
  const modeOption = getWorkOrderDocumentTrainingModeOption();
  const emailParts = [];
  if (peopleTrainingLastBulkOpenSummary.assignedTests > 0) {
    emailParts.push(`${peopleTrainingLastBulkOpenSummary.assignedTests} dodijeljenih ispita`);
  }
  if (peopleTrainingLastBulkOpenSummary.sentEmails > 0) {
    emailParts.push(`${peopleTrainingLastBulkOpenSummary.sentEmails} poslanih emailova`);
  }
  if (peopleTrainingLastBulkOpenSummary.skippedEmails > 0) {
    emailParts.push(`${peopleTrainingLastBulkOpenSummary.skippedEmails} bez emaila`);
  }
  if (peopleTrainingLastBulkOpenSummary.failedEmails > 0) {
    emailParts.push(`${peopleTrainingLastBulkOpenSummary.failedEmails} emailova nije poslano`);
  }
  return [
    `${modeOption.label}: pripremljeno ${selectedRows.length} polaganja za ${uniquePeople.size} osoba na ${uniqueWorkOrders.size} RN.`,
    emailParts.join(" · "),
  ].filter(Boolean).join(" ");
}

async function confirmWorkOrderDocumentWizardTrainingAssignments() {
  if (state.workOrderDocumentWizard.trainingBusy) {
    return;
  }
  const selectedWorkOrders = getAllSelectedWorkOrdersForDocumentWizard();
  const selectedRows = getSelectedWorkOrderDocumentTrainingRows(selectedWorkOrders);
  if (selectedRows.length === 0) {
    if (workOrderDocumentWizardError) {
      workOrderDocumentWizardError.textContent = "Odaberi barem jednu osobu i uslugu za osposobljavanje.";
    }
    return;
  }

  const modeOption = getWorkOrderDocumentTrainingModeOption();
  const examMode = normalizeWorkOrderDocumentTrainingMode(modeOption.examMode || modeOption.value || "online_test");
  const shouldCreateLearningAssignments = workOrderDocumentTrainingModeUsesLearningTest(examMode);
  const shouldSendEmails = workOrderDocumentTrainingModeSendsEmail(examMode);
  state.workOrderDocumentWizard.trainingBusy = true;
  state.workOrderDocumentWizard.trainingLastMessage = "";
  if (workOrderDocumentWizardError) {
    workOrderDocumentWizardError.textContent = "";
  }
  if (workOrderDocumentWizardNextButton) {
    workOrderDocumentWizardNextButton.disabled = true;
    workOrderDocumentWizardNextButton.textContent = "Pripremam...";
  }
  peopleTrainingLastBulkOpenSummary = {
    assignedTests: 0,
    sentEmails: 0,
    skippedEmails: 0,
    failedEmails: 0,
  };

  try {
    const rowsByWorkOrder = new Map();
    selectedRows.forEach((row) => {
      const key = String(row.workOrder?.id || row.workOrder?.workOrderNumber || "");
      if (!key) {
        return;
      }
      if (!rowsByWorkOrder.has(key)) {
        rowsByWorkOrder.set(key, { workOrder: row.workOrder, rows: [] });
      }
      rowsByWorkOrder.get(key).rows.push(row);
    });

    for (const group of rowsByWorkOrder.values()) {
      const entries = group.rows.map((row) => ({
        record: row.record,
        typeOption: row.typeOption,
        item: row.item,
      }));
      const linked = await linkPeopleTrainingEntriesToWorkOrder(entries, group.workOrder, { examMode });
      if (!linked) {
        throw new Error(`Nije uspjelo povezivanje osposobljavanja za RN ${group.workOrder?.workOrderNumber || ""}.`);
      }

      if (!shouldCreateLearningAssignments) {
        continue;
      }

      const byType = new Map();
      group.rows.forEach((row) => {
        const typeKey = String(row.typeOption?.value || row.typeOption?.serviceId || row.typeOption?.serviceCode || "");
        if (!typeKey) {
          return;
        }
        if (!byType.has(typeKey)) {
          byType.set(typeKey, { typeOption: row.typeOption, records: [] });
        }
        const bucket = byType.get(typeKey);
        if (!bucket.records.some((record) => String(record.id) === String(row.record?.id))) {
          bucket.records.push(row.record);
        }
      });

      for (const bucket of byType.values()) {
        const assigned = await assignPeopleTrainingLearningTestsForWorkOrder(bucket.records, bucket.typeOption, group.workOrder, {
          sendEmails: shouldSendEmails,
        });
        if (!assigned) {
          throw new Error(`Nije uspjela dodjela ispita za RN ${group.workOrder?.workOrderNumber || ""}.`);
        }
      }
    }

    state.workOrderDocumentWizard.trainingLastMessage = summarizeWorkOrderDocumentTrainingAssignmentResult(selectedRows);
    renderWorkOrderDocumentWizard();
    renderPeopleTrainingExamOverview();
  } catch (error) {
    console.error("Dodjela osposobljavanja iz RN wizarda nije uspjela.", error);
    if (workOrderDocumentWizardError) {
      workOrderDocumentWizardError.textContent = error?.message || "Dodjela osposobljavanja nije uspjela.";
    }
  } finally {
    state.workOrderDocumentWizard.trainingBusy = false;
    renderWorkOrderDocumentWizard();
  }
}

function buildWorkOrderDocumentWizardSelectionCard(workOrder) {
  const mode = state.workOrderDocumentWizard.mode || getSelectedWorkOrderDocumentMode() || "inspection";
  if (mode === "znr") {
    return buildWorkOrderDocumentWizardTrainingCard(workOrder);
  }

  const company = getCompany(workOrder.companyId);
  const locationDetail = [
    workOrder.locationName || "",
    workOrder.locationAddressSnapshot && workOrder.locationAddressSnapshot !== workOrder.locationName
      ? workOrder.locationAddressSnapshot
      : "",
  ].filter(Boolean).join(", ");
  const executors = getWorkOrderExecutors(workOrder);
  const resolvedServiceItems = getWorkOrderDocumentWizardResolvedServiceItems(workOrder);
  const relevantSignatureAreas = getWorkOrderRelevantSignatureAreas({
    ...workOrder,
    serviceItems: resolvedServiceItems,
  });
  const detailParts = [
    locationDetail || "Bez lokacije",
    workOrder.region || "",
  ].filter(Boolean);

  const card = document.createElement("article");
  card.className = "work-order-document-selection-card";

  const head = document.createElement("div");
  head.className = "work-order-document-selection-head";

  const copy = document.createElement("div");
  copy.className = "work-order-document-selection-copy";

  const title = document.createElement("strong");
  title.textContent = workOrder.workOrderNumber || "Bez broja";

  const meta = document.createElement("span");
  meta.className = "work-order-document-selection-subline";
  meta.textContent = detailParts.join(", ");

  copy.append(title, meta);
  if (executors.length > 0) {
    const executorRow = document.createElement("div");
    executorRow.className = "work-order-document-selection-executors";
    const executorStack = document.createElement("div");
    executorStack.className = "work-order-document-selection-executor-stack";

    executors.forEach((executor) => {
      executorStack.append(createWorkOrderMiniExecutor(executor, {
        className: "work-order-mini-executor work-order-document-selection-executor",
      }));
    });

    const executorLabel = document.createElement("span");
    executorLabel.className = "work-order-document-selection-executor-label";
    executorLabel.textContent = executors.join(", ");

    executorRow.append(executorStack, executorLabel);
    copy.append(executorRow);
  }
  head.append(copy);

  const chips = document.createElement("div");
  chips.className = "work-order-document-selection-chips";
  chips.append(
    createBadge(workOrder.region || "Bez regije", "document-template-meta-badge"),
    createBadge(workOrder.status || "Otvoreni RN", statusBadgeClass(workOrder.status)),
  );
  head.append(chips);

  const rail = document.createElement("div");
  rail.className = "work-order-document-selection-rail";
  const railLabel = document.createElement("span");
  railLabel.textContent = "Radni nalog";
  const railValue = document.createElement("strong");
  railValue.textContent = workOrder.workOrderNumber || "Bez broja";
  rail.append(railLabel, railValue);

  const grid = document.createElement("div");
  grid.className = "form-grid work-order-document-selection-grid";
  let learningSectionNode = null;

  const companyBlock = document.createElement("section");
  companyBlock.className = "work-order-document-selection-company-block field-span-full";

  const companyLogo = document.createElement("span");
  companyLogo.className = "work-order-document-selection-company-logo";
  renderCompanyLogo(companyLogo, {
    name: workOrder.companyName || company?.name || "Tvrtka",
    logoDataUrl: company?.logoDataUrl || company?.companyLogoDataUrl || "",
  });

  const companyCopy = document.createElement("div");
  companyCopy.className = "work-order-document-selection-company-copy";

  const companyTitle = document.createElement("strong");
  companyTitle.textContent = workOrder.companyName || company?.name || "Bez tvrtke";

  const companyDetails = document.createElement("span");
  companyDetails.textContent = describeCompanyPreview({
    headquarters: workOrder.headquarters || company?.headquarters || "",
    oib: workOrder.companyOib || company?.oib || "",
  }) || "Bez sjedišta i OIB-a";

  companyCopy.append(companyTitle, companyDetails);
  companyBlock.append(companyLogo, companyCopy);

  const rerenderWizard = () => {
    renderWorkOrderDocumentWizard();
  };

  const createCollapsibleSection = ({
    sectionKey,
    titleText,
    descriptionText = "",
    className = "",
    bodyClassName = "",
  }) => {
    const section = document.createElement("section");
    section.className = [className, "field-span-full", "work-order-document-selection-section-block"].filter(Boolean).join(" ");

    const headNode = document.createElement("div");
    headNode.className = "work-order-document-selection-section-head";

    const copyNode = document.createElement("div");
    copyNode.className = "work-order-document-selection-section-copy";

    const titleNode = document.createElement("strong");
    titleNode.textContent = titleText;
    copyNode.append(titleNode);

    if (descriptionText) {
      const descriptionNode = document.createElement("span");
      descriptionNode.textContent = descriptionText;
      copyNode.append(descriptionNode);
    }

    const toggleButton = document.createElement("button");
    toggleButton.type = "button";
    toggleButton.className = "ghost-button work-order-document-selection-section-toggle";

    const bodyNode = document.createElement("div");
    bodyNode.className = ["work-order-document-selection-section-body", bodyClassName].filter(Boolean).join(" ");

    const syncSectionState = () => {
      const isCollapsed = isWorkOrderDocumentWizardSectionCollapsed(workOrder.id, sectionKey);
      section.classList.toggle("is-collapsed", isCollapsed);
      bodyNode.hidden = isCollapsed;
      setWorkOrderDocumentWizardCollapseButtonState(toggleButton, isCollapsed, {
        collapsedLabel: `Prikaži ${titleText.toLowerCase()}`,
        expandedLabel: `Sakrij ${titleText.toLowerCase()}`,
      });
    };

    const toggleSection = () => {
      toggleWorkOrderDocumentWizardSectionCollapsed(workOrder.id, sectionKey);
      syncSectionState();
    };

    toggleButton.addEventListener("click", (event) => {
      event.stopPropagation();
      toggleSection();
    });

    headNode.addEventListener("click", (event) => {
      if (event.target instanceof HTMLElement && event.target.closest("button, a, input, textarea, select")) {
        return;
      }
      toggleSection();
    });

    headNode.append(copyNode, toggleButton);
    section.append(headNode, bodyNode);
    syncSectionState();
    return { section, bodyNode };
  };

  const createOverrideField = ({
    label,
    type = "text",
    fieldName,
    placeholder = "",
    spanFull = false,
    className = "",
    required = false,
    hintText = "",
    hintStatus = "",
  }) => {
    const field = document.createElement("label");
    field.className = [spanFull ? "field field-span-full" : "field", className].filter(Boolean).join(" ");

    const labelNode = document.createElement("span");
    labelNode.textContent = label;

    const input = document.createElement("input");
    const isDateField = type === "date";
    input.type = isDateField ? "text" : type;
    if (isDateField) {
      input.inputMode = "numeric";
      input.dataset.batchValueType = "date";
    }
    input.value = isDateField
      ? formatDateInputDisplayValue(getWorkOrderDocumentWizardSourceValue(workOrder.id, fieldName))
      : getWorkOrderDocumentWizardSourceValue(workOrder.id, fieldName);
    input.placeholder = isDateField ? formatDateInputDisplayValue(placeholder) || "dd.mm.yyyy" : placeholder;
    input.dataset.batchField = fieldName;
    input.dataset.batchWorkOrderId = String(workOrder.id);

    field.append(labelNode);
    if (hintText) {
      const inputWrap = document.createElement("div");
      inputWrap.className = "work-order-document-field-with-hint";
      const hint = document.createElement("small");
      hint.className = "work-order-document-weather-hint";
      hint.dataset.weatherHintStatus = hintStatus || "";
      hint.textContent = hintText;
      inputWrap.append(input, hint);
      field.append(inputWrap);
    } else {
      field.append(input);
    }
    if (required) {
      markWorkOrderDocumentWizardRequiredField(
        input,
        isDateField
          ? !normalizeDateInputValue(getWorkOrderDocumentWizardSourceValue(workOrder.id, fieldName))
          : !String(getWorkOrderDocumentWizardSourceValue(workOrder.id, fieldName) || "").trim(),
      );
    }
    return field;
  };

  const createPickerField = ({
    label,
    capability,
    signatureArea,
    multiple = false,
    fieldName,
    listFieldName = "",
    emptyLabel = "",
  }) => {
    const field = document.createElement("label");
    field.className = "field work-order-document-selection-picker-field";

    const labelNode = document.createElement("span");
    labelNode.textContent = label;

    const slot = document.createElement("div");
    slot.className = "work-order-document-wizard-control-slot work-order-document-selection-picker-slot";
    slot.append(createWorkOrderDocumentSignaturePersonPicker({
      capability,
      signatureArea,
      multiple,
      value: multiple
        ? getWorkOrderDocumentWizardSourceValues(workOrder.id, listFieldName)
        : getWorkOrderDocumentWizardSourceValue(workOrder.id, fieldName),
      emptyLabel,
      onChange: (nextValue, meta = {}) => {
        if (multiple) {
          const normalizedValues = normalizeQualifiedUserIdList(nextValue);
          setWorkOrderDocumentWizardOverride(workOrder.id, {
            [listFieldName]: normalizedValues,
            [fieldName]: normalizedValues[0] || "",
          });
        } else {
          setWorkOrderDocumentWizardOverride(workOrder.id, {
            [fieldName]: String(nextValue || "").trim(),
          });
        }

        if (meta.keepMenuOpen) {
          return;
        }

        rerenderWizard();
      },
    }));

    field.append(labelNode, slot);
    return field;
  };

  const basicSection = createCollapsibleSection({
    sectionKey: "basic",
    titleText: "Osnovno",
    descriptionText: "Datumi se preslikavaju iz zajedničkih podataka.",
    className: "work-order-document-selection-basic-block",
  });

  const basicGrid = document.createElement("div");
  basicGrid.className = "form-grid work-order-document-selection-basic-grid";
  basicGrid.append(
    createOverrideField({
      label: "Datum ispitivanja",
      type: "date",
      fieldName: "inspectionDate",
      placeholder: state.workOrderDocumentWizard.common.inspectionDate || "",
      className: "work-order-document-selection-date-field",
      required: true,
    }),
    createOverrideField({
      label: "Datum izdavanja",
      type: "date",
      fieldName: "issuedDate",
      placeholder: state.workOrderDocumentWizard.common.issuedDate || "",
      className: "work-order-document-selection-date-field",
      required: true,
    }),
  );
  basicSection.bodyNode.append(basicGrid);

  const servicesSection = createCollapsibleSection({
    sectionKey: "services",
    titleText: "Usluge",
    descriptionText: resolvedServiceItems.length > 0
      ? `${resolvedServiceItems.length} usluga, ${getWorkOrderCompletedServiceCount({ serviceItems: resolvedServiceItems })} odrađeno`
      : "Dodaj ili makni usluge za ovaj RN.",
    className: "work-order-document-selection-services",
  });

  const servicesToolbar = document.createElement("div");
  servicesToolbar.className = "work-order-document-selection-services-toolbar";
  servicesToolbar.append(createWorkOrderDocumentWizardServicePicker(workOrder));

  const serviceList = document.createElement("div");
  serviceList.className = "work-order-document-selection-service-list";

  if (resolvedServiceItems.length === 0) {
    const empty = document.createElement("span");
    empty.className = "work-order-document-selection-service-empty";
    empty.textContent = "Bez odabranih usluga";
    serviceList.append(empty);
  } else {
    resolvedServiceItems.forEach((service) => {
      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = `work-order-document-selection-service-chip${service.isCompleted ? " is-completed" : ""}`;
      chip.title = `Makni ${service.name || service.serviceCode || "uslugu"}`;
      chip.addEventListener("click", () => {
        const nextItems = getWorkOrderDocumentWizardResolvedServiceItems(workOrder)
          .filter((entry) => String(entry.serviceId || "") !== String(service.serviceId || ""));
        setWorkOrderDocumentWizardOverride(workOrder.id, {
          serviceItems: nextItems,
        });
        rerenderWizard();
      });

      const chipLabel = document.createElement("span");
      chipLabel.textContent = service.name || service.serviceCode || "Usluga";

      chip.append(chipLabel);

      if (service.serviceCode) {
        const code = document.createElement("small");
        code.textContent = service.serviceCode;
        chip.append(code);
      }

      const remove = document.createElement("span");
      remove.className = "work-order-document-selection-service-remove";
      remove.setAttribute("aria-hidden", "true");
      remove.textContent = "×";
      chip.append(remove);

      serviceList.append(chip);
    });
  }

  servicesSection.bodyNode.append(servicesToolbar, serviceList);

  const learningTestRecommendations = getWorkOrderLearningTestRecommendations([workOrder]).recommendations;
  const trainingContext = workOrder.trainingContext ?? {};
  const hasTrainingService = resolvedServiceItems.some((service) => Boolean(service?.isTraining));

  if (
    hasTrainingService
    || learningTestRecommendations.length > 0
    || trainingContext.name
    || trainingContext.role
    || trainingContext.phone
    || trainingContext.email
  ) {
    const learningSection = createCollapsibleSection({
      sectionKey: "learning",
      titleText: "Ispiti i osposobljavanje",
      descriptionText: learningTestRecommendations.length > 0
        ? `${learningTestRecommendations.length} povezanih grupa edukacije za ovaj RN.`
        : "Za uslugu osposobljavanja ovdje se nude povezani ispiti i kontakt odgovorne osobe klijenta.",
      className: "work-order-document-selection-learning-block",
    });

    if (trainingContext.name || trainingContext.role || trainingContext.phone || trainingContext.email) {
      const trainingAdmin = document.createElement("article");
      trainingAdmin.className = "work-order-document-learning-admin-card";

      const adminTitle = document.createElement("strong");
      adminTitle.textContent = trainingContext.name || "Odgovorna osoba klijenta";

      const adminMeta = document.createElement("span");
      adminMeta.textContent = [
        trainingContext.role || "",
        trainingContext.phone || "",
        trainingContext.email || "",
      ].filter(Boolean).join(" · ") || "Bez dodatnih podataka";

      trainingAdmin.append(adminTitle, adminMeta);
      learningSection.bodyNode.append(trainingAdmin);
    }

    const testList = document.createElement("div");
    testList.className = "work-order-document-learning-test-list";

    if (learningTestRecommendations.length === 0) {
      const empty = document.createElement("p");
      empty.className = "helper-copy module-copy";
      empty.textContent = hasTrainingService
        ? "Ova usluga je označena kao osposobljavanje, ali još nema povezanih ispita. Poveži ih u Organisation > List Of Services."
        : "Bez povezanih grupa edukacije.";
      testList.append(empty);
    } else {
      learningTestRecommendations.forEach((entry) => {
        const card = document.createElement("article");
        card.className = "work-order-document-learning-test-card";

        const head = document.createElement("div");
        head.className = "work-order-document-learning-test-head";

        const copy = document.createElement("div");
        copy.className = "work-order-document-learning-test-copy";

        const title = document.createElement("strong");
        title.textContent = entry.test.title || "Grupa edukacije";

        const meta = document.createElement("span");
        meta.textContent = [
          `${Array.isArray(entry.test.questionItems) ? entry.test.questionItems.length : 0} pitanja`,
          LEARNING_TEST_STATUS_OPTIONS.find((option) => option.value === entry.test.status)?.label || entry.test.status || "Skica",
        ].filter(Boolean).join(" · ");

        copy.append(title, meta);

        const badges = document.createElement("div");
        badges.className = "work-order-document-learning-test-badges";
        entry.serviceLabels.forEach((labelText) => {
          badges.append(createBadge(labelText, "document-template-meta-badge"));
        });

        head.append(copy, badges);

        const note = document.createElement("p");
        note.className = "work-order-document-learning-test-note";
        note.textContent = entry.test.description || "Grupa edukacije bit će ponuđena uz ovaj RN jer je vezana na uslugu osposobljavanja.";

        card.append(head, note);
        testList.append(card);
      });
    }

    learningSection.bodyNode.append(testList);
    learningSectionNode = learningSection.section;
  }

  const peopleSection = createCollapsibleSection({
    sectionKey: "people",
    titleText: "Ispitivači i odgovorne osobe",
    descriptionText: "Zajednički odabiri se automatski preslikaju. Ovdje prepravi samo ako ovaj RN odstupa.",
    className: "work-order-document-selection-person-block",
  });

  const peopleGrid = document.createElement("div");
  peopleGrid.className = "work-order-document-selection-person-grid";
  getWorkOrderDocumentSignatureAreaGroupsForAreas(relevantSignatureAreas).forEach((areaGroup) => {
    const fields = getWorkOrderDocumentSignaturePersonFields()
      .filter((definition) => definition.signatureArea === areaGroup.key);
    if (fields.length === 0) {
      return;
    }
    const areaCard = document.createElement("section");
    areaCard.className = "work-order-document-selection-person-area";
    areaCard.dataset.signatureArea = areaGroup.key;

    const areaTitle = document.createElement("strong");
    areaTitle.className = "work-order-document-selection-person-area-title";
    areaTitle.textContent = areaGroup.title;

    const areaFields = document.createElement("div");
    areaFields.className = "form-grid work-order-document-selection-person-area-grid";

    fields.forEach((definition) => {
      areaFields.append(createPickerField({
        label: definition.label || (definition.capability === "authorize" ? "Odgovorna osoba" : "Ispitivači"),
        capability: definition.capability,
        signatureArea: definition.signatureArea,
        multiple: Boolean(definition.multiple),
        listFieldName: definition.listFieldName || "",
        fieldName: definition.fieldName,
        emptyLabel: definition.emptyLabel,
      }));
    });

    areaCard.append(areaTitle, areaFields);
    peopleGrid.append(areaCard);
  });
  peopleSection.bodyNode.append(peopleGrid);

  const workOrderWeatherHintState = buildWorkOrderDocumentWeatherHintState(
    workOrder,
    getWorkOrderDocumentWizardWeatherDate(workOrder),
    {
      autoLoad: true,
      onLoaded: () => {
        if (state.workOrderDocumentWizard.open) {
          rerenderWizard();
        }
      },
    },
  );
  const getWeatherHintOptions = (fieldName) => {
    if (!WORK_ORDER_DOCUMENT_WEATHER_HINT_FIELDS.has(String(fieldName || "").trim())) {
      return {
        hintText: "",
        hintStatus: "",
      };
    }
    if (workOrderWeatherHintState.status === "ready") {
      return {
        hintText: getWorkOrderDocumentWeatherHintText(fieldName, workOrderWeatherHintState.summary),
        hintStatus: "ready",
      };
    }
    return {
      hintText: workOrderWeatherHintState.message || "",
      hintStatus: workOrderWeatherHintState.status || "",
    };
  };

  const environmentSection = createCollapsibleSection({
    sectionKey: "environment",
    titleText: "Uvjeti ispitivanja",
    descriptionText: state.workOrderDocumentWizard.common.randomizeEnvironment
      ? "Zajedničke vrijednosti su blago varirane po RN-u. Ovdje ih po potrebi ručno korigiraj."
      : "Zajednički uvjeti se ovdje automatski preslikaju. Mijenjaj samo ako ovaj RN odstupa.",
    className: "work-order-document-selection-env-block",
  });

  const envGrid = document.createElement("div");
  envGrid.className = "form-grid work-order-document-selection-env-grid";
  envGrid.append(
    createOverrideField({
      label: "Vanjska temperatura",
      fieldName: "outsideTemperature",
      placeholder: state.workOrderDocumentWizard.common.outsideTemperature || "npr. 18 °C",
      ...getWeatherHintOptions("outsideTemperature"),
    }),
    createOverrideField({
      label: "Relativna vlažnost",
      fieldName: "relativeHumidity",
      placeholder: state.workOrderDocumentWizard.common.relativeHumidity || "npr. 52 %",
      ...getWeatherHintOptions("relativeHumidity"),
    }),
    createOverrideField({
      label: "Brzina strujanja",
      fieldName: "airflowSpeed",
      placeholder: state.workOrderDocumentWizard.common.airflowSpeed || "npr. 0,4 m/s",
      ...getWeatherHintOptions("airflowSpeed"),
    }),
    createOverrideField({
      label: "Vrijeme",
      fieldName: "weather",
      placeholder: state.workOrderDocumentWizard.common.weather || "npr. sunčano",
      ...getWeatherHintOptions("weather"),
    }),
    createOverrideField({
      label: "Stanje tla",
      fieldName: "groundCondition",
      placeholder: state.workOrderDocumentWizard.common.groundCondition || "npr. suho",
      ...getWeatherHintOptions("groundCondition"),
    }),
    createOverrideField({
      label: "Otpor tla",
      fieldName: "groundResistance",
      placeholder: state.workOrderDocumentWizard.common.groundResistance || "npr. 5,2 Ω",
      ...getWeatherHintOptions("groundResistance"),
    }),
  );
  environmentSection.bodyNode.append(envGrid);

  grid.append(
    companyBlock,
    basicSection.section,
    servicesSection.section,
    ...(learningSectionNode ? [learningSectionNode] : []),
    peopleSection.section,
    environmentSection.section,
  );

  const footer = document.createElement("div");
  footer.className = "work-order-document-selection-footer";

  const helper = document.createElement("span");
  helper.className = "work-order-document-selection-helper";
  helper.textContent = "Status, izvršitelje, osobe, uvjete i rokove postavi gore, a ovdje prepravi samo ono što odstupa za ovaj RN.";

  const resetButton = document.createElement("button");
  resetButton.type = "button";
  resetButton.className = "ghost-button work-order-document-selection-reset";
  resetButton.textContent = "Vrati na zajednicko";
  resetButton.addEventListener("click", () => {
    delete state.workOrderDocumentWizard.overrides[String(workOrder.id)];
    rerenderWizard();
  });

  footer.append(helper, resetButton);
  card.append(head, grid, footer, rail);
  return card;
}

function renderWorkOrderDocumentWizardWorkOrders(workOrders = []) {
  if (!workOrderDocumentWizardWorkOrders) {
    return;
  }

  workOrderDocumentWizardWorkOrders.classList.remove("is-carousel");
  delete workOrderDocumentWizardWorkOrders.dataset.layout;
  if (workOrders.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Odaberi RN-ove u listi pa zatim otvori zapisnike.";
    workOrderDocumentWizardWorkOrders.replaceChildren(empty);
    return;
  }

  const cards = [];
  workOrders.forEach((workOrder) => {
    try {
      cards.push(buildWorkOrderDocumentWizardSelectionCard(workOrder));
    } catch (error) {
      console.error("Greška pri renderu RN kartice u wizardu.", {
        workOrderId: workOrder?.id,
        workOrderNumber: workOrder?.workOrderNumber,
        error,
      });
      const fallbackCard = document.createElement("article");
      fallbackCard.className = "work-order-document-selection-card";
      const title = document.createElement("strong");
      title.textContent = workOrder?.workOrderNumber || "Bez broja";
      const copy = document.createElement("p");
      copy.className = "helper-copy module-copy";
      copy.textContent = "RN se ne može prikazati zbog greške u podacima. Nastavi s ostalima ili osvježi stranicu.";
      fallbackCard.append(title, copy);
      cards.push(fallbackCard);
    }
  });

  if (workOrders.length <= 3) {
    const layout = workOrders.length === 1 ? "single" : workOrders.length === 2 ? "double" : "triple";
    workOrderDocumentWizardWorkOrders.dataset.layout = layout;
    workOrderDocumentWizardWorkOrders.replaceChildren(...cards);
    return;
  }

  workOrderDocumentWizardWorkOrders.dataset.layout = "carousel";
  workOrderDocumentWizardWorkOrders.classList.add("is-carousel");

  const shell = document.createElement("div");
  shell.className = "work-order-document-carousel-shell";

  const prevButton = document.createElement("button");
  prevButton.type = "button";
  prevButton.className = "ghost-button work-order-document-carousel-nav is-prev";
  prevButton.setAttribute("aria-label", "Prethodni radni nalozi");
  prevButton.textContent = "←";

  const nextButton = document.createElement("button");
  nextButton.type = "button";
  nextButton.className = "ghost-button work-order-document-carousel-nav is-next";
  nextButton.setAttribute("aria-label", "Sljedeći radni nalozi");
  nextButton.textContent = "→";

  const track = document.createElement("div");
  track.className = "work-order-document-carousel-track";
  track.append(...cards);

  const syncNavButtons = () => {
    const maxScrollLeft = Math.max(0, track.scrollWidth - track.clientWidth);
    prevButton.disabled = track.scrollLeft <= 4;
    nextButton.disabled = track.scrollLeft >= maxScrollLeft - 4;
  };

  prevButton.addEventListener("click", () => {
    track.scrollBy({ left: -Math.max(track.clientWidth * 0.92, 320), behavior: "smooth" });
  });
  nextButton.addEventListener("click", () => {
    track.scrollBy({ left: Math.max(track.clientWidth * 0.92, 320), behavior: "smooth" });
  });
  track.addEventListener("scroll", syncNavButtons, { passive: true });

  shell.append(prevButton, track, nextButton);
  workOrderDocumentWizardWorkOrders.replaceChildren(shell);
  requestAnimationFrame(syncNavButtons);
}

function reopenWorkOrderDocumentWizardFromRuntime() {
  if (state.workOrderDocumentWizard.selectedIds.size === 0) {
    return;
  }

  const runtimeReturnState = { ...(state.documentTemplateRuntime.returnState ?? {}) };
  closeDocumentTemplateEditor({ reset: false });
  if (runtimeReturnState.activeView) {
    state.activeView = runtimeReturnState.activeView;
    state.activeSidebarGroup = runtimeReturnState.activeSidebarGroup || state.activeSidebarGroup;
    state.activeSidebarItem = runtimeReturnState.activeSidebarItem || state.activeSidebarItem;
    state.activeModuleItem = runtimeReturnState.activeModuleItem || "";
    if (runtimeReturnState.activeView === "selfdash" && runtimeReturnState.activeWorkOrderViewMode) {
      state.activeWorkOrderViewMode = runtimeReturnState.activeWorkOrderViewMode;
    }
    renderActiveView();
    if (state.activeView === "module") {
      renderModuleView();
    }
  }
  state.workOrderDocumentWizard.open = true;
  state.workOrderDocumentWizard.step = "details";
  renderWorkOrderDocumentWizard();
  syncWorkOrderDocumentWizardModal();
  requestAnimationFrame(() => {
    const mode = state.workOrderDocumentWizard.mode || getSelectedWorkOrderDocumentMode() || "inspection";
    if (state.workOrderDocumentWizard.commonCollapsed) {
      workOrderDocumentWizardCommonToggleButton?.focus({ preventScroll: true });
      return;
    }
    if (mode === "znr") {
      const specialistSelect = workOrderDocumentWizardCommonSafetySpecialistSlot?.querySelector("select");
      specialistSelect?.focus({ preventScroll: true });
      return;
    }
    workOrderDocumentCommonInspectionDateInput?.focus({ preventScroll: true });
  });
}

function openDocumentTemplateFromWizard(
  templateId = "",
  workOrders = getAllSelectedWorkOrdersForDocumentWizard(),
  {
    sequenceEntries = null,
    sequenceIndex = -1,
    activeWorkOrderId = "",
    closeWizard = true,
    preserveRuntimeContext = false,
    keepCurrentRuntimeView = false,
  } = {},
) {
  const template = getDocumentTemplateById(templateId);
  if (!template) {
    return false;
  }

  const shouldUseModuleWorkspace = false;

  const isRuntimeEditorActuallyVisible = () => {
    if (!(documentTemplateEditorPanel instanceof HTMLElement) || !(documentTemplateEditorBackdrop instanceof HTMLElement)) {
      return false;
    }

    const panelStyle = window.getComputedStyle(documentTemplateEditorPanel);
    const backdropStyle = window.getComputedStyle(documentTemplateEditorBackdrop);
    const panelRect = documentTemplateEditorPanel.getBoundingClientRect();

    return Boolean(
      state.documentTemplateEditorOpen
      && isDocumentTemplateRuntimeFillMode()
      && !documentTemplateEditorPanel.hidden
      && !documentTemplateEditorBackdrop.hidden
      && documentTemplateEditorPanel.parentNode === document.body
      && documentTemplateEditorBackdrop.parentNode === document.body
      && documentTemplateEditorPanel.classList.contains("is-modal-open")
      && panelStyle.display !== "none"
      && panelStyle.visibility !== "hidden"
      && backdropStyle.display !== "none"
      && backdropStyle.visibility !== "hidden"
      && panelRect.width > 0
      && panelRect.height > 0
    );
  };

  const ensureRuntimeEditorVisible = ({ allowModuleFallback = true } = {}) => {
    syncDocumentTemplateEditorMountTarget(true);
    state.documentTemplateEditorOpen = true;
    syncDocumentTemplateEditorModal();

    let isVisible = isRuntimeEditorActuallyVisible();

    if (!isVisible) {
      syncDocumentTemplateEditorMountTarget(true);
      state.documentTemplateEditorOpen = true;
      syncDocumentTemplateEditorModal();
      isVisible = isRuntimeEditorActuallyVisible();
    }

    if (!isVisible && allowModuleFallback && shouldUseModuleWorkspace) {
      state.activeView = "module";
      state.activeModuleItem = "template-development";
      renderActiveView();
      renderModuleView();
      syncDocumentTemplateEditorMountTarget(true);
      state.documentTemplateEditorOpen = true;
      syncDocumentTemplateEditorModal();
      isVisible = isRuntimeEditorActuallyVisible();
    }

    return isVisible;
  };

  const reuseRuntimeContext = preserveRuntimeContext
    && hasDocumentTemplateRuntimeContext()
    && state.documentTemplateRuntime.source === "wizard";

  if (!reuseRuntimeContext) {
    setDocumentTemplateRuntimeFromWizard(workOrders);
  } else {
    const existingIds = new Set(
      (state.documentTemplateRuntime.workOrderIds ?? [])
        .map((value) => String(value ?? "").trim())
        .filter(Boolean),
    );
    const nextIds = [
      ...existingIds,
      ...(Array.isArray(workOrders) ? workOrders : [])
        .map((item) => String(item?.id ?? "").trim())
        .filter((value) => value && !existingIds.has(value)),
    ];
    state.documentTemplateRuntime.mode = "fill";
    state.documentTemplateRuntime.source = nextIds.length > 0 ? "wizard" : state.documentTemplateRuntime.source;
    state.documentTemplateRuntime.workOrderIds = nextIds;
  }

  applyWorkOrderDocumentWizardMeasurementEquipmentGroupDefaults(template, workOrders);

  if (!state.documentTemplateRuntime.returnState) {
    state.documentTemplateRuntime.returnState = {
      activeView: state.activeView,
      activeSidebarGroup: state.activeSidebarGroup,
      activeSidebarItem: state.activeSidebarItem,
      activeModuleItem: state.activeModuleItem,
      activeWorkOrderViewMode: state.activeWorkOrderViewMode,
    };
  }

  const normalizedSequenceEntries = sequenceEntries === null
    ? []
    : normalizeDocumentTemplateRuntimeSequenceEntries(sequenceEntries);
  state.documentTemplateRuntime.sequenceEntries = normalizedSequenceEntries;
  state.documentTemplateRuntime.sequenceIndex = normalizedSequenceEntries.length > 0
    ? clampDocumentTemplateRuntimeSequenceIndex(sequenceIndex, normalizedSequenceEntries)
    : -1;
  if (activeWorkOrderId) {
    state.documentTemplateRuntime.activeWorkOrderId = String(activeWorkOrderId || "").trim();
  }

  hydrateDocumentTemplateForm(template, {
    preserveRuntimeContext: true,
    runtimeMode: "fill",
    skipModuleNavigation: !shouldUseModuleWorkspace,
  });
  if (activeWorkOrderId) {
    setDocumentTemplateRuntimeActiveWorkOrder(activeWorkOrderId, { render: true });
  }

  const opened = ensureRuntimeEditorVisible({
    allowModuleFallback: true,
  });

  if (!opened) {
    return false;
  }

  if (closeWizard) {
    state.workOrderDocumentWizard.open = false;
    syncWorkOrderDocumentWizardModal();
  }
  saveDocumentTemplateRuntimeLocalDraft({ syncButton: true });
  return true;
}

function openDocumentTemplateRuntimeSequenceIndex(targetIndex, { closeWizard = false } = {}) {
  const sequenceState = getDocumentTemplateRuntimeSequenceState();
  if (!sequenceState) {
    return false;
  }

  const safeIndex = clampDocumentTemplateRuntimeSequenceIndex(targetIndex, sequenceState.entries);
  if (safeIndex === sequenceState.summaryIndex) {
    state.documentTemplateRuntime.sequenceIndex = safeIndex;
    state.documentTemplateRuntime.activePanel = "fields";
    syncDocumentTemplateEditorChrome();
    renderDocumentTemplateRuntimeContext();
    renderDocumentTemplateFieldRows();
    renderDocumentTemplatePreviewContent();
    saveDocumentTemplateRuntimeLocalDraft({ syncButton: true });
    return true;
  }

  const entry = sequenceState.entries[safeIndex];
  const selectedWorkOrders = getAllSelectedWorkOrdersForDocumentWizard();
  const runtimeWorkOrders = getDocumentTemplateRuntimeWorkOrders();
  const sourceWorkOrders = selectedWorkOrders.length > 0 ? selectedWorkOrders : runtimeWorkOrders;
  const opened = openDocumentTemplateFromWizard(entry.templateId, sourceWorkOrders, {
    sequenceEntries: sequenceState.entries,
    sequenceIndex: safeIndex,
    activeWorkOrderId: entry.workOrderId,
    closeWizard,
    preserveRuntimeContext: true,
    keepCurrentRuntimeView: true,
  });
  if (opened) {
    syncDocumentTemplateRuntimeObjectSelectionFromEntry(entry);
  }
  return opened;
}

function renderWorkOrderDocumentWizardTemplateDock(recommendations = [], workEquipmentWorkOrders = [], physicalFactorsWorkOrders = []) {
  if (!workOrderDocumentWizardTemplateDock) {
    return;
  }

  const pairs = recommendations.flatMap((entry) =>
    entry.workOrders.map((workOrder) => ({
      kind: "template",
      template: entry.template,
      workOrder,
    })),
  ).concat(
    (Array.isArray(workEquipmentWorkOrders) ? workEquipmentWorkOrders : []).map((workOrder) => ({
      kind: "workEquipment",
      template: null,
      workOrder,
    })),
    (Array.isArray(physicalFactorsWorkOrders) ? physicalFactorsWorkOrders : []).map((workOrder) => ({
      kind: "physicalFactors",
      template: null,
      workOrder,
    })),
  );

  workOrderDocumentWizardTemplateDock.hidden = pairs.length === 0;

  if (pairs.length === 0) {
    workOrderDocumentWizardTemplateDock.replaceChildren();
    return;
  }

  const shell = document.createElement("div");
  shell.className = "work-order-document-template-dock-shell";
  const dockCount = pairs.length;
  const minItemWidth = dockCount <= 3 ? 0 : dockCount <= 5 ? 132 : 148;
  workOrderDocumentWizardTemplateDock.style.width = "100%";
  workOrderDocumentWizardTemplateDock.style.maxWidth = "100%";
  shell.style.gridTemplateColumns = `repeat(${dockCount}, minmax(${minItemWidth}px, 1fr))`;

  pairs.forEach(({ kind, template, workOrder }) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `work-order-document-template-dock-item${template ? "" : " is-ro"}`;
    button.title = template
      ? `Otvori ${template.title || "zapisnik"} za RN ${workOrder.workOrderNumber || "bez broja"}`
      : kind === "physicalFactors"
        ? `Prikaži FC za RN ${workOrder.workOrderNumber || "bez broja"}`
        : `Prikaži RO za RN ${workOrder.workOrderNumber || "bez broja"}`;
    button.setAttribute("aria-label", button.title);
    button.addEventListener("click", () => {
      if (template) {
        openDocumentTemplateFromWizard(template.id, [workOrder]);
        return;
      }
      const key = String(workOrder?.id || workOrder?.workOrderNumber || "");
      const escapedKey = typeof CSS !== "undefined" && typeof CSS.escape === "function"
        ? CSS.escape(key)
        : key.replace(/"/g, "\\\"");
      const selector = kind === "physicalFactors"
        ? `[data-work-order-document-fc-card="${escapedKey}"]`
        : `[data-work-order-document-ro-card="${escapedKey}"]`;
      const target = workOrderDocumentWizardTemplateList?.querySelector(selector);
      target?.scrollIntoView({ behavior: "smooth", block: "center" });
    });

    const templateLabel = document.createElement("span");
    templateLabel.className = "work-order-document-template-dock-type";
    templateLabel.textContent = template
      ? String(template.title || getDocumentTemplateTypeLabel(template.documentType) || "Zapisnik").trim()
      : kind === "physicalFactors" ? "FC" : "RO";

    const workOrderLabel = document.createElement("strong");
    workOrderLabel.className = "work-order-document-template-dock-number";
    workOrderLabel.textContent = workOrder.workOrderNumber || "Bez broja";

    button.append(templateLabel, workOrderLabel);
    shell.append(button);
  });

  workOrderDocumentWizardTemplateDock.replaceChildren(shell);
}

function renderWorkOrderDocumentWizardTemplates(workOrders = []) {
  if (!workOrderDocumentWizardTemplateSummary || !workOrderDocumentWizardTemplateList) {
    return;
  }

  const mode = state.workOrderDocumentWizard.mode || getSelectedWorkOrderDocumentMode() || "inspection";
  if (mode === "znr") {
    const { recommendations, unmatchedTrainingWorkOrders } = getWorkOrderLearningTestRecommendations(workOrders);
    const selectedTestCount = recommendations.length;

    workOrderDocumentWizardTemplateSummary.replaceChildren();
    const summary = document.createElement("div");
    summary.className = "work-order-document-template-summary-card";
    summary.innerHTML = `
      <strong>${selectedTestCount} ispita</strong>
      <span>${selectedTestCount > 0 ? "Pronađeni su iz ZNR usluga na odabranim RN-ovima." : "Na odabranim RN-ovima još nema povezanih ispita."}</span>
    `;
    workOrderDocumentWizardTemplateSummary.append(summary);

    if (unmatchedTrainingWorkOrders.length > 0) {
      const warning = document.createElement("div");
      warning.className = "work-order-document-template-summary-card is-warning";
      warning.innerHTML = `
        <strong>${unmatchedTrainingWorkOrders.length} RN bez ispita</strong>
        <span>Poveži ispit u Organisation > List Of Services da bi se ovdje automatski pojavio.</span>
      `;
      workOrderDocumentWizardTemplateSummary.append(warning);
    }

    if (recommendations.length === 0) {
      const empty = document.createElement("p");
      empty.className = "helper-copy module-copy";
      empty.textContent = "Za odabrane RN-ove još nema povezanih ispita. Poveži ih na usluzi označenoj kao ZNR.";
      workOrderDocumentWizardTemplateList.replaceChildren(empty);
      renderWorkOrderDocumentWizardTemplateDock([]);
      return;
    }

    workOrderDocumentWizardTemplateList.replaceChildren(...recommendations.map((entry) => {
      const card = document.createElement("article");
      card.className = "work-order-document-template-card";

      const head = document.createElement("div");
      head.className = "work-order-document-template-card-head";

      const copy = document.createElement("div");
      copy.className = "work-order-document-template-card-copy";

      const title = document.createElement("strong");
      title.textContent = entry.test.title || "Grupa edukacije";

      const meta = document.createElement("span");
      meta.textContent = [
        `${entry.workOrders.length} RN`,
        `${Array.isArray(entry.test.questionItems) ? entry.test.questionItems.length : 0} pitanja`,
        LEARNING_TEST_STATUS_OPTIONS.find((option) => option.value === entry.test.status)?.label || entry.test.status || "Skica",
      ].filter(Boolean).join(" | ");

      copy.append(title, meta);

      const badges = document.createElement("div");
      badges.className = "work-order-document-template-card-badges";
      badges.append(createBadge("ZNR", "document-template-meta-badge"));
      entry.serviceLabels.forEach((label) => {
        badges.append(createBadge(label, "document-template-meta-badge"));
      });

      head.append(copy, badges);

      const workOrderList = document.createElement("div");
      workOrderList.className = "work-order-document-template-card-work-orders";
      entry.workOrders.forEach((workOrder) => {
        const chip = document.createElement("span");
        chip.className = "work-order-document-template-work-order-chip";
        chip.textContent = workOrder.workOrderNumber || "Bez broja";
        workOrderList.append(chip);
      });

      const note = document.createElement("span");
      note.className = "work-order-document-template-card-note";
      note.textContent = entry.test.description || "Ispit je povezan preko odabrane ZNR usluge.";

      card.append(head, workOrderList, note);
      return card;
    }));

    renderWorkOrderDocumentWizardTemplateDock([]);
    return;
  }

  const { recommendations, unmatchedWorkOrders } = getWorkOrderDocumentTemplateRecommendations(workOrders);
  const workEquipmentWorkOrders = getWorkOrderDocumentWizardWorkEquipmentCandidates(workOrders);
  const workEquipmentCards = workEquipmentWorkOrders.map((workOrder) =>
    createWorkOrderDocumentIsznrWorkEquipmentTemplateCard(workOrder),
  );
  const physicalFactorsWorkOrders = getWorkOrderDocumentWizardPhysicalFactorsCandidates(workOrders);
  const physicalFactorsCards = physicalFactorsWorkOrders.map((workOrder) =>
    createWorkOrderDocumentIsznrWorkEnvironmentTemplateCard(workOrder),
  );
  const selectedTemplateCount = recommendations.length;

  workOrderDocumentWizardTemplateSummary.replaceChildren();
  const summary = document.createElement("div");
  summary.className = "work-order-document-template-summary-card";
  summary.innerHTML = `
    <strong>${selectedTemplateCount} templatea${workEquipmentCards.length ? ` + ${workEquipmentCards.length} RO` : ""}${physicalFactorsCards.length ? ` + ${physicalFactorsCards.length} FC` : ""}</strong>
    <span>${selectedTemplateCount > 0 || workEquipmentCards.length > 0 || physicalFactorsCards.length > 0 ? "Pronađeni su iz usluga i IS ZNR konteksta na odabranim RN-ovima." : "Na odabranim RN-ovima još nema povezanih templatea."}</span>
  `;
  workOrderDocumentWizardTemplateSummary.append(summary);

  if (unmatchedWorkOrders.length > 0) {
    const warning = document.createElement("div");
    warning.className = "work-order-document-template-summary-card is-warning";
    warning.innerHTML = `
      <strong>${unmatchedWorkOrders.length} RN bez template veze</strong>
      <span>Povezi template u Organisation > List Of Services da bi se ovdje automatski pojavio.</span>
    `;
    workOrderDocumentWizardTemplateSummary.append(warning);
  }

  if (recommendations.length === 0 && workEquipmentCards.length === 0 && physicalFactorsCards.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Za odabrane RN-ove još nema povezanih templatea. Poveži ih na usluzi pa će se ovdje pojaviti po tipu zapisnika (SPR, TZIN, RO...).";
    workOrderDocumentWizardTemplateList.replaceChildren(empty);
    renderWorkOrderDocumentWizardTemplateDock([]);
    return;
  }

  const templateCards = recommendations.map((entry) => {
    const card = document.createElement("article");
    card.className = "work-order-document-template-card";

    const head = document.createElement("div");
    head.className = "work-order-document-template-card-head";

    const copy = document.createElement("div");
    copy.className = "work-order-document-template-card-copy";

    const title = document.createElement("strong");
    title.textContent = entry.template.title || "Template";

    const meta = document.createElement("span");
    meta.textContent = [
      getDocumentTemplateTypeLabel(entry.template.documentType),
      `${entry.workOrders.length} RN`,
      entry.template.referenceDocument?.fileName
        ? `${getDocumentTemplateReferenceLabel(entry.template.referenceDocument)} ref`
        : "Bez predloška",
    ].filter(Boolean).join(" | ");

    copy.append(title, meta);

    const badges = document.createElement("div");
    badges.className = "work-order-document-template-card-badges";
    badges.append(
      createDocumentTemplateStatusBadge(entry.template.status),
      createBadge(getDocumentTemplateTypeLabel(entry.template.documentType), "document-template-meta-badge"),
    );

    head.append(copy, badges);

    const services = document.createElement("div");
    services.className = "work-order-document-template-card-tags";
    if (entry.serviceLabels.length > 0) {
      entry.serviceLabels.forEach((label) => {
        services.append(createBadge(label, "document-template-meta-badge"));
      });
    }

    const workOrderList = document.createElement("div");
    workOrderList.className = "work-order-document-template-card-work-orders";
    entry.workOrders.forEach((workOrder) => {
      const chip = document.createElement("span");
      chip.className = "work-order-document-template-work-order-chip";
      chip.textContent = [
        workOrder.workOrderNumber || "Bez broja",
        getWorkOrderDocumentWizardSourceValue(workOrder.id, "inspectionDate")
          ? `Ispitivanje ${formatCompactDate(getWorkOrderDocumentWizardSourceValue(workOrder.id, "inspectionDate"))}`
          : "",
      ].filter(Boolean).join(" · ");
      workOrderList.append(chip);
    });

    const footer = document.createElement("div");
    footer.className = "work-order-document-template-card-footer";

    const note = document.createElement("span");
    note.textContent = entry.template.description || "Zapisnik je automatski povezan preko odabrane usluge.";

    const openButton = document.createElement("button");
    openButton.type = "button";
    openButton.className = "ghost-button";
    openButton.textContent = "Otvori zapisnik";
    openButton.addEventListener("click", () => {
      openDocumentTemplateFromWizard(entry.template.id, entry.workOrders);
    });

    footer.append(note, openButton);
    card.append(head, services, workOrderList, footer);
    return card;
  });

  workOrderDocumentWizardTemplateList.replaceChildren(...workEquipmentCards, ...physicalFactorsCards, ...templateCards);
  renderWorkOrderDocumentWizardTemplateDock(recommendations, workEquipmentWorkOrders, physicalFactorsWorkOrders);
}

function renderWorkOrderDocumentWizard() {
  const workOrders = getAllSelectedWorkOrdersForDocumentWizard();
  const mode = state.workOrderDocumentWizard.mode || getSelectedWorkOrderDocumentMode() || "inspection";
  const copy = getWorkOrderDocumentActionCopy(mode);
  const isInspectionMode = mode === "inspection";
  const isSingleWorkOrderFlow = state.workOrderDocumentWizard.launchSource === "editor" && workOrders.length === 1;
  const { recommendations } = isInspectionMode
    ? getWorkOrderDocumentTemplateRecommendations(workOrders)
    : { recommendations: [] };
  state.workOrderDocumentWizard.mode = mode;
  if (workOrderDocumentWizardPanel) {
    workOrderDocumentWizardPanel.classList.toggle("is-details-step", state.workOrderDocumentWizard.step === "details");
    workOrderDocumentWizardPanel.classList.toggle("is-templates-step", state.workOrderDocumentWizard.step === "templates");
    workOrderDocumentWizardPanel.classList.toggle("is-inspection-mode", mode === "inspection");
    workOrderDocumentWizardPanel.classList.toggle("is-znr-mode", mode === "znr");
    workOrderDocumentWizardPanel.classList.toggle("is-single-work-order-flow", isSingleWorkOrderFlow);
  }
  if (isInspectionMode) {
    ensureWorkOrderDocumentWizardPersonDefaults(workOrders);
  }

  if (workOrderDocumentWizardTitle) {
    workOrderDocumentWizardTitle.textContent = isSingleWorkOrderFlow
      ? (isInspectionMode ? "Izrada dokumentacije RN" : "Izrada ZNR dokumentacije RN")
      : copy.title;
  }
  if (workOrderDocumentWizardHelper) {
    const helperText = isSingleWorkOrderFlow
      ? "Prikazani su samo templatei povezani s uslugama na ovom RN-u. Nema masovne izrade."
      : (copy.wizardHelper || "");
    workOrderDocumentWizardHelper.textContent = helperText;
    workOrderDocumentWizardHelper.hidden = !helperText;
  }
  syncWorkOrderDocumentWizardCommonInputs();
  renderWorkOrderDocumentWizardCommonSection();

  if (workOrderDocumentWizardStepDetailsButton) {
    const isActive = state.workOrderDocumentWizard.step === "details";
    workOrderDocumentWizardStepDetailsButton.classList.toggle("is-active", isActive);
    workOrderDocumentWizardStepDetailsButton.setAttribute("aria-selected", isActive ? "true" : "false");
  }
  if (workOrderDocumentWizardStepTemplatesButton) {
    const isActive = state.workOrderDocumentWizard.step === "templates";
    workOrderDocumentWizardStepTemplatesButton.classList.toggle("is-active", isActive);
    workOrderDocumentWizardStepTemplatesButton.setAttribute("aria-selected", isActive ? "true" : "false");
  }
  if (workOrderDocumentWizardDetailsPanel) {
    workOrderDocumentWizardDetailsPanel.hidden = state.workOrderDocumentWizard.step !== "details";
  }
  if (workOrderDocumentWizardTemplatesPanel) {
    workOrderDocumentWizardTemplatesPanel.hidden = state.workOrderDocumentWizard.step !== "templates";
  }
  if (workOrderDocumentWizardPrevButton) {
    workOrderDocumentWizardPrevButton.hidden = state.workOrderDocumentWizard.step === "details" || !isInspectionMode;
    workOrderDocumentWizardPrevButton.textContent = isInspectionMode
      ? "Vrati se na osnovne podatke"
      : "Vrati se na pregled RN-ova";
  }
  if (workOrderDocumentWizardNextButton) {
    const trainingModeOption = getWorkOrderDocumentTrainingModeOption();
    workOrderDocumentWizardNextButton.textContent = isInspectionMode ? "Otvori zapisnik" : trainingModeOption.actionLabel;
    workOrderDocumentWizardNextButton.hidden = state.workOrderDocumentWizard.step === "templates";
    workOrderDocumentWizardNextButton.disabled = !isInspectionMode && state.workOrderDocumentWizard.trainingBusy;
  }

  renderWorkOrderDocumentWizardSelectionSummary(workOrders);
  renderWorkOrderDocumentWizardWorkOrders(workOrders);
  renderWorkOrderDocumentWizardTemplates(workOrders);
}

function closeOpenWorkOrderStatusMenus(except = null) {
  document.querySelectorAll(".work-item-status-dropdown.is-open, .work-order-calendar-executor-picker.is-open, .work-order-service-picker.is-open, .work-order-quick-picker.is-open").forEach((node) => {
    if (except && node === except) {
      return;
    }

    if (typeof node._closeMenu === "function") {
      node._closeMenu();
      return;
    }

    node.classList.remove("is-open");
    const trigger = node.querySelector(".work-item-status-trigger, .work-order-calendar-executor-trigger, .work-order-service-picker-trigger, .work-order-quick-picker-trigger");
    trigger?.setAttribute("aria-expanded", "false");
    if (node._menuPortal) {
      node._menuPortal.remove();
      node._menuPortal = null;
    }
  });
}

function createWorkOrderStatusDropdown(item, options = {}) {
  const { className = "" } = options;
  let currentStatusValue = item.status || "Otvoreni RN";
  const wrapper = document.createElement("div");
  wrapper.className = ["work-item-status-dropdown", className].filter(Boolean).join(" ");
  wrapper.dataset.preventRowOpen = "true";

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "work-item-status-trigger";
  trigger.dataset.status = slugifyValue(currentStatusValue);
  trigger.textContent = currentStatusValue;
  trigger.setAttribute("aria-haspopup", "menu");
  trigger.setAttribute("aria-expanded", "false");
  trigger.disabled = !getCanChangeAnyWorkOrderStatus(currentStatusValue);
  trigger.title = trigger.disabled ? "Nemas ovlastenje za promjenu statusa RN." : "";

  const setPendingState = (isPending) => {
    wrapper.classList.toggle("is-pending", isPending);
    trigger.disabled = isPending || !getCanChangeAnyWorkOrderStatus(currentStatusValue);
    trigger.title = trigger.disabled && !isPending ? "Nemas ovlastenje za promjenu statusa RN." : "";
  };

  const setCurrentStatus = (value) => {
    currentStatusValue = value || "Otvoreni RN";
    trigger.dataset.status = slugifyValue(currentStatusValue);
    trigger.textContent = currentStatusValue;
    trigger.disabled = !getCanChangeAnyWorkOrderStatus(currentStatusValue);
    trigger.title = trigger.disabled ? "Nemas ovlastenje za promjenu statusa RN." : "";
  };

  const positionMenuPortal = (menu) => {
    const triggerRect = trigger.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let left = triggerRect.left;
    let top = triggerRect.bottom + 8;

    if (left + menuRect.width > viewportWidth - 12) {
      left = Math.max(12, viewportWidth - menuRect.width - 12);
    }

    if (top + menuRect.height > viewportHeight - 12) {
      top = Math.max(12, triggerRect.top - menuRect.height - 8);
    }

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.minWidth = `${Math.round(triggerRect.width)}px`;
  };

  const openMenu = () => {
    closeOpenWorkOrderStatusMenus(wrapper);

    if (wrapper._menuPortal) {
      return;
    }

    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal";
    menu.setAttribute("role", "menu");

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => {
        event.stopPropagation();
      });
    });

    WORK_ORDER_STATUS_OPTIONS.forEach((option) => {
      const canUseOption = getCanSetWorkOrderStatus(currentStatusValue, option.value);
      const optionButton = document.createElement("button");
      optionButton.type = "button";
      optionButton.className = "work-item-status-option";
      optionButton.dataset.status = slugifyValue(option.value);
      optionButton.textContent = option.label;
      optionButton.setAttribute("role", "menuitem");
      optionButton.disabled = !canUseOption;
      optionButton.title = canUseOption ? "" : "Nemas ovlastenje za ovaj status.";

      optionButton.addEventListener("click", (event) => {
        event.stopPropagation();
        closeOpenWorkOrderStatusMenus();

        if (!getCanSetWorkOrderStatus(currentStatusValue, option.value) || option.value === currentStatusValue) {
          return;
        }

        const previousValue = currentStatusValue;
        setCurrentStatus(option.value);
        setPendingState(true);

        void runMutation(() => apiRequest(`/work-orders/${item.id}`, {
          method: "PATCH",
          body: { status: option.value },
        })).then((success) => {
          setPendingState(false);

          if (!success) {
            setCurrentStatus(previousValue);
            return;
          }

          const updatedItem = state.workOrders.find((entry) => String(entry.id) === String(item.id));
          setCurrentStatus(updatedItem?.status || option.value);
        });
      });

      menu.append(optionButton);
    });

    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    positionMenuPortal(menu);
    requestAnimationFrame(() => positionMenuPortal(menu));
  };

  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    wrapper.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });

  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (!getCanChangeAnyWorkOrderStatus(currentStatusValue)) {
      return;
    }
    if (wrapper.classList.contains("is-open")) {
      closeOpenWorkOrderStatusMenus();
      return;
    }
    openMenu();
  });

  wrapper.append(trigger);
  return wrapper;
}

function toggleWorkOrderDetails(workOrderId) {
  const normalizedId = String(workOrderId);

  if (state.expandedWorkOrderIds.has(normalizedId)) {
    state.expandedWorkOrderIds.delete(normalizedId);
  } else {
    state.expandedWorkOrderIds = new Set([normalizedId]);
  }

  renderCompactWorkOrdersList();
}

function renderGroupedWorkOrdersList() {
  const filtered = getFilteredWorkOrders();
  const visibleItems = filtered.slice(0, state.workOrderRenderLimit);
  const fullGroups = buildWorkOrderGroups(filtered);
  const visibleGroups = buildWorkOrderGroups(visibleItems);

  if (workOrdersHelper) {
    workOrdersHelper.textContent = "";
    workOrdersHelper.hidden = true;
  }

  workOrdersBody.replaceChildren(...visibleGroups.map((group) => {
    const section = document.createElement("section");
    section.className = "work-group";

    const groupHeader = document.createElement("div");
    groupHeader.className = "work-group-header";

    const headerLead = document.createElement("div");
    headerLead.className = "work-group-lead";

    const foldIcon = document.createElement("span");
    foldIcon.className = "work-group-fold";
    foldIcon.textContent = "▾";

    const statusBadge = createBadge(group.label, statusBadgeClass(group.status));
    statusBadge.classList.add("work-group-status-badge");

    const totalCount = fullGroups.find((entry) => entry.status === group.status)?.items.length ?? group.items.length;
    const count = document.createElement("span");
    count.className = "work-group-count";
    count.textContent = String(totalCount);

    headerLead.append(foldIcon, statusBadge, count);

    const groupActions = document.createElement("button");
    groupActions.type = "button";
    groupActions.className = "work-group-add-inline";
    groupActions.textContent = "+ Add task";
    groupActions.hidden = !getCanCreateWorkOrders();
    groupActions.addEventListener("click", () => {
      focusWorkOrderComposer({ status: group.status });
    });

    groupHeader.append(headerLead, groupActions);

    const columns = document.createElement("div");
    columns.className = "work-group-columns";

    [
      { title: "Osnovno", subtitle: "Broj RN · Status" },
      { title: "Klijent", subtitle: "Tvrtka · Sjedište · OIB" },
      { title: "Lokacija", subtitle: "Objekt · Regija · Koordinate" },
      { title: "Kontakt", subtitle: "Osoba · Email · Broj" },
      { title: "Usluga", subtitle: "Vrsta usluge · Odjel · Opis" },
      { title: "Akcije", subtitle: "Uredi · Obriši" },
    ].forEach((definition) => {
      const cell = document.createElement("div");
      cell.className = "work-group-column";

      const title = document.createElement("strong");
      title.className = "work-group-column-title";
      title.textContent = definition.title;

      const subtitle = document.createElement("span");
      subtitle.className = "work-group-column-subtitle";
      subtitle.textContent = definition.subtitle;

      cell.append(title, subtitle);
      columns.append(cell);
    });

    const body = document.createElement("div");
    body.className = "work-group-body";

    group.items.forEach((item) => {
      const row = document.createElement("article");
      row.className = "work-item-row";

      const createValueStack = (primary, secondary = "", tertiary = "", options = {}) => {
        const {
          badge = null,
          tertiaryClassName = "",
        } = options;
        const stack = document.createElement("div");
        stack.className = "work-item-value-stack";

        const primaryNode = document.createElement("strong");
        primaryNode.className = "work-item-value-primary";
        primaryNode.textContent = primary || "—";
        stack.append(primaryNode);

        if (secondary) {
          const secondaryNode = document.createElement("span");
          secondaryNode.className = "work-item-value-secondary";
          secondaryNode.textContent = secondary;
          stack.append(secondaryNode);
        }

        if (badge) {
          const badgeWrap = document.createElement("div");
          badgeWrap.className = "work-item-detail-badge-wrap";
          badgeWrap.append(badge);
          stack.append(badgeWrap);
        }

        if (tertiary) {
          const tertiaryNode = document.createElement("span");
          tertiaryNode.className = ["work-item-value-tertiary", tertiaryClassName].filter(Boolean).join(" ");
          tertiaryNode.textContent = tertiary;
          stack.append(tertiaryNode);
        }

        return stack;
      };

      const createInlinePills = (...values) => {
        const filteredValues = values.filter(Boolean);

        if (!filteredValues.length) {
          return null;
        }

        const wrap = document.createElement("div");
        wrap.className = "work-item-inline-pills";
        filteredValues.forEach((value) => {
          const pill = document.createElement("span");
          pill.className = "work-item-inline-pill";
          pill.textContent = value;
          wrap.append(pill);
        });
        return wrap;
      };

      const createCompactLocationLabel = (value = "") => {
        const text = String(value || "").trim();
        if (!text) {
          return "Bez lokacije";
        }

        const parts = text
          .split(",")
          .map((part) => part.trim())
          .filter(Boolean);

        if (!parts.length) {
          return text;
        }

        return parts.slice(0, 2).join(", ");
      };

      const createTagPill = (value) => {
        if (!value) {
          return null;
        }

        const pill = document.createElement("span");
        pill.className = "work-item-tag-pill";
        pill.textContent = value;
        applyWorkOrderTagTone(pill, value, { soft: true });
        return pill;
      };

      const createPriorityPill = (value) => {
        if (!value) {
          return null;
        }

        const pill = document.createElement("span");
        pill.className = "work-item-priority-pill";
        pill.dataset.priority = slugifyValue(value);

        const icon = document.createElement("span");
        icon.className = "work-item-priority-icon";
        icon.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2.5v11M4 3h6.2c.42 0 .67.47.43.81l-1.05 1.46a.75.75 0 0 0 0 .88l1.05 1.46c.24.34-.01.81-.43.81H4" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.4"/></svg>';

        const text = document.createElement("span");
        text.textContent = value;

        pill.append(icon, text);
        return pill;
      };

      const groupOne = document.createElement("div");
      groupOne.className = "work-item-cell work-item-cell-group";
      const rowStatusBadge = createBadge(item.status || "Bez statusa", statusBadgeClass(item.status));
      rowStatusBadge.classList.add("work-group-status-badge", "work-item-status-badge");
      groupOne.append(createValueStack(item.workOrderNumber || "Bez broja", "", "", { badge: rowStatusBadge }));

      const groupTwo = document.createElement("div");
      groupTwo.className = "work-item-cell work-item-cell-group";
      groupTwo.append(createValueStack(
        item.companyName || "Bez tvrtke",
        item.headquarters || "",
        item.companyOib ? `OIB ${item.companyOib}` : "",
      ));

      const groupThree = document.createElement("div");
      groupThree.className = "work-item-cell work-item-cell-group";
      groupThree.append(createValueStack(
        item.locationName || "Bez lokacije",
        item.coordinates || "",
      ));
      const locationPills = createInlinePills(item.region || "", item.coordinates ? "GPS" : "");
      if (locationPills) {
        groupThree.append(locationPills);
      }

      const groupFour = document.createElement("div");
      groupFour.className = "work-item-cell work-item-cell-group";
      groupFour.append(createValueStack(
        item.contactName || item.contactPhone || "Bez kontakta",
        item.contactEmail || "",
        item.contactPhone && item.contactPhone !== item.contactName ? item.contactPhone : "",
      ));

      const serviceItems = document.createElement("div");
      serviceItems.className = "work-item-cell work-item-cell-group";
      serviceItems.append(createValueStack(
        item.serviceLine || "Bez usluge",
        item.description || "",
        "",
      ));
      const servicePills = createInlinePills(
        item.department || "",
        item.tagText ? `#${item.tagText}` : "",
      );
      if (servicePills) {
        serviceItems.append(servicePills);
      }

      const actions = document.createElement("div");
      actions.className = "work-item-cell work-item-actions";
      actions.append(
        createActionButton("Uredi", "card-button card-button-light", () => hydrateWorkOrderForm(item)),
      );

      if (state.user?.role !== "user") {
        actions.append(
          createActionButton("Obriši", "card-button card-button-light card-danger", () => {
            if (!window.confirm(`Obrisati ${item.workOrderNumber}?`)) {
              return;
            }

            void runMutation(() => apiRequest(`/work-orders/${item.id}`, { method: "DELETE" }));
          }),
        );
      }

      row.append(groupOne, groupTwo, groupThree, groupFour, serviceItems, actions);
      body.append(row);
    });

    const addRow = document.createElement("button");
    addRow.type = "button";
    addRow.className = "work-group-add-row";
    addRow.textContent = "+ Add task";
    addRow.hidden = !getCanCreateWorkOrders();
    addRow.addEventListener("click", () => {
      focusWorkOrderComposer({ status: group.status });
    });

    section.append(groupHeader, columns, body, addRow);
    return section;
  }));

  workOrdersEmpty.hidden = filtered.length !== 0;

  if (filtered.length === 0) {
    workOrdersLoadState.hidden = true;
    workOrdersLoadState.textContent = "";
    return;
  }

  workOrdersLoadState.hidden = false;
  workOrdersLoadState.textContent = visibleItems.length < filtered.length
    ? `Prikazano ${visibleItems.length} od ${filtered.length} RN. Skrolaj dalje za jo?.`
    : `Prikazano svih ${filtered.length} RN.`;
}

function createCompactLocationLabel(value = "") {
  const text = String(value || "").trim();
  if (!text) {
    return "Bez lokacije";
  }

  const parts = text
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean);

  if (!parts.length) {
    return text;
  }

  return parts.slice(0, 2).join(", ");
}

function createWorkOrderQuickControl(labelText, control) {
  const wrap = document.createElement("div");
  wrap.className = "work-order-quick-cell";
  const label = document.createElement("label");
  label.textContent = labelText;
  wrap.append(label, control);
  return wrap;
}

function createWorkOrderQuickInput(name, placeholder = "", type = "text") {
  const input = document.createElement("input");
  input.name = name;
  input.type = type;
  input.placeholder = placeholder;
  input.autocomplete = "off";
  return input;
}

function createWorkOrderQuickSelect(name, options = [], selectedValue = "") {
  const select = document.createElement("select");
  select.name = name;
  replaceSelectOptions(select, options, selectedValue);
  return select;
}

function createWorkOrderQuickDateInput(name, placeholder = "dd.mm.yyyy") {
  const wrap = document.createElement("div");
  wrap.className = "work-order-quick-date-control";

  const input = createWorkOrderQuickInput(name, placeholder, "text");
  input.inputMode = "numeric";
  input.pattern = "[0-9.\\-/\\s]*";
  input.title = "Upiši datum, npr. 12112025 za 12.11.2025.";

  const picker = document.createElement("input");
  picker.type = "date";
  picker.className = "work-order-quick-native-date";
  picker.tabIndex = -1;
  picker.setAttribute("aria-hidden", "true");

  const button = document.createElement("button");
  button.type = "button";
  button.className = "work-order-quick-date-button";
  button.innerHTML = getWorkOrderIconMarkup("dates");
  button.setAttribute("aria-label", "Odaberi datum");
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    picker.value = normalizeDateInputValue(input.value);
    if (typeof picker.showPicker === "function") {
      picker.showPicker();
      return;
    }
    picker.focus({ preventScroll: true });
  });

  picker.addEventListener("change", () => {
    input.value = formatDateInputDisplayValue(picker.value);
    input.dispatchEvent(new Event("change", { bubbles: true }));
  });

  input.addEventListener("blur", () => {
    const normalizedValue = normalizeDateInputValue(input.value);
    input.value = formatDateInputDisplayValue(normalizedValue || input.value);
    picker.value = normalizedValue;
  });

  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      const normalizedValue = normalizeDateInputValue(input.value);
      input.value = formatDateInputDisplayValue(normalizedValue || input.value);
      picker.value = normalizedValue;
    }
  });

  wrap.append(input, button, picker);
  return wrap;
}

function readWorkOrderQuickJsonValue(formData, name, fallback = []) {
  const rawValue = String(formData.get(name) || "").trim();
  if (!rawValue) {
    return fallback;
  }

  try {
    const parsed = JSON.parse(rawValue);
    return Array.isArray(parsed) ? parsed : fallback;
  } catch {
    return fallback;
  }
}

function createWorkOrderQuickPicker({
  name,
  placeholder = "Odaberi",
  searchPlaceholder = "Traži...",
  emptyText = "Nema rezultata.",
  getOptions = () => [],
  matchesOption = () => true,
  getOptionValue = (option) => String(option?.value || option?.id || ""),
  getOptionLabel = (option) => String(option?.label || option?.name || option?.value || ""),
  getOptionMeta = () => "",
  getSelectedLabel = (items) => `${items.length} odabrano`,
  normalizeSelected = (items) => items,
  serializeSelected = (items) => items,
  renderOptionLeading = null,
} = {}) {
  const wrapper = document.createElement("div");
  wrapper.className = "work-order-quick-picker";

  const hiddenInput = document.createElement("input");
  hiddenInput.type = "hidden";
  hiddenInput.name = name;

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "work-order-quick-picker-trigger";
  trigger.setAttribute("aria-haspopup", "dialog");
  trigger.setAttribute("aria-expanded", "false");

  let selectedItems = [];
  let searchQuery = "";

  const syncHiddenInput = () => {
    hiddenInput.value = JSON.stringify(serializeSelected(selectedItems));
  };

  const renderTrigger = () => {
    trigger.textContent = selectedItems.length > 0 ? getSelectedLabel(selectedItems) : placeholder;
    trigger.classList.toggle("is-empty", selectedItems.length === 0);
    syncHiddenInput();
  };

  const closeMenu = () => {
    wrapper.classList.remove("is-open");
    trigger.setAttribute("aria-expanded", "false");
    if (wrapper._menuPortal) {
      wrapper._menuPortal.remove();
      wrapper._menuPortal = null;
    }
  };

  const getSelectedValueSet = () => new Set(selectedItems.map((item) => getOptionValue(item)));

  const setSelectedItems = (items = []) => {
    selectedItems = normalizeSelected(items);
    renderTrigger();
  };

  const openMenu = () => {
    closeOpenWorkOrderStatusMenus(wrapper);
    if (wrapper._menuPortal) {
      return;
    }

    searchQuery = "";
    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal work-order-quick-picker-menu-portal";
    menu.setAttribute("role", "dialog");

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => event.stopPropagation());
    });
    menu.addEventListener("wheel", (event) => event.stopPropagation(), { passive: true });

    const searchInput = document.createElement("input");
    searchInput.type = "search";
    searchInput.className = "work-order-quick-picker-search";
    searchInput.placeholder = searchPlaceholder;
    searchInput.autocomplete = "off";

    const selection = document.createElement("div");
    selection.className = "work-order-quick-picker-selection";

    const optionsList = document.createElement("div");
    optionsList.className = "work-order-quick-picker-options";

    const clearButton = document.createElement("button");
    clearButton.type = "button";
    clearButton.className = "ghost-button work-order-quick-picker-clear";
    clearButton.textContent = "Očisti";

    const positionMenu = () => {
      const triggerRect = trigger.getBoundingClientRect();
      const menuRect = menu.getBoundingClientRect();
      let left = triggerRect.left;
      let top = triggerRect.bottom + 8;
      if (left + menuRect.width > window.innerWidth - 12) {
        left = Math.max(12, window.innerWidth - menuRect.width - 12);
      }
      if (top + menuRect.height > window.innerHeight - 12) {
        top = Math.max(12, triggerRect.top - menuRect.height - 8);
      }
      menu.style.left = `${Math.round(left)}px`;
      menu.style.top = `${Math.round(top)}px`;
      menu.style.minWidth = `${Math.max(280, Math.round(triggerRect.width))}px`;
    };

    const renderSelection = () => {
      selection.replaceChildren();
      if (selectedItems.length === 0) {
        const empty = document.createElement("span");
        empty.className = "work-order-quick-picker-selection-empty";
        empty.textContent = placeholder;
        selection.append(empty);
        return;
      }

      selectedItems.forEach((item) => {
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "work-order-quick-picker-chip";
        chip.textContent = getOptionLabel(item);
        chip.addEventListener("click", (event) => {
          event.stopPropagation();
          setSelectedItems(selectedItems.filter((entry) => getOptionValue(entry) !== getOptionValue(item)));
          syncMenu();
        });
        selection.append(chip);
      });
    };

    const renderOptions = () => {
      optionsList.replaceChildren();
      const selectedValues = getSelectedValueSet();
      const options = getOptions(selectedItems)
        .filter((option) => matchesOption(option, searchQuery));

      if (options.length === 0) {
        const empty = document.createElement("p");
        empty.className = "work-order-quick-picker-empty";
        empty.textContent = emptyText;
        optionsList.append(empty);
        return;
      }

      options.forEach((option) => {
        const value = getOptionValue(option);
        const isSelected = selectedValues.has(value);
        const optionButton = document.createElement("button");
        optionButton.type = "button";
        optionButton.className = "work-item-status-option work-order-quick-picker-option";
        optionButton.classList.toggle("is-selected", isSelected);
        optionButton.setAttribute("role", "menuitemcheckbox");
        optionButton.setAttribute("aria-checked", String(isSelected));

        const copy = document.createElement("span");
        copy.className = "work-order-quick-picker-option-copy";
        const label = document.createElement("strong");
        label.textContent = getOptionLabel(option);
        const metaText = getOptionMeta(option);
        copy.append(label);
        if (metaText) {
          const meta = document.createElement("small");
          meta.textContent = metaText;
          copy.append(meta);
        }

        const marker = document.createElement("span");
        marker.className = "work-order-quick-picker-marker";
        marker.textContent = isSelected ? "✓" : "+";

        if (typeof renderOptionLeading === "function") {
          const leading = renderOptionLeading(option);
          if (leading) {
            optionButton.classList.add("has-leading");
            optionButton.append(leading);
          }
        }
        optionButton.append(copy, marker);
        optionButton.addEventListener("click", (event) => {
          event.stopPropagation();
          const nextItems = isSelected
            ? selectedItems.filter((item) => getOptionValue(item) !== value)
            : [...selectedItems, option];
          setSelectedItems(nextItems);
          syncMenu();
          searchInput.focus({ preventScroll: true });
        });
        optionsList.append(optionButton);
      });
    };

    const syncMenu = () => {
      renderSelection();
      renderOptions();
      clearButton.disabled = selectedItems.length === 0;
      requestAnimationFrame(positionMenu);
    };

    clearButton.addEventListener("click", (event) => {
      event.stopPropagation();
      setSelectedItems([]);
      syncMenu();
      searchInput.focus({ preventScroll: true });
    });
    searchInput.addEventListener("input", () => {
      searchQuery = searchInput.value || "";
      syncMenu();
    });
    searchInput.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        closeMenu();
        trigger.focus({ preventScroll: true });
      }
    });

    menu.append(searchInput, selection, optionsList, clearButton);
    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    syncMenu();
    requestAnimationFrame(() => {
      positionMenu();
      searchInput.focus({ preventScroll: true });
    });
  };

  wrapper._closeMenu = closeMenu;
  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    wrapper.addEventListener(eventName, (event) => event.stopPropagation());
  });
  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (wrapper.classList.contains("is-open")) {
      closeMenu();
      return;
    }
    openMenu();
  });

  renderTrigger();
  wrapper.append(hiddenInput, trigger);
  return wrapper;
}

function getWorkOrderQuickServicePickerValue(option = {}) {
  const serviceId = String(option?.serviceId || option?.id || "").trim();
  if (serviceId) {
    return `id:${serviceId}`;
  }

  const code = normalizeLooseName(option?.serviceCode || option?.code || "");
  const name = normalizeLooseName(option?.name || option?.serviceName || option?.title || "");
  const type = normalizeServiceCatalogTypeUi(option?.serviceType || "", option?.isTraining ? "znr" : "inspection");
  return [type, code, name].filter(Boolean).join("::") || normalizeLooseName(JSON.stringify(option));
}

function dedupeWorkOrderQuickServiceItems(items = []) {
  const seen = new Set();
  return (Array.isArray(items) ? items : []).filter((item) => {
    const key = getWorkOrderQuickServicePickerValue(item);
    if (!key || seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function createWorkOrderQuickServicePicker() {
  return createWorkOrderQuickPicker({
    name: "serviceItemsJson",
    placeholder: "+ Usluge",
    searchPlaceholder: "Traži uslugu...",
    emptyText: "Nema usluga u katalogu za ovaj pojam.",
    getOptions: (selectedItems) => getWorkOrderServiceCatalogOptions(selectedItems),
    matchesOption: matchesWorkOrderServiceSearch,
    getOptionValue: getWorkOrderQuickServicePickerValue,
    getOptionLabel: (option) => [option?.serviceCode, option?.name].filter(Boolean).join(" - ") || option?.name || "Usluga",
    getOptionMeta: (option) => getServiceCatalogTypeLabel(getWorkOrderServiceType(option)),
    getSelectedLabel: (items) => items.length === 1
      ? (items[0]?.name || items[0]?.serviceCode || "1 usluga")
      : `${items.length} usluga`,
    normalizeSelected: (items) => dedupeWorkOrderQuickServiceItems(getWorkOrderServiceItems({
      serviceItems: dedupeWorkOrderQuickServiceItems(items).map((item) => buildWorkOrderServiceItemSnapshot(item)),
    })),
    serializeSelected: (items) => dedupeWorkOrderQuickServiceItems(getWorkOrderServiceItems({ serviceItems: items })),
  });
}

function createWorkOrderQuickExecutorPicker() {
  return createWorkOrderQuickPicker({
    name: "executorsJson",
    placeholder: "+ Izvršitelji",
    searchPlaceholder: "Traži izvršitelja...",
    emptyText: "Nema izvršitelja za ovaj pojam.",
    getOptions: (selectedItems) => getWorkOrderExecutorOptions(selectedItems),
    matchesOption: matchesWorkOrderExecutorSearch,
    getOptionValue: (option) => String(option?.value || option?.label || ""),
    getOptionLabel: (option) => String(option?.label || option?.value || ""),
    getSelectedLabel: (items) => items.length === 1
      ? String(items[0]?.label || items[0]?.value || "1 izvršitelj")
      : `${items.length} izvršitelja`,
    normalizeSelected: (items) => normalizeWorkOrderExecutorValues(items.map((item) => (
      typeof item === "string" ? item : (item?.value || item?.label || "")
    ))).map((value) => ({
      value,
      label: value,
      user: findUserForExecutor(value),
    })),
    serializeSelected: (items) => normalizeWorkOrderExecutorValues(items.map((item) => (
      typeof item === "string" ? item : (item?.value || item?.label || "")
    ))),
    renderOptionLeading: (option) => createWorkOrderMiniExecutor(option, {
      className: "work-order-calendar-executor-option-avatar",
    }),
  });
}

function getWorkOrderQuickCompanyOptions() {
  return [
    { value: "", label: "Odaberi tvrtku" },
    ...state.companies
      .slice()
      .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "hr"))
      .map((company) => ({
        value: company.id,
        label: company.name || "Tvrtka",
      })),
  ];
}

function getWorkOrderQuickLocationOptions(companyId = "") {
  const normalizedCompanyId = String(companyId || "").trim();
  const locations = state.locations
    .filter((location) => !normalizedCompanyId || String(location.companyId || "") === normalizedCompanyId)
    .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "hr"));

  return [
    { value: "", label: normalizedCompanyId ? "Odaberi lokaciju" : "Prvo odaberi tvrtku" },
    ...locations.map((location) => ({
      value: location.id,
      label: location.name || "Lokacija",
    })),
  ];
}

function getWorkOrderQuickLocationContact(locationId = "") {
  return findWorkOrderQuickLocationContact(locationId);
}

function findWorkOrderQuickLocationContact(locationId = "", preferredSlot = "") {
  const location = getLocation(locationId);
  const contacts = buildLocationContacts(location);
  const normalizedSlot = String(preferredSlot || "").trim();
  const contact = (normalizedSlot
    ? contacts.find((entry) => String(entry.slot || "") === normalizedSlot)
    : null) || contacts[0] || null;
  if (!contact) {
    return {
      slot: "",
      name: "",
      phone: "",
      email: "",
    };
  }

  return {
    slot: String(contact.slot || "").trim(),
    name: String(contact.name || "").trim(),
    phone: String(contact.phone || "").trim(),
    email: String(contact.email || "").trim(),
  };
}

function getWorkOrderQuickLocationContactOptions(locationId = "") {
  const contacts = buildLocationContacts(getLocation(locationId));
  return [
    {
      value: "",
      label: contacts.length ? "Odaberi kontakt" : "Nema kontakata na lokaciji",
    },
    ...contacts.map((contact) => ({
      value: String(contact.slot || ""),
      label: [
        contact.name || "Kontakt",
        contact.phone || "",
        contact.email || "",
      ].filter(Boolean).join(" · "),
    })),
  ];
}

function setWorkOrderQuickRegionSelectValue(select, value = "") {
  if (!(select instanceof HTMLSelectElement)) {
    return;
  }

  const normalizedValue = String(value || "").trim();
  if (normalizedValue && !Array.from(select.options).some((option) => option.value === normalizedValue)) {
    select.append(createOption(normalizedValue, normalizedValue));
  }
  select.value = normalizedValue;
}

function buildQuickWorkOrderPayload(form) {
  const formData = new FormData(form);
  const location = getLocation(formData.get("locationId"));
  const contact = findWorkOrderQuickLocationContact(formData.get("locationId"), formData.get("contactSlot"));
  const serviceItems = getWorkOrderServiceItems({
    serviceItems: readWorkOrderQuickJsonValue(formData, "serviceItemsJson", []),
  });
  const executors = normalizeWorkOrderExecutorValues(
    readWorkOrderQuickJsonValue(formData, "executorsJson", []),
  );
  const serviceLine = getWorkOrderServiceSummary({ serviceItems });
  const region = String(formData.get("region") || "").trim() || location?.region || "";
  const tagText = formatWorkOrderTagText(formData.get("tagText") || "");

  return {
    status: String(formData.get("status") || "Otvoreni RN"),
    priority: String(formData.get("priority") || "Normal"),
    openedDate: toDateKey(new Date()),
    dueDate: normalizeDateInputValue(formData.get("dueDate")),
    teamLabel: "",
    companyId: String(formData.get("companyId") || ""),
    locationId: String(formData.get("locationId") || ""),
    coordinates: location?.coordinates || "",
    region,
    contactSlot: contact.slot,
    contactName: contact.name,
    contactPhone: contact.phone,
    contactEmail: contact.email,
    executors,
    executor1: executors[0] || "",
    executor2: executors[1] || "",
    measurementSheet: null,
    serviceItems,
    trainingContext: { name: "", role: "", phone: "", email: "" },
    serviceLine,
    department: "",
    linkReference: "",
    weight: "",
    completedBy: "",
    invoiceDate: "",
    tagText,
    description: serviceLine,
    invoiceNote: "",
  };
}

function createWorkOrderQuickCreatePanel() {
  if (!getCanEditOperationalData() || !getCanCreateWorkOrders()) {
    return null;
  }

  const card = document.createElement("section");
  card.className = "work-order-quick-create-panel";

  const head = document.createElement("div");
  head.className = "work-order-quick-create-head";
  const headCopy = document.createElement("div");
  const kicker = document.createElement("span");
  kicker.className = "section-kicker";
  kicker.textContent = "Brzo otvaranje";
  const title = document.createElement("strong");
  title.textContent = "Novi radni nalog";
  headCopy.append(kicker, title);
  const hint = document.createElement("span");
  hint.className = "work-order-quick-create-hint";
  hint.textContent = "Tvrtka, lokacija, kontakt, usluge i ekipa u jednom potezu.";
  head.append(headCopy, hint);

  const form = document.createElement("form");
  form.className = "work-order-quick-create-form";
  form.dataset.preventRowOpen = "true";

  const error = document.createElement("p");
  error.className = "work-order-quick-error";
  error.hidden = true;

  const statusSelect = createWorkOrderQuickSelect("status", WORK_ORDER_STATUS_OPTIONS, "Otvoreni RN");
  const companySelect = createWorkOrderQuickSelect("companyId", getWorkOrderQuickCompanyOptions());
  companySelect.setAttribute("aria-required", "true");
  const locationSelect = createWorkOrderQuickSelect("locationId", getWorkOrderQuickLocationOptions(""));
  locationSelect.disabled = true;
  const contactSelect = createWorkOrderQuickSelect("contactSlot", getWorkOrderQuickLocationContactOptions(""));
  contactSelect.disabled = true;
  const prioritySelect = createWorkOrderQuickSelect("priority", PRIORITY_OPTIONS, "Normal");
  const regionSelect = createWorkOrderQuickSelect("region", [
    { value: "", label: "Regija iz lokacije" },
    ...WORK_ORDER_REGION_OPTIONS.map((region) => ({ value: region, label: region })),
  ]);
  const dueDateInput = createWorkOrderQuickDateInput("dueDate", "dd.mm.yyyy");
  const servicePicker = createWorkOrderQuickServicePicker();
  const executorPicker = createWorkOrderQuickExecutorPicker();
  const tagHidden = document.createElement("input");
  tagHidden.type = "hidden";
  tagHidden.name = "tagText";
  const tagPicker = createWorkOrderTagPickerControl({
    value: "",
    placeholder: "Tagovi",
    className: "work-order-quick-tag-picker",
    ariaLabel: "Odaberi tagove za novi RN",
    onChange: (tags) => {
      tagHidden.value = formatWorkOrderTagText(tags);
    },
  });

  const syncLocationDependentControls = () => {
    const locationId = locationSelect.value;
    const location = getLocation(locationId);
    replaceSelectOptions(contactSelect, getWorkOrderQuickLocationContactOptions(locationId), "");
    contactSelect.disabled = !locationId || buildLocationContacts(location).length === 0;
    const firstContact = buildLocationContacts(location)[0];
    if (firstContact) {
      contactSelect.value = String(firstContact.slot || "");
    }
    setWorkOrderQuickRegionSelectValue(regionSelect, location?.region || "");
  };

  companySelect.addEventListener("change", () => {
    replaceSelectOptions(locationSelect, getWorkOrderQuickLocationOptions(companySelect.value), "");
    locationSelect.disabled = !companySelect.value;
    syncLocationDependentControls();
  });

  locationSelect.addEventListener("change", () => {
    syncLocationDependentControls();
  });

  form.append(
    createWorkOrderQuickControl("Status", statusSelect),
    createWorkOrderQuickControl("Tvrtka", companySelect),
    createWorkOrderQuickControl("Lokacija", locationSelect),
    createWorkOrderQuickControl("Kontakt", contactSelect),
    createWorkOrderQuickControl("Prioritet", prioritySelect),
    createWorkOrderQuickControl("Regija", regionSelect),
    createWorkOrderQuickControl("Usluge", servicePicker),
    createWorkOrderQuickControl("Tagovi", tagPicker),
    createWorkOrderQuickControl("Izvršitelji", executorPicker),
    createWorkOrderQuickControl("Rok", dueDateInput),
    tagHidden,
  );

  const actions = document.createElement("div");
  actions.className = "work-order-quick-create-actions";
  const submitButton = document.createElement("button");
  submitButton.type = "submit";
  submitButton.className = "primary-button work-order-quick-create-submit";
  submitButton.textContent = "Otvori RN";
  actions.append(error, submitButton);
  form.append(actions);

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    error.hidden = true;
    error.textContent = "";

    const payload = buildQuickWorkOrderPayload(form);
    const blockMessage = getWorkOrderRequiredBlockMessage(payload);
    if (blockMessage) {
      error.textContent = blockMessage;
      error.hidden = false;
      const focusTarget = !payload.companyId
        ? companySelect
        : !payload.locationId
          ? locationSelect
          : !payload.dueDate
            ? form.querySelector('input[name="dueDate"]')
            : null;
      focusTarget?.focus?.();
      return;
    }

    submitButton.disabled = true;
    submitButton.textContent = "Spremam...";
    const previousIds = new Set(state.workOrders.map((item) => String(item.id)));
    let createdFromResponse = null;
    const success = await runMutation(() => apiRequest("/work-orders", {
      method: "POST",
      body: payload,
    }), error, {
      onSuccessPayload: (response) => {
        createdFromResponse = applyCreatedWorkOrderResponse(response, payload);
      },
    });

    if (success) {
      const created = createdFromResponse || findCreatedWorkOrderMatch(previousIds, payload);
      if (created?.id) {
        renderWorkOrderWorkspace();
        queueGeneratedWorkOrderPdfSave(created.id);
      }
      window.setTimeout(() => {
        const nextCompanySelect = workOrderQuickCreateSlot?.querySelector('select[name="companyId"]');
        if (nextCompanySelect instanceof HTMLSelectElement) {
          nextCompanySelect.focus({ preventScroll: true });
        }
      }, 0);
      return;
    }

    submitButton.disabled = false;
    submitButton.textContent = "Otvori RN";
    if (error.textContent) {
      error.hidden = false;
    }
  });

  card.append(head, form);
  return card;
}

function renderWorkOrderQuickCreateSlot() {
  if (!workOrderQuickCreateSlot) {
    return;
  }

  const panel = createWorkOrderQuickCreatePanel();
  workOrderQuickCreateSlot.hidden = !panel;
  workOrderQuickCreateSlot.replaceChildren(...(panel ? [panel] : []));
}

function createWorkOrderQuickCreateRow(columnLayout = [], isExpanded = false) {
  if (!getCanEditOperationalData() || !getCanCreateWorkOrders()) {
    return null;
  }

  const card = document.createElement("section");
  card.className = "work-item-card work-order-quick-create-card";
  card.dataset.preventRowOpen = "true";

  const form = document.createElement("form");
  form.className = `work-item-row is-${isExpanded ? "expanded" : "collapsed"} work-order-quick-create-row`;
  form.dataset.preventRowOpen = "true";

  const error = document.createElement("p");
  error.className = "work-order-quick-error";
  error.hidden = true;

  const companySelect = createWorkOrderQuickSelect("companyId", getWorkOrderQuickCompanyOptions());
  companySelect.setAttribute("aria-required", "true");
  const locationSelect = createWorkOrderQuickSelect("locationId", getWorkOrderQuickLocationOptions(""));
  locationSelect.disabled = true;
  const dueDateInput = createWorkOrderQuickDateInput("dueDate", "dd.mm.yyyy");
  const servicePicker = createWorkOrderQuickServicePicker();
  const executorPicker = createWorkOrderQuickExecutorPicker();
  const contactInput = createWorkOrderQuickInput("contactName", "Kontakt");

  companySelect.addEventListener("change", () => {
    replaceSelectOptions(locationSelect, getWorkOrderQuickLocationOptions(companySelect.value), "");
    locationSelect.disabled = !companySelect.value;
    contactInput.value = "";
  });

  locationSelect.addEventListener("change", () => {
    const contact = getWorkOrderQuickLocationContact(locationSelect.value);
    if (!contactInput.value.trim()) {
      contactInput.value = contact.name;
    }
  });

  const statusSelect = createWorkOrderQuickSelect("status", WORK_ORDER_STATUS_OPTIONS, "Otvoreni RN");
  const hasServiceColumn = columnLayout.some((column) => column.key === "service" || column.key === "services");
  const createDeferredQuickCell = (labelText = "Kasnije", copyText = "Prioritet i tagovi") => {
    const cell = document.createElement("div");
    cell.className = "work-order-quick-cell work-order-quick-deferred";
    const label = document.createElement("label");
    label.textContent = labelText;
    const text = document.createElement("span");
    text.textContent = copyText;
    cell.append(label, text);
    return cell;
  };
  const deferredCell = createDeferredQuickCell();

  const cellsByKey = {
    select: (() => {
      const cell = document.createElement("div");
      cell.className = "work-item-cell work-item-select-cell";
      const icon = document.createElement("span");
      icon.className = "work-order-quick-icon";
      icon.textContent = "+";
      cell.append(icon);
      return cell;
    })(),
    basic: createWorkOrderQuickControl("Status", statusSelect),
    client: createWorkOrderQuickControl("Tvrtka", companySelect),
    headquarters: createDeferredQuickCell("Automatski", "Iz tvrtke"),
    region: createDeferredQuickCell("Automatski", "Iz lokacije"),
    location: createWorkOrderQuickControl("Lokacija", locationSelect),
    contact: createWorkOrderQuickControl("Kontakt", contactInput),
    service: createWorkOrderQuickControl("Usluge", servicePicker),
    services: createWorkOrderQuickControl("Usluge", servicePicker),
    billing: createWorkOrderQuickControl("Rok", dueDateInput),
    finance: createWorkOrderQuickControl("Rok", dueDateInput),
    priorityTags: hasServiceColumn ? deferredCell : createDeferredQuickCell("Kasnije", "Prioritet i tagovi"),
    priorityServices: createWorkOrderQuickControl("Usluge", servicePicker),
    executors: createWorkOrderQuickControl("Izvršitelji", executorPicker),
    actions: (() => {
      const cell = document.createElement("div");
      cell.className = "work-order-quick-cell";
      const label = document.createElement("label");
      label.textContent = "Spremi";
      const button = document.createElement("button");
      button.type = "submit";
      button.className = "primary-button work-order-quick-action";
      button.textContent = "Otvori RN";
      cell.append(label, button, error);
      return cell;
    })(),
  };

  form.append(...columnLayout.map((column) => cellsByKey[column.key]).filter(Boolean));
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    error.hidden = true;
    error.textContent = "";

    const payload = buildQuickWorkOrderPayload(form);
    const blockMessage = getWorkOrderRequiredBlockMessage(payload);
    if (blockMessage) {
      error.textContent = blockMessage;
      error.hidden = false;
      const focusTarget = !payload.companyId
        ? companySelect
        : !payload.locationId
          ? locationSelect
          : !payload.dueDate
            ? dueDateInput
            : null;
      focusTarget?.focus?.();
      return;
    }

    const submitButton = form.querySelector('button[type="submit"]');
    if (submitButton instanceof HTMLButtonElement) {
      submitButton.disabled = true;
      submitButton.textContent = "Spremam...";
    }
    const previousIds = new Set(state.workOrders.map((item) => String(item.id)));
    let createdFromResponse = null;
    const success = await runMutation(() => apiRequest("/work-orders", {
      method: "POST",
      body: payload,
    }), error, {
      onSuccessPayload: (response) => {
        createdFromResponse = applyCreatedWorkOrderResponse(response, payload);
      },
    });

    if (success) {
      const created = createdFromResponse || findCreatedWorkOrderMatch(previousIds, payload);
      if (created?.id) {
        renderWorkOrderWorkspace();
        queueGeneratedWorkOrderPdfSave(created.id);
      }
      window.setTimeout(() => {
        const nextCompanySelect = document.querySelector('.work-order-quick-create-row select[name="companyId"]');
        if (nextCompanySelect instanceof HTMLSelectElement) {
          nextCompanySelect.focus({ preventScroll: true });
        }
      }, 0);
      return;
    }

    if (submitButton instanceof HTMLButtonElement) {
      submitButton.disabled = false;
      submitButton.textContent = "Otvori RN";
    }
    if (error.textContent) {
      error.hidden = false;
    }
  });

  card.append(form);
  return card;
}

function prepareWorkOrderInlineEditorCell(cell, editorSelector = ".work-order-inline-field-editor") {
  if (!(cell instanceof HTMLElement)) {
    return false;
  }

  const alreadyPrepared = cell.classList.contains("has-inline-field-editor");
  cell.classList.add("has-inline-editor", "has-inline-field-editor");
  cell.dataset.preventRowOpen = "true";
  if (!alreadyPrepared) {
    cell.title = [cell.title || "", "Dvoklik za brzu izmjenu."].filter(Boolean).join(" ");
  }
  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    cell.addEventListener(eventName, (event) => {
      if (event.target instanceof HTMLElement && event.target.closest(editorSelector)) {
        event.stopPropagation();
      }
    });
  });
  return true;
}

function createWorkOrderInlineEditorControl(labelText = "", content = null) {
  const label = document.createElement("label");
  label.className = "work-order-inline-field-control";
  const labelNode = document.createElement("span");
  labelNode.textContent = labelText;
  label.append(labelNode);
  if (content instanceof Node) {
    label.append(content);
  }
  return label;
}

function createWorkOrderInlineEditorShell(workOrder = {}, titleText = "Brza izmjena", className = "") {
  closeWorkOrderInlineFieldEditor();

  const form = document.createElement("form");
  form.className = ["work-order-inline-field-editor", className].filter(Boolean).join(" ");
  form.dataset.preventRowOpen = "true";
  form.setAttribute("role", "dialog");
  form.setAttribute("aria-label", titleText);

  ["pointerdown", "mousedown", "click", "keydown", "contextmenu"].forEach((eventName) => {
    form.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });

  const header = document.createElement("div");
  header.className = "work-order-inline-field-head";
  const title = document.createElement("strong");
  title.textContent = titleText;
  const subtitle = document.createElement("span");
  subtitle.textContent = workOrder.workOrderNumber ? `RN ${workOrder.workOrderNumber}` : "Radni nalog";
  header.append(title, subtitle);

  const grid = document.createElement("div");
  grid.className = "work-order-inline-field-grid";

  const actions = document.createElement("div");
  actions.className = "work-order-inline-field-actions";
  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "ghost-button";
  cancelButton.textContent = "Zatvori";
  cancelButton.addEventListener("click", () => {
    closeWorkOrderInlineFieldEditor();
  });
  const saveButton = document.createElement("button");
  saveButton.type = "submit";
  saveButton.className = "primary-button";
  saveButton.textContent = "Spremi";
  actions.append(cancelButton, saveButton);

  form.append(header, grid, actions);
  form.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      closeWorkOrderInlineFieldEditor();
    }
  });

  return { form, grid, saveButton, cancelButton };
}

function mountWorkOrderInlineEditor(cell, form, focusSelector = "input, select, button") {
  document.body.append(form);
  state.workOrderInlineFieldEditor = { element: form, anchor: cell };
  positionWorkOrderInlineFieldEditor(form, cell);
  requestAnimationFrame(() => positionWorkOrderInlineFieldEditor(form, cell));
  const focusTarget = form.querySelector(focusSelector);
  if (focusTarget instanceof HTMLElement) {
    focusTarget.focus({ preventScroll: true });
    if (focusTarget instanceof HTMLInputElement) {
      focusTarget.select();
    }
  }
}

async function saveWorkOrderInlinePatch(workOrder = {}, body = {}, saveButton = null) {
  const payload = Object.fromEntries(
    Object.entries(body ?? {}).filter(([, value]) => value !== undefined),
  );
  if (!workOrder?.id || Object.keys(payload).length === 0) {
    closeWorkOrderInlineFieldEditor();
    return true;
  }

  if (saveButton instanceof HTMLButtonElement) {
    saveButton.disabled = true;
    saveButton.textContent = "Spremam...";
  }

  const success = await runMutation(() => apiRequest(`/work-orders/${encodeURIComponent(String(workOrder.id))}`, {
    method: "PATCH",
    body: payload,
  }), null);

  if (success) {
    closeWorkOrderInlineFieldEditor();
    return true;
  }

  if (saveButton instanceof HTMLButtonElement) {
    saveButton.disabled = false;
    saveButton.textContent = "Spremi";
  }
  return false;
}

function attachWorkOrderInlinePriorityEditor(cell, workOrder = {}) {
  if (!(cell instanceof HTMLElement) || !workOrder?.id || !getCanEditOperationalData()) {
    return;
  }

  prepareWorkOrderInlineEditorCell(cell);

  const openEditor = () => {
    if (state.workOrderInlineFieldEditor?.anchor === cell) {
      return;
    }

    const { form, grid, saveButton } = createWorkOrderInlineEditorShell(
      workOrder,
      "Prioritet i tagovi",
      "work-order-inline-priority-tag-editor",
    );
    const prioritySelect = document.createElement("select");
    replaceSelectOptions(prioritySelect, PRIORITY_OPTIONS, workOrder.priority || "Normal");

    let selectedTags = splitWorkOrderTags(workOrder.tagText || "");
    const tagPicker = createWorkOrderTagPickerControl({
      value: selectedTags,
      placeholder: "Tagovi",
      className: "work-order-inline-tag-picker",
      ariaLabel: "Odaberi tagove za RN",
      onChange: (tags) => {
        selectedTags = splitWorkOrderTags(tags);
      },
    });

    grid.append(
      createWorkOrderInlineEditorControl("Prioritet", prioritySelect),
      createWorkOrderInlineEditorControl("Tagovi", tagPicker),
    );

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      void saveWorkOrderInlinePatch(workOrder, {
        priority: prioritySelect.value || "Normal",
        tagText: formatWorkOrderTagText(selectedTags),
      }, saveButton);
    });

    mountWorkOrderInlineEditor(cell, form, "select");
  };

  cell.addEventListener("dblclick", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openEditor();
  });
}

function closeWorkOrderInlineFieldEditor() {
  const editorState = state.workOrderInlineFieldEditor;
  if (editorState?.element instanceof HTMLElement) {
    editorState.element.remove();
  }
  state.workOrderInlineFieldEditor = null;
}

function positionWorkOrderInlineFieldEditor(editor, anchor) {
  if (!(editor instanceof HTMLElement) || !(anchor instanceof HTMLElement)) {
    return;
  }

  const anchorRect = anchor.getBoundingClientRect();
  const editorRect = editor.getBoundingClientRect();
  const viewportWidth = window.innerWidth;
  const viewportHeight = window.innerHeight;
  let left = anchorRect.left;
  let top = anchorRect.bottom + 8;

  if (left + editorRect.width > viewportWidth - 12) {
    left = Math.max(12, viewportWidth - editorRect.width - 12);
  }
  if (top + editorRect.height > viewportHeight - 12) {
    top = Math.max(12, anchorRect.top - editorRect.height - 8);
  }

  editor.style.left = `${Math.round(Math.max(12, left))}px`;
  editor.style.top = `${Math.round(Math.max(12, top))}px`;
}

function attachWorkOrderInlineFieldEditor(cell, workOrder = {}, config = {}) {
  const fields = (Array.isArray(config.fields) ? config.fields : [])
    .map((field) => ({
      key: String(field?.key || "").trim(),
      label: String(field?.label || "").trim(),
      type: String(field?.type || "text").trim(),
      placeholder: String(field?.placeholder || "").trim(),
    }))
    .filter((field) => field.key && field.label);

  if (!(cell instanceof HTMLElement) || !workOrder?.id || fields.length === 0 || !getCanEditOperationalData()) {
    return;
  }

  cell.classList.add("has-inline-editor", "has-inline-field-editor");
  cell.dataset.preventRowOpen = "true";
  cell.title = [cell.title || "", "Dvoklik za brzu izmjenu."].filter(Boolean).join(" ");

  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    cell.addEventListener(eventName, (event) => {
      if (event.target instanceof HTMLElement && event.target.closest(".work-order-inline-field-editor")) {
        event.stopPropagation();
      }
    });
  });

  const openEditor = () => {
    if (state.workOrderInlineFieldEditor?.anchor === cell) {
      return;
    }

    closeWorkOrderInlineFieldEditor();

    const form = document.createElement("form");
    form.className = "work-order-inline-field-editor";
    form.dataset.preventRowOpen = "true";
    form.setAttribute("role", "dialog");
    form.setAttribute("aria-label", config.title || "Brza izmjena RN-a");

    ["pointerdown", "mousedown", "click", "keydown", "contextmenu"].forEach((eventName) => {
      form.addEventListener(eventName, (event) => {
        event.stopPropagation();
      });
    });

    const header = document.createElement("div");
    header.className = "work-order-inline-field-head";
    const title = document.createElement("strong");
    title.textContent = config.title || "Brza izmjena";
    const subtitle = document.createElement("span");
    subtitle.textContent = workOrder.workOrderNumber ? `RN ${workOrder.workOrderNumber}` : "Radni nalog";
    header.append(title, subtitle);

    const grid = document.createElement("div");
    grid.className = "work-order-inline-field-grid";
    const inputs = new Map();
    fields.forEach((field) => {
      const label = document.createElement("label");
      label.className = "work-order-inline-field-control";
      const labelText = document.createElement("span");
      labelText.textContent = field.label;
      const input = document.createElement("input");
      input.type = field.type === "date" ? "date" : "text";
      input.value = field.type === "date"
        ? normalizeDateInputValue(workOrder[field.key] || "")
        : String(workOrder[field.key] ?? "");
      input.placeholder = field.placeholder || (field.type === "date" ? "dd.mm.yyyy" : "");
      if (field.type === "date" && input.type !== "date") {
        input.inputMode = "numeric";
        input.pattern = "[0-9.\\-/\\s]*";
      }
      if (field.key === "completedBy") {
        const listId = `work-order-inline-completed-by-${String(workOrder.id || "").replace(/[^A-Za-z0-9_-]/g, "")}`;
        const datalist = document.createElement("datalist");
        datalist.id = listId;
        datalist.replaceChildren(...getWorkOrderExecutors(workOrder).map((executor) => {
          const option = document.createElement("option");
          option.value = executor;
          return option;
        }));
        input.setAttribute("list", listId);
        label.append(labelText, input, datalist);
      } else {
        label.append(labelText, input);
      }
      grid.append(label);
      inputs.set(field.key, { input, field, initialValue: input.value });
    });

    const actions = document.createElement("div");
    actions.className = "work-order-inline-field-actions";
    const cancelButton = document.createElement("button");
    cancelButton.type = "button";
    cancelButton.className = "ghost-button";
    cancelButton.textContent = "Zatvori";
    cancelButton.addEventListener("click", () => {
      closeWorkOrderInlineFieldEditor();
    });
    const saveButton = document.createElement("button");
    saveButton.type = "submit";
    saveButton.className = "primary-button";
    saveButton.textContent = "Spremi";
    actions.append(cancelButton, saveButton);

    form.append(header, grid, actions);
    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const body = {};
      inputs.forEach(({ input, field, initialValue }, key) => {
        if (input.value === initialValue) {
          return;
        }
        body[key] = field.type === "date" ? normalizeDateInputValue(input.value) : input.value;
      });

      if (Object.keys(body).length === 0) {
        closeWorkOrderInlineFieldEditor();
        return;
      }

      saveButton.disabled = true;
      saveButton.textContent = "Spremam...";
      void runMutation(() => apiRequest(`/work-orders/${encodeURIComponent(String(workOrder.id))}`, {
        method: "PATCH",
        body,
      })).then((success) => {
        if (success) {
          closeWorkOrderInlineFieldEditor();
          return;
        }
        saveButton.disabled = false;
        saveButton.textContent = "Spremi";
      });
    });

    form.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        closeWorkOrderInlineFieldEditor();
      }
    });

    document.body.append(form);
    state.workOrderInlineFieldEditor = { element: form, anchor: cell };
    positionWorkOrderInlineFieldEditor(form, cell);
    requestAnimationFrame(() => positionWorkOrderInlineFieldEditor(form, cell));
    const firstInput = form.querySelector("input");
    if (firstInput instanceof HTMLInputElement) {
      firstInput.focus({ preventScroll: true });
      firstInput.select();
    }
  };

  cell.addEventListener("dblclick", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openEditor();
  });
}

function attachWorkOrderInlineLocationEditor(cell, workOrder = {}) {
  if (!(cell instanceof HTMLElement) || !workOrder?.id || !getCanEditOperationalData()) {
    return;
  }

  prepareWorkOrderInlineEditorCell(cell);
  const openEditor = () => {
    if (state.workOrderInlineFieldEditor?.anchor === cell) {
      return;
    }

    const { form, grid, saveButton } = createWorkOrderInlineEditorShell(workOrder, "Lokacija");
    const select = document.createElement("select");
    const locations = getLocationsForCompany(workOrder.companyId);
    const options = [
      { value: "", label: "Odaberi lokaciju" },
      ...locations.map((location) => ({
        value: String(location.id || ""),
        label: [
          location.name || "Lokacija",
          location.region || "",
          location.coordinates || "",
        ].filter(Boolean).join(" · "),
      })),
    ];
    replaceSelectOptions(select, options, String(workOrder.locationId || ""));
    select.disabled = locations.length === 0;
    grid.append(createWorkOrderInlineEditorControl("Lokacija", select));

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const location = getLocation(select.value);
      if (!location) {
        void saveWorkOrderInlinePatch(workOrder, {
          locationId: "",
          locationName: "",
          region: "",
          coordinates: "",
          contactSlot: "",
          contactName: "",
          contactPhone: "",
          contactEmail: "",
        }, saveButton);
        return;
      }

      const contact = buildLocationContacts(location)[0] ?? {};
      void saveWorkOrderInlinePatch(workOrder, {
        locationId: String(location.id || ""),
        locationName: String(location.name || ""),
        region: String(location.region || ""),
        coordinates: String(location.coordinates || ""),
        contactSlot: String(contact.slot || ""),
        contactName: String(contact.name || ""),
        contactPhone: String(contact.phone || ""),
        contactEmail: String(contact.email || ""),
      }, saveButton);
    });

    mountWorkOrderInlineEditor(cell, form, "select");
  };

  cell.addEventListener("dblclick", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openEditor();
  });
}

function attachWorkOrderInlineContactEditor(cell, workOrder = {}) {
  if (!(cell instanceof HTMLElement) || !workOrder?.id || !getCanEditOperationalData()) {
    return;
  }

  prepareWorkOrderInlineEditorCell(cell);
  const openEditor = () => {
    if (state.workOrderInlineFieldEditor?.anchor === cell) {
      return;
    }

    const { form, grid, saveButton } = createWorkOrderInlineEditorShell(workOrder, "Kontakt");
    const location = getLocation(workOrder.locationId);
    const contacts = buildLocationContacts(location);
    const currentKey = String(workOrder.contactSlot || workOrder.contactEmail || workOrder.contactPhone || workOrder.contactName || "");
    const select = document.createElement("select");
    const options = [
      { value: "", label: contacts.length ? "Odaberi kontakt" : "Nema kontakata na lokaciji" },
      ...contacts.map((contact) => {
        const value = String(contact.slot || contact.email || contact.phone || contact.name || "");
        return {
          value,
          label: [
            contact.name || "Kontakt",
            contact.phone || "",
            contact.email || "",
          ].filter(Boolean).join(" · "),
        };
      }),
    ];
    replaceSelectOptions(select, options, currentKey);
    select.disabled = contacts.length === 0;
    grid.append(createWorkOrderInlineEditorControl("Kontakt", select));

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const contact = contacts.find((entry) => (
        String(entry.slot || entry.email || entry.phone || entry.name || "") === select.value
      ));
      if (!contact) {
        void saveWorkOrderInlinePatch(workOrder, {
          contactSlot: "",
          contactName: "",
          contactPhone: "",
          contactEmail: "",
        }, saveButton);
        return;
      }

      void saveWorkOrderInlinePatch(workOrder, {
        contactSlot: String(contact.slot || ""),
        contactName: String(contact.name || ""),
        contactPhone: String(contact.phone || ""),
        contactEmail: String(contact.email || ""),
      }, saveButton);
    });

    mountWorkOrderInlineEditor(cell, form, "select");
  };

  cell.addEventListener("dblclick", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openEditor();
  });
}

function attachWorkOrderInlineExecutorsEditor(cell, workOrder = {}) {
  if (!(cell instanceof HTMLElement) || !workOrder?.id || !getCanEditOperationalData()) {
    return;
  }

  prepareWorkOrderInlineEditorCell(cell);
  const openEditor = () => {
    if (state.workOrderInlineFieldEditor?.anchor === cell) {
      return;
    }

    const { form, grid, saveButton } = createWorkOrderInlineEditorShell(
      workOrder,
      "Izvršitelji",
      "work-order-inline-list-editor",
    );
    let selectedExecutors = normalizeWorkOrderExecutorValues(getWorkOrderExecutors(workOrder));
    let query = "";

    const search = document.createElement("input");
    search.type = "search";
    search.placeholder = "Pretraži izvršitelja...";
    search.autocomplete = "off";

    const selected = document.createElement("div");
    selected.className = "work-order-inline-chip-row";
    const list = document.createElement("div");
    list.className = "work-order-inline-option-list";

    const render = () => {
      selected.replaceChildren();
      if (selectedExecutors.length === 0) {
        const empty = document.createElement("span");
        empty.className = "work-order-quick-picker-selection-empty";
        empty.textContent = "Bez izvršitelja";
        selected.append(empty);
      } else {
        selectedExecutors.forEach((executor) => {
          const chip = document.createElement("button");
          chip.type = "button";
          chip.className = "work-order-quick-picker-chip";
          chip.textContent = executor;
          chip.addEventListener("click", () => {
            selectedExecutors = selectedExecutors.filter((entry) => entry !== executor);
            render();
          });
          selected.append(chip);
        });
      }

      list.replaceChildren();
      const options = getWorkOrderExecutorOptions(selectedExecutors)
        .filter((option) => !query || matchesWorkOrderExecutorSearch(option, query));
      options.forEach((option) => {
        const value = String(option.value || option.label || "").trim();
        const isSelected = selectedExecutors.includes(value);
        const button = document.createElement("button");
        button.type = "button";
        button.className = `work-item-status-option work-order-inline-option${isSelected ? " is-selected" : ""}`;
        const avatar = createWorkOrderMiniExecutor(value, {
          className: "work-order-calendar-executor-option-avatar",
        });
        const copy = document.createElement("span");
        copy.className = "work-order-inline-option-copy";
        const label = document.createElement("strong");
        label.textContent = String(option.label || value);
        copy.append(label);
        const marker = document.createElement("span");
        marker.className = "work-order-quick-picker-marker";
        marker.textContent = isSelected ? "✓" : "+";
        button.append(avatar, copy, marker);
        button.addEventListener("click", () => {
          selectedExecutors = isSelected
            ? selectedExecutors.filter((entry) => entry !== value)
            : normalizeWorkOrderExecutorValues([...selectedExecutors, value]);
          render();
          search.focus({ preventScroll: true });
        });
        list.append(button);
      });
    };

    search.addEventListener("input", () => {
      query = search.value || "";
      render();
    });
    grid.append(
      createWorkOrderInlineEditorControl("Pretraga", search),
      selected,
      list,
    );
    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const executors = normalizeWorkOrderExecutorValues(selectedExecutors);
      void saveWorkOrderInlinePatch(workOrder, {
        executors,
        executor1: executors[0] || "",
        executor2: executors[1] || "",
      }, saveButton);
    });
    render();
    mountWorkOrderInlineEditor(cell, form, "input");
  };

  cell.addEventListener("dblclick", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openEditor();
  });
}

function openWorkOrderInlineServicesEditor(cell, workOrder = {}) {
  if (!(cell instanceof HTMLElement) || !workOrder?.id || !getCanEditOperationalData()) {
    return false;
  }

  prepareWorkOrderInlineEditorCell(cell);
  if (state.workOrderInlineFieldEditor?.anchor === cell) {
    return true;
  }

  const { form, grid, saveButton } = createWorkOrderInlineEditorShell(
    workOrder,
    "Usluge",
    "work-order-inline-service-editor",
  );
  let draftItems = getWorkOrderServiceItems(workOrder);
  let searchQuery = "";
  let selectedType = getWorkOrderSelectionServiceType(draftItems) || "inspection";

  const tabs = document.createElement("div");
  tabs.className = "work-order-service-type-tabs";
  const search = document.createElement("input");
  search.type = "search";
  search.placeholder = "Pretraži usluge...";
  search.autocomplete = "off";
  const selected = document.createElement("div");
  selected.className = "work-order-inline-chip-row";
  const list = document.createElement("div");
  list.className = "work-order-inline-option-list";

  const getSelectedKeys = () => new Set(draftItems.map((item) => getWorkOrderQuickServicePickerValue(item)));

  const renderTabs = () => {
    tabs.replaceChildren();
    SERVICE_CATALOG_TYPE_OPTIONS.forEach((option) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = `work-order-service-type-tab${option.value === selectedType ? " is-active" : ""}`;
      button.textContent = option.label;
      button.addEventListener("click", () => {
        selectedType = option.value;
        render();
      });
      tabs.append(button);
    });
  };

  const renderSelected = () => {
    selected.replaceChildren();
    if (draftItems.length === 0) {
      const empty = document.createElement("span");
      empty.className = "work-order-quick-picker-selection-empty";
      empty.textContent = "Bez odabranih usluga";
      selected.append(empty);
      return;
    }

    draftItems.forEach((item) => {
      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = "work-order-quick-picker-chip";
      chip.textContent = item.name || item.serviceCode || "Usluga";
      chip.addEventListener("click", () => {
        const key = getWorkOrderQuickServicePickerValue(item);
        draftItems = draftItems.filter((entry) => getWorkOrderQuickServicePickerValue(entry) !== key);
        render();
      });
      selected.append(chip);
    });
  };

  const renderOptions = () => {
    list.replaceChildren();
    const selectedKeys = getSelectedKeys();
    const options = getWorkOrderServiceCatalogOptions(draftItems)
      .filter((option) => getWorkOrderServiceType(option) === selectedType)
      .filter((option) => matchesWorkOrderServiceSearch(option, searchQuery));

    if (options.length === 0) {
      const empty = document.createElement("p");
      empty.className = "work-order-quick-picker-empty";
      empty.textContent = "Nema usluga za ovaj filter.";
      list.append(empty);
      return;
    }

    options.forEach((option) => {
      const key = getWorkOrderQuickServicePickerValue(option);
      const isSelected = selectedKeys.has(key);
      const button = document.createElement("button");
      button.type = "button";
      button.className = `work-item-status-option work-order-inline-option${isSelected ? " is-selected" : ""}`;

      const copy = document.createElement("span");
      copy.className = "work-order-inline-option-copy";
      const title = document.createElement("strong");
      title.textContent = option.name || option.serviceCode || "Usluga";
      const meta = document.createElement("small");
      meta.textContent = [option.serviceCode, getServiceCatalogTypeLabel(getWorkOrderServiceType(option))].filter(Boolean).join(" · ");
      copy.append(title, meta);

      const marker = document.createElement("span");
      marker.className = "work-order-quick-picker-marker";
      marker.textContent = isSelected ? "✓" : "+";
      button.append(copy, marker);
      button.addEventListener("click", () => {
        const current = draftItems.find((item) => getWorkOrderQuickServicePickerValue(item) === key) ?? null;
        draftItems = isSelected
          ? draftItems.filter((item) => getWorkOrderQuickServicePickerValue(item) !== key)
          : dedupeWorkOrderQuickServiceItems([...draftItems, buildWorkOrderServiceItemSnapshot(option, current)]);
        render();
        search.focus({ preventScroll: true });
      });
      list.append(button);
    });
  };

  const render = () => {
    renderTabs();
    renderSelected();
    renderOptions();
  };

  search.addEventListener("input", () => {
    searchQuery = search.value || "";
    renderOptions();
  });
  grid.append(
    tabs,
    createWorkOrderInlineEditorControl("Pretraga", search),
    selected,
    list,
  );
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    const serviceItems = dedupeWorkOrderQuickServiceItems(getWorkOrderServiceItems({
      serviceItems: draftItems.map((item) => buildWorkOrderServiceItemSnapshot(getServiceCatalogItemForWorkOrderService(item) ?? item, item)),
    }));
    void saveWorkOrderInlinePatch(workOrder, {
      serviceItems,
      serviceLine: getWorkOrderServiceSummary({ serviceItems }),
    }, saveButton);
  });
  render();
  mountWorkOrderInlineEditor(cell, form, "input");
  return true;
}

function attachWorkOrderInlineServicesEditor(cell, workOrder = {}) {
  if (!(cell instanceof HTMLElement) || !workOrder?.id || !getCanEditOperationalData()) {
    return;
  }

  prepareWorkOrderInlineEditorCell(cell);
  cell.addEventListener("dblclick", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openWorkOrderInlineServicesEditor(cell, workOrder);
  });
}

function getWorkOrderPointTotal(item = {}) {
  const serviceRows = getWorkOrderPointServiceRows(item);
  if (serviceRows.length > 0) {
    const total = serviceRows.reduce((sum, row) => sum + row.points, 0);
    if (Number.isFinite(total)) {
      return Math.round(total * 100) / 100;
    }
  }

  return 0;
}

function getWorkOrderPointServiceRows(item = {}) {
  return getWorkOrderServiceItems(item)
    .map((service) => {
      const factor = getWorkOrderServicePointFactor(service);
      const quantity = getWorkOrderServiceQuantityValue(service);
      const points = Math.round(factor * quantity * 100) / 100;
      return {
        service,
        factor,
        quantity,
        points,
      };
    });
}

function getWorkOrderPointDistributionSettings() {
  const settings = getPeriodicsVisualSettings();
  const fieldSharePercent = normalizePercentValue(
    settings.workOrderFieldSharePercent,
    DEFAULT_PERIODICS_VISUAL_SETTINGS.workOrderFieldSharePercent,
  );
  return {
    fieldSharePercent,
    completionSharePercent: 100 - fieldSharePercent,
  };
}

function buildWorkOrderPointDistribution(item = {}) {
  const totalPoints = getWorkOrderPointTotal(item);
  const serviceRows = getWorkOrderPointServiceRows(item);
  const { fieldSharePercent, completionSharePercent } = getWorkOrderPointDistributionSettings();
  const executors = normalizeWorkOrderExecutorValues(getWorkOrderExecutors(item));
  const completedPeople = normalizeWorkOrderExecutorValues(
    splitWorkOrderCompletedByValue(item.completedBy),
  );
  const allocations = new Map();
  const addAllocation = (name, role, points, percent) => {
    const normalizedName = String(name || "").trim();
    if (!normalizedName) {
      return;
    }
    const key = normalizeLooseName(normalizedName) || normalizedName.toLowerCase();
    const current = allocations.get(key) ?? {
      name: normalizedName,
      roles: new Set(),
      points: 0,
      percent: 0,
    };
    current.roles.add(role);
    current.points += points;
    current.percent += percent;
    allocations.set(key, current);
  };

  const fieldPoints = executors.length > 0 ? (totalPoints * fieldSharePercent) / 100 : 0;
  const completionPoints = completedPeople.length > 0 ? (totalPoints * completionSharePercent) / 100 : 0;
  if (totalPoints > 0) {
    executors.forEach((executor) => {
      addAllocation(executor, "Teren", fieldPoints / executors.length, fieldSharePercent / executors.length);
    });
    completedPeople.forEach((person) => {
      addAllocation(person, "RN završio", completionPoints / completedPeople.length, completionSharePercent / completedPeople.length);
    });
  }

  const people = [...allocations.values()]
    .map((entry) => ({
      ...entry,
      roles: [...entry.roles],
    }))
    .sort((left, right) => (
      right.points - left.points
      || left.name.localeCompare(right.name, "hr", { sensitivity: "base" })
    ));
  const allocatedPoints = people.reduce((sum, entry) => sum + entry.points, 0);

  return {
    totalPoints,
    fieldSharePercent,
    completionSharePercent,
    executors,
    completedPeople,
    people,
    allocatedPoints,
    unallocatedPoints: Math.max(0, totalPoints - allocatedPoints),
    serviceRows,
  };
}

function createWorkOrderExecutorsColumnRatio() {
  const { fieldSharePercent, completionSharePercent } = getWorkOrderPointDistributionSettings();
  const ratio = document.createElement("span");
  ratio.className = "work-group-column-ratio";

  const field = document.createElement("span");
  field.className = "is-field";
  field.textContent = `Teren ${fieldSharePercent}%`;

  const paperwork = document.createElement("span");
  paperwork.className = "is-paper";
  paperwork.textContent = `Papir ${completionSharePercent}%`;

  ratio.append(field, paperwork);
  return ratio;
}

const WORK_ORDER_SCORE_SEGMENT_COLORS = Object.freeze([
  "#5b4dff",
  "#14b8a6",
  "#f59e0b",
  "#ec4899",
  "#0ea5e9",
]);

function createWorkOrderScoreDistributionRail(distribution = {}) {
  const totalPoints = Number(distribution.totalPoints);
  const people = Array.isArray(distribution.people) ? distribution.people : [];
  if (!Number.isFinite(totalPoints) || totalPoints <= 0 || people.length === 0) {
    return null;
  }

  const rail = document.createElement("div");
  rail.className = "work-executor-score-rail";
  rail.setAttribute(
    "aria-label",
    people
      .map((entry) => `${entry.name}: ${formatCompactDecimal(entry.points)}`)
      .join(", "),
  );

  const visiblePeople = people.slice(0, 5);
  visiblePeople.forEach((entry, index) => {
    const segment = document.createElement("span");
    segment.className = "work-executor-score-segment";
    const share = Math.max(4, Math.min(100, (Number(entry.points) / totalPoints) * 100));
    segment.style.setProperty("--score-share", `${share.toFixed(2)}%`);
    segment.style.setProperty("--score-color", WORK_ORDER_SCORE_SEGMENT_COLORS[index % WORK_ORDER_SCORE_SEGMENT_COLORS.length]);
    segment.title = `${entry.name}: ${formatCompactDecimal(entry.points)}`;
    rail.append(segment);
  });

  if (people.length > visiblePeople.length) {
    const morePoints = people
      .slice(visiblePeople.length)
      .reduce((sum, entry) => sum + (Number(entry.points) || 0), 0);
    const more = document.createElement("span");
    more.className = "work-executor-score-segment is-more";
    const share = Math.max(4, Math.min(100, (morePoints / totalPoints) * 100));
    more.style.setProperty("--score-share", `${share.toFixed(2)}%`);
    more.style.setProperty("--score-color", "#94a3b8");
    more.title = `Ostali: ${formatCompactDecimal(morePoints)}`;
    rail.append(more);
  }

  return rail;
}

function createWorkOrderPointDistributionCard(item = {}) {
  const distribution = buildWorkOrderPointDistribution(item);
  const wrap = document.createElement("div");
  wrap.className = "work-executor-score-card";

  const head = document.createElement("div");
  head.className = "work-executor-score-head";
  const headCopy = document.createElement("div");
  headCopy.className = "work-executor-score-total";
  const total = document.createElement("strong");
  total.textContent = formatCompactDecimal(distribution.totalPoints);
  const totalLabel = document.createElement("span");
  totalLabel.textContent = "bodova";
  headCopy.append(total, totalLabel);
  head.append(headCopy);
  const rail = createWorkOrderScoreDistributionRail(distribution);
  if (rail) {
    head.append(rail);
  }
  wrap.append(head);

  if (distribution.totalPoints <= 0) {
    const empty = document.createElement("span");
    empty.className = "work-executor-empty work-executor-load-empty";
    empty.textContent = distribution.serviceRows.length > 0
      ? "— Faktori ili količine su 0 b"
      : "— Dodaj usluge i količine za bodove";
    wrap.append(empty);
    return wrap;
  }

  if (distribution.people.length === 0) {
    const empty = document.createElement("span");
    empty.className = "work-executor-empty work-executor-load-empty";
    empty.textContent = "— Nije dodijeljeno";
    wrap.append(empty);
    return wrap;
  }

  const list = document.createElement("div");
  list.className = "work-executor-score-list";
  const visiblePeople = distribution.people.slice(0, 4);
  visiblePeople.forEach((entry, index) => {
    const row = document.createElement("div");
    row.className = "work-executor-score-row";
    row.style.setProperty("--score", `${Math.min(100, Math.max(0, entry.percent)).toFixed(2)}%`);

    const avatar = createWorkOrderMiniExecutor(entry.name, {
      className: "work-order-mini-executor work-executor-score-avatar",
    });

    const copy = document.createElement("div");
    copy.className = "work-executor-score-copy";
    const title = document.createElement("strong");
    title.textContent = entry.name;
    const roles = document.createElement("div");
    roles.className = "work-executor-score-roles";
    entry.roles.forEach((role) => {
      const rolePill = document.createElement("span");
      rolePill.className = role === "Teren"
        ? "is-field"
        : "is-completed";
      rolePill.textContent = role;
      roles.append(rolePill);
    });
    copy.append(title, roles);

    const value = document.createElement("div");
    value.className = "work-executor-score-value";
    const points = document.createElement("strong");
    points.textContent = `${formatCompactDecimal(entry.points)} b`;
    const percent = document.createElement("span");
    percent.textContent = `${formatCompactDecimal(entry.percent, 1)}%`;
    value.append(points, percent);

    row.append(avatar, copy, value);
    if (index === 0) {
      row.classList.add("is-primary");
    }
    list.append(row);
  });

  if (distribution.people.length > visiblePeople.length) {
    const more = document.createElement("span");
    more.className = "work-executor-load-more";
    more.textContent = `+${distribution.people.length - visiblePeople.length} osoba`;
    list.append(more);
  }
  wrap.append(list);

  return wrap;
}

function renderCompactWorkOrdersList() {
  const filtered = getFilteredWorkOrders();
  const visibleItems = filtered.slice(0, state.workOrderRenderLimit);
  const isExpanded = state.workOrderListDensity === "expanded";
  const columnMode = getWorkOrderListColumnMode();
  const columnLayout = getWorkOrderListColumnLayout(columnMode);
  applyWorkOrderListColumnWidths(columnMode);

  if (workOrdersHelper) {
    workOrdersHelper.textContent = "";
    workOrdersHelper.dataset.baseText = "";
    workOrdersHelper.hidden = true;
  }

  const section = document.createElement("section");
  section.className = "work-group work-group-flat";

  const columns = document.createElement("div");
  columns.className = `work-group-columns is-${isExpanded ? "expanded" : "collapsed"}`;

  columnLayout.forEach((column, columnIndex) => {
    const cell = document.createElement("div");
    cell.className = column.key === "select"
      ? "work-group-column work-group-column-select"
      : "work-group-column";
    cell.dataset.columnKey = column.key;

    if (column.key === "select") {
      cell.dataset.preventRowOpen = "true";

      const selectionControl = document.createElement("label");
      selectionControl.className = "work-order-row-select master";
      selectionControl.dataset.preventRowOpen = "true";
      ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
        selectionControl.addEventListener(eventName, (event) => {
          event.stopPropagation();
        });
      });

      const selectionInput = document.createElement("input");
      selectionInput.type = "checkbox";
      selectionInput.setAttribute("aria-label", "Označi sve prikazane RN-ove");
      selectionInput.dataset.workOrderSelectAll = "true";
      const selectedVisibleCount = visibleItems.filter((item) => state.workOrderDocumentWizard.selectedIds.has(String(item.id))).length;
      selectionInput.checked = visibleItems.length > 0 && selectedVisibleCount === visibleItems.length;
      selectionInput.indeterminate = selectedVisibleCount > 0 && selectedVisibleCount < visibleItems.length;
      selectionInput.addEventListener("change", () => {
        setVisibleWorkOrderDocumentSelection(selectionInput.checked);
      });

      selectionControl.append(selectionInput);
      cell.append(selectionControl);
      columns.append(cell);
      return;
    }

    const title = document.createElement("strong");
    title.className = "work-group-column-title";
    title.textContent = column.title;

    cell.append(title);
    if (column.key === "executors") {
      cell.append(createWorkOrderExecutorsColumnRatio());
    }
    appendWorkOrderListColumnResizeHandle(cell, column, columnIndex, columnMode);
    columns.append(cell);
  });

  const body = document.createElement("div");
  body.className = "work-group-body";

  visibleItems.forEach((item) => {
      const rowCard = document.createElement("section");
      rowCard.className = "work-item-card";
      rowCard.classList.toggle("is-selected", state.workOrderDocumentWizard.selectedIds.has(String(item.id)));
      rowCard.tabIndex = 0;
      rowCard.setAttribute("role", "button");
      rowCard.setAttribute("aria-label", `Otvori radni nalog ${item.workOrderNumber || item.companyName || ""}`.trim());
      rowCard.dataset.workOrderId = String(item.id || "");

      const row = document.createElement("article");
      row.className = `work-item-row is-${isExpanded ? "expanded" : "collapsed"}`;

      const createBasicField = (label, value, options = {}) => {
        const {
          valueClassName = "",
          fieldClassName = "",
        } = options;
        const field = document.createElement("div");
        field.className = ["work-item-basic-field", fieldClassName].filter(Boolean).join(" ");

        const labelNode = document.createElement("span");
        labelNode.className = "work-item-basic-label";
        labelNode.textContent = label;

        const valueNode = document.createElement("strong");
        valueNode.className = ["work-item-basic-value", valueClassName].filter(Boolean).join(" ");
        valueNode.textContent = value || "-";

        field.append(labelNode, valueNode);
        return field;
      };

      const createMetaIcon = (iconName) => {
        const icon = document.createElement("span");
        icon.className = `work-item-meta-icon is-${iconName}`;

        if (iconName === "opened") {
          icon.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2.75V1.5M12 2.75V1.5M2.75 5.25h10.5M3.75 3.5h8.5a1 1 0 0 1 1 1v7.75a1 1 0 0 1-1 1h-8.5a1 1 0 0 1-1-1V4.5a1 1 0 0 1 1-1Z" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.3"/></svg>';
        } else if (iconName === "execution") {
          icon.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4.25 8.15 2.28 2.28 5.22-5.36M8 14a6 6 0 1 0 0-12 6 6 0 0 0 0 12Z" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.3"/></svg>';
        } else {
          icon.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3.25v4l2.5 1.5M8 14a6 6 0 1 0 0-12 6 6 0 0 0 0 12Z" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.3"/></svg>';
        }

        return icon;
      };

      const createIconMetaLine = (iconName, value, options = {}) => {
        const { valueClassName = "", title = "" } = options;
        const line = document.createElement("div");
        line.className = "work-item-meta-line";
        if (title) {
          line.title = title;
        }

        const text = document.createElement("span");
        text.className = ["work-item-meta-value", valueClassName].filter(Boolean).join(" ");
        text.textContent = value || "-";

        line.append(createMetaIcon(iconName), text);
        return line;
      };

      const createValueStack = (primary, secondary = "", tertiary = "", options = {}) => {
        const { tertiaryClassName = "" } = options;
        const stack = document.createElement("div");
        stack.className = "work-item-value-stack";

        const primaryNode = document.createElement("strong");
        primaryNode.className = "work-item-value-primary";
        primaryNode.textContent = primary || "-";
        stack.append(primaryNode);

        if (secondary) {
          const secondaryNode = document.createElement("span");
          secondaryNode.className = "work-item-value-secondary";
          secondaryNode.textContent = secondary;
          stack.append(secondaryNode);
        }

        if (tertiary) {
          const tertiaryNode = document.createElement("span");
          tertiaryNode.className = ["work-item-value-tertiary", tertiaryClassName].filter(Boolean).join(" ");
          tertiaryNode.textContent = tertiary;
          stack.append(tertiaryNode);
        }

        return stack;
      };

      const createInlinePills = (...values) => {
        const filteredValues = values.filter(Boolean);

        if (!filteredValues.length) {
          return null;
        }

        const wrap = document.createElement("div");
        wrap.className = "work-item-inline-pills";
        filteredValues.forEach((value) => {
          const pill = document.createElement("span");
          pill.className = "work-item-inline-pill";
          pill.textContent = value;
          wrap.append(pill);
        });
        return wrap;
      };

      const createTagPill = (value) => {
        if (!value) {
          return null;
        }

        const pill = document.createElement("span");
        pill.className = "work-item-tag-pill";
        pill.textContent = value;
        applyWorkOrderTagTone(pill, value, { soft: true });
        return pill;
      };

      const createPriorityPill = (value) => {
        if (!value) {
          return null;
        }

        const pill = document.createElement("span");
        pill.className = "work-item-priority-pill";
        pill.dataset.priority = slugifyValue(value);

        const icon = document.createElement("span");
        icon.className = "work-item-priority-icon";
        icon.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2.5v11M4 3h6.2c.42 0 .67.47.43.81l-1.05 1.46a.75.75 0 0 0 0 .88l1.05 1.46c.24.34-.01.81-.43.81H4" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.4"/></svg>';

        const text = document.createElement("span");
        text.textContent = value;

        pill.append(icon, text);
        return pill;
      };

      const createCompactInfoLine = (label, value, options = {}) => {
        const line = document.createElement("div");
        line.className = ["work-item-compact-info", options.className || ""].filter(Boolean).join(" ");

        const labelNode = document.createElement("span");
        labelNode.className = "work-item-compact-info-label";
        labelNode.textContent = label;

        const valueNode = document.createElement("strong");
        valueNode.className = "work-item-compact-info-value";
        valueNode.textContent = value || "-";

        line.append(labelNode, valueNode);
        return line;
      };

      const createContractPill = (value) => {
        const normalizedValue = String(value || "").trim();

        if (!normalizedValue) {
          return null;
        }

        const pill = document.createElement("span");
        pill.className = "work-item-contract-pill";
        pill.textContent = `Ugovor: ${normalizedValue}`;
        return pill;
      };

      const createTagPillList = (value) => {
        const values = Array.from(new Set(String(value || "")
          .split(/[|,;/]+/u)
          .map((entry) => entry.trim())
          .filter(Boolean)));

        if (!values.length) {
          return null;
        }

        const wrap = document.createElement("div");
        wrap.className = "work-item-tag-list";
        values.slice(0, 3).forEach((tag) => {
          const pill = createTagPill(tag);
          if (pill) {
            wrap.append(pill);
          }
        });

        if (values.length > 3) {
          const overflow = document.createElement("span");
          overflow.className = "work-item-tag-pill is-muted";
          overflow.textContent = `+${values.length - 3}`;
          wrap.append(overflow);
        }

        return wrap;
      };

      const createServiceBulletList = (items = [], fallbackSummary = "") => {
        const labels = Array.from(new Set([
          ...items.map((service) => {
            const label = String(service.name || service.serviceName || service.serviceCode || "").trim();
            const quantity = getWorkOrderServiceQuantityValue(service);
            return label ? `${label}${quantity !== 1 ? ` x ${formatCompactDecimal(quantity)}` : ""}` : "";
          }),
          ...String(fallbackSummary || "")
            .split(/[·|,;/]+/u)
            .map((entry) => entry.trim()),
        ].filter(Boolean)));

        const wrap = document.createElement("div");
        wrap.className = "work-item-service-list";

        if (!labels.length) {
          const empty = document.createElement("span");
          empty.className = "work-item-service-empty";
          empty.textContent = "Bez usluge";
          wrap.append(empty);
          return wrap;
        }

        const list = document.createElement("ul");
        labels.slice(0, 3).forEach((label) => {
          const itemNode = document.createElement("li");
          itemNode.textContent = label;
          list.append(itemNode);
        });
        wrap.append(list);

        if (labels.length > 3) {
          const overflow = document.createElement("button");
          overflow.type = "button";
          overflow.className = "work-item-service-more";
          overflow.textContent = `+${labels.length - 3} više`;
          overflow.dataset.preventRowOpen = "true";
          overflow.addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            rowCard.classList.toggle("is-expanded");
            list.replaceChildren(...labels
              .slice(0, rowCard.classList.contains("is-expanded") ? labels.length : 3)
              .map((label) => {
                const itemNode = document.createElement("li");
                itemNode.textContent = label;
                return itemNode;
              }));
            overflow.textContent = rowCard.classList.contains("is-expanded")
              ? "Prikaži manje"
              : `+${labels.length - 3} više`;
          });
          wrap.append(overflow);
        }

        return wrap;
      };

      const formatWorkOrderInvoiceAmount = (value) => {
        const rawValue = String(value ?? "").trim();

        if (!rawValue) {
          return "Bez iznosa";
        }

        const numericValue = parseOfferMoneyInput(rawValue, 0);
        if (Number.isFinite(numericValue) && numericValue > 0) {
          return formatCurrencyAmount(numericValue, "EUR");
        }

        return rawValue;
      };

      rowCard.classList.add("is-clickable");
      const openWorkOrderFromRow = (event) => {
        if (isInteractiveWorkOrderTarget(event.target)) {
          return;
        }
        hydrateWorkOrderForm(item);
      };
      rowCard.addEventListener("click", openWorkOrderFromRow, { capture: true });
      rowCard.addEventListener("keydown", (event) => {
        if (isInteractiveWorkOrderTarget(event.target)) {
          return;
        }
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          hydrateWorkOrderForm(item);
        }
      });
      rowCard.addEventListener("contextmenu", (event) => {
        if (isInteractiveWorkOrderTarget(event.target)) {
          return;
        }
        event.preventDefault();
        event.stopPropagation();
        openWorkOrderRowMenu(item, event.clientX, event.clientY);
      });
      bindWorkOrderRowDocumentDropTarget(rowCard, item);

      const selectionCell = document.createElement("div");
      selectionCell.className = "work-item-cell work-item-select-cell";
      selectionCell.dataset.preventRowOpen = "true";
      ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
        selectionCell.addEventListener(eventName, (event) => {
          event.stopPropagation();
        });
      });

      const selectionToggle = document.createElement("label");
      selectionToggle.className = "work-order-row-select";
      selectionToggle.dataset.preventRowOpen = "true";

      const selectionCheckbox = document.createElement("input");
      selectionCheckbox.type = "checkbox";
      selectionCheckbox.checked = state.workOrderDocumentWizard.selectedIds.has(String(item.id));
      selectionCheckbox.setAttribute("aria-label", `Oznaci RN ${item.workOrderNumber || item.companyName || ""}`.trim());
      selectionCheckbox.addEventListener("change", () => {
        toggleWorkOrderDocumentSelection(item.id, selectionCheckbox.checked);
      });

      selectionToggle.append(selectionCheckbox);
      selectionCell.append(selectionToggle);

      const basicCell = document.createElement("div");
      basicCell.className = "work-item-cell work-item-cell-group";

      const basicsStack = document.createElement("div");
      basicsStack.className = "work-item-basic-stack";

      const numberField = document.createElement("div");
      numberField.className = "work-item-number-line";
      numberField.dataset.preventRowOpen = "true";
      numberField.addEventListener("click", (event) => {
        event.stopPropagation();
        hydrateWorkOrderForm(item);
      });
      const numberValue = document.createElement("strong");
      numberValue.className = "work-item-basic-value is-work-order-number";
      numberValue.textContent = item.workOrderNumber || "Bez broja";
      numberField.append(numberValue);
      basicsStack.append(numberField);

      const statusRow = document.createElement("div");
      statusRow.className = "work-item-basic-field work-item-status-row";
      statusRow.dataset.preventRowOpen = "true";

      ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
        statusRow.addEventListener(eventName, (event) => {
          event.stopPropagation();
        });
      });

      statusRow.append(createWorkOrderStatusDropdown(item));
      basicsStack.append(statusRow);

      const dueDistance = item.dueDate
        ? getDateDistanceInDays(getWorkOrderDateKey(item.dueDate), getTodayDateKey())
        : NaN;
      const dueToneClass = isOverdueWorkOrder(item)
        ? "is-overdue"
        : Number.isFinite(dueDistance) && dueDistance > 0
          ? "is-future"
          : "";
      const datesStack = document.createElement("div");
      datesStack.className = `work-item-date-stack${isExpanded ? "" : " is-compact"}`;
      datesStack.dataset.preventRowOpen = "true";
      datesStack.append(
        createIconMetaLine("opened", `Otvoren: ${formatCompactOpenedDate(item.openedDate)}`, {
          valueClassName: "is-subtle-date",
        }),
        createIconMetaLine("due", `Rok: ${formatCompactDueDate(item.dueDate)}`, {
          valueClassName: ["is-subtle-date", dueToneClass].join(" "),
        }),
        createIconMetaLine("execution", `Izvršenje: ${item.executionDate ? formatCompactDate(item.executionDate) : "—"}`, {
          valueClassName: ["is-subtle-date", item.executionDate ? "" : "is-muted"].join(" "),
          title: "Datum izvršenja",
        }),
      );
      attachWorkOrderInlineFieldEditor(datesStack, item, {
        title: "Datumi RN-a",
        fields: [
          { key: "openedDate", label: "Datum otvaranja", type: "date" },
          { key: "dueDate", label: "Rok završetka", type: "date" },
          { key: "executionDate", label: "Datum izvršenja", type: "date" },
        ],
      });
      basicsStack.append(datesStack);

      basicCell.append(basicsStack);

      const clientCell = document.createElement("div");
      clientCell.className = "work-item-cell work-item-cell-group";
      const headquartersCell = document.createElement("div");
      headquartersCell.className = "work-item-cell work-item-cell-group work-item-headquarters-cell";
      const regionCell = document.createElement("div");
      regionCell.className = "work-item-cell work-item-cell-group work-item-region-cell";
      const locationCell = document.createElement("div");
      locationCell.className = "work-item-cell work-item-cell-group";
      const contactCell = document.createElement("div");
      contactCell.className = "work-item-cell work-item-cell-group";
      const serviceCell = document.createElement("div");
      serviceCell.className = "work-item-cell work-item-cell-group work-item-services-cell";
      const serviceDescription = looksLikeWorkOrderLog(item.description) ? "" : item.description;
      const serviceItems = getWorkOrderServiceItems(item);
      const serviceSummary = getWorkOrderServiceSummary(item);

      const contractValue = item.contractType || getWorkOrderClientPills(item)[0] || normalizeWorkOrderClientReference(item.linkReference);
      clientCell.append(createValueStack(
        item.companyName || "Bez tvrtke",
        getWorkOrderColumnFieldVisibility("headquarters") && item.headquarters ? item.headquarters : "",
        getWorkOrderColumnFieldVisibility("companyOib") && item.companyOib ? `OIB: ${item.companyOib}` : "",
      ));
      if (getWorkOrderColumnFieldVisibility("contract")) {
        const contractPill = createContractPill(contractValue);
        if (contractPill) {
          clientCell.append(contractPill);
        }
      }

      headquartersCell.append(createValueStack(
        item.headquarters || "Bez sjedišta",
        item.companyName || "",
      ));

      regionCell.append(createValueStack(
        item.region || "Bez regije",
        item.department || "",
      ));

      locationCell.append(createValueStack(
        item.locationName || "Bez lokacije",
        getWorkOrderColumnFieldVisibility("region") && item.region ? item.region : "",
        getWorkOrderColumnFieldVisibility("coordinates") && item.coordinates ? item.coordinates : "",
      ));

      contactCell.append(createValueStack(
        item.contactName || item.contactPhone || "Bez kontakta",
        getWorkOrderColumnFieldVisibility("contactPhone") ? item.contactPhone || "" : "",
        getWorkOrderColumnFieldVisibility("contactEmail") ? item.contactEmail || "" : "",
      ));

      if (item.department) {
        const departmentPill = document.createElement("span");
        departmentPill.className = "work-item-department-pill";
        departmentPill.textContent = item.department;
        serviceCell.append(departmentPill);
      }

      serviceCell.append(createServiceBulletList(serviceItems, serviceSummary));

      if (!serviceItems.length && serviceDescription && isExpanded) {
        const serviceNote = document.createElement("div");
        serviceNote.className = "work-item-service-note";
        serviceNote.textContent = serviceDescription;
        serviceCell.append(serviceNote);
      }

      const financeCell = document.createElement("div");
      financeCell.className = "work-item-cell work-item-cell-group work-item-finance-cell work-item-billing-cell";
      financeCell.append(
        createCompactInfoLine("Broj", item.invoiceNote || "—", {
          className: "is-invoice-note",
        }),
        createCompactInfoLine("Iznos", formatWorkOrderInvoiceAmount(item.weight), {
          className: "is-amount",
        }),
        createCompactInfoLine("Datum", item.invoiceDate ? formatCompactDate(item.invoiceDate) : "—", {
          className: "is-date",
        }),
      );

      const priorityTagsCell = document.createElement("div");
      priorityTagsCell.className = "work-item-cell work-item-cell-group work-item-priority-tags-cell";
      const priorityPill = createPriorityPill(
        item.priority ? getOptionLabel(PRIORITY_OPTIONS, item.priority) : "",
      );
      const tagList = createTagPillList(item.tagText || "");
      if (priorityPill) {
        priorityTagsCell.append(priorityPill);
      }
      if (tagList) {
        priorityTagsCell.append(tagList);
      }
      if (!priorityTagsCell.childElementCount) {
        priorityTagsCell.append(createValueStack("Bez prioriteta", "Bez tagova"));
      }
      const priorityServicesCell = document.createElement("div");
      priorityServicesCell.className = "work-item-cell work-item-cell-group work-item-priority-services-cell";
      const priorityBlock = document.createElement("div");
      priorityBlock.className = "work-item-priority-service-block";
      priorityBlock.append(...Array.from(priorityTagsCell.cloneNode(true).childNodes));
      const servicesBlock = document.createElement("div");
      servicesBlock.className = "work-item-priority-service-block is-services";
      servicesBlock.append(...Array.from(serviceCell.cloneNode(true).childNodes));
      priorityServicesCell.append(priorityBlock, servicesBlock);

      attachWorkOrderInlinePriorityEditor(priorityTagsCell, item);
      attachWorkOrderInlineLocationEditor(locationCell, item);
      attachWorkOrderInlineContactEditor(contactCell, item);
      attachWorkOrderInlineServicesEditor(serviceCell, item);
      attachWorkOrderInlineFieldEditor(financeCell, item, {
        title: "Faktura i završetak",
        fields: [
          { key: "invoiceDate", label: "Datum fakture", type: "date" },
          { key: "invoiceNote", label: "Broj fakture" },
          { key: "completedBy", label: "RN završio" },
          { key: "weight", label: "Iznos" },
        ],
      });

      const executorsCell = document.createElement("div");
      executorsCell.className = "work-item-cell work-item-cell-group work-item-executors-cell";
      executorsCell.append(createWorkOrderPointDistributionCard(item));
      attachWorkOrderInlineExecutorsEditor(executorsCell, item);

      const actionsCell = document.createElement("div");
      actionsCell.className = "work-item-cell work-item-actions-cell";
      actionsCell.dataset.preventRowOpen = "true";
      ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
        actionsCell.addEventListener(eventName, (event) => {
          event.stopPropagation();
        });
      });

      const menuButton = document.createElement("button");
      menuButton.type = "button";
      menuButton.className = "work-item-action-button work-item-menu-button";
      menuButton.title = "Akcije";
      menuButton.setAttribute("aria-label", `Akcije za RN ${item.workOrderNumber || ""}`.trim());
      menuButton.innerHTML = '<span aria-hidden="true">⋮</span>';
      menuButton.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const rect = menuButton.getBoundingClientRect();
        openWorkOrderRowMenu(item, rect.left, rect.bottom);
      });
      actionsCell.append(menuButton);

      const rowCellsByKey = {
        select: selectionCell,
        basic: basicCell,
        client: clientCell,
        headquarters: headquartersCell,
        region: regionCell,
        location: locationCell,
        contact: contactCell,
        service: serviceCell,
        services: serviceCell,
        billing: financeCell,
        finance: financeCell,
        priorityTags: priorityTagsCell,
        priorityServices: priorityServicesCell,
        executors: executorsCell,
        actions: actionsCell,
      };
      row.append(...columnLayout.map((column) => rowCellsByKey[column.key]).filter(Boolean));
      rowCard.append(row);
      body.append(rowCard);
  });

  section.append(columns, body);
  workOrdersBody.replaceChildren(section);

  workOrdersEmpty.hidden = filtered.length !== 0;

  if (filtered.length === 0) {
    workOrdersLoadState.hidden = true;
    workOrdersLoadState.textContent = "";
    updateWorkOrderDocumentSelectionChrome({ visibleItems });
    return;
  }

  workOrdersLoadState.hidden = false;
  workOrdersLoadState.textContent = visibleItems.length < filtered.length
    ? `Prikazano ${visibleItems.length} od ${filtered.length} RN. Skrolaj dalje za jos.`
    : `Prikazano svih ${filtered.length} RN.`;
  if (workOrdersHelper) {
    workOrdersHelper.dataset.baseText = workOrdersLoadState.textContent;
  }
  updateWorkOrderDocumentSelectionChrome({ visibleItems });
}

function renderCompanies() {
  clearLegacyCompanyCopy();
  initializeCompaniesColumnResize();
  const canViewCompanies = getCanViewCompanies();
  const canCreateCompany = getCanCreateCompany();
  const canEditCompany = getCanEditCompany();

  if (companyOpenFormButton) {
    companyOpenFormButton.hidden = !canCreateCompany;
  }

  if (!canViewCompanies) {
    companiesListRenderSignature = "";
    companiesKpiRow?.replaceChildren();
    companiesBody.replaceChildren();
    companiesEmpty.hidden = false;
    companiesEmpty.textContent = "Nemaš ovlaštenje za pregled tvrtki.";
    closeCompanyEditor({ reset: false });
    return;
  }

  const sortedCompanies = state.companies
    .slice()
    .sort((left, right) => left.name.localeCompare(right.name, "hr"));
  const contractSummaryMap = buildCompanyListContractSummaryMap(state.contracts);
  renderCompaniesKpiRow(sortedCompanies, contractSummaryMap);
  const queryNeedle = normalizeLooseName(state.companyFilters.query || "");
  const periodFilter = ["all", "active", "inactive"].includes(state.companyFilters.periodStatus)
    ? state.companyFilters.periodStatus
    : "all";
  const activityFilter = ["all", "active", "inactive"].includes(state.companyFilters.activityStatus)
    ? state.companyFilters.activityStatus
    : "all";
  const filteredCompanies = [];
  const rowSnapshots = [];

  sortedCompanies.forEach((company) => {
    if (!matchesCompanySearch(company, queryNeedle)) {
      return;
    }

    if (periodFilter !== "all" && normalizeCompanyPeriodStatus(company.period) !== periodFilter) {
      return;
    }

    if (activityFilter !== "all") {
      const isActive = Boolean(company.isActive);
      if (activityFilter === "active" && !isActive) {
        return;
      }
      if (activityFilter === "inactive" && isActive) {
        return;
      }
    }

    filteredCompanies.push(company);
    rowSnapshots.push(buildCompanyListRowSnapshot(
      company,
      contractSummaryMap.get(String(company.id || "").trim()) ?? null,
    ));
  });

  if (companiesSearchInput && companiesSearchInput.value !== state.companyFilters.query) {
    companiesSearchInput.value = state.companyFilters.query;
  }

  if (companiesPeriodFilterInput && companiesPeriodFilterInput.value !== periodFilter) {
    companiesPeriodFilterInput.value = periodFilter;
  }

  if (companiesActivityFilterInput && companiesActivityFilterInput.value !== activityFilter) {
    companiesActivityFilterInput.value = activityFilter;
  }

  const bodySignature = [
    canEditCompany ? "edit" : "view",
    ...rowSnapshots.map((rowSnapshot) => rowSnapshot.signature),
  ].join("||");

  if (bodySignature !== companiesListRenderSignature) {
    const fragment = document.createDocumentFragment();

    rowSnapshots.forEach((rowSnapshot) => {
      const row = document.createElement("tr");
      row.className = "list-row company-list-row";
      row.classList.toggle("is-expanded", rowSnapshot.isExpanded);
      row.dataset.companyId = rowSnapshot.companyId;

      if (canEditCompany) {
        row.tabIndex = 0;
        row.setAttribute("role", "button");
        row.setAttribute("aria-label", rowSnapshot.ariaLabel);
      }

      row.append(
        createCompanyIdentityCell(rowSnapshot.company, rowSnapshot),
        createCompanyContactCell(rowSnapshot),
        createCompanyPortalCell(rowSnapshot),
        createCompanyContractsCell(rowSnapshot),
        createCompanyActivityCell(rowSnapshot),
      );

      fragment.append(row);
      if (rowSnapshot.isExpanded) {
        const detailRow = document.createElement("tr");
        detailRow.className = "company-list-expand-row";
        const detailCell = document.createElement("td");
        detailCell.colSpan = 5;
        detailCell.append(createCompanyListExpansion(rowSnapshot));
        detailRow.append(detailCell);
        fragment.append(detailRow);
      }
    });

    companiesBody.replaceChildren(fragment);
    companiesListRenderSignature = bodySignature;
  }

  const hasFilters = Boolean(queryNeedle) || periodFilter !== "all" || activityFilter !== "all";
  companiesEmpty.hidden = filteredCompanies.length !== 0;
  if (companiesEmpty) {
    companiesEmpty.textContent = sortedCompanies.length === 0
      ? "Nema unesenih tvrtki."
      : hasFilters
        ? "Nema tvrtki za odabrane filtere."
        : "Nema unesenih tvrtki.";
  }
}

function renderLocations() {
  const sortedLocations = state.locations
    .slice()
    .sort((left, right) => {
      const leftCompany = getCompany(left.companyId)?.name ?? "";
      const rightCompany = getCompany(right.companyId)?.name ?? "";
      const companyCompare = leftCompany.localeCompare(rightCompany, "hr");

      if (companyCompare !== 0) {
        return companyCompare;
      }

      return left.name.localeCompare(right.name, "hr");
    });
  const queryNeedle = normalizeLooseName(state.locationFilters.query || "");
  const filteredLocations = sortedLocations.filter((location) => matchesLocationSearch(location, queryNeedle));
  const renderLimit = Math.max(LOCATION_LIST_BATCH_SIZE, Number(state.locationRenderLimit) || LOCATION_LIST_BATCH_SIZE);
  const visibleLocations = filteredLocations.slice(0, renderLimit);
  const canViewLocations = getCanViewLocations();
  const canCreateLocations = getCanCreateLocations();
  const canEditLocations = getCanEditLocations();

  if (locationOpenFormButton) {
    locationOpenFormButton.hidden = !canCreateLocations;
    locationOpenFormButton.disabled = state.companies.length === 0;
  }

  if (locationsSearchInput && locationsSearchInput.value !== state.locationFilters.query) {
    locationsSearchInput.value = state.locationFilters.query;
  }

  if (!canViewLocations) {
    locationsBody.replaceChildren();
    locationsEmpty.hidden = false;
    locationsEmpty.textContent = "Nemas ovlastenje za pregled lokacija.";
    if (locationsHelper) {
      locationsHelper.textContent = "Pregled lokacija je dostupan samo rolama s ovlastenjem.";
    }
    if (locationsLoadMoreButton) {
      locationsLoadMoreButton.hidden = true;
    }
    closeLocationEditor({ reset: false });
    return;
  }

  if (locationsHelper) {
    if (filteredLocations.length === 0) {
      locationsHelper.textContent = sortedLocations.length === 0
        ? "Nema lokacija za prikaz."
        : "Nema lokacija za zadanu pretragu.";
    } else if (visibleLocations.length < filteredLocations.length) {
      locationsHelper.textContent = `Prikazano ${visibleLocations.length} od ${filteredLocations.length} lokacija. Pretraga odmah sužava cijelu listu.`;
    } else {
      locationsHelper.textContent = filteredLocations.length === sortedLocations.length
        ? `${filteredLocations.length} lokacija u listi.`
        : `Prikazano svih ${filteredLocations.length} od ${sortedLocations.length} lokacija.`;
    }
  }

  const fragment = document.createDocumentFragment();
  visibleLocations.forEach((location) => {
    const row = document.createElement("tr");
    row.className = "list-row";
    if (canEditLocations) {
      row.classList.add("is-clickable");
      row.tabIndex = 0;
    }
    const company = getCompany(location.companyId);
    const companyName = company?.name ?? "Nepoznata tvrtka";
    const contacts = buildLocationContacts(location);
    const primaryContact = contacts[0] ?? {};
    const openLocation = () => {
      if (canEditLocations) {
        hydrateLocationForm(location);
      }
    };
    row.addEventListener("click", (event) => {
      if (event.target.closest("button, a, input, select, textarea")) {
        return;
      }
      openLocation();
    });
    row.addEventListener("keydown", (event) => {
      if (!canEditLocations) {
        return;
      }
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openLocation();
      }
    });

    row.append(
      createStackCell({
        eyebrow: "Tvrtka",
        title: companyName,
        subtitle: company?.headquarters || "Bez sjedišta",
        meta: company?.oib ? [`OIB ${company.oib}`] : [],
      }),
      createStackCell({
        eyebrow: "Lokacija",
        title: location.name || "Bez naziva",
        subtitle: location.coordinates || "Bez koordinata",
        meta: [location.region || "Bez regije"].filter(Boolean),
      }),
      createStackCell({
        eyebrow: "Kontakt",
        title: primaryContact.name || location.representative || "Bez kontakt osobe",
        subtitle: [primaryContact.email, primaryContact.phone].filter(Boolean).join(" · ") || "Bez emaila i telefona",
        meta: contacts.length > 1 ? [`+${contacts.length - 1} dodatnih`] : [],
      }),
      createStackCell({
        title: location.isActive ? "Aktivna lokacija" : "Neaktivna lokacija",
        subtitle: location.period ? `Periodika: ${location.period}` : "Bez periodike",
        meta: [createStatusPill(location.isActive ? "Aktivno" : "Neaktivno", location.isActive)],
      }),
    );

    fragment.append(row);
  });

  locationsBody.replaceChildren(fragment);

  locationsEmpty.hidden = filteredLocations.length !== 0;
  locationsEmpty.textContent = sortedLocations.length === 0
    ? "Nema unesenih lokacija."
    : queryNeedle
      ? "Nema lokacija za zadanu pretragu."
      : "Nema unesenih lokacija.";

  if (locationsLoadMoreButton) {
    const hidden = visibleLocations.length >= filteredLocations.length;
    locationsLoadMoreButton.hidden = hidden;
    locationsLoadMoreButton.textContent = hidden
      ? "Sve lokacije su prikazane"
      : `Prikaži još ${Math.min(LOCATION_LIST_BATCH_SIZE, filteredLocations.length - visibleLocations.length)} lokacija`;
  }
}

function updatePeopleUserSheetChrome(users = []) {
  const activeCount = users.filter((user) => user?.isActive !== false).length;
  const inactiveCount = users.filter((user) => user?.isActive === false).length;
  const activeSheet = normalizePeopleUserSheet(state.peopleUserSheet);

  if (peopleUserActiveCount) {
    peopleUserActiveCount.textContent = String(activeCount);
  }

  if (peopleUserInactiveCount) {
    peopleUserInactiveCount.textContent = String(inactiveCount);
  }

  peopleUserSheetButtons.forEach((button) => {
    const sheet = normalizePeopleUserSheet(button.dataset.peopleUserSheet);
    const isActive = sheet === activeSheet;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
    button.tabIndex = isActive ? 0 : -1;
  });
}

function createPeopleUserActivityCell(user, { canEditUser = false } = {}) {
  const cell = document.createElement("td");
  const stack = document.createElement("div");
  stack.className = "list-cell people-user-activity-cell";
  stack.append(createStatusPill(user.isActive ? "Aktivno" : "Neaktivno", user.isActive));

  const isCurrentUser = String(user?.id || "") === String(state.user?.id || "");
  if (isCurrentUser) {
    stack.append(createListLine("Tvoj račun", "list-tertiary"));
  }

  if (canEditUser) {
    const actionWrap = document.createElement("div");
    actionWrap.className = "people-user-activity-actions";

    const resetButton = document.createElement("button");
    resetButton.type = "button";
    resetButton.className = "people-user-sheet-action";
    resetButton.textContent = "Lozinka";
    resetButton.title = "Pošalji privremenu lozinku korisniku";
    resetButton.disabled = user.isActive === false;
    resetButton.addEventListener("click", (event) => {
      event.stopPropagation();
      if (user.isActive === false) {
        return;
      }
      if (!window.confirm(`Poslati privremenu lozinku korisniku ${user.fullName || user.email}?`)) {
        return;
      }
      void runMutation(() => apiRequest(`/users/${encodeURIComponent(String(user.id))}/password-reset`, {
        method: "POST",
      }), userError).then((success) => {
        if (success) {
          setInlineMessage(userError, "Privremena lozinka je poslana na email korisnika.", "success");
        }
      });
    });

    const toggleButton = document.createElement("button");
    toggleButton.type = "button";
    toggleButton.className = `people-user-sheet-action ${user.isActive ? "is-archive" : "is-restore"}`;
    toggleButton.textContent = user.isActive ? "Deaktiviraj" : "Vrati";
    toggleButton.disabled = isCurrentUser;
    toggleButton.title = isCurrentUser
      ? "Ne možeš deaktivirati vlastiti račun"
      : user.isActive
        ? "Makni korisnika iz aktivnog tima bez brisanja povijesti"
        : "Vrati korisnika u aktivni tim";
    toggleButton.addEventListener("click", (event) => {
      event.stopPropagation();
      if (isCurrentUser) {
        return;
      }
      const nextActive = user.isActive === false;
      const actionLabel = nextActive ? "vratiti u aktivne korisnike" : "deaktivirati";
      if (!window.confirm(`Želiš ${actionLabel} korisnika ${user.fullName || user.email}?`)) {
        return;
      }
      void runMutation(() => apiRequest(`/users/${encodeURIComponent(String(user.id))}`, {
        method: "PATCH",
        body: {
          isActive: String(nextActive),
        },
      }), userError);
    });

    actionWrap.append(resetButton, toggleButton);
    stack.append(actionWrap);
  }

  cell.append(stack);
  return cell;
}

function renderUsers() {
  const showAccountAccess = isControlPanelUserManagementScope();
  const directoryTable = usersBody?.closest("table");
  directoryTable?.classList.toggle("is-account-access-mode", showAccountAccess);
  if (usersMetaHeader) {
    usersMetaHeader.hidden = !showAccountAccess;
    usersMetaHeader.textContent = showAccountAccess ? "Pristup" : "";
  }

  updatePeopleUserSheetChrome(state.users);
  renderPeopleIsznrPanel();

  const activeSheet = normalizePeopleUserSheet(state.peopleUserSheet);
  const scopedUsers = showAccountAccess
    ? [...state.users]
    : state.users.filter((user) => (activeSheet === "inactive" ? user?.isActive === false : user?.isActive !== false));

  const sortedUsers = [...scopedUsers].sort((left, right) => String(
    left.displayName || left.fullName || left.email || "",
  ).localeCompare(
    String(right.displayName || right.fullName || right.email || ""),
    "hr",
  ));

  if (sortedUsers.length === 0) {
    const row = document.createElement("tr");
    row.className = "list-row is-empty";
    const cell = document.createElement("td");
    cell.className = "empty-cell";
    cell.colSpan = showAccountAccess ? 5 : 4;
    cell.textContent = showAccountAccess
      ? "Nema korisnika za prikaz."
      : activeSheet === "inactive"
        ? "Nema neaktivnih korisnika."
        : "Nema aktivnih korisnika.";
    row.append(cell);
    usersBody.replaceChildren(row);
    return;
  }

  usersBody.replaceChildren(...sortedUsers.map((user) => {
    const row = document.createElement("tr");
    row.className = "list-row";
    const canEditUser = canManageRenderedUser(user);
    const roleSummary = getUserRoleSummary(user);

    if (canEditUser) {
      row.classList.add("is-clickable");
      row.tabIndex = 0;
      row.addEventListener("click", (event) => {
        if (event.target.closest("button, a, input, select, textarea")) {
          return;
        }

        hydrateUserForm(user);
      });
      row.addEventListener("keydown", (event) => {
        if (event.target !== row) {
          return;
        }

        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          hydrateUserForm(user);
        }
      });
    }

    row.append(
      createUserIdentityCell(user),
      createStackCell({
        title: getUserOrganizationSummary(user)
      }),
      createStackCell({
        title: roleSummary.title
      }),
      createPeopleUserActivityCell(user, { canEditUser })
    );

    if (showAccountAccess) {
      row.append(createUserAccountAccessCell(user));
    }

    return row;
  }));
}

function renderLoginContentItems() {
  loginContentBody.replaceChildren(...state.loginContentItems.map((item) => {
    const row = document.createElement("tr");
    row.className = "list-row";
    const actionsCell = document.createElement("td");
    actionsCell.className = "table-actions";
    actionsCell.append(
      createActionButton("Uredi", "card-button", () => hydrateLoginContentForm(item)),
      createActionButton("Obriši", "card-button card-danger", () => {
        if (!window.confirm("Obrisati ovu login priču?")) {
          return;
        }

        void runMutation(() => apiRequest(`/login-content/${item.id}`, { method: "DELETE" }), loginContentError);
      }),
    );

    row.append(
      createStackCell({
        title: item.quoteText,
      }),
      createStackCell({
        title: item.authorName || "Bez autora",
      }),
      actionsCell,
    );

    return row;
  }));
}

function renderSignupRequests() {
  if (!signupRequestsBody) {
    return;
  }

  const requests = [...(state.signupRequests ?? [])].sort((left, right) => {
    const statusDelta = (String(left.status || "pending") === "pending" ? 0 : 1)
      - (String(right.status || "pending") === "pending" ? 0 : 1);
    if (statusDelta !== 0) {
      return statusDelta;
    }
    return String(right.requestedAt || "").localeCompare(String(left.requestedAt || ""));
  });

  if (requests.length === 0) {
    const row = document.createElement("tr");
    const cell = document.createElement("td");
    cell.colSpan = 5;
    cell.className = "empty-cell";
    cell.textContent = "Nema signup zahtjeva za aktivni opseg.";
    row.append(cell);
    signupRequestsBody.replaceChildren(row);
    return;
  }

  signupRequestsBody.replaceChildren(...requests.map((request) => {
    const row = document.createElement("tr");
    row.className = "list-row";

    const actionsCell = document.createElement("td");
    actionsCell.className = "table-actions";

    if (request.status === "pending") {
      actionsCell.append(createSignupRequestActions(request));
    } else {
      actionsCell.append(createSignupRequestActions(request));
    }

    row.append(
      createStackCell({
        title: request.fullName || request.email,
        subtitle: request.email,
        tertiary: request.phone || "",
      }),
      createStackCell({
        title: getSignupRequestOrganizationLabel(request),
        subtitle: request.organizationOib ? `OIB ${request.organizationOib}` : "Bez OIB-a",
        tertiary: request.note || "",
      }),
      createStackCell({
        title: getSignupRequestStatusLabel(request.status),
        subtitle: request.emailStatus ? `Email: ${request.emailStatus}` : "Bez email loga",
      }),
      createStackCell({
        title: getSignupRequestRequestedLabel(request),
        subtitle: request.processedAt ? `Rijeseno ${formatDate(request.processedAt.slice(0, 10))}` : "Ceka odluku",
      }),
      actionsCell,
    );

    return row;
  }));
}

function renderManagement() {
  const currentOrganization = state.organizations.find((item) => item.id === state.activeOrganizationId)
    ?? state.organizations[0]
    ?? null;
  const activePeopleTab = normalizePeopleWorkspaceTab(state.peopleWorkspaceTab);
  const activePeopleTabConfig = getPeopleWorkspaceTabConfig(activePeopleTab);
  const isUsersTab = activePeopleTab === "users";
  const isAbsenceTab = activePeopleTab === "annual-leave" || activePeopleTab === "sick-leave";
  const isAbsenceReportTab = activePeopleTab === "absence-report";

  if (isUsersTab) {
    setUserManagementScope("people");
  }

  const userManagementScopeConfig = getUserManagementScopeConfig();
  const userManagementDescription = isUsersTab
    ? userManagementScopeConfig.description
    : activePeopleTabConfig.description;
  const hasUserManagementDescription = Boolean(String(userManagementDescription || "").trim());

  if (managementIntroPanel) {
    managementIntroPanel.hidden = true;
  }

  if (organizationPanel) {
    organizationPanel.hidden = true;
  }

  if (signupRequestsPanel) {
    signupRequestsPanel.hidden = true;
  }

  if (loginContentPanel) {
    loginContentPanel.hidden = true;
  }

  if (peopleWorkspaceCopy) {
    peopleWorkspaceCopy.textContent = userManagementDescription;
    peopleWorkspaceCopy.hidden = !hasUserManagementDescription;
  }

  syncUserManagementListChrome();

  peopleWorkspaceTabButtons.forEach((button) => {
    const tabValue = normalizePeopleWorkspaceTab(button.dataset.peopleWorkspaceTab);
    const isActive = tabValue === activePeopleTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
    button.tabIndex = isActive ? 0 : -1;
  });

  if (peopleUsersPanel) {
    peopleUsersPanel.hidden = !isUsersTab;
  }

  if (absenceModule) {
    absenceModule.hidden = !isAbsenceTab;
  }

  if (absenceReportModule) {
    absenceReportModule.hidden = !isAbsenceReportTab;
  }

  if (getIsSuperAdmin()) {
    if (managementViewKicker) {
      managementViewKicker.textContent = isUsersTab && isControlPanelUserManagementScope() ? "Control panel" : "People";
    }
    if (managementViewTitle) {
      managementViewTitle.textContent = isUsersTab && isControlPanelUserManagementScope()
        ? userManagementScopeConfig.listTitle
        : getPeopleWorkspaceTabLabel(activePeopleTab);
    }
    if (managementViewDescription) {
      managementViewDescription.textContent = userManagementDescription;
      managementViewDescription.hidden = !hasUserManagementDescription;
    }
    if (userManagementNote) {
      const noteText = getUserManagementNoteText(currentOrganization);
      userManagementNote.textContent = noteText;
      userManagementNote.hidden = !isUsersTab || !String(noteText || "").trim();
    }
  } else if (getIsAdmin()) {
    if (managementViewKicker) {
      managementViewKicker.textContent = isUsersTab && isControlPanelUserManagementScope() ? "Control panel" : "People";
    }
    if (managementViewTitle) {
      managementViewTitle.textContent = isUsersTab && isControlPanelUserManagementScope()
        ? userManagementScopeConfig.listTitle
        : getPeopleWorkspaceTabLabel(activePeopleTab);
    }
    if (managementViewDescription) {
      managementViewDescription.textContent = userManagementDescription;
      managementViewDescription.hidden = !hasUserManagementDescription;
    }
    if (userManagementNote) {
      const noteText = getUserManagementNoteText(currentOrganization);
      userManagementNote.textContent = noteText;
      userManagementNote.hidden = !isUsersTab || !String(noteText || "").trim();
    }
  } else if (userManagementNote) {
    const noteText = getUserManagementNoteText(currentOrganization);
    userManagementNote.textContent = noteText;
    userManagementNote.hidden = !isUsersTab || !String(noteText || "").trim();
  }

  syncUserEditorChrome(Boolean(userIdInput.value), getCurrentUserEditorRecord());

  if (isUsersTab) {
    renderUsers();
  }
  if (isAbsenceTab) {
    renderAbsenceModule();
  }
  if (isAbsenceReportTab) {
    renderAbsenceReportModule();
  }
  renderSignupRequests();
  renderLoginContentItems();
}

let helpTourAutoWelcomeQueued = false;
let helpTourRafId = 0;

function getHelpTourStorageKey(kind = "welcome") {
  const userKey = state.user?.id || state.user?.email || "anonymous";
  const organizationKey = state.activeOrganizationId || "global";
  return `${HELP_TOUR_STORAGE_PREFIX}.${HELP_TOUR_VERSION}.${organizationKey}.${userKey}.${kind}`;
}

function hasCompletedHelpTour(kind = "welcome") {
  try {
    return window.localStorage.getItem(getHelpTourStorageKey(kind)) === "done";
  } catch {
    return false;
  }
}

function markHelpTourCompleted(kind = "welcome") {
  try {
    window.localStorage.setItem(getHelpTourStorageKey(kind), "done");
  } catch {
    return;
  }
}

function getHelpTourLayer() {
  let layer = document.querySelector("#help-tour-layer");
  if (layer) {
    return layer;
  }

  layer = document.createElement("div");
  layer.id = "help-tour-layer";
  layer.className = "help-tour-layer";
  layer.hidden = true;
  layer.innerHTML = `
    <div class="help-tour-scrim" aria-hidden="true"></div>
    <div class="help-tour-focus-clone" aria-hidden="true"></div>
    <div class="help-tour-spotlight" aria-hidden="true"></div>
    <section class="help-tour-card" role="dialog" aria-modal="true" aria-live="polite" aria-labelledby="help-tour-title">
      <div class="help-tour-card-glow" aria-hidden="true"></div>
      <div class="help-tour-card-head">
        <span id="help-tour-kicker" class="section-kicker">Help</span>
        <button id="help-tour-skip" type="button" class="ghost-button help-tour-skip-button">Preskoči</button>
      </div>
      <h3 id="help-tour-title"></h3>
      <p id="help-tour-body" class="help-tour-body"></p>
      <div id="help-tour-points" class="help-tour-points"></div>
      <div id="help-tour-progress" class="help-tour-progress"></div>
      <div class="help-tour-actions">
        <button id="help-tour-back" type="button" class="ghost-button">Natrag</button>
        <button id="help-tour-next" type="button" class="primary-button">OK, dalje</button>
      </div>
    </section>
  `;
  document.body.append(layer);
  layer.querySelector("#help-tour-skip")?.addEventListener("click", () => {
    closeHelpTour({ markCompleted: true });
  });
  layer.querySelector("#help-tour-back")?.addEventListener("click", () => {
    moveHelpTourStep(-1);
  });
  layer.querySelector("#help-tour-next")?.addEventListener("click", () => {
    moveHelpTourStep(1);
  });
  return layer;
}

