function getHelpTourMenuGroups() {
  return HELP_TOUR_MENU_GROUPS;
}

function isHelpTourMenuItemVisible(kind = "") {
  const tourKind = String(kind || "").trim();
  if (!tourKind || getHelpTourSteps(tourKind).length === 0) {
    return false;
  }
  if (tourKind === "general") {
    return true;
  }
  if (tourKind === "control-panel" && !getCanManageMasterData()) {
    return false;
  }

  const sidebarButton = sidebarNavItems.find((button) => button.dataset.sidebarItem === tourKind);
  if (sidebarButton instanceof HTMLElement) {
    if (sidebarButton.hidden) {
      return false;
    }
    const style = window.getComputedStyle(sidebarButton);
    if (style.display === "none" || style.visibility === "hidden") {
      return false;
    }
  }
  return true;
}

function getModuleHelpTourDefinition(kind = "") {
  return MODULE_HELP_TOUR_DEFINITIONS[String(kind || "").trim()] ?? null;
}

function createModuleHelpTourStep({
  title,
  body,
  target,
  points = [],
  prepare,
} = {}) {
  if (!title || !body) {
    return null;
  }
  return {
    title,
    body,
    target,
    points: Array.isArray(points) ? points.filter(Boolean) : [],
    prepare,
  };
}

function getModuleHelpTourSteps(kind = "") {
  const tourKind = String(kind || "").trim();
  const definition = getModuleHelpTourDefinition(tourKind);
  if (!definition) {
    return [];
  }

  const navItem = definition.navItem || tourKind;
  const activeItem = definition.activeItem || navItem;
  const prepare = `sidebar:${activeItem}`;
  return [
    createModuleHelpTourStep({
      title: definition.title || getHelpTourKindLabel(tourKind),
      body: definition.body,
      target: definition.target,
      points: definition.points,
      prepare,
    }),
    createModuleHelpTourStep({
      title: "Ulaz iz navigacije",
      body: `${definition.title || getHelpTourKindLabel(tourKind)} otvaraš iz lijevog sidebar-a. Aktivna stavka ostaje označena dok radiš u tom modulu.`,
      target: `[data-sidebar-item="${navItem}"]`,
      points: ["Sidebar grupa se automatski širi ako je potrebno.", "Pomoć koristi isti ulaz kao stvarni rad u aplikaciji."],
      prepare,
    }),
    createModuleHelpTourStep({
      title: definition.primaryActionTitle || "Glavna akcija",
      body: definition.primaryActionBody,
      target: definition.primaryActionTarget,
      points: definition.primaryActionPoints || ["Akcija otvara editor ili pokreće glavni radni tijek modula.", "Podaci se spremaju tek kada potvrdiš formu."],
      prepare,
    }),
    createModuleHelpTourStep({
      title: definition.filtersTitle || "Pretraga i filteri",
      body: definition.filtersBody,
      target: definition.filtersTarget,
      points: definition.filtersPoints || ["Filteri ne brišu podatke, samo sužavaju prikaz.", "Pretraga je najbrži način rada kad lista naraste."],
      prepare,
    }),
    createModuleHelpTourStep({
      title: definition.listTitle || "Lista i radni prostor",
      body: definition.listBody,
      target: definition.listTarget,
      points: definition.listPoints || ["Klik na stavku najčešće otvara editor ili detalje.", "Lista ostaje radni pregled za trenutni filter."],
      prepare,
    }),
    createModuleHelpTourStep({
      title: definition.secondaryTitle || "Dodatni blok",
      body: definition.secondaryBody,
      target: definition.secondaryTarget,
      points: definition.secondaryPoints || ["Ovaj dio modula drži kontekst koji se koristi u drugim ekranima.", "Ako blok nema podataka, prikazat će prazno stanje."],
      prepare,
    }),
  ].filter(Boolean);
}

function getHelpTourSteps(kind = state.helpTour.kind) {
  const tourKind = String(kind || "").trim();
  const stepFactories = {
    general: getGeneralHelpTourSteps,
    dashboard: getDashboardHelpTourSteps,
    "control-panel": getControlPanelHelpTourSteps,
    reminders: getRemindersHelpTourSteps,
    todo: getTodoHelpTourSteps,
    notifications: getNotificationsHelpTourSteps,
    settings: getSettingsHelpTourSteps,
    offers: getOffersHelpTourSteps,
  };
  return stepFactories[tourKind]?.() ?? getModuleHelpTourSteps(tourKind);
}

function getHelpTourKindLabel(kind = state.helpTour.kind) {
  const labels = {
    general: "Opći vodič",
    dashboard: "Dashboard",
    "control-panel": "Control panel",
    reminders: "Reminders",
    todo: "ToDo",
    notifications: "Notifications",
    settings: "Settings",
    offers: "Ponude",
  };
  const tourKind = String(kind || "").trim();
  const menuItem = HELP_TOUR_MENU_GROUPS
    .flatMap((group) => group.items)
    .find((item) => item.kind === tourKind);
  return labels[tourKind] || menuItem?.label || SIDEBAR_ITEM_LABELS[tourKind] || "Pomoć";
}

function getCurrentHelpTourStep() {
  return getHelpTourSteps()[state.helpTour.stepIndex] ?? null;
}

function getHelpTourTarget(step = getCurrentHelpTourStep()) {
  const selector = step?.target || "";
  if (!selector) {
    return null;
  }
  const target = document.querySelector(selector);
  if (!(target instanceof HTMLElement) || target.hidden) {
    return null;
  }
  if (target.closest("[hidden]")) {
    return null;
  }
  const style = window.getComputedStyle(target);
  if (style.display === "none" || style.visibility === "hidden") {
    return null;
  }
  return target;
}

function syncHelpTourCloneControls(source, clone) {
  const sourceControls = Array.from(source.querySelectorAll("input, textarea, select"));
  const cloneControls = Array.from(clone.querySelectorAll("input, textarea, select"));
  cloneControls.forEach((control, index) => {
    const sourceControl = sourceControls[index];
    if (!sourceControl) {
      return;
    }
    if (control instanceof HTMLInputElement && sourceControl instanceof HTMLInputElement) {
      control.checked = sourceControl.checked;
      control.value = sourceControl.value;
      return;
    }
    if (control instanceof HTMLTextAreaElement && sourceControl instanceof HTMLTextAreaElement) {
      control.value = sourceControl.value;
      return;
    }
    if (control instanceof HTMLSelectElement && sourceControl instanceof HTMLSelectElement) {
      control.selectedIndex = sourceControl.selectedIndex;
      control.value = sourceControl.value;
    }
  });
}

function sanitizeHelpTourCloneElement(clone) {
  clone.removeAttribute("id");
  clone.removeAttribute("for");
  clone.removeAttribute("name");
  clone.removeAttribute("aria-controls");
  clone.removeAttribute("aria-describedby");
  clone.removeAttribute("aria-labelledby");
  clone.removeAttribute("tabindex");
  clone.querySelectorAll("[id], [for], [name], [aria-controls], [aria-describedby], [aria-labelledby], [tabindex]").forEach((element) => {
    element.removeAttribute("id");
    element.removeAttribute("for");
    element.removeAttribute("name");
    element.removeAttribute("aria-controls");
    element.removeAttribute("aria-describedby");
    element.removeAttribute("aria-labelledby");
    element.removeAttribute("tabindex");
  });
  clone.querySelectorAll("button, a, input, select, textarea").forEach((element) => {
    element.setAttribute("tabindex", "-1");
    element.setAttribute("aria-hidden", "true");
  });
}

function renderHelpTourFocusClone(layer, target, frame = {}) {
  const focusClone = layer.querySelector(".help-tour-focus-clone");
  if (!(focusClone instanceof HTMLElement)) {
    return;
  }

  if (!(target instanceof HTMLElement)) {
    focusClone.hidden = true;
    focusClone.replaceChildren();
    return;
  }

  const rect = frame.rect ?? target.getBoundingClientRect();
  const clone = target.cloneNode(true);
  if (!(clone instanceof HTMLElement)) {
    focusClone.hidden = true;
    focusClone.replaceChildren();
    return;
  }

  syncHelpTourCloneControls(target, clone);
  sanitizeHelpTourCloneElement(clone);
  clone.classList.add("help-tour-focus-surface");
  clone.style.width = `${Math.max(1, rect.width)}px`;
  clone.style.minWidth = `${Math.max(1, rect.width)}px`;
  clone.style.margin = "0";

  focusClone.hidden = false;
  focusClone.style.left = `${frame.safeLeft ?? Math.max(8, rect.left - 12)}px`;
  focusClone.style.top = `${frame.safeTop ?? Math.max(8, rect.top - 12)}px`;
  focusClone.style.width = `${frame.safeWidth ?? rect.width + 24}px`;
  focusClone.style.height = `${frame.safeHeight ?? rect.height + 24}px`;
  focusClone.replaceChildren(clone);
}

function closeDashboardBuilderForHelpTour() {
  if (!state.dashboardBuilder?.open) {
    if (dashboardBuilderPanel && state.activeView !== "selfdash") {
      dashboardBuilderPanel.hidden = true;
    }
    return;
  }
  closeDashboardBuilder();
  renderDashboardOverview();
  if (dashboardBuilderPanel && state.activeView !== "selfdash") {
    dashboardBuilderPanel.hidden = true;
  }
  document.body.classList.remove("is-dashboard-builder-open");
}

function prepareHelpTourStep(step = getCurrentHelpTourStep()) {
  if (!step) {
    return;
  }

  const prepareKey = String(step.prepare || "").trim();
  if (prepareKey.startsWith("sidebar:")) {
    const itemName = prepareKey.slice("sidebar:".length).trim();
    if (itemName) {
      activateSidebarItem(itemName, { expandSidebar: true });
      closeDashboardBuilderForHelpTour();
      if (itemName === "purchase-orders") {
        ensureCommercialDocumentDirectionState();
        renderOffersModule();
      }
    }
    return;
  }

  if (step.prepare === "general") {
    if (state.activeView !== "selfdash" || !isDashboardOverviewItem()) {
      activateSidebarItem("dashboard", { expandSidebar: true });
    }
    closeDashboardBuilderForHelpTour();
  }

  if (step.prepare === "control-panel") {
    if (state.activeView !== "selfdash" || !isDashboardControlPanelItem()) {
      activateSidebarItem("control-panel", { expandSidebar: true });
    }
    closeDashboardBuilderForHelpTour();
  }

  if (step.prepare === "reminders") {
    if (state.activeView !== "reminders") {
      activateSidebarItem("reminders", { expandSidebar: true });
    }
    closeDashboardBuilderForHelpTour();
  }

  if (step.prepare === "todo") {
    if (state.activeView !== "todo") {
      activateSidebarItem("todo", { expandSidebar: true });
    }
    closeDashboardBuilderForHelpTour();
  }

  if (step.prepare === "notifications") {
    if (state.activeView !== "notifications") {
      activateSidebarItem("notifications", { expandSidebar: true });
    }
    closeDashboardBuilderForHelpTour();
  }

  if (step.prepare === "settings") {
    if (state.activeView !== "module" || state.activeModuleItem !== "settings") {
      activateSidebarItem("settings", { expandSidebar: true });
    }
    closeDashboardBuilderForHelpTour();
  }

  if (step.prepare === "dashboard" || step.prepare === "dashboard-builder") {
    if (state.activeView !== "selfdash" || !isDashboardOverviewItem()) {
      activateSidebarItem("dashboard", { expandSidebar: true });
    }

    if (step.prepare === "dashboard-builder") {
      if (!state.dashboardBuilder.open) {
        openDashboardBuilder();
        renderDashboardOverview();
      }
    } else if (state.dashboardBuilder.open) {
      closeDashboardBuilder();
      renderDashboardOverview();
    }
  }

  if (step.prepare === "offers" || step.prepare === "offer-editor") {
    closeDashboardBuilderForHelpTour();
    if (state.activeView !== "module" || state.activeModuleItem !== "offers") {
      activateSidebarItem("offers", { expandSidebar: true });
    }
    ensureCommercialDocumentDirectionState();
    if (state.commercialDocumentDirections.offers !== "outgoing") {
      state.commercialDocumentDirections.offers = "outgoing";
      renderOffersModule();
    }
  }

  if (step.prepare === "offer-editor") {
    if (!state.offerEditorOpen) {
      resetOfferForm();
      renderOffersModule();
      openOfferEditor();
    }
  } else if (state.offerEditorOpen && step.prepare === "offers") {
    closeOfferEditor({ reset: false });
  }
}

function positionHelpTourCard(layer, step = getCurrentHelpTourStep()) {
  const card = layer.querySelector(".help-tour-card");
  const spotlight = layer.querySelector(".help-tour-spotlight");
  const focusClone = layer.querySelector(".help-tour-focus-clone");
  if (!(card instanceof HTMLElement) || !(spotlight instanceof HTMLElement)) {
    return;
  }

  const target = getHelpTourTarget(step);
  const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 1200;
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 800;
  const padding = 12;

  if (!target) {
    spotlight.hidden = true;
    if (focusClone instanceof HTMLElement) {
      focusClone.hidden = true;
      focusClone.replaceChildren();
    }
    card.classList.add("is-centered");
    card.style.left = "";
    card.style.top = "";
    return;
  }

  spotlight.hidden = false;
  card.classList.remove("is-centered");
  const rect = target.getBoundingClientRect();
  const safeLeft = Math.max(8, rect.left - padding);
  const safeTop = Math.max(8, rect.top - padding);
  const safeWidth = Math.min(viewportWidth - safeLeft - 8, rect.width + (padding * 2));
  const safeHeight = Math.min(viewportHeight - safeTop - 8, rect.height + (padding * 2));
  layer.style.setProperty("--tour-x", `${safeLeft}px`);
  layer.style.setProperty("--tour-y", `${safeTop}px`);
  layer.style.setProperty("--tour-w", `${Math.max(72, safeWidth)}px`);
  layer.style.setProperty("--tour-h", `${Math.max(42, safeHeight)}px`);
  renderHelpTourFocusClone(layer, target, {
    rect,
    safeLeft,
    safeTop,
    safeWidth: Math.max(72, safeWidth),
    safeHeight: Math.max(42, safeHeight),
  });

  const cardRect = card.getBoundingClientRect();
  const preferredRight = rect.right + 22;
  const preferredLeft = rect.left - cardRect.width - 22;
  let left = preferredRight + cardRect.width <= viewportWidth - 14
    ? preferredRight
    : preferredLeft >= 14
      ? preferredLeft
      : Math.min(Math.max(14, rect.left), viewportWidth - cardRect.width - 14);
  let top = rect.top + Math.min(28, Math.max(0, rect.height / 2 - 120));

  if (top + cardRect.height > viewportHeight - 14) {
    top = viewportHeight - cardRect.height - 14;
  }
  if (top < 14) {
    top = 14;
  }
  if (left < 14) {
    left = 14;
  }

  card.style.left = `${left}px`;
  card.style.top = `${top}px`;
}

function renderHelpTourProgress(layer, totalSteps = 0, currentIndex = 0) {
  const progress = layer.querySelector("#help-tour-progress");
  if (!progress) {
    return;
  }

  progress.replaceChildren(...Array.from({ length: totalSteps }, (_, index) => {
    const dot = document.createElement("span");
    dot.className = "help-tour-progress-dot";
    dot.classList.toggle("is-active", index === currentIndex);
    dot.classList.toggle("is-done", index < currentIndex);
    dot.textContent = String(index + 1);
    return dot;
  }));
}

function renderHelpTourPoints(layer, points = []) {
  const pointsWrap = layer.querySelector("#help-tour-points");
  if (!pointsWrap) {
    return;
  }
  const safePoints = Array.isArray(points) ? points.filter(Boolean) : [];
  pointsWrap.hidden = safePoints.length === 0;
  pointsWrap.replaceChildren(...safePoints.map((point) => {
    const item = document.createElement("span");
    item.textContent = point;
    return item;
  }));
}

function renderWelcomeHelpTour(layer) {
  const title = layer.querySelector("#help-tour-title");
  const body = layer.querySelector("#help-tour-body");
  const kicker = layer.querySelector("#help-tour-kicker");
  const skip = layer.querySelector("#help-tour-skip");
  const back = layer.querySelector("#help-tour-back");
  const next = layer.querySelector("#help-tour-next");
  const spotlight = layer.querySelector(".help-tour-spotlight");
  const focusClone = layer.querySelector(".help-tour-focus-clone");
  const card = layer.querySelector(".help-tour-card");
  layer.classList.add("is-welcome");
  layer.classList.remove("is-guided");
  spotlight.hidden = true;
  if (focusClone instanceof HTMLElement) {
    focusClone.hidden = true;
    focusClone.replaceChildren();
  }
  card?.classList.add("is-centered", "is-welcome-card");
  if (kicker) {
    kicker.textContent = "Dobrodošli";
  }
  if (title) {
    title.textContent = "Dobrodošli u SafeNexus";
  }
  if (body) {
    body.textContent = "SafeNexus je radni prostor za tvrtke, lokacije, radne naloge, ponude, dokumente, osposobljavanja i procjene rizika. Krenut ćemo s kratkim općim vodičem kroz aplikaciju, korak po korak.";
  }
  renderHelpTourPoints(layer, [
    "Prozor se prikazuje samo prvi put za ovog korisnika i organizaciju.",
    "Svaki korak možeš potvrditi kada si spreman.",
    "Sve vodiče možeš ponovno pokrenuti iz ikone pomoći u gornjoj traci.",
  ]);
  renderHelpTourProgress(layer, 0, 0);
  if (skip) {
    skip.textContent = "Kasnije";
  }
  if (back) {
    back.hidden = true;
  }
  if (next) {
    next.textContent = "Kreni kroz app";
  }
  positionHelpTourCard(layer, null);
}

function renderGuidedHelpTour(layer) {
  const steps = getHelpTourSteps();
  const step = getCurrentHelpTourStep();
  if (!step) {
    closeHelpTour({ markCompleted: true });
    return;
  }
  const title = layer.querySelector("#help-tour-title");
  const body = layer.querySelector("#help-tour-body");
  const kicker = layer.querySelector("#help-tour-kicker");
  const skip = layer.querySelector("#help-tour-skip");
  const back = layer.querySelector("#help-tour-back");
  const next = layer.querySelector("#help-tour-next");
  layer.classList.remove("is-welcome");
  layer.classList.add("is-guided");
  layer.querySelector(".help-tour-card")?.classList.remove("is-welcome-card");
  if (kicker) {
    kicker.textContent = `${getHelpTourKindLabel()} · korak ${state.helpTour.stepIndex + 1} od ${steps.length}`;
  }
  if (title) {
    title.textContent = step.title;
  }
  if (body) {
    body.textContent = step.body;
  }
  if (skip) {
    skip.textContent = "Preskoči";
  }
  if (back) {
    back.hidden = state.helpTour.stepIndex <= 0;
  }
  if (next) {
    next.textContent = state.helpTour.stepIndex >= steps.length - 1 ? "Završi" : "OK, dalje";
  }
  renderHelpTourPoints(layer, step.points);
  renderHelpTourProgress(layer, steps.length, state.helpTour.stepIndex);

  const target = getHelpTourTarget(step);
  target?.scrollIntoView({ block: "center", inline: "nearest", behavior: "auto" });
  window.requestAnimationFrame(() => {
    positionHelpTourCard(layer, step);
  });
}

function renderHelpTour() {
  const layer = getHelpTourLayer();
  const isOpen = Boolean(state.helpTour.open && state.user);
  layer.hidden = !isOpen;
  document.body.classList.toggle("is-help-tour-open", isOpen);
  if (!isOpen) {
    return;
  }

  if (helpTourRafId) {
    window.cancelAnimationFrame(helpTourRafId);
  }

  prepareHelpTourStep(getCurrentHelpTourStep());
  helpTourRafId = window.requestAnimationFrame(() => {
    helpTourRafId = 0;
    if (state.helpTour.kind === "welcome") {
      renderWelcomeHelpTour(layer);
      return;
    }
    renderGuidedHelpTour(layer);
  });
}

function openWelcomeHelpTour({ force = false } = {}) {
  if (!state.user || (!force && hasCompletedHelpTour("welcome"))) {
    return;
  }
  state.helpTour = {
    open: true,
    kind: "welcome",
    stepIndex: 0,
    startedFromWelcome: false,
  };
  renderHelpTour();
}

function openHelpTour(kind, { fromWelcome = false } = {}) {
  if (!state.user) {
    return;
  }
  const tourKind = String(kind || "").trim();
  if (getHelpTourSteps(tourKind).length === 0) {
    return;
  }
  if (fromWelcome) {
    markHelpTourCompleted("welcome");
  }
  setTopbarHelpMenuOpen(false, { closeOthers: false });
  state.helpTour = {
    open: true,
    kind: tourKind,
    stepIndex: 0,
    startedFromWelcome: Boolean(fromWelcome),
  };
  renderHelpTour();
}

function openOffersHelpTour({ fromWelcome = false } = {}) {
  openHelpTour("offers", { fromWelcome });
}

function openDashboardHelpTour() {
  openHelpTour("dashboard");
}

function closeHelpTour({ markCompleted = false } = {}) {
  const previousKind = state.helpTour.kind;
  if (markCompleted && previousKind) {
    markHelpTourCompleted(previousKind);
    if (previousKind === "welcome") {
      markHelpTourCompleted("general");
    }
  }
  state.helpTour = {
    open: false,
    kind: "",
    stepIndex: 0,
    startedFromWelcome: false,
  };
  renderHelpTour();
}

function moveHelpTourStep(direction = 1) {
  if (!state.helpTour.open) {
    return;
  }
  if (state.helpTour.kind === "welcome") {
    if (direction > 0) {
      openHelpTour("general", { fromWelcome: true });
    } else {
      closeHelpTour({ markCompleted: true });
    }
    return;
  }

  const steps = getHelpTourSteps();
  const nextIndex = state.helpTour.stepIndex + direction;
  if (nextIndex < 0) {
    return;
  }
  if (nextIndex >= steps.length) {
    closeHelpTour({ markCompleted: true });
    return;
  }
  state.helpTour.stepIndex = nextIndex;
  renderHelpTour();
}

function queueWelcomeHelpTourIfNeeded() {
  if (!state.user || helpTourAutoWelcomeQueued || state.helpTour.open || hasCompletedHelpTour("welcome")) {
    return;
  }
  helpTourAutoWelcomeQueued = true;
  window.setTimeout(() => {
    helpTourAutoWelcomeQueued = false;
    if (!state.user || state.helpTour.open || hasCompletedHelpTour("welcome")) {
      return;
    }
    openWelcomeHelpTour();
  }, 700);
}

function render() {
  renderAuthState();
  renderLoginContent();
  renderSummary();
  renderSharedOptions();
  if (state.activeView === "reminders") {
    renderReminders();
  }
  if (state.activeView === "todo") {
    renderTodo();
  }
  if (state.activeView === "notifications") {
    renderNotifications();
  }
  if (state.activeView === "companies") {
    renderCompanies();
  }
  if (state.activeView === "locations") {
    renderLocations();
  }
  if (state.activeView === "management") {
    renderManagement();
  }
  if (state.activeView === "module") {
    renderModuleView();
  }
  renderActiveView();
  renderChatDock();
  renderAppCapabilitiesDialog();
  renderProfileDialog();
  renderWeatherWidget();
  renderTopbarHelpMenu();
  renderHelpTour();
  queueWelcomeHelpTourIfNeeded();
}

