document.addEventListener("pointerdown", (event) => {
  const menu = state.periodicsInspectionContextMenu;
  if (menu instanceof HTMLElement) {
    if (!(event.target instanceof Node) || !menu.contains(event.target)) {
      closePeriodicsInspectionContextMenu();
    }
  }

  const inlineEditor = state.workOrderInlineFieldEditor?.element;
  if (inlineEditor instanceof HTMLElement) {
    const targetElement = event.target instanceof Element ? event.target : null;
    const isInlineEditorPortal = Boolean(targetElement?.closest(
      ".work-order-tag-picker-menu-portal, .work-order-quick-picker-menu-portal, .work-order-service-picker-menu-portal, .work-item-status-menu-portal",
    ));
    if (!(event.target instanceof Node) || (!inlineEditor.contains(event.target) && !isInlineEditorPortal)) {
      closeWorkOrderInlineFieldEditor();
    }
  }
}, true);

document.addEventListener("keydown", (event) => {
  if (event.key !== "Escape") {
    return;
  }

  if (state.periodicsInspectionContextMenu instanceof HTMLElement) {
    event.preventDefault();
    closePeriodicsInspectionContextMenu();
    return;
  }

  if (state.workOrderInlineFieldEditor?.element instanceof HTMLElement) {
    event.preventDefault();
    closeWorkOrderInlineFieldEditor();
    return;
  }

  if (documentTemplateAiWizardOpen) {
    event.preventDefault();
    closeDocumentTemplateFieldAiWizard({ render: true });
    return;
  }

  if (
    state.measurementSheet.aiPopoverOpen
    || state.measurementSheet.quickFillPopoverOpen
    || state.measurementSheet.validationPopoverOpen
    || state.measurementSheet.conditionalPopoverOpen
  ) {
    event.preventDefault();
    state.measurementSheet.aiPopoverOpen = false;
    state.measurementSheet.quickFillPopoverOpen = false;
    state.measurementSheet.validationPopoverOpen = false;
    state.measurementSheet.conditionalPopoverOpen = false;
    syncMeasurementToolbar();
    return;
  }

  if (documentTemplateInspectorModalOpen) {
    event.preventDefault();
    closeDocumentTemplateInspectorModal();
  }
});

