vehicleUsageSignatureClearButton?.addEventListener("click", clearVehicleUsageSignatureCanvas);

if (vehicleUsageSignatureCanvas) {
  const signatureContext = vehicleUsageSignatureCanvas.getContext("2d");
  if (signatureContext) {
    signatureContext.lineWidth = 4;
    signatureContext.lineCap = "round";
    signatureContext.lineJoin = "round";
    signatureContext.strokeStyle = "#111827";
  }
  vehicleUsageSignatureCanvas.addEventListener("pointerdown", (event) => {
    const point = getVehicleUsageSignaturePointer(event);
    if (!point || !signatureContext) return;
    vehicleUsageSignatureDrawing = true;
    vehicleUsageSignatureCanvas.setPointerCapture?.(event.pointerId);
    signatureContext.beginPath();
    signatureContext.moveTo(point.x, point.y);
    event.preventDefault();
  });
  vehicleUsageSignatureCanvas.addEventListener("pointermove", (event) => {
    if (!vehicleUsageSignatureDrawing) return;
    const point = getVehicleUsageSignaturePointer(event);
    if (!point || !signatureContext) return;
    signatureContext.lineTo(point.x, point.y);
    signatureContext.stroke();
    vehicleUsageSignatureDirty = true;
    event.preventDefault();
  });
  ["pointerup", "pointercancel", "pointerleave"].forEach((eventName) => {
    vehicleUsageSignatureCanvas.addEventListener(eventName, (event) => {
      if (vehicleUsageSignatureDrawing) {
        signatureContext?.closePath();
      }
      vehicleUsageSignatureDrawing = false;
      vehicleUsageSignatureCanvas.releasePointerCapture?.(event.pointerId);
    });
  });
}

vehicleUsageForm?.addEventListener("submit", (event) => {
  event.preventDefault();
  if (!getCanReserveVehicles() && !getCanManageVehicles()) {
    return;
  }

  const vehicleId = vehicleUsageVehicleIdInput?.value || "";
  if (!vehicleId) {
    if (vehicleUsageError) {
      vehicleUsageError.textContent = "Odaberi vozilo prije spremanja.";
    }
    return;
  }

  const payload = buildVehicleUsagePayload();
  if (!String(payload.reservationId || "").trim()) {
    if (vehicleUsageError) {
      vehicleUsageError.textContent = "My Trip možeš spremiti samo uz svoju aktivnu rezervaciju vozila.";
    }
    return;
  }

  if (!String(payload.startKm || "").trim()) {
    if (vehicleUsageError) {
      vehicleUsageError.textContent = "Upiši početnu kilometražu vozila.";
    }
    return;
  }

  if (String(payload.returnAt || "").trim() && !String(payload.endKm || "").trim()) {
    if (vehicleUsageError) {
      vehicleUsageError.textContent = "Za zatvaranje puta upiši krajnju kilometražu.";
    }
    return;
  }

  if (String(payload.endKm || "").trim() && !String(payload.returnAt || "").trim()) {
    if (vehicleUsageError) {
      vehicleUsageError.textContent = "Za krajnju kilometražu upiši datum i vrijeme dolaska.";
    }
    return;
  }

  if (!String(payload.destination || "").trim()) {
    if (vehicleUsageError) {
      vehicleUsageError.textContent = "Upiši lokaciju gdje se ide.";
    }
    return;
  }

  void runMutation(() => apiRequest(`/vehicles/${vehicleId}/usage`, {
    method: "POST",
    body: payload,
  }), vehicleUsageError).then((success) => {
    if (!success) {
      return;
    }
    closeVehicleUsageEditor({ reset: true });
    renderVehiclesModule();
  });
});

vehicleReservationForm?.addEventListener("submit", (event) => {
  event.preventDefault();
  if (!getCanReserveVehicles()) {
    return;
  }

  const activeVehicle = getVehicleFromReservationEditor();

  if (!activeVehicle) {
    if (vehicleReservationError) {
      vehicleReservationError.textContent = "Odaberi vozilo prije rezervacije.";
    }
    return;
  }

  const payload = buildVehicleReservationPayload();
  const previousIds = new Set((activeVehicle.reservations ?? []).map((item) => String(item.id)));
  const isEditing = Boolean(vehicleReservationIdInput?.value);

  if (!isEditing && isVehicleServiceOnlyStatus(activeVehicle)) {
    if (vehicleReservationError) {
      vehicleReservationError.textContent = VEHICLE_SERVICE_RESERVATION_MESSAGE;
    }
    return;
  }

  const path = isEditing
    ? `/vehicles/${activeVehicle.id}/reservations/${vehicleReservationIdInput.value}`
    : `/vehicles/${activeVehicle.id}/reservations`;
  const method = isEditing ? "PATCH" : "POST";

  void runMutation(() => apiRequest(path, {
    method,
    body: payload,
  }), vehicleReservationError).then((success) => {
    if (!success) {
      return;
    }

    const refreshedVehicle = state.vehicles.find((item) => String(item.id) === String(activeVehicle.id)) ?? null;

    if (!refreshedVehicle) {
      resetVehicleForm();
      renderVehiclesModule();
      return;
    }

    const targetReservation = isEditing
      ? (refreshedVehicle.reservations ?? []).find((item) => String(item.id) === String(vehicleReservationIdInput.value))
      : findCreatedVehicleReservationMatch(refreshedVehicle, previousIds, payload);

    state.activeVehicleId = refreshedVehicle.id;
    state.activeVehicleReservationId = targetReservation?.id || "";
    closeVehicleReservationEditor({ reset: true });
    renderVehiclesModule();
  });
});

