offerDeleteButton?.addEventListener("click", () => {
  const offerId = offerIdInput?.value || "";
  const config = getActiveCommercialDocumentConfig();
  const apiBasePath = getActiveCommercialApiBasePath();

  if (!offerId || !getCanEditCommercialDocuments()) {
    return;
  }

  if (!window.confirm(config.deleteConfirmLabel)) {
    return;
  }

  void runMutation(() => apiRequest(`${apiBasePath}/${offerId}`, {
    method: "DELETE",
  }), offerError).then((success) => {
    if (success) {
      closeOfferEditor({ reset: true });
      renderOffersModule();
    }
  });
});

offerForm?.addEventListener("submit", (event) => {
  event.preventDefault();

  const isEditing = Boolean(offerIdInput.value);
  const canSave = isEditing ? getCanEditCommercialDocuments() : getCanCreateCommercialDocuments();

  if (!canSave) {
    setInlineMessage(offerError, isEditing
      ? "Nemas ovlastenje za uredivanje ovog dokumenta."
      : "Nemas ovlastenje za izradu ovog dokumenta.");
    return;
  }

  const apiBasePath = getActiveCommercialApiBasePath();
  const path = isEditing ? `${apiBasePath}/${offerIdInput.value}` : apiBasePath;
  const method = isEditing ? "PATCH" : "POST";

  void runMutation(() => apiRequest(path, {
    method,
    body: buildOfferPayload(),
  }), offerError, {
    onSuccessPayload(payload) {
      if (apiBasePath === "/offers") {
        applyOfferMutationPayload(payload);
      }
    },
  }).then((success) => {
    if (success) {
      closeOfferEditor({ reset: true });
      renderOffersModule();
    }
  });
});

