jobEnvironmentSections?.addEventListener("click", (event) => {
  const target = event.target instanceof Element ? event.target : null;
  const psychosocialLevelButton = target?.closest("[data-job-psychosocial-level]");
  if (psychosocialLevelButton instanceof HTMLElement) {
    const panel = psychosocialLevelButton.closest(".job-psychosocial-panel");
    panel?.querySelectorAll("[data-job-psychosocial-level].is-selected").forEach((button) => button.classList.remove("is-selected"));
    psychosocialLevelButton.classList.add("is-selected");
    panel?.classList.add("is-enabled");
    const toggle = panel?.querySelector('[data-job-environment-flag="psychosocialRelevant"]');
    if (toggle instanceof HTMLInputElement) {
      toggle.checked = true;
      const label = toggle.closest(".job-toggle-control")?.querySelector("em");
      if (label) label.textContent = "Da";
    }
    syncJobEnvironmentTextarea("organization", { force: true });
    return;
  }
  const presetButton = target?.closest("[data-job-work-preset]");
  if (presetButton instanceof HTMLElement) {
    applyJobWorkProfilePreset(presetButton.dataset.jobWorkPreset || "");
    return;
  }
  const suggestionButton = target?.closest("[data-job-env-suggestion]");
  if (suggestionButton instanceof HTMLElement) {
    suggestionButton.classList.toggle("is-selected");
    const sectionKey = suggestionButton.dataset.jobEnvSuggestion || "";
    const card = suggestionButton.closest("[data-job-environment-card]");
    const toggle = card?.querySelector(`[data-job-env-enabled="${sectionKey}"]`);
    if (toggle instanceof HTMLInputElement && !toggle.checked) {
      toggle.checked = true;
      card?.classList.add("is-enabled");
      const label = toggle.closest(".job-toggle-control")?.querySelector("em");
      if (label) label.textContent = "Da";
    }
    syncJobEnvironmentTextarea(sectionKey, { force: true });
    return;
  }
  const aiButton = target?.closest("[data-job-nexai]");
  if (aiButton instanceof HTMLElement) {
    if (!getCanUseJobNexAi()) {
      setInlineMessage(jobFormFeedback, "Nemate pravo koristiti NexAI za Jobs.", "error");
      return;
    }
    const key = aiButton.dataset.jobNexai || "";
    const textarea = jobEnvironmentSections.querySelector(`[data-job-env-text="${key}"]`);
    if (key === "organization") {
      const text = getJobNexAiText(key);
      if (textarea instanceof HTMLTextAreaElement) {
        textarea.value = text;
      }
      syncJobOrganizationSentenceList({ sourceText: text, preserveExisting: false });
      return;
    }
    if (textarea instanceof HTMLTextAreaElement) {
      textarea.value = getJobNexAiText(key);
    }
  }
});

jobEnvironmentSections?.addEventListener("input", (event) => {
  const target = event.target instanceof Element ? event.target : null;
  const sentence = target?.closest("[data-job-organization-sentence]");
  if (sentence instanceof HTMLTextAreaElement) {
    syncJobOrganizationHiddenText(sentence.closest("[data-job-environment-card]"));
  }
});

jobEnvironmentSections?.addEventListener("change", (event) => {
  const target = event.target instanceof Element ? event.target : null;
  const toggle = target?.closest("[data-job-env-enabled]");
  if (toggle instanceof HTMLInputElement) {
    const card = toggle.closest("[data-job-environment-card]");
    card?.classList.toggle("is-enabled", toggle.checked);
    const label = toggle.closest(".job-toggle-control")?.querySelector("em");
    if (label) label.textContent = toggle.checked ? "Da" : "Ne";
    if (toggle.checked) {
      syncJobEnvironmentTextarea(toggle.dataset.jobEnvEnabled || "", { force: true });
    }
    return;
  }
  const organizationField = target?.closest("[data-job-organization-field], [data-job-environment-flag]");
  if (organizationField instanceof HTMLElement) {
    if (organizationField.matches('[data-job-environment-flag="psychosocialRelevant"]')) {
      const panel = organizationField.closest(".job-psychosocial-panel");
      panel?.classList.toggle("is-enabled", organizationField.checked);
      const label = organizationField.closest(".job-toggle-control")?.querySelector("em");
      if (label) label.textContent = organizationField.checked ? "Da" : "Ne";
      if (!organizationField.checked) {
        panel?.querySelectorAll("[data-job-psychosocial-level].is-selected").forEach((button) => button.classList.remove("is-selected"));
      }
    }
    const toggle = jobEnvironmentSections.querySelector('[data-job-env-enabled="organization"]');
    if (toggle instanceof HTMLInputElement && !toggle.checked) {
      toggle.checked = true;
      toggle.closest("[data-job-environment-card]")?.classList.add("is-enabled");
      const label = toggle.closest(".job-toggle-control")?.querySelector("em");
      if (label) label.textContent = "Da";
    }
    syncJobEnvironmentTextarea("organization", { force: true });
  }
});

jobConditionSections?.addEventListener("click", (event) => {
  const target = event.target instanceof Element ? event.target : null;
  const purButton = target?.closest("[data-job-pur-point]");
  if (purButton instanceof HTMLElement) {
    purButton.classList.toggle("is-selected");
    const panel = purButton.closest(".job-pur-panel");
    const summary = panel?.querySelector(".job-pur-panel-head > span");
    const dropdownCount = panel?.querySelector("[data-job-pur-dropdown-count]");
    const dropdownSummary = panel?.querySelector("[data-job-pur-dropdown-summary]");
    if (summary) {
      const selected = Array.from(panel?.querySelectorAll("[data-job-pur-point].is-selected") ?? [])
        .map((button) => String(button.dataset.jobPurPoint || "").trim());
      summary.textContent = getJobPurPointSummary(selected);
      if (dropdownCount) {
        dropdownCount.textContent = selected.length ? `${selected.length} odabrano` : "Otvori popis";
      }
      if (dropdownSummary) {
        dropdownSummary.textContent = getJobPurPointSummary(selected);
      }
    }
    return;
  }
  const choiceButton = target?.closest("[data-job-condition-choice]");
  if (choiceButton instanceof HTMLElement) {
    choiceButton.classList.toggle("is-selected");
    const field = choiceButton.dataset.jobConditionChoice || "";
    syncJobConditionChoiceText(field, { force: true });
    if (field === "bodyPositions") {
      renderJobConditionSections(getJobConditionsDraftFromForm());
    }
    return;
  }
  const aiButton = target?.closest("[data-job-nexai]");
  if (aiButton instanceof HTMLElement) {
    if (!getCanUseJobNexAi()) {
      setInlineMessage(jobFormFeedback, "Nemate pravo koristiti NexAI za Jobs.", "error");
      return;
    }
    const key = aiButton.dataset.jobNexai || "";
    if (key.startsWith("condition:")) {
      const noteKey = key.replace("condition:", "");
      const textarea = jobConditionSections.querySelector(`[data-job-condition-note="${noteKey}"]`);
      if (textarea instanceof HTMLTextAreaElement) {
        textarea.value = getJobNexAiText(key);
      }
    }
  }
});

jobConditionSections?.addEventListener("change", (event) => {
  const target = event.target instanceof Element ? event.target : null;
  const toggle = target?.closest("[data-job-condition-flag]");
  if (toggle instanceof HTMLInputElement) {
    const card = toggle.closest("[data-job-condition-card]");
    card?.classList.toggle("is-enabled", toggle.checked);
    const label = toggle.closest(".job-toggle-control")?.querySelector("em");
    if (label) label.textContent = toggle.checked ? "Da" : "Ne";
    if (toggle.checked) {
      const noteKey = toggle.dataset.jobConditionFlag || "";
      const textarea = jobConditionSections.querySelector(`[data-job-condition-note="${noteKey}"]`);
      if (textarea instanceof HTMLTextAreaElement && !textarea.value.trim()) {
        textarea.value = buildJobConditionToggleSentence(noteKey);
      }
    }
    return;
  }
  const blockToggle = target?.closest("[data-job-condition-block-enabled]");
  if (blockToggle instanceof HTMLInputElement) {
    const field = blockToggle.dataset.jobConditionBlockEnabled || "";
    const block = blockToggle.closest("[data-job-condition-block]");
    block?.classList.toggle("is-enabled", blockToggle.checked);
    const label = blockToggle.closest(".job-toggle-control")?.querySelector("em");
    if (label) label.textContent = blockToggle.checked ? "Da" : "Ne";
    if (!blockToggle.checked && block instanceof HTMLElement) {
      block.querySelectorAll(`[data-job-condition-choice="${field}"].is-selected`).forEach((button) => button.classList.remove("is-selected"));
      const definition = JOB_CONDITION_CHOICE_BLOCKS.find((item) => item.field === field);
      const textarea = definition ? block.querySelector(`[data-job-condition-text="${definition.textField}"]`) : null;
      if (textarea instanceof HTMLTextAreaElement) {
        textarea.value = "";
      }
    } else {
      syncJobConditionChoiceText(field, { force: true, forceEnabled: true });
    }
  }
});

jobHazardCatalogSearch?.addEventListener("input", renderJobHazardCatalog);

jobHazardCatalog?.addEventListener("click", (event) => {
  const button = event.target instanceof Element ? event.target.closest("[data-job-hazard-add]") : null;
  if (!(button instanceof HTMLElement)) {
    return;
  }
  const key = button.dataset.jobHazardAdd || "";
  const row = getJobHazardCatalogRows().find((entry) => `${entry.code || ""}::${entry.hazard || ""}` === key);
  if (!row) {
    return;
  }
  const exists = jobHazardDrafts.some((hazard) => `${hazard.catalogCode}::${hazard.catalogLabel}` === key);
  if (!exists) {
    jobHazardDrafts.push(createJobHazardDraft(row, {
      context: getJobHazardContextFromForm(),
      useContextDefaults: true,
    }));
  }
  renderJobHazardCatalog();
  renderJobSelectedHazards();
});

jobSelectedHazards?.addEventListener("input", (event) => {
  const target = event.target instanceof Element ? event.target : null;
  const field = target?.closest("[data-job-hazard-field]");
  const card = target?.closest("[data-job-hazard-index]");
  if (!(field instanceof HTMLElement) || !(card instanceof HTMLElement)) {
    return;
  }
  const index = Number(card.dataset.jobHazardIndex);
  const hazard = jobHazardDrafts[index];
  if (!hazard) {
    return;
  }
  const fieldName = field.dataset.jobHazardField;
  hazard[fieldName] = "value" in field ? String(field.value || "") : "";
  if (field instanceof HTMLTextAreaElement && (fieldName === "unwantedEvent" || fieldName === "measures")) {
    const counter = field.closest(".job-hazard-large-field")?.querySelector(".job-hazard-character-count");
    if (counter) {
      counter.textContent = `${getRiskAssessmentTextareaCount(field.value)} / 1000`;
    }
  }
  if (fieldName === "probability" || fieldName === "consequence") {
    hazard.riskLevel = calculateJobHazardRiskLevel(hazard.probability, hazard.consequence) || "";
    renderJobSelectedHazards();
  }
});

jobSelectedHazards?.addEventListener("change", (event) => {
  const target = event.target instanceof Element ? event.target : null;
  const field = target?.closest("[data-job-hazard-field]");
  const card = target?.closest("[data-job-hazard-index]");
  if (!(field instanceof HTMLElement) || !(card instanceof HTMLElement)) {
    return;
  }
  const index = Number(card.dataset.jobHazardIndex);
  const hazard = jobHazardDrafts[index];
  if (!hazard) {
    return;
  }
  const fieldName = field.dataset.jobHazardField;
  hazard[fieldName] = "value" in field ? String(field.value || "") : "";
  if (fieldName === "probability" || fieldName === "consequence") {
    hazard.riskLevel = calculateJobHazardRiskLevel(hazard.probability, hazard.consequence) || "";
    renderJobSelectedHazards();
  }
});

