function getFirstUnanalysedRiskAssessmentWorkplaceUnit() {
  const analysedUnitIds = new Set(riskAssessmentJobDrafts.map((job) => String(job.organizationUnitId || "")).filter(Boolean));
  return riskAssessmentOrganizationUnitDrafts.find((unit) => (
    normalizeRiskAssessmentUnitType(unit.type) === "workplace"
    && !analysedUnitIds.has(String(unit.id || ""))
  )) || null;
}

function addRiskAssessmentBlankJob({ openJobsModule = false } = {}) {
  const preferredUnit = getFirstUnanalysedRiskAssessmentWorkplaceUnit();
  if (preferredUnit) {
    const nextIndex = addRiskAssessmentJobFromUnit(preferredUnit.id);
    if (openJobsModule && nextIndex >= 0) {
      openJobsModuleForRiskAssessmentJob(nextIndex);
    }
    return nextIndex;
  }

  const parent = riskAssessmentOrganizationUnitDrafts.find((unit) => normalizeRiskAssessmentUnitType(unit.type) !== "workplace") || null;
  const workplace = createRiskAssessmentOrganizationUnitDraft({
    parentId: parent?.id || "",
    type: "workplace",
    name: "Novo radno mjesto",
  });
  riskAssessmentOrganizationUnitDrafts.push(workplace);
  if (parent?.id) {
    riskAssessmentOpenOrganizationUnitIds.add(String(parent.id));
  }
  const nextIndex = addRiskAssessmentJobFromUnit(workplace.id);
  if (openJobsModule && nextIndex >= 0) {
    openJobsModuleForRiskAssessmentJob(nextIndex);
  }
  return nextIndex;
}

function addRiskAssessmentJobFromUnit(unitId = "") {
  const unit = riskAssessmentOrganizationUnitDrafts.find((entry) => String(entry.id || "") === String(unitId || ""));
  if (!unit) {
    return;
  }
  const nextIndex = riskAssessmentJobDrafts.length;
  riskAssessmentJobDrafts.push(createRiskAssessmentJobDraftFromWorkplaceUnit(unit));
  setRiskAssessmentActiveJobIndex(nextIndex);
  renderRiskAssessmentOrganizationUnits();
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
  return nextIndex;
}

function createRiskAssessmentJobDraftFromWorkplaceUnit(unit = {}) {
  return seedRiskAssessmentArmorCatalogRowsForJob(createRiskAssessmentJobDraft({
    organizationUnitId: unit.id,
    jobTitle: unit.name || "Radno mjesto",
    workerCount: unit.workerCount || "",
    description: unit.description || unit.shortDescription || "",
    shortDescription: unit.shortDescription || unit.description || "",
    workplaceDescription: unit.note || "",
    status: "draft",
  }));
}

function ensureRiskAssessmentJobsFromWorkplaceUnits() {
  const workplaceUnits = riskAssessmentOrganizationUnitDrafts.filter((unit) => normalizeRiskAssessmentUnitType(unit.type) === "workplace");
  if (!workplaceUnits.length) {
    return false;
  }
  const existingUnitIds = new Set(riskAssessmentJobDrafts.map((job) => String(job.organizationUnitId || "")).filter(Boolean));
  const missingUnits = workplaceUnits.filter((unit) => !existingUnitIds.has(String(unit.id || "")));
  if (!missingUnits.length) {
    return false;
  }
  const hadJobs = riskAssessmentJobDrafts.length > 0;
  riskAssessmentJobDrafts = [
    ...riskAssessmentJobDrafts,
    ...missingUnits.map((unit) => createRiskAssessmentJobDraftFromWorkplaceUnit(unit)),
  ];
  if (!hadJobs) {
    setRiskAssessmentActiveJobIndex(0);
  }
  return true;
}

