async function convertDocumentTemplateWordFileToHtml(file) {
  if (!(file instanceof File)) {
    return;
  }

  if (documentTemplateReferenceUploadButton instanceof HTMLButtonElement) {
    documentTemplateReferenceUploadButton.disabled = true;
    documentTemplateReferenceUploadButton.classList.add("is-loading");
  }
  setDocumentTemplateMessage("Pretvaram Word u HTML...");

  try {
    const dataUrl = await readFileAsDataUrl(file, "Ne mogu učitati Word predložak.");
    const payload = await apiRequest("/document-templates/convert-word-html", {
      method: "POST",
      body: {
        referenceDocument: {
          fileName: file.name,
          fileType: file.type || "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
          fileSize: file.size || 0,
          dataUrl,
        },
      },
    });
    const htmlCode = String(payload?.html || "").trim();
    if (!htmlCode) {
      throw new Error("Konverzija nije vratila HTML kod.");
    }

    const fileName = String(payload?.fileName || sanitizeDocumentTemplateFileName(file.name || "word-template", "word-template").replace(/\.(docx|dotx)$/i, ".html")).trim()
      || "word-template.html";
    if (documentTemplateHtmlCodeInput instanceof HTMLTextAreaElement) {
      documentTemplateHtmlCodeInput.value = htmlCode;
    }
    hydrateDocumentTemplateHtmlBuilderFromCode(htmlCode);
    setDocumentTemplateReferenceDocument({
      fileName,
      fileType: "text/html",
      fileSize: new TextEncoder().encode(htmlCode).length,
      dataUrl: textToDataUrl(htmlCode),
      updatedAt: new Date().toISOString(),
    });
    renderDocumentTemplateHtmlPreviewContent();
    const warningCount = Array.isArray(payload?.messages) ? payload.messages.length : 0;
    const engine = String(payload?.engine || "").trim().toLowerCase();
    const conversionLabel = engine === "libreoffice"
      ? "Word je pretvoren u HTML s očuvanim layoutom"
      : engine === "ooxml"
        ? "Word je pretvoren u HTML s detaljnim Word stilovima"
      : engine === "mammoth"
        ? "Word je pretvoren u HTML tekstualnim fallbackom"
        : "Word je pretvoren u HTML";
    setDocumentTemplateMessage(
      warningCount > 0
        ? `${conversionLabel}. Provjeri ${warningCount} napomena iz konverzije prije spremanja.`
        : `${conversionLabel} i spreman je za preview.`,
      { type: "success" },
    );
  } catch (error) {
    console.error("Ne mogu pretvoriti Word u HTML.", error);
    setDocumentTemplateMessage(error?.message || "Ne mogu pretvoriti Word u HTML.");
  } finally {
    if (documentTemplateReferenceUploadButton instanceof HTMLButtonElement) {
      documentTemplateReferenceUploadButton.disabled = false;
      documentTemplateReferenceUploadButton.classList.remove("is-loading");
    }
  }
}

async function storeDocumentTemplateWordReferenceFile(file) {
  if (!(file instanceof File)) {
    return;
  }

  if (documentTemplateReferenceUploadButton instanceof HTMLButtonElement) {
    documentTemplateReferenceUploadButton.disabled = true;
    documentTemplateReferenceUploadButton.classList.add("is-loading");
  }
  setDocumentTemplateMessage("Učitavam Word predložak...");

  try {
    const dataUrl = await readFileAsDataUrl(file, "Ne mogu učitati Word predložak.");
    setDocumentTemplateReferenceDocument({
      fileName: file.name,
      fileType: file.type || "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      fileSize: file.size || 0,
      dataUrl,
      builderDocument: [],
      updatedAt: new Date().toISOString(),
    });
    setDocumentTemplateMessage("Word predložak je učitan u draft. Spremi template kako bi ostao povezan.", { type: "success" });
  } catch (error) {
    console.error("Ne mogu učitati Word predložak.", error);
    setDocumentTemplateMessage(error?.message || "Ne mogu učitati Word predložak.");
  } finally {
    if (documentTemplateReferenceUploadButton instanceof HTMLButtonElement) {
      documentTemplateReferenceUploadButton.disabled = false;
      documentTemplateReferenceUploadButton.classList.remove("is-loading");
    }
  }
}

documentTemplateReferenceFileInput?.addEventListener("change", () => {
  const file = documentTemplateReferenceFileInput.files?.[0];

  if (!file) {
    return;
  }

  const isHtmlFile = isDocumentTemplateHtmlReferenceDocument(file);
  const isWordFile = isDocumentTemplateWordReferenceDocument(file);
  const selectedEngine = getDocumentTemplateSelectedReferenceEngine();
  if (selectedEngine === "word" && !isWordFile) {
    setDocumentTemplateMessage("Odabrano je Word / PDF. Učitaj .docx/.dotx Word predložak.");
    documentTemplateReferenceFileInput.value = "";
    return;
  }
  if (isWordFile) {
    const task = selectedEngine === "word"
      ? storeDocumentTemplateWordReferenceFile(file)
      : convertDocumentTemplateWordFileToHtml(file);
    void task
      .finally(() => {
        documentTemplateReferenceFileInput.value = "";
      });
    return;
  }

  if (!isHtmlFile) {
    setDocumentTemplateMessage("Template Development prima .html/.htm ili Word .docx/.dotx predloške.");
    documentTemplateReferenceFileInput.value = "";
    return;
  }

  void readHtmlTemplateFileAsText(file)
    .then((htmlText) => {
      const normalizedHtmlText = ensureHtmlUtf8Meta(htmlText);
      const dataUrl = textToDataUrl(normalizedHtmlText);
      setDocumentTemplateReferenceDocument({
        fileName: file.name,
        fileType: file.type || "text/html",
        fileSize: new TextEncoder().encode(normalizedHtmlText).length,
        dataUrl,
        updatedAt: new Date().toISOString(),
      });
      if (documentTemplateHtmlCodeInput) {
        documentTemplateHtmlCodeInput.value = normalizedHtmlText;
        documentTemplateHtmlCodeDirty = false;
        hydrateDocumentTemplateHtmlBuilderFromCode(normalizedHtmlText);
        renderDocumentTemplateHtmlPreviewContent();
      }
      setDocumentTemplateMessage("Predložak je učitan u draft. Spremi template kako bi ostao povezan.", { type: "success" });
    })
    .catch((error) => {
      setDocumentTemplateMessage(error.message);
    })
    .finally(() => {
      documentTemplateReferenceFileInput.value = "";
    });
});

