function buildRiskAssessmentGeneratedTitle(companyId = riskAssessmentCompanyInput?.value || "") {
  const company = getRiskAssessmentCompany(companyId);
  return `Procjena rizika - ${company?.name || "tvrtka"}`;
}

function getRiskAssessmentEditorBlocks() {
  return Array.from(riskAssessmentForm?.querySelectorAll("[data-risk-assessment-block]") ?? []);
}

function setRiskAssessmentDockActive(blockKey = "basic") {
  const buttons = Array.from(riskAssessmentDock?.querySelectorAll("[data-risk-assessment-jump]") ?? []);
  buttons.forEach((button) => {
    const isActive = button.dataset.riskAssessmentJump === blockKey;
    button.classList.toggle("is-active", isActive);
    if (isActive) {
      button.scrollIntoView({ block: "nearest", inline: "center", behavior: "smooth" });
    }
  });
}

function syncRiskAssessmentEditorActionVisibility() {
  const isOverview = riskAssessmentActiveBlock === "overview";
  [
    riskAssessmentExportDocxButton,
    riskAssessmentExportPdfButton,
    riskAssessmentSendSignatureButton,
  ].forEach((button) => {
    if (button) {
      button.hidden = !isOverview;
    }
  });
  if (riskAssessmentResetButton) {
    riskAssessmentResetButton.hidden = true;
  }
  riskAssessmentEditorPanel?.classList.toggle("is-overview-active", isOverview);
}

function setRiskAssessmentActiveBlock(blockKey = "basic", { resetScroll = false } = {}) {
  const blocks = getRiskAssessmentEditorBlocks();
  if (!blocks.length) {
    setRiskAssessmentDockActive("basic");
    syncRiskAssessmentEditorActionVisibility();
    return;
  }
  const knownKeys = new Set(blocks.map((block) => block.dataset.riskAssessmentBlock).filter(Boolean));
  const activeKey = knownKeys.has(blockKey) ? blockKey : "basic";
  riskAssessmentActiveBlock = activeKey;
  blocks.forEach((block) => {
    const isActive = block.dataset.riskAssessmentBlock === activeKey;
    block.hidden = !isActive;
    block.classList.toggle("is-active", isActive);
  });
  setRiskAssessmentDockActive(activeKey);
  if (activeKey === "overview") {
    renderRiskAssessmentOverview();
  }
  if (activeKey === "biological") {
    renderRiskAssessmentBiologicalRulePanel();
  }
  if (riskAssessmentError && !["chemicals", "overview"].includes(activeKey)) {
    setInlineMessage(riskAssessmentError, "");
  }
  if (resetScroll && riskAssessmentEditorBody) {
    riskAssessmentEditorBody.scrollTo({ top: 0, behavior: "auto" });
    requestAnimationFrame(() => {
      riskAssessmentEditorBody.scrollTop = 0;
    });
  }
  syncRiskAssessmentEditorActionVisibility();
  scheduleRiskAssessmentJobAnalysisShellModeUpdate();
}

function getRiskAssessmentDefaultAuthorizationCompanyDetails() {
  const organization = getActiveOrganization?.();
  if (!organization) {
    return "";
  }
  const address = [
    organization.address,
    [organization.postalCode, organization.city].filter(Boolean).join(" "),
  ].filter(Boolean).join(", ");
  return [
    organization.name,
    organization.oib ? `OIB: ${organization.oib}` : "",
    address ? `sjedište: ${address}` : "",
  ].filter(Boolean).join(", ");
}

function getRiskAssessmentRichEditor(key = "") {
  if (key === "intro") {
    return riskAssessmentIntroEditor;
  }
  if (key === "process") {
    return riskAssessmentWorkProcessEditor;
  }
  return riskAssessmentForm?.querySelector(`[data-risk-rich-editor="${String(key).replace(/["\\]/g, "\\$&")}"]`) ?? null;
}

function getRiskAssessmentRichInput(key = "") {
  if (key === "intro") {
    return riskAssessmentIntroInput;
  }
  if (key === "process") {
    return riskAssessmentWorkProcessInput;
  }
  return riskAssessmentForm?.querySelector(`[data-risk-rich-storage="${String(key).replace(/["\\]/g, "\\$&")}"]`) ?? null;
}

function sanitizeRiskAssessmentImageSrc(value = "") {
  const src = String(value || "").trim();
  if (/^data:image\/(?:png|jpe?g|gif|webp|bmp);base64,[a-z0-9+/=\s]+$/i.test(src)) {
    return src;
  }
  if (/^https?:\/\//i.test(src)) {
    return src;
  }
  return "";
}

function normalizeRiskAssessmentRichHtml(value = "") {
  const raw = String(value || "").trim();
  if (!raw) {
    return "";
  }
  return normalizeRichTextHtml(raw);
}

function setRiskAssessmentRichValue(key = "", value = "") {
  const editor = getRiskAssessmentRichEditor(key);
  const input = getRiskAssessmentRichInput(key);
  const html = normalizeRiskAssessmentRichHtml(value);
  if (input) {
    input.value = html;
  }
  if (editor) {
    editor.innerHTML = html;
  }
}

function syncRiskAssessmentRichValue(key = "") {
  const editor = getRiskAssessmentRichEditor(key);
  const input = getRiskAssessmentRichInput(key);
  if (!editor || !input) {
    return "";
  }
  const html = normalizeRiskAssessmentRichHtml(editor.innerHTML);
  input.value = html;
  return html;
}

function syncRiskAssessmentRichValues() {
  RISK_ASSESSMENT_RICH_FIELD_KEYS.forEach((key) => {
    syncRiskAssessmentRichValue(key);
  });
}

function readRiskAssessmentRichTemplates() {
  const stored = readJsonFromLocalStorage(RISK_ASSESSMENT_RICH_TEMPLATE_STORAGE_KEY, {});
  return Object.entries(RISK_ASSESSMENT_RICH_TEMPLATE_FIELDS).reduce((templates, [fieldKey, config]) => {
    const customItems = Array.isArray(stored?.[fieldKey]) ? stored[fieldKey] : [];
    templates[fieldKey] = [
      ...config.defaultTemplates.map((item) => ({
        id: String(item.id || crypto.randomUUID()),
        label: String(item.label || config.label || "Predložak").trim(),
        html: normalizeRiskAssessmentRichHtml(item.html || ""),
        source: "default",
      })).filter((item) => item.label && item.html),
      ...customItems.map((item) => ({
        id: String(item?.id || crypto.randomUUID()),
        label: String(item?.label || "").trim(),
        html: normalizeRiskAssessmentRichHtml(item?.html || item?.text || ""),
        source: "custom",
      })).filter((item) => item.label && item.html),
    ];
    return templates;
  }, {});
}

function writeRiskAssessmentRichTemplates(nextTemplates = {}) {
  const customOnly = Object.entries(RISK_ASSESSMENT_RICH_TEMPLATE_FIELDS).reduce((result, [fieldKey]) => {
    result[fieldKey] = (nextTemplates[fieldKey] ?? [])
      .filter((item) => item.source === "custom")
      .map((item) => ({
        id: String(item.id || crypto.randomUUID()),
        label: String(item.label || "").trim(),
        html: normalizeRiskAssessmentRichHtml(item.html || ""),
      }))
      .filter((item) => item.label && item.html);
    return result;
  }, {});
  writeJsonToLocalStorage(RISK_ASSESSMENT_RICH_TEMPLATE_STORAGE_KEY, customOnly);
}

function renderRiskAssessmentRichTemplateControls() {
  enhanceRiskAssessmentRichToolbars();
  const templates = readRiskAssessmentRichTemplates();
  riskAssessmentForm?.querySelectorAll?.("[data-risk-rich-template-select]").forEach((select) => {
    const fieldKey = select.dataset.riskRichTemplateSelect || "";
    const options = [
      { value: "", label: "Predložak" },
      ...(templates[fieldKey] ?? []).map((item) => ({
        value: item.id,
        label: item.source === "custom" ? `${item.label} · moj` : item.label,
      })),
    ];
    replaceSelectOptions(select, options, "");
  });
}

function renderRiskAssessmentRichSelectEnhancement(config = {}) {
  const command = String(config.command || "").trim();
  if (!command) {
    return "";
  }
  const options = (config.options ?? [])
    .map((option) => `<option value="${escapeHtml(option.value)}">${escapeHtml(option.label)}</option>`)
    .join("");
  return `
    <select data-risk-rich-select-command="${escapeHtml(command)}" aria-label="${escapeHtml(config.label || "Uredi")}">
      <option value="">${escapeHtml(config.label || "Uredi")}</option>
      ${options}
    </select>
  `;
}

function renderRiskAssessmentRichColorEnhancements(command = "foreColor", swatches = [], label = "Boja") {
  return swatches.map((swatch) => `
    <button
      type="button"
      class="risk-assessment-rich-swatch"
      data-risk-rich-command="${escapeHtml(command)}"
      data-risk-rich-value="${escapeHtml(swatch.value)}"
      title="${escapeHtml(`${label}: ${swatch.label}`)}"
      aria-label="${escapeHtml(`${label}: ${swatch.label}`)}"
      style="--risk-rich-swatch:${escapeHtml(swatch.value)}"
    ></button>
  `).join("");
}

function renderRiskAssessmentRichCommandButton({
  command = "",
  label = "",
  title = "",
  value = "",
  className = "",
} = {}) {
  const valueAttribute = value ? ` data-risk-rich-value="${escapeHtml(value)}"` : "";
  const classAttribute = className ? ` class="${escapeHtml(className)}"` : "";
  return `
    <button
      type="button"
      data-risk-rich-command="${escapeHtml(command)}"
      ${valueAttribute}
      ${classAttribute}
      title="${escapeHtml(title || label || command)}"
      aria-label="${escapeHtml(title || label || command)}"
    >${escapeHtml(label || command)}</button>
  `;
}

function renderRiskAssessmentRichToolbarGroup(label = "", className = "", content = "") {
  return `
    <div class="risk-assessment-rich-toolbar-group ${escapeHtml(className)}" aria-label="${escapeHtml(label)}">
      <span class="risk-assessment-rich-toolbar-group-label">${escapeHtml(label)}</span>
      ${content}
    </div>
  `;
}

function renderRiskAssessmentRichPresetButtons(key = "", presets = []) {
  return (presets ?? [])
    .map((preset) => `
      <button
        type="button"
        data-risk-rich-preset="${escapeHtml(preset.fieldKey || key)}"
        data-risk-rich-preset-key="${escapeHtml(preset.presetKey || "")}"
        title="${escapeHtml(preset.label || "Predefinirani tekst")}"
        aria-label="${escapeHtml(preset.label || "Predefinirani tekst")}"
      >${escapeHtml(preset.label || "Predefinirani tekst")}</button>
    `)
    .join("");
}

function getRiskAssessmentRichToolbarEnhancementHtml({
  key = "",
  presets = [],
  templateLabel = "Predložak",
  fileAccept = "image/*",
} = {}) {
  const safeKey = escapeHtml(key);
  return `
    ${renderRiskAssessmentRichToolbarGroup("Stil", "is-style", RISK_ASSESSMENT_RICH_TOOLBAR_SELECTS.map(renderRiskAssessmentRichSelectEnhancement).join(""))}
    ${renderRiskAssessmentRichToolbarGroup("Tekst", "is-text", `
      ${RISK_ASSESSMENT_RICH_TEXT_COMMANDS.map(renderRiskAssessmentRichCommandButton).join("")}
      <button type="button" data-risk-rich-clear title="Očisti formatiranje" aria-label="Očisti formatiranje">Tx</button>
    `)}
    ${renderRiskAssessmentRichToolbarGroup("Liste", "is-list", RISK_ASSESSMENT_RICH_LIST_COMMANDS.map(renderRiskAssessmentRichCommandButton).join(""))}
    ${renderRiskAssessmentRichToolbarGroup("Poravnanje", "is-align", RISK_ASSESSMENT_RICH_ALIGN_COMMANDS.map(renderRiskAssessmentRichCommandButton).join(""))}
    ${renderRiskAssessmentRichToolbarGroup("Boje", "is-color", `
      ${renderRiskAssessmentRichColorEnhancements("foreColor", RISK_ASSESSMENT_RICH_COLOR_SWATCHES, "Boja teksta")}
      <span class="risk-assessment-rich-toolbar-separator" aria-hidden="true"></span>
      ${renderRiskAssessmentRichColorEnhancements("hiliteColor", RISK_ASSESSMENT_RICH_HIGHLIGHT_SWATCHES, "Marker")}
    `)}
    ${renderRiskAssessmentRichToolbarGroup("Umetanje", "is-insert", `
      <button type="button" data-risk-rich-link title="Poveznica" aria-label="Poveznica">Link</button>
      <button type="button" data-risk-rich-insert-table title="Tablica" aria-label="Tablica">Tablica</button>
      <button type="button" data-risk-rich-command="insertHorizontalRule" title="Vodoravna crta" aria-label="Vodoravna crta">Linija</button>
      <button type="button" data-risk-rich-image="file" title="Umetni sliku" aria-label="Umetni sliku">Slika</button>
      <button type="button" data-risk-rich-image="url" title="Umetni sliku s URL-a" aria-label="Umetni sliku s URL-a">URL</button>
    `)}
    ${renderRiskAssessmentRichToolbarGroup("Predlošci", "is-template", `
      ${renderRiskAssessmentRichPresetButtons(key, presets)}
      <select data-risk-rich-template-select="${safeKey}" aria-label="${escapeHtml(templateLabel || "Predložak")}"></select>
      <button type="button" data-risk-rich-template-save="${safeKey}" title="Spremi kao predložak" aria-label="Spremi kao predložak">Spremi</button>
    `)}
    ${renderRiskAssessmentRichToolbarGroup("Prikaz", "is-view", `
      <button type="button" data-risk-rich-toggle-focus title="Fokus prikaz" aria-label="Fokus prikaz">Fokus</button>
    `)}
    <input type="file" accept="${escapeHtml(fileAccept || "image/*")}" data-risk-rich-file="${safeKey}" hidden />
  `;
}

function enhanceRiskAssessmentRichToolbars() {
  riskAssessmentForm?.querySelectorAll?.("[data-risk-rich-toolbar]").forEach((toolbar) => {
    if (!(toolbar instanceof HTMLElement) || toolbar.dataset.riskRichEnhanced === "true") {
      return;
    }
    const key = toolbar.dataset.riskRichToolbar || "";
    const templateLabel = toolbar.querySelector("[data-risk-rich-template-select]")?.getAttribute("aria-label") || "Predložak";
    const fileAccept = toolbar.querySelector("[data-risk-rich-file]")?.getAttribute("accept") || "image/*";
    const presets = Array.from(toolbar.querySelectorAll("[data-risk-rich-preset]")).map((button) => ({
      fieldKey: button.dataset.riskRichPreset || key,
      presetKey: button.dataset.riskRichPresetKey || "",
      label: button.textContent?.trim() || "Predefinirani tekst",
    })).filter((preset) => preset.presetKey);
    toolbar.dataset.riskRichEnhanced = "true";
    toolbar.innerHTML = getRiskAssessmentRichToolbarEnhancementHtml({
      key,
      presets,
      templateLabel,
      fileAccept,
    });
    const editorShell = toolbar.closest(".risk-assessment-rich-editor");
    const surface = editorShell?.querySelector?.("[data-risk-rich-editor]");
    if (editorShell instanceof HTMLElement && surface instanceof HTMLElement) {
      editorShell.classList.add("is-word-enhanced");
      surface.setAttribute("data-placeholder", "Upisi tekst, zalijepi iz Worda, dodaj listu ili umetni tablicu...");
    }
  });
}

function applyRiskAssessmentRichTemplate(fieldKey = "", templateId = "") {
  const template = (readRiskAssessmentRichTemplates()[fieldKey] ?? [])
    .find((item) => String(item.id) === String(templateId));
  if (!template?.html) {
    return;
  }
  const current = syncRiskAssessmentRichValue(fieldKey);
  setRiskAssessmentRichValue(fieldKey, current ? `${current}${template.html}` : template.html);
  scheduleRiskAssessmentDraftAutosave();
}

function saveRiskAssessmentRichTemplate(fieldKey = "") {
  const html = syncRiskAssessmentRichValue(fieldKey);
  if (!html) {
    setInlineMessage(riskAssessmentError, "Upiši tekst koji želiš spremiti kao predložak.");
    return;
  }
  const config = RISK_ASSESSMENT_RICH_TEMPLATE_FIELDS[fieldKey];
  const plainText = html.replace(/<[^>]+>/g, " ");
  const fallbackName = plainText.trim().split(/\s+/).slice(0, 6).join(" ").slice(0, 70) || config?.label || "Predložak";
  const label = String(window.prompt("Naziv predloška", fallbackName) || "").trim();
  if (!label) {
    return;
  }
  const templates = readRiskAssessmentRichTemplates();
  templates[fieldKey] = [
    ...(templates[fieldKey] ?? []),
    {
      id: crypto.randomUUID(),
      label,
      html,
      source: "custom",
    },
  ];
  writeRiskAssessmentRichTemplates(templates);
  renderRiskAssessmentRichTemplateControls();
}

function rememberRiskAssessmentRichEditorSelection(editor = null) {
  if (!(editor instanceof HTMLElement)) {
    return;
  }
  const key = editor.dataset.riskRichEditor || "";
  const selection = window.getSelection?.();
  if (!key || !selection || selection.rangeCount === 0 || !editor.contains(selection.anchorNode)) {
    return;
  }
  riskAssessmentActiveRichEditorKey = key;
  riskAssessmentRichEditorSelection = selection.getRangeAt(0).cloneRange();
}

function restoreRiskAssessmentRichEditorSelection(key = "") {
  const editor = getRiskAssessmentRichEditor(key || riskAssessmentActiveRichEditorKey);
  if (!editor) {
    return null;
  }
  editor.focus({ preventScroll: true });
  const selection = window.getSelection?.();
  if (riskAssessmentRichEditorSelection && editor.contains(riskAssessmentRichEditorSelection.commonAncestorContainer)) {
    selection?.removeAllRanges();
    selection?.addRange(riskAssessmentRichEditorSelection);
  } else if (selection) {
    const range = document.createRange();
    range.selectNodeContents(editor);
    range.collapse(false);
    selection.removeAllRanges();
    selection.addRange(range);
    riskAssessmentRichEditorSelection = range.cloneRange();
  }
  return editor;
}

function insertRiskAssessmentRichHtml(key = "", html = "") {
  const editor = restoreRiskAssessmentRichEditorSelection(key);
  const safeHtml = normalizeRiskAssessmentRichHtml(html);
  if (!editor || !safeHtml) {
    return;
  }
  document.execCommand("insertHTML", false, safeHtml);
  rememberRiskAssessmentRichEditorSelection(editor);
  syncRiskAssessmentRichValue(editor.dataset.riskRichEditor || key);
}

function applyRiskAssessmentRichCommand(key = "", command = "", value = null) {
  const editor = restoreRiskAssessmentRichEditorSelection(key);
  const normalizedCommand = String(command || "").trim();
  if (!editor || !normalizedCommand) {
    return false;
  }
  let applied = false;
  try {
    applied = document.execCommand(normalizedCommand, false, value);
    if (!applied && normalizedCommand === "hiliteColor") {
      applied = document.execCommand("backColor", false, value);
    }
  } catch {
    applied = false;
  }
  rememberRiskAssessmentRichEditorSelection(editor);
  syncRiskAssessmentRichValue(editor.dataset.riskRichEditor || key);
  scheduleRiskAssessmentDraftAutosave();
  return applied;
}

function normalizeRiskAssessmentRichLinkHref(value = "") {
  const source = String(value || "").trim();
  if (!source) {
    return "";
  }
  if (/^(https?:|mailto:|tel:|#)/i.test(source)) {
    return source;
  }
  if (/^[a-z0-9][a-z0-9.-]+\.[a-z]{2,}(?:[/?#].*)?$/i.test(source)) {
    return `https://${source}`;
  }
  return "";
}

function buildRiskAssessmentRichTableHtml(rows = 3, columns = 3) {
  const safeRows = Math.min(8, Math.max(1, Number.parseInt(rows, 10) || 3));
  const safeColumns = Math.min(8, Math.max(1, Number.parseInt(columns, 10) || 3));
  const cells = Array.from({ length: safeColumns }, () => "<td>&nbsp;</td>").join("");
  const body = Array.from({ length: safeRows }, () => `<tr>${cells}</tr>`).join("");
  const headings = Array.from({ length: safeColumns }, (_, index) => `<th>Stupac ${index + 1}</th>`).join("");
  return `<table><thead><tr>${headings}</tr></thead><tbody>${body}</tbody></table><p></p>`;
}

function promptRiskAssessmentRichTableHtml() {
  const rowInput = window.prompt("Broj redaka", "3");
  if (rowInput === null) {
    return "";
  }
  const rowCount = Number.parseInt(rowInput || "3", 10);
  if (!Number.isFinite(rowCount)) {
    return "";
  }
  const columnInput = window.prompt("Broj stupaca", "3");
  if (columnInput === null) {
    return "";
  }
  const columnCount = Number.parseInt(columnInput || "3", 10);
  if (!Number.isFinite(columnCount)) {
    return "";
  }
  return buildRiskAssessmentRichTableHtml(rowCount, columnCount);
}

function insertRiskAssessmentRichLink(key = "") {
  const editor = restoreRiskAssessmentRichEditorSelection(key);
  if (!editor) {
    return;
  }
  const selection = window.getSelection?.();
  const selectedText = String(selection?.toString?.() || "").trim();
  const href = normalizeRiskAssessmentRichLinkHref(window.prompt("URL poveznice", selectedText.match(/^https?:\/\//i) ? selectedText : "https://") || "");
  if (!href) {
    setInlineMessage(riskAssessmentError, "Unesi ispravan URL poveznice.", "error");
    return;
  }
  if (selection && selection.rangeCount > 0 && !selection.isCollapsed && editor.contains(selection.anchorNode)) {
    document.execCommand("createLink", false, href);
  } else {
    insertRiskAssessmentRichHtml(key, `<a href="${escapeHtml(href)}">${escapeHtml(href)}</a>`);
    return;
  }
  rememberRiskAssessmentRichEditorSelection(editor);
  syncRiskAssessmentRichValue(editor.dataset.riskRichEditor || key);
  scheduleRiskAssessmentDraftAutosave();
}

function clearRiskAssessmentRichFormatting(key = "") {
  applyRiskAssessmentRichCommand(key, "removeFormat");
  applyRiskAssessmentRichCommand(key, "formatBlock", "p");
}

function normalizeRiskAssessmentBiologicalSearchText(value = "") {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLocaleLowerCase("hr-HR")
    .trim();
}

function getRiskAssessmentBiologicalNoteLabel(code = "") {
  return RISK_ASSESSMENT_BIOLOGICAL_NOTE_CODES.find((item) => item.code === code)?.label || "";
}

function formatRiskAssessmentBiologicalAgentNotes(agent = {}) {
  const labels = (agent.noteCodes || [])
    .map((code) => {
      const label = getRiskAssessmentBiologicalNoteLabel(code);
      return label ? `${code} - ${label}` : code;
    })
    .filter(Boolean);
  if (agent.limitedAirborneRisk) {
    labels.unshift("(**) ograničen rizik od zaraze prijenosom zrakom");
  }
  return labels.join("; ") || "-";
}

function getRiskAssessmentFilteredBiologicalAgents() {
  const query = normalizeRiskAssessmentBiologicalSearchText(riskAssessmentBiologicalAgentQuery);
  return RISK_ASSESSMENT_BIOLOGICAL_AGENT_CATALOG.filter((agent) => {
    if (riskAssessmentBiologicalAgentCategory !== "all" && agent.category !== riskAssessmentBiologicalAgentCategory) {
      return false;
    }
    if (riskAssessmentBiologicalAgentGroup !== "all" && agent.group !== riskAssessmentBiologicalAgentGroup) {
      return false;
    }
    if (!query) {
      return true;
    }
    const haystack = normalizeRiskAssessmentBiologicalSearchText([
      agent.name,
      agent.category,
      agent.group,
      agent.classification,
      agent.noteRaw,
      formatRiskAssessmentBiologicalAgentNotes(agent),
    ].join(" "));
    return haystack.includes(query);
  });
}

function renderRiskAssessmentBiologicalCategoryOptions() {
  return [
    `<option value="all">Sve kategorije (${escapeHtml(String(RISK_ASSESSMENT_BIOLOGICAL_AGENT_STATS.total))})</option>`,
    ...RISK_ASSESSMENT_BIOLOGICAL_AGENT_CATEGORIES.map((category) => {
      const count = RISK_ASSESSMENT_BIOLOGICAL_AGENT_STATS.byCategory?.[category] || 0;
      return `<option value="${escapeHtml(category)}"${riskAssessmentBiologicalAgentCategory === category ? " selected" : ""}>${escapeHtml(category)} (${escapeHtml(String(count))})</option>`;
    }),
  ].join("");
}

function renderRiskAssessmentBiologicalGroupOptions() {
  return [
    `<option value="all">Sve skupine</option>`,
    ...["2", "3", "4"].map((group) => {
      const count = RISK_ASSESSMENT_BIOLOGICAL_AGENT_STATS.byGroup?.[group] || 0;
      return `<option value="${escapeHtml(group)}"${riskAssessmentBiologicalAgentGroup === group ? " selected" : ""}>Skupina ${escapeHtml(group)} (${escapeHtml(String(count))})</option>`;
    }),
  ].join("");
}

function renderRiskAssessmentBiologicalMeasureTable(items = [], caption = "") {
  const rows = items.map((item) => `
    <tr>
      <td>${escapeHtml(item.area)}</td>
      <td>${escapeHtml(item.measure)}</td>
      <td>${escapeHtml(item.level2)}</td>
      <td>${escapeHtml(item.level3)}</td>
      <td>${escapeHtml(item.level4)}</td>
    </tr>
  `).join("");
  return `
    <table>
      <thead>
        <tr>
          <th>${escapeHtml(caption || "Mjera")}</th>
          <th>Opis mjere</th>
          <th>Razina 2</th>
          <th>Razina 3</th>
          <th>Razina 4</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
  `;
}

function buildRiskAssessmentBiologicalSummaryHtml() {
  const groups = RISK_ASSESSMENT_BIOLOGICAL_AGENT_GROUPS
    .map((item) => `
      <tr>
        <td><strong>${escapeHtml(item.group)}</strong></td>
        <td>${escapeHtml(item.title)}</td>
        <td>${escapeHtml(item.detail)}</td>
      </tr>
    `)
    .join("");
  const activities = RISK_ASSESSMENT_BIOLOGICAL_ACTIVITY_EXAMPLES
    .map((item) => `<li>${escapeHtml(item)}</li>`)
    .join("");
  const notes = RISK_ASSESSMENT_BIOLOGICAL_NOTE_CODES
    .map((item) => `<li><strong>${escapeHtml(item.code)}</strong> - ${escapeHtml(item.label)}</li>`)
    .join("");
  return `
    <h3>Biološke štetnosti prema NN 129/2020</h3>
    <p>Procjena bioloških štetnosti provodi se utvrđivanjem prirode, stupnja i trajanja izloženosti radnika, razvrstavanjem mogućih bioloških agensa i određivanjem mjera za sprječavanje ili smanjivanje izloženosti. Izvor: <a href="${escapeHtml(RISK_ASSESSMENT_BIOLOGICAL_SOURCE_URL)}">Narodne novine NN 129/2020</a>.</p>
    <h4>Skupine bioloških agensa</h4>
    <table>
      <thead><tr><th>Skupina</th><th>Opis</th><th>Procjena</th></tr></thead>
      <tbody>${groups}</tbody>
    </table>
    <h4>Aktivnosti kod kojih je moguća nenamjerna izloženost</h4>
    <ul>${activities}</ul>
    <h4>Oznake u katalogu agensa</h4>
    <ul>${notes}</ul>
    <h4>Mjere izolacije za laboratorije i prostore za životinje</h4>
    ${renderRiskAssessmentBiologicalMeasureTable(RISK_ASSESSMENT_BIOLOGICAL_LAB_ISOLATION_MEASURES, "Područje")}
    <h4>Mjere izolacije za industrijske postupke</h4>
    ${renderRiskAssessmentBiologicalMeasureTable(RISK_ASSESSMENT_BIOLOGICAL_INDUSTRIAL_ISOLATION_MEASURES, "Područje")}
  `;
}

function buildRiskAssessmentBiologicalCatalogHtml() {
  const sections = RISK_ASSESSMENT_BIOLOGICAL_AGENT_CATEGORIES
    .map((category) => {
      const rows = RISK_ASSESSMENT_BIOLOGICAL_AGENT_CATALOG
        .filter((agent) => agent.category === category)
        .map((agent) => `
          <tr>
            <td>${escapeHtml(agent.name)}</td>
            <td>${escapeHtml(agent.classification)}</td>
            <td>${escapeHtml(formatRiskAssessmentBiologicalAgentNotes(agent))}</td>
          </tr>
        `)
        .join("");
      return `
        <h4>${escapeHtml(category)}</h4>
        <table>
          <thead><tr><th>Biološki agens</th><th>Klasifikacija</th><th>Napomene</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      `;
    })
    .join("");
  return `
    <h3>Katalog bioloških agensa prema Prilogu III</h3>
    <p>U katalogu je ${escapeHtml(String(RISK_ASSESSMENT_BIOLOGICAL_AGENT_STATS.total))} klasificiranih bioloških agensa iz Priloga III pravilnika. Katalog služi za stručnu provjeru mogućih izvora izloženosti; konačno razvrstavanje i mjere usklađuju se sa stvarnim radnim procesom, nalazima i dokumentacijom.</p>
    ${sections}
  `;
}

function insertRiskAssessmentBiologicalRuleText(kind = "summary") {
  const html = kind === "catalog"
    ? buildRiskAssessmentBiologicalCatalogHtml()
    : buildRiskAssessmentBiologicalSummaryHtml();
  const current = syncRiskAssessmentRichValue("biologicalHazards");
  setRiskAssessmentRichValue("biologicalHazards", current ? `${current}${html}` : html);
  setInlineMessage(
    riskAssessmentBiologicalRuleMessage,
    kind === "catalog" ? "Katalog agensa dodan je u biološke štetnosti." : "Pregled pravilnika dodan je u biološke štetnosti.",
    "success",
  );
  scheduleRiskAssessmentDraftAutosave();
}

function addRiskAssessmentBiologicalAgentToRiskTable(agentOrName = null) {
  const agent = typeof agentOrName === "string"
    ? findRiskAssessmentBiologicalCatalogAgent(agentOrName)
    : agentOrName;
  const typedName = typeof agentOrName === "string" ? agentOrName.trim() : "";
  const draft = createRiskAssessmentBiologicalRiskDraft(agent
    ? {
      catalogId: agent.id,
      agentName: agent.name,
      category: agent.category,
      group: agent.group,
      classification: agent.classification,
      limitedAirborneRisk: agent.limitedAirborneRisk,
      noteCodes: agent.noteCodes,
    }
    : { agentName: typedName || "Biološka štetnost / izvor izloženosti" });
  riskAssessmentBiologicalRiskDrafts.push(draft);
  renderRiskAssessmentBiologicalRisks();
  scheduleRiskAssessmentDraftAutosave();
  setInlineMessage(
    riskAssessmentBiologicalRuleMessage || riskAssessmentError,
    `${agent ? "Agens" : "Redak"} je dodan u tablicu bioloških štetnosti.`,
    "success",
  );
}

function renderRiskAssessmentBiologicalRulePanel(options = {}) {
  if (!riskAssessmentBiologicalRuleContent) {
    return;
  }
  const { preserveSearchFocus = false } = options;
  const filteredAgents = getRiskAssessmentFilteredBiologicalAgents();
  const visibleAgents = filteredAgents.slice(0, 10);
  const suggestionCards = visibleAgents.map((agent) => `
    <article class="risk-assessment-biological-suggestion">
      <div>
        <strong>${escapeHtml(agent.name)}</strong>
        <small>${escapeHtml(agent.category)} · Skupina ${escapeHtml(agent.classification)}${agent.noteCodes?.length ? ` · ${escapeHtml(agent.noteCodes.join(", "))}` : ""}</small>
      </div>
      <button type="button" class="ghost-button" data-risk-biological-add-agent="${escapeHtml(agent.id)}">Dodaj</button>
    </article>
  `).join("");
  const manualAddLabel = riskAssessmentBiologicalAgentQuery.trim()
    ? `Dodaj "${riskAssessmentBiologicalAgentQuery.trim()}"`
    : "Dodaj ručni redak";
  riskAssessmentBiologicalRuleContent.innerHTML = `
    <div class="risk-assessment-biological-picker">
      <label class="field">
        <span>Pretraga / ručni unos</span>
        <input type="search" data-risk-biological-search placeholder="npr. SARS, Salmonella, otpad, krv, životinje..." value="${escapeHtml(riskAssessmentBiologicalAgentQuery)}">
      </label>
      <label class="field">
        <span>Kategorija</span>
        <select data-risk-biological-filter="category">${renderRiskAssessmentBiologicalCategoryOptions()}</select>
      </label>
      <label class="field">
        <span>Skupina</span>
        <select data-risk-biological-filter="group">${renderRiskAssessmentBiologicalGroupOptions()}</select>
      </label>
      <button type="button" class="secondary-button" data-risk-biological-add-current>${escapeHtml(manualAddLabel)}</button>
    </div>
    <section class="risk-assessment-biological-suggestions" aria-label="Brzi odabir bioloških štetnosti">
      <div class="risk-assessment-biological-suggestions-head">
        <strong>Brzi prijedlozi</strong>
        <span>${escapeHtml(String(filteredAgents.length))} mogućih odabira</span>
      </div>
      ${suggestionCards || `<p class="inline-help">Nema prijedloga za odabrani filter. Dodaj ručni redak i upiši podatke u tablicu.</p>`}
    </section>
  `;
  if (preserveSearchFocus) {
    const searchInput = riskAssessmentBiologicalRuleContent.querySelector("[data-risk-biological-search]");
    searchInput?.focus?.({ preventScroll: true });
    searchInput?.setSelectionRange?.(searchInput.value.length, searchInput.value.length);
  }
}

function renderRiskAssessmentBiologicalAgentDatalist() {
  return `
    <datalist id="risk-assessment-biological-agent-options">
      ${RISK_ASSESSMENT_BIOLOGICAL_AGENT_CATALOG.map((agent) => (
        `<option value="${escapeHtml(agent.name)}">${escapeHtml(`${agent.category} · Skupina ${agent.classification}`)}</option>`
      )).join("")}
    </datalist>
  `;
}

function renderRiskAssessmentBiologicalEditorTextInput(field, value = "", placeholder = "", extraAttributes = "") {
  return `<input data-risk-biological-risk-field="${escapeHtml(field)}" value="${escapeHtml(value || "")}" placeholder="${escapeHtml(placeholder)}"${extraAttributes ? ` ${extraAttributes}` : ""} />`;
}

function renderRiskAssessmentBiologicalEditorTextarea(field, value = "", rows = 2, placeholder = "") {
  return `<textarea data-risk-biological-risk-field="${escapeHtml(field)}" rows="${escapeHtml(String(rows))}" placeholder="${escapeHtml(placeholder)}">${escapeHtml(value || "")}</textarea>`;
}

function renderRiskAssessmentBiologicalScoreSelect({ field = "", value = "", options = [], tone = "neutral" } = {}) {
  return `
    <div class="risk-assessment-risk-select-shell risk-assessment-chemical-score-select-shell is-${escapeHtml(tone)}">
      <i aria-hidden="true"></i>
      <select data-risk-biological-risk-field="${escapeHtml(field)}">
        ${renderRiskAssessmentCompactOptions(options, value || "")}
      </select>
    </div>
  `;
}

function getRiskAssessmentJobDraftValue(job = {}, index = 0) {
  return String(job.id || `job-${index + 1}`);
}

function getRiskAssessmentSubstanceDraft(kind = "", index = -1) {
  if (kind === "biological") {
    return riskAssessmentBiologicalRiskDrafts[index] || null;
  }
  if (kind === "chemical") {
    return riskAssessmentChemicalDrafts[index] || null;
  }
  return null;
}

function setRiskAssessmentSubstanceDraftJobIds(kind = "", index = -1, jobIds = []) {
  const normalizedIds = Array.from(new Set((jobIds ?? []).map(String).filter(Boolean)));
  if (kind === "biological" && riskAssessmentBiologicalRiskDrafts[index]) {
    riskAssessmentBiologicalRiskDrafts[index] = {
      ...riskAssessmentBiologicalRiskDrafts[index],
      usedInJobIds: normalizedIds,
    };
    return true;
  }
  if (kind === "chemical" && riskAssessmentChemicalDrafts[index]) {
    riskAssessmentChemicalDrafts[index] = {
      ...riskAssessmentChemicalDrafts[index],
      usedInJobIds: normalizedIds,
    };
    return true;
  }
  return false;
}

function renderRiskAssessmentSubstanceDraftList(kind = "") {
  if (kind === "biological") {
    renderRiskAssessmentBiologicalRisks();
    return;
  }
  if (kind === "chemical") {
    renderRiskAssessmentChemicals();
  }
}

function getRiskAssessmentSubstanceDisplayName(kind = "", entry = {}) {
  if (kind === "biological") {
    return entry.agentName || "Biološka štetnost";
  }
  return entry.name || "Kemikalija";
}

function getRiskAssessmentSubstanceKindTitle(kind = "") {
  return kind === "biological" ? "Biološka štetnost" : "Kemijska štetnost";
}

function getRiskAssessmentSelectedSubstanceJobs(entry = {}) {
  const selectedIds = new Set((entry.usedInJobIds ?? []).map(String).filter(Boolean));
  if (!selectedIds.size) {
    return [];
  }
  return riskAssessmentJobDrafts
    .map((job, index) => ({ job, id: getRiskAssessmentJobDraftValue(job, index) }))
    .filter(({ id }) => selectedIds.has(id))
    .map(({ job }) => job);
}

function formatRiskAssessmentJobCount(count = 0) {
  if (count === 1) {
    return "1 posao";
  }
  if (count > 1 && count < 5) {
    return `${count} posla`;
  }
  return `${count} poslova`;
}

function getRiskAssessmentSubstanceJobSummary(entry = {}) {
  const selectedIds = (entry.usedInJobIds ?? []).map(String).filter(Boolean);
  const jobs = getRiskAssessmentSelectedSubstanceJobs(entry);
  if (!selectedIds.length) {
    return {
      count: 0,
      buttonLabel: "Odaberi poslove",
      detail: "Nije odabrano",
    };
  }
  const count = jobs.length || selectedIds.length;
  const names = jobs.map((job) => job.jobTitle).filter(Boolean);
  return {
    count,
    buttonLabel: `Poslovi (${count})`,
    detail: names.length
      ? `${names.slice(0, 2).join(", ")}${names.length > 2 ? ` +${names.length - 2}` : ""}`
      : formatRiskAssessmentJobCount(count),
  };
}

function renderRiskAssessmentSubstanceJobAction(kind = "", index = -1, entry = {}) {
  const summary = getRiskAssessmentSubstanceJobSummary(entry);
  const attribute = kind === "biological" ? "data-risk-biological-risk-apply" : "data-risk-chemical-apply";
  return `
    <button type="button" class="ghost-button" ${attribute}="${escapeHtml(String(index))}">${escapeHtml(summary.buttonLabel)}</button>
    <small class="risk-assessment-substance-job-status ${summary.count ? "is-linked" : ""}">${escapeHtml(summary.detail)}</small>
  `;
}

function getRiskAssessmentSubstanceJobPickerElements() {
  const backdrop = document.querySelector("[data-risk-substance-job-picker-backdrop]");
  return {
    backdrop,
    title: backdrop?.querySelector?.("[data-risk-substance-job-picker-title]") || null,
    summary: backdrop?.querySelector?.("[data-risk-substance-job-picker-summary]") || null,
    body: backdrop?.querySelector?.("[data-risk-substance-job-picker-body]") || null,
    feedback: backdrop?.querySelector?.("[data-risk-substance-job-picker-feedback]") || null,
  };
}

function ensureRiskAssessmentSubstanceJobPickerDialog() {
  const existing = getRiskAssessmentSubstanceJobPickerElements();
  if (existing.backdrop) {
    return existing;
  }
  const backdrop = document.createElement("div");
  backdrop.className = "risk-assessment-substance-job-picker-backdrop";
  backdrop.dataset.riskSubstanceJobPickerBackdrop = "";
  backdrop.hidden = true;
  backdrop.innerHTML = `
    <section class="risk-assessment-substance-job-picker-dialog" role="dialog" aria-modal="true" aria-labelledby="risk-assessment-substance-job-picker-title">
      <header class="risk-assessment-substance-job-picker-head">
        <div>
          <span class="section-kicker">Radna mjesta</span>
          <strong id="risk-assessment-substance-job-picker-title" data-risk-substance-job-picker-title>Odaberi poslove</strong>
          <small data-risk-substance-job-picker-summary></small>
        </div>
        <button type="button" class="ghost-button" data-risk-substance-job-picker-close>Zatvori</button>
      </header>
      <div class="risk-assessment-substance-job-picker-toolbar">
        <button type="button" class="ghost-button" data-risk-substance-job-picker-select-all>Označi sve</button>
        <button type="button" class="ghost-button" data-risk-substance-job-picker-clear>Očisti</button>
      </div>
      <div class="risk-assessment-substance-job-picker-body" data-risk-substance-job-picker-body></div>
      <p class="form-error risk-assessment-substance-job-picker-feedback" data-risk-substance-job-picker-feedback></p>
      <footer class="risk-assessment-substance-job-picker-actions">
        <button type="button" class="ghost-button" data-risk-substance-job-picker-save>Samo spremi odabir</button>
        <button type="button" class="primary-button" data-risk-substance-job-picker-apply>Dodaj u odabrana radna mjesta</button>
      </footer>
    </section>
  `;
  backdrop.addEventListener("click", handleRiskAssessmentSubstanceJobPickerClick);
  document.body.append(backdrop);
  return getRiskAssessmentSubstanceJobPickerElements();
}

function renderRiskAssessmentSubstanceJobPickerOptions(kind = "", entry = {}) {
  const selectedIds = new Set((entry.usedInJobIds ?? []).map(String).filter(Boolean));
  if (!riskAssessmentJobDrafts.length) {
    return `<p class="inline-help">Prvo dodaj radno mjesto u analizi radnih mjesta, pa se kemijska ili biološka štetnost može povezati s njim.</p>`;
  }
  return riskAssessmentJobDrafts.map((job, index) => {
    const value = getRiskAssessmentJobDraftValue(job, index);
    const meta = [
      job.organizationUnitName || job.organizationPath,
      job.workerCount ? `${job.workerCount} radnika` : "",
      job.completed ? "Dovršeno" : "",
    ].filter(Boolean).join(" · ");
    return `
      <label class="risk-assessment-substance-job-option">
        <input type="checkbox" data-risk-substance-job-picker-option value="${escapeHtml(value)}"${selectedIds.has(value) ? " checked" : ""}>
        <span>
          <strong>${escapeHtml(job.jobTitle || `Radno mjesto ${index + 1}`)}</strong>
          <small>${escapeHtml(meta || "Radno mjesto u ovoj procjeni")}</small>
        </span>
      </label>
    `;
  }).join("");
}

function renderRiskAssessmentSubstanceJobPickerDialog() {
  const picker = ensureRiskAssessmentSubstanceJobPickerDialog();
  const stateValue = riskAssessmentSubstanceJobPickerState || {};
  const entry = getRiskAssessmentSubstanceDraft(stateValue.kind, stateValue.index);
  if (!entry || !picker.backdrop) {
    return;
  }
  if (picker.title) {
    picker.title.textContent = `${getRiskAssessmentSubstanceKindTitle(stateValue.kind)} - poslovi`;
  }
  if (picker.summary) {
    picker.summary.textContent = getRiskAssessmentSubstanceDisplayName(stateValue.kind, entry);
  }
  if (picker.body) {
    picker.body.innerHTML = renderRiskAssessmentSubstanceJobPickerOptions(stateValue.kind, entry);
  }
  if (picker.feedback) {
    picker.feedback.textContent = "";
  }
}

function openRiskAssessmentSubstanceJobPicker(kind = "", index = -1) {
  const entry = getRiskAssessmentSubstanceDraft(kind, index);
  if (!entry) {
    return;
  }
  riskAssessmentSubstanceJobPickerState = { kind, index };
  const picker = ensureRiskAssessmentSubstanceJobPickerDialog();
  renderRiskAssessmentSubstanceJobPickerDialog();
  if (picker.backdrop) {
    picker.backdrop.hidden = false;
    document.body.classList.add("is-risk-substance-job-picker-open");
    picker.backdrop.querySelector("[data-risk-substance-job-picker-option]")?.focus({ preventScroll: true });
  }
}

function closeRiskAssessmentSubstanceJobPicker() {
  const picker = getRiskAssessmentSubstanceJobPickerElements();
  if (picker.backdrop) {
    picker.backdrop.hidden = true;
  }
  document.body.classList.remove("is-risk-substance-job-picker-open");
  riskAssessmentSubstanceJobPickerState = null;
}

function getRiskAssessmentSubstanceJobPickerSelectedIds() {
  const picker = getRiskAssessmentSubstanceJobPickerElements();
  return Array.from(picker.backdrop?.querySelectorAll("[data-risk-substance-job-picker-option]:checked") ?? [])
    .map((input) => input.value)
    .filter(Boolean);
}

function setRiskAssessmentSubstanceJobPickerFeedback(message = "", type = "error") {
  const picker = getRiskAssessmentSubstanceJobPickerElements();
  if (picker.feedback) {
    picker.feedback.textContent = message;
    picker.feedback.dataset.type = type;
  }
}

function saveRiskAssessmentSubstanceJobPickerSelection({ close = false } = {}) {
  const stateValue = riskAssessmentSubstanceJobPickerState || {};
  if (!setRiskAssessmentSubstanceDraftJobIds(
    stateValue.kind,
    stateValue.index,
    getRiskAssessmentSubstanceJobPickerSelectedIds(),
  )) {
    return false;
  }
  renderRiskAssessmentSubstanceDraftList(stateValue.kind);
  scheduleRiskAssessmentDraftAutosave();
  if (close) {
    closeRiskAssessmentSubstanceJobPicker();
  }
  return true;
}

function applyRiskAssessmentSubstanceJobPickerSelection() {
  const stateValue = riskAssessmentSubstanceJobPickerState || {};
  const selectedIds = getRiskAssessmentSubstanceJobPickerSelectedIds();
  if (!selectedIds.length) {
    setRiskAssessmentSubstanceJobPickerFeedback("Odaberi barem jedno radno mjesto.", "error");
    return;
  }
  if (!setRiskAssessmentSubstanceDraftJobIds(stateValue.kind, stateValue.index, selectedIds)) {
    setRiskAssessmentSubstanceJobPickerFeedback("Nije pronađen redak za povezivanje.", "error");
    return;
  }
  if (stateValue.kind === "biological") {
    applyRiskAssessmentBiologicalRiskToJobs(stateValue.index);
  } else {
    applyRiskAssessmentChemicalToJobs(stateValue.index);
  }
  scheduleRiskAssessmentDraftAutosave();
  closeRiskAssessmentSubstanceJobPicker();
}

function handleRiskAssessmentSubstanceJobPickerClick(event) {
  const target = event.target;
  if (!(target instanceof Element)) {
    return;
  }
  if (target === event.currentTarget || target.closest("[data-risk-substance-job-picker-close]")) {
    event.preventDefault();
    closeRiskAssessmentSubstanceJobPicker();
    return;
  }
  if (target.closest("[data-risk-substance-job-picker-select-all]")) {
    event.preventDefault();
    const picker = getRiskAssessmentSubstanceJobPickerElements();
    picker.backdrop?.querySelectorAll("[data-risk-substance-job-picker-option]").forEach((input) => {
      input.checked = true;
    });
    return;
  }
  if (target.closest("[data-risk-substance-job-picker-clear]")) {
    event.preventDefault();
    const picker = getRiskAssessmentSubstanceJobPickerElements();
    picker.backdrop?.querySelectorAll("[data-risk-substance-job-picker-option]").forEach((input) => {
      input.checked = false;
    });
    return;
  }
  if (target.closest("[data-risk-substance-job-picker-save]")) {
    event.preventDefault();
    saveRiskAssessmentSubstanceJobPickerSelection({ close: true });
    return;
  }
  if (target.closest("[data-risk-substance-job-picker-apply]")) {
    event.preventDefault();
    applyRiskAssessmentSubstanceJobPickerSelection();
  }
}

function getRiskAssessmentBiologicalRiskLinkedJobs(entry = {}) {
  const jobIds = new Set((entry.usedInJobIds ?? []).map(String).filter(Boolean));
  if (!jobIds.size) {
    return [];
  }
  return riskAssessmentJobDrafts.filter((job, index) => jobIds.has(getRiskAssessmentJobDraftValue(job, index)));
}

function getRiskAssessmentBiologicalRiskDisplay(entry = {}) {
  const riskLevel = calculateJobHazardRiskLevel(entry.probability, entry.consequence) || entry.riskLevel || "";
  const score = getRiskAssessmentChemicalRiskScore(entry);
  return { riskLevel, score, tone: getJobHazardRiskTone(riskLevel) };
}

function getRiskAssessmentBiologicalRiskMeta(entry = {}) {
  const notes = formatRiskAssessmentBiologicalAgentNotes({
    limitedAirborneRisk: entry.limitedAirborneRisk,
    noteCodes: entry.noteCodes,
  });
  return [
    entry.category,
    entry.classification ? `Skupina ${entry.classification}` : "",
    notes !== "-" ? notes : "",
  ].filter(Boolean).join(" · ");
}

function renderRiskAssessmentBiologicalRiskTable() {
  return `
    <div class="risk-assessment-chemical-register-head">
      <div>
        <span class="section-kicker">Uređiva tablica</span>
        <strong>Procjena bioloških štetnosti</strong>
        <small>Skupina agensa preuzima se iz Priloga III. Vjerojatnost, posljedica i rizik procjenjuju se zasebno prema stvarnoj izloženosti na radu.</small>
      </div>
      <div class="risk-assessment-biological-risk-actions">
        <span>${escapeHtml(String(riskAssessmentBiologicalRiskDrafts.length))} redaka</span>
        <button type="button" class="secondary-button" data-risk-biological-risk-add>+ Novi redak</button>
      </div>
    </div>
    ${renderRiskAssessmentBiologicalAgentDatalist()}
    <div class="risk-assessment-chemical-register-scroll">
      <table class="risk-assessment-chemical-register-table risk-assessment-chemical-editor-table risk-assessment-biological-risk-table">
        <thead>
          <tr>
            <th>Red.</th>
            <th>Biološki agens / štetnost</th>
            <th>Prilog III</th>
            <th>Izvor izloženosti</th>
            <th>Posljedice / napomena</th>
            <th>Mjere</th>
            <th>Vjerojatnost</th>
            <th>Posljedice</th>
            <th>Rizik</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          ${riskAssessmentBiologicalRiskDrafts.length ? riskAssessmentBiologicalRiskDrafts.map((entry, index) => {
            const risk = getRiskAssessmentBiologicalRiskDisplay(entry);
            const meta = getRiskAssessmentBiologicalRiskMeta(entry);
            return `
              <tr data-risk-biological-risk-index="${escapeHtml(String(index))}">
                <td class="is-index">${escapeHtml(String(index + 1))}.</td>
                <td class="is-biological-name">
                  ${renderRiskAssessmentBiologicalEditorTextInput("agentName", entry.agentName, "npr. SARS-CoV-2, Salmonella...", `list="risk-assessment-biological-agent-options"`)}
                  ${meta ? `<small>${escapeHtml(meta)}</small>` : `<small>Odaberi agens iz kataloga ili upiši izvor štetnosti.</small>`}
                </td>
                <td class="is-prilog-cell">
                  ${renderRiskAssessmentBiologicalEditorTextInput("category", entry.category, "Kategorija")}
                  ${renderRiskAssessmentBiologicalEditorTextInput("classification", entry.classification, "Skupina")}
                </td>
                <td>${renderRiskAssessmentBiologicalEditorTextarea("source", entry.source, 3, "Izvor, način prijenosa, trajanje...")}</td>
                <td>
                  ${renderRiskAssessmentBiologicalEditorTextarea("possibleConsequences", entry.possibleConsequences, 2, "Moguće posljedice")}
                  ${renderRiskAssessmentBiologicalEditorTextarea("note", entry.note, 2, "Napomena")}
                </td>
                <td>${renderRiskAssessmentBiologicalEditorTextarea("existingMeasures", entry.existingMeasures, 4, "Postojeće i dodatne mjere")}</td>
                <td class="is-score-control">
                  ${renderRiskAssessmentBiologicalScoreSelect({
                    field: "probability",
                    value: entry.probability,
                    options: RISK_ASSESSMENT_PROBABILITY_OPTIONS,
                    tone: risk.tone,
                  })}
                </td>
                <td class="is-score-control">
                  ${renderRiskAssessmentBiologicalScoreSelect({
                    field: "consequence",
                    value: entry.consequence,
                    options: RISK_ASSESSMENT_CONSEQUENCE_OPTIONS,
                    tone: risk.tone,
                  })}
                </td>
                <td class="is-risk is-${escapeHtml(risk.tone)}">
                  <output class="risk-assessment-risk-result risk-assessment-chemical-risk-result is-${escapeHtml(risk.tone)}">
                    <i aria-hidden="true"></i>
                    <strong>${escapeHtml(risk.riskLevel || "-")}</strong>
                    ${risk.score ? `<em>${escapeHtml(risk.score)}</em>` : ""}
                  </output>
                </td>
                <td class="is-row-actions">
                  ${renderRiskAssessmentSubstanceJobAction("biological", index, entry)}
                  <button type="button" class="ghost-button card-danger" data-risk-biological-risk-remove="${escapeHtml(String(index))}">Ukloni</button>
                </td>
              </tr>
            `;
          }).join("") : `
            <tr>
              <td colspan="10" class="is-empty-row">Nema redaka. Dodaj biološki agens ili izvor izloženosti za procjenu rizika.</td>
            </tr>
          `}
        </tbody>
      </table>
    </div>
  `;
}

function renderRiskAssessmentBiologicalRisks() {
  if (!riskAssessmentBiologicalRisksList) {
    return;
  }
  riskAssessmentBiologicalRisksList.innerHTML = renderRiskAssessmentBiologicalRiskTable();
  renderRiskAssessmentOverview();
}

function handleRiskAssessmentRichEditorPaste(event) {
  const editor = event.target?.closest?.("[data-risk-rich-editor]");
  if (!editor || !event.clipboardData) {
    return;
  }
  const html = getRichTextHtmlFromClipboard(event.clipboardData);
  if (!html) {
    return;
  }
  event.preventDefault();
  rememberRiskAssessmentRichEditorSelection(editor);
  insertRiskAssessmentRichHtml(editor.dataset.riskRichEditor || riskAssessmentActiveRichEditorKey || "intro", html);
  scheduleRiskAssessmentDraftAutosave();
}

function handleRiskAssessmentRichEditorInput(event) {
  const editor = event.target?.closest?.("[data-risk-rich-editor]");
  if (!editor) {
    return;
  }
  rememberRiskAssessmentRichEditorSelection(editor);
  syncRiskAssessmentRichValue(editor.dataset.riskRichEditor || "");
}

function handleRiskAssessmentRichEditorSelectionChange(event) {
  const editor = event.target?.closest?.("[data-risk-rich-editor]");
  if (editor) {
    rememberRiskAssessmentRichEditorSelection(editor);
  }
}

function handleRiskAssessmentRichToolbarMouseDown(event) {
  const toolbarControl = event.target?.closest?.(
    "[data-risk-rich-command], [data-risk-rich-preset], [data-risk-rich-image], [data-risk-rich-template-save], [data-risk-rich-link], [data-risk-rich-insert-table], [data-risk-rich-clear], [data-risk-rich-toggle-focus]",
  );
  if (!toolbarControl) {
    return;
  }
  const toolbar = toolbarControl.closest("[data-risk-rich-toolbar]");
  const key = toolbar?.dataset.riskRichToolbar || riskAssessmentActiveRichEditorKey || "intro";
  const editor = getRiskAssessmentRichEditor(key);
  if (editor) {
    rememberRiskAssessmentRichEditorSelection(editor);
  }
  event.preventDefault();
}

function handleRiskAssessmentRichEditorClick(event) {
  const commandButton = event.target?.closest?.("[data-risk-rich-command]");
  if (commandButton) {
    event.preventDefault();
    const toolbar = commandButton.closest("[data-risk-rich-toolbar]");
    const key = toolbar?.dataset.riskRichToolbar || riskAssessmentActiveRichEditorKey || "intro";
    const command = commandButton.dataset.riskRichCommand || "";
    const value = commandButton.dataset.riskRichValue || null;
    applyRiskAssessmentRichCommand(key, command, value);
    return;
  }

  const clearButton = event.target?.closest?.("[data-risk-rich-clear]");
  if (clearButton) {
    event.preventDefault();
    const toolbar = clearButton.closest("[data-risk-rich-toolbar]");
    clearRiskAssessmentRichFormatting(toolbar?.dataset.riskRichToolbar || riskAssessmentActiveRichEditorKey || "intro");
    return;
  }

  const linkButton = event.target?.closest?.("[data-risk-rich-link]");
  if (linkButton) {
    event.preventDefault();
    const toolbar = linkButton.closest("[data-risk-rich-toolbar]");
    insertRiskAssessmentRichLink(toolbar?.dataset.riskRichToolbar || riskAssessmentActiveRichEditorKey || "intro");
    return;
  }

  const tableButton = event.target?.closest?.("[data-risk-rich-insert-table]");
  if (tableButton) {
    event.preventDefault();
    const toolbar = tableButton.closest("[data-risk-rich-toolbar]");
    const key = toolbar?.dataset.riskRichToolbar || riskAssessmentActiveRichEditorKey || "intro";
    const tableHtml = promptRiskAssessmentRichTableHtml();
    if (tableHtml) {
      insertRiskAssessmentRichHtml(key, tableHtml);
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }

  const focusButton = event.target?.closest?.("[data-risk-rich-toggle-focus]");
  if (focusButton) {
    event.preventDefault();
    const shell = focusButton.closest(".risk-assessment-rich-editor");
    shell?.classList.toggle("is-focus-mode");
    return;
  }

  const presetButton = event.target?.closest?.("[data-risk-rich-preset]");
  if (presetButton) {
    event.preventDefault();
    const key = presetButton.dataset.riskRichPreset || riskAssessmentActiveRichEditorKey || "intro";
    const presetKey = presetButton.dataset.riskRichPresetKey || "";
    const html = RISK_ASSESSMENT_RICH_PRESETS[presetKey] || "";
    if (html) {
      const current = syncRiskAssessmentRichValue(key);
      setRiskAssessmentRichValue(key, current ? `${current}${html}` : html);
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }

  const imageButton = event.target?.closest?.("[data-risk-rich-image]");
  if (!imageButton) {
    return;
  }
  event.preventDefault();
  const toolbar = imageButton.closest("[data-risk-rich-toolbar]");
  const key = toolbar?.dataset.riskRichToolbar || riskAssessmentActiveRichEditorKey || "intro";
  restoreRiskAssessmentRichEditorSelection(key);
  if (imageButton.dataset.riskRichImage === "file") {
    toolbar?.querySelector(`[data-risk-rich-file="${key}"]`)?.click();
    return;
  }
  const src = sanitizeRiskAssessmentImageSrc(window.prompt("URL slike za umetanje u tekst") || "");
  if (src) {
    insertRiskAssessmentRichHtml(key, `<img src="${escapeHtml(src)}" alt="Slika procjene rizika">`);
  }
}

function handleRiskAssessmentRichEditorControlChange(event) {
  const select = event.target?.closest?.("[data-risk-rich-select-command]");
  if (!select) {
    return;
  }
  const value = select.value || "";
  if (!value) {
    return;
  }
  const toolbar = select.closest("[data-risk-rich-toolbar]");
  const key = toolbar?.dataset.riskRichToolbar || riskAssessmentActiveRichEditorKey || "intro";
  applyRiskAssessmentRichCommand(key, select.dataset.riskRichSelectCommand || "", value);
  select.value = "";
}

async function handleRiskAssessmentRichEditorFileChange(event) {
  const input = event.target?.closest?.("[data-risk-rich-file]");
  if (!input || !(input instanceof HTMLInputElement)) {
    return;
  }
  const key = input.dataset.riskRichFile || riskAssessmentActiveRichEditorKey || "intro";
  const file = input.files?.[0];
  input.value = "";
  if (!file) {
    return;
  }
  if (!String(file.type || "").startsWith("image/")) {
    if (riskAssessmentError) {
      riskAssessmentError.textContent = "Možeš umetnuti samo sliku.";
    }
    return;
  }
  try {
    const dataUrl = await readFileAsDataUrl(file, `Ne mogu učitati sliku ${file.name}.`);
    insertRiskAssessmentRichHtml(key, `<img src="${escapeHtml(dataUrl)}" alt="${escapeHtml(file.name || "Slika procjene rizika")}">`);
  } catch (error) {
    if (riskAssessmentError) {
      riskAssessmentError.textContent = error?.message || "Ne mogu učitati sliku.";
    }
  }
}

function setRiskAssessmentEditorOpen(open) {
  state.riskAssessmentEditorOpen = Boolean(open);
  document.body.classList.toggle("is-offer-editor-open", Boolean(open));
  if (riskAssessmentEditorBackdrop) {
    riskAssessmentEditorBackdrop.hidden = !open;
  }
  if (riskAssessmentEditorPanel) {
    riskAssessmentEditorPanel.hidden = !open;
    riskAssessmentEditorPanel.classList.toggle("is-modal-open", Boolean(open));
  }
  if (open) {
    ensureRiskAssessmentModuleInModuleView();
    riskAssessmentActiveBlock = "basic";
    riskAssessmentEditorPanel?.scrollTo?.({ top: 0, left: 0, behavior: "auto" });
    if (riskAssessmentEditorBody) {
      riskAssessmentEditorBody.scrollTop = 0;
      riskAssessmentEditorBody.scrollLeft = 0;
    }
    setRiskAssessmentActiveBlock("basic");
    requestAnimationFrame(() => {
      if (riskAssessmentEditorBody) {
        riskAssessmentEditorBody.scrollTop = 0;
        riskAssessmentEditorBody.scrollLeft = 0;
      }
      riskAssessmentEditorBody?.focus({ preventScroll: true });
      setRiskAssessmentActiveBlock("basic");
    });
  } else {
    riskAssessmentReportTemplateDraft = getRiskAssessmentModuleTemplateDraft();
    renderRiskAssessmentTemplateBuilder();
  }
}

