function syncSettingsWorkEquipmentAiActiveModalDraft() {
  if (!settingsWorkEquipmentAiActiveModal || !settingsWorkEquipmentAiModalElements?.body) {
    return;
  }
  const { type, kind, key, index } = settingsWorkEquipmentAiActiveModal;
  if (type === "profile") {
    const safeIndex = Number(index);
    if (Number.isInteger(safeIndex) && safeIndex >= 0) {
      settingsWorkEquipmentAiProfileDrafts[safeIndex] = collectSettingsWorkEquipmentAiProfileFromNode(settingsWorkEquipmentAiModalElements.body, safeIndex);
    }
    return;
  }
  setSettingsWorkEquipmentAiInstructionDraft(
    kind || "field",
    key || "",
    collectWorkEquipmentAiInstructionFromNode(settingsWorkEquipmentAiModalElements.body.querySelector("[data-ro-ai-instruction]")),
  );
}

function refreshSettingsWorkEquipmentAiCardStatuses() {
  const updateCard = (card) => {
    const kind = String(card.dataset.roAiCardKind || "").trim();
    const key = String(card.dataset.roAiCardKey || "").trim();
    if (!kind || !key) {
      return;
    }
    const config = getSettingsWorkEquipmentAiDraftConfig(kind, key);
    const configured = hasWorkEquipmentAiInstructionConfig(config);
    card.classList.toggle("is-configured", configured);
    const status = card.querySelector(".settings-work-equipment-ai-card-status");
    if (status) {
      status.textContent = configured ? "Uređeno" : "Default";
    }
  };
  settingsWorkEquipmentAiFields?.querySelectorAll("[data-ro-ai-card-kind]").forEach(updateCard);
  settingsWorkEquipmentAiRegisters?.querySelectorAll("[data-ro-ai-card-kind]").forEach(updateCard);
  settingsWorkEquipmentAiProfiles?.querySelectorAll("[data-ro-ai-profile-index]").forEach((card) => {
    const index = Number.parseInt(String(card.dataset.roAiProfileIndex || ""), 10);
    const profile = normalizeWorkEquipmentAiProfile(settingsWorkEquipmentAiProfileDrafts[index] ?? {}, index);
    const configured = hasWorkEquipmentAiProfile(profile);
    card.classList.toggle("is-configured", configured);
    const title = card.querySelector(".settings-work-equipment-ai-card-open strong");
    const meta = card.querySelector(".settings-work-equipment-ai-card-open em");
    const status = card.querySelector(".settings-work-equipment-ai-card-status");
    if (title) title.textContent = profile.name || `Profil ${index + 1}`;
    if (meta) meta.textContent = getSettingsWorkEquipmentAiProfileSummary(profile);
    if (status) status.textContent = configured ? "Profil" : "Default";
  });
  [settingsWorkEquipmentAiFields, settingsWorkEquipmentAiRegisters].forEach((container) => {
    container?.querySelectorAll(".settings-work-equipment-ai-group").forEach((group) => {
      const cards = Array.from(group.querySelectorAll("[data-ro-ai-card-kind]"));
      const configuredCount = cards.filter((card) => card.classList.contains("is-configured")).length;
      const count = group.querySelector("[data-ro-ai-group-count]");
      if (count) {
        count.textContent = `${configuredCount}/${cards.length}`;
        count.classList.toggle("has-progress", configuredCount > 0);
        count.classList.toggle("is-complete", configuredCount === cards.length && cards.length > 0);
      }
    });
  });
}

function rerenderSettingsWorkEquipmentAiActiveProfileModal() {
  if (!settingsWorkEquipmentAiActiveModal || settingsWorkEquipmentAiActiveModal.type !== "profile" || !settingsWorkEquipmentAiModalElements?.body) {
    return;
  }
  const safeIndex = Number(settingsWorkEquipmentAiActiveModal.index);
  if (!Number.isInteger(safeIndex) || safeIndex < 0) {
    return;
  }
  const profile = normalizeWorkEquipmentAiProfile(settingsWorkEquipmentAiProfileDrafts[safeIndex] ?? {}, safeIndex);
  const canManage = getCanManageSettings();
  settingsWorkEquipmentAiModalElements.body.innerHTML = renderSettingsWorkEquipmentAiProfileModalBody(profile, safeIndex, canManage);
  if (settingsWorkEquipmentAiModalElements.title) {
    settingsWorkEquipmentAiModalElements.title.textContent = profile.name || `Profil ${safeIndex + 1}`;
  }
}

function ensureSettingsWorkEquipmentAiModal() {
  if (settingsWorkEquipmentAiModalElements) {
    return settingsWorkEquipmentAiModalElements;
  }
  const backdrop = document.createElement("div");
  backdrop.className = "settings-work-equipment-ai-modal-backdrop";
  backdrop.hidden = true;
  backdrop.innerHTML = `
    <section class="settings-work-equipment-ai-modal" role="dialog" aria-modal="true" aria-labelledby="settings-work-equipment-ai-modal-title">
      <header class="settings-work-equipment-ai-modal-head">
        <div>
          <span class="section-kicker">RO · NexAI</span>
          <strong id="settings-work-equipment-ai-modal-title">AI uputa</strong>
          <small data-ro-ai-modal-meta></small>
        </div>
        <button type="button" class="icon-button" data-ro-ai-modal-close aria-label="Zatvori">×</button>
      </header>
      <div class="settings-work-equipment-ai-modal-body" data-ro-ai-modal-body></div>
      <footer class="settings-work-equipment-ai-modal-actions">
        <button type="button" class="ghost-button" data-ro-ai-modal-clear>Očisti</button>
        <button type="button" class="primary-button" data-ro-ai-modal-apply>Gotovo</button>
      </footer>
    </section>
  `;
  document.body.appendChild(backdrop);
  settingsWorkEquipmentAiModalElements = {
    backdrop,
    title: backdrop.querySelector("#settings-work-equipment-ai-modal-title"),
    meta: backdrop.querySelector("[data-ro-ai-modal-meta]"),
    body: backdrop.querySelector("[data-ro-ai-modal-body]"),
    closeButton: backdrop.querySelector("[data-ro-ai-modal-close]"),
    clearButton: backdrop.querySelector("[data-ro-ai-modal-clear]"),
    applyButton: backdrop.querySelector("[data-ro-ai-modal-apply]"),
  };
  const closeModal = () => closeSettingsWorkEquipmentAiModal();
  settingsWorkEquipmentAiModalElements.closeButton?.addEventListener("click", closeModal);
  settingsWorkEquipmentAiModalElements.applyButton?.addEventListener("click", closeModal);
  settingsWorkEquipmentAiModalElements.clearButton?.addEventListener("click", () => {
    if (!settingsWorkEquipmentAiActiveModal || !settingsWorkEquipmentAiModalElements?.body) {
      return;
    }
    settingsWorkEquipmentAiModalElements.body.querySelectorAll("input[type='text'], input:not([type]), textarea").forEach((input) => {
      input.value = "";
    });
    settingsWorkEquipmentAiModalElements.body.querySelectorAll("input[type='checkbox']").forEach((input) => {
      input.checked = false;
    });
    settingsWorkEquipmentAiModalElements.body.querySelectorAll("select").forEach((select) => {
      select.value = select.querySelector("option")?.value || "";
    });
    syncSettingsWorkEquipmentAiActiveModalDraft();
    refreshSettingsWorkEquipmentAiCardStatuses();
  });
  settingsWorkEquipmentAiModalElements.body?.addEventListener("input", () => {
    syncSettingsWorkEquipmentAiActiveModalDraft();
    refreshSettingsWorkEquipmentAiCardStatuses();
  });
  settingsWorkEquipmentAiModalElements.body?.addEventListener("change", () => {
    syncSettingsWorkEquipmentAiActiveModalDraft();
    refreshSettingsWorkEquipmentAiCardStatuses();
  });
  settingsWorkEquipmentAiModalElements.body?.addEventListener("click", (event) => {
    const target = event.target instanceof Element ? event.target : event.target?.parentElement;
    if (!target || !settingsWorkEquipmentAiActiveModal || settingsWorkEquipmentAiActiveModal.type !== "profile" || !getCanManageSettings()) {
      return;
    }
    const addButton = target.closest("[data-ro-ai-profile-question-add]");
    const removeButton = target.closest("[data-ro-ai-profile-question-remove]");
    const addVariantButton = target.closest("[data-ro-ai-profile-variant-add]");
    const removeVariantButton = target.closest("[data-ro-ai-profile-variant-remove]");
    if (!(addButton instanceof HTMLElement) && !(removeButton instanceof HTMLElement) && !(addVariantButton instanceof HTMLElement) && !(removeVariantButton instanceof HTMLElement)) {
      return;
    }
    event.preventDefault();
    const safeIndex = Number(settingsWorkEquipmentAiActiveModal.index);
    if (!Number.isInteger(safeIndex) || safeIndex < 0) {
      return;
    }
    syncSettingsWorkEquipmentAiActiveModalDraft();
    const current = normalizeWorkEquipmentAiProfile(settingsWorkEquipmentAiProfileDrafts[safeIndex] ?? {}, safeIndex);
    if (addButton instanceof HTMLElement) {
      current.quickQuestions = [
        ...current.quickQuestions,
        normalizeWorkEquipmentAiQuickQuestion({
          label: "Novo pitanje",
          type: "text",
          options: "",
          aiHint: "",
        }, current.quickQuestions.length),
      ];
    }
    if (removeButton instanceof HTMLElement) {
      const questionIndex = Number.parseInt(String(removeButton.dataset.roAiProfileQuestionRemove || ""), 10);
      current.quickQuestions = current.quickQuestions.filter((_, itemIndex) => itemIndex !== questionIndex);
    }
    if (addVariantButton instanceof HTMLElement) {
      current.variants = [
        ...current.variants,
        normalizeWorkEquipmentAiProfileVariant({
          name: "Nova potkategorija",
          source: "manual",
        }, current.variants.length),
      ];
    }
    if (removeVariantButton instanceof HTMLElement) {
      const variantIndex = Number.parseInt(String(removeVariantButton.dataset.roAiProfileVariantRemove || ""), 10);
      current.variants = current.variants.filter((_, itemIndex) => itemIndex !== variantIndex);
    }
    settingsWorkEquipmentAiProfileDrafts[safeIndex] = normalizeWorkEquipmentAiProfile(current, safeIndex);
    rerenderSettingsWorkEquipmentAiActiveProfileModal();
    refreshSettingsWorkEquipmentAiCardStatuses();
  });
  backdrop.addEventListener("click", (event) => {
    if (event.target === backdrop) {
      closeSettingsWorkEquipmentAiModal();
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !backdrop.hidden && settingsWorkEquipmentAiActiveModal) {
      closeSettingsWorkEquipmentAiModal();
    }
  });
  return settingsWorkEquipmentAiModalElements;
}

function openSettingsWorkEquipmentAiInstructionModal(kind = "field", key = "") {
  const normalizedKind = kind === "register" ? "register" : "field";
  const normalizedKey = String(key || "").trim();
  const field = normalizedKind === "field"
    ? WORK_EQUIPMENT_AI_FIELD_DEFINITIONS.find((definition) => definition.key === normalizedKey)
    : null;
  const register = normalizedKind === "register" ? getSettingsWorkEquipmentAiRegisterDefinition(normalizedKey) : null;
  const definition = field || register;
  if (!definition) {
    return;
  }
  const modal = ensureSettingsWorkEquipmentAiModal();
  const canManage = getCanManageSettings();
  settingsWorkEquipmentAiActiveModal = { type: "instruction", kind: normalizedKind, key: normalizedKey };
  const config = getSettingsWorkEquipmentAiDraftConfig(normalizedKind, normalizedKey);
  if (modal.title) {
    modal.title.textContent = definition.label || "AI uputa";
  }
  if (modal.meta) {
    modal.meta.textContent = normalizedKind === "field"
      ? [definition.group, definition.placeholder].filter(Boolean).join(" · ")
      : (definition.meta || "");
  }
  if (modal.body) {
    modal.body.innerHTML = renderWorkEquipmentAiInstructionMiniForm(config, normalizedKey, {
      disabled: !canManage,
      label: normalizedKind === "register" ? "Kada NexAI smije predložiti ovu IS ZNR stavku" : "Kako NexAI popunjava ovo polje",
      placeholder: normalizedKind === "register"
        ? "Opiši vidljive uvjete, opremu ili tekst zbog kojih se ovaj redak smije dodati."
        : (definition.placeholder || "Kako NexAI treba popuniti ovo polje."),
    });
  }
  if (modal.clearButton) {
    modal.clearButton.hidden = !canManage;
    modal.clearButton.textContent = "Očisti uputu";
  }
  if (modal.applyButton) {
    modal.applyButton.textContent = canManage ? "Gotovo" : "Zatvori";
  }
  modal.backdrop.hidden = false;
  document.body.classList.add("is-settings-work-equipment-ai-modal-open");
  requestAnimationFrame(() => {
    modal.body?.querySelector("textarea, input, select")?.focus({ preventScroll: true });
  });
}

function openSettingsWorkEquipmentAiProfileModal(index = 0) {
  const safeIndex = Number.parseInt(String(index), 10);
  if (!Number.isInteger(safeIndex) || safeIndex < 0) {
    return;
  }
  hydrateSettingsWorkEquipmentAiDrafts();
  const profile = normalizeWorkEquipmentAiProfile(settingsWorkEquipmentAiProfileDrafts[safeIndex] ?? {}, safeIndex);
  const modal = ensureSettingsWorkEquipmentAiModal();
  const canManage = getCanManageSettings();
  settingsWorkEquipmentAiActiveModal = { type: "profile", index: safeIndex };
  if (modal.title) {
    modal.title.textContent = profile.name || `Profil ${safeIndex + 1}`;
  }
  if (modal.meta) {
    modal.meta.textContent = "Profil radne opreme · opće upute · default tekstovi · IS ZNR stavke";
  }
  if (modal.body) {
    modal.body.innerHTML = renderSettingsWorkEquipmentAiProfileModalBody(profile, safeIndex, canManage);
  }
  if (modal.clearButton) {
    modal.clearButton.hidden = !canManage;
    modal.clearButton.textContent = "Očisti profil";
  }
  if (modal.applyButton) {
    modal.applyButton.textContent = canManage ? "Gotovo" : "Zatvori";
  }
  modal.backdrop.hidden = false;
  document.body.classList.add("is-settings-work-equipment-ai-modal-open");
  requestAnimationFrame(() => {
    modal.body?.querySelector("textarea, input, select")?.focus({ preventScroll: true });
  });
}

function closeSettingsWorkEquipmentAiModal() {
  syncSettingsWorkEquipmentAiActiveModalDraft();
  refreshSettingsWorkEquipmentAiCardStatuses();
  if (settingsWorkEquipmentAiModalElements?.backdrop) {
    settingsWorkEquipmentAiModalElements.backdrop.hidden = true;
  }
  settingsWorkEquipmentAiActiveModal = null;
  document.body.classList.remove("is-settings-work-equipment-ai-modal-open");
}

function renderSettingsWorkEquipmentAi(settings = getWorkEquipmentAiSettings()) {
  const normalized = normalizeWorkEquipmentAiSettings(settings);
  syncSettingsWorkEquipmentAiRegistersFromSettings(normalized);
  hydrateSettingsWorkEquipmentAiDrafts(normalized);
  const canManage = getCanManageSettings();
  if (settingsWorkEquipmentAiGeneralInput && document.activeElement !== settingsWorkEquipmentAiGeneralInput) {
    settingsWorkEquipmentAiGeneralInput.value = normalized.generalInstruction;
  }
  if (settingsWorkEquipmentAiExtractionInput && document.activeElement !== settingsWorkEquipmentAiExtractionInput) {
    settingsWorkEquipmentAiExtractionInput.value = normalized.extractionInstruction;
  }
  if (settingsWorkEquipmentAiMatchingInput && document.activeElement !== settingsWorkEquipmentAiMatchingInput) {
    settingsWorkEquipmentAiMatchingInput.value = normalized.matchingInstruction;
  }
  if (settingsWorkEquipmentAiReviewInput && document.activeElement !== settingsWorkEquipmentAiReviewInput) {
    settingsWorkEquipmentAiReviewInput.value = normalized.reviewInstruction;
  }
  if (settingsWorkEquipmentAiModeInput) {
    settingsWorkEquipmentAiModeInput.value = normalized.autoFillMode;
  }
  [
    settingsWorkEquipmentAiGeneralInput,
    settingsWorkEquipmentAiExtractionInput,
    settingsWorkEquipmentAiMatchingInput,
    settingsWorkEquipmentAiReviewInput,
    settingsWorkEquipmentAiModeInput,
  ].forEach((input) => {
    if (input) input.disabled = !canManage;
  });
  if (settingsWorkEquipmentAiSaveButton) {
    settingsWorkEquipmentAiSaveButton.hidden = !canManage;
    settingsWorkEquipmentAiSaveButton.disabled = !canManage;
  }
  if (settingsWorkEquipmentAiRefreshButton) {
    settingsWorkEquipmentAiRefreshButton.disabled = !canManage || !state.activeOrganizationId;
  }
  if (settingsWorkEquipmentAiAddProfileButton) {
    settingsWorkEquipmentAiAddProfileButton.disabled = !canManage;
  }
  renderSettingsWorkEquipmentAiFields();
  renderSettingsWorkEquipmentAiProfiles(normalized);
  renderSettingsWorkEquipmentAiRegisters();
  renderSettingsWorkEquipmentAiOverview(normalized);
  hydrateSettingsWorkEquipmentAiCollapsedSections();
}

async function loadSettingsWorkEquipmentAiRegisters({ force = false } = {}) {
  if (settingsWorkEquipmentAiRegisterGroupsLoaded && !force) {
    return settingsWorkEquipmentAiRegisterGroups;
  }
  if (settingsWorkEquipmentAiRefreshButton) {
    settingsWorkEquipmentAiRefreshButton.disabled = true;
  }
  setInlineMessage(settingsWorkEquipmentAiFeedback, "Dohvaćam IS ZNR šifrarnike za radnu opremu...", "success");
  try {
    const payload = await apiRequest("/isznr/work-equipment?includeRegisters=true&maxRecords=1");
    const nextGroups = normalizeWorkEquipmentAiRegisterGroupsCache(payload?.registers);
    let persistedCache = false;
    let persistCacheError = "";
    if (nextGroups.length > 0) {
      settingsWorkEquipmentAiRegisterGroups = nextGroups;
      settingsWorkEquipmentAiRegisterGroupsFromCache = false;
      settingsWorkEquipmentAiRegisterOrganizationId = String(state.activeOrganizationId || "").trim();
    }
    settingsWorkEquipmentAiRegisterGroupsLoaded = settingsWorkEquipmentAiRegisterGroups.length > 0;
    const nextSettings = collectSettingsWorkEquipmentAiSettings();
    if (nextGroups.length > 0 && getCanManageSettings() && state.activeOrganizationId) {
      try {
        await apiRequest("/work-equipment/ai-settings", {
          method: "POST",
          body: { settings: nextSettings },
        });
        state.workEquipmentAiSettings = normalizeWorkEquipmentAiSettings({
          ...nextSettings,
          organizationId: state.activeOrganizationId,
        });
        persistedCache = true;
      } catch (persistError) {
        persistCacheError = persistError?.message || "spremanje nije uspjelo";
      }
    }
    renderSettingsWorkEquipmentAi(nextSettings);
    const count = settingsWorkEquipmentAiRegisterGroups.reduce((sum, group) => sum + (Array.isArray(group.items) ? group.items.length : 0), 0);
    if (nextGroups.length > 0) {
      setInlineMessage(
        settingsWorkEquipmentAiFeedback,
        persistCacheError
          ? `IS ZNR šifrarnici su učitani (${count} stavki), ali cache nije spremljen: ${persistCacheError}.`
          : `IS ZNR šifrarnici su učitani (${count} stavki)${persistedCache ? " i spremljeni za iduće otvaranje" : ""}.`,
        persistCacheError ? "" : "success",
      );
    } else {
      setInlineMessage(
        settingsWorkEquipmentAiFeedback,
        count > 0
          ? `IS ZNR nije vratio nove šifrarnike. Zadržavam zadnji poznati popis (${count} stavki).`
          : "IS ZNR nije vratio šifrarnike za prikaz.",
        count > 0 ? "success" : "",
      );
    }
    return settingsWorkEquipmentAiRegisterGroups;
  } catch (error) {
    const count = settingsWorkEquipmentAiRegisterGroups.reduce((sum, group) => sum + (Array.isArray(group.items) ? group.items.length : 0), 0);
    setInlineMessage(
      settingsWorkEquipmentAiFeedback,
      count > 0
        ? `${error?.message || "IS ZNR šifrarnici nisu dohvaćeni."} Zadržavam zadnji poznati popis (${count} stavki).`
        : (error?.message || "IS ZNR šifrarnici nisu dohvaćeni."),
      count > 0 ? "success" : "",
    );
    return settingsWorkEquipmentAiRegisterGroups;
  } finally {
    if (settingsWorkEquipmentAiRefreshButton) {
      settingsWorkEquipmentAiRefreshButton.disabled = !getCanManageSettings();
    }
  }
}

async function saveSettingsWorkEquipmentAiSettings(options = {}) {
  const successMessage = typeof options.successMessage === "string" && options.successMessage.trim()
    ? options.successMessage.trim()
    : "RO NexAI upute su spremljene.";
  if (!getCanManageSettings()) {
    setInlineMessage(settingsWorkEquipmentAiFeedback, "Nemate pravo spremati RO NexAI upute.");
    return false;
  }
  if (!state.activeOrganizationId) {
    setInlineMessage(settingsWorkEquipmentAiFeedback, "Odaberi organizaciju prije spremanja RO NexAI uputa.");
    return false;
  }
  if (settingsWorkEquipmentAiSaveButton) {
    settingsWorkEquipmentAiSaveButton.disabled = true;
  }
  const settings = collectSettingsWorkEquipmentAiSettings();
  const success = await runMutation(() => apiRequest("/work-equipment/ai-settings", {
    method: "POST",
    body: { settings },
  }), settingsWorkEquipmentAiFeedback);
  if (settingsWorkEquipmentAiSaveButton) {
    settingsWorkEquipmentAiSaveButton.disabled = !getCanManageSettings();
  }
  if (success) {
    state.workEquipmentAiSettings = normalizeWorkEquipmentAiSettings({
      ...settings,
      organizationId: state.activeOrganizationId,
    });
    settingsWorkEquipmentAiFieldDrafts = normalizeWorkEquipmentAiInstructionMap(state.workEquipmentAiSettings.fieldInstructions);
    settingsWorkEquipmentAiRegisterDrafts = normalizeWorkEquipmentAiInstructionMap(state.workEquipmentAiSettings.registryInstructions);
    settingsWorkEquipmentAiProfileDrafts = state.workEquipmentAiSettings.profiles;
    settingsWorkEquipmentAiDraftInitialized = true;
    renderSettingsWorkEquipmentAi(state.workEquipmentAiSettings);
    setInlineMessage(settingsWorkEquipmentAiFeedback, successMessage, "success");
  }
  return success;
}

function applyJobAiInstructionToText(text = "", kind = "description") {
  const config = getJobAiInstruction(kind);
  if (!hasJobAiInstructionConfig(config)) {
    return text;
  }

  let output = String(text || "").trim();
  if (config.style === "short") {
    output = output.split(/(?<=[.!?])\s+/).slice(0, 2).join(" ").trim() || output;
  } else if (config.style === "detailed") {
    output = `${output} U opisu je potrebno navesti okolnosti rada, učestalost, opremu, očekivane uvjete i mjere zaštite koje su bitne za taj posao.`;
  } else if (config.style === "legal") {
    output = `${output} Formulacija se priprema za uporabu u dokumentaciji zaštite na radu te mora biti jasna, provjerljiva i bez nepotrebnih pretpostavki.`;
  }

  const additions = [];
  if (config.instruction) {
    additions.push(`Posebno obraditi: ${config.instruction}.`);
  }
  if (config.mustInclude) {
    additions.push(`Obavezno uključiti: ${config.mustInclude}.`);
  }
  if (config.textLength) {
    additions.push(`Duljina teksta: ${config.textLength}.`);
  }
  return [output, ...additions].filter(Boolean).join(" ");
}

function renderRiskAssessmentRowAiTemplateText(value = "", row = {}, job = {}, context = {}) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }
  const replacements = {
    radno_mjesto: context.title || job.jobTitle || job.title || "",
    posao: context.title || job.jobTitle || job.title || "",
    opis_posla: compactJobContextText(context.description || job.description || job.tasks || "", 360),
    stavka: row.hazard || row.catalogLabel || "",
    opasnost: row.hazard || row.catalogLabel || "",
    sifra: row.code || row.catalogCode || "",
    skupina: row.group || "",
    kategorija: row.category || row.topCategory || "",
    mjere: row.measures || row.existingMeasures || "",
    pur: row.shortLabel || row.label || row.hazard || row.catalogLabel || "",
    pur_tocka: row.code || row.value || row.catalogCode || "",
    posebni_uvjet: row.label || row.hazard || row.catalogLabel || "",
  };
  return text.replace(/\{([a-z0-9_]+)\}/gi, (match, token) => {
    const key = String(token || "").toLowerCase();
    return Object.prototype.hasOwnProperty.call(replacements, key) ? replacements[key] : match;
  });
}

function splitRiskAssessmentAiTerms(value = "") {
  return String(value || "")
    .split(/[,\n;]+/)
    .map((term) => normalizeRiskAssessmentAiText(term).trim())
    .filter((term) => term.length >= 3);
}

function shouldSkipRiskAssessmentRowByAiInstruction(row = {}, context = {}, config = {}) {
  const avoidTerms = splitRiskAssessmentAiTerms(config.avoid);
  if (!avoidTerms.length) {
    return false;
  }
  const haystack = normalizeRiskAssessmentAiText([
    context.text,
    context.description,
    context.title,
    row.category,
    row.group,
    row.code,
    row.hazard,
  ].filter(Boolean).join(" "));
  return avoidTerms.some((term) => haystack.includes(term));
}

function applyRiskAssessmentRowAiSettings(row = {}, job = {}, context = getRiskAssessmentJobHazardContext(job)) {
  const config = getJobAiInstruction(getRiskAssessmentRowAiInstructionKey(row));
  if (!hasJobAiInstructionConfig(config)) {
    return row;
  }

  const next = { ...row };
  if (config.probability) {
    next.probability = config.probability;
  }
  if (config.consequence) {
    next.consequence = config.consequence;
  }
  if (config.probability || config.consequence) {
    next.riskLevel = calculateRiskAssessmentRiskLevel(next.probability, next.consequence) || next.riskLevel || "";
  }

  [
    "possibleConsequences",
    "workNote",
    "note",
    "existingMeasures",
    "additionalMeasures",
    "measures",
  ].forEach((field) => {
    if (config[field]) {
      next[field] = renderRiskAssessmentRowAiTemplateText(config[field], row, job, context);
    }
  });

  const extraNotes = [];
  if (config.instruction) {
    extraNotes.push(`AI kriterij: ${renderRiskAssessmentRowAiTemplateText(config.instruction, row, job, context)}`);
  }
  if (config.mustInclude) {
    extraNotes.push(`Obavezno provjeriti: ${renderRiskAssessmentRowAiTemplateText(config.mustInclude, row, job, context)}`);
  }
  if (extraNotes.length) {
    next.workNote = joinUniqueRiskAssessmentTextBlocks([next.workNote, ...extraNotes]);
  }

  return next;
}

function applyRiskAssessmentRowAiSettingsToJobHazard(hazard = {}, sourceRow = {}, options = {}) {
  const config = getJobAiInstruction(getRiskAssessmentRowAiInstructionKey(sourceRow));
  if (!hasJobAiInstructionConfig(config)) {
    return hazard;
  }
  const context = options.context || getJobHazardContextFromForm();
  const next = { ...hazard };
  if (config.probability) {
    next.probability = config.probability;
  }
  if (config.consequence) {
    next.consequence = config.consequence;
  }
  if (config.probability || config.consequence) {
    next.riskLevel = calculateJobHazardRiskLevel(next.probability, next.consequence) || next.riskLevel || "";
  }
  if (config.workNote) {
    next.unwantedEvent = renderRiskAssessmentRowAiTemplateText(config.workNote, sourceRow, {}, context);
  }
  if (config.existingMeasures || config.measures) {
    next.measures = renderRiskAssessmentRowAiTemplateText(config.existingMeasures || config.measures, sourceRow, {}, context);
  }
  if (config.note) {
    next.note = renderRiskAssessmentRowAiTemplateText(config.note, sourceRow, {}, context);
  }
  return next;
}

function formatJobSentenceList(values = [], fallback = "") {
  const items = Array.from(new Set(
    (Array.isArray(values) ? values : [values])
      .map((value) => String(value || "").trim())
      .filter(Boolean),
  ));
  if (items.length === 0) {
    return fallback;
  }
  if (items.length === 1) {
    return items[0];
  }
  if (items.length === 2) {
    return `${items[0]} i ${items[1]}`;
  }
  return `${items.slice(0, -1).join(", ")} i ${items[items.length - 1]}`;
}

function getJobSentenceTitle() {
  return String(jobTitleInput?.value || "odabrani posao").trim() || "odabrani posao";
}

function getJobEnvironmentOptionField(sectionKey = "") {
  return JOB_ENVIRONMENT_OPTION_FIELD_BY_KEY[String(sectionKey || "").trim()] || "";
}

function getSelectedJobEnvironmentOptions(sectionKey = "") {
  return Array.from(jobEnvironmentSections?.querySelectorAll(`[data-job-env-suggestion="${sectionKey}"].is-selected`) ?? [])
    .map((button) => String(button.dataset.value || "").trim())
    .filter(Boolean);
}

function uniqueJobValues(values = []) {
  return Array.from(new Set(
    (Array.isArray(values) ? values : [values])
      .flatMap((value) => Array.isArray(value) ? value : [value])
      .map((value) => String(value || "").trim())
      .filter(Boolean),
  ));
}

function mergeJobValues(...groups) {
  return uniqueJobValues(groups.flat());
}

function normalizeJobPurPointValues(values = []) {
  const allowed = new Set(JOB_PUR_POINTS.map((point) => point.value));
  return uniqueJobValues(values).filter((value) => allowed.has(value)).slice(0, JOB_PUR_POINT_SELECTION_LIMIT);
}

function getJobPurPoint(value = "") {
  return JOB_PUR_POINTS.find((point) => point.value === String(value || "").trim()) ?? null;
}

function getJobPurPointLabel(value = "") {
  const point = getJobPurPoint(value);
  return point ? `${point.value}. ${point.label}` : String(value || "").trim();
}

function getJobPurPointSummary(values = []) {
  const labels = normalizeJobPurPointValues(values).map((value) => getJobPurPoint(value)?.shortLabel || getJobPurPointLabel(value));
  return labels.length ? labels.join(", ") : "Nema odabranih PUR točaka";
}

function getJobPurPointDefaultReasonLine(value = "") {
  const point = getJobPurPoint(value);
  return point ? `${point.value}. ${point.label} - ${point.description}` : "";
}

function getJobPurPointAiReasonLine(value = "", options = {}) {
  const point = getJobPurPoint(value);
  if (!point) {
    return "";
  }
  const config = getJobAiInstruction(getJobPurPointAiInstructionKey(point.value));
  if (!hasJobAiInstructionConfig(config)) {
    return "";
  }
  const job = options.job || {};
  const context = options.context || getRiskAssessmentJobHazardContext(job);
  const purRow = {
    ...point,
    code: point.value,
    hazard: point.label,
    category: "Poslovi s posebnim uvjetima rada",
    group: point.parentValue ? `Točka ${point.parentValue}` : "Pravilnik o poslovima s posebnim uvjetima rada",
  };
  const configuredText = renderRiskAssessmentRowAiTemplateText(
    config.workNote || config.instruction || config.note,
    purRow,
    job,
    context,
  );
  return configuredText ? `${point.value}. ${point.label} - ${configuredText}` : "";
}

function getJobPurPointReasonLines(values = [], options = {}) {
  return normalizeJobPurPointValues(values)
    .map((value) => (
      options.includeAi === false
        ? getJobPurPointDefaultReasonLine(value)
        : (getJobPurPointAiReasonLine(value, options) || getJobPurPointDefaultReasonLine(value))
    ))
    .filter(Boolean);
}

function getJobPurPointGeneratedReasonLines(values = [], options = {}) {
  const generated = new Set();
  normalizeJobPurPointValues(values).forEach((value) => {
    [
      getJobPurPointDefaultReasonLine(value),
      getJobPurPointAiReasonLine(value, options),
    ].filter(Boolean).forEach((line) => generated.add(line));
  });
  return Array.from(generated);
}

function getJobPurPointFullLines(values = [], options = {}) {
  return normalizeJobPurPointValues(values)
    .map((value) => {
      const point = getJobPurPoint(value);
      return point
        ? (options.includeAi === false
          ? getJobPurPointDefaultReasonLine(value)
          : getJobPurPointAiReasonLine(value, options) || getJobPurPointDefaultReasonLine(value))
        : "";
    })
    .filter(Boolean);
}

function getJobPurPointFullText(values = [], fallback = "Nema odabranih poslova s posebnim uvjetima rada.", options = {}) {
  const lines = getJobPurPointFullLines(values, options);
  return lines.length ? lines.join("\n") : fallback;
}

function getJobPurPointReasonText(values = [], options = {}) {
  const lines = getJobPurPointReasonLines(values, options);
  return lines.length ? lines.join("\n") : "";
}

function getJobPurPointGroups() {
  return JOB_PUR_POINTS
    .filter((point) => !point.parentValue)
    .map((point) => ({
      point,
      children: JOB_PUR_POINTS.filter((entry) => String(entry.parentValue || "") === String(point.value)),
    }));
}

function renderJobPurPointButton(point = {}, selected = new Set(), dataAttribute = "data-job-pur-point", extraAttributes = "") {
  const isSelected = selected.has(point.value);
  return `
    <button type="button"
      class="job-pur-option ${point.parentValue ? "is-subpoint" : "is-mainpoint"} ${isSelected ? "is-selected" : ""}"
      ${dataAttribute}="${escapeHtml(point.value)}"
      ${extraAttributes}
      title="${escapeHtml(point.description)}">
      <span>${escapeHtml(point.value)}</span>
      <strong>${escapeHtml(point.shortLabel || point.label)}</strong>
      <small>${escapeHtml(point.description)}</small>
    </button>
  `;
}

function renderJobPurPointGroups(selected = new Set(), dataAttribute = "data-job-pur-point", extraAttributes = "") {
  return getJobPurPointGroups().map(({ point, children }) => {
    const selectedChildren = children.filter((child) => selected.has(child.value));
    const hasSelection = selected.has(point.value) || selectedChildren.length > 0;
    return `
      <section class="job-pur-group ${children.length ? "has-children" : ""} ${hasSelection ? "is-selected" : ""}">
        <div class="job-pur-group-head">
          ${renderJobPurPointButton(point, selected, dataAttribute, extraAttributes)}
          ${children.length ? `<em>${escapeHtml(`${selectedChildren.length}/${children.length} razrada`)}</em>` : ""}
        </div>
        ${children.length ? `
          <div class="job-pur-subgrid" aria-label="${escapeHtml(`Razrada točke ${point.value}`)}">
            ${children.map((child) => renderJobPurPointButton(child, selected, dataAttribute, extraAttributes)).join("")}
          </div>
        ` : ""}
      </section>
    `;
  }).join("");
}

function renderJobPurPointPicker(selectedValues = [], dataAttribute = "data-job-pur-point") {
  const selected = new Set(normalizeJobPurPointValues(selectedValues));
  const selectedCount = selected.size;
  const selectedSummary = getJobPurPointSummary(selectedValues);
  return `
    <details class="job-pur-dropdown job-pur-multiselect" ${selectedCount ? "open" : ""}>
      <summary>
        <span>
          <strong>Odaberi PUR točke prema Pravilniku</strong>
          <small>Višestruki odabir. Točka 18 je razrađena po izloženostima, točka 19 ostaje po posebnom propisu.</small>
        </span>
        <em data-job-pur-dropdown-count>${escapeHtml(selectedCount ? `${selectedCount} odabrano` : "Otvori popis")}</em>
      </summary>
      <div class="job-pur-selected-summary" data-job-pur-dropdown-summary>${escapeHtml(selectedSummary)}</div>
      <div class="job-pur-picker">
        ${renderJobPurPointGroups(selected, dataAttribute)}
      </div>
    </details>
  `;
}

function getJobWorkProfilePreset(key = "") {
  return JOB_WORK_PROFILE_PRESETS.find((preset) => preset.key === String(key || "").trim()) ?? null;
}

function mergeJobPresetEnvironment(current = {}, preset = {}) {
  const environment = { ...current };
  const presetEnvironment = preset.environment ?? {};
  JOB_ENVIRONMENT_SECTIONS.forEach((section) => {
    const optionField = getJobEnvironmentOptionField(section.key);
    if (optionField && presetEnvironment[optionField]) {
      environment[optionField] = mergeJobValues(environment[optionField] ?? [], presetEnvironment[optionField]);
      environment[`${section.key}Enabled`] = true;
    }
  });
  JOB_ORGANIZATION_FIELDS.forEach((field) => {
    if (presetEnvironment[field.key]) {
      environment[field.key] = presetEnvironment[field.key];
    }
  });
  if (Object.prototype.hasOwnProperty.call(presetEnvironment, "psychosocialRelevant")) {
    environment.psychosocialRelevant = Boolean(presetEnvironment.psychosocialRelevant);
  }
  return environment;
}

function mergeJobPresetConditions(current = {}, preset = {}) {
  const conditions = { ...current, notes: { ...(current.notes ?? {}) } };
  const presetConditions = preset.conditions ?? {};
  JOB_CONDITION_TOGGLES.forEach((toggle) => {
    if (Object.prototype.hasOwnProperty.call(presetConditions, toggle.key)) {
      conditions[toggle.key] = Boolean(presetConditions[toggle.key]);
    }
  });
  JOB_CONDITION_CHOICE_BLOCKS.forEach((block) => {
    if (presetConditions[block.field]) {
      conditions[block.field] = mergeJobValues(conditions[block.field] ?? [], presetConditions[block.field]);
    }
  });
  if (presetConditions.purPoints) {
    conditions.purPoints = normalizeJobPurPointValues([...(conditions.purPoints ?? []), ...presetConditions.purPoints]);
  }
  if (presetConditions.loadWeights) {
    conditions.loadWeights = normalizeRiskAssessmentLoadWeights({
      ...(conditions.loadWeights || {}),
      ...presetConditions.loadWeights,
    });
  }
  return conditions;
}

function applyJobWorkProfilePreset(key = "") {
  const preset = getJobWorkProfilePreset(key);
  if (!preset) {
    return;
  }
  const environment = mergeJobPresetEnvironment(getJobEnvironmentDraftFromForm(), preset);
  const conditions = mergeJobPresetConditions(getJobConditionsDraftFromForm(), preset);
  renderJobEnvironmentSections(environment);
  renderJobConditionSections(conditions);
  setInlineMessage(jobFormFeedback, `Primijenjen brzi izbor: ${preset.label}.`, "success");
}

function normalizeJobSentence(text = "") {
  const sentence = String(text || "").replace(/\s+/g, " ").trim();
  if (!sentence) {
    return "";
  }
  return /[.!?]$/.test(sentence) ? sentence : `${sentence}.`;
}

function buildJobOrganizationSelectionSentence(value = "", title = getJobSentenceTitle()) {
  const normalized = String(value || "").trim().toLocaleLowerCase("hr");
  const sentences = {
    "jedna smjena": "Rad se obavlja u jednoj smjeni.",
    "dvije smjene": "Rad se organizira u dvije smjene prema rasporedu poslodavca.",
    "tri smjene": "Rad se organizira u tri smjene, uz poštivanje dnevnog i tjednog odmora.",
    "u smjenama": "Rad se obavlja u smjenama prema unaprijed utvrđenom rasporedu.",
    "puno radno vrijeme": "Radnik obavlja posao u punom radnom vremenu.",
    "terenski rad": "Terenski rad obavlja se prema nalogu poslodavca, uz prethodno dogovorene lokacije, rokove i odgovornosti.",
    "po pozivu": "Rad po pozivu organizira se samo kada su radniku unaprijed jasni zadatak, lokacija, vrijeme dolaska i odgovorna osoba.",
    "rad od kuće": "Rad od kuće moguć je kada su zadaci, komunikacija i očekivani rokovi jasno definirani.",
    "prekovremeno povremeno": "Prekovremeni rad može se pojaviti povremeno, prema potrebi posla i uz poštivanje propisanih ograničenja.",
    "prekovremeni rad po potrebi": "Prekovremeni rad može se organizirati samo po potrebi i u skladu s važećim pravilima.",
    "noćni rad": "Noćni rad može se pojaviti u razdoblju 22-06 h te ga je potrebno organizirati tako da se smanji umor i osigura odgovarajući odmor.",
    "bez noćnog rada": "Noćni rad nije predviđen za ovaj posao.",
    "radi sam": "Radnik može raditi samostalno, uz osiguranu komunikaciju i mogućnost pozivanja pomoći u slučaju potrebe.",
    "radi s grupom": "Rad se obavlja u grupi, uz jasnu podjelu zadataka, komunikaciju i koordinaciju radnika.",
    "radi sa strankama": "Rad uključuje komunikaciju sa strankama ili korisnicima te zahtijeva jasne upute, smiren pristup i kontrolu konfliktnih situacija.",
    "rad na traci": "Rad na traci zahtijeva usklađen ritam rada, stalnu pažnju i organizirane odmore radi smanjenja ponavljajućih opterećenja.",
    "brzi tempo rada": "Brži tempo rada pojavljuje se u pojedinim razdobljima te se mora pratiti opterećenje radnika i realnost rokova.",
    "ritam određen": "Ritam rada određen je procesom, nalogom ili tehnološkim zahtjevima te radnik mora imati jasne upute za sigurno postupanje.",
    "rotacijski raspored": "Rotacijski raspored rada planira se unaprijed kako bi radnik znao smjene, odmore i očekivane zadatke.",
    "normirani rad": "Normirani rad potrebno je organizirati tako da zadane norme ne ugrožavaju sigurno izvođenje posla.",
    "monotonija": "Monotonija se može pojaviti kod ponavljajućih zadataka te je potrebno omogućiti izmjenu aktivnosti ili kraće odmore.",
    "visoka odgovornost": "Posao uključuje povećanu odgovornost pa je potrebno osigurati jasne ovlasti, komunikaciju i nadzor nad kritičnim aktivnostima.",
  };
  return sentences[normalized] || `Za posao "${title}" evidentirana je organizacijska značajka: ${value}.`;
}

function buildJobOrganizationFieldSentence(field = {}, value = "") {
  const normalized = String(value || "").trim();
  if (!normalized) {
    return "";
  }
  const lower = normalized.toLocaleLowerCase("hr");
  switch (field.key) {
    case "workTimeMode":
      return `Način rada organiziran je kao ${normalized}.`;
    case "dailyDuration":
      return `Dnevno trajanje rada je ${normalized}.`;
    case "overtime":
      if (lower === "ne") return "Prekovremeni rad nije predviđen kao redovit dio posla.";
      if (lower === "povremeno") return "Prekovremeni rad može se pojaviti povremeno, prema potrebi posla i organizaciji poslodavca.";
      return "Prekovremeni rad je moguć uz prethodnu organizaciju i poštivanje važećih propisa.";
    case "nightWork":
      if (lower === "ne") return "Noćni rad u razdoblju 22-06 h nije predviđen.";
      if (lower === "povremeno") return "Noćni rad u razdoblju 22-06 h može se pojaviti povremeno.";
      return "Noćni rad u razdoblju 22-06 h predviđen je za ovaj posao.";
    case "breakRest":
      return lower === "30 minuta"
        ? "Odmor odnosno stanka traje 30 minuta."
        : `Odmor odnosno stanka koristi se ${normalized}.`;
    case "weeklyRest":
      return `Tjedni odmor koristi se ${normalized}.`;
    case "fieldWork":
      if (lower === "ne") return "Rad na terenu i službeni put nisu predviđeni kao redovit dio posla.";
      if (lower === "povremeno") return "Rad na terenu ili službeni put pojavljuju se povremeno, prema nalogu poslodavca.";
      return "Rad na terenu ili službeni put čest su dio organizacije posla.";
    case "remoteWork":
      if (lower === "ne") return "Rad od kuće nije predviđen za ovaj posao.";
      if (lower === "povremeno") return "Rad od kuće može se odobriti povremeno, kada priroda zadataka to dopušta.";
      return "Rad od kuće predviđen je kao dio organizacije posla.";
    case "workRhythm":
      return `Ritam rada je ${normalized}.`;
    case "monotony":
      if (lower === "ne") return "Monotonija nije izražena kao značajan čimbenik rada.";
      if (lower === "povremeno") return "Monotonija se može pojaviti povremeno kod ponavljajućih zadataka.";
      return "Monotonija je izražena i potrebno ju je uzeti u obzir pri organizaciji rada.";
    default:
      return `${field.label || "Organizacijski podatak"}: ${normalized}.`;
  }
}

function buildJobOrganizationSentences(selected = [], environment = {}) {
  return getJobOrganizationSentenceDefinitions(selected, environment)
    .map((item) => normalizeJobSentence(item.text))
    .filter(Boolean)
    .join("\n");
}

function getJobOrganizationSentenceDefinitions(selected = [], environment = {}) {
  const title = getJobSentenceTitle();
  const selectedValues = Array.from(new Set((selected ?? [])
    .map((value) => String(value || "").trim())
    .filter(Boolean)));
  const definitions = [
    ...selectedValues.map((value) => ({
      key: `selection:${value}`,
      label: value,
      text: buildJobOrganizationSelectionSentence(value, title),
    })),
    ...JOB_ORGANIZATION_FIELDS
      .map((field) => {
        const value = String(environment[field.key] || "").trim();
        return value
          ? {
            key: `field:${field.key}:${value}`,
            label: field.label,
            text: buildJobOrganizationFieldSentence(field, value),
          }
          : null;
      })
      .filter(Boolean),
    environment.psychosocialRelevant
      ? {
        key: "flag:psychosocialRelevant",
        label: "Psihosocijalni rizici",
        text: "Procjena psihosocijalnih rizika relevantna je za ovaj posao.",
      }
      : null,
  ].filter(Boolean);

  if (definitions.length === 0) {
    definitions.push({
      key: "base",
      label: "Organizacija rada",
      text: "Rad se organizira prema nalogu poslodavca.",
    });
  }

  definitions.push({
    key: "summary",
    label: "Planiranje rada",
    text: "Zadaci, rokovi, stanke, odmori i odgovornosti planiraju se tako da radnik može obaviti posao sigurno, bez nepotrebnog preopterećenja i uz jasne upute neposredno nadređene osobe.",
  });

  const seen = new Set();
  return definitions.filter((definition) => {
    const sentence = normalizeJobSentence(definition.text);
    if (!sentence || seen.has(sentence)) {
      return false;
    }
    seen.add(sentence);
    return true;
  });
}

function splitJobOrganizationTextRows(text = "") {
  return String(text || "")
    .split(/\n+/)
    .flatMap((part) => String(part || "").match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [])
    .map(normalizeJobSentence)
    .filter(Boolean);
}

function getJobOrganizationSentenceOverrides() {
  return new Map(
    Array.from(jobEnvironmentSections?.querySelectorAll("[data-job-organization-sentence]") ?? [])
      .map((textarea) => [
        String(textarea.dataset.jobOrganizationSentence || "").trim(),
        String(textarea.value || "").trim(),
      ])
      .filter(([key, value]) => key && value),
  );
}

function buildJobOrganizationSentenceRows(selected = [], environment = {}, options = {}) {
  const definitions = getJobOrganizationSentenceDefinitions(selected, environment);
  const sourceLines = splitJobOrganizationTextRows(options.sourceText || "");
  const overrides = options.preserveExisting === false
    ? new Map()
    : (options.overrides instanceof Map ? options.overrides : getJobOrganizationSentenceOverrides());
  const usedLines = [];
  const rows = definitions.map((definition, index) => {
    const fallback = normalizeJobSentence(definition.text);
    const value = overrides.get(definition.key) || sourceLines[index] || fallback;
    if (sourceLines[index]) {
      usedLines.push(index);
    }
    return {
      ...definition,
      text: value,
    };
  });

  sourceLines.forEach((line, index) => {
    if (!usedLines.includes(index) && !rows.some((row) => normalizeJobSentence(row.text) === line)) {
      rows.push({
        key: `custom:${index}`,
        label: `Rečenica ${rows.length + 1}`,
        text: line,
      });
    }
  });

  return rows;
}

function renderJobOrganizationSentenceRows(rows = []) {
  return `
    <div class="job-organization-sentence-list" data-job-organization-sentences>
      ${rows.map((row, index) => `
        <label class="job-organization-sentence-item">
          <span>${escapeHtml(row.label || `Rečenica ${index + 1}`)}</span>
          <textarea data-job-organization-sentence="${escapeHtml(row.key || `custom:${index}`)}" rows="1">${escapeHtml(normalizeJobSentence(row.text))}</textarea>
        </label>
      `).join("")}
    </div>
  `;
}

function renderJobPsychosocialPanel(environment = {}) {
  const selectedLevel = String(environment.psychosocialLevel || "").trim();
  const relevant = Boolean(environment.psychosocialRelevant || selectedLevel || environment.psychosocialText);
  return `
    <section class="job-psychosocial-panel ${relevant ? "is-enabled" : ""}">
      <div class="job-psychosocial-head">
        <label class="job-toggle-control">
          <input type="checkbox" data-job-environment-flag="psychosocialRelevant" ${relevant ? "checked" : ""} />
          <span class="job-toggle-track" aria-hidden="true"><span></span></span>
          <em>${relevant ? "Da" : "Ne"}</em>
        </label>
        <div>
          <strong>Procjena psihosocijalnih rizika</strong>
          <small>Tempo, odgovornost, smjene, monotoni rad, rad samostalno, rad sa strankama i opterećenje.</small>
        </div>
      </div>
      <div class="job-psychosocial-scale" aria-label="Razina psihosocijalnog rizika">
        ${JOB_PSYCHOSOCIAL_LEVELS.map((level) => `
          <button type="button"
            class="job-psychosocial-level is-${escapeHtml(level.tone)} ${selectedLevel === level.value ? "is-selected" : ""}"
            data-job-psychosocial-level="${escapeHtml(level.value)}">
            <span>${escapeHtml(level.marker)}</span>
            <strong>${escapeHtml(level.label)}</strong>
            <small>${escapeHtml(level.description)}</small>
          </button>
        `).join("")}
      </div>
      <label class="job-psychosocial-text">
        <span>Opis psihosocijalnih rizika i mjere</span>
        <textarea data-job-psychosocial-text rows="3" placeholder="npr. Rad se obavlja uz povremeni pritisak rokova; potrebno je jasno planirati zadatke, odmore i komunikaciju.">${escapeHtml(environment.psychosocialText || "")}</textarea>
      </label>
    </section>
  `;
}

function collectJobOrganizationSentenceText() {
  return Array.from(jobEnvironmentSections?.querySelectorAll("[data-job-organization-sentence]") ?? [])
    .map((textarea) => String(textarea.value || "").trim())
    .filter(Boolean)
    .join("\n");
}

function syncJobOrganizationHiddenText(card = null) {
  const root = card instanceof HTMLElement
    ? card
    : jobEnvironmentSections?.querySelector('[data-job-environment-card="organization"]');
  const hidden = root?.querySelector('[data-job-env-text="organization"]');
  if (hidden instanceof HTMLTextAreaElement) {
    hidden.value = collectJobOrganizationSentenceText();
  }
}

function syncJobOrganizationSentenceList(options = {}) {
  const card = jobEnvironmentSections?.querySelector('[data-job-environment-card="organization"]');
  if (!(card instanceof HTMLElement)) {
    return;
  }
  const list = card.querySelector("[data-job-organization-sentences]");
  if (!(list instanceof HTMLElement)) {
    return;
  }
  const selected = getSelectedJobEnvironmentOptions("organization");
  const draft = getJobEnvironmentDraftFromForm();
  const rows = buildJobOrganizationSentenceRows(selected, draft, {
    sourceText: options.sourceText || "",
    preserveExisting: options.preserveExisting,
  });
  list.innerHTML = rows.map((row, index) => `
    <label class="job-organization-sentence-item">
      <span>${escapeHtml(row.label || `Rečenica ${index + 1}`)}</span>
      <textarea data-job-organization-sentence="${escapeHtml(row.key || `custom:${index}`)}" rows="1">${escapeHtml(normalizeJobSentence(row.text))}</textarea>
    </label>
  `).join("");
  syncJobOrganizationHiddenText(card);
}

function buildJobEnvironmentSentence(sectionKey = "", selectedValues = [], environment = {}) {
  const title = getJobSentenceTitle();
  const selected = Array.from(new Set((selectedValues ?? []).map((value) => String(value || "").trim()).filter(Boolean)));
  const selectedList = formatJobSentenceList(selected);

  if (sectionKey === "machines") {
    const equipment = selectedList || "alat i opremu potrebnu za obavljanje posla";
    return `Radnik pri obavljanju posla "${title}" koristi ${equipment}. Sva sredstva rada moraju biti ispravna, pregledana prije uporabe i korištena prema uputama proizvođača, uz primjenu propisane osobne zaštitne opreme i postupaka za rad na siguran način.`;
  }

  if (sectionKey === "substances") {
    if (selected.some((value) => value.toLocaleLowerCase("hr").includes("nema značajnih"))) {
      return `Za posao "${title}" nisu predviđene značajne radne tvari u redovnom procesu rada. Ako radnik iznimno dođe u dodir s kemikalijama, sredstvima za čišćenje ili drugim tvarima, potrebno je primijeniti upute proizvođača, označenu ambalažu i odgovarajuće higijenske mjere.`;
    }
    const substances = selectedList || "radne tvari potrebne za obavljanje posla";
    return `Radnik tijekom obavljanja posla "${title}" rukuje ili može doći u dodir s tvarima kao što su ${substances}. Tvari se moraju koristiti u označenoj ambalaži, prema sigurnosno-tehničkim listovima i internim uputama, uz sprječavanje prolijevanja, udisanja i nepotrebnog kontakta s kožom.`;
  }

  if (sectionKey === "workplace") {
    const places = selectedList || "radnom prostoru poslodavca";
    return `Posao "${title}" obavlja se na mjestima rada kao što su ${places}. Radni prostor mora biti uredan, prohodan, dovoljno osvijetljen i organiziran tako da se smanji rizik od spoticanja, pada, neželjenog kontakta s opremom i drugih opasnosti koje proizlaze iz konkretnog mjesta rada.`;
  }

  if (sectionKey === "organization") {
    return buildJobOrganizationSentences(selected, environment);
  }

  return selectedList;
}

function syncJobEnvironmentTextarea(sectionKey = "", options = {}) {
  if (sectionKey === "organization") {
    syncJobOrganizationSentenceList({
      preserveExisting: options.preserveExisting,
      sourceText: options.sourceText || "",
    });
    return;
  }
  const textarea = jobEnvironmentSections?.querySelector(`[data-job-env-text="${sectionKey}"]`);
  if (!(textarea instanceof HTMLTextAreaElement)) {
    return;
  }
  const selected = getSelectedJobEnvironmentOptions(sectionKey);
  const draft = getJobEnvironmentDraftFromForm();
  const nextText = buildJobEnvironmentSentence(sectionKey, selected, draft);
  if (nextText || options.force) {
    textarea.value = nextText;
  }
}

function buildJobConditionToggleSentence(key = "") {
  const definition = JOB_CONDITION_TOGGLES.find((entry) => entry.key === key);
  if (!definition) {
    return "Za odabrani uvjet rada potrebno je opisati okolnosti, učestalost, trajanje izloženosti i mjere zaštite koje poslodavac mora provoditi.";
  }
  return `${definition.suggestion} U zapisniku je potrebno navesti kada se ovaj uvjet pojavljuje, koliko često utječe na radnika i koje organizacijske, tehničke ili osobne mjere zaštite se primjenjuju.`;
}

function buildJobConditionChoiceSentence(field = "", selectedValues = []) {
  const selected = Array.from(new Set((selectedValues ?? []).map((value) => String(value || "").trim()).filter(Boolean)));
  const selectedList = formatJobSentenceList(selected);
  if (!selectedList) {
    return "";
  }
  if (field === "bodyPositions") {
    return `Radnik tijekom rada najčešće zauzima sljedeće položaje ili izvodi aktivnosti: ${selectedList}. Posao je potrebno organizirati tako da se omogući izmjena položaja tijela, smanji dugotrajno statičko opterećenje i uvedu kratke pauze kada priroda posla to zahtijeva.`;
  }
  if (field === "importantFunctions") {
    return `Za sigurno obavljanje posla posebno su važne sljedeće funkcije radnika: ${selectedList}. Prije raspoređivanja na posao potrebno je osigurati da radnik može pouzdano obavljati navedene funkcije te da su upute, signalizacija i radni postupci jasni i razumljivi.`;
  }
  if (field === "workConditions") {
    return `Posao se može odvijati u uvjetima kao što su ${selectedList}. Za navedene uvjete potrebno je procijeniti razinu izloženosti, osigurati odgovarajuće tehničke i organizacijske mjere te radniku dati jasne upute o sigurnom postupanju.`;
  }
  return selectedList;
}

function syncJobConditionChoiceText(field = "", options = {}) {
  const block = jobConditionSections?.querySelector(`[data-job-condition-block="${field}"]`);
  const definition = JOB_CONDITION_CHOICE_BLOCKS.find((item) => item.field === field);
  if (!(block instanceof HTMLElement) || !definition) {
    return;
  }
  const selected = Array.from(block.querySelectorAll(`[data-job-condition-choice="${field}"].is-selected`))
    .map((button) => String(button.dataset.value || "").trim())
    .filter(Boolean);
  const toggle = block.querySelector(`[data-job-condition-block-enabled="${field}"]`);
  if (toggle instanceof HTMLInputElement) {
    toggle.checked = options.forceEnabled || selected.length > 0 || Boolean(block.querySelector(`[data-job-condition-text="${definition.textField}"]`)?.value?.trim());
    const label = toggle.closest(".job-toggle-control")?.querySelector("em");
    if (label) {
      label.textContent = toggle.checked ? "Da" : "Ne";
    }
  }
  block.classList.toggle("is-enabled", Boolean(toggle?.checked || selected.length));
  const textarea = block.querySelector(`[data-job-condition-text="${definition.textField}"]`);
  if (textarea instanceof HTMLTextAreaElement) {
    const nextText = buildJobConditionChoiceSentence(field, selected);
    if (nextText || options.force) {
      textarea.value = nextText;
    }
  }
}

function getJobNexAiText(kind = "description") {
  const title = String(jobTitleInput?.value || "Odabrani posao").trim() || "Odabrani posao";
  const environment = getJobEnvironmentDraftFromForm();
  const conditions = getJobConditionsDraftFromForm();
  const selectedWorkplaces = environment.workplaceOptions?.length ? environment.workplaceOptions.join(", ") : "radnom prostoru poslodavca";
  if (kind === "machines") {
    return applyJobAiInstructionToText(`Radnik rukuje standardnim alatima i opremom potrebnom za posao "${title}". Oprema se koristi prema uputama proizvođača, uz prethodnu vizualnu provjeru ispravnosti i primjenu propisane osobne zaštitne opreme.`, kind);
  }
  if (kind === "substances") {
    return applyJobAiInstructionToText(`Radnik može povremeno doći u dodir s radnim tvarima potrebnima za obavljanje posla. Tvari se koriste u označenoj ambalaži, uz primjenu sigurnosno-tehničkih listova, higijenskih mjera i odgovarajuće OZO.`, kind);
  }
  if (kind === "workplace") {
    return applyJobAiInstructionToText(`Posao se obavlja na lokacijama: ${selectedWorkplaces}. Radni prostor mora biti prohodan, osvijetljen, organiziran tako da se smanji rizik od pada, spoticanja i neželjenog događaja.`, kind);
  }
  if (kind === "organization") {
    return applyJobAiInstructionToText(buildJobOrganizationSentences(environment.organizationOptions ?? [], environment), kind);
  }
  if (kind.startsWith("condition:")) {
    const key = kind.replace("condition:", "");
    return applyJobAiInstructionToText(buildJobConditionToggleSentence(key), kind);
  }
  const conditionSummary = [
    ...conditions.bodyPositions,
    ...conditions.importantFunctions,
    ...conditions.workConditions,
  ].slice(0, 8).join(", ");
  return applyJobAiInstructionToText(`${title} obuhvaća obavljanje redovnih radnih zadataka prema uputama poslodavca, pravilima struke i zahtjevima zaštite na radu. Posao se izvodi u ${selectedWorkplaces}, uz korištenje potrebne opreme, alata i dokumentacije. Radnik mora biti osposobljen za siguran rad, upoznat s opasnostima i obvezan primjenjivati propisane mjere zaštite${conditionSummary ? `, posebno u dijelu: ${conditionSummary}` : ""}.`, "description");
}

function syncJobEditorModal() {
  const isOpen = Boolean(state.jobEditorOpen);
  if (jobEditorBackdrop) {
    jobEditorBackdrop.hidden = !isOpen;
  }
  if (jobEditorPanel) {
    jobEditorPanel.hidden = !isOpen;
    jobEditorPanel.setAttribute("aria-hidden", isOpen ? "false" : "true");
  }
}

function setJobEditorOpen(open) {
  state.jobEditorOpen = Boolean(open);
  syncJobEditorModal();
  if (open) {
    requestAnimationFrame(() => {
      jobTitleInput?.focus({ preventScroll: true });
    });
  }
}

function syncJobSheets() {
  const activeSheet = normalizeJobSheet(state.jobEditorSheet);
  state.jobEditorSheet = activeSheet;
  jobSheetButtons.forEach((button) => {
    const isActive = button.dataset.jobSheet === activeSheet;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });
  jobSheetPanels.forEach((panel) => {
    const isActive = panel.dataset.jobSheetPanel === activeSheet;
    panel.hidden = !isActive;
    panel.classList.toggle("is-active", isActive);
  });
}

function renderJobEnvironmentSections(environment = {}) {
  if (!jobEnvironmentSections) {
    return;
  }
  const canUseNexAi = getCanUseJobNexAi();
  jobEnvironmentSections.replaceChildren(...JOB_ENVIRONMENT_SECTIONS.map((section) => {
    const enabled = Boolean(environment[`${section.key}Enabled`]);
    const textValue = String(environment[`${section.key}Text`] ?? "").trim();
    const optionField = getJobEnvironmentOptionField(section.key);
    const selectedOptions = new Set(environment[optionField] ?? []);
    const resolvedTextValue = textValue || (enabled || selectedOptions.size ? buildJobEnvironmentSentence(section.key, [...selectedOptions], environment) : "");
    const organizationRows = section.key === "organization"
      ? buildJobOrganizationSentenceRows([...selectedOptions], environment, { sourceText: resolvedTextValue, preserveExisting: false })
      : [];
    const article = document.createElement("article");
    article.className = `job-smart-card ${enabled ? "is-enabled" : ""}`;
    article.dataset.jobEnvironmentCard = section.key;
    const chips = section.suggestions.map((suggestion) => `
      <button type="button" class="${selectedOptions.has(suggestion) ? "is-selected" : ""}" data-job-env-suggestion="${escapeHtml(section.key)}" data-value="${escapeHtml(suggestion)}">${escapeHtml(suggestion)}</button>
    `).join("");
    const organizationFields = section.key === "organization"
      ? `<div class="job-organization-panel">
          <section class="job-organization-stage">
            <div class="job-organization-stage-head">
              <div>
                <strong>Brzi profil rada</strong>
                <small>Odaberi najbliži scenarij pa po potrebi korigiraj detalje ispod.</small>
              </div>
            </div>
            <div class="job-work-profile-presets" aria-label="Brzi izbor načina rada">
              ${JOB_WORK_PROFILE_PRESETS.map((preset) => `
                <button type="button" data-job-work-preset="${escapeHtml(preset.key)}">
                  <strong>${escapeHtml(preset.label)}</strong>
                  <span>${escapeHtml(preset.description)}</span>
                </button>
              `).join("")}
            </div>
          </section>
          <section class="job-organization-stage">
            <div class="job-organization-stage-head">
              <div>
                <strong>Brzi odabiri organizacije</strong>
                <small>Ovi odabiri slažu rečenice koje se prenose u opis posla i uputnicu.</small>
              </div>
            </div>
            <div class="job-suggestion-row">${chips}</div>
          </section>
          <div class="job-organization-field-groups">
            ${JOB_ORGANIZATION_FIELD_GROUPS.map((group) => `
              <section class="job-organization-field-group">
                <div>
                  <strong>${escapeHtml(group.title)}</strong>
                  <small>${escapeHtml(group.helper)}</small>
                </div>
                <div class="job-organization-grid">
                  ${group.fields.map((fieldKey) => {
                    const field = JOB_ORGANIZATION_FIELDS.find((entry) => entry.key === fieldKey);
                    return field ? `
                      <label>
                        <span>${escapeHtml(field.label)}</span>
                        <select data-job-organization-field="${escapeHtml(field.key)}">${renderJobPlainOptions(field.options, environment[field.key] || "")}</select>
                      </label>
                    ` : "";
                  }).join("")}
                </div>
              </section>
            `).join("")}
          </div>
          ${renderJobPsychosocialPanel(environment)}
        </div>`
      : "";
    article.innerHTML = `
      <div class="job-smart-card-head">
        <label class="job-toggle-control">
          <input type="checkbox" data-job-env-enabled="${escapeHtml(section.key)}" ${enabled ? "checked" : ""} />
          <span class="job-toggle-track" aria-hidden="true"><span></span></span>
          <em>${enabled ? "Da" : "Ne"}</em>
        </label>
        <div>
          <strong>${escapeHtml(section.title)}</strong>
          <small>${escapeHtml(section.helper)}</small>
        </div>
        <div class="job-nexai-actions">
          <button type="button" class="ghost-button jobs-nexai-button" data-job-nexai="${escapeHtml(section.key)}" ${canUseNexAi ? "" : "disabled"}>NexAI</button>
        </div>
      </div>
      ${section.key === "organization" ? "" : `<div class="job-suggestion-row">${chips}</div>`}
      ${organizationFields}
      ${section.key === "organization"
        ? `<textarea class="job-organization-hidden-text" data-job-env-text="organization" hidden aria-hidden="true">${escapeHtml(resolvedTextValue)}</textarea>${renderJobOrganizationSentenceRows(organizationRows)}`
        : `<textarea data-job-env-text="${escapeHtml(section.key)}" rows="4" placeholder="${escapeHtml(section.placeholder)}">${escapeHtml(resolvedTextValue)}</textarea>`}
    `;
    return article;
  }));
}

function renderJobConditionSections(conditions = {}) {
  if (!jobConditionSections) {
    return;
  }
  const canUseNexAi = getCanUseJobNexAi();
  const notes = conditions.notes ?? {};
  const groupedToggles = JOB_CONDITION_TOGGLES.reduce((groups, item) => {
    if (!groups.has(item.group)) {
      groups.set(item.group, []);
    }
    groups.get(item.group).push(item);
    return groups;
  }, new Map());
  const togglePanels = [...groupedToggles.entries()].map(([group, items]) => {
    const article = document.createElement("article");
    article.className = "job-condition-card";
    article.innerHTML = `
      <div class="job-condition-card-head">
        <strong>${escapeHtml(group)}</strong>
        <span>${items.filter((item) => Boolean(conditions[item.key])).length}/${items.length}</span>
      </div>
      <div class="job-condition-toggle-list">
        ${items.map((item) => `
          <div class="job-condition-toggle ${conditions[item.key] ? "is-enabled" : ""}" data-job-condition-card="${escapeHtml(item.key)}">
            <label class="job-toggle-control">
              <input type="checkbox" data-job-condition-flag="${escapeHtml(item.key)}" ${conditions[item.key] ? "checked" : ""} />
              <span class="job-toggle-track" aria-hidden="true"><span></span></span>
              <em>${conditions[item.key] ? "Da" : "Ne"}</em>
            </label>
            <div class="job-condition-toggle-copy">
              <strong>${escapeHtml(item.label)}</strong>
              <small>${escapeHtml(item.suggestion)}</small>
              <textarea data-job-condition-note="${escapeHtml(item.key)}" rows="2" placeholder="Tekst za ovaj uvjet rada...">${escapeHtml(notes[item.key] || (conditions[item.key] ? buildJobConditionToggleSentence(item.key) : ""))}</textarea>
            </div>
            <div class="job-nexai-actions">
              <button type="button" class="ghost-button jobs-nexai-button" data-job-nexai="condition:${escapeHtml(item.key)}" ${canUseNexAi ? "" : "disabled"}>NexAI</button>
            </div>
          </div>
        `).join("")}
      </div>
    `;
    return article;
  });
  const selectionPanel = document.createElement("article");
  selectionPanel.className = "job-condition-card is-wide";
  selectionPanel.innerHTML = `
    <div class="job-condition-card-head">
      <strong>Organizacija posla</strong>
      <span>položaj, funkcije, uvjeti</span>
    </div>
    <div class="job-pur-panel">
      <div class="job-pur-panel-head">
        <div>
          <strong>Posebni uvjeti rada (PUR)</strong>
          <small>Točke prema Pravilniku o poslovima s posebnim uvjetima rada. Odabir se prenosi u procjenu rizika i uputnicu.</small>
        </div>
        <span>${escapeHtml(getJobPurPointSummary(conditions.purPoints ?? []))}</span>
      </div>
      ${renderJobPurPointPicker(conditions.purPoints ?? [], "data-job-pur-point")}
    </div>
    ${JOB_CONDITION_CHOICE_BLOCKS.map((block) => renderJobMultiChoiceBlock(
      block.field,
      block.label,
      block.options,
      conditions[block.field] ?? [],
      block.textField,
      conditions[block.textField] || "",
      block.helper,
      block.icon,
      block.tone,
      conditions.loadWeights || {},
    )).join("")}
  `;
  jobConditionSections.replaceChildren(...togglePanels, selectionPanel);
}

function renderJobMultiChoiceBlock(field, label, options, selectedValues = [], textField, textValue = "", helper = "", icon = "note", tone = "slate", loadWeights = {}) {
  const selected = new Set(selectedValues);
  const enabled = selected.size > 0 || Boolean(String(textValue || "").trim());
  const resolvedTextValue = String(textValue || "").trim() || (selected.size ? buildJobConditionChoiceSentence(field, [...selected]) : "");
  return `
    <div class="job-multichoice-block is-${escapeHtml(tone)} ${enabled ? "is-enabled" : ""}" data-job-condition-block="${escapeHtml(field)}">
      <div class="job-multichoice-head">
        <label class="job-toggle-control">
          <input type="checkbox" data-job-condition-block-enabled="${escapeHtml(field)}" ${enabled ? "checked" : ""} />
          <span class="job-toggle-track" aria-hidden="true"><span></span></span>
          <em>${enabled ? "Da" : "Ne"}</em>
        </label>
        <span class="job-multichoice-icon" aria-hidden="true">${renderRiskAssessmentRiskIcon(icon)}</span>
        <div>
          <strong>${escapeHtml(label)}</strong>
          <small>${escapeHtml(helper)}</small>
        </div>
      </div>
      <div class="job-suggestion-row">
        ${options.map((option) => `
          <button type="button" class="${selected.has(option) ? "is-selected" : ""}" data-job-condition-choice="${escapeHtml(field)}" data-value="${escapeHtml(option)}">${escapeHtml(option)}</button>
        `).join("")}
      </div>
      <textarea data-job-condition-text="${escapeHtml(textField)}" rows="2" placeholder="Dodatni opis...">${escapeHtml(resolvedTextValue)}</textarea>
      ${field === "bodyPositions" ? renderJobLoadWeightControls([...selected], loadWeights) : ""}
    </div>
  `;
}

function renderJobHazardCatalog() {
  if (!jobHazardCatalog) {
    return;
  }
  const query = String(jobHazardCatalogSearch?.value || "").trim().toLowerCase();
  const selectedKeys = new Set(jobHazardDrafts.map((item) => `${item.catalogCode}::${item.catalogLabel}`));
  const rows = getJobHazardCatalogRows().filter((row) => {
    if (!query) {
      return true;
    }
    return [row.category, row.group, row.code, row.hazard, row.measures].join(" ").toLowerCase().includes(query);
  }).slice(0, 120);
  if (rows.length === 0) {
    const empty = document.createElement("p");
    empty.className = "inline-help";
    empty.textContent = "Nema stavki za odabranu pretragu.";
    jobHazardCatalog.replaceChildren(empty);
    return;
  }
  jobHazardCatalog.replaceChildren(...rows.map((row) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "job-hazard-catalog-item";
    const key = `${row.code || ""}::${row.hazard || ""}`;
    button.classList.toggle("is-selected", selectedKeys.has(key));
    button.dataset.jobHazardAdd = key;
    button.innerHTML = `
      <span>${escapeHtml(row.code || "-")}</span>
      <strong>${escapeHtml(row.hazard || "Opasnost")}</strong>
      <small>${escapeHtml(row.group || row.category || "Katalog")}</small>
    `;
    return button;
  }));
}

function getRiskAssessmentOptionLabel(options = [], value = "", fallback = "-") {
  const option = options.find((entry) => String(entry.value) === String(value ?? ""));
  return option?.label || fallback;
}

function calculateJobHazardRiskLevel(probability = "", consequence = "") {
  const probabilityKey = String(probability || "").trim();
  const consequenceKey = String(consequence || "").trim();
  const matrix = {
    mv: { "mš": "Mali rizik", "sš": "Mali rizik", "iš": "Srednji rizik" },
    v: { "mš": "Mali rizik", "sš": "Srednji rizik", "iš": "Veliki rizik" },
    vv: { "mš": "Srednji rizik", "sš": "Veliki rizik", "iš": "Veliki rizik" },
  };
  return matrix[probabilityKey]?.[consequenceKey] || "";
}

function getJobHazardRiskTone(value = "") {
  const normalized = String(value || "").toLocaleLowerCase("hr");
  if (normalized.includes("velik")) {
    return "high";
  }
  if (normalized.includes("sred")) {
    return "medium";
  }
  if (normalized.includes("mal")) {
    return "low";
  }
  return "neutral";
}

function renderJobSelectedHazards() {
  if (!jobSelectedHazards) {
    return;
  }
  if (jobSelectedHazardCount) {
    jobSelectedHazardCount.textContent = `${jobHazardDrafts.length} stavki`;
  }
  if (jobHazardDrafts.length === 0) {
    const empty = document.createElement("p");
    empty.className = "inline-help";
    empty.textContent = "Dodaj opasnost iz kataloga lijevo. Svaka stavka dobiva vlastitu karticu procjene.";
    jobSelectedHazards.replaceChildren(empty);
    return;
  }
  jobSelectedHazards.replaceChildren(...jobHazardDrafts.map((hazard, index) => {
    const article = document.createElement("article");
    const calculatedRiskLevel = calculateJobHazardRiskLevel(hazard.probability, hazard.consequence);
    if (calculatedRiskLevel) {
      hazard.riskLevel = calculatedRiskLevel;
    }
    const riskTone = getJobHazardRiskTone(hazard.riskLevel);
    const riskType = getRiskAssessmentRiskType(hazard);
    const riskScore = getRiskAssessmentRiskScoreValue(hazard);
    article.className = `job-selected-hazard-card is-${riskTone}`;
    article.dataset.jobHazardIndex = String(index);
    const riskLabel = String(hazard.riskLevel || "Rizik nije određen").trim();
    const classificationText = [hazard.category, hazard.group].filter(Boolean).join(" / ");
    const unwantedEventValue = hazard.unwantedEvent || "";
    const measuresValue = hazard.measures || "";
    article.innerHTML = `
      <div class="job-selected-hazard-head">
        <div class="job-selected-hazard-title">
          <div class="job-hazard-title-row">
            <input class="job-hazard-code" data-job-hazard-field="catalogCode" value="${escapeHtml(hazard.catalogCode || "")}" placeholder="1.2" aria-label="Broj stavke opasnosti" />
            <input class="job-hazard-title-input" data-job-hazard-field="catalogLabel" value="${escapeHtml(hazard.catalogLabel || "Opasnost")}" placeholder="Naziv opasnosti, štetnosti ili napora" aria-label="Naziv stavke opasnosti" />
          </div>
          <div class="job-hazard-meta-row">
            <span class="job-hazard-type-pill is-${escapeHtml(riskType.value)}">${escapeHtml(riskType.label)}</span>
            <span>${escapeHtml(classificationText || "Ručno dodana stavka")}</span>
          </div>
        </div>
        <div class="job-selected-hazard-actions">
          <button type="button" class="job-hazard-remove-button" data-job-hazard-remove="${index}" aria-label="Ukloni opasnost">${renderRiskAssessmentRiskIcon("close")}</button>
        </div>
      </div>
      <div class="job-hazard-body">
        <section class="job-hazard-assessment-panel">
          <div class="job-hazard-panel-title">
            <span class="job-hazard-panel-icon">${renderRiskAssessmentRiskIcon("shield")}</span>
            <strong>Procjena rizika</strong>
          </div>
          <div class="job-hazard-risk-grid">
            <label class="job-hazard-score-panel">
              <span>Vjerojatnost <small aria-hidden="true">i</small></span>
              <div class="job-hazard-select-shell is-${riskTone}">
                <i aria-hidden="true"></i>
                <select data-job-hazard-field="probability">${renderRiskAssessmentCompactOptions(RISK_ASSESSMENT_PROBABILITY_OPTIONS, hazard.probability || "")}</select>
              </div>
            </label>
            <label class="job-hazard-score-panel">
              <span>Posljedica <small aria-hidden="true">i</small></span>
              <div class="job-hazard-select-shell is-${riskTone}">
                <i aria-hidden="true"></i>
                <select data-job-hazard-field="consequence">${renderRiskAssessmentCompactOptions(RISK_ASSESSMENT_CONSEQUENCE_OPTIONS, hazard.consequence || "")}</select>
              </div>
            </label>
            <section class="job-hazard-score-panel">
              <span>Rizik</span>
              <output class="job-risk-output is-${riskTone}">
                <i aria-hidden="true"></i>
                <strong>${escapeHtml(riskLabel)}</strong>
                ${riskScore ? `<em>${escapeHtml(riskScore)}</em>` : ""}
              </output>
            </section>
          </div>
        </section>
        <div class="job-hazard-detail-grid">
          <section class="job-hazard-large-field">
            <div>
              <span class="job-hazard-panel-icon">${renderRiskAssessmentRiskIcon("note")}</span>
              <span>
                <strong>Poslovi / napomena</strong>
                <small>Upiši kod kojeg zadatka se stavka pojavljuje i koga obuhvaća.</small>
              </span>
            </div>
            <textarea data-job-hazard-field="unwantedEvent" rows="4" placeholder="Unesite poslove i dodatne napomene...">${escapeHtml(unwantedEventValue)}</textarea>
            <small class="job-hazard-character-count">${escapeHtml(String(getRiskAssessmentTextareaCount(unwantedEventValue)))} / 1000</small>
          </section>
          <section class="job-hazard-large-field">
            <div>
              <span class="job-hazard-panel-icon">${renderRiskAssessmentRiskIcon("shield")}</span>
              <span>
                <strong>Mjere za uklanjanje/smanjivanje opasnosti</strong>
                <small>Navedi tehničke, organizacijske, OZO, osposobljavanje i nadzor.</small>
              </span>
            </div>
            <textarea data-job-hazard-field="measures" rows="4" placeholder="Unesite pravila, mjere i aktivnosti...">${escapeHtml(measuresValue)}</textarea>
            <small class="job-hazard-character-count">${escapeHtml(String(getRiskAssessmentTextareaCount(measuresValue)))} / 1000</small>
          </section>
        </div>
      </div>
    `;
    return article;
  }));
}

function getJobPpeCatalogSearchText(item = {}) {
  return normalizeRiskAssessmentPpeSearchValue([
    item.name,
    item.category,
    item.bodyPart,
    item.norm,
    item.standardCode,
    item.description,
    item.sourceRef,
  ].join(" "));
}

function getJobSelectedPpeCatalogKeys() {
  return new Set((jobPpeDrafts ?? [])
    .map((item) => getRiskAssessmentPpeCatalogKey(item))
    .filter(Boolean));
}

function renderJobPpeCatalog() {
  if (!jobPpeCatalog) {
    return;
  }
  const query = normalizeRiskAssessmentPpeSearchValue(jobPpeSearchInput?.value || "");
  const selectedKeys = getJobSelectedPpeCatalogKeys();
  const items = getRiskAssessmentPpeCatalog()
    .filter((item) => !query || getJobPpeCatalogSearchText(item).includes(query))
    .slice(0, 140);

  if (items.length === 0) {
    const empty = document.createElement("p");
    empty.className = "inline-help";
    empty.textContent = "Nema OZO stavki za odabranu pretragu.";
    jobPpeCatalog.replaceChildren(empty);
    return;
  }

  jobPpeCatalog.replaceChildren(...items.map((item) => {
    const button = document.createElement("button");
    const key = getRiskAssessmentPpeCatalogKey(item);
    const isSelected = selectedKeys.has(key);
    const iconUrl = item.iconUrl || RISK_PPE_CATEGORY_ICONS[item.bodyPart] || RISK_PPE_CATEGORY_ICONS.other || "";
    button.type = "button";
    button.className = `job-ppe-catalog-item${isSelected ? " is-selected" : ""}`;
    button.dataset.jobPpeAdd = String(item.id || "");
    button.setAttribute("aria-pressed", isSelected ? "true" : "false");
    button.innerHTML = `
      <span class="job-ppe-catalog-icon"><img src="${escapeHtml(iconUrl)}" alt="" loading="lazy" /></span>
      <span class="job-ppe-catalog-copy">
        <strong>${escapeHtml(item.name || "OZO")}</strong>
        <small>${escapeHtml(item.norm || item.standardCode || "Norma nije upisana")}</small>
        <em>${escapeHtml(item.category || "OZO")}</em>
      </span>
      <b>${isSelected ? "Dodano" : "+"}</b>
    `;
    return button;
  }));
}

function renderJobSelectedPpe() {
  if (!jobSelectedPpe) {
    return;
  }
  if (jobSelectedPpeCount) {
    jobSelectedPpeCount.textContent = `${jobPpeDrafts.length} ${jobPpeDrafts.length === 1 ? "stavka" : "stavki"}`;
  }

  if (!jobPpeDrafts.length) {
    const empty = document.createElement("p");
    empty.className = "inline-help";
    empty.textContent = "Odaberi OZO iz kataloga lijevo. Stavke se spremaju u Jobs i preuzimaju u procjenu rizika.";
    jobSelectedPpe.replaceChildren(empty);
    return;
  }

  jobSelectedPpe.replaceChildren(...jobPpeDrafts.map((ppe, index) => {
    const normalized = normalizeRiskPpeCatalogItem(ppe);
    const iconUrl = normalized.iconUrl || RISK_PPE_CATEGORY_ICONS[normalized.bodyPart] || RISK_PPE_CATEGORY_ICONS.other || "";
    const article = document.createElement("article");
    article.className = "job-selected-ppe-card";
    article.dataset.jobPpeIndex = String(index);
    article.innerHTML = `
      <span class="job-selected-ppe-icon"><img src="${escapeHtml(iconUrl)}" alt="" loading="lazy" /></span>
      <div class="job-selected-ppe-fields">
        <label>
          <span>Naziv</span>
          <input data-job-ppe-field="name" value="${escapeHtml(ppe.name || "")}" placeholder="Naziv OZO" />
        </label>
        <label>
          <span>Norma</span>
          <input data-job-ppe-field="norm" value="${escapeHtml(ppe.norm || "")}" placeholder="HRN EN..." />
        </label>
        <label class="field-span-full">
          <span>Primjena</span>
          <textarea data-job-ppe-field="description" rows="2" placeholder="Za koju opasnost, aktivnost ili radno mjesto se koristi.">${escapeHtml(ppe.description || "")}</textarea>
        </label>
        <label class="job-selected-ppe-required">
          <input type="checkbox" data-job-ppe-field="required" ${ppe.required === false ? "" : "checked"} />
          <span>Obvezna OZO</span>
        </label>
      </div>
      <button type="button" class="job-ppe-remove-button" data-job-ppe-remove="${index}" aria-label="Ukloni OZO">${renderRiskAssessmentRiskIcon("close")}</button>
    `;
    return article;
  }));
}

function addJobPpeFromCatalog(catalogId = "") {
  const source = getRiskAssessmentPpeCatalogItem(catalogId);
  if (!source) {
    return;
  }
  const candidate = createRiskAssessmentPpeDraft({
    ...source,
    catalogId: source.id,
    id: crypto.randomUUID(),
    required: true,
  });
  const key = getRiskAssessmentPpeCatalogKey(candidate);
  const selected = getJobSelectedPpeCatalogKeys();
  if (key && selected.has(key)) {
    return;
  }
  jobPpeDrafts = [...jobPpeDrafts, candidate];
  renderJobPpeCatalog();
  renderJobSelectedPpe();
  syncJobFormAccess();
}

function updateJobPpeDraft(index = -1, field = "", value = "") {
  if (!Number.isInteger(index) || index < 0 || !jobPpeDrafts[index]) {
    return;
  }
  const next = [...jobPpeDrafts];
  next[index] = {
    ...next[index],
    [field]: field === "required" ? Boolean(value) : String(value || ""),
  };
  if (field === "required") {
    next[index].mandatory = Boolean(value);
  }
  jobPpeDrafts = next;
}

function getJobEnvironmentDraftFromForm() {
  const environment = {};
  JOB_ENVIRONMENT_SECTIONS.forEach((section) => {
    environment[`${section.key}Enabled`] = Boolean(jobEnvironmentSections?.querySelector(`[data-job-env-enabled="${section.key}"]`)?.checked);
    environment[`${section.key}Text`] = section.key === "organization"
      ? (collectJobOrganizationSentenceText() || String(jobEnvironmentSections?.querySelector('[data-job-env-text="organization"]')?.value || "").trim())
      : String(jobEnvironmentSections?.querySelector(`[data-job-env-text="${section.key}"]`)?.value || "").trim();
    const optionField = getJobEnvironmentOptionField(section.key);
    if (optionField) {
      environment[optionField] = getSelectedJobEnvironmentOptions(section.key);
    }
  });
  JOB_ORGANIZATION_FIELDS.forEach((field) => {
    environment[field.key] = String(jobEnvironmentSections?.querySelector(`[data-job-organization-field="${field.key}"]`)?.value || "").trim();
  });
  environment.psychosocialRelevant = Boolean(jobEnvironmentSections?.querySelector('[data-job-environment-flag="psychosocialRelevant"]')?.checked);
  environment.psychosocialLevel = String(jobEnvironmentSections?.querySelector("[data-job-psychosocial-level].is-selected")?.dataset.jobPsychosocialLevel || "").trim();
  environment.psychosocialText = String(jobEnvironmentSections?.querySelector("[data-job-psychosocial-text]")?.value || "").trim();
  return environment;
}

function getJobConditionsDraftFromForm() {
  const notes = {};
  const conditions = {
    notes,
    bodyPositions: [],
    importantFunctions: [],
    workConditions: [],
    loadWeights: normalizeRiskAssessmentLoadWeights({}),
    purPoints: [],
    bodyText: "",
    functionsText: "",
    conditionsText: "",
  };
  JOB_CONDITION_TOGGLES.forEach((item) => {
    conditions[item.key] = Boolean(jobConditionSections?.querySelector(`[data-job-condition-flag="${item.key}"]`)?.checked);
    const note = String(jobConditionSections?.querySelector(`[data-job-condition-note="${item.key}"]`)?.value || "").trim();
    if (note) {
      notes[item.key] = note;
    }
  });
  ["bodyPositions", "importantFunctions", "workConditions"].forEach((field) => {
    conditions[field] = Array.from(jobConditionSections?.querySelectorAll(`[data-job-condition-choice="${field}"].is-selected`) ?? [])
      .map((button) => String(button.dataset.value || "").trim())
      .filter(Boolean);
  });
  ["bodyText", "functionsText", "conditionsText"].forEach((field) => {
    conditions[field] = String(jobConditionSections?.querySelector(`[data-job-condition-text="${field}"]`)?.value || "").trim();
  });
  const loadWeights = {};
  jobConditionSections?.querySelectorAll("[data-job-load-weight]").forEach((select) => {
    if (select instanceof HTMLSelectElement) {
      loadWeights[select.dataset.jobLoadWeight || ""] = select.value;
    }
  });
  conditions.loadWeights = normalizeRiskAssessmentLoadWeights(loadWeights);
  const activeBodyPositions = new Set(conditions.bodyPositions);
  RISK_ASSESSMENT_LOAD_WEIGHT_FIELDS.forEach((item) => {
    if (!activeBodyPositions.has(item.option)) {
      conditions.loadWeights[item.key] = "";
    }
  });
  conditions.purPoints = normalizeJobPurPointValues(Array.from(jobConditionSections?.querySelectorAll("[data-job-pur-point].is-selected") ?? [])
    .map((button) => String(button.dataset.jobPurPoint || "").trim()));
  return conditions;
}

function buildJobPayload() {
  return {
    title: jobTitleInput?.value || "",
    status: jobStatusInput?.value || "draft",
    description: jobDescriptionInput?.value || "",
    environment: getJobEnvironmentDraftFromForm(),
    conditions: getJobConditionsDraftFromForm(),
    aiInstructions: getJobAiInstructionsDraft(),
    hazards: jobHazardDrafts,
    ppeItems: jobPpeDrafts.map((item) => createRiskAssessmentPpeDraft(item)),
  };
}

function syncJobFormAccess() {
  const canManage = getCanManageJobs();
  const canUseNexAi = getCanUseJobNexAi();
  jobForm?.querySelectorAll("input, textarea, select").forEach((field) => {
    field.disabled = !canManage;
  });
  jobForm?.querySelectorAll("[data-job-env-suggestion], [data-job-work-preset], [data-job-psychosocial-level], [data-job-condition-choice], [data-job-pur-point], [data-job-hazard-add], [data-job-hazard-remove], [data-job-ppe-add], [data-job-ppe-remove]").forEach((button) => {
    button.disabled = !canManage;
  });
  jobForm?.querySelectorAll(".jobs-nexai-button").forEach((button) => {
    button.disabled = !canUseNexAi || !canManage;
  });
  if (jobSubmitButton) {
    jobSubmitButton.hidden = !canManage;
    jobSubmitButton.disabled = !canManage;
  }
  if (jobResetButton) {
    jobResetButton.hidden = !canManage;
    jobResetButton.disabled = !canManage;
  }
}

function hydrateJobForm(item = {}) {
  const draft = cloneJobDraft(item);
  if (jobIdInput) jobIdInput.value = draft.id || "";
  if (jobTitleInput) jobTitleInput.value = draft.title || "";
  if (jobStatusInput) replaceSelectOptionsIfChanged(jobStatusInput, JOB_STATUS_OPTIONS, draft.status || "draft");
  if (jobDescriptionInput) jobDescriptionInput.value = draft.description || "";
  jobHazardDrafts = (draft.hazards ?? []).map((hazard) => createJobHazardDraft(hazard));
  jobPpeDrafts = (draft.ppeItems ?? []).map((item) => createRiskAssessmentPpeDraft(item));
  if (jobPpeSearchInput) {
    jobPpeSearchInput.value = "";
  }
  renderJobEnvironmentSections(draft.environment ?? {});
  renderJobConditionSections(draft.conditions ?? {});
  renderJobHazardCatalog();
  renderJobSelectedHazards();
  renderJobPpeCatalog();
  renderJobSelectedPpe();
  syncJobCopySourceOptions(draft.id || "");
  if (jobEditorTitle) {
    jobEditorTitle.textContent = draft.id ? (draft.title || "Uredi posao") : "Novi posao";
  }
  if (jobEditorMeta) {
    const hazardText = `${jobHazardDrafts.length} opasnosti`;
    const ppeText = `${jobPpeDrafts.length} OZO`;
    jobEditorMeta.textContent = draft.id ? `${getJobStatusOption(draft.status).label} · ${hazardText} · ${ppeText}` : "Osnovni podaci, radno okruženje, uvjeti rada, opasnosti i OZO.";
  }
  if (jobDeleteButton) {
    jobDeleteButton.hidden = !draft.id || !getCanManageJobs();
    jobDeleteButton.disabled = !getCanManageJobs();
  }
  syncJobFormAccess();
  setInlineMessage(jobFormFeedback, "");
  syncJobSheets();
}

function resetJobForm() {
  hydrateJobForm({
    status: "draft",
    environment: {},
    conditions: {},
    hazards: [],
    ppeItems: [],
  });
}

function syncJobCopySourceOptions(currentId = "") {
  replaceSelectOptionsIfChanged(jobCopySourceInput, [
    { value: "", label: "Odaberi postojeći posao za kopiranje" },
    ...sortJobs(state.jobs ?? [])
      .filter((item) => String(item.id) !== String(currentId))
      .map((item) => ({ value: item.id, label: item.title || "Bez naziva" })),
  ], "");
}

function openJobEditor(item = null) {
  state.jobEditorSheet = "basic";
  state.activeJobId = item?.id || "";
  hydrateJobForm(item ?? {});
  setJobEditorOpen(true);
}

function renderJobCard(item = {}) {
  const card = document.createElement("article");
  card.className = `job-card is-${item.status || "draft"}`;
  card.tabIndex = 0;
  card.dataset.jobId = String(item.id || "");
  const status = getJobStatusOption(item.status);
  const environment = item.environment ?? {};
  const conditions = item.conditions ?? {};
  const enabledEnvironmentCount = JOB_ENVIRONMENT_SECTIONS.filter((section) => environment[`${section.key}Enabled`]).length;
  const selectedConditions = JOB_CONDITION_TOGGLES.filter((entry) => Boolean(conditions[entry.key])).length;
  const ppeCount = (item.ppeItems ?? []).length;
  card.innerHTML = `
    <div class="job-card-status-dot"></div>
    <div class="job-card-main">
      <span class="section-kicker">${escapeHtml(status.label)}</span>
      <strong>${escapeHtml(item.title || "Bez naziva")}</strong>
      <p>${escapeHtml(item.description || "Opis još nije popunjen.")}</p>
    </div>
    <div class="job-card-metrics">
      <span>${enabledEnvironmentCount}/4 okruženje</span>
      <span>${selectedConditions} uvjeta</span>
      <span>${(item.hazards ?? []).length} opasnosti</span>
      <span>${ppeCount} OZO</span>
    </div>
  `;
  card.addEventListener("click", () => openJobEditor(item));
  card.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      openJobEditor(item);
    }
  });
  return card;
}

function renderJobsModule() {
  if (!jobsModule) {
    return;
  }
  const canView = getCanViewJobs();
  const canManage = getCanManageJobs();
  const canUseNexAi = getCanUseJobNexAi();
  if (jobNewButton) {
    jobNewButton.hidden = !canManage;
    jobNewButton.disabled = !canManage;
  }
  if (jobDescriptionAiButton) {
    jobDescriptionAiButton.disabled = !canUseNexAi;
    jobDescriptionAiButton.title = canUseNexAi
      ? "Popuni opis preko NexAI"
      : "NexAI nije dostupan za tvoju rolu.";
  }
  [jobSubmitButton, jobResetButton].forEach((button) => {
    if (button) button.disabled = !canManage;
  });
  if (jobDeleteButton) {
    jobDeleteButton.hidden = jobDeleteButton.hidden || !canManage;
    jobDeleteButton.disabled = !canManage;
  }
  syncJobFormAccess();
  if (!canView) {
    jobList?.replaceChildren();
    if (jobEmpty) {
      jobEmpty.hidden = false;
      jobEmpty.textContent = "Nemate pravo za prikaz Jobs modula.";
    }
    return;
  }
  const filters = {
    query: jobSearchInput?.value?.trim() || state.jobFilters.query || "",
    status: jobStatusFilterInput?.value || state.jobFilters.status || "all",
  };
  state.jobFilters = filters;
  replaceSelectOptionsIfChanged(jobStatusFilterInput, [
    { value: "all", label: "Svi statusi" },
    ...JOB_STATUS_OPTIONS,
  ], filters.status);
  replaceSelectOptionsIfChanged(jobStatusInput, JOB_STATUS_OPTIONS, jobStatusInput?.value || "draft");
  if (jobSearchInput && jobSearchInput.value !== filters.query) {
    jobSearchInput.value = filters.query;
  }
  const allJobs = state.jobs ?? [];
  const visible = sortJobs(filterJobs(allJobs, filters));
  jobList?.replaceChildren(...visible.map((item) => renderJobCard(item)));
  if (jobEmpty) {
    jobEmpty.hidden = visible.length > 0;
    jobEmpty.textContent = "Nema poslova za odabrane filtere.";
  }
  syncJobCopySourceOptions(jobIdInput?.value || "");
}

function renderRiskAssessmentOptions(options, selectedValue = "") {
  return options.map((option) => (
    `<option value="${escapeHtml(option.value)}"${String(option.value) === String(selectedValue ?? "") ? " selected" : ""}>${escapeHtml(option.label)}</option>`
  )).join("");
}

function splitRiskAssessmentTextLines(text = "") {
  return String(text || "")
    .split(/\n+|;+/)
    .map((line) => line.replace(/\s+/g, " ").trim())
    .filter(Boolean);
}

function joinUniqueRiskAssessmentTextBlocks(values = []) {
  const seen = new Set();
  return values
    .flatMap((value) => Array.isArray(value) ? value : [value])
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .filter((value) => {
      const key = value.toLocaleLowerCase("hr");
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .join("\n");
}

function getRiskAssessmentTemplatePlaceholder(key = "") {
  return RISK_ASSESSMENT_TEMPLATE_PLACEHOLDER_BY_KEY.get(String(key || "").trim())
    || RISK_ASSESSMENT_TEMPLATE_PLACEHOLDERS[0];
}

function getRiskAssessmentContentsTitle(section = {}) {
  const key = String(section?.key || "").trim();
  const placeholder = getRiskAssessmentTemplatePlaceholder(key);
  const defaultTitle = String(placeholder.defaultTitle || placeholder.label || "").trim();
  const sectionTitle = String(section?.title || "").trim();
  const hasCustomTitle = sectionTitle && sectionTitle !== defaultTitle;
  const titleOverrides = {
    work_equipment: "Ispitivanje radne opreme",
    work_environment: "Ispitivanje fizikalnih čimbenika radnog okoliša",
    chemicals: "Ispitivanje kemijskih čimbenika",
    biological: "Ispitivanje bioloških čimbenika",
    inspections: "Popis ispitivanja",
  };
  if (hasCustomTitle) {
    return sectionTitle;
  }
  return titleOverrides[key] || sectionTitle || defaultTitle || placeholder.label || "Odjeljak";
}

function createRiskAssessmentTemplateSectionDraft(initial = {}, index = 0) {
  const placeholder = getRiskAssessmentTemplatePlaceholder(initial.key || initial.placeholderKey || "intro");
  const isAlwaysIncludedIntro = placeholder.key === "intro";
  return {
    id: String(initial.id || crypto.randomUUID()),
    key: placeholder.key,
    placeholder: String(initial.placeholder || placeholder.token),
    title: String(initial.title || placeholder.defaultTitle || placeholder.label),
    enabled: isAlwaysIncludedIntro ? true : initial.enabled !== false,
    pageBreakBefore: isAlwaysIncludedIntro ? false : Boolean(initial.pageBreakBefore),
    includeInToc: initial.includeInToc !== false && !["cover", "contents"].includes(placeholder.key),
    note: String(initial.note || ""),
    order: Number.isFinite(Number(initial.order)) ? Number(initial.order) : index + 1,
  };
}

function createRiskAssessmentReportWordTemplateDraft(initial = null) {
  const source = initial && typeof initial === "object" ? initial : {};
  const fileName = String(source.fileName || "").trim();
  const dataUrl = String(source.dataUrl || source.storageUrl || source.url || source.inlineDataUrl || "").trim();
  if (!fileName && !dataUrl) {
    return null;
  }
  return {
    id: String(source.id || "").trim(),
    fileName,
    fileType: String(source.fileType || "application/vnd.openxmlformats-officedocument.wordprocessingml.document").trim(),
    fileSize: Number.isFinite(Number(source.fileSize)) ? Number(source.fileSize) : 0,
    dataUrl,
    inlineDataUrl: String(source.inlineDataUrl || "").trim(),
    storageProvider: String(source.storageProvider || "").trim(),
    storageBucket: String(source.storageBucket || "").trim(),
    storageKey: String(source.storageKey || "").trim(),
    storageUrl: String(source.storageUrl || source.url || "").trim(),
    uploadedAt: source.uploadedAt || source.updatedAt || new Date().toISOString(),
  };
}

function createRiskAssessmentReportTemplateDraft(initial = {}) {
  const preset = RISK_ASSESSMENT_TEMPLATE_PRESETS[0];
  const sectionsSource = Array.isArray(initial.sections) && initial.sections.length
    ? initial.sections
    : preset.sections.map((key, index) => ({ key, order: index + 1 }));
  return {
    id: String(initial.id || "risk-assessment-template-default"),
    title: String(initial.title || "Standardni predložak procjene rizika"),
    description: String(initial.description || "Dokument se slaže iz odjeljaka procjene kao velikih placeholder blokova."),
    version: String(initial.version || "1.0"),
    wordTemplate: createRiskAssessmentReportWordTemplateDraft(initial.wordTemplate || initial.referenceDocument || null),
    sections: sectionsSource
      .map((section, index) => createRiskAssessmentTemplateSectionDraft(section, index))
      .sort((left, right) => left.order - right.order)
      .map((section, index) => ({ ...section, order: index + 1 })),
    updatedAt: initial.updatedAt || new Date().toISOString(),
  };
}

function sanitizeRiskAssessmentReportTemplateDraft(template = {}) {
  return createRiskAssessmentReportTemplateDraft({
    ...template,
    title: template.title || riskAssessmentTemplateTitleInput?.value || "",
    description: template.description || riskAssessmentTemplateDescriptionInput?.value || "",
    updatedAt: new Date().toISOString(),
  });
}

function normalizeRiskAssessmentTemplateMode(value = "") {
  return ["include", "page-break", "exclude"].includes(value) ? value : "include";
}

function ensureRiskAssessmentTemplateSections(sectionKeys = []) {
  const template = riskAssessmentReportTemplateDraft || createRiskAssessmentReportTemplateDraft();
  const existingKeys = new Set(template.sections.map((section) => section.key));
  const missing = sectionKeys
    .filter((key) => !existingKeys.has(key))
    .map((key, index) => createRiskAssessmentTemplateSectionDraft({ key }, template.sections.length + index));
  if (!missing.length) {
    riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft(template);
    return riskAssessmentReportTemplateDraft;
  }
  riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft({
    ...template,
    sections: [...template.sections, ...missing],
  });
  return riskAssessmentReportTemplateDraft;
}

function getRiskAssessmentTemplateBlockMode(blockKey = "") {
  const block = RISK_ASSESSMENT_TEMPLATE_BLOCK_BY_KEY.get(String(blockKey || "").trim());
  if (!block) {
    return "include";
  }
  const template = ensureRiskAssessmentTemplateSections(block.sectionKeys);
  const related = template.sections.filter((section) => block.sectionKeys.includes(section.key));
  if (related.length && related.every((section) => !section.enabled)) {
    return "exclude";
  }
  if (related.some((section) => section.pageBreakBefore)) {
    return "page-break";
  }
  return "include";
}

function setRiskAssessmentTemplateBlockMode(blockKey = "", modeValue = "include") {
  const block = RISK_ASSESSMENT_TEMPLATE_BLOCK_BY_KEY.get(String(blockKey || "").trim());
  if (!block) {
    return;
  }
  const mode = block.block === "intro" ? "include" : normalizeRiskAssessmentTemplateMode(modeValue);
  const template = ensureRiskAssessmentTemplateSections(block.sectionKeys);
  const nextSections = template.sections.map((section) => {
    if (!block.sectionKeys.includes(section.key)) {
      return section;
    }
    const enabled = mode !== "exclude";
    return {
      ...section,
      enabled,
      pageBreakBefore: enabled && mode === "page-break",
      includeInToc: enabled && !["cover", "contents"].includes(section.key),
    };
  });
  riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft({
    ...template,
    sections: nextSections,
    updatedAt: new Date().toISOString(),
  });
  renderRiskAssessmentDocumentRoutingControls();
  renderRiskAssessmentTemplatePlaceholderList();
  renderRiskAssessmentTemplatePreview();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function renderRiskAssessmentDocumentRoutingControls() {
  if (!riskAssessmentForm) {
    return;
  }
  RISK_ASSESSMENT_TEMPLATE_BLOCKS.forEach((block) => {
    const section = riskAssessmentForm.querySelector(`[data-risk-assessment-block="${block.block}"]`);
    const head = section?.querySelector(".risk-assessment-editor-section-head");
    if (!head) {
      return;
    }
    if (["intro", "jobs"].includes(block.block)) {
      head.querySelector(`[data-risk-template-routing="${block.block}"]`)?.remove();
      return;
    }
    let control = head.querySelector(`[data-risk-template-routing="${block.block}"]`);
    if (!control) {
      control = document.createElement("label");
      control.className = "risk-assessment-section-document-menu";
      control.dataset.riskTemplateRouting = block.block;
      control.innerHTML = `
        <div class="risk-assessment-section-document-menu-head">
          <span class="risk-assessment-section-document-icon">${renderRiskAssessmentRiskIcon("note")}</span>
          <div class="risk-assessment-section-document-copy">
            <strong>Dokument</strong>
            <small>Uključi ili sakrij odjeljak.</small>
          </div>
        </div>
        <select data-risk-template-routing-select="${escapeHtml(block.block)}">
          <option value="include">Ide u procjenu</option>
          <option value="page-break">Ide u procjenu + nova stranica</option>
          <option value="exclude">Ne ide u procjenu</option>
        </select>
        <em>Placeholder: ${escapeHtml(block.tokenLabel)}</em>
      `;
      const select = control.querySelector("select");
      select?.addEventListener("change", () => {
        setRiskAssessmentTemplateBlockMode(block.block, select.value);
      });
      head.append(control);
    }
    const select = control.querySelector("select");
    if (select) {
      select.value = getRiskAssessmentTemplateBlockMode(block.block);
      select.disabled = !getCanManageRiskAssessments();
    }
  });
}

function renderRiskAssessmentTemplatePlaceholderList() {
  if (!riskAssessmentTemplatePlaceholderList) {
    return;
  }
  const template = riskAssessmentReportTemplateDraft || createRiskAssessmentReportTemplateDraft();
  const enabledKeys = new Set(template.sections.filter((section) => section.enabled).map((section) => section.key));
  const createPlaceholderButton = (placeholder, { muted = false } = {}) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "risk-assessment-template-placeholder-chip";
    button.classList.toggle("is-muted", muted);
    button.innerHTML = `
      <strong>${escapeHtml(placeholder.token)}</strong>
      <span>${escapeHtml(placeholder.defaultTitle || placeholder.label)}</span>
    `;
    button.title = `Kopiraj ${placeholder.token}`;
    button.addEventListener("click", () => {
      const clipboardWrite = navigator.clipboard?.writeText?.(placeholder.token);
      if (clipboardWrite?.then) {
        void clipboardWrite.then(() => {
          setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), `Kopiran placeholder ${placeholder.token}.`, "success");
        }).catch(() => {
          setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), placeholder.token, "success");
        });
      } else {
        setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), placeholder.token, "success");
      }
    });
    return button;
  };
  const sectionButtons = RISK_ASSESSMENT_TEMPLATE_PLACEHOLDERS.map((placeholder) => (
    createPlaceholderButton(placeholder, { muted: !enabledKeys.has(placeholder.key) })
  ));
  const fieldButtons = RISK_ASSESSMENT_FIELD_PLACEHOLDERS.map((placeholder) => (
    createPlaceholderButton(placeholder)
  ));
  riskAssessmentTemplatePlaceholderList.replaceChildren(...sectionButtons, ...fieldButtons);
}

function getRiskAssessmentTemplateFeedbackTarget() {
  return riskAssessmentTemplateFeedback || riskAssessmentError;
}

function getRiskAssessmentExportFeedbackTarget() {
  return state.riskAssessmentEditorOpen
    ? (riskAssessmentExportStatus || riskAssessmentError)
    : getRiskAssessmentTemplateFeedbackTarget();
}

function setRiskAssessmentPlaceholderDialogOpen(open) {
  const isOpen = Boolean(open);
  if (riskAssessmentTemplatePlaceholderBackdrop) {
    riskAssessmentTemplatePlaceholderBackdrop.hidden = !isOpen;
  }
  if (riskAssessmentTemplatePlaceholderDialog) {
    riskAssessmentTemplatePlaceholderDialog.hidden = !isOpen;
    riskAssessmentTemplatePlaceholderDialog.classList.toggle("is-open", isOpen);
  }
  document.body.classList.toggle("is-risk-placeholder-dialog-open", isOpen);
  if (isOpen) {
    renderRiskAssessmentTemplatePlaceholderList();
    requestAnimationFrame(() => {
      riskAssessmentTemplatePlaceholderCloseButton?.focus({ preventScroll: true });
    });
  }
}

function renderRiskAssessmentTemplateWordMeta() {
  const wordTemplate = riskAssessmentReportTemplateDraft?.wordTemplate;
  const canManage = getCanManageRiskAssessments();
  if (riskAssessmentTemplateWordMeta) {
    riskAssessmentTemplateWordMeta.textContent = wordTemplate?.fileName
      ? `${wordTemplate.fileName} · ${formatFileSize(wordTemplate.fileSize || 0)} · ${formatCompactDateTime(wordTemplate.uploadedAt || "")}`
      : "Nema učitanog Word templatea.";
  }
  if (riskAssessmentTemplateWordUploadButton) {
    riskAssessmentTemplateWordUploadButton.disabled = !canManage;
  }
  if (riskAssessmentTemplateWordDownloadButton) {
    riskAssessmentTemplateWordDownloadButton.disabled = !wordTemplate?.dataUrl;
  }
  if (riskAssessmentTemplateWordRemoveButton) {
    riskAssessmentTemplateWordRemoveButton.disabled = !canManage || (!wordTemplate?.fileName && !wordTemplate?.dataUrl);
  }
  syncRiskAssessmentDocumentExportControls();
}

function syncRiskAssessmentTemplatePanelAccess() {
  const canManage = getCanManageRiskAssessments();
  [
    riskAssessmentTemplateTitleInput,
    riskAssessmentTemplateDescriptionInput,
    riskAssessmentTemplatePresetSelect,
    riskAssessmentTemplateApplyPresetButton,
    riskAssessmentTemplateWordFileInput,
    riskAssessmentTemplateWordUploadButton,
    riskAssessmentTemplateWordGenerateButton,
    riskAssessmentTemplatePdfGenerateButton,
    riskAssessmentTemplatePlaceholderOpenButton,
  ].forEach((control) => {
    if (control) {
      control.disabled = !canManage;
    }
  });
  if (riskAssessmentTemplateWordRemoveButton) {
    riskAssessmentTemplateWordRemoveButton.disabled = !canManage || riskAssessmentTemplateWordRemoveButton.disabled;
  }
  syncRiskAssessmentDocumentExportControls();
}

function buildRiskAssessmentTemplatePlaceholderText() {
  const template = riskAssessmentReportTemplateDraft || createRiskAssessmentReportTemplateDraft();
  const enabledKeys = new Set(template.sections.filter((section) => section.enabled).map((section) => section.key));
  return [
    "SafeNexus placeholderi za procjenu rizika",
    "",
    "Veliki placeholderi predstavljaju cijeli odjeljak dokumenta. U Word template ubaci tokene na mjesta gdje želiš da se odjeljci generiraju.",
    "",
    "Odjeljci:",
    ...RISK_ASSESSMENT_TEMPLATE_PLACEHOLDERS.map((placeholder) => (
      `${placeholder.token} - ${placeholder.defaultTitle || placeholder.label}${enabledKeys.has(placeholder.key) ? "" : " (trenutno isključeno)"}`
    )),
    "",
    "Pojedinačna polja:",
    ...RISK_ASSESSMENT_FIELD_PLACEHOLDERS.map((placeholder) => `${placeholder.token} - ${placeholder.label}`),
  ].join("\r\n");
}

function downloadRiskAssessmentTemplatePlaceholders() {
  triggerBlobDownload(
    new Blob(["\ufeff", buildRiskAssessmentTemplatePlaceholderText()], { type: "text/plain;charset=utf-8" }),
    `procjena-rizika-placeholderi-${new Date().toISOString().slice(0, 10)}.txt`,
  );
}

function downloadRiskAssessmentWordTemplate() {
  const wordTemplate = riskAssessmentReportTemplateDraft?.wordTemplate;
  if (!wordTemplate?.dataUrl) {
    return;
  }
  const link = document.createElement("a");
  link.href = wordTemplate.dataUrl;
  link.download = wordTemplate.fileName || "procjena-rizika-template.docx";
  document.body.append(link);
  link.click();
  link.remove();
}

function getRiskAssessmentWordPlaceholderName(value = "") {
  return String(value || "")
    .replace(/^\s*\{\{\s*/, "")
    .replace(/\s*\}\}\s*$/, "")
    .trim();
}

function getRiskAssessmentExportFileBaseName() {
  const assessmentNumber = riskAssessmentNumberInput?.value?.trim() || refreshRiskAssessmentAutoNumber("");
  const companyName = riskAssessmentCompanyInput?.selectedOptions?.[0]?.textContent?.trim()
    || riskAssessmentEmployerCompanyNameInput?.value?.trim()
    || "procjena-rizika";
  const title = riskAssessmentTitleInput?.value?.trim() || `Procjena rizika ${companyName}`;
  return sanitizeDocumentTemplateFileName(
    [assessmentNumber, title].filter(Boolean).join(" "),
    "procjena-rizika",
  );
}

function buildRiskAssessmentSectionExportHtml(section = {}, index = 0) {
  const placeholder = getRiskAssessmentTemplatePlaceholder(section.key);
  const title = section.title || placeholder.defaultTitle || placeholder.label;
  const body = renderRiskAssessmentTemplateSectionBodyContent(section, index + 1);
  if (section.key === "cover") {
    return body;
  }
  return `
    <section>
      <h2>${escapeHtml(title)}</h2>
      ${body}
    </section>
  `;
}

function isRiskAssessmentDuplicateSectionTitleText(value = "", title = "") {
  const normalizedValue = normalizeRiskAssessmentIdentityComparable(value)
    .replace(/^\d+\s+/, "")
    .trim();
  const normalizedTitle = normalizeRiskAssessmentIdentityComparable(title);
  return Boolean(normalizedValue && normalizedTitle && normalizedValue === normalizedTitle);
}

function stripRiskAssessmentDuplicateLeadingTitleFromHtml(html = "", title = "") {
  const source = String(html || "").trim();
  if (!source || !title || typeof document === "undefined") {
    return source;
  }
  const template = document.createElement("template");
  template.innerHTML = source;
  const getNextContentNode = () => Array.from(template.content.childNodes)
    .find((node) => String(node.textContent || "").trim());
  const firstNode = getNextContentNode();
  if (!firstNode) {
    return template.innerHTML;
  }
  const firstText = String(firstNode.textContent || "").replace(/\s+/g, " ").trim();
  if (isRiskAssessmentDuplicateSectionTitleText(firstText, title)) {
    firstNode.remove();
  }
  return template.innerHTML.trim();
}

function renderRiskAssessmentTemplateSectionBodyContent(section = {}, sectionNumber = 1) {
  const placeholder = getRiskAssessmentTemplatePlaceholder(section.key);
  const title = section.title || placeholder.defaultTitle || placeholder.label;
  return stripRiskAssessmentDuplicateLeadingTitleFromHtml(
    renderRiskAssessmentTemplateSectionContent(section.key, sectionNumber),
    title,
  );
}

function createRiskAssessmentExportSectionHeading(title = "", level = 2, options = {}) {
  return createRiskAssessmentExportHeading(title, level, {
    fontFamily: "arial",
    fontSize: 14,
    ...options,
  });
}

function normalizeRiskAssessmentExportText(value = "") {
  return String(value ?? "")
    .replace(/\r\n/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .trim();
}

function normalizeRiskAssessmentExportLines(value = []) {
  if (Array.isArray(value)) {
    return value.flatMap((entry) => normalizeRiskAssessmentExportLines(entry));
  }
  return normalizeRiskAssessmentExportText(value)
    .split(/\n+/)
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function joinRiskAssessmentExportLines(value = [], fallback = "-") {
  const lines = normalizeRiskAssessmentExportLines(value);
  return lines.length ? lines.join("\n") : fallback;
}

function createRiskAssessmentExportCell(value = "", format = {}) {
  const cellFormat = {
    align: format.align || "left",
    type: format.type || "text",
    bold: Boolean(format.bold),
    italic: Boolean(format.italic),
  };
  if (format.fillColor) {
    cellFormat.fillColor = format.fillColor;
  }
  if (format.borderStyle) {
    cellFormat.borderStyle = format.borderStyle;
  }
  if (format.verticalAlign) {
    cellFormat.verticalAlign = format.verticalAlign;
  }
  if (format.card) {
    cellFormat.card = {
      fillColor: format.card.fillColor || "",
      borderColor: format.card.borderColor || "",
      textColor: format.card.textColor || "",
    };
  }
  if (Number.isFinite(Number(format.fontSize))) {
    cellFormat.fontSize = Number(format.fontSize);
  }
  return {
    text: joinRiskAssessmentExportLines(value, format.fallback ?? "-"),
    format: cellFormat,
  };
}

function createRiskAssessmentExportHeaderCell(value = "", format = {}) {
  return createRiskAssessmentExportCell(value, {
    align: "center",
    fillColor: "#E5E7EB",
    fontSize: 8,
    ...format,
    bold: true,
  });
}

function createRiskAssessmentExportRow(id = "", cells = [], header = false) {
  return {
    id,
    header,
    cells,
  };
}

function createRiskAssessmentExportTable(columns = [], rows = [], options = {}) {
  const table = {
    __docxBlockType: "table",
    columns,
    rows,
    headerRows: rows.filter((row) => row.header).map((row) => row.id),
    merges: options.merges || [],
  };
  if (options.pageOrientation) {
    table.pageOrientation = options.pageOrientation;
  }
  if (options.keepRowsTogether || options.avoidRowBreaks || options.keepTogether) {
    table.keepRowsTogether = true;
  }
  return table;
}

function createRiskAssessmentExportBlocks(blocks = []) {
  return {
    __docxBlockType: "blocks",
    blocks: blocks.filter(Boolean),
  };
}

function createRiskAssessmentExportHeading(text = "", level = 2, options = {}) {
  const safeText = normalizeRiskAssessmentExportText(text);
  return safeText ? { type: "heading", text: safeText, level, ...options } : null;
}

function createRiskAssessmentExportParagraph(text = "", options = {}) {
  const safeText = normalizeRiskAssessmentExportText(text);
  return safeText ? { type: "paragraph", text: safeText, ...options } : null;
}

function createRiskAssessmentExportPageBreak() {
  return { type: "page_break" };
}

function createRiskAssessmentExportToc(entries = [], options = {}) {
  return {
    __docxBlockType: "toc",
    title: String(options.title || "Sadržaj"),
    instruction: String(options.instruction || 'TOC \\o "1-2" \\h \\z \\u'),
    entries: (Array.isArray(entries) ? entries : [])
      .map((entry, index) => ({
        id: String(entry?.id || `toc-${index + 1}`),
        title: String(entry?.title || entry?.label || "").trim(),
        level: Math.max(1, Math.min(4, Number.parseInt(entry?.level, 10) || 1)),
        page: String(entry?.page || entry?.pageNumber || "").trim(),
      }))
      .filter((entry) => entry.title),
  };
}

function getRiskAssessmentLinkedWorkOrder() {
  return getRiskAssessmentWorkOrderById(riskAssessmentWorkOrderInput?.value || "");
}

function getRiskAssessmentWorkOrderServiceCodeSummary(workOrder = {}) {
  if (!workOrder) {
    return "";
  }
  const serviceItems = getWorkOrderServiceItems(workOrder);
  const riskServiceItems = serviceItems.filter((item) => isRiskAssessmentWorkOrderServiceItem(item));
  const sourceItems = riskServiceItems.length ? riskServiceItems : serviceItems;
  const codes = sourceItems
    .map((item) => {
      const catalogItem = getRiskAssessmentServiceCatalogItem(item);
      return String(item?.serviceCode || item?.shortLabel || catalogItem?.serviceCode || item?.code || "").trim();
    })
    .filter(Boolean);
  return Array.from(new Set(codes)).join("-");
}

function buildRiskAssessmentRecordNumber(assessmentNumber = "") {
  const linkedWorkOrder = getRiskAssessmentLinkedWorkOrder();
  const workOrderNumber = String(linkedWorkOrder?.workOrderNumber || "").trim();
  const serviceCode = getRiskAssessmentWorkOrderServiceCodeSummary(linkedWorkOrder);
  return [workOrderNumber, serviceCode].filter(Boolean).join("-")
    || String(assessmentNumber || "").trim();
}

function getRiskAssessmentCompanyExportData() {
  const employer = readRiskAssessmentEmployerData();
  const company = getRiskAssessmentCompany(riskAssessmentCompanyInput?.value || "");
  const selectedCompanyName = riskAssessmentCompanyInput?.selectedOptions?.[0]?.textContent?.trim() || "";
  const companyName = employer.fullName || selectedCompanyName || company?.name || "";
  const companyAddress = employer.address || company?.address || company?.headquarters || "";
  const headquarters = employer.headquarters || companyAddress || company?.headquarters || "";
  const assessmentNumber = riskAssessmentNumberInput?.value?.trim() || refreshRiskAssessmentAutoNumber("");
  const assessmentStartDate = formatDateInputDisplayValue(riskAssessmentDateInput?.value || "");
  const assessmentCompletionDate = formatDateInputDisplayValue(riskAssessmentCompletionDateInput?.value || "");
  const locationName = getRiskAssessmentSelectedLocationLines(riskAssessmentCompanyInput?.value || "").join("; ")
    || riskAssessmentLocationInput?.selectedOptions?.[0]?.textContent?.trim()
    || employer.detachedLocations
    || "";
  return {
    employer,
    company,
    companyName,
    companyAddress,
    headquarters,
    companyOib: employer.oib || company?.oib || "",
    assessmentNumber,
    recordNumber: buildRiskAssessmentRecordNumber(assessmentNumber),
    assessmentStartDate,
    assessmentCompletionDate,
    locationName,
  };
}

function splitRiskAssessmentExportValueLines(value = [], fallback = "") {
  const lines = normalizeRiskAssessmentExportLines(value)
    .flatMap((entry) => String(entry || "").split(/;+/))
    .map((entry) => entry.trim())
    .filter(Boolean);
  return lines.length ? Array.from(new Set(lines)) : (fallback ? [fallback] : []);
}

function formatRiskAssessmentPersonExportLine(item = {}) {
  return [
    item.fullName || item.name,
    item.title || item.jobTitle || item.role,
  ].map((value) => String(value || "").trim()).filter(Boolean).join(", ");
}

function createRiskAssessmentBasicDataBox(title = "", lines = [], options = {}) {
  const safeLines = options.splitItems === false
    ? [normalizeRiskAssessmentExportLines(lines).join("; ") || "-"]
    : splitRiskAssessmentExportValueLines(lines, "-");
  const columns = [{ id: "value", label: title, width: 720 }];
  const rows = [
    createRiskAssessmentExportRow("title", [
      createRiskAssessmentExportCell(title, { fontSize: 9, bold: true, fillColor: "#FFFFFF" }),
    ]),
    ...safeLines.map((line, index) => createRiskAssessmentExportRow(`line-${index + 1}`, [
      createRiskAssessmentExportCell(line, { fontSize: 9, fillColor: "#FFFFFF" }),
    ])),
  ];
  return createRiskAssessmentExportTable(columns, rows, { keepRowsTogether: true });
}

function createRiskAssessmentAuthorizationExportBox(employer = {}) {
  if (!employer.hasZnrAuthorization) {
    return null;
  }
  const authorizationDocument = normalizeRiskAssessmentAuthorizationDocument(employer.znrAuthorizationDocument);
  const details = employer.znrAuthorizationCompanyDetails
    || employer.znrExperts
    || "Ovlaštenje izrađivača procjene rizika je dodano u prilogu procjene.";
  return createRiskAssessmentBasicDataBox("Ovlaštenje izrađivača procjene rizika:", [
    authorizationDocument?.fileName
      ? `Prilog: ${authorizationDocument.fileName}.`
      : "Prilog: ovlaštenje za obavljanje poslova zaštite na radu.",
    details,
  ], { splitItems: false });
}

function createRiskAssessmentEmployerDataTable(data = {}) {
  const employer = data.employer || {};
  const rowsData = [
    ["Puni naziv tvrtke", data.companyName],
    ["Sjedište / adresa", data.headquarters || data.companyAddress],
    ["OIB", data.companyOib],
    ["MBS", employer.mbs],
    ["NKD djelatnost", employer.nkdActivity],
    ["Broj zaposlenih", employer.employeeCount],
    ["Broj zapisnika", data.recordNumber],
    ["Datum početka rada na procjeni", data.assessmentStartDate],
    ["Datum završetka procjene", data.assessmentCompletionDate],
  ].map(([label, value]) => [label, joinRiskAssessmentExportLines(value, "")])
    .filter(([, value]) => value);
  const columns = [
    { id: "label", label: "Podatak", width: 210 },
    { id: "value", label: "Vrijednost", width: 510 },
  ];
  const rows = [
    createRiskAssessmentExportRow("title", [
      createRiskAssessmentExportCell("Podaci o poslodavcu:", { fontSize: 9, bold: true, fillColor: "#FFFFFF" }),
      createRiskAssessmentExportCell("", { fontSize: 9, fillColor: "#FFFFFF" }),
    ]),
    ...rowsData.map(([label, value], index) => createRiskAssessmentExportRow(`employer-${index + 1}`, [
      createRiskAssessmentExportCell(`${label}:`, { fontSize: 9, bold: true, fillColor: "#FFFFFF" }),
      createRiskAssessmentExportCell(value, { fontSize: 9, fillColor: "#FFFFFF" }),
    ])),
  ];
  return createRiskAssessmentExportTable(columns, rows, {
    merges: [{ rowId: "title", columnId: "label", colSpan: 2 }],
    keepRowsTogether: true,
  });
}

function buildRiskAssessmentWorkingGroupExportTable() {
  const teamLead = readRiskAssessmentPeopleSelection(riskAssessmentTeamLeadInput);
  const members = readRiskAssessmentPeopleSelection(riskAssessmentMembersInput);
  const rowsData = [
    ...teamLead.labels.map((label) => ({ name: label, role: "voditelj" })),
    ...members.labels
      .filter((label) => !teamLead.labels.includes(label))
      .map((label) => ({ name: label, role: "član" })),
  ];
  const rows = [
    createRiskAssessmentExportRow("title", [
      createRiskAssessmentExportCell("Članovi radne skupine:", { fontSize: 9, bold: true, fillColor: "#FFFFFF" }),
      createRiskAssessmentExportCell("", { fontSize: 9, fillColor: "#FFFFFF" }),
      createRiskAssessmentExportCell("", { fontSize: 9, fillColor: "#FFFFFF" }),
    ]),
    ...(rowsData.length ? rowsData : [{ name: "-", role: "" }]).map((item, index) => createRiskAssessmentExportRow(`member-${index + 1}`, [
      createRiskAssessmentExportCell(item.name, { fontSize: 9, fillColor: "#FFFFFF" }),
      createRiskAssessmentExportCell(item.role, { fontSize: 8, align: "center", fillColor: "#FFFFFF" }),
      createRiskAssessmentExportCell("", { fontSize: 9, fillColor: "#FFFFFF" }),
    ])),
  ];
  return createRiskAssessmentExportTable([
    { id: "name", label: "Ime i prezime", width: 440 },
    { id: "role", label: "Uloga", width: 120 },
    { id: "signature", label: "Potpis", width: 160 },
  ], rows, {
    merges: [{ rowId: "title", columnId: "name", colSpan: 3 }],
    keepRowsTogether: true,
  });
}

function buildRiskAssessmentBasicDataExportBlocks() {
  const data = getRiskAssessmentCompanyExportData();
  const employer = data.employer;
  const authorizedLines = [
    ...splitRiskAssessmentExportValueLines(employer.znrAuthorizedDescription),
    ...(employer.authorizedPersons ?? [])
      .filter((item) => normalizeRiskAssessmentAuthorizedPersonRole(item.role) === "authorized")
      .map(formatRiskAssessmentPersonExportLine),
  ].filter(Boolean);
  const representativeLines = [
    ...splitRiskAssessmentExportValueLines(employer.znrRepresentatives),
    ...(employer.authorizedPersons ?? [])
      .filter((item) => normalizeRiskAssessmentAuthorizedPersonRole(item.role) === "representative")
      .map(formatRiskAssessmentPersonExportLine),
  ].filter(Boolean);
  const collaboratorLines = (employer.companyCollaborators ?? [])
    .map(formatRiskAssessmentPersonExportLine)
    .filter(Boolean);
  const collaboratorSummary = getRiskAssessmentCompanyCollaboratorSummary();
  return [
    createRiskAssessmentEmployerDataTable(data),
    createRiskAssessmentAuthorizationExportBox(employer),
    createRiskAssessmentBasicDataBox("Objekti namijenjeni za rad (s naznakom lokacije):", [data.locationName || employer.detachedLocations], { splitItems: false }),
    createRiskAssessmentBasicDataBox("Stručnjaci zaštite na radu:", [employer.znrServiceMode, employer.znrExperts]),
    createRiskAssessmentBasicDataBox("Ovlaštenici za poslove zaštite na radu:", authorizedLines),
    createRiskAssessmentBasicDataBox("Povjerenici radnika za zaštitu na radu:", representativeLines.length ? representativeLines : ["Nisu izabrani."]),
    createRiskAssessmentBasicDataBox("Suradnici na izradi procjene rizika:", collaboratorLines.length ? collaboratorLines : collaboratorSummary),
    createRiskAssessmentBasicDataBox("Ovlašteno trgovačko društvo:", [employer.znrExperts || employer.znrServiceMode]),
    buildRiskAssessmentWorkingGroupExportTable(),
  ].filter(Boolean);
}

function buildRiskAssessmentContentsExportBlocks() {
  const sections = getRiskAssessmentExportSections()
    .filter((section) => (
      section.enabled
      && section.includeInToc !== false
      && !["cover", "contents"].includes(section.key)
    ))
    .map((section) => ({
      id: section.key,
      title: getRiskAssessmentContentsTitle(section),
      level: 1,
    }));
  return [createRiskAssessmentExportToc(sections, { title: "Sadržaj" })];
}

function formatRiskAssessmentExportYesNo(value = "", fallback = "-") {
  const normalized = String(value || "").toLowerCase();
  if (normalized === "da" || normalized === "yes" || normalized === "true") return "Da";
  if (normalized === "ne" || normalized === "no" || normalized === "false") return "Ne";
  if (normalized === "np" || normalized === "n/p") return "N/P";
  return fallback;
}

function hasRiskAssessmentSpecialWorkConditions(job = {}) {
  return String(job.specialWorkConditions || "").trim().toLocaleLowerCase("hr") === "da"
    || normalizeJobPurPointValues(job.purPoints ?? []).length > 0;
}

function formatRiskAssessmentSpecialWorkValue(job = {}, fallback = "ne") {
  return hasRiskAssessmentSpecialWorkConditions(job)
    ? "da"
    : (String(job.specialWorkConditions || "").trim() || fallback);
}

function formatRiskAssessmentSpecialWorkCell(job = {}) {
  if (!hasRiskAssessmentSpecialWorkConditions(job)) {
    return "Ne";
  }
  const purSummary = getJobPurPointSummary(job.purPoints ?? []);
  return joinUniqueRiskAssessmentTextBlocks([
    "Da",
    normalizeJobPurPointValues(job.purPoints ?? []).length ? purSummary : "",
  ]);
}

function formatRiskAssessmentRiskSpecialWorkCell(risk = {}) {
  const purPoints = normalizeJobPurPointValues(risk.purPoints ?? []);
  if (!purPoints.length) {
    return "Ne";
  }
  return joinUniqueRiskAssessmentTextBlocks([
    "Da",
    getJobPurPointSummary(purPoints),
  ]);
}

function formatRiskAssessmentRiskSpecialWorkNote(risk = {}) {
  const purPoints = normalizeJobPurPointValues(risk.purPoints ?? []);
  if (!purPoints.length) {
    return "";
  }
  return `Poslovi s posebnim uvjetima rada: ${getJobPurPointSummary(purPoints)}.`;
}

function getRiskAssessmentManualSpecialWorkReason(existingText = "", previousPurPoints = [], options = {}) {
  const previousPurLineKeys = new Set(
    getJobPurPointGeneratedReasonLines(previousPurPoints, options)
      .map((line) => normalizeRiskAssessmentIdentityComparable(line)),
  );
  return splitRiskAssessmentTextLines(existingText)
    .filter((line) => !previousPurLineKeys.has(normalizeRiskAssessmentIdentityComparable(line)))
    .join("\n");
}

function mergeRiskAssessmentSpecialWorkReason(existingText = "", purPoints = [], previousPurPoints = [], options = {}) {
  return joinUniqueRiskAssessmentTextBlocks([
    getJobPurPointReasonText(purPoints, options),
    getRiskAssessmentManualSpecialWorkReason(existingText, previousPurPoints, options),
  ]);
}

function getRiskAssessmentExportRiskLevelText(risk = {}) {
  return getRiskAssessmentRiskDisplayLevel(risk);
}

function getRiskAssessmentExportRiskFill(risk = {}) {
  const level = getRiskAssessmentRiskDisplayLevel(risk).toLocaleLowerCase("hr-HR");
  if (level.includes("velik")) return "#FEE2E2";
  if (level.includes("sred")) return "#FEF3C7";
  if (level.includes("mal")) return "#BBF7D0";
  return "#F8FAFC";
}

