function buildRiskAssessmentManualHandlingExportBlocks() {
  if (!riskAssessmentManualHandlingDrafts.length) {
    return [
      ...buildRiskAssessmentManualScopeExportBlocks(),
      createRiskAssessmentExportParagraph("IOR izračuni nisu dodani."),
    ];
  }
  const blocks = [...buildRiskAssessmentManualScopeExportBlocks()];
  riskAssessmentManualHandlingDrafts.forEach((entry, index) => {
    blocks.push(
      createRiskAssessmentExportHeading(`IOR obrazac ${index + 1}: ${getRiskAssessmentManualEntryTitle(entry, "Aktivnost")}`, 3),
      buildRiskAssessmentManualVisualFlowTable(entry, index),
      buildRiskAssessmentManualScoreTable(entry),
    );
  });
  blocks.push(...buildRiskAssessmentManualMethodTables());
  return blocks;
}

function buildRiskAssessmentOverviewExportBlocks() {
  const summary = getRiskAssessmentFinalSummaryData();
  const columns = [
    { id: "item", label: "Stavka", width: 260 },
    { id: "value", label: "Vrijednost", width: 160 },
    { id: "note", label: "Napomena", width: 360 },
  ];
  const rows = [
    createRiskAssessmentExportRow("head", columns.map((column) => createRiskAssessmentExportHeaderCell(column.label, { fontSize: 8 })), true),
    ["Tvrtka", summary.companyName || "-", summary.status || ""],
    ["Datum procjene", summary.assessmentDate || "-", summary.completionDate ? `Završetak: ${summary.completionDate}` : ""],
    ["Organizacijske jedinice", String(summary.units || 0), ""],
    ["Radna mjesta", `${summary.readyJobs || 0}/${summary.jobs || 0}`, "Spremno / ukupno"],
    ["Rizici", String(summary.totalRisks || 0), ""],
    ["Kemijske štetnosti", String(summary.totalChemicals || 0), ""],
    ["OZO stavke", String(summary.totalPpe || 0), ""],
    ["IOR obrasci", String(summary.totalManualHandling || 0), summary.highManualHandling ? `${summary.highManualHandling} visokih izračuna` : ""],
    ["Lokacije", String(summary.workplaceCount || 0), ""],
  ].map((entry, index) => (Array.isArray(entry)
    ? createRiskAssessmentExportRow(`summary-${index}`, [
      createRiskAssessmentExportCell(entry[0], { fontSize: 8, bold: true, fillColor: "#F8FAFC" }),
      createRiskAssessmentExportCell(entry[1], { fontSize: 8, align: "center" }),
      createRiskAssessmentExportCell(entry[2], { fontSize: 8 }),
    ])
    : entry));
  return [createRiskAssessmentExportTable(columns, rows)];
}

function buildRiskAssessmentStructuredSectionExportBlocks(key = "") {
  switch (key) {
    case "contents":
      return buildRiskAssessmentContentsExportBlocks();
    case "employer":
      return buildRiskAssessmentBasicDataExportBlocks();
    case "structure":
      return buildRiskAssessmentStructureExportBlocks();
    case "measures":
      return buildRiskAssessmentMeasuresExportBlocks();
    case "jobs":
      return buildRiskAssessmentJobsExportBlocks();
    case "chemicals":
      return buildRiskAssessmentChemicalsExportBlocks();
    case "biological":
      return buildRiskAssessmentBiologicalExportBlocks();
    case "work_equipment":
      return buildRiskAssessmentWorkEquipmentExportBlocks();
    case "inspections":
      return buildRiskAssessmentInspectionsExportBlocks();
    case "ppe":
      return buildRiskAssessmentPpeExportBlocks();
    case "manual_handling":
      return buildRiskAssessmentManualHandlingExportBlocks();
    case "overview":
      return buildRiskAssessmentOverviewExportBlocks();
    case "signatures":
      return [buildRiskAssessmentSignatureExportBlock()];
    default:
      return null;
  }
}

function buildRiskAssessmentSectionExportBlockValue(section = {}, index = 0) {
  const placeholder = getRiskAssessmentTemplatePlaceholder(section.key);
  const title = section.title || placeholder.defaultTitle || placeholder.label;
  const structuredBlocks = buildRiskAssessmentStructuredSectionExportBlocks(section.key);
  const attachSectionMeta = (value = {}) => ({
    ...value,
    __riskSectionKey: section.key || placeholder.key,
    __riskSectionOrder: index,
    __riskPageBreakBefore: Boolean(section.pageBreakBefore),
  });
  if (Array.isArray(structuredBlocks)) {
    const shouldRenderHeading = !["cover", "contents"].includes(section.key);
    return attachSectionMeta(createRiskAssessmentExportBlocks([
      shouldRenderHeading ? createRiskAssessmentExportSectionHeading(title, 2) : null,
      ...structuredBlocks,
    ]));
  }
  if (section.key !== "cover") {
    const body = renderRiskAssessmentTemplateSectionBodyContent(section, index + 1);
    return attachSectionMeta(createRiskAssessmentExportBlocks([
      createRiskAssessmentExportSectionHeading(title, 2),
      body ? { __docxBlockType: "rich_text", html: body } : null,
    ]));
  }
  return attachSectionMeta({
    __docxBlockType: "rich_text",
    html: buildRiskAssessmentSectionExportHtml(section, index),
  });
}

function getRiskAssessmentExportSections() {
  const template = ensureRiskAssessmentTemplateSections(
    RISK_ASSESSMENT_TEMPLATE_PLACEHOLDERS.map((placeholder) => placeholder.key),
  );
  return template.sections
    .slice()
    .sort((left, right) => left.order - right.order);
}

function normalizeRiskAssessmentSignatureOib(value = "") {
  return String(value || "").replace(/\D/g, "").slice(0, 11);
}

function getRiskAssessmentSignatureUser(userId = "") {
  const normalizedUserId = String(userId || "").trim();
  return normalizedUserId
    ? (state.users ?? []).find((user) => String(user?.id || "") === normalizedUserId) ?? null
    : null;
}

function getRiskAssessmentSignatureUserName(user = null, fallback = "") {
  return String(
    getUserDocumentDisplayName(user)
    || fallback
    || [user?.firstName, user?.lastName].filter(Boolean).join(" ")
    || user?.fullName
    || user?.username
    || user?.email
    || "",
  ).replace(/\s+/g, " ").trim();
}

function createRiskAssessmentDigitalSignatureItem({
  name = "",
  role = "Izrađivač procjene",
  oib = "",
  user = null,
} = {}) {
  const signerOib = normalizeRiskAssessmentSignatureOib(oib || user?.oib);
  const signerName = getRiskAssessmentSignatureUserName(user, name);
  if (!signerName || !signerOib) {
    return null;
  }

  const signerTitle = getUserDocumentTitle(user);
  const signerOrganization = getUserDocumentOrganizationName(user);
  return {
    role,
    roleLabel: role,
    name: signerName,
    label: signerName,
    metaLines: [
      signerTitle,
      `OIB ${signerOib}`,
      signerOrganization,
    ].filter(Boolean),
    signatureMode: "digital",
    signerUserId: String(user?.id || "").trim(),
    signerEmail: String(user?.email || "").trim(),
    signerTitle,
    signerOrganization,
    signerOib,
    signatureFieldRole: "PROCJENA_RIZIKA",
    signatureFieldOib: signerOib,
    digitalAnchor: signerOib,
  };
}

function buildRiskAssessmentDigitalSignatureItems() {
  const leadSelection = readRiskAssessmentPeopleSelection(riskAssessmentTeamLeadInput);
  const memberSelection = readRiskAssessmentPeopleSelection(riskAssessmentMembersInput);
  const employer = readRiskAssessmentEmployerData();
  const items = [];
  const used = new Set();

  const pushItem = (candidate = {}) => {
    const item = createRiskAssessmentDigitalSignatureItem(candidate);
    if (!item) {
      return;
    }
    const key = item.signerOib || normalizeLooseName(item.name);
    if (!key || used.has(key)) {
      return;
    }
    used.add(key);
    items.push(item);
  };

  leadSelection.userIds.forEach((userId) => {
    pushItem({
      user: getRiskAssessmentSignatureUser(userId),
      role: "Voditelj izrade procjene rizika",
    });
  });
  memberSelection.userIds.forEach((userId) => {
    pushItem({
      user: getRiskAssessmentSignatureUser(userId),
      role: "Član radne skupine",
    });
  });
  (employer.companyCollaborators ?? []).forEach((person) => {
    pushItem({
      name: person.fullName || "",
      role: person.title || person.jobTitle || "Suradnik poslodavca",
      oib: person.oib || "",
    });
  });

  return items;
}

function buildRiskAssessmentSignatureExportBlock() {
  const items = buildRiskAssessmentDigitalSignatureItems();
  if (items.length === 0) {
    return createRiskAssessmentExportParagraph("Nema odabranih potpisnika s upisanim OIB-om za digitalni potpis.");
  }
  return {
    __docxBlockType: "signature_group",
    title: "Digitalni potpisi procjene rizika",
    items,
  };
}

function buildRiskAssessmentExportPlaceholders() {
  const employer = readRiskAssessmentEmployerData();
  const companyData = getRiskAssessmentCompanyExportData();
  const sections = getRiskAssessmentExportSections();
  const companyName = companyData.companyName;
  const locationName = companyData.locationName;
  const assessmentNumber = companyData.assessmentNumber;
  const teamLead = getRiskAssessmentSelectedPeopleText(riskAssessmentTeamLeadInput);
  const members = getRiskAssessmentSelectedPeopleText(riskAssessmentMembersInput);
  const collaborators = getRiskAssessmentCompanyCollaboratorSummary();
  const basicDataBlocks = buildRiskAssessmentBasicDataExportBlocks();
  const contentsBlocks = buildRiskAssessmentContentsExportBlocks();
  const placeholders = {
    TVRTKA: companyName,
    SJEDISTE: companyData.headquarters || companyData.companyAddress,
    OIB: companyData.companyOib,
    MBS: employer.mbs || "",
    NKD: employer.nkdActivity || "",
    BROJ_ZAPOSLENIH: employer.employeeCount || "",
    BROJ_ZAPISNIKA: companyData.recordNumber,
    DATUM_POCETKA_PROCJENE: companyData.assessmentStartDate,
    DATUM_ZAVRSETKA_PROCJENE: companyData.assessmentCompletionDate,
    RISK_TITLE: riskAssessmentTitleInput?.value?.trim() || `Procjena rizika - ${companyName || "poslodavac"}`,
    RISK_NUMBER: assessmentNumber,
    RISK_RECORD_NUMBER: companyData.recordNumber,
    RISK_COMPANY: companyName,
    RISK_EMPLOYER_NAME: employer.fullName || companyName,
    RISK_EMPLOYER_ADDRESS: companyData.companyAddress || companyData.headquarters || "",
    RISK_EMPLOYER_HEADQUARTERS: companyData.headquarters || "",
    RISK_EMPLOYER_OIB: companyData.companyOib || "",
    RISK_EMPLOYER_MBS: employer.mbs || "",
    RISK_EMPLOYER_NKD: employer.nkdActivity || "",
    RISK_EMPLOYEE_COUNT: employer.employeeCount || "",
    RISK_ZNR_AUTHORIZATION: employer.hasZnrAuthorization ? "Da" : "Ne",
    RISK_ZNR_AUTHORIZATION_COMPANY_DETAILS: employer.znrAuthorizationCompanyDetails || "",
    RISK_ZNR_AUTHORIZATION_DOCUMENT: normalizeRiskAssessmentAuthorizationDocument(employer.znrAuthorizationDocument)?.fileName || "",
    RISK_LOCATION: locationName,
    RISK_WORK_ORDER: riskAssessmentWorkOrderInput?.selectedOptions?.[0]?.textContent?.trim() || "",
    RISK_STATUS: riskAssessmentStatusInput?.selectedOptions?.[0]?.textContent?.trim() || "",
    RISK_DATE: companyData.assessmentStartDate,
    RISK_START_DATE: companyData.assessmentStartDate,
    RISK_ASSESSMENT_START_DATE: companyData.assessmentStartDate,
    RISK_COMPLETION_DATE: companyData.assessmentCompletionDate,
    RISK_END_DATE: companyData.assessmentCompletionDate,
    RISK_ASSESSMENT_END_DATE: companyData.assessmentCompletionDate,
    RISK_TEAM_LEAD: teamLead,
    RISK_MEMBERS: members,
    RISK_COLLABORATORS: collaborators,
    RISK_CONTENTS: createRiskAssessmentExportBlocks(contentsBlocks),
    RISK_BASIC_DATA: createRiskAssessmentExportBlocks(basicDataBlocks),
    RISK_SIGNATURES: buildRiskAssessmentSignatureExportBlock(),
    RISK_GENERATED_AT: formatCompactDateTime(new Date().toISOString()),
  };

  sections.forEach((section, index) => {
    const placeholder = getRiskAssessmentTemplatePlaceholder(section.key);
    const blockValue = section.enabled
      ? buildRiskAssessmentSectionExportBlockValue(section, index)
      : { __docxBlockType: "optional_empty" };
    [
      placeholder.token,
      section.placeholder,
    ].forEach((token) => {
      const key = getRiskAssessmentWordPlaceholderName(token);
      if (key) {
        placeholders[key] = blockValue;
      }
    });
  });

  return placeholders;
}

function getRiskAssessmentTemplateDocumentForExport() {
  const moduleTemplate = riskAssessmentModuleReportTemplateDraft || getRiskAssessmentModuleTemplateDraft();
  const wordTemplate = riskAssessmentReportTemplateDraft?.wordTemplate || moduleTemplate?.wordTemplate;
  if (!wordTemplate?.dataUrl) {
    throw new Error("Prvo učitaj Word template procjene (.docx ili .dotx).");
  }
  return wordTemplate;
}

function syncRiskAssessmentDocumentExportControls() {
  const canManage = getCanManageRiskAssessments();
  const wordTemplate = riskAssessmentReportTemplateDraft?.wordTemplate || riskAssessmentModuleReportTemplateDraft?.wordTemplate;
  const hasDraft = Boolean(state.riskAssessmentEditorOpen || riskAssessmentIdInput?.value || riskAssessmentCompanyInput?.value);
  const canExport = canManage && hasDraft && Boolean(wordTemplate?.dataUrl) && !riskAssessmentWordExportBusy;
  [
    riskAssessmentTemplateWordGenerateButton,
    riskAssessmentTemplatePdfGenerateButton,
    riskAssessmentExportDocxButton,
    riskAssessmentExportPdfButton,
    riskAssessmentSendSignatureButton,
    ...document.querySelectorAll("[data-risk-overview-export]"),
  ].forEach((button) => {
    if (!button) {
      return;
    }
    button.disabled = !canExport;
    button.classList.toggle("is-loading", riskAssessmentWordExportBusy);
  });
}

function getRiskAssessmentPdfLoadingPhases() {
  return [
    {
      label: "Podaci",
      detail: "Provjeravam podatke procjene",
      progress: 10,
    },
    {
      label: "Placeholderi",
      detail: "Punim Word tokene podacima procjene",
      progress: 28,
    },
    {
      label: "Word",
      detail: "Pripremam Word template za izvoz",
      progress: 46,
    },
    {
      label: "PDF engine",
      detail: "Pretvaram procjenu u PDF",
      progress: 74,
    },
    {
      label: "Preuzimanje",
      detail: "Pripremam PDF datoteku za preuzimanje",
      progress: 92,
    },
    {
      label: "Gotovo",
      detail: "PDF procjene rizika je spreman",
      progress: 100,
    },
  ];
}

async function exportRiskAssessmentDocument(format = "docx") {
  if (!state.riskAssessmentEditorOpen && !riskAssessmentIdInput?.value && !riskAssessmentCompanyInput?.value) {
    throw new Error("Otvori procjenu koju želiš izvesti pa generiraj DOCX ili PDF.");
  }

  const safeFormat = String(format || "").trim().toLowerCase() === "pdf" ? "pdf" : "docx";
  const templateDocument = getRiskAssessmentTemplateDocumentForExport();
  const fileName = `${getRiskAssessmentExportFileBaseName()}.${safeFormat}`;
  const endpoint = safeFormat === "pdf"
    ? "/risk-assessments/export-pdf"
    : "/risk-assessments/export-word";
  const feedbackTarget = getRiskAssessmentExportFeedbackTarget();
  const loading = safeFormat === "pdf"
    ? createGlobalLoadingController({
      message: "Izrađujem PDF procjene rizika...",
      phases: getRiskAssessmentPdfLoadingPhases(),
    })
    : null;

  riskAssessmentWordExportBusy = true;
  setInlineMessage(
    feedbackTarget,
    `${safeFormat.toUpperCase()} procjene rizika se izrađuje...`,
    "success",
  );
  syncRiskAssessmentDocumentExportControls();
  try {
    loading?.setPhase(1, { message: "Punim Word placeholdere podacima iz procjene..." });
    const placeholders = buildRiskAssessmentExportPlaceholders();
    loading?.setPhase(2, { message: "Pripremam Word template i raspored odjeljaka..." });
    loading?.setPhase(3, { message: "PDF engine radi dokument, ovo može potrajati par sekundi..." });
    const response = await apiBinaryRequest(endpoint, {
      method: "POST",
      body: {
        templateDocument,
        placeholders,
        fileName,
        ...(safeFormat === "pdf" ? { signatureSettings: getPdfSignatureExportSettings() } : {}),
      },
    });
    loading?.setPhase(4, { message: "PDF je izrađen, pripremam preuzimanje..." });
    triggerBlobDownload(response.blob, response.fileName || fileName);
    loading?.complete({ message: "PDF procjene rizika je spreman." });
    setInlineMessage(
      feedbackTarget,
      `${safeFormat.toUpperCase()} procjene rizika je generiran.`,
      "success",
    );
  } finally {
    riskAssessmentWordExportBusy = false;
    syncRiskAssessmentDocumentExportControls();
    if (loading) {
      window.setTimeout(() => {
        loading.close();
      }, 340);
    }
  }
}

async function queueRiskAssessmentForDigitalSignature() {
  if (!state.riskAssessmentEditorOpen && !riskAssessmentIdInput?.value && !riskAssessmentCompanyInput?.value) {
    throw new Error("Otvori procjenu koju želiš poslati na digitalni potpis.");
  }

  const workOrderId = String(riskAssessmentWorkOrderInput?.value || "").trim();
  if (!workOrderId) {
    throw new Error("Procjena mora biti povezana s RN-om da bi ušla u postojeći Signatures red.");
  }

  const signatureItems = buildRiskAssessmentDigitalSignatureItems();
  if (signatureItems.length === 0) {
    throw new Error("Odaberi voditelja/člana iz People modula ili suradnika s upisanim OIB-om za digitalni potpis.");
  }

  const saved = await saveRiskAssessmentEditorAutosave({ manual: true });
  if (!saved && !riskAssessmentIdInput?.value) {
    throw new Error("Procjena nije spremljena, zato je ne mogu poslati na potpis.");
  }

  const templateDocument = getRiskAssessmentTemplateDocumentForExport();
  const fileName = `${getRiskAssessmentExportFileBaseName()}.pdf`;
  const placeholders = buildRiskAssessmentExportPlaceholders();
  setInlineMessage(getRiskAssessmentExportFeedbackTarget(), "Pripremam PDF procjene za digitalni potpis...", "success");

  const payload = await apiRequest("/risk-assessments/save-pdf", {
    method: "POST",
    body: {
      templateDocument,
      placeholders,
      fileName,
      workOrderId,
      assessmentId: riskAssessmentIdInput?.value || "",
      assessmentNumber: riskAssessmentNumberInput?.value || "",
      signatureSettings: getPdfSignatureExportSettings(),
    },
  });

  if (payload?.item) {
    upsertDocumentsExplorerWorkOrderDocuments([payload.item]);
  }
  if (payload?.record) {
    upsertDocumentsExplorerRecord(payload.record);
  }
  state.documentsExplorer.loaded = true;
  renderNotifications();
  if (state.activeView === "module" && state.activeModuleItem === "signatures") {
    renderSignaturesModule();
  }

  const signerLabel = signatureItems
    .map((item) => [item.name, item.role].filter(Boolean).join(" · "))
    .join(", ");
  setInlineMessage(
    getRiskAssessmentExportFeedbackTarget(),
    `Procjena je spremljena u RN Documents i čeka digitalni potpis. Potpisnici: ${signerLabel}.`,
    "success",
  );
}

async function uploadRiskAssessmentWordTemplateFile(file) {
  if (!(file instanceof File)) {
    return;
  }
  const extension = String(file.name || "").split(".").pop()?.toLowerCase() || "";
  if (!["docx", "dotx"].includes(extension)) {
    setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), "Word template mora biti .docx ili .dotx dokument.", "error");
    return;
  }
  if (riskAssessmentTemplateWordUploadButton) {
    riskAssessmentTemplateWordUploadButton.disabled = true;
    riskAssessmentTemplateWordUploadButton.classList.add("is-loading");
  }
  try {
    const dataUrl = await readFileAsDataUrl(file, `Ne mogu učitati Word template ${file.name}.`);
    riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft({
      ...riskAssessmentReportTemplateDraft,
      wordTemplate: {
        fileName: file.name,
        fileType: file.type || "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        fileSize: file.size || 0,
        dataUrl,
        uploadedAt: new Date().toISOString(),
      },
      updatedAt: new Date().toISOString(),
    });
    renderRiskAssessmentTemplateBuilder();
    await persistRiskAssessmentModuleTemplate({ immediate: true, silent: false });
    if (state.riskAssessmentEditorOpen) {
      scheduleRiskAssessmentDraftAutosave();
    }
    renderRiskAssessmentOverview();
    setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), `Word template "${file.name}" je postavljen kao globalni template modula.`, "success");
  } catch (error) {
    setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), error?.message || "Ne mogu učitati Word template.", "error");
  } finally {
    if (riskAssessmentTemplateWordUploadButton) {
      riskAssessmentTemplateWordUploadButton.disabled = !getCanManageRiskAssessments();
      riskAssessmentTemplateWordUploadButton.classList.remove("is-loading");
    }
    if (riskAssessmentTemplateWordFileInput) {
      riskAssessmentTemplateWordFileInput.value = "";
    }
  }
}

function removeRiskAssessmentWordTemplate() {
  const wordTemplate = riskAssessmentReportTemplateDraft?.wordTemplate;
  if (!wordTemplate?.fileName && !wordTemplate?.dataUrl) {
    return;
  }
  riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft({
    ...riskAssessmentReportTemplateDraft,
    wordTemplate: null,
    updatedAt: new Date().toISOString(),
  });
  renderRiskAssessmentTemplateBuilder();
  void persistRiskAssessmentModuleTemplate({ immediate: true, silent: false });
  if (state.riskAssessmentEditorOpen) {
    scheduleRiskAssessmentDraftAutosave();
  }
  setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), "Word template je maknut iz globalnog templatea.", "success");
}

function getRiskAssessmentTemplateSectionIndex(element) {
  const row = element?.closest?.("[data-risk-template-section-index]");
  const index = Number(row?.dataset?.riskTemplateSectionIndex);
  return Number.isInteger(index) && index >= 0 ? index : -1;
}

function getRiskAssessmentTemplatePlaceholderOptions(selectedKey = "") {
  return RISK_ASSESSMENT_TEMPLATE_PLACEHOLDERS.map((placeholder) => `
    <option value="${escapeHtml(placeholder.key)}"${placeholder.key === selectedKey ? " selected" : ""}>${escapeHtml(placeholder.label)}</option>
  `).join("");
}

function getRiskAssessmentTemplatePresetOptions(selectedValue = "complete") {
  return RISK_ASSESSMENT_TEMPLATE_PRESETS.map((preset) => `
    <option value="${escapeHtml(preset.id)}"${preset.id === selectedValue ? " selected" : ""}>${escapeHtml(preset.label)}</option>
  `).join("");
}

function renderRiskAssessmentTemplateSections() {
  if (!riskAssessmentTemplateSectionsList) {
    return;
  }
  const template = riskAssessmentReportTemplateDraft || createRiskAssessmentReportTemplateDraft();
  if (!template.sections.length) {
    riskAssessmentTemplateSectionsList.innerHTML = `<p class="inline-help">Dodaj barem jedan odjeljak templatea.</p>`;
    return;
  }
  riskAssessmentTemplateSectionsList.innerHTML = template.sections.map((section, index) => {
    const placeholder = getRiskAssessmentTemplatePlaceholder(section.key);
    return `
      <article class="risk-assessment-template-section-card" data-risk-template-section-index="${index}">
        <div class="risk-assessment-template-section-order">
          <strong>${String(index + 1).padStart(2, "0")}</strong>
          <span>${escapeHtml(section.placeholder || placeholder.token)}</span>
        </div>
        <div class="risk-assessment-template-section-main">
          <div class="risk-assessment-template-section-grid">
            <label><span>Placeholder odjeljak</span><select data-risk-template-section-field="key">${getRiskAssessmentTemplatePlaceholderOptions(section.key)}</select></label>
            <label><span>Naslov u dokumentu</span><input data-risk-template-section-field="title" value="${escapeHtml(section.title || placeholder.defaultTitle)}" /></label>
            <label class="field-span-full"><span>Napomena za template</span><input data-risk-template-section-field="note" value="${escapeHtml(section.note || "")}" placeholder="npr. obavezno nakon općeg dijela" /></label>
          </div>
          <div class="risk-assessment-template-section-flags">
            <label><input type="checkbox" data-risk-template-section-field="enabled" ${section.enabled ? "checked" : ""} /> Uključi</label>
            <label><input type="checkbox" data-risk-template-section-field="pageBreakBefore" ${section.pageBreakBefore ? "checked" : ""} /> Nova stranica prije</label>
            <label><input type="checkbox" data-risk-template-section-field="includeInToc" ${section.includeInToc ? "checked" : ""} /> U sadržaj</label>
          </div>
        </div>
        <div class="risk-assessment-template-section-actions">
          <button type="button" class="ghost-button" data-risk-template-copy-token="${escapeHtml(section.placeholder || placeholder.token)}">Token</button>
          <button type="button" class="ghost-button" data-risk-template-section-up="${index}" ${index === 0 ? "disabled" : ""}>Gore</button>
          <button type="button" class="ghost-button" data-risk-template-section-down="${index}" ${index === template.sections.length - 1 ? "disabled" : ""}>Dolje</button>
          <button type="button" class="ghost-button card-danger" data-risk-template-section-remove="${index}">Ukloni</button>
        </div>
      </article>
    `;
  }).join("");
}

function renderRiskAssessmentTemplateBuilder() {
  riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft(riskAssessmentReportTemplateDraft || {});
  if (riskAssessmentTemplateTitleInput && riskAssessmentTemplateTitleInput.value !== riskAssessmentReportTemplateDraft.title) {
    riskAssessmentTemplateTitleInput.value = riskAssessmentReportTemplateDraft.title;
  }
  if (riskAssessmentTemplateDescriptionInput && riskAssessmentTemplateDescriptionInput.value !== riskAssessmentReportTemplateDraft.description) {
    riskAssessmentTemplateDescriptionInput.value = riskAssessmentReportTemplateDraft.description;
  }
  if (riskAssessmentTemplatePresetSelect && !riskAssessmentTemplatePresetSelect.children.length) {
    riskAssessmentTemplatePresetSelect.innerHTML = getRiskAssessmentTemplatePresetOptions("complete");
  }
  renderRiskAssessmentTemplateSections();
  renderRiskAssessmentTemplatePlaceholderList();
  renderRiskAssessmentTemplateWordMeta();
  syncRiskAssessmentTemplatePanelAccess();
  renderRiskAssessmentDocumentRoutingControls();
  renderRiskAssessmentTemplatePreview();
}

function addRiskAssessmentTemplateSection() {
  const template = riskAssessmentReportTemplateDraft || createRiskAssessmentReportTemplateDraft();
  const used = new Set(template.sections.map((section) => section.key));
  const nextPlaceholder = RISK_ASSESSMENT_TEMPLATE_PLACEHOLDERS.find((placeholder) => !used.has(placeholder.key))
    || RISK_ASSESSMENT_TEMPLATE_PLACEHOLDERS[0];
  riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft({
    ...template,
    sections: [
      ...template.sections,
      createRiskAssessmentTemplateSectionDraft({ key: nextPlaceholder.key }, template.sections.length),
    ],
  });
  renderRiskAssessmentTemplateBuilder();
  persistRiskAssessmentModuleTemplate();
  scheduleRiskAssessmentDraftAutosave();
}

function applyRiskAssessmentTemplatePreset(presetId = "complete") {
  const preset = RISK_ASSESSMENT_TEMPLATE_PRESETS.find((entry) => entry.id === presetId) || RISK_ASSESSMENT_TEMPLATE_PRESETS[0];
  riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft({
    ...riskAssessmentReportTemplateDraft,
    title: riskAssessmentTemplateTitleInput?.value || preset.label,
    description: preset.description,
    sections: preset.sections.map((key, index) => ({ key, order: index + 1 })),
  });
  renderRiskAssessmentTemplateBuilder();
  persistRiskAssessmentModuleTemplate();
  if (state.riskAssessmentEditorOpen) {
    scheduleRiskAssessmentDraftAutosave();
  }
  setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), `Primijenjen je template: ${preset.label}.`, "success");
}

function updateRiskAssessmentTemplateSection(index, patch = {}) {
  const template = riskAssessmentReportTemplateDraft || createRiskAssessmentReportTemplateDraft();
  if (!template.sections[index]) {
    return;
  }
  const nextSections = template.sections.map((section, sectionIndex) => {
    if (sectionIndex !== index) {
      return section;
    }
    const merged = { ...section, ...patch };
    const placeholder = getRiskAssessmentTemplatePlaceholder(merged.key);
    return {
      ...merged,
      key: placeholder.key,
      placeholder: placeholder.token,
      title: patch.key && !patch.title ? placeholder.defaultTitle : merged.title,
    };
  });
  riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft({ ...template, sections: nextSections });
  renderRiskAssessmentTemplatePreview();
  persistRiskAssessmentModuleTemplate();
  scheduleRiskAssessmentDraftAutosave();
}

function moveRiskAssessmentTemplateSection(index, direction) {
  const template = riskAssessmentReportTemplateDraft || createRiskAssessmentReportTemplateDraft();
  const target = index + direction;
  if (index < 0 || target < 0 || target >= template.sections.length) {
    return;
  }
  const nextSections = [...template.sections];
  [nextSections[index], nextSections[target]] = [nextSections[target], nextSections[index]];
  riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft({ ...template, sections: nextSections });
  renderRiskAssessmentTemplateBuilder();
  persistRiskAssessmentModuleTemplate();
  scheduleRiskAssessmentDraftAutosave();
}

function removeRiskAssessmentTemplateSection(index) {
  const template = riskAssessmentReportTemplateDraft || createRiskAssessmentReportTemplateDraft();
  riskAssessmentReportTemplateDraft = createRiskAssessmentReportTemplateDraft({
    ...template,
    sections: template.sections.filter((_, sectionIndex) => sectionIndex !== index),
  });
  renderRiskAssessmentTemplateBuilder();
  persistRiskAssessmentModuleTemplate();
  scheduleRiskAssessmentDraftAutosave();
}

function handleRiskAssessmentTemplateSectionsInput(event) {
  const target = event.target;
  if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement)) {
    return;
  }
  const index = getRiskAssessmentTemplateSectionIndex(target);
  if (index < 0) {
    return;
  }
  const field = target.dataset.riskTemplateSectionField;
  if (!field) {
    return;
  }
  updateRiskAssessmentTemplateSection(index, {
    [field]: target instanceof HTMLInputElement && target.type === "checkbox" ? target.checked : target.value,
  });
  if (field === "key") {
    renderRiskAssessmentTemplateSections();
  }
}

function handleRiskAssessmentTemplateSectionsClick(event) {
  const copyButton = event.target?.closest?.("[data-risk-template-copy-token]");
  if (copyButton) {
    event.preventDefault();
    const token = copyButton.dataset.riskTemplateCopyToken || "";
    const clipboardWrite = navigator.clipboard?.writeText?.(token);
    if (clipboardWrite?.then) {
      void clipboardWrite.then(() => {
        setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), `Kopiran placeholder ${token}.`, "success");
      }).catch(() => {
        setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), token, "success");
      });
    } else {
      setInlineMessage(getRiskAssessmentTemplateFeedbackTarget(), token, "success");
    }
    return;
  }
  const upButton = event.target?.closest?.("[data-risk-template-section-up]");
  if (upButton) {
    event.preventDefault();
    moveRiskAssessmentTemplateSection(Number(upButton.dataset.riskTemplateSectionUp), -1);
    return;
  }
  const downButton = event.target?.closest?.("[data-risk-template-section-down]");
  if (downButton) {
    event.preventDefault();
    moveRiskAssessmentTemplateSection(Number(downButton.dataset.riskTemplateSectionDown), 1);
    return;
  }
  const removeButton = event.target?.closest?.("[data-risk-template-section-remove]");
  if (removeButton) {
    event.preventDefault();
    removeRiskAssessmentTemplateSection(Number(removeButton.dataset.riskTemplateSectionRemove));
  }
}

function renderRiskAssessmentDocumentParagraphs(text = "", fallback = "Nije uneseno.") {
  const lines = splitRiskAssessmentTextLines(text);
  if (lines.length === 0) {
    return `<p class="is-muted">${escapeHtml(fallback)}</p>`;
  }
  return lines.map((line) => `<p>${escapeHtml(line)}</p>`).join("");
}

function renderRiskAssessmentDocumentBullets(text = "", fallback = "Nije uneseno.") {
  const lines = splitRiskAssessmentTextLines(text);
  if (lines.length === 0) {
    return `<p class="is-muted">${escapeHtml(fallback)}</p>`;
  }
  return `<ul>${lines.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul>`;
}

