function getRiskAssessmentPpeIconClass(ppe = {}) {
  const id = String(ppe.id || "");
  const bodyPart = String(ppe.bodyPart || "item");
  if (id.includes("face") || id.includes("goggles")) return "eyes";
  if (id.includes("respirator") || id.includes("filter")) return "respiratory";
  if (id.includes("gloves")) return "hands";
  if (id.includes("shoes")) return "feet";
  if (id.includes("harness")) return "fall";
  return bodyPart || "item";
}

function renderRiskAssessmentPpeBodyPartOptions(selectedValue = "other") {
  return RISK_ASSESSMENT_PPE_BODY_FILTERS
    .filter((filter) => filter.value !== "all")
    .map((filter) => `
      <option value="${escapeHtml(filter.value)}" ${String(selectedValue || "other") === filter.value ? "selected" : ""}>
        ${escapeHtml(filter.label)}
      </option>
    `).join("");
}

function getRiskAssessmentPpeNewDraft(job = {}) {
  const draft = job.ppeNewDraft && typeof job.ppeNewDraft === "object" ? job.ppeNewDraft : {};
  return {
    name: String(draft.name || ""),
    category: String(draft.category || ""),
    bodyPart: String(draft.bodyPart || "other"),
    norm: String(draft.norm || ""),
    standardCode: String(draft.standardCode || ""),
    description: String(draft.description || ""),
    imageUrl: String(draft.imageUrl || ""),
  };
}

function getRiskAssessmentPpeBodyPartLabel(bodyPart = "other") {
  return RISK_ASSESSMENT_PPE_BODY_FILTERS.find((filter) => filter.value === bodyPart)?.label || "Ostalo";
}

function getRiskAssessmentPpeWorkerGearKind(item = {}) {
  const normalized = normalizeRiskPpeCatalogItem(item);
  const bodyPart = normalized.bodyPart || "other";
  const text = normalizeRiskAssessmentPpeSearchValue([
    normalized.id,
    normalized.catalogId,
    normalized.name,
    normalized.category,
    normalized.norm,
    normalized.standardCode,
    normalized.description,
  ].join(" "));
  const zoneRule = getRiskAssessmentPpeWorkerZoneRule(text);

  if (zoneRule?.bodyPart === "hearing") {
    return text.includes("cepic") || text.includes("earplug") ? "earplugs" : "earmuffs";
  }
  if (zoneRule?.bodyPart === "eyes") {
    return text.includes("vizir") || text.includes("stitnik lica") || text.includes("face shield") ? "faceShield" : "glasses";
  }
  if (zoneRule?.kind) {
    return zoneRule.kind;
  }

  if (text.includes("earmuff") || text.includes("antifon") || text.includes("usne skoljke") || text.includes("stitnici sluha") || text.includes("zastita sluha") || text.includes("en 352")) {
    return text.includes("cepic") || text.includes("earplug") ? "earplugs" : "earmuffs";
  }
  if (text.includes("vizir") || text.includes("stitnik lica") || text.includes("stitnik za lice") || text.includes("face shield")) {
    return "faceShield";
  }
  if (text.includes("respirator") || text.includes("aparat") || text.includes("boca") || text.includes("izolacij")) {
    return "respirator";
  }
  if (text.includes("maska") || text.includes("polumaska")) {
    return "mask";
  }
  if (bodyPart === "head") {
    return text.includes("kapa") || text.includes("kapuljaca") || text.includes("hood") ? "cap" : "helmet";
  }
  if (bodyPart === "eyes") {
    return "glasses";
  }
  if (bodyPart === "hearing") {
    return "earmuffs";
  }
  if (bodyPart === "respiratory") {
    return text.includes("aparat") || text.includes("boca") || text.includes("scba") ? "respirator" : "mask";
  }
  if (bodyPart === "hands") {
    return "gloves";
  }
  if (bodyPart === "feet") {
    return "boots";
  }
  if (bodyPart === "fall") {
    return "harness";
  }
  if (bodyPart === "body") {
    if (text.includes("prsluk") || text.includes("reflektir")) {
      return "vest";
    }
    if (text.includes("odijelo") || text.includes("kombinezon") || text.includes("odjeca") || text.includes("pregaca") || text.includes("hlace")) {
      return "coverall";
    }
    return "vest";
  }
  return "kneepads";
}

function getRiskAssessmentPpeWorkerGearItems(ppeItems = []) {
  const byKind = new Map();
  (ppeItems ?? []).forEach((item) => {
    const normalized = normalizeRiskPpeCatalogItem(item);
    const kind = getRiskAssessmentPpeWorkerGearKind(normalized);
    if (!byKind.has(kind)) {
      byKind.set(kind, {
        kind,
        label: RISK_ASSESSMENT_PPE_WORKER_GEAR_LABELS[kind] || normalized.name || "OZO",
        part: normalized.bodyPart || "other",
      });
    }
  });

  RISK_ASSESSMENT_PPE_WORKER_EXCLUSIVE_GEAR.forEach(([primary, secondary]) => {
    if (byKind.has(primary) && byKind.has(secondary)) {
      byKind.delete(secondary);
    }
  });

  return RISK_ASSESSMENT_PPE_WORKER_GEAR_ORDER
    .filter((kind) => byKind.has(kind))
    .map((kind) => byKind.get(kind));
}

function normalizeRiskAssessmentPpeWorkerVariantKind(kind = "") {
  if (kind === "cap") {
    return "helmet";
  }
  if (kind === "mask") {
    return "respirator";
  }
  if (kind === "coverall") {
    return "vest";
  }
  if (kind === "harness" || kind === "kneepads" || kind === "boots") {
    return null;
  }
  return kind;
}

function getRiskAssessmentPpeWorkerVariant(gearItems = []) {
  const wanted = new Set((gearItems ?? [])
    .map((gear) => normalizeRiskAssessmentPpeWorkerVariantKind(gear.kind))
    .filter(Boolean));
  if (!wanted.size) {
    return RISK_ASSESSMENT_PPE_WORKER_VARIANTS[0];
  }

  let bestVariant = RISK_ASSESSMENT_PPE_WORKER_VARIANTS[0];
  let bestScore = Number.NEGATIVE_INFINITY;
  RISK_ASSESSMENT_PPE_WORKER_VARIANTS.forEach((variant) => {
    let overlap = 0;
    let missing = 0;
    let extras = 0;
    wanted.forEach((kind) => {
      if (variant.gearSet.has(kind)) {
        overlap += 1;
      } else {
        missing += 1;
      }
    });
    variant.gearSet.forEach((kind) => {
      if (!wanted.has(kind)) {
        extras += 1;
      }
    });
    const exactBonus = missing === 0 && extras === 0 ? 24 : 0;
    const fullBonus = wanted.size >= 5 && variant.id === "full" ? 12 : 0;
    const score = overlap * 14 - missing * 9 - extras * 4 + exactBonus + fullBonus;
    if (score > bestScore) {
      bestScore = score;
      bestVariant = variant;
    }
  });
  return bestVariant;
}

function getRiskAssessmentPpeWorkerOverlayClass(kind = "") {
  if (kind === "helmet" || kind === "cap") {
    return "head";
  }
  if (kind === "faceShield" || kind === "glasses") {
    return "eyes";
  }
  if (kind === "earmuffs") {
    return "hearing";
  }
  if (kind === "mask" || kind === "respirator") {
    return "respiratory";
  }
  if (kind === "vest" || kind === "coverall") {
    return "body";
  }
  if (kind === "gloves") {
    return "hands";
  }
  if (kind === "boots") {
    return "feet";
  }
  if (kind === "harness") {
    return "fall";
  }
  if (kind === "kneepads") {
    return "knees";
  }
  return "other";
}

function getRiskAssessmentPpeWorkerOverlayGear(gearItems = [], workerVariant = {}) {
  const seenOverlayClasses = new Set();
  return (gearItems ?? []).filter((gear) => {
    const overlayClass = getRiskAssessmentPpeWorkerOverlayClass(gear.kind);
    const key = `${overlayClass}:${gear.part || "other"}`;
    if (seenOverlayClasses.has(key)) {
      return false;
    }
    seenOverlayClasses.add(key);
    return true;
  });
}

function renderRiskAssessmentPpeWorkerPreview(job = {}) {
  const selectedItems = job.ppeItems ?? [];
  const gearItems = getRiskAssessmentPpeWorkerGearItems(selectedItems);
  const workerVariant = getRiskAssessmentPpeWorkerVariant(gearItems);
  const activeParts = Array.from(new Set(gearItems.map((gear) => gear.part || "other")));
  const selectedCount = selectedItems.length;
  const gearLabels = gearItems.length
    ? gearItems.slice(0, 7).map((gear) => gear.label)
    : ["Bez odabrane OZO"];

  return `
    <section class="risk-assessment-ppe-worker-preview ozo-worker-panel" aria-label="Prikaz radnika s odabranom OZO">
      <div class="ozo-worker-hero is-ai">
        <div class="ozo-worker-stage-copy">
          <span>AI realistic worker preview</span>
          <strong>Radnici i oprema prema odabiru</strong>
        </div>
        <div class="ozo-stage-tags" aria-label="Aktivne zone zaštite">
          ${gearLabels.map((label) => `<span>${escapeHtml(label)}</span>`).join("")}
        </div>
        <div class="ozo-worker-image-wrap" data-ozo-worker-variant="${escapeHtml(workerVariant.id)}">
          <img
            class="ozo-ai-worker-image"
            src="${escapeHtml(workerVariant.src)}"
            alt="Muški i ženski industrijski radnik s odabranom osobnom zaštitnom opremom"
            loading="eager"
          />
          <div class="ozo-worker-image-sheen" aria-hidden="true"></div>
        </div>
      </div>
      <div class="ozo-worker-summary">
        <div>
          <span>OZO status</span>
          <strong>${escapeHtml(selectedCount ? `${selectedCount} odabrano` : "Bez OZO")}</strong>
        </div>
        <div>
          <span>Prikaz radnika</span>
          <strong>${escapeHtml(workerVariant.label)}</strong>
        </div>
        <div>
          <span>Zone zaštite</span>
          <strong>${escapeHtml(activeParts.length ? activeParts.map((part) => getRiskAssessmentPpeBodyPartLabel(part)).join(", ") : "Nije odabrano")}</strong>
        </div>
      </div>
      <div class="ozo-worker-selected-strip">
        ${selectedItems.slice(0, 5).map((item) => `<span>${escapeHtml(item.name || "OZO")}</span>`).join("")}
      </div>
    </section>
  `;
}

function OzoStepHeader(job = {}, jobIndex = 0) {
  const newFormOpen = Boolean(job.ppeNewOpen);
  return `
    <header class="ozo-step-header">
      <span class="ozo-step-icon" aria-hidden="true">${renderRiskAssessmentRiskIcon("shield")}</span>
      <div>
        <span>Završni korak / OZO</span>
        <strong>Osobna zaštitna oprema (OZO)</strong>
        <small>Odaberi opremu iz kataloga ili dodaj novu stavku. Ovaj blok završava obradu radnog mjesta u procjeni.</small>
      </div>
      <button type="button" class="ozo-primary-action" data-risk-ppe-new-toggle>${newFormOpen ? "Zatvori unos" : "+ Nova OZO"}</button>
    </header>
  `;
}

function OzoWorkerPreview(job = {}) {
  const selectedItems = job.ppeItems ?? [];
  const gearItems = getRiskAssessmentPpeWorkerGearItems(selectedItems);
  const workerVariant = getRiskAssessmentPpeWorkerVariant(gearItems);
  const activeParts = Array.from(new Set(gearItems.map((gear) => gear.part || "other")));
  const selectedCount = selectedItems.length;
  const zoneLabel = activeParts.length
    ? activeParts.map((part) => getRiskAssessmentPpeBodyPartLabel(part)).join(", ")
    : "Nije odabrano";

  return `
    <aside class="ozo-worker-card" aria-label="AI realistic worker preview">
      <div class="ozo-worker-card-head">
        <span>AI realistic worker preview</span>
        <strong>Radnici i oprema</strong>
        <small>Prikaz radnika s odabranom OZO</small>
        <em>${escapeHtml(selectedCount ? `${selectedCount} odabrano` : "Bez odabrane OZO")}</em>
      </div>
      <div class="ozo-worker-visual" data-ozo-worker-variant="${escapeHtml(workerVariant.id)}">
        <img src="${escapeHtml(workerVariant.src)}" alt="Industrijski radnici s osobnom zaštitnom opremom" loading="eager" />
      </div>
      <dl class="ozo-worker-status">
        <div>
          <dt>OZO status</dt>
          <dd>${escapeHtml(selectedCount ? `${selectedCount} stavki` : "Bez OZO")}</dd>
        </div>
        <div>
          <dt>Prikaz radnika</dt>
          <dd>${escapeHtml(workerVariant.label)}</dd>
        </div>
        <div>
          <dt>Zone zaštite</dt>
          <dd>${escapeHtml(zoneLabel)}</dd>
        </div>
      </dl>
      <article class="ozo-system-advice">
        <span aria-hidden="true">${renderRiskAssessmentRiskIcon("shield")}</span>
        <strong>Savjet sustava</strong>
        <p>Odaberi opremu koja odgovara identificiranim opasnostima na radnom mjestu za potpunu zaštitu.</p>
      </article>
    </aside>
  `;
}

function OzoCategoryFilters(job = {}, catalog = []) {
  const activeFilter = String(job.ppeFilter || "all");
  const searchValue = String(job.ppeSearch || "");
  const countByBodyPart = RISK_ASSESSMENT_PPE_BODY_FILTERS.reduce((accumulator, filter) => {
    accumulator[filter.value] = filter.value === "all"
      ? catalog.length
      : catalog.filter((item) => item.bodyPart === filter.value).length;
    return accumulator;
  }, {});
  return `
    <section class="ozo-filter-shell">
      <div class="ozo-category-filters" aria-label="Filter OZO kategorija">
        ${RISK_ASSESSMENT_PPE_BODY_FILTERS.map((filter) => `
          <button type="button"
            class="ozo-category-chip ${activeFilter === filter.value ? "is-active" : ""}"
            data-risk-ppe-filter="${escapeHtml(filter.value)}">
            <span>${escapeHtml(filter.label)}</span>
            <small>${escapeHtml(String(countByBodyPart[filter.value] || 0))}</small>
          </button>
        `).join("")}
      </div>
      <label class="ozo-search-field">
        <span>Pretraži katalog</span>
        <input data-risk-ppe-search value="${escapeHtml(searchValue)}" placeholder="Pretraži katalog..." />
        <i aria-hidden="true">${renderRiskAssessmentRiskIcon("note")}</i>
      </label>
    </section>
  `;
}

function OzoNewItemForm(job = {}) {
  const newDraft = getRiskAssessmentPpeNewDraft(job);
  const newFormOpen = Boolean(job.ppeNewOpen);
  return `
    <section class="ozo-new-form" ${newFormOpen ? "" : "hidden"}>
      <label><span>Naziv</span><input data-risk-ppe-new-field="name" value="${escapeHtml(newDraft.name)}" placeholder="npr. Štitnik za koljena" /></label>
      <label><span>Norma</span><input data-risk-ppe-new-field="norm" value="${escapeHtml(newDraft.norm)}" placeholder="npr. HRN EN 14404" /></label>
      <label><span>Kategorija</span><input data-risk-ppe-new-field="category" value="${escapeHtml(newDraft.category)}" placeholder="npr. Zaštita nogu" /></label>
      <label><span>Dio tijela</span><select data-risk-ppe-new-field="bodyPart">${renderRiskAssessmentPpeBodyPartOptions(newDraft.bodyPart)}</select></label>
      <label><span>EN norma</span><input data-risk-ppe-new-field="standardCode" value="${escapeHtml(newDraft.standardCode)}" placeholder="npr. EN 14404" /></label>
      <label><span>URL slike</span><input data-risk-ppe-new-field="imageUrl" value="${escapeHtml(newDraft.imageUrl)}" placeholder="https://..." /></label>
      <label class="field-span-full"><span>Opis primjene</span><textarea data-risk-ppe-new-field="description" rows="2">${escapeHtml(newDraft.description)}</textarea></label>
      <div class="ozo-new-form-actions">
        <span>Spremi u bazu i odmah dodaj na ovo radno mjesto.</span>
        <button type="button" class="ozo-primary-action" data-risk-ppe-new-save>Spremi OZO</button>
      </div>
    </section>
  `;
}

function OzoCatalogList(job = {}, jobIndex = 0, catalog = []) {
  const selectedSet = getRiskAssessmentSelectedPpeSet(job);
  const activeFilter = String(job.ppeFilter || "all");
  const searchValue = String(job.ppeSearch || "");
  const visibleCatalogItems = filterRiskAssessmentPpeCatalogItems(catalog, activeFilter, searchValue);
  const visibleCatalogIds = new Set(visibleCatalogItems.map((item) => String(item.id)));
  return `
    <section class="ozo-catalog-card">
      <div class="ozo-card-head">
        <div>
          <strong>Katalog OZO</strong>
          <small><b data-risk-ppe-match-count>${visibleCatalogItems.length}</b> prikazanih stavki</small>
        </div>
        <div class="ozo-card-actions">
          <a href="${escapeHtml(RISK_PPE_SOURCE_URL)}" target="_blank" rel="noopener noreferrer">NN 110/2009</a>
          <select aria-label="Sortiranje OZO kataloga">
            <option>Najnovije</option>
            <option>Naziv A-Z</option>
            <option>Kategorija</option>
          </select>
        </div>
      </div>
      <div class="ozo-catalog-list">
        ${catalog.map((ppe) => {
          const searchText = normalizeRiskAssessmentPpeSearchValue([
            ppe.name,
            ppe.category,
            ppe.norm,
            ppe.standardCode,
            ppe.description,
            ppe.sourceRef,
          ].join(" "));
          const isVisible = visibleCatalogIds.has(String(ppe.id));
          const isSelected = selectedSet.has(ppe.id);
          const iconUrl = ppe.iconUrl || RISK_PPE_CATEGORY_ICONS[ppe.bodyPart] || RISK_PPE_CATEGORY_ICONS.other || "";
          const norm = ppe.norm || ppe.standardCode || "Norma nije upisana";
          return `
            <label class="ozo-catalog-item ${isSelected ? "is-selected" : ""}" data-risk-ppe-option-card data-risk-ppe-option-body-part="${escapeHtml(ppe.bodyPart)}" data-risk-ppe-option-search="${escapeHtml(searchText)}" title="${escapeHtml([ppe.name, norm, ppe.category].filter(Boolean).join(" · "))}" ${isVisible ? "" : "hidden"}>
              <input type="checkbox" data-risk-ppe-toggle="${escapeHtml(ppe.id)}" ${isSelected ? "checked" : ""} />
              <span class="ozo-catalog-icon"><img src="${escapeHtml(iconUrl)}" alt="" loading="lazy" /></span>
              <span class="ozo-catalog-copy">
                <strong>${escapeHtml(ppe.name)}</strong>
                <small>${escapeHtml(norm)}</small>
                <em>${escapeHtml(ppe.category || "OZO")}</em>
              </span>
              <span class="ozo-catalog-chevron" aria-hidden="true">&rsaquo;</span>
            </label>
          `;
        }).join("")}
      </div>
      <p class="inline-help risk-assessment-ppe-empty" ${visibleCatalogItems.length ? "hidden" : ""}>Nema OZO stavki za odabrani filter ili pretragu.</p>
    </section>
  `;
}

function getOzoQuickSummaryMetrics(job = {}) {
  const selectedItems = job.ppeItems ?? [];
  const selectedBodyParts = getRiskAssessmentPpeBodyParts(selectedItems);
  const standards = new Set(selectedItems.map((item) => item.norm || item.standardCode).filter(Boolean));
  const riskLinks = new Set(
    selectedItems
      .flatMap((item) => String(item.hazardLinks || item.description || "").split(/[,;\n]+/))
      .map((item) => item.trim())
      .filter(Boolean),
  );
  return [
    { label: "odabrane stavke", value: selectedItems.length },
    { label: "zona zaštite pokriveno", value: selectedBodyParts.size },
    { label: "standarda primijenjeno", value: standards.size },
    { label: "rizika adresirano", value: riskLinks.size },
  ];
}

function OzoQuickSummary(job = {}) {
  const metrics = getOzoQuickSummaryMetrics(job);
  return `
    <section class="ozo-quick-summary">
      <strong>Brzi pregled</strong>
      <dl>
        ${metrics.map((metric) => `
          <div>
            <dt>${renderRiskAssessmentRiskIcon("shield")}</dt>
            <dd><b>${escapeHtml(String(metric.value))}</b> ${escapeHtml(metric.label)}</dd>
          </div>
        `).join("")}
      </dl>
    </section>
  `;
}

function OzoSelectedPanel(job = {}) {
  const selectedItems = job.ppeItems ?? [];
  const selectedCount = selectedItems.length;
  const selectedBodyPartLabels = Array.from(getRiskAssessmentPpeBodyParts(selectedItems))
    .map((part) => RISK_ASSESSMENT_PPE_BODY_FILTERS.find((filter) => filter.value === part)?.label || part)
    .filter(Boolean);
  return `
    <aside class="ozo-selected-column">
      <section class="ozo-selected-card ${selectedCount ? "has-items" : "is-empty"}">
        <div class="ozo-card-head">
          <div>
            <strong>Odabrana OZO</strong>
            <small>${escapeHtml(selectedCount ? `${selectedCount} stavki · ${selectedBodyPartLabels.join(", ") || "bez kategorije"}` : "Odaberi OZO iz kataloga")}</small>
          </div>
          <span class="ozo-selected-count">${escapeHtml(String(selectedCount))}</span>
        </div>
        ${selectedItems.length ? `
          <div class="ozo-selected-list">
            ${selectedItems.map((ppe, ppeIndex) => {
              const normalized = normalizeRiskPpeCatalogItem(ppe);
              const iconUrl = normalized.iconUrl || RISK_PPE_CATEGORY_ICONS[normalized.bodyPart] || RISK_PPE_CATEGORY_ICONS.other || "";
              return `
                <article class="ozo-selected-item">
                  <span class="ozo-selected-icon"><img src="${escapeHtml(iconUrl)}" alt="" loading="lazy" /></span>
                  <div class="ozo-selected-fields">
                    <label>
                      <span>Naziv</span>
                      <input data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="name" value="${escapeHtml(ppe.name || "")}" placeholder="Naziv opreme" />
                    </label>
                    <label>
                      <span>Norma</span>
                      <input data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="norm" value="${escapeHtml(ppe.norm || "")}" placeholder="Norma" />
                    </label>
                    <label class="field-span-full">
                      <span>Primjena</span>
                      <input data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="description" value="${escapeHtml(ppe.description || "")}" placeholder="Primjena i povezana opasnost" />
                    </label>
                    <label class="ozo-selected-required">
                      <input type="checkbox" data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="required" ${ppe.required === false ? "" : "checked"} />
                      <span>Obvezna</span>
                    </label>
                  </div>
                  <button type="button" class="ghost-button card-danger" data-risk-ppe-remove="${ppeIndex}" aria-label="Ukloni OZO">Ukloni</button>
                </article>
              `;
            }).join("")}
          </div>
        ` : `
          <div class="ozo-empty-state">
            <span aria-hidden="true">${renderRiskAssessmentRiskIcon("shield")}</span>
            <strong>Ovdje će se prikazati odabrana oprema s normom i primjenom.</strong>
          </div>
        `}
      </section>
      ${OzoQuickSummary(job)}
      <button type="button" class="ozo-save-continue" data-risk-ppe-save-continue>Spremi OZO</button>
    </aside>
  `;
}

function renderRiskAssessmentPpeCompactPicker(job = {}, jobIndex = 0) {
  const catalog = getRiskAssessmentPpeCatalog();
  return `
    <div class="risk-assessment-ppe-compact ozo-premium-step" data-risk-ppe-panel="${jobIndex}">
      ${OzoStepHeader(job, jobIndex)}
      ${OzoNewItemForm(job)}
      <div class="ozo-premium-grid">
        ${OzoWorkerPreview(job)}
        <main class="ozo-main-column">
          ${OzoCategoryFilters(job, catalog)}
          ${OzoCatalogList(job, jobIndex, catalog)}
        </main>
        ${OzoSelectedPanel(job)}
      </div>
    </div>
  `;
}

function renderRiskAssessmentPpeVisualLegacy(job = {}, jobIndex = 0) {
  const selectedSet = getRiskAssessmentSelectedPpeSet(job);
  const activeFilter = String(job.ppeFilter || "all");
  const searchValue = String(job.ppeSearch || "");
  const selectedBodyParts = getRiskAssessmentPpeBodyParts(job.ppeItems ?? []);
  const selectedCatalogIds = getRiskAssessmentPpeCatalogIds(job.ppeItems ?? []);
  const catalog = getRiskAssessmentPpeCatalog();
  const visibleCatalogItems = filterRiskAssessmentPpeCatalogItems(catalog, activeFilter, searchValue);
  const visibleCatalogIds = new Set(visibleCatalogItems.map((item) => String(item.id)));
  const countByBodyPart = catalog.reduce((accumulator, item) => {
    accumulator[item.bodyPart] = (accumulator[item.bodyPart] || 0) + 1;
    return accumulator;
  }, { all: catalog.length });
  const selectedCount = job.ppeItems?.length ?? 0;
  const newDraft = getRiskAssessmentPpeNewDraft(job);
  const newFormOpen = Boolean(job.ppeNewOpen);
  const bodyPartLabel = Array.from(selectedBodyParts)
    .map((part) => RISK_ASSESSMENT_PPE_BODY_FILTERS.find((filter) => filter.value === part)?.label || part)
    .join(", ");
  const selectedPreviewItems = (job.ppeItems ?? [])
    .slice(0, 6)
    .map((item) => normalizeRiskPpeCatalogItem(item));
  return `
    <div class="risk-assessment-ppe-panel" data-risk-ppe-panel="${jobIndex}">
      <div class="risk-assessment-mini-title risk-assessment-ppe-title">
        <strong>OSOBNA ZAŠTITNA OPREMA</strong>
        <span>Zaštiti sebe. Zaštiti druge. Radi sigurno. ${selectedCount ? `${selectedCount} odabranih komada OZO.` : ""} Katalog: ${catalog.length} stvarnih OZO stavki.</span>
      </div>
      <div class="risk-assessment-ppe-toolbar">
        <label class="risk-assessment-ppe-search">
          <span>Pretraga</span>
          <input data-risk-ppe-search value="${escapeHtml(searchValue)}" placeholder="Maska, rukavice, HRN EN 397..." />
        </label>
        <a class="risk-assessment-ppe-source" href="${escapeHtml(RISK_PPE_SOURCE_URL)}" target="_blank" rel="noopener noreferrer">Narodne novine 110/2009</a>
        <button type="button" class="secondary-button" data-risk-ppe-new-toggle>${newFormOpen ? "Zatvori unos" : "+ Nova OZO"}</button>
      </div>
      <div class="risk-assessment-ppe-filters">
        ${RISK_ASSESSMENT_PPE_BODY_FILTERS.map((filter) => `
          <button type="button" class="${activeFilter === filter.value ? "is-active" : ""}" data-risk-ppe-filter="${escapeHtml(filter.value)}">
            <span>${escapeHtml(filter.label)}</span>
            <small>${countByBodyPart[filter.value] || 0}</small>
          </button>
        `).join("")}
      </div>
      <div class="risk-assessment-ppe-new-form" ${newFormOpen ? "" : "hidden"}>
        <label><span>Naziv</span><input data-risk-ppe-new-field="name" value="${escapeHtml(newDraft.name)}" placeholder="npr. Štitnik za koljena" /></label>
        <label><span>Norma</span><input data-risk-ppe-new-field="norm" value="${escapeHtml(newDraft.norm)}" placeholder="npr. HRN EN 14404" /></label>
        <label><span>Kategorija</span><input data-risk-ppe-new-field="category" value="${escapeHtml(newDraft.category)}" placeholder="npr. Zaštita nogu" /></label>
        <label><span>Dio tijela</span><select data-risk-ppe-new-field="bodyPart">${renderRiskAssessmentPpeBodyPartOptions(newDraft.bodyPart)}</select></label>
        <label><span>EN norma</span><input data-risk-ppe-new-field="standardCode" value="${escapeHtml(newDraft.standardCode)}" placeholder="npr. EN 14404" /></label>
        <label><span>URL slike</span><input data-risk-ppe-new-field="imageUrl" value="${escapeHtml(newDraft.imageUrl)}" placeholder="https://..." /></label>
        <label class="field-span-full"><span>Opis primjene</span><textarea data-risk-ppe-new-field="description" rows="2">${escapeHtml(newDraft.description)}</textarea></label>
        <div class="risk-assessment-ppe-new-actions">
          <span>Spremi u bazu i odmah dodaj na ovo radno mjesto.</span>
          <button type="button" class="primary-button" data-risk-ppe-new-save>Spremi OZO</button>
        </div>
      </div>
      <div class="risk-assessment-ppe-layout">
        <div class="risk-assessment-worker-preview" aria-label="Vizualni prikaz OZO">
          <div
            class="risk-assessment-worker-canvas"
            data-risk-ppe-scene="${jobIndex}"
            data-risk-ppe-body-parts="${escapeHtml(Array.from(selectedBodyParts).join(","))}"
            data-risk-ppe-catalog-ids="${escapeHtml(Array.from(selectedCatalogIds).join(","))}"
            aria-hidden="true"
          ></div>
          <div class="risk-assessment-worker-figure" aria-hidden="true">
            <span class="worker-shadow"></span>
            <span class="worker-head"></span>
            <span class="worker-face"></span>
            <span class="worker-neck"></span>
            <span class="worker-body"></span>
            <span class="worker-arm is-left"></span>
            <span class="worker-arm is-right"></span>
            <span class="worker-leg is-left"></span>
            <span class="worker-leg is-right"></span>
            ${selectedBodyParts.has("head") ? `<span class="ppe-layer ppe-helmet"></span>` : ""}
            ${selectedBodyParts.has("eyes") ? `<span class="ppe-layer ppe-glasses"></span>` : ""}
            ${selectedBodyParts.has("hearing") ? `<span class="ppe-layer ppe-earmuffs"></span>` : ""}
            ${selectedBodyParts.has("respiratory") ? `<span class="ppe-layer ppe-mask"></span>` : ""}
            ${selectedBodyParts.has("hands") ? `<span class="ppe-layer ppe-gloves"></span>` : ""}
            ${selectedBodyParts.has("body") ? `<span class="ppe-layer ppe-vest"></span>` : ""}
            ${selectedBodyParts.has("feet") ? `<span class="ppe-layer ppe-boots"></span>` : ""}
            ${selectedBodyParts.has("fall") ? `<span class="ppe-layer ppe-harness"></span>` : ""}
          </div>
          <div class="risk-assessment-ppe-callouts" aria-hidden="true">
            ${selectedPreviewItems.map((item, itemIndex) => `
              <span class="risk-assessment-ppe-callout is-${escapeHtml(item.bodyPart || "other")}" style="--ppe-callout-index: ${itemIndex};">
                <img src="${escapeHtml(item.iconUrl || RISK_PPE_CATEGORY_ICONS[item.bodyPart] || RISK_PPE_CATEGORY_ICONS.other || "")}" alt="" loading="lazy" />
                <b>${escapeHtml(item.name)}</b>
              </span>
            `).join("")}
          </div>
          <div class="risk-assessment-worker-preview-meta">
            <strong>${selectedCount || 0}</strong>
            <span>${escapeHtml(bodyPartLabel || "Bez OZO")}</span>
          </div>
        </div>
        <div class="risk-assessment-ppe-list-wrap">
           <div class="risk-assessment-ppe-list-head">
            <strong data-risk-ppe-match-count>${visibleCatalogItems.length}</strong>
            <span>prikazanih OZO stavki</span>
          </div>
          <div class="risk-assessment-ppe-list">
            ${catalog.map((ppe) => {
              const searchText = normalizeRiskAssessmentPpeSearchValue([
                ppe.name,
                ppe.category,
                ppe.norm,
                ppe.standardCode,
                ppe.description,
                ppe.sourceRef,
              ].join(" "));
              const isVisible = visibleCatalogIds.has(String(ppe.id));
              const isSelected = selectedSet.has(ppe.id);
              return `
            <label class="risk-assessment-ppe-option ${isSelected ? "is-selected" : ""}" data-risk-ppe-option-card data-risk-ppe-option-body-part="${escapeHtml(ppe.bodyPart)}" data-risk-ppe-option-search="${escapeHtml(searchText)}" title="${escapeHtml([ppe.name, ppe.norm, ppe.category].filter(Boolean).join(" · "))}" ${isVisible ? "" : "hidden"}>
              <input type="checkbox" data-risk-ppe-toggle="${escapeHtml(ppe.id)}" ${isSelected ? "checked" : ""} />
              <span class="risk-assessment-ppe-option-symbol">
                <img src="${escapeHtml(ppe.iconUrl || RISK_PPE_CATEGORY_ICONS[ppe.bodyPart] || RISK_PPE_CATEGORY_ICONS.other || "")}" alt="" loading="lazy" />
              </span>
              <span class="risk-assessment-ppe-option-photo">
                <img src="${escapeHtml(ppe.imageUrl || RISK_PPE_CATEGORY_IMAGES[ppe.bodyPart] || RISK_PPE_CATEGORY_IMAGES.other || "")}" alt="" loading="lazy" />
              </span>
              <span class="risk-assessment-ppe-option-copy">
                <strong>${escapeHtml(ppe.name)}</strong>
                <small>${escapeHtml([ppe.category, ppe.norm].filter(Boolean).join(" · "))}</small>
                <em>${escapeHtml(ppe.sourceRef || (ppe.isCustom ? "Korisnički unos" : "Katalog"))}</em>
              </span>
              <span class="risk-assessment-ppe-option-icon is-${escapeHtml(getRiskAssessmentPpeIconClass(ppe))}" aria-hidden="true"></span>
            </label>
              `;
            }).join("")}
          </div>
          <p class="inline-help risk-assessment-ppe-empty" ${visibleCatalogItems.length ? "hidden" : ""}>Nema OZO stavki za odabrani filter ili pretragu.</p>
        </div>
      </div>
      <div class="risk-assessment-ppe-selected">
        ${(job.ppeItems ?? []).length ? (job.ppeItems ?? []).map((ppe, ppeIndex) => `
          <div class="risk-assessment-ppe-selected-row">
            <label><span>Naziv</span><input data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="name" value="${escapeHtml(ppe.name || "")}" /></label>
            <label><span>Kategorija</span><input data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="category" value="${escapeHtml(ppe.category || "")}" /></label>
            <label><span>Dio tijela</span><input data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="bodyPart" value="${escapeHtml(ppe.bodyPart || "")}" /></label>
            <label><span>Norma</span><input data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="norm" value="${escapeHtml(ppe.norm || "")}" /></label>
            <label class="field-span-full"><span>Opis primjene</span><textarea data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="description" rows="2">${escapeHtml(ppe.description || "")}</textarea></label>
            <label><span>Za koje opasnosti</span><input data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="hazardLinks" value="${escapeHtml(ppe.hazardLinks || "")}" /></label>
            <label class="risk-assessment-checkbox-line"><input type="checkbox" data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="required" ${ppe.required === false ? "" : "checked"} /><span>Obvezna</span></label>
            <label><span>Napomena</span><input data-risk-ppe-index="${ppeIndex}" data-risk-ppe-field="note" value="${escapeHtml(ppe.note || "")}" /></label>
          </div>
        `).join("") : `<p class="inline-help">Odabrana oprema će se ovdje prikazati i na lutki.</p>`}
      </div>
    </div>
  `;
}

function renderRiskAssessmentPpeVisual(job = {}, jobIndex = 0) {
  const selectedSet = getRiskAssessmentSelectedPpeSet(job);
  const activeFilter = String(job.ppeFilter || "all");
  const searchValue = String(job.ppeSearch || "");
  const selectedBodyParts = Array.from(getRiskAssessmentPpeBodyParts(job.ppeItems ?? []));
  const catalog = getRiskAssessmentPpeCatalog();
  const countByBodyPart = RISK_ASSESSMENT_PPE_BODY_FILTERS.reduce((accumulator, filter) => {
    accumulator[filter.value] = filter.value === "all"
      ? catalog.length
      : catalog.filter((item) => item.bodyPart === filter.value).length;
    return accumulator;
  }, {});
  const catalogPayload = catalog.map((item) => ({
    ...normalizeRiskPpeCatalogItem(item),
    searchText: normalizeRiskAssessmentPpeSearchValue([
      item.name,
      item.category,
      item.norm,
      item.standardCode,
      item.description,
      item.sourceRef,
    ].join(" ")),
  }));
  const payload = {
    jobIndex,
    catalog: catalogPayload,
    filters: RISK_ASSESSMENT_PPE_BODY_FILTERS,
    counts: countByBodyPart,
    selectedIds: Array.from(selectedSet),
    selectedItems: (job.ppeItems ?? []).map((item) => normalizeRiskPpeCatalogItem(item)),
    selectedBodyParts,
    activeFilter,
    searchValue,
    newDraft: getRiskAssessmentPpeNewDraft(job),
    newFormOpen: Boolean(job.ppeNewOpen),
    sourceUrl: RISK_PPE_SOURCE_URL,
    iconFallbacks: RISK_PPE_CATEGORY_ICONS,
  };

  return `
    <div class="risk-assessment-ppe-panel ozo-react-panel" data-ozo-equipment-panel="${jobIndex}">
      <script type="application/json" data-ozo-equipment-payload>${serializeJsonForHtml(payload)}</script>
      <div class="ozo-equipment-react-root" data-ozo-equipment-root="${jobIndex}">
        <div class="ozo-loading-shell">
          <strong>OSOBNA ZAŠTITNA OPREMA</strong>
          <span>Učitavam profesionalni OZO prikaz...</span>
        </div>
      </div>
    </div>
  `;
}

function applyRiskAssessmentPpeCatalogDomFilter(jobIndex) {
  const job = riskAssessmentJobDrafts[jobIndex];
  const panel = riskAssessmentJobsList?.querySelector(`[data-risk-ppe-panel="${jobIndex}"]`);
  if (!job || !(panel instanceof HTMLElement)) {
    return;
  }

  const activeFilter = String(job.ppeFilter || "all");
  const searchText = normalizeRiskAssessmentPpeSearchValue(job.ppeSearch || "");
  let visibleCount = 0;
  panel.querySelectorAll("[data-risk-ppe-filter]").forEach((button) => {
    button.classList.toggle("is-active", button.dataset.riskPpeFilter === activeFilter);
  });
  panel.querySelectorAll("[data-risk-ppe-option-card]").forEach((card) => {
    if (!(card instanceof HTMLElement)) {
      return;
    }
    const matchesBodyPart = activeFilter === "all" || card.dataset.riskPpeOptionBodyPart === activeFilter;
    const matchesSearch = !searchText || String(card.dataset.riskPpeOptionSearch || "").includes(searchText);
    const isVisible = matchesBodyPart && matchesSearch;
    card.hidden = !isVisible;
    if (isVisible) {
      visibleCount += 1;
    }
  });
  const countElement = panel.querySelector("[data-risk-ppe-match-count]");
  if (countElement) {
    countElement.textContent = String(visibleCount);
  }
  const emptyElement = panel.querySelector(".risk-assessment-ppe-empty");
  if (emptyElement instanceof HTMLElement) {
    emptyElement.hidden = visibleCount > 0;
  }
}

function parseRiskAssessmentPpeSceneSet(value = "") {
  return new Set(String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean));
}

function loadRiskAssessmentPpeThreeModule() {
  if (!riskAssessmentPpeThreeModulePromise) {
    riskAssessmentPpeThreeModulePromise = import(RISK_ASSESSMENT_PPE_THREE_MODULE_URL);
  }
  return riskAssessmentPpeThreeModulePromise;
}

function disposeRiskAssessmentPpeScenes() {
  riskAssessmentPpeSceneObserver?.disconnect();
  riskAssessmentPpeSceneObserver = null;
  riskAssessmentPpeSceneControllers.forEach((controller) => {
    controller?.dispose?.();
  });
  riskAssessmentPpeSceneControllers.clear();
}

function loadRiskAssessmentPpeSceneHost(host) {
  if (!(host instanceof HTMLElement) || riskAssessmentPpeSceneControllers.has(host) || host.dataset.riskPpeLoading === "true") {
    return;
  }

  host.dataset.riskPpeLoading = "true";
  void loadRiskAssessmentPpeThreeModule()
    .then((THREE) => {
      if (!host.isConnected) {
        return;
      }
      const controller = createRiskAssessmentPpeThreeScene(THREE, host, {
        bodyParts: parseRiskAssessmentPpeSceneSet(host.dataset.riskPpeBodyParts || ""),
        catalogIds: parseRiskAssessmentPpeSceneSet(host.dataset.riskPpeCatalogIds || ""),
      });
      if (controller) {
        riskAssessmentPpeSceneControllers.set(host, controller);
      }
    })
    .catch(() => {
      host.closest(".risk-assessment-worker-preview")?.classList.add("is-webgl-fallback");
    })
    .finally(() => {
      delete host.dataset.riskPpeLoading;
    });
}

function initializeRiskAssessmentPpeScenes() {
  const hosts = Array.from(riskAssessmentJobsList?.querySelectorAll("[data-risk-ppe-scene]") ?? []);
  if (typeof IntersectionObserver !== "undefined") {
    riskAssessmentPpeSceneObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        const host = entry.target;
        if (!(host instanceof HTMLElement)) {
          return;
        }
        if (entry.isIntersecting) {
          loadRiskAssessmentPpeSceneHost(host);
          riskAssessmentPpeSceneControllers.get(host)?.start?.();
        } else {
          riskAssessmentPpeSceneControllers.get(host)?.stop?.();
        }
      });
    }, {
      root: null,
      rootMargin: "220px",
      threshold: 0.05,
    });
    hosts.forEach((host) => {
      if (host instanceof HTMLElement) {
        riskAssessmentPpeSceneObserver?.observe(host);
      }
    });
    return;
  }

  hosts.forEach((host) => {
    loadRiskAssessmentPpeSceneHost(host);
  });
}

function createRiskAssessmentPpeThreeScene(THREE, host, selection = {}) {
  const preview = host.closest(".risk-assessment-worker-preview");
  const bodyParts = selection.bodyParts ?? new Set();
  const catalogIds = selection.catalogIds ?? new Set();
  const hasPart = (part) => bodyParts.has(part);
  const hasCatalog = (id) => catalogIds.has(id);
  const hasAnyCatalog = (...ids) => ids.some((id) => hasCatalog(id));
  const geometries = new Set();
  const materials = new Set();
  const materialCache = new Map();

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(36, 1, 0.1, 40);
  camera.position.set(0, 0.82, 5.15);
  camera.lookAt(0, 0.72, 0);

  let renderer;
  try {
    renderer = new THREE.WebGLRenderer({
      alpha: true,
      antialias: true,
      powerPreference: "high-performance",
    });
  } catch {
    preview?.classList.add("is-webgl-fallback");
    return null;
  }

  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, window.innerWidth < 720 ? 1.35 : 1.75));
  if (THREE.SRGBColorSpace) {
    renderer.outputColorSpace = THREE.SRGBColorSpace;
  }
  host.replaceChildren(renderer.domElement);
  preview?.classList.add("is-webgl-ready");

  const group = new THREE.Group();
  group.rotation.set(0.05, -0.34, 0);
  scene.add(group);

  const ambientLight = new THREE.HemisphereLight(0xf8fbff, 0x9aa9bd, 2.1);
  scene.add(ambientLight);
  const keyLight = new THREE.DirectionalLight(0xffffff, 2.4);
  keyLight.position.set(2.8, 4.2, 3.8);
  scene.add(keyLight);
  const rimLight = new THREE.DirectionalLight(0x93c5fd, 1.3);
  rimLight.position.set(-3, 2.2, -2.2);
  scene.add(rimLight);

  function getMaterial(key, options = {}, MaterialType = THREE.MeshStandardMaterial) {
    if (materialCache.has(key)) {
      return materialCache.get(key);
    }
    const material = new MaterialType(options);
    materialCache.set(key, material);
    materials.add(material);
    return material;
  }

  function rememberGeometry(geometry) {
    geometries.add(geometry);
    return geometry;
  }

  function addMesh(geometry, material, position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1], parent = group) {
    const mesh = new THREE.Mesh(rememberGeometry(geometry), material);
    mesh.position.set(position[0], position[1], position[2]);
    mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
    mesh.scale.set(scale[0], scale[1], scale[2]);
    parent.add(mesh);
    return mesh;
  }

  function addCylinderBetween(start, end, radius, material, segments = 24, parent = group) {
    const startVector = new THREE.Vector3(start[0], start[1], start[2]);
    const endVector = new THREE.Vector3(end[0], end[1], end[2]);
    const direction = new THREE.Vector3().subVectors(endVector, startVector);
    const length = direction.length();
    if (length <= 0) {
      return null;
    }
    const mesh = new THREE.Mesh(rememberGeometry(new THREE.CylinderGeometry(radius, radius, length, segments)), material);
    mesh.position.copy(startVector).add(endVector).multiplyScalar(0.5);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize());
    parent.add(mesh);
    return mesh;
  }

  addMesh(new THREE.CircleGeometry(1.28, 72), getMaterial("floor", {
    color: 0x93c5fd,
    transparent: true,
    opacity: 0.15,
    roughness: 0.9,
    side: THREE.DoubleSide,
  }), [0, -0.68, 0], [-Math.PI / 2, 0, 0], [1.55, 0.64, 1]);

  const workerProfiles = [
    { key: "male", x: -0.44, scale: 0.94, yaw: 0.1, skin: 0xd4a17f, hair: 0x2b211d, torsoTop: 0.3, torsoBottom: 0.38, shoulder: 0.36, hip: 0.19 },
    { key: "female", x: 0.48, scale: 0.9, yaw: -0.12, skin: 0xe4b799, hair: 0x40271d, torsoTop: 0.26, torsoBottom: 0.31, shoulder: 0.32, hip: 0.16 },
  ];
  workerProfiles.forEach((profile) => buildWorkerAvatar(profile));

  function buildWorkerAvatar(profile) {
    const avatar = new THREE.Group();
    avatar.position.set(profile.x, -0.02, 0);
    avatar.rotation.y = profile.yaw;
    avatar.scale.setScalar(profile.scale);
    group.add(avatar);

    const materialSkin = getMaterial(`${profile.key}-skin`, {
      color: profile.skin,
      roughness: 0.66,
      metalness: 0.02,
    });
    const materialHair = getMaterial(`${profile.key}-hair`, {
      color: profile.hair,
      roughness: 0.72,
      metalness: 0.01,
    });
    const materialShirt = getMaterial(`${profile.key}-shirt`, {
      color: 0x172b45,
      roughness: 0.54,
      metalness: 0.03,
    });
    const materialPants = getMaterial(`${profile.key}-pants`, {
      color: 0x0f2034,
      roughness: 0.58,
      metalness: 0.03,
    });
    const materialBootBase = getMaterial(`${profile.key}-boot-base`, {
      color: 0x3b2a1d,
      roughness: 0.68,
      metalness: 0.04,
    });
    const materialEye = getMaterial(`${profile.key}-eye`, {
      color: 0x111827,
      roughness: 0.4,
      metalness: 0.02,
    });
    const materialTrim = getMaterial(`${profile.key}-trim`, {
      color: 0xf8fafc,
      emissive: 0xe0f2fe,
      emissiveIntensity: 0.12,
      roughness: 0.28,
      metalness: 0.02,
    });

    addMesh(new THREE.CircleGeometry(0.46, 48), getMaterial(`${profile.key}-shadow`, {
      color: 0x0f172a,
      transparent: true,
      opacity: 0.13,
      roughness: 0.9,
      side: THREE.DoubleSide,
    }), [0, -0.63, 0.03], [-Math.PI / 2, 0, 0], [1.05, 0.42, 1], avatar);

    addMesh(new THREE.SphereGeometry(0.22, 36, 24), materialSkin, [0, 1.61, 0.02], [0, 0, 0], [0.86, 1.02, 0.78], avatar);
    addMesh(new THREE.SphereGeometry(0.215, 32, 18), materialHair, [0, 1.64, -0.06], [0, 0, 0], [0.92, 0.84, 0.68], avatar);
    if (profile.key === "female") {
      addMesh(new THREE.SphereGeometry(0.075, 20, 14), materialHair, [0.16, 1.38, -0.1], [0, 0, -0.1], [0.9, 1.35, 0.85], avatar);
    }
    addMesh(new THREE.SphereGeometry(0.018, 12, 8), materialEye, [-0.065, 1.62, 0.19], [0, 0, 0], [1, 1, 0.55], avatar);
    addMesh(new THREE.SphereGeometry(0.018, 12, 8), materialEye, [0.065, 1.62, 0.19], [0, 0, 0], [1, 1, 0.55], avatar);
    addMesh(new THREE.BoxGeometry(0.08, 0.012, 0.012), materialEye, [0, 1.535, 0.195], [0, 0, 0], [1, 1, 1], avatar);
    addMesh(new THREE.CylinderGeometry(0.072, 0.084, 0.18, 24), materialSkin, [0, 1.36, 0.01], [0, 0, 0], [1, 1, 0.9], avatar);

    addMesh(new THREE.CylinderGeometry(profile.torsoTop, profile.torsoBottom, 0.82, 36), materialShirt, [0, 0.88, 0], [0, 0, 0], [1, 1, 0.62], avatar);
    addMesh(new THREE.SphereGeometry(0.145, 24, 16), materialShirt, [-profile.shoulder, 1.19, 0], [0, 0, 0], [0.9, 0.7, 0.76], avatar);
    addMesh(new THREE.SphereGeometry(0.145, 24, 16), materialShirt, [profile.shoulder, 1.19, 0], [0, 0, 0], [0.9, 0.7, 0.76], avatar);
    addMesh(new THREE.BoxGeometry(0.035, 0.62, 0.018), materialTrim, [-0.12, 0.92, 0.25], [0, 0, 0], [1, 1, 1], avatar);
    addMesh(new THREE.BoxGeometry(0.035, 0.62, 0.018), materialTrim, [0.12, 0.92, 0.25], [0, 0, 0], [1, 1, 1], avatar);

    addCylinderBetween([-profile.shoulder, 1.12, 0], [-0.5, 0.68, 0.04], 0.062, materialShirt, 24, avatar);
    addCylinderBetween([profile.shoulder, 1.12, 0], [0.5, 0.68, 0.04], 0.062, materialShirt, 24, avatar);
    addCylinderBetween([-0.5, 0.68, 0.04], [-0.58, 0.43, 0.08], 0.052, hasPart("hands") ? getWorkerGloveMaterial(profile.key) : materialSkin, 20, avatar);
    addCylinderBetween([0.5, 0.68, 0.04], [0.58, 0.43, 0.08], 0.052, hasPart("hands") ? getWorkerGloveMaterial(profile.key) : materialSkin, 20, avatar);
    addMesh(new THREE.SphereGeometry(0.075, 18, 12), hasPart("hands") ? getWorkerGloveMaterial(profile.key) : materialSkin, [-0.59, 0.37, 0.09], [0, 0, 0], [1.15, 0.82, 0.9], avatar);
    addMesh(new THREE.SphereGeometry(0.075, 18, 12), hasPart("hands") ? getWorkerGloveMaterial(profile.key) : materialSkin, [0.59, 0.37, 0.09], [0, 0, 0], [1.15, 0.82, 0.9], avatar);

    addCylinderBetween([-profile.hip, 0.44, 0], [-0.22, -0.43, 0.02], 0.082, materialPants, 28, avatar);
    addCylinderBetween([profile.hip, 0.44, 0], [0.22, -0.43, 0.02], 0.082, materialPants, 28, avatar);
    addWorkerBoot(profile.key, -0.22, materialBootBase, avatar);
    addWorkerBoot(profile.key, 0.22, materialBootBase, avatar);

    if (hasPart("body")) {
      addWorkerBodyProtection(profile, avatar, materialTrim);
    }
    if (hasPart("head")) {
      addWorkerHelmet(profile.key, avatar);
    }
    if (hasPart("eyes")) {
      addWorkerEyeProtection(avatar);
    }
    if (hasPart("hearing")) {
      addWorkerHearingProtection(avatar);
    }
    if (hasPart("respiratory")) {
      addWorkerRespirator(avatar);
    }
    if (hasPart("feet")) {
      addWorkerSafetyToe(-0.22, avatar);
      addWorkerSafetyToe(0.22, avatar);
    }
    if (hasPart("fall")) {
      addWorkerHarness(profile, avatar);
    }
  }

  function getWorkerGloveMaterial(key) {
    const gloveColor = hasCatalog("gloves-electrical") ? 0x7c3aed : hasCatalog("gloves-chemical") ? 0x2563eb : 0x111827;
    return getMaterial(`${key}-glove-${gloveColor}`, {
      color: gloveColor,
      roughness: 0.5,
      metalness: 0.02,
    });
  }

  function addWorkerBoot(key, x, fallbackMaterial, parent) {
    const bootMaterial = hasPart("feet")
      ? getMaterial(`${key}-safety-boot`, { color: 0x111827, roughness: 0.64, metalness: 0.06 })
      : fallbackMaterial;
    addMesh(new THREE.BoxGeometry(0.27, 0.12, 0.44), bootMaterial, [x, -0.58, 0.13], [0, x < 0 ? -0.07 : 0.07, 0], [1, 1, 1], parent);
  }

  function addWorkerSafetyToe(x, parent) {
    addMesh(new THREE.BoxGeometry(0.16, 0.04, 0.07), getMaterial("steel-toe", {
      color: 0x94a3b8,
      roughness: 0.28,
      metalness: 0.5,
    }), [x, -0.53, 0.35], [0, 0, 0], [1, 1, 1], parent);
  }

  function addWorkerBodyProtection(profile, parent, reflectiveMaterial) {
    const coverallColor = hasAnyCatalog("chemical-suit") ? 0x93c5fd : hasAnyCatalog("heat-cold") ? 0x64748b : 0xfacc15;
    if (hasAnyCatalog("chemical-suit", "protective-clothing", "heat-cold")) {
      const materialCoverall = getMaterial(`${profile.key}-coverall-${coverallColor}`, {
        color: coverallColor,
        roughness: 0.54,
        metalness: 0.04,
      });
      addMesh(new THREE.CylinderGeometry(profile.torsoTop + 0.02, profile.torsoBottom + 0.03, 0.84, 36), materialCoverall, [0, 0.87, 0.02], [0, 0, 0], [1.02, 1, 0.66], parent);
      addCylinderBetween([-profile.shoulder, 1.12, 0.02], [-0.58, 0.43, 0.06], 0.064, materialCoverall, 24, parent);
      addCylinderBetween([profile.shoulder, 1.12, 0.02], [0.58, 0.43, 0.06], 0.064, materialCoverall, 24, parent);
    } else {
      const vestMaterial = getMaterial(`${profile.key}-hi-vis-vest`, {
        color: 0xfacc15,
        roughness: 0.42,
        metalness: 0.02,
      });
      addMesh(new THREE.CylinderGeometry(profile.torsoTop + 0.025, profile.torsoBottom + 0.03, 0.64, 32, 1, true), vestMaterial, [0, 0.92, 0.03], [0, 0, 0], [1.02, 1, 0.7], parent);
      addMesh(new THREE.BoxGeometry(0.04, 0.48, 0.024), reflectiveMaterial, [-0.13, 0.93, 0.26], [0, 0, 0], [1, 1, 1], parent);
      addMesh(new THREE.BoxGeometry(0.04, 0.48, 0.024), reflectiveMaterial, [0.13, 0.93, 0.26], [0, 0, 0], [1, 1, 1], parent);
      addMesh(new THREE.BoxGeometry(0.4, 0.04, 0.024), reflectiveMaterial, [0, 0.78, 0.27], [0, 0, 0], [1, 1, 1], parent);
    }
  }

  function addWorkerHelmet(key, parent) {
    const helmetColor = hasCatalog("bump-cap") ? 0x2563eb : 0xfacc15;
    const helmetMaterial = getMaterial(`${key}-helmet-${helmetColor}`, {
      color: helmetColor,
      roughness: 0.34,
      metalness: 0.04,
    });
    addMesh(new THREE.SphereGeometry(0.25, 36, 16, 0, Math.PI * 2, 0, Math.PI / 2), helmetMaterial, [0, 1.72, 0.02], [0, 0, 0], [1, 0.72, 0.86], parent);
    addMesh(new THREE.BoxGeometry(0.38, 0.04, 0.15), helmetMaterial, [0, 1.68, 0.15], [0, 0, 0], [1, 1, 1], parent);
    addMesh(new THREE.BoxGeometry(0.035, 0.12, 0.02), getMaterial(`${key}-helmet-rib`, {
      color: 0xeab308,
      roughness: 0.36,
      metalness: 0.03,
    }), [0, 1.75, 0.2], [0, 0, 0], [1, 1, 1], parent);
  }

  function addWorkerEyeProtection(parent) {
    const lensMaterial = getMaterial("duo-goggles-lens", {
      color: 0x7dd3fc,
      transparent: true,
      opacity: 0.62,
      roughness: 0.08,
      metalness: 0.02,
      side: THREE.DoubleSide,
    }, THREE.MeshPhysicalMaterial || THREE.MeshStandardMaterial);
    const frameMaterial = getMaterial("duo-goggles-frame", {
      color: 0x0f172a,
      roughness: 0.42,
    });
    addMesh(new THREE.BoxGeometry(0.14, 0.065, 0.032), lensMaterial, [-0.08, 1.62, 0.2], [0, 0, 0], [1, 1, 1], parent);
    addMesh(new THREE.BoxGeometry(0.14, 0.065, 0.032), lensMaterial, [0.08, 1.62, 0.2], [0, 0, 0], [1, 1, 1], parent);
    addMesh(new THREE.BoxGeometry(0.34, 0.022, 0.04), frameMaterial, [0, 1.62, 0.215], [0, 0, 0], [1, 1, 1], parent);
    if (hasCatalog("face-shield")) {
      addMesh(new THREE.PlaneGeometry(0.44, 0.42), lensMaterial, [0, 1.5, 0.3], [0, 0, 0], [1, 1, 1], parent);
    }
  }

  function addWorkerHearingProtection(parent) {
    const hearingMaterial = getMaterial("duo-hearing-blue", {
      color: 0x2563eb,
      roughness: 0.34,
      metalness: 0.04,
    });
    addMesh(new THREE.TorusGeometry(0.24, 0.016, 8, 48), hearingMaterial, [0, 1.67, -0.01], [Math.PI / 2, 0, 0], [1, 0.72, 1], parent);
    addMesh(new THREE.SphereGeometry(0.085, 24, 18), hearingMaterial, [-0.22, 1.58, 0], [0, 0, 0], [0.68, 1, 0.72], parent);
    addMesh(new THREE.SphereGeometry(0.085, 24, 18), hearingMaterial, [0.22, 1.58, 0], [0, 0, 0], [0.68, 1, 0.72], parent);
  }

  function addWorkerRespirator(parent) {
    const maskMaterial = getMaterial("duo-mask", {
      color: 0xe2e8f0,
      roughness: 0.48,
      metalness: 0.02,
    });
    const filterMaterial = getMaterial("duo-mask-filter", {
      color: 0x64748b,
      roughness: 0.38,
      metalness: 0.06,
    });
    addMesh(new THREE.SphereGeometry(0.13, 28, 18), maskMaterial, [0, 1.49, 0.205], [0, 0, 0], [1, 0.62, 0.46], parent);
    addMesh(new THREE.CylinderGeometry(0.044, 0.05, 0.085, 18), filterMaterial, [-0.105, 1.48, 0.235], [Math.PI / 2, 0, 0], [1, 1, 1], parent);
    addMesh(new THREE.CylinderGeometry(0.044, 0.05, 0.085, 18), filterMaterial, [0.105, 1.48, 0.235], [Math.PI / 2, 0, 0], [1, 1, 1], parent);
  }

  function addWorkerHarness(profile, parent) {
    const harnessMaterial = getMaterial(`${profile.key}-fall-harness`, {
      color: 0xdc2626,
      roughness: 0.38,
      metalness: 0.03,
    });
    const ringMaterial = getMaterial("duo-harness-ring", {
      color: 0xf8fafc,
      roughness: 0.18,
      metalness: 0.42,
    });
    addCylinderBetween([-0.21, 1.2, 0.29], [0.17, 0.58, 0.29], 0.015, harnessMaterial, 12, parent);
    addCylinderBetween([0.21, 1.2, 0.29], [-0.17, 0.58, 0.29], 0.015, harnessMaterial, 12, parent);
    addCylinderBetween([-0.26, 0.68, 0.29], [0.26, 0.68, 0.29], 0.015, harnessMaterial, 12, parent);
    addMesh(new THREE.TorusGeometry(0.055, 0.01, 8, 28), ringMaterial, [0, 0.74, 0.31], [0, 0, 0], [1, 1, 1], parent);
    addCylinderBetween([0, 1.16, -0.24], [0, 1.66, -0.62], 0.013, harnessMaterial, 12, parent);
  }

  const resize = () => {
    const width = Math.max(host.clientWidth || 1, 1);
    const height = Math.max(host.clientHeight || 1, 1);
    renderer.setSize(width, height, false);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
  };

  const resizeObserver = typeof ResizeObserver !== "undefined" ? new ResizeObserver(resize) : null;
  resizeObserver?.observe(host);
  window.addEventListener("resize", resize);
  resize();

  const reduceMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
  const clock = new THREE.Clock();
  let frameId = 0;
  let running = false;
  const animate = () => {
    if (!running) {
      return;
    }
    clock.getDelta();
    if (!reduceMotion) {
      const elapsed = clock.getElapsedTime();
      group.rotation.y = -0.16 + Math.sin(elapsed * 0.58) * 0.44;
    }
    group.rotation.x = 0.06 + Math.sin(group.rotation.y * 1.4) * 0.018;
    renderer.render(scene, camera);
    frameId = window.requestAnimationFrame(animate);
  };
  const stop = () => {
    running = false;
    window.cancelAnimationFrame(frameId);
    frameId = 0;
  };
  const start = () => {
    if (running || document.visibilityState === "hidden") {
      return;
    }
    running = true;
    clock.getDelta();
    animate();
  };
  const handleVisibilityChange = () => {
    if (document.visibilityState === "hidden") {
      stop();
    } else {
      start();
    }
  };
  document.addEventListener("visibilitychange", handleVisibilityChange);
  renderer.render(scene, camera);
  start();

  return {
    start,
    stop,
    dispose() {
      stop();
      resizeObserver?.disconnect();
      window.removeEventListener("resize", resize);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      geometries.forEach((geometry) => geometry.dispose?.());
      materials.forEach((material) => material.dispose?.());
      renderer.dispose();
      host.replaceChildren();
      preview?.classList.remove("is-webgl-ready");
    },
  };
}

function createRiskAssessmentEligibilityDraft(initial = {}) {
  return Object.fromEntries(RISK_ASSESSMENT_ELIGIBILITY_ROWS.map((row) => {
    const entry = initial?.[row.key] ?? {};
    return [row.key, {
      allowed: String(entry.allowed || "np"),
      note: String(entry.note || ""),
    }];
  }));
}

function createRiskAssessmentRiskRowDraft(initial = {}) {
  const rawCategory = String(initial.category || "").trim();
  const rawGroup = String(initial.group || "").trim();
  const hierarchy = getRiskAssessmentCatalogHierarchy(initial);
  const hasCatalogCategory = ["I. OPASNOSTI", "II. ŠTETNOSTI", "III. NAPORI"].includes(rawCategory);
  const probability = String(initial.probability || "");
  const consequence = String(initial.consequence || "");
  return {
    id: String(initial.id || crypto.randomUUID()),
    code: String(initial.code || ""),
    topCategory: String(initial.topCategory || (hasCatalogCategory ? rawCategory : "")),
    category: String(initial.displayCategory || initial.family || (hasCatalogCategory ? hierarchy.family : rawCategory)),
    group: String(initial.displayGroup || initial.subgroup || (hasCatalogCategory ? hierarchy.subgroup : rawGroup)),
    hazard: String(initial.hazard || ""),
    description: String(initial.description || ""),
    source: String(initial.source || ""),
    possibleConsequences: String(initial.possibleConsequences || initial.possibleEvent || ""),
    probability,
    consequence,
    riskCode: String(initial.riskCode || ""),
    riskLevel: String(initial.riskLevel || calculateRiskAssessmentRiskLevel(probability, consequence) || ""),
    likelihoodConsequence: String(initial.likelihoodConsequence || ""),
    purPoints: normalizeJobPurPointValues(initial.purPoints ?? []),
    workNote: String(initial.workNote || initial.jobsNote || initial.note || ""),
    note: String(initial.note || ""),
    existingMeasures: String(initial.existingMeasures || ""),
    additionalMeasures: String(initial.additionalMeasures || ""),
    measures: String(initial.measures || ""),
    deadline: String(initial.deadline || ""),
    responsiblePerson: String(initial.responsiblePerson || ""),
    controlMethod: String(initial.controlMethod || ""),
    collapsed: Boolean(initial.collapsed),
  };
}

function prepareRiskAssessmentCatalogRowForJob(row = {}, job = {}) {
  const context = getRiskAssessmentJobHazardContext(job);
  return applyRiskAssessmentRowAiSettings({
    ...row,
    possibleConsequences: "",
    workNote: buildContextualHazardEvent(row, context),
    note: "",
    existingMeasures: buildContextualHazardMeasures(row, context),
    additionalMeasures: "",
    measures: "",
  }, job, context);
}

function prepareRiskAssessmentCatalogRowsForJob(job = {}, rows = []) {
  return (Array.isArray(rows) ? rows : [])
    .filter(Boolean)
    .map((row) => prepareRiskAssessmentCatalogRowForJob(row, job));
}

