function getRiskAssessmentFilledRiskRowCount(job = {}) {
  return (job.riskRows ?? []).filter((risk) => isRiskAssessmentArmorRiskRow(risk) && (
    risk.code || risk.category || risk.group || risk.hazard || risk.description || risk.source
    || risk.possibleConsequences || risk.riskLevel || risk.workNote || risk.existingMeasures
    || risk.additionalMeasures || risk.measures || risk.deadline || risk.responsiblePerson || risk.controlMethod
  )).length;
}

function getRiskAssessmentRiskRowKey(row = {}) {
  const hierarchy = getRiskAssessmentCatalogHierarchy(row);
  const code = String(row.code || "").trim();
  const hazard = String(row.hazard || "").trim();
  const rawGroup = String(row.group || "").trim();
  const group = code || hazard ? (hierarchy.subgroup || rawGroup) : rawGroup;
  return [
    code,
    group,
    hazard,
  ].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean).join("::");
}

function isRiskAssessmentChemicalOrBiologicalRiskRow(row = {}) {
  const hierarchy = getRiskAssessmentCatalogHierarchy(row);
  const section = normalizeRiskAssessmentIdentityComparable(hierarchy.category || row.topCategory || row.category || "");
  const family = normalizeRiskAssessmentIdentityComparable(hierarchy.family || row.category || "");
  const subgroup = normalizeRiskAssessmentIdentityComparable(hierarchy.subgroup || row.group || "");
  const text = normalizeRiskAssessmentIdentityComparable([
    row.topCategory,
    row.category,
    row.group,
    row.code,
    row.hazard,
    row.description,
  ].filter(Boolean).join(" "));
  if (text.includes("kemij") || text.includes("biolos")) {
    return true;
  }
  if (!section.includes("ii stetnosti")) {
    return false;
  }
  return family.startsWith("1 kemijske")
    || family.startsWith("2 bioloske")
    || subgroup.startsWith("1 ")
    || subgroup.startsWith("1.")
    || subgroup.startsWith("2 ")
    || subgroup.startsWith("2.");
}

function isRiskAssessmentArmorRiskRow(row = {}) {
  return !isRiskAssessmentChemicalOrBiologicalRiskRow(row);
}

function getRiskAssessmentArmorRiskRowsWithIndexes(job = {}) {
  return (job.riskRows ?? [])
    .map((risk, riskIndex) => ({ risk, riskIndex }))
    .filter(({ risk }) => isRiskAssessmentArmorRiskRow(risk));
}

function mergeRiskAssessmentRiskRows(currentRows = [], incomingRows = []) {
  const incoming = incomingRows.map((row) => createRiskAssessmentRiskRowDraft(row));
  const hasIncoming = incoming.some((row) => getRiskAssessmentRiskRowKey(row));
  const rows = currentRows
    .map((row) => createRiskAssessmentRiskRowDraft(row))
    .filter((row) => !hasIncoming || getRiskAssessmentRiskRowKey(row) || row.measures || row.workNote);
  const seen = new Set(rows.map((row) => getRiskAssessmentRiskRowKey(row)).filter(Boolean));
  incoming.forEach((draft) => {
    const key = getRiskAssessmentRiskRowKey(draft);
    if (!key || !seen.has(key)) {
      rows.push(draft);
      if (key) {
        seen.add(key);
      }
    }
  });
  return sortRiskAssessmentRiskRowsByPrilogOrder(
    rows.filter((row, index) => index === 0 || getRiskAssessmentRiskRowKey(row) || row.measures || row.workNote),
  );
}

function seedRiskAssessmentArmorCatalogRowsForJob(job = {}) {
  return {
    ...job,
    armorCatalogSeeded: true,
    riskRows: mergeRiskAssessmentRiskRows(
      job.riskRows ?? [],
      prepareRiskAssessmentCatalogRowsForJob(job, RISK_ASSESSMENT_CATALOG_ROWS.filter(isRiskAssessmentArmorRiskRow)),
    ),
  };
}

function ensureRiskAssessmentArmorCatalogRowsForWorkplaceJobs() {
  let changed = false;
  riskAssessmentJobDrafts = riskAssessmentJobDrafts.map((job) => {
    if (!isRiskAssessmentWorkplaceJob(job) || job.armorCatalogSeeded) {
      return job;
    }
    changed = true;
    return seedRiskAssessmentArmorCatalogRowsForJob(job);
  });
  return changed;
}

function applyRiskAssessmentArmorTemplateRows(jobIndex) {
  const job = riskAssessmentJobDrafts[jobIndex];
  if (!job) {
    return;
  }
  riskAssessmentJobDrafts[jobIndex] = seedRiskAssessmentArmorCatalogRowsForJob(job);
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function applyRiskAssessmentArmorTemplateRowsToJobs(indexes = null) {
  const targetIndexes = Array.isArray(indexes)
    ? indexes.filter((index) => Number.isInteger(index) && riskAssessmentJobDrafts[index])
    : riskAssessmentJobDrafts.map((_, index) => index);
  if (!targetIndexes.length) {
    setInlineMessage(riskAssessmentError, "Dodaj barem jedno radno mjesto prije dodavanja ARMOR redaka.", "error");
    return;
  }
  const targetSet = new Set(targetIndexes);
  riskAssessmentJobDrafts = riskAssessmentJobDrafts.map((job, index) => (
    targetSet.has(index)
      ? seedRiskAssessmentArmorCatalogRowsForJob(job)
      : job
  ));
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
  setInlineMessage(riskAssessmentError, `ARMOR retci dodani su na ${targetIndexes.length} radnih mjesta.`, "success");
}

function getRiskAssessmentJobCatalogAiConfig() {
  return getJobAiInstruction("riskJob:catalogSelectionRules");
}

function getRiskAssessmentJobCatalogAiQuery() {
  return String(
    riskAssessmentJobCatalogAiDescriptionInput?.value
    || getRiskAssessmentJobCatalogDescriptionSource()
    || riskAssessmentJobCatalogSearchInput?.value
    || "",
  ).trim();
}

function getRiskAssessmentJobCatalogAiCorpus(job = {}) {
  const environment = job.environment ?? {};
  const conditions = job.conditions ?? {};
  const environmentText = JOB_ENVIRONMENT_SECTIONS.flatMap((section) => [
    section.title,
    ...(environment[`${section.key}Options`] ?? []),
    getJobCatalogEnvironmentText(job, section.key),
  ]);
  const conditionText = JOB_CONDITION_TOGGLES.flatMap((toggle) => [
    toggle.label,
    conditions[toggle.key] ? buildJobConditionToggleSentence(toggle.key) : "",
    getJobCatalogConditionNote(job, toggle.key),
  ]);
  const hazardText = (job.hazards ?? []).flatMap((hazard) => [
    hazard.catalogCode,
    hazard.catalogLabel,
    hazard.category,
    hazard.group,
    hazard.unwantedEvent,
    hazard.measures,
    hazard.ppeText,
  ]);
  const ppeText = (job.ppeItems ?? []).flatMap((ppe) => [
    ppe.name,
    ppe.category,
    ppe.bodyPart,
    ppe.norm,
    ppe.standardCode,
    ppe.description,
  ]);
  return [
    job.title,
    job.description,
    getJobStatusOption(job.status).label,
    ...environmentText,
    ...conditionText,
    ...(conditions.workConditions ?? []),
    ...(conditions.bodyPositions ?? []),
    ...(conditions.importantFunctions ?? []),
    ...(conditions.purPoints ?? []).map((value) => getJobPurPointLabel(value)),
    ...hazardText,
    ...ppeText,
  ].filter(Boolean).join(" ");
}

function getRiskAssessmentJobCatalogAiTokens(value = "") {
  const stopWords = new Set([
    "koji",
    "koja",
    "koje",
    "kada",
    "radi",
    "rada",
    "radnik",
    "radnici",
    "posao",
    "posla",
    "mjesto",
    "radno",
    "obavlja",
    "obavljaju",
    "koristi",
    "koriste",
    "povremeno",
    "stalno",
    "prema",
    "npr",
  ]);
  return Array.from(new Set(
    normalizeRiskAssessmentAiText(value)
      .split(/\s+/)
      .map((token) => token.trim())
      .filter((token) => token.length >= 3 && !stopWords.has(token)),
  ));
}

function scoreRiskAssessmentJobCatalogAiMatch(job = {}, query = "", config = {}) {
  const normalizedQuery = normalizeRiskAssessmentAiText(query);
  const corpus = getRiskAssessmentJobCatalogAiCorpus(job);
  const normalizedCorpus = normalizeRiskAssessmentAiText(corpus);
  const normalizedTitle = normalizeRiskAssessmentAiText(job.title || "");
  if (!normalizedQuery || !normalizedCorpus) {
    return null;
  }

  const avoidTerms = splitRiskAssessmentAiTerms(config.avoid);
  if (avoidTerms.some((term) => term && normalizedCorpus.includes(term) && !normalizedQuery.includes(term))) {
    return null;
  }

  const tokens = getRiskAssessmentJobCatalogAiTokens(query);
  const titleHits = tokens.filter((token) => normalizedTitle.includes(token));
  const corpusHits = tokens.filter((token) => normalizedCorpus.includes(token));
  const mustTerms = splitRiskAssessmentAiTerms(config.mustInclude);
  const instructionTerms = splitRiskAssessmentAiTerms(config.instruction);
  const positiveTerms = [...mustTerms, ...instructionTerms].filter((term) => term.length >= 4);
  const positiveHits = positiveTerms.filter((term) => normalizedCorpus.includes(term) || normalizedQuery.includes(term));
  const hazardHits = (job.hazards ?? []).filter((hazard) => (
    getRiskAssessmentJobCatalogAiTokens([
      hazard.catalogCode,
      hazard.catalogLabel,
      hazard.category,
      hazard.group,
      hazard.unwantedEvent,
    ].join(" ")).some((token) => normalizedQuery.includes(token))
  ));
  const exactTitleBoost = normalizedTitle && (
    normalizedQuery.includes(normalizedTitle)
    || normalizedTitle.includes(normalizedQuery)
  ) ? 32 : 0;
  const statusBoost = String(job.status || "") === "active" ? 4 : 0;
  const hazardBoost = Math.min(24, hazardHits.length * 8);
  const score = exactTitleBoost
    + (titleHits.length * 16)
    + (corpusHits.length * 7)
    + (positiveHits.length * 5)
    + hazardBoost
    + statusBoost
    + Math.min(8, (job.hazards ?? []).length);

  if (score < 18 || corpusHits.length === 0) {
    return null;
  }

  const reasons = [
    titleHits.length ? `naziv: ${titleHits.slice(0, 3).join(", ")}` : "",
    corpusHits.length ? `opis/oprema: ${corpusHits.slice(0, 4).join(", ")}` : "",
    hazardHits.length ? `${hazardHits.length} povezanih opasnosti` : "",
    positiveHits.length ? "Settings upute" : "",
  ].filter(Boolean);
  return {
    id: String(job.id || ""),
    job,
    score,
    confidence: Math.max(32, Math.min(98, Math.round(score * 1.7))),
    reasons,
  };
}

function getRiskAssessmentJobCatalogAiSuggestions(query = getRiskAssessmentJobCatalogAiQuery()) {
  const config = getRiskAssessmentJobCatalogAiConfig();
  return sortJobs(state.jobs ?? [])
    .map((job) => scoreRiskAssessmentJobCatalogAiMatch(job, query, config))
    .filter(Boolean)
    .sort((a, b) => b.score - a.score)
    .slice(0, 6);
}

function setRiskAssessmentJobCatalogSelectedIds(ids = []) {
  const selectedIds = new Set((ids ?? []).map(String).filter(Boolean));
  Array.from(riskAssessmentJobCatalogSelect?.options ?? []).forEach((option) => {
    option.selected = selectedIds.has(String(option.value || ""));
  });
}

function runRiskAssessmentJobCatalogAiSelection({ importNow = false } = {}) {
  if (!getCanManageRiskAssessments()) {
    setInlineMessage(riskAssessmentJobCatalogAiFeedback || riskAssessmentError, "Nemate pravo upravljati procjenama rizika.", "error");
    return;
  }
  if (!getCanUseJobNexAi()) {
    setInlineMessage(riskAssessmentJobCatalogAiFeedback || riskAssessmentError, "Nemate pravo koristiti Jobs NexAI prijedloge.", "error");
    return;
  }
  const query = getRiskAssessmentJobCatalogAiQuery();
  if (normalizeRiskAssessmentAiText(query).length < 12) {
    setInlineMessage(riskAssessmentJobCatalogAiFeedback || riskAssessmentError, "Upiši malo konkretniji opis posla za NexAI odabir.", "error");
    return;
  }
  const suggestions = getRiskAssessmentJobCatalogAiSuggestions(query);
  riskAssessmentJobCatalogAiSuggestions = suggestions;
  if (!suggestions.length) {
    setRiskAssessmentJobCatalogSelectedIds([]);
    renderRiskAssessmentJobCatalogPicker();
    setInlineMessage(riskAssessmentJobCatalogAiFeedback || riskAssessmentError, "NexAI nije pronašao dovoljno dobro poklapanje u Jobs katalogu.", "error");
    return;
  }
  setRiskAssessmentJobCatalogSelectedIds(suggestions.map((entry) => entry.id));
  renderRiskAssessmentJobCatalogPicker();
  const summary = suggestions
    .map((entry) => `${entry.job.title || "Posao"} (${entry.confidence}%)`)
    .join(", ");
  setInlineMessage(riskAssessmentJobCatalogAiFeedback || riskAssessmentError, `NexAI je odabrao: ${summary}.`, "success");
  if (importNow) {
    importSelectedJobsIntoRiskAssessment({ source: "ai", messageTarget: riskAssessmentJobCatalogAiFeedback });
  }
}

function getRiskAssessmentJobCatalogSelectedIds() {
  return new Set(
    Array.from(riskAssessmentJobCatalogSelect?.selectedOptions ?? [])
      .map((option) => String(option.value || "").trim())
      .filter(Boolean),
  );
}

function getRiskAssessmentCatalogJobSearchText(job = {}) {
  return [
    job.title,
    job.description,
    getJobStatusOption(job.status).label,
    ...(job.hazards ?? []).flatMap((hazard) => [
      hazard.catalogCode,
      hazard.catalogLabel,
      hazard.category,
      hazard.group,
      hazard.measures,
    ]),
    ...(job.ppeItems ?? []).flatMap((ppe) => [
      ppe.name,
      ppe.category,
      ppe.bodyPart,
      ppe.norm,
      ppe.standardCode,
      ppe.description,
    ]),
  ].join(" ").toLocaleLowerCase("hr");
}

function getVisibleRiskAssessmentCatalogJobs() {
  const jobs = sortJobs(state.jobs ?? []);
  const query = String(riskAssessmentJobCatalogSearchInput?.value || "").trim().toLocaleLowerCase("hr");
  if (!query) {
    return jobs;
  }
  return jobs.filter((job) => getRiskAssessmentCatalogJobSearchText(job).includes(query));
}

function getRiskAssessmentCatalogJobMetrics(job = {}) {
  const environment = job.environment ?? {};
  const conditions = job.conditions ?? {};
  const environmentCount = JOB_ENVIRONMENT_SECTIONS.filter((section) => (
    environment[`${section.key}Enabled`] || getJobCatalogEnvironmentText(job, section.key)
  )).length;
  const conditionCount = JOB_CONDITION_TOGGLES.filter((entry) => Boolean(conditions[entry.key])).length;
  return {
    environmentCount,
    conditionCount,
    hazardCount: (job.hazards ?? []).length,
    ppeCount: (job.ppeItems ?? []).length,
  };
}

function renderRiskAssessmentJobCatalogStats(jobs = [], visibleJobs = [], selectedIds = new Set()) {
  if (!riskAssessmentJobCatalogStats) {
    return;
  }
  const activeJob = getRiskAssessmentActiveJobDraft();
  const activeUnit = getRiskAssessmentJobCatalogTargetUnit(activeJob);
  const targetLabel = activeJob
    ? (activeJob.jobTitle || activeUnit?.name || "Aktivno radno mjesto")
    : "Odaberi radno mjesto";
  riskAssessmentJobCatalogStats.innerHTML = `
    <span class="is-target ${activeJob ? "is-active" : "is-missing"}"><strong>${escapeHtml(targetLabel)}</strong><small>radno mjesto</small></span>
  `;
}

function renderRiskAssessmentJobCatalogPicker() {
  if (!riskAssessmentJobCatalogList) {
    return;
  }
  if (riskAssessmentJobCatalogPickerRenderTimer) {
    window.clearTimeout(riskAssessmentJobCatalogPickerRenderTimer);
    riskAssessmentJobCatalogPickerRenderTimer = null;
  }
  const canManage = getCanManageRiskAssessments();
  const canUseNexAi = getCanUseJobNexAi();
  const jobs = sortJobs(state.jobs ?? []);
  const visibleJobs = getVisibleRiskAssessmentCatalogJobs();
  const selectedIds = getRiskAssessmentJobCatalogSelectedIds();
  const aiSuggestionsById = new Map((riskAssessmentJobCatalogAiSuggestions ?? []).map((entry) => [String(entry.id || ""), entry]));
  renderRiskAssessmentJobCatalogStats(jobs, visibleJobs, selectedIds);
  if (riskAssessmentJobCatalogDropdownCount) {
    riskAssessmentJobCatalogDropdownCount.textContent = selectedIds.size
      ? `${selectedIds.size} odabrano`
      : "0 odabrano";
  }

  if (riskAssessmentJobCatalogSelectVisibleButton) {
    riskAssessmentJobCatalogSelectVisibleButton.disabled = !canManage || visibleJobs.length === 0;
  }
  if (riskAssessmentJobCatalogClearButton) {
    riskAssessmentJobCatalogClearButton.disabled = !canManage || selectedIds.size === 0;
  }
  if (riskAssessmentImportJobsButton) {
    const activeJob = getRiskAssessmentActiveJobDraft();
    riskAssessmentImportJobsButton.disabled = !canManage || selectedIds.size === 0 || !activeJob;
    riskAssessmentImportJobsButton.textContent = selectedIds.size
      ? (activeJob ? `Dodaj u radno mjesto (${selectedIds.size})` : "Prvo odaberi radno mjesto")
      : (activeJob ? "Dodaj odabrane poslove u radno mjesto" : "Dodaj odabrane poslove");
  }
  if (riskAssessmentJobCatalogAiSuggestButton) {
    riskAssessmentJobCatalogAiSuggestButton.disabled = !canManage || !canUseNexAi || jobs.length === 0;
  }
  if (riskAssessmentJobCatalogAiImportButton) {
    riskAssessmentJobCatalogAiImportButton.disabled = !canManage || !canUseNexAi || jobs.length === 0 || !getRiskAssessmentActiveJobDraft();
  }

  if (jobs.length === 0) {
    riskAssessmentJobCatalogList.innerHTML = `
      <div class="risk-assessment-job-catalog-empty">
        <strong>Nema poslova u Jobs katalogu</strong>
        <span>Prvo dodaj posao u Jobs modulu, zatim ga ovdje možeš preuzeti u procjenu rizika.</span>
      </div>
    `;
    return;
  }

  if (visibleJobs.length === 0) {
    riskAssessmentJobCatalogList.innerHTML = `
      <div class="risk-assessment-job-catalog-empty">
        <strong>Nema rezultata za ovu pretragu</strong>
        <span>Probaj naziv radnog mjesta, opis, opasnost ili normirani pojam iz kataloga.</span>
      </div>
    `;
    return;
  }

  riskAssessmentJobCatalogList.replaceChildren(...visibleJobs.map((job) => {
    const card = document.createElement("button");
    const id = String(job.id || "");
    const selected = selectedIds.has(id);
    const aiSuggestion = aiSuggestionsById.get(id);
    const status = getJobStatusOption(job.status);
    const metrics = getRiskAssessmentCatalogJobMetrics(job);
    const firstHazards = (job.hazards ?? [])
      .map((hazard) => hazard.catalogLabel || hazard.hazard || hazard.catalogCode)
      .filter(Boolean)
      .slice(0, 2);
    card.type = "button";
    card.className = `risk-assessment-job-catalog-card${selected ? " is-selected" : ""}${aiSuggestion ? " is-ai-suggested" : ""}`;
    card.dataset.riskJobCatalogToggle = id;
    card.setAttribute("aria-pressed", selected ? "true" : "false");
    card.disabled = !canManage;
    card.innerHTML = `
      <span class="risk-assessment-job-catalog-check" aria-hidden="true">${renderRiskAssessmentRiskIcon(selected ? "check" : "briefcase")}</span>
      <span class="risk-assessment-job-catalog-main">
        <span class="risk-assessment-job-catalog-title-row">
          <strong>${escapeHtml(job.title || "Bez naziva")}</strong>
          <em>${escapeHtml(status.label)}</em>
        </span>
        <span class="risk-assessment-job-catalog-metrics">
          <span>${escapeHtml(String(metrics.hazardCount))} opasnosti</span>
          <span>${escapeHtml(String(metrics.ppeCount))} OZO</span>
          ${aiSuggestion ? `<span class="is-ai-score">NexAI ${escapeHtml(String(aiSuggestion.confidence))}%</span>` : ""}
        </span>
        ${aiSuggestion?.reasons?.length ? `<span class="risk-assessment-job-catalog-ai-reason">${escapeHtml(aiSuggestion.reasons.join(" · "))}</span>` : ""}
        ${firstHazards.length ? `
          <span class="risk-assessment-job-catalog-hazards">
            ${firstHazards.map((label) => `<small>${escapeHtml(label)}</small>`).join("")}
          </span>
        ` : ""}
      </span>
    `;
    return card;
  }));
}

function syncRiskAssessmentJobCatalogOptions() {
  if (!(riskAssessmentJobCatalogSelect instanceof HTMLSelectElement)) {
    return;
  }

  const jobs = sortJobs(state.jobs ?? []);
  const currentSelectedIds = getRiskAssessmentJobCatalogSelectedIds();
  const options = jobs.map((job) => ({
    value: job.id,
    label: `${job.title || "Bez naziva"} · ${(job.hazards ?? []).length} opasnosti · ${(job.ppeItems ?? []).length} OZO`,
  }));
  const signature = getSelectOptionsSignature(options);
  if (riskAssessmentJobCatalogSelect.dataset.optionsSignature !== signature) {
    riskAssessmentJobCatalogSelect.replaceChildren(
      ...(options.length
        ? options.map((option) => createOption(option.value, option.label, ""))
        : [createOption("", "Nema poslova u Jobs katalogu", "")]),
    );
    Array.from(riskAssessmentJobCatalogSelect.options).forEach((option) => {
      option.selected = currentSelectedIds.has(String(option.value));
    });
    riskAssessmentJobCatalogSelect.dataset.optionsSignature = signature;
  }
  riskAssessmentJobCatalogSelect.disabled = !getCanManageRiskAssessments() || options.length === 0;
  renderRiskAssessmentJobCatalogPicker();
}

function getRiskAssessmentActiveJobDraft() {
  const index = getRiskAssessmentActiveWorkplaceJobIndex();
  return index >= 0 ? riskAssessmentJobDrafts[index] : null;
}

function getRiskAssessmentJobCatalogTargetUnit(job = getRiskAssessmentActiveJobDraft()) {
  const unitId = String(job?.organizationUnitId || "").trim();
  if (!unitId) {
    return null;
  }
  return riskAssessmentOrganizationUnitDrafts.find((unit) => String(unit.id || "") === unitId) || null;
}

function getRiskAssessmentJobCatalogDescriptionSource(job = getRiskAssessmentActiveJobDraft()) {
  const unit = getRiskAssessmentJobCatalogTargetUnit(job);
  return String(
    job?.description
    || unit?.description
    || unit?.shortDescription
    || job?.shortDescription
    || job?.tasks
    || "",
  ).trim();
}

function syncRiskAssessmentJobCatalogAiDescriptionFromActiveJob({ force = false } = {}) {
  if (!(riskAssessmentJobCatalogAiDescriptionInput instanceof HTMLTextAreaElement)) {
    return;
  }
  if (!force && document.activeElement === riskAssessmentJobCatalogAiDescriptionInput) {
    return;
  }
  const description = getRiskAssessmentJobCatalogDescriptionSource();
  if (force || !riskAssessmentJobCatalogAiDescriptionInput.value.trim()) {
    riskAssessmentJobCatalogAiDescriptionInput.value = description;
  }
}

function mergeCatalogJobsIntoExistingRiskAssessmentJob(current = {}, selectedJobs = []) {
  const imported = selectedJobs.length > 1
    ? mergeCatalogJobsIntoRiskAssessmentJob(selectedJobs)
    : createRiskAssessmentJobDraftFromCatalogJob(selectedJobs[0] || {});
  const unit = getRiskAssessmentJobCatalogTargetUnit(current);
  const unitType = normalizeRiskAssessmentUnitType(unit?.type || "");
  const descriptionFromAiBox = String(riskAssessmentJobCatalogAiDescriptionInput?.value || "").trim();
  const workplaceTitle = unitType === "workplace" ? String(unit?.name || "").trim() : "";
  const sourceJobIds = uniqueJobValues([
    ...(current.sourceJobIds ?? []),
    ...(imported.sourceJobIds ?? []),
    ...selectedJobs.map((job) => job.id),
  ]);
  const preferCurrent = (field) => String(current[field] || "").trim() || String(imported[field] || "").trim();
  const mergeText = (field) => joinUniqueRiskAssessmentTextBlocks([current[field], imported[field]]);
  const mergeOptions = (field) => mergeJobValues([current[field] ?? [], imported[field] ?? []]);

  return createRiskAssessmentJobDraft({
    ...sanitizeRiskAssessmentTransientJob(current),
    sourceJobIds,
    organizationUnitId: current.organizationUnitId || imported.organizationUnitId,
    status: current.status || imported.status || "draft",
    jobTitle: workplaceTitle || current.jobTitle || imported.jobTitle,
    shortDescription: current.shortDescription || unit?.shortDescription || imported.shortDescription,
    description: descriptionFromAiBox || current.description || unit?.description || imported.description,
    detailedDescription: current.detailedDescription || unit?.detailedDescription || imported.detailedDescription,
    workplaceDescription: current.workplaceDescription || unit?.note || imported.workplaceDescription,
    workerCount: current.workerCount || unit?.workerCount || imported.workerCount,
    tasks: mergeText("tasks"),
    workEnvironment: mergeText("workEnvironment"),
    workplace: mergeText("workplace"),
    workplaces: mergeText("workplaces"),
    workOrganization: mergeText("workOrganization"),
    organization: mergeText("organization"),
    workSubstances: mergeText("workSubstances"),
    chemicalSubstances: mergeText("chemicalSubstances"),
    biologicalHazards: mergeText("biologicalHazards"),
    workEquipment: mergeText("workEquipment"),
    toolsAndMachines: mergeText("toolsAndMachines"),
    workplaceArrangement: mergeText("workplaceArrangement"),
    harmfulSources: mergeText("harmfulSources"),
    specialWorkReason: mergeText("specialWorkReason"),
    specialConditions: mergeText("specialConditions"),
    requiredQualification: mergeText("requiredQualification"),
    qualifications: mergeText("qualifications"),
    trainings: mergeText("trainings"),
    medicalExams: mergeText("medicalExams"),
    ppeText: mergeText("ppeText"),
    workplaceOptions: mergeOptions("workplaceOptions"),
    organizationOptions: mergeOptions("organizationOptions"),
    bodyPositions: mergeOptions("bodyPositions"),
    importantFunctions: mergeOptions("importantFunctions"),
    workConditions: mergeOptions("workConditions"),
    toolsAndMachinesOptions: mergeOptions("toolsAndMachinesOptions"),
    chemicalSubstanceOptions: mergeOptions("chemicalSubstanceOptions"),
    biologicalHazardOptions: mergeOptions("biologicalHazardOptions"),
    purPoints: normalizeJobPurPointValues([...(current.purPoints ?? []), ...(imported.purPoints ?? [])]),
    safeWorkTrainingRequired: Boolean(current.safeWorkTrainingRequired || imported.safeWorkTrainingRequired),
    medicalFitnessRequired: Boolean(current.medicalFitnessRequired || imported.medicalFitnessRequired),
    visionCheckRequired: Boolean(current.visionCheckRequired || imported.visionCheckRequired),
    psychosocialRelevant: Boolean(current.psychosocialRelevant || imported.psychosocialRelevant),
    increasedInsurance: current.increasedInsurance || imported.increasedInsurance,
    alcoholLimit: preferCurrent("alcoholLimit"),
    riskRows: mergeRiskAssessmentRiskRows(current.riskRows ?? [], (imported.riskRows ?? []).filter(isRiskAssessmentArmorRiskRow)),
    ppeItems: mergeRiskAssessmentPpeItems(current.ppeItems ?? [], imported.ppeItems ?? []),
    hiddenBlocks: current.hiddenBlocks ?? imported.hiddenBlocks,
    clientInput: current.clientInput,
  });
}

function importSelectedJobsIntoRiskAssessment(options = {}) {
  const messageTarget = options.messageTarget || riskAssessmentError;
  if (!getCanManageRiskAssessments()) {
    setInlineMessage(messageTarget, "Nemate pravo upravljati procjenama rizika.", "error");
    return;
  }
  const selectedIds = Array.from(riskAssessmentJobCatalogSelect?.selectedOptions ?? [])
    .map((option) => String(option.value || "").trim())
    .filter(Boolean);
  const selectedJobs = selectedIds
    .map((id) => (state.jobs ?? []).find((job) => String(job.id) === id))
    .filter(Boolean);
  if (selectedJobs.length === 0) {
    setInlineMessage(messageTarget, "Odaberi barem jedan posao iz Jobs kataloga.", "error");
    return;
  }

  const activeIndex = getRiskAssessmentActiveJobIndex();
  const activeJob = activeIndex >= 0 && isRiskAssessmentWorkplaceJob(riskAssessmentJobDrafts[activeIndex])
    ? riskAssessmentJobDrafts[activeIndex]
    : null;
  if (!activeJob) {
    setInlineMessage(messageTarget, "Prvo odaberi ili dodaj radno mjesto iz organizacijske strukture, zatim u njega dodaj poslove iz Jobs kataloga.", "error");
    return;
  }

  riskAssessmentJobDrafts[activeIndex] = mergeCatalogJobsIntoExistingRiskAssessmentJob(activeJob, selectedJobs);
  Array.from(riskAssessmentJobCatalogSelect?.options ?? []).forEach((option) => {
    option.selected = false;
  });
  riskAssessmentJobCatalogAiSuggestions = [];
  renderRiskAssessmentJobs();
  renderRiskAssessmentOrganizationUnits();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
  const sourceText = options.source === "ai" ? "NexAI je dodao" : "Dodano";
  const targetTitle = riskAssessmentJobDrafts[activeIndex]?.jobTitle || "aktivno radno mjesto";
  setInlineMessage(messageTarget, `${sourceText} ${selectedJobs.length} ${selectedJobs.length === 1 ? "posao" : "poslova"} u radno mjesto: ${targetTitle}.`, "success");
}

function applyRiskAssessmentSourceJob(jobIndex, sourceJobId = "") {
  const current = riskAssessmentJobDrafts[jobIndex];
  const source = (state.jobs ?? []).find((job) => String(job.id) === String(sourceJobId));
  if (!current || !source) {
    return;
  }

  riskAssessmentJobDrafts[jobIndex] = mergeCatalogJobsIntoExistingRiskAssessmentJob(current, [source]);
  renderRiskAssessmentOrganizationUnits();
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function openJobsModuleForRiskAssessmentJob(jobIndex) {
  if (!getCanManageJobs()) {
    setInlineMessage(riskAssessmentError, "Nemate pravo dodavati poslove u Jobs bazu.", "error");
    return;
  }

  const current = riskAssessmentJobDrafts[jobIndex] || {};
  scheduleRiskAssessmentDraftAutosave();
  setRiskAssessmentEditorOpen(false);
  activateSidebarItem("jobs", { expandSidebar: true });
  openJobEditor({
    title: current.jobTitle || "",
    description: current.description || current.shortDescription || "",
    status: "draft",
    environment: {
      workplaceOptions: current.workplaceOptions ?? [],
      organizationOptions: current.organizationOptions ?? [],
      substancesText: current.chemicalSubstances || current.workSubstances || "",
      machinesText: current.toolsAndMachines || current.workEquipment || "",
      workplaceText: current.workplaces || current.workplace || "",
      organizationText: current.workOrganization || current.organization || "",
    },
    conditions: {
      bodyPositions: current.bodyPositions ?? [],
      importantFunctions: current.importantFunctions ?? [],
      workConditions: current.workConditions ?? [],
      purPoints: current.purPoints ?? [],
      bodyText: "",
      functionsText: "",
      conditionsText: current.biologicalHazards || current.harmfulSources || "",
    },
    hazards: [],
    ppeItems: current.ppeItems ?? [],
  });
}

function getCanManageRiskAssessments() {
  return getCanEditOperationalData();
}

function getRiskAssessmentClientJobInputEnabled() {
  const company = getRiskAssessmentCompany(riskAssessmentCompanyInput?.value || "");
  return Boolean(company?.riskAssessmentClientJobInputEnabled);
}

function syncRiskAssessmentEditorAccess() {
  if (!state.riskAssessmentEditorOpen && riskAssessmentEditorPanel?.hidden) {
    return;
  }

  const canManage = getCanManageRiskAssessments();
  const canComment = isClientPortalUser(state.user);
  const clientJobInputEnabled = getRiskAssessmentClientJobInputEnabled();
  const allowClientNote = canManage || canComment;
  const allowClientPortalInput = canManage || (canComment && clientJobInputEnabled);
  const canUseJobNexAi = getCanUseJobNexAi();

  riskAssessmentForm?.querySelectorAll("input, select, textarea, button").forEach((control) => {
    if (!(control instanceof HTMLElement)) {
      return;
    }

    if (control === riskAssessmentClientNoteInput) {
      control.disabled = !allowClientNote;
      return;
    }

    control.disabled = !canManage;
  });
  if (riskAssessmentSaveButton) {
    riskAssessmentSaveButton.hidden = !(canManage || canComment);
    riskAssessmentSaveButton.disabled = !getCanAutosaveRiskAssessmentToServer() || riskAssessmentServerAutosaveBusy;
    riskAssessmentSaveButton.textContent = riskAssessmentServerAutosaveBusy ? "Spremam..." : "Spremi";
  }
  if (riskAssessmentResetButton) {
    riskAssessmentResetButton.hidden = true;
  }
  if (riskAssessmentAddMeasureButton) {
    riskAssessmentAddMeasureButton.hidden = !canManage;
  }
  if (riskAssessmentAddUnitButton) {
    riskAssessmentAddUnitButton.hidden = !canManage;
  }
  if (riskAssessmentStructureUploadButton) {
    riskAssessmentStructureUploadButton.hidden = !canManage;
  }
  if (riskAssessmentStructureImportButton) {
    riskAssessmentStructureImportButton.disabled = !canManage;
  }
  if (riskAssessmentAddJobButton) {
    riskAssessmentAddJobButton.hidden = !canManage;
  }
  if (riskAssessmentArmorAllButton) {
    riskAssessmentArmorAllButton.hidden = !canManage;
    riskAssessmentArmorAllButton.disabled = !canManage || riskAssessmentJobDrafts.length === 0;
  }
  if (riskAssessmentAddAuthorizedPersonButton) {
    riskAssessmentAddAuthorizedPersonButton.hidden = !canManage;
  }
  if (riskAssessmentAddCompanyCollaboratorButton) {
    riskAssessmentAddCompanyCollaboratorButton.hidden = !canManage;
  }
  if (riskAssessmentZnrAuthorizationUploadButton) {
    riskAssessmentZnrAuthorizationUploadButton.hidden = !canManage;
    riskAssessmentZnrAuthorizationUploadButton.disabled = !canManage;
  }
  if (riskAssessmentZnrAuthorizationRemoveButton) {
    riskAssessmentZnrAuthorizationRemoveButton.hidden = !canManage || !riskAssessmentZnrAuthorizationDocumentDraft;
    riskAssessmentZnrAuthorizationRemoveButton.disabled = !canManage || !riskAssessmentZnrAuthorizationDocumentDraft;
  }
  if (riskAssessmentAddWorkplaceJobButton) {
    riskAssessmentAddWorkplaceJobButton.hidden = !canManage;
  }
  if (riskAssessmentJobCatalogSelect) {
    riskAssessmentJobCatalogSelect.disabled = !canManage || (state.jobs ?? []).length === 0;
  }
  if (riskAssessmentJobCatalogSearchInput) {
    riskAssessmentJobCatalogSearchInput.disabled = !canManage || (state.jobs ?? []).length === 0;
  }
  if (riskAssessmentJobCatalogAiDescriptionInput) {
    riskAssessmentJobCatalogAiDescriptionInput.disabled = !canManage || !canUseJobNexAi || (state.jobs ?? []).length === 0;
  }
  if (riskAssessmentJobCatalogAiSuggestButton) {
    riskAssessmentJobCatalogAiSuggestButton.disabled = !canManage || !canUseJobNexAi || (state.jobs ?? []).length === 0;
  }
  if (riskAssessmentJobCatalogAiImportButton) {
    riskAssessmentJobCatalogAiImportButton.disabled = !canManage || !canUseJobNexAi || (state.jobs ?? []).length === 0;
  }
  if (riskAssessmentJobCatalogSelectVisibleButton) {
    riskAssessmentJobCatalogSelectVisibleButton.disabled = !canManage || (state.jobs ?? []).length === 0;
  }
  if (riskAssessmentJobCatalogClearButton) {
    riskAssessmentJobCatalogClearButton.disabled = !canManage || getRiskAssessmentJobCatalogSelectedIds().size === 0;
  }
  if (riskAssessmentOpenNewJobButton) {
    riskAssessmentOpenNewJobButton.hidden = !canManage;
    riskAssessmentOpenNewJobButton.disabled = !canManage;
  }
  if (riskAssessmentImportJobsButton) {
    riskAssessmentImportJobsButton.disabled = !canManage || getRiskAssessmentJobCatalogSelectedIds().size === 0;
  }
  if (riskAssessmentAddManualHandlingButton) {
    riskAssessmentAddManualHandlingButton.hidden = !canManage;
  }
  if (riskAssessmentAddChemicalButton) {
    riskAssessmentAddChemicalButton.hidden = !canManage;
  }
  if (riskAssessmentChemicalSearchButton) {
    riskAssessmentChemicalSearchButton.disabled = !canManage || riskAssessmentChemicalSearchBusy;
  }
  if (riskAssessmentChemicalStlButton) {
    riskAssessmentChemicalStlButton.disabled = !canManage || riskAssessmentChemicalImportBusy;
  }
  riskAssessmentForm?.querySelectorAll("[data-risk-job-ai], [data-risk-unit-ai]").forEach((control) => {
    control.disabled = !canManage || !canUseJobNexAi;
  });
  riskAssessmentForm?.querySelectorAll("[data-risk-job-toggle-block], [data-risk-job-psychosocial-level], [data-risk-job-pur-point], [data-risk-job-template]").forEach((control) => {
    control.disabled = !canManage;
  });
  riskAssessmentForm?.querySelectorAll("[data-risk-client-field], [data-risk-client-boolean], [data-risk-client-choice], [data-risk-client-pur-point], [data-risk-client-psychosocial-level], [data-risk-client-preset]").forEach((control) => {
    control.disabled = !allowClientPortalInput;
  });
  [
    riskAssessmentTemplateTitleInput,
    riskAssessmentTemplateDescriptionInput,
    riskAssessmentTemplatePresetSelect,
    riskAssessmentTemplateApplyPresetButton,
    riskAssessmentTemplateAddSectionButton,
  ].forEach((control) => {
    if (control) {
      control.disabled = !canManage;
    }
  });
  if (riskAssessmentDeleteButton) {
    riskAssessmentDeleteButton.hidden = !canManage || !riskAssessmentIdInput?.value;
  }
  if (riskAssessmentEditorPanel) {
    riskAssessmentEditorPanel.classList.toggle("is-client-note-mode", !canManage && canComment);
  }
  syncRiskAssessmentEditorActionVisibility();
  syncRiskAssessmentDocumentExportControls();
}

function renderRiskAssessmentMeasures() {
  if (!riskAssessmentMeasuresList) {
    return;
  }

  if (riskAssessmentMeasureDrafts.length === 0) {
    const empty = document.createElement("p");
    empty.className = "inline-help";
    empty.textContent = "Dodaj mjere iz plana mjera procjene rizika.";
    riskAssessmentMeasuresList.replaceChildren(empty);
    return;
  }

  riskAssessmentMeasuresList.replaceChildren(...riskAssessmentMeasureDrafts.map((item, index) => {
    const row = document.createElement("div");
    row.className = "risk-assessment-repeat-row is-measure";
    row.innerHTML = `
      <label><span>Mjera</span><input data-risk-measure-field="measure" value="${escapeHtml(item.measure || "")}" placeholder="Plan mjera" /></label>
      <label><span>Rok</span><input data-risk-measure-field="deadline" value="${escapeHtml(item.deadline || "")}" placeholder="npr. odmah / 30 dana" /></label>
      <label><span>Odgovorna osoba</span><input data-risk-measure-field="responsiblePerson" value="${escapeHtml(item.responsiblePerson || "")}" /></label>
      <label><span>Kontrola</span><input data-risk-measure-field="controlMethod" value="${escapeHtml(item.controlMethod || "")}" /></label>
      <button type="button" class="ghost-button card-danger" data-risk-measure-remove="${index}">Ukloni</button>
    `;
    row.querySelectorAll("[data-risk-measure-field]").forEach((input) => {
      input.addEventListener("input", () => {
        riskAssessmentMeasureDrafts[index] = {
          ...riskAssessmentMeasureDrafts[index],
          [input.dataset.riskMeasureField]: input.value,
        };
        renderRiskAssessmentOverview();
        scheduleRiskAssessmentDraftAutosave();
      });
    });
    row.querySelector("[data-risk-measure-remove]")?.addEventListener("click", () => {
      riskAssessmentMeasureDrafts.splice(index, 1);
      renderRiskAssessmentMeasures();
      renderRiskAssessmentOverview();
      scheduleRiskAssessmentDraftAutosave();
    });
    return row;
  }));
}

