function parseRiskAssessmentManualNumber(value = "") {
  const normalized = String(value ?? "").replace(",", ".").replace(/[^0-9.-]/g, "");
  const number = Number(normalized);
  return Number.isFinite(number) && number > 0 ? number : 0;
}

function getRiskAssessmentManualOption(options = [], value = "") {
  return options.find((option) => option.value === value) ?? options[0];
}

function normalizeRiskAssessmentManualMethod(value = "") {
  const normalized = String(value || "").trim();
  return RISK_ASSESSMENT_MANUAL_METHOD_OPTIONS.some((option) => option.value === normalized) ? normalized : "load";
}

function getRiskAssessmentManualMethodOption(value = "") {
  return getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_METHOD_OPTIONS, normalizeRiskAssessmentManualMethod(value));
}

function normalizeRiskAssessmentManualStringArray(value = []) {
  return (Array.isArray(value) ? value : String(value || "").split(","))
    .map((entry) => String(entry || "").trim())
    .filter(Boolean)
    .filter((entry, index, list) => list.indexOf(entry) === index);
}

function createRiskAssessmentManualScopeDraft(initial = {}) {
  return {
    unitIds: normalizeRiskAssessmentManualStringArray(initial?.unitIds ?? initial?.organizationUnitIds ?? initial?.units),
    jobIds: normalizeRiskAssessmentManualStringArray(initial?.jobIds ?? initial?.workplaceJobIds ?? initial?.jobs),
  };
}

function sanitizeRiskAssessmentManualScopeDraft(scope = {}) {
  const draft = createRiskAssessmentManualScopeDraft(scope);
  const validUnitIds = new Set(riskAssessmentOrganizationUnitDrafts.map((unit) => String(unit.id || "").trim()).filter(Boolean));
  const validJobIds = new Set(riskAssessmentJobDrafts.map((job) => String(job.id || "").trim()).filter(Boolean));
  return {
    unitIds: draft.unitIds.filter((id) => !validUnitIds.size || validUnitIds.has(String(id))),
    jobIds: draft.jobIds.filter((id) => !validJobIds.size || validJobIds.has(String(id))),
  };
}

function getRiskAssessmentManualScopeResolvedJobIds(scope = riskAssessmentManualHandlingScopeDraft) {
  const draft = createRiskAssessmentManualScopeDraft(scope);
  const selected = new Set(draft.jobIds.map(String));
  const selectedUnits = new Set(draft.unitIds.map(String));
  if (selectedUnits.size) {
    riskAssessmentJobDrafts.forEach((job) => {
      if (selectedUnits.has(String(job.organizationUnitId || ""))) {
        selected.add(String(job.id || ""));
      }
    });
  }
  return Array.from(selected).filter(Boolean);
}

function getRiskAssessmentManualScopeSummary(scope = riskAssessmentManualHandlingScopeDraft) {
  const draft = createRiskAssessmentManualScopeDraft(scope);
  const unitNames = draft.unitIds
    .map((id) => riskAssessmentOrganizationUnitDrafts.find((unit) => String(unit.id || "") === String(id))?.name)
    .filter(Boolean);
  const jobNames = draft.jobIds
    .map((id) => riskAssessmentJobDrafts.find((job) => String(job.id || "") === String(id))?.jobTitle)
    .filter(Boolean);
  const resolvedJobIds = getRiskAssessmentManualScopeResolvedJobIds(draft);
  return {
    unitNames,
    jobNames,
    resolvedJobIds,
    count: resolvedJobIds.length,
    text: [
      unitNames.length ? `Organizacijske jedinice: ${unitNames.join(", ")}` : "",
      jobNames.length ? `Radna mjesta: ${jobNames.join(", ")}` : "",
    ].filter(Boolean).join("\n") || "Opseg IOR-a nije odabran. Odaberi radna mjesta ili organizacijske jedinice na početku bloka.",
  };
}

function getRiskAssessmentManualRiskTone(score = 0, method = "load") {
  if (method === "repetitive") {
    if (score > 65) return { level: "Vrlo visok rizik", tone: "critical", recommendation: "Nužno je preoblikovanje mjesta rada, uvođenje opreme i promjena metode ili organizacije rada." };
    if (score >= 45) return { level: "Visok rizik", tone: "danger", recommendation: "Postoji opasnost od preopterećenja svih radnika; preporučuje se preoblikovanje mjesta rada." };
    if (score >= 20) return { level: "Povećan rizik", tone: "warning", recommendation: "Moguće je preopterećenje manje otpornih radnika; potrebno je smanjiti trajanje, broj ponavljanja ili snagu." };
    return { level: "Nizak rizik", tone: "success", recommendation: "Niska razina rizika uz redovno praćenje opterećenja i organizaciju rada." };
  }
  if (score > 50) return { level: "Vrlo visok rizik", tone: "critical", recommendation: "Potrebno je neposredno preprojektiranje rada, mehanička pomagala ili uklanjanje ručnog rukovanja prije redovnog rada." };
  if (score >= 25) return { level: "Visok rizik", tone: "danger", recommendation: "Smanjiti masu, učestalost, trajanje ili udaljenost te uvesti tehnička pomagala, timski rad i nadzor." };
  if (score >= 10) return { level: "Povećan rizik", tone: "warning", recommendation: "Optimizirati organizaciju rada, put nošenja, visinu zahvata, odmore i osposobljavanje radnika." };
  return { level: "Nizak rizik", tone: "success", recommendation: "Rizik je prihvatljiv uz osposobljavanje, uredan prostor i praćenje promjena uvjeta." };
}

function getRiskAssessmentManualT1Points(entry = {}, totals = {}) {
  const operation = String(entry.operationType || "lift");
  const hasInput = totals.mass || totals.transfersPerHour || totals.durationMinutes || totals.carryingDistanceMeters;
  if (!hasInput) return 0;
  if (operation === "hold") {
    const minutes = totals.durationMinutes;
    if (minutes < 5) return 1;
    if (minutes < 15) return 2;
    if (minutes < 60) return 4;
    if (minutes < 120) return 6;
    if (minutes < 240) return 8;
    return 10;
  }
  if (operation === "carry") {
    const distance = totals.totalDistanceMeters;
    if (distance < 300) return 1;
    if (distance < 1000) return 2;
    if (distance < 4000) return 4;
    if (distance < 8000) return 6;
    if (distance < 16000) return 8;
    return 10;
  }
  const repetitions = totals.totalRepetitions;
  if (repetitions < 10) return 1;
  if (repetitions < 40) return 2;
  if (repetitions < 200) return 4;
  if (repetitions < 500) return 6;
  if (repetitions < 1000) return 8;
  return 10;
}

function getRiskAssessmentManualT2Points(mass = 0, gender = "male") {
  if (!mass) return 0;
  if (gender === "female") {
    if (mass < 5) return 1;
    if (mass < 10) return 2;
    if (mass < 15) return 4;
    if (mass < 25) return 7;
    return 25;
  }
  if (mass < 10) return 1;
  if (mass < 20) return 2;
  if (mass < 30) return 4;
  if (mass < 40) return 7;
  return 25;
}

function getRiskAssessmentManualPushPullT1Points(entry = {}, totals = {}) {
  const mode = String(entry.pushPullMode || "short");
  const hasInput = totals.repetitions || totals.totalDistanceMeters || totals.durationMinutes || totals.distancePerTransferMeters;
  if (!hasInput) return 0;
  if (mode === "long") {
    const distance = totals.totalDistanceMeters;
    if (distance < 300) return 1;
    if (distance < 1000) return 2;
    if (distance < 4000) return 4;
    if (distance < 8000) return 6;
    if (distance < 16000) return 8;
    return 10;
  }
  const repetitions = totals.repetitions;
  if (repetitions < 10) return 1;
  if (repetitions < 40) return 2;
  if (repetitions < 200) return 4;
  if (repetitions < 500) return 6;
  if (repetitions < 1000) return 8;
  return 10;
}

function getRiskAssessmentManualPushPullT2Points(mass = 0, transportType = "industrial") {
  if (!mass) return 0;
  if (transportType === "pull_slide") {
    if (mass < 10) return 1;
    if (mass < 25) return 2;
    if (mass < 50) return 4;
    return 8;
  }
  if (mass < 50) return 0.5;
  if (mass < 100) return 1;
  if (mass < 200) return ["industrial", "steerable", "manipulator"].includes(transportType) ? 1.5 : 2;
  if (mass < 300) {
    if (["industrial", "steerable"].includes(transportType)) return 2;
    if (transportType === "hand_cart") return 3;
    return 4;
  }
  if (mass < 400) return ["industrial", "hand_cart"].includes(transportType) ? 3 : 4;
  if (mass < 600) return transportType === "hand_cart" ? 4 : 5;
  return 5;
}

function getRiskAssessmentManualRepetitiveT1Points(minutes = 0) {
  if (!minutes) return 0;
  if (minutes <= 60) return 1;
  if (minutes <= 120) return 2;
  if (minutes <= 240) return 4;
  return 5;
}

function getRiskAssessmentManualRepetitiveT2Points(repetitions = 0) {
  if (!repetitions) return 0;
  if (repetitions <= 1000) return 1;
  if (repetitions <= 4800) return 2;
  if (repetitions <= 10000) return 3;
  if (repetitions <= 12000) return 4;
  return 5;
}

function calculateRiskAssessmentManualLoad(entry = {}) {
  const mass = parseRiskAssessmentManualNumber(entry.loadWeightKg);
  const transfersPerHour = parseRiskAssessmentManualNumber(entry.transfersPerHour);
  const durationMinutes = parseRiskAssessmentManualNumber(entry.durationMinutes);
  const carryingDistanceMeters = parseRiskAssessmentManualNumber(entry.carryingDistanceMeters);
  const totalRepetitions = Math.round(transfersPerHour * (durationMinutes / 60));
  const totalDistanceMeters = Math.round(carryingDistanceMeters * totalRepetitions);
  const posture = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_POSTURE_OPTIONS, entry.posture || "upright");
  const conditions = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_WORK_CONDITION_OPTIONS, entry.workConditions || "good");
  const gender = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_WORKER_GENDER_OPTIONS, entry.workerGender || "male");
  const operation = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_OPERATION_OPTIONS, entry.operationType || "lift");
  const dailyLoadKg = Math.round(mass * totalRepetitions);
  const tonnage = dailyLoadKg / 1000;
  const t1Points = getRiskAssessmentManualT1Points(entry, { mass, transfersPerHour, durationMinutes, carryingDistanceMeters, totalRepetitions, totalDistanceMeters });
  const t2Points = getRiskAssessmentManualT2Points(mass, gender.value);
  const t3Points = posture.points;
  const t4Points = conditions.points;
  const score = t1Points ? t1Points * (t2Points + t3Points + t4Points) : 0;
  return {
    methodType: "load",
    methodLabel: getRiskAssessmentManualMethodOption("load").label,
    formulaText: "(T2 + T3 + T4) × T1",
    formulaValueText: `${t1Points} × (${t2Points} + ${t3Points} + ${t4Points})`,
    mass,
    transfersPerHour,
    durationMinutes,
    carryingDistanceMeters,
    totalRepetitions,
    totalDistanceMeters,
    dailyLoadKg,
    tonnage,
    score,
    t1Points,
    t2Points,
    t3Points,
    t4Points,
    operationLabel: operation.label,
    workerGenderLabel: gender.label,
    postureLabel: posture.label,
    workConditionLabel: conditions.label,
    factorLabels: [`T1 ${t1Points}`, `T2 ${t2Points}`, `T3 ${t3Points}`, `T4 ${t4Points}`],
    workloadText: [dailyLoadKg ? `${dailyLoadKg} kg/dan` : "", totalDistanceMeters ? `${totalDistanceMeters} m/dan` : ""].filter(Boolean).join(" / "),
    ...getRiskAssessmentManualRiskTone(score, "load"),
  };
}

function calculateRiskAssessmentManualPushPull(entry = {}) {
  const mass = parseRiskAssessmentManualNumber(entry.loadWeightKg);
  const transfersPerHour = parseRiskAssessmentManualNumber(entry.transfersPerHour);
  const durationMinutes = parseRiskAssessmentManualNumber(entry.durationMinutes);
  const distancePerTransferMeters = parseRiskAssessmentManualNumber(entry.carryingDistanceMeters);
  const repetitions = Math.round(transfersPerHour * (durationMinutes / 60));
  const totalDistanceMeters = Math.round(distancePerTransferMeters * repetitions);
  const mode = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_PUSH_PULL_MODE_OPTIONS, entry.pushPullMode || "short");
  const transport = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_PUSH_PULL_TRANSPORT_OPTIONS, entry.pushPullTransport || "industrial");
  const precision = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_PUSH_PULL_PRECISION_OPTIONS, entry.pushPullPrecisionSpeed || "low_slow");
  const posture = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_PUSH_PULL_POSTURE_OPTIONS, entry.pushPullPosture || entry.posture || "upright");
  const conditions = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_PUSH_PULL_WORK_CONDITION_OPTIONS, entry.pushPullWorkConditions || "good");
  const gender = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_WORKER_GENDER_OPTIONS, entry.workerGender || "male");
  const t1Points = getRiskAssessmentManualPushPullT1Points(entry, { repetitions, totalDistanceMeters, durationMinutes, distancePerTransferMeters });
  const t2Points = getRiskAssessmentManualPushPullT2Points(mass, transport.value);
  const t3Points = precision.points;
  const t4Points = posture.points;
  const t5Points = conditions.points;
  const baseScore = t1Points ? t1Points * (t2Points + t3Points + t4Points + t5Points) : 0;
  const multiplier = gender.value === "female" ? 1.3 : 1;
  const score = Number((baseScore * multiplier).toFixed(1));
  return {
    methodType: "push_pull",
    methodLabel: getRiskAssessmentManualMethodOption("push_pull").label,
    formulaText: "(T2 + T3 + T4 + T5) × T1",
    formulaValueText: `${t1Points} × (${t2Points} + ${t3Points} + ${t4Points} + ${t5Points})${multiplier > 1 ? " × 1,3" : ""}`,
    mass,
    transfersPerHour,
    durationMinutes,
    carryingDistanceMeters: distancePerTransferMeters,
    totalRepetitions: repetitions,
    totalDistanceMeters,
    score,
    baseScore,
    multiplier,
    t1Points,
    t2Points,
    t3Points,
    t4Points,
    t5Points,
    operationLabel: mode.label,
    workerGenderLabel: gender.label,
    transportLabel: transport.label,
    precisionLabel: precision.label,
    postureLabel: posture.label,
    workConditionLabel: conditions.label,
    factorLabels: [`T1 ${t1Points}`, `T2 ${t2Points}`, `T3 ${t3Points}`, `T4 ${t4Points}`, `T5 ${t5Points}`],
    workloadText: [repetitions ? `${repetitions} ponavljanja` : "", totalDistanceMeters ? `${totalDistanceMeters} m/dan` : "", mass ? `${mass} kg` : ""].filter(Boolean).join(" / "),
    ...getRiskAssessmentManualRiskTone(score, "push_pull"),
  };
}

function calculateRiskAssessmentManualRepetitive(entry = {}) {
  const durationMinutes = parseRiskAssessmentManualNumber(entry.durationMinutes);
  const repetitions = parseRiskAssessmentManualNumber(entry.repetitionsPerShift);
  const force = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_REPETITIVE_FORCE_OPTIONS, entry.forceLevel || "small");
  const headNeck = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_BODY_PART_OPTIONS, entry.bodyHeadNeck || "none");
  const back = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_BODY_PART_OPTIONS, entry.bodyBack || "none");
  const shoulder = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_BODY_PART_STRONG_OPTIONS, entry.bodyShoulder || "none");
  const elbow = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_BODY_PART_STRONG_OPTIONS, entry.bodyElbow || "none");
  const wrist = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_BODY_PART_OPTIONS, entry.bodyWrist || "none");
  const fingers = getRiskAssessmentManualOption(RISK_ASSESSMENT_MANUAL_BODY_PART_OPTIONS, entry.bodyFingers || "none");
  const t1Points = getRiskAssessmentManualRepetitiveT1Points(durationMinutes);
  const t2Points = getRiskAssessmentManualRepetitiveT2Points(repetitions);
  const t3Points = force.points;
  const t4Points = Number((headNeck.points + back.points + shoulder.points + elbow.points + wrist.points + fingers.points).toFixed(1));
  const score = t1Points ? Number(((t2Points + t3Points + t4Points) * t1Points).toFixed(1)) : 0;
  return {
    methodType: "repetitive",
    methodLabel: getRiskAssessmentManualMethodOption("repetitive").label,
    formulaText: "(T2 + T3 + T4) × T1",
    formulaValueText: `${t1Points} × (${t2Points} + ${t3Points} + ${t4Points})`,
    durationMinutes,
    repetitionsPerShift: repetitions,
    forceLabel: force.label,
    score,
    t1Points,
    t2Points,
    t3Points,
    t4Points,
    bodyPartLabels: [
      `Glava/vrat: ${headNeck.label}`,
      `Leđa: ${back.label}`,
      `Rame: ${shoulder.label}`,
      `Lakat: ${elbow.label}`,
      `Ručni zglob: ${wrist.label}`,
      `Prsti: ${fingers.label}`,
    ],
    operationLabel: "Ponavljajući pokreti",
    workerGenderLabel: "",
    postureLabel: "Zbroj položaja tijela po dijelovima",
    workConditionLabel: force.label,
    factorLabels: [`T1 ${t1Points}`, `T2 ${t2Points}`, `T3 ${t3Points}`, `T4 ${t4Points}`],
    workloadText: [durationMinutes ? `${durationMinutes} min` : "", repetitions ? `${repetitions} pokreta/smjenu` : ""].filter(Boolean).join(" / "),
    ...getRiskAssessmentManualRiskTone(score, "repetitive"),
  };
}

function calculateRiskAssessmentManualHandling(entry = {}) {
  const method = normalizeRiskAssessmentManualMethod(entry.methodType || entry.calculationType || entry.method);
  if (method === "push_pull") return calculateRiskAssessmentManualPushPull(entry);
  if (method === "repetitive") return calculateRiskAssessmentManualRepetitive(entry);
  return calculateRiskAssessmentManualLoad(entry);
}

function getRiskAssessmentManualFactorSummary(calculation = {}) {
  return (Array.isArray(calculation.factorLabels) ? calculation.factorLabels : []).filter(Boolean).join(" · ") || "T vrijednosti nisu izračunate";
}

function getRiskAssessmentManualWorkloadSummary(calculation = {}) {
  return calculation.workloadText || "Nije izračunato";
}

function getRiskAssessmentManualEntryTitle(entry = {}, fallback = "IOR izračun") {
  const method = getRiskAssessmentManualMethodOption(entry.methodType || entry.calculationType || entry.method);
  return String(entry.activity || "").trim() || method.shortLabel || fallback;
}

function normalizeRiskAssessmentManualBodyValue(value = "", options = RISK_ASSESSMENT_MANUAL_BODY_PART_OPTIONS) {
  const normalized = String(value || "");
  return options.some((option) => option.value === normalized) ? normalized : "none";
}

function normalizeRiskAssessmentManualSelectValue(value = "", options = []) {
  const normalized = String(value || "");
  return options.some((option) => option.value === normalized) ? normalized : (options[0]?.value || "");
}

function normalizeRiskAssessmentManualPostureValue(value = "") {
  const normalized = String(value || "");
  if (normalized === "bent" || normalized === "twist") return "slight";
  if (normalized === "overhead") return "unfavorable";
  if (normalized === "neutral") return "upright";
  return RISK_ASSESSMENT_MANUAL_POSTURE_OPTIONS.some((option) => option.value === normalized) ? normalized : "upright";
}

function createRiskAssessmentManualHandlingDraft(initial = {}) {
  return {
    id: String(initial.id || crypto.randomUUID()),
    activity: String(initial.activity || initial.title || ""),
    methodType: normalizeRiskAssessmentManualMethod(initial.methodType || initial.calculationType || initial.method),
    jobId: String(initial.jobId || ""),
    operationType: String(initial.operationType || "lift"),
    workerGender: String(initial.workerGender || "male"),
    loadWeightKg: String(initial.loadWeightKg ?? initial.massKg ?? ""),
    transfersPerHour: String(initial.transfersPerHour ?? initial.frequencyPerHour ?? ""),
    durationMinutes: String(initial.durationMinutes ?? ""),
    carryingDistanceMeters: String(initial.carryingDistanceMeters ?? initial.distanceMeters ?? ""),
    verticalLiftCm: String(initial.verticalLiftCm ?? ""),
    horizontalReachCm: String(initial.horizontalReachCm ?? ""),
    posture: normalizeRiskAssessmentManualPostureValue(initial.posture),
    workConditions: String(initial.workConditions || "good"),
    gripQuality: String(initial.gripQuality || "good"),
    pushPullMode: normalizeRiskAssessmentManualSelectValue(initial.pushPullMode, RISK_ASSESSMENT_MANUAL_PUSH_PULL_MODE_OPTIONS),
    pushPullTransport: normalizeRiskAssessmentManualSelectValue(initial.pushPullTransport, RISK_ASSESSMENT_MANUAL_PUSH_PULL_TRANSPORT_OPTIONS),
    pushPullPrecisionSpeed: normalizeRiskAssessmentManualSelectValue(initial.pushPullPrecisionSpeed, RISK_ASSESSMENT_MANUAL_PUSH_PULL_PRECISION_OPTIONS),
    pushPullPosture: normalizeRiskAssessmentManualSelectValue(initial.pushPullPosture || initial.posture, RISK_ASSESSMENT_MANUAL_PUSH_PULL_POSTURE_OPTIONS),
    pushPullWorkConditions: normalizeRiskAssessmentManualSelectValue(initial.pushPullWorkConditions, RISK_ASSESSMENT_MANUAL_PUSH_PULL_WORK_CONDITION_OPTIONS),
    repetitionsPerShift: String(initial.repetitionsPerShift ?? initial.repetitions ?? ""),
    forceLevel: normalizeRiskAssessmentManualSelectValue(initial.forceLevel, RISK_ASSESSMENT_MANUAL_REPETITIVE_FORCE_OPTIONS),
    bodyHeadNeck: normalizeRiskAssessmentManualBodyValue(initial.bodyHeadNeck),
    bodyBack: normalizeRiskAssessmentManualBodyValue(initial.bodyBack),
    bodyShoulder: normalizeRiskAssessmentManualBodyValue(initial.bodyShoulder, RISK_ASSESSMENT_MANUAL_BODY_PART_STRONG_OPTIONS),
    bodyElbow: normalizeRiskAssessmentManualBodyValue(initial.bodyElbow, RISK_ASSESSMENT_MANUAL_BODY_PART_STRONG_OPTIONS),
    bodyWrist: normalizeRiskAssessmentManualBodyValue(initial.bodyWrist),
    bodyFingers: normalizeRiskAssessmentManualBodyValue(initial.bodyFingers),
    existingMeasures: String(initial.existingMeasures || initial.measures || ""),
    note: String(initial.note || ""),
  };
}

function sanitizeRiskAssessmentManualHandlingDraft(entry = {}) {
  const draft = createRiskAssessmentManualHandlingDraft(entry);
  return {
    id: draft.id,
    activity: draft.activity.trim(),
    methodType: draft.methodType,
    jobId: draft.jobId,
    operationType: draft.operationType,
    workerGender: draft.workerGender,
    loadWeightKg: draft.loadWeightKg.trim(),
    transfersPerHour: draft.transfersPerHour.trim(),
    durationMinutes: draft.durationMinutes.trim(),
    carryingDistanceMeters: draft.carryingDistanceMeters.trim(),
    verticalLiftCm: draft.verticalLiftCm.trim(),
    horizontalReachCm: draft.horizontalReachCm.trim(),
    posture: draft.posture,
    workConditions: draft.workConditions,
    gripQuality: draft.gripQuality,
    pushPullMode: draft.pushPullMode,
    pushPullTransport: draft.pushPullTransport,
    pushPullPrecisionSpeed: draft.pushPullPrecisionSpeed,
    pushPullPosture: draft.pushPullPosture,
    pushPullWorkConditions: draft.pushPullWorkConditions,
    repetitionsPerShift: draft.repetitionsPerShift.trim(),
    forceLevel: draft.forceLevel,
    bodyHeadNeck: draft.bodyHeadNeck,
    bodyBack: draft.bodyBack,
    bodyShoulder: draft.bodyShoulder,
    bodyElbow: draft.bodyElbow,
    bodyWrist: draft.bodyWrist,
    bodyFingers: draft.bodyFingers,
    existingMeasures: draft.existingMeasures.trim(),
    note: draft.note.trim(),
  };
}

function renderRiskAssessmentManualOptionList(options = [], value = "") {
  return options.map((option) => `
    <option value="${escapeHtml(option.value)}" ${option.value === value ? "selected" : ""}>${escapeHtml(option.label)}</option>
  `).join("");
}

function renderRiskAssessmentManualScope() {
  if (!riskAssessmentManualScopePanel) {
    return;
  }
  const scope = createRiskAssessmentManualScopeDraft(riskAssessmentManualHandlingScopeDraft);
  const selectedUnits = new Set(scope.unitIds.map(String));
  const selectedJobs = new Set(scope.jobIds.map(String));
  const summary = getRiskAssessmentManualScopeSummary(scope);
  const unitButtons = riskAssessmentOrganizationUnitDrafts.length
    ? riskAssessmentOrganizationUnitDrafts.map((unit, index) => {
      const id = String(unit.id || `unit-${index}`);
      const jobsInUnit = riskAssessmentJobDrafts.filter((job) => String(job.organizationUnitId || "") === id).length;
      return `
        <button type="button" class="risk-assessment-manual-scope-chip ${selectedUnits.has(id) ? "is-selected" : ""}" data-risk-manual-scope-type="unit" data-risk-manual-scope-id="${escapeHtml(id)}">
          <strong>${escapeHtml(unit.name || `Organizacija ${index + 1}`)}</strong>
          <span>${escapeHtml(jobsInUnit ? `${jobsInUnit} radnih mjesta` : "Bez radnih mjesta")}</span>
        </button>
      `;
    }).join("")
    : `<p class="inline-help">Organizacijske jedinice nisu dodane. Možeš odabrati pojedina radna mjesta.</p>`;
  const jobButtons = riskAssessmentJobDrafts.length
    ? riskAssessmentJobDrafts.map((job, index) => {
      const id = String(job.id || `job-${index}`);
      const unit = riskAssessmentOrganizationUnitDrafts.find((entry) => String(entry.id || "") === String(job.organizationUnitId || ""));
      const isInherited = unit && selectedUnits.has(String(unit.id || ""));
      return `
        <button type="button" class="risk-assessment-manual-scope-chip is-job ${selectedJobs.has(id) || isInherited ? "is-selected" : ""} ${isInherited ? "is-inherited" : ""}" data-risk-manual-scope-type="job" data-risk-manual-scope-id="${escapeHtml(id)}">
          <strong>${escapeHtml(job.jobTitle || `Radno mjesto ${index + 1}`)}</strong>
          <span>${escapeHtml(isInherited ? `Uključeno kroz ${unit.name}` : (unit?.name || "Bez organizacije"))}</span>
        </button>
      `;
    }).join("")
    : `<p class="inline-help">Dodaj radna mjesta u procjeni pa ih ovdje označi za IOR.</p>`;

  riskAssessmentManualScopePanel.innerHTML = `
    <section class="risk-assessment-manual-scope-hero">
      <div>
        <span class="section-kicker">Opseg IOR-a</span>
        <strong>Koja radna mjesta imaju ručno rukovanje teretom?</strong>
        <p>Odaberi organizacijsku jedinicu ili pojedina radna mjesta. Izračuni ispod vrijede za ovaj odabrani opseg, ne za opis posla.</p>
      </div>
      <div class="risk-assessment-manual-scope-count">
        <strong>${escapeHtml(String(summary.count))}</strong>
        <span>radnih mjesta</span>
      </div>
    </section>
    <div class="risk-assessment-manual-scope-summary">${escapeHtml(summary.text).replace(/\n/g, "<br>")}</div>
    <div class="risk-assessment-manual-scope-group">
      <div class="risk-assessment-manual-scope-title">
        <strong>Organizacija</strong>
        <span>Klikom odabireš sve poslove unutar jedinice.</span>
      </div>
      <div class="risk-assessment-manual-scope-chips">${unitButtons}</div>
    </div>
    <div class="risk-assessment-manual-scope-group">
      <div class="risk-assessment-manual-scope-title">
        <strong>Radna mjesta</strong>
        <span>Pojedinačni odabir kada ne želiš uzeti cijelu organizaciju.</span>
      </div>
      <div class="risk-assessment-manual-scope-chips">${jobButtons}</div>
    </div>
    <div class="risk-assessment-manual-scope-actions">
      <button type="button" class="ghost-button" data-risk-manual-scope-action="select-all-jobs">Sva radna mjesta</button>
      <button type="button" class="ghost-button" data-risk-manual-scope-action="clear">Očisti opseg</button>
    </div>
  `;
}

function handleRiskAssessmentManualScopeClick(event) {
  const actionButton = event.target?.closest?.("[data-risk-manual-scope-action]");
  if (actionButton) {
    const action = actionButton.dataset.riskManualScopeAction;
    if (action === "clear") {
      riskAssessmentManualHandlingScopeDraft = { unitIds: [], jobIds: [] };
    } else if (action === "select-all-jobs") {
      riskAssessmentManualHandlingScopeDraft = {
        unitIds: [],
        jobIds: riskAssessmentJobDrafts.map((job) => String(job.id || "")).filter(Boolean),
      };
    }
    renderRiskAssessmentManualScope();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  const chip = event.target?.closest?.("[data-risk-manual-scope-type][data-risk-manual-scope-id]");
  if (!chip) {
    return;
  }
  const type = String(chip.dataset.riskManualScopeType || "");
  const id = String(chip.dataset.riskManualScopeId || "");
  if (!id) {
    return;
  }
  const scope = createRiskAssessmentManualScopeDraft(riskAssessmentManualHandlingScopeDraft);
  const key = type === "unit" ? "unitIds" : "jobIds";
  const current = new Set(scope[key].map(String));
  if (current.has(id)) {
    current.delete(id);
  } else {
    current.add(id);
  }
  riskAssessmentManualHandlingScopeDraft = {
    ...scope,
    [key]: Array.from(current),
  };
  renderRiskAssessmentManualScope();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function renderRiskAssessmentManualJobOptions(selectedValue = "") {
  const options = [{ value: "", label: "Nije vezano uz posao" }].concat(
    riskAssessmentJobDrafts.map((job, index) => ({
      value: String(job.id || `job-${index}`),
      label: job.jobTitle || `Posao ${index + 1}`,
    })),
  );
  return options.map((option) => `
    <option value="${escapeHtml(option.value)}" ${String(option.value) === String(selectedValue) ? "selected" : ""}>${escapeHtml(option.label)}</option>
  `).join("");
}

function refreshRiskAssessmentManualHandlingCard(card = null, index = -1) {
  const entry = riskAssessmentManualHandlingDrafts[index];
  if (!card || !entry) {
    return;
  }
  const calculation = calculateRiskAssessmentManualHandling(entry);
  card.dataset.riskTone = calculation.tone;
  const result = card.querySelector("[data-risk-manual-result]");
  if (result) {
    result.textContent = calculation.level;
    result.className = `risk-assessment-manual-result is-${calculation.tone}`;
  }
  const score = card.querySelector("[data-risk-manual-score]");
  if (score) {
    score.textContent = String(calculation.score);
  }
  const method = card.querySelector("[data-risk-manual-method-label]");
  if (method) {
    method.textContent = calculation.methodLabel;
  }
  const factors = card.querySelector("[data-risk-manual-factors]");
  if (factors) {
    factors.textContent = getRiskAssessmentManualFactorSummary(calculation);
  }
  const workload = card.querySelector("[data-risk-manual-workload]");
  if (workload) {
    workload.textContent = getRiskAssessmentManualWorkloadSummary(calculation);
  }
  const recommendation = card.querySelector("[data-risk-manual-recommendation]");
  if (recommendation) {
    recommendation.textContent = calculation.recommendation;
  }
}

function updateRiskAssessmentManualHandlingField(index, field = "", value = "", card = null) {
  const current = riskAssessmentManualHandlingDrafts[index];
  if (!current || !field) {
    return;
  }
  riskAssessmentManualHandlingDrafts[index] = {
    ...current,
    [field]: value,
  };
  refreshRiskAssessmentManualHandlingCard(card, index);
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function renderRiskAssessmentManualLoadFields(entry = {}) {
  return `
    <label><span>Vrsta radnje</span><select data-risk-manual-field="operationType">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_OPERATION_OPTIONS, entry.operationType)}</select></label>
    <label><span>Masa tereta (kg)</span><input data-risk-manual-field="loadWeightKg" inputmode="decimal" value="${escapeHtml(entry.loadWeightKg)}" /></label>
    <label><span>Ponavljanja / sat</span><input data-risk-manual-field="transfersPerHour" inputmode="decimal" value="${escapeHtml(entry.transfersPerHour)}" /></label>
    <label><span>Trajanje (min)</span><input data-risk-manual-field="durationMinutes" inputmode="decimal" value="${escapeHtml(entry.durationMinutes)}" /></label>
    <label><span>Udaljenost po prijenosu (m)</span><input data-risk-manual-field="carryingDistanceMeters" inputmode="decimal" value="${escapeHtml(entry.carryingDistanceMeters)}" /></label>
    <label><span>Položaj tijela</span><select data-risk-manual-field="posture">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_POSTURE_OPTIONS, entry.posture)}</select></label>
    <label><span>Uvjeti rada</span><select data-risk-manual-field="workConditions">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_WORK_CONDITION_OPTIONS, entry.workConditions)}</select></label>
  `;
}

function renderRiskAssessmentManualPushPullFields(entry = {}) {
  return `
    <label><span>Način rada</span><select data-risk-manual-field="pushPullMode">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_PUSH_PULL_MODE_OPTIONS, entry.pushPullMode)}</select></label>
    <label><span>Masa tereta (kg)</span><input data-risk-manual-field="loadWeightKg" inputmode="decimal" value="${escapeHtml(entry.loadWeightKg)}" /></label>
    <label><span>Pomagalo / transport</span><select data-risk-manual-field="pushPullTransport">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_PUSH_PULL_TRANSPORT_OPTIONS, entry.pushPullTransport)}</select></label>
    <label><span>Preciznost i brzina</span><select data-risk-manual-field="pushPullPrecisionSpeed">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_PUSH_PULL_PRECISION_OPTIONS, entry.pushPullPrecisionSpeed)}</select></label>
    <label><span>Ponavljanja / sat</span><input data-risk-manual-field="transfersPerHour" inputmode="decimal" value="${escapeHtml(entry.transfersPerHour)}" /></label>
    <label><span>Trajanje (min)</span><input data-risk-manual-field="durationMinutes" inputmode="decimal" value="${escapeHtml(entry.durationMinutes)}" /></label>
    <label><span>Udaljenost po radnji (m)</span><input data-risk-manual-field="carryingDistanceMeters" inputmode="decimal" value="${escapeHtml(entry.carryingDistanceMeters)}" /></label>
    <label><span>Položaj tijela</span><select data-risk-manual-field="pushPullPosture">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_PUSH_PULL_POSTURE_OPTIONS, entry.pushPullPosture)}</select></label>
    <label><span>Radni uvjeti</span><select data-risk-manual-field="pushPullWorkConditions">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_PUSH_PULL_WORK_CONDITION_OPTIONS, entry.pushPullWorkConditions)}</select></label>
  `;
}

function renderRiskAssessmentManualRepetitiveFields(entry = {}) {
  return `
    <label><span>Trajanje zadatka (min)</span><input data-risk-manual-field="durationMinutes" inputmode="decimal" value="${escapeHtml(entry.durationMinutes)}" /></label>
    <label><span>Broj pokreta / smjenu</span><input data-risk-manual-field="repetitionsPerShift" inputmode="decimal" value="${escapeHtml(entry.repetitionsPerShift)}" /></label>
    <label><span>Potrebna snaga</span><select data-risk-manual-field="forceLevel">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_REPETITIVE_FORCE_OPTIONS, entry.forceLevel)}</select></label>
    <label><span>Glava i vrat</span><select data-risk-manual-field="bodyHeadNeck">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_BODY_PART_OPTIONS, entry.bodyHeadNeck)}</select></label>
    <label><span>Leđa</span><select data-risk-manual-field="bodyBack">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_BODY_PART_OPTIONS, entry.bodyBack)}</select></label>
    <label><span>Rame</span><select data-risk-manual-field="bodyShoulder">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_BODY_PART_STRONG_OPTIONS, entry.bodyShoulder)}</select></label>
    <label><span>Lakat</span><select data-risk-manual-field="bodyElbow">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_BODY_PART_STRONG_OPTIONS, entry.bodyElbow)}</select></label>
    <label><span>Ručni zglob</span><select data-risk-manual-field="bodyWrist">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_BODY_PART_OPTIONS, entry.bodyWrist)}</select></label>
    <label><span>Prsti</span><select data-risk-manual-field="bodyFingers">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_BODY_PART_OPTIONS, entry.bodyFingers)}</select></label>
  `;
}

function renderRiskAssessmentManualMethodFields(entry = {}) {
  const method = normalizeRiskAssessmentManualMethod(entry.methodType);
  if (method === "push_pull") {
    return renderRiskAssessmentManualPushPullFields(entry);
  }
  if (method === "repetitive") {
    return renderRiskAssessmentManualRepetitiveFields(entry);
  }
  return renderRiskAssessmentManualLoadFields(entry);
}

function renderRiskAssessmentManualHandling() {
  if (!riskAssessmentManualHandlingList) {
    return;
  }
  if (!riskAssessmentManualHandlingDrafts.length) {
    const empty = document.createElement("p");
    empty.className = "inline-help";
    empty.textContent = "Dodaj IOR izračun za odabrani opseg radnih mjesta.";
    riskAssessmentManualHandlingList.replaceChildren(empty);
    return;
  }

  riskAssessmentManualHandlingList.replaceChildren(...riskAssessmentManualHandlingDrafts.map((entry, index) => {
    const calculation = calculateRiskAssessmentManualHandling(entry);
    const method = getRiskAssessmentManualMethodOption(entry.methodType);
    const row = document.createElement("article");
    row.className = "risk-assessment-manual-card";
    row.dataset.riskManualIndex = String(index);
    row.dataset.riskTone = calculation.tone;
    row.innerHTML = `
      <div class="risk-assessment-manual-head">
        <div>
          <span class="section-kicker">IOR ${index + 1} · <span data-risk-manual-method-label>${escapeHtml(calculation.methodLabel)}</span></span>
          <strong>${escapeHtml(getRiskAssessmentManualEntryTitle(entry, `IOR ${index + 1}`))}</strong>
          <small data-risk-manual-recommendation>${escapeHtml(calculation.recommendation)}</small>
        </div>
        <div class="risk-assessment-manual-metrics">
          <span data-risk-manual-result class="risk-assessment-manual-result is-${escapeHtml(calculation.tone)}">${escapeHtml(calculation.level)}</span>
          <span><b data-risk-manual-score>${escapeHtml(String(calculation.score))}</b> bodova</span>
          <span>${escapeHtml(method.formula)}</span>
          <span data-risk-manual-factors>${escapeHtml(getRiskAssessmentManualFactorSummary(calculation))}</span>
          <span data-risk-manual-workload>${escapeHtml(getRiskAssessmentManualWorkloadSummary(calculation))}</span>
        </div>
      </div>
      <div class="risk-assessment-manual-flow" aria-hidden="true">
        <span>Opseg</span><strong>${escapeHtml(getRiskAssessmentManualScopeSummary().count ? `${getRiskAssessmentManualScopeSummary().count} radnih mjesta` : "nije odabran")}</strong>
        <span>Vrijednosti</span><strong>${escapeHtml(getRiskAssessmentManualWorkloadSummary(calculation))}</strong>
        <span>Izračun</span><strong>${escapeHtml(calculation.formulaValueText || method.formula)}</strong>
        <span>Ocjena</span><strong>${escapeHtml(`${calculation.score} bodova`)}</strong>
      </div>
      <div class="risk-assessment-manual-grid">
        <label><span>Aktivnost</span><input data-risk-manual-field="activity" value="${escapeHtml(entry.activity)}" placeholder="npr. Premještanje boca / kutija" /></label>
        <label><span>Tip IOR-a</span><select data-risk-manual-field="methodType">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_METHOD_OPTIONS, entry.methodType)}</select></label>
        <label><span>Radnik</span><select data-risk-manual-field="workerGender">${renderRiskAssessmentManualOptionList(RISK_ASSESSMENT_MANUAL_WORKER_GENDER_OPTIONS, entry.workerGender)}</select></label>
        <label><span>Primjena</span><input value="${escapeHtml(getRiskAssessmentManualScopeSummary().count ? `${getRiskAssessmentManualScopeSummary().count} radnih mjesta u opsegu` : "Opseg odaberi gore")}" readonly /></label>
        ${renderRiskAssessmentManualMethodFields(entry)}
        <label class="field-span-full"><span>Postojeće / potrebne mjere</span><textarea data-risk-manual-field="existingMeasures" rows="2">${escapeHtml(entry.existingMeasures)}</textarea></label>
        <label class="field-span-full"><span>Napomena</span><textarea data-risk-manual-field="note" rows="2">${escapeHtml(entry.note)}</textarea></label>
      </div>
      <div class="risk-assessment-manual-actions">
        <button type="button" class="ghost-button card-danger" data-risk-manual-remove="${index}">Ukloni izračun</button>
      </div>
    `;
    return row;
  }));
}

function renderRiskAssessmentOverview() {
  if (!riskAssessmentOverview) {
    return;
  }
  const summary = getRiskAssessmentFinalSummaryData();
  const readinessTone = getRiskAssessmentFinalReadinessTone(summary.readinessPercent);
  const readinessLabel = readinessTone === "ready"
    ? "Spremno za izvoz"
    : readinessTone === "warning"
      ? "Skoro spremno"
      : "U izradi";
  const canManage = getCanManageRiskAssessments();
  const canExport = canManage
    && Boolean(summary.wordTemplate?.dataUrl)
    && Boolean(state.riskAssessmentEditorOpen || riskAssessmentIdInput?.value || riskAssessmentCompanyInput?.value)
    && !riskAssessmentWordExportBusy;
  const unitsHtml = riskAssessmentOrganizationUnitDrafts.length
    ? riskAssessmentOrganizationUnitDrafts.map((unit) => {
      const unitJobs = riskAssessmentJobDrafts.filter((job) => String(job.organizationUnitId) === String(unit.id));
      return `
        <article class="risk-assessment-overview-card">
          <span class="section-kicker">${escapeHtml(unit.responsiblePerson || "Bez odgovorne osobe")}</span>
          <strong>${escapeHtml(unit.name || "Organizacijska jedinica")}</strong>
          <small>${escapeHtml(formatRiskAssessmentWorkerCount(unit, { includeLabel: true, fallback: "Broj radnika nije unesen" }))}</small>
          <div>${unitJobs.map((job) => `<span>${escapeHtml(job.jobTitle || "Radno mjesto")} · ${getRiskAssessmentJobCompletion(job)}%</span>`).join("") || "<span>Nema povezanih poslova</span>"}</div>
        </article>
      `;
    }).join("")
    : `<p class="inline-help">Dodaj organizacijske jedinice za strukturirani pregled procjene.</p>`;
  const chemicalsHtml = riskAssessmentChemicalDrafts.length
    ? `
      <div class="risk-assessment-overview-chemicals">
        ${riskAssessmentChemicalDrafts.map((chemical) => `
          <article>
            <span class="section-kicker">${escapeHtml([chemical.source, chemical.casNumber ? `CAS ${chemical.casNumber}` : ""].filter(Boolean).join(" · ") || "Kemikalija")}</span>
            <strong>${escapeHtml(chemical.name || "Kemikalija")}</strong>
            <small>${escapeHtml([chemical.formula, chemical.signalWords?.join(", "), chemical.hazardStatements?.[0]].filter(Boolean).join(" · ") || "Bez dodatnih podataka")}</small>
          </article>
        `).join("")}
      </div>
    `
    : "";
  const ppeByJobHtml = riskAssessmentJobDrafts.length
    ? `
      <section class="risk-assessment-overview-table-section">
        <div class="risk-assessment-overview-section-head">
          <span class="section-kicker">OZO po radnim mjestima</span>
          <strong>Pregled osobne zaštitne opreme</strong>
        </div>
        ${renderRiskAssessmentPpeByJobTable()}
      </section>
    `
    : "";

  riskAssessmentOverview.innerHTML = `
    <section class="risk-assessment-overview-hero">
      <div>
        <span class="section-kicker">Završni sheet</span>
        <h3>${escapeHtml(summary.companyName ? `Pregled za ${summary.companyName}` : "Pregled procjene rizika")}</h3>
        <p>${escapeHtml([
          summary.status || "Status nije odabran",
          summary.assessmentDate ? `Datum ${summary.assessmentDate}` : "",
          summary.completionDate ? `Završetak ${summary.completionDate}` : "",
        ].filter(Boolean).join(" · "))}</p>
      </div>
      <div class="risk-assessment-overview-readiness is-${escapeHtml(readinessTone)}">
        <strong>${escapeHtml(String(summary.readinessPercent))}%</strong>
        <span>${escapeHtml(readinessLabel)}</span>
      </div>
    </section>
    <section class="risk-assessment-overview-export-panel">
      <div class="risk-assessment-overview-export-copy">
        <span class="section-kicker">Izvoz dokumenta</span>
        <strong>${escapeHtml(summary.wordTemplate?.fileName ? "Template je učitan" : "Word template nije učitan")}</strong>
        <small>${escapeHtml(summary.wordTemplate?.fileName || "Word template se postavlja na početnom prozoru modula.")}</small>
        <em>${escapeHtml(summary.fileBaseName)}</em>
      </div>
      <div class="risk-assessment-overview-export-actions">
        <button type="button" class="secondary-button" data-risk-overview-export="docx" ${canExport ? "" : "disabled"}>Word DOCX</button>
        <button type="button" class="primary-button" data-risk-overview-export="pdf" ${canExport ? "" : "disabled"}>PDF</button>
      </div>
    </section>
    <div class="risk-assessment-overview-checklist">
      ${summary.checklist.map((item) => `
        <article class="${item.ok ? "is-ok" : "is-missing"}">
          <span>${item.ok ? "✓" : "!"}</span>
          <div>
            <strong>${escapeHtml(item.label)}</strong>
            <small>${escapeHtml(item.detail)}</small>
          </div>
        </article>
      `).join("")}
    </div>
    <div class="risk-assessment-overview-stats">
      <span><strong>${escapeHtml(String(summary.workplaceCount))}</strong> mjesta rada</span>
      <span><strong>${escapeHtml(String(summary.units))}</strong> jedinica</span>
      <span><strong>${escapeHtml(String(summary.jobs))}</strong> poslova</span>
      <span><strong>${escapeHtml(String(summary.readyJobs))}</strong> spremno</span>
      <span><strong>${escapeHtml(String(summary.totalRisks))}</strong> rizika</span>
      <span><strong>${escapeHtml(String(summary.totalManualHandling))}</strong> IOR</span>
      <span><strong>${escapeHtml(String(summary.highManualHandling))}</strong> visokih IOR</span>
      <span><strong>${escapeHtml(String(summary.totalChemicals))}</strong> kemikalija</span>
      <span><strong>${escapeHtml(String(summary.appendixData.equipmentItems.length))}</strong> oprema</span>
      <span><strong>${escapeHtml(String(summary.appendixData.inspectionItems.length))}</strong> ispitivanja</span>
      <span><strong>${escapeHtml(String(summary.totalPpe))}</strong> OZO</span>
    </div>
    <div class="risk-assessment-overview-grid">${unitsHtml}</div>
    ${ppeByJobHtml}
    ${chemicalsHtml}
  `;
  renderRiskAssessmentLinkedAppendix();
  renderRiskAssessmentTemplatePreview();
}

function getRiskAssessmentJobIndexFromElement(element) {
  const row = element?.closest?.("[data-risk-job-index]");
  const index = Number(row?.dataset?.riskJobIndex);
  return Number.isInteger(index) && index >= 0 ? index : -1;
}

function getRiskAssessmentUnitIndexFromElement(element) {
  const row = element?.closest?.("[data-risk-unit-index]");
  const index = Number(row?.dataset?.riskUnitIndex);
  return Number.isInteger(index) && index >= 0 ? index : -1;
}

function getRiskAssessmentManualIndexFromElement(element) {
  const row = element?.closest?.("[data-risk-manual-index]");
  const index = Number(row?.dataset?.riskManualIndex);
  return Number.isInteger(index) && index >= 0 ? index : -1;
}

function handleRiskAssessmentManualHandlingInput(event) {
  const target = event.target;
  if (!(
    target instanceof HTMLInputElement
    || target instanceof HTMLTextAreaElement
    || target instanceof HTMLSelectElement
  )) {
    return;
  }
  if (event.type === "input" && target instanceof HTMLSelectElement) {
    return;
  }
  if (event.type === "change" && !(target instanceof HTMLSelectElement)) {
    return;
  }
  const field = target.dataset.riskManualField;
  if (!field) {
    return;
  }
  const card = target.closest("[data-risk-manual-index]");
  const index = getRiskAssessmentManualIndexFromElement(target);
  updateRiskAssessmentManualHandlingField(index, field, target.value, card);
  if (field === "methodType") {
    renderRiskAssessmentManualHandling();
  }
}

function handleRiskAssessmentManualHandlingClick(event) {
  const removeButton = event.target?.closest?.("[data-risk-manual-remove]");
  if (!removeButton) {
    return;
  }
  const index = Number(removeButton.dataset.riskManualRemove);
  if (!Number.isInteger(index) || index < 0) {
    return;
  }
  riskAssessmentManualHandlingDrafts.splice(index, 1);
  renderRiskAssessmentManualHandling();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function refreshRiskAssessmentJobDocumentPreview(jobIndex) {
  const row = riskAssessmentJobsList?.querySelector(`[data-risk-job-index="${jobIndex}"]`);
  const documentPreview = row?.querySelector?.(".risk-assessment-job-document");
  const job = riskAssessmentJobDrafts[jobIndex];
  if (documentPreview && job) {
    documentPreview.outerHTML = renderRiskAssessmentJobDocumentPreview(job, jobIndex);
  }
}

function scheduleRiskAssessmentJobDocumentPreviewRefresh(jobIndex) {
  if (!Number.isInteger(jobIndex) || jobIndex < 0) {
    return;
  }
  const existingTimer = riskAssessmentJobDocumentPreviewTimers.get(jobIndex);
  if (existingTimer) {
    window.clearTimeout(existingTimer);
  }
  const timer = window.setTimeout(() => {
    riskAssessmentJobDocumentPreviewTimers.delete(jobIndex);
    refreshRiskAssessmentJobDocumentPreview(jobIndex);
  }, 180);
  riskAssessmentJobDocumentPreviewTimers.set(jobIndex, timer);
}

function scheduleRiskAssessmentOverviewRender() {
  if (riskAssessmentOverviewRenderTimer) {
    window.clearTimeout(riskAssessmentOverviewRenderTimer);
  }
  riskAssessmentOverviewRenderTimer = window.setTimeout(() => {
    riskAssessmentOverviewRenderTimer = null;
    renderRiskAssessmentOverview();
  }, 180);
}

function scheduleRiskAssessmentJobTreeRender({ immediate = false } = {}) {
  if (!riskAssessmentJobTree) {
    return;
  }
  if (riskAssessmentJobTreeRenderTimer) {
    window.clearTimeout(riskAssessmentJobTreeRenderTimer);
    riskAssessmentJobTreeRenderTimer = null;
  }
  if (immediate) {
    renderRiskAssessmentJobTree();
    return;
  }
  riskAssessmentJobTreeRenderTimer = window.setTimeout(() => {
    riskAssessmentJobTreeRenderTimer = null;
    renderRiskAssessmentJobTree();
  }, 140);
}

function scheduleRiskAssessmentJobCatalogPickerRender({ immediate = false } = {}) {
  if (!riskAssessmentJobCatalogList) {
    return;
  }
  if (riskAssessmentJobCatalogPickerRenderTimer) {
    window.clearTimeout(riskAssessmentJobCatalogPickerRenderTimer);
    riskAssessmentJobCatalogPickerRenderTimer = null;
  }
  if (immediate) {
    renderRiskAssessmentJobCatalogPicker();
    return;
  }
  riskAssessmentJobCatalogPickerRenderTimer = window.setTimeout(() => {
    riskAssessmentJobCatalogPickerRenderTimer = null;
    renderRiskAssessmentJobCatalogPicker();
  }, 160);
}

function handleRiskAssessmentOrganizationUnitsInput(event) {
  const target = event.target;
  if (!(
    target instanceof HTMLInputElement
    || target instanceof HTMLTextAreaElement
    || target instanceof HTMLSelectElement
  )) {
    return;
  }
  if (event.type === "input" && target instanceof HTMLSelectElement) {
    return;
  }
  if (event.type === "change" && !(target instanceof HTMLSelectElement)) {
    return;
  }

  const unitIndex = getRiskAssessmentUnitIndexFromElement(target);
  if (unitIndex < 0) {
    return;
  }
  if (target.dataset.riskUnitAiText !== undefined) {
    const proposal = riskAssessmentOrganizationUnitDrafts[unitIndex]?.aiProposal;
    if (proposal) {
      riskAssessmentOrganizationUnitDrafts[unitIndex] = {
        ...riskAssessmentOrganizationUnitDrafts[unitIndex],
        aiProposal: {
          ...proposal,
          text: target.value,
        },
      };
    }
    return;
  }
  const field = target.dataset.riskUnitField;
  if (!field) {
    return;
  }
  riskAssessmentOrganizationUnitDrafts[unitIndex] = {
    ...riskAssessmentOrganizationUnitDrafts[unitIndex],
    [field]: field === "type" ? normalizeRiskAssessmentUnitType(target.value) : target.value,
  };
  if (["parentId", "type"].includes(field)) {
    renderRiskAssessmentOrganizationUnits();
    renderRiskAssessmentJobs();
  }
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function handleRiskAssessmentOrganizationUnitsClick(event) {
  const button = event.target?.closest?.("button");
  if (!(button instanceof HTMLButtonElement)) {
    return;
  }
  const unitIndex = getRiskAssessmentUnitIndexFromElement(button);
  if (unitIndex < 0) {
    return;
  }
  if (button.matches("[data-risk-unit-add-child]")) {
    event.preventDefault();
    addRiskAssessmentChildUnit(unitIndex, button.dataset.riskUnitChildType || "subunit");
    return;
  }
  if (button.matches("[data-risk-unit-toggle-edit]")) {
    event.preventDefault();
    const unit = riskAssessmentOrganizationUnitDrafts[unitIndex];
    const unitId = String(unit?.id || "");
    if (!unitId) {
      return;
    }
    if (riskAssessmentOpenOrganizationUnitIds.has(unitId)) {
      riskAssessmentOpenOrganizationUnitIds.delete(unitId);
    } else {
      riskAssessmentOpenOrganizationUnitIds.add(unitId);
    }
    renderRiskAssessmentOrganizationUnits();
    return;
  }
  if (button.matches("[data-risk-unit-ai]")) {
    event.preventDefault();
    setRiskAssessmentUnitAiProposal(unitIndex, button.dataset.riskUnitAiAction || "generate");
    return;
  }
  if (button.matches("[data-risk-unit-ai-apply]")) {
    event.preventDefault();
    const unit = riskAssessmentOrganizationUnitDrafts[unitIndex];
    const proposal = unit?.aiProposal;
    if (unit && proposal) {
      riskAssessmentOrganizationUnitDrafts[unitIndex] = {
        ...unit,
        [proposal.field || "description"]: proposal.text || "",
        aiProposal: null,
      };
      renderRiskAssessmentOrganizationUnits();
      renderRiskAssessmentOverview();
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }
  if (button.matches("[data-risk-unit-ai-reject]")) {
    event.preventDefault();
    riskAssessmentOrganizationUnitDrafts[unitIndex] = {
      ...riskAssessmentOrganizationUnitDrafts[unitIndex],
      aiProposal: null,
    };
    renderRiskAssessmentOrganizationUnits();
    return;
  }
  if (button.matches("[data-risk-unit-remove]")) {
    event.preventDefault();
    const unit = riskAssessmentOrganizationUnitDrafts[unitIndex];
    riskAssessmentOpenOrganizationUnitIds.delete(String(unit?.id || ""));
    riskAssessmentOrganizationUnitDrafts.splice(unitIndex, 1);
    riskAssessmentJobDrafts = riskAssessmentJobDrafts.map((job) => (
      String(job.organizationUnitId) === String(unit?.id)
        ? { ...job, organizationUnitId: "" }
        : job
    ));
    renderRiskAssessmentOrganizationUnits();
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
  }
}

function handleRiskAssessmentOrganizationUnitsDragOver(event) {
  const target = event.target?.closest?.("[data-risk-unit-drop]");
  if (!target) {
    return;
  }
  event.preventDefault();
  target.classList.add("is-drop-target");
}

function handleRiskAssessmentOrganizationUnitsDragLeave(event) {
  event.target?.closest?.("[data-risk-unit-drop]")?.classList.remove("is-drop-target");
}

function handleRiskAssessmentOrganizationUnitsDrop(event) {
  const target = event.target?.closest?.("[data-risk-unit-drop]");
  if (!target) {
    return;
  }
  event.preventDefault();
  target.classList.remove("is-drop-target");
  const jobId = event.dataTransfer?.getData("text/risk-job-id") || "";
  const jobIndex = riskAssessmentJobDrafts.findIndex((job) => String(job.id) === String(jobId));
  if (jobIndex < 0) {
    return;
  }
  riskAssessmentJobDrafts[jobIndex] = {
    ...riskAssessmentJobDrafts[jobIndex],
    organizationUnitId: target.dataset.riskUnitDrop || "",
  };
  renderRiskAssessmentOrganizationUnits();
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function updateRiskAssessmentJobDraftField(jobIndex, field, value) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !field) {
    return;
  }

  const previousAutoShortDescription = buildRiskAssessmentShortJobDescription({
    ...current,
    shortDescription: "",
  });
  const next = {
    ...current,
    [field]: value,
  };

  if (["description", "tasks", "detailedDescription"].includes(field)) {
    const shouldRefreshShort = !String(current.shortDescription || "").trim()
      || String(current.shortDescription || "").trim() === previousAutoShortDescription;
    if (shouldRefreshShort) {
      next.shortDescription = buildRiskAssessmentShortJobDescription({ ...next, shortDescription: "" });
    }
  }

  if (field === "organizationUnitId") {
    const unit = riskAssessmentOrganizationUnitDrafts.find((entry) => String(entry.id || "") === String(value || ""));
    if (unit) {
      if (!String(next.jobTitle || "").trim() || /^radno mjesto\s+\d+$/i.test(String(next.jobTitle || "").trim())) {
        next.jobTitle = unit.name || next.jobTitle;
      }
      if (!String(next.workerCount || "").trim() && unit.workerCount) {
        next.workerCount = unit.workerCount;
      }
      if (!String(next.description || "").trim() && unit.description) {
        next.description = unit.description;
        next.shortDescription = buildRiskAssessmentShortJobDescription({ ...next, shortDescription: "" });
      }
      if (!String(next.workplaceDescription || "").trim() && unit.note) {
        next.workplaceDescription = unit.note;
      }
    }
  }

  riskAssessmentJobDrafts[jobIndex] = next;

  if (field === "specialWorkReason") {
    riskAssessmentJobDrafts[jobIndex].specialConditions = value;
  }
  if (field === "requiredQualification") {
    riskAssessmentJobDrafts[jobIndex].qualifications = value;
  }
  if (field === "workOrganization") {
    riskAssessmentJobDrafts[jobIndex].organization = value;
  }
  if (field === "chemicalSubstances") {
    riskAssessmentJobDrafts[jobIndex].workSubstances = value;
  }
  if (field === "workSubstances") {
    riskAssessmentJobDrafts[jobIndex].chemicalSubstances = value;
  }
  if (["organizationUnitId", "status"].includes(field)) {
    renderRiskAssessmentOrganizationUnits();
    scheduleRiskAssessmentOverviewRender();
  }
  if (["catalogQuery", "catalogType"].includes(field)) {
    scheduleRiskAssessmentOverviewRender();
  }
  if (!["catalogQuery", "catalogType"].includes(field)) {
    scheduleRiskAssessmentJobDocumentPreviewRefresh(jobIndex);
  }
  scheduleRiskAssessmentJobTreeRender();
  scheduleRiskAssessmentDraftAutosave();
}

function updateRiskAssessmentJobBooleanField(jobIndex, field = "", checked = false) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !field) {
    return;
  }
  const next = {
    ...current,
    [field]: Boolean(checked),
  };
  if (field === "safeWorkTrainingRequired" && checked && !next.trainings) {
    next.trainings = buildRiskAssessmentSafeWorkTrainingText(next);
  }
  if ((field === "medicalFitnessRequired" || field === "visionCheckRequired") && checked && !next.medicalExams) {
    next.medicalExams = buildRiskAssessmentMedicalText(next);
  }
  riskAssessmentJobDrafts[jobIndex] = next;
  renderRiskAssessmentJobs();
  scheduleRiskAssessmentDraftAutosave();
}

function updateRiskAssessmentClientJobInput(jobIndex, patch = {}, { rerender = false } = {}) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current) {
    return;
  }
  riskAssessmentJobDrafts[jobIndex] = {
    ...current,
    clientInput: createRiskAssessmentClientJobInputDraft({
      ...(current.clientInput || {}),
      ...patch,
    }),
  };
  if (rerender) {
    renderRiskAssessmentJobs();
  }
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function updateRiskAssessmentClientJobInputField(jobIndex, field = "", value = "") {
  if (!field) {
    return;
  }
  updateRiskAssessmentClientJobInput(jobIndex, { [field]: value });
}

function updateRiskAssessmentClientJobInputBoolean(jobIndex, field = "", checked = false) {
  if (!field) {
    return;
  }
  updateRiskAssessmentClientJobInput(jobIndex, { [field]: Boolean(checked) }, { rerender: true });
}

function toggleRiskAssessmentClientJobInputChoice(jobIndex, field = "", value = "") {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !field || !value) {
    return;
  }
  const input = createRiskAssessmentClientJobInputDraft(current.clientInput || {});
  const selected = new Set(uniqueJobValues(input[field] ?? []));
  if (selected.has(value)) {
    selected.delete(value);
  } else {
    selected.add(value);
  }
  const patch = { [field]: Array.from(selected) };
  if (field === "bodyPositions") {
    const weights = normalizeRiskAssessmentLoadWeights(input.loadWeights || {});
    const activeLoadOptions = new Set(Array.from(selected));
    RISK_ASSESSMENT_LOAD_WEIGHT_FIELDS.forEach((item) => {
      if (!activeLoadOptions.has(item.option)) {
        weights[item.key] = "";
      }
    });
    patch.loadWeights = weights;
  }
  updateRiskAssessmentClientJobInput(jobIndex, patch, { rerender: true });
}

function toggleRiskAssessmentClientJobInputPurPoint(jobIndex, value = "") {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !value) {
    return;
  }
  const input = createRiskAssessmentClientJobInputDraft(current.clientInput || {});
  const selected = new Set(normalizeJobPurPointValues(input.purPoints ?? []));
  if (selected.has(value)) {
    selected.delete(value);
  } else {
    selected.add(value);
  }
  const purPoints = normalizeJobPurPointValues(Array.from(selected));
  updateRiskAssessmentClientJobInput(jobIndex, {
    purPoints,
    medicalFitnessRequired: input.medicalFitnessRequired || purPoints.length > 0,
    specialWorkReason: mergeRiskAssessmentSpecialWorkReason(input.specialWorkReason, purPoints, input.purPoints ?? [], { job: current }),
  }, { rerender: true });
}

function applyRiskAssessmentClientJobPreset(jobIndex, key = "") {
  const preset = getJobWorkProfilePreset(key);
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!preset || !current) {
    return;
  }
  const input = createRiskAssessmentClientJobInputDraft(current.clientInput || {});
  const presetEnvironment = preset.environment ?? {};
  const presetConditions = preset.conditions ?? {};
  const nextPurPoints = normalizeJobPurPointValues([
    ...(input.purPoints ?? []),
    ...(presetConditions.purPoints ?? []),
  ]);
  updateRiskAssessmentClientJobInput(jobIndex, {
    workplaceOptions: filterJobValuesByAllowedOptions(mergeJobValues(input.workplaceOptions ?? [], presetEnvironment.workplaceOptions ?? []), RISK_ASSESSMENT_WORKPLACE_OPTIONS),
    organizationOptions: filterJobValuesByAllowedOptions(mergeJobValues(input.organizationOptions ?? [], presetEnvironment.organizationOptions ?? []), RISK_ASSESSMENT_ORGANIZATION_OPTIONS),
    bodyPositions: filterJobValuesByAllowedOptions(mergeJobValues(input.bodyPositions ?? [], presetConditions.bodyPositions ?? []), JOB_BODY_POSITION_OPTIONS),
    importantFunctions: filterJobValuesByAllowedOptions(mergeJobValues(input.importantFunctions ?? [], presetConditions.importantFunctions ?? []), JOB_IMPORTANT_FUNCTION_OPTIONS),
    workConditions: filterJobValuesByAllowedOptions(mergeJobValues(input.workConditions ?? [], presetConditions.workConditions ?? []), JOB_WORK_CONDITION_OPTIONS),
    loadWeights: normalizeRiskAssessmentLoadWeights({
      ...(input.loadWeights || {}),
      ...(presetConditions.loadWeights || {}),
    }),
    purPoints: nextPurPoints,
    workSchedule: input.workSchedule || buildRiskAssessmentPresetSchedule(preset),
    workOrganization: input.workOrganization || buildJobOrganizationSentences(presetEnvironment.organizationOptions ?? [], presetEnvironment),
    workplace: input.workplace || (presetEnvironment.workplaceOptions ?? []).join(", "),
    safeWorkTrainingRequired: Boolean(input.safeWorkTrainingRequired || presetConditions.safeWorkTrainingCertificate || presetConditions.trainingRequired),
    medicalFitnessRequired: Boolean(input.medicalFitnessRequired || presetConditions.medicalFitnessCertificate || nextPurPoints.length),
    visionCheckRequired: Boolean(input.visionCheckRequired || presetConditions.visionCheck),
    specialWorkReason: mergeRiskAssessmentSpecialWorkReason(input.specialWorkReason, nextPurPoints, input.purPoints ?? [], { job: current }),
  }, { rerender: true });
}

function sanitizeRiskAssessmentClientPortalJobPayload(job = {}) {
  return {
    id: String(job.id || ""),
    clientInput: createRiskAssessmentClientJobInputDraft(job.clientInput || {}),
  };
}

function updateRiskAssessmentRiskRowDraftField(jobIndex, riskIndex, field, value) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !field || !Number.isInteger(riskIndex) || riskIndex < 0) {
    return;
  }

  const riskRows = [...(current.riskRows ?? [])];
  riskRows[riskIndex] = {
    ...(riskRows[riskIndex] ?? { id: crypto.randomUUID() }),
    [field]: value,
  };
  if (field === "workNote") {
    riskRows[riskIndex].note = value;
  }
  if (field === "measures") {
    riskRows[riskIndex].existingMeasures = riskRows[riskIndex].existingMeasures || value;
  }
  if (field === "existingMeasures") {
    riskRows[riskIndex].measures = value;
  }
  if (field === "probability" || field === "consequence") {
    const calculated = calculateRiskAssessmentRiskLevel(
      riskRows[riskIndex].probability,
      riskRows[riskIndex].consequence,
    );
    if (calculated) {
      riskRows[riskIndex].riskLevel = calculated;
    }
  }

  riskAssessmentJobDrafts[jobIndex] = {
    ...current,
    riskRows,
  };
  scheduleRiskAssessmentJobDocumentPreviewRefresh(jobIndex);
  scheduleRiskAssessmentOverviewRender();
  scheduleRiskAssessmentDraftAutosave();
}

function updateRiskAssessmentRiskRowVisualState(jobIndex, riskIndex) {
  const risk = riskAssessmentJobDrafts[jobIndex]?.riskRows?.[riskIndex];
  if (!risk) {
    return;
  }
  const riskLevel = getRiskAssessmentRiskDisplayLevel(risk);
  const riskTone = getRiskAssessmentRiskDisplayTone(risk);
  const riskShortLabel = getRiskAssessmentRiskShortLabel(riskLevel);
  const riskScore = getRiskAssessmentRiskScoreValue(risk);
  const row = riskAssessmentJobsList?.querySelector(`[data-risk-job-index="${jobIndex}"]`);
  const output = row?.querySelector?.(`[data-risk-row-output="${riskIndex}"]`);
  if (!(output instanceof HTMLElement)) {
    return;
  }
  const toneClasses = ["is-low", "is-medium", "is-high", "is-unknown"];
  output.classList.remove(...toneClasses);
  output.classList.add(`is-${riskTone}`);
  output.innerHTML = `
    <i aria-hidden="true"></i>
    <strong>${escapeHtml(riskLevel || `${riskShortLabel} rizik`)}</strong>
    ${riskScore ? `<em>${escapeHtml(riskScore)}</em>` : ""}
  `;
  const card = output.closest(".risk-assessment-risk-card");
  if (card instanceof HTMLElement) {
    card.classList.remove(...toneClasses);
    card.classList.add(`is-${riskTone}`);
    card.querySelectorAll(`[data-risk-row-index="${riskIndex}"]`).forEach((control) => {
      const shell = control.closest(".risk-assessment-risk-select-shell");
      if (shell instanceof HTMLElement) {
        shell.classList.remove(...toneClasses);
        shell.classList.add(`is-${riskTone}`);
      }
    });
  }
}

function updateRiskAssessmentRiskRowPurVisualState(jobIndex, riskIndex) {
  const risk = riskAssessmentJobDrafts[jobIndex]?.riskRows?.[riskIndex];
  if (!risk) {
    return;
  }
  const selected = new Set(normalizeJobPurPointValues(risk.purPoints ?? []));
  const row = riskAssessmentJobsList?.querySelector(`[data-risk-job-index="${jobIndex}"]`);
  const purField = row?.querySelector?.(`[data-risk-row-pur-point][data-risk-row-index="${riskIndex}"]`)?.closest(".risk-assessment-risk-pur-field");
  if (!(purField instanceof HTMLElement)) {
    return;
  }
  const countLabel = selected.size ? `${selected.size} odabrano` : "Ne";
  const countPill = purField.querySelector(".risk-assessment-risk-pur-head em");
  if (countPill) {
    countPill.textContent = countLabel;
  }
  const summary = purField.querySelector(".risk-assessment-risk-pur-dropdown summary span");
  if (summary) {
    summary.textContent = selected.size ? getJobPurPointSummary(Array.from(selected)) : "Odaberi iz popisa prema Pravilniku";
  }
  purField.querySelectorAll("[data-risk-row-pur-point]").forEach((control) => {
    const value = String(control.dataset.riskRowPurPoint || "").trim();
    control.classList.toggle("is-selected", selected.has(value));
  });
}

function updateRiskAssessmentArmorExplorerVisualState(jobIndex, riskIndex) {
  const risk = riskAssessmentJobDrafts[jobIndex]?.riskRows?.[riskIndex];
  if (!risk) {
    return;
  }
  const item = riskAssessmentJobTree
    ?.querySelector?.(`[data-risk-row-select="${riskIndex}"][data-risk-job-index="${jobIndex}"]`)
    ?.closest(".risk-assessment-armor-tree-node.is-item");
  if (!(item instanceof HTMLElement)) {
    return;
  }
  const riskTone = getRiskAssessmentRiskDisplayTone(risk);
  const riskLevel = getRiskAssessmentRiskDisplayLevel(risk);
  const complete = isRiskAssessmentRiskRowComplete(risk);
  const title = getRiskAssessmentRiskRowDisplayTitle(risk, riskIndex);
  const code = String(risk.code || "").trim();
  const dot = item.querySelector(".risk-assessment-armor-risk-dot");
  if (dot instanceof HTMLElement) {
    dot.classList.remove("is-low", "is-medium", "is-high", "is-unknown");
    dot.classList.add(`is-${riskTone}`);
  }
  const titleNode = item.querySelector(".risk-assessment-job-tree-copy strong");
  if (titleNode) {
    titleNode.textContent = code ? `${code} ${title}` : title;
  }
  const levelNode = item.querySelector(".risk-assessment-job-tree-copy small");
  if (levelNode) {
    levelNode.textContent = riskLevel || "N/P";
  }
  item.classList.toggle("is-complete", complete);
  const stateNode = item.querySelector(".risk-assessment-job-tree-state");
  if (stateNode) {
    stateNode.classList.toggle("is-done", complete);
    stateNode.textContent = complete ? "✓" : "";
    stateNode.setAttribute("aria-label", complete ? "Stavka popunjena" : "Nedovršeno");
  }
}

function toggleRiskAssessmentRiskRowPurPoint(jobIndex, riskIndex, value = "", { rerender = true } = {}) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !value || !Number.isInteger(riskIndex) || riskIndex < 0) {
    return;
  }
  const riskRows = [...(current.riskRows ?? [])];
  const row = createRiskAssessmentRiskRowDraft(riskRows[riskIndex] ?? {});
  const selected = new Set(normalizeJobPurPointValues(row.purPoints ?? []));
  if (selected.has(value)) {
    selected.delete(value);
  } else {
    selected.add(value);
  }
  riskRows[riskIndex] = {
    ...row,
    purPoints: normalizeJobPurPointValues(Array.from(selected)),
  };
  const nextPurPoints = normalizeJobPurPointValues([
    ...(current.purPoints ?? []),
    ...riskRows.flatMap((risk) => risk.purPoints ?? []),
  ]);
  const nextJob = {
    ...current,
    riskRows,
    purPoints: nextPurPoints,
    specialWorkConditions: nextPurPoints.length ? "da" : current.specialWorkConditions,
    medicalFitnessRequired: current.medicalFitnessRequired || nextPurPoints.length > 0,
  };
  nextJob.specialWorkReason = mergeRiskAssessmentSpecialWorkReason(current.specialWorkReason || current.specialConditions, nextPurPoints, current.purPoints ?? [], { job: current });
  nextJob.specialConditions = nextJob.specialWorkReason;
  if (nextJob.medicalFitnessRequired && !nextJob.medicalExams) {
    nextJob.medicalExams = buildRiskAssessmentMedicalText(nextJob);
  }
  riskAssessmentJobDrafts[jobIndex] = nextJob;
  scheduleRiskAssessmentJobDocumentPreviewRefresh(jobIndex);
  if (rerender) {
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
  } else {
    scheduleRiskAssessmentOverviewRender();
  }
  scheduleRiskAssessmentDraftAutosave();
}

function updateRiskAssessmentEligibilityDraftField(jobIndex, key, field, value) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !key || !field) {
    return;
  }

  const currentEligibility = current.eligibility || createRiskAssessmentEligibilityDraft();
  riskAssessmentJobDrafts[jobIndex] = {
    ...current,
    eligibility: {
      ...currentEligibility,
      [key]: {
        ...(currentEligibility[key] ?? { allowed: "np", note: "" }),
        [field]: value,
      },
    },
  };
  refreshRiskAssessmentJobDocumentPreview(jobIndex);
  scheduleRiskAssessmentDraftAutosave();
}

function toggleRiskAssessmentPpeItem(jobIndex, catalogId = "", checked = false) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !catalogId) {
    return;
  }
  const existing = [...(current.ppeItems ?? [])];
  const existingIndex = existing.findIndex((item) => String(item.catalogId || item.id) === String(catalogId));
  if (checked && existingIndex < 0) {
    const catalog = getRiskAssessmentPpeCatalogItem(catalogId);
    if (catalog) {
      existing.push(createRiskAssessmentPpeDraft({
        catalogId,
        jobId: current.id,
        hazardLinks: (current.riskRows ?? []).map((risk) => risk.hazard).filter(Boolean).slice(0, 4).join(", "),
      }));
    }
  } else if (!checked && existingIndex >= 0) {
    existing.splice(existingIndex, 1);
  }
  riskAssessmentJobDrafts[jobIndex] = {
    ...current,
    ppeItems: existing,
    ppeText: syncRiskAssessmentPpeSummaryText(current, existing),
  };
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function updateRiskAssessmentPpeNewDraftField(jobIndex, field = "", value = "") {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !field) {
    return;
  }
  riskAssessmentJobDrafts[jobIndex] = {
    ...current,
    ppeNewDraft: {
      ...getRiskAssessmentPpeNewDraft(current),
      [field]: value,
    },
  };
}

async function saveRiskAssessmentPpeCatalogItem(jobIndex) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current) {
    return;
  }

  const draft = getRiskAssessmentPpeNewDraft(current);
  const name = draft.name.trim();
  if (!name) {
    setSyncError("Naziv OZO stavke je obavezan.");
    return;
  }

  const requestBody = {
    ...draft,
    name,
    category: draft.category.trim() || RISK_ASSESSMENT_PPE_BODY_FILTERS.find((filter) => filter.value === draft.bodyPart)?.label || "",
  };
  const success = await runMutation(() => apiRequest("/risk-ppe-catalog", {
    method: "POST",
    body: requestBody,
  }));
  if (!success) {
    return;
  }

  const savedItem = getRiskAssessmentPpeCatalog()
    .find((item) => item.isCustom && item.name === requestBody.name && item.norm === requestBody.norm)
    ?? normalizeRiskPpeCatalogItem({
      ...requestBody,
      id: `custom-${crypto.randomUUID()}`,
      isCustom: true,
    });
  const updated = riskAssessmentJobDrafts[jobIndex];
  if (!updated) {
    return;
  }
  const existing = [...(updated.ppeItems ?? [])];
  if (!existing.some((item) => String(item.catalogId || item.id) === String(savedItem.id))) {
    existing.push(createRiskAssessmentPpeDraft({
      ...savedItem,
      catalogId: savedItem.id,
      jobId: updated.id,
      hazardLinks: (updated.riskRows ?? []).map((risk) => risk.hazard).filter(Boolean).slice(0, 4).join(", "),
    }));
  }
  riskAssessmentJobDrafts[jobIndex] = {
    ...updated,
    ppeNewOpen: false,
    ppeNewDraft: {},
    ppeItems: existing,
    ppeText: syncRiskAssessmentPpeSummaryText(updated, existing),
  };
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function updateRiskAssessmentPpeItemField(jobIndex, ppeIndex, field = "", value) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !field || !Number.isInteger(ppeIndex) || ppeIndex < 0) {
    return;
  }
  const ppeItems = [...(current.ppeItems ?? [])];
  ppeItems[ppeIndex] = {
    ...(ppeItems[ppeIndex] ?? createRiskAssessmentPpeDraft()),
    [field]: value,
  };
  if (field === "required") {
    ppeItems[ppeIndex].mandatory = Boolean(value);
  }
  riskAssessmentJobDrafts[jobIndex] = {
    ...current,
    ppeItems,
    ppeText: syncRiskAssessmentPpeSummaryText(current, ppeItems),
  };
  refreshRiskAssessmentJobDocumentPreview(jobIndex);
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function removeRiskAssessmentPpeItem(jobIndex, ppeIndex) {
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current || !Number.isInteger(ppeIndex) || ppeIndex < 0) {
    return;
  }
  const ppeItems = [...(current.ppeItems ?? [])];
  if (!ppeItems[ppeIndex]) {
    return;
  }
  ppeItems.splice(ppeIndex, 1);
  riskAssessmentJobDrafts[jobIndex] = {
    ...current,
    ppeItems,
    ppeText: syncRiskAssessmentPpeSummaryText(current, ppeItems),
  };
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function handleRiskAssessmentJobsListInput(event) {
  const target = event.target;
  if (!(
    target instanceof HTMLInputElement
    || target instanceof HTMLTextAreaElement
    || target instanceof HTMLSelectElement
  )) {
    return;
  }
  if (event.type === "input" && target instanceof HTMLSelectElement) {
    return;
  }
  if (event.type === "change" && !(target instanceof HTMLSelectElement)) {
    return;
  }

  const jobIndex = getRiskAssessmentJobIndexFromElement(target);
  if (jobIndex < 0) {
    return;
  }

  if (target.dataset.riskClientField) {
    updateRiskAssessmentClientJobInputField(jobIndex, target.dataset.riskClientField, target.value);
    return;
  }

  if (target.dataset.riskClientBoolean) {
    updateRiskAssessmentClientJobInputBoolean(jobIndex, target.dataset.riskClientBoolean, target.checked);
    return;
  }

  if (target.dataset.riskClientLoadWeight) {
    const current = riskAssessmentJobDrafts[jobIndex];
    const input = createRiskAssessmentClientJobInputDraft(current?.clientInput || {});
    updateRiskAssessmentClientJobInput(jobIndex, {
      loadWeights: {
        ...normalizeRiskAssessmentLoadWeights(input.loadWeights || {}),
        [target.dataset.riskClientLoadWeight]: target.value,
      },
    });
    return;
  }

  if (target.dataset.riskJobAiText !== undefined) {
    const proposal = riskAssessmentJobDrafts[jobIndex]?.aiProposal;
    if (proposal) {
      riskAssessmentJobDrafts[jobIndex] = {
        ...riskAssessmentJobDrafts[jobIndex],
        aiProposal: {
          ...proposal,
          text: target.value,
        },
      };
    }
    return;
  }

  if (target.dataset.riskJobFlag) {
    updateRiskAssessmentJobDraftField(jobIndex, target.dataset.riskJobFlag, target.checked);
    target.closest("label")?.classList.toggle("is-selected", target.checked);
    return;
  }

  if (target.dataset.riskJobBoolean) {
    updateRiskAssessmentJobBooleanField(jobIndex, target.dataset.riskJobBoolean, target.checked);
    return;
  }

  if (target.dataset.riskJobSourceSelect !== undefined) {
    applyRiskAssessmentSourceJob(jobIndex, target.value);
    return;
  }

  if (target.dataset.riskCatalogSelect !== undefined) {
    const selection = new Set(riskAssessmentJobDrafts[jobIndex]?.catalogSelection ?? []);
    if (target.checked) {
      selection.add(String(target.dataset.riskCatalogSelect));
    } else {
      selection.delete(String(target.dataset.riskCatalogSelect));
    }
    riskAssessmentJobDrafts[jobIndex] = {
      ...riskAssessmentJobDrafts[jobIndex],
      catalogSelection: Array.from(selection),
    };
    renderRiskAssessmentJobs();
    return;
  }

  if (target.dataset.riskPpeToggle) {
    toggleRiskAssessmentPpeItem(jobIndex, target.dataset.riskPpeToggle, target.checked);
    return;
  }

  if (target.dataset.riskPpeSearch !== undefined) {
    riskAssessmentJobDrafts[jobIndex] = {
      ...riskAssessmentJobDrafts[jobIndex],
      ppeSearch: target.value,
    };
    applyRiskAssessmentPpeCatalogDomFilter(jobIndex);
    return;
  }

  if (target.dataset.riskPpeNewField) {
    updateRiskAssessmentPpeNewDraftField(jobIndex, target.dataset.riskPpeNewField, target.value);
    return;
  }

  if (target.dataset.riskPpeField) {
    updateRiskAssessmentPpeItemField(
      jobIndex,
      Number(target.dataset.riskPpeIndex),
      target.dataset.riskPpeField,
      target.type === "checkbox" ? target.checked : target.value,
    );
    return;
  }

  if (target.dataset.riskJobLoadWeight) {
    const current = riskAssessmentJobDrafts[jobIndex];
    if (current) {
      riskAssessmentJobDrafts[jobIndex] = {
        ...current,
        loadWeights: {
          ...normalizeRiskAssessmentLoadWeights(current.loadWeights || {}),
          [target.dataset.riskJobLoadWeight]: target.value,
        },
      };
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }

  if (target.dataset.riskJobField) {
    const field = target.dataset.riskJobField;
    updateRiskAssessmentJobDraftField(jobIndex, field, target.value);
    const requiredShell = target.closest(".risk-assessment-required-field");
    if (requiredShell) {
      const hasValue = Boolean(String(target.value || "").trim());
      requiredShell.classList.toggle("is-filled", hasValue);
      requiredShell.classList.toggle("is-missing", !hasValue);
    }
    if (field === "description" && jobIndex === getRiskAssessmentActiveWorkplaceJobIndex()) {
      syncRiskAssessmentJobCatalogAiDescriptionFromActiveJob({ force: true });
    }
    if (["description", "tasks", "detailedDescription"].includes(field)) {
      const shortField = riskAssessmentJobsList?.querySelector(`[data-risk-job-index="${jobIndex}"] [data-risk-job-field="shortDescription"]`);
      if (shortField instanceof HTMLTextAreaElement && shortField !== target) {
        shortField.value = riskAssessmentJobDrafts[jobIndex]?.shortDescription || "";
      }
    }
    if (["catalogQuery", "catalogType"].includes(field)) {
      scheduleRiskAssessmentCatalogPickerRefresh(jobIndex, {
        delay: field === "catalogQuery" ? 180 : 0,
        focusField: document.activeElement === target ? field : "",
        selectionStart: target instanceof HTMLInputElement ? target.selectionStart : null,
        selectionEnd: target instanceof HTMLInputElement ? target.selectionEnd : null,
      });
    } else if (["organizationUnitId", "status"].includes(field)) {
      renderRiskAssessmentJobs({ refreshLinkedSheets: false, refreshOverview: false });
    }
    return;
  }

  if (target.dataset.riskRowField) {
    const riskIndex = Number(target.dataset.riskRowIndex);
    const field = target.dataset.riskRowField;
    updateRiskAssessmentRiskRowDraftField(
      jobIndex,
      riskIndex,
      field,
      target.value,
    );
    if (target instanceof HTMLTextAreaElement && ["workNote", "existingMeasures"].includes(field)) {
      const counter = target.closest(".risk-assessment-risk-large-field")?.querySelector(".risk-assessment-risk-character-count");
      if (counter) {
        counter.textContent = `${getRiskAssessmentTextareaCount(target.value)} / 1000`;
      }
    }
    updateRiskAssessmentArmorExplorerVisualState(jobIndex, riskIndex);
    if (["probability", "consequence"].includes(field)) {
      updateRiskAssessmentRiskRowVisualState(jobIndex, riskIndex);
      scheduleRiskAssessmentJobTreeRender();
    }
    return;
  }

  if (target.dataset.riskEligibilityKey) {
    updateRiskAssessmentEligibilityDraftField(
      jobIndex,
      target.dataset.riskEligibilityKey,
      target.dataset.riskEligibilityField,
      target.value,
    );
  }
}

function handleRiskAssessmentJobsListClick(event) {
  const button = event.target?.closest?.("button");
  if (button?.matches?.("[data-risk-jobs-collapse]")) {
    event.preventDefault();
    const collapse = button.dataset.riskJobsCollapse === "collapse";
    riskAssessmentJobDrafts = riskAssessmentJobDrafts.map((job) => ({
      ...job,
      collapsed: collapse,
    }));
    renderRiskAssessmentJobs();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  const toggleTarget = event.target?.closest?.("[data-risk-job-toggle-head]")
    || event.target?.closest?.(".risk-assessment-repeat-row.is-job.is-collapsed");
  if (!button && toggleTarget) {
    const jobIndex = getRiskAssessmentJobIndexFromElement(toggleTarget);
    const current = riskAssessmentJobDrafts[jobIndex];
    if (current) {
      riskAssessmentJobDrafts[jobIndex] = {
        ...current,
        collapsed: !current.collapsed,
      };
      setRiskAssessmentActiveJobIndex(jobIndex);
      renderRiskAssessmentJobs();
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }

  if (!(button instanceof HTMLButtonElement)) {
    return;
  }

  const jobIndex = getRiskAssessmentJobIndexFromElement(button);
  if (jobIndex < 0) {
    return;
  }

  if (button.matches("[data-risk-row-select]")) {
    event.preventDefault();
    const riskIndex = Number(button.dataset.riskRowSelect);
    if (setRiskAssessmentActiveRiskRowIndex(jobIndex, riskIndex)) {
      const current = riskAssessmentJobDrafts[jobIndex];
      const riskRows = [...(current?.riskRows ?? [])];
      if (riskRows[riskIndex]) {
        riskRows[riskIndex] = {
          ...riskRows[riskIndex],
          collapsed: false,
        };
        riskAssessmentJobDrafts[jobIndex] = {
          ...current,
          riskRows,
        };
      }
      renderRiskAssessmentJobs({
        refreshLinkedSheets: false,
        refreshOverview: false,
        refreshCatalogOptions: false,
      });
    }
    return;
  }

  if (button.matches("[data-risk-client-preset]")) {
    event.preventDefault();
    applyRiskAssessmentClientJobPreset(jobIndex, button.dataset.riskClientPreset || "");
    return;
  }

  if (button.matches("[data-risk-client-choice]")) {
    event.preventDefault();
    toggleRiskAssessmentClientJobInputChoice(
      jobIndex,
      button.dataset.riskClientChoice || "",
      button.dataset.value || "",
    );
    return;
  }

  if (button.matches("[data-risk-client-pur-point]")) {
    event.preventDefault();
    toggleRiskAssessmentClientJobInputPurPoint(jobIndex, button.dataset.riskClientPurPoint || "");
    return;
  }

  if (button.matches("[data-risk-client-psychosocial-level]")) {
    event.preventDefault();
    updateRiskAssessmentClientJobInput(jobIndex, {
      psychosocialRelevant: true,
      psychosocialLevel: String(button.dataset.riskClientPsychosocialLevel || "").trim(),
    }, { rerender: true });
    return;
  }

  if (button.matches("[data-risk-job-catalog]")) {
    event.preventDefault();
    riskAssessmentJobDrafts[jobIndex] = {
      ...riskAssessmentJobDrafts[jobIndex],
      catalogOpen: !riskAssessmentJobDrafts[jobIndex]?.catalogOpen,
    };
    renderRiskAssessmentJobs();
    return;
  }

  if (button.matches("[data-risk-job-open-job-module]")) {
    event.preventDefault();
    openJobsModuleForRiskAssessmentJob(jobIndex);
    return;
  }

  if (button.matches("[data-risk-job-toggle-block]")) {
    event.preventDefault();
    const block = String(button.dataset.riskJobToggleBlock || "").trim();
    const current = riskAssessmentJobDrafts[jobIndex];
    if (current && block) {
      const hidden = getRiskAssessmentJobHiddenBlocks(current);
      if (hidden.has(block)) {
        hidden.delete(block);
      } else {
        hidden.add(block);
      }
      riskAssessmentJobDrafts[jobIndex] = {
        ...current,
        hiddenBlocks: Array.from(hidden),
      };
      renderRiskAssessmentJobs();
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }

  if (button.matches("[data-risk-job-psychosocial-level]")) {
    event.preventDefault();
    const level = String(button.dataset.riskJobPsychosocialLevel || "").trim();
    const current = riskAssessmentJobDrafts[jobIndex];
    if (current && level) {
      riskAssessmentJobDrafts[jobIndex] = {
        ...current,
        psychosocialRelevant: true,
        psychosocialLevel: level,
      };
      renderRiskAssessmentJobs();
      renderRiskAssessmentOverview();
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }

  if (button.matches("[data-risk-job-work-preset]")) {
    event.preventDefault();
    applyRiskAssessmentJobWorkProfilePreset(jobIndex, button.dataset.riskJobWorkPreset || "");
    return;
  }

  if (button.matches("[data-risk-job-choice]")) {
    event.preventDefault();
    const field = button.dataset.riskJobChoice || "";
    const value = String(button.dataset.value || "").trim();
    const current = riskAssessmentJobDrafts[jobIndex];
    if (current && field && value) {
      const selected = new Set(uniqueJobValues(current[field] ?? []));
      if (selected.has(value)) {
        selected.delete(value);
      } else {
        selected.add(value);
      }
      const next = {
        ...current,
        [field]: Array.from(selected),
      };
      if (field === "importantFunctions") {
        next.visionCheckRequired = next.visionCheckRequired || Array.from(selected).some((entry) => String(entry || "").toLocaleLowerCase("hr").includes("vid"));
      }
      if (field === "bodyPositions") {
        const activeLoadOptions = new Set(Array.from(selected));
        const currentWeights = normalizeRiskAssessmentLoadWeights(next.loadWeights || {});
        RISK_ASSESSMENT_LOAD_WEIGHT_FIELDS.forEach((item) => {
          if (!activeLoadOptions.has(item.option)) {
            currentWeights[item.key] = "";
          }
        });
        next.loadWeights = currentWeights;
      }
      const textFieldByChoice = {
        toolsAndMachinesOptions: "toolsAndMachines",
        chemicalSubstanceOptions: "chemicalSubstances",
        biologicalHazardOptions: "biologicalHazards",
      };
      const linkedTextField = textFieldByChoice[field];
      if (linkedTextField) {
        next[linkedTextField] = Array.from(selected).join(", ");
        if (linkedTextField === "chemicalSubstances") {
          next.workSubstances = next[linkedTextField];
        }
      }
      riskAssessmentJobDrafts[jobIndex] = next;
      renderRiskAssessmentJobs();
      renderRiskAssessmentOverview();
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }

  if (button.matches("[data-risk-job-pur-point]")) {
    event.preventDefault();
    const value = String(button.dataset.riskJobPurPoint || "").trim();
    const current = riskAssessmentJobDrafts[jobIndex];
    if (current && value) {
      const selected = new Set(normalizeJobPurPointValues(current.purPoints ?? []));
      if (selected.has(value)) {
        selected.delete(value);
      } else {
        selected.add(value);
      }
      const purPoints = normalizeJobPurPointValues(Array.from(selected));
      const next = {
        ...current,
        purPoints,
        specialWorkConditions: purPoints.length ? "da" : current.specialWorkConditions,
        medicalFitnessRequired: current.medicalFitnessRequired || purPoints.length > 0,
      };
      next.specialWorkReason = mergeRiskAssessmentSpecialWorkReason(current.specialWorkReason || current.specialConditions, purPoints, current.purPoints ?? [], { job: current });
      next.specialConditions = next.specialWorkReason;
      if (next.medicalFitnessRequired && !next.medicalExams) {
        next.medicalExams = buildRiskAssessmentMedicalText(next);
      }
      riskAssessmentJobDrafts[jobIndex] = next;
      renderRiskAssessmentJobs();
      renderRiskAssessmentOverview();
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }

  if (button.matches("[data-risk-row-pur-point]")) {
    event.preventDefault();
    const riskIndex = Number(button.dataset.riskRowIndex);
    toggleRiskAssessmentRiskRowPurPoint(
      jobIndex,
      riskIndex,
      button.dataset.riskRowPurPoint || "",
      { rerender: false },
    );
    updateRiskAssessmentRiskRowPurVisualState(jobIndex, riskIndex);
    scheduleRiskAssessmentJobTreeRender();
    return;
  }

  if (button.matches("[data-risk-row-collapse]")) {
    event.preventDefault();
    const riskIndex = Number(button.dataset.riskRowCollapse);
    const current = riskAssessmentJobDrafts[jobIndex];
    const riskRows = [...(current?.riskRows ?? [])];
    if (!current || !riskRows[riskIndex]) {
      return;
    }
    riskRows[riskIndex] = {
      ...riskRows[riskIndex],
      collapsed: !Boolean(riskRows[riskIndex].collapsed),
    };
    riskAssessmentJobDrafts[jobIndex] = {
      ...current,
      riskRows,
    };
    renderRiskAssessmentJobs({
      refreshLinkedSheets: false,
      refreshOverview: false,
      refreshCatalogOptions: false,
    });
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-catalog-add-selected]")) {
    event.preventDefault();
    const currentJob = riskAssessmentJobDrafts[jobIndex];
    const selection = currentJob?.catalogSelection ?? [];
    const catalogRows = selection
      .map((value) => RISK_ASSESSMENT_CATALOG_ROWS[Number(value)])
      .filter((row) => row && isRiskAssessmentArmorRiskRow(row));
    riskAssessmentJobDrafts[jobIndex] = {
      ...currentJob,
      riskRows: mergeRiskAssessmentRiskRows(currentJob.riskRows, prepareRiskAssessmentCatalogRowsForJob(currentJob, catalogRows)),
      catalogSelection: [],
      catalogOpen: true,
    };
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-catalog-row]")) {
    event.preventDefault();
    const catalogIndex = Number(button.dataset.riskCatalogRow);
    const catalogRow = RISK_ASSESSMENT_CATALOG_ROWS[catalogIndex];
    if (catalogRow && isRiskAssessmentArmorRiskRow(catalogRow)) {
      const currentJob = riskAssessmentJobDrafts[jobIndex];
      riskAssessmentJobDrafts[jobIndex] = {
        ...currentJob,
        riskRows: mergeRiskAssessmentRiskRows(currentJob.riskRows, prepareRiskAssessmentCatalogRowsForJob(currentJob, [catalogRow])),
        catalogOpen: true,
      };
      renderRiskAssessmentJobs();
      renderRiskAssessmentOverview();
      scheduleRiskAssessmentDraftAutosave();
    }
    return;
  }

  if (button.matches("[data-risk-catalog-group]")) {
    event.preventDefault();
    event.stopPropagation();
    const [category, family, subgroup] = String(button.dataset.riskCatalogGroup || "").split("||");
    const catalogRows = RISK_ASSESSMENT_CATALOG_ROWS.filter((row) => {
      const hierarchy = getRiskAssessmentCatalogHierarchy(row);
      return isRiskAssessmentArmorRiskRow(row)
        && hierarchy.category === category
        && hierarchy.family === family
        && hierarchy.subgroup === subgroup;
    });
    const currentJob = riskAssessmentJobDrafts[jobIndex];
    riskAssessmentJobDrafts[jobIndex] = {
      ...currentJob,
      riskRows: mergeRiskAssessmentRiskRows(currentJob.riskRows, prepareRiskAssessmentCatalogRowsForJob(currentJob, catalogRows)),
      catalogOpen: true,
    };
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-catalog-family]")) {
    event.preventDefault();
    event.stopPropagation();
    const [category, family] = String(button.dataset.riskCatalogFamily || "").split("||");
    const catalogRows = RISK_ASSESSMENT_CATALOG_ROWS.filter((row) => {
      const hierarchy = getRiskAssessmentCatalogHierarchy(row);
      return isRiskAssessmentArmorRiskRow(row)
        && hierarchy.category === category
        && hierarchy.family === family;
    });
    const currentJob = riskAssessmentJobDrafts[jobIndex];
    riskAssessmentJobDrafts[jobIndex] = {
      ...currentJob,
      riskRows: mergeRiskAssessmentRiskRows(currentJob.riskRows, prepareRiskAssessmentCatalogRowsForJob(currentJob, catalogRows)),
      catalogOpen: true,
    };
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-job-copy]")) {
    event.preventDefault();
    const source = riskAssessmentJobDrafts[jobIndex];
    const copy = createRiskAssessmentJobDraft({
      ...sanitizeRiskAssessmentTransientJob(source),
      id: crypto.randomUUID(),
      jobTitle: `${source.jobTitle || "Radno mjesto"} - kopija`,
      riskRows: (source.riskRows ?? []).filter(isRiskAssessmentArmorRiskRow).map((risk) => ({ ...risk, id: crypto.randomUUID() })),
      ppeItems: (source.ppeItems ?? []).map((ppe) => ({ ...ppe, id: crypto.randomUUID() })),
    });
    riskAssessmentJobDrafts.splice(jobIndex + 1, 0, copy);
    setRiskAssessmentActiveJobIndex(jobIndex + 1);
    renderRiskAssessmentOrganizationUnits();
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-job-save-template]")) {
    event.preventDefault();
    const job = riskAssessmentJobDrafts[jobIndex];
    const name = window.prompt("Naziv predloška za česte poslove", job?.jobTitle || "Predložak rizika");
    if (!name) {
      return;
    }
    riskAssessmentRiskTemplateDrafts.push({
      id: crypto.randomUUID(),
      name,
      jobHint: job?.jobTitle || "",
      riskRows: (job?.riskRows ?? []).filter((risk) => isRiskAssessmentArmorRiskRow(risk) && getRiskAssessmentRiskRowKey(risk)).map((risk) => createRiskAssessmentRiskRowDraft(risk)),
      ppeItems: (job?.ppeItems ?? []).map((ppe) => createRiskAssessmentPpeDraft(ppe)),
    });
    renderRiskAssessmentJobs();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-job-apply-template]")) {
    event.preventDefault();
    const template = riskAssessmentRiskTemplateDrafts.find((item) => String(item.id) === String(button.dataset.riskJobApplyTemplate));
    if (!template) {
      return;
    }
    const job = riskAssessmentJobDrafts[jobIndex];
    const existingPpeIds = new Set((job.ppeItems ?? []).map((ppe) => ppe.catalogId || ppe.name));
    const nextPpeItems = [
      ...(job.ppeItems ?? []),
      ...(template.ppeItems ?? [])
        .filter((ppe) => !existingPpeIds.has(ppe.catalogId || ppe.name))
        .map((ppe) => createRiskAssessmentPpeDraft({ ...ppe, id: crypto.randomUUID(), jobId: job.id })),
    ];
    riskAssessmentJobDrafts[jobIndex] = {
      ...job,
      riskRows: mergeRiskAssessmentRiskRows(job.riskRows, template.riskRows ?? []),
      ppeItems: nextPpeItems,
      ppeText: syncRiskAssessmentPpeSummaryText(job, nextPpeItems),
    };
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-ppe-filter]")) {
    event.preventDefault();
    riskAssessmentJobDrafts[jobIndex] = {
      ...riskAssessmentJobDrafts[jobIndex],
      ppeFilter: button.dataset.riskPpeFilter || "all",
    };
    applyRiskAssessmentPpeCatalogDomFilter(jobIndex);
    return;
  }

  if (button.matches("[data-risk-ppe-save-continue]")) {
    event.preventDefault();
    scheduleRiskAssessmentDraftAutosave();
    void saveRiskAssessmentEditorAutosave({ manual: true });
    return;
  }

  if (button.matches("[data-risk-ppe-remove]")) {
    event.preventDefault();
    removeRiskAssessmentPpeItem(jobIndex, Number(button.dataset.riskPpeRemove));
    return;
  }

  if (button.matches("[data-risk-ppe-new-toggle]")) {
    event.preventDefault();
    riskAssessmentJobDrafts[jobIndex] = {
      ...riskAssessmentJobDrafts[jobIndex],
      ppeNewOpen: !riskAssessmentJobDrafts[jobIndex]?.ppeNewOpen,
    };
    renderRiskAssessmentJobs();
    return;
  }

  if (button.matches("[data-risk-ppe-new-save]")) {
    event.preventDefault();
    void saveRiskAssessmentPpeCatalogItem(jobIndex);
    return;
  }

  if (button.matches("[data-risk-job-remove]")) {
    event.preventDefault();
    riskAssessmentJobDrafts.splice(jobIndex, 1);
    setRiskAssessmentActiveJobIndex(Math.min(jobIndex, riskAssessmentJobDrafts.length - 1));
    renderRiskAssessmentOrganizationUnits();
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-row-add]")) {
    event.preventDefault();
    const nextRiskRow = createRiskAssessmentRiskRowDraft();
    riskAssessmentJobDrafts[jobIndex] = {
      ...riskAssessmentJobDrafts[jobIndex],
      riskRows: [
        ...(riskAssessmentJobDrafts[jobIndex].riskRows ?? []),
        nextRiskRow,
      ],
      activeRiskRowId: nextRiskRow.id,
    };
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-job-template]")) {
    event.preventDefault();
    applyRiskAssessmentArmorTemplateRows(jobIndex);
    return;
  }

  if (button.matches("[data-risk-job-ai]")) {
    event.preventDefault();
    setRiskAssessmentJobAiProposal(jobIndex, button.dataset.riskJobAi || "description");
    return;
  }

  if (button.matches("[data-risk-job-ai-apply]")) {
    event.preventDefault();
    const job = riskAssessmentJobDrafts[jobIndex];
    const proposal = job?.aiProposal;
    if (!job || !proposal) {
      return;
    }
    if (proposal.action === "full") {
      const existingPpeIds = new Set((job.ppeItems ?? []).map((ppe) => ppe.catalogId || ppe.name));
      const nextPpeItems = [
        ...(job.ppeItems ?? []),
        ...(proposal.ppeItems ?? [])
          .filter((ppe) => !existingPpeIds.has(ppe.catalogId || ppe.name))
          .map((ppe) => createRiskAssessmentPpeDraft({ ...ppe, id: crypto.randomUUID(), jobId: job.id })),
      ];
      riskAssessmentJobDrafts[jobIndex] = {
        ...job,
        ...(proposal.patch ?? {}),
        riskRows: mergeRiskAssessmentRiskRows(job.riskRows, (proposal.riskRows ?? []).filter(isRiskAssessmentArmorRiskRow)),
        ppeItems: nextPpeItems,
        ppeText: proposal.patch?.ppeText || syncRiskAssessmentPpeSummaryText(job, nextPpeItems),
        aiProposal: null,
      };
    } else if (proposal.action === "risks") {
      const existingPpeIds = new Set((job.ppeItems ?? []).map((ppe) => ppe.catalogId || ppe.name));
      const nextPpeItems = [
        ...(job.ppeItems ?? []),
        ...(proposal.ppeItems ?? [])
          .filter((ppe) => !existingPpeIds.has(ppe.catalogId || ppe.name))
          .map((ppe) => createRiskAssessmentPpeDraft({ ...ppe, id: crypto.randomUUID(), jobId: job.id })),
      ];
      riskAssessmentJobDrafts[jobIndex] = {
        ...job,
        riskRows: mergeRiskAssessmentRiskRows(job.riskRows, (proposal.riskRows ?? []).filter(isRiskAssessmentArmorRiskRow)),
        ppeItems: nextPpeItems,
        ppeText: syncRiskAssessmentPpeSummaryText(job, nextPpeItems),
        aiProposal: null,
      };
    } else if (proposal.action === "ppe") {
      const existingPpeIds = new Set((job.ppeItems ?? []).map((ppe) => ppe.catalogId || ppe.name));
      const nextPpeItems = [
        ...(job.ppeItems ?? []),
        ...(proposal.ppeItems ?? [])
          .filter((ppe) => !existingPpeIds.has(ppe.catalogId || ppe.name))
          .map((ppe) => createRiskAssessmentPpeDraft({ ...ppe, id: crypto.randomUUID(), jobId: job.id })),
      ];
      riskAssessmentJobDrafts[jobIndex] = {
        ...job,
        ppeItems: nextPpeItems,
        ppeText: syncRiskAssessmentPpeSummaryText(job, nextPpeItems),
        aiProposal: null,
      };
    } else {
      riskAssessmentJobDrafts[jobIndex] = {
        ...job,
        [proposal.field || "description"]: proposal.text || "",
        aiProposal: null,
      };
    }
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
    return;
  }

  if (button.matches("[data-risk-job-ai-reject]")) {
    event.preventDefault();
    riskAssessmentJobDrafts[jobIndex] = {
      ...riskAssessmentJobDrafts[jobIndex],
      aiProposal: null,
    };
    renderRiskAssessmentJobs();
    return;
  }

  if (button.matches("[data-risk-row-remove]")) {
    event.preventDefault();
    const riskIndex = Number(button.dataset.riskRowRemove);
    const riskRows = [...(riskAssessmentJobDrafts[jobIndex].riskRows ?? [])];
    riskRows.splice(riskIndex, 1);
    const fallbackRiskRows = riskRows.length > 0 ? riskRows : [createRiskAssessmentRiskRowDraft()];
    const nextActiveRisk = fallbackRiskRows[Math.min(riskIndex, fallbackRiskRows.length - 1)] || fallbackRiskRows[0];
    riskAssessmentJobDrafts[jobIndex] = {
      ...riskAssessmentJobDrafts[jobIndex],
      riskRows: fallbackRiskRows,
      activeRiskRowId: nextActiveRisk?.id || "",
    };
    renderRiskAssessmentJobs();
    renderRiskAssessmentOverview();
    scheduleRiskAssessmentDraftAutosave();
  }
}

function handleRiskAssessmentJobsListKeydown(event) {
  if (!["Enter", " "].includes(event.key)) {
    return;
  }
  if (event.target?.closest?.("button, input, select, textarea")) {
    return;
  }
  const toggleHead = event.target?.closest?.("[data-risk-job-toggle-head]");
  if (!toggleHead) {
    return;
  }
  const jobIndex = getRiskAssessmentJobIndexFromElement(toggleHead);
  const current = riskAssessmentJobDrafts[jobIndex];
  if (!current) {
    return;
  }
  event.preventDefault();
  riskAssessmentJobDrafts[jobIndex] = {
    ...current,
    collapsed: !current.collapsed,
  };
  setRiskAssessmentActiveJobIndex(jobIndex);
  renderRiskAssessmentJobs();
  scheduleRiskAssessmentDraftAutosave();
}

function handleRiskAssessmentJobsDragStart(event) {
  const row = event.target?.closest?.("[data-risk-job-index]");
  if (!row || !event.dataTransfer) {
    return;
  }
  const jobIndex = Number(row.dataset.riskJobIndex);
  const job = riskAssessmentJobDrafts[jobIndex];
  if (!job) {
    return;
  }
  event.dataTransfer.setData("text/risk-job-id", job.id);
  event.dataTransfer.effectAllowed = "move";
}

function renderRiskAssessmentJobTemplateActions() {
  if (!riskAssessmentRiskTemplateDrafts.length) {
    return "";
  }
  return `
    <div class="risk-assessment-template-strip">
      <span>Predlošci:</span>
      ${riskAssessmentRiskTemplateDrafts.map((template) => `
        <button type="button" class="ghost-button" data-risk-job-apply-template="${escapeHtml(template.id)}">${escapeHtml(template.name)}</button>
      `).join("")}
    </div>
  `;
}

function getRiskAssessmentRiskDisplayLevel(risk = {}) {
  return calculateRiskAssessmentRiskLevel(risk.probability, risk.consequence)
    || String(risk.riskLevel || "").trim()
    || "N/P";
}

function getRiskAssessmentRiskDisplayTone(risk = {}) {
  return getJobHazardRiskTone(getRiskAssessmentRiskDisplayLevel(risk));
}

function getRiskAssessmentRiskShortLabel(value = "") {
  const normalized = String(value || "").toLocaleLowerCase("hr");
  if (normalized.includes("mali")) return "Mali";
  if (normalized.includes("srednji")) return "Srednji";
  if (normalized.includes("veliki")) return "Veliki";
  return "N/P";
}

function getRiskAssessmentRiskType(risk = {}) {
  const source = [risk.topCategory, risk.category, risk.group]
    .filter(Boolean)
    .join(" ")
    .toLocaleLowerCase("hr");
  if (source.includes("napor")) {
    return { value: "effort", label: "Napor" };
  }
  if (source.includes("štetnost") || source.includes("stetnost")) {
    return { value: "harm", label: "Štetnost" };
  }
  if (source.includes("opasnost")) {
    return { value: "hazard", label: "Opasnost" };
  }
  return { value: "item", label: "Stavka" };
}

function getRiskAssessmentRiskScoreValue(risk = {}) {
  const probabilityScore = { mv: 1, v: 2, vv: 3 }[String(risk.probability || "").toLowerCase()] || 0;
  const consequenceScore = { "mš": 1, "ms": 1, "sš": 2, "ss": 2, "iš": 3, "is": 3 }[String(risk.consequence || "").toLowerCase()] || 0;
  return probabilityScore && consequenceScore ? String(probabilityScore * consequenceScore) : "";
}

function renderRiskAssessmentRiskIcon(name = "note") {
  const icons = {
    back: '<path d="M19 12H5" /><path d="m12 19-7-7 7-7" />',
    close: '<path d="M18 6 6 18" /><path d="m6 6 12 12" />',
    save: '<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z" /><path d="M17 21v-8H7v8" /><path d="M7 3v5h8" />',
    shield: '<path d="M20 13c0 5-3.5 7.5-7.3 8.8a2 2 0 0 1-1.4 0C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.2-2.4a1.3 1.3 0 0 1 1.6 0C14.5 3.8 17 5 19 5a1 1 0 0 1 1 1v7Z" /><path d="m9 12 2 2 4-4" />',
    note: '<path d="M8 2v4" /><path d="M16 2v4" /><rect width="16" height="18" x="4" y="4" rx="2" /><path d="M8 10h8" /><path d="M8 14h5" />',
    briefcase: '<path d="M16 20V4a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16" /><rect width="20" height="14" x="2" y="6" rx="2" /><path d="M2 13h20" />',
    map: '<path d="M9 18 3 21V6l6-3 6 3 6-3v15l-6 3-6-3Z" /><path d="M9 3v15" /><path d="M15 6v15" />',
    activity: '<path d="M22 12h-4l-3 8L9 4l-3 8H2" />',
    plus: '<path d="M12 5v14" /><path d="M5 12h14" />',
    edit: '<path d="M12 20h9" /><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z" />',
    eye: '<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z" /><circle cx="12" cy="12" r="3" />',
    thermometer: '<path d="M14 14.8V5a2 2 0 0 0-4 0v9.8a4 4 0 1 0 4 0Z" />',
    tools: '<path d="M14.7 6.3a4 4 0 0 0-5.6 5.6L3 18l3 3 6.1-6.1a4 4 0 0 0 5.6-5.6l-2.8 2.8-2-2 2.8-2.8Z" />',
    flask: '<path d="M9 2h6" /><path d="M10 2v6.7L4.7 18A3 3 0 0 0 7.3 22h9.4a3 3 0 0 0 2.6-4L14 8.7V2" /><path d="M7 16h10" />',
    building: '<path d="M3 21h18" /><path d="M5 21V7l8-4v18" /><path d="M19 21V11l-6-4" /><path d="M9 9h1" /><path d="M9 13h1" /><path d="M9 17h1" />',
    check: '<path d="M20 6 9 17l-5-5" />',
    lock: '<rect width="18" height="11" x="3" y="11" rx="2" /><path d="M7 11V7a5 5 0 0 1 10 0v4" />',
  };
  return `<svg class="risk-assessment-risk-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${icons[name] || icons.note}</svg>`;
}

function getRiskAssessmentTextareaCount(value = "") {
  return String(value || "").length;
}

function renderRiskAssessmentCompactOptions(options = [], selectedValue = "") {
  return options.map((option) => {
    const compactLabel = String(option.label || "")
      .replace(/\s+vjerojatnost$/i, "")
      .replace(/\s+posljedica$/i, "")
      .trim() || option.label;
    return `
      <option value="${escapeHtml(option.value)}" ${String(option.value) === String(selectedValue) ? "selected" : ""}>
        ${escapeHtml(compactLabel)}
      </option>
    `;
  }).join("");
}

function renderRiskAssessmentRiskScorePanel({
  title = "",
  field = "",
  value = "",
  options = [],
  riskIndex = 0,
  tone = "unknown",
  required = false,
} = {}) {
  return `
    <label class="risk-assessment-risk-score-panel">
      <span>${escapeHtml(title)}${required ? " *" : ""}<small aria-hidden="true">i</small></span>
      <div class="risk-assessment-risk-select-shell is-${tone}">
        <i aria-hidden="true"></i>
        <select data-risk-row-index="${riskIndex}" data-risk-row-field="${escapeHtml(field)}">
          ${renderRiskAssessmentCompactOptions(options, value || "")}
        </select>
      </div>
    </label>
  `;
}

function renderRiskAssessmentRiskPurPicker(risk = {}, riskIndex = 0) {
  const selected = new Set(normalizeJobPurPointValues(risk.purPoints ?? []));
  const selectedCount = selected.size;
  return `
    <section class="risk-assessment-risk-pur-field">
      <div class="risk-assessment-risk-pur-head">
        <span class="risk-assessment-risk-panel-icon">${renderRiskAssessmentRiskIcon("shield")}</span>
        <span>
          <strong>Posebni uvjeti rada za ovu stavku</strong>
          <small>Odaberi PUR točke koje se stvarno odnose na ovu opasnost, štetnost ili napor.</small>
        </span>
        <em>${escapeHtml(selectedCount ? `${selectedCount} odabrano` : "Ne")}</em>
      </div>
      <details class="risk-assessment-risk-pur-dropdown job-pur-multiselect">
        <summary>
          <span>${escapeHtml(selectedCount ? getJobPurPointSummary(Array.from(selected)) : "Odaberi iz popisa prema Pravilniku")}</span>
          <strong>Popis PUR</strong>
        </summary>
        <div class="risk-assessment-risk-pur-options job-pur-picker">
          ${renderJobPurPointGroups(selected, "data-risk-row-pur-point", `data-risk-row-index="${riskIndex}"`)}
        </div>
      </details>
    </section>
  `;
}

function getRiskAssessmentRiskRowDisplayTitle(risk = {}, index = 0) {
  return String(risk.hazard || risk.group || risk.category || risk.code || `ARMOR stavka ${index + 1}`).trim();
}

function isRiskAssessmentRiskRowComplete(risk = {}) {
  return Boolean(
    String(risk.hazard || "").trim()
    && String(risk.probability || "").trim()
    && String(risk.consequence || "").trim()
    && String(risk.existingMeasures || risk.measures || "").trim()
  );
}

function getRiskAssessmentActiveRiskRowIndex(job = {}) {
  const armorRows = getRiskAssessmentArmorRiskRowsWithIndexes(job);
  if (!armorRows.length) {
    return -1;
  }
  const activeId = String(job.activeRiskRowId || "");
  if (activeId) {
    const active = armorRows.find(({ risk }) => String(risk.id || "") === activeId);
    if (active) {
      return active.riskIndex;
    }
  }
  return armorRows[0].riskIndex;
}

function setRiskAssessmentActiveRiskRowIndex(jobIndex, riskIndex) {
  const job = riskAssessmentJobDrafts[jobIndex];
  const risk = job?.riskRows?.[riskIndex];
  if (!job || !risk) {
    return false;
  }
  riskAssessmentJobDrafts[jobIndex] = {
    ...job,
    activeRiskRowId: String(risk.id || ""),
  };
  return true;
}

function getRiskAssessmentArmorTreeGroupLabels(risk = {}) {
  const riskType = getRiskAssessmentRiskType(risk);
  const topLabel = String(risk.topCategory || riskType.label || "ARMOR").trim();
  const subLabel = String(risk.category || risk.group || "Stavke").trim();
  return {
    top: topLabel || "ARMOR",
    sub: subLabel || "Stavke",
  };
}

function getRiskAssessmentArmorSectionTone(label = "") {
  const normalized = String(label || "").trim();
  if (normalized.startsWith("I.")) {
    return "hazards";
  }
  if (normalized.startsWith("II.")) {
    return "harms";
  }
  if (normalized.startsWith("III.")) {
    return "efforts";
  }
  return "neutral";
}

function getRiskAssessmentArmorHierarchy(risk = {}) {
  if (risk.topCategory) {
    return getRiskAssessmentCatalogHierarchy({
      ...risk,
      category: risk.topCategory,
      group: risk.group || risk.category,
    });
  }
  const hierarchy = getRiskAssessmentCatalogHierarchy(risk);
  return {
    category: hierarchy.category || risk.topCategory || "ARMOR",
    family: hierarchy.family || risk.category || "Stavke",
    subgroup: hierarchy.subgroup || risk.group || hierarchy.family || "Stavke",
  };
}

function renderRiskAssessmentArmorExplorer(item = {}, jobIndex = 0) {
  const armorRows = getRiskAssessmentArmorRiskRowsWithIndexes(item);
  const activeIndex = getRiskAssessmentActiveRiskRowIndex(item);
  const sections = [];
  const sectionMap = new Map();
  armorRows.forEach(({ risk, riskIndex }) => {
    const hierarchy = getRiskAssessmentArmorHierarchy(risk);
    const sectionKey = hierarchy.category;
    let section = sectionMap.get(sectionKey);
    if (!section) {
      section = {
        label: hierarchy.category,
        tone: getRiskAssessmentArmorSectionTone(hierarchy.category),
        families: [],
        familyMap: new Map(),
      };
      sectionMap.set(sectionKey, section);
      sections.push(section);
    }
    let family = section.familyMap.get(hierarchy.family);
    if (!family) {
      family = { label: hierarchy.family, subgroups: [], subgroupMap: new Map() };
      section.familyMap.set(hierarchy.family, family);
      section.families.push(family);
    }
    let subgroup = family.subgroupMap.get(hierarchy.subgroup);
    if (!subgroup) {
      subgroup = { label: hierarchy.subgroup, rows: [] };
      family.subgroupMap.set(hierarchy.subgroup, subgroup);
      family.subgroups.push(subgroup);
    }
    subgroup.rows.push({ risk, riskIndex });
  });

  return `
    <section class="risk-assessment-armor-explorer">
      <div class="risk-assessment-armor-explorer-head">
        <strong>ARMOR explorer</strong>
        <span>${escapeHtml(`${armorRows.length} stavki`)}</span>
      </div>
      <div class="risk-assessment-armor-tree-nodes">
        ${sections.length ? sections.map((section) => `
          <div class="risk-assessment-armor-tree-node is-folder is-section is-${escapeHtml(section.tone)}" style="--unit-depth: 0">
            <div class="risk-assessment-armor-tree-row is-title is-section-title">
              <span class="risk-assessment-job-tree-icon" aria-hidden="true">${renderRiskAssessmentRiskIcon("activity")}</span>
              <span class="risk-assessment-job-tree-copy">
                <strong>${escapeHtml(section.label)}</strong>
                <small>${escapeHtml(`${section.families.reduce((sum, family) => sum + family.subgroups.reduce((subSum, subgroup) => subSum + subgroup.rows.length, 0), 0)} stavki`)}</small>
              </span>
            </div>
            <div class="risk-assessment-armor-tree-children">
              ${section.families.map((family) => `
                <div class="risk-assessment-armor-tree-node is-folder is-family is-${escapeHtml(section.tone)}" style="--unit-depth: 1">
                  <div class="risk-assessment-armor-tree-row is-title is-family-title">
                    <span class="risk-assessment-job-tree-icon" aria-hidden="true">${renderRiskAssessmentRiskIcon("note")}</span>
                    <span class="risk-assessment-job-tree-copy">
                      <strong>${escapeHtml(family.label)}</strong>
                      <small>${escapeHtml(`${family.subgroups.reduce((sum, subgroup) => sum + subgroup.rows.length, 0)} stavki`)}</small>
                    </span>
                  </div>
                  <div class="risk-assessment-armor-tree-children">
                    ${family.subgroups.map((subgroup) => `
                      <div class="risk-assessment-armor-tree-node is-folder is-subgroup is-${escapeHtml(section.tone)}" style="--unit-depth: 2">
                        <div class="risk-assessment-armor-tree-row is-title is-subgroup-title">
                          <span class="risk-assessment-job-tree-icon" aria-hidden="true">${renderRiskAssessmentRiskIcon("note")}</span>
                          <span class="risk-assessment-job-tree-copy">
                            <strong>${escapeHtml(subgroup.label)}</strong>
                            <small>${escapeHtml(`${subgroup.rows.length} stavki`)}</small>
                          </span>
                        </div>
                        <div class="risk-assessment-armor-tree-children">
                          ${subgroup.rows.map(({ risk, riskIndex }) => {
                            const riskLevel = getRiskAssessmentRiskDisplayLevel(risk);
                            const riskTone = getRiskAssessmentRiskDisplayTone(risk);
                            const complete = isRiskAssessmentRiskRowComplete(risk);
                            const title = getRiskAssessmentRiskRowDisplayTitle(risk, riskIndex);
                            const code = String(risk.code || "").trim();
                            return `
                              <div class="risk-assessment-armor-tree-node is-item ${riskIndex === activeIndex ? "is-active" : ""} ${complete ? "is-complete" : ""}" style="--unit-depth: 3">
                                <button type="button" class="risk-assessment-armor-tree-row" data-risk-row-select="${escapeHtml(String(riskIndex))}" data-risk-job-index="${escapeHtml(String(jobIndex))}">
                                  <span class="risk-assessment-armor-risk-dot is-${escapeHtml(riskTone)}" aria-hidden="true"></span>
                                  <span class="risk-assessment-job-tree-copy">
                                    <strong>${escapeHtml(code ? `${code} ${title}` : title)}</strong>
                                    <small>${escapeHtml(riskLevel || "N/P")}</small>
                                  </span>
                                  <span class="risk-assessment-job-tree-state ${complete ? "is-done" : ""}" aria-label="${escapeHtml(complete ? "Stavka popunjena" : "Nedovršeno")}">${complete ? "✓" : ""}</span>
                                </button>
                              </div>
                            `;
                          }).join("")}
                        </div>
                      </div>
                    `).join("")}
                  </div>
                </div>
              `).join("")}
            </div>
          </div>
        `).join("") : `
          <div class="risk-assessment-job-tree-empty">
            <strong>Nema ARMOR stavki</strong>
            <span>Dodaj stavku ili cijeli popis iz Priloga III.</span>
          </div>
        `}
      </div>
    </section>
  `;
}

function renderRiskAssessmentRiskCards(item = {}) {
  const activeIndex = getRiskAssessmentActiveRiskRowIndex(item);
  const visibleRows = getRiskAssessmentArmorRiskRowsWithIndexes(item);
  return `
    <div class="risk-assessment-risk-cards">
      ${visibleRows.length ? visibleRows.map(({ risk, riskIndex }) => {
        const riskLevel = getRiskAssessmentRiskDisplayLevel(risk);
        const riskTone = getRiskAssessmentRiskDisplayTone(risk);
        const riskShortLabel = getRiskAssessmentRiskShortLabel(riskLevel);
        const riskScore = getRiskAssessmentRiskScoreValue(risk);
        const riskType = getRiskAssessmentRiskType(risk);
        const classificationText = getRiskAssessmentRiskHierarchyParts(risk).join("\n");
        const workNoteValue = risk.workNote || risk.note || risk.possibleConsequences || "";
        const measuresValue = risk.existingMeasures || risk.measures || risk.additionalMeasures || "";
        const isActive = riskIndex === activeIndex;
        const isCollapsed = Boolean(risk.collapsed);
        return `
        <article class="risk-assessment-risk-card is-${riskTone} ${isActive ? "is-active" : ""} ${isCollapsed ? "is-collapsed" : ""}">
          <div class="risk-assessment-risk-card-head">
            <div class="risk-assessment-risk-title-shell">
              <div class="risk-assessment-risk-title-row">
                <input class="risk-assessment-risk-code-input" data-risk-row-index="${riskIndex}" data-risk-row-field="code" value="${escapeHtml(risk.code || "")}" placeholder="2.1.1" aria-label="Broj stavke rizika" />
                <input class="risk-assessment-risk-title-input" data-risk-row-index="${riskIndex}" data-risk-row-field="hazard" value="${escapeHtml(risk.hazard || "")}" placeholder="Naziv opasnosti, štetnosti ili napora" aria-label="Naziv stavke rizika" />
              </div>
              <div class="risk-assessment-risk-meta-row">
                <span class="risk-assessment-risk-type-pill is-${escapeHtml(riskType.value)}">${escapeHtml(riskType.label)}</span>
                <span class="risk-assessment-risk-classification">${escapeHtml(classificationText || "Ručno dodana stavka procjene")}</span>
              </div>
            </div>
            <div class="risk-assessment-risk-head-actions">
              <button type="button" class="risk-assessment-risk-collapse-icon" data-risk-row-collapse="${riskIndex}" aria-label="${escapeHtml(isCollapsed ? "Prikaži ARMOR stavku" : "Sakrij ARMOR stavku")}" aria-expanded="${isCollapsed ? "false" : "true"}">${isCollapsed ? "+" : "−"}</button>
              <button type="button" class="risk-assessment-risk-remove-icon" data-risk-row-remove="${riskIndex}" aria-label="Ukloni ARMOR stavku">${renderRiskAssessmentRiskIcon("close")}</button>
            </div>
          </div>
          <div class="risk-assessment-risk-body" ${isCollapsed ? "hidden" : ""}>
            <section class="risk-assessment-risk-assessment-panel">
              <div class="risk-assessment-risk-panel-title">
                <span class="risk-assessment-risk-panel-icon">${renderRiskAssessmentRiskIcon("shield")}</span>
                <strong>Procjena rizika</strong>
              </div>
              <div class="risk-assessment-risk-score-grid">
                ${renderRiskAssessmentRiskScorePanel({
                  title: "Vjerojatnost",
                  field: "probability",
                  value: risk.probability,
                  options: RISK_ASSESSMENT_PROBABILITY_OPTIONS,
                  riskIndex,
                  tone: riskTone,
                  required: true,
                })}
                ${renderRiskAssessmentRiskScorePanel({
                  title: "Posljedica",
                  field: "consequence",
                  value: risk.consequence,
                  options: RISK_ASSESSMENT_CONSEQUENCE_OPTIONS,
                  riskIndex,
                  tone: riskTone,
                  required: true,
                })}
                <section class="risk-assessment-risk-score-panel is-result">
                  <span>Rizik</span>
                  <output class="risk-assessment-risk-result is-${riskTone}" data-risk-row-output="${riskIndex}">
                    <i aria-hidden="true"></i>
                    <strong>${escapeHtml(riskLevel || `${riskShortLabel} rizik`)}</strong>
                    ${riskScore ? `<em>${escapeHtml(riskScore)}</em>` : ""}
                  </output>
                </section>
              </div>
              ${renderRiskAssessmentRiskPurPicker(risk, riskIndex)}
            </section>
            <div class="risk-assessment-risk-detail-grid">
              <section class="risk-assessment-risk-large-field">
                <div>
                  <span class="risk-assessment-risk-panel-icon">${renderRiskAssessmentRiskIcon("note")}</span>
                  <span>
                    <strong>Poslovi / napomena</strong>
                    <small>Upiši kod kojeg zadatka se stavka pojavljuje i koga obuhvaća.</small>
                  </span>
                </div>
                <textarea data-risk-row-index="${riskIndex}" data-risk-row-field="workNote" rows="2" placeholder="Unesite poslove i dodatne napomene...">${escapeHtml(workNoteValue)}</textarea>
                <small class="risk-assessment-risk-character-count">${escapeHtml(String(getRiskAssessmentTextareaCount(workNoteValue)))} / 1000</small>
              </section>
              <section class="risk-assessment-risk-large-field">
                <div>
                  <span class="risk-assessment-risk-panel-icon">${renderRiskAssessmentRiskIcon("shield")}</span>
                  <span>
                    <strong>Pravila, mjere, postupci i aktivnosti za smanjivanje razine rizika</strong>
                    <small>Uključi postupak rada, opremu, OZO, osposobljavanje, preglede i nadzor.</small>
                  </span>
                </div>
                <textarea data-risk-row-index="${riskIndex}" data-risk-row-field="existingMeasures" rows="2" placeholder="Unesite pravila, mjere i aktivnosti...">${escapeHtml(measuresValue)}</textarea>
                <small class="risk-assessment-risk-character-count">${escapeHtml(String(getRiskAssessmentTextareaCount(measuresValue)))} / 1000</small>
              </section>
            </div>
          </div>
        </article>
      `;
      }).join("") : `
        <div class="risk-assessment-job-tree-empty">
          <strong>Nema ARMOR stavki</strong>
          <span>Dodaj stavku ili cijeli popis iz Priloga III.</span>
        </div>
      `}
    </div>
  `;
}

function getRiskAssessmentActiveJobIndex() {
  if (!riskAssessmentJobDrafts.length) {
    return -1;
  }
  const index = Number(riskAssessmentActiveJobIndex);
  if (!Number.isInteger(index) || index < 0) {
    riskAssessmentActiveJobIndex = 0;
    return 0;
  }
  if (index >= riskAssessmentJobDrafts.length) {
    riskAssessmentActiveJobIndex = riskAssessmentJobDrafts.length - 1;
  }
  return riskAssessmentActiveJobIndex;
}

function setRiskAssessmentActiveJobIndex(index = 0) {
  if (!riskAssessmentJobDrafts.length) {
    riskAssessmentActiveJobIndex = 0;
    return -1;
  }
  const safeIndex = Math.max(0, Math.min(Number(index) || 0, riskAssessmentJobDrafts.length - 1));
  riskAssessmentActiveJobIndex = safeIndex;
  return safeIndex;
}

function getRiskAssessmentJobAnalysisShell() {
  return riskAssessmentJobsList?.closest?.(".risk-assessment-job-analysis-shell") ?? null;
}

function updateRiskAssessmentJobAnalysisShellMode() {
  const shell = getRiskAssessmentJobAnalysisShell();
  if (!shell) {
    return;
  }
  if (riskAssessmentActiveBlock !== "jobs") {
    shell.classList.remove("is-armor-focus");
    return;
  }
  if (!riskAssessmentJobDrafts.length) {
    shell.classList.toggle("is-armor-focus", riskAssessmentOrganizationUnitDrafts.length > 0);
    return;
  }

  const viewport = riskAssessmentEditorBody?.getBoundingClientRect?.() ?? {
    top: 0,
    bottom: window.innerHeight || document.documentElement.clientHeight || 0,
  };
  const armorCards = Array.from(shell.querySelectorAll(".risk-assessment-job-profile-card.is-armor"));
  const armorInView = armorCards.some((card) => {
    const rect = card.getBoundingClientRect();
    return rect.top < viewport.bottom - 120 && rect.bottom > viewport.top + 120;
  });
  shell.classList.toggle("is-armor-focus", armorInView);
}

function scheduleRiskAssessmentJobAnalysisShellModeUpdate() {
  if (riskAssessmentJobAnalysisScrollFrame) {
    return;
  }
  riskAssessmentJobAnalysisScrollFrame = window.requestAnimationFrame(() => {
    riskAssessmentJobAnalysisScrollFrame = 0;
    updateRiskAssessmentJobAnalysisShellMode();
  });
}

function renderRiskAssessmentJobTreeQuickAddForm(parentId = "", type = "workplace") {
  const normalizedType = normalizeRiskAssessmentUnitType(type);
  const isWorkplace = normalizedType === "workplace";
  return `
    <div class="risk-assessment-job-tree-quick-form"
      data-risk-job-tree-quick-form
      data-risk-parent-id="${escapeHtml(parentId)}"
      data-risk-child-type="${escapeHtml(normalizedType)}">
      <label>
        <span>${escapeHtml(isWorkplace ? "Novo radno mjesto" : "Nova podorganizacija")}</span>
        <input data-risk-job-tree-quick-name
          placeholder="${escapeHtml(isWorkplace ? "npr. Serviser automobila" : "npr. Servis")}"
          autocomplete="off" />
      </label>
      <div>
        <button type="button" class="primary-button" data-risk-job-tree-quick-save>${escapeHtml(isWorkplace ? "Dodaj radno mjesto" : "Dodaj podorganizaciju")}</button>
        <button type="button" class="ghost-button" data-risk-job-tree-quick-cancel>Odustani</button>
      </div>
    </div>
  `;
}

function addRiskAssessmentQuickTreeUnit(parentId = "", type = "workplace", name = "") {
  if (!getCanManageRiskAssessments()) {
    return;
  }
  const normalizedType = normalizeRiskAssessmentUnitType(type);
  const parent = parentId
    ? riskAssessmentOrganizationUnitDrafts.find((unit) => String(unit.id || "") === String(parentId))
    : null;
  if (parentId && !parent) {
    return;
  }
  const trimmedName = String(name || "").trim();
  const child = createRiskAssessmentOrganizationUnitDraft({
    parentId: parent?.id || "",
    type: normalizedType,
    name: trimmedName || (normalizedType === "workplace" ? "Novo radno mjesto" : "Nova podorganizacija"),
  });
  riskAssessmentOrganizationUnitDrafts.push(child);
  if (parent?.id) {
    riskAssessmentOpenOrganizationUnitIds.add(String(parent.id));
  }
  riskAssessmentOpenOrganizationUnitIds.add(String(child.id || ""));
  riskAssessmentJobTreeQuickAddState = null;
  if (normalizedType === "workplace") {
    addRiskAssessmentJobFromUnit(child.id);
    return;
  }
  renderRiskAssessmentOrganizationUnits();
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  scheduleRiskAssessmentDraftAutosave();
}

function renderRiskAssessmentJobTreeNode(unit = {}, childrenByParent = new Map(), activeIndex = -1, depth = 0) {
  const unitId = String(unit.id || "");
  const type = normalizeRiskAssessmentUnitType(unit.type || "");
  const isWorkplace = type === "workplace";
  const children = childrenByParent.get(unitId) || [];
  const jobIndex = isWorkplace ? getRiskAssessmentJobIndexForWorkplaceUnit(unitId) : -1;
  const job = jobIndex >= 0 ? riskAssessmentJobDrafts[jobIndex] : null;
  const requiredComplete = Boolean(job && isRiskAssessmentJobRequiredComplete(job));
  const completion = job ? getRiskAssessmentJobCompletion(job) : 0;
  const riskCount = job ? getRiskAssessmentFilledRiskRowCount(job) : 0;
  const nodeClass = [
    "risk-assessment-job-tree-node",
    isWorkplace ? "is-workplace" : "is-folder",
    jobIndex === activeIndex ? "is-active" : "",
    requiredComplete ? "is-complete" : "",
  ].filter(Boolean).join(" ");
  const label = unit.name || getRiskAssessmentUnitTypeLabel(type);
  const typeLabel = isWorkplace ? "Radno mjesto" : getRiskAssessmentUnitTypeLabel(type);
  const row = isWorkplace
    ? `
      <button type="button" class="risk-assessment-job-tree-row" data-risk-workplace-job-index="${escapeHtml(String(jobIndex))}" ${jobIndex >= 0 ? "" : "disabled"}>
        <span class="risk-assessment-job-tree-icon" aria-hidden="true">${renderRiskAssessmentRiskIcon("briefcase")}</span>
        <span class="risk-assessment-job-tree-copy">
          <strong>${escapeHtml(label)}</strong>
          <small>${escapeHtml(`${completion}% · ${riskCount} ARMOR`)}</small>
        </span>
        <span class="risk-assessment-job-tree-state ${requiredComplete ? "is-done" : ""}" aria-label="${escapeHtml(requiredComplete ? "Obavezna polja popunjena" : "Nedovršeno")}">${requiredComplete ? "✓" : ""}</span>
      </button>
    `
    : `
      <div class="risk-assessment-job-tree-row">
        <span class="risk-assessment-job-tree-icon" aria-hidden="true">${renderRiskAssessmentRiskIcon("building")}</span>
        <span class="risk-assessment-job-tree-copy">
          <strong>${escapeHtml(label)}</strong>
          <small>${escapeHtml(typeLabel)}</small>
        </span>
        <span class="risk-assessment-job-tree-actions" aria-label="Dodaj u ${escapeHtml(label)}">
          <button type="button"
            data-risk-job-tree-quick-add="${escapeHtml(unitId)}"
            data-risk-child-type="subunit"
            title="Dodaj podorganizaciju"
            aria-label="Dodaj podorganizaciju">${renderRiskAssessmentRiskIcon("building")}${renderRiskAssessmentRiskIcon("plus")}</button>
          <button type="button"
            data-risk-job-tree-quick-add="${escapeHtml(unitId)}"
            data-risk-child-type="workplace"
            title="Dodaj radno mjesto"
            aria-label="Dodaj radno mjesto">${renderRiskAssessmentRiskIcon("briefcase")}${renderRiskAssessmentRiskIcon("plus")}</button>
        </span>
      </div>
    `;
  const quickState = riskAssessmentJobTreeQuickAddState;
  const quickForm = quickState && String(quickState.parentId || "") === unitId
    ? renderRiskAssessmentJobTreeQuickAddForm(unitId, quickState.type || "workplace")
    : "";
  return `
    <div class="${escapeHtml(nodeClass)}" style="--unit-depth: ${escapeHtml(String(Math.min(depth, 6)))}">
      ${row}
      ${quickForm}
      ${children.length ? `<div class="risk-assessment-job-tree-children">${children.map((child) => renderRiskAssessmentJobTreeNode(child, childrenByParent, activeIndex, depth + 1)).join("")}</div>` : ""}
    </div>
  `;
}

function renderRiskAssessmentJobTreeHead(completedCount = 0, workplaceCount = 0) {
  const disabled = !getCanManageRiskAssessments();
  return `
    <div class="risk-assessment-job-tree-head">
      <div>
        <strong>Stablo radnih mjesta</strong>
        <span>${escapeHtml(`${completedCount}/${workplaceCount} obrađeno`)}</span>
      </div>
      <button type="button"
        class="ghost-button risk-assessment-icon-button risk-assessment-job-tree-add"
        data-risk-job-tree-add-workplace
        title="Dodaj radno mjesto"
        aria-label="Dodaj radno mjesto"
        ${disabled ? "disabled" : ""}>${renderRiskAssessmentRiskIcon("plus")}</button>
    </div>
  `;
}

function renderRiskAssessmentJobTree() {
  if (!riskAssessmentJobTree) {
    return;
  }
  if (riskAssessmentJobTreeRenderTimer) {
    window.clearTimeout(riskAssessmentJobTreeRenderTimer);
    riskAssessmentJobTreeRenderTimer = null;
  }
  if (!riskAssessmentJobDrafts.length && !riskAssessmentOrganizationUnitDrafts.length) {
    riskAssessmentJobTree.innerHTML = `
      <section class="risk-assessment-job-tree-block is-jobs">
      ${renderRiskAssessmentJobTreeHead(0, 0)}
      ${riskAssessmentJobTreeQuickAddState && !riskAssessmentJobTreeQuickAddState.parentId ? renderRiskAssessmentJobTreeQuickAddForm("", riskAssessmentJobTreeQuickAddState.type || "workplace") : ""}
      <div class="risk-assessment-job-tree-empty">
        <strong>Nema radnih mjesta</strong>
        <span>Klikni + za brzo dodavanje prvog radnog mjesta.</span>
      </div>
      </section>
    `;
    return;
  }
  const activeIndex = getRiskAssessmentActiveWorkplaceJobIndex();
  const childrenByParent = getRiskAssessmentUnitChildrenMap();
  const roots = childrenByParent.get("") || [];
  const workplaceUnits = riskAssessmentOrganizationUnitDrafts.filter((unit) => normalizeRiskAssessmentUnitType(unit.type) === "workplace");
  const completedCount = getRiskAssessmentProcessableJobIndexes()
    .filter((index) => isRiskAssessmentJobRequiredComplete(riskAssessmentJobDrafts[index]))
    .length;
  const activeJob = activeIndex >= 0 && isRiskAssessmentWorkplaceJob(riskAssessmentJobDrafts[activeIndex])
    ? riskAssessmentJobDrafts[activeIndex]
    : null;
  riskAssessmentJobTree.innerHTML = `
    <section class="risk-assessment-job-tree-block is-jobs">
      ${renderRiskAssessmentJobTreeHead(completedCount, workplaceUnits.length)}
      ${riskAssessmentJobTreeQuickAddState && !riskAssessmentJobTreeQuickAddState.parentId ? renderRiskAssessmentJobTreeQuickAddForm("", riskAssessmentJobTreeQuickAddState.type || "workplace") : ""}
      ${roots.length ? `<div class="risk-assessment-job-tree-nodes">${roots.map((unit) => renderRiskAssessmentJobTreeNode(unit, childrenByParent, activeIndex)).join("")}</div>` : `
        <div class="risk-assessment-job-tree-empty">
          <strong>Nema strukture</strong>
          <span>Dodaj organizacijsku jedinicu i radna mjesta u prethodnom koraku.</span>
        </div>
      `}
    </section>
    ${activeJob ? `
      <section class="risk-assessment-job-tree-block is-armor">
        ${renderRiskAssessmentArmorExplorer(activeJob, activeIndex)}
      </section>
    ` : ""}
  `;
}

function renderRiskAssessmentJobs(options = {}) {
  if (!riskAssessmentJobsList) {
    return;
  }
  const {
    refreshLinkedSheets = true,
    refreshOverview = true,
    refreshTree = true,
    refreshCatalogOptions = true,
  } = options || {};
  ensureRiskAssessmentJobsFromWorkplaceUnits();
  const armorCatalogSeeded = ensureRiskAssessmentArmorCatalogRowsForWorkplaceJobs();
  const activeWorkplaceIndex = getRiskAssessmentActiveWorkplaceJobIndex();
  if (refreshCatalogOptions) {
    syncRiskAssessmentJobCatalogOptions();
  }
  disposeRiskAssessmentPpeScenes();
  syncRiskAssessmentJobCatalogAiDescriptionFromActiveJob();

  if (activeWorkplaceIndex < 0) {
    const empty = document.createElement("p");
    empty.className = "inline-help";
    empty.textContent = "Dodaj radno mjesto u organizacijskoj strukturi, zatim ga ovdje obradi.";
    riskAssessmentJobsList.replaceChildren(empty);
    if (refreshTree) {
      renderRiskAssessmentJobTree();
    }
    renderRiskAssessmentManualScope();
    updateRiskAssessmentJobAnalysisShellMode();
    if (refreshOverview) {
      renderRiskAssessmentOverview();
    }
    return;
  }
  riskAssessmentJobDrafts[activeWorkplaceIndex] = {
    ...riskAssessmentJobDrafts[activeWorkplaceIndex],
    riskRows: sortRiskAssessmentRiskRowsByPrilogOrder(riskAssessmentJobDrafts[activeWorkplaceIndex]?.riskRows ?? []),
  };

  const item = riskAssessmentJobDrafts[activeWorkplaceIndex];
  if (!item) {
    riskAssessmentJobsList.replaceChildren();
    return;
  }
  const row = (() => {
    const index = activeWorkplaceIndex;
    const row = document.createElement("div");
    row.className = "risk-assessment-repeat-row is-job is-active-workplace";
    row.dataset.riskJobIndex = String(index);
    row.draggable = true;
    const hiddenBlocks = getRiskAssessmentJobHiddenBlocks(item);
    const riskCount = getRiskAssessmentFilledRiskRowCount(item);
    const selectedJobTitle = item.jobTitle || `Radno mjesto ${index + 1}`;
    const completion = getRiskAssessmentJobCompletion(item);
    const requiredComplete = isRiskAssessmentJobRequiredComplete(item);
    const status = getRiskAssessmentJobStatusOption(item.status);
    const isClientPortalActor = isClientPortalUser(state.user);
    const clientJobInputEnabled = getRiskAssessmentClientJobInputEnabled();
    const showClientInput = (isClientPortalActor && clientJobInputEnabled)
      || (!isClientPortalActor && hasRiskAssessmentClientJobInput(item.clientInput));
    const showClientLockedNotice = isClientPortalActor && !clientJobInputEnabled;
    const isCollapsed = false;
    row.classList.toggle("is-required-complete", requiredComplete);
    row.classList.toggle("is-collapsed", isCollapsed);
    row.innerHTML = `
      <div class="risk-assessment-job-head" data-risk-job-toggle-head role="button" tabindex="0" aria-expanded="${isCollapsed ? "false" : "true"}" title="${escapeHtml(isCollapsed ? "Klikni za prikaz detalja radnog mjesta" : "Klikni za sažimanje radnog mjesta")}">
        <div>
          <span class="section-kicker">${escapeHtml(getRiskAssessmentUnitName(item.organizationUnitId) || "Bez jedinice")}</span>
          <div class="risk-assessment-job-title-row">
            <strong>${escapeHtml(selectedJobTitle)}</strong>
            ${requiredComplete ? `<span class="risk-assessment-job-complete-badge"><span aria-hidden="true">&#10003;</span> Obavezno popunjeno</span>` : ""}
          </div>
          <small>${escapeHtml(`${status.label} · ${completion}% popunjeno · ${riskCount} ARMOR stavki`)}</small>
        </div>
        <div class="risk-assessment-job-tools">
          <span class="risk-assessment-job-collapse-marker" aria-hidden="true">${isCollapsed ? "+" : "&minus;"}</span>
          <button type="button" class="ghost-button" data-risk-job-copy="${index}">Kopiraj</button>
          <button type="button" class="ghost-button card-danger" data-risk-job-remove="${index}">Ukloni</button>
        </div>
      </div>

      ${isCollapsed ? `
        <div class="risk-assessment-job-collapsed-summary">
          <span>${escapeHtml(getRiskAssessmentUnitPath(riskAssessmentOrganizationUnitDrafts.find((unit) => String(unit.id || "") === String(item.organizationUnitId || "")) || {}) || "Bez organizacijske jedinice")}</span>
          <span>${escapeHtml(item.workerCount || "Bez broja radnika")}</span>
          <span>${escapeHtml(`${riskCount} ARMOR stavki`)}</span>
        </div>
      ` : `
        ${renderRiskAssessmentJobAiProposal(item, index)}

        ${hiddenBlocks.has("profile") ? "" : renderRiskAssessmentJobProfile(item, index)}

        ${showClientInput ? renderRiskAssessmentClientPortalJobInput(item, index) : ""}
        ${showClientLockedNotice ? renderRiskAssessmentClientPortalLockedNotice() : ""}
      `}
    `;
    return row;
  })();
  riskAssessmentJobsList.replaceChildren(row);
  setRiskAssessmentActiveBlock(riskAssessmentActiveBlock || "basic");
  initializeRiskAssessmentPpeScenes();
  if (refreshTree) {
    renderRiskAssessmentJobTree();
  }
  if (refreshLinkedSheets) {
    renderRiskAssessmentManualScope();
    renderRiskAssessmentManualHandling();
    renderRiskAssessmentChemicals();
    renderRiskAssessmentBiologicalRisks();
  }
  if (refreshOverview) {
    renderRiskAssessmentOverview();
  }
  if (armorCatalogSeeded) {
    scheduleRiskAssessmentDraftAutosave();
  }
  scheduleRiskAssessmentJobAnalysisShellModeUpdate();
}

function buildRiskAssessmentPayload() {
  if (!getCanManageRiskAssessments() && isClientPortalUser(state.user)) {
    const payload = {
      clientNote: riskAssessmentClientNoteInput?.value || "",
    };
    if (getRiskAssessmentClientJobInputEnabled()) {
      payload.jobs = riskAssessmentJobDrafts
        .filter((job) => isRiskAssessmentWorkplaceJob(job))
        .map((job) => sanitizeRiskAssessmentClientPortalJobPayload(job));
    }
    return {
      ...payload,
    };
  }
  syncRiskAssessmentRichValues();
  const leadSelection = readRiskAssessmentPeopleSelection(riskAssessmentTeamLeadInput);
  const legacyCollaboratorSelection = readRiskAssessmentPeopleSelection(riskAssessmentCollaboratorsInput);
  const companyCollaboratorSummary = getRiskAssessmentCompanyCollaboratorSummary();
  const companyId = riskAssessmentCompanyInput?.value || "";
  const assessmentDate = normalizeDateInputValue(riskAssessmentDateInput?.value || "");
  const completionDate = normalizeDateInputValue(riskAssessmentCompletionDateInput?.value || "");
  const assessmentNumber = refreshRiskAssessmentAutoNumber(riskAssessmentNumberInput?.value || "");
  const selectedLocationIds = getRiskAssessmentSelectedLocationIds();
  const locationId = Boolean(riskAssessmentAllLocationsInput?.checked)
    ? ""
    : (riskAssessmentLocationInput?.value || selectedLocationIds[0] || "");

  return {
    companyId,
    locationId,
    workOrderId: riskAssessmentWorkOrderInput?.value || "",
    assessmentNumber,
    status: riskAssessmentStatusInput?.value || "draft",
    title: riskAssessmentTitleInput?.value || buildRiskAssessmentGeneratedTitle(companyId),
    assessmentDate,
    completionDate,
    revisionDate: "",
    teamLead: leadSelection.labels.join(", "),
    teamLeadUserIds: leadSelection.userIds,
    collaborators: companyCollaboratorSummary || legacyCollaboratorSelection.labels.join(", "),
    collaboratorUserIds: companyCollaboratorSummary ? [] : legacyCollaboratorSelection.userIds,
    employerData: readRiskAssessmentEmployerData(),
    intro: riskAssessmentIntroInput?.value || "",
    workProcessDescription: riskAssessmentWorkProcessInput?.value || "",
    generalData: riskAssessmentGeneralDataInput?.value || "",
    computerWorkplaces: riskAssessmentComputerWorkplacesInput?.value || "",
    basicRules: riskAssessmentBasicRulesInput?.value || "",
    specialRules: riskAssessmentSpecialRulesInput?.value || "",
    omissionsBasic: riskAssessmentOmissionsBasicInput?.value || "",
    omissionsSpecial: riskAssessmentOmissionsSpecialInput?.value || "",
    conclusion: riskAssessmentConclusionInput?.value || "",
    biologicalHazards: riskAssessmentBiologicalHazardsInput?.value || "",
    clientNote: riskAssessmentClientNoteInput?.value || "",
    clientJobInputEnabled: getRiskAssessmentClientJobInputEnabled(),
    measures: riskAssessmentMeasureDrafts,
    organizationUnits: riskAssessmentOrganizationUnitDrafts.map((unit) => sanitizeRiskAssessmentTransientUnit(unit)),
    jobs: riskAssessmentJobDrafts
      .filter((job) => isRiskAssessmentWorkplaceJob(job))
      .map((job) => sanitizeRiskAssessmentTransientJob({
        ...job,
        riskRows: sortRiskAssessmentRiskRowsByPrilogOrder(job.riskRows ?? []),
      })),
    riskTemplates: riskAssessmentRiskTemplateDrafts,
    manualHandlingScope: sanitizeRiskAssessmentManualScopeDraft(riskAssessmentManualHandlingScopeDraft),
    manualHandling: riskAssessmentManualHandlingDrafts.map((entry) => sanitizeRiskAssessmentManualHandlingDraft(entry)),
    chemicals: riskAssessmentChemicalDrafts.map((chemical) => sanitizeRiskAssessmentTransientChemical(chemical)),
    biologicalRisks: riskAssessmentBiologicalRiskDrafts.map((entry) => sanitizeRiskAssessmentTransientBiologicalRisk(entry)),
    reportTemplate: sanitizeRiskAssessmentReportTemplateDraft(riskAssessmentReportTemplateDraft || {}),
    attachments: normalizeRiskAssessmentAttachmentDrafts(riskAssessmentAttachmentDrafts),
  };
}

function renderRiskAssessmentCard(item = {}) {
  const card = document.createElement("article");
  card.className = `risk-assessment-card is-${item.status || "draft"}`;
  card.tabIndex = 0;
  const status = getRiskAssessmentStatusOption(item.status);
  const measuresOpen = (item.measures ?? []).filter((entry) => String(entry.status || "open") !== "done").length;
  const jobsCount = (item.jobs ?? []).length;
  const unitsCount = (item.organizationUnits ?? []).length;
  const ppeCount = (item.jobs ?? []).reduce((sum, job) => sum + (job.ppeItems ?? []).length, 0);
  const chemicalCount = (item.chemicals ?? []).length;
  const manualCount = (item.manualHandling ?? item.manualHandlingItems ?? []).length;
  const locationText = item.locationName || "Sve lokacije / nije vezano";
  const workOrderText = item.workOrderNumber ? `RN ${item.workOrderNumber}` : "";
  card.innerHTML = `
    <div class="risk-assessment-card-main">
      <span class="section-kicker">${escapeHtml(status.label)}</span>
      <strong>${escapeHtml(item.assessmentNumber || "Bez broja")} · ${escapeHtml(item.title || "Procjena rizika")}</strong>
      <span>${escapeHtml([item.companyName || "Tvrtka", locationText, workOrderText].filter(Boolean).join(" · "))}</span>
    </div>
    <div class="risk-assessment-card-meta">
      <span class="soft-pill">${unitsCount} jedinica</span>
      <span class="soft-pill">${jobsCount} poslova</span>
      <span class="soft-pill">${manualCount} IOR</span>
      <span class="soft-pill">${chemicalCount} kemikalija</span>
      <span class="soft-pill">${ppeCount} OZO</span>
      <span class="soft-pill">${measuresOpen} mjera</span>
      <span class="soft-pill">${escapeHtml(item.assessmentDate ? formatCompactDate(item.assessmentDate) : "Bez datuma")}</span>
      ${item.completionDate ? `<span class="soft-pill">Završetak ${escapeHtml(formatCompactDate(item.completionDate))}</span>` : ""}
    </div>
  `;
  card.addEventListener("click", () => hydrateRiskAssessmentForm(item));
  card.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      hydrateRiskAssessmentForm(item);
    }
  });
  return card;
}

function renderRiskAssessmentModule() {
  if (!riskAssessmentModule) {
    return;
  }

  const canManage = getCanManageRiskAssessments();
  loadRiskAssessmentModuleTemplate();
  if (!state.riskAssessmentEditorOpen) {
    riskAssessmentReportTemplateDraft = getRiskAssessmentModuleTemplateDraft();
    renderRiskAssessmentTemplateBuilder();
  }
  if (riskAssessmentNewButton) {
    riskAssessmentNewButton.hidden = !canManage;
    riskAssessmentNewButton.disabled = !canManage;
  }
  syncRiskAssessmentEditorAccess();

  const filters = {
    query: riskAssessmentSearchInput?.value?.trim() || state.riskAssessmentFilters.query || "",
    status: riskAssessmentStatusFilterInput?.value || state.riskAssessmentFilters.status || "all",
    companyId: riskAssessmentCompanyFilterInput?.value || state.riskAssessmentFilters.companyId || "all",
  };
  state.riskAssessmentFilters = filters;
  replaceSelectOptionsIfChanged(riskAssessmentCompanyFilterInput, buildRiskAssessmentCompanyOptions(true), filters.companyId);
  replaceSelectOptionsIfChanged(riskAssessmentStatusFilterInput, [
    { value: "all", label: "Svi statusi" },
    ...RISK_ASSESSMENT_STATUS_OPTIONS,
  ], filters.status);

  if (riskAssessmentSearchInput && riskAssessmentSearchInput.value !== filters.query) {
    riskAssessmentSearchInput.value = filters.query;
  }

  const visible = sortRiskAssessments(filterRiskAssessments(state.riskAssessments ?? [], filters));
  riskAssessmentList?.replaceChildren(...visible.map((item) => renderRiskAssessmentCard(item)));
  if (riskAssessmentEmpty) {
    riskAssessmentEmpty.hidden = visible.length > 0;
  }
}

async function handleForgotPasswordSubmit(event) {
  event.preventDefault();

  const email = String(forgotPasswordEmailInput?.value ?? "").trim();
  setInlineMessage(forgotPasswordError, "");

  if (!email) {
    setInlineMessage(forgotPasswordError, "Unesi email korisnika.");
    return;
  }

  setForgotPasswordBusy(true);

  try {
    await withGlobalLoading("Šaljem privremenu lozinku...", () => apiRequest("/auth/forgot-password", {
      method: "POST",
      body: {
        email,
      },
    }), { immediate: true });

    if (loginEmailInput) {
      loginEmailInput.value = email;
    }
    if (loginPasswordInput) {
      loginPasswordInput.value = "";
    }
    setAuthView("login");
    setInlineMessage(loginError, "Ako račun postoji, privremena lozinka je poslana na email.", "success");
  } catch (error) {
    setInlineMessage(
      forgotPasswordError,
      error?.message || "Slanje privremene lozinke trenutno nije uspjelo. Pokusaj ponovno.",
    );
  } finally {
    setForgotPasswordBusy(false);
  }
}

async function handleForcedPasswordChangeSubmit(event) {
  event.preventDefault();

  const newPassword = String(changePasswordNewInput?.value ?? "");
  const confirmPassword = String(changePasswordConfirmInput?.value ?? "");
  const targetEmail = state.authResetEmail || state.user?.email || "";
  setInlineMessage(changePasswordError, "");

  if (!newPassword) {
    setInlineMessage(changePasswordError, "Unesi novu lozinku.");
    return;
  }

  if (!meetsPasswordPolicy(newPassword)) {
    setInlineMessage(changePasswordError, PASSWORD_POLICY_MESSAGE);
    return;
  }

  if (newPassword !== confirmPassword) {
    setInlineMessage(changePasswordError, "Nova lozinka i potvrda moraju biti iste.");
    return;
  }

  setForcedPasswordChangeBusy(true);

  try {
    await withGlobalLoading("Spremam novu lozinku...", async () => {
      const payload = await apiRequest("/auth/change-password", {
        method: "POST",
        body: {
          newPassword,
        },
      });

      resetAuthenticatedWorkspaceState();
      if (loginEmailInput) {
        loginEmailInput.value = payload.email || targetEmail;
      }
      setInlineMessage(loginError, "Lozinka je promijenjena. Prijavi se ponovno novom lozinkom.", "success");
      changePasswordForm?.reset();
    }, { immediate: true });
  } catch (error) {
    setInlineMessage(
      changePasswordError,
      error?.message || "Spremanje nove lozinke trenutno nije uspjelo. Pokusaj ponovno.",
    );
    document.body.classList.remove("is-auth-leaving");
    renderAuthState();
  } finally {
    setForcedPasswordChangeBusy(false);
  }
}

