document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && riskAssessmentTemplatePlaceholderDialog && !riskAssessmentTemplatePlaceholderDialog.hidden) {
    event.preventDefault();
    setRiskAssessmentPlaceholderDialogOpen(false);
    return;
  }

  if (event.key === "Escape" && weatherMenuOpen) {
    event.preventDefault();
    setWeatherMenuOpen(false);
    return;
  }

  if (event.key === "Escape" && topbarHelpMenuOpen) {
    event.preventDefault();
    setTopbarHelpMenuOpen(false);
    return;
  }

  if (event.key === "Escape" && state.helpTour.open) {
    event.preventDefault();
    closeHelpTour({ markCompleted: false });
    return;
  }

  if (event.key === "Escape" && state.workOrderDocumentWizard.open) {
    closeWorkOrderDocumentWizard();
    return;
  }

  if (event.key === "Escape" && state.measurementEquipmentExportDialogOpen) {
    closeMeasurementEquipmentExportDialog();
    return;
  }

  if (event.key === "Escape" && state.todoEditorOpen) {
    dismissTodoEditor();
    return;
  }

  if (event.key === "Escape" && state.reminderEditorOpen) {
    dismissReminderEditor();
    return;
  }

  if (event.key === "Escape" && state.documentTemplateEditorOpen) {
    dismissDocumentTemplateEditor();
    return;
  }

  if (event.key === "Escape" && state.legalFrameworkEditorOpen) {
    dismissLegalFrameworkEditor();
    return;
  }

  if (event.key === "Escape" && state.rulebookEditorOpen) {
    dismissRulebookEditor();
    return;
  }

  if (event.key === "Escape" && state.locationEditorOpen) {
    dismissLocationEditor();
    return;
  }

  if (event.key === "Escape" && state.userEditorOpen) {
    dismissUserEditor();
    return;
  }

  if (event.key === "Escape" && state.companyEditorOpen) {
    dismissCompanyEditor();
    return;
  }

  if (event.key === "Escape" && state.vehicleReservationEditorOpen) {
    dismissVehicleReservationEditor();
    return;
  }

  if (event.key === "Escape" && state.vehicleEditorOpen) {
    dismissVehicleEditor();
    return;
  }

  if (event.key === "Escape" && state.offerEditorOpen) {
    dismissOfferEditor();
    return;
  }

  if (event.key === "Escape" && state.publicProcurementEditorOpen) {
    dismissPublicProcurementEditor();
    return;
  }

  if (event.key === "Escape" && state.chat.composerOpen) {
    setChatComposerOpen(false);
  }

  if (event.key === "Escape" && state.chat.emojiPickerOpen) {
    state.chat.emojiPickerOpen = false;
    renderChatDock();
    return;
  }

  if (event.key === "Escape" && state.chat.open && !state.chat.composerOpen && !state.workOrderEditorOpen) {
    setChatOpen(false);
  }

  if (event.key === "Escape" && state.dashboardBuilder.open) {
    closeDashboardBuilder();
    renderDashboardOverview();
  }
});

